INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a783c306-17a9-4b66-9c01-fea112407bc0', 'ALG.01', 1, 'numeric', 'Simplify by combining like terms', 'A box holds $x$ pens. Maya has 3 boxes and 5 loose pens. Lee has 2 boxes and 4 loose pens. Together they have $ax+b$ pens. What is $a+b$?', '[]', '14', '5+9', 'Boxes: $3x+2x=5x$. Loose pens: $5+4=9$. So they have $5x+9$ pens, and $a+b=5+9=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x + 5) + (2x + 4) = 5x + 9; a + b = 14.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
