VALUES ('ec620beb-1c46-42b7-a413-955f58926782', 'ALG.01', 2, 'choice', 'Order of operations with whole numbers', 'Which expression has the greatest value?', '["$(2+3)\\times4$","$2+3\\times4$","$2\\times3+4$","$2\\times(3+4)$"]', '$(2+3)\times4$', NULL, 'The values are $(2+3)\times4=20$, $2+3\times4=14$, $2\times3+4=10$ and $2\times(3+4)=14$. The greatest is 20.', 'checked', '{"lint":[],"solve":{"answer":"$(2+3)\\times4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values: 14, 20, 14, 10. Greatest is (2+3)*4 = 20.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
