VALUES ('447a0ac7-1161-459b-a957-97b6364dabbf', 'ALG.01', 2, 'numeric', 'Use the distributive property', 'Find the value of $99\times37-98\times37$.', '[]', '37', '37', 'Both products have the factor 37: $(99-98)\times37=1\times37=37$.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(99 - 98)*37 = 37.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b519a4f2-e4b5-4c50-aa85-e09beda9be40', 'ALG.01', 2, 'numeric', 'Simplify by combining like terms', '$7x-3y+2x+8y$ is simplified to $ax+by$. What is $a+b$?', '[]', '14', '9+5', '$7x+2x=9x$ and $-3y+8y=5y$. So $a=9$, $b=5$ and $a+b=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x + 5y; a + b = 14.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cb83325-806d-4585-aad7-515e3577b245', 'ALG.01', 2, 'choice', 'Simplify by combining like terms', 'Simplify $3a^2+2a-a^2+5a$.', '["$4a^2+7a$","$2a^2+7a$","$9a^2$","$2a^2+3a$"]', '$2a^2+7a$', NULL, 'The $a^2$ terms: $3a^2-a^2=2a^2$. The $a$ terms: $2a+5a=7a$. The result is $2a^2+7a$.', 'checked', '{"lint":[],"solve":{"answer":"$2a^2+7a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 - 1)a^2 + (2 + 5)a = 2a^2 + 7a.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f07eee-d842-48a7-bc9c-fab3bdea5e0a', 'ALG.01', 2, 'numeric', 'Simplify by combining like terms', '$5-2(x-3)+x$ is simplified to $ax+b$. What is $a+b$?', '[]', '10', '-1+11', '$-2(x-3)=-2x+6$. So the expression is $5-2x+6+x=-x+11$. Then $a=-1$, $b=11$, and $a+b=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2x + 6 + x = -x + 11; a + b = -1 + 11 = 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfe7b98d-e003-4308-b3c3-f94f859cb204', 'ALG.01', 2, 'choice', 'Simplify by combining like terms', 'Which expression is equal to $10x-(3x-4)$?', '["$7x-4$","$13x-4$","$7x+4$","$13x+4$"]', '$7x+4$', NULL, 'The minus sign changes both signs inside: $10x-3x+4=7x+4$.', 'checked', '{"lint":[],"solve":{"answer":"$7x+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x - 3x + 4 = 7x + 4.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7be5caf1-96ea-42c7-8a3d-87cb87e1337f', 'ALG.01', 2, 'numeric', 'Simplify by combining like terms', 'A rectangle has a width of $3x+2$ and a length of $x+5$ (both in centimeters). Its perimeter is $ax+b$. What is $a+b$?', '[]', '22', '8+14', 'Perimeter $=2\times(\text{width}+\text{length})=2\times(4x+7)=8x+14$. So $a=8$, $b=14$ and $a+b=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3x + 2 + x + 5) = 8x + 14; a + b = 22.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cab7e25-2b5d-406d-83bf-96362d0282d6', 'ALG.01', 2, 'choice', 'Simplify by combining like terms', 'Simplify $\frac{6x+9}{3}$.', '["$2x+9$","$6x+3$","$3x+2$","$2x+3$"]', '$2x+3$', NULL, 'Divide each term on top by 3: $\frac{6x}{3}=2x$ and $\frac{9}{3}=3$. The result is $2x+3$.', 'checked', '{"lint":[],"solve":{"answer":"$2x+3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x/3 + 9/3 = 2x + 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6b45439-4453-4103-91ea-6f24fa5a5148', 'ALG.01', 3, 'choice', 'Order of operations with whole numbers', 'Parentheses can be added to $2+3\times4+5$ to change its value. Which way of adding them makes the value 25?', '["$2+3\\times(4+5)$","$(2+3)\\times(4+5)$","$(2+3)\\times4+5$","$2+(3\\times4)+5$"]', '$(2+3)\times4+5$', NULL, '$(2+3)\times4+5=5\times4+5=25$. The others give $2+3\times9=29$, $5\times9=45$ and $2+12+5=19$.', 'checked', '{"lint":[],"solve":{"answer":"$(2+3)\\times4+5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+3*9 = 29; 5*4+5 = 25; 2+12+5 = 19; 5*9 = 45. Only (2+3)*4+5 gives 25.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9ae33f8-1804-4ae0-ab48-40762bea36c8', 'ALG.01', 3, 'numeric', 'Order of operations with whole numbers', 'Find the value of $\frac{3+9}{2+4}+2\times3$.', '[]', '8', '(3+9)/(2+4)+2*3', 'A fraction bar groups the top and the bottom: $\frac{12}{6}=2$. Then $2+2\times3=2+6=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/6 = 2; 2 + 6 = 8.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a502fef-71c0-4444-95b1-61f0a16cada1', 'ALG.01', 3, 'numeric', 'Order of operations with whole numbers', 'Find the value of $1000-2\times(30+4\times(5+1))$.', '[]', '892', '1000-2*(30+4*(5+1))', 'Work from the inside out: $5+1=6$, $4\times6=24$, $30+24=54$, $2\times54=108$. Then $1000-108=892$.', 'checked', '{"lint":[],"solve":{"answer":"892","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*6 = 24; 30 + 24 = 54; 2*54 = 108; 1000 - 108 = 892.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18828247-5180-4d39-aa97-3f698270ca2e', 'ALG.01', 3, 'numeric', 'Order of operations with whole numbers', 'In $5\ ?\ 4\ ?\ 3$, one ? is replaced by $+$ and the other ? by $\times$, in either order. What is the largest value you can get?', '[]', '23', '5*4+3', 'There are two ways: $5+4\times3=5+12=17$ and $5\times4+3=20+3=23$. The largest is 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 4*3 = 17; 5*4 + 3 = 23. Largest 23.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('715c1fb6-97bb-4ed7-92d7-9411394016d3', 'ALG.01', 3, 'numeric', 'Order of operations with whole numbers', 'Find the value of $100\div5\div2\times3-4\times(7-5)$.', '[]', '22', '100/5/2*3-4*(7-5)', 'Left to right: $100\div5=20$, $20\div2=10$, $10\times3=30$. Also $4\times(7-5)=8$. Then $30-8=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100/5 = 20; /2 = 10; *3 = 30. 4*(2) = 8. 30 - 8 = 22.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
