INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cebd7d97-48a1-4161-959b-9ed8ccc6e84e', 'ALG.01', 3, 'choice', 'Order of operations with whole numbers', 'What is the value of $2+2\times2+2\times2+2$?', '["22","16","20","12"]', '12', '2+2*2+2*2+2', 'Multiply first: $2\times2=4$ twice. Then $2+4+4+2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 4 + 4 + 2 = 12.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
