INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('319b320b-92f3-425e-86a6-97639467c6a6', 'ALG.01', 3, 'numeric', 'Order of operations with exponents, negatives and grouping', 'Work out the value of $3^2-2\times(1-4)^2\div3+(-5)$.', '[]', '-2', '3^2-2*(1-4)^2/3+(-5)', 'Parentheses first: $1-4=-3$, and $(-3)^2=9$. So $2\times9\div3=6$. Also $3^2=9$. Then $9-6+(-5)=-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^2 = 9; (1-4)^2 = 9; 2*9/3 = 6; 9 - 6 + (-5) = -2.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8a37816-20cb-480d-b5b7-9175a56e9aa7', 'ALG.01', 3, 'choice', 'Order of operations with exponents, negatives and grouping', 'Which expression has the least value?', '["$(-2)^4$","$(-2)^3$","$-2^4$","$-(-2)^2$"]', '$-2^4$', NULL, 'The values are $-2^4=-16$, $(-2)^4=16$, $(-2)^3=-8$ and $-(-2)^2=-4$. The least is $-16$.', 'checked', '{"lint":[],"solve":{"answer":"$-2^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2^4 = -16; -(-2)^2 = -4; (-2)^4 = 16; (-2)^3 = -8. Least -16.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
