INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a7a5507-2fb2-4c8d-9538-073ba07afe8c', 'ALG.01', 3, 'numeric', 'Order of operations with exponents, negatives and grouping', 'Simplify $2^{1+2}\times3^{2-1}$ to a single whole number.', '[]', '24', '2^(1+2)*3^(2-1)', 'Work the exponents first: $1+2=3$ and $2-1=1$. Then $2^3\times3^1=8\times3=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 * 3^1 = 8*3 = 24.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
