INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d74680e2-935f-4609-8a2e-7a3a4dd2d167', 'ALG.01', 3, 'numeric', 'Order of operations with exponents, negatives and grouping', 'Evaluate $10-2\times\left(3^2-(4-1)^2\right)+5$.', '[]', '15', '10-2*(3^2-(4-1)^2)+5', 'Inside, $(4-1)^2=9$, so $3^2-9=0$. Then $2\times0=0$ and $10-0+5=15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^2 - 3^2 = 0; 10 - 0 + 5 = 15.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
