INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c26e42d-3a93-4b1e-8e0a-2dbe3f4fe6da', 'ALG.01', 3, 'numeric', 'Order of operations with exponents, negatives and grouping', 'What number can replace the ? to make $3\times?-2^3=19$ true?', '[]', '9', '(19+2^3)/3', '$2^3=8$, so $3\times?-8=19$. Then $3\times?=27$, so ? is 9. Check: $27-8=19$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3? - 8 = 19; 3? = 27; ? = 9.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
