INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('039b0726-1886-4b2e-9b91-e34e92b327ce', 'ALG.01', 3, 'numeric', 'Order of operations with exponents, negatives and grouping', 'A positive number is called ?. It makes $(?-3)^2+1=26$ true. Which number is it?', '[]', '8', '5+3', 'Subtract 1: $(?-3)^2=25$. So $?-3$ is 5 or $-5$. Then ? is 8 or $-2$. The positive one is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Wording ''A positive number is called ?.'' is awkward (calling it x would read better), but the question is unambiguous.","work":"(? - 3)^2 = 25, so ? - 3 = 5 or -5, ? = 8 or -2; positive gives 8.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('690246f9-20bf-4754-8d92-9f40c2f25e78', 'ALG.01', 3, 'choice', 'Order of operations with exponents, negatives and grouping', 'What is the value of $\frac{(-3)^2-1}{2\times(-2)}$?', '["$2$","$4$","$-4$","$-2$"]', '$-2$', '-2', 'Top: $(-3)^2-1=9-1=8$. Bottom: $2\times(-2)=-4$. Then $8\div(-4)=-2$.', 'checked', '{"lint":[],"solve":{"answer":"$-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9 - 1)/(-4) = 8/(-4) = -2.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b045a16-0d6a-4a1f-8159-03d95abca6b5', 'ALG.01', 3, 'numeric', 'Evaluate an expression for given values', 'If $x=3$ and $y=-2$, find the value of $x^2y-xy^2$.', '[]', '-30', '9*(-2)-3*(-2)^2', '$x^2y=9\times(-2)=-18$. $xy^2=3\times(-2)^2=3\times4=12$. Then $-18-12=-30$.', 'checked', '{"lint":[],"solve":{"answer":"-30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 y = 9*(-2) = -18; x y^2 = 3*4 = 12; -18 - 12 = -30.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca7aebf2-c264-45b3-9dac-f88051329c35', 'ALG.01', 3, 'choice', 'Evaluate an expression for given values', 'The sum of the whole numbers from 1 to $n$ is $\frac{n(n+1)}{2}$. What is the sum of the whole numbers from 1 to 40?', '["800","820","840","1640"]', '820', '40*41/2', 'Put $n=40$: $\frac{40\times41}{2}=\frac{1640}{2}=820$.', 'checked', '{"lint":[],"solve":{"answer":"820","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40*41/2 = 820.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
