INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c78dc60-1b67-4d11-a37c-37a9265ebdad', 'ALG.01', 3, 'choice', 'Evaluate an expression for given values', 'If $a=2$ and $b=-3$, which expression has the greatest value?', '["$a-b$","$(a+b)^2$","$a^2+b^2$","$-ab$"]', '$a^2+b^2$', NULL, 'The values are $a^2+b^2=4+9=13$, $a-b=2-(-3)=5$, $(a+b)^2=(-1)^2=1$ and $-ab=-(2\times(-3))=6$. The greatest is 13.', 'checked', '{"lint":[],"solve":{"answer":"$a^2+b^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2+b^2 = 13; a-b = 5; -ab = 6; (a+b)^2 = 1. Greatest 13.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcdd2331-90a5-4245-996a-c72ece3f94ab', 'ALG.01', 3, 'numeric', 'Evaluate an expression for given values', 'Find the value of $x^3-6x^2+11x-6$ when $x=4$.', '[]', '6', '4^3-6*4^2+11*4-6', '$4^3=64$ and $6\times4^2=96$ and $11\times4=44$. So $64-96+44-6=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 - 96 + 44 - 6 = 6.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
