VALUES ('37766f0b-cc15-48c2-a672-d4620dcf42e8', 'ALG.01', 3, 'choice', 'Evaluate an expression for given values', 'To change a temperature from Celsius to Fahrenheit, use $\frac{9}{5}C+32$. What is the temperature in Fahrenheit when $C=-10$?', '["-18","50","-50","14"]', '14', '9/5*(-10)+32', '$\frac{9}{5}\times(-10)=-18$. Then $-18+32=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/5*(-10) = -18; -18 + 32 = 14.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
