INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39d253b7-f20d-4a97-82af-477f1d1acd99', 'ALG.01', 3, 'numeric', 'Use the distributive property', 'Find the value of $\frac{8\times13+8\times7}{4}$.', '[]', '40', '8*(13+7)/4', 'Take out the common factor 8: $8\times(13+7)=8\times20=160$. Then $160\div4=40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*(13 + 7)/4 = 160/4 = 40.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
