INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd56b0d0-858c-4782-ba89-0d12850ad660', 'ALG.01', 3, 'choice', 'Use the distributive property', 'Which expression is equal to $3(x+2)-2(x-5)$?', '["$x-4$","$5x+16$","$5x-4$","$x+16$"]', '$x+16$', NULL, 'Distribute: $3x+6-2x+10$. Combine like terms: $x+16$.', 'checked', '{"lint":[],"solve":{"answer":"$x+16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 6 - 2x + 10 = x + 16.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
