INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c692332-8348-4746-997b-513808d97b90', 'ALG.01', 3, 'numeric', 'Use the distributive property', '$-3(2x-5)+4x$ is written as $ax+b$. What is $a+b$?', '[]', '13', '-2+15', '$-3(2x-5)=-6x+15$. Adding $4x$ gives $-2x+15$. So $a=-2$, $b=15$, and $a+b=13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6x + 15 + 4x = -2x + 15; a + b = 13.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
