INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0d37f50-1881-4aeb-ac0d-af0d26add9d6', 'ALG.01', 3, 'choice', 'Use the distributive property', 'Which of these is NOT equal to $12\times15$?', '["$12\\times10+5$","$10\\times15+2\\times15$","$12\\times10+12\\times5$","$12\\times20-12\\times5$"]', '$12\times10+5$', NULL, 'The others are all 180: $150+30$, $120+60$ and $240-60$. But $12\times10+5=125$.', 'checked', '{"lint":[],"solve":{"answer":"$12\\times10+5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12*15 = 180. 150+30 = 180; 120+5 = 125; 120+60 = 180; 240-60 = 180. Not equal: 12*10+5.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
