INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2e9f64d-b5b9-4280-819d-d19f28c4fdea', 'ALG.01', 3, 'numeric', 'Use the distributive property', 'For what number $k$ does $2(x+3)+k(x-1)$ have no constant term (no number added or subtracted on its own)?', '[]', '6', '6', '$2(x+3)=2x+6$ and $k(x-1)=kx-k$. The numbers on their own are $6-k$. This is 0 when $k=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Constant term 6 - k = 0, k = 6.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
