VALUES ('e96483e9-db7a-4b6e-9902-4ba19a4ff8e9', 'ALG.01', 3, 'numeric', 'Use the distributive property', 'Simplify $5(2x-3)-2(5x-4)$. What number is the result?', '[]', '-7', '-15+8', '$5(2x-3)=10x-15$ and $2(5x-4)=10x-8$. So $10x-15-(10x-8)=10x-15-10x+8=-7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x - 15 - 10x + 8 = -7.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
