VALUES ('acb39d2c-3545-435c-becf-edd1fc30d353', 'ALG.02', 2, 'choice', 'Combine like terms in one variable', 'Which expression is equal to $3a-5+7a-9$?', '["$10a-14$","$10a-4$","$10a+14$","$4a-14$"]', '$10a-14$', NULL, '$3a+7a=10a$ and $-5-9=-14$. So the result is $10a-14$.', 'checked', '{"lint":[],"solve":{"answer":"$10a-14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a+7a=10a; -5-9=-14; 10a-14","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
