INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d7789bc-1217-4d61-8cb5-3c4d1a54796a', 'ALG.02', 2, 'numeric', 'Combine like terms in one variable', 'Simplify $9x-4+2x+10$ to the form $ax+b$. What is $a+b$?', '[]', '17', '11+6', '$9x+2x=11x$ and $-4+10=6$, so the expression is $11x+6$. Then $a+b=11+6=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11x+6; a+b=17","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
