INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b15fa9d0-71aa-407b-9ff7-09630ca074db', 'ALG.02', 2, 'choice', 'Combine like terms in one variable', 'Simplify $x^2+5x+3x^2-2x$.', '["$4x^2+7x$","$4x^2+3x$","$7x^2$","$4x^4+3x$"]', '$4x^2+3x$', NULL, '$x^2$ and $3x^2$ are like terms: $x^2+3x^2=4x^2$. Also $5x-2x=3x$. The terms with $x^2$ and with $x$ are not like terms, so they stay apart.', 'checked', '{"lint":[],"solve":{"answer":"$4x^2+3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+3x^2=4x^2; 5x-2x=3x; 4x^2+3x","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
