VALUES ('4e809f7e-ea98-42ea-8e1c-8a4aee0ea484', 'ALG.02', 2, 'choice', 'Use the distributive property and simplify', 'Which expression is equal to $-(x-6)+2x$?', '["$x-6$","$3x-6$","$3x+6$","$x+6$"]', '$x+6$', NULL, 'The minus sign flips both signs inside: $-(x-6)=-x+6$. Then $-x+6+2x=x+6$.', 'checked', '{"lint":[],"solve":{"answer":"$x+6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x+6+2x=x+6","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
