VALUES ('6365f33c-3869-4420-9314-ba7342713a6a', 'ALG.02', 2, 'choice', 'Simplify expressions with two variables', 'What is $(6x+2y)+(x-5y)$ in simplest form?', '["$7x+3y$","$7x-3y$","$7x-7y$","$5x-3y$"]', '$7x-3y$', NULL, '$6x+x=7x$ and $2y-5y=-3y$. So the sum is $7x-3y$.', 'checked', '{"lint":[],"solve":{"answer":"$7x-3y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x-3y","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
