INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8160d50-fbd5-4125-a2ac-f192cbcf6219', 'ALG.02', 2, 'choice', 'Decide whether expressions are equal', 'Which statement is true for every number $x$?', '["$x+x=x^2$","$3x-x=2x$","$2(x+3)=2x+3$","$x\\cdot x=2x$"]', '$3x-x=2x$', NULL, '$3x-x=2x$ is true. Test $x=3$ in the others: $3+3=6$ but $3^2=9$; $2(6)=12$ but $2\times3+3=9$; $3\cdot3=9$ but $2\times3=6$.', 'checked', '{"lint":[],"solve":{"answer":"$3x-x=2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-x=2x always; others fail e.g. at x=1.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
