INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cacc582-a51f-4fad-8604-145060af6192', 'ALG.02', 2, 'numeric', 'Decide whether expressions are equal', 'For how many of the numbers $x=1,2,3,4$ do $3x+6$ and $2x+8$ have the same value?', '[]', '1', '1', 'Try each number. At $x=1$: 9 and 10. At $x=2$: 12 and 12, equal. At $x=3$: 15 and 14. At $x=4$: 18 and 16. Only $x=2$ works, so the answer is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6=2x+8 gives x=2 only; one value in the list.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
