INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9acb311-b71c-4024-82d7-29d2ef782bf9', 'ALG.02', 2, 'choice', 'Decide whether expressions are equal', 'Which pair of expressions has the same value for every $x$?', '["$5x+2x$ and $7x^2$","$5x-2x$ and $7x$","$5x+2x$ and $7x$","$5x+2$ and $7x$"]', '$5x+2x$ and $7x$', NULL, '$5x+2x=7x$ for every $x$. The other pairs fail when $x=2$: $5x+2x=14$ but $7x^2=28$; $5x-2x=6$ but $7x=14$; $5x+2=12$ but $7x=14$.', 'checked', '{"lint":[],"solve":{"answer":"$5x+2x$ and $7x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+2x=7x identically.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
