VALUES ('25f6dbb2-30a5-4108-9e77-3c8540d4adcd', 'ALG.02', 2, 'choice', 'Translate a sentence into an equation', 'Sara has $s$ dollars. Her brother has 5 dollars more than twice what Sara has. Together they have 38 dollars. Which equation shows this?', '["$s+2(s+5)=38$","$2s+5=38$","$s+2s+5=38$","$s+5s=38$"]', '$s+2s+5=38$', NULL, 'Her brother has $2s+5$ dollars. Together: $s+(2s+5)=38$.', 'checked', '{"lint":[],"solve":{"answer":"$s+2s+5=38$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Brother has 2s+5; s+(2s+5)=38, i.e. s+2s+5=38.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
