INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da3ca65e-4211-427c-a49f-332e18b930f3', 'ALG.02', 3, 'choice', 'Evaluate an expression for a given value', 'Let $n=7$. Which of these expressions has the greatest value?', '["$3n-4$","$n^2-30$","$2n+1$","$60-6n$"]', '$n^2-30$', NULL, 'Put $n=7$ in each. $n^2-30=49-30=19$; $3n-4=17$; $2n+1=15$; $60-6n=18$. The greatest is 19, from $n^2-30$.', 'checked', '{"lint":[],"solve":{"answer":"$n^2-30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n=7: 60-42=18; 21-4=17; 49-30=19; 14+1=15. Greatest is n^2-30=19.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c54a13-c730-44a4-b0af-e28ef32f313a', 'ALG.02', 3, 'choice', 'Translate a phrase into an expression', 'Ruth is $r$ years old. Her father is 4 years older than three times her age. Which expression gives her father''s age 5 years from now?', '["$3r+4$","$3r+19$","$3r+9$","$3(r+9)$"]', '$3r+9$', NULL, 'Her father''s age now is $3r+4$. In 5 years it is $3r+4+5=3r+9$.', 'checked', '{"lint":[],"solve":{"answer":"$3r+9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Father now 3r+4; in 5 years 3r+4+5=3r+9.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc56fc23-b58b-4a64-9aae-fbec93a0f767', 'ALG.02', 3, 'numeric', 'Translate a phrase into an expression', 'A gym charges a joining fee of 30 dollars and 18 dollars for each month. Let $m$ be the number of months. What is the total cost, in dollars, for 6 months?', '[]', '138', '30+18*6', 'The cost is $30+18m$ dollars. For 6 months: $30+18\times6=30+108=138$.', 'checked', '{"lint":[],"solve":{"answer":"138","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30+18*6=30+108=138","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077b5ec8-381e-4ea2-9463-6e13c0048203', 'ALG.02', 3, 'choice', 'Translate a phrase into an expression', 'Four consecutive whole numbers start at $n$: they are $n$, $n+1$, $n+2$ and $n+3$. Which expression is their sum?', '["$4n+3$","$4n+10$","$4n+4$","$4n+6$"]', '$4n+6$', NULL, 'Add: $n+(n+1)+(n+2)+(n+3)=4n+(1+2+3)=4n+6$.', 'checked', '{"lint":[],"solve":{"answer":"$4n+6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n+(n+1)+(n+2)+(n+3)=4n+6","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ccc60b5-a361-4c67-b3e4-b055a5e2941e', 'ALG.02', 3, 'choice', 'Write an expression for a perimeter or an area', 'A picture is $p$ cm wide and $2p$ cm long. A frame 3 cm wide goes all the way around it. Which expression gives the perimeter of the outside edge of the frame, in cm?', '["$6p+24$","$6p+6$","$6p+12$","$6p+18$"]', '$6p+24$', NULL, 'The outside edge is $p+6$ cm wide and $2p+6$ cm long (3 cm is added on each side). Perimeter: $2\times(p+6+2p+6)=2\times(3p+12)=6p+24$.', 'checked', '{"lint":[],"solve":{"answer":"$6p+24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outside is (p+6) by (2p+6). P=2(3p+12)=6p+24.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2d4af0c-b6b0-44e9-b230-6e2cde05165b', 'ALG.02', 3, 'numeric', 'Write an expression for a perimeter or an area', 'A rectangle is $a$ cm long and $b$ cm wide, with $a=10$ and $b=7$. Its length is made 3 cm longer and its width 2 cm shorter. What is the perimeter of the new rectangle in cm?', '[]', '36', '2*(13+5)', 'The new length is $10+3=13$ and the new width is $7-2=5$. The perimeter is $2\times(13+5)=36$ cm.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New 13 by 5; P=2(18)=36","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e2870a4-cee9-4d58-8b63-1d7a9a3c9027', 'ALG.02', 3, 'choice', 'Write an expression for a perimeter or an area', 'The perimeter of a rectangle is $20x$ cm and its width is $3x$ cm. Which expression gives its length in cm?', '["$17x$","$7x$","$14x$","$10x-3$"]', '$7x$', NULL, 'Half the perimeter is length plus width: $10x$. So the length is $10x-3x=7x$.', 'checked', '{"lint":[],"solve":{"answer":"$7x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(L+3x)=20x so L+3x=10x, L=7x.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bb417f1-02c7-4b34-957f-520e3538736b', 'ALG.02', 3, 'choice', 'Combine like terms in one variable', 'What is $9x-3x+x-7x$ in simplest form?', '["$x$","$2x$","$0$","$-8x$"]', '$0$', NULL, 'Add the numbers in front of $x$ in order: $9-3+1-7=0$. So the whole expression is $0x=0$.', 'checked', '{"lint":[],"solve":{"answer":"$0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-3+1-7=0, so 0x=0.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70df452f-7e53-4fd7-b1e6-eb8e9b3d3400', 'ALG.02', 3, 'numeric', 'Combine like terms in one variable', 'After like terms are combined, $5x+kx-9+2x+4$ equals $3x-5$. What is $k$?', '[]', '-4', '3-5-2', 'Combining gives $(5+k+2)x-5$. This must equal $3x-5$, so $5+k+2=3$ and $k=-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(7+k)x-5=3x-5, so 7+k=3, k=-4.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1eaa109-8a45-4732-b90f-0af53cdfdfb2', 'ALG.02', 3, 'choice', 'Combine like terms in one variable', 'Which of these expressions is NOT equal to $8x+4$ for every value of $x$?', '["$4(2x+1)$","$2x+6x+4$","$12x-4x+4$","$8(x+4)$"]', '$8(x+4)$', NULL, '$8(x+4)=8x+32$, which is different. The others all simplify to $8x+4$: $4(2x+1)=8x+4$, $2x+6x=8x$, and $12x-4x=8x$.', 'checked', '{"lint":[],"solve":{"answer":"$8(x+4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12x-4x+4=8x+4; 2x+6x+4=8x+4; 4(2x+1)=8x+4; 8(x+4)=8x+32, not equal.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2af8160-faf4-425e-8ea9-d3e2cb9debb5', 'ALG.02', 3, 'numeric', 'Use the distributive property and simplify', 'When $2(3x-4)-3(x-5)$ is simplified, it becomes $3x+k$. What is $k$?', '[]', '7', '-8+15', '$2(3x-4)=6x-8$ and $-3(x-5)=-3x+15$. Together: $6x-3x-8+15=3x+7$. So $k=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-8-3x+15=3x+7, k=7","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
