VALUES ('5dbbd68b-a40a-4d3b-ac90-0307500a1e1b', 'ALG.02', 3, 'choice', 'Use the distributive property and simplify', 'Simplify $5-2(x-3)+x$.', '["$11-x$","$-1-x$","$11-3x$","$1-x$"]', '$11-x$', NULL, '$-2(x-3)=-2x+6$. So the expression is $5-2x+6+x=11-x$.', 'checked', '{"lint":[],"solve":{"answer":"$11-x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5-2x+6+x=11-x","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
