INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a2d02a1-39ef-4745-9068-8fb204232d27', 'ALG.02', 3, 'choice', 'Use the distributive property and simplify', 'What is $\frac{1}{2}(6x+8)-\frac{1}{3}(9x-12)$ in simplest form?', '["$0$","$8$","$12$","$4$"]', '$8$', NULL, '$\frac12(6x+8)=3x+4$ and $\frac13(9x-12)=3x-4$. Subtracting: $3x+4-3x+4=8$.', 'checked', '{"lint":[],"solve":{"answer":"$8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+4-(3x-4)=8","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
