INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c65fd906-d6c3-45b4-a7a2-12ad07280e36', 'ALG.02', 3, 'numeric', 'Simplify expressions with two variables', 'When $(5a+3b)-(2a-4b)$ is simplified, it becomes $pa+qb$. What is $p+q$?', '[]', '10', '3+7', 'Subtracting changes both signs: $5a+3b-2a+4b=3a+7b$. So $p=3$, $q=7$, and $p+q=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a-2a=3a; 3b+4b=7b; p+q=10","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64092bbb-2024-449e-ad45-e072edd1b878', 'ALG.02', 3, 'choice', 'Simplify expressions with two variables', 'Simplify $3(2x-y)-2(x-3y)$.', '["$4x-9y$","$8x+3y$","$4x+3y$","$4x+9y$"]', '$4x+3y$', NULL, '$3(2x-y)=6x-3y$ and $-2(x-3y)=-2x+6y$. Together: $6x-2x-3y+6y=4x+3y$.', 'checked', '{"lint":[],"solve":{"answer":"$4x+3y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-3y-2x+6y=4x+3y","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
