INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04414c5d-b761-47df-b9da-d24b6a7fb75a', 'ALG.02', 3, 'numeric', 'Simplify expressions with two variables', 'Suppose $x+y=9$. Group the terms to find the value of $3x+3y-5$.', '[]', '22', '3*9-5', '$3x+3y=3(x+y)=3\times9=27$. So $3x+3y-5=27-5=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+y)-5=27-5=22","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
