INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57b7bc0f-4131-41e6-973d-94996421d44c', 'ALG.02', 3, 'numeric', 'Decide whether expressions are equal', 'Find the number $k$ for which $3(2x+k)-x$ and $5x+12$ are equal for every value of $x$.', '[]', '4', '12/3', '$3(2x+k)-x=6x+3k-x=5x+3k$. This equals $5x+12$ when $3k=12$, so $k=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x+3k-x=5x+3k, so 3k=12, k=4.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bfdfed-b3f1-4c7a-9b04-ba4e4c017e40', 'ALG.02', 3, 'numeric', 'Decide whether expressions are equal', 'For which number $c$ is $c(x+2)+3x$ equal to $8x+10$ for every value of $x$?', '[]', '5', '8-3', '$c(x+2)+3x=(c+3)x+2c$. We need $c+3=8$ and $2c=10$. Both give $c=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(c+3)x+2c: c+3=8 gives c=5, and 2c=10 matches.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed35f755-2df8-4854-83f8-4db4880044fa', 'ALG.02', 3, 'choice', 'Decide whether expressions are equal', 'Which of these is equal to $4(x-3)-(x-3)$ for every $x$?', '["$3x-15$","$5x-15$","$3x-3$","$3x-9$"]', '$3x-9$', NULL, '$4(x-3)=4x-12$. Subtracting $(x-3)$ means subtracting $x$ and adding 3: $4x-12-x+3=3x-9$. (Or: 4 of something minus 1 of it leaves 3 of it, $3(x-3)$.)', 'checked', '{"lint":[],"solve":{"answer":"$3x-9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x-3)=3x-9","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24ff7e02-3513-4636-9539-5b1673359dd2', 'ALG.02', 3, 'choice', 'Translate a sentence into an equation', 'Jo is $j$ years old and her sister is 3 years younger. In 6 years the sum of their ages will be 41. Which equation shows this?', '["$(j+6)+(j+3)=41$","$(j+6)+(j-3)=41$","$(j+6)+(j+9)=41$","$2j+6=41$"]', '$(j+6)+(j+3)=41$', NULL, 'In 6 years Jo will be $j+6$. Her sister is $j-3$ now and will be $j-3+6=j+3$. So the sum is $(j+6)+(j+3)=41$.', 'checked', '{"lint":[],"solve":{"answer":"$(j+6)+(j+3)=41$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sister j-3. In 6 years: j+6 and j+3. (j+6)+(j+3)=41.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9e495b-0071-49f4-adac-d9af56e106d1', 'ALG.02', 3, 'numeric', 'Translate a sentence into an equation', 'A number is doubled and then 5 is subtracted. The result equals the number increased by 9. What is the number?', '[]', '14', '9+5', 'The equation is $2n-5=n+9$. Take away $n$ from both sides: $n-5=9$. Then $n=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n-5=n+9, n=14","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
