INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6d7df7a-8336-4908-831f-46a3660caedf', 'ALG.02', 3, 'numeric', 'Translate a sentence into an equation', 'The sum of three consecutive whole numbers is 72. What is the smallest of them?', '[]', '23', '(72-3)/3', 'Call the numbers $n$, $n+1$, $n+2$. Their sum is $3n+3=72$, so $3n=69$ and $n=23$. (23, 24, 25 add to 72.)', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n+3=72, n=23","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
