INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e9525bf-0535-4e42-aee2-715bdcc7f805', 'ALG.02', 3, 'numeric', 'Terms, coefficients and constants', '$4x+7-(kx-2)$ simplifies to an expression whose coefficient of $x$ is $-2$. What is $k$?', '[]', '6', '4+2', 'Remove the brackets: $4x+7-kx+2=(4-k)x+9$. We need $4-k=-2$, so $k=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4-k)x+9; 4-k=-2, k=6","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
