INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9127bce-ee38-4144-ba0f-4d43d6015560', 'ALG.02', 3, 'choice', 'Terms, coefficients and constants', 'Which statement is true about $3(x+2)-3x+4$?', '["It equals 10 for every value of $x$","It equals $6x+10$ for every value of $x$","It gets bigger when $x$ gets bigger","It equals 4 when $x$ is 0"]', 'It equals 10 for every value of $x$', NULL, '$3(x+2)=3x+6$. Then $3x+6-3x+4=10$. The $x$ terms cancel, so the value is always 10.', 'checked', '{"lint":[],"solve":{"answer":"It equals 10 for every value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6-3x+4=10 for every x.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('416519a1-2b21-489e-8cc6-511ab4ebecf8', 'ALG.02', 3, 'choice', 'Terms, coefficients and constants', 'After simplifying, which expression has the greatest coefficient of $x$?', '["$3x+4x-2x$","$10x-3(x+1)$","$2(3x+1)-x$","$x+x+x+x+x+x$"]', '$10x-3(x+1)$', NULL, 'The coefficients are: $3+4-2=5$; $10-3=7$; $6-1=5$; and $6$. The greatest is 7, from $10x-3(x+1)$.', 'checked', '{"lint":[],"solve":{"answer":"$10x-3(x+1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x; 6x; 7x-3 (coef 7); 5x+2. Greatest: 10x-3(x+1).","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
