INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e95de4e-5343-4fc9-a517-e09f8128ec54', 'ALG.02', 3, 'numeric', 'Substitute and use a given relationship', 'If $a=2b$ and $b=3c$, what is the value of $a+b+c$ when $c=2$?', '[]', '20', '12+6+2', 'First $b=3\times2=6$. Then $a=2\times6=12$. So $a+b+c=12+6+2=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b=6, a=12; 12+6+2=20","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
