INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('076f77dd-bbbb-423b-bbc3-7465af8326bd', 'ALG.03', 2, 'choice', 'Consecutive numbers and ages', 'In 5 years, Ella will be twice as old as she was 3 years ago. How old is Ella now?', '["8","13","11","16"]', '11', NULL, 'Let Ella be $e$ now. In 5 years she is $e+5$, and 3 years ago she was $e-3$. So $e+5=2(e-3)$, which is $e+5=2e-6$. Then $e=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+5=2(x-3), x=11","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dfb32e3-d6ab-4095-9cfc-966b743b951b', 'ALG.03', 2, 'numeric', 'Money problems', 'Jo has 12 coins, all dimes (10 cents each) and quarters (25 cents each). They are worth 210 cents in all. How many quarters does Jo have?', '[]', '6', '12-6', 'Let $d$ be the dimes; then there are $12-d$ quarters. $10d+25(12-d)=210$, so $300-15d=210$ and $d=6$. So there are $12-6=6$ quarters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10(12-q)+25q=210, 15q=90, q=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4067ef8-bdb2-44f0-bf76-3ca8abb26d74', 'ALG.03', 2, 'numeric', 'Money problems', 'A show sells 40 tickets. Adult tickets cost 5 dollars and student tickets cost 3 dollars. The sales are 150 dollars. How many adult tickets were sold?', '[]', '15', '30/2', 'Let $a$ be adult tickets; then $40-a$ are student tickets. $5a+3(40-a)=150$, so $2a+120=150$ and $a=15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a+3(40-a)=150, 2a=30, a=15","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d272c6c-a7ff-491f-8a1d-47e7744e50cd', 'ALG.03', 2, 'choice', 'Money problems', 'Sam earns 12 dollars for each hour of work plus a bonus of 30 dollars. For how many hours must Sam work to earn 150 dollars?', '["15","10","12.5","5"]', '10', '(150-30)/12', '$12h+30=150$. Subtract 30: $12h=120$. So $h=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12h+30=150, h=10","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
