INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eab7640-cf67-47be-a4a8-e1389a956a19', 'ALG.03', 2, 'choice', 'Distance, perimeter and rate problems', 'A bus leaves a station at 60 miles per hour. Two hours later a car leaves the same station on the same road at 90 miles per hour. How many hours after the car leaves does it catch up with the bus?', '["4","6","3","2"]', '4', NULL, 'Let $s$ be the car''s hours. The bus has been driving $s+2$ hours. They are at the same spot when $90s=60(s+2)$. So $30s=120$ and $s=4$. (Both have gone 360 miles.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus is 120 miles ahead; gap closes at 30 mph: 4 hours.","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed1a1cb6-ccc4-4f00-9c6e-eefd80817c88', 'ALG.03', 2, 'numeric', 'Distance, perimeter and rate problems', 'The sides of a triangle are $x$ cm, $x+4$ cm and $2x-1$ cm. Its perimeter is 43 cm. What is $x$?', '[]', '10', '(43-3)/4', '$x+(x+4)+(2x-1)=4x+3=43$. So $4x=40$ and $x=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+3=43, x=10","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
