INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4c49492-2860-4789-9685-0389b9df17ba', 'ALG.03', 2, 'choice', 'Distance, perimeter and rate problems', 'Two cars start 300 miles apart and drive toward each other. One goes 45 miles per hour and the other 55 miles per hour. After how many hours do they meet?', '["30","3","6","5"]', '3', '300/(45+55)', 'Together they close 100 miles each hour: $45t+55t=300$, so $100t=300$ and $t=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"300/(45+55)=3","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
