INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc46f4be-04b3-411c-8eb8-b4aaa58e3556', 'ALG.03', 2, 'choice', 'Equations with no solution or with every number as a solution', 'Which statement is true about the equation $3(x+2)=3x+6$?', '["It has no solution","Every number is a solution","Its only solution is $x=0$","Its only solution is $x=6$"]', 'Every number is a solution', NULL, '$3(x+2)=3x+6$. The two sides are the same expression, so the equation is true for every value of $x$.', 'checked', '{"lint":[],"solve":{"answer":"Every number is a solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6=3x+6 identity","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
