INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc281133-4a61-4225-8336-b9a6a86d06e5', 'ALG.03', 2, 'choice', 'Equations with no solution or with every number as a solution', 'Which statement is true about the equation $4x+2=2(2x+1)+1$?', '["It is true for every value of $x$","Its only solution is $x=1$","It has no solution","Its only solution is $x=0$"]', 'It has no solution', NULL, 'The right side is $4x+2+1=4x+3$. Then $4x+2=4x+3$ becomes $2=3$, which is never true. There is no solution.', 'checked', '{"lint":[],"solve":{"answer":"It has no solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+2=4x+3, no solution","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
