VALUES ('86543506-2f63-4c79-b860-6ba04444d094', 'ALG.03', 2, 'choice', 'Use an equation to find another value', 'If $4x-3=13$, what is the value of $x+2$?', '["4","15","6","18"]', '6', '(13+3)/4+2', '$4x=16$, so $x=4$. Then $x+2=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x=16, x=4, x+2=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
