INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e01eb680-ee73-423d-a6a7-3af83c53cbb9', 'ALG.03', 2, 'choice', 'Use an equation to find another value', 'Ned writes $3(x-2)=x+8$ and then $3x-2=x+8$, which is a mistake. What is the correct solution of $3(x-2)=x+8$?', '["5","-7","14","7"]', '7', '(8+6)/2', 'Multiply out correctly: $3x-6=x+8$. Subtract $x$: $2x-6=8$. Add 6: $2x=14$. So $x=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-6=x+8, x=7","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
