VALUES ('7c31a0f4-3528-4fb4-a73f-ef97eeee368d', 'ALG.03', 3, 'numeric', 'Solve a one-step or two-step equation', 'Solve $-3x-7=14$.', '[]', '-7', '(14+7)/(0-3)', 'Add 7 to both sides: $-3x=21$. Divide by $-3$: $x=-7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x=21, x=-7","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
