VALUES ('c292fe4d-e6c7-473f-a8d4-ca71d12682fe', 'ALG.03', 3, 'numeric', 'Solve an equation with the variable on both sides', 'The expression $6x-7$ is 13 more than the expression $2x+4$. What is $x$?', '[]', '6', '24/4', 'We need $6x-7=2x+4+13$, so $6x-7=2x+17$. Subtract $2x$: $4x-7=17$. Add 7: $4x=24$. So $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-7=2x+4+13, 4x=24, x=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
