VALUES ('f7f71d4f-b5b0-4913-92fb-ecd6f95285be', 'ALG.03', 3, 'numeric', 'Solve an equation with parentheses', 'Solve $3(2x-5)-2(x+4)=1$.', '[]', '6', '24/4', 'Multiply out: $6x-15-2x-8=1$. Combine: $4x-23=1$. Add 23: $4x=24$. So $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-15-2x-8=1, 4x=24, x=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
