VALUES ('780d2482-b80c-40c3-85f3-84be798a18d1', 'ALG.03', 3, 'choice', 'Solve an equation with parentheses', 'Solve $x-(2x-9)=3(x-5)$.', '["$\\frac{3}{2}$","$-6$","$3$","$6$"]', '$6$', NULL, 'Multiply out: $x-2x+9=3x-15$, so $-x+9=3x-15$. Add $x$ and add 15: $24=4x$. So $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x+9=3x-15, 24=4x, x=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
