INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f4a9314-b7e6-47e8-bfc5-8d3704a80be7', 'ALG.03', 3, 'numeric', 'Solve an equation with fractions on both sides', 'Three-fourths of $x+2$ equals two-thirds of $x+5$. What is $x$?', '[]', '22', '40-18', 'The equation is $\frac34(x+2)=\frac23(x+5)$. Multiply by 12: $9(x+2)=8(x+5)$, so $9x+18=8x+40$. Then $x=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9(x+2)=8(x+5), 9x+18=8x+40, x=22","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
