INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69e1fc68-17d8-4df9-8a4e-ef26c85852f9', 'ALG.03', 3, 'numeric', 'Solve a number puzzle with an equation', 'A number is multiplied by 5 and then 12 is subtracted. The result is the same as when the number is taken away from 36. What is the number?', '[]', '8', '48/6', '$5n-12=36-n$. Add $n$ and add 12: $6n=48$. So $n=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5n-12=36-n, 6n=48, n=8","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a7baeba-9de3-4541-b716-3b0211c6a4dc', 'ALG.03', 3, 'choice', 'Solve a number puzzle with an equation', 'Two-thirds of a number is 4 more than half of the number. What is the number?', '["$12$","$\\frac{24}{7}$","$48$","$24$"]', '$24$', NULL, '$\frac23n=\frac12n+4$. Multiply by 6: $4n=3n+24$. So $n=24$.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n/3-n/2=4, n/6=4, n=24","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63bd376e-dec8-405e-8b56-8554c7ee48ff', 'ALG.03', 3, 'numeric', 'Solve a number puzzle with an equation', 'The sum of two numbers is 40 and their difference is 12. What is the larger number?', '[]', '26', '(40+12)/2', 'Let the larger be $n$. Then the smaller is $n-12$, and $n+(n-12)=40$. So $2n=52$ and $n=26$. (The smaller is 14.)', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L=(40+12)/2=26","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
