INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b564c523-b5f1-4d94-90b3-b4a0cd910434', 'ALG.03', 3, 'numeric', 'Consecutive numbers and ages', 'The sum of three consecutive whole numbers is 12 more than twice the largest of them. What is the smallest of the three?', '[]', '13', '16-3', 'Call them $n$, $n+1$, $n+2$. Then $3n+3=2(n+2)+12=2n+16$. So $n=13$. Check: $13+14+15=42$ and $2\times15+12=42$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n+3=2(n+2)+12, n=13 (13+14+15=42=2*15+12)","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c0e06ed-5029-4bbe-a318-55cb41e059dc', 'ALG.03', 3, 'choice', 'Consecutive numbers and ages', 'A mother is 4 times as old as her daughter. In 6 years, the mother will be 3 times as old as her daughter. How old is the daughter now?', '["6","8","24","12"]', '12', NULL, 'Daughter is $d$, mother is $4d$. In 6 years: $4d+6=3(d+6)=3d+18$. So $d=12$. (Mother is 48.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4d+6=3(d+6), d=12","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75cc0178-4bc0-4e6d-937d-a7f876ea10b2', 'ALG.03', 3, 'numeric', 'Consecutive numbers and ages', 'Ben is 5 years older than Amy. Four years ago, Ben was twice as old as Amy was then. How old is Ben now?', '[]', '14', '9+5', 'Amy is $a$ now and Ben is $a+5$. Four years ago: $a+5-4=2(a-4)$, so $a+1=2a-8$ and $a=9$. Ben is $9+5=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B=A+5; B-4=2(A-4): A+1=2A-8, A=9, B=14","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ea01f47-a524-4e11-9b46-44ce5cefad8b', 'ALG.03', 3, 'numeric', 'Money problems', 'Plan A costs 10 dollars a month plus 5 cents per minute of calls. Plan B costs 4 dollars a month plus 15 cents per minute. For how many minutes in a month do the two plans cost the same?', '[]', '60', '6/0.1', 'Work in dollars: $10+0.05m=4+0.15m$. Subtract $0.05m$ and 4: $6=0.10m$. So $m=60$. (Both cost 13 dollars.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10+0.05m=4+0.15m, 6=0.1m, m=60","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d12c7ae-21d5-4288-a794-45d2e245c50f', 'ALG.03', 3, 'choice', 'Money problems', 'Ela buys 8 items, some pens at 3 dollars each and the rest notebooks at 5 dollars each. She pays 32 dollars. How many notebooks did she buy?', '["3","5","4","6"]', '4', '(32-24)/2', 'Let $n$ be notebooks; pens are $8-n$. $3(8-n)+5n=32$, so $24+2n=32$ and $n=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(8-n)+5n=32, 2n=8, n=4","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfe11fe7-3221-455a-85f8-f9b56bb05b64', 'ALG.03', 3, 'numeric', 'Money problems', 'Lena spent half of her money, and then 8 dollars more. She has 11 dollars left. How many dollars did she start with?', '[]', '38', '19*2', 'Let her start with $x$. Then $x-\frac{x}{2}-8=11$, so $\frac{x}{2}=19$ and $x=38$.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2-8=11, x=38","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
