INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b7ae6cb-4db4-474b-8fa0-a4325ffebee3', 'ALG.03', 3, 'numeric', 'Distance, perimeter and rate problems', 'A rectangle''s length is 4 more than 3 times its width. Its perimeter is 56 cm. What is its length, in cm?', '[]', '22', '3*6+4', 'Width $w$, length $3w+4$. Then $2(w+3w+4)=56$, so $8w+8=56$ and $w=6$. The length is $3\times6+4=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8w+8=56, w=6, L=22","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
