INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7318f52f-c07c-46dc-bda0-25711e8b21af', 'ALG.03', 3, 'choice', 'Distance, perimeter and rate problems', 'One pipe fills a pool in 6 hours. A second pipe fills the same pool in 3 hours. Working together, how many hours do they take to fill it?', '["4.5","9","2","3"]', '2', '1/(1/6+1/3)', 'In $t$ hours the pipes fill $\frac{t}{6}+\frac{t}{3}$ of the pool. Set it equal to 1: $\frac{t}{6}+\frac{2t}{6}=1$, so $\frac{t}{2}=1$ and $t=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6+1/3=1/2 pool per hour: 2 hours","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5790ef40-6e8d-414f-9b00-6a4c964a4e62', 'ALG.03', 3, 'numeric', 'Distance, perimeter and rate problems', 'Kim bikes to a lake at 12 miles per hour and comes back the same way at 4 miles per hour. The whole trip takes 2 hours. How many miles is it to the lake?', '[]', '6', '24/4', 'Let the distance be $d$ miles. Time out is $\frac{d}{12}$ and time back is $\frac{d}{4}$. So $\frac{d}{12}+\frac{d}{4}=2$. Multiply by 12: $d+3d=24$, so $d=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d/12+d/4=2, d/3=2, d=6","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('184cf4c8-e518-4913-9083-70df069c7e10', 'ALG.03', 3, 'numeric', 'Equations with no solution or with every number as a solution', 'For which number $k$ is every number a solution of $5x+k=3x+2(x+4)$?', '[]', '8', '8', 'The right side is $3x+2x+8=5x+8$. The two sides match for every $x$ when $k=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+k=5x+8, k=8","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
