INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f5435c9-2d4f-4470-843a-77621ba2e473', 'ALG.03', 3, 'choice', 'Equations with no solution or with every number as a solution', 'For which value of $a$ does the equation $2(x+1)=ax+5$ have no solution?', '["$0$","$5$","$-2$","$2$"]', '$2$', NULL, 'The left side is $2x+2$. If $a=2$ the equation is $2x+2=2x+5$, which is never true. For any other $a$ there is exactly one solution.', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+2=ax+5: a=2 gives 2=5, no solution","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69e37a53-194c-4c1f-8722-ac7bda0128f3', 'ALG.03', 3, 'choice', 'Equations with no solution or with every number as a solution', 'Which of these equations has no solution?', '["$3x+7=3x-7$","$3x+7=7-3x$","$3x+7=7x+3$","$3x-7=-(7-3x)$"]', '$3x+7=3x-7$', NULL, 'In $3x+7=3x-7$, subtracting $3x$ gives $7=-7$, never true. The second has solution $x=0$, the third $x=1$, and the last is true for every $x$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+7=3x-7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=1; identity; 7=-7 none; x=0. Answer 3x+7=3x-7.","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
