VALUES ('65a55688-7d74-43e2-9634-24c11d0c88f3', 'ALG.03', 3, 'numeric', 'Use an equation to find another value', 'The equation $5x-k=3x+10$ has the solution $x=6$. What is $k$?', '[]', '2', '30-28', 'Put $x=6$: $30-k=18+10=28$. So $k=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30-k=28, k=2","run_id":"claude-code","at":"2026-10-19T01:40:43.244Z"}}', 'ai', NULL, NULL)
