VALUES ('deb5cbcf-e27f-46bb-a2cc-bffcad66f138', 'ALG.04', 1, 'choice', 'Combine like terms with several variables', 'Simplify $5x+3y-2x+y$.', '["$3x+2y$","$7x+4y$","$3x+3y$","$3x+4y$"]', '$3x+4y$', NULL, 'The $x$ terms give $5x-2x=3x$. The $y$ terms give $3y+y=4y$ (remember $y$ means $1y$). The result is $3x+4y$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+4y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x-2x=3x; 3y+y=4y -> 3x+4y","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
