INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('960ba871-ea24-462c-beee-861063a0a5a6', 'ALG.04', 2, 'numeric', 'Evaluate an expression with several variables', 'Find the value of $6x+9y$ when $x=\frac{1}{2}$ and $y=\frac{2}{3}$.', '[]', '9', '6*(1/2)+9*(2/3)', '$6\times\frac{1}{2}=3$ and $9\times\frac{2}{3}=6$. So $3+6=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(1/2)+9(2/3)=3+6=9","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
