INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53b75b3d-6180-4a7d-97c7-f3d7514ff7ac', 'ALG.04', 2, 'choice', 'Evaluate an expression with several variables', 'When $a=5$, $b=7$ and $c=4$, what is the value of $\frac{a+b}{c}$?', '["$\\frac{27}{4}$","48","3","8"]', '3', '(5+7)/4', 'The top is $5+7=12$, and $12\div4=3$. (Dividing only $b$ by $c$ is a mistake: the fraction bar groups $a+b$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5+7)/4=12/4=3","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
