VALUES ('c9689fe7-4c56-482d-889a-cbce91620c08', 'ALG.04', 2, 'choice', 'Combine like terms with several variables', 'Simplify $3(a+2b)-2(2a-b)$.', '["$-a+4b$","$7a+8b$","$-a-4b$","$-a+8b$"]', '$-a+8b$', NULL, '$3(a+2b)=3a+6b$ and $-2(2a-b)=-4a+2b$. Add: $3a-4a=-a$ and $6b+2b=8b$. The result is $-a+8b$.', 'checked', '{"lint":[],"solve":{"answer":"$-a+8b$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a+6b-4a+2b=-a+8b","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
