VALUES ('c54eefa2-091e-43f5-8ec0-98213fbdd7ef', 'ALG.04', 2, 'choice', 'Expand with the distributive property', 'Simplify $(x+2y)+3(x-y)$.', '["$4x-y$","$4x+y$","$4x+5y$","$4x-5y$"]', '$4x-y$', NULL, '$3(x-y)=3x-3y$. Then $x+3x=4x$ and $2y-3y=-y$. The result is $4x-y$.', 'checked', '{"lint":[],"solve":{"answer":"$4x-y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+2y+3x-3y=4x-y","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
