VALUES ('5b31832b-9166-4e49-8be1-b633c6861012', 'ALG.04', 2, 'choice', 'Expand with the distributive property', 'Which expression is equal to $2x(y+3)-xy$?', '["$2xy+6x$","$xy+6x$","$xy+3x$","$2xy+3x$"]', '$xy+6x$', NULL, '$2x(y+3)=2xy+6x$. Subtracting $xy$ leaves $xy+6x$.', 'checked', '{"lint":[],"solve":{"answer":"$xy+6x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2xy+6x-xy=xy+6x","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
