VALUES ('c5e37e66-168b-4318-ba15-c68256f5f87c', 'ALG.04', 2, 'numeric', 'Use a formula to find an unknown value', 'A rectangle has length $2a+b$ and width $a-b$. What is its perimeter when $a=7$ and $b=2$?', '[]', '42', '2*((2*7+2)+(7-2))', 'Length $=14+2=16$ and width $=7-2=5$. Perimeter $=2(16+5)=42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"length 2(7)+2=16, width 7-2=5; perimeter 2(21)=42","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
