INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0db0895-5bc2-45ba-8f3c-d6f62fbfc4b4', 'ALG.04', 2, 'numeric', 'Combine like terms with several variables', 'After combining like terms, $7x+3y-2z-4x+y+2z$ can be written as $ax+by$. What is $a+b$?', '[]', '7', '3+4', '$x$: $7x-4x=3x$. $y$: $3y+y=4y$. $z$: $-2z+2z=0$. So $a=3$, $b=4$ and $a+b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x-4x=3x, 3y+y=4y, z terms cancel; a+b=3+4=7","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
