VALUES ('e5a22bc7-948c-4572-af2b-1437e751efd6', 'ALG.04', 2, 'choice', 'Combine like terms with several variables', 'Simplify $9m-3(2m-n)+n$.', '["$3m-2n$","$15m+4n$","$3m+4n$","$3m+2n$"]', '$3m+4n$', NULL, '$-3(2m-n)=-6m+3n$. So $9m-6m=3m$ and $3n+n=4n$. The result is $3m+4n$.', 'checked', '{"lint":[],"solve":{"answer":"$3m+4n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9m-6m+3n+n=3m+4n","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
