INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d29e37b5-c103-48fc-899c-1d3367d3590b', 'ALG.04', 2, 'choice', 'Write an expression with several variables', 'Pens cost $p$ dollars each and a notebook costs $n$ dollars. Tom buys 4 pens and 1 notebook and pays with a 20 dollar bill. Which expression gives his change in dollars?', '["$20-4p-n$","$4p+n-20$","$20-4pn$","$20-p-n$"]', '$20-4p-n$', NULL, 'He spends $4p+n$ dollars. The change is $20-(4p+n)=20-4p-n$.', 'checked', '{"lint":[],"solve":{"answer":"$20-4p-n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 4p+n, change 20-4p-n","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb9c7693-4af1-434e-ae40-67829ba51183', 'ALG.04', 2, 'choice', 'Write an expression with several variables', 'A hiker walks at $s$ miles per hour for $h$ hours, and then walks $r$ more miles. Which expression gives the total miles walked?', '["$s+h+r$","$sh+r$","$s(h+r)$","$hr+s$"]', '$sh+r$', NULL, 'Distance equals speed times time, so the first part is $sh$ miles. Add $r$: $sh+r$.', 'checked', '{"lint":[],"solve":{"answer":"$sh+r$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance sh then r more: sh+r","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
