INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1625554f-80d2-4295-8cac-4525c67fedb1', 'ALG.04', 2, 'choice', 'Solve a formula for one variable: two steps', 'Solve $5m-n=k$ for $n$.', '["$n=k-5m$","$n=5m-k$","$n=5m+k$","$n=\\frac{k}{5m}$"]', '$n=5m-k$', NULL, 'Add $n$ and subtract $k$ on both sides: $5m-k=n$.', 'checked', '{"lint":[],"solve":{"answer":"$n=5m-k$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n=5m-k","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
