INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2d0489d-b3c2-4ece-b48c-55fc83ffc45d', 'ALG.04', 2, 'numeric', 'Expand with the distributive property', 'Simplify $-2(3x-y)+x$ and write it as $px+qy$. What is $p+q$?', '[]', '-3', '-5+2', '$-2(3x-y)=-6x+2y$. Adding $x$ gives $-5x+2y$. So $p=-5$, $q=2$ and $p+q=-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6x+2y+x=-5x+2y; p+q=-5+2=-3","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
