INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85cf745a-31a0-4661-a66f-6bb3f4af708c', 'ALG.04', 2, 'numeric', 'Evaluate an expression with several variables', 'A taxi charges a flat fee of $f$ dollars plus $m$ dollars for each mile, so a ride of $d$ miles costs $f+md$ dollars. How many dollars does a 7 mile ride cost when $f=3$ and $m=2$?', '[]', '17', '3+2*7', '$f+md=3+2\times7=3+14=17$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+2(7)=17","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
