INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36feee25-3125-4047-9f67-ceddf4ae9089', 'ALG.04', 3, 'numeric', 'Evaluate an expression with several variables', 'Find the value of $\frac{ab}{a+b}$ when $a=12$ and $b=4$.', '[]', '3', '12*4/(12+4)', 'The top is $12\times4=48$ and the bottom is $12+4=16$. So $48\div16=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48/16=3","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
