INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a2c0f85-f99d-4ce1-a474-53aec5a8c37e', 'ALG.04', 3, 'numeric', 'Evaluate an expression with several variables', 'Find the value of $a^2b-bc^2+abc$ when $a=-3$, $b=2$ and $c=-1$.', '[]', '22', '(-3)^2*2-2*(-1)^2+(-3)*2*(-1)', '$a^2b=9\times2=18$. $bc^2=2\times1=2$. $abc=(-3)(2)(-1)=6$. So $18-2+6=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2b=9*2=18; bc^2=2*1=2; abc=(-3)(2)(-1)=6; 18-2+6=22","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
