INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95ca33eb-cb5f-462b-aeba-dc34dc2ee26f', 'ALG.04', 3, 'numeric', 'Substitute one expression for a variable', 'Suppose $a=2b$, $b=3c$ and $c=4$. What is the value of $a+b+c$?', '[]', '40', '24+12+4', '$b=3\times4=12$ and $a=2\times12=24$. So $a+b+c=24+12+4=40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c=4, b=12, a=24; sum 40","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
