INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('489cdb2e-fd0a-43bb-b428-08e4d41e2eef', 'ALG.04', 3, 'choice', 'Substitute one expression for a variable', 'If $x=2y-1$ and $y=\frac{z+3}{2}$, which expression gives $x$ in terms of $z$?', '["$z+3$","$z+4$","$z+2$","$2z+2$"]', '$z+2$', NULL, '$2y=z+3$, so $x=2y-1=(z+3)-1=z+2$.', 'checked', '{"lint":[],"solve":{"answer":"$z+2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=2(z+3)/2-1=z+3-1=z+2","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
