INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e91e4666-2db8-4241-ae91-d1fd42e7aa4e', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'A shop''s income is modeled by $T=3a-2b$. When $a=5$, the value of $T$ is 7. What is $b$?', '[]', '4', '(3*5-7)/2', '$7=15-2b$, so $2b=8$ and $b=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15-2b=7, b=4","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
