INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bff9ea1-b65f-4e9c-b4e8-51636c9ef787', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'Use $C=\frac{5}{9}(F-32)$ to find the Fahrenheit temperature $F$ when $C=-10$.', '[]', '14', '(-10)*9/5+32', '$F-32=\frac{9}{5}\times(-10)=-18$, so $F=-18+32=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-10=(5/9)(F-32), F-32=-18, F=14","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
