INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1e35635-d499-466a-861d-ea92e8d0e887', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'The amount after $t$ years of simple interest is $A=P(1+rt)$. If $A=1260$, $P=1000$ and $t=2$, what is the rate $r$, written as a decimal?', '[]', '0.13', '(1260/1000-1)/2', '$1260=1000(1+2r)$, so $1+2r=1.26$. Then $2r=0.26$ and $r=0.13$.', 'checked', '{"lint":[],"solve":{"answer":"0.13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1260=1000(1+2r), 1.26=1+2r, r=0.13","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
