INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('327cb53e-3e9a-4922-8aa9-1e606a33b60e', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'The sum of the first $n$ terms of a list is $S=\frac{n}{2}(a+l)$, where $a$ is the first term and $l$ is the last. If $S=105$, $n=10$ and $a=3$, what is $l$?', '[]', '18', '2*105/10-3', '$105=5(3+l)$, so $3+l=21$ and $l=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"105=5(3+l), 21=3+l, l=18","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
