INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2eaecb75-91eb-4b37-8d90-e85e262cf09a', 'ALG.04', 3, 'choice', 'Solve a formula for one variable: harder forms', 'In $S=\frac{n}{2}(a+l)$, solve for $l$.', '["$l=\\frac{2S}{n}+a$","$l=\\frac{S}{2n}-a$","$l=2Sn-a$","$l=\\frac{2S}{n}-a$"]', '$l=\frac{2S}{n}-a$', NULL, 'Multiply by 2: $2S=n(a+l)$. Divide by $n$: $\frac{2S}{n}=a+l$. Subtract $a$: $l=\frac{2S}{n}-a$.', 'checked', '{"lint":[],"solve":{"answer":"$l=\\frac{2S}{n}-a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2S/n=a+l, l=2S/n-a","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
