VALUES ('f9923ff3-0ad9-45ae-b22a-e877abab697a', 'ALG.04', 3, 'choice', 'Solve a formula for one variable: harder forms', 'Solve $a(x+b)=c(x-d)$ for $x$.', '["$x=\\frac{ab+cd}{a-c}$","$x=\\frac{ab-cd}{c-a}$","$x=\\frac{cd-ab}{a+c}$","$x=\\frac{ab+cd}{c-a}$"]', '$x=\frac{ab+cd}{c-a}$', NULL, 'Expand: $ax+ab=cx-cd$. Gather the $x$ terms: $ab+cd=cx-ax=x(c-a)$. Divide: $x=\frac{ab+cd}{c-a}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{ab+cd}{c-a}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ax+ab=cx-cd; ax-cx=-ab-cd; x(a-c)=-(ab+cd); x=(ab+cd)/(c-a)","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
