VALUES ('fbcf3e5b-1a54-45d4-bcfe-e3566ca1c1a6', 'ALG.04', 3, 'choice', 'Solve a formula for one variable: harder forms', 'Solve $xy-3y=z$ for $y$.', '["$y=\\frac{z}{x-3}$","$y=\\frac{z}{x}-3$","$y=\\frac{z}{x+3}$","$y=z-x+3$"]', '$y=\frac{z}{x-3}$', NULL, 'Both terms on the left contain $y$: $y(x-3)=z$. Divide by $x-3$: $y=\frac{z}{x-3}$.', 'checked', '{"lint":[],"solve":{"answer":"$y=\\frac{z}{x-3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y(x-3)=z, y=z/(x-3)","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
