VALUES ('b2c362d8-da9e-4d41-a0be-4c54ab84de3b', 'ALG.04', 3, 'choice', 'Solve a formula for one variable: harder forms', 'Solve $\frac{x}{a}+\frac{y}{b}=1$ for $y$.', '["$y=\\frac{b(a+x)}{a}$","$y=\\frac{b(a-x)}{a}$","$y=\\frac{a(b-x)}{b}$","$y=b-\\frac{x}{a}$"]', '$y=\frac{b(a-x)}{a}$', NULL, '$\frac{y}{b}=1-\frac{x}{a}=\frac{a-x}{a}$. Multiply by $b$: $y=\frac{b(a-x)}{a}$.', 'checked', '{"lint":[],"solve":{"answer":"$y=\\frac{b(a-x)}{a}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/b=1-x/a=(a-x)/a, y=b(a-x)/a","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
