INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c102e4c-f74e-4d49-b36b-38e30097857b', 'ALG.04', 3, 'numeric', 'Reason about how an expression changes', 'If $x+y=7$, what is the value of $3x+3y-4$?', '[]', '17', '3*7-4', '$3x+3y=3(x+y)=21$. So $21-4=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+y)-4=21-4=17","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
