INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('326bd0e9-0c0c-4a43-a23d-a8e96c7ab5fd', 'ALG.04', 3, 'numeric', 'Reason about how an expression changes', 'If $2p-q=5$, what is the value of $4p-2q+1$?', '[]', '11', '2*5+1', '$4p-2q=2(2p-q)=10$. So $10+1=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(2p-q)+1=10+1=11","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
