INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9dc0d1c-250d-47ea-9dc8-461683a97030', 'ALG.04', 3, 'numeric', 'Substitute one expression for a variable', 'A rectangle has perimeter 46. Its length $l$ is 5 more than its width $w$, so $l=w+5$. What is $w$?', '[]', '9', '(46/2-5)/2', '$2l+2w=46$, so $l+w=23$. Then $(w+5)+w=23$, $2w=18$ and $w=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(w+5)+2w=46, 4w=36, w=9","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4397b21d-3657-477e-8fd8-025f6ee4bba9', 'ALG.04', 3, 'choice', 'Write an expression with several variables', 'Small boxes hold $s$ pencils and large boxes hold $l$ pencils. A teacher buys 4 small boxes and 2 large boxes, then gives 15 pencils to each of 3 students. Which expression gives the pencils left?', '["$4s+2l-15$","$4s+2l-45$","$6(s+l)-45$","$4s+2l+45$"]', '$4s+2l-45$', NULL, 'She buys $4s+2l$ pencils and gives away $3\times15=45$. What is left is $4s+2l-45$.', 'checked', '{"lint":[],"solve":{"answer":"$4s+2l-45$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4s+2l pencils, gives 3*15=45: 4s+2l-45","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
