INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95a0c296-6e32-4ecf-8058-17540a216fd1', 'ALG.04', 3, 'numeric', 'Substitute one expression for a variable', 'If $x=3y$ and $2x+y=35$, what is $y$?', '[]', '5', '35/7', 'Replace $x$ by $3y$: $6y+y=35$, so $7y=35$ and $y=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6y+y=35, y=5","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
