INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb499071-8526-4152-b898-9061217f1ecb', 'ALG.04', 3, 'choice', 'Solve a formula for one variable: harder forms', 'A tank has $w$ gallons at the start. A pump adds $p$ gallons each minute, so after $t$ minutes it holds $g=w+pt$. Solve for $t$.', '["$t=\\frac{g+w}{p}$","$t=g-w-p$","$t=\\frac{g-w}{p}$","$t=\\frac{g}{w+p}$"]', '$t=\frac{g-w}{p}$', NULL, 'Subtract $w$: $g-w=pt$. Divide by $p$: $t=\frac{g-w}{p}$.', 'checked', '{"lint":[],"solve":{"answer":"$t=\\frac{g-w}{p}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pt=g-w, t=(g-w)/p","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0351db0-1527-4e14-a57a-7ef41f8e51b9', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'A candle burns down $r$ centimeters each hour. After $t$ hours its height is $h=H-rt$, where $H$ is its starting height. Find $r$ if $H=30$, $h=12$ and $t=6$.', '[]', '3', '(30-12)/6', '$12=30-6r$, so $6r=18$ and $r=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12=30-6r, 6r=18, r=3","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
