INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a188fa5-3256-40bc-8b2a-0cf8dda39be4', 'ALG.04', 3, 'choice', 'Evaluate an expression with several variables', 'When $x=7$ and $y=4$, which is the value of $x^2-2xy+y^2$?', '["121","33","65","9"]', '9', '49-2*7*4+16', '$x^2=49$, $2xy=56$, $y^2=16$. So $49-56+16=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-y)^2=3^2=9 (49-56+16=9)","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
