INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dcde671-1d93-425b-9e95-c7bd5a60aef7', 'ALG.04', 3, 'choice', 'Combine like terms with several variables', 'Simplify $a-(b-c)+(b-a)$ by removing the brackets and combining like terms.', '["$c$","$-c$","$2a-2b+c$","$a-b-c$"]', '$c$', NULL, 'Remove the brackets: $a-b+c+b-a$. The $a$''s cancel and the $b$''s cancel, leaving $c$.', 'checked', '{"lint":[],"solve":{"answer":"$c$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a-b+c+b-a=c","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
