INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56f33ed7-2716-4cdf-abf7-f23ab12fe97e', 'ALG.04', 3, 'numeric', 'Reason about how an expression changes', 'A package''s weight is $W=2a+3b$. If both $a$ and $b$ increase by 4, by how much does $W$ increase?', '[]', '20', '2*4+3*4', '$a$ increases by 4, so $2a$ increases by 8. $b$ increases by 4, so $3b$ increases by 12. In all $W$ goes up by 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 2(4)+3(4)=20","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
