INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d4242ba-4d8e-47e0-b568-9e5a2dd117e0', 'ALG.04', 3, 'numeric', 'Reason about how an expression changes', 'In the expression $4x-y$, the value of $x$ decreases by 2 and the value of $y$ decreases by 3. By how much does the value of the expression change? (Give a negative number for a decrease.)', '[]', '-5', '-8+3', '$4x$ decreases by 8, which changes the value by $-8$. Subtracting $y$ when $y$ is 3 smaller adds 3. The change is $-8+3=-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change =4(-2)-(-3)=-8+3=-5","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
