INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd2b38fe-c488-4c0a-8112-f2b192e9485d', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'How many pairs of positive whole numbers $(a,b)$ satisfy $2a+3b=20$?', '[]', '3', '3', '$3b$ must be $20$ minus an even number, so $b$ is even. $b=2$ gives $a=7$. $b=4$ gives $a=4$. $b=6$ gives $a=1$. $b=8$ would make $a$ negative. So there are 3 pairs.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3b=20-2a so b even: b=2,a=7; b=4,a=4; b=6,a=1. 3 pairs","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e54f9416-b1db-4f24-9e48-68c9bce037b4', 'ALG.04', 3, 'numeric', 'Use a formula to find an unknown value', 'Suppose the Fahrenheit and Celsius readings are the same number, so $F=C$ in $F=\frac{9}{5}C+32$. What is that temperature?', '[]', '-40', '-40', 'Put $F=C$: $C=\frac{9}{5}C+32$. Then $-\frac{4}{5}C=32$, so $C=-40$. Check: $\frac{9}{5}(-40)+32=-72+32=-40$.', 'checked', '{"lint":[],"solve":{"answer":"-40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C=(9/5)C+32, -(4/5)C=32, C=-40","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
