INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7489053-e2dd-4880-a6bc-ca4bf2d52f74', 'ALG.05', 1, 'choice', 'Check which pair solves a system', 'Which pair $(x, y)$ makes both $x+y=7$ and $x-y=1$ true?', '["$(4, 3)$","$(3, 4)$","$(5, 2)$","$(6, 1)$"]', '$(4, 3)$', NULL, 'Try $(4, 3)$: $4+3=7$ and $4-3=1$. Both are true. The other pairs make $x+y=7$ true but not $x-y=1$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 2x=8, x=4; y=3. Check 4-3=1","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
