VALUES ('a02b30ba-024b-4f5d-9d69-7fbf52af2902', 'ALG.05', 2, 'numeric', 'Solve a system by elimination', 'Solve $3x+2y=13$ and $2x-y=4$. What is $y$?', '[]', '2', '(13-3*3)/2', 'Double the second equation: $4x-2y=8$. Add it to the first: $7x=21$, so $x=3$. Then $9+2y=13$ and $y=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=2x-4; 3x+4x-8=13, x=3, y=2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
