INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41faa0e8-af7d-4ff1-8935-2fee2aab5c0a', 'ALG.05', 2, 'numeric', 'Solve a system by elimination', 'Solve $5x+4y=31$ and $3x+2y=17$. What is $y$?', '[]', '4', '(17-3*3)/2', 'Double the second equation: $6x+4y=34$. Subtract the first equation: $x=3$. Then $9+2y=17$ and $y=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double second: 6x+4y=34; minus first: x=3; 9+2y=17, y=4","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
