INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e29e386f-2d95-4030-b0a7-b75e921007b1', 'ALG.05', 2, 'numeric', 'Solve a system by elimination', 'Solve $3x-4y=-10$ and $5x+4y=26$. What is $x+y$?', '[]', '6', '2+4', 'Add the equations: $8x=16$, so $x=2$. Then $10+4y=26$ and $y=4$. So $x+y=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 8x=16, x=2; 10+4y=26, y=4; x+y=6","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
