INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4443d8f-ec55-43dc-9008-541db62f0282', 'ALG.05', 2, 'numeric', 'Solve a system by elimination', 'The equations $4x+3y=10$ and $2x+y=4$ are to be solved by subtraction after multiplying the second equation by a number so that the $y$ terms match. What number should the second equation be multiplied by?', '[]', '3', '3', 'The first equation has $3y$ and the second has $y$. Multiplying the second by 3 gives $6x+3y=12$, which has $3y$ too.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply 2x+y=4 by 3: 6x+3y=12, y terms match","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
