INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('924192b0-2803-4861-9d74-f2df02ad15c2', 'ALG.05', 2, 'choice', 'Check which pair solves a system', 'Which pair $(x, y)$ solves both $2x+5y=1$ and $3x-2y=11$?', '["$(-1, 3)$","$(3, 1)$","$(-3, 1)$","$(3, -1)$"]', '$(3, -1)$', NULL, 'Try $(3,-1)$: $6-5=1$ and $9+2=11$. Both are true. Each other pair breaks one of them.', 'checked', '{"lint":[],"solve":{"answer":"$(3, -1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,-1): 6-5=1, 9+2=11","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
