INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da414b45-b7e7-42cf-a02f-f92dfe470b47', 'ALG.05', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $x+y=5$ and $2x+2y=10$ have?', '["infinitely many solutions","exactly one solution","exactly two solutions","no solution"]', 'infinitely many solutions', NULL, 'Doubling the first equation gives the second, so they say the same thing. Any pair with $x+y=5$ works, which is infinitely many.', 'checked', '{"lint":[],"solve":{"answer":"infinitely many solutions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second is twice the first: same line","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
