INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8f6c203-693d-4c46-9c36-33218361c8e4', 'ALG.05', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $x-y=3$ and $2x-2y=8$ have?', '["exactly one solution","no solution","exactly two solutions","infinitely many solutions"]', 'no solution', NULL, 'Doubling the first equation gives $2x-2y=6$, but the second says $2x-2y=8$. Both cannot be true, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"no solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second gives x-y=4, contradicts x-y=3","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
