INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('927292a5-783a-4dc2-a948-fd595398ffc8', 'ALG.05', 2, 'numeric', 'Find an unknown coefficient from a solution', 'The solution of $x+y=8$ and $x-y=2$ also satisfies $ax+y=18$. What is $a$?', '[]', '3', '(18-3)/5', 'Adding the first two gives $2x=10$, so $x=5$ and $y=3$. Then $5a+3=18$ and $a=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=5, y=3; 5a+3=18, a=3","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
