INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('793ba7a6-b82a-4273-94b1-24ccc85d8171', 'ALG.05', 2, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'A farm has 10 animals, all hens and cows, and they have 26 legs in all. How many cows are there?', '["7","4","3","6"]', '3', '(26-2*10)/2', 'Let $h$ be hens and $c$ cows. $h+c=10$ and $2h+4c=26$. Double the first: $2h+2c=20$. Subtract: $2c=6$, so $c=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h+c=10, 2h+4c=26; 2c=6, c=3","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
