INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('145822fb-0855-4764-a3f9-c2270d585780', 'ALG.05', 2, 'choice', 'Word problem leading to a system: money and mixtures', 'A theater sold 40 tickets for 275 dollars. Adult tickets cost 8 dollars and child tickets cost 5 dollars. How many adult tickets were sold?', '["15","20","30","25"]', '25', '(275-5*40)/(8-5)', '$a+c=40$ and $8a+5c=275$. Multiply the first by 5: $5a+5c=200$. Subtract: $3a=75$, so $a=25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+c=40, 8a+5c=275; 3a=75, a=25","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
