INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24b765c4-5ce6-45cb-bfa8-487ce064fb25', 'ALG.05', 2, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'Mia is 3 times as old as Joe. In 4 years the sum of their ages will be 40. How old is Mia now?', '["24","8","12","32"]', '24', '3*8', 'Let Joe be $j$ now, so Mia is $3j$. In 4 years: $(3j+4)+(j+4)=40$. So $4j=32$, $j=8$ and Mia is 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M=3J, M+J+8=40, J=8, M=24","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
