INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('645f6ac9-3a94-4be2-93e9-f5dc3d943327', 'ALG.05', 2, 'numeric', 'Word problem leading to a system: motion and rates', 'A boat goes 14 miles per hour downstream and 6 miles per hour upstream. How fast is the current, in miles per hour?', '[]', '4', '(14-6)/2', 'Downstream is boat plus current: $b+c=14$. Upstream is boat minus current: $b-c=6$. Subtracting: $2c=8$, so $c=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b+c=14, b-c=6, c=4","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
