INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a54f66f-f1f4-4d2c-a40b-f8c26fa2783c', 'ALG.05', 2, 'choice', 'Word problem leading to a system: money and mixtures', 'A snack mix is made of nuts costing 6 dollars per pound and raisins costing 3 dollars per pound. 10 pounds of the mix cost 42 dollars. How many pounds of nuts are in it?', '["6","4","5","8"]', '4', '(42-3*10)/(6-3)', '$n+r=10$ and $6n+3r=42$. Multiply the first by 3: $3n+3r=30$. Subtract: $3n=12$, so $n=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n+r=10, 6n+3r=42; 3n=12, n=4","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
