INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4fef114-d5aa-4fa3-926c-522f75fe8dee', 'ALG.05', 2, 'numeric', 'Word problem leading to a system: numbers, ages and shapes', 'The sum of two numbers is 22. Twice the first number minus the second is 5. What is the larger number?', '[]', '13', '22-9', '$x+y=22$ and $2x-y=5$. Add: $3x=27$, so $x=9$. Then $y=22-9=13$, the larger.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b=22, 2a-b=5; a=9, b=13; larger 13","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
