INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a29aaf6-d79e-48fe-a5c4-e071ce73cb63', 'ALG.05', 2, 'numeric', 'Word problem leading to a system: numbers, ages and shapes', 'A rectangle has perimeter 28 centimeters, and its length is 2 centimeters more than its width. What is its area, in square centimeters?', '[]', '48', '6*8', '$l+w=14$ and $l=w+2$. So $2w+2=14$, $w=6$ and $l=8$. The area is $6\times8=48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"l+w=14, l=w+2; w=6, l=8; area 48","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
