INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('815411e1-87fa-483e-bcc2-6c76a48b5438', 'ALG.05', 2, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'A 48 centimeter ribbon is cut into two pieces. One piece is 8 centimeters longer than 3 times the other. How long is the longer piece, in centimeters?', '["10","28","38","30"]', '38', '3*10+8', 'Let the short piece be $s$. Then $s+(3s+8)=48$, so $4s=40$ and $s=10$. The longer piece is $3\times10+8=38$.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+3x+8=48, x=10, longer 38","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
