INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31835e31-1798-4f71-a26f-ff0bd4873c09', 'ALG.05', 2, 'choice', 'Word problem leading to a system: money and mixtures', 'Ana pays 210 cents for 2 pens and 3 pencils. Ben pays 240 cents for 3 pens and 2 pencils at the same prices. What is the price of one pen, in cents?', '["30","90","120","60"]', '60', '(3*240-2*210)/5', '$2p+3q=210$ and $3p+2q=240$. Adding: $5p+5q=450$, so $p+q=90$. Subtracting: $p-q=30$. So $p=60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2p+3q=210, 3p+2q=240: p+q=90, p-q=30, p=60","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
