INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d06aba2-3035-44e2-ad71-444491cab98a', 'ALG.05', 2, 'choice', 'Solve a system of three equations', 'Three numbers satisfy $x+y=7$, $y+z=9$ and $x+z=8$. What is $z$?', '["5","3","4","12"]', '5', '12-7', 'Add all three: $2(x+y+z)=24$, so $x+y+z=12$. Then $z=12-(x+y)=12-7=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x+y+z)=24, x+y+z=12, z=12-7=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
