INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b09c0a9d-0373-486b-9778-5c9895944177', 'ALG.05', 2, 'choice', 'Find a sum, difference or product from a system', 'Which statement is true about the solution of $2x+y=7$ and $x-y=2$?', '["$x=y+1$","$x+y=5$","$x=3y$","$y=x+2$"]', '$x=3y$', NULL, 'Adding the equations gives $3x=9$, so $x=3$. Then $y=1$. So $x=3y$ is true, while the other statements are false.', 'checked', '{"lint":[],"solve":{"answer":"$x=3y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 3x=9, x=3, y=1; x=3y true, others false","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
