INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5f764c9-cc00-4126-98ca-a79959559a1a', 'ALG.05', 2, 'choice', 'Write the system for a word problem', 'To eliminate $x$ from $x+2y=9$ and $3x-y=6$, which first step works?', '["Multiply the first equation by 3, then add the second","Multiply the second equation by 3, then subtract the first","Add the two equations as they are","Multiply the first equation by 3, then subtract the second"]', 'Multiply the first equation by 3, then subtract the second', NULL, 'Times 3, the first equation is $3x+6y=27$. Its $x$ term matches $3x$ in the second, so subtracting removes $x$: $7y=21$.', 'checked', '{"lint":[],"solve":{"answer":"Multiply the first equation by 3, then subtract the second","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6y=27 minus 3x-y=6 gives 7y=21; other steps leave x","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
