INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('617e9267-31a0-4560-b25c-07a1d7ba8742', 'ALG.05', 2, 'numeric', 'Find a sum, difference or product from a system', 'If $4x+y=17$ and $2x-y=1$, what is the value of $y-x$?', '[]', '2', '5-3', 'Adding gives $6x=18$, so $x=3$. Then $12+y=17$ and $y=5$. So $y-x=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 6x=18, x=3, y=5; y-x=2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
