INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f5a2436-29d8-4870-818e-1cc8531eb27d', 'ALG.05', 2, 'numeric', 'Word problem leading to a system: numbers, ages and shapes', 'Two numbers differ by 7. Three times the smaller number equals twice the larger number. What is the smaller number?', '[]', '14', '14', 'Let the smaller be $s$, the larger $s+7$. Then $3s=2(s+7)=2s+14$, so $s=14$. (The larger is 21, and $3\times14=2\times21$.)', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L=S+7, 3S=2S+14, S=14","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
