INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0fdf948-144c-4821-a1a5-e1f2952c8363', 'ALG.05', 3, 'choice', 'Solve a system by elimination', 'Solve $3x+4y=1$ and $5x-3y=-8$. What is $y$?', '["-1","1","2","5"]', '1', '1', 'Multiply the first by 3 and the second by 4: $9x+12y=3$ and $20x-12y=-32$. Add: $29x=-29$, so $x=-1$. Then $-3+4y=1$ and $y=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x3: 9x+12y=3; x4: 20x-12y=-32; 29x=-29, x=-1, y=1","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
