INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('991a1015-a64b-4f46-aff3-6f44a40c5d67', 'ALG.05', 3, 'choice', 'Solve a system by elimination', 'Solve $4x+3y=5$ and $6x-2y=1$. What is $x$?', '["1","1/3","1/2","2"]', '1/2', '1/2', 'Multiply the first by 2 and the second by 3: $8x+6y=10$ and $18x-6y=3$. Add: $26x=13$, so $x=\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x2: 8x+6y=10; x3: 18x-6y=3; 26x=13, x=1/2, y=1","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
