INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81f75f34-5d92-4911-b928-8422ee2c4692', 'ALG.05', 3, 'choice', 'Solve a system by elimination', 'Solve $\frac{x}{2}+\frac{y}{3}=4$ and $\frac{x}{4}-\frac{y}{6}=0$. What is $y$?', '["4","3","12","6"]', '6', '6', 'Multiply the first by 6: $3x+2y=24$. Multiply the second by 12: $3x-2y=0$. Add: $6x=24$, so $x=4$. Then $12+2y=24$ and $y=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/4=y/6 so x=2y/3; y/3+y/3=4, y=6, x=4","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
