INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2ab7d6d-c4a5-44fb-9605-fc79acfd6a1c', 'ALG.05', 3, 'numeric', 'Solve a system by substitution', 'Solve $2(x+1)+3y=19$ and $x=y+1$. What is the value of $xy$?', '[]', '12', '4*3', 'Replace $x$: $2(y+2)+3y=19$, so $5y+4=19$ and $y=3$. Then $x=4$ and $xy=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(y+2)+3y=19, y=3, x=4, xy=12","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
