INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76e95eb6-cb8d-476e-a671-f25a974aec3f', 'ALG.05', 3, 'numeric', 'Count the solutions of a system', 'The system $2x+3y=5$ and $4x+6y=k$ has infinitely many solutions. What is $k$?', '[]', '10', '2*5', 'Doubling the first equation gives $4x+6y=10$. The second equation is the same as this only if $k=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second must be 2x first: k=10","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
