INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7adfb564-f571-4045-8530-f766a1af9e1a', 'ALG.05', 3, 'numeric', 'Find an unknown coefficient from a solution', 'The pair $(2,-1)$ solves both $ax+by=7$ and $bx-ay=1$. What is $a$?', '[]', '3', '3', 'First equation: $2a-b=7$. Second: $2b+a=1$. From the first, $b=2a-7$. Then $2(2a-7)+a=1$, so $5a=15$ and $a=3$. (Then $b=-1$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a-b=7, 2b+a=1; b=2a-7, 5a-14=1, a=3, b=-1","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
