INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0929712c-4ef3-45e7-bdbc-6824303f2e56', 'ALG.05', 3, 'choice', 'Solve a system of three equations', 'Solve $x+y+z=6$, $2x-y+z=3$ and $x+2y-z=2$. What is $z$?', '["3","1","2","6"]', '3', '3', 'Add the first and third equations: $2x+3y=8$. Add the second and third: $3x+y=5$, so $y=5-3x$. Then $2x+15-9x=8$, so $x=1$, $y=2$, and $z=6-1-2=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"eq1-eq2: x=2y-3; eq1+eq3: 2x+3y=8, y=2, x=1, z=3","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b5f43cd-2ce1-41d8-8327-2c88fa6074e9', 'ALG.05', 3, 'choice', 'Solve a system of three equations', 'The sum of three numbers is 30. The first is twice the second. The third is 2 less than the second. What is the largest of the three numbers?', '["8","16","6","12"]', '16', '2*8', 'Let the second be $y$. The numbers are $2y$, $y$ and $y-2$. So $4y-2=30$, $y=8$. The numbers are 16, 8 and 6.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=2b, c=b-2; 4b-2=30, b=8, a=16, c=6","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34b3827e-53d8-4818-a5d8-b3c294f9be6c', 'ALG.05', 3, 'choice', 'Find a sum, difference or product from a system', 'If $x-y+z=2$, $x+y-z=6$ and $-x+y+z=4$, what is the value of $x+y+z$?', '["6","8","12","14"]', '12', '(2+6+4)', 'Add all three equations. The $x$''s give $x+x-x=x$, the $y$''s give $-y+y+y=y$, and the $z$''s give $z-z+z=z$. So $x+y+z=2+6+4=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add all three: x+y+z=12","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
