INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('243f7f11-1309-4c8c-be38-5eed2efc3c35', 'ALG.05', 3, 'numeric', 'Solve a system of three equations', 'Three numbers satisfy $a+b+c=11$, $a-b=2$ and $b-c=3$. What is $a$?', '[]', '6', '4+2', '$a=b+2$ and $c=b-3$. So $(b+2)+b+(b-3)=11$, which gives $3b-1=11$ and $b=4$. Then $a=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=b+2, c=b-3; 3b-1=11, b=4, a=6","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba1a82e5-1587-4714-b830-64aaafccfef8', 'ALG.05', 3, 'choice', 'Word problem leading to a system: money and mixtures', 'A shop mixes tea costing 8 dollars per pound with tea costing 12 dollars per pound to make 20 pounds of tea worth 180 dollars in all. How many pounds of the 12-dollar tea are used?', '["15","10","4","5"]', '5', '(180-8*20)/(12-8)', '$a+b=20$ and $8a+12b=180$. Multiply the first by 8: $8a+8b=160$. Subtract: $4b=20$, so $b=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=20, 8x+12y=180; 4y=20, y=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
