INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('236af4ae-1c0e-48f4-b471-59e8365c76b9', 'ALG.05', 3, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'Mr. Chen is 4 times as old as his son. Six years ago he was 7 times as old as his son. How old is the son now?', '["12","48","6","7"]', '12', '12', 'Let the son be $s$ and Mr. Chen $4s$. Six years ago: $4s-6=7(s-6)$. So $4s-6=7s-42$, $3s=36$ and $s=12$. (Check: 6 and 42 six years ago.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"F=4s, 4s-6=7(s-6), 3s=36, s=12","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
