INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccde27bb-e085-44aa-a84a-1bbf1ca16f64', 'ALG.05', 3, 'choice', 'Word problem leading to a system: motion and rates', 'Two cars start 300 miles apart and drive toward each other. They meet after 3 hours. One car is 20 miles per hour faster than the other. What is the speed of the faster car, in miles per hour?', '["40","60","80","100"]', '60', '(300/3+20)/2', 'Together they close 100 miles each hour, so $s+(s+20)=100$. Then $s=40$ and the faster car goes 60 miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(v+v+20)=300, v=40, faster 60","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
