INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('267274f9-7246-4c21-864c-52798e9e7b32', 'ALG.05', 3, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'The digits of a two-digit number add up to 11. If the digits are reversed, the number becomes 27 more. What is the original number?', '["74","56","47","38"]', '47', '47', 'Tens digit $t$, ones digit $u$: $t+u=11$ and $(10u+t)-(10t+u)=27$, so $9(u-t)=27$ and $u-t=3$. Then $u=7$, $t=4$. The number is 47 (and 74 is 27 more).', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b=11, 9(b-a)=27, b-a=3; a=4, b=7: 47","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('607afc68-1604-4ae5-8d3e-44848ab4eeec', 'ALG.05', 3, 'choice', 'Word problem leading to a system: money and mixtures', 'A jar has 30 coins, all quarters and dimes, worth 555 cents. How many quarters are there?', '["13","15","22","17"]', '17', '(555-10*30)/(25-10)', '$q+d=30$ and $25q+10d=555$. Multiply the first by 10: $10q+10d=300$. Subtract: $15q=255$, so $q=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"q+d=30, 25q+10d=555; 15q=255, q=17","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
