INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0364d36-79fd-4bf3-a163-486c300e4b2f', 'ALG.05', 3, 'choice', 'Word problem leading to a system: money and mixtures', 'Ms. Ray puts 10000 dollars into two accounts. One earns 3 percent a year and the other earns 5 percent a year. After one year the interest is 380 dollars. How many dollars are in the 5 percent account?', '["4000","6000","5000","3000"]', '4000', '(380-0.03*10000)/(0.05-0.03)', 'Let $y$ be the 5 percent account. The other holds $10000-y$. Then $0.03(10000-y)+0.05y=380$, so $300+0.02y=380$ and $y=4000$.', 'checked', '{"lint":[],"solve":{"answer":"4000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=10000, .03x+.05y=380; 300+.02y=380, y=4000","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
