INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a86432f-f7fa-4b73-b6e1-f2befd4cd630', 'ALG.05', 3, 'choice', 'Word problem leading to a system: motion and rates', 'A boat travels 24 miles downstream in 2 hours and comes back upstream in 3 hours. What is the speed of the current, in miles per hour?', '["4","2","10","12"]', '2', '(24/2-24/3)/2', 'Downstream speed $=24\div2=12$. Upstream speed $=24\div3=8$. The boat''s speed plus the current is 12 and minus the current is 8, so the current is $(12-8)\div2=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"down 12, up 8 mph; current (12-8)/2=2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
