INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cab6cbf-9781-4405-98ed-cecf3119815c', 'ALG.05', 3, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'A rectangle''s length is 3 times its width. If the length is decreased by 4 and the width is increased by 2, the rectangle becomes a square. What is the perimeter of the original rectangle?', '["12","27","24","36"]', '24', '2*(3+9)', '$l=3w$ and $l-4=w+2$. So $3w-4=w+2$, $w=3$ and $l=9$. The perimeter is $2(3+9)=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L=3W, 3W-4=W+2, W=3, L=9; perimeter 24","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31a376a3-201c-4df3-a479-7e2fd5efaca8', 'ALG.05', 3, 'choice', 'Word problem leading to a system: numbers, ages and shapes', 'The numerator and denominator of a fraction add up to 15. When 3 is added to both, the fraction becomes $\frac{1}{2}$. What is the denominator of the original fraction?', '["4","7","14","11"]', '11', '11', 'Let the fraction be $\frac{n}{d}$. $n+d=15$ and $\frac{n+3}{d+3}=\frac{1}{2}$, so $2n+6=d+3$ and $d=2n+3$. Then $3n+3=15$, $n=4$ and $d=11$. (Check: $\frac{7}{14}=\frac{1}{2}$.)', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n+d=15, 2(n+3)=d+3; 3n+3=15, n=4, d=11","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbc7c6f2-b7e6-4928-9fba-6308c5fd5506', 'ALG.05', 3, 'numeric', 'Word problem leading to a system: motion and rates', '2 machines of type A and 3 machines of type B make 130 parts per hour. 4 machines of type A and 1 machine of type B make 110 parts per hour. How many parts per hour does one machine of type A make?', '[]', '20', '20', '$2a+3b=130$ and $4a+b=110$. Multiply the second by 3: $12a+3b=330$. Subtract the first: $10a=200$, so $a=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a+3b=130, 4a+b=110; b=110-4a, -10a=-200, a=20","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
