VALUES ('b66e7e03-4db6-4462-aa81-7ebb68bf95ec', 'ALG.05', 3, 'choice', 'Find a sum, difference or product from a system', 'If $2x+3y=12$ and $3x+2y=13$, what is the value of $x+y$?', '["25","5","6","1"]', '5', '(12+13)/5', 'Add the equations: $5x+5y=25$. Divide by 5: $x+y=5$. (You do not need $x$ and $y$ separately.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 5x+5y=25, x+y=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
