INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac2c0e10-6fd1-415e-9b02-08f4866ca8ff', 'ALG.05', 3, 'choice', 'Check which pair solves a system', 'Which pair $(x, y)$ solves $3x-2y=16$ and $2x+5y=-2$?', '["$(4, -2)$","$(-2, 4)$","$(4, 2)$","$(-4, 2)$"]', '$(4, -2)$', NULL, 'Try $(4,-2)$: $12+4=16$ and $8-10=-2$. Both hold. The other pairs fail the first equation.', 'checked', '{"lint":[],"solve":{"answer":"$(4, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,-2): 12+4=16, 8-10=-2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
