INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77a103f8-4c92-480a-a846-1e7e971331f4', 'ALG.05', 3, 'numeric', 'Word problem leading to a system: money and mixtures', '3 pens and 2 notebooks cost 12 dollars. 1 pen and 4 notebooks cost 14 dollars. How many dollars does one notebook cost?', '[]', '3', '(3*14-12)/10', '$3p+2n=12$ and $p+4n=14$. Multiply the second by 3: $3p+12n=42$. Subtract the first: $10n=30$, so $n=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p=14-4n; 3(14-4n)+2n=12, n=3, p=2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
