INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39bb130c-1334-476a-8de0-0dea40a71241', 'ALG.05', 3, 'numeric', 'Solve a system by elimination', 'Solve $3x+y=17$ and $x+3y=11$. What is $x$?', '[]', '5', '(3*17-11)/8', 'Multiply the first by 3: $9x+3y=51$. Subtract the second: $8x=40$, so $x=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: x+y=7; subtract: x-y=3; x=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
