INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21bcc89e-8bd8-49ed-9a24-bd340d17dc55', 'ALG.05', 3, 'choice', 'Write the system for a word problem', 'A farm has 18 animals, all chickens and goats. Together they have 52 legs. Let $c$ be the chickens and $g$ the goats. Which pair of equations matches this?', '["$c+g=18$ and $4c+2g=52$","$c+g=18$ and $2c+4g=52$","$c+g=52$ and $2c+4g=18$","$c+g=18$ and $c+g=52$"]', '$c+g=18$ and $2c+4g=52$', NULL, 'The animals number $c+g=18$. A chicken has 2 legs and a goat has 4, so the legs number $2c+4g=52$.', 'checked', '{"lint":[],"solve":{"answer":"$c+g=18$ and $2c+4g=52$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 legs each chicken, 4 each goat","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f5c30b-62ce-4289-8120-ed023c3f97cd', 'ALG.05', 3, 'numeric', 'Solve a system of three equations', 'Solve $x+y+z=6$, $x+2y+3z=14$ and $x+4y+9z=36$. What is $z$?', '[]', '3', '3', 'Subtract the first from the second: $y+2z=8$. Subtract the second from the third: $2y+6z=22$, so $y+3z=11$. Then $z=11-8=3$ (and $y=2$, $x=1$).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"eq2-eq1: y+2z=8; eq3-eq2: y+3z=11; z=3 (y=2, x=1)","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('281ac213-914c-46d0-9537-212c9c2f4412', 'ALG.05', 3, 'numeric', 'Word problem leading to a system: motion and rates', 'Pipe A fills a tank at $a$ liters per minute and pipe B at $b$ liters per minute. When A runs for 4 minutes and B for 5 minutes, they put in 58 liters. When A runs for 6 minutes and B for 2 minutes, they put in 54 liters. What is $a$?', '[]', '7', '7', '$4a+5b=58$ and $6a+2b=54$. Multiply the first by 2 and the second by 5: $8a+10b=116$ and $30a+10b=270$. Subtract: $22a=154$, so $a=7$. (Then $b=6$.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a+5b=58, 3a+b=27; b=27-3a, 4a+135-15a=58, a=7","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0dfbcd8-46f5-491c-8406-71ee38dc07e1', 'ALG.05', 3, 'numeric', 'Find an unknown coefficient from a solution', 'The solution of $x+y=10$ and $x-y=4$ also satisfies $x=ky+1$. What is $k$?', '[]', '2', '(7-1)/3', 'Adding the first two gives $2x=14$, so $x=7$ and $y=3$. Then $7=3k+1$, so $k=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=7, y=3; 7=3k+1, k=2","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
