INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f523ba2-368c-46b1-816b-5abaf818d219', 'ALG.05', 3, 'numeric', 'Solve a system of three equations', 'Three numbers satisfy $x=2y$, $z=x+y+6$ and $x+y+z=30$. What is $z$?', '[]', '18', '8+4+6', '$x+y=3y$, so $z=3y+6$. Then $3y+3y+6=30$, $y=4$. So $x=8$ and $z=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=2y, z=3y+6; 6y+6=30, y=4, z=18","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
