INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f15f0b0-a4cf-4e74-a9ff-6a4093c3be92', 'ALG.06', 1, 'choice', 'Writing and simplifying ratios', 'A pet shop has 8 cats and 20 dogs. Which statement is true?', '["For every 5 cats there are 2 dogs.","For every 3 cats there are 5 dogs.","For every 2 cats there are 10 dogs.","For every 2 cats there are 5 dogs."]', 'For every 2 cats there are 5 dogs.', NULL, '$8:20$ becomes $2:5$ when both numbers are divided by 4. So for every 2 cats there are 5 dogs.', 'checked', '{"lint":[],"solve":{"answer":"For every 2 cats there are 5 dogs.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8:20 = 2:5 (divide by 4): for every 2 cats, 5 dogs.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
