INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c502fb2c-2650-4764-9178-0970877be34e', 'ALG.06', 1, 'choice', 'Writing and simplifying ratios', 'Which ratio is NOT equal to $6:9$?', '["$9:6$","$2:3$","$4:6$","$12:18$"]', '$9:6$', NULL, '$6:9 = 2:3 = 4:6 = 12:18$. The ratio $9:6$ has the numbers in the other order, so it is not equal.', 'checked', '{"lint":[],"solve":{"answer":"$9:6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6:9=2:3. 4:6=2:3, 2:3, 12:18=2:3 equal; 9:6=3:2 is not.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
