INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a277323-233a-4238-bc35-b6bed1d1a0f0', 'ALG.06', 1, 'choice', 'Using a ratio to find a quantity', 'The ratio of the length to the width of a rectangle is $7:3$. The width is 9 cm. What is the length, in centimeters?', '["$27$","$12$","$21$","$16$"]', '$21$', '9/3*7', '$9 = 3 \times 3$, so each part is 3 cm. The length is $7 \times 3 = 21$ cm.', 'checked', '{"lint":[],"solve":{"answer":"$21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 3 parts = 9, part = 3, length 7*3 = 21.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
