VALUES ('fade548b-d879-4ce2-9819-da31038fc50a', 'ALG.06', 2, 'choice', 'Fractions, decimals and percents', 'Which of these is NOT equal to 40%?', '["$\\frac{2}{5}$","$0.04$","$0.4$","$\\frac{4}{10}$"]', '$0.04$', NULL, '40% is $0.40$, which equals $\frac{4}{10}$ and $\frac{2}{5}$. The decimal $0.04$ is only 4%.', 'checked', '{"lint":[],"solve":{"answer":"$0.04$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40% = 0.4 = 4/10 = 2/5; 0.04 = 4% is not.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
