INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d20d4fe9-2e70-4533-ae7d-213105f8fbc7', 'ALG.06', 2, 'numeric', 'Fractions, decimals and percents', 'Write $\frac{7}{20}$ as a percent. Give the number of percent, without the % sign.', '[]', '35', '7/20*100', '$\frac{7}{20} = \frac{35}{100} = 35\%$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/20 = 35/100 = 35%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
