INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8878feae-75c9-440a-bdca-8d7d1b9e9bca', 'ALG.06', 2, 'numeric', 'Fractions, decimals and percents', 'A savings account pays 0.6% interest for one month. As a decimal, what number do you multiply the balance by to find the interest?', '[]', '0.006', '0.6/100', 'Percent means per hundred, so divide by 100: $0.6 \div 100 = 0.006$.', 'checked', '{"lint":[],"solve":{"answer":"0.006","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6% = 0.006.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
