INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a72f86c5-c118-4023-bae5-27a3693415f1', 'ALG.06', 2, 'choice', 'Fractions, decimals and percents', 'Which of these numbers is the greatest?', '["$0.6$","55%","$\\frac{3}{5}$","$\\frac{5}{8}$"]', '$\frac{5}{8}$', NULL, 'As decimals: $0.6$, $0.55$, $\frac{5}{8} = 0.625$, $\frac{3}{5} = 0.6$. The greatest is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 = 0.625, 0.6, 0.55, 0.6. Greatest 5/8.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
