INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ba7b81d-fc4d-41a4-9630-8b50172d65d2', 'ALG.06', 2, 'numeric', 'Finding the percent or the whole', 'On a quiz with 40 questions, Lena got 34 right. What percent of the questions did she get right? Give the number of percent, without the % sign.', '[]', '85', '34/40*100', '$\frac{34}{40} = \frac{85}{100}$, so she got 85% right.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34/40 = 0.85 = 85%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
