INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86c0684f-bf23-4209-a8a3-6c2f437ebd9b', 'ALG.06', 2, 'choice', 'Finding the percent or the whole', 'Dana has read 60 pages of a book, which is 40% of the book. How many pages are in the whole book?', '["$24$","$100$","$150$","$240$"]', '$150$', '60/0.4', '40% is 60 pages, so 10% is 15 pages. The whole book is $10 \times 15 = 150$ pages.', 'checked', '{"lint":[],"solve":{"answer":"$150$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4n = 60, n = 150.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
