INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b652288b-b641-436f-a419-b70c0eb6f3f3', 'ALG.06', 2, 'choice', 'Percent increase and decrease', 'A jacket costs 120 dollars. It is on sale for 35% off. What is the sale price in dollars?', '["$42$","$78$","$85$","$84$"]', '$78$', '120*0.65', '35% of 120 is 42, so the sale price is $120 - 42 = 78$ dollars. (42 is the amount taken off.)', 'checked', '{"lint":[],"solve":{"answer":"$78$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"65% of 120 = 78.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
