VALUES ('89860523-d750-4d76-9271-1692220afebf', 'ALG.06', 2, 'numeric', 'Percent increase and decrease', 'A bike costs 250 dollars before tax. The sales tax is 6%. What is the total cost in dollars, tax included?', '[]', '265', '250*1.06', '6% of 250 is 15 dollars. The total is $250 + 15 = 265$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"265","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6% of 250 = 15; 265.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
