INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28614a38-3336-48f4-939b-ee8571201a11', 'ALG.06', 2, 'numeric', 'Percent increase and decrease', 'A shop''s sales fell by 20% and are now 360 dollars. How many dollars were its sales before they fell?', '[]', '450', '360/0.8', 'After a 20% fall, sales are 80% of before. 80% of the old amount is 360, so 10% is 45 and the old amount is 450 dollars.', 'checked', '{"lint":[],"solve":{"answer":"450","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8x = 360, x = 450.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
