INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de34aed-7a87-4e99-9edf-5f3a7dcfd9fa', 'ALG.06', 2, 'numeric', 'Successive percent changes', 'A price of 200 dollars is raised by 10%. Then the new price is lowered by 10%. What is the final price in dollars?', '[]', '198', '200*1.1*0.9', 'After the rise: $200 \times 1.1 = 220$. The 10% cut is of 220, which is 22, so the final price is $220 - 22 = 198$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"198","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200*1.1 = 220; 220*0.9 = 198.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
