INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b885d0ff-2304-4c87-9fc5-3cbd3d5e90c3', 'ALG.06', 2, 'choice', 'Successive percent changes', 'A price is raised by 50%, and then the new price is lowered by 50%. How does the final price compare with the original?', '["It is 25% lower than the original.","It is the same as the original.","It is 25% higher than the original.","It is 50% lower than the original."]', 'It is 25% lower than the original.', NULL, 'Start at 100. After a 50% rise it is 150. A 50% cut of 150 takes off 75, leaving 75. That is 25% lower than 100.', 'checked', '{"lint":[],"solve":{"answer":"It is 25% lower than the original.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5*0.5 = 0.75: 25% lower.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
