INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('544d7b4c-4b6a-4f35-a077-9fce0a6f5322', 'ALG.06', 2, 'numeric', 'Successive percent changes', 'A 50-dollar item is discounted by 20%. The sale price is then discounted by another 10%. What is the final price in dollars?', '[]', '36', '50*0.8*0.9', 'After 20% off: $50 \times 0.8 = 40$. Then 10% off 40 is $40 \times 0.9 = 36$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50*0.8 = 40; 40*0.9 = 36.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
