INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('beb5b959-e00e-45fe-9de0-6412133fbdf2', 'ALG.06', 2, 'numeric', 'Mixture problems', 'A chemist mixes 200 mL of a 15% acid solution with 300 mL of a 40% acid solution. What percent of the mixture is acid? Give the number of percent, without the % sign.', '[]', '30', '(200*0.15+300*0.4)/500*100', 'Acid in the first: $0.15 \times 200 = 30$ mL. Acid in the second: $0.4 \times 300 = 120$ mL. Together 150 mL in 500 mL, and $\frac{150}{500} = 30\%$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acid 30 + 120 = 150 mL of 500 mL = 30%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
