INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04d665c8-6c43-49ca-b278-b5ab55b498fd', 'ALG.06', 3, 'choice', 'Writing and simplifying ratios', 'The ratio of apples to bananas is $2:3$, and the ratio of bananas to cherries is $6:5$. What is the ratio of apples to cherries?', '["$2:5$","$5:4$","$4:5$","$12:5$"]', '$4:5$', NULL, 'Make the banana numbers match: $2:3 = 4:6$. Then apples : bananas : cherries is $4:6:5$, so apples to cherries is $4:5$.', 'checked', '{"lint":[],"solve":{"answer":"$4:5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a:b = 2:3 = 4:6, b:c = 6:5, so a:c = 4:5.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('126409ca-d975-4f7e-b91e-a599ac473c41', 'ALG.06', 3, 'choice', 'Writing and simplifying ratios', 'Ann and Ben have coins in the ratio $3:5$. Ann gives 4 coins to Ben, and then Ann''s coins to Ben''s coins are in the ratio $1:3$. How many coins did Ann have at first?', '["$8$","$12$","$20$","$15$"]', '$12$', NULL, 'Let Ann have $3k$ and Ben $5k$. After the gift: $\frac{3k-4}{5k+4} = \frac{1}{3}$, so $9k - 12 = 5k + 4$ and $k = 4$. Ann had $3 \times 4 = 12$. Check: $8 : 24 = 1:3$.', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ann 3k, Ben 5k. (3k-4)/(5k+4) = 1/3: 9k-12 = 5k+4, k = 4. Ann 12 (then 8:24 = 1:3).","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9009396-8c6f-4991-aae9-0efb23ff52f5', 'ALG.06', 3, 'choice', 'Writing and simplifying ratios', 'The ratio of $x$ to $y$ is $2:5$. What is the ratio of $x+y$ to $y$?', '["$7:2$","$2:7$","$3:5$","$7:5$"]', '$7:5$', NULL, 'Take $x = 2k$ and $y = 5k$. Then $x + y = 7k$, so $(x+y):y = 7k : 5k = 7:5$.', 'checked', '{"lint":[],"solve":{"answer":"$7:5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=2t, y=5t; x+y = 7t; 7:5.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35156c34-f088-4449-a9d9-48cbeae0d75c', 'ALG.06', 3, 'numeric', 'Writing and simplifying ratios', 'In a group the ratio of boys to girls is $4:5$. After 6 more girls join, the ratio of boys to girls is $4:7$. How many boys are in the group?', '[]', '12', '4*3', 'Let boys be $4k$ and girls $5k$. Then $\frac{4k}{5k+6} = \frac{4}{7}$, so $28k = 20k + 24$ and $k = 3$. Boys: $4 \times 3 = 12$ (and girls were 15, then 21).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 4k, girls 5k. 4k/(5k+6) = 4/7: 28k = 20k+24, k = 3; boys 12.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('455a5161-feec-4253-a996-f407dea8e54b', 'ALG.06', 3, 'choice', 'Writing and simplifying ratios', 'The three angles of a triangle are in the ratio $2:3:4$. How many degrees is the largest angle?', '["$80$","$60$","$90$","$40$"]', '$80$', '180/9*4', 'The angles of a triangle add to $180^\circ$. There are $2+3+4 = 9$ parts of $20^\circ$ each, so the largest is $4 \times 20 = 80^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$80$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 parts = 180, part 20; largest 80.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7332b580-e46c-4cca-bbfe-c6d3215cf017', 'ALG.06', 3, 'numeric', 'Using a ratio to find a quantity', 'Three friends share 91 dollars in the ratio $2:5:6$. How many dollars does the friend with the largest share get?', '[]', '42', '91/13*6', 'There are $2+5+6 = 13$ parts, so a part is $91 \div 13 = 7$ dollars. The largest share is $6 \times 7 = 42$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 parts = 91, part 7; largest 6*7 = 42.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('461ad184-b1d6-493f-a3f6-19765b5b79f0', 'ALG.06', 3, 'numeric', 'Using a ratio to find a quantity', 'Jo and Kim share some money in the ratio $4:5$. Kim gets 6 dollars more than Jo. How many dollars do they share altogether?', '[]', '54', '6*9', 'Kim''s share is 1 part more than Jo''s, so 1 part is 6 dollars. The total is $4 + 5 = 9$ parts, which is $9 \times 6 = 54$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kim - Jo = 1 part = 6; total 9 parts = 54.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da7d642f-f725-4a33-a3b8-489277af83cc', 'ALG.06', 3, 'choice', 'Using a ratio to find a quantity', 'An orchard has apple trees and pear trees in the ratio $7:4$. It has 36 more apple trees than pear trees. How many pear trees does it have?', '["$84$","$36$","$48$","$12$"]', '$48$', '36/3*4', 'The difference is $7 - 4 = 3$ parts, which is 36 trees, so a part is 12 trees. Pear trees are 4 parts: $4 \times 12 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"$48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Apple - pear = 3 parts = 36, part 12; pears 48.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
