INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6ece1e2-cfc8-4048-a7cd-a1b543b7b768', 'ALG.06', 3, 'choice', 'Using a ratio to find a quantity', 'A cake uses sugar, flour and butter in the ratio $2:5:3$ by weight. A cook uses 45 grams of butter. How many grams of ingredients are used altogether?', '["$135$","$150$","$75$","$90$"]', '$150$', '45/3*10', 'Butter is 3 parts, so a part is 15 grams. All $2+5+3 = 10$ parts weigh $10 \times 15 = 150$ grams.', 'checked', '{"lint":[],"solve":{"answer":"$150$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Butter 3 parts = 45, part 15; total 10 parts = 150.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
