INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bfe7d2a-fede-4aa5-a334-e0c8317aa505', 'ALG.06', 3, 'choice', 'Finding a percent of a number', 'The number $x$ is 40% of $y$, and $y$ is 50% of $z$. Then $x$ is what percent of $z$?', '["90%","10%","45%","20%"]', '20%', NULL, '$x = 0.4y$ and $y = 0.5z$, so $x = 0.4 \times 0.5\,z = 0.2z$, which is 20% of $z$.', 'checked', '{"lint":[],"solve":{"answer":"20%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0.4y = 0.4*0.5z = 0.2z: 20%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
