INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e3759b5-ea1d-4265-8339-71cc4f6583b8', 'ALG.06', 3, 'choice', 'Finding a percent of a number', 'What is 0.5% of 400?', '["$2$","$0.2$","$20$","$200$"]', '$2$', '0.005*400', '1% of 400 is 4, so 0.5% is half of that: 2.', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.005*400 = 2.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
