INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa1748b9-46fa-4a32-9926-bd550c73f2e2', 'ALG.06', 3, 'numeric', 'Finding the percent or the whole', 'In a class of 40 students, 55% are girls. How many more girls than boys are in the class?', '[]', '4', '22-18', 'Girls: 55% of 40 is 22. Boys: 18. The difference is $22 - 18 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 22, boys 18; difference 4.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
