INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd0cf41f-2d4c-483d-a179-e1bb62fe2834', 'ALG.06', 3, 'numeric', 'Finding the percent or the whole', 'Of the whole numbers from 1 to 50, what percent are multiples of 4? Give the number of percent, without the % sign.', '[]', '24', '12/50*100', 'The multiples of 4 up to 50 are $4, 8, \dots, 48$: 12 numbers. $\frac{12}{50} = \frac{24}{100} = 24\%$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4 up to 50: 4..48, 12 numbers; 12/50 = 24%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
