INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dc23c7c-3b81-4ffd-a9aa-27ef69585e04', 'ALG.06', 3, 'choice', 'Percent increase and decrease', 'A coat is on sale for 20% off, and the sale price is 56 dollars. What was the price before the sale, in dollars?', '["$67.20$","$70$","$76$","$44.80$"]', '$70$', '56/0.8', 'The sale price is 80% of the old price, so 80% = 56, 10% = 7, and the old price is 70 dollars.', 'checked', '{"lint":[],"solve":{"answer":"$70$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8x = 56, x = 70.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
