INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('157fea01-147f-433e-b962-cfd343574c89', 'ALG.06', 3, 'numeric', 'Percent increase and decrease', 'A store buys a toy for 60 dollars and marks it up by 40%. Later it sells the toy for 25% off the marked price. How many dollars of profit does the store make?', '[]', '3', '60*1.4*0.75-60', 'Marked price: $60 \times 1.4 = 84$. The sale price is $84 \times 0.75 = 63$. Profit: $63 - 60 = 3$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Marked 60*1.4 = 84; sold 84*0.75 = 63; profit 3.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
