INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e083d183-615c-449e-a22a-f9ecc111a776', 'ALG.06', 3, 'choice', 'Percent increase and decrease', 'A price is increased by 25%. By what percent must the new price be decreased to get back to the original price?', '["25%","30%","75%","20%"]', '20%', NULL, 'Start at 100. After the rise the price is 125. To get back to 100 it must drop by 25, and $\frac{25}{125} = 20\%$.', 'checked', '{"lint":[],"solve":{"answer":"20%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.25 * (1-d) = 1, 1-d = 0.8, d = 20%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
