INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df8a944c-3f88-4fcd-8672-3b44e87cc780', 'ALG.06', 3, 'choice', 'Percent increase and decrease', 'After an increase of 40%, a number is 91. What was the number before the increase?', '["$65$","$54.6$","$51$","$127.4$"]', '$65$', '91/1.4', 'The new number is 140% of the old, so the old is $91 \div 1.4 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"$65$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.4x = 91, x = 65.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
