INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5c3079a-4b44-412f-ace4-efa014a7f55e', 'ALG.06', 3, 'numeric', 'Successive percent changes', 'A price rises by 50%. Then it falls by 40% of the new price and ends at 900 dollars. What was the original price, in dollars?', '[]', '1000', '900/(1.5*0.6)', 'The final price is $1.5 \times 0.6 = 0.9$ of the original. So the original is $900 \div 0.9 = 1000$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x*1.5*0.6 = 0.9x = 900, x = 1000.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
