INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85d4cce8-81d2-41ef-a432-a10497fd2c81', 'ALG.06', 3, 'numeric', 'Successive percent changes', 'A rectangle''s length is increased by 20% and its width is decreased by 20%. The original area was 100 square centimeters. What is the new area, in square centimeters?', '[]', '96', '100*1.2*0.8', 'The area is multiplied by $1.2 \times 0.8 = 0.96$, so the new area is $100 \times 0.96 = 96$.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2*0.8 = 0.96; 96.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
