INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9a86a6c-1ad8-480b-ba21-8ca5c129acc5', 'ALG.06', 3, 'choice', 'Successive percent changes', 'A town''s population grows by 10% in one year and by 10% again the next year. By what percent did it grow over the two years?', '["20%","11%","21%","210%"]', '21%', NULL, 'Start at 100. After year one: 110. Year two adds 10% of 110, which is 11, giving 121. The total growth is 21%.', 'checked', '{"lint":[],"solve":{"answer":"21%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.1*1.1 = 1.21: 21%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
