INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8750346c-fd31-470a-a4d3-1017d3c0a1e6', 'ALG.06', 3, 'numeric', 'Successive percent changes', 'A price rises by 20%, and then the new price falls by 20%. The final price is 192 dollars. What was the original price, in dollars?', '[]', '200', '192/(1.2*0.8)', 'The final price is $1.2 \times 0.8 = 0.96$ of the original. So the original is $192 \div 0.96 = 200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2*0.8 = 0.96; 0.96x = 192, x = 200.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
