INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e9250ed-5ec0-49de-9b43-d050debc132d', 'ALG.06', 3, 'numeric', 'Mixture problems', 'How many liters of pure water must be added to 10 liters of a 40% salt solution to make a 20% salt solution?', '[]', '10', '10*0.4/0.2-10', 'The 10 liters hold 4 liters of salt. For a 20% solution, 4 liters of salt must be one fifth of the total, so the total is 20 liters. Add $20 - 10 = 10$ liters of water.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Salt 4 L; 4/0.2 = 20 L total; add 10.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
