INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3806ad5f-5bc4-481f-96a5-5177776f98f7', 'ALG.06', 3, 'numeric', 'Mixture problems', 'How many kilograms of a 50% copper alloy must be mixed with a 20% copper alloy to make 12 kilograms of a 30% copper alloy?', '[]', '4', '(0.3*12-0.2*12)/0.3', 'Let $x$ be the kilograms of the 50% alloy. Copper: $0.5x + 0.2(12 - x) = 0.3 \times 12$, so $0.3x + 2.4 = 3.6$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5x + 0.2(12-x) = 3.6: 0.3x = 1.2, x = 4.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('978ca24e-e733-44c2-890a-1453b843e2c1', 'ALG.06', 3, 'numeric', 'Mixture problems', 'How many milliliters of pure acid must be added to 300 mL of a 10% acid solution to make a 40% acid solution?', '[]', '150', '(0.4*300-30)/0.6', 'The solution holds 30 mL of acid. Adding $x$ mL of acid gives $30 + x = 0.4(300 + x)$, so $0.6x = 90$ and $x = 150$.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acid 30 mL; (30+a)/(300+a) = 0.4: 30+a = 120+0.4a, 0.6a = 90, a = 150.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2a3e384-8206-4fb6-a825-c9229366f8ea', 'ALG.06', 3, 'choice', 'Mixture problems', 'Two liters of 30% juice are mixed with 3 liters of 50% juice. What percent of the mixture is juice?', '["40%","42%","80%","38%"]', '42%', NULL, 'Juice: $0.3 \times 2 = 0.6$ L and $0.5 \times 3 = 1.5$ L, which is 2.1 L in 5 L, and $\frac{2.1}{5} = 42\%$. (Averaging 30% and 50% to get 40% ignores that there is more of the stronger juice.)', 'checked', '{"lint":[],"solve":{"answer":"42%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 + 1.5 = 2.1 L juice of 5 L = 42%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7537cbd9-673e-4408-8a95-dabe4dea98c1', 'ALG.06', 3, 'numeric', 'Mixture problems', 'Coffee that costs 8 dollars per pound is mixed with coffee that costs 12 dollars per pound to make 20 pounds of a blend worth 10.50 dollars per pound. How many pounds of the 12-dollar coffee are used?', '[]', '12.5', '(10.5*20-8*20)/4', 'Let $x$ pounds be the 12-dollar coffee. The total cost is $12x + 8(20-x) = 10.5 \times 20 = 210$. So $4x + 160 = 210$ and $x = 12.5$.', 'checked', '{"lint":[],"solve":{"answer":"12.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y lb of 12-dollar: 8(20-y) + 12y = 210, 4y = 50, y = 12.5.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('451ee436-5bc5-4d05-9539-fabfa12c752e', 'ALG.06', 3, 'numeric', 'Mixture problems', 'One class of 20 students has an average test score of 80. Another class of 30 students has an average score of 70. What is the average score of all 50 students together?', '[]', '74', '(20*80+30*70)/50', 'The first class scored $20 \times 80 = 1600$ points in total and the second $30 \times 70 = 2100$. Together that is 3700 points for 50 students, an average of 74.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(20*80 + 30*70)/50 = 3700/50 = 74.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15edf1f4-0939-4b72-9100-cec9777ce21b', 'ALG.06', 3, 'numeric', 'Mixture problems', 'There are 20 liters of salt water that is 15% salt. How many liters of water must evaporate to leave a solution that is 20% salt?', '[]', '5', '20-20*0.15/0.2', 'The 3 liters of salt stay. For it to be 20% of the solution, the solution must be $3 \div 0.2 = 15$ liters. So $20 - 15 = 5$ liters evaporate.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Salt 3 L; 3/0.2 = 15 L; evaporate 5.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
