INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be353bfb-71c5-4fe6-b515-b112d84e8077', 'ALG.07', 1, 'choice', 'Solving proportions', 'Which of these is a true proportion?', '["$\\frac{2}{3} = \\frac{8}{12}$","$\\frac{2}{3} = \\frac{8}{10}$","$\\frac{2}{3} = \\frac{5}{6}$","$\\frac{2}{3} = \\frac{4}{7}$"]', '$\frac{2}{3} = \frac{8}{12}$', NULL, '$\frac{8}{12}$ simplifies to $\frac{2}{3}$. The others do not: $\frac{8}{10} = \frac{4}{5}$, $\frac{5}{6}$ is already in lowest terms and different, and $\frac{4}{7}$ is different.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} = \\frac{8}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/12 = 2/3 true; 5/6, 4/7, 8/10 are not 2/3.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
