INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d606891-0391-4cf9-8a3a-420b38078f2b', 'ALG.07', 1, 'numeric', 'Solving proportions', 'Solve for $y$: $3 : 5 = 12 : y$.', '[]', '20', '12*5/3', 'The first number went from 3 to 12, which is times 4. So $y = 5 \times 4 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3y = 60, y = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
