INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e361ad7d-e2a3-406e-a610-5e35bfec751b', 'ALG.07', 1, 'numeric', 'Solving proportions', '$x$ is to 9 as 4 is to 6. What is $x$?', '[]', '6', '4*9/6', 'This says $\frac{x}{9} = \frac{4}{6}$. Since $\frac{4}{6} = \frac{2}{3}$ and $9 = 3 \times 3$, $x = 2 \times 3 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/9 = 4/6, x = 36/6 = 6.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
