INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b35b2b7-0bad-4fea-a3ed-7e50fbca4663', 'ALG.07', 1, 'choice', 'Solving proportions', 'Cross-multiplying $\frac{5}{x} = \frac{3}{7}$ gives which equation?', '["$15 = 7x$","$5x = 21$","$35 = 3x$","$5 + 7 = 3 + x$"]', '$35 = 3x$', NULL, 'Cross-multiplying multiplies the top of each fraction by the bottom of the other: $5 \times 7 = 3 \times x$, which is $35 = 3x$.', 'checked', '{"lint":[],"solve":{"answer":"$35 = 3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*7 = 3x: 35 = 3x.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
