INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc61292d-0299-4447-8408-57e7cfcd39af', 'ALG.07', 1, 'choice', 'Rates and proportion word problems', 'A bus travels at a steady speed and goes 60 miles in 2 hours. How many miles does it go in 5 hours at that speed?', '["$63$","$150$","$120$","$300$"]', '$150$', '60/2*5', 'The bus goes 30 miles each hour, so in 5 hours it goes $30 \times 5 = 150$ miles.', 'checked', '{"lint":[],"solve":{"answer":"$150$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 mph * 5 = 150.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
