VALUES ('a7488b08-83fc-4a2a-8292-dd85e35ce3b5', 'ALG.07', 1, 'choice', 'Direct variation', 'Which equation shows that $y$ varies directly with $x$?', '["$y = x + 5$","$y = \\frac{5}{x}$","$y = 5 - x$","$y = 5x$"]', '$y = 5x$', NULL, 'Direct variation means $y$ is a constant times $x$, as in $y = 5x$. Adding to $x$ or dividing by $x$ is not direct variation.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Direct variation y = kx: y = 5x.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
