VALUES ('5c495f85-044e-4514-acb3-9ba0cfbfcef1', 'ALG.07', 1, 'choice', 'Inverse variation', 'Which equation shows that $y$ varies inversely with $x$?', '["$y = 6x$","$y = x + 6$","$y = \\frac{6}{x}$","$y = x - 6$"]', '$y = \frac{6}{x}$', NULL, 'Inverse variation means $xy$ is a constant, which is the same as $y = \frac{k}{x}$. Here $y = \frac{6}{x}$ gives $xy = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{6}{x}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inverse: y = 6/x.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
