INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96f98182-7d2e-44ac-a956-c17631910fed', 'ALG.07', 1, 'numeric', 'Rates and proportion word problems', 'A printer prints 12 pages in 3 minutes. How many pages does it print in 10 minutes at the same speed?', '[]', '40', '12/3*10', 'It prints $12 \div 3 = 4$ pages per minute, so in 10 minutes it prints 40 pages.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 pages/min; 40.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
