INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b19a6ec9-1946-428d-91bc-0900754c6ed7', 'ALG.07', 1, 'choice', 'Direct variation', 'When $x$ is 1, 2 and 3, the values of $y$ are 4, 8 and 12. Which equation fits all three?', '["$y = 4x$","$y = x + 3$","$y = \\frac{12}{x}$","$y = 12 - 4x$"]', '$y = 4x$', NULL, 'Each $y$ is 4 times its $x$: $4 \times 1 = 4$, $4 \times 2 = 8$, $4 \times 3 = 12$. The other equations fail already at $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 4 each time: y = 4x.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
