VALUES ('ae6e5d80-2cd0-409f-9bcf-c25e26c27f13', 'ALG.07', 1, 'numeric', 'Direct variation', '$y = 3x$. If $y = 21$, what is $x$?', '[]', '7', '21/3', 'Divide both sides by 3: $x = 21 \div 3 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 7.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
