VALUES ('4c10a67b-ce12-4018-8513-0832258664bd', 'ALG.07', 2, 'choice', 'Solving proportions', 'Solve for $x$: $\frac{3}{x-1} = \frac{6}{10}$.', '["$5$","$1.8$","$6$","$11$"]', '$6$', '10/2+1', 'Cross-multiply: $6(x-1) = 30$, so $x - 1 = 5$ and $x = 6$. (The value 5 is $x - 1$, not $x$.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(x-1) = 30, x - 1 = 5, x = 6.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
