INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e369ed-da7e-41d7-941e-08f3377e14f8', 'ALG.07', 2, 'choice', 'Direct variation', '$y$ varies directly with $x$. When $x = 6$, $y = 21$. What is $y$ when $x = 10$?', '["$25$","$60$","$210$","$35$"]', '$35$', '21/6*10', '$\frac{y}{x}$ is constant: $\frac{21}{6} = 3.5$. So when $x = 10$, $y = 3.5 \times 10 = 35$. (Adding the same 4 to both is not direct variation.)', 'checked', '{"lint":[],"solve":{"answer":"$35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 3.5; y = 35.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
