INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10c99973-0e66-4004-b691-11bce5cab689', 'ALG.07', 2, 'numeric', 'Direct variation', 'The distance $d$ a cyclist rides is directly proportional to the time $t$ she rides. In 1.5 hours she rides 45 kilometers. How many kilometers does she ride in 4 hours?', '[]', '120', '45/1.5*4', 'Her speed is $45 \div 1.5 = 30$ kilometers per hour, so in 4 hours she rides $30 \times 4 = 120$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 km/h * 4 = 120.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
