INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7391015-2ef2-4f03-bc7c-be11aac6fd94', 'ALG.07', 2, 'choice', 'Direct variation', 'Which pair of points could both belong to the same direct variation $y = kx$ (with the same $k$)?', '["$(2, 6)$ and $(5, 15)$","$(2, 6)$ and $(5, 9)$","$(2, 6)$ and $(4, 10)$","$(2, 6)$ and $(6, 2)$"]', '$(2, 6)$ and $(5, 15)$', NULL, 'The point $(2, 6)$ gives $k = 3$. Then $x = 5$ needs $y = 15$, which the first pair has. The others give $\frac{9}{5}$, $\frac{10}{4}$ and $\frac{2}{6}$ for $\frac{y}{x}$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 6)$ and $(5, 15)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 3 for (2,6) and (5,15).","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
