INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c4f55cd-0311-48f4-8df4-1b85d2f47f37', 'ALG.07', 2, 'numeric', 'Direct variation', 'A spring stretches in direct proportion to the weight hung on it. A 3 kg weight stretches it 4.5 cm. What weight, in kilograms, stretches it 12 cm?', '[]', '8', '12/4.5*3', 'Each kilogram stretches it $4.5 \div 3 = 1.5$ cm. For 12 cm the weight is $12 \div 1.5 = 8$ kg.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5 cm/kg; 12/1.5 = 8.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
