INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0ddd439-fb74-491c-bed2-6ad991df1cee', 'ALG.07', 2, 'numeric', 'Direct variation', '$y$ varies directly with $x$. When $x = 12$, $y = 3$. What is $x$ when $y = 7$?', '[]', '28', '7*12/3', '$y$ is one quarter of $x$ ($\frac{3}{12} = \frac{1}{4}$). So $y = 7$ means $x = 4 \times 7 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 1/4; x = 4y = 28.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
