INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d96d98b-f0d8-4e39-a000-b21040775cbe', 'ALG.07', 2, 'choice', 'Inverse variation', '$y$ varies inversely with $x$. When $x = 4$, $y = 9$. What is $y$ when $x = 12$?', '["$27$","$1$","$3$","$7$"]', '$3$', '4*9/12', '$xy = 4 \times 9 = 36$. When $x = 12$, $y = 36 \div 12 = 3$. (Multiplying $y$ by 3 would be direct variation.)', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy = 36; 36/12 = 3.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
