INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f849a4a3-a28d-4d69-8152-a26f1168f0f3', 'ALG.07', 2, 'choice', 'Inverse variation', 'Which list of $y$-values goes with $x = 1, 2, 4$ so that $y$ varies inversely with $x$?', '["$y = 12, 11, 9$","$y = 3, 6, 12$","$y = 12, 10, 6$","$y = 12, 6, 3$"]', '$y = 12, 6, 3$', NULL, 'Inverse variation needs $xy$ to be the same each time: $1 \times 12 = 2 \times 6 = 4 \times 3 = 12$. The other lists give different products.', 'checked', '{"lint":[],"solve":{"answer":"$y = 12, 6, 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy = 12 needs 12, 6, 3.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
