INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80a7cb8e-c45b-42cf-aea5-0b2d18d30291', 'ALG.07', 2, 'numeric', 'Rates and proportion word problems', 'Mia types 180 words in 4 minutes. At that speed, how many minutes does she need to type 630 words?', '[]', '14', '630/180*4', 'She types $180 \div 4 = 45$ words per minute, and $630 \div 45 = 14$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 words/min; 630/45 = 14.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe42f7b3-5fd4-4b58-89dd-6f1609c3d990', 'ALG.07', 2, 'choice', 'Telling direct from inverse variation', '$y$ varies inversely with $x$. What happens to $y$ when $x$ is tripled?', '["$y$ is multiplied by 3","$y$ is increased by 3","$y$ stays the same","$y$ is divided by 3"]', '$y$ is divided by 3', NULL, 'The product $xy$ stays fixed. If $x$ becomes 3 times as big, $y$ must become one third as big.', 'checked', '{"lint":[],"solve":{"answer":"$y$ is divided by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy const: tripling x divides y by 3.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7eb19391-3678-4616-b2f6-befdd365b2fe', 'ALG.07', 2, 'choice', 'Telling direct from inverse variation', 'Which pair of quantities varies directly?', '["The number of toy cars bought and the total cost, when all cost the same","The speed of a car and the time to travel a fixed distance","The number of painters and the days needed to paint one house","The width and the length of rectangles that all have area 36"]', 'The number of toy cars bought and the total cost, when all cost the same', NULL, 'Buying more toy cars at one price raises the total in the same proportion. In the other pairs, one quantity goes up when the other goes down.', 'checked', '{"lint":[],"solve":{"answer":"The number of toy cars bought and the total cost, when all cost the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal price: cost = price * number, direct. Others inverse.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5250197-5f4e-4d22-8d8f-20d04055f0e5', 'ALG.07', 2, 'numeric', 'Inverse variation', '$y$ varies inversely with $x$, and right now $y = 48$. Then $x$ is multiplied by 4. What is the new value of $y$?', '[]', '12', '48/4', 'For inverse variation, multiplying $x$ by 4 divides $y$ by 4: $48 \div 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48/4 = 12.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf513c1a-5b37-469d-b003-4fa6d7c109c0', 'ALG.07', 2, 'choice', 'Telling direct from inverse variation', 'If $y = kx$ for a fixed number $k$ that is not 0, which statement is true?', '["The value of $\\frac{y}{x}$ is always 1.","The value of $\\frac{y}{x}$ gets bigger when $x$ gets bigger.","The value of $\\frac{y}{x}$ is always the same.","The value of $\\frac{y}{x}$ gets smaller when $x$ gets bigger."]', 'The value of $\frac{y}{x}$ is always the same.', NULL, 'Dividing $y = kx$ by $x$ gives $\frac{y}{x} = k$, which does not change.', 'checked', '{"lint":[],"solve":{"answer":"The value of $\\frac{y}{x}$ is always the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = k always (x not 0).","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a7961b-f6a6-455f-ac98-af324b786833', 'ALG.07', 2, 'numeric', 'Inverse variation', 'Three identical pipes fill a tank in 10 hours. How many hours would 5 of these pipes need to fill the same tank?', '[]', '6', '3*10/5', 'The job is $3 \times 10 = 30$ pipe-hours. With 5 pipes it takes $30 \div 5 = 6$ hours.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 pipe-hours / 5 = 6.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd3314d6-7c55-4bc8-9582-109d294d13b9', 'ALG.07', 2, 'numeric', 'Scale drawings, maps and similar figures', 'A scale model of a car is made at a scale of $1:24$ (model length to real length). The real car is 4.8 meters long. How many centimeters long is the model?', '[]', '20', '480/24', '4.8 meters is 480 cm. The model is $480 \div 24 = 20$ cm long.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"480 cm / 24 = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
