INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('276762b5-3825-49fa-898e-ae13c8a3efdb', 'ALG.07', 2, 'numeric', 'Rates and proportion word problems', 'A bike wheel turns 50 times while the bike rolls 120 meters. How many times does the wheel turn while the bike rolls 300 meters?', '[]', '125', '50/120*300', '300 meters is $2.5$ times 120 meters, so the wheel turns $50 \times 2.5 = 125$ times.', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50*300/120 = 125.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
