INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51fe7dcd-16d2-4b35-b670-ecc539d06be6', 'ALG.07', 2, 'choice', 'Solving proportions', 'If $\frac{a}{b} = \frac{c}{d}$ where none of the numbers is 0, which equation must be true?', '["$ab = cd$","$ad = bc$","$a + d = b + c$","$ac = bd$"]', '$ad = bc$', NULL, 'Multiply both sides by $bd$: $ad = bc$. This is cross-multiplication. For example $\frac{1}{2} = \frac{3}{6}$ gives $1 \times 6 = 2 \times 3$, but $1 \times 2 \ne 3 \times 6$.', 'checked', '{"lint":[],"solve":{"answer":"$ad = bc$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cross-multiply: ad = bc.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c29263e-3cbc-45fb-99a5-3c5b9ac1576e', 'ALG.07', 3, 'numeric', 'Solving proportions', 'Solve for $x$: $\frac{x+2}{x-2} = \frac{5}{3}$.', '[]', '8', '8', 'Cross-multiply: $3(x+2) = 5(x-2)$, so $3x + 6 = 5x - 10$, which gives $16 = 2x$ and $x = 8$. Check: $\frac{10}{6} = \frac{5}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+2) = 5(x-2): 3x+6 = 5x-10, x = 8.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b28db11-da80-4d12-ae1c-3494c9159e44', 'ALG.07', 3, 'numeric', 'Solving proportions', 'Solve for $x$: $\frac{3x-1}{4} = \frac{2x+4}{3}$.', '[]', '19', '19', 'Cross-multiply: $3(3x-1) = 4(2x+4)$, so $9x - 3 = 8x + 16$ and $x = 19$. Check: $\frac{56}{4} = 14 = \frac{42}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(3x-1) = 4(2x+4): 9x - 3 = 8x + 16, x = 19.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0009ec8c-e488-4fde-ab8c-cca53152d4c0', 'ALG.07', 3, 'choice', 'Solving proportions', 'Suppose $\frac{a}{b} = \frac{3}{5}$ and $\frac{b}{c} = \frac{10}{7}$. What is $\frac{a}{c}$?', '["$\\frac{7}{6}$","$\\frac{21}{50}$","$\\frac{13}{12}$","$\\frac{6}{7}$"]', '$\frac{6}{7}$', NULL, 'Multiply: $\frac{a}{c} = \frac{a}{b} \times \frac{b}{c} = \frac{3}{5} \times \frac{10}{7} = \frac{30}{35} = \frac{6}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a/c = (a/b)(b/c) = 3/5*10/7 = 6/7.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0727d4a3-f3c4-4763-8970-48b1f40d3c23', 'ALG.07', 3, 'numeric', 'Solving proportions', 'The numbers $a$, $b$, $c$ satisfy $a : b = 2 : 3$ and $b : c = 4 : 5$. If $a + b + c = 70$, what is $b$?', '[]', '24', '70/35*12', 'Rewrite $a:b = 8:12$ so that $b$ matches, then $b:c = 12:15$. So $a:b:c = 8:12:15$. These add to 35 parts, so a part is 2 and $b = 12 \times 2 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a:b:c = 8:12:15, 35 parts = 70, part 2, b = 24.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b40cc62f-19b0-4140-b60a-df90531d6ee1', 'ALG.07', 3, 'choice', 'Solving proportions', 'If $\frac{x}{y} = \frac{2}{3}$, what is the value of $\frac{x+y}{x-y}$?', '["$-5$","$5$","$-\\frac{1}{5}$","$\\frac{1}{5}$"]', '$-5$', NULL, 'Take $x = 2$ and $y = 3$ (any multiple gives the same answer). Then $x + y = 5$ and $x - y = -1$, so the value is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"$-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 2, y = 3: 5/(-1) = -5.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31c1db1c-b952-42d5-bac5-04e9b102b7cd', 'ALG.07', 3, 'choice', 'Solving proportions', 'The positive number $x$ satisfies $\frac{4}{x} = \frac{x}{9}$. What is $x$?', '["$6.5$","$36$","$6$","$5$"]', '$6$', NULL, 'Cross-multiply: $x^2 = 36$, and the positive solution is $x = 6$. (The average of 4 and 9 is 6.5, which does not work.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 36, x = 6.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('384a50dd-44d3-40eb-90f3-1d4b91611072', 'ALG.07', 3, 'numeric', 'Solving proportions', 'Suppose $x : y = 3 : 4$ and $y : z = 2 : 5$. If $z = 50$, what is $x$?', '[]', '15', '50/20*6', 'Write $y:z = 2:5 = 8:20$ and $x:y = 3:4 = 6:8$. Then $x:y:z = 6:8:20$. Since $z = 50$ is $2.5$ times 20, $x = 2.5 \times 6 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x:y:z = 3:4:10; z = 50 gives part 5, x = 15.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5566aa-987b-4398-826b-523f5e58ca90', 'ALG.07', 3, 'choice', 'Direct variation', 'The weight of a metal rod is directly proportional to its length. A rod 2.4 meters long weighs 9 kg. How long, in meters, is a rod of the same metal that weighs 15 kg?', '["$8.4$","$4$","$1.44$","$5.4$"]', '$4$', '15/9*2.4', 'Each meter weighs $9 \div 2.4 = 3.75$ kg. For 15 kg the length is $15 \div 3.75 = 4$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.75 kg/m; 15/3.75 = 4.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02d6e838-3b67-45b7-8987-d839f24b4b94', 'ALG.07', 3, 'numeric', 'Direct variation', '$y$ varies directly with $x$. When $x = 8$, $y = 20$. What is the value of $y - x$ when $x = 12$?', '[]', '18', '20/8*12-12', '$y = 2.5x$. When $x = 12$, $y = 30$, and $y - x = 30 - 12 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2.5; y = 30; 30 - 12 = 18.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fab61c2-32d0-4266-8bfa-342dd8f30d15', 'ALG.07', 3, 'numeric', 'Direct variation', 'Ann and Ben are paid the same amount for each hour they work. Ann worked 4 hours more than Ben and earned 50 dollars more. Ben earned 75 dollars. How many dollars did Ann earn?', '[]', '125', '75+50', 'The 4 extra hours were worth 50 dollars, so an hour pays 12.50 dollars. Ben worked $75 \div 12.5 = 6$ hours, Ann worked 10 hours, and she earned $10 \times 12.5 = 125$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ann earned 75 + 50 = 125 (12.5/h, Ben 6 h, Ann 10 h).","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d7b0ca1-83ee-4f8c-b19a-a24792338907', 'ALG.07', 3, 'numeric', 'Direct variation', 'The points $(4, 10)$, $(a, 25)$ and $(6, b)$ all lie on one direct variation $y = kx$. What is $a + b$?', '[]', '25', '25/2.5+2.5*6', '$k = \frac{10}{4} = 2.5$. Then $25 = 2.5a$ gives $a = 10$, and $b = 2.5 \times 6 = 15$. So $a + b = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2.5; a = 10, b = 15; 25.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d46e093e-cbe9-4292-a81a-a601fdddb721', 'ALG.07', 3, 'choice', 'Rates and proportion word problems', 'A pancake recipe needs 2 eggs and 3 cups of milk for every 12 pancakes. Kim has 7 eggs and 10 cups of milk. What is the greatest number of pancakes she can make?', '["$42$","$28$","$45$","$40$"]', '$40$', '10/3*12', 'The eggs would make $\frac{7}{2} \times 12 = 42$ pancakes, but the milk would make only $\frac{10}{3} \times 12 = 40$. The milk runs out first, so 40.', 'checked', '{"lint":[],"solve":{"answer":"$40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Keyed 40 assumes fractional batches: 40 pancakes need 6 2/3 eggs. Only 40 among options fits, but whole eggs give 36; consider rewording (\"enough milk\" limit) or numbers.","work":"Eggs allow 7/2*12 = 42; milk 10/3*12 = 40. Milk limits: 40.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25916e66-a79e-43ba-b645-cf36a4a32d1b', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'A car uses 4 gallons of gas per 100 miles in the city and 3 gallons per 100 miles on the highway. On a 250-mile trip, 150 miles are in the city and the rest is on the highway. How many gallons does the car use?', '[]', '9', '150*4/100+100*3/100', 'City: $1.5 \times 4 = 6$ gallons. Highway: 100 miles, so 3 gallons. The total is $6 + 3 = 9$ gallons.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"City 150 mi: 6 gal; highway 100 mi: 3 gal; 9.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d7535e1-272a-4872-bea7-f9d0be8aee47', 'ALG.07', 3, 'choice', 'Inverse variation', 'Eight workers, all working at the same speed, can build a wall in 15 days. After 5 days, 4 workers leave and the other 4 keep working at the same speed. How many more days do they need to finish the wall?', '["$20$","$10$","$25$","$30$"]', '$20$', '(8*15-8*5)/4', 'The wall is $8 \times 15 = 120$ worker-days. In 5 days the 8 workers did 40, leaving 80. At 4 workers, that is $80 \div 4 = 20$ more days.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 worker-days; 40 done; 80/4 = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('904acdbd-4d55-40ae-b62c-39d7ea12c2f0', 'ALG.07', 3, 'choice', 'Inverse variation', '$y$ varies inversely with $x$. When $x = 40$, $y = 30$. What is $y$ when $x = 50$?', '["$37.5$","$1200$","$24$","$35$"]', '$24$', '40*30/50', '$xy = 40 \times 30 = 1200$. When $x = 50$, $y = 1200 \div 50 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy = 1200; 1200/50 = 24.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
