INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba5b7602-17c2-44d7-918b-fde2380d6697', 'ALG.07', 3, 'numeric', 'Inverse variation', 'Gear A has 30 teeth and is meshed with gear B, which has 24 teeth. Gear A turns 40 times. How many times does gear B turn?', '[]', '50', '30*40/24', 'The number of teeth that pass must match: $30 \times 40 = 1200$. Gear B turns $1200 \div 24 = 50$ times.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30*40 = 1200 teeth; 1200/24 = 50.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27f3a58c-3a71-4f70-a130-9d00b2eaf278', 'ALG.07', 3, 'choice', 'Inverse variation', 'A trip of 240 miles takes 4 hours. On the way back, the driver goes 20 miles per hour slower than on the way there. How many hours does the return trip take?', '["$5$","$6$","$4.8$","$8$"]', '$6$', '240/(240/4-20)', 'The speed there is $240 \div 4 = 60$ mph, and back it is 40 mph. The return trip takes $240 \div 40 = 6$ hours.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 mph there; 40 back; 240/40 = 6.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
