INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4812df81-eccd-4f94-b028-76e7161a7faa', 'ALG.07', 3, 'numeric', 'Inverse variation', '$y$ varies inversely with $x$. When $x = 6$, $y = 12$. For what value of $x$ is $y = 9$?', '[]', '8', '6*12/9', '$xy = 6 \times 12 = 72$. When $y = 9$, $x = 72 \div 9 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy = 72; x = 72/9 = 8.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
