INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e6b8a8c-d7f2-4ef4-8ad9-da910dbe9bbe', 'ALG.07', 3, 'choice', 'Inverse variation', 'A farmer has enough feed for 20 cows for 30 days. If there are 30 cows instead, for how many days will the same feed last?', '["$45$","$40$","$25$","$20$"]', '$20$', '20*30/30', 'The feed is $20 \times 30 = 600$ cow-days. With 30 cows it lasts $600 \div 30 = 20$ days.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 cow-days / 30 = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4d57475-4f50-4631-b48a-f2cbfb0db49c', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'Printer A prints 45 pages in 3 minutes. Printer B prints 40 pages in 2 minutes. Working together, how many pages do they print in 6 minutes?', '[]', '210', '(45/3+40/2)*6', 'A prints 15 pages per minute and B prints 20. Together that is 35 pages per minute, so in 6 minutes they print $35 \times 6 = 210$ pages.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 20 = 35 pages/min; 210.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('672c639b-a7d2-4e4a-a647-3ca1ef994c53', 'ALG.07', 3, 'choice', 'Scale drawings, maps and similar figures', 'A map has the scale 1 : 50,000, so 1 cm on the map is 50,000 cm on the ground. Two towns are 8.4 cm apart on the map. How many kilometers apart are they?', '["$4.2$","$42$","$420$","$0.42$"]', '$4.2$', '8.4*50000/100000', '$8.4 \times 50{,}000 = 420{,}000$ cm on the ground. There are 100,000 cm in a kilometer, so the distance is 4.2 km.', 'checked', '{"lint":[],"solve":{"answer":"$4.2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8.4*50000 = 420000 cm = 4.2 km.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5197ab76-8f8a-470a-80e8-7224e411c393', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'Ten identical machines make 150 widgets in 6 hours. How many hours would 4 of these machines need to make 100 widgets?', '[]', '10', '100/(150/60*4)', 'One machine makes $150 \div (10 \times 6) = 2.5$ widgets per hour. Four machines make 10 per hour, so 100 widgets take 10 hours.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/(10*6) = 2.5 per machine-hour; 100/(4*2.5) = 10.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
