INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('685b783a-ff6d-4b16-a118-148f0b59b7e1', 'ALG.07', 3, 'numeric', 'Inverse variation', 'A pool is filled by a pump that moves 12 gallons per minute, which takes 50 minutes. To fill the pool in only 30 minutes, how many gallons per minute must be pumped?', '[]', '20', '12*50/30', 'The pool holds $12 \times 50 = 600$ gallons. In 30 minutes the pump must move $600 \div 30 = 20$ gallons per minute.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pool 600 gal; 600/30 = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
