INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('519feb8c-7f61-469b-ba57-cea8311d5698', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'Pete reads 24 pages in 40 minutes. At that rate, how many hours does he need to read a 270-page book?', '[]', '7.5', '270/24*40/60', 'He reads $24 \div 40 = 0.6$ pages per minute, so 270 pages take $270 \div 0.6 = 450$ minutes, which is 7.5 hours.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 pages/min; 270/0.6 = 450 min = 7.5 h.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
