INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58bb1126-1243-47c9-a863-e9c1e8b16748', 'ALG.07', 3, 'choice', 'Rates and proportion word problems', 'In a game, 8 tokens trade for 5 gems, and 6 gems trade for 9 stars. How many tokens trade for 30 stars?', '["$18.75$","$48$","$32$","$25$"]', '$32$', '30/9*6/5*8', '30 stars is $\frac{30}{9}$ of 9 stars, which is $\frac{30}{9} \times 6 = 20$ gems. Then 20 gems is 4 times 5 gems, so 4 times 8 tokens: 32 tokens.', 'checked', '{"lint":[],"solve":{"answer":"$32$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 stars = 20 gems; 5 gems = 8 tokens, so 20 gems = 32 tokens.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f4077be-4ebf-44b9-8422-fc61bd5e02b2', 'ALG.07', 3, 'choice', 'Rates and proportion word problems', 'Alex runs 400 meters in 80 seconds at a steady pace. How many minutes does Alex need to run 1.5 kilometers at that pace?', '["$300$","$5$","$3$","$7.5$"]', '$5$', '1500/400*80/60', '1.5 km is 1500 m. Alex runs 5 meters each second, so 1500 m takes 300 seconds, which is 5 minutes.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 m/s; 1500/5 = 300 s = 5 min.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
