INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b45b3a29-8f50-4817-9b73-d4566a6e88d4', 'ALG.07', 3, 'numeric', 'Scale drawings, maps and similar figures', 'A drawing is enlarged so that a line of 3 cm becomes 11.25 cm long. How many centimeters long does a line of 8 cm become?', '[]', '30', '8*11.25/3', 'Every length is multiplied by $11.25 \div 3 = 3.75$. A line of 8 cm becomes $8 \times 3.75 = 30$ cm.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 11.25/3 = 3.75; 8*3.75 = 30.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
