INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13a1eb80-acd8-46ec-ae3a-bb348ee72c48', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'A baker uses 5 cups of flour for every 2 cups of sugar. She uses all of her 20 cups of flour and has 9 cups of sugar to start with. How many cups of sugar are left over?', '[]', '1', '9-20/5*2', '20 cups of flour is 4 times 5 cups, so she needs $4 \times 2 = 8$ cups of sugar. She has $9 - 8 = 1$ cup left.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 flour needs 8 sugar; 9 - 8 = 1.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee50001f-6a98-4ce0-9722-44fe1885c70a', 'ALG.07', 3, 'choice', 'Telling direct from inverse variation', 'For a gas kept at one temperature, the pressure $P$ times the volume $V$ is always the same number. If the volume is cut to half its size, what happens to the pressure?', '["It is cut in half","It stays the same","It increases by 2","It doubles"]', 'It doubles', NULL, '$PV$ stays fixed, so halving $V$ means $P$ must be twice as big. This is inverse variation.', 'checked', '{"lint":[],"solve":{"answer":"It doubles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PV const: V halved, P doubles.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b87f2f-8865-4b72-89cb-869e54fafd86', 'ALG.07', 3, 'choice', 'Telling direct from inverse variation', 'The quantity $A$ varies directly with $B$, and $B$ varies inversely with $C$. Which statement is true?', '["The product $A \\times C$ is always the same.","The ratio $\\frac{A}{C}$ is always the same.","The sum $A + C$ is always the same.","The difference $A - C$ is always the same."]', 'The product $A \times C$ is always the same.', NULL, '$A = kB$ and $BC = m$ for fixed numbers $k$ and $m$. So $AC = kBC = km$, which does not change. Thus $A$ and $C$ vary inversely.', 'checked', '{"lint":[],"solve":{"answer":"The product $A \\times C$ is always the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = kB, B = m/C, A = km/C, so AC = km constant.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9fe9d8-59f6-4f3f-9f45-97eb5eaacb98', 'ALG.07', 3, 'numeric', 'Direct variation', '$y$ varies directly with $x$. When $x = 5$, $y = 40$. The points $(a, 56)$ and $(a+2, b)$ also lie on this variation. What is $b$?', '[]', '72', '8*(56/8+2)', '$k = \frac{40}{5} = 8$. From $56 = 8a$, $a = 7$. Then $b = 8 \times 9 = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 8; a = 7; b = 8*9 = 72.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9658e191-bf1b-4d63-a790-c651d8701113', 'ALG.07', 3, 'numeric', 'Inverse variation', '$y$ varies inversely with $x$. The points $(3, 20)$, $(a, 12)$ and $(10, b)$ all fit this variation. What is $a + b$?', '[]', '11', '60/12+60/10', '$xy = 3 \times 20 = 60$. Then $12a = 60$ gives $a = 5$, and $10b = 60$ gives $b = 6$. So $a + b = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy = 60; a = 5, b = 6; 11.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf422820-8e10-418d-93eb-941fae1abca0', 'ALG.07', 3, 'numeric', 'Rates and proportion word problems', 'A train 120 meters long passes a pole in 8 seconds at a steady speed. How many seconds pass from the moment the front of the train enters a 300-meter bridge until the moment the back of the train leaves it?', '[]', '28', '(300+120)/(120/8)', 'The speed is $120 \div 8 = 15$ meters per second. From front entering to back leaving, the train covers $300 + 120 = 420$ meters, which takes $420 \div 15 = 28$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 m/s; distance 300+120 = 420; 28 s.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d670a6ba-4e8c-4ad0-a327-ccebacd9cb66', 'ALG.08', 1, 'numeric', 'Slope from two points', 'What is the slope of the line through $(1, 2)$ and $(3, 8)$?', '[]', '3', '(8-2)/(3-1)', 'Slope is rise over run. From $(1, 2)$ to $(3, 8)$ the line rises $8-2=6$ and runs $3-1=2$, so the slope is $6\div 2=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8-2)/(3-1)=6/2=3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff73614f-9501-421d-998d-f53c79c8bf28', 'ALG.08', 1, 'choice', 'Slope from two points', 'Which is the slope of the line through $(0, 1)$ and $(4, 9)$?', '["$2$","$\\frac{1}{2}$","$-2$","$\\frac{5}{2}$"]', '$2$', '(9-1)/(4-0)', 'The rise is $9-1=8$ and the run is $4-0=4$, so the slope is $8\div 4=2$. (Adding the $y$-values instead of subtracting gives $\frac{5}{2}$, and turning the fraction upside down gives $\frac{1}{2}$.)', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9-1)/(4-0)=8/4=2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32bc26cc-66f7-44dd-87e3-f6142439791c', 'ALG.08', 1, 'numeric', 'Slope from two points', 'A line goes through $(-3, 4)$ and $(5, 4)$. What is its slope?', '[]', '0', '(4-4)/(5+3)', 'Both points have $y=4$, so the line does not rise at all. The rise is $0$ and the run is $5-(-3)=8$, so the slope is $0\div 8=0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4-4)/(5+3)=0","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
