INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68193233-f858-49e5-95ae-d3833f97f505', 'ALG.08', 1, 'choice', 'Slope from two points', 'Walking along a straight line on a coordinate plane, Ivan goes 4 units to the right and 10 units up. What is the slope of the line?', '["$\\frac{2}{5}$","$\\frac{5}{2}$","$14$","$6$"]', '$\frac{5}{2}$', NULL, 'Slope is rise divided by run: $10\div 4=\frac{10}{4}=\frac{5}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"rise/run = 10/4 = 5/2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
