INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44076fb9-cc7f-497a-b874-7d85ec084b4c', 'ALG.08', 1, 'choice', 'Slope and y-intercept from an equation', 'A line has the equation $y=3x+5$. Which statement about it is true?', '["Its slope is $5$ and its $y$-intercept is $3$.","Its slope is $3$ and its $y$-intercept is $5$.","Its slope is $3$ and its $y$-intercept is $-5$.","Its slope is $-3$ and its $y$-intercept is $5$."]', 'Its slope is $3$ and its $y$-intercept is $5$.', NULL, 'In $y=mx+b$ the slope is $m$ (the number multiplying $x$) and the $y$-intercept is $b$ (the number added). Here $m=3$ and $b=5$.', 'checked', '{"lint":[],"solve":{"answer":"Its slope is $3$ and its $y$-intercept is $5$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=mx+b with m=3, b=5","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
