VALUES ('961947a5-2b56-4116-b324-6ff00ac24cbb', 'ALG.08', 1, 'choice', 'Intercepts of a line', 'Which point is the $y$-intercept of the line $y=5x+2$?', '["$(2, 0)$","$(0, 2)$","$(0, 5)$","$(0, -2)$"]', '$(0, 2)$', NULL, 'The $y$-intercept is where $x=0$. Then $y=5(0)+2=2$, so the point is $(0, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0 gives y=2: (0,2)","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
