INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe024e5d-9475-4481-b3f5-f83394a8795c', 'ALG.08', 2, 'choice', 'Slope from two points', 'Which pair of points lies on a line with slope $-\frac{1}{2}$?', '["$(2, 5)$ and $(6, 7)$","$(2, 5)$ and $(4, 9)$","$(2, 5)$ and $(6, 3)$","$(2, 5)$ and $(3, 3)$"]', '$(2, 5)$ and $(6, 3)$', NULL, 'For $(2, 5)$ and $(6, 3)$ the rise is $3-5=-2$ and the run is $6-2=4$, so the slope is $-\frac{2}{4}=-\frac{1}{2}$. The other pairs have slopes $\frac{1}{2}$, $2$ and $-2$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$ and $(6, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6,7):2/4=1/2; (6,3):-2/4=-1/2; (3,3):-2/1=-2; (4,9):4/2=2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
