INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fedaccfa-9845-49ee-9ce8-eaba2e7fc5ad', 'ALG.08', 2, 'numeric', 'Slope from two points', 'The line through $(3, 7)$ and $(9, k)$ has slope $2$. What is $k$?', '[]', '19', '7+2*(9-3)', 'Going from $x=3$ to $x=9$ is a run of $6$. A slope of $2$ means the line rises $2\times 6=12$ over that run, so $k=7+12=19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k-7)/(9-3)=2 so k-7=12, k=19","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
