INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97407a6c-c5f9-4fe0-8652-3d157e5f1312', 'ALG.08', 2, 'choice', 'Slope and y-intercept from an equation', 'What is the slope of the line $3x+y=8$?', '["$-3$","$3$","$8$","$-\\frac{1}{3}$"]', '$-3$', '-3', 'Solve for $y$: $y=-3x+8$. The slope is the number multiplying $x$, which is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"$-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=-3x+8, slope -3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
