INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('601ed8b6-9343-4dbc-a58e-ed2edb67e106', 'ALG.08', 2, 'choice', 'Slope and y-intercept from an equation', 'Which equation is $2y=6x-10$ written in slope-intercept form?', '["$y=6x-10$","$y=3x-5$","$y=3x-10$","$y=3x+5$"]', '$y=3x-5$', NULL, 'Divide every term by $2$: $y=\frac{6x}{2}-\frac{10}{2}=3x-5$. Forgetting to divide one of the terms gives the wrong options.', 'checked', '{"lint":[],"solve":{"answer":"$y=3x-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"divide by 2: y=3x-5","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
