INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe46bb3-6bc8-475e-a1e0-a6afef109526', 'ALG.08', 2, 'choice', 'Slope and y-intercept from an equation', 'What is the slope of the line $2x+5y=10$?', '["$\\frac{2}{5}$","$-\\frac{5}{2}$","$-\\frac{2}{5}$","$-2$"]', '$-\frac{2}{5}$', NULL, 'Solve for $y$: $5y=-2x+10$, so $y=-\frac{2}{5}x+2$. The slope is $-\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5y=-2x+10, y=-2/5 x+2, slope -2/5","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
