INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43971664-8b47-48fd-a9fd-44f29889dbb5', 'ALG.08', 2, 'choice', 'Intercepts of a line', 'The line $y=-\frac{1}{2}x+3$ has which intercepts?', '["$x$-intercept $3$ and $y$-intercept $6$","$x$-intercept $-6$ and $y$-intercept $3$","$x$-intercept $6$ and $y$-intercept $3$","$x$-intercept $2$ and $y$-intercept $3$"]', '$x$-intercept $6$ and $y$-intercept $3$', NULL, 'The $y$-intercept is the constant term, $3$. For the $x$-intercept put $y=0$: $0=-\frac{1}{2}x+3$, so $\frac{1}{2}x=3$ and $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"$x$-intercept $6$ and $y$-intercept $3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=0: x/2=3, x=6; x=0: y=3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
