VALUES ('f851ffa5-bec6-4f06-b3c2-4b577c738c72', 'ALG.08', 2, 'numeric', 'Intercepts of a line', 'Where does the line $y=-\frac{3}{4}x+6$ cross the $x$-axis? Give the value of $x$.', '[]', '8', '6/(3/4)', 'Put $y=0$: $\frac{3}{4}x=6$, so $x=6\times\frac{4}{3}=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0=-3/4 x+6, x=8","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
