INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7271055e-e54a-40c6-af3b-98001c857d72', 'ALG.08', 2, 'numeric', 'Intercepts of a line', 'Find the sum of the $x$-intercept and the $y$-intercept (both as numbers) of the line $5x-2y=20$.', '[]', '-6', '20/5+20/(-2)', 'Put $y=0$: $5x=20$, so the $x$-intercept is $4$. Put $x=0$: $-2y=20$, so the $y$-intercept is $-10$. Their sum is $4+(-10)=-6$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-int: 5x=20, x=4; y-int: -2y=20, y=-10; sum -6","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
