INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d00661c-6343-45e0-8b8b-3b548b09abe9', 'ALG.08', 2, 'choice', 'Write the equation of a line from a slope and a point or two points', 'A line with slope $\frac{2}{3}$ passes through $(3, 5)$. Which is its equation?', '["$y=\\frac{2}{3}x+5$","$y=\\frac{2}{3}x-3$","$y=\\frac{3}{2}x+3$","$y=\\frac{2}{3}x+3$"]', '$y=\frac{2}{3}x+3$', NULL, 'Write $y=\frac{2}{3}x+b$ and put in $(3, 5)$: $5=2+b$, so $b=3$. The equation is $y=\frac{2}{3}x+3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=\\frac{2}{3}x+3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-5=2/3(x-3) gives y=2/3 x+3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
