INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fb7a08d-8826-4cd1-a22e-f51b86b36b05', 'ALG.08', 2, 'numeric', 'Write the equation of a line from a slope and a point or two points', 'A line passes through $(2, 7)$ and $(5, 16)$. What is its $y$-intercept?', '[]', '1', '7-(16-7)/(5-2)*2', 'The slope is $\frac{16-7}{5-2}=3$. Then $y=3x+b$ and $7=3(2)+b$, so $b=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope 9/3=3; 7=6+b, b=1","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
