INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e6fb871-856c-452f-83bc-06a1d01914fb', 'ALG.08', 2, 'choice', 'Write the equation of a line from a slope and a point or two points', 'Which line passes through both $(-1, -3)$ and $(3, 5)$?', '["$y=2x-1$","$y=2x+1$","$y=2x-3$","$y=-2x-1$"]', '$y=2x-1$', NULL, 'The slope is $\frac{5-(-3)}{3-(-1)}=\frac{8}{4}=2$. Put in $(3, 5)$: $5=6+b$, so $b=-1$ and the line is $y=2x-1$. Check with $(-1, -3)$: $2(-1)-1=-3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=2x-1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope 8/4=2; -3=-2+b, b=-1: y=2x-1","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9cddb69-929f-4008-87f1-19e6b7ad7cc9', 'ALG.08', 2, 'numeric', 'Write the equation of a line from a slope and a point or two points', 'A line with slope $-4$ goes through the point $(2, -5)$. At what value of $y$ does it cross the $y$-axis?', '[]', '3', '-5+4*2', 'Write $y=-4x+b$ and put in $(2, -5)$: $-5=-8+b$, so $b=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5=-4*2+b, b=3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
