INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('277a0eab-66b7-4593-863d-b9de6b8f1bb1', 'ALG.08', 2, 'choice', 'Point-slope form', 'Which is the point-slope form of the line with slope $-2$ through the point $(-3, 5)$?', '["$y-5=-2(x+3)$","$y+5=-2(x-3)$","$y-5=-2(x-3)$","$y-5=2(x+3)$"]', '$y-5=-2(x+3)$', NULL, 'Use $y-y_1=m(x-x_1)$ with $m=-2$, $x_1=-3$, $y_1=5$: $y-5=-2(x-(-3))=-2(x+3)$.', 'checked', '{"lint":[],"solve":{"answer":"$y-5=-2(x+3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-5=-2(x-(-3)) = -2(x+3)","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
