VALUES ('3dba30b2-128d-4279-a2fd-f3e5fb9e7f0d', 'ALG.08', 2, 'choice', 'Standard form (Ax + By = C)', 'Which equation is $y=-\frac{3}{4}x+2$ in the form $Ax+By=C$ with whole-number coefficients and $A>0$?', '["$3x-4y=8$","$3x+4y=8$","$4x+3y=8$","$3x+4y=2$"]', '$3x+4y=8$', NULL, 'Multiply both sides by $4$: $4y=-3x+8$. Move the $x$-term: $3x+4y=8$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+4y=8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4y=-3x+8 -> 3x+4y=8","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
