VALUES ('295b7623-a79c-4060-b269-0b121bbbb668', 'ALG.08', 2, 'choice', 'Standard form (Ax + By = C)', 'Which equation is the line through $(0, 3)$ and $(4, 0)$?', '["$4x+3y=12$","$3x-4y=12$","$3x+4y=7$","$3x+4y=12$"]', '$3x+4y=12$', NULL, 'Check $(0, 3)$: $3(0)+4(3)=12$. Check $(4, 0)$: $3(4)+4(0)=12$. Both work, so the line is $3x+4y=12$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+4y=12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"intercepts 4 and 3: x/4+y/3=1 -> 3x+4y=12","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
