INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68d19630-0a86-4c2a-87cd-7cd6bb07025a', 'ALG.08', 2, 'choice', 'Using a line: points on it, horizontal and vertical lines, rates', 'A gym charges a joining fee of 40 dollars plus 12 dollars each month. After how many months has a member paid exactly 136 dollars in total?', '["$8$","$11$","$14$","$10$"]', '$8$', '(136-40)/12', 'After $m$ months the total is $40+12m$. Set $40+12m=136$: $12m=96$ and $m=8$.', 'checked', '{"lint":[],"solve":{"answer":"$8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40+12m=136, 12m=96, m=8","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
