INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b47242c-802d-4392-92f9-74f2444f474d', 'ALG.08', 2, 'numeric', 'Using a line: points on it, horizontal and vertical lines, rates', 'The points $(1, 3)$, $(2, 5)$, $(3, 7)$ and $(4, 9)$ lie on a line. What is $y$ on this line when $x=10$?', '[]', '21', '1+2*10', 'Each step of $1$ in $x$ raises $y$ by $2$, so the slope is $2$. The line is $y=2x+1$ (check: $x=1$ gives $3$). At $x=10$, $y=21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=2x+1, x=10: 21","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
