INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40ba637c-7e04-4f92-9c0c-54b54b72ef8d', 'ALG.08', 3, 'numeric', 'Slope from two points', 'The line through $(a, 3)$ and $(7, 9)$ has slope $\frac{3}{2}$. What is $a$?', '[]', '3', '7-(9-3)/(3/2)', 'The rise from $(a, 3)$ to $(7, 9)$ is $6$. Since rise $\div$ run $=\frac{3}{2}$, the run is $6\div\frac{3}{2}=4$. So $7-a=4$ and $a=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9-3)/(7-a)=3/2 so 7-a=4, a=3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
