INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac65a94b-e102-4cee-a42d-b407ca96cdb0', 'ALG.08', 3, 'numeric', 'Slope from two points', 'The points $(0, 0)$, $(2, 3)$ and $(6, k)$ all lie on one straight line. What is $k$?', '[]', '9', '3/2*6', 'The slope from $(0, 0)$ to $(2, 3)$ is $\frac{3}{2}$. Every pair of points on the line has this slope, so from $(0, 0)$ to $(6, k)$ we need $\frac{k}{6}=\frac{3}{2}$, giving $k=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope from (0,0) to (2,3) is 3/2; y=1.5x; at x=6, k=9","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
