INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('443dd7cd-dd68-483c-a833-f1db1e993e3c', 'ALG.08', 3, 'choice', 'Slope from two points', 'The points $(1, 1)$ and $(3, 7)$ are on a line. Which of these points is also on that line?', '["$(5, 13)$","$(4, 11)$","$(6, 17)$","$(2, 5)$"]', '$(5, 13)$', NULL, 'The slope is $\frac{7-1}{3-1}=3$. From $(1, 1)$, going to $x=5$ is a run of $4$, which raises $y$ by $12$, so the point is $(5, 13)$. The others would need $y=10$, $16$ and $4$ at $x=4$, $6$ and $2$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 13)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope (7-1)/(3-1)=3, y=3x-2. (5,13): 15-2=13 yes; (6,17):16 no; (4,11):10 no; (2,5):4 no","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
