INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9c20593-df6b-4238-8624-50c9a414241c', 'ALG.08', 3, 'numeric', 'Slope from two points', 'The slope of the line through $(0, 5)$ and $(8, k)$ is $-\frac{3}{4}$. What is $k$?', '[]', '-1', '5-3/4*8', 'The run is $8$, so the rise is $-\frac{3}{4}\times 8=-6$. Then $k=5+(-6)=-1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k-5)/8=-3/4 so k-5=-6, k=-1","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
