INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17d3b735-1ec0-4ed6-a1f3-be1c4b1f1d49', 'ALG.08', 3, 'choice', 'Slope and y-intercept from an equation', 'Which of these lines has the greatest slope?', '["$y=3x+10$","$x-y=-4$","$3y=10x-2$","$2y=7x+1$"]', '$2y=7x+1$', NULL, 'Put each in slope-intercept form. The slopes are: $3$ for $y=3x+10$; $\frac{7}{2}=3.5$ for $2y=7x+1$; $1$ for $x-y=-4$ (it is $y=x+4$); and $\frac{10}{3}\approx 3.33$ for $3y=10x-2$. The greatest is $3.5$.', 'checked', '{"lint":[],"solve":{"answer":"$2y=7x+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slopes: 10/3~3.33, 7/2=3.5, 3, and y=x+4 gives 1. Greatest 7/2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c70a4213-978b-4e29-b113-8eb25fdb0467', 'ALG.08', 3, 'numeric', 'Slope and y-intercept from an equation', 'The line $ax+4y=20$ has slope $-\frac{3}{2}$. What is $a$?', '[]', '6', '3/2*4', 'Solve for $y$: $4y=-ax+20$, so $y=-\frac{a}{4}x+5$. The slope is $-\frac{a}{4}=-\frac{3}{2}$, so $a=\frac{3}{2}\times 4=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4y=-ax+20, slope -a/4=-3/2 so a=6","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
