INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dc11897-a94b-4d2a-8954-ba988d1421fd', 'ALG.08', 3, 'numeric', 'Slope and y-intercept from an equation', 'The line $6x-4y=10$ crosses the $y$-axis at $(0, b)$. What is $b$ as a fraction in lowest terms?', '[]', '-5/2', '10/(-4)', 'Put $x=0$: $-4y=10$, so $y=-\frac{10}{4}=-\frac{5}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-5/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0: -4y=10, y=-5/2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
