INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a59ca9e3-99ed-442f-aec7-834c2d911533', 'ALG.08', 3, 'choice', 'Intercepts of a line', 'A line has $x$-intercept $6$ and $y$-intercept $-4$. What is its slope?', '["$-\\frac{2}{3}$","$\\frac{3}{2}$","$-\\frac{3}{2}$","$\\frac{2}{3}$"]', '$\frac{2}{3}$', NULL, 'The line passes through $(6, 0)$ and $(0, -4)$. The rise is $-4-0=-4$ and the run is $0-6=-6$, so the slope is $\frac{-4}{-6}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"points (6,0),(0,-4): slope (0+4)/(6-0)=2/3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
