INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3a690de-ec91-4e2e-abf3-ebfefafe90e1', 'ALG.08', 3, 'numeric', 'Intercepts of a line', 'The line $3x+4y=12$ and the two axes enclose a triangle. What is the area of that triangle, in square units?', '[]', '6', '4*3/2', 'The $x$-intercept is $4$ (put $y=0$) and the $y$-intercept is $3$ (put $x=0$). The triangle has a right angle at the origin with legs $4$ and $3$, so its area is $\frac{1}{2}\times 4\times 3=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"intercepts x=4, y=3; area 4*3/2=6","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
