INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('488f6669-0b74-4499-91fa-91b5525a4e27', 'ALG.08', 3, 'choice', 'Intercepts of a line', 'Which line has $x$-intercept $4$ and $y$-intercept $-6$?', '["$3x-2y=12$","$2x-3y=12$","$3x+2y=12$","$3x-2y=24$"]', '$3x-2y=12$', NULL, 'For $3x-2y=12$: with $y=0$, $x=4$; with $x=0$, $y=-6$. The others give intercepts $(6, -4)$, $(4, 6)$ and $(8, -12)$.', 'checked', '{"lint":[],"solve":{"answer":"$3x-2y=12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-2y=12: x=4, y=-6 yes. 3x+2y=12 has y-int 6; 3x-2y=24 has x-int 8; 2x-3y=12 has x-int 6","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
