INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a2035a4-60fe-4ea5-a6d3-07be9e07816c', 'ALG.08', 3, 'choice', 'Write the equation of a line from a slope and a point or two points', 'Which line passes through both $(-2, 1)$ and $(4, -3)$?', '["$y=-\\frac{2}{3}x+\\frac{1}{3}$","$y=-\\frac{2}{3}x-\\frac{1}{3}$","$y=-\\frac{3}{2}x-\\frac{1}{3}$","$y=\\frac{2}{3}x-\\frac{1}{3}$"]', '$y=-\frac{2}{3}x-\frac{1}{3}$', NULL, 'The slope is $\frac{-3-1}{4-(-2)}=-\frac{4}{6}=-\frac{2}{3}$. Put in $(-2, 1)$: $1=\frac{4}{3}+b$, so $b=-\frac{1}{3}$. Check with $(4, -3)$: $-\frac{8}{3}-\frac{1}{3}=-3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=-\\frac{2}{3}x-\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope -4/6=-2/3; 1=4/3+b, b=-1/3; check (4,-3): -8/3-1/3=-3","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('053ae3f0-32b3-4ab7-9d5e-73fb294fe3ad', 'ALG.08', 3, 'numeric', 'Write the equation of a line from a slope and a point or two points', 'A line passes through $(2, 3)$ and $(6, 11)$ and crosses the $x$-axis at $(a, 0)$. What is $a$? Write it as a fraction.', '[]', '1/2', '1/2', 'The slope is $\frac{11-3}{6-2}=2$. Then $y=2x+b$ with $3=4+b$, so $b=-1$ and the line is $y=2x-1$. Setting $y=0$ gives $x=\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope 8/4=2, y=2x-1, x-int 1/2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
