INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae01d27a-b6e9-471b-8abb-70976f5ed739', 'ALG.08', 3, 'numeric', 'Write the equation of a line from a slope and a point or two points', 'A taxi charges a fixed fee plus the same amount for every mile. A 5-mile ride costs 13 dollars and a 9-mile ride costs 21 dollars. How many dollars does a 12-mile ride cost?', '[]', '27', '13+(21-13)/(9-5)*(12-5)', 'From 5 to 9 miles (4 more miles) the cost rises by 8 dollars, so each mile costs 2 dollars. A 12-mile ride is 7 miles longer than a 5-mile ride: $13+7\times 2=27$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"per mile (21-13)/4=2, fee 13-10=3; 12 miles: 3+24=27","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
