INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffcb740e-ff10-47e8-80dd-9dd3d505102f', 'ALG.08', 3, 'numeric', 'Point-slope form', 'The equations $y-1=3(x-2)$ and $y+2=3(x-h)$ describe the same line. What is $h$?', '[]', '1', '1', 'The first line is $y=3x-5$. The second is $y=3x-3h-2$. Matching the constants: $-3h-2=-5$, so $h=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3x-5; y=3x-3h-2; -3h-2=-5, h=1","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
