INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c122604-be32-44c6-b4bb-32460de2636c', 'ALG.08', 3, 'numeric', 'Point-slope form', 'A line passes through $(1, -2)$ and $(5, 6)$. What is $y$ on this line when $x=7$?', '[]', '10', '-2+(6+2)/(5-1)*(7-1)', 'The slope is $\frac{6-(-2)}{5-1}=2$. From $x=1$ to $x=7$ is a run of $6$, which raises $y$ by $12$: $-2+12=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope 8/4=2, y=2x-4, x=7: 10","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
