INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75fa93e2-1046-4e18-a77d-90ca88b614f1', 'ALG.08', 3, 'choice', 'Standard form (Ax + By = C)', 'A line has slope $\frac{2}{3}$ and passes through $(3, -1)$. It can be written as $2x-3y=C$. What is $C$?', '["$9$","$3$","$-3$","$-9$"]', '$9$', '2*3-3*(-1)', 'Put the point in $2x-3y$: $2(3)-3(-1)=6+3=9$. Since the slope is $\frac{2}{3}$ this form is correct for the line, so $C=9$.', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3)-3(-1)=6+3=9","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a99932a2-bde7-4b7e-ae26-ad1c4ba2d2eb', 'ALG.08', 3, 'choice', 'Standard form (Ax + By = C)', 'Which equation has exactly the same graph as $6x+9y=27$?', '["$3x+2y=9$","$2x+3y=9$","$2x+3y=27$","$2x+3y=3$"]', '$2x+3y=9$', NULL, 'Divide every term by $3$: $2x+3y=9$. The other choices change only some of the terms.', 'checked', '{"lint":[],"solve":{"answer":"$2x+3y=9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"divide by 3: 2x+3y=9","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
