INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('628383d8-2f0a-480d-b6be-749f4b50ea6d', 'ALG.08', 3, 'numeric', 'Standard form (Ax + By = C)', 'The line $Ax+By=12$ passes through $(2, 0)$ and $(0, 3)$. What is $A+B$?', '[]', '10', '12/2+12/3', 'Put in $(2, 0)$: $2A=12$, so $A=6$. Put in $(0, 3)$: $3B=12$, so $B=4$. Then $A+B=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2A=12 A=6; 3B=12 B=4; sum 10","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
