INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f763dcd0-11b1-46f8-8eb5-b935a36d41b6', 'ALG.08', 3, 'numeric', 'Standard form (Ax + By = C)', 'How many pairs of positive whole numbers $(x, y)$ satisfy $3x+5y=31$?', '[]', '2', '2', 'Try each $y$: $y=1$ gives $3x=26$; $y=2$ gives $3x=21$, so $x=7$; $y=3$ gives $3x=16$; $y=4$ gives $3x=11$; $y=5$ gives $3x=6$, so $x=2$; $y=6$ gives $3x=1$. Larger $y$ is too big. The pairs are $(7, 2)$ and $(2, 5)$: 2 pairs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=2: x=7; y=5: x=2; other y in 1..6 fail; 2 pairs","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f39107f-b2db-4fb9-9fc1-bc8e15e61d94', 'ALG.08', 3, 'numeric', 'Parallel and perpendicular lines', 'The line through $(1, 2)$ and $(4, k)$ is parallel to $y=3x-5$. What is $k$?', '[]', '11', '2+3*3', 'The slope must be $3$. The run from $x=1$ to $x=4$ is $3$, so the rise is $9$ and $k=2+9=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k-2)/3=3, k=11","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
