INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fa4e32f-b706-40bb-9177-2f162617e234', 'ALG.08', 3, 'choice', 'Parallel and perpendicular lines', 'The lines $kx+2y=5$ and $3x+y=4$ are parallel. What is $k$?', '["$6$","$-6$","$\\frac{3}{2}$","$\\frac{2}{3}$"]', '$6$', '6', 'The second line is $y=-3x+4$, slope $-3$. The first is $y=-\frac{k}{2}x+\frac{5}{2}$. Equal slopes: $-\frac{k}{2}=-3$, so $k=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slopes -k/2 and -3; k=6","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('319eabdd-0a3a-4524-9357-5b48da50b356', 'ALG.08', 3, 'numeric', 'Parallel and perpendicular lines', 'The lines $ax+3y=7$ and $2x-y=5$ are perpendicular. What is $a$? Write it as a fraction.', '[]', '3/2', '3/2', 'The first has slope $-\frac{a}{3}$ and the second has slope $2$. Perpendicular: $-\frac{a}{3}\times 2=-1$, so $a=\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slopes -a/3 and 2; (-a/3)*2=-1, a=3/2","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
