INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5fee886-4797-4dd5-a05f-0c8ec5626967', 'ALG.08', 3, 'numeric', 'Using a line: points on it, horizontal and vertical lines, rates', 'How many points with both coordinates positive whole numbers lie on the line $x+2y=15$?', '[]', '7', '7', 'Since $x=15-2y$, we need $15-2y\ge 1$, so $y\le 7$. Each $y$ from $1$ to $7$ gives a positive whole $x$ ($13, 11, 9, 7, 5, 3, 1$). That is 7 points.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=15-2y>0: y=1..7 (x=13,...,1): 7 points","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
