INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef39ad59-3038-40e8-8fb2-7e70abea1dfb', 'ALG.08', 3, 'numeric', 'Using a line: points on it, horizontal and vertical lines, rates', 'A line crosses the $y$-axis at $(0, 2)$ and passes through $(4, 14)$. At what value of $x$ does the line reach $y=50$?', '[]', '16', '(50-2)/((14-2)/4)', 'The slope is $\frac{14-2}{4-0}=3$, so the line is $y=3x+2$. Setting $y=50$: $3x=48$ and $x=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope 12/4=3, y=3x+2=50, x=16","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
