INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa5fd742-d33d-4759-9673-235661f4b243', 'ALG.08', 3, 'choice', 'Using a line: points on it, horizontal and vertical lines, rates', 'A line has a positive slope and a negative $y$-intercept. In which quadrant does the line have no points at all?', '["Quadrant I","Quadrant III","Quadrant II","Quadrant IV"]', 'Quadrant II', NULL, 'Take $y=mx+b$ with $m>0$ and $b<0$. In Quadrant II we need $x<0$ and $y>0$, but then $mx<0$ and $b<0$, so $y=mx+b<0$. So no point is in Quadrant II. The line does cross the other three quadrants: for example $y=x-1$ passes through $(3, 2)$ in Quadrant I, $(-1, -2)$ in Quadrant III and $(\frac{1}{2}, -\frac{1}{2})$ in Quadrant IV.', 'checked', '{"lint":[],"solve":{"answer":"Quadrant II","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"line y=mx+b, m>0,b<0 passes through III, IV and I; for x<0, y<b<0 so never in II","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c91ffb9-93c1-44ec-8f0e-aa4df8d05e55', 'ALG.08', 3, 'numeric', 'Using a line: points on it, horizontal and vertical lines, rates', 'A car drives at a steady speed. After 1 hour it is 70 miles from home and after 3 hours it is 190 miles from home. After how many hours is it 400 miles from home?', '[]', '13/2', '(400-10)/60', 'In 2 hours it travels $190-70=120$ miles, so its speed is 60 miles per hour. At time 0 it was $70-60=10$ miles from home, so the distance is $60t+10$. Setting this to $400$: $60t=390$ and $t=6.5$ hours.', 'checked', '{"lint":[],"solve":{"answer":"6.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"speed (190-70)/2=60 mph, d=60t+10; 400=60t+10, t=6.5","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
