VALUES ('b9968aef-18d0-4f15-8ecf-973e599d0ec0', 'ALG.09', 1, 'choice', 'Multi-step inequalities (variables on both sides, brackets, fractions)', 'Which is the solution of $4(x+1)>12$?', '["$x>\\frac{11}{4}$","$x>2$","$x<2$","$x>11$"]', '$x>2$', NULL, 'Expand: $4x+4>12$. Then $4x>8$ and $x>2$. (Another way: divide both sides by $4$ first to get $x+1>3$.)', 'checked', '{"lint":[],"solve":{"answer":"$x>2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+1>3, x>2","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
