INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75294f24-318b-41dd-8327-99a8579c48b0', 'ALG.09', 1, 'choice', 'Inequality word problems', 'Tom has 20 dollars. A notebook costs 3 dollars. What is the greatest number of notebooks he can buy?', '["$7$","$5$","$6$","$17$"]', '$6$', '6', 'If he buys $n$ notebooks, $3n\le 20$, so $n\le 6\frac{2}{3}$. He can buy 6 notebooks (7 would cost 21 dollars).', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n<=20, n<=6","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
