VALUES ('1925a2dc-b382-40dd-aa7f-716656fd9089', 'ALG.09', 2, 'numeric', 'Compound inequalities with "or"', 'How many integers from $-5$ to $5$ (including both) satisfy $3x-2\le -5$ or $3x-2\ge 7$?', '[]', '8', '5+3', 'First: $3x\le -3$, so $x\le -1$. Second: $3x\ge 9$, so $x\ge 3$. The integers are $-5, -4, -3, -2, -1$ and $3, 4, 5$: that is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x<=-1 or x>=3: -5..-1 (5) and 3,4,5 (3) = 8","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
