INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019cba15-5a7b-48a2-ad57-53200088ceef', 'ALG.09', 2, 'numeric', 'Inequality word problems', 'Plan A costs 15 dollars plus 3 dollars per hour. Plan B costs 6 dollars per hour. For how many whole numbers of hours (1 or more) is plan B cheaper than plan A?', '[]', '4', '4', 'Plan B is cheaper when $6h<15+3h$, so $3h<15$ and $h<5$. The whole numbers of hours from 1 to 4 work: 4 values. (At 5 hours both cost 30 dollars.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6h<15+3h, h<5: 1..4 -> 4","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
