INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6164bd3-7b16-420d-8823-df5d08df0305', 'ALG.09', 3, 'numeric', 'Solve a one- or two-step linear inequality', 'The inequality $3x-4>k$ has the solution $x>5$. What is $k$?', '[]', '11', '3*5-4', 'Solving gives $x>\frac{k+4}{3}$. This equals $5$, so $k+4=15$ and $k=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x>(k+4)/3=5, k=11","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
