VALUES ('858ca714-4cda-4dac-9e80-2b06ab092501', 'ALG.09', 3, 'choice', 'Inequalities with a negative coefficient (reverse the sign)', 'Which inequality has exactly the same solutions as $6-2x<4x$?', '["$x<1$","$x>-1$","$x>3$","$x>1$"]', '$x>1$', NULL, 'Add $2x$ to both sides: $6<6x$. Divide by $6$: $1<x$, which is $x>1$. No sign needs reversing because $6$ is positive.', 'checked', '{"lint":[],"solve":{"answer":"$x>1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6<6x, x>1","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
