INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('113120db-1a0a-433a-8214-c98ad9332003', 'ALG.09', 3, 'numeric', 'Inequalities with a negative coefficient (reverse the sign)', 'What is the greatest value of $x$ that satisfies $\frac{1-x}{2}\ge\frac{x+3}{3}$? Write it as a fraction.', '[]', '-3/5', '-3/5', 'Multiply by $6$: $3(1-x)\ge 2(x+3)$, so $3-3x\ge 2x+6$. Collect the $x$ terms on the right and the numbers on the left: $3-6\ge 2x+3x$, so $-3\ge 5x$ and $x\le -\frac{3}{5}$. The greatest value is $-\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"-3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(1-x)>=2(x+3), 3-3x>=2x+6, -3>=5x, x<=-3/5","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
