VALUES ('d1f44235-b1e0-4f6a-bcbe-b841d05823e2', 'ALG.09', 3, 'choice', 'Multi-step inequalities (variables on both sides, brackets, fractions)', 'Which is the solution of $\frac{x}{4}-\frac{1}{2}<\frac{x}{6}+1$?', '["$x>18$","$x<18$","$x<6$","$x<30$"]', '$x<18$', NULL, 'Multiply every term by $12$: $3x-6<2x+12$. Subtract $2x$ and add $6$: $x<18$.', 'checked', '{"lint":[],"solve":{"answer":"$x<18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"times 12: 3x-6<2x+12, x<18","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
