INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c2c889b-e411-46ee-8b1a-48e9cd7afc3b', 'ALG.09', 3, 'numeric', 'Absolute value inequalities', 'What is the sum of all integers $x$ that satisfy $|2x-5|\le 3$?', '[]', '10', '1+2+3+4', '$-3\le 2x-5\le 3$. Add $5$: $2\le 2x\le 8$. Divide by $2$: $1\le x\le 4$. The integers $1, 2, 3, 4$ add up to $10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2<=2x<=8, 1<=x<=4, sum 10","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ff3e070-fc22-4abe-9f67-eec8e8e8af33', 'ALG.09', 3, 'choice', 'Absolute value inequalities', 'Which inequality has the solution $-1<x<5$?', '["$|x-2|>3$","$|x-2|<3$","$|x+2|<3$","$|x-3|<3$"]', '$|x-2|<3$', NULL, 'The interval from $-1$ to $5$ has centre $2$ and half-width $3$, so it is the set of $x$ within $3$ of $2$: $|x-2|<3$. The other choices give intervals centred at $2$ (outside), $-2$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$|x-2|<3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"centre 2, radius 3: |x-2|<3","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a318b2c7-8b69-4409-a4af-cce3db3bb495', 'ALG.09', 3, 'numeric', 'Absolute value inequalities', 'The solutions of $|x-a|\le 4$ are all the numbers from $-1$ to $b$. What is $a\times b$?', '[]', '21', '3*7', 'The solutions are $a-4\le x\le a+4$. The left end is $-1$, so $a=3$. The right end is $b=3+4=7$. Then $a\times b=21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a-4=-1, a=3, b=a+4=7, ab=21","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8a8e535-314d-4948-aa4e-f3fbf64b983f', 'ALG.09', 3, 'numeric', 'Absolute value inequalities', 'How many integers satisfy $2<|x|<6$?', '[]', '6', '6', 'Positive solutions: $3, 4, 5$. Negative solutions: $-3, -4, -5$. That is 6 integers.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|x| in {3,4,5}: 6","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
