INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4517ef1-c18a-4642-9832-b1dff2f5754e', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'A rectangle is 6 cm wide and its length is a whole number of centimeters. Its perimeter is less than 50 cm. What is the greatest possible length?', '[]', '18', '18', 'Perimeter $=2(6+L)<50$, so $6+L<25$ and $L<19$. The greatest whole length is $18$ cm.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(6+L)<50, L<19, 18","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10106fd9-07e1-4e41-bf6c-80b9621eb1aa', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'The sum of three consecutive integers is greater than 40 and less than 60. How many such sets of three consecutive integers are there?', '[]', '6', '18-13+1', 'Let the smallest be $n$. The sum is $3n+3$, and $40<3n+3<60$ gives $37<3n<57$, so $12.3\ldots<n<19$. The values are $n=13, 14, \ldots, 18$: 6 sets.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3m with middle m: 40<3m<60, 13.3<m<20, m=14..19: 6","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e261d1f3-709d-4e8d-be21-3b426efd6c79', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'Ann has $x$ marbles. Ben has 3 more than twice as many as Ann. Together they have fewer than 40 marbles. What is the greatest whole number Ann can have?', '[]', '12', '12', 'Together: $x+(2x+3)<40$, so $3x<37$ and $x<12.3\ldots$ The greatest whole number is $12$. (Check: 12 and 27 make 39.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+3<40, x<37/3, 12","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30590f80-f8e7-4e91-864e-284f71bb3390', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'A bag of rice is labelled 50 pounds. A bag is accepted if its weight $w$, a whole number of pounds, satisfies $|w-50|\le 4$. How many different whole-number weights are accepted?', '[]', '9', '9', '$-4\le w-50\le 4$, so $46\le w\le 54$. The whole numbers from $46$ to $54$ number 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"46..54: 9","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5be1fa9c-545f-4a7f-92e7-deb9845cef27', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'Ria buys pens at 3 dollars each and notebooks at 5 dollars each. She buys 10 items in all and spends at most 38 dollars. What is the greatest number of notebooks she can buy?', '[]', '4', '4', 'With $n$ notebooks she buys $10-n$ pens. Cost: $3(10-n)+5n=30+2n\le 38$, so $n\le 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n notebooks: 5n+3(10-n)=30+2n<=38, n<=4","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f9e1937-1461-43e7-9d00-d130d21f5886', 'ALG.10', 1, 'choice', 'Factor a monic quadratic', 'Which expression is equal to $x^2+7x+12$?', '["$(x+3)(x+4)$","$(x-3)(x-4)$","$(x+2)(x+6)$","$(x+7)(x+12)$"]', '$(x+3)(x+4)$', NULL, 'We need two numbers that multiply to 12 and add to 7. Those are 3 and 4, so $x^2+7x+12=(x+3)(x+4)$. Check: $(x+3)(x+4)=x^2+7x+12$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+3)(x+4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need two numbers with product 12 and sum 7: 3 and 4. (x+3)(x+4)=x^2+7x+12.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e2176cb-db95-4002-b431-ff7354f61921', 'ALG.10', 1, 'numeric', 'Factor a monic quadratic', '$x^2+9x+20=(x+4)(x+k)$. What number is $k$?', '[]', '5', '20/4', 'The numbers in the two brackets multiply to 20. Since $4\times k=20$, $k=5$. Check the middle term: $4+5=9$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/4=5 and 4+5=9, so (x+4)(x+5). k=5.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
