INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70e9c5ca-5956-43cf-90bd-d90efdc4a9d1', 'ALG.10', 1, 'choice', 'Factor a monic quadratic', 'Which of these is a factor of $x^2+10x+21$?', '["$x+5$","$x+3$","$x+10$","$x+21$"]', '$x+3$', NULL, 'Two numbers that multiply to 21 and add to 10 are 3 and 7, so $x^2+10x+21=(x+3)(x+7)$. Of the choices, only $x+3$ is a factor.', 'checked', '{"lint":[],"solve":{"answer":"$x+3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21=3*7, 3+7=10, so (x+3)(x+7). Factor x+3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c1bd057-0635-478d-9645-81bad29015f0', 'ALG.10', 1, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'Which expression is equal to $2x^2+7x+3$?', '["$(2x+3)(x+1)$","$(2x+1)(x+3)$","$(2x-1)(x-3)$","$(x+1)(x+6)$"]', '$(2x+1)(x+3)$', NULL, 'Try $(2x+1)(x+3)$. The product is $2x^2+6x+x+3=2x^2+7x+3$. The other choices give a different middle term or a different first term.', 'checked', '{"lint":[],"solve":{"answer":"$(2x+1)(x+3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+1)(x+3)=2x^2+6x+x+3=2x^2+7x+3. (2x+3)(x+1)=2x^2+5x+3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
