INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73142c23-8a55-4ca0-b4ee-1d787f3c22b7', 'ALG.10', 1, 'numeric', 'Factor a quadratic with a leading coefficient or common factor', '$3x^2+12x+9=3(x+p)(x+q)$, where $p<q$. What is $q$?', '[]', '3', NULL, 'Take out the common factor 3: $3x^2+12x+9=3(x^2+4x+3)=3(x+1)(x+3)$. So $p=1$ and $q=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x^2+4x+3)=3(x+1)(x+3). p=1, q=3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fa68909-52de-43eb-a9a1-367309757143', 'ALG.10', 1, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'Which expression is equal to $5x^2-20x+15$?', '["$(x-1)(x-3)$","$5(x+1)(x+3)$","$5(x-1)(x-3)$","$5(x-1)(x+3)$"]', '$5(x-1)(x-3)$', NULL, 'First take out the common factor 5: $5(x^2-4x+3)$. Then $x^2-4x+3=(x-1)(x-3)$. So the expression is $5(x-1)(x-3)$.', 'checked', '{"lint":[],"solve":{"answer":"$5(x-1)(x-3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x^2-4x+3)=5(x-1)(x-3).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
