INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d60b0fcc-d0ef-4ec4-a7d1-f46fdcceb379', 'ALG.10', 1, 'numeric', 'Solve a factored equation (zero-product rule)', 'Solve $(x-4)(x+2)=0$. What is the larger solution?', '[]', '4', NULL, 'A product is 0 only when one factor is 0. So $x-4=0$ or $x+2=0$, giving $x=4$ or $x=-2$. The larger is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=4 or x=-2. Larger 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
