INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a86a7616-6acf-49f8-bfa1-64ae6118e7a1', 'ALG.10', 1, 'choice', 'Solve a factored equation (zero-product rule)', 'What are the solutions of $(x+5)(x-1)=0$?', '["$x=5$ or $x=-1$","$x=5$ or $x=1$","$x=-5$ or $x=-1$","$x=-5$ or $x=1$"]', '$x=-5$ or $x=1$', NULL, 'Set each factor to 0: $x+5=0$ gives $x=-5$, and $x-1=0$ gives $x=1$.', 'checked', '{"lint":[],"solve":{"answer":"$x=-5$ or $x=1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+5=0 or x-1=0: x=-5 or 1.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
