INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c0fdf3-688e-4c2c-9aa5-8894ff50ca58', 'ALG.10', 1, 'choice', 'Solve a quadratic equation by factoring', 'Solve $x^2-5x+6=0$. What is the smaller solution?', '["3","6","-2","2"]', '2', NULL, 'Factor: $x^2-5x+6=(x-2)(x-3)=0$. So $x=2$ or $x=3$. The smaller is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x-3)=0: 2 or 3. Smaller 2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
