INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3e412d2-4b1e-40b7-8ae2-5038dcbd4e45', 'ALG.10', 1, 'choice', 'Solve a quadratic equation by factoring', 'Solve $x^2+3x-10=0$. Which gives all the solutions?', '["$x=5$ or $x=-2$","$x=-5$ or $x=-2$","$x=-5$ or $x=2$","$x=5$ or $x=2$"]', '$x=-5$ or $x=2$', NULL, 'Two numbers that multiply to $-10$ and add to 3 are 5 and $-2$. So $(x+5)(x-2)=0$ and $x=-5$ or $x=2$.', 'checked', '{"lint":[],"solve":{"answer":"$x=-5$ or $x=2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+5)(x-2)=0: -5 or 2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
