INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b80f1e57-433e-49d3-972e-379785c1602d', 'ALG.10', 1, 'numeric', 'Equations with a common factor of x', 'Find the smaller solution of $x^2+4x=0$.', '[]', '-4', NULL, '$x(x+4)=0$, so $x=0$ or $x=-4$. The smaller is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x+4)=0: 0 or -4. Smaller -4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
