INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8df47784-ade0-4bfc-944f-f09ddf00e912', 'ALG.10', 1, 'choice', 'Sum and product of the roots', 'What is the sum of the solutions of $x^2-11x+24=0$?', '["-11","24","11","-24"]', '11', NULL, 'For $x^2+bx+c=0$ the solutions add to $-b$. Here $b=-11$, so the sum is 11. (Check: $(x-3)(x-8)=0$ gives 3 and 8.)', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)(x-8)=0: 3+8=11 (= -b/a).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
