INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9cabbca-b96b-453d-a8b5-9bbca0116148', 'ALG.10', 1, 'choice', 'Sum and product of the roots', 'What is the product of the solutions of $x^2+4x-21=0$?', '["21","4","-4","-21"]', '-21', '-21', 'For $x^2+bx+c=0$ the solutions multiply to $c$. Here $c=-21$. (Check: $(x+7)(x-3)=0$ gives $-7$ and 3, and $-7\times3=-21$.)', 'checked', '{"lint":[],"solve":{"answer":"-21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+7)(x-3)=0: product -21 (= c/a).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
