INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72a0d5d6-6c8b-4b85-ac99-1c999490efed', 'ALG.10', 1, 'numeric', 'Sum and product of the roots', 'Find the product of the two solutions of $x^2-15x+56=0$.', '[]', '56', NULL, 'The product of the solutions of $x^2+bx+c=0$ is $c$, which is 56. (They are 7 and 8.)', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-7)(x-8)=0: 56.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
