INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d783ff36-224a-4b0c-88f6-783da9ed0144', 'ALG.10', 1, 'choice', 'Build a quadratic from its roots', 'Which equation has the solutions $x=2$ and $x=5$?', '["$x^2+7x+10=0$","$x^2-7x+10=0$","$x^2-7x-10=0$","$x^2-10x+7=0$"]', '$x^2-7x+10=0$', NULL, '$(x-2)(x-5)=x^2-7x+10$. In general the equation is $x^2-(\text{sum})x+(\text{product})=0$, with sum 7 and product 10.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-7x+10=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x-5)=x^2-7x+10.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
