INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef81f56b-e460-4098-af85-d57a40962983', 'ALG.10', 1, 'choice', 'Build a quadratic from its roots', 'The number 3 is a solution of $x^2-5x+k=0$. What is $k$?', '["6","-6","9","4"]', '6', '15-9', 'Put $x=3$ in: $9-15+k=0$, so $k=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-15+k=0, k=6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
