INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a914c4ef-2a92-42b1-9798-a04babf9b045', 'ALG.10', 1, 'numeric', 'Build a quadratic from its roots', 'The solutions of $x^2+bx+10=0$ are 2 and 5. What is $b$?', '[]', '-7', '-(2+5)', 'The solutions add to $-b$. Since $2+5=7$, $b=-7$. Check: $(x-2)(x-5)=x^2-7x+10$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7=-b, b=-7. Product 10 checks.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
