INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5139a217-aff3-40a4-901b-d5a65366cdce', 'ALG.10', 1, 'choice', 'Expressions in the roots', 'The solutions of $x^2-8x+12=0$ are $r$ and $s$. What is the value of $r+s+rs$?', '["-4","96","20","8"]', '20', '8+12', 'The sum $r+s=8$ and the product $rs=12$. So $r+s+rs=8+12=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=8, rs=12. 20.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
