INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4539cc0-b007-40f8-bcf5-bf074b276cbf', 'ALG.10', 1, 'numeric', 'Expressions in the roots', 'The solutions of $x^2-4x-12=0$ are $r$ and $s$. Find $(r+s)\times rs$.', '[]', '-48', '4*(-12)', '$r+s=4$ and $rs=-12$. The product is $4\times(-12)=-48$.', 'checked', '{"lint":[],"solve":{"answer":"-48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=4, rs=-12. -48.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
