INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16f4e36a-378d-4853-93a2-70f6ac364218', 'ALG.10', 1, 'numeric', 'Word problems leading to a quadratic', 'A rectangle is $x$ meters wide and $x+4$ meters long. Its area is 21 square meters. What is $x$?', '[]', '3', NULL, 'The area is $x(x+4)=21$, so $x^2+4x-21=0$, which is $(x+7)(x-3)=0$. A width cannot be negative, so $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+4x-21=0, (x+7)(x-3)=0, x=3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69c167fb-1ec3-4509-b758-302323f007dd', 'ALG.10', 1, 'choice', 'Word problems leading to a quadratic', 'Two positive numbers differ by 3 and multiply to 40. Which pair are they?', '["4 and 10","4 and 7","8 and 11","5 and 8"]', '5 and 8', NULL, 'Call the smaller $x$. Then $x(x+3)=40$, so $x^2+3x-40=0$, which is $(x+8)(x-5)=0$. So $x=5$ and the numbers are 5 and 8.', 'checked', '{"lint":[],"solve":{"answer":"5 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x+3)=40, x=5: 5 and 8.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a86c4e1f-6e92-4a5e-ac1d-9095e0d2aead', 'ALG.10', 1, 'choice', 'Word problems leading to a quadratic', 'The product of two consecutive positive whole numbers is 72. What is the larger number?', '["9","8","7","36"]', '9', NULL, 'Let the numbers be $n$ and $n+1$. Then $n^2+n-72=0$, which is $(n+9)(n-8)=0$. So $n=8$ and the larger number is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*9=72. Larger 9.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a28cfb8-3e9f-4824-814a-d6cb55bf80a9', 'ALG.10', 1, 'numeric', 'Counting and describing solutions', 'How many different values of $x$ satisfy $(x-3)(x-3)=0$?', '[]', '1', NULL, 'The only way the product is 0 is $x-3=0$, so $x=3$. There is just 1 value.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only x=3. 1.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bfd80c9-908c-45a8-ad73-dad6a31ea440', 'ALG.10', 1, 'choice', 'Counting and describing solutions', 'Which equation has exactly one solution?', '["$(x-2)(x+2)=0$","$x(x-2)=0$","$(x-2)(x-2)=0$","$(x-2)(x-3)=0$"]', '$(x-2)(x-2)=0$', NULL, '$(x-2)(x-2)=0$ gives only $x=2$. Each of the others has two different solutions.', 'checked', '{"lint":[],"solve":{"answer":"$(x-2)(x-2)=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)^2=0 only x=2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
