INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('243b203d-3ecc-4d80-9651-427eb3e10549', 'ALG.10', 1, 'numeric', 'Counting and describing solutions', 'How many different values of $x$ satisfy $x^2+5x-6=0$?', '[]', '2', NULL, '$x^2+5x-6=(x+6)(x-1)=0$, so $x=-6$ or $x=1$. There are 2 values.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+6)(x-1)=0: two values.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
