INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('721c485e-2352-4983-824d-267fe9806577', 'ALG.10', 2, 'choice', 'Factor a monic quadratic', 'Which is the factored form of $x^2-5x-14$?', '["$(x+7)(x-2)$","$(x-7)(x-2)$","$(x-7)(x+2)$","$(x-14)(x+1)$"]', '$(x-7)(x+2)$', NULL, 'We need two numbers that multiply to $-14$ and add to $-5$. These are $-7$ and $2$. So $x^2-5x-14=(x-7)(x+2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-7)(x+2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product -14, sum -5: -7 and 2. (x-7)(x+2)=x^2-5x-14.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a464d432-1e9b-4cbc-91e8-5a3d0cea107d', 'ALG.10', 2, 'numeric', 'Factor a monic quadratic', 'Maya writes $x^2-x-12=(x-4)(x+k)$. What is the number $k$?', '[]', '3', '12/4', 'The constant terms multiply to $-12$: $(-4)\times k=-12$, so $k=3$. Check the middle term: $-4+3=-1$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-4)(x+k)=x^2+(k-4)x-4k. -4k=-12 gives k=3; k-4=-1 checks.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ba81132-50f0-4bdf-8229-0d3bc311dbaf', 'ALG.10', 2, 'choice', 'Factor a monic quadratic', 'Which product is equal to $x^2-11x+28$?', '["$(x+4)(x+7)$","$(x-2)(x-14)$","$(x-3)(x-8)$","$(x-4)(x-7)$"]', '$(x-4)(x-7)$', NULL, 'The constant terms must multiply to 28 and add to $-11$. Both are negative: $-4$ and $-7$. So the product is $(x-4)(x-7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-4)(x-7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product 28, sum -11: -4 and -7. (x-4)(x-7). (x-2)(x-14) has middle -16x.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c42f8d6-ce77-48fd-b160-72761682da5e', 'ALG.10', 2, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'Which product is equal to $3x^2+10x+8$?', '["$(3x+2)(x+4)$","$(3x+8)(x+1)$","$(3x-4)(x-2)$","$(3x+4)(x+2)$"]', '$(3x+4)(x+2)$', NULL, 'Try $(3x+4)(x+2)=3x^2+6x+4x+8=3x^2+10x+8$. The other choices give middle terms $14x$, $11x$ and $-10x$.', 'checked', '{"lint":[],"solve":{"answer":"$(3x+4)(x+2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+4)(x+2)=3x^2+6x+4x+8=3x^2+10x+8. (3x+2)(x+4) gives 14x.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cd68b98-bbc5-41ab-92a9-9b4355ac0146', 'ALG.10', 2, 'numeric', 'Factor a quadratic with a leading coefficient or common factor', 'The expression $2x^2+11x+12$ has the factor $2x+3$. The other factor is $x+k$. What is $k$?', '[]', '4', '12/3', 'The constant terms multiply to 12: $3\times k=12$, so $k=4$. Check: $(2x+3)(x+4)=2x^2+8x+3x+12=2x^2+11x+12$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+3)(x+k)=2x^2+(2k+3)x+3k. 3k=12, k=4; 2k+3=11 checks.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70009a14-1a22-43ad-904f-2435e223a3b8', 'ALG.10', 2, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'Which of these is a factor of $2x^2-7x-15$?', '["$x-5$","$x+5$","$2x-3$","$x-3$"]', '$x-5$', NULL, 'Try $(2x+3)(x-5)=2x^2-10x+3x-15=2x^2-7x-15$. So $x-5$ is a factor (and so is $2x+3$).', 'checked', '{"lint":[],"solve":{"answer":"$x-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2-7x-15=(2x+3)(x-5): 2x^2-10x+3x-15. Factor x-5.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7b76d97-8956-4de9-95d1-c23cf2aedb2e', 'ALG.10', 2, 'choice', 'Solve a factored equation (zero-product rule)', 'What are the solutions of $(2x-1)(x+3)=0$?', '["$x=\\frac{1}{2}$ or $x=-3$","$x=2$ or $x=-3$","$x=\\frac{1}{2}$ or $x=3$","$x=-\\frac{1}{2}$ or $x=-3$"]', '$x=\frac{1}{2}$ or $x=-3$', NULL, '$2x-1=0$ gives $x=\frac{1}{2}$, and $x+3=0$ gives $x=-3$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{1}{2}$ or $x=-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x-1=0 gives 1/2; x+3=0 gives -3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
