INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('244cedd0-dbae-496b-a671-44b9af545f24', 'ALG.10', 2, 'numeric', 'Solve a factored equation (zero-product rule)', 'Find the smallest solution of $(3x+6)(x-5)=0$.', '[]', '-2', '-6/3', '$3x+6=0$ gives $x=-2$, and $x-5=0$ gives $x=5$. The smaller solution is $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6=0 gives -2; x=5. Smallest -2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
