INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b624e683-189e-4e50-8466-c18d5ddab997', 'ALG.10', 2, 'choice', 'Solve a quadratic equation by factoring', 'Which number is a solution of $x^2-9x+18=0$?', '["9","18","-3","6"]', '6', '6', '$x^2-9x+18=(x-3)(x-6)=0$, so the solutions are 3 and 6. Of the choices, 6 is the one.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)(x-6)=0: 3 or 6. Option 6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
