INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('552bd3c3-a23e-4f49-b9fc-aeab82548e4e', 'ALG.10', 2, 'numeric', 'Solve a quadratic equation by factoring', 'How much larger is the greater solution of $x^2-4x-21=0$ than the smaller solution?', '[]', '10', '7+3', '$x^2-4x-21=(x-7)(x+3)=0$, so $x=7$ or $x=-3$. The difference is $7-(-3)=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-7)(x+3)=0: 7 and -3. 7-(-3)=10.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4183ecca-52d6-4f9e-8679-3ef2b26f8bb6', 'ALG.10', 2, 'numeric', 'Rearrange to zero, then factor', 'Solve $x(x+3)=28$. What is the positive solution?', '[]', '4', NULL, 'Multiply out: $x^2+3x=28$, so $x^2+3x-28=0$. This factors as $(x+7)(x-4)=0$. The positive solution is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+3x-28=0, (x+7)(x-4)=0. Positive 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
