INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('995b9219-6717-43a1-a14d-0e4a65a4fb9b', 'ALG.10', 2, 'choice', 'Rearrange to zero, then factor', 'Which gives all the solutions of $(x+2)(x+3)=12$?', '["$x=6$ or $x=-1$","$x=10$ or $x=9$","$x=-6$ or $x=1$","$x=-2$ or $x=-3$"]', '$x=-6$ or $x=1$', NULL, 'Multiply out: $x^2+5x+6=12$, so $x^2+5x-6=0$, which is $(x+6)(x-1)=0$. So $x=-6$ or $x=1$. (We cannot set each factor equal to 12, because the product is not 0.)', 'checked', '{"lint":[],"solve":{"answer":"$x=-6$ or $x=1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+5x+6=12, x^2+5x-6=0, (x+6)(x-1)=0: -6 or 1.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27804bc7-5bcd-4591-910f-e67f1eab825a', 'ALG.10', 2, 'numeric', 'Rearrange to zero, then factor', 'Find the positive solution of $2x^2=x+15$.', '[]', '3', NULL, '$2x^2-x-15=0$ factors as $(2x+5)(x-3)=0$. So $x=-\frac{5}{2}$ or $x=3$, and the positive one is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2-x-15=0, (2x+5)(x-3)=0: 3 or -5/2. Positive 3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
