VALUES ('7a5efb76-0581-4a68-8fbc-f27aa06d8333', 'ALG.10', 2, 'numeric', 'Equations with a common factor of x', 'The equation $3x^2-12x=0$ has two solutions. What is their sum?', '[]', '4', NULL, '$3x(x-4)=0$, so $x=0$ or $x=4$. The sum is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x(x-4)=0: 0 or 4. Sum 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
