VALUES ('4a5593be-af09-4b10-bc01-a74c7f75babe', 'ALG.10', 2, 'choice', 'Equations with a common factor of x', 'What are the solutions of $4x^2+8x=0$?', '["$x=-2$","$x=0$ or $x=2$","$x=0$ or $x=-2$","$x=0$ or $x=-8$"]', '$x=0$ or $x=-2$', NULL, '$4x(x+2)=0$, so $x=0$ or $x=-2$.', 'checked', '{"lint":[],"solve":{"answer":"$x=0$ or $x=-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x(x+2)=0: 0 or -2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
