VALUES ('8c18296e-9ee1-4130-aced-9a087bc40eb3', 'ALG.10', 2, 'numeric', 'Sum and product of the roots', 'What is the sum of the solutions of $2x^2-14x+20=0$?', '[]', '7', NULL, 'Divide both sides by 2: $x^2-7x+10=0$. The solutions add to 7. (They are 2 and 5.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x^2-7x+10)=0: 2 and 5, sum 7.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
