INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b051f936-93c6-421a-8035-c65f1318abd4', 'ALG.10', 2, 'choice', 'Build a quadratic from its roots', 'Which equation has the solutions $x=-3$ and $x=7$?', '["$x^2+4x-21=0$","$x^2-4x+21=0$","$x^2-4x-21=0$","$x^2+4x+21=0$"]', '$x^2-4x-21=0$', NULL, '$(x+3)(x-7)=x^2-4x-21$. The sum of the solutions is 4 and the product is $-21$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-4x-21=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)(x-7)=x^2-4x-21.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a453ff6-af75-4b6c-ad81-213a4c9a4337', 'ALG.10', 2, 'numeric', 'Build a quadratic from its roots', 'The solutions of $x^2-bx+c=0$ are 6 and $-2$. What is the value of $b+c$?', '[]', '-8', '(6-2)+6*(-2)', 'The sum of the solutions is $b$, so $b=6+(-2)=4$. The product is $c$, so $c=6\times(-2)=-12$. Then $b+c=4-12=-8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b=6+(-2)=4, c=-12. b+c=-8.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55967b8d-730c-4187-b150-ffded8238f74', 'ALG.10', 2, 'numeric', 'Expressions in the roots', 'The solutions of $x^2-5x+6=0$ are $r$ and $s$. What is $r^2+s^2$?', '[]', '13', '5^2-2*6', '$r^2+s^2=(r+s)^2-2rs=5^2-2\times6=25-12=13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 2,3: 4+9=13. (25-12=13.)","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dbf23ab-1c62-4f6b-aaa7-9055068f977d', 'ALG.10', 2, 'numeric', 'Expressions in the roots', 'The solutions of $x^2-7x+10=0$ are $r$ and $s$. What is $(r-s)^2$?', '[]', '9', '7^2-4*10', '$(r-s)^2=(r+s)^2-4rs=49-40=9$. (The solutions are 2 and 5, and $(2-5)^2=9$.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 2,5: 9. ((7)^2-40=9.)","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
