INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76f863f9-a525-4dc9-a531-648ec7db3189', 'ALG.10', 2, 'choice', 'Expressions in the roots', 'The solutions of $x^2-7x+12=0$ are $r$ and $s$. What is $\frac{1}{r}+\frac{1}{s}$?', '["12/7","7/12","1/12","19/12"]', '7/12', '7/12', '$\frac{1}{r}+\frac{1}{s}=\frac{r+s}{rs}=\frac{7}{12}$. (Check with $r=3$, $s=4$: $\frac13+\frac14=\frac{7}{12}$.)', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)/rs=7/12.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66078e1b-fa4c-4d79-acef-182f2ca1592b', 'ALG.10', 2, 'numeric', 'Word problems leading to a quadratic', 'A garden is 3 meters longer than it is wide, and its area is 54 square meters. What is the distance around the garden, in meters?', '[]', '30', '2*(6+9)', 'Let the width be $w$. Then $w(w+3)=54$, so $w^2+3w-54=0$, which is $(w+9)(w-6)=0$. The width is 6 and the length is 9. The distance around is $2(6+9)=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w(w+3)=54, w=6, length 9. Perimeter 2(15)=30.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66de1a1a-b55d-4357-9210-f7d13a77746c', 'ALG.10', 2, 'numeric', 'Word problems leading to a quadratic', 'A ball thrown up has height $30t-5t^2$ meters after $t$ seconds. At what time $t>0$ does it come back to the ground?', '[]', '6', NULL, 'The height is 0 when $30t-5t^2=0$, so $5t(6-t)=0$. Then $t=0$ (the throw) or $t=6$. The ball lands after 6 seconds.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5t(6-t)=0, t=6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ddac82e-2a03-4f75-b1ee-72ddeac2f66b', 'ALG.10', 2, 'choice', 'Word problems leading to a quadratic', 'The ages of two children, in years, multiply to 84, and one child is 5 years older than the other. How old is the younger child?', '["7","12","5","14"]', '7', '7', 'Let the younger be $a$. Then $a(a+5)=84$, so $a^2+5a-84=0$, which is $(a+12)(a-7)=0$. So $a=7$ and the older child is 12. ($7\times12=84$.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x+5)=84, (x+12)(x-7)=0, x=7.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c1bc73b-66db-4ac1-844f-22d3b5be0ce1', 'ALG.10', 2, 'numeric', 'Counting and describing solutions', 'What is the only solution of $x^2-12x+36=0$?', '[]', '6', NULL, '$x^2-12x+36=(x-6)(x-6)=0$, so $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-6)^2=0, x=6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72e3e25c-2f97-462c-951a-b25d711233f1', 'ALG.10', 2, 'choice', 'Counting and describing solutions', 'Which equation has $x=5$ as a solution?', '["$x^2+2x-15=0$","$x^2-5x+6=0$","$x^2+5x-10=0$","$x^2-2x-15=0$"]', '$x^2-2x-15=0$', NULL, 'Put $x=5$ in each. For $x^2-2x-15$: $25-10-15=0$. The others give 20, 6 and 40.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-2x-15=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25-10-15=0 for x^2-2x-15. Others: 20, 40, 6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd4dc8cc-d677-420a-8696-67ec3f64dd11', 'ALG.10', 2, 'choice', 'Counting and describing solutions', 'Ana solves $x^2-3x=10$. She writes $x(x-3)=10$ and says "so $x=10$ or $x-3=10$." Why is this wrong?', '["The zero-product rule only works when the product is 0, not 10.","She should have divided both sides by $x$ first.","She cannot write $x^2-3x$ as $x(x-3)$.","She forgot to add 3 to both sides."]', 'The zero-product rule only works when the product is 0, not 10.', NULL, 'If a product is 0, one factor must be 0. A product equal to 10 can come from many pairs of factors (2 and 5, 1 and 10, and so on). Correct method: $x^2-3x-10=0$, so $(x-5)(x+2)=0$.', 'checked', '{"lint":[],"solve":{"answer":"The zero-product rule only works when the product is 0, not 10.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zero-product property requires product 0.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd1b62ce-4992-4ed3-8943-502ea9b50137', 'ALG.10', 3, 'numeric', 'Factor a monic quadratic', 'The expression $x^2+bx+12$ can be written as $(x+m)(x+n)$, where $b$, $m$ and $n$ are integers (they may be negative). How many different values can $b$ take?', '[]', '6', NULL, 'We need $mn=12$, and $b=m+n$. The pairs are $(1,12)$, $(2,6)$, $(3,4)$ with sums 13, 8, 7, and the same pairs made negative with sums $-13$, $-8$, $-7$. That gives 6 different values of $b$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"mn=12, b=m+n. Pairs (1,12),(2,6),(3,4) give 13,8,7; negatives give -13,-8,-7. 6 values.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('892367ae-a237-4dc4-9fc0-29fdac7d4817', 'ALG.10', 3, 'numeric', 'Factor a monic quadratic', 'The expression $x^2+bx-24$ can be written as $(x+m)(x+n)$ for integers $m$ and $n$. What is the greatest possible value of $b$?', '[]', '23', NULL, 'We need $mn=-24$ and $b=m+n$. The pairs are $(24,-1)$, $(12,-2)$, $(8,-3)$, $(6,-4)$ (and the same pairs swapped in sign). Their sums are 23, 10, 5, 2, and the negatives of those. The greatest is 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"mn=-24, b=m+n. Largest sum: 24 and -1 gives 23.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca759cee-28e4-4359-8039-383a5aed9176', 'ALG.10', 3, 'choice', 'Factor a monic quadratic', 'For which value of $k$ can $x^2-kx+36$ be written as $(x-a)(x-b)$, where $a$ and $b$ are two different positive whole numbers?', '["13","12","9","36"]', '13', '4+9', 'We need $ab=36$ with $a\ne b$, and $k=a+b$. The possible pairs are $(1,36)$, $(2,18)$, $(3,12)$ and $(4,9)$, giving $k=37, 20, 15, 13$. Of the choices, only 13 appears. (The choice 12 would need $a=b=6$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ab=36, a,b distinct positive, k=a+b: 37,20,15,13 (6,6 excluded, so 12 not allowed). 13 is the only option.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1bd3b40-ffc4-4d43-9062-043af4f0bbcd', 'ALG.10', 3, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'Which product is equal to $6x^2-x-12$?', '["$(3x-4)(2x+3)$","$(3x+4)(2x-3)$","$(6x+4)(x-3)$","$(3x+4)(2x+3)$"]', '$(3x+4)(2x-3)$', NULL, 'Try $(3x+4)(2x-3)=6x^2-9x+8x-12=6x^2-x-12$. The choice with the signs swapped has middle term $+x$, and the others have the wrong middle term too.', 'checked', '{"lint":[],"solve":{"answer":"$(3x+4)(2x-3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+4)(2x-3)=6x^2-9x+8x-12=6x^2-x-12. (3x-4)(2x+3)=6x^2+x-12.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f3f38b6-85f4-4e08-9515-9c6f9bf2d836', 'ALG.10', 3, 'numeric', 'Factor a quadratic with a leading coefficient or common factor', '$6x^2+17x+5$ can be written as the product of two binomials with positive whole-number coefficients. What is the sum of the two constant terms of those binomials?', '[]', '6', NULL, 'The constants multiply to 5, so they are 1 and 5. Try $(2x+5)(3x+1)=6x^2+2x+15x+5=6x^2+17x+5$. The constants are 5 and 1, and their sum is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+1)(2x+5)=6x^2+15x+2x+5=6x^2+17x+5. Other splits give 11x,31x,13x. Constants 1+5=6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c3e9727-151e-45b6-9a70-0d71cf63e340', 'ALG.10', 3, 'choice', 'Factor a quadratic with a leading coefficient or common factor', 'A rectangle has area $6x^2+11x+3$ and width $3x+1$. What is its length?', '["$2x+1$","$3x+3$","$2x+3$","$2x+2$"]', '$2x+3$', NULL, 'Width times length is the area, so we need a length with $(3x+1)\times\text{length}=6x^2+11x+3$. Try $2x+3$: $(3x+1)(2x+3)=6x^2+9x+2x+3=6x^2+11x+3$. The length is $2x+3$.', 'checked', '{"lint":[],"solve":{"answer":"$2x+3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+1)(2x+3)=6x^2+9x+2x+3=6x^2+11x+3. Length 2x+3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('145b0c79-9ef4-4dd3-9073-6d4c3fa707cd', 'ALG.10', 3, 'choice', 'Solve a factored equation (zero-product rule)', 'The equation $(4x-3)(2x+5)=0$ has two solutions. What is their sum?', '["7/4","13/4","-7/4","-13/4"]', '-7/4', '3/4-5/2', '$4x-3=0$ gives $x=\frac{3}{4}$, and $2x+5=0$ gives $x=-\frac{5}{2}$. The sum is $\frac{3}{4}-\frac{10}{4}=-\frac{7}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"-7/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=3/4 or -5/2. Sum 3/4-10/4=-7/4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a66ff665-a391-4fca-b0ba-8ce86c4258be', 'ALG.10', 3, 'choice', 'Solve a factored equation (zero-product rule)', 'Which equation has exactly the solutions $x=\frac{2}{3}$ and $x=-4$?', '["$(3x+2)(x-4)=0$","$(3x-2)(x+4)=0$","$(2x-3)(x+4)=0$","$(3x-2)(x-4)=0$"]', '$(3x-2)(x+4)=0$', NULL, '$3x-2=0$ gives $x=\frac{2}{3}$ and $x+4=0$ gives $x=-4$. So $(3x-2)(x+4)=0$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(3x-2)(x+4)=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-2=0 gives 2/3, x+4=0 gives -4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6815608c-a359-4fe7-9956-e5f898e14253', 'ALG.10', 3, 'numeric', 'Solve a factored equation (zero-product rule)', 'Here $k$ is a positive number. The equation $(x-k)(x+2k)=0$ has $x=5$ as one of its solutions. What is its other solution?', '[]', '-10', '-2*5', 'The solutions are $x=k$ and $x=-2k$. Since $k$ is positive, $-2k$ is negative, so the solution 5 must be $k$. The other solution is $-2k=-10$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solutions k and -2k. k=5 (positive); -2k=5 would make k negative. Other solution -10.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f1a713-99cf-425a-8b6b-3df0b71f554c', 'ALG.10', 3, 'numeric', 'Solve a quadratic equation by factoring', 'Find the positive solution of $x^2-x-182=0$.', '[]', '14', NULL, 'We need two numbers that multiply to $-182$ and add to $-1$. Since $13\times14=182$, they are 13 and $-14$. So $(x+13)(x-14)=0$ and the positive solution is 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14*13=182, so (x-14)(x+13)=0. Positive 14.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06a000c7-08c4-4225-b698-25b56a738998', 'ALG.10', 3, 'choice', 'Solve a quadratic equation by factoring', 'Which number is a solution of $x^2+27x+176=0$?', '["-11","11","16","-27"]', '-11', '-11', 'We need two numbers that multiply to 176 and add to 27. Since $11\times16=176$ and $11+16=27$, we get $(x+11)(x+16)=0$. The solutions are $-11$ and $-16$, and only $-11$ is among the choices.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11*16=176, 11+16=27: (x+11)(x+16)=0, x=-11 or -16. Option -11.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('911164de-3af9-40ca-9be7-e3e22d2907fa', 'ALG.10', 3, 'numeric', 'Solve a quadratic equation by factoring', 'The equation $x^2-6x-16=0$ has a positive solution $p$. What is the value of $3p+1$?', '[]', '25', '3*8+1', '$x^2-6x-16=(x-8)(x+2)=0$, so $p=8$. Then $3p+1=3\times8+1=25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-8)(x+2)=0, p=8, 3p+1=25.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9bf2b41-2468-4944-a482-6d33d6b652f1', 'ALG.10', 3, 'choice', 'Rearrange to zero, then factor', 'Find the positive solution of $(x+3)^2=4x+24$.', '["3","-5","5","-3"]', '3', NULL, 'Multiply out: $x^2+6x+9=4x+24$, so $x^2+2x-15=0$. This is $(x+5)(x-3)=0$, giving $x=-5$ or $x=3$. The positive solution is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+6x+9=4x+24, x^2+2x-15=0, (x+5)(x-3)=0. Positive 3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dde2bdd4-2d8c-437c-9d45-7b73129f3b4c', 'ALG.10', 3, 'choice', 'Rearrange to zero, then factor', 'Which gives all the solutions of $x(x-2)=3x+24$?', '["$x=-8$ or $x=3$","$x=-8$ or $x=-3$","$x=0$ or $x=-13$","$x=8$ or $x=-3$"]', '$x=8$ or $x=-3$', NULL, 'Multiply out and collect: $x^2-2x=3x+24$, so $x^2-5x-24=0$. This factors as $(x-8)(x+3)=0$. So $x=8$ or $x=-3$.', 'checked', '{"lint":[],"solve":{"answer":"$x=8$ or $x=-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-2x=3x+24, x^2-5x-24=0, (x-8)(x+3)=0: 8 or -3.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7223fe66-10d8-496d-ab7d-ac90c3f9bbde', 'ALG.10', 3, 'numeric', 'Rearrange to zero, then factor', 'The equation $(2x+1)(x+3)=x^2+2x+27$ has one negative solution. What is it?', '[]', '-8', NULL, 'The left side is $2x^2+7x+3$. Subtract the right side: $x^2+5x-24=0$. This is $(x+8)(x-3)=0$, so $x=-8$ or $x=3$. The negative solution is $-8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2+7x+3=x^2+2x+27, x^2+5x-24=0, (x+8)(x-3)=0. Negative -8.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb9e57ef-8463-40b5-b21d-f1b33ee9c3ca', 'ALG.10', 3, 'numeric', 'Equations with a common factor of x', 'Solve $x^2-3x=4x$. What is the sum of the squares of the solutions?', '[]', '49', NULL, 'Move terms: $x^2-7x=0$, so $x(x-7)=0$ and $x=0$ or $x=7$. The squares are 0 and 49, with sum 49.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-7x=0: 0 or 7. 0+49=49.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdac2ee2-8859-4e3a-a99e-1336a6fe8f72', 'ALG.10', 3, 'numeric', 'Equations with a common factor of x', 'The equation $(x-2)(x+3)=(x-2)(2x-1)$ has two solutions. What is their sum?', '[]', '6', NULL, 'Move everything to one side and take out the common factor $x-2$: $(x-2)[(x+3)-(2x-1)]=0$, so $(x-2)(4-x)=0$. Then $x=2$ or $x=4$. The sum is 6. (Dividing both sides by $x-2$ would lose $x=2$.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)[(x+3)-(2x-1)]=0, (x-2)(4-x)=0: 2 or 4. Sum 6.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd368922-3c79-4660-bc9b-5d08dfda91ad', 'ALG.10', 3, 'numeric', 'Equations with a common factor of x', 'The equation $x^2+8x=3x^2$ has two solutions. What is the positive one?', '[]', '4', NULL, 'Subtract $x^2+8x$ from the right side: $0=2x^2-8x=2x(x-4)$. So $x=0$ or $x=4$. The positive solution is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2-8x=0, 2x(x-4)=0: 0 or 4. Positive 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f57d93c2-b4dc-4d81-a747-932eea9a1b7a', 'ALG.10', 3, 'numeric', 'Sum and product of the roots', 'The solutions of $x^2+(k-3)x+10=0$ add up to 8. What is $k$?', '[]', '-5', '3-8', 'The sum of the solutions is $-(k-3)=8$, so $k-3=-8$ and $k=-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum=-(k-3)=8, k=-5. Equation x^2-8x+10=0 has real solutions (disc 24).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dc452fe-3c34-4a81-9733-6ef77f97b307', 'ALG.10', 3, 'numeric', 'Sum and product of the roots', 'The two solutions of $x^2-12x+k=0$ differ by 4. What is $k$?', '[]', '32', '4*8', 'Call them $r$ and $r+4$. Their sum is $2r+4=12$, so $r=4$. The solutions are 4 and 8, and $k=4\times8=32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=12, r-s=4: 8 and 4. k=32.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8bed200-e1db-4762-972b-97b179cc3bf6', 'ALG.10', 3, 'choice', 'Sum and product of the roots', 'The equation $(x+1)(x+2)=(2x-1)(x-3)$ has two solutions that are not whole numbers. What is their sum?', '["-10","1","5","10"]', '10', NULL, 'Multiply out: $x^2+3x+2=2x^2-7x+3$. Collect: $0=x^2-10x+1$. The solutions of $x^2-10x+1=0$ add up to 10, even though we cannot find them by simple factoring.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+3x+2=2x^2-7x+3, so x^2-10x+1=0. Sum 10 (roots 5+-sqrt24, not whole).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cf54c3f-4c65-4b79-8669-38cecf2abe26', 'ALG.10', 3, 'numeric', 'Build a quadratic from its roots', 'The two solutions of $x^2-7x+k=0$ are positive, and one of them is $\frac{5}{2}$ times the other. What is $k$?', '[]', '10', '2*5', 'Call them $r$ and $\frac{5}{2}r$. Their sum is $\frac{7}{2}r=7$, so $r=2$ and the other is 5. Then $k=2\times5=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+2.5r=7, r=2, other 5. k=10.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80794410-e632-4fc5-8458-c84f95f38f85', 'ALG.10', 3, 'choice', 'Build a quadratic from its roots', 'The solutions of $x^2-5x+6=0$ are each increased by 3. Which equation has the new numbers as its solutions?', '["$x^2-5x+30=0$","$x^2-11x+6=0$","$x^2+11x+30=0$","$x^2-11x+30=0$"]', '$x^2-11x+30=0$', NULL, 'The old solutions are 2 and 3, so the new ones are 5 and 6. Their sum is 11 and their product is 30, so the equation is $x^2-11x+30=0$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-11x+30=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 2,3 become 5,6: x^2-11x+30=0.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ec8004b-9cc1-4633-ba60-af2fcd163b38', 'ALG.10', 3, 'choice', 'Build a quadratic from its roots', 'The equation $x^2+bx+40=0$ has two positive solutions, and one is 3 more than the other. What is $b$?', '["13","-13","3","-8"]', '-13', '-(5+8)', 'Call the solutions $r$ and $r+3$. Then $r(r+3)=40$, so $r^2+3r-40=0$, which is $(r+8)(r-5)=0$. Since $r$ is positive, $r=5$ and the solutions are 5 and 8. Then $b=-(5+8)=-13$.', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r(r+3)=40, r=5, roots 5 and 8, sum 13=-b, b=-13.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e7bb82-349c-4382-bbda-df0a2e68b148', 'ALG.10', 3, 'choice', 'Expressions in the roots', 'The solutions of $x^2-5x+4=0$ are $r$ and $s$. Find $r^3+s^3$.', '["125","185","5","65"]', '65', '5^3-3*4*5', '$r^3+s^3=(r+s)^3-3rs(r+s)=125-3\times4\times5=125-60=65$. (Check: $1^3+4^3=65$.)', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 1 and 4: 1+64=65.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6a0fc26-1fe7-41d5-8195-5f9481baf809', 'ALG.10', 3, 'numeric', 'Expressions in the roots', 'The solutions of $x^2-6x+k=0$ are $r$ and $s$, and $r^2+s^2=20$. What is $k$?', '[]', '8', '(36-20)/2', '$r^2+s^2=(r+s)^2-2rs=36-2k=20$, so $2k=16$ and $k=8$. (The solutions are 2 and 4.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36-2k=20, k=8 (roots 2,4).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
