INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6499b87f-063b-48b0-9572-b8a47972d3cd', 'ALG.10', 3, 'choice', 'Expressions in the roots', 'The solutions of $x^2+bx+c=0$ are $r$ and $s$. Which expression equals $r^2+s^2$?', '["$b^2+2c$","$b^2-c$","$b^2-2c$","$-b-2c$"]', '$b^2-2c$', NULL, 'We know $r+s=-b$ and $rs=c$. Then $r^2+s^2=(r+s)^2-2rs=b^2-2c$.', 'checked', '{"lint":[],"solve":{"answer":"$b^2-2c$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=-b, rs=c. (r+s)^2-2rs=b^2-2c.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c492186-3a56-426b-9b8b-37b3385db7fa', 'ALG.10', 3, 'numeric', 'Word problems leading to a quadratic', 'A sheet of paper is 12 cm long and 10 cm wide. A strip of the same width $x$ cm is cut from each of the four edges. The paper that is left has area 80 square centimeters. What is $x$?', '[]', '1', NULL, 'The paper left is $(12-2x)$ by $(10-2x)$. So $(12-2x)(10-2x)=80$, which gives $4x^2-44x+120=80$, so $x^2-11x+10=0$ and $(x-1)(x-10)=0$. We need $10-2x>0$, so $x=10$ is impossible. Then $x=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12-2x)(10-2x)=80, 4x^2-44x+40=0, x^2-11x+10=0, x=1 or 10. x=10 impossible (negative sides). x=1.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('663b9082-e1f8-48a3-a57b-93d46da1a56d', 'ALG.10', 3, 'choice', 'Word problems leading to a quadratic', 'The squares of two consecutive positive whole numbers add up to 145. What is the larger of the two numbers?', '["8","9","72","10"]', '9', NULL, 'Let the numbers be $n$ and $n+1$. Then $n^2+(n+1)^2=145$, so $2n^2+2n-144=0$, so $n^2+n-72=0$ and $(n+9)(n-8)=0$. So $n=8$, and the larger is 9. (Check: $64+81=145$.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^2+(n+1)^2=145, n^2+n-72=0, n=8. Larger 9.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad7bcca6-6b2f-4a94-8809-842965170af8', 'ALG.10', 3, 'choice', 'Word problems leading to a quadratic', 'In a right triangle the two shorter sides differ in length by 7 units and the longest side is 13 units. What is the area of the triangle, in square units?', '["60","30","65","35"]', '30', '5*12/2', 'Let the legs be $x$ and $x+7$. Then $x^2+(x+7)^2=169$, so $2x^2+14x-120=0$, so $x^2+7x-60=0$ and $(x+12)(x-5)=0$. The legs are 5 and 12, and the area is $\frac12\times5\times12=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2+(a+7)^2=169, a^2+7a-60=0, a=5, sides 5,12. Area 30.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('026c6e74-4909-4489-b0b4-dc76e6cded97', 'ALG.10', 3, 'numeric', 'Counting and describing solutions', 'How many whole numbers $c$ from 1 to 20 make $x^2-9x+c=0$ have two whole-number solutions?', '[]', '4', NULL, 'We need two whole numbers adding to 9 and multiplying to $c$. The pairs are $(1,8)$, $(2,7)$, $(3,6)$, $(4,5)$ with products 8, 14, 18, 20; the pair $(0,9)$ gives $c=0$, which is outside the range. So 4 values of $c$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=9, rs=c, whole numbers: (1,8)8, (2,7)14, (3,6)18, (4,5)20; (0,9) gives c=0, excluded. 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8c08b91-9aa6-4c9f-b085-d54e33d979e2', 'ALG.10', 3, 'numeric', 'Counting and describing solutions', 'The equation $x^2-kx+16=0$ has exactly one solution, and $k$ is positive. What is $k$?', '[]', '8', '2*4', 'One solution means $x^2-kx+16=(x-r)(x-r)$. Then $r^2=16$ and $r=4$ (positive since $k=2r>0$). So $k=2\times4=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double root: (x-4)^2=x^2-8x+16. k=8.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4afcfbb-653a-48eb-a27c-f4e2cb7de1e8', 'ALG.10', 3, 'choice', 'Counting and describing solutions', 'The equation $x^2-6x+c=0$ has two different positive whole-number solutions. Which could $c$ be?', '["9","8","10","12"]', '8', '8', 'The solutions add to 6, so they are 1 and 5 or 2 and 4 (3 and 3 are not different). Then $c=5$ or $c=8$. Of the choices, only 8 works.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=6 distinct positive: (1,5) c=5, (2,4) c=8. Option 8 (9 is a double root).","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19b4606a-96c0-4865-926f-9ab36ec81b10', 'ALG.11', 1, 'choice', 'Factor a difference of squares', 'Which product is equal to $x^2-49$?', '["$(x-7)(x+7)$","$(x-7)^2$","$(x+7)^2$","$(x-49)(x+1)$"]', '$(x-7)(x+7)$', NULL, 'A difference of squares factors as $a^2-b^2=(a-b)(a+b)$. Here $x^2-49=x^2-7^2=(x-7)(x+7)$. The middle terms cancel: $+7x-7x=0$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-7)(x+7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference of squares: x^2-7^2=(x-7)(x+7).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
