VALUES ('ef44175b-d89e-41a7-b3ef-e2b71aee6c39', 'ALG.11', 1, 'numeric', 'Factor a difference of squares', '$x^2-81=(x-9)(x+k)$. What number is $k$?', '[]', '9', NULL, '$x^2-81=x^2-9^2=(x-9)(x+9)$, so $k=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-81=(x-9)(x+9). k=9.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
