INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eee8cf65-3d29-4302-af9e-7570bea3b025', 'ALG.11', 2, 'choice', 'Factor a sum or difference of cubes', 'Which product is equal to $8x^3-1$?', '["$(2x-1)(4x^2-2x+1)$","$(2x+1)(4x^2-2x+1)$","$(2x-1)(4x^2+2x+1)$","$(2x-1)(2x^2+2x+1)$"]', '$(2x-1)(4x^2+2x+1)$', NULL, '$8x^3-1=(2x)^3-1^3=(2x-1)((2x)^2+2x\times1+1^2)=(2x-1)(4x^2+2x+1)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2x-1)(4x^2+2x+1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x)^3-1: (2x-1)(4x^2+2x+1).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
