VALUES ('e79c2bf5-ad32-4ea5-9f41-358faf48687c', 'ALG.11', 2, 'choice', 'Use sum and difference of cubes', 'Which product is equal to $8a^3-27b^3$?', '["$(2a-3b)(4a^2+6ab+9b^2)$","$(2a-3b)(4a^2-6ab+9b^2)$","$(2a+3b)(4a^2-6ab+9b^2)$","$(2a-3b)(4a^2+12ab+9b^2)$"]', '$(2a-3b)(4a^2+6ab+9b^2)$', NULL, '$8a^3-27b^3=(2a)^3-(3b)^3=(2a-3b)(4a^2+6ab+9b^2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2a-3b)(4a^2+6ab+9b^2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2a)^3-(3b)^3=(2a-3b)(4a^2+6ab+9b^2).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
