VALUES ('f85f23b8-cf64-4e7f-a85e-b7bc48ce8d23', 'ALG.11', 2, 'numeric', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'Positive whole numbers $x$ and $y$ satisfy $xy+x+y=23$, and $x=2$. What is $y$?', '[]', '7', '24/3-1', 'Add 1 to both sides: $(x+1)(y+1)=24$. With $x=2$: $3(y+1)=24$, so $y+1=8$ and $y=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)(y+1)=24, 3(y+1)=24, y=7. Check 14+2+7=23.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
