INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5db55d6a-5b69-477c-bd7e-e78aaa45e941', 'ALG.11', 2, 'choice', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'Which pair of positive whole numbers satisfies $xy+x+y=34$?', '["$x=5$ and $y=6$","$x=3$ and $y=10$","$x=2$ and $y=17$","$x=4$ and $y=6$"]', '$x=4$ and $y=6$', NULL, 'Add 1: $(x+1)(y+1)=35=5\times7$, so $x=4$ and $y=6$. Check: $24+4+6=34$.', 'checked', '{"lint":[],"solve":{"answer":"$x=4$ and $y=6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)(y+1)=35=5*7, x=4,y=6: 24+4+6=34. Others give 53, 43, 41.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
