VALUES ('6e3f54ed-c3c8-4eeb-ad7d-c60392ba1be9', 'ALG.11', 2, 'numeric', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'Use $xy-x-y+1=(x-1)(y-1)$ to find $xy-x-y+1$ when $x=11$ and $y=7$.', '[]', '60', '10*6', '$(11-1)(7-1)=10\times6=60$. (Check: $77-11-7+1=60$.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*6=60.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
