VALUES ('efd8ca1d-0306-4770-922a-7d6f464fee94', 'ALG.11', 2, 'choice', 'Factor by grouping', 'Which product is equal to $ab-3a+4b-12$?', '["$(a-4)(b+3)$","$(a+3)(b-4)$","$(a-3)(b+4)$","$(a+4)(b-3)$"]', '$(a+4)(b-3)$', NULL, 'Group: $a(b-3)+4(b-3)=(a+4)(b-3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(a+4)(b-3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a(b-3)+4(b-3)=(a+4)(b-3).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
