VALUES ('39136f50-0c63-47b9-8c2e-764de7f5aac2', 'ALG.11', 2, 'numeric', 'Factor by grouping', '$x^3+2x^2+3x+6=(x+2)(x^2+k)$. What is $k$?', '[]', '3', NULL, 'Group: $x^2(x+2)+3(x+2)=(x+2)(x^2+3)$. So $k=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2(x+2)+3(x+2)=(x+2)(x^2+3). k=3.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
