VALUES ('a073ef12-263a-4667-8849-c45d129c58c2', 'ALG.11', 2, 'numeric', 'Factor by grouping', 'Use grouping to find $xy+2x+3y+6$ when $x=4$ and $y=7$.', '[]', '63', '7*9', '$xy+2x+3y+6=x(y+2)+3(y+2)=(x+3)(y+2)$. With $x=4$ and $y=7$: $7\times9=63$.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)(y+2)=7*9=63. Check 28+8+21+6=63.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
