VALUES ('85312ba7-19eb-44fb-b0e7-c57ac438ecbc', 'ALG.11', 2, 'numeric', 'Factor completely (more than one step)', 'Find $\dfrac{x^4-1}{x^2+1}$ when $x=5$.', '[]', '24', '25-1', '$x^4-1=(x^2-1)(x^2+1)$, so the fraction equals $x^2-1=25-1=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2-1)(x^2+1)/(x^2+1)=x^2-1=24.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
