INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e33cfa2-1efc-4cd0-9534-dc4907ce977d', 'ALG.11', 2, 'choice', 'Factor completely (more than one step)', 'Which expression is equal to $x^2y-y^3$?', '["$y(x-y)^2$","$x(x-y)(x+y)$","$(x-y)(x+y)$","$y(x-y)(x+y)$"]', '$y(x-y)(x+y)$', NULL, 'Take out the common factor $y$: $x^2y-y^3=y(x^2-y^2)=y(x-y)(x+y)$.', 'checked', '{"lint":[],"solve":{"answer":"$y(x-y)(x+y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y(x^2-y^2)=y(x-y)(x+y).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
