INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b5817e-7254-4b6c-b08c-1becdb10eeaa', 'ALG.11', 2, 'numeric', 'Factor completely (more than one step)', 'What is the largest prime factor of $5^4-3^4$?', '[]', '17', NULL, '$5^4-3^4=(5^2-3^2)(5^2+3^2)=16\times34=544=2^5\times17$. The largest prime factor is 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(25-9)(25+9)=16*34=544=2^5*17. 17.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
