INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90bb99e3-e6fa-49d2-aed4-e18b90b655f8', 'ALG.11', 2, 'numeric', 'Solve equations using special factorizations', 'Find the positive solution of $9x^2-25=0$.', '[]', '5/3', '5/3', '$9x^2-25=(3x-5)(3x+5)=0$, so $x=\frac53$ or $x=-\frac53$.', 'checked', '{"lint":[],"solve":{"answer":"5/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x-5)(3x+5)=0, x=5/3.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
