INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3b13d1f-05c9-4789-a20d-c520426b13ff', 'ALG.11', 2, 'choice', 'Solve equations using special factorizations', 'Solve $x^4=16$ where $x$ is a real number. Which gives all the solutions?', '["$x=2$","$x=4$ or $x=-4$","$x=2$ or $x=-2$","$x=2$ or $x=4$"]', '$x=2$ or $x=-2$', NULL, '$x^4-16=(x^2-4)(x^2+4)=(x-2)(x+2)(x^2+4)$. The factor $x^2+4$ is never 0 for a real $x$. So $x=2$ or $x=-2$.', 'checked', '{"lint":[],"solve":{"answer":"$x=2$ or $x=-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2-4)(x^2+4)=0; real: x=2 or -2.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93d1b650-2035-4257-850a-d03c957816e8', 'ALG.11', 2, 'numeric', 'Solve equations using special factorizations', 'The equation $x^2-6x+9=25$ has two solutions. What is their sum?', '[]', '6', '8-2', 'The left side is $(x-3)^2$. So $(x-3)^2=25$, which gives $x-3=5$ or $x-3=-5$, so $x=8$ or $x=-2$. The sum is $8+(-2)=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2=25, x=8 or -2. Sum 6.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be073ef8-543c-4e23-923d-ac73aab17eef', 'ALG.11', 2, 'numeric', 'Use the identities with given sums, differences and products', 'Two numbers satisfy $a+b=7$ and $ab=10$. What is $a^2+b^2$?', '[]', '29', '49-20', '$a^2+b^2=(a+b)^2-2ab=49-20=29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49-20=29.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af0ce85b-2767-4eaf-923c-841364469cc6', 'ALG.11', 2, 'numeric', 'Use the identities with given sums, differences and products', 'Two numbers satisfy $x-y=3$ and $x^2+y^2=29$. What is $xy$?', '[]', '10', '(29-9)/2', '$(x-y)^2=x^2-2xy+y^2$, so $9=29-2xy$ and $xy=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-y)^2=x^2+y^2-2xy: 9=29-2xy, xy=10.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
