INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b149f9e9-d18b-426c-b4a7-a324cbda0234', 'ALG.11', 2, 'choice', 'Use the identities with given sums, differences and products', 'A number $x$ satisfies $x+\dfrac1x=4$. What is $x^2+\dfrac{1}{x^2}$?', '["16","14","18","8"]', '14', '16-2', 'Square both sides: $x^2+2+\frac{1}{x^2}=16$, so $x^2+\frac1{x^2}=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1/x)^2-2=16-2=14.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9093328-8119-4127-94e8-d0b26af73304', 'ALG.11', 3, 'numeric', 'Factor a difference of squares', 'For how many positive whole numbers $n$ is $n^2-1$ a prime number?', '[]', '1', NULL, '$n^2-1=(n-1)(n+1)$. For $n=1$ this is 0, not prime. For $n\ge3$ both factors are bigger than 1, so the number is not prime. For $n=2$ it is $1\times3=3$, which is prime. So only 1 value of $n$ works.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^2-1=(n-1)(n+1). Prime needs n-1=1, n=2, giving 3. n=1 gives 0. One value.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f7bdf55-83a5-4c3c-bde4-86707a67fae1', 'ALG.11', 3, 'numeric', 'Factor a difference of squares', 'How many pairs of positive whole numbers $(x,y)$ satisfy $x^2-y^2=15$?', '[]', '2', NULL, '$(x-y)(x+y)=15$, and $x+y>x-y>0$. The factor pairs of 15 are $1\times15$ and $3\times5$. These give $x-y=1,\ x+y=15$, so $x=8,\ y=7$; and $x-y=3,\ x+y=5$, so $x=4,\ y=1$. That is 2 pairs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-y)(x+y)=15 with x+y>x-y>0: (1,15) gives (8,7); (3,5) gives (4,1). 2 pairs.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1353b891-0eaf-4a37-b8be-d509ee07865c', 'ALG.11', 3, 'choice', 'Factor a difference of squares', 'Which product is equal to $4x^2y^2-81$?', '["$(2xy-9)(2xy+9)$","$(2xy-9)^2$","$(4xy-9)(xy+9)$","$(2xy+9)^2$"]', '$(2xy-9)(2xy+9)$', NULL, 'Treat $2xy$ as one quantity: $4x^2y^2=(2xy)^2$ and $81=9^2$. So $4x^2y^2-81=(2xy-9)(2xy+9)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2xy-9)(2xy+9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2xy)^2-9^2=(2xy-9)(2xy+9).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
