INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25777b2d-e81a-48b9-bb6a-1975fedff914', 'ALG.11', 3, 'choice', 'Use a difference of squares to calculate', 'Find the value of $1^2-2^2+3^2-4^2+5^2-6^2$.', '["21","-3","-42","-21"]', '-21', '-3-7-11', 'Pair them: $1^2-2^2=(1-2)(1+2)=-3$, $3^2-4^2=-7$, $5^2-6^2=-11$. The total is $-3-7-11=-21$.', 'checked', '{"lint":[],"solve":{"answer":"-21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1-2)(1+2)+(3-4)(3+4)+(5-6)(5+6)=-3-7-11=-21.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fe0c5d2-62c5-492b-9616-37b5ebd715b4', 'ALG.11', 3, 'numeric', 'Use a difference of squares to calculate', 'Find the value of $100^2-99^2+98^2-97^2+\cdots+2^2-1^2$, where the signs alternate and the numbers go down from 100 to 1.', '[]', '5050', '100*101/2', 'Pair them: each pair is $n^2-(n-1)^2=(n-(n-1))(n+(n-1))=n+(n-1)$. So the pairs give $100+99$, $98+97$, and so on down to $2+1$. Together these are all the numbers from 1 to 100, whose sum is $\frac{100\times101}{2}=5050$.', 'checked', '{"lint":[],"solve":{"answer":"5050","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each pair (n+1)^2-n^2=(n+1)+n, so total = 100+99+...+1 = 5050.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ee30f06-da70-48f1-9780-0e8555d0a9ad', 'ALG.11', 3, 'choice', 'Use a difference of squares to calculate', 'Which of these numbers is a factor of $87^2-83^2$?', '["19","23","29","17"]', '17', '17', '$87^2-83^2=(87-83)(87+83)=4\times170=680=2^3\times5\times17$. Of the choices, only 17 divides it.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(87-83)(87+83)=4*170=680=2^3*5*17. 17 divides; 23,29,19 do not.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be725b00-2d8c-4cc3-8070-2410b6d8dab6', 'ALG.11', 3, 'numeric', 'Recognize and factor a perfect square trinomial', 'For how many whole numbers $k$ (positive, zero or negative) is $x^2+kx+36$ the square of a binomial $(x+m)^2$ with $m$ a whole number?', '[]', '2', NULL, '$(x+m)^2=x^2+2mx+m^2$. We need $m^2=36$, so $m=6$ or $m=-6$. Then $k=2m=12$ or $-12$. There are 2 values.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+m)^2=x^2+2mx+m^2, m^2=36, m=6 or -6, k=12 or -12. 2 values.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca3a241-92aa-4dae-99f7-d2dba3e57b57', 'ALG.11', 3, 'choice', 'Recognize and factor a perfect square trinomial', 'Exactly one of these is NOT the square of a binomial. Which one?', '["$16x^2+20x+25$","$4x^2-12x+9$","$9x^2+24x+16$","$x^2+14x+49$"]', '$16x^2+20x+25$', NULL, '$4x^2-12x+9=(2x-3)^2$, $9x^2+24x+16=(3x+4)^2$ and $x^2+14x+49=(x+7)^2$. For $16x^2+20x+25$ we would need $(4x+5)^2$, whose middle term is $40x$, not $20x$.', 'checked', '{"lint":[],"solve":{"answer":"$16x^2+20x+25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x-3)^2, (3x+4)^2, (x+7)^2 match. (4x+5)^2=16x^2+40x+25, not 20x. So 16x^2+20x+25.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82091525-0393-4b1d-a447-6f9c319cfb1e', 'ALG.11', 3, 'numeric', 'Recognize and factor a perfect square trinomial', '$2x^2+20x+50=a(x+b)^2$. What is $a+b$?', '[]', '7', '2+5', 'Take out 2: $2(x^2+10x+25)=2(x+5)^2$. So $a=2$ and $b=5$, and $a+b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x^2+10x+25)=2(x+5)^2. a=2, b=5, a+b=7.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47820e99-b793-49c4-9e40-4dba24d212a2', 'ALG.11', 3, 'choice', 'Use a perfect square to calculate', 'Find the value of $1001^2-2\times1001+1$.', '["$1{,}002{,}001$","$998{,}001$","$1{,}000{,}001$","$1{,}000{,}000$"]', '$1{,}000{,}000$', NULL, 'This is $a^2-2a+1=(a-1)^2$ with $a=1001$. So it equals $1000^2=1000000$.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}000{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1001-1)^2=1000^2=1000000.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
