INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('250606a4-01af-4ee9-adcf-de47c39c6f00', 'ALG.11', 3, 'numeric', 'Use a perfect square to calculate', 'Find the value of $2026^2-2\times2026\times2025+2025^2$.', '[]', '1', '(2026-2025)^2', 'This is $a^2-2ab+b^2=(a-b)^2$ with $a=2026$ and $b=2025$. So it equals $1^2=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2026-2025)^2=1.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a82543f-5d02-41d2-adc6-3529a8e29f14', 'ALG.11', 3, 'numeric', 'Use a perfect square to calculate', 'When $99999^2$ is written out as an ordinary whole number, how many of its digits are 9?', '[]', '4', NULL, '$99999=100000-1$, so $99999^2=100000^2-2\times100000+1=10000000000-200000+1=9999800001$. Its digits are 9, 9, 9, 9, 8, 0, 0, 0, 0, 1, so four of them are 9.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10^5-1)^2=10^10-2*10^5+1=9999800001. Four 9s.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f864ddd-449c-4911-ad95-67e59c0e7226', 'ALG.11', 3, 'choice', 'Factor a sum or difference of cubes', 'Which product is equal to $27x^3+8y^3$?', '["$(3x+2y)(9x^2-6xy+4y^2)$","$(3x+2y)(9x^2+6xy+4y^2)$","$(3x-2y)(9x^2+6xy+4y^2)$","$(3x+2y)(9x^2-12xy+4y^2)$"]', '$(3x+2y)(9x^2-6xy+4y^2)$', NULL, '$27x^3+8y^3=(3x)^3+(2y)^3=(3x+2y)\big((3x)^2-(3x)(2y)+(2y)^2\big)=(3x+2y)(9x^2-6xy+4y^2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3x+2y)(9x^2-6xy+4y^2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x)^3+(2y)^3=(3x+2y)(9x^2-6xy+4y^2).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('569e833b-ec65-47b5-b7bc-361b4945963a', 'ALG.11', 3, 'numeric', 'Factor a sum or difference of cubes', 'Two numbers satisfy $x-y=3$ and $xy=10$. What is $x^3-y^3$?', '[]', '117', '3*(9+30)', '$x^3-y^3=(x-y)(x^2+xy+y^2)$ and $x^2+xy+y^2=(x-y)^2+3xy=9+30=39$. So $x^3-y^3=3\times39=117$. (Check: $x=5$, $y=2$ gives $125-8=117$.)', 'checked', '{"lint":[],"solve":{"answer":"117","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+y^2=(x-y)^2+2xy=29. x^3-y^3=(x-y)(x^2+xy+y^2)=3*39=117.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('829ef777-08ec-43df-9784-c01dcafc4ff4', 'ALG.11', 3, 'choice', 'Factor a sum or difference of cubes', 'What is $\dfrac{2^9-1}{2^3-1}$?', '["73","63","72","81"]', '73', '(2^9-1)/(2^3-1)', '$2^9-1=(2^3)^3-1^3=(2^3-1)\big((2^3)^2+2^3+1\big)$. So the fraction equals $2^6+2^3+1=64+8+1=73$.', 'checked', '{"lint":[],"solve":{"answer":"73","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^9-1=(2^3)^3-1=(2^3-1)(64+8+1), so 73. (511/7=73.)","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('758ecb27-317a-4b9e-b43b-8dd1a72c77d0', 'ALG.11', 3, 'choice', 'Use sum and difference of cubes', 'A number $x$ satisfies $x+\dfrac{1}{x}=3$. What is $x^3+\dfrac{1}{x^3}$?', '["27","18","24","21"]', '18', '3*(9-2-1)', '$x^3+\frac{1}{x^3}=\left(x+\frac1x\right)\left(x^2-1+\frac{1}{x^2}\right)$. Also $x^2+\frac1{x^2}=3^2-2=7$. So the value is $3\times(7-1)=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1/x)^3=x^3+1/x^3+3(x+1/x): 27=S+9, S=18.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('110331a1-f135-4de1-bf79-5820ccb51bfd', 'ALG.11', 3, 'numeric', 'Use sum and difference of cubes', 'Two numbers satisfy $a+b=5$ and $ab=6$. What is $a^3+b^3$?', '[]', '35', '5*(25-18)', '$a^3+b^3=(a+b)(a^2-ab+b^2)=(a+b)\big((a+b)^2-3ab\big)=5\times(25-18)=35$. (The numbers are 2 and 3: $8+27=35$.)', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a+b)^3-3ab(a+b)=125-90=35.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2d499b7-5031-4630-8c50-75b54e0f761e', 'ALG.11', 3, 'numeric', 'Use sum and difference of cubes', 'Find $\dfrac{13^3+7^3}{13+7}$.', '[]', '127', '169-91+49', '$\dfrac{a^3+b^3}{a+b}=a^2-ab+b^2$. With $a=13$ and $b=7$ this is $169-91+49=127$.', 'checked', '{"lint":[],"solve":{"answer":"127","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13^2-13*7+7^2=169-91+49=127. (2540/20=127.)","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9269287-56e2-4c8c-a531-2c611a751c58', 'ALG.11', 3, 'numeric', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'How many ordered pairs of positive whole numbers $(x,y)$ satisfy $xy+x+y=15$?', '[]', '3', NULL, 'Add 1 to both sides: $(x+1)(y+1)=16$. Both factors are at least 2. The possibilities are $2\times8$, $4\times4$, $8\times2$, giving $(1,7)$, $(3,3)$, $(7,1)$. That is 3 pairs.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)(y+1)=16 with both factors >=2: (2,8),(4,4),(8,2). 3.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('117fa0c2-5130-480b-8187-d718ee561ed5', 'ALG.11', 3, 'numeric', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'How many ordered pairs of positive whole numbers $(x,y)$ satisfy $xy+2x+3y=26$?', '[]', '2', NULL, 'Add 6 to both sides: $xy+2x+3y+6=32$, which is $(x+3)(y+2)=32$. Here $x+3\ge4$ and $y+2\ge3$. The factor pairs of 32 that work are $4\times8$ and $8\times4$, giving $(x,y)=(1,6)$ and $(5,2)$. Check: $6+2+18=26$ and $10+10+6=26$. So there are 2 pairs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)(y+2)=32, x+3>=4, y+2>=3: (4,8) gives (1,6); (8,4) gives (5,2). 2.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2958f881-3448-436c-9a33-49e71d96e8bc', 'ALG.11', 3, 'choice', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'Positive whole numbers $a$ and $b$ satisfy $ab-5a-5b=0$. Which could be the value of $a+b$?', '["36","25","30","40"]', '36', '6+30', 'Add 25 to both sides: $ab-5a-5b+25=25$, so $(a-5)(b-5)=25$. Because $a$ and $b$ are positive, the factors $a-5$ and $b-5$ are $1\times25$, $5\times5$ or $25\times1$. That gives $(6,30)$, $(10,10)$, $(30,6)$ and sums of 36 or 20. Only 36 is among the choices.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a-5)(b-5)=25. Positive a,b: (1,25),(25,1) give a+b=36; (5,5) gives 20; negative pairs make a or b <=0. Option 36.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c932f6a-b106-443c-822a-f9b7ef439caa', 'ALG.11', 3, 'choice', 'Factor by grouping', 'Which product is equal to $x^3-x^2-4x+4$?', '["$(x-1)(x-2)(x+2)$","$(x-1)(x+2)^2$","$(x+1)(x-2)(x+2)$","$(x-1)(x-2)^2$"]', '$(x-1)(x-2)(x+2)$', NULL, 'Group: $x^2(x-1)-4(x-1)=(x-1)(x^2-4)=(x-1)(x-2)(x+2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-1)(x-2)(x+2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2(x-1)-4(x-1)=(x-1)(x^2-4)=(x-1)(x-2)(x+2).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('540d18ba-8f8e-4450-b92f-d7d7b3903186', 'ALG.11', 3, 'numeric', 'Factor by grouping', 'Numbers $x$ and $y$ satisfy $xy+5x+2y+10=77$ and $x+2=7$. What is $y+5$?', '[]', '11', '77/7', '$xy+5x+2y+10=x(y+5)+2(y+5)=(x+2)(y+5)$. So $7(y+5)=77$ and $y+5=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+2)(y+5)=77, 7(y+5)=77, y+5=11.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
