INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d0d3d45-a3fd-43a0-9890-265e0c337113', 'ALG.11', 3, 'numeric', 'Factor by grouping', 'What is the greatest solution of $x^3+x^2-9x-9=0$?', '[]', '3', NULL, 'Group: $x^2(x+1)-9(x+1)=(x+1)(x^2-9)=(x+1)(x-3)(x+3)=0$. The solutions are $-1$, 3 and $-3$, and the greatest is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2(x+1)-9(x+1)=(x+1)(x-3)(x+3). Greatest 3.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4becaf27-1e4b-4e05-94a9-16e3fcfe66ae', 'ALG.11', 3, 'choice', 'Factor completely (more than one step)', 'What is the largest prime factor of $3^6-1$?', '["7","3","13","2"]', '13', NULL, '$3^6-1=(3^3-1)(3^3+1)=26\times28=728=2^3\times7\times13$. The largest prime factor is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(27-1)(27+1)=26*28=728=2^3*7*13. 13.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f47554e-1aaf-44bf-85b9-bd605cea27b6', 'ALG.11', 3, 'numeric', 'Factor completely (more than one step)', 'What is the largest whole number that divides $n^3-n$ for every whole number $n$?', '[]', '6', NULL, '$n^3-n=n(n-1)(n+1)$ is a product of three consecutive whole numbers, so it is a multiple of 6 (one of them is a multiple of 3, and at least one is even). For $n=2$ it equals 6, so nothing larger than 6 works for all $n$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^3-n=(n-1)n(n+1), product of 3 consecutive, divisible by 6; n=2 gives 6. Answer 6.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
