INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96bd0b26-6b8d-4bc7-8a8d-7a0f7a874ebd', 'ALG.11', 3, 'choice', 'Factor completely (more than one step)', 'Which of these is a factor of $x^4-5x^2+4$?', '["$x+2$","$x-4$","$x+4$","$x^2+1$"]', '$x+2$', NULL, '$x^4-5x^2+4=(x^2-1)(x^2-4)=(x-1)(x+1)(x-2)(x+2)$. So $x+2$ is a factor.', 'checked', '{"lint":[],"solve":{"answer":"$x+2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2-1)(x^2-4)=(x-1)(x+1)(x-2)(x+2). x+2.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bba9a43-b311-4914-9f4b-9038d3d2e9bf', 'ALG.11', 3, 'choice', 'Solve equations using special factorizations', 'The equation $(x+2)^2-49=0$ has two solutions. What is their product?', '["45","-49","-35","-45"]', '-45', '5*(-9)', '$(x+2)^2-49=(x+2-7)(x+2+7)=(x-5)(x+9)=0$. The solutions are 5 and $-9$, with product $-45$.', 'checked', '{"lint":[],"solve":{"answer":"-45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+2=7 or -7: x=5 or -9. Product -45.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca082356-2d79-4fe2-8469-89cb528a8582', 'ALG.11', 3, 'numeric', 'Solve equations using special factorizations', 'The equation $x^2-10x+25=4x^2$ has two solutions. What is the positive one?', '[]', '5/3', '5/3', 'The left side is $(x-5)^2$ and the right side is $(2x)^2$. So $(x-5)^2-(2x)^2=0$, which is $(x-5-2x)(x-5+2x)=(-x-5)(3x-5)=0$. The solutions are $x=-5$ and $x=\frac53$. The positive one is $\frac53$.', 'checked', '{"lint":[],"solve":{"answer":"5/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-5)^2=(2x)^2: x-5=2x gives -5; x-5=-2x gives 5/3. Positive 5/3.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fdc402c-efff-4e19-bacc-fe3269e238c5', 'ALG.11', 3, 'choice', 'Solve equations using special factorizations', 'Find the sum of the squares of all the real solutions of $x^4-13x^2+36=0$.', '["13","52","5","26"]', '26', '4+4+9+9', '$x^4-13x^2+36=(x^2-4)(x^2-9)=0$, so $x=2,-2,3,-3$. The squares are 4, 4, 9, 9 and their sum is 26.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2-4)(x^2-9)=0, x=+-2,+-3. Squares 4+4+9+9=26.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc7756b5-73ac-49f0-b431-36cdbf3de2fe', 'ALG.11', 3, 'choice', 'Use the identities with given sums, differences and products', 'Two numbers satisfy $x+y=6$ and $x^2+y^2=20$. What is $x^3+y^3$?', '["72","120","216","48"]', '72', '6*(20-8)', 'First, $36=x^2+2xy+y^2=20+2xy$, so $xy=8$. Then $x^3+y^3=(x+y)\big(x^2-xy+y^2\big)=6\times(20-8)=72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2xy=36-20, xy=8. x^3+y^3=216-3*8*6=72 (x,y=2,4).","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77d5c7d9-bf8c-4c38-9825-3f700683b652', 'ALG.11', 3, 'numeric', 'Use the identities with given sums, differences and products', 'Positive numbers $x$ and $y$ satisfy $x^2-y^2=63$ and $x+y=9$. What is $x^2+y^2$?', '[]', '65', '64+1', '$x-y=63\div9=7$. With $x+y=9$ this gives $x=8$ and $y=1$. Then $x^2+y^2=64+1=65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-y=63/9=7, x=8, y=1. 64+1=65.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('faa1f9bc-2d51-47a4-906e-6e45e53f45a3', 'ALG.11', 3, 'choice', 'Use the identities with given sums, differences and products', 'Suppose $x$ is not zero and $x-\dfrac1x=2$. Find the value of $x^2+\dfrac{1}{x^2}$.', '["2","4","6","8"]', '6', '4+2', 'Square both sides: $x^2-2+\frac{1}{x^2}=4$, so $x^2+\frac1{x^2}=4+2=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1/x)^2+2=4+2=6.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
