VALUES ('41c19926-8af8-48c0-89eb-680994fe7f17', 'ALG.12', 1, 'choice', 'Reciprocals of complex numbers', 'Find the reciprocal of $1+i$ and write it as $a+bi$.', '["$1-i$","$\\frac{1}{2}-\\frac{1}{2}i$","$-1-i$","$\\frac{1}{2}+\\frac{1}{2}i$"]', '$\frac{1}{2}-\frac{1}{2}i$', NULL, '$\frac{1}{1+i}=\frac{1-i}{(1+i)(1-i)}=\frac{1-i}{2}=\frac12-\frac12i$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}-\\frac{1}{2}i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1-i)/2=1/2-1/2 i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
