VALUES ('56445ee2-a08e-4973-89b9-65295f1e598a', 'ALG.12', 2, 'choice', 'Dividing complex numbers', 'Write $\dfrac{5+5i}{1+2i}$ in the form $a+bi$.', '["$-1+3i$","$1+i$","$3-i$","$3+i$"]', '$3-i$', NULL, 'Multiply top and bottom by the conjugate $1-2i$. Bottom: $(1+2i)(1-2i)=5$. Top: $(5+5i)(1-2i)=5-10i+5i-10i^2=15-5i$. So the quotient is $\frac{15-5i}{5}=3-i$.', 'checked', '{"lint":[],"solve":{"answer":"$3-i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5+5i)(1-2i)/5=(5-10i+5i+10)/5=(15-5i)/5=3-i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86495847-fa5f-4380-a20b-8dca9bfd2e05', 'ALG.12', 2, 'choice', 'Dividing complex numbers', 'Simplify $\dfrac{10}{1+3i}$.', '["$1+3i$","$10-30i$","$1$","$1-3i$"]', '$1-3i$', NULL, 'Multiply top and bottom by $1-3i$. Bottom: $1+9=10$. Top: $10(1-3i)$. So the result is $1-3i$.', 'checked', '{"lint":[],"solve":{"answer":"$1-3i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10(1-3i)/(1+9)=1-3i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd85841c-4e82-40dd-9338-f09ff66a42b8', 'ALG.12', 2, 'numeric', 'Dividing complex numbers', 'What is the real part of $\dfrac{7+i}{1+i}$?', '[]', '4', '(7+1)/2', 'Multiply top and bottom by $1-i$. Bottom: $2$. Top: $(7+i)(1-i)=7-7i+i-i^2=8-6i$. The quotient is $4-3i$, so the real part is $4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(7+i)(1-i)/2=(7-7i+i+1)/2=4-3i; real part 4.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
