INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b4c2d2e-757f-46ae-88f9-30217c758744', 'ALG.12', 2, 'choice', 'Squares and powers of complex numbers', 'Find $(3-2i)^2$.', '["$13$","$9+4i$","$13-12i$","$5-12i$"]', '$5-12i$', NULL, '$(3-2i)^2=9-12i+4i^2=9-12i-4=5-12i$.', 'checked', '{"lint":[],"solve":{"answer":"$5-12i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-12i+4i^2=5-12i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
