INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('908e665e-4f7b-4042-bc79-071d3f870c7c', 'ALG.12', 2, 'numeric', 'Squares and powers of complex numbers', 'Evaluate $(1+i)^4$.', '[]', '-4', '-4', '$(1+i)^2=1+2i-1=2i$. Then $(1+i)^4=(2i)^2=4i^2=-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+i)^2=2i; (2i)^2=-4.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
