INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92d749f8-c550-4b0e-999f-5fb1aa88fc72', 'ALG.12', 2, 'choice', 'Squares and powers of complex numbers', 'Square the number $-1+2i$.', '["$-3-4i$","$5$","$-3+4i$","$1+4i$"]', '$-3-4i$', NULL, '$(-1+2i)^2=1-4i+4i^2=1-4i-4=-3-4i$.', 'checked', '{"lint":[],"solve":{"answer":"$-3-4i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-4i+4i^2=-3-4i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
