INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb52aba2-30e4-41f2-a1c7-21c6034aeb9a', 'ALG.12', 2, 'numeric', 'Real and imaginary parts, equal complex numbers', 'Real numbers $x$ and $y$ satisfy $(x+2)+(y-1)i=6+4i$. Find $x+y$.', '[]', '9', '4+5', 'Equal complex numbers have equal real parts and equal imaginary parts. $x+2=6$ gives $x=4$, and $y-1=4$ gives $y=5$. So $x+y=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+2=6, y-1=4: x=4, y=5, x+y=9.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b888d197-a77d-4404-9955-774f411d1cc7', 'ALG.12', 2, 'numeric', 'Real and imaginary parts, equal complex numbers', 'Real numbers $a$ and $b$ satisfy $(2a-3)+(b+1)i=5-2i$. Find the product $ab$.', '[]', '-12', '4*(-3)', 'Real parts: $2a-3=5$, so $a=4$. Imaginary parts: $b+1=-2$, so $b=-3$. Then $ab=-12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a-3=5 so a=4; b+1=-2 so b=-3; ab=-12.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
