INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f5e7d1d-b193-43c2-8f8c-f26e07f41efd', 'ALG.12', 2, 'choice', 'Real and imaginary parts, equal complex numbers', 'Which pair of complex numbers are equal to each other?', '["$\\frac{6+4i}{2}$ and $3+2i$","$3+2i$ and $2+3i$","$3+2i$ and $3-2i$","$3+2i$ and $5i$"]', '$\frac{6+4i}{2}$ and $3+2i$', NULL, '$\frac{6+4i}{2}=3+2i$, so the two are equal. In the other pairs the real parts or the imaginary parts differ.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6+4i}{2}$ and $3+2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6+4i)/2=3+2i; the other pairs differ.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
