INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('659a971a-d453-499c-8191-70ff43deeaa6', 'ALG.12', 2, 'choice', 'Solving equations for a complex number', 'Solve $(1+i)z=4+2i$.', '["$3-i$","$3+i$","$5+3i$","$2+6i$"]', '$3-i$', NULL, 'Divide by $1+i$ by multiplying top and bottom by $1-i$: $z=\frac{(4+2i)(1-i)}{2}=\frac{4-4i+2i+2}{2}=\frac{6-2i}{2}=3-i$.', 'checked', '{"lint":[],"solve":{"answer":"$3-i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=(4+2i)(1-i)/2=(4-4i+2i+2)/2=3-i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddd5afa3-080d-474e-9470-f646adac0218', 'ALG.12', 2, 'choice', 'Solving equations for a complex number', 'Find $z$ if $(2-i)z=5$.', '["$2-i$","$2+i$","$5-2i$","$3+i$"]', '$2+i$', NULL, '$z=\frac{5}{2-i}=\frac{5(2+i)}{(2-i)(2+i)}=\frac{5(2+i)}{5}=2+i$.', 'checked', '{"lint":[],"solve":{"answer":"$2+i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=5(2+i)/5=2+i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8962377-d1c2-4335-a9e7-339d130e94c2', 'ALG.12', 2, 'numeric', 'Solving equations for a complex number', 'The number $z$ satisfies $iz=4-3i$. What is the imaginary part of $z$?', '[]', '-4', '-4', '$z=\frac{4-3i}{i}$. Multiply top and bottom by $-i$ (since $\frac1i=-i$): $(4-3i)(-i)=-4i+3i^2=-3-4i$. The imaginary part is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=(4-3i)/i=(4-3i)(-i)=-4i+3i^2=-3-4i; imaginary part -4.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0ec2e22-8af1-4ce1-8a1f-cb099ad5e896', 'ALG.12', 2, 'choice', 'Reciprocals of complex numbers', 'Write the reciprocal of $3+4i$ in the form $a+bi$.', '["$3-4i$","$\\frac{3}{5}-\\frac{4}{5}i$","$\\frac{3}{25}-\\frac{4}{25}i$","$-\\frac{3}{25}+\\frac{4}{25}i$"]', '$\frac{3}{25}-\frac{4}{25}i$', NULL, '$\frac{1}{3+4i}=\frac{3-4i}{(3+4i)(3-4i)}=\frac{3-4i}{25}=\frac{3}{25}-\frac{4}{25}i$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{25}-\\frac{4}{25}i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3-4i)/25.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61158b7f-b648-4356-b27c-6ef62ae56f7d', 'ALG.12', 2, 'choice', 'Reciprocals of complex numbers', 'What is $\dfrac{1}{2-i}$?', '["$2+i$","$\\frac{2}{3}+\\frac{1}{3}i$","$-\\frac{2}{5}+\\frac{1}{5}i$","$\\frac{2}{5}+\\frac{1}{5}i$"]', '$\frac{2}{5}+\frac{1}{5}i$', NULL, 'Multiply top and bottom by $2+i$: $\frac{2+i}{(2-i)(2+i)}=\frac{2+i}{5}=\frac25+\frac15i$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}+\\frac{1}{5}i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+i)/5=2/5+1/5 i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('427dc557-37a1-4fd8-b2d6-8b2207243fe4', 'ALG.12', 2, 'numeric', 'Reciprocals of complex numbers', 'The reciprocal of $1-i$ is written $a+bi$. Find $a+b$.', '[]', '1', '1/2+1/2', '$\frac{1}{1-i}=\frac{1+i}{2}=\frac12+\frac12i$. So $a=b=\frac12$ and $a+b=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+i)/2: a=b=1/2, a+b=1.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e32bbf55-cf87-4591-92ac-87bbf9b6888b', 'ALG.12', 2, 'choice', 'Multi-step complex number expressions', 'Evaluate $(1+i)(1-i)+(2+i)^2$ and give the answer as $a+bi$.', '["$4+4i$","$3+4i$","$5$","$5+4i$"]', '$5+4i$', NULL, '$(1+i)(1-i)=2$ and $(2+i)^2=4+4i-1=3+4i$. The sum is $5+4i$.', 'checked', '{"lint":[],"solve":{"answer":"$5+4i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+(3+4i)=5+4i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbb90514-df8e-4d23-8058-b71470af4303', 'ALG.12', 2, 'numeric', 'Multi-step complex number expressions', 'Evaluate $\dfrac{(3+i)(3-i)}{(1+i)(1-i)}$.', '[]', '5', '10/2', 'Each product is the sum of two squares: $(3+i)(3-i)=9+1=10$ and $(1+i)(1-i)=1+1=2$. So the result is $\frac{10}{2}=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/2=5.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e938e51-716a-4a19-87b5-675951ff1ecb', 'ALG.12', 2, 'numeric', 'Multi-step complex number expressions', 'Two fractions, $\dfrac{2+i}{1+i}$ and $\dfrac{2-i}{1-i}$, are added. What is their sum?', '[]', '3', '3', 'The two fractions are conjugates of each other, so their sum is twice the real part of one of them. $\frac{2+i}{1+i}=\frac{(2+i)(1-i)}{2}=\frac{3-i}{2}$. The other is $\frac{3+i}{2}$. The sum is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+i)(1-i)/2=(3-i)/2; the second is its conjugate (3+i)/2; sum 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d98c39c-0335-4631-b09f-8e2646672072', 'ALG.12', 3, 'choice', 'Powers of i', 'Simplify the sum $i+i^2+i^3+\cdots+i^{10}$.', '["$0$","$-1-i$","$1+i$","$-1+i$"]', '$-1+i$', NULL, 'Each group of four consecutive powers adds to $i-1-i+1=0$. The first eight terms give $0$. What is left is $i^9+i^{10}=i+(-1)=-1+i$.', 'checked', '{"lint":[],"solve":{"answer":"$-1+i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each block of four consecutive powers sums to 0, so i..i^8 gives 0; i^9+i^10=i-1.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c551f92c-0fa4-4303-9e01-3425fedfddd3', 'ALG.12', 3, 'numeric', 'Powers of i', 'For how many positive integers $n$ less than $40$ is $i^n=-i$?', '[]', '10', '10', '$i^n=-i$ exactly when $n$ leaves remainder 3 when divided by 4: $n=3,7,11,\ldots,39$. That is $(39-3)/4+1=10$ values, and $39$ is less than $40$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"i^n=-i iff n≡3 mod 4: n=3,7,...,39, that is (39-3)/4+1=10 values.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef94c18a-bb21-4cc9-93bd-812dcf00b94f', 'ALG.12', 3, 'choice', 'Powers of i', 'Simplify the product $i\cdot i^2\cdot i^3\cdot i^4\cdot i^5\cdot i^6$.', '["$i$","$-i$","$1$","$-1$"]', '$i$', NULL, 'Add the exponents: $1+2+3+4+5+6=21$. So the product is $i^{21}$. Since $21=4\cdot5+1$, $i^{21}=i$.', 'checked', '{"lint":[],"solve":{"answer":"$i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exponents sum 1+2+...+6=21; i^21=i^1=i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81f887cf-22d6-4ceb-bdef-3b9e7c910f52', 'ALG.12', 3, 'numeric', 'Square roots of negative numbers', 'Find $\sqrt{-18}\cdot\sqrt{-8}$.', '[]', '-12', '-12', '$\sqrt{-18}=3i\sqrt2$ and $\sqrt{-8}=2i\sqrt2$. Multiply: $3\cdot2\cdot i^2\cdot(\sqrt2)^2=6\cdot(-1)\cdot2=-12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(-18)=3i sqrt2, sqrt(-8)=2i sqrt2; product 6*2*i^2=-12.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
