VALUES ('b3480e2a-65e9-4bc3-a198-de2ecd6b3a7a', 'ALG.12', 3, 'choice', 'Square roots of negative numbers', 'Simplify $\sqrt{-4}+\sqrt{-9}+\sqrt{-16}$.', '["$29i$","$9i$","$9$","$\\sqrt{-29}$"]', '$9i$', NULL, '$\sqrt{-4}=2i$, $\sqrt{-9}=3i$ and $\sqrt{-16}=4i$. Their sum is $(2+3+4)i=9i$.', 'checked', '{"lint":[],"solve":{"answer":"$9i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2i+3i+4i=9i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
