INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('820524c5-51b0-40c8-a190-d00446b4e544', 'ALG.12', 3, 'numeric', 'Square roots of negative numbers', 'Lena says $\sqrt{-4}\cdot\sqrt{-25}=\sqrt{100}=10$. Find the correct value of $\sqrt{-4}\cdot\sqrt{-25}$.', '[]', '-10', '-10', 'The rule $\sqrt{a}\sqrt{b}=\sqrt{ab}$ is not safe when both numbers are negative. Write $\sqrt{-4}=2i$ and $\sqrt{-25}=5i$. Then $2i\cdot5i=10i^2=-10$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(-4)=2i, sqrt(-25)=5i; 2i*5i=10i^2=-10.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c974e3-e550-40f4-be9e-8063b88107f9', 'ALG.12', 3, 'numeric', 'Adding and subtracting complex numbers', 'The sum of $a+4i$ and $6-bi$ is $10+i$, where $a$ and $b$ are real numbers. Find $a+b$.', '[]', '7', '4+3', 'Real parts: $a+6=10$, so $a=4$. Imaginary parts: $4-b=1$, so $b=3$. Then $a+b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a+6)+(4-b)i=10+i: a=4, b=3; a+b=7.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
