INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('191516e9-91d7-469e-9a73-697571e69322', 'ALG.12', 3, 'choice', 'Adding and subtracting complex numbers', 'Simplify $(2+3i)-(4-i)-(-1+5i)$.', '["$-3+7i$","$1+i$","$-1-i$","$-1+i$"]', '$-1-i$', NULL, 'Real parts: $2-4-(-1)=-1$. Imaginary parts: $3-(-1)-5=-1$. The result is $-1-i$.', 'checked', '{"lint":[],"solve":{"answer":"$-1-i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real 2-4+1=-1; imag 3+1-5=-1: -1-i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
