INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b5e307b-55fc-4cec-9648-2b032b86a1d2', 'ALG.12', 3, 'numeric', 'Multiplying complex numbers', 'What is the imaginary part of the product $(1+i)(2+i)(3+i)$?', '[]', '10', '10', '$(1+i)(2+i)=2+i+2i+i^2=1+3i$. Then $(1+3i)(3+i)=3+i+9i+3i^2=0+10i$. The imaginary part is $10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+i)(2+i)=1+3i; (1+3i)(3+i)=3+i+9i+3i^2=10i; imaginary part 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62d68f40-ba5d-4feb-99d6-915b218e3919', 'ALG.12', 3, 'choice', 'Multiplying complex numbers', 'Find $(2+i)(2-i)(1+3i)$. A shortcut helps.', '["$3+9i$","$5+3i$","$25+15i$","$5+15i$"]', '$5+15i$', NULL, 'First $(2+i)(2-i)=4-i^2=5$. Then $5(1+3i)=5+15i$.', 'checked', '{"lint":[],"solve":{"answer":"$5+15i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+i)(2-i)=5; 5(1+3i)=5+15i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('209a988b-2879-41ed-a2ce-19b0b7b3ce3e', 'ALG.12', 3, 'numeric', 'Multiplying complex numbers', 'For which real number $a$ is $(a+2i)(3-i)$ a real number?', '[]', '6', '6', '$(a+2i)(3-i)=3a-ai+6i-2i^2=(3a+2)+(6-a)i$. It is real when the imaginary part is zero: $6-a=0$, so $a=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a+2i)(3-i)=(3a+2)+(6-a)i; real when a=6.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5de44d6-9689-49d3-87a3-13fa51c2584b', 'ALG.12', 3, 'numeric', 'Complex conjugates', 'A complex number $z=5+bi$ has positive integer $b$ and satisfies $z\overline{z}=50$. What is $b$?', '[]', '5', '5', '$z\overline{z}=5^2+b^2=25+b^2=50$, so $b^2=25$. Since $b$ is positive, $b=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z zbar=25+b^2=50, b^2=25, b=5.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccab5e37-977e-4c31-8ec8-f8ecb19288f4', 'ALG.12', 3, 'choice', 'Complex conjugates', 'The number $z$ has real part $2$, and $z-\overline{z}=6i$. Which number is $z$?', '["$2+6i$","$2-3i$","$3+2i$","$2+3i$"]', '$2+3i$', NULL, 'If $z=2+bi$ then $z-\overline{z}=2bi$. Setting $2bi=6i$ gives $b=3$, so $z=2+3i$.', 'checked', '{"lint":[],"solve":{"answer":"$2+3i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=2+bi, z-zbar=2bi=6i, b=3: 2+3i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('919c3d35-ec66-40b8-9e27-8debe8947253', 'ALG.12', 3, 'numeric', 'Complex conjugates', 'Let $z=2+i$. Find the value of $z^2\cdot\overline{z^2}$.', '[]', '25', '(2*2+1*1)^2', '$z^2=4+4i+i^2=3+4i$. Then $(3+4i)(3-4i)=9+16=25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z^2=4+4i-1=3+4i; times its conjugate =9+16=25.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae4dd6b5-35c2-4dbf-a850-3e879487790a', 'ALG.12', 3, 'choice', 'Dividing complex numbers', 'Simplify $\dfrac{3+4i}{3-4i}$.', '["$-\\frac{7}{25}+\\frac{24}{25}i$","$1$","$-7+24i$","$\\frac{9}{25}+\\frac{16}{25}i$"]', '$-\frac{7}{25}+\frac{24}{25}i$', NULL, 'Multiply top and bottom by $3+4i$. Bottom: $9+16=25$. Top: $(3+4i)^2=9+24i-16=-7+24i$. So the quotient is $-\frac{7}{25}+\frac{24}{25}i$.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{7}{25}+\\frac{24}{25}i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3+4i)^2/25=(9+24i-16)/25=-7/25+24/25 i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86122162-475c-4b41-a241-0fdc62ad07b5', 'ALG.12', 3, 'numeric', 'Dividing complex numbers', 'For which real number $k$ is $\dfrac{2+ki}{1-i}$ a real number?', '[]', '-2', '-2', 'Multiply top and bottom by $1+i$: $\frac{(2+ki)(1+i)}{2}=\frac{2+2i+ki+ki^2}{2}=\frac{(2-k)+(2+k)i}{2}$. It is real when $2+k=0$, so $k=-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+ki)(1+i)/2=((2-k)+(2+k)i)/2; real when k=-2.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80b9f7d7-78ac-4a4a-8b47-013235aed4cd', 'ALG.12', 3, 'numeric', 'Dividing complex numbers', 'It is known that $\dfrac{1+i}{1-i}=i$. Use this to find $\left(\dfrac{1+i}{1-i}\right)^{10}$.', '[]', '-1', '-1', 'The expression equals $i^{10}$. Since $10=4\cdot2+2$, $i^{10}=i^2=-1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"i^10=i^2=-1.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
