INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffffb569-8145-4d59-b259-1dd6bf97b1dd', 'ALG.12', 3, 'numeric', 'Squares and powers of complex numbers', 'Find the value of $(1+i)^8$.', '[]', '16', '(-4)^2', '$(1+i)^2=2i$ and $(1+i)^4=(2i)^2=-4$. So $(1+i)^8=(-4)^2=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+i)^2=2i; (2i)^4=16.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
