INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a74319e6-bcaf-4143-b924-2a988c4484c9', 'ALG.12', 3, 'choice', 'Squares and powers of complex numbers', 'Compute $(1+i)^3$.', '["$2+2i$","$-2+2i$","$-2-2i$","$1+3i$"]', '$-2+2i$', NULL, '$(1+i)^2=2i$, so $(1+i)^3=2i(1+i)=2i+2i^2=-2+2i$.', 'checked', '{"lint":[],"solve":{"answer":"$-2+2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2i(1+i)=2i-2=-2+2i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
