INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120a237f-03e6-4d50-b251-992f046c1ccd', 'ALG.12', 3, 'choice', 'Squares and powers of complex numbers', 'Compute $(1-i)^6$.', '["$-8$","$-8i$","$8i$","$8$"]', '$8i$', NULL, '$(1-i)^2=-2i$. Then $(1-i)^6=(-2i)^3=-8i^3=-8(-i)=8i$.', 'checked', '{"lint":[],"solve":{"answer":"$8i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1-i)^2=-2i; (-2i)^3=-8i^3=8i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
