INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c1f8727-c7b1-4d46-814a-4618351584b2', 'ALG.12', 3, 'numeric', 'Real and imaginary parts, equal complex numbers', 'Real numbers $x$ and $y$ satisfy $(x+yi)(1+i)=5+i$. What is $x$?', '[]', '3', '3', '$(x+yi)(1+i)=x+xi+yi+yi^2=(x-y)+(x+y)i$. So $x-y=5$ and $x+y=1$. Adding the two equations gives $2x=6$, so $x=3$ (and $y=-2$).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+yi=(5+i)/(1+i)=(5+i)(1-i)/2=(6-4i)/2=3-2i; x=3.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a11304a0-ba45-4a21-8c00-91096e023dd0', 'ALG.12', 3, 'numeric', 'Real and imaginary parts, equal complex numbers', 'Real numbers $x$ and $y$ satisfy $2(x+yi)+(x-yi)=9+4i$. Find the product $xy$.', '[]', '12', '3*4', 'The left side is $3x+yi$. Matching parts: $3x=9$, so $x=3$, and $y=4$. Then $xy=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+yi=9+4i: x=3, y=4, xy=12.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
