INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96886490-3e92-4230-b11e-f1246f999b47', 'ALG.12', 3, 'choice', 'Real and imaginary parts, equal complex numbers', 'For which value of $k$ is $(k-3)+(2k-8)i$ a real number?', '["$3$","$4$","$8$","$\\frac{3}{2}$"]', '$4$', '8/2', 'It is real when the imaginary part is zero: $2k-8=0$, so $k=4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Imaginary part 2k-8=0, k=4.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
