INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('898f0885-5ddb-4851-8e65-545017f56bfb', 'ALG.12', 3, 'choice', 'Solving equations for a complex number', 'Find $z$ if $z+2\overline{z}=6+3i$, where $\overline{z}$ is the conjugate of $z$.', '["$2+3i$","$6+3i$","$2-3i$","$3-2i$"]', '$2-3i$', NULL, 'Let $z=x+yi$. Then $z+2\overline{z}=3x-yi$. Matching $6+3i$: $3x=6$ gives $x=2$, and $-y=3$ gives $y=-3$. So $z=2-3i$.', 'checked', '{"lint":[],"solve":{"answer":"$2-3i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=a+bi: 3a-bi=6+3i, a=2, b=-3: 2-3i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14f0e0df-823d-4b05-9489-f909c1bf834e', 'ALG.12', 3, 'numeric', 'Solving equations for a complex number', 'Write the solution of $z(1+2i)=5i$ as $a+bi$. What is $a+b$?', '[]', '3', '2+1', '$z=\frac{5i}{1+2i}=\frac{5i(1-2i)}{5}=i(1-2i)=i-2i^2=2+i$. So $a=2$, $b=1$ and $a+b=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=5i(1-2i)/5=i+2=2+i; a+b=3.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ad02f2d-11de-4d50-b3ad-7a11482c61df', 'ALG.12', 3, 'choice', 'Solving equations for a complex number', 'Solve $\dfrac{z}{1+i}=2-i$ for $z$.', '["$3-i$","$1+i$","$\\frac{1}{2}-\\frac{3}{2}i$","$3+i$"]', '$3+i$', NULL, 'Multiply both sides by $1+i$: $z=(2-i)(1+i)=2+2i-i-i^2=3+i$.', 'checked', '{"lint":[],"solve":{"answer":"$3+i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=(2-i)(1+i)=2+2i-i+1=3+i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fda903a2-1bd2-4c15-b729-717c7c5abf8b', 'ALG.12', 3, 'numeric', 'Reciprocals of complex numbers', 'What is the total of the four reciprocals $\dfrac1i$, $\dfrac1{i^2}$, $\dfrac1{i^3}$ and $\dfrac1{i^4}$?', '[]', '0', '0', '$\frac1i=-i$, $\frac1{i^2}=-1$, $\frac1{i^3}=i$, $\frac1{i^4}=1$. The sum is $-i-1+i+1=0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-i + (-1) + i + 1 = 0.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
