INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56095106-9047-4d88-904d-a752658a1157', 'ALG.12', 3, 'choice', 'Reciprocals of complex numbers', 'Subtract the reciprocal of $1-i$ from the reciprocal of $1+i$. What is the result?', '["$-i$","$i$","$1$","$2i$"]', '$-i$', NULL, '$\frac{1}{1+i}=\frac{1-i}{2}$ and $\frac{1}{1-i}=\frac{1+i}{2}$. The difference is $\frac{(1-i)-(1+i)}{2}=\frac{-2i}{2}=-i$.', 'checked', '{"lint":[],"solve":{"answer":"$-i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1-i)/2-(1+i)/2=-i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7478008-166a-416a-ad96-ced593f5bdb1', 'ALG.12', 3, 'numeric', 'Reciprocals of complex numbers', 'The reciprocal of $a+bi$ is $\frac{3}{25}-\frac{4}{25}i$, where $a$ and $b$ are real numbers. Find $a+b$.', '[]', '7', '3+4', 'The reciprocal of $3+4i$ is $\frac{3-4i}{25}$, so $a+bi=3+4i$ (the reciprocal of the reciprocal is the original number). Then $a+b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+bi=25/(3-4i)=3+4i; a+b=7.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc8d2bdc-bde2-4047-b1bc-973a64f5ee2b', 'ALG.12', 3, 'choice', 'Multi-step complex number expressions', 'Simplify $(1+i)^2(1-i)^3$.', '["$4-4i$","$4+4i$","$-4+4i$","$4$"]', '$4-4i$', NULL, '$(1+i)^2(1-i)^2=\big((1+i)(1-i)\big)^2=2^2=4$. Multiply by the last factor $(1-i)$: $4(1-i)=4-4i$.', 'checked', '{"lint":[],"solve":{"answer":"$4-4i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+i)^2(1-i)^2=((1+i)(1-i))^2=4; times (1-i): 4-4i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
