INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a45b39d7-20d4-4640-b8cc-ce3f8e398da3', 'ALG.12', 3, 'choice', 'Multi-step complex number expressions', 'Compute $(2+i)^3$.', '["$8+i$","$2+11i$","$2+7i$","$6+11i$"]', '$2+11i$', NULL, '$(2+i)^2=4+4i-1=3+4i$. Then $(3+4i)(2+i)=6+3i+8i+4i^2=2+11i$.', 'checked', '{"lint":[],"solve":{"answer":"$2+11i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+i)^2=3+4i; (3+4i)(2+i)=6+3i+8i-4=2+11i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
