INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5242c3a1-6bc8-4450-8ad9-92eec8e55207', 'ALG.13', 1, 'numeric', 'Completing the square: the missing constant', 'What number must be added to $x^2+6x$ to make a perfect square trinomial?', '[]', '9', '(6/2)^2', 'Take half of the coefficient of $x$, then square it: $\left(\frac62\right)^2=9$. Indeed $x^2+6x+9=(x+3)^2$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6/2)^2=9: x^2+6x+9=(x+3)^2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17dcad64-75d6-425d-ab46-20edce19db75', 'ALG.13', 1, 'numeric', 'Completing the square: the missing constant', 'Find $c$ so that $x^2-10x+c$ is the square of a binomial.', '[]', '25', '(10/2)^2', 'Half of $-10$ is $-5$, and $(-5)^2=25$. So $c=25$, and $x^2-10x+25=(x-5)^2$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-10/2)^2=25: (x-5)^2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c73bd2d8-8e89-4942-8dae-36fb538519a3', 'ALG.13', 1, 'choice', 'Completing the square: the missing constant', 'Which value of $c$ makes $x^2+4x+c$ a perfect square?', '["$4$","$2$","$8$","$16$"]', '$4$', '(4/2)^2', 'Half of $4$ is $2$ and $2^2=4$. So $x^2+4x+4=(x+2)^2$. The value $16$ comes from squaring the coefficient itself instead of half of it.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4/2)^2=4: (x+2)^2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('385782a0-a039-494a-8088-045f392ed749', 'ALG.13', 1, 'numeric', 'Solving by completing the square', 'Solve $(x+3)^2=16$. What is the positive solution?', '[]', '1', '4-3', 'Take square roots: $x+3=\pm4$. So $x=1$ or $x=-7$. The positive one is $1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+3=±4: x=1 or -7; positive 1.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
