INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fef0c957-cd4a-48ae-b1f7-2b7eb1ff4449', 'ALG.13', 1, 'choice', 'Solving by completing the square', 'What are the solutions of $(x-2)^2=9$?', '["$x=1$ or $x=-5$","$x=11$ or $x=-7$","$x=5$ or $x=-1$","$x=3$ or $x=-3$"]', '$x=5$ or $x=-1$', NULL, '$x-2=\pm3$, so $x=2+3=5$ or $x=2-3=-1$.', 'checked', '{"lint":[],"solve":{"answer":"$x=5$ or $x=-1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-2=±3: x=5 or -1.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
