INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29955e66-abec-483c-8d8a-11d0b60c8525', 'ALG.13', 1, 'choice', 'Solving by completing the square', 'Adding $9$ to both sides of $x^2+6x=7$ gives which equation?', '["$(x+3)^2=7$","$(x+6)^2=16$","$(x+3)^2=9$","$(x+3)^2=16$"]', '$(x+3)^2=16$', NULL, 'The left side becomes $x^2+6x+9=(x+3)^2$. The right side becomes $7+9=16$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+3)^2=16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+6x+9=16: (x+3)^2=16.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
