INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6aba958b-fbf3-4da7-9de6-1070e4ac11a2', 'ALG.13', 1, 'choice', 'Rewriting in vertex form', 'Which expression is equal to $x^2+4x+7$?', '["$(x+2)^2+7$","$(x+4)^2-9$","$(x+2)^2+11$","$(x+2)^2+3$"]', '$(x+2)^2+3$', NULL, '$x^2+4x+4=(x+2)^2$, so $x^2+4x+7=(x^2+4x+4)+3=(x+2)^2+3$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+2)^2+3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+2)^2=x^2+4x+4, +3 gives x^2+4x+7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
