INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cea91bf9-26b5-4ccc-a3df-658eb8c46b0b', 'ALG.13', 1, 'numeric', 'Rewriting in vertex form', 'Given $x^2+6x+5=(x+3)^2+k$, find $k$.', '[]', '-4', '5-9', '$(x+3)^2=x^2+6x+9$, so $x^2+6x+5=(x+3)^2+(5-9)=(x+3)^2-4$. Hence $k=-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)^2=x^2+6x+9; 5-9=-4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
