VALUES ('b84b2ab3-e038-425b-a6c6-80ef7ef767b0', 'ALG.13', 1, 'choice', 'Rewriting in vertex form', 'Rewrite $x^2-2x+5$ by completing the square.', '["$(x-1)^2+4$","$(x-1)^2+5$","$(x+1)^2+4$","$(x-2)^2+1$"]', '$(x-1)^2+4$', NULL, '$(x-1)^2=x^2-2x+1$, so $x^2-2x+5=(x-1)^2+4$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-1)^2+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1)^2=x^2-2x+1; +4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
