INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('812af677-a1cc-45c2-a9d8-84492c33f6e2', 'ALG.13', 1, 'numeric', 'Quadratic formula with rational solutions', 'Use the quadratic formula to solve $x^2-5x+6=0$. What is the larger solution?', '[]', '3', '(5+1)/2', '$a=1,\ b=-5,\ c=6$. $b^2-4ac=25-24=1$. So $x=\frac{5\pm1}{2}$, which gives $3$ and $2$. The larger is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(5±√(25-24))/2=(5±1)/2: 3 or 2; larger 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
