INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9649c021-3ad2-43d0-977f-202bb784ff8e', 'ALG.13', 1, 'choice', 'Quadratic formula with irrational solutions', 'Use the quadratic formula to solve $x^2-2x-1=0$.', '["$x=-1\\pm\\sqrt{2}$","$x=2\\pm2\\sqrt{2}$","$x=\\frac{2\\pm\\sqrt{6}}{2}$","$x=1\\pm\\sqrt{2}$"]', '$x=1\pm\sqrt{2}$', NULL, 'Here $a=1,\ b=-2,\ c=-1$, so $b^2-4ac=8$. Then $x=\frac{2\pm\sqrt{8}}{2}$, which simplifies to $x=1\pm\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=1\\pm\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(2±√8)/2=1±√2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
