VALUES ('8ac59399-2ad6-474a-814d-1048c03e3eef', 'ALG.13', 1, 'numeric', 'Sum and product of solutions', 'Find the product of the two solutions of $x^2+3x-10=0$.', '[]', '-10', '-10', 'For $x^2+bx+c=0$ the product of the solutions is $c=-10$. (They are $2$ and $-5$.)', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product = c/a = -10 (roots 2, -5).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
