INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af3ce05e-81fe-43c1-938f-8138d0dfe55e', 'ALG.13', 1, 'choice', 'Sum and product of solutions', 'The equation $x^2+9x+8=0$ has two solutions. Which statement about them is true?', '["Their sum is $-9$ and their product is $8$.","Their sum is $9$ and their product is $8$.","Their sum is $-9$ and their product is $-8$.","Their sum is $8$ and their product is $-9$."]', 'Their sum is $-9$ and their product is $8$.', NULL, 'The sum is $-b=-9$ and the product is $c=8$. (The solutions are $-1$ and $-8$.)', 'checked', '{"lint":[],"solve":{"answer":"Their sum is $-9$ and their product is $8$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum -b/a=-9, product 8 (roots -1, -8).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
