INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c02b785e-e840-44f7-9ee7-12db8c9eb95f', 'ALG.13', 1, 'choice', 'Building an equation from its solutions', 'Which equation has solutions $2$ and $5$?', '["$x^2+7x+10=0$","$x^2-7x+10=0$","$x^2-10x+7=0$","$x^2-3x+10=0$"]', '$x^2-7x+10=0$', NULL, '$(x-2)(x-5)=x^2-7x+10$. In general the equation is $x^2-(\text{sum})x+(\text{product})=0$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-7x+10=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x-5)=x^2-7x+10.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6b14eb1-efb6-49fa-bb94-5bf9e4e29a1a', 'ALG.13', 1, 'choice', 'Building an equation from its solutions', 'Find the equation of the form $x^2+bx+c=0$ whose solutions are $-1$ and $4$.', '["$x^2+3x-4=0$","$x^2-3x+4=0$","$x^2-3x-4=0$","$x^2-4x-1=0$"]', '$x^2-3x-4=0$', NULL, '$(x+1)(x-4)=x^2-3x-4$. Sum $=3$, so $b=-3$; product $=-4$, so $c=-4$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-3x-4=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)(x-4)=x^2-3x-4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
