INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e24f984d-7ccd-44ab-9209-94656e085952', 'ALG.13', 1, 'numeric', 'Expressions in the solutions, complex solutions', 'The solutions of $x^2-5x+2=0$ are $r$ and $s$. What is $r+s+rs$?', '[]', '7', '5+2', '$r+s=5$ and $rs=2$. So $r+s+rs=5+2=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=5, rs=2: 7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
