INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2869903b-d611-4776-bf3d-9012d24e8bba', 'ALG.13', 1, 'numeric', 'Expressions in the solutions, complex solutions', 'If $r$ and $s$ are the solutions of $x^2-8x+5=0$, find $2r+2s$.', '[]', '16', '2*8', '$r+s=8$, so $2r+2s=2(r+s)=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=8: 16.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
