INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('917a7323-f81a-475a-8dbf-8efe51e38a08', 'ALG.13', 1, 'choice', 'Expressions in the solutions, complex solutions', 'Let $r$ and $s$ be the solutions of a quadratic equation. Which expression equals $r^2+s^2$?', '["$(r+s)^2$","$(r+s)^2+2rs$","$(r-s)^2$","$(r+s)^2-2rs$"]', '$(r+s)^2-2rs$', NULL, '$(r+s)^2=r^2+2rs+s^2$, so $r^2+s^2=(r+s)^2-2rs$.', 'checked', '{"lint":[],"solve":{"answer":"$(r+s)^2-2rs$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)^2=r^2+2rs+s^2, so r^2+s^2=(r+s)^2-2rs.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
