INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e55e0aa6-d640-411f-9784-ca6ae7f2de03', 'ALG.13', 2, 'numeric', 'Completing the square: the missing constant', 'What must be added to $x^2+3x$ to complete the square?', '[]', '9/4', '(3/2)^2', 'Half of $3$ is $\frac32$, and $\left(\frac32\right)^2=\frac94$. So $x^2+3x+\frac94=\left(x+\frac32\right)^2$.', 'checked', '{"lint":[],"solve":{"answer":"9/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/2)^2=9/4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
