INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7704aff0-74af-46e6-9f8e-7c32d5d21e82', 'ALG.13', 2, 'numeric', 'Completing the square: the missing constant', 'If $x^2-7x+c=(x-h)^2$ for every $x$, what is $c$?', '[]', '49/4', '(7/2)^2', 'Matching the $x$ terms, $-2h=-7$, so $h=\frac72$. Then $c=h^2=\frac{49}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"49/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2h=7, h=7/2, c=h^2=49/4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
