INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9a6298e-b7e2-425d-b7a1-7fd405f7c97e', 'ALG.13', 2, 'choice', 'Completing the square: the missing constant', 'Which of these is a perfect square trinomial?', '["$x^2-14x+196$","$x^2-14x+49$","$x^2-14x+28$","$x^2-14x+7$"]', '$x^2-14x+49$', NULL, 'A perfect square $(x-h)^2=x^2-2hx+h^2$. With $2h=14$, $h=7$ and $h^2=49$. So $x^2-14x+49=(x-7)^2$. The other constants do not equal $\left(\frac{14}{2}\right)^2$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-14x+49$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(14/2)^2=49: x^2-14x+49=(x-7)^2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd93b530-ae81-4a5b-8fe3-917a65032fb1', 'ALG.13', 2, 'numeric', 'Solving by completing the square', 'Solve $x^2-8x+7=0$ by completing the square. What is the smaller solution?', '[]', '1', '4-3', 'Move the $7$: $x^2-8x=-7$. Add $16$: $(x-4)^2=9$. So $x-4=\pm3$ and $x=1$ or $x=7$. The smaller is $1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-8x+16=9: (x-4)^2=9, x=7 or 1; smaller 1.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1889bac3-3a63-4702-8af3-7bbea609d8f2', 'ALG.13', 2, 'choice', 'Solving by completing the square', 'Complete the square to solve $x^2+4x-1=0$.', '["$x=-2\\pm\\sqrt{5}$","$x=2\\pm\\sqrt{5}$","$x=-2\\pm\\sqrt{3}$","$x=-4\\pm\\sqrt{5}$"]', '$x=-2\pm\sqrt{5}$', NULL, '$x^2+4x=1$. Add $4$ to both sides: $(x+2)^2=5$. So $x+2=\pm\sqrt5$, giving $x=-2\pm\sqrt5$.', 'checked', '{"lint":[],"solve":{"answer":"$x=-2\\pm\\sqrt{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+4x+4=5: (x+2)^2=5, x=-2±√5.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
