INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ca46d91-558a-487d-a9cf-740d24ddd652', 'ALG.13', 2, 'numeric', 'Solving by completing the square', 'By completing the square, solve $x^2+x-12=0$. What is the positive solution?', '[]', '3', '-1/2+7/2', '$x^2+x=12$. Add $\frac14$: $\left(x+\frac12\right)^2=\frac{49}{4}$. So $x+\frac12=\pm\frac72$, giving $x=3$ or $x=-4$. The positive one is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1/2)^2=12+1/4=49/4: x=-1/2±7/2 = 3 or -4; positive 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
