INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('405e6ba3-19ec-49d5-a052-012006b746a8', 'ALG.13', 2, 'choice', 'Rewriting in vertex form', 'Write $x^2-8x+3$ in the form $(x-h)^2+k$.', '["$(x-4)^2+19$","$(x-4)^2-13$","$(x-4)^2+3$","$(x+4)^2-13$"]', '$(x-4)^2-13$', NULL, '$(x-4)^2=x^2-8x+16$. Then $x^2-8x+3=(x-4)^2+3-16=(x-4)^2-13$.', 'checked', '{"lint":[],"solve":{"answer":"$(x-4)^2-13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-4)^2=x^2-8x+16; 3-16=-13.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
