INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3327eaa-a961-4514-955b-2aa2e2b60e97', 'ALG.13', 2, 'numeric', 'Rewriting in vertex form', 'What is the least value of $x^2-6x+14$ for real $x$?', '[]', '5', '14-9', '$x^2-6x+14=(x-3)^2+5$. A square is never negative, so the least value is $5$ (when $x=3$).', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2+5; least value 5 at x=3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
