INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f283c441-f66e-4183-86c9-43bfcc7cb139', 'ALG.13', 2, 'choice', 'Rewriting in vertex form', 'Which expression equals $x^2+5x+1$?', '["$\\left(x+\\frac52\\right)^2+1$","$(x+5)^2-24$","$\\left(x+\\frac52\\right)^2-\\frac{21}{4}$","$\\left(x+\\frac52\\right)^2+\\frac{21}{4}$"]', '$\left(x+\frac52\right)^2-\frac{21}{4}$', NULL, '$\left(x+\frac52\right)^2=x^2+5x+\frac{25}{4}$. So $x^2+5x+1=\left(x+\frac52\right)^2+1-\frac{25}{4}=\left(x+\frac52\right)^2-\frac{21}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\left(x+\\frac52\\right)^2-\\frac{21}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+5/2)^2=x^2+5x+25/4; 1-25/4=-21/4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
