INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ef13ec4-f469-475e-b245-8e10e340bc7f', 'ALG.13', 2, 'numeric', 'Quadratic formula with rational solutions', 'Find the larger solution of $2x^2-7x+3=0$.', '[]', '3', '(7+5)/4', '$a=2,\ b=-7,\ c=3$. $b^2-4ac=49-24=25$. $x=\frac{7\pm5}{4}$ gives $3$ and $\frac12$. The larger is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(7±√(49-24))/4=(7±5)/4: 3 or 1/2; larger 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
