INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2ad65bf-1edf-45a3-9a3c-589dc006e0bf', 'ALG.13', 2, 'numeric', 'Quadratic formula with rational solutions', 'The equation $3x^2+5x-2=0$ has exactly one positive solution. What is it?', '[]', '1/3', '(-5+7)/6', '$a=3,\ b=5,\ c=-2$. $b^2-4ac=25+24=49$. $x=\frac{-5\pm7}{6}$ gives $\frac13$ and $-2$. The positive one is $\frac13$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(-5±√(25+24))/6=(-5±7)/6: 1/3 or -2; positive 1/3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
