INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('886583ef-4ab9-454c-a8c4-a076929ec257', 'ALG.13', 2, 'choice', 'Quadratic formula with rational solutions', 'Use the quadratic formula on $6x^2-x-2=0$. What are the solutions?', '["$x=-\\frac{2}{3}$ or $x=\\frac{1}{2}$","$x=\\frac{2}{3}$ or $x=-\\frac{1}{2}$","$x=\\frac{4}{3}$ or $x=-1$","$x=\\frac{2}{3}$ or $x=\\frac{1}{2}$"]', '$x=\frac{2}{3}$ or $x=-\frac{1}{2}$', NULL, '$a=6,\ b=-1,\ c=-2$. $b^2-4ac=1+48=49$. $x=\frac{1\pm7}{12}$, which gives $\frac{8}{12}=\frac23$ and $\frac{-6}{12}=-\frac12$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{2}{3}$ or $x=-\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(1±√(1+48))/12=(1±7)/12: 2/3 or -1/2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
