INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0667503-7e0d-484d-aa24-680e1741a45c', 'ALG.13', 2, 'choice', 'Quadratic formula with irrational solutions', 'Solve $2x^2+4x-1=0$ with the quadratic formula.', '["$x=\\frac{2\\pm\\sqrt{6}}{2}$","$x=-2\\pm\\sqrt{6}$","$x=\\frac{-2\\pm\\sqrt{6}}{2}$","$x=-4\\pm2\\sqrt{6}$"]', '$x=\frac{-2\pm\sqrt{6}}{2}$', NULL, 'Here $a=2,\ b=4,\ c=-1$, so $b^2-4ac=24$. Then $x=\frac{-4\pm\sqrt{24}}{4}$, which simplifies to $x=\frac{-2\pm\sqrt{6}}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{-2\\pm\\sqrt{6}}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(-4±√(16+8))/4=(-4±2√6)/4=(-2±√6)/2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
