INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da3f65e3-429a-41ea-86c9-590764b41a90', 'ALG.13', 2, 'choice', 'Quadratic formula with irrational solutions', 'The equation $x^2+x-1=0$ has two real solutions. What are they?', '["$x=\\frac{1\\pm\\sqrt{5}}{2}$","$x=-1\\pm\\sqrt{5}$","$x=\\frac{-1\\pm\\sqrt{3}}{2}$","$x=\\frac{-1\\pm\\sqrt{5}}{2}$"]', '$x=\frac{-1\pm\sqrt{5}}{2}$', NULL, 'Here $a=1,\ b=1,\ c=-1$, so $b^2-4ac=5$. Then $x=\frac{-1\pm\sqrt{5}}{2}$, which simplifies to $x=\frac{-1\pm\sqrt{5}}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{-1\\pm\\sqrt{5}}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(-1±√(1+4))/2=(-1±√5)/2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
