INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e7d8bd-a6db-4be6-95ed-6fbb8a3c9317', 'ALG.13', 2, 'numeric', 'Computing the discriminant', 'Compute the discriminant of $3x^2+x+2$.', '[]', '-23', '1-24', '$a=3,\ b=1,\ c=2$. $b^2-4ac=1-24=-23$.', 'checked', '{"lint":[],"solve":{"answer":"-23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-4*3*2=-23.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
