INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42c228fd-48af-483f-a153-3131b9a140a5', 'ALG.13', 2, 'choice', 'Computing the discriminant', 'What is the discriminant of the equation $x^2=5x-3$ once it is written as $ax^2+bx+c=0$?', '["$37$","$13$","$22$","$-13$"]', '$13$', '25-12', 'Rewrite as $x^2-5x+3=0$, so $a=1,\ b=-5,\ c=3$. Then $b^2-4ac=25-12=13$.', 'checked', '{"lint":[],"solve":{"answer":"$13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-5x+3=0: 25-12=13 (same for the negated form).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
