INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87a1e326-466f-424f-a327-a11304ce8801', 'ALG.13', 2, 'choice', 'Discriminant and the number of real solutions', 'How many real solutions does $x^2+2x+5=0$ have?', '["exactly two real solutions","no real solutions","exactly one real solution","infinitely many real solutions"]', 'no real solutions', NULL, '$b^2-4ac=4-20=-16<0$, so there are no real solutions.', 'checked', '{"lint":[],"solve":{"answer":"no real solutions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4-20=-16<0: none.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
