INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec13dfe5-6b2f-4149-8302-1af6aa2462ca', 'ALG.13', 2, 'choice', 'Discriminant and the number of real solutions', 'Without solving it, decide how many real solutions $2x^2-4x+2=0$ has.', '["exactly two real solutions","no real solutions","exactly one real solution","infinitely many real solutions"]', 'exactly one real solution', NULL, '$b^2-4ac=16-16=0$, so there is exactly one real solution (it is $x=1$).', 'checked', '{"lint":[],"solve":{"answer":"exactly one real solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16-16=0: one (x=1).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
