VALUES ('737d7a96-d4f9-4fd1-9b2d-1312561c0a54', 'ALG.13', 2, 'choice', 'Discriminant and the number of real solutions', 'Use the discriminant to tell how many real solutions $x^2-3x-1=0$ has.', '["exactly one real solution","no real solutions","infinitely many real solutions","exactly two real solutions"]', 'exactly two real solutions', NULL, '$b^2-4ac=9+4=13>0$, so there are two different real solutions.', 'checked', '{"lint":[],"solve":{"answer":"exactly two real solutions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9+4=13>0: two.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
