INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca9a354f-83f2-4856-8fc3-24042f62541d', 'ALG.13', 2, 'numeric', 'Finding a coefficient from the discriminant', 'The equation $2x^2-5x+k=0$ has two different real solutions when $k$ is a whole number. What is the largest possible $k$?', '[]', '3', '3', 'The discriminant $25-8k$ must be positive: $k<\frac{25}{8}=3.125$. The largest whole number is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25-8k>0, k<3.125; largest whole k=3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
