INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f89d3f2e-aed6-4abb-a104-d456252f33fa', 'ALG.13', 2, 'numeric', 'Finding a coefficient from the discriminant', 'The equation $x^2+2x+k=0$ has no real solutions. What is the smallest whole number $k$ that can work?', '[]', '2', '2', 'The discriminant $4-4k$ must be negative: $k>1$. The smallest whole number greater than $1$ is $2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4-4k<0 iff k>1; smallest whole number 2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
