INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f9cb3fb-6119-4239-a446-f031a3bb5477', 'ALG.13', 2, 'choice', 'Finding a coefficient from the discriminant', 'For which nonzero value of $k$ does $x^2+kx+k=0$ have exactly one solution?', '["$2$","$-4$","$4$","$8$"]', '$4$', '4', 'The discriminant is $k^2-4k$, and it must be $0$: $k(k-4)=0$. Since $k\neq0$, $k=4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k^2-4k=0, k nonzero: 4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
