INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcee25d3-2940-429f-a464-e3f5ec43a323', 'ALG.13', 2, 'numeric', 'Sum and product of solutions', 'What is the sum of the solutions of $2x^2-6x+1=0$?', '[]', '3', '6/2', 'For $ax^2+bx+c=0$ the sum is $-\frac ba=\frac62=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 6/2 = 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
