INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b256aa8-9ff5-468e-b404-f0c28cd68b5b', 'ALG.13', 2, 'numeric', 'Sum and product of solutions', 'Find the product of the solutions of $3x^2+5x-12=0$.', '[]', '-4', '-12/3', 'For $ax^2+bx+c=0$ the product is $\frac ca=\frac{-12}{3}=-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product = -12/3 = -4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
