INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e20cdc-a89f-44a2-a3b1-bb29c6ddd1c0', 'ALG.13', 2, 'numeric', 'Sum and product of solutions', 'One solution of $x^2+bx+18=0$ is $2$. Find $b$.', '[]', '-11', '-(2+18/2)', 'The product of the solutions is $18$, so the other is $\frac{18}{2}=9$. The sum is $2+9=11=-b$, so $b=-11$.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+2b+18=0, b=-11 (other root 9).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
