INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2459d732-f9ae-4733-a3cd-d81c316fb571', 'ALG.13', 2, 'choice', 'Building an equation from its solutions', 'Which equation with whole-number coefficients has solutions $\frac12$ and $3$?', '["$2x^2+7x+3=0$","$2x^2-7x-3=0$","$x^2-7x+3=0$","$2x^2-7x+3=0$"]', '$2x^2-7x+3=0$', NULL, '$(2x-1)(x-3)=2x^2-6x-x+3=2x^2-7x+3$. Check: $x=\frac12$ makes $2x-1=0$, and $x=3$ makes $x-3=0$.', 'checked', '{"lint":[],"solve":{"answer":"$2x^2-7x+3=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x-1)(x-3)=2x^2-7x+3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dac4abf1-b394-402b-be75-21c73994b3a8', 'ALG.13', 2, 'choice', 'Building an equation from its solutions', 'A quadratic equation has solutions $3+\sqrt2$ and $3-\sqrt2$. Which equation is it?', '["$x^2-6x+7=0$","$x^2-6x+11=0$","$x^2+6x+7=0$","$x^2-6x-7=0$"]', '$x^2-6x+7=0$', NULL, 'The sum is $(3+\sqrt2)+(3-\sqrt2)=6$ and the product is $9-2=7$. So the equation is $x^2-6x+7=0$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-6x+7=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 6, product 9-2=7: x^2-6x+7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc267145-5c90-4ff6-9317-0eec44773359', 'ALG.13', 2, 'numeric', 'Building an equation from its solutions', 'Two numbers have sum $1$ and product $-20$. What is the larger number?', '[]', '5', '5', 'They are the solutions of $x^2-x-20=0$, i.e. $(x-5)(x+4)=0$. The numbers are $5$ and $-4$, and the larger is $5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t^2-t-20=0: 5 and -4; larger 5.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('938beee6-a8bd-4cbf-89b6-26ccf1553f6e', 'ALG.13', 2, 'numeric', 'Expressions in the solutions, complex solutions', 'The solutions of $x^2-4x+1=0$ are $r$ and $s$. Find $r^2+s^2$.', '[]', '14', '4^2-2*1', '$r+s=4$ and $rs=1$. So $r^2+s^2=(r+s)^2-2rs=16-2=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16-2=14.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1747dd94-06d9-4df9-ad70-861812d35201', 'ALG.13', 2, 'choice', 'Expressions in the solutions, complex solutions', 'If $r$ and $s$ are the solutions of $x^2-9x+20=0$, what is $\frac1r+\frac1s$?', '["$\\frac{9}{20}$","$\\frac{20}{9}$","$-\\frac{9}{20}$","$\\frac{1}{9}$"]', '$\frac{9}{20}$', NULL, '$\frac1r+\frac1s=\frac{r+s}{rs}=\frac{9}{20}$. (Check: the solutions are $4$ and $5$, and $\frac14+\frac15=\frac9{20}$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)/rs=9/20.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
