INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33b1c573-df04-478d-92b5-7adceb6404e2', 'ALG.13', 2, 'numeric', 'Expressions in the solutions, complex solutions', 'The solutions of $x^2-6x+4=0$ are $r$ and $s$. Find $(r-s)^2$.', '[]', '20', '6^2-4*4', '$(r-s)^2=(r+s)^2-4rs=36-16=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)^2-4rs=36-16=20.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
