INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2c9c91f-4f6a-4096-a82b-c8d8e401f490', 'ALG.13', 3, 'numeric', 'Completing the square: the missing constant', 'For which $c$ is $2x^2+12x+c$ equal to $2(x+h)^2$ for some number $h$?', '[]', '18', '2*(6/2)^2', '$2(x+h)^2=2x^2+4hx+2h^2$. Matching $4h=12$ gives $h=3$, and then $c=2h^2=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x+h)^2=2x^2+4hx+2h^2; 4h=12, h=3, c=18.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e11e4e2-1a5c-402b-896c-61f92ddf5757', 'ALG.13', 3, 'numeric', 'Completing the square: the missing constant', 'The trinomial $x^2+bx+\frac{81}{4}$ is a perfect square and $b>0$. Find $b$.', '[]', '9', '9', 'The constant of a perfect square is $\left(\frac b2\right)^2$. So $\frac{b^2}{4}=\frac{81}{4}$, giving $b^2=81$. Since $b>0$, $b=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(b/2)^2=81/4, b/2=9/2, b=9.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d67a25a-8806-425e-bbff-e881891d18c8', 'ALG.13', 3, 'numeric', 'Completing the square: the missing constant', 'The trinomial $x^2+bx+(2b-4)$ is a perfect square. Find $b$.', '[]', '4', '4', 'A perfect square needs constant $=\left(\frac b2\right)^2$: $\frac{b^2}{4}=2b-4$. Multiply by 4: $b^2=8b-16$, so $b^2-8b+16=0$, which is $(b-4)^2=0$. Hence $b=4$ (the only value).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(b/2)^2=2b-4 gives b^2-8b+16=0, (b-4)^2=0, b=4. Check: x^2+4x+4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8079c64b-7964-439f-8c5a-84f7c598c874', 'ALG.13', 3, 'choice', 'Solving by completing the square', 'Solve $x^2-6x+1=0$ by completing the square.', '["$x=-3\\pm2\\sqrt{2}$","$x=3\\pm2\\sqrt{2}$","$x=3\\pm\\sqrt{2}$","$x=3\\pm\\sqrt{10}$"]', '$x=3\pm2\sqrt{2}$', NULL, '$x^2-6x=-1$. Add $9$: $(x-3)^2=8$. So $x-3=\pm\sqrt8=\pm2\sqrt2$, and $x=3\pm2\sqrt2$.', 'checked', '{"lint":[],"solve":{"answer":"$x=3\\pm2\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2=8: x=3±2√2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dd806b7-91a6-4e9f-b3ba-acea38a8db2d', 'ALG.13', 3, 'choice', 'Solving by completing the square', 'Divide by the leading coefficient and complete the square to solve $2x^2+8x-10=0$.', '["$x=-1$ or $x=5$","$x=3$ or $x=-7$","$x=1$ or $x=-5$","$x=1$ or $x=5$"]', '$x=1$ or $x=-5$', NULL, 'Divide by 2: $x^2+4x-5=0$, so $x^2+4x=5$. Add $4$: $(x+2)^2=9$. So $x+2=\pm3$, giving $x=1$ or $x=-5$.', 'checked', '{"lint":[],"solve":{"answer":"$x=1$ or $x=-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+4x-5=0, (x+2)^2=9, x=1 or -5.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dd49cd5-d2da-4980-99f1-bf818c6ceeab', 'ALG.13', 3, 'numeric', 'Solving by completing the square', 'What is the larger solution of $3x^2-6x-9=0$?', '[]', '3', '1+2', 'Divide by 3: $x^2-2x-3=0$, so $x^2-2x=3$. Add $1$: $(x-1)^2=4$. So $x-1=\pm2$, and $x=3$ or $x=-1$. The larger is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-2x-3=0, (x-1)^2=4, x=3 or -1; larger 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('181435ef-91d7-473a-9fd3-f92c14de8fad', 'ALG.13', 3, 'choice', 'Rewriting in vertex form', 'Complete the square on $2x^2+12x+7$.', '["$2(x+3)^2-2$","$2(x+3)^2+7$","$2(x+6)^2-65$","$2(x+3)^2-11$"]', '$2(x+3)^2-11$', NULL, 'Factor 2 from the $x$ terms: $2(x^2+6x)+7=2(x^2+6x+9-9)+7=2(x+3)^2-18+7=2(x+3)^2-11$.', 'checked', '{"lint":[],"solve":{"answer":"$2(x+3)^2-11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x^2+6x)+7=2(x+3)^2-18+7=2(x+3)^2-11.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
