INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4daedf9c-a93c-4bad-a840-59293700bdef', 'ALG.13', 3, 'numeric', 'Rewriting in vertex form', 'What is the least value of $3x^2-12x+20$?', '[]', '8', '20-3*4', '$3x^2-12x+20=3(x^2-4x)+20=3(x-2)^2-12+20=3(x-2)^2+8$. The square is at least $0$, so the least value is $8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x^2-4x)+20=3(x-2)^2-12+20=3(x-2)^2+8; least 8.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
