INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2177ef2-13f9-4058-8c7e-35ce1ee00f47', 'ALG.13', 3, 'numeric', 'Rewriting in vertex form', 'The expression $x^2+bx+c$ equals $(x+4)^2-7$ for every $x$. Find $b+c$.', '[]', '17', '8+9', '$(x+4)^2-7=x^2+8x+16-7=x^2+8x+9$. So $b=8$, $c=9$ and $b+c=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+4)^2-7=x^2+8x+9; b+c=17.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce6b20af-a38a-4335-8c5c-918bf62b90ff', 'ALG.13', 3, 'numeric', 'Quadratic formula with rational solutions', 'What is the larger solution of $4x^2-4x-3=0$?', '[]', '3/2', '(4+8)/8', '$a=4,\ b=-4,\ c=-3$. $b^2-4ac=16+48=64$. $x=\frac{4\pm8}{8}$ gives $\frac32$ and $-\frac12$. The larger is $\frac32$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(4±√(16+48))/8=(4±8)/8: 3/2 or -1/2; larger 3/2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b41ca13b-e1f8-4e26-aa74-17b08a392cb6', 'ALG.13', 3, 'numeric', 'Quadratic formula with rational solutions', 'Solve $5x^2+x-4=0$. What is the smaller solution?', '[]', '-1', '(-1-9)/10', '$a=5,\ b=1,\ c=-4$. $b^2-4ac=1+80=81$. $x=\frac{-1\pm9}{10}$ gives $\frac45$ and $-1$. The smaller is $-1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(-1±√(1+80))/10=(-1±9)/10: 4/5 or -1; smaller -1.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('450fb502-d01b-443b-bfb0-22dea9d9b1dc', 'ALG.13', 3, 'choice', 'Quadratic formula with rational solutions', 'Solve $x(x+7)=18$.', '["$x=-2$ or $x=9$","$x=18$ or $x=11$","$x=2$ or $x=-9$","$x=2$ or $x=9$"]', '$x=2$ or $x=-9$', NULL, 'Expand and move everything to one side: $x^2+7x-18=0$. Then $b^2-4ac=49+72=121$, and $x=\frac{-7\pm11}{2}$, giving $2$ and $-9$. (Setting each factor equal to $18$ is a mistake: that rule only works when the product is $0$.)', 'checked', '{"lint":[],"solve":{"answer":"$x=2$ or $x=-9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+7x-18=0=(x+9)(x-2): x=2 or -9.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34533b63-9197-49ad-bd56-13bc56d30486', 'ALG.13', 3, 'choice', 'Quadratic formula with irrational solutions', 'Solve $x^2=3x+3$.', '["$x=\\frac{-3\\pm\\sqrt{21}}{2}$","$x=\\frac{3\\pm\\sqrt{21}}{2}$","$x=3\\pm\\sqrt{21}$","$x=\\frac{3\\pm\\sqrt{15}}{2}$"]', '$x=\frac{3\pm\sqrt{21}}{2}$', NULL, 'Move everything to one side: $x^2-3x-3=0$. Here $a=1,\ b=-3,\ c=-3$, so $b^2-4ac=21$. Then $x=\frac{3\pm\sqrt{21}}{2}$, which simplifies to $x=\frac{3\pm\sqrt{21}}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{3\\pm\\sqrt{21}}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-3x-3=0: x=(3±√(9+12))/2=(3±√21)/2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50843d57-987e-497b-91a6-62a82aa560a7', 'ALG.13', 3, 'choice', 'Quadratic formula with irrational solutions', 'Find the solutions of $5x^2-10x+3=0$.', '["$x=\\frac{-5\\pm\\sqrt{10}}{5}$","$x=\\frac{10\\pm2\\sqrt{10}}{5}$","$x=\\frac{5\\pm\\sqrt{10}}{5}$","$x=10\\pm2\\sqrt{10}$"]', '$x=\frac{5\pm\sqrt{10}}{5}$', NULL, 'Here $a=5,\ b=-10,\ c=3$, so $b^2-4ac=40$. Then $x=\frac{10\pm\sqrt{40}}{10}$, which simplifies to $x=\frac{5\pm\sqrt{10}}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\frac{5\\pm\\sqrt{10}}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(10±√(100-60))/10=(10±2√10)/10=(5±√10)/5.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8789d80-77d9-49ef-b701-7b72c1c551a9', 'ALG.13', 3, 'choice', 'Quadratic formula with irrational solutions', 'Solve $(x-1)(x+3)=3$.', '["$x=1\\pm\\sqrt{7}$","$x=-2\\pm2\\sqrt{7}$","$x=\\frac{-2\\pm\\sqrt{26}}{2}$","$x=-1\\pm\\sqrt{7}$"]', '$x=-1\pm\sqrt{7}$', NULL, 'Expand: $x^2+2x-3=3$, so $x^2+2x-6=0$. Here $a=1,\ b=2,\ c=-6$, so $b^2-4ac=28$. Then $x=\frac{-2\pm\sqrt{28}}{2}$, which simplifies to $x=-1\pm\sqrt{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$x=-1\\pm\\sqrt{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+2x-3=3, x^2+2x-6=0: x=(-2±√28)/2=-1±√7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ab9cb4c-5999-4864-9d10-f1d9f1d324bd', 'ALG.13', 3, 'numeric', 'Computing the discriminant', 'Find the discriminant of the equation $(2x-1)(x+3)=4$.', '[]', '81', '25+56', 'Expand: $2x^2+5x-3=4$, so $2x^2+5x-7=0$. Then $b^2-4ac=25-4(2)(-7)=25+56=81$.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2+5x-3=4, 2x^2+5x-7=0: 25+56=81.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d72e58c1-198e-4dac-a2ba-680f0850303f', 'ALG.13', 3, 'numeric', 'Computing the discriminant', 'What is the discriminant of $3x^2-12x=7$?', '[]', '228', '144+84', 'Rewrite as $3x^2-12x-7=0$. Then $b^2-4ac=144-4(3)(-7)=144+84=228$.', 'checked', '{"lint":[],"solve":{"answer":"228","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x^2-12x-7=0: 144+84=228.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
