INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccdeb0fc-13f5-4ad8-92bf-b06e70c34817', 'ALG.13', 3, 'numeric', 'Discriminant and the number of real solutions', 'For how many integers $k$ from $-5$ to $5$ inclusive does $x^2+4x+k=0$ have two different real solutions?', '[]', '9', '3-(-5)+1', 'The discriminant is $16-4k$, which must be positive: $k<4$. The integers from $-5$ to $5$ with $k<4$ are $-5,-4,\ldots,3$, and there are $9$ of them.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16-4k>0 iff k<4: k=-5..3, 9 integers.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acc20aed-3aa0-4a94-ba07-536e586b6627', 'ALG.13', 3, 'numeric', 'Discriminant and the number of real solutions', 'For how many whole numbers $k$ from $1$ to $20$ does $x^2+kx+16=0$ have no real solutions?', '[]', '7', '7', 'The discriminant is $k^2-64$. There are no real solutions when $k^2<64$, i.e. $k<8$ for positive $k$. So $k=1,2,\ldots,7$, which is $7$ values.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k^2-64<0 iff k<8: k=1..7, 7 values.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bf10419-b96b-4efc-a2f5-f9d4f6acca4d', 'ALG.13', 3, 'choice', 'Discriminant and the number of real solutions', 'Which of these equations has exactly one real solution?', '["$4x^2-12x+9=0$","$4x^2-12x+8=0$","$4x^2-12x+10=0$","$4x^2-12x+7=0$"]', '$4x^2-12x+9=0$', NULL, 'For $4x^2-12x+c$, the discriminant is $144-16c$, which is $0$ only when $c=9$. The values $c=8$ and $c=7$ give positive discriminants ($16$ and $32$), and $c=10$ gives $-16$.', 'checked', '{"lint":[],"solve":{"answer":"$4x^2-12x+9=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"144-16c=0 at c=9.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b887c608-2569-4726-aaee-d62a3cb6979f', 'ALG.13', 3, 'numeric', 'Finding a coefficient from the discriminant', 'The equation $kx^2-6x+3=0$, with $k\neq0$, has exactly one solution. Find $k$.', '[]', '3', '36/12', 'The discriminant is $36-4k(3)=36-12k$. Setting it to $0$ gives $k=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36-12k=0, k=3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2b95794-8f65-4d35-8673-efdcf9bc9ac1', 'ALG.13', 3, 'numeric', 'Finding a coefficient from the discriminant', 'The equation $x^2+(k-1)x+9=0$ has exactly one solution for two values of $k$. What is the sum of those two values?', '[]', '2', '7+(-5)', 'The discriminant is $(k-1)^2-36=0$, so $k-1=\pm6$. Then $k=7$ or $k=-5$, and their sum is $2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k-1)^2=36: k=7 or -5; sum 2.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba8ef34a-e99f-44c5-be0b-317f864eb5f5', 'ALG.13', 3, 'choice', 'Finding a coefficient from the discriminant', 'For which values of $k$ does $2x^2+kx+2=0$ have no real solutions?', '["$k<-4$ or $k>4$","$k<4$","$k>-4$","$-4<k<4$"]', '$-4<k<4$', NULL, 'The discriminant is $k^2-16$, which is negative when $k^2<16$, i.e. $-4<k<4$.', 'checked', '{"lint":[],"solve":{"answer":"$-4<k<4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k^2-16<0 iff -4<k<4.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9caa6892-862a-4780-b3f8-294bfcd34d2e', 'ALG.13', 3, 'numeric', 'Sum and product of solutions', 'The two solutions of $x^2-6x+c=0$ differ by $2$. Find $c$.', '[]', '8', '2*4', 'The solutions add to $6$ and differ by $2$, so they are $2$ and $4$. Their product is $c=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=6, r-s=2: 4 and 2; c=8.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbab98a7-6a23-4bd0-9a05-9624d2a999f6', 'ALG.13', 3, 'numeric', 'Sum and product of solutions', 'In $x^2-10x+c=0$, one solution is four times the other. Find $c$.', '[]', '16', '2*8', 'Let the solutions be $r$ and $4r$. Their sum is $5r=10$, so $r=2$ and the solutions are $2$ and $8$. Then $c=2\cdot8=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+4r=10, r=2, roots 2 and 8; c=16.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c879090e-85c3-400d-95dd-f0c0d4beb70b', 'ALG.13', 3, 'numeric', 'Sum and product of solutions', 'The equation $x^2-(m+5)x+3m=0$ has two solutions whose sum is $1$ more than their product. Find $m$.', '[]', '2', '4/2', 'The sum is $m+5$ and the product is $3m$. So $m+5=3m+1$, which gives $2m=4$ and $m=2$. (The equation is then $x^2-7x+6=0$, with solutions $1$ and $6$.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum m+5, product 3m: m+5=3m+1, m=2; equation x^2-7x+6, roots 1,6 real.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('924b2d0d-31a3-4995-be6a-734b2249340a', 'ALG.13', 3, 'choice', 'Building an equation from its solutions', 'The equation $x^2-5x+6=0$ has solutions $2$ and $3$. Which equation has solutions twice as large?', '["$x^2-10x+12=0$","$x^2-10x+24=0$","$x^2-5x+24=0$","$x^2-10x+6=0$"]', '$x^2-10x+24=0$', NULL, 'The new solutions are $4$ and $6$. Their sum is $10$ and their product is $24$, so the equation is $x^2-10x+24=0$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-10x+24=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 4, 6: x^2-10x+24.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc554156-7322-4d1e-a0cc-714655a6d250', 'ALG.13', 3, 'choice', 'Building an equation from its solutions', 'The equation $x^2-5x+6=0$ has solutions $2$ and $3$. Which equation with whole-number coefficients has the reciprocals of those solutions?', '["$6x^2+5x+1=0$","$x^2-6x+5=0$","$6x^2-5x+1=0$","$5x^2-6x+1=0$"]', '$6x^2-5x+1=0$', NULL, 'The new solutions are $\frac12$ and $\frac13$. Their sum is $\frac56$ and their product is $\frac16$, so $x^2-\frac56x+\frac16=0$. Multiply by 6: $6x^2-5x+1=0$.', 'checked', '{"lint":[],"solve":{"answer":"$6x^2-5x+1=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 1/2, 1/3: (2x-1)(3x-1)=6x^2-5x+1.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd3d1407-118d-454e-9c9b-b018cef72261', 'ALG.13', 3, 'numeric', 'Building an equation from its solutions', 'Two positive numbers add to $17$ and multiply to $60$. Find their positive difference.', '[]', '7', '12-5', 'They solve $x^2-17x+60=0$, whose discriminant is $289-240=49$. So $x=\frac{17\pm7}{2}$, giving $12$ and $5$. The difference is $7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 and 5; difference 7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f416a4b6-1f02-4018-bdb7-fa151574af67', 'ALG.13', 3, 'numeric', 'Expressions in the solutions, complex solutions', 'The solutions of $x^2-3x+1=0$ are $r$ and $s$. Find $r^3+s^3$.', '[]', '18', '3^3-3*1*3', '$r^3+s^3=(r+s)^3-3rs(r+s)$. With $r+s=3$ and $rs=1$ this is $27-9=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)^3-3rs(r+s)=27-9=18.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82598122-2c9f-4f06-9d36-7c6811f56991', 'ALG.13', 3, 'numeric', 'Expressions in the solutions, complex solutions', 'The solutions of $x^2-4x+k=0$ are $r$ and $s$, and $r^2+s^2=10$. Find $k$.', '[]', '3', '(16-10)/2', '$r^2+s^2=(r+s)^2-2rs=16-2k=10$, so $k=3$. (Then the solutions are $1$ and $3$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16-2k=10, k=3 (roots 1, 3).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
