INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef2c03a3-3257-41ba-868e-73ab34525349', 'ALG.13', 3, 'choice', 'Expressions in the solutions, complex solutions', 'Solve $x^2-2x+5=0$ using the quadratic formula, allowing non-real answers.', '["$x=1\\pm4i$","$x=1\\pm2i$","$x=-1\\pm2i$","$x=1\\pm\\sqrt{6}$"]', '$x=1\pm2i$', NULL, '$b^2-4ac=4-20=-16$, and $\sqrt{-16}=4i$. So $x=\frac{2\pm4i}{2}=1\pm2i$.', 'checked', '{"lint":[],"solve":{"answer":"$x=1\\pm2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=(2±√(4-20))/2=(2±4i)/2=1±2i.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
