VALUES ('f10b474f-dd96-4c1e-bd48-62ecc2f04ab9', 'ALG.16', 2, 'choice', 'Composition as an expression and its order', 'Machine $g$ turns $x$ into $x^2+x$, and machine $f$ turns $x$ into $2x-1$. A number $x$ goes into $g$ first, and the result goes into $f$. What comes out?', '["$4x^2-2x$","$2x^2+x-1$","$2x^2+2x+1$","$2x^2+2x-1$"]', '$2x^2+2x-1$', NULL, '$f(g(x))=2(x^2+x)-1=2x^2+2x-1$. The expression $4x^2-2x$ is $g(f(x))$.', 'checked', '{"lint":[],"solve":{"answer":"$2x^2+2x-1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x^2+x)=2x^2+2x-1","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a41743bc-681e-452c-bd56-381187d41608', 'ALG.16', 2, 'choice', 'Composition as an expression and its order', 'Let $f(x)=x-5$ and $g(x)=3x$. Which expression is $g(f(x))$?', '["$3x-15$","$3x-5$","$x-15$","$3x+15$"]', '$3x-15$', NULL, '$g(f(x))=3(x-5)=3x-15$. Remember to multiply the 5 as well.', 'checked', '{"lint":[],"solve":{"answer":"$3x-15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x-5)=3x-15","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
