INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c7c5b23-96bc-415b-9106-2226d3f21e84', 'ALG.16', 2, 'numeric', 'Composition as an expression and its order', 'Let $f(x)=2x+1$ and $g(x)=ax$. If $f(g(x))=6x+1$ for every $x$, what number is $a$?', '[]', '3', NULL, '$f(g(x))=2ax+1$. Setting $2a=6$ gives $a=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2ax+1=6x+1, a=3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
