INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea39a403-6e2f-4c4b-86d0-c720df193e60', 'ALG.16', 2, 'numeric', 'Find the value of an inverse function', 'Let $f(x)=3x-5$. What is $f^{-1}(16)$?', '[]', '7', '(16+5)/3', 'Solve $3x-5=16$: $3x=21$, so $x=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-5=16, x=7","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
