INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfb4eebf-f783-4c30-84eb-7d6010410683', 'ALG.16', 2, 'choice', 'Find the value of an inverse function', 'A function $f$ has $f(1)=4$, $f(2)=7$, $f(3)=9$ and $f(4)=12$. What is $f^{-1}(9)$?', '["$2$","$4$","$9$","$3$"]', '$3$', NULL, '$f^{-1}(9)$ is the input whose output is $9$. That input is $3$.', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)=9 so f^{-1}(9)=3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
