INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5898e1c-6431-431c-b65b-d7a58c0334f6', 'ALG.16', 2, 'numeric', 'Find the value of an inverse function', 'Let $f(x)=\frac{x+1}{2}$. What is $f^{-1}(5)$?', '[]', '9', '5*2-1', 'Solve $\frac{x+1}{2}=5$: $x+1=10$, so $x=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)/2=5, x=9","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
