INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ee43f4c-d029-48d1-976b-0119df05b305', 'ALG.16', 2, 'choice', 'Find the formula of an inverse function', 'If $f(x)=\frac{x-1}{3}$, which rule gives $f^{-1}(x)$?', '["$f^{-1}(x)=3x+1$","$f^{-1}(x)=3x-1$","$f^{-1}(x)=\\frac{x}{3}+1$","$f^{-1}(x)=\\frac{3}{x-1}$"]', '$f^{-1}(x)=3x+1$', NULL, 'From $y=\frac{x-1}{3}$ we get $x=3y+1$, so $f^{-1}(x)=3x+1$.', 'checked', '{"lint":[],"solve":{"answer":"$f^{-1}(x)=3x+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=(x-1)/3 -> x=3y+1","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
