INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29ecab4f-1a41-421f-94eb-1f03540a90e9', 'ALG.16', 2, 'numeric', 'Find the formula of an inverse function', 'The function $f(x)=-x+7$ is its own inverse, so $f^{-1}(x)=-x+c$ for a number $c$. What is $c$?', '[]', '7', NULL, 'From $y=-x+7$ we get $x=7-y$, so $f^{-1}(x)=-x+7$ and $c=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=-x+7 -> x=-y+7, c=7","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
