INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7448b6d-cd0b-40bb-a5ba-8c7b3aee97b4', 'ALG.16', 2, 'choice', 'Properties of inverse functions and one-to-one functions', 'Which list of (input, output) pairs is a function that has an inverse function?', '["$(1,5),\\ (2,5),\\ (3,7)$","$(1,5),\\ (2,6),\\ (3,7)$","$(1,5),\\ (1,6),\\ (2,7)$","$(1,5),\\ (2,6),\\ (2,7)$"]', '$(1,5),\ (2,6),\ (3,7)$', NULL, 'The second list is a function, but two inputs give the output $5$, so it cannot be undone. The last two lists give one input two outputs. Only the first list is a function with a different output for each input.', 'checked', '{"lint":[],"solve":{"answer":"$(1,5),\\ (2,6),\\ (3,7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distinct inputs and distinct outputs","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
