INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f40a6007-ae15-467a-a15d-351141bc86b4', 'ALG.16', 2, 'choice', 'Properties of inverse functions and one-to-one functions', 'Which statement about $f(x)=x^2$, with all real numbers as inputs, is true?', '["It has an inverse function, because every input has an output","It has no inverse function, because $f(0)=0$","It has no inverse function, because $3$ and $-3$ give the same output","It has the inverse function $f^{-1}(x)=x^2$"]', 'It has no inverse function, because $3$ and $-3$ give the same output', NULL, 'An inverse needs each output to come from only one input. Here $f(3)=f(-3)=9$, so $9$ could not be sent back to a single input.', 'checked', '{"lint":[],"solve":{"answer":"It has no inverse function, because $3$ and $-3$ give the same output","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)=f(-3)=9, not one-to-one","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
