VALUES ('64a62fd9-ae57-4e33-af22-691155d03bc2', 'ALG.16', 3, 'numeric', 'Evaluate a function at a number', 'Let $f(x)=|x-3|+|x+2|$. Find $f(-4)$.', '[]', '9', '7+2', '$f(-4)=|-4-3|+|-4+2|=|-7|+|-2|=7+2=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-4-3|+|-4+2|=7+2=9","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
