VALUES ('de4dba0a-9c71-46ab-a387-fb16c8ade310', 'ALG.16', 3, 'choice', 'Function notation and expressions like f(a+1)', 'Let $f(x)=x^2$. Which expression is equal to $f(x+3)-f(x)$?', '["$9$","$6x$","$6x+9$","$x^2+9$"]', '$6x+9$', NULL, '$f(x+3)=(x+3)^2=x^2+6x+9$. Subtract $f(x)=x^2$ to leave $6x+9$.', 'checked', '{"lint":[],"solve":{"answer":"$6x+9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)^2-x^2=6x+9","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
