INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4e4f57d-9fda-4b20-9488-32f18343838c', 'ALG.16', 3, 'numeric', 'Function notation and expressions like f(a+1)', 'Let $f(x)=4x-1$. For every number $a$, $f(a+3)=f(a)+k$ for the same number $k$. What is $k$?', '[]', '12', '4*3', '$f(a+3)=4a+12-1=4a+11$ and $f(a)=4a-1$. The difference is $12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(a+3)=4a+12-1=f(a)+12, k=12","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
