VALUES ('c8be9321-2961-429e-886f-5a34f0c140fb', 'ALG.16', 3, 'choice', 'Function notation and expressions like f(a+1)', 'Let $f(x)=x^2-x$. Which expression is $f(x+1)$?', '["$x^2-x+1$","$x^2+x+2$","$x^2+2x$","$x^2+x$"]', '$x^2+x$', NULL, '$f(x+1)=(x+1)^2-(x+1)=x^2+2x+1-x-1=x^2+x$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2+x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)^2-(x+1)=x^2+2x+1-x-1=x^2+x","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
