INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('712095fe-e6a0-48b9-9308-4a830cde03ce', 'ALG.16', 3, 'choice', 'Find an unknown number in the rule of a function', 'A linear function has $f(2)=7$ and $f(6)=-1$. Which is its rule?', '["$f(x)=2x+3$","$f(x)=-2x+11$","$f(x)=-2x+7$","$f(x)=-2x+3$"]', '$f(x)=-2x+11$', NULL, 'The output drops 8 as the input rises 4, so the slope is $-2$. Then $7=-2\cdot2+b$ gives $b=11$. Check $f(6)=-12+11=-1$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=-2x+11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"slope (-1-7)/(6-2)=-2, 7=-4+b, b=11","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
