INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27cbb6e3-2fa2-45f5-a0de-fcee63dd17da', 'ALG.16', 3, 'numeric', 'Domain of a function', 'Let $f(x)=\frac{\sqrt{x-1}}{x-4}$. How many integers from $0$ to $10$ (including both) are in the domain of $f$?', '[]', '9', '10-1', 'We need $x-1\ge0$, so $x\ge1$, and $x\ne4$. The integers $1$ through $10$ are $10$ numbers; removing $4$ leaves $9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need x>=1 and x!=4: integers 1..10 except 4 -> 9","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18ea160e-5c01-4619-99f8-843eafa19de9', 'ALG.16', 3, 'choice', 'Domain of a function', 'The domain of a function is exactly all numbers $x$ with $x\ge-2$. Which could be that function?', '["$f(x)=\\sqrt{x-2}$","$f(x)=\\sqrt{2-x}$","$f(x)=\\sqrt{x+2}$","$f(x)=\\frac{1}{x+2}$"]', '$f(x)=\sqrt{x+2}$', NULL, '$\sqrt{x+2}$ needs $x+2\ge0$, i.e. $x\ge-2$. The others give $x\ge2$, $x\le2$, and $x\ne-2$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=\\sqrt{x+2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x+2) needs x>=-2; 1/(x+2) excludes -2, sqrt(x-2) x>=2, sqrt(2-x) x<=2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a36200cc-8550-4529-96dd-3062794154e5', 'ALG.16', 3, 'choice', 'Range of a function', 'Which describes the range of $f(x)=|x-4|+2$?', '["$y\\ge4$","$y\\ge2$","$y\\ge-2$","$y\\le2$"]', '$y\ge2$', NULL, '$|x-4|\ge0$ with $0$ at $x=4$, so $|x-4|+2\ge2$ and every value from $2$ up is reached.', 'checked', '{"lint":[],"solve":{"answer":"$y\\ge2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|x-4|>=0, y>=2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
