INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac0e13ea-542b-45fe-bfad-bac5fcc35641', 'ALG.16', 3, 'numeric', 'Range of a function', 'What is the smallest value of $f(x)=x^2-6x+4$?', '[]', '-5', NULL, 'Complete the square: $x^2-6x+4=(x-3)^2-5$. The smallest value is $-5$ at $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2-5, min -5","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
