INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f582c57-7cda-46e0-899b-38dfdf056398', 'ALG.16', 3, 'numeric', 'Range of a function', 'The function $f(x)=x^2$ has as its domain the integers from $-4$ to $3$ (including both). How many different numbers are in its range?', '[]', '5', NULL, 'The inputs $-4,\dots,3$ give $16,9,4,1,0,1,4,9$. The different outputs are $16,9,4,1,0$: five numbers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares 16,9,4,1,0,1,4,9 -> {0,1,4,9,16}: 5","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
