VALUES ('f163d044-710e-49b5-ab31-f358d6e84d6f', 'ALG.16', 3, 'numeric', 'Evaluate a composition at a number', 'Let $f(x)=x^2-3x$ and $g(x)=x+2$. There are two numbers $x$ with $f(g(x))=0$. What is the positive one?', '[]', '1', NULL, '$f(g(x))=(x+2)^2-3(x+2)=(x+2)(x-1)$. This is $0$ at $x=-2$ and $x=1$. The positive one is $1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+2)^2-3(x+2)=(x+2)(x-1)=0, x=-2 or 1; positive 1","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
