INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86c46458-72bd-4af5-a381-8aa603e1d6c2', 'ALG.16', 3, 'choice', 'Evaluate a composition at a number', 'Let $f(x)=2x+1$ and $g(x)=x^2$. There are two numbers $a$ with $f(g(a))=g(f(a))$, and one of them is $0$. Which is the other?', '["$-2$","$2$","$-1$","$1$"]', '$-2$', NULL, '$f(g(a))=2a^2+1$ and $g(f(a))=(2a+1)^2=4a^2+4a+1$. Setting them equal: $2a^2+4a=0$, so $a=0$ or $a=-2$.', 'checked', '{"lint":[],"solve":{"answer":"$-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(g(a))=2a^2+1, g(f(a))=4a^2+4a+1; 2a^2+4a=0, a=0 or -2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4aa6f14-afb8-497f-92f0-613234506a6a', 'ALG.16', 3, 'numeric', 'Composition as an expression and its order', 'Let $f(x)=3x+b$ and $g(x)=2x-1$. If $f(g(x))=g(f(x))$ for every $x$, what number is $b$?', '[]', '-2', NULL, '$f(g(x))=6x-3+b$ and $g(f(x))=6x+2b-1$. Equal for every $x$ means $-3+b=2b-1$, so $b=-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-3+b = 6x+2b-1, b=-2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ba92d29-b6dd-473b-b379-4e291c82a23e', 'ALG.16', 3, 'choice', 'Composition as an expression and its order', 'Let $f(x)=x^2$. Which of these could be $g(x)$ if $f(g(x))=x^2-6x+9$ for every $x$?', '["$g(x)=x+3$","$g(x)=x-3$","$g(x)=3x$","$g(x)=x^2-3$"]', '$g(x)=x-3$', NULL, '$f(g(x))=(g(x))^2$ must equal $x^2-6x+9=(x-3)^2$, so $g(x)=x-3$ works.', 'checked', '{"lint":[],"solve":{"answer":"$g(x)=x-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2=x^2-6x+9, g=x-3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
