INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94dcacc5-b9fa-4151-809a-11e6e4fd47b3', 'ALG.16', 3, 'numeric', 'Composition as an expression and its order', 'Let $f(x)=x+1$ and $g(x)=2x$, and let $h(x)=f(g(x))$. Then $h(h(x))=ax+b$ for numbers $a$ and $b$. What is $a+b$?', '[]', '7', NULL, '$h(x)=2x+1$. Then $h(h(x))=2(2x+1)+1=4x+3$, so $a=4$, $b=3$ and $a+b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h=2x+1, h(h(x))=4x+3, a+b=7","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
