VALUES ('74258e0e-b509-420b-ace8-715824fbbf74', 'ALG.16', 3, 'numeric', 'Find the value of an inverse function', 'Let $f(x)=x^3+1$. What is $f^{-1}(28)$?', '[]', '3', NULL, 'Solve $x^3+1=28$: $x^3=27$, so $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^3+1=28, x=3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
