INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8ef7de1-cb57-4073-b8d3-a195e91b8dc6', 'ALG.16', 3, 'numeric', 'Find the value of an inverse function', 'Let $f(x)=2x-3$. What is $f^{-1}(f^{-1}(9))$?', '[]', '9/2', '((9+3)/2+3)/2', '$f^{-1}(9)$: $2x-3=9$ gives $x=6$. Then $f^{-1}(6)$: $2x-3=6$ gives $x=\frac92$.', 'checked', '{"lint":[],"solve":{"answer":"9/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f^{-1}(x)=(x+3)/2; f^{-1}(9)=6, f^{-1}(6)=9/2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
