VALUES ('747dce24-8d2c-4ee6-a95a-590874390491', 'ALG.16', 3, 'choice', 'Find the value of an inverse function', 'Let $f(x)=\frac{4}{x-1}$. Which number is $f^{-1}(2)$?', '["$3$","$5$","$1$","$9$"]', '$3$', NULL, 'Solve $\frac{4}{x-1}=2$: $x-1=2$, so $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/(x-1)=2, x=3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
