INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ba16174-b0e6-4870-bce0-914282fec0a2', 'ALG.16', 3, 'choice', 'Find the formula of an inverse function', 'If $f(x)=\frac{3}{x+2}$, which rule gives $f^{-1}(x)$?', '["$f^{-1}(x)=\\frac{3}{x}+2$","$f^{-1}(x)=\\frac{3}{x}-2$","$f^{-1}(x)=\\frac{x}{3}-2$","$f^{-1}(x)=\\frac{3}{x-2}$"]', '$f^{-1}(x)=\frac{3}{x}-2$', NULL, 'From $y=\frac{3}{x+2}$ we get $x+2=\frac{3}{y}$, so $x=\frac3y-2$.', 'checked', '{"lint":[],"solve":{"answer":"$f^{-1}(x)=\\frac{3}{x}-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3/(x+2) -> x=3/y-2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
