INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a31d669-6fe4-4c0f-91f6-7058646950eb', 'ALG.16', 3, 'numeric', 'Find the formula of an inverse function', 'Let $f(x)=2x-3$. There is exactly one number $x$ for which $f^{-1}(x)=f(x)$. What is it?', '[]', '3', NULL, '$f^{-1}(x)=\frac{x+3}{2}$. Setting $\frac{x+3}{2}=2x-3$ gives $x+3=4x-6$, so $x=3$. Check: $f(3)=3$ and $f^{-1}(3)=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f^{-1}(x)=(x+3)/2=2x-3, x+3=4x-6, x=3","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d4ccd73-e459-406c-bd70-09beb36c0607', 'ALG.16', 3, 'choice', 'Find the formula of an inverse function', 'Which function is its own inverse, that is, $f^{-1}(x)=f(x)$?', '["$f(x)=x+1$","$f(x)=2x$","$f(x)=5-x$","$f(x)=x-5$"]', '$f(x)=5-x$', NULL, 'If $y=5-x$ then $x=5-y$, so the inverse is the same rule. The others have inverses $x-1$, $\frac x2$ and $x+5$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=5-x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5-(5-x)=x, self-inverse; others are not","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
