VALUES ('76830482-2a55-4d44-aaa2-9a124ac3469b', 'ALG.16', 3, 'choice', 'Properties of inverse functions and one-to-one functions', 'Which of these functions, with all real numbers as inputs, has an inverse function?', '["$f(x)=x^2$","$f(x)=|x|$","$f(x)=x^2+1$","$f(x)=x^3$"]', '$f(x)=x^3$', NULL, 'Different inputs always give different outputs for $x^3$. The others send $2$ and $-2$ to the same output.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=x^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^3 is one-to-one; others are even","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
