VALUES ('849c68ad-d457-40af-8954-edd45ef5aa69', 'ALG.17', 2, 'choice', 'Shift a graph up or down', 'The graph of $y=|x|$ is moved so that its lowest point is $(0,-3)$ instead of $(0,0)$, without any sideways move. What is its equation?', '["$y=|x-3|$","$y=|x+3|$","$y=|x|-3$","$y=|x|+3$"]', '$y=|x|-3$', NULL, 'The lowest point has dropped 3, so subtract 3 from every $y$-value: $y=|x|-3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=|x|-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down 3: |x|-3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
