INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e847370-011e-4f83-ac0b-ca1e2414cdd2', 'ALG.17', 2, 'choice', 'Order of transformations', 'Starting from $y=f(x)$, the graph is moved up 3 units and then reflected across the $x$-axis. What is the equation of the result?', '["$y=-f(x)+3$","$y=f(x)-3$","$y=-f(x)-3$","$y=-f(x+3)$"]', '$y=-f(x)-3$', NULL, 'Moving up gives $y=f(x)+3$. Reflecting negates the whole right side: $y=-(f(x)+3)=-f(x)-3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=-f(x)-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f+3 then negate: -f-3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
