INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d8a7699-3cd6-4fba-90f3-00c15ea89fce', 'ALG.17', 2, 'numeric', 'Order of transformations', 'The graph of $y=x^2$ is first moved up 2 units and then stretched vertically by a factor of $3$. What is the $y$-coordinate of the new graph at $x=3$?', '[]', '33', '3*(3^2+2)', 'After moving up: $y=x^2+2$. After stretching: $y=3(x^2+2)$. At $x=3$: $3\cdot11=33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9+2)*3=33","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
