INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3371e256-868d-43fb-91e5-43722cc9202c', 'ALG.17', 2, 'choice', 'Order of transformations', 'Which pair of moves gives the same final graph in either order?', '["Move up 2 units and stretch vertically by a factor of 3","Reflect across the $x$-axis and move up 4 units","Move down 1 unit and reflect across the $x$-axis","Move up 2 units and move right 5 units"]', 'Move up 2 units and move right 5 units', NULL, 'Up and right do not affect each other, so they can be done in either order. In the other pairs the order changes the result: for example, up 2 then stretching by 3 gives $3(f+2)$, but stretching then up 2 gives $3f+2$.', 'checked', '{"lint":[],"solve":{"answer":"Move up 2 units and move right 5 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical and horizontal shifts commute; others give -f-1 vs -f+1, -f+4 vs -f-4, 3f+6 vs 3f+2","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38e9847b-845e-4a15-848d-3e5d8074a029', 'ALG.17', 2, 'choice', 'Intercepts, zeros and symmetry after a change', 'The graph of $y=f(x)$ is symmetric about the $y$-axis. Which of these graphs must also be symmetric about the $y$-axis?', '["$y=f(x+4)$","$y=f(x)+4$","$y=f(x-4)$","$y=f(x-1)+4$"]', '$y=f(x)+4$', NULL, 'Moving up or down keeps the mirror line. Moving sideways moves the mirror line away from the $y$-axis.', 'checked', '{"lint":[],"solve":{"answer":"$y=f(x)+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical shift keeps symmetry about y-axis; horizontal shifts move the axis","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3970afb7-c701-4d08-a003-d603217a4fe2', 'ALG.17', 2, 'numeric', 'Intercepts, zeros and symmetry after a change', 'The graph of $y=f(x)$ crosses the $x$-axis at $x=1$ and $x=5$ and nowhere else. What is the sum of the $x$-values where $y=f(x-2)$ crosses the $x$-axis?', '[]', '10', '3+7', 'Moving right 2 gives $x=3$ and $x=7$. The sum is $10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"zeros at 3 and 7, sum 10","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f05353d-831b-4622-9233-882edd1d3ec2', 'ALG.17', 2, 'numeric', 'Intercepts, zeros and symmetry after a change', 'Let $f(x)=x^2-9$, which is $0$ at $x=3$ and $x=-3$. What is the positive $x$-value where the graph of $y=f\left(\frac{x}{2}\right)$ crosses the $x$-axis?', '[]', '6', '3*2', 'We need $\frac x2=3$, so $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2=3, x=6","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e332d840-415f-4e10-b61b-f9394b47c24f', 'ALG.17', 2, 'choice', 'Describe how one equation changes into another', 'Which describes how the graph of $y=2f(x)-4$ comes from the graph of $y=f(x)$?', '["Move down 4, then stretch vertically by a factor of 2","Stretch horizontally by a factor of 2, then move down 4","Stretch vertically by a factor of 2, then move down 4","Stretch vertically by a factor of 4, then move down 2"]', 'Stretch vertically by a factor of 2, then move down 4', NULL, 'First multiply by 2 to get $2f(x)$, then subtract 4. Moving down 4 first would give $2(f(x)-4)=2f(x)-8$.', 'checked', '{"lint":[],"solve":{"answer":"Stretch vertically by a factor of 2, then move down 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2f then -4","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b1f0e59-2a49-44ef-80d1-08984f5db951', 'ALG.17', 2, 'choice', 'Describe how one equation changes into another', 'Let $g(x)=f\left(\frac{x}{3}\right)$. Compared with the graph of $f$, what is true of the graph of $g$?', '["It is compressed horizontally by a factor of 3","It is stretched vertically by a factor of 3","It is compressed vertically by a factor of 3","It is stretched horizontally by a factor of 3"]', 'It is stretched horizontally by a factor of 3', NULL, 'The value of $f$ at $x$ now appears at $3x$, three times as far from the $y$-axis. So the graph is stretched horizontally by 3.', 'checked', '{"lint":[],"solve":{"answer":"It is stretched horizontally by a factor of 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/3 stretches horizontally by 3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04f94c9b-1759-40a0-a89a-8fa95e96eadc', 'ALG.17', 2, 'numeric', 'Describe how one equation changes into another', 'The graph of $y=f(x-4)+9$ comes from the graph of $y=f(x)$ by moving it some units right and some units up. What is the total of those two numbers of units?', '[]', '13', '4+9', 'Replacing $x$ by $x-4$ moves right 4. Adding 9 moves up 9. The total is $13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"right 4, up 9, total 13","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ef67930-1e67-4647-9007-3563689d604b', 'ALG.17', 3, 'numeric', 'Shift a graph up or down', 'The graph of $y=x^2-6x$ is moved up so that it just touches the $x$-axis at one point. How many units up is it moved?', '[]', '9', NULL, '$x^2-6x=(x-3)^2-9$ has lowest point $(3,-9)$. Moving up 9 puts the lowest point on the $x$-axis.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-6x=(x-3)^2-9, min -9, up 9","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8037e83f-3b95-4537-88a6-986b5121f210', 'ALG.17', 3, 'choice', 'Shift a graph up or down', 'The line $y=3x-2$ is moved straight up or down so that it passes through $(2,10)$. What is the equation of the new line?', '["$y=3x+8$","$y=3x-4$","$y=3x+10$","$y=3x+4$"]', '$y=3x+4$', NULL, 'The new line is $y=3x+c$. At $x=2$: $6+c=10$, so $c=4$.', 'checked', '{"lint":[],"solve":{"answer":"$y=3x+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3x+b, 6+b=10, b=4","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29c8b3ea-3a48-4c3c-b77a-4bea9493f8f5', 'ALG.17', 3, 'numeric', 'Shift a graph up or down', 'Let $f(x)=x^2$. The graph of $y=f(x)+k$ passes through the point $(3,1)$. What number is $k$?', '[]', '-8', '1-9', '$f(3)+k=9+k=1$, so $k=-8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9+k=1, k=-8","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
