INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9dcd882-5b56-4c7e-904e-40f1789712c4', 'ALG.17', 3, 'choice', 'Shift a graph left or right', 'The graph of $y=x^2$ is moved to the right so that it passes through $(1,16)$. What is the equation of the moved graph?', '["$y=(x-3)^2$","$y=(x+5)^2$","$y=(x-4)^2$","$y=(x-5)^2$"]', '$y=(x-5)^2$', NULL, 'Moved right by $h$ the graph is $y=(x-h)^2$. At $x=1$: $(1-h)^2=16$, so $1-h=\pm4$, $h=5$ or $-3$. Moved right means $h=5$.', 'checked', '{"lint":[],"solve":{"answer":"$y=(x-5)^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1-h)^2=16 with h>0 gives h=5: (x-5)^2; checked others fail at x=1","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ee847af-e16e-48bb-bd28-e27be9a9d10a', 'ALG.17', 3, 'numeric', 'Shift a graph left or right', 'Let $f(x)=x^2+2x$. What is the $y$-intercept of the graph of $y=f(x-3)$?', '[]', '3', '(-3)^2+2*(-3)', 'At $x=0$: $f(-3)=9-6=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-3)=9-6=3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
