INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3177f193-1677-4148-9296-91a82202c5cd', 'ALG.17', 3, 'numeric', 'Shift a graph left or right', 'Let $f(x)=|x-1|$. The graph of $y=f(x+6)$ has its lowest point at $x=a$. What is $a$?', '[]', '-5', NULL, '$f(x+6)=|x+6-1|=|x+5|$, which is smallest at $x=-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x+6)=|x+5|, lowest at x=-5","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
