INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2810e990-1034-4ab1-8fee-8764fdd8d64c', 'ALG.17', 3, 'choice', 'Reflect a graph across an axis', 'The graph of $y=x^2-4x+3$ is reflected across the $x$-axis. What is the equation of the new graph?', '["$y=-x^2-4x+3$","$y=x^2+4x+3$","$y=-x^2+4x+3$","$y=-x^2+4x-3$"]', '$y=-x^2+4x-3$', NULL, 'Reflecting across the $x$-axis changes the sign of every $y$-value, so every term changes sign: $y=-(x^2-4x+3)=-x^2+4x-3$.', 'checked', '{"lint":[],"solve":{"answer":"$y=-x^2+4x-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(x^2-4x+3)=-x^2+4x-3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
