INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('703f60d7-34e9-43e4-9463-21fa03ddb326', 'ALG.17', 3, 'numeric', 'Reflect a graph across an axis', 'Let $f(x)=3x-12$. The graphs of $y=f(x)$ and $y=-f(x)$ cross at one point. What is its $x$-coordinate?', '[]', '4', '12/3', 'Solve $3x-12=-(3x-12)$: $6x=24$, $x=4$. The graph and its reflection meet where $f(x)=0$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f=-f means f=0: 3x-12=0, x=4","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('071f4276-e3c3-4ae4-8497-9baec71b1768', 'ALG.17', 3, 'choice', 'Reflect a graph across an axis', 'The graph of which equation is unchanged when it is reflected across the $y$-axis?', '["$y=x^2+1$","$y=x^3$","$y=x+1$","$y=x^2+x$"]', '$y=x^2+1$', NULL, 'The graph is unchanged if replacing $x$ by $-x$ gives the same equation. That holds for $x^2+1$ only; $(-x)^3=-x^3$, and the others change.', 'checked', '{"lint":[],"solve":{"answer":"$y=x^2+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even function x^2+1","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
