INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b04469f2-fef3-45f7-ae31-5ce394c20ff3', 'ALG.17', 3, 'choice', 'Stretch or compress a graph vertically', 'The graph of $y=f(x)$ crosses the $x$-axis at $x=2$ and $x=5$ and nowhere else. Where does the graph of $y=7f(x)$ cross the $x$-axis?', '["At $x=14$ and $x=35$","At $x=\\frac{2}{7}$ and $x=\\frac{5}{7}$","At $x=9$ and $x=12$","At $x=2$ and $x=5$"]', 'At $x=2$ and $x=5$', NULL, 'A vertical stretch multiplies $y$-values, and $7\cdot0=0$. The points where $y=0$ do not move.', 'checked', '{"lint":[],"solve":{"answer":"At $x=2$ and $x=5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7f(x)=0 iff f(x)=0","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
