INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b61a366-4f48-4046-9647-fd84af4bfa84', 'ALG.17', 3, 'numeric', 'Stretch or compress a graph vertically', 'Let $f(x)=x^2-4x$. The graph of $y=kf(x)$ passes through the point $(1,9)$. What is $k$?', '[]', '-3', '9/(1-4)', '$f(1)=1-4=-3$. So $k\cdot(-3)=9$ and $k=-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1)=-3, -3k=9, k=-3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
