INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad1bec1e-f38e-4f4f-a8a9-5ab0596988c3', 'ALG.17', 3, 'numeric', 'Stretch or compress a graph vertically', 'The smallest value of $f(x)$ is $-8$. What is the largest value of $y=-2f(x)$?', '[]', '16', '-2*(-8)', '$-2f(x)$ is largest where $f(x)$ is smallest: $-2\cdot(-8)=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2f max when f is min: -2*(-8)=16","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
