VALUES ('6930e9fb-fecb-4691-997e-a96a67902382', 'ALG.17', 3, 'choice', 'Stretch or compress a graph horizontally', 'Let $f(x)=x^2-x$. Which expression is $f(2x)$?', '["$2x^2-2x$","$4x^2-x$","$2x^2-x$","$4x^2-2x$"]', '$4x^2-2x$', NULL, '$f(2x)=(2x)^2-2x=4x^2-2x$. Both terms use $2x$.', 'checked', '{"lint":[],"solve":{"answer":"$4x^2-2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x)^2-2x=4x^2-2x","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
