INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dc259b3-3f7f-4c9a-b871-f02430e68c84', 'ALG.17', 3, 'numeric', 'Lowest or highest point of a shifted graph', 'The graph of $y=-(x-5)^2+9$ crosses the $x$-axis at two points. What is the sum of their $x$-coordinates?', '[]', '10', '2+8', 'Solve $(x-5)^2=9$: $x=2$ or $x=8$. The sum is $10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-5)^2=9, x=2 or 8, sum 10","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
