INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b402acc1-7a3f-4a76-8134-447c626048ae', 'ALG.17', 3, 'choice', 'Lowest or highest point of a shifted graph', 'What is the lowest point of the graph of $y=|2x-6|+1$?', '["$(3,1)$","$(6,1)$","$(-3,1)$","$(3,-1)$"]', '$(3,1)$', NULL, '$|2x-6|=2|x-3|$, which is $0$ at $x=3$. So the lowest point is $(3,1)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3,1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x-6=0 at x=3, y=1","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
