INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8ad4eff-c158-4185-99d1-606232c8946f', 'ALG.17', 3, 'numeric', 'Lowest or highest point of a shifted graph', 'The graph of $y=a(x-4)^2-3$ has its lowest point at $(4,-3)$ and passes through $(6,5)$. What number is $a$?', '[]', '2', '8/4', '$a(6-4)^2-3=5$ gives $4a=8$, so $a=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a-3=5, a=2","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
