INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1c6b59e-93d4-4ed4-8852-ceecf57cf078', 'ALG.17', 3, 'numeric', 'Order of transformations', 'At a certain $x$, $f(x)=5$. The graph of $y=f(x)$ is changed in two ways. In plan A it is moved up 3 and then stretched vertically by a factor of $2$. In plan B it is stretched by $2$ and then moved up 3. How much greater is plan A''s $y$-value at that $x$ than plan B''s?', '[]', '3', '16-13', 'Plan A: $2(5+3)=16$. Plan B: $2\cdot5+3=13$. The difference is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: (5+3)*2=16; B: 2*5+3=13; difference 3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2efc2626-f196-49fd-aa67-2eae8827f462', 'ALG.17', 3, 'choice', 'Order of transformations', 'The graph of $y=f(x)$ is reflected across the $y$-axis and then moved right 2 units. What is the equation of the result?', '["$y=f(2-x)$","$y=f(-x-2)$","$y=f(-x)-2$","$y=f(x-2)$"]', '$y=f(2-x)$', NULL, 'Reflecting gives $y=f(-x)$. Moving right 2 replaces $x$ by $x-2$: $y=f(-(x-2))=f(2-x)$.', 'checked', '{"lint":[],"solve":{"answer":"$y=f(2-x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect: f(-x); right 2: f(-(x-2))=f(2-x)","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
