INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18ecbecf-f387-4b46-9c52-138b12797cd6', 'ALG.17', 3, 'numeric', 'Order of transformations', 'The graph of $y=x$ is reflected across the $x$-axis, then moved up 4 units, then stretched vertically by a factor of $3$. What is the $y$-coordinate of the new graph at $x=5$?', '[]', '-3', '3*(-5+4)', 'Reflecting gives $y=-x$. Up 4 gives $y=-x+4$. Stretching gives $y=3(-x+4)$. At $x=5$: $3\cdot(-1)=-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x+4 then *3: 3(-5+4)=-3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
