INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d319e725-2908-4794-a22b-1cdab7459b1c', 'ALG.17', 3, 'numeric', 'Intercepts, zeros and symmetry after a change', 'Let $f(x)=x^2-4x$. What is the sum of the $x$-values where the graph of $y=f(x-5)$ crosses the $x$-axis?', '[]', '14', '5+9', '$f(x)=x(x-4)$ is $0$ at $x=0$ and $x=4$. Moving right 5 gives $x=5$ and $x=9$. The sum is $14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f zeros 0,4; shifted to 5,9; sum 14","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
