INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfa0ac55-bbbe-49ea-a0b1-3a0770b06cec', 'ALG.17', 3, 'choice', 'Intercepts, zeros and symmetry after a change', 'Let $f(x)=x^2-2x-3$, which crosses the $x$-axis at $x=-1$ and $x=3$. Which graph crosses the $x$-axis at $x=1$ and $x=-3$?', '["$y=-f(x)$","$y=f(x+1)$","$y=f(-x)$","$y=2f(x)$"]', '$y=f(-x)$', NULL, '$f(-x)=0$ when $-x=-1$ or $-x=3$, i.e. $x=1$ or $x=-3$. The graphs $-f(x)$ and $2f(x)$ keep the old crossings, and $f(x+1)$ crosses at $-2$ and $2$.', 'checked', '{"lint":[],"solve":{"answer":"$y=f(-x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-x)=0 when -x=-1 or 3: x=1, -3","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
