INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0ceb60d-9131-4a8b-8698-6ac3d7017f2f', 'BA1.07', 3, 'numeric', 'Fact families', 'Kim is thinking of a fact family. The biggest number is 16. The two small numbers are not the same. One is 6 more than the other. What is the larger small number?', '[]', '11', '(16+6)/2', 'The two small numbers add up to 16. Try pairs: 5 and 11 differ by 6 and 5 + 11 = 16. So the larger one is 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two numbers sum to 16, differ by 6: 11 and 5. Larger 11.","run_id":"claude-code","at":"2026-10-19T01:19:04.163Z"}}', 'ai', NULL, NULL)
