INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d33ba5aa-7575-437c-a7e3-558e059801cc', 'BA1.07', 3, 'choice', 'Fact families', 'Only one of these groups of three numbers could NOT be a fact family. Which one?', '["$6, 7, 13$","$4, 11, 15$","$8, 8, 17$","$5, 9, 14$"]', '$8, 8, 17$', NULL, 'A fact family needs the two small numbers to add up to the big one. 8 + 8 = 16, not 17. The others do add up.', 'checked', '{"lint":[],"solve":{"answer":"$8, 8, 17$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+11=15, 8+8=16 not 17, 5+9=14, 6+7=13. 8,8,17 cannot.","run_id":"claude-code","at":"2026-10-19T01:19:04.163Z"}}', 'ai', NULL, NULL)
