INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c75dca7b-580f-4084-926b-da27804bf00e', 'BA1.07', 3, 'choice', 'Fact families', 'Ned knows that $? + 18 = 51$. Which sentence must be true?', '["$18 - ? = 51$","$? - 18 = 51$","$51 + 18 = ?$","$51 - 18 = ?$"]', '$51 - 18 = ?$', NULL, 'The family has ?, 18 and 51. Taking 18 away from the total 51 leaves the missing number, so 51 - 18 = ?.', 'checked', '{"lint":[],"solve":{"answer":"$51 - 18 = ?$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"?+18=51 means 51-18=?.","run_id":"claude-code","at":"2026-10-19T01:19:04.163Z"}}', 'ai', NULL, NULL)
