INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb42980a-b1b2-496f-bf10-b82dfe10d779', 'BA1.07', 3, 'numeric', 'Fact families', 'The three numbers of a fact family add up to 80. What is the biggest number in the family?', '[]', '40', '80/2', 'The two small numbers add up to the big one, so all three together are the big number twice. Half of 80 is 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Abstract reasoning step (biggest equals the sum of the other two) is a stretch for some 6-7 year olds, but fits a challenge curriculum.","work":"Biggest = sum of the other two, so total = 2 x biggest = 80; biggest 40.","run_id":"claude-code","at":"2026-10-19T01:19:04.163Z"}}', 'ai', NULL, NULL)
