INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('612d8ef3-a28a-477a-b59a-2d2695f48028', 'BA1.12', 2, 'choice', 'Logic puzzle: who has what, and mystery numbers', 'Which sentence is true?', '["$7 + 2 = 8$","$3 + 4 = 8$","$10 - 6 = 4$","$9 - 5 = 3$"]', '$10 - 6 = 4$', NULL, '10 - 6 = 4 is true. 7 + 2 is 9, 3 + 4 is 7, and 9 - 5 is 4, so the others are false.', 'checked', '{"lint":[],"solve":{"answer":"$10 - 6 = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-5 = 4 not 3; 7+2 = 9 not 8; 10-6 = 4 true; 3+4 = 7 not 8.","run_id":"claude-code","at":"2026-10-19T01:34:15.503Z"}}', 'ai', NULL, NULL)
