INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('112be23c-9d43-4207-93dd-60b9e828971f', 'BA2.01', 3, 'numeric', 'Place-value puzzles', 'I am a 3-digit number. All three of my digits are the same. My digits add up to 6. What number am I?', '[]', '222', '2*111', 'Three equal digits add to 6, so each digit is 6 divided by 3, which is 2. The number is 222.', 'checked', '{"lint":[],"solve":{"answer":"222","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d+d+d = 6 so d = 2: 222.","run_id":"claude-code","at":"2026-10-19T01:34:15.390Z"}}', 'ai', NULL, NULL)
