INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('206b5562-a09d-4446-8a42-c1cd3e14e9cf', 'BA2.02', 3, 'numeric', 'Greatest or least number from digits', 'Use the digits 3, 5 and 7, once each, to make the greatest number you can and also the least number you can. How much greater is the greatest number than the least?', '[]', '396', '753-357', 'The greatest number is 753 and the least is 357. 753 - 357 = 396.', 'checked', '{"lint":[],"solve":{"answer":"396","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 753, least 357. 753 - 357 = 396.","run_id":"claude-code","at":"2026-10-19T01:34:15.428Z"}}', 'ai', NULL, NULL)
