INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('624c7852-ebdc-4e17-b7b5-f59d3062d71d', 'BA2.02', 3, 'numeric', 'Greatest or least number from digits', 'Using the digits 5, 9 and 3 once each, how many different 3-digit numbers less than 500 can you make?', '[]', '2', '2', 'A number less than 500 must start with 3, the only digit under 5. After 3, the other two digits go in 2 orders: 359 and 395. So 2 numbers.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 500 needs hundreds 3: 359, 395. 2.","run_id":"claude-code","at":"2026-10-19T01:34:15.428Z"}}', 'ai', NULL, NULL)
