INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15ff681e-3c31-4d77-9ad6-5bb5406682c4', 'BA2.02', 3, 'choice', 'Greatest or least number from digits', 'You have cards with the digits 0, 6, 9 and 5. You pick three cards to make the least 3-digit number you can. Which number is it?', '["569","560","506","960"]', '506', '506', 'A 3-digit number cannot start with 0, so start with 5, the smallest digit that is not 0. Then use 0 and then 6: 506.', 'checked', '{"lint":[],"solve":{"answer":"506","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds smallest nonzero 5, then 0, then 6: 506.","run_id":"claude-code","at":"2026-10-19T01:34:15.428Z"}}', 'ai', NULL, NULL)
