INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149b0a91-7080-4d22-85f6-f2492b22ca92', 'BA2.02', 3, 'numeric', 'Greatest or least number from digits', 'You have cards with the digits 7, 8, 2, 1. You pick three cards to make the greatest 3-digit number you can that is less than 500. What number is it?', '[]', '287', '287', 'To be less than 500 the hundreds digit must be under 5. Use the biggest such digit, 2. Then use the two biggest of the other cards for the tens and ones: 8 and 7. The number is 287.', 'checked', '{"lint":[],"solve":{"answer":"287","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 500: hundreds 1 or 2; take 2, then 8, 7: 287.","run_id":"claude-code","at":"2026-10-19T01:34:15.428Z"}}', 'ai', NULL, NULL)
