INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8f7362c-3ae8-4274-9bd8-16d782a789cd', 'BA2.03', 3, 'choice', 'Adding three-digit numbers', 'A game has 469 points on level one and 375 points on level two. A bonus adds 30 more points. What is the total number of points?', '["864","874","884","774"]', '874', '469+375+30', 'Ones: 9 + 5 = 14. Write 4 and regroup 1 into the next place. Tens: 6 + 7 + 1 = 14. Write 4 and regroup 1 into the next place. Hundreds: 4 + 3 + 1 = 8. The sum is 844. Then 844 + 30 = 874.', 'checked', '{"lint":[],"solve":{"answer":"874","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"469 + 375 = 844, + 30 = 874.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba76bcba-6de3-4686-a93f-9ade6bc26c3a', 'BA2.03', 3, 'choice', 'Adding three-digit numbers', 'Raj walked 269 steps on Saturday and 342 steps on Sunday. Uma walked 326 steps on Saturday and 294 steps on Sunday. Who walked more steps in all?', '["Raj","They walked the same number","Uma","It is not possible to tell"]', 'Uma', NULL, 'Raj: 269 + 342 = 611. Uma: 326 + 294 = 620. Uma walked more.', 'checked', '{"lint":[],"solve":{"answer":"Uma","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Raj 269 + 342 = 611; Uma 326 + 294 = 620. Uma.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
