VALUES ('6d6d39ad-47b0-43a2-a239-090e26f170ad', 'BA2.03', 3, 'choice', 'Adding three-digit numbers', 'Which pair of numbers adds up to 500?', '["$203 + 297$","$203 + 307$","$193 + 297$","$213 + 307$"]', '$203 + 297$', NULL, '203 + 297 = 500. The other pairs make 510, 490, 520.', 'checked', '{"lint":[],"solve":{"answer":"$203 + 297$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"203+297=500; 213+307=520; 203+307=510; 193+297=490.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
