INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ed34525-4ed1-47d2-87bf-b67dbbb458d1', 'BA2.03', 3, 'choice', 'Mental addition strategies', 'Which sum is equal to $598 + 331$?', '["$600 + 331$","$600 + 329$","$596 + 335$","$600 + 333$"]', '$600 + 329$', NULL, '598 is 2 less than 600. Moving 2 from the second number to the first keeps the sum: 598 + 331 = 600 + 329.', 'checked', '{"lint":[],"solve":{"answer":"$600 + 329$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"598 + 331 = 929; 600+333=933, 600+329=929, 596+335=931, 600+331=931.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
