INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31a12700-14a1-42d1-9824-f1ae08754e60', 'BA2.03', 3, 'numeric', 'Mental addition strategies', '398 is 2 less than 400 and 397 is 3 less than 400. Use this to work out $398 + 397$.', '[]', '795', '398+397', '400 + 400 = 800. But we added 5 too many (2 and 3), so 800 - 5 = 795.', 'checked', '{"lint":[],"solve":{"answer":"795","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800 - 2 - 3 = 795.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
