INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a79207b-7647-4215-b4e7-02bbbe42c69c', 'BA2.03', 3, 'choice', 'Mental addition strategies', 'Break 232 into 200 + 30 + 2. Add the three parts to 237 one at a time. What number do you end with?', '["459","479","469","369"]', '469', '237+232', '237 + 200 = 437. 437 + 30 = 467. 467 + 2 = 469.', 'checked', '{"lint":[],"solve":{"answer":"469","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"237 + 200 = 437, + 30 = 467, + 2 = 469.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
