INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4129b65-ec7d-49ac-9943-97586dc08e19', 'BA2.03', 3, 'numeric', 'Mental addition strategies', 'You know that $400 + 400 = 800$. Use it to find $399 + 400$.', '[]', '799', '799', '399 is 1 less than 400, so 399 + 400 is 1 less than 400 + 400. 800 - 1 = 799.', 'checked', '{"lint":[],"solve":{"answer":"799","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800 - 1 = 799.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
