INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6293493-f64e-48e0-a7c1-0f4e825b17a4', 'BA2.03', 3, 'choice', 'Mental addition strategies', 'Which sum is the greatest? Think about how far each number is from 400.', '["$403 + 398$","$399 + 397$","$398 + 401$","$402 + 403$"]', '$402 + 403$', NULL, 'Each number is near 400, so compare the small differences. 402 + 403 = 805; 403 + 398 = 801; 399 + 397 = 796; 398 + 401 = 799. The greatest is 805.', 'checked', '{"lint":[],"solve":{"answer":"$402 + 403$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"805, 801, 796, 799. Greatest 402 + 403.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
