INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a345f13f-b70d-43e5-bc69-b2baaca6d4b3', 'BA2.03', 3, 'numeric', 'Mental addition strategies', '295 is close to 300 and 296 is close to 300. What is $295 + 296$?', '[]', '591', '295+296', '300 + 300 = 600. 295 is 5 less than 300 and 296 is 4 less than 300, so take away 5 + 4 = 9: 600 - 9 = 591.', 'checked', '{"lint":[],"solve":{"answer":"591","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 - 5 - 4 = 591.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
