INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31f65ac8-8068-499b-a3c5-bc9773fab417', 'BA2.03', 3, 'choice', 'Adding several numbers', 'What is $92 + 25 + 175 + 108$? Find numbers that add to a round number.', '["400","390","410","300"]', '400', '400', '108 + 92 = 200 and 25 + 175 = 200. So the total is 200 + 200 = 400.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"92 + 108 = 200, 25 + 175 = 200, total 400.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
