INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f876977-ef56-48b7-b479-e84872b3fe01', 'BA2.03', 3, 'numeric', 'Adding several numbers', 'What is $19 + 20 + 21 + 22 + 23$? The middle number may help.', '[]', '105', '5*21', 'The numbers are spread evenly around 21. 19 + 23 = 42, which is 2 groups of 21, and 20 + 22 is another 2 groups. With the middle 21, there are 5 groups of 21. Adding: 42 + 42 + 21 = 105.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 21 = 105.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
