VALUES ('35210951-2205-4710-82a8-879de2c119f4', 'BA2.03', 3, 'numeric', 'Adding several numbers', 'What is $8 + 18 + 28 + 38$?', '[]', '92', '92', '8 + 18 + 28 + 38: each number is 2 less than 10, 20, 30, 40. That total is 100, and we took away 8 in all: 100 - 8 = 92.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8+18+28+38 = 4 x 8 + 60 = 92.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
