INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c646886-f45e-4a6f-819a-957b22c2ce67', 'BA2.03', 3, 'choice', 'Adding several numbers', 'What is the sum of all the whole numbers from 31 to 40? (31, 32, 33, and so on up to 40.)', '["345","355","365","255"]', '355', '355', 'Pair the first with the last: 31 + 40 = 71. The next pair also makes 71, and so on. There are 5 pairs, so 355.', 'checked', '{"lint":[],"solve":{"answer":"355","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31..40: 10 x 30 + 55 = 355.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
