INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efb92f0a-32bd-44fb-9b86-cb7c164b7a48', 'BA2.03', 3, 'choice', 'Adding several numbers', 'A school has 145 students in Grade 1, 167 in Grade 2, 133 in Grade 3 and 155 in Grade 4. How many students are there in these four grades?', '["590","610","600","500"]', '600', '600', 'Find two numbers that make 300: 155 + 145 = 300 and 133 + 167 = 300. So the total is 300 + 300 = 600.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"145 + 155 = 300, 167 + 133 = 300, total 600.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
