INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78214943-0740-44b8-98f5-af7495761849', 'BA2.03', 3, 'numeric', 'Adding several numbers', 'Each of these numbers is close to 100: 101, 100, 102, 99, 98. What is their total?', '[]', '500', '500', 'Each is 100 plus or minus a little: the small amounts (-2, +1, -1, +2, 0) cancel out and add to 0. So the total is 5 x 100 = 500.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500 + 1 + 0 + 2 - 1 - 2 = 500.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
