INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6341a798-8520-477e-9675-0e1dc32b8252', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', 'A and B are digits. $3A + B9 = 96$ What is A + B?', '[]', '12', '12', 'Ones: A + 9 ends in 6, so A = 7. That makes 1 ten. Tens: 3 + B + 1 = 9, so B = 5. A + B = 7 + 5 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones: A + 9 ends in 6, so A = 7, carry 1. Tens: 3 + B + 1 = 9, B = 5. 37 + 59 = 96. A + B = 12.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eb1c47e-ea94-4eb5-a21e-ec9f71c43911', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', 'A and B are digits. $4A7 + 5B8 = 985$ What is A + B?', '[]', '7', '7', 'Ones: 7 + 8 = 15, so 1 ten is regrouped. Tens: A + B + 1 = 8, so A + B = 7. The hundreds work out without any further regrouping.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones 7 + 8 = 15, carry 1. Hundreds 4 + 5 = 9, so no carry from tens: A + B + 1 = 8, A + B = 7.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e930449-b65d-4724-8b87-4b01172fb5d8', 'BA2.03', 3, 'choice', 'Missing digits in a sum', 'One number ends in the digit 4. Another number ends in the digit 9. What is the ones digit of their sum?', '["13","5","4","3"]', '3', '3', '4 + 9 = 13. The ones digit of 13 is 3, because the 1 ten is regrouped into the tens place.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 9 = 13, ones digit 3.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
