INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ea70ced-27ff-4db6-893f-f3f935a58fae', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', 'A and B are digits. $7A4 + 2B = 731$ The first number has three digits and the second has two. What is A + B?', '[]', '7', '7', 'Ones: 4 + B ends in 1, so B = 7. Then A is in the tens place of the first number. Tens: A + 2 + 1 ends in 3, so A = 0. A + B = 0 + 7 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones: 4 + B ends in 1, B = 7, carry 1. Tens: A + 2 + 1 = 3, A = 0. 704 + 27 = 731. A + B = 7.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
