INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31166b32-7bcb-42c3-b4be-1e20c350c51a', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', '$5? + 47 > 100$ The ? is one digit. What is the smallest digit that can replace the ?', '[]', '4', '4', '5? + 47 is 97 + ?. For this to be more than 100, ? must be at least 4: 97 + 4 = 101. With 3 it makes 100, which is not more than 100.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 5? > 53. 53 + 47 = 100 (not >), 54 + 47 = 101. Smallest digit 4.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d57a8b-3fba-40d5-9c57-0cf0a8b6624c', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', 'The same digit goes in both boxes. $\square2 + \square9 = 91$ What digit is it?', '[]', '4', '4', 'The ones make 2 + 9 = 11, so 1 ten is regrouped. Tens: box + box + 1 = 9, so the two boxes make 8, and each box is 4. Check: 42 + 49 = 91.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones 2 + 9 = 11, carry 1; tens 2d + 1 = 9, d = 4. 42 + 49 = 91.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a033d07c-3d37-416b-8b3a-3791f088c10d', 'BA2.03', 3, 'choice', 'Addition stories and missing numbers', 'I think of a number. I add 45, then I add 15. The answer is 104. What number did I think of?', '["44","34","54","144"]', '44', '104-45-15', '45 + 15 = 60. So the number plus 60 is 104, and the number is 104 - 60 = 44.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"104 - 15 - 45 = 44.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
