INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9737cad6-c58d-42bf-899c-28996384cfe8', 'BA2.03', 3, 'numeric', 'Addition stories and missing numbers', 'How many ways can you write 10 as the sum of two whole numbers, each at least 1? Order does not matter, so 3 + 7 and 7 + 3 count as the same way.', '[]', '5', '5', 'List them from the smallest first number: 1 + 9, 2 + 8, 3 + 7, 4 + 6, 5 + 5. That is 5 ways.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+9, 2+8, 3+7, 4+6, 5+5: 5 ways.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('098dfb38-933b-4d3c-be0e-1e6a2c2c562b', 'BA2.03', 3, 'choice', 'Addition stories and missing numbers', 'Zoe has 55 blocks. Ned has 14 more than Zoe. Val has 17 more than Ned. How many blocks do the three children have in all?', '["200","210","220","110"]', '210', '55+69+86', 'Ned has 55 + 14 = 69. Val has 69 + 17 = 86. Total: 55 + 69 + 86 = 210.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zoe 55, Ned 69, Val 86. 55 + 69 + 86 = 210.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
