INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35ac1c4f-83c7-4d00-9863-8c7934ea8658', 'BA2.03', 3, 'choice', 'Addition stories and missing numbers', 'Two numbers add up to 106. One is 30 more than the other. What is the greater number?', '["38","78","68","76"]', '68', '68', 'If the numbers were equal, they would add to 106 - 30 = 76, so the smaller is 38. The greater is 38 + 30 = 68. Check: 38 + 68 = 106.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(106 + 30) / 2 = 68; 68 + 38 = 106.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
