INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5db358c4-1893-42f0-ab13-93503e0bc4f1', 'BA2.03', 3, 'numeric', 'Addition stories and missing numbers', 'A book has 132 pages. Ben read 40 pages on Monday and 62 pages on Tuesday. The sentence $40 + 62 + ? = 132$ shows the problem. How many pages are left to read?', '[]', '30', '132-40-62', '40 + 62 = 102. Then 102 + ? = 132, so ? = 132 - 102 = 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 + 62 = 102, 132 - 102 = 30.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
