VALUES ('cb717bb6-4167-4b41-831c-4ef2ae00fe00', 'BA2.04', 2, 'choice', 'Checking subtraction with addition', 'Which subtraction sentence can be checked with $57 + 36 = 93$?', '["$93 - 57 = 36$","$93 - 57 = 57$","$36 - 57 = 93$","$93 - 36 = 36$"]', '$93 - 57 = 36$', NULL, '57 + 36 = 93, so 93 - 57 = 36 (and 93 - 36 = 57). The other sentences are not true.', 'checked', '{"lint":[],"solve":{"answer":"$93 - 57 = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"57 + 36 = 93 checks 93 - 57 = 36.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
