VALUES ('2b151abc-a8ab-4314-8cc7-571881ec3e28', 'BA2.04', 2, 'numeric', 'Checking subtraction with addition', 'Jo subtracted two numbers. The number taken away was 12 and the difference was 69. What number did Jo start with?', '[]', '81', '69+12', 'To undo the subtraction, add: 69 + 12 = 81. Check: 81 - 12 = 69.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"69 + 12 = 81.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
