VALUES ('3ae22d9c-1466-425a-a3b0-468741471bdd', 'BA2.04', 3, 'choice', 'Regrouping and mental subtraction', 'Which subtraction has the same answer as $653 - 497$?', '["$656 - 497$","$653 - 500$","$650 - 500$","$656 - 500$"]', '$656 - 500$', NULL, 'Adding 3 to both numbers keeps the gap the same, and 500 is easy to take away. 653 - 497 = 656 - 500 = 156.', 'checked', '{"lint":[],"solve":{"answer":"$656 - 500$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"653 - 497 = 156. 653-500=153, 656-497=159, 650-500=150, 656-500=156.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
