VALUES ('b191cbe2-4b14-4070-9612-421fc34627b0', 'BA2.04', 3, 'choice', 'Checking subtraction with addition', 'A number minus 364 equals 311. What is the number? (Check your answer by subtracting.)', '["685","675","665","676"]', '675', '364+311', 'The number is the amount taken away plus what is left: 364 + 311 = 675. Check: 675 - 364 = 311.', 'checked', '{"lint":[],"solve":{"answer":"675","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"311 + 364 = 675; 675 - 364 = 311.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
