INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62686583-5eca-4de5-8757-401d954806bd', 'BA2.04', 3, 'numeric', 'Checking subtraction with addition', 'I think of a number and take away 35. I get 74. What number did I think of?', '[]', '109', '35+74', 'Undo the subtraction by adding: 74 + 35 = 109. Check: 109 - 35 = 74.', 'checked', '{"lint":[],"solve":{"answer":"109","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"74 + 35 = 109.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
