VALUES ('6942db39-7365-4ebc-96e7-03235e00db51', 'BA2.04', 3, 'choice', 'Checking subtraction with addition', 'Which number sentence is NOT in the same fact family as $39 + 40 = 79$?', '["$79 - 40 = 39$","$79 - 39 = 40$","$79 + 40 = 39$","$40 + 39 = 79$"]', '$79 + 40 = 39$', NULL, '39 + 40 = 79 goes with 40 + 39 = 79, 79 - 39 = 40 and 79 - 40 = 39. But 79 + 40 = 119, not 39, so that sentence is not in the family.', 'checked', '{"lint":[],"solve":{"answer":"$79 + 40 = 39$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"79 + 40 = 39 is false and not in the family.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
