VALUES ('b154dc27-8cf5-4f80-a910-1b1981632609', 'BA2.04', 3, 'choice', 'Checking subtraction with addition', 'The sum of two numbers is 800. One of them is 409. What is the other?', '["391","401","381","392"]', '391', '800-409', 'The other number is 800 - 409 = 391. Check: 409 + 391 = 800.', 'checked', '{"lint":[],"solve":{"answer":"391","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800 - 409 = 391.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
