INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cb3d452-8260-4cea-8fae-5e7d55565c41', 'BA2.04', 3, 'numeric', 'Missing digits in a difference', 'A and B are digits. $3A6 - 18B = 159$ What is A + B?', '[]', '11', '11', 'Ones: 6 is less than B, so regroup: 16 - B = 9, so B = 7. That used 1 ten. Tens: (A - 1) + 10 - 8 = 5, so A = 4. A + B = 4 + 7 = 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3A6 = 159 + 18B. Ones 9 + B ends 6: B = 7, carry 1. Tens 5 + 8 + 1 = 14: A = 4, carry 1. Hundreds 1+1+1 = 3. 346 - 187 = 159. A + B = 11.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
