INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1dd99aa-776d-4949-9478-6a262ae3845c', 'BA2.05', 2, 'choice', 'Equal and unequal expressions', 'Work out both sides of each statement. Which one has the correct symbol?', '["$25 + 25 < 55 - 27$","$26 + 38 > 36 - 19$","$34 + 20 = 23 - 5$","$30 + 11 = 32 - 20$"]', '$26 + 38 > 36 - 19$', NULL, 'Work out both sides of each statement and compare. Only 26 + 38 > 36 - 19 is correct: 64 and 17.', 'checked', '{"lint":[],"solve":{"answer":"$26 + 38 > 36 - 19$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"41 vs 12 no; 54 vs 18 no; 64 > 17 yes; 50 < 28 no.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
