INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e2ed9a-970f-4905-bf70-b504acae793a', 'BA2.05', 2, 'numeric', 'Equal and unequal expressions', 'What is the greatest whole number that can go in the box to make this true? $\square + 21 < 41$', '[]', '19', '41-21-1', '41 - 21 = 20. If the box were 20, the two sides would be equal, so the box must be less than that. The greatest whole number is 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"?<41-21=20, greatest whole number 19.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
