INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d708fbb7-8b3f-4afa-afa3-758a00b3c99f', 'BA2.05', 2, 'choice', 'Equal and unequal expressions', 'Which expression is equal to $35 + 20 - 5$?', '["$35 - 20 + 5$","$35 - 20 - 5$","$35 - 5 + 20$","$35 + 20 + 5$"]', '$35 - 5 + 20$', NULL, 'You can do the adding and taking away in a different order and get the same answer. 35 - 5 + 20 = 50, just like 35 + 20 - 5.', 'checked', '{"lint":[],"solve":{"answer":"$35 - 5 + 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35+20-5=50. Options: 60, 10, 50, 20.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
