VALUES ('c02b461e-b339-46de-a1e8-5d46a338dc32', 'BA2.05', 2, 'choice', 'Equal and unequal expressions', 'Three of these four statements are true. Which one is NOT true?', '["$11 + 26 = 14 + 25$","$20 + 11 = 21 + 10$","$18 + 32 = 13 + 37$","$25 + 33 = 20 + 38$"]', '$11 + 26 = 14 + 25$', NULL, 'Work out both sides. In the three true statements both sides have the same total. In 11 + 26 = 14 + 25 the two sides are different.', 'checked', '{"lint":[],"solve":{"answer":"$11 + 26 = 14 + 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31=31; 37 vs 39 not true; 50=50; 58=58.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
