VALUES ('a83f9c55-8a60-4b1e-8ad5-c60fa111e623', 'BA2.05', 2, 'choice', 'Keeping a difference the same', 'Which subtraction is NOT equal to $62 - 17$?', '["$67 - 22$","$66 - 21$","$65 - 20$","$64 - 18$"]', '$64 - 18$', NULL, 'Adding the same number to both numbers keeps the difference at 45. In 64 - 18 a different amount was added to each number, so the answer changes to 46.', 'checked', '{"lint":[],"solve":{"answer":"$64 - 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62-17=45. 66-21=45, 65-20=45, 64-18=46, 67-22=45.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
