INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('895a5053-707e-4089-8f12-c362d39d9762', 'BA2.05', 2, 'numeric', 'Keeping a difference the same', 'Kim wants to keep the answer of $78 - 45$ the same. Kim adds 5 to 78. What should the second number be now?', '[]', '50', '45+5', 'To keep the difference, add the same 5 to the second number too: 45 + 5 = 50. Check: 83 - 50 = 33.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 5 to both: 45+5=50 (83-50=33=78-45).","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
