VALUES ('728b2d49-7fb6-474e-8dfd-2b66693aa25e', 'BA2.05', 2, 'numeric', 'Balancing an equation', 'What number goes in the box? $32 - 16 = \square - 10$', '[]', '26', '32-16+10', '32 - 16 = 16. The box minus 10 must also be 16, so the box is 16 + 10 = 26.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32-16=16, ?-10=16, so 26.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
