INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfc41583-10f9-4eda-9a90-29db21073bad', 'BA2.05', 2, 'numeric', 'Balancing an equation', 'A top shelf has 34 books and a middle shelf has 21 books. A bottom shelf has 27 books. The library puts more books on the bottom shelf until it has as many books as the other two shelves together. How many books are added to the bottom shelf?', '[]', '28', '34+21-27', 'The other two shelves together hold 34 + 21 = 55 books. The bottom shelf has 27, so it needs 55 - 27 = 28 more.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34+21=55, 55-27=28.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
