VALUES ('a0e1e67f-a519-402a-9744-f3be4aa07800', 'BA2.05', 3, 'choice', 'Evaluating addition and subtraction expressions', 'Find the value of $92 - 15 + 35 - 34 + 24$.', '["102","112","92","101"]', '102', '92 - 15 + 35 - 34 + 24', 'Go from left to right: 92 - 15 = 77; + 35 = 112; - 34 = 78; + 24 = 102.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"92-15=77, +35=112, -34=78, +24=102.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
