INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('198c53e2-8c95-4335-83a7-78109f0d8a38', 'BA2.05', 3, 'numeric', 'Evaluating addition and subtraction expressions', 'Tom thinks of a number. Tom adds 27, then subtracts 19, and gets 31. What number did Tom think of?', '[]', '23', '31-27+19', 'Work backwards: undo subtracting 19 by adding 19: 31 + 19 = 50. Undo adding 27 by subtracting 27: 50 - 27 = 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Work back: 31+19=50, 50-27=23.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
