INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c1466e0-789e-47ec-b2ae-283c213f73f7', 'BA2.05', 3, 'choice', 'Parentheses in expressions', 'Three of these expressions have the same value. Which one has a different value?', '["$99 - 20 - 10$","$99 - (20 - 10)$","$(99 - 20) - 10$","$99 - (10 + 20)$"]', '$99 - (20 - 10)$', NULL, 'The three others are 69: taking away 20 and 10 one after the other, or together. But 99 - (20 - 10) = 89, because only 10 is taken away.', 'checked', '{"lint":[],"solve":{"answer":"$99 - (20 - 10)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"99-(20-10)=89; the other three are 69.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c0de818-a308-4a9d-ad25-64c14931908d', 'BA2.05', 3, 'numeric', 'Parentheses in expressions', 'Work out $(42 + 31) - (42 - 9)$.', '[]', '40', '(42 + 31) - (42 - 9)', '42 + 31 = 73 and 42 - 9 = 33. Then 73 - 33 = 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"73-33=40.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
