INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e18fdb53-302c-4a66-b54a-7c70ff8fe39d', 'BA2.05', 3, 'numeric', 'Parentheses in expressions', 'What number goes in the box? $74 - (35 - \square) = 56$', '[]', '17', '35-(74-56)', '74 - 56 = 18, so the parentheses must equal 18. 35 minus the box is 18, so the box is 35 - 18 = 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"74-56=18, 35-?=18, so 17.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
