INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e56968c6-b28e-474b-90d2-59d8a3c77d5f', 'BA2.05', 3, 'choice', 'Parentheses in expressions', 'Each expression uses the numbers 72, 25, 10 and 3 in that order, with different parentheses. Which one has the value 60?', '["$(72 - 25) - (10 - 3)$","$72 - (25 - 10) - 3$","$72 - (25 - 10 - 3)$","$72 - 25 - 10 - 3$"]', '$72 - (25 - 10 - 3)$', NULL, 'Work out each one: (72 - 25) - (10 - 3) = 40; 72 - (25 - 10) - 3 = 54; 72 - (25 - 10 - 3) = 60; 72 - 25 - 10 - 3 = 34. Only 72 - (25 - 10 - 3) gives 60.', 'checked', '{"lint":[],"solve":{"answer":"$72 - (25 - 10 - 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(47)-(7)=40; 72-(12)=60; 72-15-3=54; 72-38=34.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0c9f91-c3fe-47b7-930b-79381c1924b5', 'BA2.05', 3, 'numeric', 'Parentheses in expressions', 'Ned can write $37 - 13 - 4$ with parentheses as $(37 - 13) - 4$ or as $37 - (13 - 4)$. What is the difference between the two answers?', '[]', '8', '2*4', '(37 - 13) - 4 = 20. 37 - (13 - 4) = 28. The second is bigger by 28 - 20 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(37-13)-4=20; 37-(13-4)=37-9=28; difference 8.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ddad204-17fa-4fbf-9cd7-de495cc4e969', 'BA2.05', 3, 'numeric', 'Equal and unequal expressions', 'How many whole numbers (counting 0) can go in the box to make this true? $\square + 13 < 23$', '[]', '10', '10', 'The box can be 0, 1, 2, and so on, up to 9, because 9 + 13 = 22, but 10 + 13 = 23 is not less than 23. That is 10 numbers.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"?<10: 0 through 9, ten numbers.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
