INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3356870-374e-4bdd-96c0-d7c2a3c685f0', 'BA2.05', 3, 'choice', 'Equal and unequal expressions', 'Each expression below uses the numbers 60, 30 and 6. Which one has the greatest value?', '["$60 - (30 + 6)$","$60 - (30 - 6)$","$60 - 30 - 6$","$60 + (30 - 6)$"]', '$60 + (30 - 6)$', NULL, 'Work out each one: 60 - (30 + 6) = 24; 60 - (30 - 6) = 36; 60 + (30 - 6) = 84; 60 - 30 - 6 = 24. The greatest is 84.', 'checked', '{"lint":[],"solve":{"answer":"$60 + (30 - 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60+24=84; 24; 24; 60-24=36. Greatest 84.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d765bab-d41c-437c-937e-91a1531d8c4e', 'BA2.05', 3, 'numeric', 'Equal and unequal expressions', 'Dee writes six expressions: $44 + 3$; $42 + (8 - 3)$; $45 + 2$; $42 + (9 - 4)$; $45 + (4 - 3)$; $(57 - 4) - 5$. How many of them are equal to 47?', '[]', '4', NULL, 'Work out each expression and count the ones equal to 47. There are 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47; 47; 47; 47; 46; 48. Four.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2af6f85-9cd4-4561-9ab0-8579db404038', 'BA2.05', 3, 'choice', 'Equal and unequal expressions', 'Which number makes both of these true? $\square + 9 > 17$ and $\square - 4 < 6$', '["9","8","10","7"]', '9', '9', 'The first needs the box to be more than 8 (since 8 + 9 = 17 is not more than 17). The second needs it to be less than 10. The only whole number between 8 and 10 is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"?>8 and ?<10, so 9.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('836b5677-e273-4c9c-8724-4379674594fe', 'BA2.05', 3, 'numeric', 'Equal and unequal expressions', 'By how much is $69 - 12$ greater than $34 + 15 - 10$?', '[]', '18', '18', '34 + 15 - 10 = 39 and 69 - 12 = 57. The difference is 57 - 39 = 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"69-12=57, 34+15-10=39, 57-39=18.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
