INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79c47b41-53d5-40a7-a025-cfc912bf3dad', 'BA2.05', 3, 'choice', 'Equal and unequal expressions', 'Mia knows that $20 + 21 = 12 + 29$. Which statement must then be true?', '["$20 + (21 + 2) = 12 + 29$","$(20 + 1) + 21 > 12 + 29$","$(20 - 3) + 21 > 12 + 29$","$20 + 21 < (12 - 1) + 29$"]', '$(20 + 1) + 21 > 12 + 29$', NULL, 'Both sides of the fact equal 41. Making the left side 1 bigger gives 42, which is more than 41. The others do not hold.', 'checked', '{"lint":[],"solve":{"answer":"$(20 + 1) + 21 > 12 + 29$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both sides 41. (21)+21=42>41 true; 43=41 false; 41<40 false; 38>41 false.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b34836b-7767-4532-9206-9fb9e4c9422f', 'BA2.05', 3, 'numeric', 'Keeping a difference the same', 'Mia has two towers. The first has 44 blocks and the second has 31. Mia adds 15 blocks to the first tower and 7 blocks to the second. How many more blocks does the first tower have than the second now?', '[]', '21', '(44-31)+15-7', 'Before: 44 - 31 = 13 more. Now the first has 59 and the second has 38. 59 - 38 = 21.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"44+15=59, 31+7=38, 59-38=21.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72fa77c0-6f4a-4b2f-8732-4c2a0c7ae5e5', 'BA2.05', 3, 'numeric', 'Keeping a difference the same', 'Add 5 to both numbers to make $171 - 95$ easier. What is the answer?', '[]', '76', '171-95', '171 + 5 = 176 and 95 + 5 = 100. 176 - 100 = 76, and the difference has not changed.', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"176-100=76.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
