INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c38053e-689d-46de-9c38-4b1d7c47dc77', 'BA2.05', 3, 'choice', 'Keeping a difference the same', 'Which subtraction that starts with 100 has the same answer as $76 - 29$?', '["$100 - 29$","$100 - 47$","$100 - 53$","$100 - 56$"]', '$100 - 53$', NULL, '76 + 24 = 100, so add 24 to 29 too: 29 + 24 = 53. Then 100 - 53 = 47.', 'checked', '{"lint":[],"solve":{"answer":"$100 - 53$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"76-29=47; 100-53=47.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
