INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99f69691-17bd-4a9d-9e89-99c81c84343b', 'BA2.05', 3, 'numeric', 'Keeping a difference the same', 'Dee is 8 years older than Kim. In 6 years, Kim will be 16. How old is Dee now?', '[]', '18', '10+8', 'Kim is now 16 - 6 = 10. Dee is always 8 years older, so Dee is 10 + 8 = 18 now.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kim now 16-6=10, Dee 10+8=18.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
