INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee311047-d035-4578-80fc-e40cf67a6962', 'BA2.05', 3, 'numeric', 'Keeping a difference the same', 'The difference between two numbers is 30. The smaller number is 41. Both numbers are made 7 bigger. What is the bigger number now?', '[]', '78', '41+30+7', 'The bigger number was 41 + 30 = 71. Now it is 71 + 7 = 78. (The smaller is 48, and the difference is still 30.)', 'checked', '{"lint":[],"solve":{"answer":"78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bigger 41+30=71, plus 7 = 78.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('310d192b-9789-4941-b17f-837bd18fbc8c', 'BA2.05', 3, 'choice', 'Balancing an equation', 'What number goes in the box? $36 + 38 = 15 + 23 + \square$', '["36","46","26","35"]', '36', '36+38-15-23', 'The left side is 74. On the right, 15 + 23 = 38, so the box is 74 - 38 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36+38=74, 15+23=38, 74-38=36.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
