INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5007a5b6-c154-45ac-ba15-7758316e052f', 'BA2.05', 3, 'numeric', 'Balancing an equation', 'A balance scale is level. The left pan holds weights of 28 g, 23 g and 20 g. The right pan holds weights of 39 g and 16 g and one more weight. How many grams does the one more weight have?', '[]', '16', '28+23+20-39-16', 'Left pan: 28 + 23 + 20 = 71 g. Right pan so far: 39 + 16 = 55 g. The missing weight is 71 - 55 = 16 g.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28+23+20=71, 39+16=55, 71-55=16.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
