INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('556e96ea-7a43-423e-8a64-f4fc2cf42fb8', 'BA2.05', 3, 'numeric', 'Balancing an equation', 'Pia has three piggy banks with 39, 26 and 22 coins. Quin has two piggy banks with 42 and 23 coins, and a third piggy bank. Pia and Quin have the same number of coins in all. How many coins are in Quin''s third piggy bank?', '[]', '22', '39+26+22-42-23', 'Pia has 39 + 26 + 22 = 87 coins. Quin''s first two banks hold 42 + 23 = 65. The third holds 87 - 65 = 22.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"39+26+22=87, 42+23=65, 87-65=22.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
