INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5615cd0a-881e-41ca-9063-0337ab4fbe97', 'BA2.06', 3, 'choice', 'Organized lists', 'A stair has 5 steps. Ivy goes up it by taking one step or two steps at a time, and she must land exactly on the top step. How many different ways can she climb the stair?', '["8","9","7","10"]', '8', '8', 'Use the pattern: 1 step has 1 way, 2 steps have 2 ways, 3 steps have 3, 4 steps have 5. Each new count is the two before it added: 5 steps have 3 + 5 = 8 ways.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ways(n)=Ways(n-1)+Ways(n-2): 1,2,3,5,8.","run_id":"claude-code","at":"2026-10-19T01:31:31.193Z"}}', 'ai', NULL, NULL)
