INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a2fbf70-ba7f-4a06-9605-f0bc2b7534cb', 'BA2.06', 3, 'choice', 'Organized lists', 'Using the digits 4, 5 and 6 once each, you can make 3-digit numbers. How many of those numbers are bigger than 500?', '["3","4","2","6"]', '4', '4', 'All the numbers are 456, 465, 546, 564, 645 and 654. The ones bigger than 500 are 546, 564, 645 and 654. That is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"546, 564, 645, 654: 4.","run_id":"claude-code","at":"2026-10-19T01:31:31.193Z"}}', 'ai', NULL, NULL)
