INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c8dc8ac-a1cd-41a9-a777-a012baf84517', 'BA2.06', 3, 'choice', 'Organized lists', 'A piggy bank holds four coins, worth 1 cent, 2 cents, 5 cents and 10 cents. If Sam takes out any group of at least one of these coins, how many different amounts of money can Sam get?', '["16","14","15","17"]', '15', '15', 'There are 15 ways to pick one or more of four coins. The totals are 1, 2, 5, 10, 3, 6, 11, 7, 12, 15, 8, 13, 16, 17 and 18. No two are the same, so there are 15 different totals.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 non-empty groups; sums 1,2,3,5,6,7,8,10,11,12,13,15,16,17,18 all different: 15.","run_id":"claude-code","at":"2026-10-19T01:31:31.193Z"}}', 'ai', NULL, NULL)
