INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd3eabe3-e68e-4a7a-970f-f5ff2311e79f', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'Which sum is an odd number?', '["$24 + 36$","$38 + 27$","$51 + 49$","$62 + 18$"]', '$38 + 27$', NULL, '38 is even and 27 is odd, so the sum is odd (65). The other sums add two evens (24 + 36, 62 + 18) or two odds (51 + 49), so they are even.', 'checked', '{"lint":[],"solve":{"answer":"$38 + 27$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38+27=65 odd; 62+18=80, 51+49=100, 24+36=60 even.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
