INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e8fd2b9-7b77-4595-bb57-de34462da585', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'Use the rules for odd and even numbers, without adding. Which of these sums is odd?', '["$147 + 253$","$318 + 462$","$130 + 271$","$205 + 119$"]', '$130 + 271$', NULL, '130 is even and 271 is odd, so their sum is odd. 147 + 253 and 205 + 119 are odd plus odd, which is even. 318 + 462 is even plus even, which is even.', 'checked', '{"lint":[],"solve":{"answer":"$130 + 271$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"odd+odd=even (205+119, 147+253); even+even=even (318+462); even+odd=odd (130+271).","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b196affc-2d31-4456-b69c-6a2c32ee03a8', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'Which difference is an even number?', '["$85 - 42$","$90 - 33$","$64 - 19$","$77 - 31$"]', '$77 - 31$', NULL, '77 - 31 = 46, which is even. Odd minus odd is even. The other three each take an odd number from an even number or an even number from an odd number, so they are odd.', 'checked', '{"lint":[],"solve":{"answer":"$77 - 31$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90-33=57, 77-31=46, 64-19=45, 85-42=43. Only 46 is even.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
