INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dd7923b-699e-4d4c-883d-75719b4121db', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'You add three odd numbers together, such as $3 + 7 + 9$. The total is...', '["always odd","always even","sometimes odd and sometimes even","neither odd nor even"]', 'always odd', NULL, 'Odd plus odd is even. Then even plus the third odd number is odd. For example, 3 + 7 + 9 = 19.', 'checked', '{"lint":[],"solve":{"answer":"always odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"odd+odd=even, even+odd=odd. Three odds sum to odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
