INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cf73bac-804b-4cc9-b911-717db5dea171', 'BA2.09', 2, 'numeric', 'Odd or even sums and differences', 'How many of these sums are odd? $12 + 35$, $48 + 26$, $57 + 19$, $63 + 40$, $29 + 31$, $74 + 85$', '[]', '3', '3', '12 + 35 = 47 (odd). 48 + 26 = 74 (even). 57 + 19 = 76 (even). 63 + 40 = 103 (odd). 29 + 31 = 60 (even). 74 + 85 = 159 (odd). Three sums are odd.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12+35 odd, 48+26 even, 57+19 even, 63+40 odd, 29+31 even, 74+85 odd -> 3 odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
