INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9de12f7-0a8a-414f-b24f-e28e3e88a186', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'Sam says that $28 + 15$ is an even number. Why is Sam wrong?', '["28 is even and 15 is odd, so the sum is even","28 is even and 15 is odd, so the sum is odd","Two numbers added together always make an odd number","The answer ends in 3, and numbers ending in 3 are even"]', '28 is even and 15 is odd, so the sum is odd', NULL, 'Even plus odd is odd. 28 + 15 = 43, which is odd. It is not true that every sum is odd, and numbers ending in 3 are odd.', 'checked', '{"lint":[],"solve":{"answer":"28 is even and 15 is odd, so the sum is odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"even + odd = odd (28+15=43).","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
