INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7189595-00c5-444d-aa56-46ca0b4456f1', 'BA2.09', 2, 'choice', 'Odd or even sums and differences', 'Two numbers add up to 21. One of them is even. What can you say about the other number?', '["It must be even","It must be 10","It must be odd","It could be odd or even"]', 'It must be odd', NULL, '21 is odd. An even number plus an even number is even, so the other number cannot be even. It must be odd. For example, 8 + 13 = 21.', 'checked', '{"lint":[],"solve":{"answer":"It must be odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 is odd; odd - even = odd, so the other number must be odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
