INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ea26d3a-54e2-4f93-b6a8-9785021f86ef', 'BA2.09', 2, 'numeric', 'Odd and even patterns', 'Ben counts 15, 16, 17, 18, and so on, saying every number. Every other number he says is even. What is the 10th number he says?', '[]', '24', '15+9', 'The 10th number is 9 more than the first. 15 + 9 = 24. (24 is even, as it should be: the 2nd, 4th, 6th, ... numbers are even.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1st is 15, so 10th is 15 + 9 = 24.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
