INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51f557a9-7d9f-4086-aab5-1a531f7dea2b', 'BA2.09', 2, 'choice', 'Odd and even patterns', 'A list begins at 3 and always has only odd numbers. Which rule could make it?', '["Add 2 each time","Add 1 each time","Add 3 each time","Add 5 each time"]', 'Add 2 each time', NULL, 'Adding 2 keeps the number odd: 3, 5, 7, 9. Adding 1, 3 or 5 swaps odd and even each time: 3, 4, 5 or 3, 6, 9 or 3, 8, 13.', 'checked', '{"lint":[],"solve":{"answer":"Add 2 each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd + 2 stays odd: 3,5,7. Add 1 gives 4; add 3 gives 6; add 5 gives 8.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
