INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b2acb6a-8946-47f4-afc4-cf892d752c02', 'BA2.09', 3, 'choice', 'Odd and even numbers', 'How many 2-digit numbers have a tens digit that is even and a ones digit that is even?', '["$16$","$25$","$20$","$10$"]', '$20$', '4*5', 'The tens digit can be 2, 4, 6 or 8 (not 0). The ones digit can be 0, 2, 4, 6 or 8. That makes 4 groups of 5, which is 20 numbers.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tens digit 2,4,6,8 (4 ways; not 0); ones digit 0,2,4,6,8 (5 ways). 20.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
