INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eac235ed-084f-4cb6-b884-87cc5c13b8b8', 'BA2.09', 3, 'choice', 'Odd and even numbers', 'How many different 3-digit even numbers can you make using each of the digits 1, 4 and 6 exactly once?', '["$2$","$3$","$6$","$4$"]', '$4$', '4', 'The number must end in 4 or 6. Ending in 4: 164 and 614. Ending in 6: 146 and 416. That makes 4 numbers.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"End in 4: 164, 614. End in 6: 146, 416. Total 4.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
