INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f751731-f0f8-49cb-9ad6-ef9eca85f4d7', 'BA2.09', 3, 'choice', 'Odd and even numbers', 'The number 3,000 is even. Which of these is the odd number right before 3,000?', '["$2{,}999$","$2{,}998$","$3{,}001$","$2{,}997$"]', '$2{,}999$', NULL, 'The number right before 3,000 is 2,999, which ends in 9 and is odd. 2,998 is even, 3,001 comes after 3,000, and 2,997 is two numbers before.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}999$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The number right before 3,000 is 2,999, which is odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
