INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4a41b03-3bf0-415c-995b-70cae41a7bf6', 'BA2.09', 3, 'numeric', 'Odd and even numbers', 'I am a 2-digit number. My digits add up to 11. My tens digit is 3 more than my ones digit. What number am I?', '[]', '74', '74', 'Try ones digit 4: the tens digit is 7, and 7 + 4 = 11. So the number is 74. (Check other ones digits: 3 gives 63, sum 9, and 5 gives 85, sum 13.)', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t + o = 11, t = o + 3 -> 2o = 8, o = 4, t = 7: 74.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
