INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd50f0fd-4d97-477d-a1c4-d3adbd6d64f4', 'BA2.09', 3, 'numeric', 'Odd and even numbers', 'Mia uses the digit cards 5, 8 and 0 to make 3-digit numbers (0 cannot be first). How many of the numbers she can make are even?', '[]', '3', '3', 'The numbers are 508, 580, 805 and 850. Only 805 is odd, so 3 are even.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbers: 508, 580, 805, 850. Even: 508, 580, 850 -> 3.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
