INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9db35ff6-421f-4fe6-836e-aaf338e52737', 'BA2.09', 3, 'choice', 'Odd or even sums and differences', 'Four odd numbers are added together. Then one more odd number is added. The final total is...', '["always even","always odd","sometimes odd and sometimes even","never a whole number"]', 'always odd', NULL, 'Odd + odd = even. So four odd numbers make two evens, which make an even number. Even plus one more odd is odd.', 'checked', '{"lint":[],"solve":{"answer":"always odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Five odd numbers: four odds sum to even, plus odd -> odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
