INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8dd7df8-5769-444b-b00f-1fb7297f153c', 'BA2.09', 3, 'choice', 'Odd or even sums and differences', 'Which of these rules is NOT true?', '["odd + odd = even","even - even = even","odd - odd = odd","even + odd = odd"]', 'odd - odd = odd', NULL, 'For example 9 - 3 = 6, which is even. So odd - odd = odd is false. The other three rules are always true.', 'checked', '{"lint":[],"solve":{"answer":"odd - odd = odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"odd - odd = even (e.g. 7-3=4), so that rule is false; others are true.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
