INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5affcabf-916f-4c17-a6f0-39a17bef0d7d', 'BA2.09', 3, 'choice', 'Odd or even sums and differences', 'Three numbers add up to 30. Two of the numbers are odd. What can you say about the third number?', '["It must be odd","It could be odd or even","It must be 0","It must be even"]', 'It must be even', NULL, 'The two odd numbers add to an even number. Even plus the third number must be 30, which is even, so the third number must be even.', 'checked', '{"lint":[],"solve":{"answer":"It must be even","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"odd + odd = even; 30 - even = even.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
