INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22131f25-e125-4858-b363-a7c1e4bcc66d', 'BA2.09', 3, 'numeric', 'Odd or even sums and differences', 'Three different odd numbers, each less than 10, add up to 21. What is the smallest of the three numbers?', '[]', '5', '5', 'The biggest odd numbers under 10 are 9, 7 and 5, and they add to 21. Any other three different odd numbers under 10 have a smaller total, so the numbers must be 5, 7 and 9. The smallest is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd numbers below 10: 1,3,5,7,9. Triples of different ones summing to 21: 5+7+9 only (1+9+? needs 11; 3+? needs two summing to 18 = 9+9). Smallest 5.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1259b6b1-9df3-4e61-9b48-f8382327047f', 'BA2.09', 3, 'numeric', 'Odd or even sums and differences', 'Pick two different numbers from this list: $3, 8, 11, 14$. In how many different pairs is the sum even?', '[]', '2', '2', 'There are 6 pairs. 3 + 11 = 14 and 8 + 14 = 22 are even (odd + odd and even + even). The other four pairs add an odd and an even number, so they are odd. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs: 3+8=11, 3+11=14, 3+14=17, 8+11=19, 8+14=22, 11+14=25. Even: 14, 22 -> 2.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6c620e7-906d-445c-a713-22a902cfd163', 'BA2.09', 3, 'numeric', 'Odd or even sums and differences', 'Ana picks two numbers from $6, 9, 12, 17$. Their sum is odd and less than 25. What is the largest sum she can get?', '[]', '23', '6+17', 'An odd sum needs one even and one odd number. The pairs are 6 + 9 = 15, 6 + 17 = 23, 12 + 9 = 21 and 12 + 17 = 29. The sums less than 25 are 15, 23 and 21, and the largest is 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd sums need one even, one odd: 6+9=15, 6+17=23, 12+9=21, 12+17=29. Under 25: largest 23.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a21021f4-cb3a-4113-8ebb-d9bcd3dc8ef6', 'BA2.09', 3, 'choice', 'Odd or even sums and differences', 'Fay thinks of an odd number and does one thing to it. Which one is sure to give an even number?', '["Add 1","Add 2","Subtract 4","Add 6"]', 'Add 1', NULL, 'Odd plus an odd number is even, and 1 is odd. Adding 2, 6 or subtracting 4 (all even) leaves an odd number odd.', 'checked', '{"lint":[],"solve":{"answer":"Add 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"odd + 1 = even; odd - 4, odd + 6, odd + 2 stay odd.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
