INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77712a60-2d15-4fff-a972-d7ee502e4d83', 'BA2.09', 3, 'choice', 'Counting odd or even numbers in a range', 'How many odd numbers are between 99 and 199?', '["$49$","$48$","$50$","$99$"]', '$49$', '49', 'The odd numbers are 101, 103, ..., 197. From 101 to 197 is 96 apart, and it goes up by 2: 96 / 2 = 48 steps, so 48 + 1 = 49 numbers.', 'checked', '{"lint":[],"solve":{"answer":"$49$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd numbers strictly between 99 and 199: 101, ..., 197 -> (197-101)/2+1 = 49.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
