INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e76e7983-4d15-4104-9490-9a9ce90ad1ae', 'BA2.09', 3, 'choice', 'Counting odd or even numbers in a range', 'Which sentence is true about the whole numbers from 1 to 51?', '["The numbers of odd and even numbers are the same","There is one more even number than odd numbers","There are 5 more odd numbers than even numbers","There is one more odd number than even numbers"]', 'There is one more odd number than even numbers', NULL, 'From 1 to 51 there are 26 odd numbers (1, 3, ..., 51) and 25 even numbers (2, 4, ..., 50). So there is one more odd number.', 'checked', '{"lint":[],"solve":{"answer":"There is one more odd number than even numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-51: 26 odd, 25 even.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
