INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2fe593b-8511-44c0-bdb8-2d140e11f6b1', 'BA2.09', 3, 'numeric', 'Odd and even patterns', 'Zoe puts out cards in this pattern: odd, odd, even, odd, odd, even, and so on. She puts out 20 cards. How many of them are even?', '[]', '6', '6', 'The pattern repeats in groups of 3, with one even card in each group. 20 cards make 6 full groups (18 cards) and 2 more cards. Those 2 are both odd. So there are 6 even cards.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Groups of 3 (odd, odd, even): 20 = 6 groups + 2 (odd, odd). 6 even.","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
