INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a3ef619-3e20-466c-baf4-cd4092689eec', 'BA2.11', 1, 'choice', 'Regrouping and place value in the algorithm', 'To work out $64 - 26$, the ones digit 4 is smaller than 6. What do you do?', '["Subtract 4 from 6 instead","Regroup 1 ten as 10 ones, giving 14 ones","Regroup 1 one as 10 tens, giving 16 tens","Add 10 to the tens digit 6"]', 'Regroup 1 ten as 10 ones, giving 14 ones', NULL, '4 is too small to take 6 away. Take 1 ten from the tens and break it into 10 ones: 4 + 10 = 14 ones. Then 14 - 6 = 8.', 'checked', '{"lint":[],"solve":{"answer":"Regroup 1 ten as 10 ones, giving 14 ones","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Borrow a ten: 64 = 5 tens 14 ones.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
