VALUES ('e30afd8d-c814-4f20-9b46-ad426243a374', 'BA2.11', 2, 'choice', 'Regrouping and place value in the algorithm', 'How many times do you regroup when you add $131 + 686$?', '["1","2","0","3"]', '1', '1', 'Ones: 1 + 6 = 7. Tens: 3 + 8 = 11, so write 1 and regroup 1 to the next place. Hundreds: 1 + 6 + 1 = 8. The sum is 817. Regrouping happened 1 time.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+6=7, 3+8=11 (regroup), 1+6+1=8. Once. 817.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
