INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d45fc91-f314-4cfe-9284-b146a3a2182d', 'BA2.11', 2, 'choice', 'Regrouping and place value in the algorithm', 'Which of these subtractions needs you to regroup exactly twice?', '["$775 - 712$","$330 - 190$","$551 - 275$","$617 - 471$"]', '$551 - 275$', NULL, 'Check each column. 551 - 275 needs a regroup in the ones and in the tens, so twice. The other subtractions need to regroup fewer times.', 'checked', '{"lint":[],"solve":{"answer":"$551 - 275$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"551-275: ones 1<5, tens 4<7: twice. 330-190: once (tens). 775-712: none. 617-471: once (tens).","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
