INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ecbccf6-7992-4646-b911-2f437478dd6c', 'BA2.11', 2, 'numeric', 'Regrouping and place value in the algorithm', 'To subtract $900 - 427$, the ones are too small and there are no tens to give. So you regroup 1 hundred as 10 tens, and then 1 of those tens as 10 ones. After all the regrouping, how many ones are in the ones place of 900?', '[]', '10', '10', '900 is 9 hundreds, 0 tens and 0 ones. Regroup 1 hundred: 8 hundreds and 10 tens. Regroup 1 ten: 9 tens and 10 ones. So there are 8 hundreds, 9 tens and 10 ones; the answer is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"900 becomes 8 hundreds, 9 tens, 10 ones. 10 ones.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
