INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb89a0d7-5646-4854-95df-6c0760b5cbc0', 'BA2.11', 3, 'choice', 'Addition and subtraction stories', 'A park had $8{,}000$ trees. Workers cut down $1{,}367$ trees and then planted 501 new trees. How many trees are in the park now?', '["$7{,}134$","$7{,}144$","$7{,}124$","$7{,}234$"]', '$7{,}134$', NULL, 'After cutting: $8{,}000$ - $1{,}367$ = $6{,}633$. After planting: $6{,}633$ + 501 = $7{,}134$.', 'checked', '{"lint":[],"solve":{"answer":"$7{,}134$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8000-1367=6633; 6633+501=7134.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
