INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88c0d3f4-64b8-4f26-b432-2c8d446264d0', 'BA2.12', 2, 'choice', 'Organized lists and counting ways', 'A kid can choose a shirt from 2 shirts, a pair of pants from 3 pairs, and a cap from 2 caps. How many different outfits of one shirt, one pair of pants and one cap are there?', '["7","6","12","14"]', '12', '2*3*2', '2 shirts x 3 pants = 6 ways to pick a shirt and pants. Each of those can go with either cap: 6 x 2 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 3 x 2 = 12.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
