INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3e2fa76-b140-4393-83ca-a53dd0b9ce5c', 'BA2.12', 2, 'numeric', 'Organized lists and counting ways', 'Leo, Kim, Cal, Tom each shake hands once with every other person in the group. How many handshakes are there in all?', '[]', '6', '6', 'List them: Leo shakes with Kim, Cal, Tom (3). Kim shakes with Cal, Tom (2 more). Cal shakes with Tom (1 more). 3 + 2 + 1 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 people: 3+2+1 = 6.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
