INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eecdb33e-a85f-4c36-b13a-ab1ef01cf3bd', 'BA2.12', 2, 'numeric', 'Organized lists and counting ways', 'How many different ways can you make exactly 25 cents using only dimes (10 cents) and nickels (5 cents)? (Only how many of each coin matters.)', '[]', '3', '3', 'List by the number of dimes, from the most to none: 2 dimes and 1 nickel; 1 dime and 3 nickels; 0 dimes and 5 nickels. That is 3 ways.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 dimes + 5 nickels; 1 dime + 3 nickels; 2 dimes + 1 nickel: 3.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
