INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7fadc040-05d5-4d7f-92c0-176868c4359c', 'BA2.12', 2, 'choice', 'Organized lists and counting ways', 'Gus, Uma, Cal, Ivy line up for lunch. Gus must be first in the line. How many different orders are possible for the whole line?', '["3","4","12","6"]', '6', '6', 'Gus is first. The other three can line up in 6 different orders (any of them first, then 2 ways for the last two: 3 x 2 = 6).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gus fixed; other 3 in 3 x 2 x 1 = 6 orders.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
