INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8fac373-1651-4447-bb39-0a6274e7d02c', 'BA2.12', 2, 'choice', 'Logic puzzles', 'Four children stand in a line. Val is somewhere ahead of Ana. Raj is somewhere ahead of Ben. Ana is somewhere ahead of Raj. Who is second in the line?', '["Ben","Val","Raj","Ana"]', 'Ana', NULL, 'The only order that fits every clue is Val, Ana, Raj, Ben (from the front). So Ana is second.', 'checked', '{"lint":[],"solve":{"answer":"Ana","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Val before Ana before Raj before Ben: Val, Ana, Raj, Ben. Second Ana.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
