INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70b2e75c-959e-4e34-81b0-68379e05eb4f', 'BA2.12', 2, 'numeric', 'Logic puzzles', 'I am a 2-digit number. My two digits are the same. I am between 80 and 100. I am even. What number am I?', '[]', '88', '88', 'Numbers with two matching digits are 11, 22, 33, ..., 99. The ones between 80 and 100 are 88, 99. Only 88 is even.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same digits between 80 and 100: 88, 99. Even: 88.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
