INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('872c183c-ec76-48b7-8494-7db5235f6667', 'BA2.12', 2, 'choice', 'Logic puzzles', 'Leo is 10 years old. Raj is 2 years older than Leo. Eli is 4 years younger than Raj. Which sentence is true?', '["Eli is older than Raj.","Raj is older than Leo.","Leo is older than Raj.","Eli is the same age as Leo."]', 'Raj is older than Leo.', NULL, 'Raj is 10 + 2 = 12. Eli is 12 - 4 = 8. So the ages are Leo 10, Raj 12, Eli 8. Only "Raj is older than Leo." matches.', 'checked', '{"lint":[],"solve":{"answer":"Raj is older than Leo.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leo 10, Raj 12, Eli 8. Only ''Raj is older than Leo'' is true.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
