INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21f8213b-6789-4d56-aeec-45f60f06845a', 'BA2.12', 2, 'choice', 'Logic puzzles', 'A ball, a block and a bear are put in three boxes, one thing in each: the small box, the medium box, the large box. The ball is in the large box. The bear is not in the large box. The bear is in the small box. Which box holds the block?', '["The small box","The large box","The medium box","We cannot tell"]', 'The medium box', NULL, 'The only way to place all three things so that every clue is true is: the ball in the large box; the block in the medium box; the bear in the small box. So the block is in the medium box.', 'checked', '{"lint":[],"solve":{"answer":"The medium box","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ball large, bear small, block medium.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
