INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a1d50fb-a126-4302-be47-030b1169b513', 'BA2.12', 2, 'choice', 'Multi-step stories', 'A farmer has 3 baskets with 11 eggs in each. 6 eggs break. The farmer sells 15 of the eggs that are not broken. How many eggs are left?', '["12","27","18","13"]', '12', '3*11-6-15', '3 x 11 = 33 eggs. After the broken ones: 33 - 6 = 27. After selling: 27 - 15 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"33 eggs, 6 break: 27 good; sell 15: 12 left.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
