INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3477426d-e60c-4437-b693-cca0421900e3', 'BA2.12', 2, 'numeric', 'Multi-step stories', 'Uma has 49 stickers. Uma gives 14 stickers to Dee and 17 stickers to Mia. Then Uma is given 21 new stickers. How many stickers does Uma have now?', '[]', '39', '49-14-17+21', '14 + 17 = 31 stickers given away. 49 - 31 = 18. Then 18 + 21 = 39.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49-14=35, 35-17=18, 18+21=39.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
