INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56549996-536c-4177-8e33-178cfbc05bbb', 'BA2.12', 2, 'choice', 'Multi-step stories', 'Eli saves 6 dollars every week for 6 weeks. Then Eli spends 11 dollars on a toy. How many dollars does Eli have left?', '["36","25","47","19"]', '25', '6*6-11', 'Saved: 6 x 6 = 36 dollars. Spent 11: 36 - 11 = 25 dollars.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x6=36, 36-11=25.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
