INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f199796f-3ff2-4d59-a236-56e2f607bad2', 'BA2.12', 2, 'numeric', 'Working backwards and guess and check', 'I think of a number and add 7. Then I double my answer. The result is 26. What number did I think of?', '[]', '6', '26/2-7', 'Work backwards. Undo "double": half of 26 is 13. Undo "add 7": 13 - 7 = 6. Check: 6 + 7 = 13, doubled is 26.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26/2=13, 13-7=6.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
