INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd3aad43-c588-4be3-b376-b87ae818f87a', 'BA2.12', 2, 'numeric', 'Working backwards and guess and check', 'I think of a number and subtract 3. Then I multiply my answer by 2. The result is 26. What number did I think of?', '[]', '16', '26/2+3', 'Work backwards. Undo "multiply by 2": 26 / 2 = 13. Undo "subtract 3": 13 + 3 = 16. Check: 16 - 3 = 13, times 2 is 26.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26/2=13, 13+3=16.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
