INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c76d1c7d-e73f-4fa3-9540-e8269e6fb54b', 'BA2.12', 2, 'numeric', 'Working backwards and guess and check', 'Tom has only 2-cent stamps and 5-cent stamps. He has 5 stamps, worth 19 cents in all. How many 5-cent stamps does he have?', '[]', '3', '3', 'Guess and check. Try 3 stamps worth 5 cents and 2 stamps worth 2 cents: 3 x 5 = 15 and 2 x 2 = 4. 15 + 4 = 19. That works. Other guesses give a different total.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f fives, 5-f twos: 5f + 2(5-f) = 19, 3f = 9, f = 3. (15+4=19.)","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
