INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d44db8bf-537a-4a21-b430-9348caecc6d8', 'BA2.12', 2, 'numeric', 'Working backwards and guess and check', 'I think of a number and cut it in half. Then I add 3. The result is 9. What number did I think of?', '[]', '12', '(9-3)*2', 'Work backwards. Undo "add 3": 9 - 3 = 6. Undo "cut in half" by doubling: 6 x 2 = 12. Check: half of 12 is 6, plus 3 is 9.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-3=6, 6x2=12.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
