INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01a354cb-2b48-447d-ad68-039b243c5254', 'BA2.12', 3, 'numeric', 'Number patterns', 'A pattern begins 6, 13, 20, 27, and goes up by the same amount each time. What is the first number in the pattern that is greater than 102?', '[]', '104', '104', 'Every number is 6 plus a multiple of 7. Counting up from 6 by 7, the last number not greater than 102 is 97, and the next number is 104.', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms 6+7k: ..., 97, 104. First above 102 is 104.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
