INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a1c8c28-90c5-4ed2-a84a-b245374f3ba2', 'BA2.12', 3, 'choice', 'Number patterns', 'Squares are made from matchsticks and joined in a row. One square uses 4 matchsticks. Two squares joined in a row use 7 matchsticks. Three squares joined in a row use 10 matchsticks. How many matchsticks do 10 squares joined in a row use?', '["34","28","31","40"]', '31', '3*10+1', 'Each new square adds 3 matchsticks. So 10 squares use 4 + 3 x 9 = 31 matchsticks.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, then 3 more per square: 4 + 9x3 = 31.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
