INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45bfca94-84b5-4968-836d-f9bc5d2f7f1e', 'BA2.12', 3, 'choice', 'Repeating patterns', 'Cards are laid out in the order 4, 2, 1, 4, 2, 1, 4, 2, 1, and so on, over and over. What is the total of the first 17 cards?', '["37","42","35","41"]', '41', '41', 'One group adds to 4 + 2 + 1 = 7. 17 cards is 5 groups and 2 extra cards. 5 x 7 = 35, plus 4 + 2 makes 41.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 cards = 5 units of total 7 = 35; cards 16, 17 are 4, 2. 41.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a101913-0b6f-418a-9f95-24553a88e698', 'BA2.12', 3, 'numeric', 'Repeating patterns', 'Beads are strung in this pattern of 5 beads, over and over: red, red, blue, red, blue. The pattern keeps repeating. At which bead number is the 7th blue bead?', '[]', '18', '18', 'Each group of 5 beads has 2 blue beads. 7 blue beads need 3 full groups (15 beads) and then blue bead number 1 of a group. Counting it out, the 7th blue bead is bead 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blues at 3 and 5 of each unit of 5. Units 1-3 give 6 blues (last at 15); 7th blue at 15+3 = 18.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dfd4b6a-2545-464d-8e47-97d9fe78d5e7', 'BA2.12', 3, 'numeric', 'Organized lists and counting ways', 'Four different toy cars are put in a row on a table. How many different orders can they be put in?', '[]', '24', '4*3*2*1', 'There are 4 choices for the first place, then 3 for the second, 2 for the third and 1 for the last. 4 x 3 x 2 x 1 = 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 x 2 x 1 = 24.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8dc3db5-dd8e-4880-b853-7a813a82c04b', 'BA2.12', 3, 'numeric', 'Organized lists and counting ways', 'You have four digit cards: 1, 3, 5, 9. You make 2-digit numbers by choosing a tens digit and a ones digit (each card may be used only once in a number, so both digits are different). How many different 2-digit numbers can you make?', '[]', '12', '4*3', '4 choices for the tens digit, then 3 choices left for the ones digit: 4 x 3 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 tens choices x 3 ones choices = 12.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('058b9751-8fe2-40e3-ba87-1050c7341f4d', 'BA2.12', 3, 'choice', 'Organized lists and counting ways', 'There are 5 teams in a league. Every team plays every other team once. How many games are played in all?', '["10","15","9","20"]', '10', '5*(5-1)/2', 'Count without repeats: the first one has 4 partners, the next has 3 more, and so on. 4 + 3 + 2 + 1 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+3+2+1 = 10.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
