INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5f2f537-0827-4355-868f-16ee6a8d9410', 'BA2.12', 3, 'choice', 'Organized lists and counting ways', 'Two number cubes each show 1 to 6. One is red and one is blue, so a red 2 and a blue 6 is different from a red 6 and a blue 2. In how many different ways can the two cubes add up to 8?', '["6","5","4","3"]', '5', '5', 'List the (red, blue) pairs that add to 8: (2, 6), (3, 5), (4, 4), (5, 3), (6, 2). That is 5 ways.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(red, blue): (2,6), (3,5), (4,4), (5,3), (6,2): 5.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6febc006-5b8b-4421-bec5-1ad1d100338f', 'BA2.12', 3, 'numeric', 'Organized lists and counting ways', 'A child climbs 4 stairs. Each time, the child steps up either 1 stair or 2 stairs. In how many different ways can the child climb all 4 stairs?', '[]', '5', '5', 'Let ways(k) be the number of ways to climb k stairs. ways(1) = 1, ways(2) = 2, and each later number is the sum of the two before it (the last step was 1 stair or 2 stairs): 1, 2, 3, 5, 8, 13. So 4 stairs can be climbed in 5 ways.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1111; 112, 121, 211; 22: 5.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('751a3e6e-8ce6-4acf-99d2-29a3de922fd4', 'BA2.12', 3, 'choice', 'Organized lists and counting ways', 'How many different pairs of two different whole numbers from 1 to 9 add up to 11? (Order does not matter, so 2 + 5 and 5 + 2 count as one pair.)', '["5","3","4","8"]', '4', '4', 'List them from the smallest first number: 2 + 9; 3 + 8; 4 + 7; 5 + 6. That is 4 pairs.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+9, 3+8, 4+7, 5+6 (1+10 not allowed): 4.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d13a9b7b-6344-45d6-993e-c146c344e99a', 'BA2.12', 3, 'choice', 'Logic puzzles', 'One of three children ate the last cookie. Each child says one sentence, and exactly one of the three sentences is true. Gus says: "Jo did not eat it." Ben says: "I did not eat it." Jo says: "I ate it." Who ate the cookie?', '["Ben","Gus","Jo","We cannot tell"]', 'Ben', NULL, 'Try each child as the one who ate the cookie and count the true sentences. Only when Ben ate it are exactly one of the three sentences true, so Ben ate the cookie.', 'checked', '{"lint":[],"solve":{"answer":"Ben","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If Jo: Ben and Jo true (2). If Gus: Gus and Ben true (2). If Ben: only Gus true (1). Ben.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cb22549-c1b3-4a72-bd0c-ed5703d7fb9a', 'BA2.12', 3, 'choice', 'Logic puzzles', 'Five children stand in a line. Ben is somewhere ahead of Raj. Raj is right behind Dee. Zoe is right behind Raj. Kim is right behind Zoe. Who is third in the line?', '["Ben","Raj","Dee","Zoe"]', 'Raj', NULL, 'The only order that fits every clue is Ben, Dee, Raj, Zoe, Kim (from the front). So Raj is third.', 'checked', '{"lint":[],"solve":{"answer":"Raj","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dee, Raj, Zoe, Kim back to back; Ben ahead of Raj and not between Dee and Raj, so Ben first. Ben, Dee, Raj, Zoe, Kim. Third Raj.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('584b5fb3-c082-4cf4-891e-f55ae1ca36f9', 'BA2.12', 3, 'choice', 'Logic puzzles', 'I am a 2-digit number. My two digits add up to 14. My tens digit is 4 more than my ones digit. What number am I?', '["59","86","95","84"]', '95', '95', 'Two digits that add to 14 and differ by 4: the bigger digit is (14 + 4) / 2 = 9 and the smaller is (14 - 4) / 2 = 5. The tens digit is the bigger one, so I am 95.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tens + ones = 14, tens - ones = 4: tens 9, ones 5. 95.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ab9b776-3560-47cd-9c54-a649a64e0971', 'BA2.12', 3, 'choice', 'Logic puzzles', 'Oli is 3 years old. Uma is 2 times as old as Oli. Val is 2 years older than Uma. How old is Val?', '["6","5","11","8"]', '8', '3*2+2', 'Uma is 2 x 3 = 6. Val is 6 + 2 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Uma 6, Val 8.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c9ab45-c3fd-4263-a67e-2e6e7b78382e', 'BA2.12', 3, 'numeric', 'Logic puzzles', 'Dee, Jo and Raj have 34 marbles in all. Jo has 2 more marbles than Raj. Dee has 3 more marbles than Jo. How many marbles does Raj have?', '[]', '9', '(34-7)/3', 'Imagine Jo and Dee each give away their extras. Jo gives 2, Dee gives 5. That removes 7 marbles, leaving 27. Now all three have the same number: 27 / 3 = 9. So Raj has 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Raj r, Jo r+2, Dee r+5: 3r+7=34, r=9. (9+11+14=34.)","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1787df50-62a8-4d2b-b69f-ffdfe3cfbd17', 'BA2.12', 3, 'choice', 'Logic puzzles', 'Raj is taller than Val. Ben is shorter than Val. Leo is taller than Raj. Which sentence must be true?', '["Leo is taller than Ben.","Raj is the tallest.","Ben is taller than Val.","Val is taller than Leo."]', 'Leo is taller than Ben.', NULL, 'The order from tallest to shortest is Leo, Raj, Val, Ben. So Leo is taller than Ben. The other sentences are false.', 'checked', '{"lint":[],"solve":{"answer":"Leo is taller than Ben.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leo > Raj > Val > Ben. Leo taller than Ben must be true; the others are false.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f1e03e5-d749-4102-a4a6-f90d754d6b46', 'BA2.12', 3, 'numeric', 'Multi-step stories', 'A pack of pens costs 5 dollars and a notebook costs 2 dollars. Ava buys 3 packs of pens and 3 notebooks. She pays with 50 dollars. How many dollars of change does she get?', '[]', '29', '50-3*5-3*2', 'Pens: 3 x 5 = 15. Notebooks: 3 x 2 = 6. Total 21 dollars. Change: 50 - 21 = 29 dollars.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x5 + 3x2 = 21; 50-21 = 29.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55ce6f6c-d733-478b-986a-3d46e229fc8e', 'BA2.12', 3, 'choice', 'Multi-step stories', 'A class has 28 children, and 12 of them are boys. Then 4 girls leave for a music lesson and 4 boys come in from another class. How many more boys than girls are in the room now?', '["28","16","4","12"]', '4', '(12+4)-(28-12-4)', 'Girls at first: 28 - 12 = 16. Girls now: 16 - 4 = 12. Boys now: 12 + 4 = 16. Difference: 16 - 12 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 16, boys 12. Girls 16-4=12, boys 12+4=16. 16-12=4.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e24cdfe5-2ea4-45f2-9c58-99ae5c4f1afc', 'BA2.12', 3, 'numeric', 'Multi-step stories', 'Fay has 4 boxes with 15 pencils in each box. Fay gives 6 pencils to each of 4 friends. How many pencils does Fay have left?', '[]', '36', '4*15-4*6', 'Pencils at first: 4 x 15 = 60. Given away: 4 x 6 = 24. Left: 60 - 24 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x15=60, 6x4=24, 60-24=36.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81afb4f3-bdc0-4fce-825a-f76ad983e528', 'BA2.12', 3, 'choice', 'Multi-step stories', 'On Monday Ana reads 13 pages. Each day after that, Ana reads 3 more pages than the day before. How many pages does Ana read from Monday to Thursday altogether?', '["22","67","73","70"]', '70', '70', 'The pages each day: 13, 16, 19, 22. Add them: 13 + 16 + 19 + 22 = 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13+16+19+22 = 70.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
