INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('200fa0e2-58fa-4eac-b3bd-270a5a547a66', 'BA2.12', 3, 'choice', 'Multi-step stories', 'A baker bakes 8 trays of rolls with 12 rolls on each tray. 36 rolls are sold. The rest are put into bags of 6 rolls. How many bags are filled?', '["10","11","9","12"]', '10', '(8*12-36)/6', 'Rolls baked: 8 x 12 = 96. After selling 36: 96 - 36 = 60. Bags: 60 / 6 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x12=96, 96-36=60, 60/6=10.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
