INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('628081e1-b78a-4ddf-a7d6-1236bf706908', 'BA2.12', 3, 'choice', 'Multi-step stories', '3 friends share the cost of a plant and a card equally. The plant costs 16 dollars and the card costs 2 dollars. How many dollars does each friend pay?', '["7","6","5","8"]', '6', '(16+2)/3', 'Total cost: 16 + 2 = 18 dollars. Shared between 3 friends: 18 / 3 = 6 dollars each.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16+2=18, 18/3=6.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36f02373-0d63-4eda-a953-12a30e5d1c3c', 'BA2.12', 3, 'numeric', 'Working backwards and guess and check', 'I think of a number. I double it, then subtract 3, then add 10. My answer is 35. What number did I think of?', '[]', '14', '(35-10+3)/2', 'Work backwards, undoing the last step first. Undo "add 10": 35 - 10 = 25. Undo "subtract 3": 25 + 3 = 28. Undo "double": half of 28 is 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35-10=25, +3=28, /2=14.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abc4e622-923c-4544-bfb8-3f313e452892', 'BA2.12', 3, 'choice', 'Working backwards and guess and check', 'Kim has 12 coins. Each coin is a dime (10 cents) or a nickel (5 cents). Together the coins are worth 85 cents. How many of the coins are dimes?', '["7","5","6","4"]', '5', '5', 'Guess and check. If all 12 coins were nickels they would be worth 60 cents. Each dime swapped in for a nickel adds 5 cents. The difference is 85 - 60 = 25, so 5 coins are dimes. Check: 5 dimes = 50, 7 nickels = 35, total 85.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All nickels = 60 cents; each dime adds 5: 25/5 = 5 dimes. 50+35=85.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17a6f28f-4f08-4399-8095-069caeb81511', 'BA2.12', 3, 'numeric', 'Working backwards and guess and check', 'Zoe spent half of Zoe''s money on a book. Then Zoe spent 7 dollars on lunch. Now Zoe has 5 dollars left. How many dollars did Zoe have at the start?', '[]', '24', '(5+7)*2', 'Work backwards. Before lunch: 5 + 7 = 12 dollars. That was half of the money, so at the start: 12 x 2 = 24 dollars.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before lunch 5+7=12; that is half, so 24.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffa88f74-4b93-4821-967f-9a6f581b6b8b', 'BA2.12', 3, 'choice', 'Working backwards and guess and check', 'Ben thinks of a number. He adds 5, then subtracts 2, then doubles the result. He gets 26. What number did Ben think of?', '["13","8","10","20"]', '10', '26/2+2-5', 'Work backwards. Undo "double": 26 / 2 = 13. Undo "subtract 2": 13 + 2 = 15. Undo "add 5": 15 - 5 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26/2=13, +2=15, -5=10.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cef73172-ff14-4a11-9125-17c0dd7d0686', 'BA2.12', 3, 'choice', 'Working backwards and guess and check', 'A farm has 8 animals. They are chickens (2 legs each) and cows (4 legs each). The animals have 24 legs altogether. How many cows are there?', '["5","3","6","4"]', '4', '4', 'Guess and check. If all 8 animals were chickens there would be 16 legs. Each cow instead of a chicken adds 2 legs. 24 - 16 = 8, so there are 4 cows. Check: 4 cows have 16 legs and 4 chickens have 8 legs; the total is 24.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All chickens = 16 legs; each cow adds 2: 8/2 = 4 cows. 4x4 + 4x2 = 24.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99d4660c-992c-4960-9b0f-0fb9335b6e65', 'BA2.12', 3, 'choice', 'Working backwards and guess and check', '5 equal books and a box that weighs 3 kilograms together weigh 13 kilograms. How many kilograms does one of the books weigh?', '["2","10","3","1"]', '2', '(13-3)/5', 'Take the box away: 13 - 3 = 10 kilograms for the 5 books. Share equally: 10 / 5 = 2 kilograms each.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13-3=10, 10/5=2.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
