VALUES ('cde38f5e-4886-4184-9442-acf989252dc5', 'BA3.02', 3, 'numeric', 'Finding the nth number in a skip-counting list', 'On day 1 Mara reads page 4. Each day after that she starts 5 pages later than the day before: page 4, then page 9, then page 14, and so on. On which day does she start on page 64? Give the day number.', '[]', '13', '(64-4)/5+1', '64 - 4 = 60, and 60 / 5 = 12 jumps. Day 1 plus 12 more days is day 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(64 - 4)/5 = 12 steps, day 13.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0630fe2f-fe11-446d-8882-c74d81209a03', 'BA3.02', 3, 'numeric', 'Counting backwards by skips', 'Count backward by 7s from 100: $100, 93, 86, \ldots$ What is the first number you say that is less than 10?', '[]', '9', '100-13*7', '100 - 7 x 13 = 100 - 91 = 9. Going one step less, 100 - 7 x 12 = 16 is still more than 10. So 9 is the first number below 10.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 7k < 10: k = 13 gives 9 (k = 12 gives 16).","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eed620a-28ce-4d4c-9a6a-93ce954db627', 'BA3.02', 3, 'choice', 'Counting backwards by skips', 'Count backward by 6s from 100 and stop before you would go below 0. What is the last number you say?', '["0","2","6","4"]', '4', '100-16*6', 'The numbers are 100 minus a multiple of 6. 6 x 16 = 96 and 100 - 96 = 4. Another step would give a number below 0, so 4 is the last number.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = 6 x 16 + 4, so counting down ends at 4 (next would be -2).","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1925e03e-7d46-4d9a-9bc5-9fae36a45962', 'BA3.02', 3, 'choice', 'Counting backwards by skips', 'Count backward by 15s from 150 all the way to 0: $150, 135, 120, \ldots, 0$. How many numbers do you say?', '["11","10","12","15"]', '11', '150/15+1', '150 / 15 = 10 jumps. One more number than jumps: 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/15 + 1 = 11.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
