INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('799d846c-57c5-4d60-ba55-f11ce24889ed', 'BA3.02', 3, 'choice', 'Counting backwards by skips', 'Count backward by 7s: $60, 53, 46, \ldots, 11$. How many numbers are in this list?', '["7","8","9","49"]', '8', '(60-11)/7+1', '60 - 11 = 49, and 49 / 7 = 7 jumps. One more number than jumps: 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(60 - 11)/7 = 7; 7 + 1 = 8.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
