VALUES ('9d0d87ad-b5f2-4302-b2ce-665e3be100a9', 'BA3.02', 3, 'choice', 'Counting backwards by skips', 'A countdown goes $300, 285, 270, \ldots, 30$. How many numbers are in the countdown?', '["18","20","19","270"]', '19', '(300-30)/15+1', '300 - 30 = 270, and 270 / 15 = 18 jumps. One more number than jumps: 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(300 - 30)/15 = 18; 18 + 1 = 19.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
