INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58e6aa3b-3e39-49b7-866a-7d3e7a02bce9', 'BA3.02', 3, 'choice', 'Finding a missing number in a skip-counting list', 'A skip-counting list goes up by 5 each time. Its 7th number is 38. What is its 1st number?', '["3","8","13","33"]', '8', '38-6*5', 'Going back from the 7th number to the 1st is 6 jumps. 6 x 5 = 30, and 38 - 30 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38 - 6 x 5 = 8.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
