INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa32524a-3734-4ca5-b933-71f912aef735', 'BA3.02', 3, 'choice', 'Finding a missing number in a skip-counting list', 'A skip-counting list goes up by 6 each time. Its 10th number is 100. What is its 1st number?', '["40","54","56","46"]', '46', '100-9*6', 'From the 1st number to the 10th there are 9 jumps. 9 x 6 = 54, and 100 - 54 = 46.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 9 x 6 = 46.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
