INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77a4caa6-707d-49dc-abb5-28be0225de1b', 'BA3.02', 3, 'numeric', 'Skip-counting patterns: step size, membership and shared numbers', 'Ana counts by 6s starting at 6. Ben counts by 9s starting at 9. What is the smallest number they both say?', '[]', '18', '18', 'Ana says 6, 12, 18. Ben says 9, 18. The smallest number both say is 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common multiples of 6 and 9: 18 first.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
