INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035ac7f3-b10a-4d39-8983-35c5e774df5f', 'BA3.02', 3, 'numeric', 'Skip-counting patterns: step size, membership and shared numbers', 'Ana counts by 6s starting at 6. Ben counts by 9s starting at 9. How many numbers less than 100 do they both say?', '[]', '5', '5', 'They both say 18, then every 18 after that: 18, 36, 54, 72, 90. The next would be 108, which is more than 100. That is 5 numbers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 18 below 100: 18, 36, 54, 72, 90 = 5.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
