INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('559bdd9f-b6f5-49c5-b7f2-4b572c0b77e5', 'BA3.02', 3, 'choice', 'Skip-counting patterns: step size, membership and shared numbers', 'The list $15, 22, 29, \ldots$ goes up by 7. What is the sum of the 4th number and the 5th number?', '["43","72","79","86"]', '79', '(15+3*7)+(15+4*7)', 'The 4th number is 15 + 3 x 7 = 36. The 5th number is 36 + 7 = 43. 36 + 43 = 79.', 'checked', '{"lint":[],"solve":{"answer":"79","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15, 22, 29, 36, 43: 36 + 43 = 79.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
