INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('770b20d7-d497-4670-95a9-c13323e7ecd2', 'BA3.02', 3, 'choice', 'Skip-counting patterns: step size, membership and shared numbers', 'Which skip-counting list has 50 as its 8th number?', '["starts at 6 and counts by 8","starts at 8 and counts by 7","starts at 10 and counts by 5","starts at 8 and counts by 6"]', 'starts at 8 and counts by 6', NULL, 'The 8th number is the start plus 7 jumps. Starting at 8 and counting by 6: 8 + 7 x 6 = 50. The others give 62, 57 and 45.', 'checked', '{"lint":[],"solve":{"answer":"starts at 8 and counts by 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8th = start + 7 steps. 10+35 = 45; 8+49 = 57; 8+42 = 50; 6+56 = 62.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
