INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5dead94-37b9-43ec-b320-af855290143f', 'BA3.03', 3, 'numeric', 'Perimeter of rectangles and squares', 'A rectangle is 6 centimeters long and 4 centimeters wide. A new rectangle is made with every side twice as long. What is the perimeter of the new rectangle, in centimeters?', '[]', '40', '2*(12+8)', 'The new sides are 12 and 8 centimeters. Its perimeter is 12 + 8 + 12 + 8 = 40 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 by 8: 2 x 20 = 40.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
