INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cda847f1-c79f-418f-a108-e44693da8911', 'BA3.03', 3, 'choice', 'Perimeter of rectangles and squares', 'A rectangular field is 50 meters long and 30 meters wide. Sam runs around its edge 3 times. How many meters does he run in all?', '["160","240","4500","480"]', '480', '3*2*(50+30)', 'One time around is 50 + 30 + 50 + 30 = 160 meters. Three times is 3 x 160 = 480 meters.', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 2 x 80 = 160; 3 x 160 = 480.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
