INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('301128a2-07ca-47b9-98bf-1a574755d641', 'BA3.03', 3, 'choice', 'Perimeter of polygons from side lengths', 'Mia walks a path shaped like a triangle: 120 meters from A to B, 95 meters from B to C, and 140 meters from C back to A. She walks the whole path twice. How many meters does she walk?', '["355","710","430","470"]', '710', '2*(120+95+140)', 'Once around: 120 + 95 + 140 = 355 meters. Twice: 2 x 355 = 710 meters.', 'checked', '{"lint":[],"solve":{"answer":"710","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120+95+140 = 355; x 2 = 710.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
