INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('341ebe70-b4e2-43f5-9028-29928ab4a819', 'BA3.03', 3, 'numeric', 'Perimeter of polygons from side lengths', 'A fence goes all the way around a six-sided yard. Its sides are 9, 9, 9, 12, 12 and 12 meters. Fencing costs 3 dollars for each meter. How many dollars does the fence cost?', '[]', '189', '(3*9+3*12)*3', 'The perimeter is 9 + 9 + 9 + 12 + 12 + 12 = 63 meters. At 3 dollars per meter: 63 x 3 = 189 dollars.', 'checked', '{"lint":[],"solve":{"answer":"189","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 27 + 36 = 63; 63 x 3 = 189.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
