INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3d16565-4068-43cf-9f12-61af419c9dd2', 'BA3.03', 3, 'choice', 'Perimeter of polygons from side lengths', 'A four-sided shape has a first side of 14 centimeters. The second side is 3 centimeters longer than the first. The third side is twice as long as the second. The fourth side is 9 centimeters shorter than the third. What is the perimeter, in centimeters?', '["65","99","74","90"]', '90', '14+17+34+25', 'Side 1 is 14. Side 2 is 14 + 3 = 17. Side 3 is 2 x 17 = 34. Side 4 is 34 - 9 = 25. Perimeter: 14 + 17 + 34 + 25 = 90 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 14, 17, 34, 25. Sum 90.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
