INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0907b992-d815-45be-bb76-68d3cb02805f', 'BA3.03', 3, 'choice', 'Missing side from the perimeter', 'A rectangle has a perimeter of 48 centimeters. Its length is 4 centimeters more than its width. What is its width, in centimeters?', '["24","20","10","14"]', '10', '(24-4)/2', 'Half the perimeter is 24, which is a length plus a width. Try widths: if the width is 10, the length is 14, and 10 + 14 = 24. So the width is 10 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L + W = 24, L = W + 4: 2W = 20, W = 10.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
