VALUES ('496cac1c-c19d-4686-bdbd-323407f22833', 'BA3.04', 3, 'choice', 'Equal groups and arrays', '24 dots are arranged in equal rows with none left over. Which number of rows would NOT work?', '["3 rows","4 rows","5 rows","6 rows"]', '5 rows', NULL, '24 / 3 = 8, 24 / 4 = 6 and 24 / 6 = 4 all work. But 5 x 4 = 20 and 5 x 5 = 25 miss 24, so 5 equal rows cannot hold exactly 24 dots.', 'checked', '{"lint":[],"solve":{"answer":"5 rows","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 5 is not whole; 3, 4, 6 divide 24.","run_id":"claude-code","at":"2026-10-19T01:25:25.515Z"}}', 'ai', NULL, NULL)
