INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79a65d96-151a-4a23-afe9-287ab0c32913', 'BA3.05', 3, 'numeric', 'Recognizing square numbers', 'Two different square numbers add up to 100. Both are bigger than 0. What is the larger one?', '[]', '64', '64', 'Try the squares: 100 - 36 = 64. And 36 = 6 times 6 and 64 = 8 times 8 are both squares. No other pair of squares adds to 100, so the larger one is 64.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 + 64 = 100 (6x6 + 8x8). Checking others: 100-1=99, 100-4=96, 100-9=91, 100-16=84, 100-25=75, 100-49=51, 100-81=19: none square. Larger 64.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
