VALUES ('d4d0a2f0-b8da-406b-9f68-09713653527e', 'BA3.05', 3, 'choice', 'Squares of numbers up to 20', 'Which number is equal to $19 \times 19$?', '["380","361","342","399"]', '361', '19*19', '19 times 19 = 19 times 20 - 19 = 380 - 19 = 361. (380 is 19 times 20 and 342 is 19 times 18.)', 'checked', '{"lint":[],"solve":{"answer":"361","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19 x 19 = 190 + 171 = 361.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
