INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6260d655-fde6-4538-aff6-06fa4b248c5f', 'BA3.05', 3, 'choice', 'Squares of numbers up to 20', 'What is the square of 20 minus the square of 13?', '["7","49","231","241"]', '231', '20*20-13*13', '20 times 20 = 400 and 13 times 13 = 169. 400 - 169 = 231.', 'checked', '{"lint":[],"solve":{"answer":"231","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400 - 169 = 231.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
