INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0aac9d9-a42b-4bd0-acc4-466f030e6b78', 'BA3.05', 3, 'choice', 'Squares of numbers up to 20', 'The square of a number is 361. What is the square of the number that is 2 less?', '["17","323","359","289"]', '289', '17*17', '19 times 19 = 361, so the number is 19. 2 less is 17, and 17 times 17 = 289.', 'checked', '{"lint":[],"solve":{"answer":"289","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"361 = 19 x 19; 2 less is 17; 17 x 17 = 289.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
