INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('628593ee-de7a-4e61-8828-6e2a600245b4', 'BA3.05', 3, 'numeric', 'Differences between squares', 'The difference between $18 \times 18$ and $19 \times 19$ is 37. What is the difference between $19 \times 19$ and $20 \times 20$?', '[]', '39', '37+2', 'The gaps between neighboring squares go up by 2 each time. So the next gap is 37 + 2 = 39. (400 - 361 = 39.)', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400 - 361 = 39 (gaps go up by 2: 37 + 2).","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
