INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b53a3b6-5730-4d01-8b44-6fc02d0f1a50', 'BA3.05', 3, 'choice', 'Differences between squares', 'How much bigger is $17 \times 17$ than $15 \times 15$?', '["64","2","33","62"]', '64', '289-225', '17 times 17 = 289 and 15 times 15 = 225. 289 - 225 = 64. (The gaps are 31 and 33, and 31 + 33 = 64.)', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"289 - 225 = 64.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
