INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be73a43-bbda-4e87-a6b9-12621acf96d5', 'BA3.05', 3, 'numeric', 'Differences between squares', 'Two neighboring square numbers have a difference of 27. What is the smaller one?', '[]', '169', '13*13', 'The gaps are odd numbers: 27 = 13 + 14, which is the gap from 13 times 13 to 14 times 14. 14 times 14 = 196 and 13 times 13 = 169. 196 - 169 = 27, so the smaller one is 169.', 'checked', '{"lint":[],"solve":{"answer":"169","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gap between n x n and the next is 2n + 1 = 27, n = 13: 169 and 196.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
