INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('225d610d-e597-4c75-981a-8d78ea540e3c', 'BA3.05', 3, 'choice', 'Differences between squares', 'Three of these four numbers are gaps between neighboring square numbers. Which one is not a gap?', '["17","19","18","21"]', '18', '18', 'The gaps between neighboring squares are odd numbers: 3, 5, 7, 9, ... 17, 19 and 21 are odd, but 18 is even, so it is not a gap.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gaps are odd numbers 3, 5, 7, ...; 18 is even.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
