INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf7198d5-96ea-44d2-82ae-49d9545e282a', 'BA3.05', 3, 'numeric', 'Differences between squares', 'How many whole numbers are between $14 \times 14$ and $15 \times 15$? (Do not count the two squares.)', '[]', '28', '225-196-1', '14 times 14 = 196 and 15 times 15 = 225. The numbers 197 to 224 are between them: 225 - 196 - 1 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"196 and 225: numbers 197 to 224 -> 224 - 197 + 1 = 28.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
