INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26cf145e-185e-4e59-8b1c-e440d7a02d6b', 'BA3.05', 3, 'choice', 'Differences between squares', 'Two neighboring square numbers have a gap of 29. What is the larger of the two?', '["196","169","256","225"]', '225', '225', 'The gap 29 goes from 14 times 14 = 196 to 15 times 15 = 225. The larger one is 225. (196 is the smaller.)', 'checked', '{"lint":[],"solve":{"answer":"225","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gap 29 = 225 - 196. Larger 225.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
