INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3add166-b9fc-4ff0-af2f-197721577e9e', 'BA3.05', 3, 'numeric', 'Square arrays', 'Nina makes a square of coins with 9 rows and 9 columns. She takes away all the coins on the outside edge: the first and last rows and the first and last columns. How many coins are left?', '[]', '49', '7*7', 'Taking off the outside leaves a square with 2 fewer rows and 2 fewer columns: 7 by 7. 7 times 7 = 49.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inner square is 7 by 7 = 49 (81 - 32).","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
