INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fabd4c3-528a-4c6a-819e-e5bda4279b8a', 'BA3.05', 3, 'choice', 'Square arrays', 'A square array has 8 rows and 8 columns of tiles. How many tiles are on its outside edge (the first and last rows and the first and last columns)?', '["32","36","28","24"]', '28', '64-6*6', 'The whole array has 64 tiles. The inside is a 6 by 6 square with 36 tiles. 64 - 36 = 28 tiles are on the edge.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 - inner 6x6 = 64 - 36 = 28.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
