INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0671f1a-e577-429b-b80b-bd4dfbd2cfe6', 'BA3.05', 3, 'numeric', 'Square arrays', 'Adding one row and one column to a square array of tiles takes 21 more tiles. How many tiles are in the square array to begin with?', '[]', '100', '10*10', 'Going from n by n to the next square adds n + n + 1 tiles. 21 = 10 + 10 + 1, so n = 10. The array has 10 times 10 = 100 tiles.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Going from n by n to (n+1) by (n+1) adds 2n + 1 = 21, n = 10: 100 tiles.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
