INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8b1ea96-cd24-40cb-bb4e-3d6923364f45', 'BA3.05', 3, 'numeric', 'Square arrays', 'Zed has 50 tiles. He wants the next bigger square array than the biggest one he can make now. How many more tiles does he need?', '[]', '14', '64-50', 'The biggest square he can make is 7 by 7 (49 tiles). The next one is 8 by 8, which takes 64 tiles. He needs 64 - 50 = 14 more tiles.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"A careless reader may answer 15 (64 - 49), but as written 14 is the answer.","work":"Biggest now: 7x7 = 49. Next: 8x8 = 64. He has 50, so needs 64 - 50 = 14 more.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
