INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f74b689-47d2-4b96-ba89-647604007704', 'BA3.05', 3, 'numeric', 'Square arrays', 'A rectangle of tiles has 4 rows and 9 columns. The tiles are rearranged into a square array with none left over. How many tiles are in each row of the square?', '[]', '6', '6', '4 times 9 = 36 tiles. 6 times 6 = 36, so each row of the square has 6 tiles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 9 = 36 = 6 x 6.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
