INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096b8db1-4cff-4fa9-bf34-1fed377bd1d0', 'BA3.05', 3, 'numeric', 'Square arrays', 'The outside edge of a square array of tiles has 40 tiles. How many tiles are in the whole array?', '[]', '121', '11*11', 'The edge of an n by n square has 4 sides of n tiles, but the 4 corners are counted twice: 4 times n - 4 = 40, so 4 times n = 44 and n = 11. The array has 11 times 11 = 121 tiles.', 'checked', '{"lint":[],"solve":{"answer":"121","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge tiles 4n - 4 = 40, n = 11: 11 x 11 = 121.","run_id":"claude-code","at":"2026-10-19T01:26:38.827Z"}}', 'ai', NULL, NULL)
