INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71833ef3-265a-4222-9ffb-d655f9282bc7', 'BA3.06', 1, 'numeric', 'Breaking a product apart', 'To find $4 \times 12$, Kim thinks of 12 as 10 + 2. She works out $4 \times 10 = 40$ and $4 \times 2 = 8$. What is $4 \times 12$?', '[]', '48', '40+8', '4 times 12 = 4 times 10 + 4 times 2 = 40 + 8 = 48.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 + 8 = 48.","run_id":"claude-code","at":"2026-10-19T01:26:38.865Z"}}', 'ai', NULL, NULL)
