INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3209b816-ba61-4c00-8ea5-4d7384baf263', 'BA3.06', 1, 'choice', 'Breaking a product apart', 'Which expression is equal to $6 \times 14$?', '["$6 \\times 10 + 4$","$6 \\times 10 + 6 \\times 4$","$6 \\times 4 + 10$","$10 \\times 4 + 6$"]', '$6 \times 10 + 6 \times 4$', NULL, '14 is 10 + 4, so 6 times 14 = 6 times 10 + 6 times 4 = 60 + 24 = 84. In the other expressions, a part is not multiplied by 6.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 10 + 6 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 14 = 6 x (10 + 4) = 60 + 24 = 84. Others: 64, 34, 46.","run_id":"claude-code","at":"2026-10-19T01:26:38.865Z"}}', 'ai', NULL, NULL)
