VALUES ('ef6c6b62-6872-4f74-9740-5bafecd23fb1', 'BA3.06', 1, 'choice', 'Breaking a product apart', 'Which number sentence is true?', '["$5 \\times 12 = 5 \\times 10 + 2$","$5 \\times 12 = 5 \\times 1 + 5 \\times 2$","$5 \\times 12 = 5 \\times 10 + 5 \\times 20$","$5 \\times 12 = 5 \\times 10 + 5 \\times 2$"]', '$5 \times 12 = 5 \times 10 + 5 \times 2$', NULL, '12 = 10 + 2, so 5 times 12 = 5 times 10 + 5 times 2 = 50 + 10 = 60. The others do not make 60.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 12 = 5 \\times 10 + 5 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 10 + 2, so 5 x 12 = 50 + 10 = 60. Others give 15, 150, 52.","run_id":"claude-code","at":"2026-10-19T01:26:38.865Z"}}', 'ai', NULL, NULL)
