VALUES ('a6dcd087-3c98-41af-9be2-222dc3f1da6e', 'BA3.06', 3, 'choice', 'Breaking a product apart', 'Which expression is equal to $6 \times 47$?', '["$6 \\times 40 + 6 \\times 5 + 6 \\times 2$","$6 \\times 40 + 6 \\times 5 + 2$","$6 \\times 40 + 6 \\times 5 + 6 \\times 3$","$6 \\times 4 + 6 \\times 5 + 6 \\times 2$"]', '$6 \times 40 + 6 \times 5 + 6 \times 2$', NULL, '47 = 40 + 5 + 2, so 6 times 47 = 6 times 40 + 6 times 5 + 6 times 2 = 240 + 30 + 12 = 282.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 40 + 6 \\times 5 + 6 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 = 40 + 5 + 2; 240 + 30 + 12 = 282 = 6 x 47.","run_id":"claude-code","at":"2026-10-19T01:26:38.865Z"}}', 'ai', NULL, NULL)
