INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fb8aa45-d814-4193-9448-f2b691f26b23', 'BA3.06', 3, 'numeric', 'Breaking a product apart', 'Lena says $8 \times 36 = 8 \times 30 + 8 \times 6$. Her brother says $8 \times 36 = 4 \times 36 + 4 \times 36$. Both are right. What is $8 \times 36$?', '[]', '288', '8*30+8*6', '8 times 30 = 240 and 8 times 6 = 48. 240 + 48 = 288. (Also 4 times 36 = 144 and 144 + 144 = 288.)', 'checked', '{"lint":[],"solve":{"answer":"288","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 30 + 8 x 6 = 240 + 48 = 288.","run_id":"claude-code","at":"2026-10-19T01:26:38.865Z"}}', 'ai', NULL, NULL)
