VALUES ('33a46869-c04f-4502-8adf-2d909ce3f3f2', 'BA3.07', 1, 'choice', 'Writing an expression or equation for a story', 'Which equation says, "A number times 4 is 36"?', '["$n + 4 = 36$","$n - 4 = 36$","$n \\div 4 = 36$","$4 \\times n = 36$"]', '$4 \times n = 36$', NULL, '"Times 4" is $4 \times n$, and "is 36" is $= 36$.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times n = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"number times 4 is 36: 4 x n = 36 (same as n x 4).","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
