INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb773b4d-9541-4211-9278-62e5f6ef05e6', 'BA3.07', 2, 'numeric', 'Puzzles with two unknowns', 'A triangle stands for a number, and so does a circle. Two triangles make 12. A triangle and a circle make 15. What number does the circle stand for?', '[]', '9', '15-12/2', 'Two triangles make 12, so a triangle is $12 \div 2 = 6$. Then the circle is $15 - 6 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle = 6; circle = 15 - 6 = 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
