INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2febe07-fe01-4c55-a785-c7e3d142c87a', 'BA3.07', 3, 'numeric', 'Puzzles with two unknowns', 'Two numbers $a$ and $b$ add to 12, and $a$ is 2 more than $b$. What is $a$?', '[]', '7', '(12+2)/2', 'If $a$ were 2 smaller it would equal $b$, and the two would add to $12 - 2 = 10$, so $b = 5$. Then $a = 5 + 2 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + b = 12, a = b + 2: 2b + 2 = 12, b = 5, a = 7.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
