VALUES ('003c2c39-7b66-4d6e-b3de-e0fc2147549a', 'BA3.07', 3, 'numeric', 'Puzzles with two unknowns', 'Two numbers $x$ and $y$ add to 15, and $x$ is twice as big as $y$. What is $y$?', '[]', '5', '15/3', '$x + y = y + y + y = 15$ (three equal parts), so $y = 15 \div 3 = 5$. Then $x = 10$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2y + y = 15, y = 5.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
