INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8c0ed0e-db62-467b-990c-179e859cc2c6', 'BA3.07', 3, 'choice', 'Puzzles with two unknowns', 'Two whole numbers add to 10 and multiply to 21. Which pair are they?', '["3 and 7","2 and 8","4 and 6","1 and 9"]', '3 and 7', NULL, 'Pairs adding to 10 have products: $2 \times 8 = 16$, $4 \times 6 = 24$, $1 \times 9 = 9$, and $3 \times 7 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"3 and 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 7 = 10, 3 x 7 = 21.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
