INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4898581-f654-469e-a0ce-6ff21853e230', 'BA3.07', 3, 'numeric', 'Puzzles with two unknowns', 'How many pairs of whole numbers $(a, b)$, counting 0, have $a + b = 6$? The pairs $(0, 6)$ and $(6, 0)$ count as different pairs.', '[]', '7', '7', 'Choose $a$ from 0 to 6 and $b$ is $6 - a$: (0,6), (1,5), (2,4), (3,3), (4,2), (5,1), (6,0). That is 7 pairs.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a from 0 to 6: 7 pairs.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
