INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ddcc1b6-95fe-4ddc-b773-5493c91ea248', 'BA3.07', 3, 'numeric', 'Balance puzzles', 'A balance is level. The left pan holds 2 identical boxes and a 6 gram weight. The right pan holds 1 of the same boxes and a 15 gram weight. How many grams does one box weigh?', '[]', '9', '15-6', 'Take 1 box off each pan. Then 1 box and 6 grams balance 15 grams, so a box weighs $15 - 6 = 9$ grams.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2b + 6 = b + 15, b = 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
