INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d131c308-b171-48da-af01-723f3b6528de', 'BA3.07', 3, 'numeric', 'Balance puzzles', 'A balance is level. The left pan holds 3 identical cubes and a 4 gram weight. The right pan holds 2 of the same cubes and a 10 gram weight. How many grams does one cube weigh?', '[]', '6', '10-4', 'Take 2 cubes off each pan. Then 1 cube and 4 grams balance 10 grams, so a cube weighs $10 - 4 = 6$ grams.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3c + 4 = 2c + 10, c = 6.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
