INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e69a4267-c45f-4cf1-a0c9-91f25393c195', 'BA3.07', 3, 'choice', 'Balance puzzles', 'A balance is level. The left pan holds 2 big stones and 1 small stone. The small stone weighs 5 grams. The right pan holds 25 grams. How many grams does one big stone weigh?', '["20","10","15","30"]', '10', '(25-5)/2', 'The small stone takes 5 of the 25 grams, so the 2 big stones weigh $25 - 5 = 20$ grams. One big stone weighs $20 \div 2 = 10$ grams.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2b + 5 = 25, b = 10.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
