INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d427dc4c-bccd-4c63-9570-322521abe473', 'BA3.07', 3, 'numeric', 'Balance puzzles', 'One apple weighs the same as 2 pears. One pear weighs the same as 3 plums. How many plums weigh the same as 3 apples?', '[]', '18', '3*2*3', 'One apple is 2 pears, which is $2 \times 3 = 6$ plums. So 3 apples are $3 \times 6 = 18$ plums.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 apples = 6 pears = 18 plums.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
