INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2a65fc3-351f-4335-a0b2-0f9451a6990a', 'BA3.07', 3, 'choice', 'Writing an expression or equation for a story', 'Each of 5 boxes holds $b$ pens, and there are also 3 loose pens. There are 28 pens in all. Which equation fits?', '["$5 + b + 3 = 28$","$5 \\times (b + 3) = 28$","$5 \\times b - 3 = 28$","$5 \\times b + 3 = 28$"]', '$5 \times b + 3 = 28$', NULL, '5 boxes give $5 \times b$ pens, and 3 loose pens are added: $5 \times b + 3 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times b + 3 = 28$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x b + 3 = 28.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
