INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48fefc03-4c3c-4bc7-b3ef-4842e5cb8639', 'BA3.07', 3, 'numeric', 'Writing an expression or equation for a story', 'Mia has some marbles. Noel has 3 times as many marbles as Mia. Together they have 32 marbles. How many marbles does Mia have?', '[]', '8', '32/4', 'Mia has 1 share and Noel has 3 shares, so there are 4 equal shares in 32 marbles. $32 \div 4 = 8$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m + 3m = 32, m = 8.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
