INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d734685-8921-4900-91a1-bd030cf0f6f3', 'BA3.07', 3, 'choice', 'Writing an expression or equation for a story', 'Which story fits the equation $3n + 2 = 20$?', '["3 packs with $n$ cards in each, plus 2 loose cards, make 20 cards.","A pack with $n$ cards, plus 3 loose cards, make 20 cards.","3 packs with $n$ cards in each, take away 2 cards, leave 20 cards.","Each pack has 3 cards, and $n$ packs plus 2 packs make 20."]', '3 packs with $n$ cards in each, plus 2 loose cards, make 20 cards.', NULL, '$3n$ is 3 groups of $n$, and $+ 2$ is 2 more. Only the first story has 3 groups of $n$ with 2 added.', 'checked', '{"lint":[],"solve":{"answer":"3 packs with $n$ cards in each, plus 2 loose cards, make 20 cards.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 packs of n cards plus 2 loose = 3n + 2 = 20.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c4025ba-9023-4d18-8c76-b3979487172d', 'BA3.07', 3, 'numeric', 'Writing an expression or equation for a story', 'Dan is $d$ years old. His mother is 4 times as old as Dan. Together their ages add up to 45. How old is Dan''s mother?', '[]', '36', '4*(45/5)', 'Dan is 1 share and his mother is 4 shares, so there are 5 equal shares in 45. $45 \div 5 = 9$, so Dan is 9 and his mother is $4 \times 9 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d + 4d = 45, d = 9, mother 36.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
