INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('503f6317-0377-4f3d-8f7d-0941d03084e2', 'BA3.07', 3, 'numeric', 'Working backwards from a result', 'I think of a number, add 6 and then multiply by 3. The answer is 45. What was my number?', '[]', '9', '45/3-6', 'Undo in reverse. Divide by 3: $45 \div 3 = 15$. Take away 6: $15 - 6 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(n + 6) x 3 = 45, n + 6 = 15, n = 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
