INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('567a991a-4b70-4275-9465-cc0716277b66', 'BA3.07', 3, 'numeric', 'Working backwards from a result', 'I think of a number, take away 4 and then divide by 2. The answer is 7. What was my number?', '[]', '18', '7*2+4', 'Undo in reverse. Multiply by 2: $7 \times 2 = 14$. Add 4: $14 + 4 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(n - 4)/2 = 7, n - 4 = 14, n = 18.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
