INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a5ec2fe-45cb-4d2e-910c-4eed79953fb6', 'BA3.07', 3, 'choice', 'Working backwards from a result', 'I start with a number, multiply it by 5 and then take away 8. I get 37. Which number did I start with?', '["45","9","29","6"]', '9', '(37+8)/5', 'Undo in reverse. Add 8: $37 + 8 = 45$. Divide by 5: $45 \div 5 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5n - 8 = 37, 5n = 45, n = 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
