INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1895b062-44d4-4807-9e24-a1d1e6997d05', 'BA3.07', 3, 'numeric', 'Working backwards from a result', 'A box has some cookies. Ana eats 3 of them. Then the rest are shared equally among 4 friends, and each friend gets 5 cookies. How many cookies were in the box at first?', '[]', '23', '4*5+3', 'The friends got $4 \times 5 = 20$ cookies. Those are what was left after Ana ate 3, so there were $20 + 3 = 23$ cookies.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(c - 3)/4 = 5, c - 3 = 20, c = 23.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
