INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c44662c-d30f-48ca-81b3-50dc9f88da8a', 'BA3.07', 3, 'numeric', 'Rules and patterns with a variable', 'A rule turns a number $n$ into $4 \times n$ plus a fixed number. When $n$ is 2 the result is 11, and when $n$ is 4 the result is 19. What is the result when $n$ is 10?', '[]', '43', '4*10+3', 'When $n = 2$: $4 \times 2 = 8$ and $11 - 8 = 3$, so the fixed number is 3. Then for $n = 10$: $4 \times 10 + 3 = 43$.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*2 + k = 11, k = 3; check 4*4 + 3 = 19. 4*10 + 3 = 43.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
