INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f6684ea-1ba6-4243-920a-d47d3c0092f7', 'BA3.07', 3, 'choice', 'Rules and patterns with a variable', 'A rule gives 7 when $n$ is 2 and 13 when $n$ is 5. Which rule is it?', '["$3n + 1$","$n + 5$","$2n + 3$","$4n - 1$"]', '$2n + 3$', NULL, 'Check each rule at $n = 2$ and $n = 5$. $2n + 3$ gives 7 and 13. $3n + 1$ gives 16 at 5. $n + 5$ gives 10 at 5. $4n - 1$ gives 19 at 5.', 'checked', '{"lint":[],"solve":{"answer":"$2n + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n + 3: 7, 13. 4n - 1: 7, 19; 3n + 1: 7, 16; n + 5: 7, 10.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
