VALUES ('b01c068f-9e8f-48d3-8f20-d2bd78916bc0', 'BA3.08', 3, 'choice', 'Remainders', 'Which division has the greatest remainder?', '["$29 \\div 6$","$29 \\div 7$","$29 \\div 5$","$29 \\div 10$"]', '$29 \div 10$', NULL, 'The remainders are: $29 \div 10$ leaves 9; $29 \div 6$ leaves 5; $29 \div 7$ leaves 1; $29 \div 5$ leaves 4. The greatest is 9.', 'checked', '{"lint":[],"solve":{"answer":"$29 \\div 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remainders 1, 4, 5, 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.553Z"}}', 'ai', NULL, NULL)
