INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abd16ee9-e685-4b15-966b-4fc6847ded52', 'BA3.08', 3, 'numeric', 'Remainders', 'Divide 59 by 8. What is the quotient plus the remainder?', '[]', '10', '7+3', '$7 \times 8 = 56$ and $59 - 56 = 3$. The quotient is 7 and the remainder is 3, so the total is $7 + 3 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"59 = 8 x 7 + 3; 7 + 3 = 10.","run_id":"claude-code","at":"2026-10-19T01:24:30.553Z"}}', 'ai', NULL, NULL)
