INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cb75af5-4eec-4fbb-a9ad-08f10e62a6dd', 'BA3.08', 3, 'choice', 'Remainders', 'A pattern of beads repeats red, blue, green, yellow over and over. What color is the 50th bead?', '["blue","red","green","yellow"]', 'blue', NULL, 'Each group of 4 beads uses the colors once. $50 \div 4 = 12$ remainder 2, so the 50th bead is the 2nd color in a group: blue.', 'checked', '{"lint":[],"solve":{"answer":"blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 = 4 x 12 + 2: 2nd colour, blue.","run_id":"claude-code","at":"2026-10-19T01:24:30.553Z"}}', 'ai', NULL, NULL)
