INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fabdd5e-c13e-484b-96a9-a0f8a97f5456', 'BA3.08', 3, 'numeric', 'Reasoning about remainders', 'What is the largest whole number less than 100 that leaves a remainder of 3 when divided by 8?', '[]', '99', '12*8+3', '$12 \times 8 = 96$, and $96 + 3 = 99$ is less than 100. The next number that works, 107, is too big. So the answer is 99.', 'checked', '{"lint":[],"solve":{"answer":"99","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 12 + 3 = 99 < 100.","run_id":"claude-code","at":"2026-10-19T01:24:30.553Z"}}', 'ai', NULL, NULL)
