INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('191e07f7-e6d6-4ac6-a7a0-4455ec60066a', 'BA3.09', 3, 'numeric', 'Length: feet and inches', 'Jo cut 3 equal pieces from a board, each 16 inches long. Exactly 1 foot of the board was left over. How many feet long was the board at the start?', '[]', '5', '(3*16+12)/12', 'The pieces use $3 \times 16 = 48$ inches. Add the 12 inches left: $48 + 12 = 60$ inches, which is 5 feet.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 16 = 48 in, + 12 in left = 60 in = 5 feet.","run_id":"claude-code","at":"2026-10-19T01:27:09.066Z"}}', 'ai', NULL, NULL)
