INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be37de8d-42e7-4ddf-895d-6d112f2228d2', 'BA3.09', 3, 'numeric', 'Weight: pounds and ounces', 'Eli puts 5 books into an empty bag. Each book weighs 12 ounces and the bag weighs 4 ounces. How many pounds does the bag with the books weigh? (16 ounces make 1 pound.)', '[]', '4', '(5*12+4)/16', 'The books weigh $5 \times 12 = 60$ ounces. With the bag: 64 ounces. $64 \div 16 = 4$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 12 = 60, + 4 = 64 oz = 4 pounds.","run_id":"claude-code","at":"2026-10-19T01:27:09.066Z"}}', 'ai', NULL, NULL)
