INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9794d0-6528-4d7a-9974-a9068014a44b', 'BA3.09', 3, 'choice', 'Weight: pounds and ounces', 'A melon weighs 2 pounds 6 ounces and a pineapple weighs 2 pounds 14 ounces. How much do they weigh together? (16 ounces make 1 pound.)', '["5 pounds 4 ounces","4 pounds 4 ounces","5 pounds 20 ounces","6 pounds 4 ounces"]', '5 pounds 4 ounces', NULL, 'Pounds: 2 + 2 = 4. Ounces: 6 + 14 = 20, which is 1 pound 4 ounces. So the total is 5 pounds 4 ounces.', 'checked', '{"lint":[],"solve":{"answer":"5 pounds 4 ounces","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 lb + 20 oz = 4 lb + 1 lb 4 oz = 5 pounds 4 ounces.","run_id":"claude-code","at":"2026-10-19T01:27:09.066Z"}}', 'ai', NULL, NULL)
