INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a35d2e5-5993-465c-8059-2eaf724a41d2', 'BA3.10', 2, 'choice', 'Unit fractions', 'Which statement is true?', '["A pizza cut into 5 equal slices has slices that are each $\\frac{1}{5}$ of the pizza.","A pizza cut into 5 slices of different sizes has slices that are each $\\frac{1}{5}$ of the pizza.","A pizza cut into 5 equal slices has slices that are each $\\frac{1}{4}$ of the pizza.","A pizza cut into 5 equal slices has slices that are each 5 of the pizza."]', 'A pizza cut into 5 equal slices has slices that are each $\frac{1}{5}$ of the pizza.', NULL, 'A unit fraction needs EQUAL parts. 5 equal slices make fifths, so each slice is $\frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"A pizza cut into 5 equal slices has slices that are each $\\frac{1}{5}$ of the pizza.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal slices, 5 of them: each 1/5. The unequal-slices statement is false.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
