INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('317a2b8f-f563-477c-b25a-04c27fb30701', 'BA3.10', 2, 'choice', 'Unit fractions', 'Which list puts these fractions in order from the smallest to the largest?', '["$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{6}$, $\\frac{1}{9}$","$\\frac{1}{9}$, $\\frac{1}{6}$, $\\frac{1}{3}$, $\\frac{1}{2}$","$\\frac{1}{6}$, $\\frac{1}{9}$, $\\frac{1}{3}$, $\\frac{1}{2}$","$\\frac{1}{9}$, $\\frac{1}{3}$, $\\frac{1}{6}$, $\\frac{1}{2}$"]', '$\frac{1}{9}$, $\frac{1}{6}$, $\frac{1}{3}$, $\frac{1}{2}$', NULL, 'More pieces means smaller pieces. Ninths are the smallest, then sixths, thirds and halves.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{9}$, $\\frac{1}{6}$, $\\frac{1}{3}$, $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger denominator = smaller unit fraction: 1/9 < 1/6 < 1/3 < 1/2.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
