INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fffec4ec-1341-4606-b21a-bdbd81191a33', 'BA3.10', 2, 'numeric', 'Naming a fraction of a whole', 'A flag has 12 equal stripes. Five are red, 4 are white and the rest are blue. What fraction of the flag is blue?', '[]', '3/12', '3/12', '$5 + 4 = 9$ stripes are red or white, so $12 - 9 = 3$ are blue: $\frac{3}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 5 - 4 = 3 blue: 3/12 = 1/4.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
