VALUES ('bdec535f-9f4d-4c93-8eb8-098d2c82677d', 'BA3.10', 2, 'choice', 'Naming a fraction of a whole', 'A tray has 8 equal brownies. Five of them are eaten. What fraction of the brownies is NOT eaten?', '["$\\frac{5}{8}$","$\\frac{3}{5}$","$\\frac{3}{8}$","$\\frac{8}{3}$"]', '$\frac{3}{8}$', NULL, '$8 - 5 = 3$ brownies are left out of 8: $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 5 = 3 not eaten: 3/8.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
