VALUES ('6e32a9f7-9b86-4d7b-aec4-4b08a630f649', 'BA3.10', 2, 'numeric', 'Naming a fraction of a whole', 'A pizza has 8 equal slices. Rae eats 3 slices, Tim eats 2 slices and Bo eats 1 slice. What fraction of the pizza is left?', '[]', '2/8', '2/8', '$3 + 2 + 1 = 6$ slices are eaten, so $8 - 6 = 2$ slices are left: $\frac{2}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2 + 1 = 6 eaten, 2 left: 2/8 = 1/4.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
