INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('872ac213-5e4f-48df-a2dc-a6588558b22f', 'BA3.10', 2, 'choice', 'Naming a fraction of a whole', 'Which sentence tells what $\frac{5}{8}$ means?', '["The whole is cut into 8 equal parts and 5 of them are taken.","The whole is cut into 5 equal parts and 8 of them are taken.","The whole is cut into 8 parts of any size and 5 of them are taken.","The whole is cut into 8 equal parts and 8 minus 5 of them are taken."]', 'The whole is cut into 8 equal parts and 5 of them are taken.', NULL, 'The bottom number says how many equal parts, 8. The top number says how many are taken, 5.', 'checked', '{"lint":[],"solve":{"answer":"The whole is cut into 8 equal parts and 5 of them are taken.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Denominator 8 = equal parts, numerator 5 = parts taken.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
