VALUES ('b13a45f0-8950-4511-89cb-44ea2a148484', 'BA3.10', 2, 'choice', 'Equivalent fractions', 'Maya says $\frac{2}{5}$ = $\frac{4}{10}$. Dan says $\frac{2}{5}$ = $\frac{4}{7}$. Who is right?', '["Dan only","Maya only","Both of them","Neither of them"]', 'Maya only', NULL, 'Doubling the top and bottom of $\frac{2}{5}$ gives $\frac{4}{10}$, so Maya is right. For $\frac{4}{7}$ the bottom would have to go from 5 to 7 by adding 2, but equal fractions come from multiplying both numbers by the same amount, so Dan is wrong.', 'checked', '{"lint":[],"solve":{"answer":"Maya only","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = 4/10 (true); 4/7 is not 2/5. Maya only.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e3c144-040c-4eb6-af34-6f4a549849f1', 'BA3.10', 2, 'choice', 'Comparing fractions', 'Two bars are the same size. The first bar is cut into 3 equal parts and 2 parts are colored. The second bar is cut into 5 equal parts and 2 parts are colored. Which bar has more colored?', '["The second bar","The first bar","They have the same amount","It cannot be told"]', 'The first bar', NULL, 'Compare $\frac{2}{3}$ and $\frac{2}{5}$. Thirds are bigger than fifths, so 2 thirds is more than 2 fifths.', 'checked', '{"lint":[],"solve":{"answer":"The first bar","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 > 2/5: first bar.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f395471-93f0-4aa0-ae68-1ddff16e34e2', 'BA3.10', 2, 'numeric', 'Comparing fractions', 'How many of these fractions are greater than $\frac{1}{2}$: $\frac{3}{8}$, $\frac{5}{6}$, $\frac{4}{10}$, $\frac{7}{12}$, $\frac{1}{3}$, $\frac{2}{3}$?', '[]', '3', '3', '$\frac{5}{6}$, $\frac{7}{12}$ and $\frac{2}{3}$ are each more than half. The others are less than half.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 no; 5/6 yes; 4/10 no; 7/12 yes; 1/3 no; 2/3 yes. 3.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
