INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a364b39d-6ee1-46bf-ab7b-42e5dfa9876e', 'BA3.10', 2, 'choice', 'Comparing fractions', 'Which list shows these fractions from the smallest to the largest?', '["$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{6}$, $\\frac{5}{6}$","$\\frac{1}{3}$, $\\frac{1}{6}$, $\\frac{1}{2}$, $\\frac{5}{6}$","$\\frac{1}{6}$, $\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","$\\frac{1}{6}$, $\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{5}{6}$"]', '$\frac{1}{6}$, $\frac{1}{3}$, $\frac{1}{2}$, $\frac{5}{6}$', NULL, 'In sixths: $\frac{1}{6}$, $\frac{2}{6}$, $\frac{3}{6}$, $\frac{5}{6}$. So the order is $\frac{1}{6}$, $\frac{1}{3}$, $\frac{1}{2}$, $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$, $\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6 < 1/3 < 1/2 < 5/6.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
