INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af8d2918-881b-430c-b7be-8316da84e5b0', 'BA3.10', 2, 'choice', 'Comparing fractions', 'Kim and Lou have ribbons of the same length. Kim used $\frac{3}{4}$ of her ribbon and Lou used $\frac{5}{8}$ of his. Who used more?', '["Lou","They used the same amount","It cannot be told","Kim"]', 'Kim', NULL, '$\frac{3}{4}$ = $\frac{6}{8}$, which is more than $\frac{5}{8}$. Kim used more.', 'checked', '{"lint":[],"solve":{"answer":"Kim","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 6/8 > 5/8: Kim.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
