INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('295b4f8e-b4c7-4b4b-84e0-f319f883a5aa', 'BA3.10', 2, 'numeric', 'Where a fraction lies between whole numbers', '$\frac{9}{4}$ is between 2 and which whole number?', '[]', '3', '3', '$\frac{8}{4}$ = 2 and $\frac{12}{4}$ = 3, so $\frac{9}{4}$ is between 2 and 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/4 = 2 1/4: between 2 and 3.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
