INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f53272d0-cf35-48d4-bd16-cd64d3b996e3', 'BA3.10', 2, 'choice', 'Where a fraction lies between whole numbers', 'Which fraction is between 2 and 3?', '["$\\frac{5}{3}$","$\\frac{10}{3}$","$\\frac{7}{3}$","$\\frac{3}{2}$"]', '$\frac{7}{3}$', NULL, '3 thirds make 1, so 6 thirds make 2 and 9 thirds make 3. $\frac{7}{3}$ is between 6 and 9 thirds.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/3 = 2 1/3. 5/3, 3/2 < 2; 10/3 > 3.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
