INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b56718f1-ba5c-468d-aaf6-cd038217e389', 'BA3.10', 2, 'choice', 'Where a fraction lies between whole numbers', 'Pam has 11 pieces of pizza. Each piece is $\frac{1}{3}$ of a pizza. How many whole pizzas can she make from the pieces?', '["4","2","33","3"]', '3', '3', 'Every 3 pieces make 1 pizza. $11 \div 3$ is 3 with 2 left over, so she can make 3 whole pizzas.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 thirds = 3 wholes and 2 thirds: 3 whole pizzas.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
