INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4a0cd6-9f07-4212-8fee-e37b45a16529', 'BA3.10', 2, 'choice', 'Where a fraction lies between whole numbers', 'Mara says $\frac{9}{5}$ is more than 2. What is the best reply?', '["No, $\\frac{9}{5}$ is between 1 and 2.","Yes, $\\frac{9}{5}$ is between 2 and 3.","No, $\\frac{9}{5}$ is less than 1.","Yes, because 9 is more than 5."]', 'No, $\frac{9}{5}$ is between 1 and 2.', NULL, '5 fifths make 1 and 10 fifths make 2. 9 fifths is between 5 and 10 fifths, so it lies between 1 and 2.', 'checked', '{"lint":[],"solve":{"answer":"No, $\\frac{9}{5}$ is between 1 and 2.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/5 = 1 4/5: between 1 and 2.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
