VALUES ('526341cd-79eb-4c3a-bfb0-69d8f3b34b25', 'BA3.10', 2, 'numeric', 'Where a fraction lies between whole numbers', 'How many halves are there in 3 whole pies?', '[]', '6', '3*2', 'Each pie has 2 halves, so $3 \times 2 = 6$ halves.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 halves per pie x 3 = 6.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
