INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4726170a-263c-4308-90e3-3160db935993', 'BA3.10', 3, 'numeric', 'Unit fractions', 'A unit fraction is smaller than $\frac{1}{6}$ but larger than $\frac{1}{8}$. What is its denominator?', '[]', '7', '7', 'Bigger denominators make smaller unit fractions, so the denominator is between 6 and 8. It is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 < 1/d < 1/6 means 6 < d < 8, d = 7.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
