INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff10c758-8f76-40ff-96e4-d9aa70c73f2c', 'BA3.10', 3, 'choice', 'Unit fractions', 'Four friends cut identical sandwiches into equal pieces. Ava cuts hers into 6 pieces, Ben into 9, Cy into 4 and Di into 12. Whose pieces are the biggest?', '["Ava","Ben","Cy","Di"]', 'Cy', NULL, 'Fewer pieces means each piece is bigger. Cy cut into only 4 pieces, so each of Cy''s pieces is $\frac{1}{4}$ of the sandwich, the biggest.', 'checked', '{"lint":[],"solve":{"answer":"Cy","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fewest pieces of the same sandwich are biggest: Cy (4 pieces).","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
