INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b58cfdca-0787-4609-85ca-3371652cf3c6', 'BA3.10', 3, 'numeric', 'Unit fractions', '$\frac{1}{4}$ of the marbles in a jar is 6 marbles. How many marbles are in the jar?', '[]', '24', '6*4', '6 marbles are one of 4 equal parts, so the jar has $4 \times 6 = 24$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 is 6, so whole is 4 x 6 = 24.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
