INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('216e70f0-5f15-48c6-a585-1b21d8cefe4e', 'BA3.10', 3, 'numeric', 'Naming a fraction of a whole', 'Mia cuts $\frac{2}{10}$ of a ribbon off, then $\frac{3}{10}$ of the ribbon, then $\frac{1}{10}$ of the ribbon. What fraction of the ribbon is left?', '[]', '4/10', '4/10', 'She cut off $2 + 3 + 1 = 6$ tenths, so $10 - 6 = 4$ tenths are left: $\frac{4}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 + 1 = 6 tenths cut; 4/10 = 2/5 left.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
