INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5419041d-fabe-4c31-926e-3df334495715', 'BA3.10', 3, 'choice', 'Naming a fraction of a whole', 'Seven of the 9 equal parts of a field are planted with corn. The corn covers 28 square meters. How many square meters is the whole field?', '["28","36","32","63"]', '36', '28/7*9', '7 parts cover 28 square meters, so 1 part covers $28 \div 7 = 4$. All 9 parts: $9 \times 4 = 36$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 parts = 28, one part = 4, 9 parts = 36.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
