INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a18c98e-e6e7-4649-87fd-506d602a79c7', 'BA3.10', 3, 'numeric', 'Naming a fraction of a whole', 'A candy bar has 12 equal pieces. Lee eats 4 pieces and Mia eats 3 pieces. What fraction of the candy bar is left?', '[]', '5/12', '5/12', '$4 + 3 = 7$ pieces are eaten, so $12 - 7 = 5$ are left: $\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 3 = 7 eaten, 5 left: 5/12.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
