INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6c400f1-c1dc-4004-8ab2-07b97ffe71c8', 'BA3.10', 3, 'numeric', 'Naming a fraction of a whole', 'A pizza is cut into 8 equal slices. Then every slice is cut in half, making smaller slices that are all equal. Ana eats 5 of the smaller slices. What fraction of the whole pizza did she eat?', '[]', '5/16', '5/16', 'Cutting each of 8 slices in half makes $8 \times 2 = 16$ equal slices. Ana ate 5 of them: $\frac{5}{16}$.', 'checked', '{"lint":[],"solve":{"answer":"5/16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 slices halved = 16 equal slices; 5 of them = 5/16.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
