INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0ee9d25-0777-4880-8700-04599dccdcb0', 'BA3.10', 3, 'choice', 'Naming a fraction of a whole', 'A pizza is cut into 12 equal slices. Ann eats 3 slices, Bo eats 4 slices and Cy eats 2 slices. Who ate exactly $\frac{1}{3}$ of the pizza?', '["Ann","Cy","Bo","Nobody"]', 'Bo', NULL, '$\frac{1}{3}$ of 12 slices is 4 slices, and Bo ate 4. Ann ate $\frac{3}{12}$ (one fourth) and Cy ate $\frac{2}{12}$ (one sixth).', 'checked', '{"lint":[],"solve":{"answer":"Bo","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 of 12 slices = 4 slices: Bo.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
