INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb536e6-523d-42f4-9c50-672c94791c13', 'BA3.10', 3, 'choice', 'Fraction of a group', '$\frac{3}{8}$ of the passengers on a bus are children. There are 15 children. How many passengers are on the bus?', '["5","40","45","24"]', '40', '15/3*8', '3 parts are 15 children, so 1 part is $15 \div 3 = 5$. All 8 parts: $8 \times 5 = 40$ passengers.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 is 15, so 1/8 is 5; total 40.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8ba2a32-6ccd-46d7-a185-1e06f2d556b4', 'BA3.10', 3, 'choice', 'Fraction of a group', 'A class has 24 students. $\frac{1}{3}$ of them wear glasses and $\frac{1}{4}$ of them are left-handed. No student does both. How many students are neither left-handed nor wearing glasses?', '["14","8","10","6"]', '10', '24-24/3-24/4', 'Glasses: $24 \div 3 = 8$. Left-handed: $24 \div 4 = 6$. Together 14 students, so $24 - 14 = 10$ are neither.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Glasses 24/3 = 8; left-handed 24/4 = 6; neither 24 - 14 = 10.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
