INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99def7ac-e4f8-4380-8f2c-13bdbfefba74', 'BA3.10', 3, 'choice', 'Fraction of a group', 'Which of these is the greatest?', '["$\\frac{2}{3}$ of 12","$\\frac{3}{4}$ of 12","$\\frac{1}{2}$ of 14","$\\frac{5}{6}$ of 12"]', '$\frac{5}{6}$ of 12', NULL, '$\frac{2}{3}$ of 12 is 8, $\frac{3}{4}$ of 12 is 9, $\frac{1}{2}$ of 14 is 7, and $\frac{5}{6}$ of 12 is 10. The greatest is 10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$ of 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 of 12 = 9; 1/2 of 14 = 7; 5/6 of 12 = 10; 2/3 of 12 = 8. Greatest 10.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93bd5168-61d0-4bd5-8de2-264649baab87', 'BA3.10', 3, 'numeric', 'Fraction of a group', 'A jar has 40 marbles. Half of them are blue. Then $\frac{1}{4}$ of the marbles that are NOT blue are green. How many green marbles are there?', '[]', '5', '(40/2)/4', 'Not blue: $40 \div 2 = 20$ marbles. One fourth of 20 is $20 \div 4 = 5$ green marbles.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 20, not blue 20; 1/4 of 20 = 5 green.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06b5cc50-aeb1-4337-ad29-658aecbeaaee', 'BA3.10', 3, 'numeric', 'Fraction of a group', 'Mai had 45 dollars. She spent $\frac{2}{3}$ of it on a book and $\frac{1}{5}$ of it on lunch. How many dollars does she have left?', '[]', '6', '45-45/3*2-45/5', 'Book: $45 \div 3 \times 2 = 30$ dollars. Lunch: $45 \div 5 = 9$ dollars. $45 - 30 - 9 = 6$ dollars are left.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 of 45 = 30; 1/5 of 45 = 9; 45 - 39 = 6.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d0c478f-7cde-4943-bd9f-10c25ed68508', 'BA3.10', 3, 'numeric', 'Fraction of a group', 'In a box of marbles, half are red and $\frac{1}{3}$ are blue. The other 5 marbles are green. How many marbles are in the box?', '[]', '30', '5*6', '$\frac{1}{2}$ + $\frac{1}{3}$ = $\frac{5}{6}$ of the marbles are red or blue (sixths: 3 + 2 = 5). So the 5 green marbles are $\frac{1}{6}$ of the box, and the box has $6 \times 5 = 30$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 + 1/3 = 5/6, so green is 1/6 = 5 marbles; total 30.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
