INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fd92519-5af7-4859-b664-d30876f877ab', 'BA3.10', 3, 'choice', 'Fraction of a group', 'Only one of these statements is true. Which one?', '["$\\frac{1}{4}$ of 20 is equal to $\\frac{1}{5}$ of 25.","$\\frac{1}{2}$ of 10 is equal to $\\frac{1}{3}$ of 12.","$\\frac{1}{3}$ of 15 is equal to $\\frac{1}{5}$ of 20.","$\\frac{2}{3}$ of 9 is equal to $\\frac{1}{2}$ of 8."]', '$\frac{1}{4}$ of 20 is equal to $\frac{1}{5}$ of 25.', NULL, '$\frac{1}{4}$ of 20 is 5 and $\frac{1}{5}$ of 25 is 5. In the others the two amounts are 5 and 4, 5 and 4, 6 and 4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$ of 20 is equal to $\\frac{1}{5}$ of 25.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 vs 4; 5 vs 4; 6 vs 4; 5 vs 5. Only the last is true.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
