INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bfa709a-219c-4730-b5aa-92a920ad22bf', 'BA3.10', 3, 'choice', 'Equivalent fractions', 'Tara has run $\frac{3}{5}$ of a race. If the race were cut into 25 equal parts, how many parts would she have run?', '["3","10","15","25"]', '15', '3*5', '5 times 5 is 25, so multiply the top by 5 too: $3 \times 5 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 15/25.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
