VALUES ('ac005e27-2086-4e69-84d8-86d52d44a6e2', 'BA3.10', 3, 'choice', 'Equivalent fractions', 'Three of these four fractions are equal to each other. Which fraction is the odd one out?', '["$\\frac{2}{3}$","$\\frac{4}{6}$","$\\frac{6}{9}$","$\\frac{8}{10}$"]', '$\frac{8}{10}$', NULL, '$\frac{2}{3}$, $\frac{4}{6}$ and $\frac{6}{9}$ are all two thirds. $\frac{8}{10}$ is four fifths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6 = 6/9; 8/10 = 4/5 differs.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
