INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18fdc8ed-8aa3-4c4f-8edb-a0cb1188396e', 'BA3.10', 3, 'numeric', 'Equivalent fractions', 'A fraction is equal to $\frac{1}{2}$. Its top number and bottom number add up to 12. What is its bottom number?', '[]', '8', '8', 'Halves have a bottom number twice the top. Top + bottom = 12 means the top is 4 and the bottom is 8: $\frac{4}{8}$ = $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n/(2n), n + 2n = 12, n = 4: 4/8, bottom 8.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
