INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ae6231b-0881-4cd7-92e0-99eb78ffff71', 'BA3.10', 3, 'choice', 'Comparing fractions', 'Put these four fractions in order, smallest first. Which list is right?', '["$\\frac{1}{2}$, $\\frac{3}{8}$, $\\frac{5}{8}$, $\\frac{3}{4}$","$\\frac{3}{8}$, $\\frac{1}{2}$, $\\frac{5}{8}$, $\\frac{3}{4}$","$\\frac{3}{8}$, $\\frac{1}{2}$, $\\frac{3}{4}$, $\\frac{5}{8}$","$\\frac{3}{4}$, $\\frac{5}{8}$, $\\frac{1}{2}$, $\\frac{3}{8}$"]', '$\frac{3}{8}$, $\frac{1}{2}$, $\frac{5}{8}$, $\frac{3}{4}$', NULL, 'In eighths: $\frac{3}{8}$, $\frac{4}{8}$, $\frac{5}{8}$, $\frac{6}{8}$. That is the order shown.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$, $\\frac{1}{2}$, $\\frac{5}{8}$, $\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In eighths: 3/8, 4/8, 5/8, 6/8.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
