INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ea85c8b-152d-40a1-873e-3b4b69218939', 'BA3.10', 3, 'numeric', 'Comparing fractions', 'A fraction with a bottom number of 8 is greater than $\frac{1}{2}$ and less than $\frac{3}{4}$. What is the fraction?', '[]', '5/8', '5/8', '$\frac{1}{2}$ = $\frac{4}{8}$ and $\frac{3}{4}$ = $\frac{6}{8}$. The only eighth between them is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 < x/8 < 6/8: 5/8.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
