INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('874c62bb-88bb-4375-95da-f70d04f79fe9', 'BA3.10', 3, 'choice', 'Comparing fractions', 'Which comparison is true?', '["$\\frac{2}{3}$ is less than $\\frac{2}{5}$.","$\\frac{5}{8}$ is less than $\\frac{3}{8}$.","$\\frac{4}{9}$ is less than $\\frac{4}{7}$.","$\\frac{1}{4}$ is greater than $\\frac{1}{3}$."]', '$\frac{4}{9}$ is less than $\frac{4}{7}$.', NULL, 'With the same top number, the larger bottom number makes the smaller fraction. 9 is more than 7, so $\frac{4}{9}$ is less than $\frac{4}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{9}$ is less than $\\frac{4}{7}$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator, smaller denominator larger: 4/9 < 4/7 true; others false.","run_id":"claude-code","at":"2026-10-19T01:27:09.104Z"}}', 'ai', NULL, NULL)
