INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771d467d-cac9-4ce0-84ba-dcdfc185651a', 'BA3.11', 2, 'choice', 'Deciding whether an answer is reasonable', 'Sam says that $612 - 389 = 1{,}001$. Which sentence shows that Sam must be wrong?', '["The answer must be more than 612, so 1,001 is a good answer.","The answer must be about 1,000, because 612 + 389 is about 1,000.","Taking something away leaves less than 612, but 1,001 is more than 612.","The answer must be more than 389 + 612, so 1,001 is too small."]', 'Taking something away leaves less than 612, but 1,001 is more than 612.', NULL, 'Subtracting 389 from 612 leaves a number smaller than 612. Since 1,001 is bigger than 612, Sam cannot be right. (The real answer is 223.)', 'checked', '{"lint":[],"solve":{"answer":"Taking something away leaves less than 612, but 1,001 is more than 612.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"612 - 389 must be less than 612, but 1,001 is more.","run_id":"claude-code","at":"2026-10-19T01:27:09.143Z"}}', 'ai', NULL, NULL)
