VALUES ('ce59e8f6-8536-4e80-b560-f3260861bf02', 'BA3.11', 3, 'choice', 'Rounding to the nearest 100', 'Which of these numbers rounds to 2,400 when rounded to the nearest 100?', '["$2{,}349$","$2{,}251$","$2{,}451$","$2{,}351$"]', '$2{,}351$', NULL, '2,351 is between 2,300 and 2,400 and is past the halfway mark of 2,350, so it rounds up to 2,400. 2,349 and 2,251 round to 2,300, and 2,451 rounds to 2,500.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}351$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,351 -> 2,400; 2,349 -> 2,300; 2,451 -> 2,500; 2,251 -> 2,300.","run_id":"claude-code","at":"2026-10-19T01:27:09.143Z"}}', 'ai', NULL, NULL)
