INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84bc32ee-0cc8-4a64-b892-c9c86a40d182', 'BA3.12', 3, 'choice', 'Area of a shape made of rectangles', 'A rectangle is 12 meters by 10 meters. A square with 4-meter sides is cut out of one corner. What is the perimeter of the shape that is left?', '["$36$ meters","$52$ meters","$44$ meters","$40$ meters"]', '$44$ meters', NULL, 'Cutting out a corner does not change the distance around: the missing top and side are replaced by two edges of the same total length. The perimeter stays 2 times (12 + 10) = 44 meters.', 'checked', '{"lint":[],"solve":{"answer":"$44$ meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cutting a square from a corner keeps the perimeter: 2 x (12 + 10) = 44.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
