VALUES ('34717f8f-d208-4f46-902c-7e59b8429bdf', 'BA3.12', 3, 'choice', 'Area of a shape made of rectangles', 'Three identical squares are put side by side in a row to make a rectangle with an area of 75 square centimeters. How long is the side of one square?', '["$3$ centimeters","$5$ centimeters","$15$ centimeters","$25$ centimeters"]', '$5$ centimeters', NULL, 'Each square has area 75 divided by 3 = 25. Since 5 times 5 = 25, each side is 5 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$5$ centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each square 75 / 3 = 25; side 5.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
