INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eb70824-fea5-4a7f-baef-15d815fd4f59', 'BA3.12', 3, 'numeric', 'Area of a shape made of rectangles', 'A rectangle is 16 centimeters by 9 centimeters. One straight cut makes two rectangles. One of them is 10 centimeters by 9 centimeters. What is the area of the other one, in square centimeters?', '[]', '54', '(16-10)*9', 'The other piece is (16 - 10) = 6 centimeters by 9 centimeters. Area = 6 times 9 = 54 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 x 9 = 144; 10 x 9 = 90; other 54 (6 by 9).","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
