INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebc6e5dd-360b-4298-8a65-d3430bb5a29f', 'BA3.12', 3, 'choice', 'Area of a shape made of rectangles', 'Which of these has the greatest area?', '["A square with 9-meter sides","A rectangle 11 meters by 7 meters","A rectangle 12 meters by 6 meters","A rectangle 10 meters by 8 meters with a 4-meter by 3-meter rectangle cut out of a corner"]', 'A square with 9-meter sides', NULL, 'The areas are 81, 77, 72 and 80 - 12 = 68 square meters. The square is greatest.', 'checked', '{"lint":[],"solve":{"answer":"A square with 9-meter sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 - 12 = 68; 77; 72; 81. Greatest 81.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
