INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66a54367-1035-4453-90bb-688968dc2224', 'BA3.12', 3, 'numeric', 'Area of a shape made of rectangles', 'A square of 10 meters by 10 meters has an 8-meter by 3-meter rectangle cut out of one corner and a 2-meter by 2-meter square cut out of a different corner. What area is left, in square meters?', '[]', '72', '10*10-8*3-2*2', 'The big square has area 100. Take away 24 and 4: 100 - 24 - 4 = 72 square meters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 24 - 4 = 72 (8 + 2 <= 10 so the cut-outs cannot overlap).","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e28464b1-9459-4190-9bd9-fa86a3e7c030', 'BA3.12', 3, 'numeric', 'Area and perimeter compared', 'A rectangle has whole-number sides and a perimeter of 20 centimeters. What is the greatest area it could have, in square centimeters?', '[]', '25', '5*5', 'Length plus width = 10. The pairs are 1 and 9, 2 and 8, 3 and 7, 4 and 6, 5 and 5, with areas 9, 16, 21, 24 and 25. The greatest is 25.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a child who thinks a square is not a rectangle answers 24; Q96 in this set says ''A square counts as a rectangle'' and this one should too.","work":"L + W = 10: 1x9 = 9, 2x8 = 16, 3x7 = 21, 4x6 = 24, 5x5 = 25. Greatest 25 (a square is a rectangle).","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24152cc1-8d7d-40bc-baa7-09315b735b47', 'BA3.12', 3, 'numeric', 'Area and perimeter compared', 'A fence of 20 meters goes all the way around a rectangular pen. The pen is 4 meters longer than it is wide. What is the area of the pen, in square meters?', '[]', '21', '7*3', 'Length plus width = 20 divided by 2 = 10. The length is 4 more than the width, so the sides are 7 and 3 (7 + 3 = 10 and 7 - 3 = 4). Area = 7 times 3 = 21 square meters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L + W = 10, L = W + 4: W = 3, L = 7; area 21.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
