INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6b036f8-0717-4edc-acbb-b543dfd93e08', 'BA3.12', 3, 'choice', 'Area and perimeter compared', 'Which pair of rectangles has the same perimeter?', '["3 cm by 8 cm and 4 cm by 6 cm","2 cm by 12 cm and 4 cm by 6 cm","2 cm by 8 cm and 3 cm by 6 cm","3 cm by 8 cm and 5 cm by 6 cm"]', '3 cm by 8 cm and 5 cm by 6 cm', NULL, 'The perimeters are 22 and 22 for the first pair. The other pairs have perimeters 22 and 20, 28 and 20, and 20 and 18.', 'checked', '{"lint":[],"solve":{"answer":"3 cm by 8 cm and 5 cm by 6 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28/20; 20/18; 22/20; 22/22. Only 3 by 8 and 5 by 6.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
