INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76427bdf-13ab-4447-8409-081690d685f2', 'BA3.12', 3, 'numeric', 'Area and perimeter compared', 'A rectangle is 10 meters long and 6 meters wide. Its length is changed to 20 meters. How many meters greater is the perimeter of the new rectangle than the old one?', '[]', '20', '2*(20+6)-2*(10+6)', 'Old perimeter: 2 times 16 = 32. New perimeter: 2 times 26 = 52. 52 - 32 = 20 meters greater.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 32, new 2 x (20 + 6) = 52; difference 20.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
