INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae84d1e-86d4-46e9-8392-7f866957cc1d', 'BA3.12', 3, 'numeric', 'Area and perimeter compared', 'A square and a rectangle both have a perimeter of 36 meters. The rectangle is 12 meters long. How many square meters greater is the area of the square than the area of the rectangle?', '[]', '9', '9*9-12*6', 'The square has sides of 36 divided by 4 = 9, so its area is 81. The rectangle has width 18 - 12 = 6, so its area is 72. 81 - 72 = 9 square meters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square side 9, area 81. Rectangle 12 by 6, area 72. 81 - 72 = 9.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
