INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1c30476-acf6-4183-9f65-4e62a3bcdd70', 'BA3.12', 3, 'choice', 'Area and perimeter compared', 'A rectangle is 8 centimeters by 5 centimeters. Another rectangle has the same area and is 10 centimeters long. What is the perimeter of the second rectangle?', '["$26$ centimeters","$40$ centimeters","$14$ centimeters","$28$ centimeters"]', '$28$ centimeters', NULL, 'The area is 8 times 5 = 40. The second rectangle has width 40 divided by 10 = 4. Its perimeter is 10 + 4 + 10 + 4 = 28 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$28$ centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 40; width 40 / 10 = 4; perimeter 2 x 14 = 28.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
