INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('314effb0-0d47-4bc9-bbf5-0b5f29f46b25', 'BA3.12', 3, 'choice', 'Area and perimeter compared', 'Which sentence is true?', '["Two rectangles with the same area must have the same perimeter.","A rectangle with a greater area must have a greater perimeter.","Two rectangles can have the same perimeter but different areas.","Two rectangles with the same perimeter must have the same area."]', 'Two rectangles can have the same perimeter but different areas.', NULL, 'A 1 by 9 rectangle and a 5 by 5 rectangle both have perimeter 20, but their areas are 9 and 25. The other sentences are false for the same kind of example.', 'checked', '{"lint":[],"solve":{"answer":"Two rectangles can have the same perimeter but different areas.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"E.g. 1x5 and 2x4 both have perimeter 12, areas 5 and 8.","run_id":"claude-code","at":"2026-10-19T01:27:09.181Z"}}', 'ai', NULL, NULL)
