INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04ead05e-8d6d-44bf-8443-3bc361aeb0cf', 'BA4.01', 3, 'choice', 'Classifying angles by size', 'Two acute angles are put side by side to make one bigger angle. Which kind of angle can NEVER be made this way?', '["obtuse","right","straight","acute"]', 'straight', NULL, 'Two acute angles add to less than 90 + 90 = 180, so they can never make exactly 180 (a straight angle). They can make acute, right or obtuse angles, for example 20 + 30, 45 + 45 and 80 + 80.', 'checked', '{"lint":[],"solve":{"answer":"straight","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two acute angles total less than 90 + 90 = 180, so never straight. Right (45+45), obtuse (80+80), acute (20+30) are all possible.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e0a3a27-49ee-4b47-9697-42219a10b71b', 'BA4.01', 3, 'numeric', 'Missing angles on a line, in a right angle and around a point', 'Two angles lie on a straight line. One is $20^\circ$ bigger than the other. How many degrees is the smaller angle?', '[]', '80', '(180-20)/2', 'If the angles were equal they would be 90 each. Take away the extra 20: 180 - 20 = 160, and 160 / 2 = 80. The angles are 80 and 100.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (x + 20) = 180, 2x = 160, x = 80.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
