INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('961efb58-bcf3-45c7-83f7-eefd00424f3c', 'BA4.01', 3, 'choice', 'Missing angles on a line, in a right angle and around a point', 'Two angles together make a right angle, and one is twice as big as the other. How many degrees is the smaller angle?', '["$45^\\circ$","$30^\\circ$","$60^\\circ$","$15^\\circ$"]', '$30^\circ$', NULL, 'The angles are 1 part and 2 parts, 3 parts in all. 90 / 3 = 30 degrees per part, so the smaller angle is 30.', 'checked', '{"lint":[],"solve":{"answer":"$30^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x = 90, x = 30.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
