INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80ae2a8a-4cac-46a3-baf7-a232fbe087ef', 'BA4.01', 3, 'numeric', 'Missing angles on a line, in a right angle and around a point', 'Two angles lie on a straight line. One is four times as big as the other. How many degrees is the larger angle?', '[]', '144', '4*180/5', 'There are 1 + 4 = 5 equal parts in 180 degrees. Each part is 36, so the larger angle is 4 x 36 = 144.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 4x = 180, x = 36; larger = 144.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
