INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e357a54-ae2e-4af7-853d-7370cc46c587', 'BA4.01', 3, 'numeric', 'Missing angles on a line, in a right angle and around a point', 'A straight angle is cut into three angles. The second angle is twice the first and the third is three times the first. How many degrees is the first angle?', '[]', '30', '180/6', 'In parts: 1 + 2 + 3 = 6 parts make 180 degrees, so one part is 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, 6x = 180, x = 30.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3af3063-920b-405b-9f88-2c23c191b25b', 'BA4.01', 3, 'numeric', 'Missing angles on a line, in a right angle and around a point', 'At 8:00 the hour hand points at the 8 and the minute hand points at the 12. The 12 numbers on a clock are spread evenly around a full turn. What is the smaller of the two angles between the hands, in degrees?', '[]', '120', '4*30', 'Each gap is 30 degrees. From 8 around to 12 is 4 gaps, which is 120 degrees. The other way round is 8 gaps, 240 degrees. The smaller is 120.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From 12 clockwise to 8 is 8 x 30 = 240; the smaller angle is 360 - 240 = 120.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a40fd87-fa34-40f5-9a4a-bfd15c36ed9e', 'BA4.01', 3, 'choice', 'Missing angles on a line, in a right angle and around a point', 'Four angles fit exactly around a point. Three of them are equal and the fourth is $60^\circ$. How many degrees is each of the three equal angles?', '["$75^\\circ$","$100^\\circ$","$90^\\circ$","$120^\\circ$"]', '$100^\circ$', NULL, '360 - 60 = 300, shared by three equal angles: 300 / 3 = 100.', 'checked', '{"lint":[],"solve":{"answer":"$100^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(360 - 60) / 3 = 100.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb4cbf24-423b-4f1d-999d-80173d0d63e4', 'BA4.01', 3, 'choice', 'Angle sum of a triangle', 'The angles of a triangle are $x^\circ$, $2x^\circ$ and $3x^\circ$. What is the smallest angle?', '["$30^\\circ$","$60^\\circ$","$45^\\circ$","$90^\\circ$"]', '$30^\circ$', NULL, 'x + 2x + 3x = 6x = 180, so x = 30. The smallest angle is 30 degrees.', 'checked', '{"lint":[],"solve":{"answer":"$30^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, x = 30. Smallest is 30.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
