INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2b07d8b-a4f2-47fc-b37b-633f52c7e0f6', 'BA4.01', 3, 'numeric', 'Angle sum of a triangle', 'The angles of a triangle are $a^\circ$, $(a + 20)^\circ$ and $(a + 40)^\circ$, where $a$ is a whole number. How many degrees is the largest angle?', '[]', '80', '(180-60)/3+40', 'Together: 3a + 60 = 180, so 3a = 120 and a = 40. The largest is 40 + 40 = 80.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a + 60 = 180, a = 40; angles 40, 60, 80; largest 80.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
