INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fc8c370-0958-427f-975a-934428eb6428', 'BA4.01', 3, 'numeric', 'Angle sum of a triangle', 'Two angles of a triangle are $85^\circ$ and $86^\circ$. How many degrees is the third angle?', '[]', '9', '180-85-86', '85 + 86 = 171, and 180 - 171 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 85 - 86 = 9.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
