INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b53800d7-02a2-4ba6-8941-244cc1627aa8', 'BA4.01', 3, 'numeric', 'Angle sum of a triangle', 'A student says a triangle has angles of $64^\circ$, $58^\circ$ and $62^\circ$. By how many degrees do these three angles miss the correct total for a triangle?', '[]', '4', '64+58+62-180', '64 + 58 + 62 = 184, but a triangle''s angles add to 180. They miss by 4 degrees.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 + 58 + 62 = 184; 184 - 180 = 4.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
