INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('748c45d6-030e-4eb3-aabd-35f46c8892dc', 'BA4.01', 3, 'choice', 'Angle sum of a triangle', 'A triangle has angles of $a^\circ$ and $b^\circ$. Which expression gives its third angle, in degrees?', '["$180 - a + b$","$90 - a - b$","$360 - a - b$","$180 - a - b$"]', '$180 - a - b$', NULL, 'The three angles add to 180, so the third angle is 180 minus the other two: 180 - a - b.', 'checked', '{"lint":[],"solve":{"answer":"$180 - a - b$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third angle = 180 - a - b.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
