INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('913474ef-dd3e-40f6-a7f7-05786da99840', 'BA4.01', 3, 'numeric', 'Triangles by their sides', 'An isosceles triangle has a perimeter of 29 cm and a base of 11 cm. The other two sides are equal. How long is each of them, in centimeters?', '[]', '9', '(29-11)/2', '29 - 11 = 18, shared by two equal sides: 18 / 2 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(29 - 11) / 2 = 9 (valid: 9 + 9 > 11).","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
