INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22644cb7-36a8-413b-bb08-6dab56b6bddf', 'BA4.01', 3, 'numeric', 'Triangles by their sides', 'An equilateral triangle has a perimeter of 36 cm. A second equilateral triangle has sides that are each 3 cm shorter. What is the second triangle''s perimeter, in centimeters?', '[]', '27', '3*(36/3-3)', 'The first triangle has sides of 36 / 3 = 12 cm. The second has sides of 9 cm, so its perimeter is 3 x 9 = 27.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First side 36/3 = 12; second side 9; perimeter 27.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
