INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d0f49f6-aec6-4602-8255-6109d2a0f981', 'BA4.01', 3, 'numeric', 'Triangles by their sides', 'Here are five triangles, with side lengths in cm: (3, 3, 5), (4, 5, 6), (7, 7, 2), (6, 6, 6), (2, 8, 8). How many of them have exactly two equal sides?', '[]', '3', '3', '(3, 3, 5), (7, 7, 2) and (2, 8, 8) each have exactly two equal sides. (4, 5, 6) has none and (6, 6, 6) has three. So there are 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,3,5) yes; (4,5,6) no; (7,7,2) yes; (6,6,6) no, all three equal; (2,8,8) yes. Count 3.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa04bd14-c3e0-42d6-a7fd-afe1604231f6', 'BA4.01', 3, 'choice', 'Triangles by their sides', 'A triangle has a perimeter of 24 cm, and two of its sides are 8 cm each. By its sides, what kind of triangle must it be?', '["scalene","right","equilateral","obtuse"]', 'equilateral', NULL, '8 + 8 = 16, so the third side is 24 - 16 = 8 cm. All three sides are 8 cm, so it is equilateral.', 'checked', '{"lint":[],"solve":{"answer":"equilateral","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side 24 - 16 = 8, so all sides 8: equilateral.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
