INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0acafa2e-31ac-4033-a08c-2904f065512e', 'BA4.01', 3, 'numeric', 'Triangles by their angles', 'What is the smallest number of acute angles that any triangle can have?', '[]', '2', '2', 'A triangle''s angles add to 180, so two angles that are 90 or more would already use up 180. So at least two angles must be acute.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At most one angle can be 90 or more, so every triangle has at least 2 acute angles; e.g. a right triangle has exactly 2.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c08e5c5-652e-4202-80b3-a543da5ab9b2', 'BA4.01', 3, 'choice', 'Triangles by their angles', 'The angles of a triangle are $x^\circ$, $x^\circ$ and $2x^\circ$. What kind of triangle is it, by its angles?', '["acute","obtuse","right","equilateral"]', 'right', NULL, 'x + x + 2x = 4x = 180, so x = 45. The angles are 45, 45 and 90, which makes a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x = 180, x = 45; angles 45, 45, 90: right.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c8578a3-9043-42b2-8f37-a1267669eace', 'BA4.01', 3, 'choice', 'Triangles by their angles', 'One angle of a triangle is $100^\circ$. Which statement must be true?', '["The other two angles add to $100^\\circ$.","The other two angles are both acute.","The triangle is isosceles.","The other two angles are equal."]', 'The other two angles are both acute.', NULL, 'The other two angles add to 180 - 100 = 80 degrees, so each is less than 80 and therefore acute. They need not be equal, and they do not add to 100.', 'checked', '{"lint":[],"solve":{"answer":"The other two angles are both acute.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other two add to 80, so each is less than 80: both acute. Not necessarily equal/isosceles; they add to 80 not 100.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f6646d5-69a3-4c84-b93d-98df8976a11e', 'BA4.01', 3, 'numeric', 'Triangles by their angles', 'Here are five sets of angles: (20, 30, 130), (60, 60, 60), (100, 40, 40), (90, 45, 45), (10, 10, 160). How many of them are the angles of an obtuse triangle?', '[]', '3', '3', 'Each set adds to 180. An obtuse triangle has one angle over 90: (20, 30, 130), (100, 40, 40) and (10, 10, 160). That is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(20,30,130) obtuse; (60,60,60) acute; (100,40,40) obtuse; (90,45,45) right; (10,10,160) obtuse. All sum to 180. Count 3.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdfb744c-daab-4b4f-9358-eb242a44d8ab', 'BA4.01', 3, 'choice', 'Angles of isosceles and equilateral triangles', 'An isosceles triangle has an angle of $100^\circ$, and its other two angles are equal. How many degrees is each of the other two angles?', '["$40^\\circ$","$80^\\circ$","$100^\\circ$","$50^\\circ$"]', '$40^\circ$', NULL, '180 - 100 = 80, shared by two equal angles: 80 / 2 = 40.', 'checked', '{"lint":[],"solve":{"answer":"$40^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(180 - 100) / 2 = 40.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
