INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e99dacc5-a4a3-4d64-8bca-0b592fb1e698', 'BA4.01', 3, 'choice', 'Angles of isosceles and equilateral triangles', 'The top angle of an isosceles triangle is three times as big as each of its two equal base angles. How many degrees is the top angle?', '["$90^\\circ$","$60^\\circ$","$120^\\circ$","$108^\\circ$"]', '$108^\circ$', NULL, 'In parts: the top is 3 parts and each base angle 1 part, 5 parts in all. 180 / 5 = 36, so the top angle is 3 x 36 = 108.', 'checked', '{"lint":[],"solve":{"answer":"$108^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b + b + 3b = 180, b = 36; top = 108.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
