INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26132b7c-aa2f-4f99-948f-0b6d47f7b21f', 'BA4.01', 3, 'choice', 'Angles of isosceles and equilateral triangles', 'Two identical equilateral triangles share one side to make a four-sided shape. How many degrees is the biggest angle of the new shape?', '["$60^\\circ$","$90^\\circ$","$180^\\circ$","$120^\\circ$"]', '$120^\circ$', NULL, 'Two of the shape''s corners are made from two triangle angles side by side: 60 + 60 = 120. The other two corners are 60 each. So the biggest is 120.', 'checked', '{"lint":[],"solve":{"answer":"$120^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The shape is a rhombus with angles 60, 120, 60, 120 (the shared-side ends get 60 + 60). Biggest 120.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07249e26-2f6b-4775-bb65-3530bc748de6', 'BA4.01', 3, 'numeric', 'Angles of isosceles and equilateral triangles', 'In an isosceles triangle, each of the two equal base angles is $15^\circ$ bigger than the top angle. How many degrees is the top angle?', '[]', '50', '(180-30)/3', 'If the top angle is t, the base angles are t + 15 each. So 3t + 30 = 180, 3t = 150 and t = 50.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t + 2(t + 15) = 180, 3t = 150, t = 50 (base angles 65).","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bbe6438-ab69-4b39-8773-3692809380e2', 'BA4.01', 3, 'choice', 'Kinds of quadrilaterals', 'Which shape has four equal sides AND four equal angles?', '["rhombus","rectangle","square","trapezoid"]', 'square', NULL, 'Four equal angles make each one 90 degrees, so a rectangle; adding four equal sides gives a square. A rhombus has equal sides but not always equal angles; a rectangle has equal angles but not always equal sides.', 'checked', '{"lint":[],"solve":{"answer":"square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four equal sides and four equal angles: square.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f835a8-3578-47cd-a5c3-2061c6a39853', 'BA4.01', 3, 'numeric', 'Kinds of quadrilaterals', 'A square is cut along one diagonal into two triangles. How many degrees is each acute angle of these triangles?', '[]', '45', '90/2', 'The diagonal cuts a 90 degree corner into two equal angles: 90 / 2 = 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The diagonal bisects the right angles: 90/2 = 45.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed4d2eef-4a4e-47fb-a18e-4938497d4f7d', 'BA4.01', 3, 'numeric', 'Kinds of quadrilaterals', 'A rectangle is cut along a diagonal into two triangles. In one of the triangles, the two angles that are not the right angle add up to how many degrees?', '[]', '90', '180-90', 'A triangle''s angles add to 180 and one of them is 90, so the other two add to 180 - 90 = 90.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 90 = 90.","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
