VALUES ('10183131-a939-4bff-a610-d77017b083f9', 'BA4.03', 3, 'numeric', 'Evaluating expressions with exponents', 'Find each power first, then combine them. What is the value of $3^3 - 2^4 + 4^2$?', '[]', '27', '3^3-2^4+4^2', '$3^3 = 27$, $2^4 = 16$ and $4^2 = 16$. Then $27 - 16 + 16 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 - 16 + 16 = 27.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
