VALUES ('845563f2-f25a-4786-9ef7-4c5c74ba0adb', 'BA4.03', 3, 'choice', 'Evaluating expressions with exponents', 'Jo works out $(5^2 - 3^2) \times 2^3$. What number does Jo get?', '["16","128","96","224"]', '128', '(5^2-3^2)*2^3', '$5^2 - 3^2 = 25 - 9 = 16$ and $2^3 = 8$. Then $16 \times 8 = 128$.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(25 - 9) x 8 = 16 x 8 = 128.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
