VALUES ('3e420a86-2b79-4887-b782-ccb6771cd60b', 'BA4.03', 3, 'numeric', 'Evaluating expressions with exponents', 'Evaluate $10^2 - 9^2 + 8^2 - 7^2$.', '[]', '34', '10^2-9^2+8^2-7^2', '$100 - 81 = 19$ and $64 - 49 = 15$. Then $19 + 15 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 81 + 64 - 49 = 34.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
