VALUES ('2dc752fb-ac60-4c37-92e1-bfe9a78e99d6', 'BA4.03', 3, 'numeric', 'Evaluating expressions with exponents', 'Find $3^3 \times 2^2 - 2^3 \times 3^2$.', '[]', '36', '3^3*2^2-2^3*3^2', '$27 \times 4 = 108$ and $8 \times 9 = 72$. Then $108 - 72 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27x4 = 108; 8x9 = 72; 108 - 72 = 36.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
