INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d5001b6-9186-4940-8c63-dae1fee56895', 'BA4.03', 3, 'numeric', 'Order of operations', 'Evaluate $2 \times (3 + 4)^2 - 5 \times 2^3$.', '[]', '58', '2*(3+4)^2-5*2^3', 'Parentheses: $3 + 4 = 7$. Exponents: $7^2 = 49$ and $2^3 = 8$. Multiply: $2 \times 49 = 98$ and $5 \times 8 = 40$. Subtract: $98 - 40 = 58$.', 'checked', '{"lint":[],"solve":{"answer":"58","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 49 = 98; 5 x 8 = 40; 98 - 40 = 58.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
