INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3711bd5b-c132-4e05-89c5-317531fe37ab', 'BA4.03', 3, 'choice', 'Order of operations', 'Where can parentheses be put in $2 + 3 \times 4^2$ to make its value 80?', '["$2 + (3 \\times 4)^2$","$(2 + 3 \\times 4)^2$","$((2 + 3) \\times 4)^2$","$(2 + 3) \\times 4^2$"]', '$(2 + 3) \times 4^2$', NULL, '$(2 + 3) \times 4^2 = 5 \times 16 = 80$. The others give 146, 196 and 400.', 'checked', '{"lint":[],"solve":{"answer":"$(2 + 3) \\times 4^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+3)x16 = 80; (14)^2=196; 20^2=400; 2+144=146.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
