INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b45eb632-08fb-4213-8a03-9ab459bbddf1', 'BA4.03', 3, 'numeric', 'Order of operations', 'Tess starts with 100 and takes away the value of $2 \times (4^2 - 6) \div 5$. What number is left?', '[]', '96', '100-2*(4^2-6)/5', 'Inside the parentheses: $16 - 6 = 10$. Then $2 \times 10 = 20$ and $20 \div 5 = 4$. Finally $100 - 4 = 96$.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^2-6 = 10; 2x10 = 20; 20/5 = 4; 100 - 4 = 96.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
