INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb73fd5f-2950-4ab8-9070-2147faa6e2cf', 'BA4.03', 3, 'numeric', 'Order of operations', 'Subtract $2^2$ and $3^2$ from $(2 + 3)^2$. What is left?', '[]', '12', '(2+3)^2-2^2-3^2', '$(2 + 3)^2 = 25$. Then $25 - 4 - 9 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 - 4 - 9 = 12.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
