VALUES ('143a511f-be96-4489-a8fe-6dd169f6a037', 'BA4.03', 3, 'numeric', 'Order of operations', 'What is $48 \div 2^3 \times 3 - 4$?', '[]', '14', '48/2^3*3-4', 'Exponent: $2^3 = 8$. Then work left to right: $48 \div 8 = 6$, $6 \times 3 = 18$, and $18 - 4 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8; 48/8 = 6; 6x3 = 18; 18 - 4 = 14.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
