INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8b75ca8-6f22-40d8-9bb7-0cee67f2153f', 'BA4.03', 3, 'numeric', 'Exponent puzzles and patterns', 'The units digits of $3^1, 3^2, 3^3, 3^4$ are 3, 9, 7, 1, and then the pattern repeats in the same order. What is the units digit of $3^{20}$?', '[]', '1', '1', 'The pattern repeats every 4 powers, and 20 is a multiple of 4, so $3^{20}$ ends in the same digit as $3^4$: 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cycle of 4; 20 is a multiple of 4, so like 3^4: 1.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
