VALUES ('e3b350ea-67e6-4a3c-a67b-0f0fe82601fb', 'BA4.03', 3, 'numeric', 'Exponent puzzles and patterns', 'What is the smallest whole number you can multiply 12 by to get a perfect square?', '[]', '3', '3', '$12 \times 1 = 12$ and $12 \times 2 = 24$ are not squares. $12 \times 3 = 36 = 6^2$ is.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2^2 x 3; multiply by 3 to get 36.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
