INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b69e0750-0006-4748-b036-d45a353c05a6', 'BA4.04', 3, 'choice', 'Organized lists', 'How many 3-digit numbers have digits that add up to 4?', '["4","6","10","12"]', '10', '10', 'Hundreds digit 1: the other two add to 3 (03, 12, 21, 30), 4 numbers. Hundreds digit 2: others add to 2 (02, 11, 20), 3 numbers. Hundreds digit 3: 2 numbers. Hundreds digit 4: 1 number. $4 + 3 + 2 + 1 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400,310,301,220,211,202,130,121,112,103 = 10.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
