INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff921605-85d8-4b7a-ad0d-cdfa2878fcdd', 'BA4.04', 3, 'numeric', 'Organized lists', 'How many ways can you make 30 cents using nickels (5 cents), dimes (10 cents) and quarters (25 cents)? The order does not matter.', '[]', '5', '5', 'With a quarter: 5 cents left, so 1 nickel (1 way). With no quarter: 0, 1, 2 or 3 dimes, and nickels for the rest (4 ways). Total: 5 ways.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''using nickels, dimes and quarters'' could be read as needing all three coins (then 0 ways); ''using any of'' would be clearer.","work":"Quarter+nickel (1); no quarter: 3D, 2D+2N, 1D+4N, 6N (4). Total 5.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb04364a-f676-4487-b217-d892fdf80c54', 'BA4.04', 3, 'choice', 'Organized lists', 'A frog climbs 6 stairs, going up 1 or 2 stairs at a time. In how many different ways can it reach the top?', '["12","8","21","13"]', '13', '13', 'Let the number of ways to reach stair n be the sum of the ways to reach n-1 and n-2. For stairs 1 to 6 this gives 1, 2, 3, 5, 8, 13. The answer is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ways: 1,2,3,5,8,13 for 1..6 stairs: 13.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b4af2c5-b78d-42a5-9ada-749f6cd056e4', 'BA4.04', 3, 'numeric', 'Organized lists', 'Three different numbers from 1, 2, 3, 4, 5, 6 are added to make 10. How many different sets of three numbers can do this? The order does not matter.', '[]', '3', '3', 'The sets are {1, 3, 6}, {1, 4, 5} and {2, 3, 5}. No other set of three different numbers adds up to 10. So 3 sets.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"{1,3,6}, {1,4,5}, {2,3,5} = 3.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
