INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42841eb5-689e-4b2c-9076-49c0f010d444', 'BA4.04', 3, 'numeric', 'Organized lists', 'How many 2-digit numbers have a tens digit that is bigger than the ones digit?', '[]', '45', '1+2+3+4+5+6+7+8+9', 'Tens digit 1 has 1 choice for the ones digit (0). Tens digit 2 has 2 (0, 1). Tens digit 9 has 9. Total: $1 + 2 + \ldots + 9 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tens d gives d choices of ones: 1+2+...+9 = 45.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
