INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f54f55-fdd1-40f2-8118-3b092a476266', 'BA4.04', 3, 'numeric', 'How many numbers in a list', 'How many numbers are in the list 5, 12, 19, and so on up to 348, where each number is 7 more than the one before?', '[]', '50', '(348-5)/7+1', '$(348 - 5) \div 7 = 49$ steps, so there are 50 numbers.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(348 - 5)/7 + 1 = 49 + 1 = 50.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
