INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4f1c9ee-a369-4896-bb08-6f28193e45f7', 'BA4.04', 3, 'choice', 'How many numbers in a list', 'How many multiples of 7 are there between 100 and 300?', '["29","28","27","43"]', '28', '42-15+1', 'The first multiple is $7 \times 15 = 105$ and the last is $7 \times 42 = 294$. So there are $42 - 15 + 1 = 28$ of them.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"105 = 7x15 to 294 = 7x42: 42 - 15 + 1 = 28.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
