INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('016bab7c-51ef-4232-9f2a-2a21d208560d', 'BA4.04', 3, 'numeric', 'How many numbers in a list', 'The pages of a book are numbered from 1 to 60. How many digits are printed in all to number the pages?', '[]', '111', '9+51*2', 'Pages 1 to 9 use 1 digit each: 9 digits. Pages 10 to 60 are 51 pages with 2 digits each: 102 digits. Total: 111.', 'checked', '{"lint":[],"solve":{"answer":"111","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-9: 9 digits; 10-60: 51 x 2 = 102; total 111.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
