VALUES ('bff887cd-2935-40d2-9fb2-56a078662a0b', 'BA4.04', 3, 'numeric', 'How many numbers in a list', 'A list starts 100, 97, 94, 91 and keeps going down by 3 until it reaches 10. How many numbers are in the list?', '[]', '31', '(100-10)/3+1', '$(100 - 10) \div 3 = 30$ steps, so there are 31 numbers.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(100 - 10)/3 + 1 = 31.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
