INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d155fe69-0289-4569-b9c6-221d2f6156f6', 'BA4.04', 3, 'choice', 'The multiplication principle', 'A sandwich shop has 3 breads, 5 fillings and 4 sauces. A sandwich has one bread, one filling, and either one sauce or no sauce. How many different sandwiches can be ordered?', '["60","12","75","90"]', '75', '3*5*5', 'The sauce part has 4 + 1 = 5 choices. So $3 \times 5 \times 5 = 75$ sandwiches.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 5 x (4+1) = 75.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
