INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94c4f9c4-0d77-4782-b12f-46bc2650b0d8', 'BA4.04', 3, 'choice', 'The multiplication principle', 'Digits may repeat. How many 2-digit numbers can be made from the digits 0, 1, 2 and 3? A number cannot start with 0.', '["16","9","7","12"]', '12', '3*4', 'The tens digit can be 1, 2 or 3: 3 choices. The ones digit can be any of the 4 digits. $3 \times 4 = 12$ numbers.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tens 1,2,3 (3) x ones 4 = 12.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
