INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54c81000-1f22-4489-9ee4-76afd9293501', 'BA4.04', 3, 'numeric', 'The multiplication principle', 'A flag has 3 stripes in a row, and each stripe is red, white, blue or green. Two stripes next to each other must be different colors. How many different flags can be made?', '[]', '36', '4*3*3', '4 choices for the first stripe. Each next stripe can be any color except the one before it: 3 choices each. $4 \times 3 \times 3 = 36$ flags.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 x 3 = 36.","run_id":"claude-code","at":"2026-10-19T01:28:36.787Z"}}', 'ai', NULL, NULL)
