INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74858fc9-d40b-4ca4-8832-af16bd1ff39a', 'BA4.05', 2, 'choice', 'Divisibility by 2, 3, 5, 9 and 10', 'Which number is divisible by 3 but NOT by 9?', '["$2{,}718$","$4{,}563$","$1{,}236$","$1{,}235$"]', '$1{,}236$', NULL, '1 + 2 + 3 + 6 = 12 is a multiple of 3 but not of 9. The digits of 2,718 and 4,563 add to 18, so they are divisible by 9. The digits of 1,235 add to 11.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}236$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digit sums: 11, 12, 18, 18. 1236 is divisible by 3 not 9.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bf66a39-a181-41b6-a097-1a4231eab5db', 'BA4.05', 2, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'What digit can go in the blank so that the number 7,3_5 is divisible by 9?', '[]', '3', '3', '7 + 3 + 5 = 15 already. The digit sum must be a multiple of 9, and 18 is the next one after 15. So the digit is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 3 + d + 5 = 15 + d, multiple of 9 needs d = 3 (18).","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('915473ba-038e-4fd7-9795-32039e6bfba0', 'BA4.05', 2, 'choice', 'Divisibility by 2, 3, 5, 9 and 10', 'Which statement is true?', '["Every number divisible by 3 is also divisible by 9","Every number divisible by 5 is also divisible by 10","Every number divisible by 2 is also divisible by 10","Every number divisible by 9 is also divisible by 3"]', 'Every number divisible by 9 is also divisible by 3', NULL, 'Since 9 = 3 × 3, any multiple of 9 is a multiple of 3. But 6 is divisible by 3 and not by 9, and 15 is divisible by 5 and not by 10, and 4 is divisible by 2 and not by 10.', 'checked', '{"lint":[],"solve":{"answer":"Every number divisible by 9 is also divisible by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 3 x 3, so multiples of 9 are multiples of 3. Others false (3, 2, 5 counterexamples).","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0951a618-a865-4be2-b2e6-8abde5df798f', 'BA4.05', 2, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'How many numbers from 1 to 50 are divisible by 9?', '[]', '5', '5', 'The multiples of 9 up to 50 are 9, 18, 27, 36 and 45. That is 5 numbers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9, 18, 27, 36, 45: 5.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
