VALUES ('88916488-a1bd-4cb9-956c-3d7407ef3a56', 'BA4.05', 2, 'choice', 'Divisibility by 2, 3, 5, 9 and 10', 'Which number is divisible by both 2 and 5?', '["$1{,}260$","$1{,}265$","$1{,}262$","$1{,}263$"]', '$1{,}260$', NULL, 'Divisible by 2 and 5 means the number ends in 0. Only 1,260 does. 1,265 is divisible by 5 only; 1,262 is divisible by 2 only.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}260$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 10: 1260.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
