INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('696a580f-4e15-4ab4-a1a1-4a9b2e2bb190', 'BA4.05', 2, 'numeric', 'Division puzzles and missing numbers', 'Ben shares 540 marbles equally among some friends. Each friend gets 36 marbles. How many friends are there?', '[]', '15', '540/36', 'The number of friends is 540 ÷ 36. 36 × 10 = 360 and 36 × 5 = 180, which make 540. So 15 friends.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"540/36 = 15.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
