INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8dec6ea-1d26-4712-ba03-6217c56b5e65', 'BA4.05', 2, 'choice', 'Division puzzles and missing numbers', 'Which division has the same answer as $840 \div 20$?', '["$8{,}400 \\div 20$","$840 \\div 2$","$420 \\div 20$","$84 \\div 2$"]', '$84 \div 2$', NULL, '840 ÷ 20 = 42. And 84 ÷ 2 = 42 too. The others give 420, 420 and 21.', 'checked', '{"lint":[],"solve":{"answer":"$84 \\div 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"840/20 = 42 = 84/2. Others 21, 420, 420.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
