INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1059734-2ec5-40dc-9155-ae161622b392', 'BA4.05', 2, 'numeric', 'Division puzzles and missing numbers', 'Pat divides a number by 6 and gets 48. What would she get if she divided the same number by 8?', '[]', '36', '48*6/8', 'The number is 48 × 6 = 288. Then 288 ÷ 8 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number = 288; 288/8 = 36.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
