INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d53d6f1-d292-449f-97cf-01be90f11d88', 'BA4.05', 2, 'numeric', 'Division puzzles and missing numbers', 'Tom has 3 boxes with 24 marbles in each and 2 boxes with 12 marbles in each. He shares all his marbles equally among 8 friends. How many marbles does each friend get?', '[]', '12', '(3*24+2*12)/8', '3 × 24 = 72 and 2 × 12 = 24, so he has 96 marbles. 96 ÷ 8 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 + 24 = 96 marbles; 96/8 = 12.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
