INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('216d3117-c18d-4d52-a07f-1601dd221678', 'BA4.05', 3, 'numeric', 'Long division', 'Find $52{,}416 \div 12$.', '[]', '4368', '52416/12', 'Divide in steps. 52 ÷ 12 = 4 with 4 left; 44 ÷ 12 = 3 with 8 left; 81 ÷ 12 = 6 with 9 left; 96 ÷ 12 = 8. The quotient is 4,368. Check: 4,368 × 12 = 52,416.', 'checked', '{"lint":[],"solve":{"answer":"4368","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52416/12 = 4368 (12 x 4368 = 52416).","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
