INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c92b91b4-ce01-44ac-a544-488cfa834eee', 'BA4.05', 3, 'choice', 'Long division', 'Which is the value of $6{,}048 \div 28$?', '["$206$","$216$","$261$","$226$"]', '$216$', '6048/28', '28 × 200 = 5,600, which leaves 448. And 28 × 16 = 448. So the answer is 200 + 16 = 216.', 'checked', '{"lint":[],"solve":{"answer":"$216$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 x 216 = 6048.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
