INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4f5f47e-16ff-4dd4-9ab3-4615f78e49a4', 'BA4.05', 3, 'choice', 'Long division', 'A bakery bakes 7,280 rolls in 14 batches. Every batch has the same number of rolls. How many rolls are in one batch?', '["$52$","$502$","$520$","$560$"]', '$520$', '7280/14', '14 × 500 = 7,000, which leaves 280. And 14 × 20 = 280. So each batch has 500 + 20 = 520 rolls.', 'checked', '{"lint":[],"solve":{"answer":"$520$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7280/14 = 520.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
