VALUES ('6eb7a3fe-e27e-4454-be17-771320c4e5d3', 'BA4.05', 3, 'choice', 'Long division', 'Which number divided by 23 gives exactly 41?', '["$923$","$933$","$963$","$943$"]', '$943$', '23*41', 'Work backwards: 41 × 23 = 41 × 20 + 41 × 3 = 820 + 123 = 943.', 'checked', '{"lint":[],"solve":{"answer":"$943$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"23 x 41 = 943.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
