VALUES ('6b33c85f-ff32-46a4-93ec-ff18914d7acf', 'BA4.05', 3, 'numeric', 'Long division', 'Find $(2{,}400 + 360) \div 12$.', '[]', '230', '(2400+360)/12', 'Split the sum: 2,400 ÷ 12 = 200 and 360 ÷ 12 = 30. Then 200 + 30 = 230. (Or add first: 2,760 ÷ 12 = 230.)', 'checked', '{"lint":[],"solve":{"answer":"230","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2760/12 = 230.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
