INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b4c92d1-f735-4263-a242-330bbb55c32b', 'BA4.05', 3, 'choice', 'Remainders', 'A number is divided by 9. The quotient is 15 and the remainder is 4. What is the number?', '["$139$","$135$","$144$","$28$"]', '$139$', '15*9+4', 'Number = quotient × 9 + remainder = 15 × 9 + 4 = 135 + 4 = 139.', 'checked', '{"lint":[],"solve":{"answer":"$139$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 15 + 4 = 139.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
