INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11d6fd6a-5149-48db-94f5-625201e8c0e0', 'BA4.05', 3, 'numeric', 'Remainders', 'When a number n is divided by 6, the remainder is 5. What is the remainder when n + 4 is divided by 6?', '[]', '3', '(5+4)-6', 'Try n = 11: 11 + 4 = 15, and 15 = 2 × 6 + 3. In general, adding 4 to a remainder of 5 gives 9, which is one full 6 and 3 more.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 6k + 5, n + 4 = 6k + 9 = 6(k+1) + 3. Remainder 3.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da3920af-be1d-463b-bc69-fea9247451a4', 'BA4.05', 3, 'choice', 'Remainders', 'A number divided by 8 gives a quotient of 12 and the greatest remainder possible. What is the number?', '["$104$","$103$","$108$","$96$"]', '$103$', '12*8+7', 'The greatest remainder when dividing by 8 is 7. So the number is 12 × 8 + 7 = 96 + 7 = 103.', 'checked', '{"lint":[],"solve":{"answer":"$103$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest remainder 7: 8 x 12 + 7 = 103.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cef3626-3b73-4eea-b2a9-5f765cdbf030', 'BA4.05', 3, 'numeric', 'Remainders', 'How many whole numbers from 1 to 100 leave a remainder of 2 when divided by 7?', '[]', '15', '(100-2)/7+1', 'The numbers are 2, 9, 16, ..., 100, each 7 more than the one before. From 2 to 100 is 98, and 98 ÷ 7 = 14 steps. That makes 14 + 1 = 15 numbers.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 9, 16, ..., 100 (2 + 7 x 14). k = 0..14: 15 numbers.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad8a3061-94c0-4818-9308-5d5a1d2bb051', 'BA4.05', 3, 'numeric', 'Remainders', 'What is the remainder when $7{,}000$ is divided by 13?', '[]', '6', '7000-538*13', '13 × 500 = 6,500, leaving 500. 13 × 38 = 494, leaving 6. So the remainder is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 x 538 = 6994, remainder 6.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
