INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df325b60-a747-4e08-a3c8-fcdf75e34532', 'BA4.05', 3, 'numeric', 'Remainders in stories', 'A group of 100 people rides in vans. Each van holds 8 people. The vans are filled one at a time and the last van carries whoever is left. How many people ride in the last van?', '[]', '4', '100-12*8', '12 vans carry 96 people. The other 100 − 96 = 4 people ride in the last van.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = 12 x 8 + 4: last van carries 4.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
