INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dbee79f-2286-4c04-982c-a877d1709631', 'BA4.05', 3, 'choice', 'Remainders in stories', 'Today is Tuesday. What day of the week will it be 100 days from today?', '["Thursday","Wednesday","Friday","Tuesday"]', 'Thursday', NULL, 'The days repeat every 7. 100 ÷ 7 = 14 with 2 left over. So 100 days is 14 whole weeks (back to Tuesday) plus 2 more days: Thursday.', 'checked', '{"lint":[],"solve":{"answer":"Thursday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = 14 x 7 + 2: two days after Tuesday is Thursday.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce0b5e7-a86e-40e2-bc8e-4bb6e1a37602', 'BA4.05', 3, 'choice', 'Remainders in stories', 'Beads are strung in a repeating pattern: red, blue, green, yellow, red, blue, green, yellow, and so on. What color is the 50th bead?', '["red","blue","green","yellow"]', 'blue', NULL, 'The pattern repeats every 4 beads. 50 ÷ 4 = 12 with 2 left over. So the 50th bead is the 2nd color of the pattern: blue.', 'checked', '{"lint":[],"solve":{"answer":"blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 = 12 x 4 + 2: 2nd in the pattern, blue.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f1e3659-8ec0-45cb-92bd-fb9c74a8f8bf', 'BA4.05', 3, 'numeric', 'Remainders in stories', 'Ben must pack 250 cookies in boxes that each hold 12 cookies. Every cookie goes in a box, and the last box may be only partly full. A box costs 2 dollars. How many dollars do the boxes cost in all?', '[]', '42', '21*2', '250 ÷ 12 = 20 with 10 left over. He needs 20 full boxes and 1 more box, so 21 boxes. 21 × 2 = 42 dollars.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"250 = 20 x 12 + 10: 21 boxes x 2 = 42 dollars.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ab94e25-4c26-4ced-b772-4273b597aad5', 'BA4.05', 3, 'choice', 'Remainders in stories', 'Three bags hold 25 marbles each. Four friends share all the marbles equally, and each friend takes as many as possible. How many marbles does each friend get?', '["$19$","$25$","$18$","$3$"]', '$18$', '18', '3 × 25 = 75 marbles. 75 ÷ 4 = 18 with 3 left over, so each friend gets 18 marbles.', 'checked', '{"lint":[],"solve":{"answer":"$18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"75 marbles, 75 = 18 x 4 + 3: 18 each.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
