INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae342c3-3838-40e9-aded-d4110ee9bb5d', 'BA4.05', 3, 'numeric', 'Remainders in stories', 'Mia has 5 bags with 17 apples in each bag. She packs all the apples into boxes of 8. How many apples are left over after she fills as many boxes as she can?', '[]', '5', '85-10*8', '5 × 17 = 85 apples. 85 ÷ 8 = 10 with 5 left over.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"85 apples, 85 = 10 x 8 + 5: 5 left.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
