INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72e94989-1684-4b27-bb06-4133d6b43909', 'BA4.05', 3, 'choice', 'Dividing by multiples of 10', 'Which of these numbers leaves a remainder of 20 when divided by 30?', '["$130$","$150$","$100$","$110$"]', '$110$', '110', '110 = 3 × 30 + 20, so its remainder is 20. The others leave 10, 0 and 10.', 'checked', '{"lint":[],"solve":{"answer":"$110$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"130 r 10, 110 = 90 + 20 r 20, 150 r 0, 100 r 10.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
