INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14de3eee-201b-4304-9ca9-d5a3e465934c', 'BA4.05', 3, 'numeric', 'Dividing by multiples of 10', 'A number divided by 60 gives a quotient of 45 and a remainder of 12. What is the number?', '[]', '2712', '45*60+12', '45 × 60 = 2,700. Adding the remainder, 2,700 + 12 = 2,712.', 'checked', '{"lint":[],"solve":{"answer":"2712","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 x 45 + 12 = 2712.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
