VALUES ('8f083e33-6e29-4d13-b060-503b6ad00166', 'BA4.05', 3, 'numeric', 'Dividing by multiples of 10', 'Find $(480 \times 50) \div 40$ by first dividing 480 by 40.', '[]', '600', '480/40*50', '480 ÷ 40 = 12. Then 12 × 50 = 600.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"480/40 = 12, x 50 = 600.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
