INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e68931ac-aa3c-4550-b1b3-fc516a9ada94', 'BA4.05', 3, 'choice', 'Dividing by multiples of 10', 'Which is a quick way to find $3{,}600 \div 120$?', '["Divide $360$ by $12$","Divide $36$ by $12$, then write two zeros","Divide $3{,}600$ by $12$, then multiply by $10$","Divide $36$ by $12$"]', 'Divide $360$ by $12$', NULL, 'Take one zero off both numbers: 3,600 ÷ 120 = 360 ÷ 12 = 30. The other ways give 300, 3,000 and 3.', 'checked', '{"lint":[],"solve":{"answer":"Divide $360$ by $12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3600/120 = 30 = 360/12. Others give 3, 300, 3000.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
