INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2e12e32-d0cf-4f90-95ad-2dc98bc593d9', 'BA4.05', 3, 'numeric', 'Dividing by multiples of 10', 'A machine makes 60 toys every hour. It must make at least 1,000 toys, and it runs for whole hours only. How many hours must it run?', '[]', '17', '17', '1,000 ÷ 60 = 16 with 40 left over. 16 hours make 960 toys, which is not enough. 17 hours make 1,020 toys.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 x 16 = 960 < 1000, 60 x 17 = 1020: 17 hours.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
