INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c90f185-1cd4-4ca5-ad58-d89775757590', 'BA4.05', 3, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'What is the smallest 4-digit number that is divisible by 9?', '[]', '1008', '1008', 'Try 1,000: its digits add to 1. We need a multiple of 9, so we need 8 more: 1,008, whose digits add to 9.', 'checked', '{"lint":[],"solve":{"answer":"1008","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1000 digit sum 1; add 8: 1008 (sum 9).","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
