INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a50e63ea-f1ac-42e8-b33c-5821ce1f94c9', 'BA4.05', 3, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'What is the greatest 3-digit number that is divisible by both 3 and 5?', '[]', '990', '990', 'Divisible by 5 means it ends in 0 or 5. Try 995: digit sum 23, not a multiple of 3. Try 990: digit sum 18, a multiple of 3. So 990.', 'checked', '{"lint":[],"solve":{"answer":"990","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 15: 999 = 15 x 66 + 9, so 990.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
