INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb76b0b1-e8c3-4043-8b65-d116838b751c', 'BA4.05', 3, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'How many different digits can go in the blank so that 6_52 is divisible by 3?', '[]', '3', '3', '6 + 5 + 2 = 13. We need the total to be a multiple of 3, so the digit must be 2 (15), 5 (18) or 8 (21). That is 3 digits.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + d + 5 + 2 = 13 + d multiple of 3: d = 2, 5, 8. Three digits.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
