INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09de2a46-9145-4689-820b-31be8577638b', 'BA4.05', 3, 'numeric', 'Divisibility by 2, 3, 5, 9 and 10', 'A 3-digit number ends in 5, has a middle digit of 4, and is divisible by 9. What is the number?', '[]', '945', '945', 'The digits are _, 4, 5. 4 + 5 = 9 already, so the first digit must make the sum a multiple of 9. A 3-digit number cannot start with 0, so the first digit is 9. The number is 945.', 'checked', '{"lint":[],"solve":{"answer":"945","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d45: d + 9 multiple of 9, d = 9 (0 not allowed as first digit): 945.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
