INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac264202-d6b4-4fce-a4f0-54dba824912a', 'BA4.05', 3, 'choice', 'Divisibility by 2, 3, 5, 9 and 10', 'Which statement about the number 2,745 is true?', '["It is divisible by 2 and by 3","It is divisible by 5 and by 9","It is divisible by 10 and by 5","It is divisible by 2 and by 9"]', 'It is divisible by 5 and by 9', NULL, '2,745 ends in 5, so it is divisible by 5 but not by 2 or 10. Its digits add to 2 + 7 + 4 + 5 = 18, so it is divisible by 9 (and 3).', 'checked', '{"lint":[],"solve":{"answer":"It is divisible by 5 and by 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2745: ends in 5 (not 2, not 10), digit sum 18 so divisible by 9 and 3.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
