INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2e0ec16-f289-4829-b776-f886865bece2', 'BA4.05', 3, 'numeric', 'Division puzzles and missing numbers', 'A number is divided by 7. The quotient and the remainder are the same number, and the number is more than 40 and less than 50. What is the number?', '[]', '48', '8*6', 'If the quotient and remainder are both q, the number is 7 × q + q = 8 × q. The only multiple of 8 between 40 and 50 is 48 (q = 6, and 6 is less than 7, so it is a valid remainder).', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 7q + q = 8q with q <= 6. Between 40 and 50: 48 (q = 6).","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
