INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('573076a8-d18f-41d6-bdcc-f8e9eb0cf636', 'BA4.05', 3, 'numeric', 'Division puzzles and missing numbers', 'What is the smallest number greater than 1 that leaves a remainder of 1 when divided by 2, by 3, by 4, by 5 and by 6?', '[]', '61', '60+1', 'A number that leaves remainder 1 is one more than a multiple of all of them. The smallest number that 2, 3, 4, 5 and 6 all divide is 60. So the answer is 60 + 1 = 61.', 'checked', '{"lint":[],"solve":{"answer":"61","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - 1 is a multiple of lcm(2,3,4,5,6) = 60; smallest n > 1 is 61.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f902074-9243-4b93-a011-ebdae03f9577', 'BA4.05', 3, 'choice', 'Division puzzles and missing numbers', 'Eli thinks of a number. He divides it by 4, adds 6, and then divides by 5. His answer is 8. What number did he think of?', '["$34$","$136$","$184$","$44$"]', '$136$', '(8*5-6)*4', 'Work backwards. 8 × 5 = 40. Then 40 − 6 = 34. Then 34 × 4 = 136. Check: 136 ÷ 4 = 34, 34 + 6 = 40, 40 ÷ 5 = 8.', 'checked', '{"lint":[],"solve":{"answer":"$136$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Work back: 8 x 5 = 40, - 6 = 34, x 4 = 136.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37a2610d-d4ed-436d-ae36-9e14e0df0650', 'BA4.05', 3, 'choice', 'Division puzzles and missing numbers', 'Which number leaves a remainder of 5 when divided by 12 AND a remainder of 2 when divided by 5?', '["$65$","$62$","$77$","$29$"]', '$77$', '77', '77 = 6 × 12 + 5 and 77 = 15 × 5 + 2, so 77 works. 65 leaves 5 and 0; 62 leaves 2 and 2; 29 leaves 5 and 4.', 'checked', '{"lint":[],"solve":{"answer":"$77$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29: r5, r4. 77: 77 = 72 + 5 r5, 77 = 75 + 2 r2. 62: r2. 65: r5, r0. Answer 77.","run_id":"claude-code","at":"2026-10-19T01:32:17.283Z"}}', 'ai', NULL, NULL)
