INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4d3f86c-68ba-43d9-8cfc-b9055c6694c7', 'BA4.06', 1, 'numeric', 'Truth-tellers and liars: one speaker', 'Tara always lies. She says: "I have 3 dogs." Tara has either 3 dogs or 4 dogs. How many dogs does she have?', '[]', '4', '4', 'Tara always lies, so what she said is false. She does not have 3 dogs, so she has 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A liar''s statement is false, so not 3: she has 4.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
