INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3483a23e-2db4-4a72-98e5-7bd123ab027a', 'BA4.06', 1, 'numeric', 'Truth-tellers and liars: one speaker', 'Sam always tells the truth. He says: "My number is bigger than 7 and smaller than 9." Sam''s number is a whole number. What is it?', '[]', '8', '8', 'The only whole number bigger than 7 and smaller than 9 is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole number with 7 < n < 9: 8.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
