INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fc5523e-07c4-45c7-8310-f96ed6a747ca', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: one speaker', 'Mia always lies. She says: "It is raining." Which statement must be true?', '["It is not raining","It is raining","It is snowing","Mia is telling the truth"]', 'It is not raining', NULL, 'Mia lies, so "It is raining" is false. That means it is not raining. We cannot say what the weather is instead, so "snowing" is not certain.', 'checked', '{"lint":[],"solve":{"answer":"It is not raining","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Her statement is false, so it is not raining.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
