INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19451e31-7061-4787-806e-7d8da50dc90d', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: one speaker', 'Pia says: "Two plus two is five." Pia is either a truth-teller or a liar. Which is she? (A truth-teller always tells the truth. A liar always lies.)', '["A truth-teller","A liar","Sometimes one, sometimes the other","We cannot tell"]', 'A liar', NULL, 'Two plus two is four, so her statement is false. A truth-teller would never say something false, so Pia is a liar.', 'checked', '{"lint":[],"solve":{"answer":"A liar","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 2 = 5 is false, so she is a liar.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
