INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fe0dbe9-30ff-451a-b01f-05992e469a2d', 'BA4.06', 1, 'numeric', 'Truth-tellers and liars: one speaker', 'Dan always tells the truth. Zack always lies. Both are asked: "Is 9 an even number?" How many of them answer "yes"?', '[]', '1', '1', '9 is not even, so the true answer is "no". Dan tells the truth and says "no". Zack lies and says "yes". So 1 of them says yes.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is odd. Dan says no, Zack lies and says yes: 1.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
