INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8389c3b-8386-4616-8779-364e3717d39f', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: one speaker', 'Eli always tells the truth. He says: "The pet is not a cat, and it is not a bird." The pet is a cat, a bird or a fish. Which is it?', '["A cat","A bird","A fish","We cannot tell"]', 'A fish', NULL, 'Eli tells the truth, so the pet is not a cat and not a bird. The only one left is a fish.', 'checked', '{"lint":[],"solve":{"answer":"A fish","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not a cat, not a bird: a fish.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
