INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8ede3e6-4260-4802-8c16-fd5b26c41f96', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: several speakers', 'Ari always tells the truth and Bo always lies. One of them has the key. Ari says: "Bo has the key." Bo says: "I do not have the key." Who has the key?', '["Ari","Both of them","Neither of them","Bo"]', 'Bo', NULL, 'Ari tells the truth, so Bo has the key. Check Bo: he lies, and "I do not have the key" is false, so he does have it. Everything agrees.', 'checked', '{"lint":[],"solve":{"answer":"Bo","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ari is truthful: Bo has the key. Bo''s denial is a lie, consistent.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
