INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e50fd79-0660-4ac0-accb-9485f341e8cd', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: several speakers', 'Of three children, exactly one always tells the truth and two always lie. Ana says: "Ben is the truth-teller." Ben says: "I am the truth-teller." Cora says: "Ana is a liar." Who is the truth-teller?', '["Cora","Ana","Ben","We cannot tell"]', 'Cora', NULL, 'Try Ana as the truth-teller: she says Ben is, which would make two truth-tellers. No. Try Ben: then Ana would be a liar saying something true. No. Try Cora: Ana and Ben are liars, so "Ana is a liar" is true, which fits Cora. And Ana''s statement is false, as a liar''s should be. So Cora.', 'checked', '{"lint":[],"solve":{"answer":"Cora","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ana truthful -> Ben too (two truth-tellers), no. Ben truthful -> Ana''s statement true, but she must lie, no. Cora truthful: Ana liar (says Ben, false), Ben liar (false claim). Cora.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('476db92c-6e00-438a-9ad0-bb1940105ff1', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: several speakers', 'Dan always tells the truth. Dan says: "Eve and I are both truth-tellers." What is Eve? (A truth-teller always tells the truth. A liar always lies.)', '["A liar","A truth-teller","Sometimes a liar","We cannot tell"]', 'A truth-teller', NULL, 'Dan tells the truth, so what he said is true: Eve and Dan are both truth-tellers.', 'checked', '{"lint":[],"solve":{"answer":"A truth-teller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dan''s statement is true, so Eve is a truth-teller.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd8d9740-ae0d-4a90-95da-1c24dab94b89', 'BA4.06', 1, 'choice', 'Truth-tellers and liars: several speakers', 'Fay always lies. Fay says: "Gus and I are both liars." What is Gus? (A truth-teller always tells the truth. A liar always lies.)', '["A liar","We cannot tell","A truth-teller","Sometimes a liar"]', 'A truth-teller', NULL, 'Fay is a liar, so what she said is false. "Gus and I are both liars" would be true only if Gus were a liar too (Fay is one). Since it is false, Gus is not a liar. So Gus is a truth-teller.', 'checked', '{"lint":[],"solve":{"answer":"A truth-teller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The statement is false; Fay is a liar, so Gus is not a liar: truth-teller.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
