INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e30f5bfa-3fed-41fe-9aa4-66aab986ff4f', 'BA4.06', 2, 'choice', 'Truth-tellers and liars: one speaker', 'Bo says: "6 times 7 is 42." Cy says: "8 times 7 is 54." One of them always tells the truth and the other always lies. Who always lies?', '["Cy","Bo","Both of them","Neither of them"]', 'Cy', NULL, '6 times 7 is 42, so Bo said something true. 8 times 7 is 56, so Cy said something false. Bo is the truth-teller and Cy is the liar.', 'checked', '{"lint":[],"solve":{"answer":"Cy","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 7 = 42 true, 8 x 7 = 56 not 54. Cy lies.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
