INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0c1c120-97fa-48dd-bd2a-d2c73d5b4b59', 'BA4.06', 2, 'choice', 'Ordering people or things from clues', 'Four families live on different floors, 1 to 4, of a building. The Moss family lives on floor 1. The Kim family lives below the Lee family. The Nash family lives on the floor right above the Kim family. Which family lives on floor 4?', '["The Kim family","The Moss family","The Lee family","The Nash family"]', 'The Lee family', NULL, 'Moss is on floor 1. Of the floors 2, 3 and 4, the Nash family is right above the Kim family, so Kim is on 2 and Nash on 3 (if Kim were on 3, Nash would be on 4 and Lee would be on 2, below Kim, which breaks the rule). That leaves floor 4 for the Lee family.', 'checked', '{"lint":[],"solve":{"answer":"The Lee family","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Floors 2-4 for Kim, Lee, Nash. Nash = Kim + 1 and Lee above Kim: Kim 2, Nash 3, Lee 4.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
