INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('398e9ac9-dd0a-42e6-abe7-21cd36adf308', 'BA4.06', 2, 'choice', 'Ordering people or things from clues', 'Five runners ran a race with no ties. Ravi finished before Sal but after Tia. Uma finished after Sal. Vic finished before Tia. Who finished third?', '["Tia","Sal","Uma","Ravi"]', 'Ravi', NULL, 'Vic finished before Tia, Tia before Ravi, Ravi before Sal, and Sal before Uma. So the order is Vic, Tia, Ravi, Sal, Uma, and Ravi was third.', 'checked', '{"lint":[],"solve":{"answer":"Ravi","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vic, Tia, Ravi, Sal, Uma. Third Ravi.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
