INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c5fe659-c8f7-4cfa-8e74-be11ffcd425a', 'BA4.06', 2, 'choice', 'Ordering people or things from clues', 'Four cards lie in a row from left to right: a circle, a heart, a square and a star. The circle is at the far left. The star is not next to the circle. The heart is right after the square. Which card is third from the left?', '["The heart","The circle","The square","The star"]', 'The heart', NULL, 'The star cannot be 2nd (next to the circle). The square and the heart must be side by side, with the heart on the right. They can only be 2nd and 3rd or 3rd and 4th. If they were 3rd and 4th, the star would be 2nd, which is not allowed. So the square is 2nd, the heart is 3rd and the star is 4th.', 'checked', '{"lint":[],"solve":{"answer":"The heart","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circle 1. Star not 2. Square-heart adjacent in 2-4: square 2, heart 3, star 4. Third: heart.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
