INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b9de2e-a1fd-4c03-93f2-16e6de10f62c', 'BA4.06', 3, 'numeric', 'Ordering people or things from clues', 'Kit is taller than Gus. Gus is taller than Hal. Hal is taller than Ian. Fay is shorter than Ian but taller than Jo. All six children have different heights. How many of the six are taller than Fay?', '[]', '4', NULL, 'From tallest to shortest: Kit, Gus, Hal, Ian, Fay, Jo. Four children (Kit, Gus, Hal and Ian) are taller than Fay.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kit > Gus > Hal > Ian > Fay > Jo. 4 taller.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
