INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e741ef3-0d12-4b58-9336-e00066a925a3', 'BA4.06', 3, 'choice', 'Ordering with numbers and counting orders', 'Ann is 5 cm taller than Ben. Ben is 3 cm shorter than Cy. Cy is 4 cm shorter than Dee. Dee is 150 cm tall. Who is the shortest of the four?', '["Ben","Ann","Cy","Dee"]', 'Ben', NULL, 'Dee is 150 cm. Cy is 150 - 4 = 146 cm. Ben is 146 - 3 = 143 cm. Ann is 143 + 5 = 148 cm. The shortest is Ben at 143 cm.', 'checked', '{"lint":[],"solve":{"answer":"Ben","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dee 150, Cy 146, Ben 143, Ann 148. Ben.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
