INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e17f97ae-deeb-4f90-a041-4d4494d388aa', 'BA4.06', 3, 'numeric', 'Ordering with numbers and counting orders', 'Seven children stand in a row. Kim is 3rd from the left end. Leo is 3rd from the right end. How many children stand between Kim and Leo?', '[]', '1', '5-3-1', 'Leo is 3rd from the right of 7 children, so Leo is 5th from the left. Kim is 3rd from the left. Only the 4th child is between them: 1 child.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kim 3rd, Leo 5th from left: 1 between.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
