INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d3e3fec-0cd8-453e-8d68-c52e66e7686c', 'BA4.06', 3, 'numeric', 'Ordering with numbers and counting orders', 'Three friends, Ann, Ben and Cal, line up in a row. How many different lines are possible if Ann must be somewhere ahead of Ben?', '[]', '3', '6/2', 'Three people can line up in 3 × 2 × 1 = 6 ways. In exactly half of them Ann is ahead of Ben, so 3 ways: Ann Ben Cal, Ann Cal Ben, Cal Ann Ben.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABC, ACB, CAB: 3.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
