INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c9e7375-66d0-4268-9e37-d3b0cebdf754', 'BA4.06', 3, 'numeric', 'Ordering with numbers and counting orders', 'Four children, Quin, Sam, Rae and Tam, have different ages. Quin is older than Sam. Rae is older than Tam. How many different orders by age are possible?', '[]', '6', '4*3*2*1/2/2', 'Four children can be ordered in 24 ways. Quin is older than Sam in half of them, and Rae is older than Tam in half of those. 24 / 2 / 2 = 6. (For example Quin Sam Rae Tam, Quin Rae Sam Tam, Quin Rae Tam Sam, Rae Quin Sam Tam, Rae Quin Tam Sam, Rae Tam Quin Sam.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / (2 x 2) = 6.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc5ebd29-a86e-4bd8-8252-87c5dd8c84a5', 'BA4.06', 3, 'choice', 'Deciding what must be true', 'Some of the apples in a basket are green. Every green fruit in the basket is sour. Which statement must be true?', '["All of the apples in the basket are sour","Some of the apples in the basket are sour","All of the sour fruit in the basket are apples","No apple in the basket is red"]', 'Some of the apples in the basket are sour', NULL, 'Some apples are green, and green fruit is sour, so those apples are sour. The other statements say more than we know.', 'checked', '{"lint":[],"solve":{"answer":"Some of the apples in the basket are sour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The green apples are sour, so some apples are sour.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5ceaa44-e2f3-49e9-92da-f804b19eecb5', 'BA4.06', 3, 'numeric', 'Deciding what must be true', 'A box holds 10 balls, each red, blue or green. There are more red balls than blue balls, more blue balls than green balls, and at least one ball of each color. What is the fewest red balls the box could hold?', '[]', '5', NULL, 'Red must beat blue and blue must beat green. Red = 4 would force blue to be at most 3 and green at most 2, for a total of at most 4 + 3 + 2 = 9, which is less than 10. Red = 5 works: 5 red, 4 blue, 1 green (or 5, 3, 2). So the fewest is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R = 4: B <= 3, G <= 2, max total 9. R = 5, B = 3, G = 2 works. 5.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74cd889e-86b5-4602-a73e-50130dd6b217', 'BA4.06', 3, 'choice', 'Deciding what must be true', 'If Ana goes to the party, Ben goes. If Ben goes to the party, Cal goes. Cal did not go to the party. Which statement must be true?', '["Ana went but Ben did not","Ben went but Ana did not","Neither Ana nor Ben went","Only Ana stayed home"]', 'Neither Ana nor Ben went', NULL, 'If Ben had gone, Cal would have gone, but he did not, so Ben did not go. If Ana had gone, Ben would have gone, so Ana did not go either.', 'checked', '{"lint":[],"solve":{"answer":"Neither Ana nor Ben went","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cal did not go -> Ben did not -> Ana did not.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f84767b-9dd4-4457-9ed3-fb2d438bdc54', 'BA4.06', 3, 'choice', 'Deciding what must be true', 'Every student who plays chess also plays checkers. No student who plays checkers is in the art club. Mo plays chess. Which statement must be true?', '["Mo plays only chess","Mo is in the art club","Mo does not play checkers","Mo is not in the art club"]', 'Mo is not in the art club', NULL, 'Mo plays chess, so Mo plays checkers. A student who plays checkers is not in the art club, so Mo is not in the art club.', 'checked', '{"lint":[],"solve":{"answer":"Mo is not in the art club","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mo plays chess -> checkers -> not in art club.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
