INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8956f1a-e1c0-42ca-b847-ce980dacca19', 'BA4.06', 3, 'numeric', 'Deciding what must be true', 'Three signs hang on a wall. Sign A says: "Exactly one of the three signs is false." Sign B says: "Exactly two of the three signs are false." Sign C says: "All three signs are false." How many of the signs are true?', '[]', '1', NULL, 'The signs say different things, so at most one can be true. If none were true, sign C ("all three are false") would be true. So exactly one is true. That is sign B: two signs (A and C) are false.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Claims exclude each other. All false makes C true: no. One true, two false: B true. 1.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
