INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5eae47d0-646f-40a7-9f2d-8efe38c4dc9c', 'BA4.06', 3, 'choice', 'Matching, elimination and counting cases', 'Ana, Ben, Cal, Dev and Eli each have a different pet: a cat, a dog, a fish, a bird or a rabbit. Eli has the rabbit. Ana has neither the fish nor the bird. Ben has none of the dog, the bird or the cat. Cal does not have the cat. Dev has neither the dog nor the bird. Who has the bird?', '["Ana","Ben","Cal","Dev"]', 'Cal', NULL, 'Eli has the rabbit. Ben cannot have the dog, bird, cat or rabbit, so Ben has the fish. Dev cannot have the dog or bird, and fish and rabbit are gone, so Dev has the cat. Ana cannot have the fish or bird, so Ana has the dog. That leaves the bird for Cal.', 'checked', '{"lint":[],"solve":{"answer":"Cal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eli rabbit. Ben fish. Dev not dog/bird -> cat. Ana not fish/bird -> dog. Cal bird.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('145ef114-b030-481c-9745-20780b1a3b6f', 'BA4.06', 3, 'choice', 'Matching, elimination and counting cases', 'Ali, Bea and Cy each have one pet (a cat, a dog or a bird) and each have a different favorite color (red, blue or green). The person with the cat likes green. Ali has the dog. Bea likes blue. The person with the bird does not like red. What color does Ali like?', '["Blue","Green","We cannot tell","Red"]', 'Red', NULL, 'The cat owner likes green. Bea likes blue, so Bea does not own the cat, and Ali has the dog, so Cy has the cat and likes green. Bea has the bird, who likes blue (not red, which fits). Ali is left with red.', 'checked', '{"lint":[],"solve":{"answer":"Red","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cat-owner likes green. Ali dog. Bea blue, so not cat: bird (bird not red, ok). Cy cat, green. Ali red.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
