INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be00571-7e78-4b7a-bac5-f4591f7e2ab6', 'BA4.07', 2, 'numeric', 'Divisibility rules', 'The three-digit number 38? is divisible by 9. What digit is ? ?', '[]', '7', '18-11', '3 + 8 = 11. To reach a multiple of 9 the digits must add to 18, so ? = 7. Check: 387 / 9 = 43.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+8+? = 11+? must be a multiple of 9: ? = 7 (387 = 9x43).","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
