VALUES ('4b74fc96-f2e4-423f-a76e-ff039332586e', 'BA4.07', 2, 'choice', 'Common factors and greatest common factor', 'What is the greatest common factor of 24 and 36?', '["6","8","12","72"]', '12', '12', 'Factors of 24: 1, 2, 3, 4, 6, 8, 12, 24. Factors of 36: 1, 2, 3, 4, 6, 9, 12, 18, 36. The greatest in both lists is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 2^3x3, 36 = 2^2x3^2; GCF = 4x3 = 12.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
