INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb685705-15d8-4266-8095-2afe6dc3b232', 'BA4.07', 2, 'choice', 'Common factors and greatest common factor', 'A garden is 18 meters long and 30 meters wide. Square tiles with whole-number sides must cover it exactly, with no cutting. What is the longest possible side of a tile, in meters?', '["3","6","9","90"]', '6', '6', 'The side must be a factor of both 18 and 30. The greatest common factor is 6, so the largest tile is 6 meters on a side.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tile side divides 18 and 30; GCF 6.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
