VALUES ('661b1a6c-2aac-4d5b-a646-e67ec4768a5b', 'BA4.07', 2, 'choice', 'Common factors and greatest common factor', 'Which two numbers have a greatest common factor of 1?', '["8 and 15","8 and 12","15 and 21","8 and 20"]', '8 and 15', NULL, '8 and 15 share no factor except 1. The pairs 8 and 12, 15 and 21, and 8 and 20 have greatest common factors of 4, 3 and 4.', 'checked', '{"lint":[],"solve":{"answer":"8 and 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 = 2^3, 15 = 3x5 share no prime; others share 4, 3, 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
