INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8654d75e-48fb-4cbb-b120-726b478113d4', 'BA4.07', 3, 'choice', 'Factors and multiples', 'Which of these is NOT a factor of $6 \times 14$?', '["12","21","28","24"]', '24', '24', '6 x 14 = 84. And 84 = 12 x 7 = 21 x 4 = 28 x 3, so 12, 21 and 28 are factors. 84 / 24 is not a whole number, so 24 is not.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 14 = 84 = 2x2x3x7. 21 = 3x7 divides; 12 = 2x2x3 divides; 28 = 2x2x7 divides; 24 = 2x2x2x3 needs three 2s, so not a factor (84/24 = 3.5).","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
