INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e504d49-42d7-4bf3-a41d-c705d5e7e495', 'BA4.07', 3, 'numeric', 'Factors and multiples', 'Sam counts by 9s: 9, 18, 27, and so on, up to the 12th multiple of 9. How many of the 12 numbers he says are even?', '[]', '6', '12/2', 'Multiples of 9 alternate odd, even, odd, even, because 9 is odd. Among the first 12 multiples, every second one is even: 18, 36, 54, 72, 90, 108. That is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples 9k for k=1..12; 9k is even when k is even: k = 2,4,6,8,10,12. Count 6.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e50d0fb9-1461-49ac-bb02-14190040bd95', 'BA4.07', 3, 'numeric', 'Primes and composite numbers', 'The sum of two prime numbers is 15. What is the larger of the two primes?', '[]', '13', '15-2', 'Two odd numbers add to an even number, so one of the primes must be even. The only even prime is 2, and 15 - 2 = 13, which is prime.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd sum means one prime is 2: 15 - 2 = 13 (prime). Larger is 13.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de8aaf92-7cab-4b1b-9f72-8566efc29f95', 'BA4.07', 3, 'numeric', 'Primes and composite numbers', 'Twin primes are two primes that differ by 2, like 11 and 13. How many pairs of twin primes are there when both numbers are less than 20?', '[]', '4', '4', 'The primes below 20 are 2, 3, 5, 7, 11, 13, 17, 19. Pairs that differ by 2: 3 and 5, 5 and 7, 11 and 13, 17 and 19. That is 4 pairs.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes below 20: 2,3,5,7,11,13,17,19. Twin pairs: (3,5),(5,7),(11,13),(17,19). Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
