INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92395ba9-3075-43f3-a276-aa8028d815c3', 'BA4.07', 3, 'choice', 'Primes and composite numbers', 'How many of the numbers 31, 32, 33, 34, 35, 36, 37, 38 and 39 are composite?', '["2","6","7","9"]', '7', '9-2', 'Only 31 and 37 are prime. The other 7 numbers each have a factor besides 1 and themselves, so 7 are composite.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31 and 37 prime; 32,33,34,35,36,38,39 composite. Count 7.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
