INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c874463e-b701-407d-b2a3-c579c6a26e62', 'BA4.07', 3, 'numeric', 'Primes and composite numbers', 'A prime number p is such that p + 2 and p + 4 are also both prime. What is p?', '[]', '3', '3', 'Try p = 3: 3, 5 and 7 are all prime. For any larger p, one of p, p + 2, p + 4 is a multiple of 3, so it would not be prime. So p = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One of p, p+2, p+4 is divisible by 3, so one must equal 3: p = 3 gives 3,5,7 all prime. p = 3.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ee8fe4a-9c16-4861-835c-bc3497f95bb2', 'BA4.07', 3, 'choice', 'Prime factorization', 'What is the largest prime factor of 187?', '["11","19","17","187"]', '17', '17', 'Try dividing by primes: 187 / 11 = 17. So 187 = 11 x 17, and both are prime. The larger is 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"187 = 11 x 17; largest prime factor 17.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6c40970-c2cb-4d85-85e4-194eb0c8146c', 'BA4.07', 3, 'numeric', 'Prime factorization', 'Half of a number is $2 \times 3 \times 5 \times 5$. What is the number?', '[]', '300', '2*(2*3*5*5)', '2 x 3 x 5 x 5 = 150, and the whole number is twice that: 300. In primes it is 2 x 2 x 3 x 5 x 5.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half is 2x3x5x5 = 150, so the number is 300.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b370ad29-8b52-4fe9-924b-1507c1364533', 'BA4.07', 3, 'numeric', 'Prime factorization', 'The only prime factors of a number are 3 and 5. The number is odd and is between 40 and 50. What is it?', '[]', '45', '45', '45 = 3 x 3 x 5 has only the prime factors 3 and 5. No other number between 40 and 50 is made only from 3s and 5s.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd numbers 41..49 using only 3s and 5s (both present): 45 = 3x3x5.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('203a0d7b-415f-4e60-b14b-a8c446a3c0e4', 'BA4.07', 3, 'choice', 'Prime factorization', 'Which of these products equals a perfect square (a whole number times itself)?', '["$2 \\times 2 \\times 3 \\times 5$","$2 \\times 2 \\times 3 \\times 3$","$2 \\times 3 \\times 3 \\times 3$","$2 \\times 2 \\times 2 \\times 5 \\times 5$"]', '$2 \times 2 \times 3 \times 3$', NULL, 'A number is a perfect square when its primes pair up exactly. 2 x 2 x 3 x 3 = 36 = 6 x 6. In the other products at least one prime is left without a partner.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times 2 \\times 3 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x2x3x3 = 36 = 6x6. Others: 60, 54, 200 not squares.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcd4b89e-404e-4733-b2d7-3fca72d10473', 'BA4.07', 3, 'numeric', 'Prime factorization', 'What is the smallest number greater than 100 that has 2, 3 and 5 among its prime factors?', '[]', '120', '30*4', 'The number must be a multiple of 2 x 3 x 5 = 30. The multiples of 30 are 30, 60, 90, 120. The first one above 100 is 120.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must be a multiple of 30. Multiples: 90, 120. Smallest above 100 is 120.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e96b35d-a118-41d9-b909-04711565586f', 'BA4.07', 3, 'choice', 'Counting factors', 'How many factors does 100 have?', '["9","8","10","12"]', '9', '9', 'The factors of 100 are 1, 2, 4, 5, 10, 20, 25, 50 and 100. That is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = 2^2 x 5^2: (2+1)(2+1) = 9. 1,2,4,5,10,20,25,50,100.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86aa3259-65c2-4ddf-afb8-8f858eb108de', 'BA4.07', 3, 'choice', 'Counting factors', 'What is the smallest number that has exactly 8 factors?', '["24","16","20","30"]', '24', '24', 'The factors of 24 are 1, 2, 3, 4, 6, 8, 12, 24: eight. Checking smaller numbers (for example 12 has 6, 16 has 5, 18 has 6, 20 has 6), none has exactly 8.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 2^3 x 3 has 4x2 = 8 factors; 16 has 5, 20 has 6, 30 has 8 but is larger. No number below 24 has 8 factors.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49ee74a9-2507-47a5-9bdd-7dcf1173b69d', 'BA4.07', 3, 'numeric', 'Counting factors', 'How many of the factors of 72 are multiples of 3?', '[]', '8', '8', 'The factors of 72 are 1, 2, 3, 4, 6, 8, 9, 12, 18, 24, 36, 72. The multiples of 3 among them: 3, 6, 9, 12, 18, 24, 36, 72. That is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 2^3 x 3^2. Factors with at least one 3: 4 choices of power of 2 x 2 choices (3 or 9) = 8: 3,6,12,24,9,18,36,72.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c6eb517-deda-4ef1-9a16-2541581ad509', 'BA4.07', 3, 'numeric', 'Counting factors', 'A number has exactly 3 factors, and the largest of them is 49. What is the middle factor?', '[]', '7', '7', 'The factors are 1, some middle number, and 49. Since 7 x 7 = 49, the three factors are 1, 7 and 49. The middle one is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exactly 3 factors means square of a prime: 49 = 7x7, factors 1,7,49. Middle 7.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3eb59261-307c-44ed-a5f6-b097fc31c359', 'BA4.07', 3, 'choice', 'Counting factors', 'The prime factorization of 60 is $2^2 \times 3 \times 5$. How many factors does 60 have?', '["4","7","60","12"]', '12', '3*2*2', 'Add 1 to each exponent and multiply: (2 + 1) x (1 + 1) x (1 + 1) = 3 x 2 x 2 = 12. Check: 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+1)(1+1)(1+1) = 12 factors.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff790639-bcaf-4654-b4ff-eb84a7e45ae7', 'BA4.07', 3, 'choice', 'Divisibility rules', 'What is the largest three-digit number that is divisible by 5 and has three different digits?', '["995","990","985","980"]', '985', '985', 'The last digit is 0 or 5. 995 and 990 repeat a digit. Next is 985, whose digits 9, 8, 5 are all different.', 'checked', '{"lint":[],"solve":{"answer":"985","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must end in 0 or 5. 995, 990 repeat 9. Next: 985 (9,8,5 distinct) > 980.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
