INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6473ba34-7fdf-4b12-aac5-83e08e7c7495', 'BA4.08', 1, 'choice', 'Equivalent fractions', 'Which fraction is equal to $\frac{1}{2}$?', '["$\\frac{2}{4}$","$\\frac{1}{4}$","$\\frac{2}{3}$","$\\frac{1}{3}$"]', '$\frac{2}{4}$', NULL, 'Multiply the top and bottom of 1/2 by 2 to get 2/4. Changing only the bottom (1/4) or only the top (2/3) changes the amount.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4 = 1/2; 1/4, 1/3, 2/3 are not.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
