INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('666614ae-56ca-4651-a3ff-847e105d9f6d', 'BA4.08', 1, 'numeric', 'Equivalent fractions', 'A pizza is cut into 3 equal slices and Jon eats 2 of them. Suppose the pizza had been cut into 9 equal slices instead. How many of those slices would be the same amount?', '[]', '6', '2*3', 'Each third is cut into 3 smaller slices, so the 2 thirds Jon ate are 2 x 3 = 6 of the 9 slices. So 2/3 = 6/9.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 6/9: 6 slices.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
