INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a38fb1a-dddf-483f-9d04-4da99df6288f', 'BA4.08', 1, 'choice', 'Equivalent fractions', 'Which fraction is equal to $\frac{4}{8}$?', '["$\\frac{1}{4}$","$\\frac{4}{4}$","$\\frac{2}{8}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, '4/8 means 4 of 8 equal parts, which is half of the whole. Dividing the top and bottom by 4 gives 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
