INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('391cc9f8-1946-48e6-9297-a6a4ee19afec', 'BA4.08', 1, 'choice', 'Equivalent fractions', '$\frac{3}{5} = \frac{6}{?}$ What number does the ? stand for?', '["8","11","10","15"]', '10', '5*2', 'The top went from 3 to 6, so it was multiplied by 2. Multiply the bottom the same way: 5 x 2 = 10. So 3/5 = 6/10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 3 x 2, so ? = 5 x 2 = 10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
