INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('571d9cad-1894-4785-b939-6fc3d2239f2e', 'BA4.08', 1, 'numeric', 'Equivalent fractions', 'To change $\frac{1}{4}$ into twelfths, the top and the bottom are both multiplied by the same number. What is that number?', '[]', '3', '12/4', '4 x 3 = 12, so the number is 3. The top becomes 1 x 3 = 3, giving 3/12.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 = 12, so multiply by 3.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
