VALUES ('5d736b5a-9468-4920-9972-194d7f15b5c3', 'BA4.08', 1, 'choice', 'Simplest form', 'Which fraction is in simplest form?', '["$\\frac{3}{5}$","$\\frac{2}{4}$","$\\frac{3}{6}$","$\\frac{5}{10}$"]', '$\frac{3}{5}$', NULL, '3 and 5 have no common factor except 1. The others can be simplified: 2/4 = 1/2, 3/6 = 1/2, 5/10 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 has no common factor; 3/6, 2/4, 5/10 all = 1/2.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
