INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7007a09-6edc-491c-adf7-77bc1eb60d49', 'BA4.08', 1, 'choice', 'Comparing fractions', 'Which fraction is less than $\frac{1}{2}$?', '["$\\frac{3}{4}$","$\\frac{2}{3}$","$\\frac{5}{6}$","$\\frac{1}{3}$"]', '$\frac{1}{3}$', NULL, 'Half a whole is cut into 2 equal parts, and a third is smaller than a half. So 1/3 is less than 1/2. The others are more than half: 3/4 = 6/8 and 5/6 and 2/3 = 4/6 are all more than 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 < 1/2; the others exceed 1/2.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
