INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ac795b3-cd87-4900-b64b-4226c01b979f', 'BA4.08', 1, 'choice', 'Comparing fractions', 'Which fraction is greater than 1?', '["$\\frac{3}{4}$","$\\frac{4}{4}$","$\\frac{5}{4}$","$\\frac{4}{5}$"]', '$\frac{5}{4}$', NULL, '5/4 is 5 quarters, and 4 quarters make a whole, so 5/4 is more than 1. 4/4 is equal to 1, and the others are less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/4 has numerator greater than denominator.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
