INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('524cfc60-a301-4258-8c44-25ea2883f00b', 'BA4.08', 1, 'choice', 'Comparing fractions', 'How many of the fractions $\frac{1}{6}$, $\frac{3}{6}$, $\frac{5}{6}$ and $\frac{7}{6}$ are less than 1?', '["2","4","3","5"]', '3', '3', 'A fraction is less than 1 when the numerator is less than the denominator. 1/6, 3/6 and 5/6 are less than 1, but 7/6 is more than 1.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6, 3/6, 5/6 are less than 1; 7/6 is not. Count 3.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
