INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b9cbce3-94c7-41ff-ac6d-888a33862b05', 'BA4.08', 1, 'choice', 'Comparing fractions', 'Which statement is true?', '["$\\frac{1}{5} > \\frac{1}{4}$","$\\frac{1}{3} > \\frac{1}{4}$","$\\frac{1}{6} > \\frac{1}{3}$","$\\frac{1}{8} > \\frac{1}{2}$"]', '$\frac{1}{3} > \frac{1}{4}$', NULL, 'With the same top, the smaller the denominator, the bigger the pieces. A third of a whole is bigger than a quarter, so 1/3 > 1/4. The other statements have it the wrong way round.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3} > \\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fewer equal parts means bigger parts: 1/3 > 1/4 is true; the rest false.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035beeb1-1aec-4c38-bd2d-7ce415c08d73', 'BA4.08', 1, 'numeric', 'Improper fractions to mixed numbers', '$\frac{7}{4} = 1\frac{?}{4}$ What number does the ? stand for?', '[]', '3', '7-4', '4/4 makes 1 whole. 7/4 is 4/4 and 3/4 more, so 7/4 = 1 and 3/4.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/4 = 4/4 + 3/4 = 1 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
