INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5561339-64da-4547-9062-b31075156aee', 'BA4.08', 1, 'choice', 'Improper fractions to mixed numbers', 'Which mixed number is equal to $\frac{5}{2}$?', '["$2\\frac{1}{5}$","$2\\frac{1}{2}$","$1\\frac{1}{2}$","$5\\frac{1}{2}$"]', '$2\frac{1}{2}$', NULL, '2/2 makes 1 whole, so 4/2 makes 2 wholes. That leaves 1/2 more. So 5/2 = 2 and 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/2 = 2 1/2.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
