INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a6befb6-9443-4a6e-af8f-6e6f799e8e24', 'BA4.08', 1, 'choice', 'Subtracting fractions with like denominators', 'Dad has $\frac{6}{7}$ of a cake and gives $\frac{2}{7}$ of the cake to a neighbor. What fraction of the cake does he have now?', '["$\\frac{8}{7}$","$\\frac{4}{7}$","$\\frac{4}{14}$","$\\frac{5}{7}$"]', '$\frac{4}{7}$', NULL, 'Subtract the numerators and keep the denominator: 6 - 2 = 4, so 4/7.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/7 - 2/7 = 4/7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
