INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfb609a9-0e2d-4c63-bb2f-9042f44d897e', 'BA4.08', 1, 'numeric', 'Subtracting fractions with like denominators', 'Uri has a whole pizza and eats $\frac{3}{8}$ of it. What fraction of the pizza is left?', '[]', '5/8', '8/8-3/8', 'One whole pizza is 8/8. Then 8/8 - 3/8 = 5/8.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/8 - 3/8 = 5/8.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
