INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ed3f5cd-3d6f-427a-8040-67ee897e2f29', 'BA4.08', 1, 'numeric', 'Subtracting fractions with like denominators', '$\frac{10}{11} - \frac{6}{11}$ = ?', '[]', '4/11', '10/11-6/11', 'The denominators match, so subtract the numerators: 10 - 6 = 4. The answer is 4/11.', 'checked', '{"lint":[],"solve":{"answer":"4/11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/11 - 6/11 = 4/11.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
