INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b63acc1b-86c2-481a-bf45-b679de5d6546', 'BA4.08', 1, 'numeric', 'Adding and subtracting mixed numbers with like denominators', '$3\frac{1}{5} + 1\frac{2}{5}$ = ? Write the answer as a mixed number.', '[]', '4 3/5', '3+1+3/5', 'Add the wholes: 3 + 1 = 4. Add the fractions: 1/5 + 2/5 = 3/5. The answer is 4 and 3/5.', 'checked', '{"lint":[],"solve":{"answer":"4 3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 1 = 4, 1/5 + 2/5 = 3/5: 4 3/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
