INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48c9e629-6e33-466c-98b1-e1f05a1b1f54', 'BA4.08', 2, 'choice', 'Equivalent fractions', '$\frac{5}{8} = \frac{?}{24}$ What number does the ? stand for?', '["21","16","15","9"]', '15', '5*3', '8 x 3 = 24, so multiply the top by 3 as well: 5 x 3 = 15. So 5/8 = 15/24.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 8 x 3, so ? = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
