INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe1c2731-012f-44ff-86a2-5f3f69e221a7', 'BA4.08', 2, 'choice', 'Equivalent fractions', 'Which fraction is equivalent to $\frac{3}{4}$?', '["$\\frac{5}{6}$","$\\frac{9}{12}$","$\\frac{9}{4}$","$\\frac{6}{9}$"]', '$\frac{9}{12}$', NULL, 'Multiply the top and the bottom of 3/4 by 3: 9/12. The fraction 5/6 comes from adding 2 to both numbers, which does not keep the amount the same.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x 3/3 = 9/12.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
