INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0882bec7-c436-4f14-a83d-478c298c534e', 'BA4.08', 2, 'numeric', 'Equivalent fractions', 'A recipe uses $\frac{2}{3}$ cup of milk. How many sixths of a cup is that?', '[]', '4', '2*2', '3 x 2 = 6, so multiply the top by 2: 2 x 2 = 4. So 2/3 cup is 4/6 cup, which is 4 sixths.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6: 4 sixths.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d073a25-a681-49e5-89a5-8d654108e01c', 'BA4.08', 2, 'choice', 'Equivalent fractions', 'Which pair of fractions are equal to each other?', '["$\\frac{4}{6}$ and $\\frac{6}{9}$","$\\frac{3}{5}$ and $\\frac{6}{9}$","$\\frac{2}{5}$ and $\\frac{4}{12}$","$\\frac{3}{8}$ and $\\frac{6}{12}$"]', '$\frac{4}{6}$ and $\frac{6}{9}$', NULL, '4/6 simplifies to 2/3 (divide by 2) and 6/9 simplifies to 2/3 (divide by 3), so they are equal. In the other pairs, the fractions are different amounts.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$ and $\\frac{6}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 = 2/3 and 6/9 = 2/3. 3/5 vs 6/9 = 2/3 no; 3/8 vs 1/2 no; 2/5 vs 1/3 no.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135bde7d-1c26-47d9-a428-a1c2a0787cec', 'BA4.08', 2, 'numeric', 'Equivalent fractions', '$\frac{18}{24} = \frac{3}{?}$ What number does the ? stand for?', '[]', '4', '24/6', 'The top went from 18 to 3, which is dividing by 6. Divide the bottom by 6 too: 24 / 6 = 4. So 18/24 = 3/4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 3/4 (divide by 6), so ? = 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53e7ca38-7c11-4565-97f6-e91e11b8c2c3', 'BA4.08', 2, 'numeric', 'Simplest form', 'Write $\frac{18}{24}$ in simplest form.', '[]', '3/4', '18/24', 'The greatest common factor of 18 and 24 is 6. 18 / 6 = 3 and 24 / 6 = 4, so 18/24 = 3/4.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 6: 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d40a0277-fe80-4d05-84f2-39b16a0cd8cf', 'BA4.08', 2, 'choice', 'Simplest form', 'Which of these fractions cannot be simplified?', '["$\\frac{9}{15}$","$\\frac{12}{16}$","$\\frac{10}{16}$","$\\frac{9}{16}$"]', '$\frac{9}{16}$', NULL, '9 and 16 share no factor except 1. The others can be simplified: 9/15 = 3/5, 12/16 = 3/4 and 10/16 = 5/8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{16}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/16: 9 = 3x3, 16 = 2^4, no common factor. 9/15, 12/16, 10/16 simplify.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f18243c-ca59-4b50-ade3-5a34b2cd4d8a', 'BA4.08', 2, 'numeric', 'Simplest form', 'A bag has 20 marbles and 8 of them are blue. What fraction of the marbles are blue, in simplest form?', '[]', '2/5', '8/20', '8/20 has a greatest common factor of 4. 8 / 4 = 2 and 20 / 4 = 5, so 2/5.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/20 = 2/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69f1dabe-c06a-4994-969c-6d6b03d357a1', 'BA4.08', 2, 'numeric', 'Simplest form', 'Simplify $\frac{28}{42}$ as far as you can.', '[]', '2/3', '28/42', 'The greatest common factor of 28 and 42 is 14. 28 / 14 = 2 and 42 / 14 = 3, so the answer is 2/3.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(28,42) = 14: 2/3.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
