INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ed0d978-237f-472d-881d-be8aa80e46e0', 'BA4.08', 2, 'choice', 'Comparing fractions', 'Dan ate $\frac{2}{3}$ of a small pizza, Eve ate $\frac{3}{4}$ of an identical one, Fay ate $\frac{5}{6}$ of another one and Gus ate $\frac{7}{12}$ of another one. All the pizzas are the same size. Who ate the least?', '["Gus","Dan","Eve","Fay"]', 'Gus', NULL, 'Write all in twelfths: Dan 8/12, Eve 9/12, Fay 10/12, Gus 7/12. The smallest is 7/12, so Gus ate the least.', 'checked', '{"lint":[],"solve":{"answer":"Gus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In twelfths: Dan 8/12, Eve 9/12, Fay 10/12, Gus 7/12. Least: Gus.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4a22d10-c418-4887-86dc-4a83be870d9d', 'BA4.08', 2, 'choice', 'Comparing fractions', 'Which comparison is correct?', '["$\\frac{5}{8} > \\frac{2}{3}$","$\\frac{3}{5} > \\frac{3}{4}$","$\\frac{7}{10} < \\frac{1}{2}$","$\\frac{5}{8} < \\frac{2}{3}$"]', '$\frac{5}{8} < \frac{2}{3}$', NULL, 'In twenty-fourths, 5/8 = 15/24 and 2/3 = 16/24, so 5/8 < 2/3. Also 3/5 < 3/4 (fifths are smaller than quarters) and 7/10 > 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8} < \\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 = 15/24, 2/3 = 16/24, so 5/8 < 2/3. 7/10 > 1/2; 3/5 < 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13be13b9-b3dd-4247-a81c-556f2be29788', 'BA4.08', 2, 'choice', 'Comparing fractions', 'How many fractions with a denominator of 10 and a whole-number numerator are greater than $\frac{1}{2}$ and less than 1?', '["3","5","9","4"]', '4', '4', '1/2 = 5/10 and 1 = 10/10. The numerators between 5 and 10 are 6, 7, 8, 9, so there are 4 fractions.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/10 < k/10 < 10/10: k = 6,7,8,9. Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1ee7aed-b9ad-4711-8ff7-ce5ed7dce8e9', 'BA4.08', 2, 'choice', 'Comparing fractions', 'Which fraction is closest to 1?', '["$\\frac{7}{8}$","$\\frac{5}{6}$","$\\frac{9}{10}$","$\\frac{3}{4}$"]', '$\frac{9}{10}$', NULL, 'Each is a bit less than 1. The missing piece is 1/10, 1/8, 1/6 and 1/4. The smallest missing piece is 1/10, so 9/10 is closest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 1: 1/4, 1/10, 1/8, 1/6; smallest 1/10, so 9/10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
