INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69af2af7-e6e9-4a90-956f-a1dcc8eb07e4', 'BA4.08', 2, 'numeric', 'Adding fractions with like denominators', '$\frac{5}{12} + \frac{11}{12}$ = ? Write the answer as a mixed number.', '[]', '1 1/3', '5/12+11/12', '5 + 11 = 16, so the sum is 16/12. 12/12 is 1 whole, with 4/12 left. 4/12 = 1/3, so the answer is 1 and 1/3.', 'checked', '{"lint":[],"solve":{"answer":"1 1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/12 + 11/12 = 16/12 = 1 4/12 = 1 1/3.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
