INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d74d04c6-7add-4866-b5ba-b6f179c221ec', 'BA4.08', 2, 'choice', 'Adding fractions with like denominators', 'A recipe uses $\frac{3}{5}$ cup of oil and then $\frac{4}{5}$ cup more. How much oil is that in all?', '["$1\\frac{2}{5}$","$\\frac{7}{10}$","$\\frac{12}{25}$","$1\\frac{4}{5}$"]', '$1\frac{2}{5}$', NULL, '3/5 + 4/5 = 7/5. 5/5 is 1 whole, and 2/5 is left, so it is 1 and 2/5 cups. Adding the denominators (7/10) is a common mistake.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 + 4/5 = 7/5 = 1 2/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
