INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bbbe179-b83b-468e-89cc-14ed1683af9a', 'BA4.08', 2, 'numeric', 'Adding fractions with like denominators', '$\frac{7}{15} + \frac{4}{15} + \frac{2}{15}$ = ?', '[]', '13/15', '7/15+4/15+2/15', 'Add all three numerators: 7 + 4 + 2 = 13. The denominator stays 15. So 13/15.', 'checked', '{"lint":[],"solve":{"answer":"13/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 4 + 2 = 13: 13/15.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
