INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8a86e6-5678-48e1-944a-a2458512080d', 'BA4.08', 2, 'numeric', 'Adding fractions with like denominators', 'Tess runs $\frac{5}{8}$ of a mile on Monday and $\frac{3}{8}$ of a mile on Tuesday. How many miles does she run in all?', '[]', '1', '5/8+3/8', '5/8 + 3/8 = 8/8, which is 1 whole mile.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 + 3/8 = 8/8 = 1.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
