INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d80c27cc-3e1d-4005-af0a-3afb3521444c', 'BA4.08', 2, 'numeric', 'Subtracting fractions with like denominators', '$\frac{13}{15} - \frac{4}{15}$ = ? Write the answer in simplest form.', '[]', '3/5', '9/15', '13 - 4 = 9, so 9/15. Divide the top and bottom by 3 to get 3/5.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13/15 - 4/15 = 9/15 = 3/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
