INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2c028bd-f2b2-486a-b0b5-98a2bf1851bf', 'BA4.08', 2, 'numeric', 'Subtracting fractions with like denominators', '$\frac{11}{8} - \frac{5}{8}$ = ? Write the answer in simplest form.', '[]', '3/4', '6/8', '11 - 5 = 6, so 6/8. Dividing the top and bottom by 2 gives 3/4.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/8 - 5/8 = 6/8 = 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
