INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e13c7f3c-0bf2-4070-b5e8-e77ae9ac0887', 'BA4.08', 2, 'choice', 'Subtracting fractions with like denominators', 'Which difference is equal to $\frac{3}{10}$?', '["$\\frac{9}{10}$ - $\\frac{3}{10}$","$\\frac{9}{10}$ - $\\frac{6}{10}$","$\\frac{9}{5}$ - $\\frac{6}{5}$","$\\frac{12}{10}$ - $\\frac{3}{10}$"]', '$\frac{9}{10}$ - $\frac{6}{10}$', NULL, '9/10 - 6/10 = 3/10. The others come to 6/10, 3/5 and 9/10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{10}$ - $\\frac{6}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 - 6/10 = 3/10. Others: 9/10, 3/5, 6/10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3010bae-ab73-41c0-ba92-a6c322229347', 'BA4.08', 2, 'numeric', 'Subtracting fractions with like denominators', 'A jar is $\frac{7}{9}$ full of paint. Some paint is used, and then the jar is $\frac{2}{9}$ full. What fraction of a jar of paint was used?', '[]', '5/9', '7/9-2/9', 'The amount used is 7/9 - 2/9 = 5/9.', 'checked', '{"lint":[],"solve":{"answer":"5/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/9 - 2/9 = 5/9.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
