INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f2a22db-94ad-451a-827f-b77a4a76a549', 'BA4.08', 2, 'numeric', 'Adding and subtracting mixed numbers with like denominators', '$5\frac{3}{4} - 2\frac{1}{4}$ = ? Write the answer in simplest form.', '[]', '3 1/2', '3+2/4', 'Subtract the wholes: 5 - 2 = 3. Subtract the fractions: 3/4 - 1/4 = 2/4 = 1/2. The answer is 3 and 1/2.', 'checked', '{"lint":[],"solve":{"answer":"3 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 3/4 - 2 1/4 = 3 2/4 = 3 1/2.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
