INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72d3b9ea-f9d9-4c2a-ab0a-5c71b86894f0', 'BA4.08', 2, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'Mara has $2\frac{3}{5}$ cups of rice in one jar and $1\frac{4}{5}$ cups in another jar. How many cups does she have in all? Write a mixed number.', '[]', '4 2/5', '3+7/5', 'Wholes: 2 + 1 = 3. Fractions: 3/5 + 4/5 = 7/5 = 1 and 2/5. Then 3 + 1 and 2/5 = 4 and 2/5.', 'checked', '{"lint":[],"solve":{"answer":"4 2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 3/5 + 1 4/5 = 3 7/5 = 4 2/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b31bf270-f758-409b-b24a-ef7f27bd801c', 'BA4.08', 2, 'choice', 'Adding and subtracting mixed numbers with like denominators', 'What is $7\frac{5}{9} - 3\frac{1}{9}$?', '["$10\\frac{6}{9}$","$4\\frac{6}{9}$","$3\\frac{4}{9}$","$4\\frac{4}{9}$"]', '$4\frac{4}{9}$', NULL, 'Wholes: 7 - 3 = 4. Fractions: 5/9 - 1/9 = 4/9. So 4 and 4/9. (Adding gives 10 and 6/9.)', 'checked', '{"lint":[],"solve":{"answer":"$4\\frac{4}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 5/9 - 3 1/9 = 4 4/9.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef6e45c4-98be-447b-bc49-0f2946417204', 'BA4.08', 2, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'A board is $6\frac{5}{8}$ feet long. A piece $2\frac{3}{8}$ feet long is cut off. How long is the rest of the board, in feet? Write the answer in simplest form.', '[]', '4 1/4', '4+2/8', 'Wholes: 6 - 2 = 4. Fractions: 5/8 - 3/8 = 2/8 = 1/4. So 4 and 1/4 feet.', 'checked', '{"lint":[],"solve":{"answer":"4 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 5/8 - 2 3/8 = 4 2/8 = 4 1/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6960126a-596c-4320-8908-850930fb4e7a', 'BA4.08', 2, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'Dev reads for $2\frac{2}{7}$ hours on Saturday and $1\frac{3}{7}$ hours on Sunday. How many hours does he read in all?', '[]', '3 5/7', '3+5/7', 'Wholes: 2 + 1 = 3. Fractions: 2/7 + 3/7 = 5/7. The total is 3 and 5/7 hours.', 'checked', '{"lint":[],"solve":{"answer":"3 5/7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 2/7 + 1 3/7 = 3 5/7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b65e915-8b54-4f4c-99da-47d8fd17a8eb', 'BA4.08', 3, 'choice', 'Equivalent fractions', 'A fraction is equal to $\frac{2}{5}$. Its numerator and denominator add up to 35. What is its numerator?', '["14","25","5","10"]', '10', '2*35/7', 'In 2/5 the top and bottom add to 2 + 5 = 7. To reach 35 we multiply the top and bottom by 35 / 7 = 5, giving 10/25. Check: 10 + 25 = 35. The numerator is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2k + 5k = 35, k = 5: 10/25. Numerator 10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c60d0cd0-a1a9-4bb2-900a-a1a427ad0d72', 'BA4.08', 3, 'choice', 'Equivalent fractions', 'A fraction is equal to $\frac{5}{6}$. Its denominator is 12 more than its numerator. What is its numerator?', '["12","72","30","60"]', '60', '5*12', 'The fraction is 5k/6k. The denominator minus the numerator is 6k - 5k = k, so k = 12. The numerator is 5 x 12 = 60 (and the fraction is 60/72).', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6k - 5k = 12, k = 12: 60/72. Numerator 60.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c5dc94b-bda9-4074-9c36-8aa12094c077', 'BA4.08', 3, 'choice', 'Equivalent fractions', 'Which of these fractions is NOT equal to $\frac{12}{18}$?', '["$\\frac{2}{3}$","$\\frac{4}{6}$","$\\frac{6}{8}$","$\\frac{6}{9}$"]', '$\frac{6}{8}$', NULL, '12/18 simplifies to 2/3. Also 4/6 = 2/3 and 6/9 = 2/3. But 6/8 simplifies to 3/4, which is not 2/3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/18 = 2/3 = 4/6 = 6/9; 6/8 = 3/4 is not.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee523d09-b3cc-42e1-a22d-cd236f43a5c6', 'BA4.08', 3, 'choice', 'Equivalent fractions', 'How many different fractions equal to $\frac{1}{2}$ have a whole-number numerator and a denominator from 1 to 20?', '["9","10","20","11"]', '10', '20/2', 'Fractions equal to 1/2 have a denominator that is double the numerator: 1/2, 2/4, 3/6, ..., 10/20. The denominators are the even numbers 2, 4, 6, ..., 20, which is 10 fractions.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fractions k/(2k) with 2k from 1 to 20: denominators 2,4,...,20, ten fractions.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0689e884-09ab-412f-95d5-e4b4a7c1ac32', 'BA4.08', 3, 'choice', 'Simplest form', 'How many fractions with a denominator of 12 and a numerator from 1 to 11 are already in simplest form?', '["3","5","4","6"]', '4', '4', 'The numerator and 12 must share no factor but 1. Numerators 1, 5, 7 and 11 work. The others (2, 3, 4, 6, 8, 9, 10) share 2 or 3 with 12. So 4 fractions.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerators 1-11 sharing no factor with 12: 1, 5, 7, 11. Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27d4cffa-494d-443c-8854-dd64dbeba653', 'BA4.08', 3, 'choice', 'Simplest form', 'When $\frac{24}{60}$ is written in simplest form, what is the sum of the numerator and the denominator?', '["84","7","12","3"]', '7', '2+5', 'The greatest common factor of 24 and 60 is 12. 24/60 = 2/5 and 2 + 5 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF 12: 24/60 = 2/5; 2 + 5 = 7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f701606f-cdd7-409d-a495-e4b8e47eeb38', 'BA4.08', 3, 'choice', 'Simplest form', 'Which fraction simplifies to $\frac{3}{4}$?', '["$\\frac{21}{24}$","$\\frac{21}{28}$","$\\frac{14}{21}$","$\\frac{28}{35}$"]', '$\frac{21}{28}$', NULL, '21/28: divide the top and the bottom by 7 to get 3/4. The others simplify to 7/8, 2/3 and 4/5.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{21}{28}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21/28 = 3/4 (divide by 7). 14/21 = 2/3, 21/24 = 7/8, 28/35 = 4/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eed08918-a56a-4cba-9d47-72ccee113daa', 'BA4.08', 3, 'numeric', 'Simplest form', 'Write $\frac{2 \times 3 \times 5}{2 \times 2 \times 3 \times 7}$ in simplest form.', '[]', '5/14', '30/84', 'The top is 30 and the bottom is 84. Cancel the 2 and the 3 that appear in both: 5 over (2 x 7) = 5/14.', 'checked', '{"lint":[],"solve":{"answer":"5/14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cancel 2 and 3: 5/(2x7) = 5/14.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b37482f9-6284-4066-8683-2f6f5a67ba44', 'BA4.08', 3, 'choice', 'Comparing fractions', 'Which list is in order from least to greatest?', '["$\\frac{1}{2}, \\frac{5}{8}, \\frac{2}{3}, \\frac{3}{4}$","$\\frac{1}{2}, \\frac{2}{3}, \\frac{5}{8}, \\frac{3}{4}$","$\\frac{1}{2}, \\frac{5}{8}, \\frac{3}{4}, \\frac{2}{3}$","$\\frac{5}{8}, \\frac{1}{2}, \\frac{2}{3}, \\frac{3}{4}$"]', '$\frac{1}{2}, \frac{5}{8}, \frac{2}{3}, \frac{3}{4}$', NULL, 'In twenty-fourths: 1/2 = 12/24, 5/8 = 15/24, 2/3 = 16/24, 3/4 = 18/24. The order is 12, 15, 16, 18.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}, \\frac{5}{8}, \\frac{2}{3}, \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Decimals: 1/2 = .5, 5/8 = .625, 2/3 = .667, 3/4 = .75.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b73c922f-b604-4f9f-8ce5-6761af6921d0', 'BA4.08', 3, 'choice', 'Comparing fractions', 'What is the smallest whole number n for which $\frac{3}{n}$ is less than $\frac{1}{4}$?', '["13","12","7","15"]', '13', '3*4+1', '3/n < 1/4 means n is more than 3 x 4 = 12 (3/12 = 1/4 exactly, which is not less). So the smallest whole number is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 3/12; 3/n < 3/12 needs n > 12; smallest 13.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e6ff9f3-7197-4f6f-873c-5b4011f6276e', 'BA4.08', 3, 'choice', 'Comparing fractions', 'How many fractions with a denominator of 14 and a whole-number numerator are greater than $\frac{3}{7}$ and less than $\frac{5}{7}$?', '["2","4","5","3"]', '3', '3', '3/7 = 6/14 and 5/7 = 10/14. The numerators between 6 and 10 are 7, 8, 9, so there are 3 fractions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/7 = 6/14, 5/7 = 10/14; numerators 7, 8, 9. Count 3.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c96d4345-0c5d-48c9-a9e8-feffa0c9da60', 'BA4.08', 3, 'choice', 'Comparing fractions', 'Which fraction is between $\frac{2}{5}$ and $\frac{1}{2}$?', '["$\\frac{3}{10}$","$\\frac{3}{5}$","$\\frac{9}{20}$","$\\frac{11}{20}$"]', '$\frac{9}{20}$', NULL, 'In twentieths: 2/5 = 8/20 and 1/2 = 10/20. 9/20 is between them. 3/10 = 6/20 is less than both, and 3/5 = 12/20 and 11/20 are more than both.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = 8/20, 1/2 = 10/20; 9/20 lies between. 11/20 and 3/5 too big; 3/10 too small.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('219dd887-dbdf-45ab-a2df-47f1721169f7', 'BA4.08', 3, 'choice', 'Improper fractions to mixed numbers', 'Between which two neighboring whole numbers is $\frac{53}{6}$? Give the smaller of the two.', '["8","9","7","6"]', '8', '8', '6 x 8 = 48 and 6 x 9 = 54. Since 53 is between 48 and 54, 53/6 is between 8 and 9. The smaller is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"53/6 = 8 5/6, between 8 and 9; smaller 8.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ab30f7c-2ca6-4d74-bc68-f1d0271b26a1', 'BA4.08', 3, 'choice', 'Improper fractions to mixed numbers', 'Which fraction is greater than 3 and less than 4?', '["$\\frac{12}{4}$","$\\frac{16}{4}$","$\\frac{11}{4}$","$\\frac{15}{4}$"]', '$\frac{15}{4}$', NULL, '12/4 = 3 and 16/4 = 4, so neither is between 3 and 4. 11/4 = 2 and 3/4. But 15/4 = 3 and 3/4, which is between 3 and 4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{15}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/4 = 3 3/4. 12/4 = 3, 16/4 = 4, 11/4 = 2 3/4 not strictly between.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a8733e6-b299-4f9f-bfa9-eb20154e69d7', 'BA4.08', 3, 'choice', 'Improper fractions to mixed numbers', 'Ria writes every fraction with a denominator of 5 that is greater than 2 and less than 3. How many fractions does she write?', '["3","5","4","6"]', '4', '4', '2 = 10/5 and 3 = 15/5. The numerators between 10 and 15 are 11, 12, 13, 14, so she writes 4 fractions.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 = 10/5, 3 = 15/5; numerators 11-14. Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8af912a4-5514-498c-bf79-5036a1157b0c', 'BA4.08', 3, 'choice', 'Mixed numbers to improper fractions', '$\frac{?}{6} = 9\frac{5}{6}$ What number does the ? stand for?', '["54","14","95","59"]', '59', '9*6+5', '9 wholes are 9 x 6 = 54 sixths. Add 5 more sixths: 59/6.', 'checked', '{"lint":[],"solve":{"answer":"59","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 6 + 5 = 59.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
