INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b4740d2-4c08-44c2-b4bf-03af9163fa84', 'BA4.08', 3, 'choice', 'Mixed numbers to improper fractions', 'Which of these numbers is the greatest?', '["$\\frac{7}{2}$","$\\frac{11}{3}$","$\\frac{18}{5}$","$3\\frac{3}{4}$"]', '$3\frac{3}{4}$', NULL, 'Write each as a mixed number: 7/2 = 3 and 1/2, 11/3 = 3 and 2/3, 18/5 = 3 and 3/5. All have 3 wholes, so compare 3/4, 1/2, 2/3 and 3/5. In sixtieths these are 45, 30, 40 and 36, so 3 and 3/4 is the greatest.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/3 = 3.67, 7/2 = 3.5, 18/5 = 3.6, 3 3/4 = 3.75. Greatest 3 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc98e39a-4254-4c04-a277-f9288421d1c0', 'BA4.08', 3, 'choice', 'Mixed numbers to improper fractions', 'A mixed number has a whole part of 4 and a fraction part of $\frac{3}{8}$. When it is written as an improper fraction, what is the sum of the numerator and the denominator?', '["35","15","43","38"]', '43', '4*8+3+8', '4 wholes are 32 eighths and 3 more eighths make 35/8. Then 35 + 8 = 43.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 3/8 = 35/8; 35 + 8 = 43.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14b79d2e-a52c-4e3b-aa56-1eead07f085b', 'BA4.08', 3, 'choice', 'Adding fractions with like denominators', '$\frac{?}{9} + \frac{4}{9} = \frac{11}{9}$ What number does the ? stand for?', '["15","6","4","7"]', '7', '11-4', 'The numerators must add to 11: ? + 4 = 11, so ? = 7. Check: 7/9 + 4/9 = 11/9.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? + 4 = 11, ? = 7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
