INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98e515e2-4aa6-4824-a390-d80e3fbfc3ca', 'BA4.08', 3, 'choice', 'Adding fractions with like denominators', 'Which pair of fractions has a sum of exactly 1?', '["$\\frac{3}{8}$ + $\\frac{3}{8}$","$\\frac{5}{16}$ + $\\frac{3}{16}$","$\\frac{3}{8}$ + $\\frac{5}{8}$","$\\frac{5}{8}$ + $\\frac{5}{8}$"]', '$\frac{3}{8}$ + $\frac{5}{8}$', NULL, '3/8 + 5/8 = 8/8 = 1. The other sums are 6/8, 8/16 and 10/8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$ + $\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 + 5/8 = 8/8 = 1. Others: 10/8, 8/16, 6/8.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
