INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1db048b0-98d3-4b33-a8e8-912a2d067f47', 'BA4.08', 3, 'numeric', 'Adding fractions with like denominators', '$\frac{1}{9} + \frac{8}{9} = 1$ is one way to split 1 into two fractions with a denominator of 9. How many different pairs of fractions with a denominator of 9 and numerators of 1 or more add up to 1? (Count $\frac{3}{9}$ + $\frac{6}{9}$ and $\frac{6}{9}$ + $\frac{3}{9}$ as the same pair.)', '[]', '4', '4', 'The numerators must add to 9: 1 + 8, 2 + 7, 3 + 6, 4 + 5. That is 4 pairs (the others are the same pairs in the other order).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator pairs summing to 9, both >= 1, unordered: (1,8),(2,7),(3,6),(4,5). Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b19bf66-5471-4ad1-880b-9e19d1a966c1', 'BA4.08', 3, 'numeric', 'Adding fractions with like denominators', 'A jug is $\frac{1}{12}$ full. Liam pours in $\frac{5}{12}$ of a jug of water and then Mia pours in $\frac{4}{12}$ of a jug. What fraction of the jug is still empty, in simplest form?', '[]', '1/6', '12/12-10/12', 'Full: 1/12 + 5/12 + 4/12 = 10/12. The empty part is 12/12 - 10/12 = 2/12, which is 1/6 in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/12 + 5/12 + 4/12 = 10/12 full; empty 2/12 = 1/6.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
