VALUES ('e531af17-0194-4389-bb94-8c830475e57e', 'BA4.08', 3, 'numeric', 'Subtracting fractions with like denominators', '$1 - \frac{3}{11} - \frac{5}{11}$ = ?', '[]', '3/11', '11/11-3/11-5/11', 'Write 1 as 11/11. Then 11/11 - 3/11 - 5/11 = 3/11.', 'checked', '{"lint":[],"solve":{"answer":"3/11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/11 - 3/11 - 5/11 = 3/11.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
