INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbda0ea1-28de-4411-b66e-67ff1c55defe', 'BA4.08', 3, 'numeric', 'Subtracting fractions with like denominators', 'I subtract $\frac{5}{12}$ from a secret fraction and get $\frac{4}{12}$. What is the secret fraction?', '[]', '9/12', '4/12+5/12', 'Work backwards: the secret fraction is 4/12 + 5/12 = 9/12.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Secret = 4/12 + 5/12 = 9/12 = 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
