INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94a0f031-b2d7-42c8-b3f0-bbbfea369e1a', 'BA4.08', 3, 'choice', 'Subtracting fractions with like denominators', 'Which difference is the greatest?', '["$\\frac{9}{10}$ - $\\frac{2}{10}$","$\\frac{8}{10}$ - $\\frac{4}{10}$","$\\frac{7}{10}$ - $\\frac{1}{10}$","$\\frac{9}{10}$ - $\\frac{5}{10}$"]', '$\frac{9}{10}$ - $\frac{2}{10}$', NULL, 'The differences are 7/10, 4/10, 6/10 and 4/10. The greatest is 9/10 - 2/10 = 7/10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{10}$ - $\\frac{2}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences: 4/10, 6/10, 4/10, 7/10. Greatest 7/10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
