INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b00e5f75-1fd6-48a7-a7f1-273e1ef802f1', 'BA4.08', 3, 'choice', 'Adding and subtracting mixed numbers with like denominators', 'What is $4\frac{2}{7} - 1\frac{5}{7}$?', '["$3\\frac{3}{7}$","$3\\frac{4}{7}$","$2\\frac{4}{7}$","$2\\frac{3}{7}$"]', '$2\frac{4}{7}$', NULL, '4 and 2/7 = 3 and 9/7 (one whole is 7/7). Then 3 and 9/7 - 1 and 5/7 = 2 and 4/7.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{4}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/7 - 12/7 = 18/7 = 2 4/7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
