VALUES ('651ea76b-62f4-44e5-808a-b7b53f82522c', 'BA4.08', 3, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'A rope is 3 meters long. A piece $1\frac{2}{5}$ meters long is cut from it. How many meters of rope are left? Write a mixed number.', '[]', '1 3/5', '3-7/5', '3 = 2 and 5/5. Then 2 and 5/5 - 1 and 2/5 = 1 and 3/5.', 'checked', '{"lint":[],"solve":{"answer":"1 3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 - 1 2/5 = 15/5 - 7/5 = 8/5 = 1 3/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
