INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8ea9098-5918-459a-8b6e-636a28a02391', 'BA4.08', 3, 'numeric', 'Adding and subtracting mixed numbers with like denominators', '$5\frac{1}{6} + 2\frac{5}{6}$ = ?', '[]', '8', '5+2+1', 'Wholes: 5 + 2 = 7. Fractions: 1/6 + 5/6 = 6/6 = 1. So the total is 7 + 1 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 2 = 7, 1/6 + 5/6 = 1; total 8.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
