VALUES ('d3ca2f4b-34f7-48fd-9de8-1fd1f47d1db0', 'BA4.08', 3, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'What number added to $2\frac{3}{8}$ makes $5\frac{1}{8}$? Write the answer in simplest form.', '[]', '2 3/4', '(41-19)/8', 'Subtract: 5 and 1/8 - 2 and 3/8. Regroup 5 and 1/8 as 4 and 9/8. Then 4 and 9/8 - 2 and 3/8 = 2 and 6/8 = 2 and 3/4.', 'checked', '{"lint":[],"solve":{"answer":"2 3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/8 - 2 3/8 = 41/8 - 19/8 = 22/8 = 11/4 = 2 3/4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
