INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fe82dc8-8cce-4599-af3a-12b385d4cd5f', 'BA4.08', 3, 'choice', 'Adding and subtracting mixed numbers with like denominators', 'Which is the value of $3\frac{3}{5} + 3\frac{3}{5}$?', '["$6\\frac{6}{10}$","$7\\frac{6}{5}$","$7\\frac{1}{5}$","$6\\frac{1}{5}$"]', '$7\frac{1}{5}$', NULL, '3 + 3 = 6 and 3/5 + 3/5 = 6/5 = 1 and 1/5. So 6 + 1 and 1/5 = 7 and 1/5.', 'checked', '{"lint":[],"solve":{"answer":"$7\\frac{1}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 6/5 = 7 1/5. (7 6/5 = 8 1/5, 6 6/10 = 6 3/5.)","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
