INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a0509d6-08d7-42e5-b335-e3966c866865', 'BA4.08', 3, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'A trail has three parts. They are $1\frac{2}{9}$ km, $2\frac{4}{9}$ km and $3\frac{5}{9}$ km long. How long is the whole trail in kilometers?', '[]', '7 2/9', '6+11/9', 'Wholes: 1 + 2 + 3 = 6. Fractions: 2/9 + 4/9 + 5/9 = 11/9 = 1 and 2/9. Total 6 + 1 and 2/9 = 7 and 2/9 km.', 'checked', '{"lint":[],"solve":{"answer":"7 2/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 1+2+3 = 6; ninths 2+4+5 = 11/9 = 1 2/9; total 7 2/9.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
