VALUES ('af4eb67e-c133-4ffc-883e-1d91b5a0a2fc', 'BA4.08', 3, 'numeric', 'Adding and subtracting mixed numbers with like denominators', 'A plant was $3\frac{3}{5}$ inches tall. Now it is $8\frac{1}{5}$ inches tall. How many inches did it grow?', '[]', '4 3/5', '(41-18)/5', 'Subtract: 8 and 1/5 - 3 and 3/5. Regroup 8 and 1/5 as 7 and 6/5. Then 7 and 6/5 - 3 and 3/5 = 4 and 3/5 inches.', 'checked', '{"lint":[],"solve":{"answer":"4 3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"41/5 - 18/5 = 23/5 = 4 3/5.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
