VALUES ('ab4deb39-7290-4c25-bb81-3db926647c64', 'BA4.09', 3, 'choice', 'Comparing and ordering integers', 'Which expression has the greatest value?', '["$5 - 9$","$-2 - 3$","$0 - 6$","$1 - 4$"]', '$1 - 4$', NULL, '1 - 4 = -3, 5 - 9 = -4, -2 - 3 = -5 and 0 - 6 = -6. The greatest is -3, from 1 - 4.', 'checked', '{"lint":[],"solve":{"answer":"$1 - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5, -4, -3, -6. Greatest -3 = 1 - 4.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
