VALUES ('f6889504-9163-410e-a9ea-7a3b3b6f3543', 'BA4.09', 3, 'choice', 'Subtracting integers', 'Three of these expressions have the same value. Which one does NOT?', '["$20 - 13$","$-6 - (-13)$","$-9 + 16$","$-1 - 8$"]', '$-1 - 8$', NULL, '20 - 13 = 7, -6 - (-13) = -6 + 13 = 7 and -9 + 16 = 7. But -1 - 8 = -9.', 'checked', '{"lint":[],"solve":{"answer":"$-1 - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9+16 = 7, -1-8 = -9, -6+13 = 7, 20-13 = 7. The odd one is -1 - 8.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
