VALUES ('750f9083-0395-4910-bca0-a273908f34f5', 'BA4.09', 3, 'choice', 'Temperature stories', 'At 8 am the temperature was $-5$ degrees. By 10 am it had risen 7 degrees. By noon it had fallen 4 degrees. By 2 pm it had risen 9 degrees. What was the temperature at 2 pm, in degrees?', '["$-7$","$3$","$7$","$17$"]', '$7$', '-5+7-4+9', '-5 + 7 = 2. Then 2 - 4 = -2. Then -2 + 9 = 7 degrees.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 + 7 = 2; 2 - 4 = -2; -2 + 9 = 7.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
