INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96ce3120-791e-4e73-bd8d-d2aeb20c4fda', 'BA4.09', 3, 'numeric', 'Elevation stories', 'An explorer is at an elevation of 12 meters and walks down a slope that falls 4 meters every minute. After how many minutes is the explorer at $-20$ meters?', '[]', '8', '32/4', 'The explorer must go down 12 + 20 = 32 meters. At 4 meters a minute that takes 32 / 4 = 8 minutes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 to -20 is 32 m down; 32/4 = 8 minutes.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
