INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('733b38ec-e191-494a-8594-2b9e520fb037', 'BA4.10', 1, 'numeric', 'Fraction stories', 'Rosa ate $\frac{1}{2}$ of a pie and Ted ate $\frac{1}{4}$ of the same pie. What fraction of the pie is left?', '[]', '1/4', '1/4', 'Together they ate 2/4 + 1/4 = 3/4 of the pie. 1 - 3/4 = 1/4 is left.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 1/2 - 1/4 = 1/4.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
