INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34d7dd11-0a59-4d49-b70f-98705b01df92', 'BA4.10', 1, 'choice', 'Fraction stories', 'A farmer has 20 cows. $\frac{1}{5}$ of them are brown. How many cows are NOT brown?', '["$16$","$4$","$5$","$15$"]', '$16$', '16/1', '1/5 of 20 is 4 brown cows. The rest are 20 - 4 = 16 cows.', 'checked', '{"lint":[],"solve":{"answer":"$16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 of 20 = 4 brown; 16 not brown.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
