INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('391c5253-ebca-4784-a79a-77c568c0d239', 'BA4.10', 1, 'choice', 'Fraction stories', 'Leo read $\frac{1}{2}$ of his book on Monday and $\frac{1}{3}$ of it on Tuesday. What fraction of the book has he read?', '["$\\frac{5}{6}$","$\\frac{2}{5}$","$\\frac{1}{5}$","$\\frac{2}{6}$"]', '$\frac{5}{6}$', NULL, 'In sixths: 1/2 = 3/6 and 1/3 = 2/6. Together, 5/6 of the book.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6 + 2/6 = 5/6.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
