VALUES ('b9d9c8fa-7cba-47ac-b520-b04dfcc74225', 'BA4.10', 2, 'choice', 'Adding fractions with unlike denominators', 'What is $\frac{3}{4} + \frac{2}{3}$?', '["$\\frac{5}{7}$","$1\\frac{1}{12}$","$1\\frac{5}{12}$","$\\frac{5}{12}$"]', '$1\frac{5}{12}$', NULL, 'Use twelfths: 3/4 = 9/12 and 2/3 = 8/12. Then 9/12 + 8/12 = 17/12 = 1 5/12.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 + 8/12 = 17/12 = 1 5/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
