VALUES ('e6dfd688-963f-4d34-9a41-3e51482dca07', 'BA4.10', 2, 'choice', 'Adding fractions with unlike denominators', 'What is $\frac{2}{3} + \frac{1}{4}$?', '["$\\frac{3}{7}$","$\\frac{11}{12}$","$\\frac{3}{12}$","$\\frac{5}{12}$"]', '$\frac{11}{12}$', NULL, 'Use twelfths: 2/3 = 8/12 and 1/4 = 3/12. Then 8/12 + 3/12 = 11/12.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/12 + 3/12 = 11/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
