INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a10f1c73-5bb6-4c56-949a-80a5202e60cc', 'BA4.10', 2, 'numeric', 'Adding fractions with unlike denominators', 'A recipe uses $\frac{2}{3}$ cup of flour and $\frac{1}{2}$ cup of sugar. How many cups of flour and sugar are used in all?', '[]', '1 1/6', '7/6', 'Use sixths: 2/3 = 4/6 and 1/2 = 3/6. Then 4/6 + 3/6 = 7/6 = 1 1/6 cups.', 'checked', '{"lint":[],"solve":{"answer":"1 1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 + 3/6 = 7/6 = 1 1/6 cups.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
