INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('668af802-72e5-4b11-bffc-3564bea1da04', 'BA4.10', 2, 'numeric', 'Adding fractions with unlike denominators', 'Find $\frac{5}{6} + \frac{3}{10}$.', '[]', '1 2/15', '17/15', 'Use thirtieths: 5/6 = 25/30 and 3/10 = 9/30. Then 25/30 + 9/30 = 34/30 = 17/15 = 1 2/15.', 'checked', '{"lint":[],"solve":{"answer":"1 2/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25/30 + 9/30 = 34/30 = 17/15 = 1 2/15.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
