INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3de57044-8eb0-4577-8816-2cbe55f07047', 'BA4.10', 2, 'choice', 'Adding fractions with unlike denominators', 'Which of these sums is equal to 1?', '["$\\frac{1}{2} + \\frac{1}{3} + \\frac{1}{6}$","$\\frac{1}{2} + \\frac{1}{4} + \\frac{1}{8}$","$\\frac{1}{3} + \\frac{1}{4} + \\frac{1}{5}$","$\\frac{1}{2} + \\frac{1}{3} + \\frac{1}{4}$"]', '$\frac{1}{2} + \frac{1}{3} + \frac{1}{6}$', NULL, 'In sixths: 1/2 + 1/3 + 1/6 = 3/6 + 2/6 + 1/6 = 6/6 = 1. The others make 7/8, 47/60 and 13/12.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2} + \\frac{1}{3} + \\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2+1/3+1/6 = 6/6 = 1. Others: 13/12, 47/60, 7/8.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
