VALUES ('e364fafe-e328-47d8-a568-df473c8be604', 'BA4.10', 2, 'choice', 'Subtracting fractions with unlike denominators', 'What is $\frac{5}{6} - \frac{3}{8}$?', '["$\\frac{1}{12}$","$\\frac{13}{24}$","$\\frac{11}{24}$","$\\frac{5}{24}$"]', '$\frac{11}{24}$', NULL, 'Use twenty-fourths: 5/6 = 20/24 and 3/8 = 9/24. So 20/24 - 9/24 = 11/24.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{24}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/24 - 9/24 = 11/24.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
