INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe1a3a2c-bdcb-4ae6-a010-b69e9060c578', 'BA4.10', 2, 'choice', 'Adding and subtracting mixed numbers with unlike denominators', 'Find the difference: $3\frac{1}{4} - 1\frac{2}{3}$', '["$2\\frac{5}{12}$","$1\\frac{5}{12}$","$2\\frac{1}{12}$","$1\\frac{7}{12}$"]', '$1\frac{7}{12}$', NULL, 'Use twelfths: 3 1/4 = 3 3/12 and 1 2/3 = 1 8/12. Since 3/12 is less than 8/12, change 3 3/12 into 2 15/12. Then 2 15/12 - 1 8/12 = 1 7/12.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 3/12 - 1 8/12 = 2 15/12 - 1 8/12 = 1 7/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
