VALUES ('6bded3b5-f408-4e98-b28d-31b275e19c05', 'BA4.10', 2, 'choice', 'A fraction of a quantity', 'A ribbon is 2 meters long. A piece that is $\frac{3}{4}$ of the ribbon is cut off. How many meters long is the piece?', '["$\\frac{3}{8}$","$\\frac{3}{4}$","$2\\frac{3}{4}$","$1\\frac{1}{2}$"]', '$1\frac{1}{2}$', NULL, '3/4 of 2 meters is 3 x 2 / 4 = 6/4 = 3/2 = 1 1/2 meters.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 of 2 = 6/4 = 1 1/2 m.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
