INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3b1c235-0b99-4ccf-878f-7da235c3707e', 'BA4.10', 2, 'numeric', 'Fraction stories', 'A tank holds 60 liters. It is $\frac{5}{12}$ full. How many more liters are needed to fill it?', '[]', '35', '35/1', '5/12 of 60 = 25 liters. To fill it needs 60 - 25 = 35 more liters.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Empty part 7/12 of 60 = 35.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
