INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83df4e05-b094-461a-9286-63a8502b0656', 'BA4.10', 2, 'choice', 'Fraction stories', 'Pam walked $\frac{2}{3}$ of a mile to the park and $\frac{3}{4}$ of a mile to get home. How much farther was the walk home?', '["$\\frac{5}{12}$","$\\frac{1}{7}$","$\\frac{1}{12}$","$1\\frac{5}{12}$"]', '$\frac{1}{12}$', NULL, 'In twelfths: 3/4 = 9/12 and 2/3 = 8/12. The difference is 1/12 of a mile.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 - 8/12 = 1/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
