INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a996b0c-80fb-4b62-83d3-8b9c1d3eb92a', 'BA4.10', 2, 'numeric', 'Fraction stories', 'Anna has a ribbon that is 2 meters long. She uses $\frac{3}{5}$ of a meter for a gift and $\frac{1}{2}$ of a meter for a card. How many meters of ribbon are left?', '[]', '9/10', '9/10', 'Use tenths: 3/5 = 6/10 and 1/2 = 5/10, so she uses 11/10 meters. Then 2 - 11/10 = 20/10 - 11/10 = 9/10 of a meter.', 'checked', '{"lint":[],"solve":{"answer":"9/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 + 1/2 = 11/10; 2 - 11/10 = 9/10.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
