INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41961c95-99b6-4f0f-9a17-1d85357d4496', 'BA4.10', 2, 'choice', 'Fraction stories', 'Zoe spends $\frac{1}{3}$ of a day at school and $\frac{1}{4}$ of the day asleep. What fraction of the day is left for other things?', '["$\\frac{7}{12}$","$\\frac{5}{12}$","$\\frac{2}{7}$","$\\frac{5}{7}$"]', '$\frac{5}{12}$', NULL, 'In twelfths: 1/3 = 4/12 and 1/4 = 3/12, so 7/12 of the day is used. The rest is 12/12 - 7/12 = 5/12.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 + 1/4 = 7/12; 1 - 7/12 = 5/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
