VALUES ('fcf9747c-eee0-4b7c-bf2f-e4792c96198e', 'BA4.10', 2, 'numeric', 'Fraction stories', 'Three friends ran $\frac{1}{2}$ of a mile, $\frac{3}{4}$ of a mile and $\frac{2}{3}$ of a mile. How many miles did they run in total?', '[]', '1 11/12', '23/12', 'In twelfths: 6/12 + 9/12 + 8/12 = 23/12 = 1 11/12 miles.', 'checked', '{"lint":[],"solve":{"answer":"1 11/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/12 + 9/12 + 8/12 = 23/12 = 1 11/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
