VALUES ('6abce511-0427-4744-a998-828bd8169caf', 'BA4.10', 3, 'choice', 'Adding fractions with unlike denominators', 'Add the three fractions: $\frac{1}{2} + \frac{1}{3} + \frac{1}{4}$', '["$\\frac{3}{9}$","$1\\frac{1}{6}$","$\\frac{11}{12}$","$1\\frac{1}{12}$"]', '$1\frac{1}{12}$', NULL, 'Use twelfths: 6/12 + 4/12 + 3/12 = 13/12 = 1 1/12.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{1}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/12 + 4/12 + 3/12 = 13/12 = 1 1/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
