INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b62001a4-3f1a-442e-9790-866f39786366', 'BA4.10', 3, 'choice', 'Adding fractions with unlike denominators', 'Find the missing number: $\frac{1}{6} + ? = \frac{3}{4}$', '["$\\frac{5}{12}$","$\\frac{11}{12}$","$\\frac{2}{10}$","$\\frac{7}{12}$"]', '$\frac{7}{12}$', NULL, 'The missing number is 3/4 - 1/6. In twelfths, 9/12 - 2/12 = 7/12. Check: 2/12 + 7/12 = 9/12 = 3/4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 - 1/6 = 9/12 - 2/12 = 7/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
