INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bef2fb9-df87-429b-b124-4577874c50e2', 'BA4.10', 3, 'choice', 'Adding fractions with unlike denominators', 'Which two fractions add up to $\frac{7}{12}$?', '["$\\frac{1}{3}$ and $\\frac{1}{6}$","$\\frac{1}{4}$ and $\\frac{1}{6}$","$\\frac{1}{3}$ and $\\frac{1}{4}$","$\\frac{1}{2}$ and $\\frac{1}{3}$"]', '$\frac{1}{3}$ and $\frac{1}{4}$', NULL, 'In twelfths, 1/3 = 4/12 and 1/4 = 3/12, and 4/12 + 3/12 = 7/12. The other pairs add to 6/12, 5/12 and 10/12.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$ and $\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3+1/4 = 7/12; 1/2+1/3 = 5/6; 1/4+1/6 = 5/12; 1/3+1/6 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
