INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cb29d11-f842-42d9-a07e-67364c674a11', 'BA4.10', 3, 'numeric', 'Adding fractions with unlike denominators', 'Ben ran $\frac{3}{4}$ of a mile and Cal ran $\frac{5}{6}$ of a mile. Together, how many miles more than 1 mile did they run?', '[]', '7/12', '7/12', 'In twelfths: 3/4 = 9/12 and 5/6 = 10/12. Together 19/12, which is 1 7/12 miles. That is 7/12 of a mile more than 1 mile.', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 + 10/12 = 19/12; 19/12 - 1 = 7/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
