INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8db08b64-9541-4e67-b31f-33b85fbe3978', 'BA4.10', 3, 'choice', 'Adding fractions with unlike denominators', 'What comes next in this pattern? $\frac{1}{2},\ \frac{5}{6},\ \frac{7}{6},\ \ldots$ (Each number is a fixed amount more than the one before.)', '["$1\\frac{1}{3}$","$1\\frac{1}{2}$","$1\\frac{5}{6}$","$1\\frac{1}{6}$"]', '$1\frac{1}{2}$', NULL, 'Each step adds 1/3: 1/2 + 1/3 = 5/6, 5/6 + 1/3 = 7/6, and 7/6 + 1/3 = 9/6 = 1 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Step: 5/6 - 1/2 = 2/6 = 1/3; 7/6 - 5/6 = 1/3. Next 7/6 + 2/6 = 9/6 = 1 1/2.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cef1fa90-9a99-46bc-b904-5cb761baa4a4', 'BA4.10', 3, 'choice', 'Subtracting fractions with unlike denominators', 'Find the missing number: $\frac{7}{8} - ? = \frac{1}{3}$', '["$1\\frac{1}{5}$","$1\\frac{5}{24}$","$\\frac{4}{5}$","$\\frac{13}{24}$"]', '$\frac{13}{24}$', NULL, 'The missing number is 7/8 - 1/3. In twenty-fourths: 21/24 - 8/24 = 13/24. Check: 13/24 + 8/24 = 21/24 = 7/8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13}{24}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? = 7/8 - 1/3 = 21/24 - 8/24 = 13/24.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
