INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77e6052d-7234-40cf-83a7-c57cd703a74a', 'BA4.10', 3, 'choice', 'Subtracting fractions with unlike denominators', 'Which fraction is closest to $\frac{1}{2}$?', '["$\\frac{3}{5}$","$\\frac{5}{12}$","$\\frac{4}{9}$","$\\frac{7}{10}$"]', '$\frac{4}{9}$', NULL, 'The gaps from 1/2 are: 4/9 is 1/18 away, 3/5 is 1/10 away, 5/12 is 1/12 away and 7/10 is 1/5 away. 1/18 is the smallest gap, so 4/9 is closest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 1/2: 5/12 -> 1/12, 4/9 -> 1/18, 3/5 -> 1/10, 7/10 -> 1/5. Smallest is 1/18: 4/9.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
