VALUES ('48bdf865-ae7e-4e33-b972-dfb3742ef426', 'BA4.10', 3, 'choice', 'Subtracting fractions with unlike denominators', 'The difference between two fractions is $\frac{1}{12}$. The greater fraction is $\frac{3}{4}$. What is the lesser fraction?', '["$\\frac{5}{6}$","$\\frac{7}{12}$","$\\frac{2}{3}$","$\\frac{1}{3}$"]', '$\frac{2}{3}$', NULL, '3/4 = 9/12. The lesser fraction is 9/12 - 1/12 = 8/12 = 2/3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 - 1/12 = 9/12 - 1/12 = 8/12 = 2/3.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
