VALUES ('324323c4-02bb-4224-a7ec-bd49a37a1790', 'BA4.10', 3, 'numeric', 'Adding and subtracting mixed numbers with unlike denominators', 'What is $4\frac{2}{3} - 1\frac{5}{6}$?', '[]', '2 5/6', '17/6', '4 2/3 = 4 4/6. Since 4/6 is less than 5/6, change 4 4/6 into 3 10/6. Then 3 10/6 - 1 5/6 = 2 5/6.', 'checked', '{"lint":[],"solve":{"answer":"2 5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 4/6 - 1 5/6 = 3 10/6 - 1 5/6 = 2 5/6.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
