INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98f083e2-a78f-46d7-8b1a-36314fc91a4d', 'BA4.10', 3, 'choice', 'Adding and subtracting mixed numbers with unlike denominators', 'What is $3\frac{1}{4} + 1\frac{5}{6}$?', '["$4\\frac{1}{12}$","$5\\frac{1}{6}$","$5\\frac{1}{12}$","$4\\frac{6}{10}$"]', '$5\frac{1}{12}$', NULL, 'Add the wholes: 3 + 1 = 4. Add the fractions: 1/4 + 5/6 = 3/12 + 10/12 = 13/12 = 1 1/12. So the total is 5 1/12.', 'checked', '{"lint":[],"solve":{"answer":"$5\\frac{1}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/12 + 10/12 = 13/12; 4 + 1 1/12 = 5 1/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
