INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe5c408f-7f34-4d65-bddd-1cd614c326d0', 'BA4.10', 3, 'choice', 'Adding and subtracting mixed numbers with unlike denominators', 'Find the missing number: $2\frac{1}{4} + ? = 5\frac{1}{3}$', '["$7\\frac{7}{12}$","$3\\frac{1}{12}$","$2\\frac{11}{12}$","$3\\frac{1}{7}$"]', '$3\frac{1}{12}$', NULL, 'The missing number is 5 1/3 - 2 1/4. In twelfths, 5 4/12 - 2 3/12 = 3 1/12.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{1}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/3 - 2 1/4 = 3 + 4/12 - 3/12 = 3 1/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
