INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdd79012-f6fd-4c5c-a44e-2fd0935cad6f', 'BA4.10', 3, 'numeric', 'Adding and subtracting mixed numbers with unlike denominators', 'A rope is $5\frac{1}{2}$ meters long. Pip cuts off $2\frac{1}{4}$ meters and then another $1\frac{2}{3}$ meters. How many meters of rope are left?', '[]', '1 7/12', '19/12', 'In twelfths: 5 1/2 = 5 6/12, 2 1/4 = 2 3/12, 1 2/3 = 1 8/12. After the first cut: 5 6/12 - 2 3/12 = 3 3/12. Then 3 3/12 = 2 15/12, and 2 15/12 - 1 8/12 = 1 7/12 meters.', 'checked', '{"lint":[],"solve":{"answer":"1 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/2 - 2 1/4 = 3 1/4; 3 3/12 - 1 8/12 = 1 7/12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
