INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e01f6d6e-c3bc-4697-a298-a1fef147eaff', 'BA4.10', 3, 'choice', 'Adding and subtracting mixed numbers with unlike denominators', 'What comes next in this pattern? $1\frac{1}{2},\ 2\frac{1}{6},\ 2\frac{5}{6},\ 3\frac{1}{2},\ \ldots$', '["$4\\frac{1}{6}$","$4$","$4\\frac{1}{3}$","$4\\frac{1}{2}$"]', '$4\frac{1}{6}$', NULL, 'Each number is 2/3 more than the one before: 3 1/2 + 2/3 = 3 3/6 + 4/6 = 3 7/6 = 4 1/6.', 'checked', '{"lint":[],"solve":{"answer":"$4\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each step adds 2/3: 1 1/2 -> 2 1/6 -> 2 5/6 -> 3 1/2 -> 4 1/6.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
