INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a24c4da-c8f0-4749-8121-3c966baad786', 'BA4.10', 3, 'choice', 'Multiplying a fraction by a whole number', 'Which product has the greatest value?', '["$4 \\times \\frac{3}{8}$","$3 \\times \\frac{1}{2}$","$2 \\times \\frac{7}{10}$","$5 \\times \\frac{1}{3}$"]', '$5 \times \frac{1}{3}$', NULL, '5 x 1/3 = 1 2/3. The others are 4 x 3/8 = 1 1/2, 3 x 1/2 = 1 1/2 and 2 x 7/10 = 1 2/5. The greatest is 1 2/3.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times \\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/10 = 1.4; 5/3 = 1 2/3; 3/2; 12/8 = 3/2. Greatest 5 x 1/3.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
