VALUES ('81e82d75-5cf1-4d60-9ffd-505220de5020', 'BA4.10', 3, 'numeric', 'Multiplying a fraction by a whole number', 'What is $10 \times \frac{3}{4} - 3 \times \frac{5}{6}$?', '[]', '5', '5/1', '10 x 3/4 = 30/4 = 15/2, and 3 x 5/6 = 15/6 = 5/2. Then 15/2 - 5/2 = 10/2 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/4 = 7 1/2; 15/6 = 2 1/2; 7 1/2 - 2 1/2 = 5.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
