INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0344512-4d1d-43c0-82d3-66036ea8a270', 'BA4.10', 3, 'numeric', 'Multiplying a fraction by a whole number', 'Liam pours $\frac{3}{8}$ of a liter into each of 12 bottles. Maya pours $\frac{5}{6}$ of a liter into each of 9 bottles. How many more liters does Maya pour than Liam?', '[]', '3', '3/1', 'Liam: 12 x 3/8 = 36/8 = 4 1/2 liters. Maya: 9 x 5/6 = 45/6 = 7 1/2 liters. The difference is 7 1/2 - 4 1/2 = 3 liters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Liam 12 x 3/8 = 4 1/2; Maya 9 x 5/6 = 7 1/2; difference 3.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
