INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cd8caae-8021-4ad0-85f6-c7a2531e59df', 'BA4.10', 3, 'choice', 'A fraction of a quantity', '$\frac{3}{5}$ of a number is 18. What is the number?', '["$6$","$54$","$30$","$90$"]', '$30$', '30/1', '3/5 of the number is 18, so 1/5 of it is 18 / 3 = 6. The whole number is 5 x 6 = 30.', 'checked', '{"lint":[],"solve":{"answer":"$30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 of the number is 6; number is 30.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
