INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f77a322-0df6-4328-8602-952407f44f44', 'BA4.10', 3, 'numeric', 'A fraction of a quantity', 'A school has 240 students. $\frac{3}{8}$ of them are in fourth grade and $\frac{1}{6}$ of them are in fifth grade. How many students are in neither grade?', '[]', '110', '110/1', '3/8 of 240 = 90 and 1/6 of 240 = 40. Then 240 - 90 - 40 = 110 students.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 of 240 = 90; 1/6 of 240 = 40; 240 - 130 = 110.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
