INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1f5b25c-e6b8-4d3e-8429-1c96f0cb9b34', 'BA4.10', 3, 'choice', 'A fraction of a quantity', 'Tom spent $\frac{1}{4}$ of his money on a book. Then he spent $\frac{1}{3}$ of the money he had left on lunch. After that he had 12 dollars. How many dollars did Tom have at the start?', '["$18$","$24$","$36$","$48$"]', '$24$', '24/1', 'After the book he had 3/4 of his money. Lunch took 1/3 of that, so 2/3 of 3/4 remained, which is 1/2 of his money. Half of his money is 12 dollars, so he started with 24 dollars.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After book 3/4 left; lunch takes 1/3 of that, leaving 2/3 x 3/4 = 1/2 of start = 12; start 24. Check: 24 -> 18 -> 12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('446b58da-38fd-4a93-9449-05ceea0638af', 'BA4.10', 3, 'numeric', 'A fraction of a quantity', 'Find $\frac{1}{3}$ of $\frac{3}{4}$ of 48.', '[]', '12', '12/1', '3/4 of 48 is 36. Then 1/3 of 36 is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 of 48 = 36; 1/3 of 36 = 12.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
