INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1adccb26-d31d-4963-9e44-0a303f55548f', 'BA4.10', 3, 'numeric', 'A fraction of a quantity', 'How much greater is $\frac{5}{6}$ of 48 than $\frac{3}{4}$ of 48?', '[]', '4', '4/1', '5/6 of 48 = 40 and 3/4 of 48 = 36. The difference is 40 - 36 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 - 36 = 4.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
