INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48472456-64fe-41b1-ac77-338919c90ab2', 'BA4.10', 3, 'numeric', 'Fraction stories', 'Ryan spent $\frac{1}{3}$ of his money on a book and $\frac{1}{4}$ of his money on a snack. After that he had 15 dollars left. How many dollars did Ryan have at the start?', '[]', '36', '36/1', 'He spent 1/3 + 1/4 = 4/12 + 3/12 = 7/12 of his money, so 5/12 was left. 5/12 of his money is 15 dollars, so 1/12 is 3 dollars. All 12 twelfths make 36 dollars.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 1/3 - 1/4 = 5/12 is 15 dollars; 1/12 is 3; total 36.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
