INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9ba3597-681c-4d01-af2b-6ce00777fde5', 'BA4.10', 3, 'choice', 'Fraction stories', 'A water tank is $\frac{1}{2}$ full. After 15 liters are added, it is $\frac{5}{6}$ full. How many liters does the full tank hold?', '["$30$","$45$","$90$","$75$"]', '$45$', '45/1', '5/6 - 1/2 = 5/6 - 3/6 = 2/6 = 1/3. So 15 liters is 1/3 of the tank, and the full tank holds 3 x 15 = 45 liters.', 'checked', '{"lint":[],"solve":{"answer":"$45$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 - 1/2 = 1/3 of the tank is 15 L; full = 45.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
