INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('996fd548-622d-4063-8713-4959a04c1b45', 'BA4.10', 3, 'numeric', 'Fraction stories', 'A hiking trail has three parts. The first part is $\frac{1}{2}$ of the trail and the second part is $\frac{1}{5}$ of the trail. The third part is 12 kilometers long. How many kilometers long is the whole trail?', '[]', '40', '40/1', 'The first two parts are 1/2 + 1/5 = 5/10 + 2/10 = 7/10 of the trail, so the third part is 3/10. 3/10 of the trail is 12 km, so 1/10 is 4 km and the whole trail is 40 km.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 1/2 - 1/5 = 3/10 is 12 km; 1/10 is 4; whole 40.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
