INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba6e1c92-ac19-48ac-b0d9-f5c994002a4a', 'BA4.10', 3, 'numeric', 'Fraction stories', 'Mia has 4 ribbons that are each $\frac{5}{6}$ of a meter long. Nate has 3 ribbons that are each $1\frac{1}{8}$ meters long. How many more meters of ribbon does Nate have than Mia?', '[]', '1/24', '1/24', 'Mia: 4 x 5/6 = 20/6 = 10/3 meters. Nate: 3 x 9/8 = 27/8 meters. In twenty-fourths: 27/8 = 81/24 and 10/3 = 80/24. The difference is 1/24 of a meter.', 'checked', '{"lint":[],"solve":{"answer":"1/24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia 4 x 5/6 = 10/3 = 80/24; Nate 3 x 9/8 = 27/8 = 81/24; difference 1/24.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
