INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('884232f2-28cd-4676-aaa8-171eb799d9fb', 'BA4.12', 2, 'choice', 'Probability with number cubes', 'A cube has its faces numbered 1, 1, 2, 3, 3, 3. Each face is equally likely to land up. What is the probability of rolling a 3?', '["$\\frac{1}{3}$","$\\frac{1}{6}$","$\\frac{2}{3}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, 'Three of the six faces show 3. 3/6 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three 3s of 6 faces: 1/2.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
