VALUES ('5b9fda48-714f-4c33-805a-b9c5f6194386', 'BA4.12', 2, 'choice', 'Impossible, certain and likely events', 'Which probability describes an event that is more likely than not, but not certain?', '["$\\frac{1}{4}$","$1$","$\\frac{3}{4}$","$0$"]', '$\frac{3}{4}$', NULL, 'More likely than not means greater than 1/2, and not certain means less than 1. Only 3/4 fits.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 is between 1/2 and 1.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
