INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('750d8acc-1ac0-4a4c-883f-0acf1889e6f5', 'BA4.12', 2, 'choice', 'Working backwards from a probability, and what does not happen', 'Which two probabilities could belong to an event and to that event NOT happening?', '["$\\frac{2}{9}$ and $\\frac{2}{7}$","$\\frac{3}{5}$ and $\\frac{3}{5}$","$\\frac{2}{9}$ and $\\frac{7}{9}$","$\\frac{1}{4}$ and $\\frac{1}{3}$"]', '$\frac{2}{9}$ and $\frac{7}{9}$', NULL, 'An event and its opposite make a whole: 2/9 + 7/9 = 9/9 = 1. The other pairs do not add to 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{9}$ and $\\frac{7}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complementary probabilities sum to 1: 2/9 + 7/9 = 1.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
