INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd70753d-b9f1-47cc-8e40-d5c18b88416d', 'BA4.12', 3, 'numeric', 'Probability as favorable outcomes over equally likely outcomes', 'Tickets numbered 1 to 30 are in a box. One ticket is drawn without looking. What is the probability that its number is a multiple of 5? Write your answer as a fraction.', '[]', '1/5', '6/30', 'The multiples of 5 are 5, 10, 15, 20, 25 and 30: 6 tickets out of 30. 6/30 = 1/5.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,10,...,30: 6 of 30 = 1/5.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
