INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9be04ebf-d053-4b38-966d-906ca01627a1', 'BA4.12', 3, 'choice', 'Probability as favorable outcomes over equally likely outcomes', 'Four games each have equally likely outcomes. Game R wins in 3 of 8 outcomes, game S in 2 of 5, game T in 1 of 3 and game U in 1 of 4. Which game gives the best chance of winning?', '["Game R","Game S","Game T","Game U"]', 'Game S', NULL, 'Use a common denominator of 120: R is 45/120, S is 48/120, T is 40/120, U is 30/120. Game S is greatest.', 'checked', '{"lint":[],"solve":{"answer":"Game S","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375, 2/5 = 0.4, 1/3 = 0.33, 1/4 = 0.25; best S.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
