INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9ee7607-ee46-453a-960e-4bf8e239a16f', 'BA4.12', 3, 'numeric', 'Probability as favorable outcomes over equally likely outcomes', 'Slips numbered 1 to 20 are in a bag. One slip is drawn without looking. What is the probability that its number has the digit 1 in it? Write your answer as a fraction.', '[]', '11/20', '11/20', 'The numbers with a digit 1 are 1, 10, 11, 12, 13, 14, 15, 16, 17, 18 and 19. That is 11 slips out of 20.', 'checked', '{"lint":[],"solve":{"answer":"11/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1, 10-19: 11 of 20.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
