INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('060db042-aade-48b1-99c6-40a179bddc9e', 'BA4.12', 3, 'numeric', 'Probability with spinners', 'A spinner has 20 equal sections numbered 1 to 20. What is the probability that it stops on a number that has the digit 2 in it? Write your answer as a fraction.', '[]', '3/20', '3/20', 'The numbers with a digit 2 are 2, 12 and 20: 3 sections out of 20.', 'checked', '{"lint":[],"solve":{"answer":"3/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 12, 20: 3/20.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
