INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('695bd189-f9c6-485a-9350-0f40d324f5f6', 'BA4.12', 3, 'choice', 'Probability with spinners', 'A spinner has 6 equal sections numbered 1 to 6. Mia says the probability of stopping on a number greater than 2 is 2/6. What is the correct probability?', '["$\\frac{1}{3}$","$\\frac{1}{2}$","$\\frac{5}{6}$","$\\frac{2}{3}$"]', '$\frac{2}{3}$', NULL, 'The numbers greater than 2 are 3, 4, 5 and 6: 4 sections out of 6. 4/6 = 2/3. Mia counted the numbers that are NOT greater than 2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,4,5,6: 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
