INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f21f2b3-a934-4e07-b9a2-54339d79d755', 'BA4.12', 3, 'numeric', 'Probability with spinners', 'A spinner has 10 equal sections numbered 1 to 10. What is the probability that it stops on a factor of 12? Write your answer as a fraction.', '[]', '1/2', '5/10', 'The factors of 12 from 1 to 10 are 1, 2, 3, 4 and 6: 5 sections out of 10. 5/10 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,2,3,4,6: 5/10 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
