INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a7f8e83-8733-4185-a74e-8badd3784408', 'BA4.12', 3, 'choice', 'Probability with spinners', 'Spinner P has 5 equal sections, 3 red and 2 blue. Spinner Q has 8 equal sections, 4 red and 4 blue. Which spinner is more likely to stop on red?', '["Spinner Q","Spinner P","Both are equally likely","Neither can ever stop on red"]', 'Spinner P', NULL, 'P: 3/5 = 6/10. Q: 4/8 = 1/2 = 5/10. 6/10 is greater, so spinner P.', 'checked', '{"lint":[],"solve":{"answer":"Spinner P","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 3/5 = 0.6; Q: 4/8 = 0.5. P.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
