INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc4fb105-87b6-4c70-9125-0b10cd51def6', 'BA4.12', 3, 'numeric', 'Probability with number cubes', 'A cube has six faces. Three are painted red, 2 are painted blue and 1 is painted green. It is rolled once and the color on top is noted. What is the probability that the top is red or green? Write your answer as a fraction.', '[]', '2/3', '4/6', 'Red faces: 3, green faces: 1. Together 4 of 6 faces. 4/6 = 2/3.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 1 = 4 of 6: 2/3.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
