INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f0f3d12-c105-47be-9507-00dc68cdcbc3', 'BA4.12', 3, 'numeric', 'Probability with number cubes', 'A fair number cube is rolled once. What is the probability that the square of the number rolled is less than 20? Write your answer as a fraction.', '[]', '2/3', '4/6', '1x1 = 1, 2x2 = 4, 3x3 = 9, 4x4 = 16 are all less than 20, but 5x5 = 25 and 6x6 = 36 are not. So 4 of 6 faces work: 2/3.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,4,9,16 < 20 from 1-4: 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
