VALUES ('383135c2-d1a4-41c9-a089-e1ebc4ea97be', 'BA4.12', 3, 'choice', 'Probability with number cubes', 'Which event is the LEAST likely when a fair number cube is rolled once?', '["Rolling an even number","Rolling a number greater than 2","Rolling a number less than 2","Rolling a number that is not 6"]', 'Rolling a number less than 2', NULL, 'Less than 2 is only a 1: probability 1/6. The others are 3/6, 4/6 and 5/6.', 'checked', '{"lint":[],"solve":{"answer":"Rolling a number less than 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6, 1/6, 4/6, 3/6; least is less than 2.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
