INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbdc30e4-5674-43d8-8343-ef92a12297d7', 'BA4.12', 3, 'choice', 'Impossible, certain and likely events', 'Jess says, "The probability of my event is 5/4." Why must she be wrong?', '["A probability must have a numerator of 1.","A probability can never be a fraction.","A probability can never be greater than 1.","A probability must have an even denominator."]', 'A probability can never be greater than 1.', NULL, 'An event cannot happen more often than every time, so a probability is never more than 1. And 5/4 is greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"A probability can never be greater than 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/4 > 1, impossible for a probability.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
