INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4b6b56c-2f5c-4d40-b89f-708a985b01f8', 'BA4.12', 3, 'numeric', 'Working backwards from a probability, and what does not happen', 'A box has 3 red cubes and 7 white cubes. How many white cubes must be taken out so that the probability of picking a red cube is exactly 1/2? Write your answer as a number.', '[]', '4', '7-3', 'For a probability of 1/2 there must be as many white cubes as red cubes: 3. So take out 7 - 3 = 4 white cubes.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/(10 - x) = 1/2: 10 - x = 6, x = 4. Check 3/6.","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
