INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ee139c2-a58b-4a7b-9121-d611321fc333', 'BA4.12', 3, 'choice', 'Working backwards from a probability, and what does not happen', 'A bag has red, blue and green marbles. The probability of red is 1/4, the probability of blue is 1/3, and there are 10 green marbles. How many marbles are in the bag?', '["$24$","$30$","$40$","$12$"]', '$24$', '24', 'Probability of green: 1 - 1/4 - 1/3 = 12/12 - 3/12 - 4/12 = 5/12. So 10 marbles are 5/12 of the bag; 1/12 is 2 marbles, and the whole bag is 24.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Green = 1 - 1/4 - 1/3 = 5/12; 10 = 5/12 of total, total 24 (6 red, 8 blue, 10 green).","run_id":"claude-code","at":"2026-10-19T01:28:36.864Z"}}', 'ai', NULL, NULL)
