INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6fff580-911f-4702-8ba2-8f011494f664', 'BA5.01', 2, 'choice', 'Volume of a box', 'Box P is 4 cm by 5 cm by 6 cm. Box Q is 3 cm by 7 cm by 5 cm. Which statement is true?', '["Box Q holds 15 cubic centimeters more than Box P.","The two boxes hold the same amount.","Box P holds 5 cubic centimeters more than Box Q.","Box P holds 15 cubic centimeters more than Box Q."]', 'Box P holds 15 cubic centimeters more than Box Q.', NULL, 'Box P: $4 \times 5 \times 6 = 120$. Box Q: $3 \times 7 \times 5 = 105$. The difference is $120 - 105 = 15$ and Box P is bigger.', 'checked', '{"lint":[],"solve":{"answer":"Box P holds 15 cubic centimeters more than Box Q.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 4x5x6 = 120; Q = 3x7x5 = 105; P holds 15 more.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
