INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fe56c6f-63dd-4625-a7eb-19ae6972cb9e', 'BA5.01', 2, 'numeric', 'Small cubes in a larger cube or box', 'Tom builds a cube 4 small cubes long, 4 wide and 4 tall. He removes the whole top layer. How many small cubes are left?', '[]', '48', '64-16', 'The cube had $4 \times 4 \times 4 = 64$ cubes and the top layer has 16. $64 - 16 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 - 16 = 48.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
