INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f951cb9b-4f51-4068-91a2-ea7014583be7', 'BA5.01', 2, 'choice', 'Small cubes in a larger cube or box', 'How many more small cubes are needed to turn a cube that is 3 cubes on each edge into a cube that is 4 cubes on each edge?', '["27","37","16","7"]', '37', '64-27', '$4 \times 4 \times 4 = 64$ and $3 \times 3 \times 3 = 27$. The extra cubes are $64 - 27 = 37$.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 - 27 = 37.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
