VALUES ('9599cb16-1b0f-4d55-9ed4-7b661fd1ffca', 'BA5.01', 2, 'numeric', 'Small cubes in a larger cube or box', 'Each layer of a box holds 24 cubes. The box is exactly full with 120 cubes. How many layers tall is the box?', '[]', '5', '120/24', '$120 \div 24 = 5$ layers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 / 24 = 5.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
