INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6979e13-66bd-4eb1-9b0a-1a9655ca9cb1', 'BA5.01', 3, 'choice', 'Faces, edges and vertices of solids', 'A prism has 21 edges. How many faces does it have?', '["9","7","10","12"]', '9', '2+21/3', 'A prism with an $n$-sided end has $3n$ edges. $3n = 21$ gives $n = 7$. It has 2 ends and 7 side rectangles: $2 + 7 = 9$ faces.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prism with n-gon ends has 3n edges; n = 7; faces n + 2 = 9.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
