INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74bb22e1-193c-481f-9edb-af9bc03afe13', 'BA5.01', 3, 'numeric', 'Faces, edges and vertices of solids', 'A pyramid has 14 edges. How many vertices does it have?', '[]', '8', '14/2+1', 'A pyramid with an $n$-sided base has $2n$ edges (n around the base and n up the sides). $2n = 14$ gives $n = 7$. Vertices: $7 + 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pyramid has 2n edges; n = 7; vertices n + 1 = 8.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
