INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c7d66ec-2ec5-4289-8357-c6e3770c5d5f', 'BA5.01', 3, 'numeric', 'Faces, edges and vertices of solids', 'A prism and a pyramid have bases with the same number of sides. The prism has 6 more edges than the pyramid. How many sides does the base have?', '[]', '6', '6', 'If the base has $n$ sides, the prism has $3n$ edges and the pyramid has $2n$. The difference is $n$, so $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prism 3n, pyramid 2n; difference n = 6.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
