INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdae2ae5-9c12-466d-9f93-bcf3e99611b5', 'BA5.01', 3, 'choice', 'Faces, edges and vertices of solids', 'A square pyramid is glued by its square base onto one face of a cube, and the base is exactly the size of that face. How many faces does the new solid have?', '["11","9","10","8"]', '9', '5+4', 'The cube has 6 faces but the glued face is hidden, leaving 5. The pyramid adds its 4 triangles: $5 + 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 6 faces, one covered: 5 remain; plus 4 triangles (slanted, not coplanar with cube faces) = 9.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
