INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d0f0b7d-7065-4d4e-969a-c56ea71a7cef', 'BA5.01', 3, 'numeric', 'Faces, edges and vertices of solids', 'A toy is a cube with a square pyramid on top. The pyramid''s base is exactly the cube''s top face. How many edges does the toy have on its surface?', '[]', '16', '12+4', 'The cube has 12 edges (the top four are also the pyramid''s base edges). The pyramid adds 4 edges from the base corners to its tip: $12 + 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 12 edges (the 4 top edges stay edges, as the slanted triangles meet the cube sides at an angle) + 4 slant edges = 16.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
