INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6abac5c9-568d-489c-abdf-b991ab9991f8', 'BA5.01', 3, 'numeric', 'Faces, edges and vertices of solids', 'A pyramid has 10 vertices. A prism has ends with the same shape as the pyramid''s base. How many edges does the prism have?', '[]', '27', '3*(10-1)', 'The pyramid has $10 - 1 = 9$ base corners, so the base has 9 sides. A prism with 9-sided ends has $3 \times 9 = 27$ edges.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 vertices = base of 9 sides + apex. Prism with 9-gon ends has 27 edges.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
