INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7842620c-080f-4d72-b6f7-4ef18938215e', 'BA5.01', 3, 'choice', 'Faces, edges and vertices of solids', 'Which of these solids has the same number of faces as vertices?', '["a cube","a triangular prism","a square pyramid","a pentagonal prism"]', 'a square pyramid', NULL, 'A square pyramid has 5 faces and 5 vertices. A cube has 6 and 8, a triangular prism 5 and 6, and a pentagonal prism 7 and 10.', 'checked', '{"lint":[],"solve":{"answer":"a square pyramid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square pyramid 5 faces, 5 vertices. Others: pentagonal prism 7/10, triangular prism 5/6, cube 6/8.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
