INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c9b0147-770a-48d0-837a-ecef77c608d0', 'BA5.01', 3, 'numeric', 'Faces, edges and vertices of solids', 'Every edge of a pentagonal prism is 3 cm long. A wire frame is made from all of its edges. How many centimeters of wire are needed?', '[]', '45', '15*3', 'A pentagonal prism has $5 + 5 + 5 = 15$ edges, so $15 \times 3 = 45$ cm of wire.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pentagonal prism has 15 edges; 15 x 3 = 45.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
