INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc5ac5c6-fb0f-4885-9c0d-cf3a35b1dda7', 'BA5.01', 3, 'numeric', 'Volume of a box', 'Two boxes are joined face to face with no overlap. One is 4 cm by 3 cm by 2 cm and the other is 2 cm by 3 cm by 5 cm. What is the total volume of the joined solid in cubic centimeters?', '[]', '54', '4*3*2+2*3*5', '$4 \times 3 \times 2 = 24$ and $2 \times 3 \times 5 = 30$. Together $24 + 30 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 + 30 = 54.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
