INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cd52bf1-bdc1-4109-881d-ee856058f71b', 'BA5.01', 3, 'numeric', 'Volume of a box', 'The three edges of a box are three whole numbers in a row, such as 7, 8 and 9. The volume of the box is 120 cubic centimeters. How long is the longest edge, in centimeters?', '[]', '6', '6', 'Try $4 \times 5 \times 6 = 120$. The longest edge is 6 cm. (Smaller sets such as $3 \times 4 \times 5 = 60$ are too small.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 5 x 6 = 120; longest 6.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
