INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3464a6db-38e4-4904-89a2-618d277a39c0', 'BA5.01', 3, 'choice', 'Volume of a box', 'A pool is 10 m long, 6 m wide and 2 m deep and is full of water. A pump removes 5 cubic meters of water each minute. How many minutes does it take to empty the pool?', '["12","24","48","120"]', '24', '10*6*2/5', 'The pool holds $10 \times 6 \times 2 = 120$ cubic meters. $120 \div 5 = 24$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 6 x 2 = 120; 120 / 5 = 24.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
