INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06edcd5c-3d41-4280-a7dd-57cacce6b958', 'BA5.01', 3, 'choice', 'Volume of a box', 'A solid box is 8 cm by 6 cm by 5 cm. A cube-shaped hole 2 cm on each edge is cut out of its middle, leaving the rest of the box. How many cubic centimeters does the remaining solid have?', '["240","236","232","224"]', '232', '8*6*5-2*2*2', 'The whole box is $8 \times 6 \times 5 = 240$. The hole is $2 \times 2 \times 2 = 8$. $240 - 8 = 232$.', 'checked', '{"lint":[],"solve":{"answer":"232","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 6 x 5 = 240; minus 8 = 232.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
