INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8e96632-e56f-4596-b46f-3321622116bc', 'BA5.01', 3, 'choice', 'Volume of a box', 'A tank has a bottom of 30 cm by 20 cm. It holds water 12 cm deep. More water is poured in until it is 18 cm deep. How many cubic centimeters of water were added?', '["600","7200","10800","3600"]', '3600', '30*20*(18-12)', 'The water rose by $18 - 12 = 6$ cm over a $30 \times 20 = 600$ square centimeter bottom: $600 \times 6 = 3600$.', 'checked', '{"lint":[],"solve":{"answer":"3600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 20 x 6 = 3600.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed26fc84-5b15-4bf1-8401-6f2ba5defca5', 'BA5.01', 3, 'choice', 'Volume of a box', 'A box has a volume of 480 cubic centimeters. Its length is 12 cm and the area of its bottom is 96 square centimeters. What is the sum of its width and its height, in centimeters?', '["8","13","5","17"]', '13', '96/12+480/96', 'Width $= 96 \div 12 = 8$. Height $= 480 \div 96 = 5$. The sum is $8 + 5 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 480 / 96 = 5; width = 96 / 12 = 8; 8 + 5 = 13.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a58fecd9-4d6f-4c82-b154-a85d41812eea', 'BA5.01', 3, 'numeric', 'Volume of a box', 'Box A has a bottom of 6 cm by 4 cm and a volume of 96 cubic centimeters. Box B has the same volume and a bottom of 8 cm by 2 cm. How many centimeters taller is Box B than Box A?', '[]', '2', '96/16-96/24', 'Box A: height $96 \div 24 = 4$. Box B: height $96 \div 16 = 6$. Box B is $6 - 4 = 2$ cm taller.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 96/24 = 4; B: 96/16 = 6; difference 2.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf8864af-2925-49be-91df-fede91c8008d', 'BA5.01', 3, 'choice', 'Surface area of a box', 'Every edge of a cube is made 3 times as long. How many times as large does the surface area become?', '["3","6","9","27"]', '9', '9', 'A cube with edge 1 has surface area 6. With edge 3 it is $6 \times 9 = 54$. And $54 \div 6 = 9$. Each face is 3 times as long and 3 times as wide.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area scales by 3 x 3 = 9.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbb2c104-2813-4678-aa61-b978eb6d0e47', 'BA5.01', 3, 'choice', 'Surface area of a box', 'A box with a square bottom 3 cm by 3 cm has a surface area of 78 square centimeters. How tall is the box in centimeters?', '["15","4","6","5"]', '5', '(78-18)/4/3', 'The top and bottom are $2 \times 9 = 18$. The four sides must be $78 - 18 = 60$, so each is 15. A side is 3 cm wide, so the height is $15 \div 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 9 = 18; 78 - 18 = 60 for four sides of 3h; 12h = 60; h = 5.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d804eda1-bccd-4704-a420-dfe2cb7a5f5a', 'BA5.01', 3, 'numeric', 'Surface area of a box', 'Two cubes with 2 cm edges are put side by side so they touch face to face and form one box that is 2 cm by 2 cm by 4 cm. How many fewer square centimeters is the surface area of the box than the total surface area of the two separate cubes?', '[]', '8', '48-40', 'Two separate cubes: $2 \times 24 = 48$. The box: $2 \times (4 + 8 + 8) = 40$. The difference is $8$ (the two touching faces, $4 + 4$, are hidden).', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Separate: 2 x 24 = 48. Box: 2(4 + 8 + 8) = 40. 48 - 40 = 8.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9ce7943-2c67-4e5b-b3ed-048591e10c0b', 'BA5.01', 3, 'choice', 'Surface area of a box', 'A cube with 4 cm edges has a small 1 cm by 1 cm by 1 cm cube cut away from one of its corners. How does the surface area of the new solid compare with the surface area of the original cube?', '["It stays the same.","It is 3 square centimeters smaller.","It is 3 square centimeters larger.","It is 1 square centimeter smaller."]', 'It stays the same.', NULL, 'Cutting away the corner removes 3 small squares from the outside, but it uncovers 3 new small squares inside the notch. The surface area is unchanged.', 'checked', '{"lint":[],"solve":{"answer":"It stays the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Removing a corner cube removes 3 unit squares and exposes 3 new ones: unchanged.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a239134-3bcb-443b-8df5-f2388ba080f2', 'BA5.01', 3, 'choice', 'Surface area of a box', 'Three faces of a box that meet at one corner have areas of 12, 15 and 20 square centimeters. What is the surface area of the whole box in square centimeters?', '["47","60","94","188"]', '94', '2*(12+15+20)', 'The other three faces match these three, so the total is $2 \times (12 + 15 + 20) = 2 \times 47 = 94$.', 'checked', '{"lint":[],"solve":{"answer":"94","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12 + 15 + 20) = 94.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
