INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d367cef9-0ea4-4327-82e2-17cdbc9a3004', 'BA5.01', 3, 'numeric', 'Surface area of a box', 'A 2 cm cube has a 1 cm cube glued flat onto the middle of one face. What is the surface area of the new solid in square centimeters?', '[]', '28', '24+4', 'The big cube has $6 \times 4 = 24$. The small cube covers 1 square centimeter of that but shows 4 side faces and a top: $24 - 1 + 4 + 1 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 - 1 covered + 5 new faces of the small cube = 28.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abdded0c-4809-432c-94da-e249fc664f11', 'BA5.01', 3, 'choice', 'Surface area of a box', 'Four boxes each have a volume of 24 cubic centimeters. Which of them has the greatest surface area?', '["2 cm by 3 cm by 4 cm","2 cm by 2 cm by 6 cm","1 cm by 4 cm by 6 cm","1 cm by 1 cm by 24 cm"]', '1 cm by 1 cm by 24 cm', NULL, '1 by 1 by 24: $2(1 + 24 + 24) = 98$. 2 by 3 by 4: 52. 2 by 2 by 6: 56. 1 by 4 by 6: 68. The long thin box has the most.', 'checked', '{"lint":[],"solve":{"answer":"1 cm by 1 cm by 24 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1x1x24: 98; 2x3x4: 52; 1x4x6: 68; 2x2x6: 56. Greatest 1x1x24.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d346ff2a-80dd-4665-8ee8-63117ec96e87', 'BA5.01', 3, 'numeric', 'Surface area of a box', 'A closed box is 5 cm by 4 cm by h cm and its surface area is 94 square centimeters. What is h?', '[]', '3', '(94/2-20)/9', '$2(20 + 5h + 4h) = 94$, so $20 + 9h = 47$, so $9h = 27$ and $h = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(20 + 5h + 4h) = 94; 20 + 9h = 47; h = 3.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d50426-6d13-4d39-9b80-1bdb11a09697', 'BA5.01', 3, 'choice', 'Surface area of a box', 'A room is 5 m long, 4 m wide and 3 m high. Sam paints the four walls and the ceiling but not the floor. How many square meters does he paint?', '["74","54","94","59"]', '74', '2*5*3+2*4*3+5*4', 'Walls: $2 \times (5 \times 3) + 2 \times (4 \times 3) = 30 + 24 = 54$. Ceiling: $5 \times 4 = 20$. Total $54 + 20 = 74$.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ceiling 20; walls 2(5x3) + 2(4x3) = 54; total 74.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2769a230-28ba-40cc-84a6-20df96367c65', 'BA5.01', 3, 'choice', 'Small cubes in a larger cube or box', 'A 4 by 4 by 4 cube made of small cubes has its whole outside painted. How many small cubes have paint on exactly one face?', '["16","24","12","32"]', '24', '6*2*2', 'Each face has a middle $2 \times 2 = 4$ cubes with exactly one painted face. With 6 faces, $6 \times 4 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each face has (4-2)^2 = 4 such cubes; 6 x 4 = 24.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2a44d68-ee9e-4122-8917-22b33c0a09e5', 'BA5.01', 3, 'numeric', 'Small cubes in a larger cube or box', 'A 5 by 5 by 5 cube made of small cubes has its whole outside painted. How many small cubes have paint on exactly two faces?', '[]', '36', '12*3', 'Those cubes sit along the 12 edges, not counting the corners. Each edge has $5 - 2 = 3$ of them. $12 \times 3 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 edges x (5-2) = 36.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
