INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd8a43a8-c9a0-4e99-a685-37adaf98917d', 'BA5.01', 3, 'numeric', 'Small cubes in a larger cube or box', 'A cube with edges of 10 cm is painted all over, then cut into cubes with edges of 2 cm. How many of the small cubes have paint on exactly one face?', '[]', '54', '6*3*3', 'Each edge makes $10 \div 2 = 5$ small cubes. On each face the cubes with just one painted face form a $3 \times 3$ middle: 9. For 6 faces, $6 \times 9 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 small cubes per edge; per face (5-2)^2 = 9; 6 x 9 = 54.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
