INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e7333a4-01a6-43cc-93e7-59b3f09672d3', 'BA5.01', 3, 'choice', 'Small cubes in a larger cube or box', 'A solid cube is made from small cubes, 6 along each edge. Dan removes every small cube that touches the outside of the big cube. How many small cubes does he remove?', '["152","64","216","88"]', '152', '216-64', 'The cube has $6 \times 6 \times 6 = 216$ cubes. What is left is a $4 \times 4 \times 4 = 64$ cube. He removes $216 - 64 = 152$.', 'checked', '{"lint":[],"solve":{"answer":"152","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"216 - 4^3 = 216 - 64 = 152.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
