INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52865925-dd10-4fe2-90e3-8b2d039ebbc9', 'BA5.01', 3, 'numeric', 'Small cubes in a larger cube or box', 'A solid cube is made from small cubes. Exactly 98 of the small cubes touch the outside of the big cube. How many small cubes are along each edge of the big cube?', '[]', '5', '5', 'Try 5: the cube has 125 cubes, and the inside is $3 \times 3 \times 3 = 27$. $125 - 27 = 98$ touch the outside. So 5 along each edge.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^3 - (n-2)^3 = 98. n = 5: 125 - 27 = 98.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ffe8c13-ebe4-4fea-b4b5-bf3c0697216b', 'BA5.01', 3, 'choice', 'Small cubes in a larger cube or box', 'Ann stacks 1 cm cubes to make a box 4 cm long, 3 cm wide and 2 cm tall, then paints its whole outside, including the bottom. How many small cubes have paint on exactly two faces?', '["8","12","4","16"]', '12', '12', 'A cube has two painted faces when it is at an end in exactly two of the three directions. Every cube is at an end in the height direction (the box is only 2 tall). So it must be at an end in exactly one of the other two. Cubes at an end of the length but in the middle of the width: $2 \times 1 = 2$. Middle of the length (2) and end of the width (2): $2 \times 2 = 4$. That is 6 positions, times 2 heights = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height 2 so every cube is on top or bottom. Corners: 8 (three faces). Along the 4 length-4 edges: 2 each = 8; along the 4 width-3 edges: 1 each = 4; vertical edges have only corners. Two faces: 12.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
