INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76ed3477-e424-4aa9-b5ed-b1942e599405', 'BA5.02', 3, 'choice', 'Adding and subtracting integers', 'The sum of two integers is $-3$. When the smaller is subtracted from the larger the result is 11. What is the smaller integer?', '["4","-7","-4","7"]', '-7', '-3-4', 'Let the larger be $a$ and the smaller $b$: $a + b = -3$ and $a - b = 11$. Adding gives $2a = 8$, so $a = 4$. Then $b = -3 - 4 = -7$. Check: $4 - (-7) = 11$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L + S = -3, L - S = 11; L = 4, S = -7.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
