VALUES ('b7c0899f-8d84-40e7-8517-79ac28aafd42', 'BA5.02', 3, 'choice', 'Adding and subtracting integers', 'Which of these has the greatest value?', '["$-8 - (-3) - (-6)$","$-8 + 3 - 6$","$-8 - 3 + 6$","$8 - (-3) - 6$"]', '$8 - (-3) - 6$', NULL, '$8 - (-3) - 6 = 5$. The others are $1$, $-11$ and $-5$.', 'checked', '{"lint":[],"solve":{"answer":"$8 - (-3) - 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8+3-6 = 5; -8+3+6 = 1; -8+3-6 = -11; -8-3+6 = -5. Greatest 5.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
