INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('992060cf-b584-46c9-ac2b-0ddb7fa2921d', 'BA5.02', 3, 'choice', 'Multiplying and dividing integers', 'The product $a \times b$ is negative and the product $b \times c$ is positive. Which statement must be true?', '["$a \\times c$ is negative.","$a \\times c$ is positive.","$a$ is positive.","$b$ is positive."]', '$a \times c$ is negative.', NULL, '$a$ and $b$ have different signs, and $b$ and $c$ have the same sign. So $a$ and $c$ have different signs, and $a \times c$ is negative. The other statements could be false.', 'checked', '{"lint":[],"solve":{"answer":"$a \\times c$ is negative.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ab < 0: a, b opposite signs (nonzero). bc > 0: b, c same sign. So a and c have opposite signs: ac negative. Signs of a and b individually are not determined.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a65e06da-86e2-48f3-bfe9-3c19e71105a3', 'BA5.02', 3, 'numeric', 'Order of operations with integers', 'What is $4 - 3 \times (2 - 6) + (-8) \div 2$?', '[]', '12', '4-3*(2-6)+(-8)/2', 'Parentheses: $2 - 6 = -4$. Multiply and divide: $3 \times (-4) = -12$ and $(-8) \div 2 = -4$. Then $4 - (-12) + (-4) = 4 + 12 - 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 - 6 = -4; 3 x -4 = -12; -8/2 = -4; 4 + 12 - 4 = 12.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
