INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4629f61-f597-4329-a2cb-e3ef5cd53c3d', 'BA5.02', 3, 'choice', 'Order of operations with integers', 'Which expression is equal to $-20$?', '["$-2 + 7 \\times (-4)$","$(-2 + 7) \\times (-4)$","$(-2 + 7) \\times 4$","$-2 \\times 7 + 4$"]', '$(-2 + 7) \times (-4)$', NULL, '$(-2 + 7) \times (-4) = 5 \times (-4) = -20$. The others are $-30$, $20$ and $-10$.', 'checked', '{"lint":[],"solve":{"answer":"$(-2 + 7) \\times (-4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x -4 = -20; 5 x 4 = 20; -2 - 28 = -30; -14 + 4 = -10.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
