INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6940194c-a164-4edc-86a3-44143e39400a', 'BA5.02', 3, 'numeric', 'Absolute value', 'How many pairs of integers $(x, y)$ have $|x| + |y| = 3$? Count $(2, -1)$ and $(-1, 2)$ as different pairs.', '[]', '12', '2+4+4+2', '$|x| = 0$: $y = 3$ or $-3$, 2 pairs. $|x| = 1$: $x$ has 2 choices and $|y| = 2$ gives 2, so 4 pairs. $|x| = 2$: 4 pairs likewise. $|x| = 3$: $x$ has 2 choices and $y = 0$, 2 pairs. Total $2 + 4 + 4 + 2 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(+-3,0),(0,+-3): 4; (+-1,+-2): 4; (+-2,+-1): 4. Total 12.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
