VALUES ('48a705c8-5bdc-4c88-9a93-4e938a813c87', 'BA5.03', 2, 'choice', 'Evaluating an expression', 'If $x = 4$ and $y = 3$, which expression has the greatest value?', '["$2x + y$","$5x - 2y$","$x + 3y$","$4y - x$"]', '$5x - 2y$', NULL, 'The values are: $2x + y = 11$, $x + 3y = 13$, $4y - x = 8$ and $5x - 2y = 20 - 6 = 14$. The greatest is $5x - 2y$.', 'checked', '{"lint":[],"solve":{"answer":"$5x - 2y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4y-x = 12-4 = 8; 2x+y = 11; x+3y = 13; 5x-2y = 20-6 = 14. Greatest is 14.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
