VALUES ('3effd3e3-599c-488b-95ba-27fbcc0ecc1d', 'BA5.03', 2, 'numeric', 'Equations from stories', 'Three friends share the cost of a gift equally. Each friend also pays 2 dollars for a card. Each friend paid 9 dollars in all. How many dollars did the gift cost?', '[]', '21', '3*(9-2)', 'Each friend paid $9 - 2 = 7$ dollars toward the gift. For 3 friends, $3 \times 7 = 21$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g/3 + 2 = 9, g/3 = 7, g = 21.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d422fae-f121-46fa-b029-9a6dcc2f200a', 'BA5.03', 3, 'numeric', 'Evaluating an expression', 'If $3x + 2 = 20$, what is the value of $6x + 5$?', '[]', '41', '6*((20-2)/3)+5', '$3x = 18$, so $x = 6$. Then $6x + 5 = 36 + 5 = 41$. (Or: $6x$ is twice $3x$, which is 36.)', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 18, x = 6; 6x + 5 = 36 + 5 = 41.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed06b173-603a-423d-b648-062bc3014561', 'BA5.03', 3, 'numeric', 'Evaluating an expression', 'Find the value of $\frac{n + 4}{2} \times (n - 4)$ when $n = 6$.', '[]', '10', '(6+4)/2*(6-4)', '$\frac{6 + 4}{2} = 5$ and $6 - 4 = 2$. Then $5 \times 2 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6+4)/2 * (6-4) = 5 * 2 = 10.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ffbf7b-89d4-4b0c-a614-55649ea70aef', 'BA5.03', 3, 'choice', 'Evaluating an expression', 'Which expression has the greatest value when $x = 5$?', '["$5x - 3$","$3x + 4$","$2(x + 4)$","$6x - 9$"]', '$5x - 3$', NULL, 'The values are: $3x + 4 = 19$, $5x - 3 = 22$, $2(x + 4) = 18$ and $6x - 9 = 21$. The greatest is $5x - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$5x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=5: 5x-3 = 22; 6x-9 = 21; 2(x+4) = 18; 3x+4 = 19. Greatest 22.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aae78c82-b80c-4ccf-96f1-0f53e6c0d288', 'BA5.03', 3, 'numeric', 'Evaluating an expression', 'Renting a bike for $h$ hours costs $5 + 3h$ dollars. A coupon takes 2 dollars off the cost. How many dollars does a 7-hour rental cost with the coupon?', '[]', '24', '5+3*7-2', '$5 + 3 \times 7 = 26$ dollars. With the coupon, $26 - 2 = 24$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3*7 = 26, minus 2 = 24.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
