INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56fa2b47-4794-4ccb-81f7-ae16529b0941', 'BA5.03', 3, 'choice', 'Evaluating an expression', 'What is the value of $4(a + b) - 3a$ when $a = 2$ and $b = 7$?', '["36","9","33","30"]', '30', '4*(2+7)-3*2', '$4 \times (2 + 7) = 36$ and $3 \times 2 = 6$. Then $36 - 6 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2+7) - 3*2 = 36 - 6 = 30.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
