INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d2de7a7-56f0-4d96-b8a3-88905cf2d67a', 'BA5.03', 3, 'choice', 'Combining like terms', 'Simplify $4(x + 3) - 2x + 5$.', '["$2x + 8$","$6x + 17$","$2x + 17$","$2x + 7$"]', '$2x + 17$', NULL, '$4(x + 3) = 4x + 12$. Then $4x + 12 - 2x + 5 = 2x + 17$.', 'checked', '{"lint":[],"solve":{"answer":"$2x + 17$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 12 - 2x + 5 = 2x + 17.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
