INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7628cf08-c0d7-48b3-aef4-72bcbb9c484b', 'BA5.03', 3, 'numeric', 'Combining like terms', 'After simplifying, $5(a + 2) + 3(a - 1)$ becomes $8a + ?$. What number is the ?', '[]', '7', '10-3', '$5(a + 2) = 5a + 10$ and $3(a - 1) = 3a - 3$. Together: $8a + 10 - 3 = 8a + 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a + 10 + 3a - 3 = 8a + 7.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
