INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54108b97-c2f1-46a1-9df8-cc44f35d961f', 'BA5.03', 3, 'choice', 'Combining like terms', 'Which expression is equal to $x + 2x + 3x + 4$?', '["$10x$","$6x + 4$","$6x^2 + 4$","$x + 9$"]', '$6x + 4$', NULL, '$x + 2x + 3x = 6x$, and the 4 is a plain number that stays: $6x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 6x, plus 4.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
