INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2916dd79-b5a9-4159-8c06-d032a0f5a766', 'BA5.03', 3, 'numeric', 'Combining like terms', 'A triangle has sides of $x + 3$, $2x$ and $3x - 1$ centimeters. Its perimeter is $6x + ?$ centimeters. What number is the ?', '[]', '2', '3-1', '$x + 2x + 3x = 6x$ and $3 - 1 = 2$. The perimeter is $6x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3) + 2x + (3x-1) = 6x + 2.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
