INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05693296-2a8e-446c-9b94-31c262953ff4', 'BA5.03', 3, 'numeric', 'Combining like terms', 'The expression $7n - 2(n - 4) + 3$ equals $5n + ?$. What number is the ?', '[]', '11', '8+3', '$2(n - 4) = 2n - 8$, and taking it away gives $7n - 2n + 8 + 3 = 5n + 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7n - 2n + 8 + 3 = 5n + 11.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
