INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b3d9b6f-967e-4796-97b2-4409778b5bab', 'BA5.03', 3, 'choice', 'Combining like terms', 'Which statement is true for every value of $x$?', '["$3(x + 1) = 3x + 3$","$2x + 3x = 5x^2$","$4x - x = 4$","$5 - 2x = 3x$"]', '$3(x + 1) = 3x + 3$', NULL, 'The 3 multiplies both terms in $3(x + 1)$, so it equals $3x + 3$ whatever $x$ is. The others hold for only some values of $x$, or never.', 'checked', '{"lint":[],"solve":{"answer":"$3(x + 1) = 3x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+1) = 3x + 3 always. 2x+3x = 5x, not 5x^2 (true only at x = 0, 1); 5-2x = 3x only at x = 1; 4x - x = 3x only equals 4 at x = 4/3.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f574daf-955a-40fc-92ac-cecfd33a64d0', 'BA5.03', 3, 'numeric', 'The distributive property', 'Use the distributive property to find $17 \times 6 + 17 \times 4 - 17$.', '[]', '153', '17*(6+4-1)', 'There are 6 + 4 = 10 seventeens, and one is taken away, so 9 seventeens: $17 \times 9 = 153$.', 'checked', '{"lint":[],"solve":{"answer":"153","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17(6 + 4 - 1) = 17*9 = 153.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
