INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5a52fc8-b308-48d4-8589-a7c622e08061', 'BA5.03', 3, 'choice', 'The distributive property', 'Which expression is equal to $12x - 18$?', '["$6(2x - 18)$","$3(4x - 18)$","$12(x - 18)$","$6(2x - 3)$"]', '$6(2x - 3)$', NULL, '$12x - 18 = 6 \times 2x - 6 \times 3 = 6(2x - 3)$. In the others, a term would multiply out to something different from 18.', 'checked', '{"lint":[],"solve":{"answer":"$6(2x - 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(2x-3) = 12x - 18. Others: 12x-216, 12x-108, 12x-54.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
