VALUES ('801b7785-2dde-45d0-886b-73c7a825469f', 'BA5.03', 3, 'choice', 'The distributive property', 'Which expression is equal to $2(3x - 4) - 5(x - 1)$?', '["$x - 13$","$x + 3$","$x - 3$","$11x - 3$"]', '$x - 3$', NULL, '$2(3x - 4) = 6x - 8$ and $5(x - 1) = 5x - 5$. Then $6x - 8 - 5x + 5 = x - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 8 - 5x + 5 = x - 3.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
