VALUES ('3c531cd6-6df1-45ea-a23c-526e0661d82e', 'BA5.03', 3, 'choice', 'The distributive property', 'Which expression is equal to $5(2x + 3) - 4(x + 2)$?', '["$6x + 13$","$6x + 7$","$6x + 23$","$14x + 7$"]', '$6x + 7$', NULL, '$5(2x + 3) = 10x + 15$ and $4(x + 2) = 4x + 8$. Then $10x + 15 - 4x - 8 = 6x + 7$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x + 15 - 4x - 8 = 6x + 7.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
