VALUES ('0c83511b-3976-4903-9c21-db7131f0bd6d', 'BA5.03', 3, 'numeric', 'Solving two-step equations', 'Solve: $5y + 2(y - 3) = 36$.', '[]', '6', '(36+6)/7', '$2(y - 3) = 2y - 6$, so $7y - 6 = 36$. Add 6: $7y = 42$. Divide by 7: $y = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5y + 2y - 6 = 36, 7y = 42, y = 6.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
