INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9d12550-03e0-46d5-a074-77f5a53446da', 'BA5.03', 3, 'numeric', 'Equations from stories', 'A number is doubled, then 9 is added, and the result is divided by 3. The final answer is 7. What was the number?', '[]', '6', '(7*3-9)/2', 'Work backwards: $7 \times 3 = 21$, then $21 - 9 = 12$, then $12 \div 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2n + 9)/3 = 7, 2n + 9 = 21, n = 6.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
