INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a25fa5e0-82c8-41ee-9f36-b7aa9fa8b659', 'BA5.03', 3, 'numeric', 'Equations from stories', 'A repair visit costs a 25-dollar fee plus 20 dollars each hour. A 5-dollar coupon is taken off the bill. Jess paid 100 dollars. For how many hours was the repair?', '[]', '4', '(100+5-25)/20', 'Before the coupon the bill was $100 + 5 = 105$. Take off the fee: $105 - 25 = 80$. Then $80 \div 20 = 4$ hours.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + 20h - 5 = 100, 20h = 80, h = 4.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
