INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85900fc6-392e-4983-834e-105b53dea617', 'BA5.03', 3, 'choice', 'Equations from stories', 'The sum of three whole numbers that come one after another (such as 4, 5, 6) is 66. What is the largest of the three?', '["22","23","21","24"]', '23', '(66-3)/3+2', 'If the smallest is $n$, then $n + (n + 1) + (n + 2) = 66$, so $3n + 3 = 66$ and $n = 21$. The numbers are 21, 22, 23, and the largest is 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + (n+1) + (n+2) = 66, 3n = 63, n = 21; numbers 21, 22, 23; largest 23.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
