VALUES ('03ab05f0-8724-4086-81dc-16fa81cea17a', 'BA5.04', 2, 'choice', 'Finding the range', 'What is the range of 105, 87, 93, 120 and 99?', '["33","120","87","207"]', '33', '120-87', 'The largest is 120 and the smallest is 87. $120 - 87 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 87 = 33.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
