INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dd6cef9-8692-467e-b54d-767f43cf3ba8', 'BA5.04', 2, 'numeric', 'Finding a missing value from a mean', 'The mean of five numbers is 12. Four of them are 10, 14, 9 and 13. What is the fifth number?', '[]', '14', '5*12-10-14-9-13', 'The five numbers add up to $5 \times 12 = 60$. The four known numbers add up to 46. $60 - 46 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 60; 60 - (10+14+9+13 = 46) = 14.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
