INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e99c9e8-b115-4bab-81ab-5760af92888c', 'BA5.04', 2, 'choice', 'Finding a missing value from a mean', 'After three tests, a student''s mean score is 82. The first two scores were 80 and 90. What was the third score?', '["82","86","90","76"]', '76', '3*82-80-90', 'Three scores with mean 82 add up to 246. $246 - 80 - 90 = 76$.', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 246; 246 - 170 = 76.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
