VALUES ('dd727325-34f6-4a53-aaf0-45259f18b64a', 'BA5.04', 2, 'choice', 'Finding a missing value from a mean', 'The mean of 8 numbers is 15. What is the sum of the 8 numbers?', '["23","105","120","150"]', '120', '15*8', 'Sum = mean times how many numbers = $15 \times 8 = 120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*15 = 120.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
