INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63d451e5-03a4-4f4b-b20a-77512f97507f', 'BA5.04', 2, 'choice', 'How adding or changing a value changes the statistics', 'The list 5, 6, 7, 8, 9 has a mean of 7 and a median of 7. The 9 is changed to 19. What happens?', '["Both go up by the same amount","The mean goes up and the median stays 7","The median goes up and the mean stays 7","Neither of them changes"]', 'The mean goes up and the median stays 7', NULL, 'The new list is 5, 6, 7, 8, 19. The middle number is still 7. The sum is now 45, so the mean is $45 \div 5 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"The mean goes up and the median stays 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,6,7,8,19: sum 45, mean 9; median still 7.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
