INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f9e1381-4683-4e78-abdf-be95bd29a807', 'BA5.04', 3, 'choice', 'Finding the mean', 'Three numbers have a mean of 14. Another five numbers have a mean of 6. What is the mean of all eight numbers?', '["10","20","9","12"]', '9', '(3*14+5*6)/8', 'The first group adds up to $3 \times 14 = 42$ and the second to $5 \times 6 = 30$. Together 72 for 8 numbers: $72 \div 8 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*14 + 5*6 = 42 + 30 = 72; 72/8 = 9.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
