INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c5b6d0-3d3b-4e0b-b6ff-90596b90df07', 'BA5.04', 3, 'choice', 'Finding the range', 'A list of seven numbers has a range of 40. Every number in the list is then increased by 15. What is the range of the new list?', '["55","25","40","15"]', '40', '40', 'The biggest and smallest both go up by 15, so the gap between them stays 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shifting all values by 15 leaves max - min unchanged: 40.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
