INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ab77076-d602-46df-b4ff-ee93f33ba185', 'BA5.04', 3, 'numeric', 'Finding the range', 'Every number in a list is doubled. The range of the old list was 13. What is the range of the new list?', '[]', '26', '2*13', 'The largest and smallest are both doubled, so the gap between them is doubled: $2 \times 13 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling doubles max - min: 26.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
