INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e81018a-7a2c-4602-ad7f-d6affcfc95f0', 'BA5.04', 3, 'choice', 'Finding the range', 'List A is 10, 20, 30. List B is 100, 110, 120. Which statement is true?', '["List B has a range of 120","Both lists have a range of 20","List A has the larger range","List B has a range 10 more than List A"]', 'Both lists have a range of 20', NULL, 'List A: $30 - 10 = 20$. List B: $120 - 100 = 20$. The ranges are equal.', 'checked', '{"lint":[],"solve":{"answer":"Both lists have a range of 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 30 - 10 = 20; B: 120 - 100 = 20.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
