INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efdf92b5-44a6-461e-ba16-3d7a160d3287', 'BA5.04', 3, 'numeric', 'Finding the range', 'The list 12, 7, 15, ? has a range of 18, and the ? is the biggest number in it. What number is the ?', '[]', '25', '7+18', 'The smallest number is 7. The biggest is $7 + 18 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smallest 7; ? = 7 + 18 = 25 (> 15, so it is biggest).","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
