INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9cae45e-c4d1-4109-adad-4f666f58db60', 'BA5.04', 3, 'numeric', 'Finding the range', 'The highest of six temperatures is 4 degrees more than twice the lowest, and the range is 22 degrees. What is the lowest temperature, in degrees?', '[]', '18', '22-4', 'Let the lowest be $L$. The highest is $2L + 4$, so the range is $2L + 4 - L = L + 4 = 22$. So $L = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"H = 2L + 4, H - L = 22 gives L + 4 = 22, L = 18 (H = 40).","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f824bb5-0fc1-4200-b32e-cede1ed85c1b', 'BA5.04', 3, 'choice', 'Finding a missing value from a mean', 'The mean of four quiz scores is 78. After a fifth quiz the mean is 80. What was the fifth score?', '["88","80","82","98"]', '88', '5*80-4*78', 'After five quizzes the sum is $5 \times 80 = 400$. The first four added to $4 \times 78 = 312$. The fifth is $400 - 312 = 88$.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*80 - 4*78 = 400 - 312 = 88.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c6c6cfa-cd59-4e74-9c29-4e983014ddbf', 'BA5.04', 3, 'numeric', 'Finding a missing value from a mean', 'The mean of six numbers is 15. One number is removed and the mean of the five left is 14. What number was removed?', '[]', '20', '6*15-5*14', 'The six numbers add up to 90 and the five left add up to 70. The number removed is $90 - 70 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*15 - 5*14 = 90 - 70 = 20.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
