INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0799b195-3c5c-41f0-a67f-e40d2c760446', 'BA5.04', 3, 'choice', 'Finding a missing value from a mean', 'Ana wants a mean of 90 on 5 tests. Her first four scores are 88, 92, 85 and 91. What must she score on the fifth test?', '["90","93","98","94"]', '94', '5*90-88-92-85-91', 'Five tests with mean 90 add up to 450. The first four add up to 356. $450 - 356 = 94$.', 'checked', '{"lint":[],"solve":{"answer":"94","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*90 = 450; 88+92+85+91 = 356; 450 - 356 = 94.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
