INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b629ace5-24b1-404a-a46d-6332754cd234', 'BA5.04', 3, 'numeric', 'Finding a missing value from a mean', 'A player scored 12, 15 and 9 points in three games. How many points must the player score in the fourth game to bring the mean to 13 points?', '[]', '16', '4*13-12-15-9', 'Four games with a mean of 13 means 52 points. So far there are 36 points, and $52 - 36 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*13 = 52; 12+15+9 = 36; 52 - 36 = 16.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
