INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29c12ba9-90a6-44c5-b497-fd00eaf91246', 'BA5.04', 3, 'numeric', 'Finding a missing value from a mean', 'The mean of five numbers is 20. One of them is 40, and the other four are all the same number. What is that number?', '[]', '15', '(5*20-40)/4', 'The five numbers add up to 100. The four equal numbers add up to $100 - 40 = 60$, so each is $60 \div 4 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 100; 100 - 40 = 60; 60/4 = 15.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
