INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15d84805-7fd3-4f68-a1b4-023683c5cfa6', 'BA5.04', 3, 'choice', 'How adding or changing a value changes the statistics', 'The mean of five test scores is 84. The teacher finds that one score of 70 should have been 85. What is the correct mean?', '["84","85","87","99"]', '87', '(5*84+85-70)/5', 'The sum was $5 \times 84 = 420$. The fix adds $85 - 70 = 15$, making 435. $435 \div 5 = 87$.', 'checked', '{"lint":[],"solve":{"answer":"87","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 420 + 15 = 435; 435/5 = 87.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
