INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d9ed0a9-0f8e-4883-b9a8-7e5d10cd98e6', 'BA5.04', 3, 'choice', 'How adding or changing a value changes the statistics', 'Five numbers have a mean of 10 and a median of 10. The largest number is raised by 10. What are the new mean and median?', '["mean 10, median 12","mean 12, median 10","mean 12, median 12","mean 20, median 10"]', 'mean 12, median 10', NULL, 'The sum goes up by 10, from 50 to 60, so the mean is 12. The middle number is not the one that changed, so the median stays 10.', 'checked', '{"lint":[],"solve":{"answer":"mean 12, median 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 50 + 10 = 60, mean 12; raising the largest does not move the middle value, median 10.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
