INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe9531f7-f023-4bb0-9f0b-c262cd8a1109', 'BA5.05', 2, 'choice', 'Factors, multiples and primes', 'Which number is both a multiple of 4 and a factor of 60?', '["15","12","8","120"]', '12', '12', '12 = 4 times 3, and 60 divided by 12 is 5. 15 is not a multiple of 4. 8 is a multiple of 4 but is not a factor of 60. 120 is a multiple of 4 but is not a factor of 60.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 4x3 and 60/12 = 5. 8 does not divide 60; 15 not a multiple of 4; 120 not a factor of 60.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
