INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbaf634a-7eca-4a2f-9165-724a0b0d4acd', 'BA5.05', 2, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 24 and 36?', '[]', '12', '12', '24 = 2 x 2 x 2 x 3 and 36 = 2 x 2 x 3 x 3. They share 2 x 2 x 3 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24=2^3x3, 36=2^2x3^2; gcd 12.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
