VALUES ('0e5d4364-db9a-4fc6-86cb-253022cc9a4d', 'BA5.05', 2, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 45 and 75?', '[]', '15', '15', '45 = 3 x 3 x 5 and 75 = 3 x 5 x 5. They share 3 x 5 = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45=3^2x5, 75=3x5^2; gcd 15.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
