INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f174d88e-ee6b-443e-8eb0-dd83701927c9', 'BA5.05', 2, 'choice', 'Greatest common factor', 'To write $\frac{36}{48}$ in simplest form, you divide the top and the bottom by their greatest common factor. What is that number?', '["12","6","4","144"]', '12', '12', '36 = 12 x 3 and 48 = 12 x 4, and 3 and 4 share no factor. So the greatest common factor is 12, and $\frac{36}{48} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(36,48)=12; 36/48 = 3/4.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031c89aa-b534-480e-b71b-f33117c994f5', 'BA5.05', 2, 'numeric', 'Greatest common factor', 'What is the greatest number that is a factor of all three of 16, 24 and 40?', '[]', '8', '8', '16 = 8 x 2, 24 = 8 x 3 and 40 = 8 x 5, and 2, 3 and 5 share no factor. So the greatest common factor is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(16,24,40)=8.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b82a6085-3915-4fee-8bb2-31a6aaec199f', 'BA5.05', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of 12 and 18?', '[]', '36', '36', '12 = 2 x 2 x 3 and 18 = 2 x 3 x 3. Use each prime as many times as in the one that has more: 2 x 2 x 3 x 3 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12=2^2x3, 18=2x3^2; lcm 36.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ae72ddd-f731-4d84-bd2b-43de88932a51', 'BA5.05', 2, 'choice', 'Least common multiple', 'What is the least common multiple of 8 and 20?', '["160","4","80","40"]', '40', '40', '8 = 2 x 2 x 2 and 20 = 2 x 2 x 5. The least common multiple is 2 x 2 x 2 x 5 = 40. (160 is the product, 4 is the greatest common factor, and 80 is a larger common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8=2^3, 20=2^2x5; lcm 40.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1594768-9455-4b71-9938-8471895cf537', 'BA5.05', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of 9 and 15?', '[]', '45', '45', 'Multiples of 15: 15, 30, 45. 45 is 9 x 5, so it is the first one that 9 also divides.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9=3^2, 15=3x5; lcm 45.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
