INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4eb19337-ae68-4c45-9656-5cd53903c328', 'BA5.05', 2, 'choice', 'Least common multiple', 'What is the least common multiple of 6, 8 and 10?', '["480","120","240","60"]', '120', '120', '6 = 2 x 3, 8 = 2 x 2 x 2 and 10 = 2 x 5. The least common multiple is 2 x 2 x 2 x 3 x 5 = 120. (480 is the product of all three. 60 is not a multiple of 8.)', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 3 x 5 = 120.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
