INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4df2bac9-4272-4ec1-8040-ad7c48d8fc9b', 'BA5.05', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of 14 and 21?', '[]', '42', '42', '14 = 2 x 7 and 21 = 3 x 7. They share the 7, so the least common multiple is 2 x 3 x 7 = 42.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14=2x7, 21=3x7; lcm 42.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
