INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93b33926-a22c-4280-bed5-15c2062af498', 'BA5.05', 2, 'choice', 'Prime factorization', 'What is the prime factorization of 72?', '["$2^3 \\times 3^2$","$2^2 \\times 3^3$","$2^3 \\times 3$","$2 \\times 3^4$"]', '$2^3 \times 3^2$', NULL, '72 = 8 x 9 = $2^3 \times 3^2$. The others equal 108, 24 and 162.', 'checked', '{"lint":[],"solve":{"answer":"$2^3 \\times 3^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 8 x 9 = 2^3 x 3^2.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
