INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d0af3b2-f3f3-4469-93da-f5e8ef1ae13f', 'BA5.05', 2, 'numeric', 'Prime factorization', '180 can be written as $2^a \times 3^b \times 5^c$ with a, b and c whole numbers. What is a + b + c?', '[]', '5', '2+2+1', '180 = 4 x 9 x 5 = $2^2 \times 3^2 \times 5^1$. So a = 2, b = 2, c = 1 and the sum is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 = 2^2 x 3^2 x 5; 2+2+1 = 5.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
