INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6b2a49f-a428-495a-8acc-ef038bef605b', 'BA5.05', 2, 'choice', 'Prime factorization', 'Which number has the prime factorization $2^2 \times 5 \times 7$?', '["70","280","700","140"]', '140', '140', '4 x 5 x 7 = 140. The others come from $2 \times 5 \times 7$ = 70, $2^3 \times 5 \times 7$ = 280 and $2^2 \times 5^2 \times 7$ = 700.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 5 x 7 = 140.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
