INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac5d6097-992d-4413-af56-7d5426d3d074', 'BA5.05', 2, 'numeric', 'Prime factorization', 'The prime factorization of a number is $2 \times 3^2 \times 7$. What is the number?', '[]', '126', '2*9*7', '$3^2$ = 9. Then 2 x 9 = 18 and 18 x 7 = 126.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 9 x 7 = 126.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
