INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0cb96c0-0afa-4963-8dd0-d7458be020bf', 'BA5.05', 2, 'choice', 'Prime factorization', 'Which is the prime factorization of 84?', '["$2 \\times 3 \\times 14$","$2^2 \\times 3 \\times 7$","$2^2 \\times 21$","$4 \\times 3 \\times 7$"]', '$2^2 \times 3 \times 7$', NULL, '84 = 4 x 21 = 2 x 2 x 3 x 7. The other products also equal 84, but each uses a number that is not prime (14, 21 or 4).', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3 \\times 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = 4 x 21 = 2^2 x 3 x 7; others contain non-primes.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
