VALUES ('ffa6d8ed-a8db-4ab6-aad6-26dc04df19b8', 'BA5.05', 2, 'choice', 'Counting the factors of a number', 'Which number has exactly 6 factors?', '["18","16","15","24"]', '18', '18', '18 has 1, 2, 3, 6, 9, 18, which is 6 factors. 16 has 5, 15 has 4 and 24 has 8.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16:5, 15:4, 24:8, 18=2x3^2: 2x3=6.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
