INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a16da15-3485-43cd-b47d-526835d2eb56', 'BA5.05', 2, 'numeric', 'Counting the factors of a number', 'How many of the factors of 30 are even?', '[]', '4', '4', 'The factors of 30 are 1, 2, 3, 5, 6, 10, 15 and 30. The even ones are 2, 6, 10 and 30. That is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors 1,2,3,5,6,10,15,30; even: 2,6,10,30 = 4.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
