INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da2f09c0-8724-4acf-8914-3fd50d66bcb0', 'BA5.05', 2, 'numeric', 'Grouping stories (greatest common factor)', 'A baker has 24 chocolate cookies and 36 oatmeal cookies. She fills boxes that are all the same, with the same number of each kind in every box, and uses every cookie. What is the greatest number of boxes she can fill?', '[]', '12', '12', 'The number of boxes must divide both 24 and 36. The greatest is 12. Each box has 2 chocolate and 3 oatmeal cookies.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(24,36) = 12.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
