INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84d07824-eca2-4fb3-9f9d-480cf0a38d52', 'BA5.05', 2, 'numeric', 'Grouping stories (greatest common factor)', 'A sheet of paper is 18 centimeters wide and 30 centimeters long. It is cut into squares that are all the same, with no paper left over. What is the side of the largest possible square, in centimeters?', '[]', '6', '6', 'The side must divide both 18 and 30. The greatest is 6 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(18,30) = 6.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
