INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e2a7b98-1ef1-49a9-a25e-4030d89be4cb', 'BA5.05', 2, 'choice', 'Grouping stories (greatest common factor)', 'Ravi has 28 red stickers and 42 blue stickers. He shares them among as many friends as possible so that each friend gets the same number of red and the same number of blue, with none left over. How many friends get stickers?', '["7","14","84","70"]', '14', '14', 'The number of friends must divide both 28 and 42. The greatest is 14. Each friend gets 2 red and 3 blue stickers.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(28,42) = 14.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
