INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6f4f3a4-a0a6-471b-af21-4c385dcbc133', 'BA5.05', 2, 'numeric', 'Cycle stories (least common multiple)', 'One lamp flashes every 12 seconds and another flashes every 18 seconds. They flash together at noon. After how many seconds do they next flash together?', '[]', '36', '36', 'The least common multiple of 12 and 18 is 36 (12 = 2 x 2 x 3 and 18 = 2 x 3 x 3), so 36 seconds.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(12,18) = 36.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
