INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dac3cc38-fddf-45dc-b4d6-2810e30b15d6', 'BA5.05', 2, 'choice', 'Cycle stories (least common multiple)', 'Mia goes to the library every 6 days and Noah goes every 8 days. They are both there on Monday. In how many days will they next both be there?', '["48","2","24","14"]', '24', '24', 'The least common multiple of 6 and 8 is 24, so they meet again in 24 days. (48 is a later meeting.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,8) = 24.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
