INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c3a65e0-4835-4405-b3cd-3f5d2b7fe243', 'BA5.05', 2, 'choice', 'Cycle stories (least common multiple)', 'Hot dogs come in packs of 10 and buns come in packs of 8. Ellie wants exactly the same number of hot dogs and buns. What is the least number of hot dogs she can buy?', '["40","80","18","20"]', '40', '40', 'She needs a number that is a multiple of 10 and of 8. The least is 40, which is 4 packs of hot dogs and 5 packs of buns.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(10,8) = 40 hot dogs (4 packs; 5 packs of buns).","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f163e1d-046e-49ac-88d8-cceda56d3cca', 'BA5.05', 3, 'numeric', 'Factors, multiples and primes', 'Two different prime numbers add to 24, and their difference is 10. What is the larger prime?', '[]', '17', '(24+10)/2', 'The larger is (24 + 10) / 2 = 17 and the smaller is 17 - 10 = 7. Both 17 and 7 are prime and 17 + 7 = 24.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b=24, a-b=10 gives a=17, b=7, both prime.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3661301-1d28-4f80-98b6-5ef20bfab207', 'BA5.05', 3, 'choice', 'Factors, multiples and primes', 'Which statement about prime numbers is true?', '["Every odd number above 1 is prime.","1 is the smallest prime number.","2 is the only even prime number.","The product of two primes is a prime."]', '2 is the only even prime number.', NULL, 'Every even number above 2 can be divided by 2, so 2 is the only even prime. 9 is odd but not prime. A prime must have exactly two factors, so 1 is not prime. 2 times 3 = 6 is not prime.', 'checked', '{"lint":[],"solve":{"answer":"2 is the only even prime number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 not prime; 2x3=6 not prime; 9 odd not prime; 2 is the only even prime.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d22f38b4-3eff-4a22-b571-012df69e5eb1', 'BA5.05', 3, 'numeric', 'Factors, multiples and primes', 'Mia writes down every multiple of 7 that is between 100 and 200. How many numbers does she write?', '[]', '14', '28-15+1', 'The first multiple above 100 is 7 times 15 = 105. The last below 200 is 7 times 28 = 196. From the 15th to the 28th multiple is 28 - 15 + 1 = 14 numbers.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 7 from 105 (7x15) to 196 (7x28): 28-15+1 = 14.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
