INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac4af6ea-1c1c-4c45-ae98-dc2f958ac57b', 'BA5.05', 3, 'numeric', 'Factors, multiples and primes', 'Three different primes have a product of 105. What is their sum?', '[]', '15', '3+5+7', '105 = 3 times 5 times 7, and these are three different primes. Their sum is 3 + 5 + 7 = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"105 = 3 x 5 x 7; sum 15.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
