INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1900854e-27c8-45ed-8c87-9d3e1b117d02', 'BA5.05', 3, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 84 and 126?', '[]', '42', '42', '84 = 2 x 2 x 3 x 7 and 126 = 2 x 3 x 3 x 7. They share 2 x 3 x 7 = 42.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84=2^2x3x7, 126=2x3^2x7; gcd 42.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
