INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e1e78f6-93ce-4b9b-8c91-01fab806e2f0', 'BA5.05', 3, 'choice', 'Greatest common factor', 'The greatest common factor of 36 and N is 12. Which number could N be?', '["18","72","30","60"]', '60', '60', 'gcd(36, 60) = 12. For the others the greatest common factor with 36 is 18 (for 18), 36 (for 72) and 6 (for 30).', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(36,18)=18, gcd(36,72)=36, gcd(36,30)=6, gcd(36,60)=12.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('181019a4-3071-4d36-9aaa-1be83dff99ee', 'BA5.05', 3, 'numeric', 'Greatest common factor', 'The greatest common factor of 45 and another number is 9. The other number is between 50 and 60. What is it?', '[]', '54', '54', 'The other number is a multiple of 9, and the only multiple of 9 between 50 and 60 is 54. Check: 45 = 9 x 5 and 54 = 9 x 6, and 5 and 6 share no factor.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must be multiple of 9 in 50-60: only 54. gcd(45,54)=9.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('398ffb1b-9e83-43f4-b0ac-cdd8410277a8', 'BA5.05', 3, 'choice', 'Greatest common factor', 'Which pair of numbers has a greatest common factor of 1?', '["14 and 21","14 and 15","15 and 25","16 and 20"]', '14 and 15', NULL, '14 = 2 x 7 and 15 = 3 x 5 share no prime. 14 and 21 share 7, 15 and 25 share 5, and 16 and 20 share 4.', 'checked', '{"lint":[],"solve":{"answer":"14 and 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14,21 share 7; 16,20 share 4; 15,25 share 5; 14,15 share only 1.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
