INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a0b3f7a-df59-4101-b88e-88df1588af57', 'BA5.05', 3, 'numeric', 'Greatest common factor', 'What is the greatest common factor of $2^3 \times 3^2 \times 5$ and $2^2 \times 3^4 \times 7$?', '[]', '36', '4*9', 'Take the smaller power of each prime they share: $2^2$ and $3^2$. The 5 and the 7 are not shared. So the answer is 4 x 9 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"min powers: 2^2 x 3^2 = 36.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
