INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('edebce83-55d1-4c49-9c2d-df344552108c', 'BA5.05', 3, 'numeric', 'Least common multiple', 'What is the least common multiple of 18, 24 and 30?', '[]', '360', '8*9*5', '18 = 2 x 3 x 3, 24 = 2 x 2 x 2 x 3 and 30 = 2 x 3 x 5. Use the most of each prime: three 2s, two 3s and one 5. That is 8 x 9 x 5 = 360.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18=2x3^2, 24=2^3x3, 30=2x3x5; lcm 2^3x3^2x5=360.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d361eaf9-6d07-43eb-bc7c-94b28d051081', 'BA5.05', 3, 'choice', 'Least common multiple', 'The least common multiple of 12 and N is 60. Which number could N be?', '["24","18","20","40"]', '20', '20', 'lcm(12, 20) = 60. The least common multiple of 12 with 24 is 24, with 18 is 36 and with 40 is 120.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(12,20)=60; lcm(12,24)=24; lcm(12,40)=120; lcm(12,18)=36.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
