INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('420ecca0-7e68-499a-9154-207f3f79dd65', 'BA5.05', 3, 'numeric', 'Least common multiple', 'What is the smallest number greater than 50 that is a multiple of both 6 and 8?', '[]', '72', '3*24', 'The least common multiple of 6 and 8 is 24, so the common multiples are 24, 48, 72, and so on. The first one above 50 is 72.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,8)=24; multiples 24, 48, 72; first above 50 is 72.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
