INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f503770-8202-4500-8c49-5dfe0a8c835b', 'BA5.05', 3, 'choice', 'Least common multiple', 'Which of these is a common multiple of 6 and 15 but is NOT their least common multiple?', '["60","30","45","15"]', '60', '60', 'The least common multiple of 6 and 15 is 30. 60 is also a multiple of both. 45 is not a multiple of 6, and 15 is not a multiple of 6.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,15)=30. 60 is a common multiple, not least; 45 and 15 are not multiples of 6.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
