INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46c65ff2-9f39-4d28-82ac-ca64cf69029c', 'BA5.05', 3, 'numeric', 'Least common multiple', 'The least common multiple of 8 and an odd number N is 56. What is N?', '[]', '7', '56/8', '56 = 8 x 7, so N must supply the factor 7. N is odd and divides 56, so N is 7 (1 would give 8).', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"N odd and lcm(8,N)=56=2^3x7, so N is an odd divisor of 56 giving the 7: N=7 (N=1 gives 8).","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
