INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('800839d2-db7f-4f33-8c85-1311480fda6b', 'BA5.05', 3, 'numeric', 'Prime factorization', 'What is the largest prime factor of 1001?', '[]', '13', '13', '1001 = 7 x 143 = 7 x 11 x 13. All three are prime, and the largest is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1001 = 7 x 11 x 13; largest 13.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
