INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('885d9d56-8752-4e7f-aade-b1ea04419b6d', 'BA5.05', 3, 'choice', 'Prime factorization', 'What is the value of $2^3 \times 3 \times 5^2$?', '["450","240","600","120"]', '600', '600', '$2^3$ = 8 and $5^2$ = 25. Then 8 x 3 x 25 = 600. (Mistakes: using 6 for $2^3$ gives 450, using 10 for $5^2$ gives 240, using 5 for $5^2$ gives 120.)', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 3 x 25 = 600.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
