INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19aa98f3-06d9-41e4-9747-42d89c6f9835', 'BA5.05', 3, 'numeric', 'Prime factorization', 'The prime factorization of 210 is $2 \times 3 \times 5 \times 7$. What is the largest factor of 210 that has two digits?', '[]', '70', '2*5*7', 'Leaving one prime out of 210 gives 105, 70, 42 or 30. 105 has three digits. The largest two-digit factor is 210 divided by 3 = 70. Any other two-digit factor is smaller.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 210/k is two-digit only for k>=3; 210/3 = 70. So 70.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69c64514-c48c-43e8-9ab1-fdb6560e4115', 'BA5.05', 3, 'choice', 'Prime factorization', '$360 = 2^3 \times 3^2 \times 5$. Which of these is NOT a factor of 360?', '["54","40","45","72"]', '54', '54', '54 = 2 x $3^3$ needs three 3s, but 360 has only two. 40 = $2^3 \times 5$, 45 = $3^2 \times 5$ and 72 = $2^3 \times 3^2$ all fit.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72=2^3x3^2 ok, 40=2^3x5 ok, 45=3^2x5 ok, 54=2x3^3 needs 3^3: not a factor.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fe6956a-e855-40cd-a505-7870c090273d', 'BA5.05', 3, 'numeric', 'Prime factorization', 'What is the smallest number you can multiply 360 by to get a perfect square?', '[]', '10', '10', '360 = $2^3 \times 3^2 \times 5$. A perfect square has an even number of each prime. The 2 and the 5 appear an odd number of times, so multiply by 2 x 5 = 10. Then 3600 = 60 x 60.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: strictly, multiplying by 0 (or a fraction) also gives a perfect square; \"smallest positive whole number\" would be tighter. Conventional reading gives 10.","work":"360 = 2^3 x 3^2 x 5; need one more 2 and one more 5: x10 gives 3600 = 60^2.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9259cea-e352-4b54-966b-3e62a6843736', 'BA5.05', 3, 'numeric', 'Counting the factors of a number', '$360 = 2^3 \times 3^2 \times 5$. How many factors does 360 have?', '[]', '24', '4*3*2', 'Add 1 to each exponent and multiply: (3 + 1) x (2 + 1) x (1 + 1) = 4 x 3 x 2 = 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3+1)(2+1)(1+1) = 24.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e856def-9957-400d-a713-46218d67415c', 'BA5.05', 3, 'choice', 'Counting the factors of a number', 'Which of these numbers has exactly 3 factors?', '["12","27","35","49"]', '49', '49', '49 = 7 x 7, so its factors are 1, 7 and 49. 12 has 6 factors, 27 has 4 (1, 3, 9, 27) and 35 has 4 (1, 5, 7, 35).', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49 = 7^2: 1,7,49. 12:6, 27:4, 35:4.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad390662-1b94-4572-ba84-e44ae24f7e6a', 'BA5.05', 3, 'numeric', 'Counting the factors of a number', 'What is the smallest number that has exactly 8 factors?', '[]', '24', '24', 'Numbers below 24 have at most 6 factors (12, 18 and 20 have 6 each). 24 has 8: 1, 2, 3, 4, 6, 8, 12, 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 factors: p^7 (128), p^3 q (24), pqr (30). Smallest 24.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
