INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('746c1f6c-57f1-4cc3-868f-2a91b6629711', 'BA5.05', 3, 'choice', 'Counting the factors of a number', 'How many of the factors of 72 are odd?', '["12","3","6","9"]', '3', '3', '72 = $2^3 \times 3^2$. An odd factor uses no 2s, so it is 1, 3 or 9. That is 3. (12 is the number of ALL factors of 72.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 2^3 x 3^2; odd factors are factors of 9: 3.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d8268e8-860f-4b28-8274-de4f40909b28', 'BA5.05', 3, 'numeric', 'Counting the factors of a number', 'A number has the prime factorization $2^2 \times 3 \times 7$. How many of its factors are greater than 1 and also less than the number itself?', '[]', '10', '12-2', 'It has (2 + 1) x (1 + 1) x (1 + 1) = 12 factors. Take away 1 and the number itself, leaving 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = 2^2x3x7 has 3x2x2 = 12 factors; drop 1 and 84: 10.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1da1c74-57c0-48f8-b8b4-6960723e6715', 'BA5.05', 3, 'numeric', 'Grouping stories (greatest common factor)', 'A sheet 60 centimeters wide and 84 centimeters long is cut into squares that are all the same, with none left over. The squares are as big as possible. How many squares are there?', '[]', '35', '5*7', 'The side must divide 60 and 84, so the greatest is 12 centimeters. Along the width there are 60 / 12 = 5 squares, along the length 84 / 12 = 7. In all 5 x 7 = 35 squares.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(60,84) = 12; 5 x 7 = 35 squares.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54767cbb-231a-4cd3-9382-2ac9aa4d77c0', 'BA5.05', 3, 'choice', 'Grouping stories (greatest common factor)', 'Three ribbons are 30, 45 and 75 inches long. Each is cut into pieces that all have the same length, as long as possible, with nothing left over. How many pieces are there altogether?', '["15","5","10","25"]', '10', '10', 'The greatest common factor of 30, 45 and 75 is 15, so each piece is 15 inches long. The ribbons give 2 + 3 + 5 = 10 pieces. (15 is the length of a piece, not the number of pieces.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(30,45,75)=15; 2+3+5 = 10 pieces.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb6e6425-1735-4aaa-b2b0-091e08b7bef1', 'BA5.05', 3, 'numeric', 'Grouping stories (greatest common factor)', 'A cook has 48 carrots, 72 potatoes and 120 onions. She packs as many identical crates as possible, with the same number of each vegetable in every crate and none left over. How many onions are in each crate?', '[]', '5', '120/24', 'The number of crates is the greatest common factor of 48, 72 and 120, which is 24. Each crate holds 120 / 24 = 5 onions (and 2 carrots and 3 potatoes).', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(48,72,120) = 24 crates; 120/24 = 5 onions.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f18b8c2-4d87-42f4-bfc8-171d2179ce56', 'BA5.05', 3, 'choice', 'Grouping stories (greatest common factor)', 'Tara has 40 red tiles and 56 blue tiles. She makes as many identical patterns as she can, using every tile. How many tiles are in each pattern?', '["12","8","96","16"]', '12', '12', 'The number of patterns is the greatest common factor of 40 and 56, which is 8. Each pattern has 40 / 8 = 5 red and 56 / 8 = 7 blue tiles, which is 12 tiles. (8 is the number of patterns, 96 is all the tiles.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(40,56) = 8 patterns; each 5 red + 7 blue = 12 tiles.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e990f86d-7ab8-4624-bb70-0b2ade358228', 'BA5.05', 3, 'numeric', 'Cycle stories (least common multiple)', 'Three signs blink every 9, 12 and 15 seconds. They all blink together at the start. After how many seconds do they all blink together again?', '[]', '180', '4*9*5', '9 = 3 x 3, 12 = 2 x 2 x 3 and 15 = 3 x 5. The least common multiple uses two 2s, two 3s and one 5: 4 x 9 x 5 = 180.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9=3^2, 12=2^2x3, 15=3x5: lcm 180.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
