INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d7fa11a-9cac-4d86-8d73-2b848ca4c80f', 'BA5.05', 3, 'numeric', 'Cycle stories (least common multiple)', 'Two bells ring together at 9:00. One then rings every 12 minutes and the other every 20 minutes. How many minutes after 9:00 do they ring together for the third time, not counting the ring at 9:00?', '[]', '180', '3*60', 'The least common multiple of 12 and 20 is 60, so they ring together every 60 minutes. The third time is 3 x 60 = 180 minutes after 9:00.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(12,20) = 60; together at 60, 120, 180; third is 180.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
