INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d85a4804-4cb1-48e4-8d61-2388a8aaf804', 'BA5.05', 3, 'choice', 'Cycle stories (least common multiple)', 'Sara swims every 4 days and Tim swims every 6 days. They both swim on day 0. On how many of the days from day 1 to day 90 do they swim on the same day?', '["8","15","22","7"]', '7', '7', 'They both swim every 12 days: day 12, 24, 36, 48, 60, 72 and 84. Day 96 is past 90. That is 7 days. (8 would count 90 / 12 = 7.5 as 8.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Together every lcm(4,6)=12 days: 12, 24, ..., 84 within 1-90: 7.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('795570d9-0511-4998-bfa1-e17d063f5921', 'BA5.05', 3, 'numeric', 'Cycle stories (least common multiple)', 'A gear with 15 teeth turns against a gear with 20 teeth. A marked tooth on each gear touch at the start. After how many turns of the 20-tooth gear do the two marked teeth touch again?', '[]', '3', '60/20', 'The marks meet again after a number of teeth that is a common multiple of 15 and 20. The least is 60 teeth. The 20-tooth gear makes 60 / 20 = 3 turns (the 15-tooth gear makes 4).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Marked teeth meet after lcm(15,20) = 60 teeth pass; 20-tooth gear turns 60/20 = 3.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
