VALUES ('c33ad797-023f-4d8a-bc22-a8b3e7497f10', 'BA5.06', 2, 'choice', 'Dividing with whole numbers and mixed numbers', 'Find the quotient when $2\frac{2}{5}$ is divided by $1\frac{1}{5}$.', '["2","$2\\frac{22}{25}$","$\\frac{1}{2}$","$1\\frac{1}{5}$"]', '2', '2', '$\frac{12}{5} \div \frac{6}{5} = \frac{12}{5} \times \frac{5}{6} = 2$. ($2\frac{22}{25}$ multiplies, $\frac{1}{2}$ is upside down, and $1\frac{1}{5}$ subtracts.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/5 / (6/5) = 2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
