INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88e623a3-ff7c-4ecb-b425-be0c42655346', 'BA5.06', 2, 'numeric', 'A fraction of a quantity', 'A lesson lasts 45 minutes. Sam spends $\frac{3}{5}$ of it reading. How many minutes does he spend reading?', '[]', '27', '(3/5)*45', '$\frac{1}{5}$ of 45 is 9, and $\frac{3}{5}$ is 3 x 9 = 27 minutes.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45/5 x 3 = 27.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
