INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f326414-37a0-481a-9d00-e5ee9dab68d3', 'BA5.06', 2, 'choice', 'A fraction of a quantity', 'A farm has 64 acres. $\frac{3}{8}$ of the farm is planted with corn. How many acres is that?', '["$170\\frac{2}{3}$","40","8","24"]', '24', '24', '$\frac{1}{8}$ of 64 is 8, so $\frac{3}{8}$ is 24 acres. (40 acres is $\frac{5}{8}$, the part that is NOT corn.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64/8 x 3 = 24.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
