INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1c75623-6f02-47ed-b2ab-8d5605a05903', 'BA5.06', 2, 'numeric', 'A fraction of a quantity', 'A recipe needs $\frac{3}{4}$ cup of milk. Sara makes only $\frac{2}{3}$ of the recipe. How many cups of milk does she use? Write your answer as a fraction or a mixed number.', '[]', '1/2', '(3/4)*(2/3)', '$\frac{2}{3}$ of $\frac{3}{4}$ is $\frac{2}{3} \times \frac{3}{4} = \frac{6}{12} = \frac{1}{2}$ cup.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 x 3/4 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
