INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15384ee8-3ec3-45a0-9910-213e773a89c4', 'BA5.06', 2, 'choice', 'A fraction of a quantity', 'A ribbon is $\frac{5}{6}$ meter long. Dan cuts off $\frac{3}{5}$ of it. How long is the piece he cuts off, in meters?', '["$1\\frac{7}{18}$","$\\frac{1}{2}$","$\\frac{7}{30}$","$\\frac{8}{11}$"]', '$\frac{1}{2}$', NULL, '$\frac{3}{5} \times \frac{5}{6} = \frac{15}{30} = \frac{1}{2}$ meter. (The other options divide, subtract or add the parts.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 x 5/6 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
