INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3528a9a-0cfc-455e-a50d-68cb796fd879', 'BA5.06', 2, 'numeric', 'A fraction of a quantity', 'A tank holds 120 liters. It is $\frac{3}{4}$ full. Then $\frac{1}{3}$ of the water in the tank is used. How many liters are used?', '[]', '30', '(3/4)*120/3', '$\frac{3}{4}$ of 120 is 90 liters of water. $\frac{1}{3}$ of 90 is 30 liters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Water 90 L; 1/3 of 90 = 30.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
