INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4808b0c8-0fc5-4dde-b729-71721e6b97d9', 'BA5.06', 2, 'choice', 'Fraction stories with several steps', 'A path is 12 kilometers long. Hector walks $\frac{1}{4}$ of it in the morning and $\frac{1}{3}$ of it in the afternoon. How many kilometers are left?', '["7","8","5","9"]', '5', '12-12/4-12/3', 'Morning: 3 km. Afternoon: 4 km. He walks 7 km in all, so 12 - 7 = 5 km are left.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 4 = 7 walked; 12 - 7 = 5 left.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
