INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f298926-2609-4274-84cc-bce8157da129', 'BA5.06', 2, 'numeric', 'Fraction stories with several steps', 'A ribbon $\frac{9}{10}$ meter long is cut into pieces that are each $\frac{3}{20}$ meter long. How many pieces are there?', '[]', '6', '(9/10)/(3/20)', '$\frac{9}{10} \div \frac{3}{20} = \frac{9}{10} \times \frac{20}{3} = \frac{180}{30} = 6$ pieces.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 / (3/20) = 9/10 x 20/3 = 6.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
