INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2031c52f-b7b1-48da-b0a7-5f805b5f751b', 'BA5.06', 3, 'numeric', 'Reciprocals', 'What is the sum of the reciprocal of $\frac{3}{4}$ and the reciprocal of $\frac{3}{2}$?', '[]', '2', '4/3+2/3', 'The reciprocals are $\frac{4}{3}$ and $\frac{2}{3}$. Their sum is $\frac{6}{3} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/3 + 2/3 = 6/3 = 2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
