INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cacbf15-9be1-4f23-a36f-cc4a2edefb17', 'BA5.06', 3, 'choice', 'Reciprocals', 'Which of these numbers is greater than its own reciprocal?', '["$\\frac{1}{3}$","3","1","$\\frac{3}{4}$"]', '3', '3', 'The reciprocal of 3 is $\frac{1}{3}$, which is smaller. For $\frac{1}{3}$ and $\frac{3}{4}$ the reciprocal is greater (3 and $\frac{4}{3}$). For 1 the two are equal.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 > 1/3; 3/4 < 4/3; 1 = 1; 1/3 < 3.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
