INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60f40f70-259c-4a29-be0a-cb5a14abaec0', 'BA5.06', 3, 'choice', 'Reciprocals', 'What is the reciprocal of $\frac{2}{3} + \frac{1}{6}$?', '["$\\frac{5}{6}$","3","$\\frac{6}{5}$","$7\\frac{1}{2}$"]', '$\frac{6}{5}$', NULL, '$\frac{2}{3} + \frac{1}{6} = \frac{4}{6} + \frac{1}{6} = \frac{5}{6}$. The reciprocal is $\frac{6}{5}$. ($\frac{5}{6}$ forgets to flip. 3 comes from adding tops and bottoms. $7\frac{1}{2}$ adds the reciprocals instead.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 + 1/6 = 5/6; reciprocal 6/5.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
