INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c755d09-4790-43e7-83ef-8afa62b4c502', 'BA5.06', 3, 'numeric', 'Multiplying fractions', 'What is $\frac{3}{4} \times \frac{8}{9} \times \frac{3}{2}$?', '[]', '1', '(3/4)*(8/9)*(3/2)', 'Multiply the tops: 3 x 8 x 3 = 72. Multiply the bottoms: 4 x 9 x 2 = 72. So the product is $\frac{72}{72} = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x 8/9 = 2/3; x 3/2 = 1.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
