INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6846b38b-e084-4069-892a-57047cae190d', 'BA5.06', 3, 'choice', 'Multiplying fractions', 'What is $\frac{5}{9} \times \frac{6}{7} \times \frac{14}{15}$?', '["$\\frac{4}{9}$","$\\frac{10}{21}$","$\\frac{4}{5}$","$\\frac{14}{27}$"]', '$\frac{4}{9}$', NULL, 'Tops: 5 x 6 x 14 = 420. Bottoms: 9 x 7 x 15 = 945. $\frac{420}{945} = \frac{4}{9}$. (The other options leave out one of the three fractions.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/9 x 6/7 = 10/21; x 14/15 = 140/315 = 4/9.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
