VALUES ('908da7fd-b64f-4b89-8ad0-6df59e0eb0dd', 'BA5.06', 3, 'numeric', 'Multiplying mixed numbers', 'One batch of a recipe uses $1\frac{3}{4}$ cups of flour. How many cups of flour do $2\frac{2}{3}$ batches use?', '[]', '4 2/3', '(7/4)*(8/3)', '$\frac{7}{4} \times \frac{8}{3} = \frac{56}{12} = \frac{14}{3} = 4\frac{2}{3}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"14/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/4 x 8/3 = 14/3 = 4 2/3.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
