INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c6a423b-bc65-4801-8ae2-0b5da696fe7d', 'BA5.06', 3, 'choice', 'Multiplying mixed numbers', 'Which of these is NOT equal to 4?', '["$1\\frac{1}{3} \\times 3$","$2 \\times 2\\frac{1}{4}$","$2\\frac{2}{3} \\times 1\\frac{1}{2}$","$\\frac{16}{5} \\times 1\\frac{1}{4}$"]', '$2 \times 2\frac{1}{4}$', NULL, '$2 \times 2\frac{1}{4} = 4\frac{1}{2}$. The others: $\frac{4}{3} \times 3 = 4$, $\frac{8}{3} \times \frac{3}{2} = 4$, and $\frac{16}{5} \times \frac{5}{4} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times 2\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 9/4 = 9/2 (not 4); 16/5 x 5/4 = 4; 8/3 x 3/2 = 4; 4/3 x 3 = 4.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
