INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0c70af9-73d5-481c-942b-cd132e89eb05', 'BA5.06', 3, 'numeric', 'Multiplying mixed numbers', '? $\times 1\frac{1}{3} = 3\frac{1}{5}$. What is the ?', '[]', '2 2/5', '(16/5)/(4/3)', '$3\frac{1}{5} = \frac{16}{5}$ and $1\frac{1}{3} = \frac{4}{3}$. To undo the multiplication, divide: $\frac{16}{5} \div \frac{4}{3} = \frac{16}{5} \times \frac{3}{4} = \frac{12}{5} = 2\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"12/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? = 16/5 / (4/3) = 16/5 x 3/4 = 12/5.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
