INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1325a1d-d003-4985-b5f7-885b5135e790', 'BA5.06', 3, 'numeric', 'Dividing fractions', 'Start with $\frac{4}{9}$. Divide it by $\frac{2}{3}$, then divide that result by $\frac{8}{9}$. What number do you get?', '[]', '3/4', '(4/9)/(2/3)/(8/9)', 'First, $\frac{4}{9} \div \frac{2}{3} = \frac{4}{9} \times \frac{3}{2} = \frac{2}{3}$. Then $\frac{2}{3} \div \frac{8}{9} = \frac{2}{3} \times \frac{9}{8} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/9 x 3/2 = 2/3; 2/3 x 9/8 = 3/4.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
