INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de20007b-7d94-41ea-91c8-79f29bdafbc7', 'BA5.06', 3, 'choice', 'Dividing fractions', 'Which of these four quotients is the greatest?', '["$\\frac{3}{4} \\div \\frac{3}{2}$","$\\frac{3}{4} \\div 3$","$\\frac{3}{4} \\div \\frac{1}{2}$","$\\frac{1}{2} \\div \\frac{3}{4}$"]', '$\frac{3}{4} \div \frac{1}{2}$', NULL, 'The values are $\frac{3}{2}$, $\frac{1}{2}$, $\frac{1}{4}$ and $\frac{2}{3}$. The greatest is $\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4} \\div \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/2, 1/2, 1/4, 2/3; greatest 3/2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
