INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('868bb791-f657-450b-a324-7e197a0ebd5d', 'BA5.06', 3, 'numeric', 'Dividing with whole numbers and mixed numbers', 'A jug holds $5\frac{1}{2}$ liters of juice. How many FULL cups, of $\frac{3}{4}$ liter each, can be poured from it?', '[]', '7', '(22-1)/3', '$5\frac{1}{2} \div \frac{3}{4} = \frac{11}{2} \times \frac{4}{3} = \frac{22}{3} = 7\frac{1}{3}$. Only the 7 whole cups are full cups.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/2 / (3/4) = 22/3 = 7 1/3; 7 full cups.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
