INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5522db1-b0eb-4ff2-b5fc-d435e7088baf', 'BA5.06', 3, 'choice', 'Dividing with whole numbers and mixed numbers', 'A number divided by $1\frac{1}{4}$ is $2\frac{2}{5}$. What is the number?', '["$1\\frac{23}{25}$","3","$3\\frac{13}{20}$","$1\\frac{3}{20}$"]', '3', '3', 'Undo the division by multiplying: $2\frac{2}{5} \times 1\frac{1}{4} = \frac{12}{5} \times \frac{5}{4} = 3$. ($1\frac{23}{25}$ divides again, $3\frac{13}{20}$ adds and $1\frac{3}{20}$ subtracts.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/4 x 12/5 = 3.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
