INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7ffb913-6a00-4883-97ea-46181ece247d', 'BA5.06', 3, 'numeric', 'A fraction of a quantity', 'A club has 72 members. $\frac{5}{8}$ of them are girls. $\frac{2}{5}$ of the girls wear glasses. How many girls wear glasses?', '[]', '18', '(5/8)*72*(2/5)', 'Girls: $\frac{5}{8}$ of 72 = 45. Those with glasses: $\frac{2}{5}$ of 45 = 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 45; 2/5 x 45 = 18.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
