INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f396690-dce8-4364-895d-bc0fb48f48d6', 'BA5.06', 3, 'numeric', 'Fraction stories with several steps', 'In a parking lot, $\frac{1}{3}$ of the cars are red. Then $\frac{1}{4}$ of the REST of the cars are blue. The other 18 cars are white. How many cars are there in all?', '[]', '36', '18/(1-1/3-(2/3)*(1/4))', 'Red: $\frac{1}{3}$. Rest: $\frac{2}{3}$, of which blue is $\frac{1}{4} \times \frac{2}{3} = \frac{1}{6}$. White: $1 - \frac{1}{3} - \frac{1}{6} = \frac{1}{2}$. Half of the cars is 18, so there are 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rest 2/3; blue 1/4 x 2/3 = 1/6; white 2/3 - 1/6 = 1/2 = 18; total 36.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
