INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad1225e9-1e4e-412f-aca7-cc8e95e93c37', 'BA5.07', 2, 'numeric', 'Common difference and missing terms', 'In an arithmetic sequence the 5th term is 27 and the 9th term is 43. What is the 10th term?', '[]', '47', '43+(43-27)/4', 'From the 5th to the 9th term is 4 steps and a rise of 16, so each step is 4. The 10th term is $43 + 4 = 47$.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 steps raise 16, d=4; 10th=43+4=47","run_id":"claude-code","at":"2026-10-19T01:34:00.664Z"}}', 'ai', NULL, NULL)
