VALUES ('dc470466-42b8-4104-8fb9-2f09e2e0d7cd', 'BA5.07', 2, 'choice', 'Finding a term (the 10th, the 50th)', 'A theater has 12 seats in row 1. Each row has 3 more seats than the row before it. How many seats are in row 15?', '["57","45","51","54"]', '54', '12+14*3', 'Row 15 is 14 rows after row 1, so it has $12 + 14 \times 3 = 12 + 42 = 54$ seats.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12+14x3=54","run_id":"claude-code","at":"2026-10-19T01:34:00.664Z"}}', 'ai', NULL, NULL)
