INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73eb84b1-d2ca-4744-a039-5f0195f44235', 'BA5.07', 3, 'choice', 'Common difference and missing terms', 'Which number is NOT a term of the sequence $6, 13, 20, 27, \ldots$?', '["489","496","500","510"]', '500', NULL, 'Each term is 1 less than a multiple of 7 ($7-1$, $14-1$, $21-1$, ...). Adding 1 gives 490, 497 and 511, which are $7\times 70$, $7\times 71$ and $7 \times 73$. But $500 + 1 = 501$ is not a multiple of 7 ($7 \times 71 = 497$ and $7 \times 72 = 504$), so 500 is not a term.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms are 6 more than multiples of 7: 496,489,510 yes; 500=497+3 no","run_id":"claude-code","at":"2026-10-19T01:34:00.664Z"}}', 'ai', NULL, NULL)
