INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a0f369d-0a9f-475d-90ab-78c09da198af', 'BA5.08', 3, 'numeric', 'Writing ratios (part-to-part and part-to-whole)', 'A bag has red and blue marbles in the ratio $2:3$. After 6 more red marbles are put in, there are exactly as many red marbles as blue. How many blue marbles are in the bag?', '[]', '18', '3*6', 'Say there are 2 parts red and 3 parts blue. Adding 6 red makes red equal blue, so 1 part is 6 marbles. Blue is $3 \times 6 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 2x, blue 3x; 2x+6=3x, x=6; blue 18","run_id":"claude-code","at":"2026-10-19T01:34:00.703Z"}}', 'ai', NULL, NULL)
