INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ab0f773-ae67-4407-800e-fb4851b4ae20', 'BA5.08', 3, 'choice', 'Ratio problems: finding a part or the whole', 'A class of 28 students has boys and girls in the ratio $4:3$. Then 2 more girls join the class. What is the ratio of boys to girls now, in simplest form?', '["$4:3$","$8:7$","$7:8$","$2:1$"]', '$8:7$', NULL, '28 students is 7 parts of 4, so there are 16 boys and 12 girls. After 2 more girls join there are 14 girls. The ratio $16:14$ simplifies to $8:7$.', 'checked', '{"lint":[],"solve":{"answer":"$8:7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 16, girls 12; girls 14; 16:14=8:7","run_id":"claude-code","at":"2026-10-19T01:34:00.703Z"}}', 'ai', NULL, NULL)
