INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7fa60d8-8a3a-4aea-8c90-338ef6c6e922', 'BA5.08', 3, 'numeric', 'Ratio problems: finding a part or the whole', 'A mixture has 2 parts concentrate to 5 parts water. There are 28 liters of the mixture. How many liters of water are in it?', '[]', '20', '28/7*5', 'There are $2 + 5 = 7$ parts, each worth $28 \div 7 = 4$ liters. Water is $5 \times 4 = 20$ liters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 parts=28, part 4; water 20","run_id":"claude-code","at":"2026-10-19T01:34:00.703Z"}}', 'ai', NULL, NULL)
