INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f8ea146-13ca-4520-8d4b-4e1571d5e5d5', 'BA5.11', 3, 'choice', 'Square roots of whole numbers', 'Add the square roots of 4, 9, 16, 25 and 36. What is the total?', '["18","20","90","55"]', '20', '2+3+4+5+6', 'The square roots are 2, 3, 4, 5 and 6. 2 + 3 + 4 + 5 + 6 = 20. (90 is what you get by adding the numbers themselves, 4 + 9 + 16 + 25 + 36.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+3+4+5+6=20","run_id":"claude-code","at":"2026-10-19T01:39:00.540Z"}}', 'ai', NULL, NULL)
