INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3223823f-c4ab-4a66-8f15-efa9c782ea4a', 'BA5.11', 3, 'choice', 'Square roots of whole numbers', 'Which of these could be the area of a square whose sides are a whole number of units long?', '["$1{,}000$","$1{,}200$","$1{,}225$","$1{,}300$"]', '$1{,}225$', NULL, '35 times 35 is 1,225 (35 times 35 = 1,050 + 175). The others are not made by a whole number times itself: 31 times 31 = 961 and 32 times 32 = 1,024 surround 1,000; 34 times 34 = 1,156 and 35 times 35 = 1,225 surround 1,200; 36 times 36 = 1,296 and 37 times 37 = 1,369 surround 1,300.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}225$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35^2=1225; 1000,1200,1300 not squares (31^2=961,32^2=1024,34^2=1156,36^2=1296)","run_id":"claude-code","at":"2026-10-19T01:39:00.540Z"}}', 'ai', NULL, NULL)
