VALUES ('79a8aaac-c57e-4df5-ad68-53fed42adc93', 'BA5.11', 3, 'choice', 'Square roots of fractions and decimals', 'Which statement compares $\sqrt{0.16}$ with 0.16?', '["$\\sqrt{0.16} < 0.16$","$\\sqrt{0.16} > 0.16$","$\\sqrt{0.16} = 0.16$","$\\sqrt{0.16} = 0.8$"]', '$\sqrt{0.16} > 0.16$', NULL, 'The square root of 0.16 is 0.4, because 0.4 times 0.4 is 0.16. And 0.4 is greater than 0.16.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{0.16} > 0.16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt0.16=0.4>0.16","run_id":"claude-code","at":"2026-10-19T01:39:00.540Z"}}', 'ai', NULL, NULL)
