VALUES ('fd9eb2ff-e592-43e5-97e2-fae7c1cdee5d', 'BA5.12', 1, 'choice', 'Evaluating powers', 'Which is the same as $2 \times 2 \times 2 \times 2 \times 2$?', '["$5^{2}$","$2^{5}$","$2^{10}$","$2 \\times 5$"]', '$2^{5}$', NULL, 'The number 2 is multiplied 5 times, so it is 2 to the 5th power, $2^5$. (The base is the number being multiplied, and the exponent counts how many times.)', 'checked', '{"lint":[],"solve":{"answer":"$2^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"five factors of 2 = 2^5","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
