VALUES ('30e7b190-4d9d-480f-8383-3bafdb4bf999', 'BA5.12', 2, 'choice', 'Comparing powers', 'Which statement about $4^{3}$ and $3^{4}$ is true?', '["$4^3 > 3^4$","$4^3 = 3^4$","$4^3 < 3^3$","$4^3 < 3^4$"]', '$4^3 < 3^4$', NULL, '$4^3 = 64$ and $3^4 = 81$. 64 is less than 81, so $4^3 < 3^4$.', 'checked', '{"lint":[],"solve":{"answer":"$4^3 < 3^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64<81","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
