INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68f8abc3-20b3-408d-b400-d03070e71aab', 'BA5.12', 2, 'numeric', 'Comparing powers', 'What is the smallest whole number n for which $2^n$ is greater than 1000?', '[]', '10', '10', '$2^9 = 512$ is too small, and $2^{10} = 1024$ is greater than 1000. So n = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^9=512, 2^10=1024>1000 -> 10","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
