INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3e60d6c-2292-4d98-aa17-a7cbb89f1331', 'BA5.12', 2, 'choice', 'Comparing powers', 'Which list shows the numbers in order from least to greatest?', '["$6^2, 2^6, 3^4$","$2^6, 6^2, 3^4$","$3^4, 6^2, 2^6$","$6^2, 3^4, 2^6$"]', '$6^2, 2^6, 3^4$', NULL, '$6^2 = 36$, $2^6 = 64$ and $3^4 = 81$. From least to greatest: $6^2$, $2^6$, $3^4$.', 'checked', '{"lint":[],"solve":{"answer":"$6^2, 2^6, 3^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36, 64, 81 -> 6^2, 2^6, 3^4","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
