INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b65eb248-c9a9-44fe-877b-269f2c1ba247', 'BA5.12', 2, 'choice', 'Comparing powers', 'How many of the numbers $2^5$, $5^2$, $3^3$, $4^2$ and $6^1$ are greater than 20?', '["2","3","4","5"]', '3', '3', '$2^5 = 32$, $5^2 = 25$, $3^3 = 27$, $4^2 = 16$ and $6^1 = 6$. Three of them (32, 25 and 27) are greater than 20.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32,25,27,16,6: three exceed 20","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
