INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca0c65db-959b-41cf-9c4e-ae1c7d1ee73a', 'BA5.12', 2, 'numeric', 'Last digit of a power', 'What is the last digit of $2^{10}$?', '[]', '4', '4', 'The last digits of 2, 4, 8, 16, 32, 64, ... go 2, 4, 8, 6, then repeat every 4 powers. The 10th power is 2 steps into the cycle (10 = 4 + 4 + 2), so the last digit is 4. (Check: $2^{10} = 1024$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^10=1024 -> 4","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
