INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e1b3875-b334-4885-878c-411bc8179905', 'BA5.12', 2, 'choice', 'Last digit of a power', 'What is the last digit of $7^{5}$?', '["1","3","7","9"]', '7', '7', 'The last digits of powers of 7 go 7, 9, 3, 1, then repeat every 4 powers. The 5th power is back to the start of the cycle, so the last digit is 7. (Check: $7^5 = 16{,}807$.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7,9,3,1 cycle; 7^5 ends 7 (16807)","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
