VALUES ('542b0cf6-c761-44a9-86b2-22757629f6a8', 'BA5.12', 3, 'choice', 'Comparing powers', 'Which statement about $2^{30}$ and $3^{20}$ is true?', '["$2^{30} > 3^{20}$","$2^{30} = 3^{20}$","$2^{30} = 3^{10}$","$2^{30} < 3^{20}$"]', '$2^{30} < 3^{20}$', NULL, '$2^{30} = (2^3)^{10} = 8^{10}$ and $3^{20} = (3^2)^{10} = 9^{10}$. Since 8 is less than 9, $8^{10}$ is less than $9^{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{30} < 3^{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^30=8^10, 3^20=9^10; 8^10<9^10","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
