INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d44843b6-67e8-4d7b-9d22-df767deb9777', 'BA5.12', 3, 'numeric', 'Last digit of a power', 'What is the last digit of $2^{100}$?', '[]', '6', '6', 'The last digits of powers of 2 go 2, 4, 8, 6, then repeat every 4 powers. 100 is a multiple of 4, so $2^{100}$ ends where the cycle ends, in 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2: cycle 2,4,8,6; 100 divisible by 4 -> 6","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
