INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a004a20-e4bc-4498-8403-50aced38e785', 'NC26.3.ANR.1', 3, 'numeric', 'Expanded form', 'A number is $6{,}000 + 300 + 20 + 8$. If the digit in the hundreds place and the digit in the tens place swap places, what is the new number?', '[]', '6238', '6000+200+30+8', 'The number is 6,328. Swap the 3 in the hundreds place with the 2 in the tens place: 6 thousands, 2 hundreds, 3 tens, 8 ones. The new number is 6,238.', 'checked', '{"lint":[],"solve":{"answer":"6238","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,000 + 300 + 20 + 8 = 6,328. Hundreds digit 3, tens digit 2; swap: hundreds 2, tens 3 -> 6,238.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
