INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06452ea3-1d29-4899-8d9e-987abac6f95e', 'NC26.3.ANR.1', 3, 'numeric', 'Equivalent forms: regroup place values', 'A number has 7 thousands, 15 hundreds and 12 tens. What is the number?', '[]', '8620', '7*1000+15*100+12*10', '7 thousands is 7,000. 15 hundreds is 1,500. 12 tens is 120. Add: $7{,}000 + 1{,}500 + 120 = 8{,}620$.', 'checked', '{"lint":[],"solve":{"answer":"8620","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 thousands = 7,000; 15 hundreds = 1,500; 12 tens = 120. 7,000 + 1,500 + 120 = 8,620.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
