INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95f16731-eeba-4098-bc35-44d064ed57c4', 'NC26.3.ANR.1', 3, 'choice', 'Equivalent forms: regroup place values', 'Which number is the same as 3 thousands, 25 tens and 14 ones?', '["3,039","3,264","3,390","5,640"]', '3,264', '3000+250+14', '3 thousands is 3,000. 25 tens is 250. 14 ones is 14. Add: $3{,}000 + 250 + 14 = 3{,}264$.', 'checked', '{"lint":[],"solve":{"answer":"3,264","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,000 + 25 x 10 + 14 = 3,000 + 250 + 14 = 3,264.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
