INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('789cc0ad-bfd8-4b0c-bc02-9bfda9b2d8c5', 'NC26.3.ANR.1', 3, 'choice', 'Equivalent forms: regroup place values', 'Maria says that $3{,}400$ is the same as 34 hundreds. Tom says that it is the same as 340 tens. Who is right?', '["Only Maria","Only Tom","Both Maria and Tom","Neither Maria nor Tom"]', 'Both Maria and Tom', NULL, '34 hundreds is $34 \times 100 = 3{,}400$. 340 tens is $340 \times 10 = 3{,}400$. Both are right.', 'checked', '{"lint":[],"solve":{"answer":"Both Maria and Tom","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34 hundreds = 3,400 and 340 tens = 3,400. Both correct.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
