INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5638761c-dfa8-443b-bb2d-6d2a958bb101', 'NC26.3.ANR.1', 3, 'numeric', 'Equivalent forms: regroup place values', 'Jon thinks of $5{,}306$ as 5 thousands, 3 hundreds and 6 ones. He trades 2 of the thousands for hundreds. Now the same number is 3 thousands, some hundreds and 6 ones. How many hundreds is that?', '[]', '23', '2*10+3', 'Each thousand is worth 10 hundreds, so 2 thousands is 20 hundreds. Add the 3 hundreds he already had: $20 + 3 = 23$ hundreds. (Now the number is 3 thousands, 23 hundreds and 6 ones, still 5,306.)', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trading 2 thousands gives 20 hundreds; 3 + 20 = 23 hundreds. Check: 3,000 + 2,300 + 6 = 5,306.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
