VALUES ('597999a8-7801-4347-a44d-17eae245d43f', 'NC26.3.ANR.1', 3, 'numeric', 'Mentally add multiples of 10, 100 or 1,000', 'What is $6{,}950 + 70$?', '[]', '7020', '6950+70', '$6{,}950 + 50 = 7{,}000$, because 95 tens plus 5 tens is 100 tens. The other 20 is still to add: $7{,}000 + 20 = 7{,}020$.', 'checked', '{"lint":[],"solve":{"answer":"7020","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,950 + 70: 6,950 + 50 = 7,000; + 20 = 7,020.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
