INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84c3addf-4957-4014-971b-5c9cc3790feb', 'NC26.3.ANR.1', 3, 'choice', 'Mentally add multiples of 10, 100 or 1,000', 'Which sum equals $5{,}000$?', '["$4{,}600 + 400$","$4{,}600 + 40$","$4{,}060 + 400$","$4{,}500 + 400$"]', '$4{,}600 + 400$', NULL, '46 hundreds plus 4 hundreds is 50 hundreds, which is 5,000. The other sums are 4,640, 4,460 and 4,900.', 'checked', '{"lint":[],"solve":{"answer":"$4{,}600 + 400$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,600 + 400 = 5,000. 4,500 + 400 = 4,900. 4,060 + 400 = 4,460. 4,600 + 40 = 4,640. Only the first.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
