INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('862ac290-74c5-458f-9029-1a8c9ab1a05c', 'NC26.3.ANR.1', 3, 'numeric', 'Mentally add multiples of 10, 100 or 1,000', 'What number makes $3{,}200 + ? = 4{,}500$ true?', '[]', '1300', '4500-3200', '3,200 is 32 hundreds and 4,500 is 45 hundreds. $45 - 32 = 13$, so the missing number is 13 hundreds, or 1,300. Check: $3{,}200 + 1{,}300 = 4{,}500$.', 'checked', '{"lint":[],"solve":{"answer":"1300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,500 - 3,200 = 1,300. Check 3,200 + 1,300 = 4,500.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
