VALUES ('57d6182a-81f7-4c63-b268-beaf84cdc17a', 'NC26.3.ANR.2', 1, 'numeric', 'Add or subtract by place value', 'Find $624 - 301$ by taking away the 3 hundreds first and then the 1 one. What is the answer?', '[]', '323', '624-301', '$624 - 300 = 324$. Then take away the 1 one: $324 - 1 = 323$.', 'checked', '{"lint":[],"solve":{"answer":"323","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"624 - 300 = 324; 324 - 1 = 323.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
