VALUES ('6e0f4d27-6efe-44f2-9a19-86bb1f6ee89e', 'NC26.3.ANR.2', 1, 'numeric', 'Add or subtract by place value', 'Tess finds $135 + 62$ by adding 60 to 135 first and then adding 2. What is the sum?', '[]', '197', '135+62', '$135 + 60 = 195$. Then $195 + 2 = 197$.', 'checked', '{"lint":[],"solve":{"answer":"197","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"135 + 60 = 195; 195 + 2 = 197.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
