INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29880fb0-b581-46c5-badc-031d7044337c', 'NC26.3.ANR.2', 2, 'choice', 'Add by place value (expanded form)', 'Sam adds $364 + 258$ by adding the hundreds, then the tens, then the ones. Which choice shows his steps?', '["300 + 200, then 60 + 50, then 4 + 5","300 + 20, then 60 + 5, then 4 + 8","300 + 200, then 6 + 5, then 4 + 8","300 + 200, then 60 + 50, then 4 + 8"]', '300 + 200, then 60 + 50, then 4 + 8', NULL, '364 = 300 + 60 + 4 and 258 = 200 + 50 + 8. So the hundreds are 300 + 200, the tens are 60 + 50, and the ones are 4 + 8. (500 + 110 + 12 = 622.)', 'checked', '{"lint":[],"solve":{"answer":"300 + 200, then 60 + 50, then 4 + 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"364 = 300+60+4, 258 = 200+50+8. Hundreds 300+200, tens 60+50, ones 4+8. Only the last option has all three right.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c5af546-c519-4d78-9aa0-d5be19c75673', 'NC26.3.ANR.2', 2, 'choice', 'Subtract in a story with regrouping twice', 'A school has 453 students. Of these, 178 ride the bus. How many students do not ride the bus?', '["285","275","325","631"]', '275', '453-178', 'Subtract: 453 − 178. Ones: trade a ten, 13 − 8 = 5. Tens: now 4 tens, so trade a hundred, 14 − 7 = 7. Hundreds: now 3 hundreds, 3 − 1 = 2. The answer is 275. Check: 275 + 178 = 453.', 'checked', '{"lint":[],"solve":{"answer":"275","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"453 - 178: 453 - 200 = 253, + 22 = 275. Check 275 + 178 = 453.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
