INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52917678-413d-49dc-8e65-191a4c88e667', 'NC26.3.ANR.2', 2, 'choice', 'Subtract in a story (take away or compare)', 'A zoo has 713 animals. Of these, 289 are birds. How many of the animals are not birds?', '["576","424","534","1,002"]', '424', '713-289', 'Subtract: $713 - 289$. Ones: trade a ten, $13 - 9 = 4$. Tens: now 0 tens, so trade a hundred, $10 - 8 = 2$. Hundreds: now 6 hundreds, $6 - 2 = 4$. The answer is 424. Check: $424 + 289 = 713$.', 'checked', '{"lint":[],"solve":{"answer":"424","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"713 - 289 = 713 - 300 + 11 = 413 + 11 = 424. Check 289 + 424 = 713.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4263de6-27f2-4435-a3a7-fcd0ff22e690', 'NC26.3.ANR.2', 2, 'numeric', 'Find the unknown in a story', 'A library had 329 books. After a delivery it had 512 books. How many books were delivered?', '[]', '183', '512-329', 'Books delivered: $329 + ? = 512$, so $? = 512 - 329$. Ones: trade a ten, $12 - 9 = 3$. Tens: now 0 tens, so trade a hundred, $10 - 2 = 8$. Hundreds: $4 - 3 = 1$. The answer is 183. Check: $329 + 183 = 512$.', 'checked', '{"lint":[],"solve":{"answer":"183","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"329 + ? = 512; 512 - 329 = 183. Check 329 + 183 = 512.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b7d096-44d3-4ae9-a3ff-60a1de75df52', 'NC26.3.ANR.2', 2, 'choice', 'Find the unknown in a story', 'Bo has 245 points in a game. He needs 600 points to win a prize. How many more points does he need?', '["845","355","455","365"]', '355', '600-245', 'Find $600 - 245$. Count up from 245 to 250 is 5, from 250 to 300 is 50, and from 300 to 600 is 300. $5 + 50 + 300 = 355$. Check: $245 + 355 = 600$.', 'checked', '{"lint":[],"solve":{"answer":"355","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 - 245 = 355. Check 245 + 355 = 600.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f0ceb33-f44e-47e8-b08d-7e08c4e54c07', 'NC26.3.ANR.2', 2, 'numeric', 'Find the unknown in a story', 'After 276 people left a theater, 349 people were still inside. How many people were in the theater before anyone left?', '[]', '625', '349+276', 'The people before = the people who left + the people still inside. $276 + 349$: ones $6 + 9 = 15$, tens $7 + 4 + 1 = 12$, hundreds $2 + 3 + 1 = 6$. The answer is 625.', 'checked', '{"lint":[],"solve":{"answer":"625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start - 276 = 349, so start = 349 + 276 = 625.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('020acb22-ed64-49d2-ad72-94e9b7c13d17', 'NC26.3.ANR.2', 2, 'numeric', 'Add or subtract by place value', 'Lia finds $752 - 238$ by taking away 200, then 30, then 8. What is the answer?', '[]', '514', '752-238', '$752 - 200 = 552$. $552 - 30 = 522$. $522 - 8 = 514$.', 'checked', '{"lint":[],"solve":{"answer":"514","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"752 - 200 = 552; 552 - 30 = 522; 522 - 8 = 514.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
