INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb86cf4b-9fa0-489c-80c0-baeb1a4c571a', 'NC26.3.ANR.2', 2, 'choice', 'Strategies and properties of addition and subtraction', 'Which number sentence is true?', '["$215 - 85 = 85 - 215$","$(215 + 85) + 40 = 215 + (85 + 40)$","$(215 - 85) - 40 = 215 - (85 - 40)$","$215 + 85 = 215 - 85$"]', '$(215 + 85) + 40 = 215 + (85 + 40)$', NULL, 'In addition, the numbers can be grouped in any way: $(215 + 85) + 40 = 300 + 40 = 340$ and $215 + (85 + 40) = 215 + 125 = 340$. Subtraction does not work that way: for example $(215 - 85) - 40 = 90$ but $215 - (85 - 40) = 170$.', 'checked', '{"lint":[],"solve":{"answer":"$(215 + 85) + 40 = 215 + (85 + 40)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: option B contains 85 - 215, a smaller-minus-larger subtraction Grade 3 students have not met; still clearly not the answer.","work":"A: 300 vs 130, false. B: 85 - 215 is not a whole number, false. C: 300 + 40 = 340 and 215 + 125 = 340, true (associative). D: 130 - 40 = 90 vs 215 - 45 = 170, false.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a64a5486-b935-4a44-a6f8-94cecf6fa398', 'NC26.3.ANR.2', 2, 'numeric', 'Strategies and properties of addition and subtraction', 'Subtract by counting up. To find $500 - 468$, count up from 468 to 500. How many do you count up?', '[]', '32', '500-468', 'From 468 up to 470 is 2. From 470 up to 500 is 30. $2 + 30 = 32$. So $500 - 468 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"468 to 470 is 2, 470 to 500 is 30. 2 + 30 = 32.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('828ae92c-7e26-48b2-afbd-5ffca97e2fb3', 'NC26.3.ANR.2', 2, 'choice', 'Strategies and properties of addition and subtraction', 'Which expression has the same value as $603 - 297$?', '["$600 - 300$","$603 - 300$","$606 - 297$","$606 - 300$"]', '$606 - 300$', NULL, 'Adding the same number to both parts of a subtraction keeps the difference the same. Adding 3 to both numbers: $603 + 3 = 606$ and $297 + 3 = 300$. So $603 - 297 = 606 - 300 = 306$.', 'checked', '{"lint":[],"solve":{"answer":"$606 - 300$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"603 - 297 = 306. Add 3 to both: 606 - 300 = 306. Others: 309, 303, 300.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce0cd45f-b8df-4388-94e5-db9d9cfc062d', 'NC26.3.ANR.2', 2, 'numeric', 'Strategies and properties of addition and subtraction', 'Jess finds $145 + 78$ by adding $145 + 80$ and then taking away 2. What does she get?', '[]', '223', '145+78', '$145 + 80 = 225$. Then take away 2: $225 - 2 = 223$. (78 is 2 less than 80, so the sum is 2 less.)', 'checked', '{"lint":[],"solve":{"answer":"223","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"145 + 80 = 225; 225 - 2 = 223. Check 145 + 78 = 223.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
