VALUES ('f3c65d0d-de0e-43e2-8cc0-c564dd58b8f8', 'NC26.3.ANR.2', 2, 'choice', 'Add with regrouping', 'Add: $356 + 278$.', '["634","624","534","524"]', '634', '356+278', 'Ones: $6 + 8 = 14$, write 4 and carry 1 ten. Tens: $5 + 7 + 1 = 13$, write 3 and carry 1 hundred. Hundreds: $3 + 2 + 1 = 6$. The sum is 634.', 'checked', '{"lint":[],"solve":{"answer":"634","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"356 + 278: 500 + 120 + 14 = 634.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
