INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed929a03-215f-47ab-8e89-20e7820f552d', 'NC26.3.ANR.2', 3, 'numeric', 'Add in a story', 'Three classes collected 189, 215 and 276 stamps. How many stamps did they collect in all?', '[]', '680', '189+215+276', 'Add the first two: $189 + 215 = 404$. Then add the third: $404 + 276 = 680$. They collected 680 stamps.', 'checked', '{"lint":[],"solve":{"answer":"680","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"189 + 215 = 404; 404 + 276 = 680.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
