INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a936d1ff-0a66-48b4-8461-3a0b8105632d', 'NC26.3.ANR.2', 3, 'choice', 'Add in a story', 'A park had 548 visitors in the morning and 375 visitors in the afternoon. How many visitors came in all?', '["913","923","823","813"]', '923', '548+375', 'Ones: $8 + 5 = 13$, write 3 and carry 1 ten. Tens: $4 + 7 + 1 = 12$, write 2 and carry 1 hundred. Hundreds: $5 + 3 + 1 = 9$. The total is 923 visitors.', 'checked', '{"lint":[],"solve":{"answer":"923","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"548 + 375: 500 + 300 = 800, 40 + 70 = 110, 8 + 5 = 13. 800 + 110 + 13 = 923.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
