INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2409872e-26d3-4c85-b283-62e34d000417', 'NC26.3.ANR.2', 3, 'choice', 'Subtract in a story (take away or compare)', 'Dan scored 645 points in game one and 387 points in game two. How many more points did he score in game one than in game two?', '["258","342","268","358"]', '258', '645-387', 'Find the difference: $645 - 387$. Ones: trade a ten, $15 - 7 = 8$. Tens: now 3 tens, so trade a hundred, $13 - 8 = 5$. Hundreds: now 5 hundreds, $5 - 3 = 2$. The answer is 258. Check: $387 + 258 = 645$.', 'checked', '{"lint":[],"solve":{"answer":"258","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"645 - 387 = 645 - 400 + 13 = 245 + 13 = 258. Check 387 + 258 = 645.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
