INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7c0c597-ef3e-42b0-9a8e-effee9613277', 'NC26.3.ANR.2', 3, 'numeric', 'Find the unknown in a story', 'Chen put 186 coins into a jar. The jar now has 431 coins. How many coins were in the jar before Chen put his coins in?', '[]', '245', '431-186', 'Coins before + 186 = 431, so coins before = $431 - 186$. Ones: trade, $11 - 6 = 5$. Tens: now 2 tens, $12 - 8 = 4$ (trade a hundred). Hundreds: now 3 hundreds, $3 - 1 = 2$. The answer is 245. Check: $245 + 186 = 431$.', 'checked', '{"lint":[],"solve":{"answer":"245","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? + 186 = 431; 431 - 186 = 245. Check 245 + 186 = 431.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
