INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5f89fca-01ae-422f-8ef8-b89e63c5f825', 'NC26.3.ANR.2', 3, 'numeric', 'Find the unknown in a story', 'Marcus read 168 pages on Monday. On Tuesday he read some more pages. By the end of Tuesday he had read 391 pages in all. How many pages did he read on Tuesday?', '[]', '223', '391-168', 'Pages on Tuesday = all the pages minus Monday''s pages = $391 - 168$. Ones: $11 - 8 = 3$ (trade). Tens: $8 - 6 = 2$. Hundreds: $3 - 1 = 2$. The answer is 223. Check: $168 + 223 = 391$.', 'checked', '{"lint":[],"solve":{"answer":"223","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"168 + ? = 391; 391 - 168 = 223. Check 168 + 223 = 391.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
