INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a2892d6-de76-4fce-bd62-ef5bd9884620', 'NC26.3.ANR.2', 3, 'choice', 'Add or subtract by place value', 'Mina finds $538 - 276$ by splitting 276 into $200 + 70 + 6$ and subtracting 200 first, then 70, then 6. Which choice shows her three steps correctly?', '["$538 - 200 = 338$, $338 - 70 = 278$, $278 - 6 = 272$","$538 - 200 = 438$, $438 - 70 = 368$, $368 - 6 = 362$","$538 - 200 = 338$, $338 - 70 = 268$, $268 - 6 = 264$","$538 - 200 = 338$, $338 - 70 = 268$, $268 - 6 = 262$"]', '$538 - 200 = 338$, $338 - 70 = 268$, $268 - 6 = 262$', NULL, '$538 - 200 = 338$. Then $338 - 70 = 268$, because 33 tens minus 7 tens is 26 tens, so 268. Then $268 - 6 = 262$. The other choices each have one wrong step. Check: $262 + 276 = 538$.', 'checked', '{"lint":[],"solve":{"answer":"$538 - 200 = 338$, $338 - 70 = 268$, $268 - 6 = 262$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"538 - 200 = 338; 338 - 70 = 268; 268 - 6 = 262. Option B. A ends 264 (wrong), C 538 - 200 = 438 (wrong), D 338 - 70 = 278 (wrong).","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87f96e83-87b2-44d1-9fac-ec87d3e98034', 'NC26.3.ANR.2', 3, 'numeric', 'Add or subtract by place value', 'Zara adds $467 + 235$ by place value. She adds the hundreds, the tens and the ones separately and gets $600 + 90 + 12$. What is the sum of those three parts?', '[]', '702', '600+90+12', '$600 + 90 = 690$, and $690 + 12 = 702$. So $467 + 235 = 702$.', 'checked', '{"lint":[],"solve":{"answer":"702","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 + 90 + 12 = 702. Check 467 + 235 = 702 (400+200, 60+30, 7+5).","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
