VALUES ('a5621432-9681-4c7a-bce7-83d2f3bf011f', 'NC26.3.ANR.2', 3, 'numeric', 'Subtract with regrouping', 'Find the difference: $706 - 389$.', '[]', '317', '706-389', 'Trade so that 7 hundreds, 0 tens, 6 ones becomes 6 hundreds, 9 tens, 16 ones. Ones: $16 - 9 = 7$. Tens: $9 - 8 = 1$. Hundreds: $6 - 3 = 3$. The answer is 317. Check: $317 + 389 = 706$.', 'checked', '{"lint":[],"solve":{"answer":"317","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"706 - 389 = 706 - 400 + 11 = 306 + 11 = 317. Check 389 + 317 = 706.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e52b06b4-63a2-4b05-b63e-5a16ec5cbc0a', 'NC26.3.ANR.2', 3, 'choice', 'Subtract with regrouping', 'Which difference equals 268?', '["$514 - 256$","$524 - 246$","$504 - 246$","$514 - 246$"]', '$514 - 246$', NULL, '$514 - 246$: ones $14 - 6 = 8$, tens $0 - 4$ means trade, so $10 - 4 = 6$, hundreds $4 - 2 = 2$. That is 268. The other differences are 258, 278 and 258.', 'checked', '{"lint":[],"solve":{"answer":"$514 - 246$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"504 - 246 = 258; 514 - 256 = 258; 524 - 246 = 278; 514 - 246 = 268. Only the last.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6583cc93-8486-4edf-9e87-422c4c844ab7', 'NC26.3.ANR.2', 3, 'numeric', 'Equation with a missing number or digit', 'What digit goes in the place of the ? to make $3?4 + 157 = 501$ true?', '[]', '4', '(501-157-304)/10', '$501 - 157 = 344$. So the three-digit number is 344, and the ? is 4. Check: $344 + 157 = 501$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3?4 = 501 - 157 = 344, so ? = 4. Check 344 + 157 = 501.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
