VALUES ('9e5b7f8b-def9-4400-a35a-7e08849829aa', 'NC26.3.ANR.2', 3, 'numeric', 'Equation with a missing number or digit', 'The difference between two numbers is 238. The smaller number is 457. What is the greater number?', '[]', '695', '457+238', 'The greater number is the smaller number plus the difference: $457 + 238 = 695$. Check: $695 - 457 = 238$.', 'checked', '{"lint":[],"solve":{"answer":"695","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greater = smaller + difference = 457 + 238 = 695. Check 695 - 457 = 238.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
