VALUES ('3881646d-f807-4842-9453-dc17c7031d79', 'NC26.3.ANR.3', 2, 'choice', 'Equal groups and multiplication sentences', 'Which repeated addition has the same total as $4 \times 6$?', '["$4 + 4 + 4 + 4 + 4$","$6 + 6 + 6$","$6 + 6 + 6 + 6$","$4 + 6$"]', '$6 + 6 + 6 + 6$', NULL, '$4 \times 6$ is 4 groups of 6, which is $6 + 6 + 6 + 6 = 24$. The other sums are 20, 18 and 10.', 'checked', '{"lint":[],"solve":{"answer":"$6 + 6 + 6 + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24. 4+4+4+4+4 = 20; 6+6+6 = 18; 6+6+6+6 = 24; 4+6 = 10. Only 6+6+6+6 totals 24.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
