INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('572ff38e-5cc2-46e9-8791-589bdd77ddb3', 'NC26.3.ANR.3', 3, 'choice', 'Breaking a factor apart to multiply', 'Which expression does NOT equal $8 \times 4$?', '["$(4 \\times 4) + (4 \\times 4)$","$(5 \\times 4) + (3 \\times 4)$","$(2 \\times 4) + (6 \\times 4)$","$(6 \\times 4) + (3 \\times 4)$"]', '$(6 \times 4) + (3 \times 4)$', NULL, '$8 \times 4 = 32$. The groups $4 + 4$, $5 + 3$ and $2 + 6$ all make 8, so they give 32. But $6 + 3 = 9$ groups of 4 is 36.', 'checked', '{"lint":[],"solve":{"answer":"$(6 \\times 4) + (3 \\times 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 4 = 32. 16+16 = 32; 8+24 = 32; 24+12 = 36; 20+12 = 32. Only (6 x 4) + (3 x 4) is not 32 (it is 9 x 4).","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d90dbb09-090d-4d55-89e5-db2dbed70a49', 'NC26.3.ANR.3', 3, 'choice', 'Breaking a factor apart to multiply', 'Omar knows that 10 groups of 8 make 80. He takes away 1 group of 8 to find 9 groups of 8. How many are in 9 groups of 8?', '["64","72","79","88"]', '72', '80-8', 'Take one group of 8 away from 80: $80 - 8 = 72$. So $9 \times 8 = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 - 8 = 72.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
