INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a886e3a-c9a3-487c-8449-84f2e47aff04', 'NC26.3.ANR.3', 3, 'choice', 'Equal-groups word problems', 'Ari bought 4 boxes of markers with 6 markers in each box. Then he lost 5 markers. How many markers does he have now?', '["5","24","29","19"]', '19', '4*6-5', 'First find all the markers: $4 \times 6 = 24$. Then take away the 5 he lost: $24 - 5 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 markers, 24 - 5 = 19.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
