VALUES ('0d846183-6701-4411-adea-e5b4ade34196', 'NC26.3.ANR.4', 1, 'choice', 'Use a multiplication fact to divide (fact families)', 'Which multiplication fact helps you find $27 \div 3$?', '["$3 \\times 9 = 27$","$27 \\times 3 = 81$","$27 + 3 = 30$","$27 - 3 = 24$"]', '$3 \times 9 = 27$', NULL, '$27 \div 3$ asks "3 times what number makes 27?". The fact $3 \times 9 = 27$ answers it, so $27 \div 3 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 9 = 27$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 / 3 is the missing factor in 3 x ? = 27; 3 x 9 = 27 is the related fact.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
