INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e54fa81b-887e-4360-b3a9-82ebeb5235ae', 'NC26.3.ANR.4', 2, 'choice', 'Division as repeated subtraction or skip counting', 'Which is the correct way to find $27 \div 9$ by skip counting?', '["Count by 9s to 27: 9, 18, 27. The last number is 27, so the answer is 27.","Count by 9s to 27: 9, 18, 27. That is 3 counts, so the answer is 3.","Count by 3s to 27: 3, 6, 9, 12, 15, 18, 21, 24, 27. That is 9 counts, so the answer is 9.","Count by 9s to 27: 9, 18, 27. The first number is 9, so the answer is 9."]', 'Count by 9s to 27: 9, 18, 27. That is 3 counts, so the answer is 3.', NULL, 'To find $27 \div 9$, count by 9s until you reach 27 and count how many numbers you said: 9, 18, 27 is 3 counts. So $27 \div 9 = 3$. Counting by 3s finds $27 \div 3$ instead.', 'checked', '{"lint":[],"solve":{"answer":"Count by 9s to 27: 9, 18, 27. That is 3 counts, so the answer is 3.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 / 9 = 3. Counting by 9s: 9, 18, 27 is 3 counts, answer 3. Other options give 9 or 27.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
