INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('976fb5f1-e2f8-44a8-a3bd-9a838d80a525', 'NC26.3.ANR.4', 2, 'choice', 'Write or match an equation for a division story', 'A baker packs 48 rolls into bags of 6 rolls each. Let $b$ be the number of bags. Which equation can be used to find $b$?', '["$6 \\times b = 48$","$6 \\times 48 = b$","$48 + 6 = b$","$48 \\times b = 6$"]', '$6 \times b = 48$', NULL, '$b$ bags with 6 rolls each make 48 rolls, so $6 \times b = 48$. That is the same as $48 \div 6 = b$, so $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times b = 48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b bags of 6 make 48: 6 x b = 48 (b = 8). Others wrong.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5826e1a-a096-4450-93a7-d8d1c5bf04f2', 'NC26.3.ANR.4', 2, 'choice', 'Write or match an equation for a division story', 'Ruth puts 54 books into 6 equal stacks. Let $s$ be the number of books in each stack. Which equation does NOT fit this story?', '["$54 \\div 6 = s$","$6 \\times s = 54$","$s \\times 6 = 54$","$54 - 6 = s$"]', '$54 - 6 = s$', NULL, 'Equal stacks of $s$ books, 6 stacks, 54 books in all: $54 \div 6 = s$, $6 \times s = 54$ and $s \times 6 = 54$ all fit. Subtracting 6 from 54 does not describe putting books into equal stacks.', 'checked', '{"lint":[],"solve":{"answer":"$54 - 6 = s$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = 54 / 6 = 9; 6 x s = 54 and s x 6 = 54 also fit. 54 - 6 = 48 does not fit.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bfec64e-2ee3-46c0-9e1c-2c8e9f7c78f6', 'NC26.3.ANR.4', 2, 'choice', 'Meaning of the quotient and the divisor', 'In a division equation, the divisor is the number you divide by. In $63 \div 9 = 7$, which number is the divisor?', '["9","63","7","Both 9 and 7"]', '9', '9', 'You divide 63 by 9, so 9 is the divisor. The 63 is the number being divided and 7 is the quotient.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dividing 63 by 9: divisor is 9.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('436db093-deb9-4e44-af84-9587809caaa0', 'NC26.3.ANR.4', 2, 'choice', 'Meaning of the quotient and the divisor', 'In $48 \div 8 = 6$, the answer 6 is called the quotient. 48 apples are put into bags with 8 apples in each bag. What does the quotient tell you?', '["The number of apples in each bag","The total number of apples","The number of apples left over","The number of bags"]', 'The number of bags', NULL, 'Each bag holds 8 apples, so 8 is the size of each group. The quotient 6 tells how many bags are filled.', 'checked', '{"lint":[],"solve":{"answer":"The number of bags","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 apples, 8 per bag: 48 / 8 = 6 bags. The quotient is the number of bags.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0313092b-7c98-4711-8612-8dc2b41c7263', 'NC26.3.ANR.4', 2, 'numeric', 'Meaning of the quotient and the divisor', 'Nora divides 56 plums into 8 equal groups, and each group has 7 plums. If she makes groups of 8 plums instead, how many groups will there be?', '[]', '7', '56/8', '$56 \div 8 = 7$ can be read two ways: 8 groups of 7, or groups of 8 that make 7 groups. With groups of 8 plums there are 7 groups.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 plums in groups of 8: 56 / 8 = 7 groups.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9e99df4-e827-4b90-b98e-5e69feac1dc0', 'NC26.3.ANR.4', 2, 'choice', 'Dividing by 1 and dividing a number by itself', 'Which equation is true?', '["$12 \\div 1 = 1$","$12 \\div 12 = 12$","$1 \\div 12 = 12$","$12 \\div 12 = 1$"]', '$12 \div 12 = 1$', NULL, 'Any number other than 0 divided by itself is 1, so $12 \div 12 = 1$. Dividing 12 by 1 gives 12, not 1.', 'checked', '{"lint":[],"solve":{"answer":"$12 \\div 12 = 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 1 = 12, not 1; 1 / 12 is not 12; 12 / 12 = 1, not 12. True: 12 / 12 = 1.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87745991-3170-4c0e-bc24-8fdf75a5ed10', 'NC26.3.ANR.4', 2, 'numeric', 'Division strategy: break the total into easier facts', 'Max finds $42 \div 6$ by splitting 42 into 30 and 12. He knows $30 \div 6 = 5$ and $12 \div 6 = 2$. What is $42 \div 6$?', '[]', '7', '30/6+12/6', 'Add the two parts: $5 + 2 = 7$. So $42 \div 6 = 7$. Check: $6 \times 7 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42 = 30 + 12; 5 + 2 = 7. Check 6 x 7 = 42.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('820054ee-fb22-422a-a0d5-8a76b1d23db1', 'NC26.3.ANR.4', 2, 'choice', 'Division strategy: break the total into easier facts', 'Which pair of easier facts helps find $56 \div 7$?', '["$35 \\div 7$ and $20 \\div 7$","$35 \\div 7$ and $21 \\div 7$","$28 \\div 7$ and $24 \\div 7$","$35 \\div 5$ and $21 \\div 3$"]', '$35 \div 7$ and $21 \div 7$', NULL, '$56 = 35 + 21$, and both 35 and 21 are multiples of 7: $35 \div 7 = 5$ and $21 \div 7 = 3$. Then $5 + 3 = 8$. In the other pairs the parts do not add to 56, are not multiples of 7, or change the divisor.', 'checked', '{"lint":[],"solve":{"answer":"$35 \\div 7$ and $21 \\div 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 = 35 + 21, both multiples of 7: 5 + 3 = 8. 28 + 24 = 52 and 35 + 20 = 55 do not make 56 (24, 20 not multiples of 7); 35/5 and 21/3 use wrong divisors.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f155c2d8-8bad-42e3-ad14-7c461ce865a8', 'NC26.3.ANR.4', 3, 'numeric', 'Equation with an unknown dividend', 'A number divided by 6 is 7. What is the number?', '[]', '42', '7*6', 'Division and multiplication undo each other. If a number split into groups of 6 gives 7 groups, then the number is $7 \times 6 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? / 6 = 7, so ? = 6 x 7 = 42.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a15f83c-ed9b-4f8a-ae51-73486610acf9', 'NC26.3.ANR.4', 3, 'choice', 'Write an equation for a division story', '24 students are split into 4 teams with the same number of students on each team. Let $n$ be the number of students on each team. Which equation can be used to find $n$?', '["$n \\times 24 = 4$","$24 \\times 4 = n$","$n + 4 = 24$","$4 \\times n = 24$"]', '$4 \times n = 24$', NULL, '4 teams with $n$ students each is $4 \times n$, and that equals 24 students. So $4 \times n = 24$, which gives $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times n = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 teams of n students make 24: 4 x n = 24 (n = 6). Other equations are wrong.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a950668-d804-4f5e-bdbd-3f5fea04b409', 'NC26.3.ANR.4', 3, 'choice', 'Meaning of the quotient', '72 buttons are put into equal groups of 9 buttons, and $72 \div 9 = 8$. What does the 8 tell you?', '["The number of buttons in each group","The total number of buttons","The number of buttons left over","The number of groups"]', 'The number of groups', NULL, 'Each group has 9 buttons (that is the divisor). The total is 72. The answer 8 tells how many groups of 9 can be made.', 'checked', '{"lint":[],"solve":{"answer":"The number of groups","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Groups of 9 is the group size; 72 / 9 = 8 tells how many groups.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af711ec3-cd87-435a-8dce-1feae2ee2230', 'NC26.3.ANR.4', 3, 'numeric', 'Share equally: find the size of each group', 'A teacher has 4 packs of 9 markers. She shares all of the markers equally among 6 tables. How many markers does each table get?', '[]', '6', '4*9/6', 'There are $4 \times 9 = 36$ markers in all. Sharing them among 6 tables gives $36 \div 6 = 6$ markers for each table.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total markers 4 x 9 = 36. Shared among 6 tables: 36 / 6 = 6.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e7c909f-b645-46cc-9fff-50124d7721e8', 'NC26.3.ANR.4', 3, 'numeric', 'Share equally: find the size of each group', 'Hana had 50 marbles. She gave 5 of them to her cousin, then shared the rest equally among 5 friends. How many marbles did each friend get?', '[]', '9', '(50-5)/5', 'After giving 5 away, Hana has $50 - 5 = 45$ marbles. Sharing them among 5 friends gives $45 \div 5 = 9$ marbles each.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 5 = 45 left. 45 / 5 = 9 each.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a4a5e77-a7ad-4e08-9ce8-d1f367929151', 'NC26.3.ANR.4', 3, 'choice', 'Share equally: find the size of each group', 'Four groups of friends each share some fruit equally. In which group does each friend get the most?', '["24 figs shared among 3 friends","30 pears shared among 5 friends","28 plums shared among 4 friends","35 nuts shared among 7 friends"]', '24 figs shared among 3 friends', NULL, 'Work out each share: $30 \div 5 = 6$, $28 \div 4 = 7$, $24 \div 3 = 8$, $35 \div 7 = 5$. The largest share is 8, from 24 figs shared among 3 friends. The group with the most fruit (35) does not give the biggest share.', 'checked', '{"lint":[],"solve":{"answer":"24 figs shared among 3 friends","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor wording: the stem says each group shares ''fruit'' but one option is nuts, which a child may not think of as fruit. Does not affect the answer; ''some food'' would be cleaner.","work":"35/7 = 5, 24/3 = 8, 28/4 = 7, 30/5 = 6. Largest share is 8: figs.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d18dd54-ef4a-4b3f-8882-d60e2d917759', 'NC26.3.ANR.4', 3, 'choice', 'Share equally: find the size of each group', 'Omar packs 72 pencils into 9 equal boxes. He then puts 3 of the boxes into a bag. How many pencils are in the bag?', '["8","27","69","24"]', '24', '72/9*3', 'Each box has $72 \div 9 = 8$ pencils. Three boxes have $3 \times 8 = 24$ pencils. The choice 8 stops after one box, 27 multiplies 3 by 9, and 69 takes 3 from 72.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 / 9 = 8 pencils per box. 3 boxes: 3 x 8 = 24.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e455605-ad60-4251-8f07-b5b793d63ebc', 'NC26.3.ANR.4', 3, 'numeric', 'Make equal groups: find the number of groups', 'Zoe has 3 bags with 12 oranges in each bag. She puts all the oranges into baskets of 9 oranges each. How many baskets does she fill?', '[]', '4', '3*12/9', 'There are $3 \times 12 = 36$ oranges. The number of baskets is $36 \div 9 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 12 = 36 oranges. 36 / 9 = 4 baskets.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13253354-1aee-481f-9674-cbe10c40848c', 'NC26.3.ANR.4', 3, 'choice', 'Make equal groups: find the number of groups', '24 children and 12 adults go on a trip. Everyone rides in vans, and every van is full with exactly 6 people. How many vans are there?', '["4","6","2","30"]', '6', '(24+12)/6', 'There are $24 + 12 = 36$ people in all. The number of vans is $36 \div 6 = 6$. The choice 4 counts only the children, 2 counts only the adults, and 30 subtracts 6 from 36.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 + 12 = 36 people. 36 / 6 = 6 vans.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4d26aac-a796-4aea-9c4d-2fec3e6b0b8a', 'NC26.3.ANR.4', 3, 'choice', 'Make equal groups: find the number of groups', 'Which number of marbles can be put into equal groups of 8 marbles with none left over?', '["54","60","64","70"]', '64', '64', 'Count by 8s: 8, 16, 24, 32, 40, 48, 56, 64. Only 64 is on the list, and $64 \div 8 = 8$. The other numbers fall between multiples of 8, so some marbles would be left over.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 8 near: 48, 56, 64, 72. Only 64 is a multiple (8 x 8). 54, 60, 70 leave remainders.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72a45978-04b2-4c87-865e-658f616b463c', 'NC26.3.ANR.4', 3, 'numeric', 'Division as repeated subtraction or skip counting', 'Ben has 54 beads. He makes bracelets with 6 beads each and keeps going until the beads run out. After he has made 3 bracelets, how many more bracelets can he make?', '[]', '6', '54/6-3', 'Taking away 6 beads at a time from 54 makes $54 \div 6 = 9$ bracelets in all. He has made 3, so he can make $9 - 3 = 6$ more.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 / 6 = 9 bracelets in all. After 3, 9 - 3 = 6 more. (Or 54 - 18 = 36, 36 / 6 = 6.)","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcf7f8fb-4fc5-4293-a100-be7c52cef5da', 'NC26.3.ANR.4', 3, 'numeric', 'Division as repeated subtraction or skip counting', 'Quinn takes 9 away from 81, then 9 away again, and keeps going until nothing is left. Then she does the same with 45. How many more times does she take away 9 from 81 than from 45?', '[]', '4', '81/9-45/9', 'From 81 she subtracts 9 a total of $81 \div 9 = 9$ times. From 45 she subtracts 9 a total of $45 \div 9 = 5$ times. The difference is $9 - 5 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81 / 9 = 9 subtractions; 45 / 9 = 5 subtractions. 9 - 5 = 4 more.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad9090ce-16a8-4e68-8bc6-d2c271f68e42', 'NC26.3.ANR.4', 3, 'numeric', 'Use a multiplication fact to divide (fact families)', 'Use $7 \times 8 = 56$ to find $56 \div 7$ and $56 \div 8$. What is the sum of the two quotients?', '[]', '15', '56/7+56/8', '$56 \div 7 = 8$ and $56 \div 8 = 7$. The sum is $8 + 7 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / 7 = 8, 56 / 8 = 7. Sum 8 + 7 = 15.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('059deb3a-4233-4762-afd3-5f44625ae818', 'NC26.3.ANR.4', 3, 'choice', 'Use a multiplication fact to divide (fact families)', 'Which equation is NOT from the same fact family as $6 \times 9 = 54$?', '["$54 \\div 3 = 18$","$9 \\times 6 = 54$","$54 \\div 9 = 6$","$54 \\div 6 = 9$"]', '$54 \div 3 = 18$', NULL, 'The fact family uses only 6, 9 and 54: $6 \times 9 = 54$, $9 \times 6 = 54$, $54 \div 6 = 9$ and $54 \div 9 = 6$. The equation $54 \div 3 = 18$ is true, but it uses 3 and 18, so it belongs to a different family.', 'checked', '{"lint":[],"solve":{"answer":"$54 \\div 3 = 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Family of 6, 9, 54: 54/9 = 6, 54/6 = 9, 9 x 6 = 54. 54 / 3 = 18 is true but uses 3 and 18, not in the family.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17916a17-e11e-4cfc-a79f-6c66522f150d', 'NC26.3.ANR.4', 3, 'numeric', 'Use a multiplication fact to divide (fact families)', 'Mia knows $4 \times 9 = 36$. She says, "$36 \div 4 = 9$, so $36 \div 9$ must also be 9." What is the correct value of $36 \div 9$?', '[]', '4', '36/9', 'Mia is mixing up the two quotients. From $4 \times 9 = 36$, $36 \div 4 = 9$ but $36 \div 9 = 4$. Check: $9 \times 4 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 9 = 36 so 36 / 9 = 4.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65618fc4-fc82-4b12-906b-a4fb4644fe61', 'NC26.3.ANR.4', 3, 'numeric', 'Array word problem: rows and columns', 'A music teacher puts 56 chairs in an array with 8 rows. Then 8 chairs are taken away, and the rest stay in 8 equal rows. How many chairs are in each row now?', '[]', '6', '(56-8)/8', 'After taking 8 chairs away, $56 - 8 = 48$ chairs are left. In 8 equal rows, each row has $48 \div 8 = 6$ chairs.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 - 8 = 48 chairs. 48 / 8 = 6 per row.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
