INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52b5b8c4-089c-4633-bd29-bc367eccad75', 'NC26.3.ANR.4', 3, 'choice', 'Array word problem: rows and columns', '45 tiles are put in an array with the same number of tiles in every row. Which could be the number of rows?', '["4","6","9","10"]', '9', '45/5', 'The number of rows must divide 45 with nothing left over. $45 \div 9 = 5$, so 9 rows of 5 tiles works. 4, 6 and 10 do not divide 45 evenly.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rows must divide 45. 45 / 9 = 5 works. 6, 4, 10 do not divide 45.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cae0e6b-928b-4808-a461-c25cd13831f0', 'NC26.3.ANR.4', 3, 'numeric', 'Array word problem: rows and columns', 'Rosa arranges bottle caps in an array with 4 rows and 6 caps in each row. She then puts all the caps into an array with 3 rows. How many caps are in each row now?', '[]', '8', '4*6/3', 'There are $4 \times 6 = 24$ caps. In 3 equal rows, each row has $24 \div 3 = 8$ caps.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 caps. 24 / 3 = 8 per row.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec7cc0b2-87ea-44fa-8dd0-fa72f4fa610c', 'NC26.3.ANR.4', 3, 'numeric', 'Equation with an unknown divisor', '$48 \div \square = 12 \div 2$. What number goes in the box?', '[]', '8', '48/(12/2)', 'First work out the right side: $12 \div 2 = 6$. Now $48 \div \square = 6$, and $48 \div 8 = 6$, so the box is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 2 = 6. 48 / ? = 6: 6 x 8 = 48, so 8.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e2d6209-40aa-40db-9d85-10a3c409b973', 'NC26.3.ANR.4', 3, 'choice', 'Equation with an unknown divisor', 'Which equation has the same solution for $n$ as $56 \div n = 7$?', '["$n \\times 56 = 7$","$n \\times 7 = 56$","$n + 7 = 56$","$7 \\div n = 56$"]', '$n \times 7 = 56$', NULL, 'If $56 \div n = 7$, then 7 groups of $n$ make 56, which is $n \times 7 = 56$. Both give $n = 8$. The other equations have different solutions.', 'checked', '{"lint":[],"solve":{"answer":"$n \\times 7 = 56$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / n = 7 gives n = 8. n + 7 = 56 gives 49; n x 7 = 56 gives 8; 7 / n = 56 and n x 56 = 7 have no whole solution 8.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cccae229-971a-4a14-ad8f-635adddb29f4', 'NC26.3.ANR.4', 3, 'numeric', 'Equation with an unknown divisor', '$63 \div \square = 7$. Anna then divides 36 by the same number. What is 36 divided by that number?', '[]', '4', '36/(63/7)', '$63 \div 9 = 7$, so the number is 9. Then $36 \div 9 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63 / ? = 7 gives 9. 36 / 9 = 4.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('968b964c-4154-4b58-b595-0943aec34a75', 'NC26.3.ANR.4', 3, 'numeric', 'Equation with an unknown dividend', '$\square \div 9 = 12 \div 3$. What number goes in the box?', '[]', '36', '9*(12/3)', 'First work out the right side: $12 \div 3 = 4$. Now $\square \div 9 = 4$, so the box is $9 \times 4 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 3 = 4. ? / 9 = 4: 9 x 4 = 36.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d9a56b6-171e-4174-8601-3616b41466f4', 'NC26.3.ANR.4', 3, 'choice', 'Equation with an unknown dividend', 'Eli thinks of a number. He divides it by 5, then adds 3, and gets 10. What was Eli''s number?', '["50","35","65","7"]', '35', '(10-3)*5', 'Work backward. Before adding 3 the result was $10 - 3 = 7$. Before dividing by 5 the number was $7 \times 5 = 35$. Check: $35 \div 5 = 7$ and $7 + 3 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Work backwards: 10 - 3 = 7; 7 x 5 = 35. Check 35 / 5 + 3 = 10. 65 gives 16, 7 is the quotient, 50 gives 13.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf6ccb59-2d5e-4513-a32c-eed9448e0b90', 'NC26.3.ANR.4', 3, 'choice', 'Write or match an equation for a division story', 'Sofia has 50 beads. She uses 8 of them on a key chain. She puts the rest of the beads into 6 equal bags. Let $x$ be the number of beads in each bag. Which equation can be used to find $x$?', '["$50 - 8 \\div 6 = x$","$(50 + 8) \\div 6 = x$","$(50 - 8) \\div 6 = x$","$50 \\div 6 - 8 = x$"]', '$(50 - 8) \div 6 = x$', NULL, 'The beads left are $50 - 8$, and that amount is shared among 6 bags: $(50 - 8) \div 6 = x$. So $x = 42 \div 6 = 7$. The parentheses make the subtraction happen first.', 'checked', '{"lint":[],"solve":{"answer":"$(50 - 8) \\div 6 = x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rest = 50 - 8 = 42; 42 / 6 = 7. Equation (50 - 8) / 6 = x. The unbracketed 50 - 8 / 6 would divide first.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dac52af8-16bd-4adf-b54e-40adfb77d323', 'NC26.3.ANR.4', 3, 'choice', 'Write or match an equation for a division story', 'Which story matches $\square \div 5 = 9$?', '["Some apples are shared equally among 5 baskets. Each basket gets 9 apples.","Some apples are in a basket. After 5 apples are eaten, 9 apples are left.","Some apples are in a basket. After 5 more apples are put in, there are 9 apples.","Some apples are shared equally among 4 baskets. Each basket gets 9 apples."]', 'Some apples are shared equally among 5 baskets. Each basket gets 9 apples.', NULL, '$\square \div 5 = 9$ means an unknown total shared equally among 5 baskets, with 9 in each basket. That is the first story, and the total is $5 \times 9 = 45$. The other stories are $\square - 5 = 9$, $\square + 5 = 9$ and $\square \div 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"Some apples are shared equally among 5 baskets. Each basket gets 9 apples.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? / 5 = 9: an unknown total shared among 5 groups giving 9 each. Option with 4 baskets is ? / 4; others are subtraction/addition.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d9cfdf9-14fb-41a8-8cd8-29943badf08b', 'NC26.3.ANR.4', 3, 'numeric', 'Write or match an equation for a division story', 'Eli writes $72 \div 8 = c$ for the number of cookies on each plate. He then writes $c \div 3 = d$ for the number of cookies each of 3 children gets from one plate. What is $d$?', '[]', '3', '72/8/3', '$c = 72 \div 8 = 9$. Then $d = 9 \div 3 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = 72 / 8 = 9. d = 9 / 3 = 3.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76e6c595-def2-4421-9b93-47fc5ea51087', 'NC26.3.ANR.4', 3, 'choice', 'Meaning of the quotient and the divisor', '$36 \div 9 = 4$. In which story does the 4 tell the number of groups?', '["36 stamps are shared equally among 9 friends. How many stamps does each friend get?","36 stamps are put on pages with 9 stamps on each page. How many pages are used?","There are 9 pages with 4 stamps on each page. How many stamps are there?","Dan has 36 stamps and gives 9 away. How many stamps does he have left?"]', '36 stamps are put on pages with 9 stamps on each page. How many pages are used?', NULL, 'With 9 stamps on each page, the number of pages is $36 \div 9 = 4$, so the 4 is a number of groups. In the friends story the 4 is the number in each share.', 'checked', '{"lint":[],"solve":{"answer":"36 stamps are put on pages with 9 stamps on each page. How many pages are used?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 as number of groups: 36 stamps, 9 per page, 36 / 9 = 4 pages. The sharing story gives 4 per friend (group size); the last is multiplication with 4 per page; the first is subtraction.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8e0ebd9-ab92-420a-814d-3f2246924393', 'NC26.3.ANR.4', 3, 'choice', 'Meaning of the quotient and the divisor', 'Which statement about $24 \div 6 = 4$ is true?', '["The 4 always tells the number of groups, however the story is told","The 4 always tells how many are in each group, however the story is told","Sharing 24 among 6 groups gives 4 in each group, and groups of 6 make 4 groups","The 6 always tells how many are in each group, however the story is told"]', 'Sharing 24 among 6 groups gives 4 in each group, and groups of 6 make 4 groups', NULL, 'A quotient can be the size of each group (24 shared among 6 groups is 4 each) or the number of groups (24 in groups of 6 is 4 groups). Which one it is depends on the story.', 'checked', '{"lint":[],"solve":{"answer":"Sharing 24 among 6 groups gives 4 in each group, and groups of 6 make 4 groups","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 6 = 4 can be sharing (4 in each of 6 groups) or measuring (4 groups of 6). So the 4 does not always mean groups or group size, and 6 is not always group size. Option A is true.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('538398fc-891e-4d43-91c2-9fd4b8a8c4fa', 'NC26.3.ANR.4', 3, 'numeric', 'Meaning of the quotient and the divisor', 'Ava puts 40 beads into groups of 5. Ben puts the same 40 beads into groups of 8. How many more groups does Ava make than Ben?', '[]', '3', '40/5-40/8', 'Ava makes $40 \div 5 = 8$ groups. Ben makes $40 \div 8 = 5$ groups. Ava makes $8 - 5 = 3$ more groups.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ava: 40 / 5 = 8 groups. Ben: 40 / 8 = 5 groups. 8 - 5 = 3.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('859f387c-c394-4fbe-b04f-e908b1eae953', 'NC26.3.ANR.4', 3, 'choice', 'Division strategy: break the total into easier facts', 'Ana knows $40 \div 8 = 5$. She wants to use it to find $80 \div 8$. What should she do next?', '["Add 5 and 8 to get 13","Subtract 5 from 40 to get 35","Double 5 to get 10","Multiply 5 by 8 to get 40"]', 'Double 5 to get 10', NULL, '80 is double 40, so there are twice as many groups of 8. Double 5 to get 10. Check: $10 \times 8 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"Double 5 to get 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 is double 40, so 80 / 8 is double 40 / 8: 2 x 5 = 10.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1f727ee-2acd-4353-a65a-77ac24820e20', 'NC26.3.ANR.4', 3, 'numeric', 'Division strategy: break the total into easier facts', 'Tess divides a number by 8 by splitting it into 40 and 24. She finds $40 \div 8 = 5$ and $24 \div 8 = 3$. What is the number she started with?', '[]', '64', '40+24', 'The two parts add up to the whole number: $40 + 24 = 64$. Check: $64 \div 8 = 8$, and $5 + 3 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number = 40 + 24 = 64. Check 64 / 8 = 8 = 5 + 3.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13954915-e9b1-4867-a42f-99fa131b1858', 'NC26.3.ANR.4', 3, 'choice', 'Division strategy: break the total into easier facts', 'Which way of splitting 72 is NOT helpful for finding $72 \div 9$?', '["$70 + 2$","$36 + 36$","$45 + 27$","$63 + 9$"]', '$70 + 2$', NULL, 'A helpful split uses parts that are multiples of 9. $36 + 36$, $45 + 27$ and $63 + 9$ all do. But 70 and 2 are not multiples of 9, so they are not easy to divide by 9.', 'checked', '{"lint":[],"solve":{"answer":"$70 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45+27 (5+3), 63+9 (7+1), 36+36 (4+4) all split into multiples of 9 and give 8. 70 + 2: neither part divides by 9, so not helpful.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a49a0ee4-9682-40ec-8b35-1af2def8aac6', 'NC26.3.ANR.4', 3, 'choice', 'Division as repeated subtraction or skip counting', 'Which way of finding $30 \div 5$ is NOT correct?', '["Skip count by 5s from 0 up to 30, and count the jumps","Subtract 5 from 30 again and again until you reach 0, and count the subtractions","Find the missing number in $5 + \\square = 30$","Find the missing number in $5 \\times \\square = 30$"]', 'Find the missing number in $5 + \square = 30$', NULL, 'Division asks how many 5s fit in 30, so skip counting by 5s, subtracting 5s until 0, and finding the missing factor in $5 \times \square = 30$ all work (each gives 6). The missing number in $5 + \square = 30$ is 25, which is a subtraction answer, not $30 \div 5$.', 'checked', '{"lint":[],"solve":{"answer":"Find the missing number in $5 + \\square = 30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Repeated subtraction, skip counting and 5 x ? = 30 all give 6. 5 + ? = 30 gives 25, not the quotient.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0d536ed-add5-48d8-b646-41f1cea38f43', 'NC26.3.ANR.5', 1, 'choice', 'Multiply by zero', 'What is $9 \times 0$?', '["0","9","1","90"]', '0', '9*0', 'Zero groups of 9 (or 9 groups of nothing) is nothing. Any number times 0 is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any number times 0 is 0.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
