INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d1c223e-80be-4fac-8df5-8a5b92d1efc3', 'NC26.3.ANR.5', 1, 'numeric', 'Multiplication fact with 5', 'What is $5 \times 7$?', '[]', '35', '5*7', 'Count by 5s seven times: 5, 10, 15, 20, 25, 30, 35. So $5 \times 7 = 35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 7 = 35.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
