INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('552f8d44-c87c-4ef8-a7d8-39a3c9d823c7', 'NC26.3.ANR.5', 1, 'choice', 'Explaining multiplication and division in context', '24 cookies are shared equally among 4 plates. Which number sentence shows how many cookies go on each plate?', '["$24 \\div 4 = 6$","$24 \\times 4 = 96$","$24 - 4 = 20$","$24 + 4 = 28$"]', '$24 \div 4 = 6$', NULL, 'Sharing equally is division: $24 \div 4 = 6$. Each plate gets 6 cookies.', 'checked', '{"lint":[],"solve":{"answer":"$24 \\div 4 = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sharing 24 equally among 4 plates is division: 24 / 4 = 6 per plate. The other sentences add, multiply or subtract.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f3d91d6-bcb4-403b-b738-f7f58a2b5153', 'NC26.3.ANR.5', 1, 'choice', 'Explaining multiplication and division in context', 'Sam writes $5 \times 3 = 15$ for 5 bags with 3 apples in each bag. What does 15 tell us?', '["the number of bags","the total number of apples","the number of apples in each bag","how many more apples than bags"]', 'the total number of apples', NULL, 'The 5 is the number of bags and the 3 is the number of apples in each bag. The product, 15, is the total number of apples.', 'checked', '{"lint":[],"solve":{"answer":"the total number of apples","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 bags x 3 apples each = 15: the product is the total number of apples.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e045025-1e4f-4fea-b52f-ae3a6ea1376b', 'NC26.3.ANR.5', 1, 'numeric', 'Explaining multiplication and division in context', 'Ava has 18 beads. She puts 3 beads on each bracelet and uses all of the beads. How many bracelets does she make?', '[]', '6', '18/3', 'Find how many groups of 3 are in 18: $18 \div 3 = 6$. She makes 6 bracelets.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 3 = 6 bracelets (6 x 3 = 18).","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1c6097f-a56d-4377-a93e-7027a5a7fa08', 'NC26.3.ANR.5', 1, 'numeric', 'Inverse relationship and fact families', 'You know that $3 \times 4 = 12$. What is $12 \div 4$?', '[]', '3', '12/4', 'Multiplication and division undo each other. Since $3 \times 4 = 12$, we get $12 \div 4 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 4 = 12, so 12 / 4 = 3.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('997196bc-1d88-4edb-8ed8-2c6eed63ef08', 'NC26.3.ANR.5', 1, 'choice', 'Inverse relationship and fact families', 'Which division fact is related to $2 \times 5 = 10$?', '["$5 \\div 10 = 2$","$2 \\div 5 = 10$","$10 \\div 10 = 2$","$10 \\div 5 = 2$"]', '$10 \div 5 = 2$', NULL, 'The product, 10, is divided by one of the factors. $10 \div 5 = 2$ is true and uses the same three numbers.', 'checked', '{"lint":[],"solve":{"answer":"$10 \\div 5 = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fact family 2, 5, 10: 10 / 5 = 2 and 10 / 2 = 5. 5 / 10, 2 / 5 and 10 / 10 = 2 are false.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
