INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('298d84cd-e3fd-4402-bf32-66f1b7630c6b', 'NC26.3.ANR.5', 2, 'numeric', 'Explaining multiplication and division in context', 'There are 7 days in 1 week. Zoe says that $4 \times 7$ tells the number of days in 4 weeks. How many days is that?', '[]', '28', '4*7', '4 weeks with 7 days in each week: $4 \times 7 = 28$ days.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 7 = 28 days.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
