INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ffa50e2-1375-42da-990a-9adc85511506', 'NC26.3.ANR.5', 2, 'choice', 'Inverse relationship and fact families', 'Which equation does NOT belong to the fact family for 4, 7 and 28?', '["$7 \\times 4 = 28$","$28 - 7 = 21$","$28 \\div 4 = 7$","$28 \\div 7 = 4$"]', '$28 - 7 = 21$', NULL, 'A fact family uses only multiplying or dividing with 4, 7 and 28. The subtraction fact does not belong.', 'checked', '{"lint":[],"solve":{"answer":"$28 - 7 = 21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fact family of 4, 7, 28 is 4 x 7, 7 x 4, 28 / 4, 28 / 7. 28 - 7 = 21 uses 21 and subtraction, not in the family.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
