INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55164658-5e17-4f28-80fb-5fa6d44e1afc', 'NC26.3.ANR.5', 3, 'numeric', 'Explaining multiplication and division in context', 'Lila bought 4 packs of 6 pencils. She shared all of the pencils equally among 3 friends. How many pencils does each friend get?', '[]', '8', '4*6/3', 'All the pencils: $4 \times 6 = 24$. Shared among 3 friends: $24 \div 3 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 pencils; 24 / 3 = 8 each.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
