INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eae3dcbc-ac2b-4395-bf02-3c5057f47e3b', 'NC26.3.ANR.5', 3, 'numeric', 'Inverse relationship and fact families', 'Use the fact $8 \times 6 = 48$ to find the value of $(48 \div 6) + (48 \div 8)$.', '[]', '14', '48/6+48/8', '$48 \div 6 = 8$ and $48 \div 8 = 6$. Then $8 + 6 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 6 = 8 and 48 / 8 = 6; 8 + 6 = 14.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
