INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a995f77d-4a79-4650-b85a-8b7454cb15a9', 'NC26.3.ANR.5', 3, 'choice', 'Inverse relationship and fact families', 'Mark says $24 \div 3 = 8$ because $3 \times 8 = 24$. Lena says $24 \div 3 = 21$ because $24 - 3 = 21$. Who is using the connection between multiplication and division correctly?', '["Lena","Mark","Both Mark and Lena","Neither Mark nor Lena"]', 'Mark', NULL, 'Division is checked by multiplying: $3 \times 8 = 24$, so Mark is right. Subtracting 3 does not give a quotient.', 'checked', '{"lint":[],"solve":{"answer":"Mark","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mark: 3 x 8 = 24 so 24 / 3 = 8, correct. Lena uses subtraction once and gets 21, wrong.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
