VALUES ('aa7eba02-976c-418e-a4c0-fb5b9cec8f9e', 'NC26.3.ANR.6', 1, 'choice', 'Choose the equation or expression for a story', 'Which expression shows 3 groups of 4, plus 2 more?', '["$3 + 4 + 2$","$3 \\times 4 + 2$","$3 \\times (4 + 2)$","$4 \\times 2 + 3$"]', '$3 \times 4 + 2$', NULL, '3 groups of 4 is $3 \times 4$, and then 2 more is added: $3 \times 4 + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 4 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 groups of 4 is 3 x 4; plus 2 more: 3 x 4 + 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
