INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a185355-d22c-41f2-b1b7-8f3911309c0a', 'NC26.3.ANR.6', 1, 'choice', 'Choose the equation or expression for a story', 'Leo has 10 stickers. He gets 4 more, and then he gives 3 away. Which expression shows how many stickers Leo has now?', '["$10 + 4 - 3$","$10 - 4 + 3$","$10 - 4 - 3$","$10 + 4 + 3$"]', '$10 + 4 - 3$', NULL, 'Getting 4 more adds 4, and giving 3 away subtracts 3: $10 + 4 - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$10 + 4 - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 10, add 4, subtract 3: 10 + 4 - 3 (= 11).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
