INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93a96a92-5881-40d2-92a6-8385e6b27089', 'NC26.3.ANR.6', 1, 'numeric', 'Find a missing amount in a two-step story', 'Zed has 2 boxes with 4 cars in each box and some cars in a bag. He has 11 cars in all. How many cars are in the bag?', '[]', '3', '11-2*4', 'The boxes hold $2 \times 4 = 8$ cars. The bag holds the rest: $11 - 8 = 3$ cars.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 4 = 8 in boxes; 11 - 8 = 3 in the bag.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
