INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2bcbcd-9bf8-4922-bf02-155bfda9741f', 'NC26.3.ANR.6', 1, 'choice', 'Decide what to find first, or decide with the total', 'Mia has 3 bags with 6 apples in each bag. She eats 2 apples. To find how many apples are left, what should Mia find first?', '["How many apples are in all 3 bags","How many apples she ate","How many bags she has","How many apples are in 2 bags"]', 'How many apples are in all 3 bags', NULL, 'The number eaten (2) and the number of bags (3) are given. She must first find the total in the bags, $3 \times 6 = 18$, and then subtract the 2.', 'checked', '{"lint":[],"solve":{"answer":"How many apples are in all 3 bags","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First find the total: 3 x 6 = 18, then subtract 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
