INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e524b638-a247-47d4-94d0-d8c9c0c972cb', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: multiply, then add more', 'A farmer plants 7 rows of corn with 6 plants in each row. He also plants 9 pumpkin plants. How many plants does he plant in all?', '[]', '51', '7*6+9', 'The corn is $7 \times 6 = 42$ plants. Adding the 9 pumpkin plants gives $42 + 9 = 51$.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 6 = 42 corn plants; 42 + 9 = 51.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
