INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5cf3753-aa6e-418d-b672-5c9c254f28da', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: multiply, then add more', 'A library has 8 tables. Each table has 4 chairs. There are also 5 chairs by the door. How many chairs are in the library in all?', '["37","32","17","72"]', '37', '8*4+5', 'The tables have $8 \times 4 = 32$ chairs, and $32 + 5 = 37$. The choice 32 forgets the door chairs, 17 adds 8 + 4 + 5, and 72 multiplies 8 by (4 + 5).', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 4 = 32 chairs at tables; 32 + 5 = 37.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
