INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16fbeb38-530b-4fc6-910a-c9ff9b84f9a1', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: multiply, then take away', 'A bakery makes 6 trays of 9 rolls each. By noon, 17 rolls have been sold. How many rolls are left?', '[]', '37', '6*9-17', 'The bakery made $6 \times 9 = 54$ rolls. After selling 17, $54 - 17 = 37$ rolls are left.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 9 = 54 rolls; 54 - 17 = 37.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
