INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76ccc3f2-6a22-4909-93a0-5ed5f467908e', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: multiply, then take away', 'Sara has 40 stickers. She puts 4 stickers on each of 7 cards. How many stickers does she have left?', '["12","29","68","33"]', '12', '40-7*4', 'She uses $7 \times 4 = 28$ stickers, and $40 - 28 = 12$ are left. The choice 29 takes away 7 and 4 separately, 68 adds the 28, and 33 takes away only the 7 cards.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 7 = 28 stickers used; 40 - 28 = 12.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
