INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('078c9bcd-a917-4002-8192-88be542996e2', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: add and subtract in a story', 'Kai has 52 stamps. He trades away 18 of them. Then he buys a new pack of 25 stamps. How many stamps does Kai have now?', '[]', '59', '52-18+25', 'After the trade Kai has $52 - 18 = 34$ stamps. Adding the new pack gives $34 + 25 = 59$ stamps.', 'checked', '{"lint":[],"solve":{"answer":"59","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 - 18 = 34; 34 + 25 = 59.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
