INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('054ad559-80e5-47a0-af24-7511181d7e4a', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: add or subtract first, then multiply', 'A club has 9 girls and 7 boys. Each member gets 4 pencils. How many pencils are needed?', '[]', '64', '(9+7)*4', 'The club has $9 + 7 = 16$ members. At 4 pencils each, $16 \times 4 = 64$ pencils.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 + 7 = 16 members; 16 x 4 = 64 pencils.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
