INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c104eee2-f87b-4a2d-ae35-cc7f0eae97a6', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: add two products', 'At a fruit stand, a bag of apples costs 4 dollars and a bag of pears costs 6 dollars. Kim buys 3 bags of apples and 2 bags of pears. How many dollars does she spend?', '[]', '24', '3*4+2*6', 'The apples cost $3 \times 4 = 12$ dollars and the pears cost $2 \times 6 = 12$ dollars. In all she spends $12 + 12 = 24$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 4 = 12 dollars on apples; 2 x 6 = 12 on pears; 12 + 12 = 24.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
