INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86976689-babf-48f0-9f7c-e6d83bb490b1', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: add two products', 'A pet store has 5 tanks with 6 fish in each tank and 4 tanks with 8 fish in each tank. How many fish are in the tanks in all?', '["72","54","62","23"]', '62', '5*6+4*8', 'The first tanks hold $5 \times 6 = 30$ fish and the others hold $4 \times 8 = 32$ fish, so $30 + 32 = 62$. The choice 72 treats all 9 tanks as having 8 fish, 54 treats them as having 6, and 23 adds all four numbers.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 6 = 30; 4 x 8 = 32; 30 + 32 = 62.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21a777f0-8a79-4eac-8713-573851e9cb48', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: compare two products', 'A red shelf has 9 rows with 4 books in each row. A blue shelf has 5 rows with 6 books in each row. How many more books are on the red shelf than on the blue shelf?', '[]', '6', '9*4-5*6', 'The red shelf holds $9 \times 4 = 36$ books. The blue shelf holds $5 \times 6 = 30$ books. The difference is $36 - 30 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 9 x 4 = 36; blue 5 x 6 = 30; 36 - 30 = 6.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f87e520e-839e-459a-b54e-547900f26531', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: compare two products', 'Each of 4 boxes holds 9 pens. Each of 5 cups holds 5 pens. How many more pens are in the boxes than in the cups?', '["61","25","11","3"]', '11', '4*9-5*5', 'The boxes hold $4 \times 9 = 36$ pens and the cups hold $5 \times 5 = 25$ pens. The difference is $36 - 25 = 11$. The choice 61 adds them, 25 is just the cups, and 3 comes from 4 + 9 - 5 - 5.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boxes 4 x 9 = 36; cups 5 x 5 = 25; 36 - 25 = 11.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afc1762e-e2a3-4869-a00b-765a9537bbf8', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: "more than" and "fewer than" stories', 'A red kite has a string 35 meters long. The blue kite string is 12 meters shorter than the red one. The green kite string is 8 meters longer than the blue one. How many meters long is the green kite string?', '[]', '31', '35-12+8', 'The blue string is $35 - 12 = 23$ meters. The green string is $23 + 8 = 31$ meters.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 35 - 12 = 23; green 23 + 8 = 31.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
