INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46e8bf66-127b-4204-b735-90472ed615c1', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: "more than" and "fewer than" stories', 'On Monday, 48 children came to the pool. On Tuesday, 15 more children came than on Monday. How many children came on the two days in all?', '["63","111","96","126"]', '111', '48+(48+15)', 'Tuesday had $48 + 15 = 63$ children. In all, $48 + 63 = 111$. The choice 63 is only Tuesday, 96 doubles Monday, and 126 adds the extra 15 a second time.', 'checked', '{"lint":[],"solve":{"answer":"111","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tuesday 48 + 15 = 63; total 48 + 63 = 111.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
