INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88c881cb-7257-4ef3-93bc-94ca17eca607', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: three numbers to add or subtract', 'A baker had 90 rolls. She sold 34 rolls in the morning and 27 rolls in the afternoon. How many rolls does she have left?', '["83","29","61","151"]', '29', '90-34-27', 'She sold $34 + 27 = 61$ rolls, so $90 - 61 = 29$ are left. The choice 83 adds the afternoon sales, 61 is the number sold, and 151 adds everything.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - 34 = 56; 56 - 27 = 29.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
