INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('134e0278-2998-4b52-8904-df02b01a0bca', 'NC26.3.ANR.6', 2, 'choice', 'Estimate a product by rounding', 'A bus holds 38 children. Round 38 to the nearest ten. About how many children can 5 buses hold?', '["200","190","150","250"]', '200', '40*5', '38 rounds to 40. Five buses hold about $40 \times 5 = 200$ children. The choice 190 is the exact product, 150 rounds 38 down to 30, and 250 rounds it up to 50.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38 -> 40; 5 x 40 = 200.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
