INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae9cc10a-a371-4b13-98c9-7cd29db57eb7', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: two products added', 'A museum charges 8 dollars for each child and 12 dollars for each adult. A group has 5 children and 2 adults. How many dollars does the group pay in all?', '[]', '64', '5*8+2*12', 'Children: $5 \times 8 = 40$ dollars. Adults: $2 \times 12 = 24$ dollars. Together: 40 + 24 = 64 dollars.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Children 5 x 8 = 40; adults 2 x 12 = 24; 40 + 24 = 64.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
