INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae4d56e-662f-4562-ae8d-7abb48dac437', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: add and subtract in a story', 'A warehouse has 450 boxes. A truck brings 275 more boxes. Then 380 boxes are shipped out. How many boxes are in the warehouse now?', '[]', '345', '450+275-380', 'After the truck comes there are $450 + 275 = 725$ boxes. After shipping, $725 - 380 = 345$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"345","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"450 + 275 = 725; 725 - 380 = 345.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
