INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a70645b1-878a-4cfb-bdad-a007ccd43953', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: add and subtract in a story', 'A water tank has 600 liters of water. 245 liters are poured out. Then 130 liters are added. How many liters are in the tank now?', '["355","225","975","485"]', '485', '600-245+130', 'First $600 - 245 = 355$ liters. Then $355 + 130 = 485$ liters. The choice 355 forgets the water added, 225 takes away the 130, and 975 adds everything.', 'checked', '{"lint":[],"solve":{"answer":"485","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 - 245 = 355; 355 + 130 = 485.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c222ee1a-31c5-4995-a663-a799665fdcf8', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: add or subtract first, then multiply', 'A gardener plants 8 rows with 9 seeds in each row. In every row, 2 seeds do not sprout. How many seeds sprout in all?', '[]', '56', '8*(9-2)', 'In each row $9 - 2 = 7$ seeds sprout. Eight rows give $8 \times 7 = 56$ seeds.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 2 = 7 sprout per row; 8 x 7 = 56. (Check: 72 - 16 = 56.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('675e3de5-a98a-42c2-a6ec-bd85ff6e94c1', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: add or subtract first, then multiply', 'Mr. Ray has 6 boxes with 12 pencils in each box. He takes 4 pencils out of each box. How many pencils are left in the 6 boxes?', '["48","68","24","8"]', '48', '6*(12-4)', 'Each box now has $12 - 4 = 8$ pencils. Six boxes have $6 \times 8 = 48$ pencils. The choice 68 takes away only 4 pencils in all, 24 is the number taken out, and 8 is the count for one box.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 4 = 8 left per box; 6 x 8 = 48. (Check: 72 - 24 = 48.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
