INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71ed2fdc-f92f-4bd3-8648-94ba04b05411', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: add or subtract first, then multiply', 'A school buys 4 boxes of red pens, 3 boxes of blue pens and 2 boxes of black pens. Each box has 10 pens. The school gives 30 of the pens to a class. How many pens are left?', '[]', '60', '(4+3+2)*10-30', 'The school buys $4 + 3 + 2 = 9$ boxes. That is $9 \times 10 = 90$ pens. After giving 30 away, $90 - 30 = 60$ pens are left.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 3 + 2 = 9 boxes; 9 x 10 = 90 pens; 90 - 30 = 60.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
