INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b58c0e2b-eb4c-414b-a0d4-c91a193f3ccb', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: compare two products', 'Sam saves 7 dollars every week for 9 weeks. Tara saves 6 dollars every week for 8 weeks. How many more dollars did Sam save than Tara?', '[]', '15', '7*9-6*8', 'Sam saved $7 \times 9 = 63$ dollars. Tara saved $6 \times 8 = 48$ dollars. Sam saved $63 - 48 = 15$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sam 7 x 9 = 63; Tara 6 x 8 = 48; 63 - 48 = 15.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
