INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0f8c75a-fbde-481e-9940-c6ec45970242', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: compare two products', 'Which is more, 8 packs with 7 pencils in each pack or 6 packs with 9 pencils in each pack, and by how many pencils?', '["8 packs of 7 pencils, by 2 pencils","6 packs of 9 pencils, by 2 pencils","8 packs of 7 pencils, by 1 pencil","The two amounts are equal"]', '8 packs of 7 pencils, by 2 pencils', NULL, '8 packs of 7 is $8 \times 7 = 56$ pencils. 6 packs of 9 is $6 \times 9 = 54$ pencils. The first is more, by $56 - 54 = 2$ pencils.', 'checked', '{"lint":[],"solve":{"answer":"8 packs of 7 pencils, by 2 pencils","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 7 = 56; 6 x 9 = 54; 56 - 54 = 2, so 8 packs of 7 by 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7e4afc8-594c-44da-ab58-277bfe771cab', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: "more than" and "fewer than" stories', 'Pat collects 36 cans. Quinn collects 14 fewer cans than Pat. Rae collects 9 more cans than Quinn. How many cans do the three friends collect in all?', '[]', '89', '36+(36-14)+(36-14+9)', 'Quinn collects $36 - 14 = 22$ cans. Rae collects $22 + 9 = 31$ cans. In all, $36 + 22 + 31 = 89$ cans.', 'checked', '{"lint":[],"solve":{"answer":"89","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Needs three or four operations (two derived amounts, then a three-addend sum); more than the two steps the standard describes, though still solvable at grade 3.","work":"Quinn 36 - 14 = 22; Rae 22 + 9 = 31; total 36 + 22 + 31 = 89.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84a25673-f514-4636-a4e2-5fb2b1bee847', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: "more than" and "fewer than" stories', 'A zoo has 54 birds. It has 17 fewer reptiles than birds. How many birds and reptiles does the zoo have in all?', '["91","37","71","108"]', '91', '54+(54-17)', 'The zoo has $54 - 17 = 37$ reptiles. In all, $54 + 37 = 91$. The choice 37 is only the reptiles, 71 adds the 17 instead, and 108 counts the same number of reptiles as birds.', 'checked', '{"lint":[],"solve":{"answer":"91","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reptiles 54 - 17 = 37; total 54 + 37 = 91.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
