INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a670d37b-03e3-4a03-a0bb-58cc15453db7', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: three numbers to add or subtract', 'A shelf had 240 books. On Monday 85 books were checked out. On Tuesday 60 books were returned and 45 books were checked out. How many books are on the shelf now?', '[]', '170', '240-85+60-45', 'After Monday: $240 - 85 = 155$. Tuesday returns: $155 + 60 = 215$. Tuesday checkouts: $215 - 45 = 170$ books.', 'checked', '{"lint":[],"solve":{"answer":"170","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Three steps rather than two; fine for grade 3 but beyond the standard''s two-step scope.","work":"240 - 85 = 155; 155 + 60 = 215; 215 - 45 = 170.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
