INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f53fc5b5-4808-4659-9df7-b2a657d66680', 'NC26.3.ANR.6', 3, 'choice', 'Estimate a sum or difference by rounding', 'Which number sentence shows an estimate of $346 + 528$ made by rounding each number to the nearest hundred?', '["$350 + 530 = 880$","$300 + 530 = 830$","$300 + 500 = 800$","$400 + 500 = 900$"]', '$300 + 500 = 800$', NULL, '346 rounds to 300 (the tens digit 4 is less than 5) and 528 rounds to 500 (the tens digit 2 is less than 5). The estimate is $300 + 500 = 800$. The other choices round to the nearest ten or round 346 up.', 'checked', '{"lint":[],"solve":{"answer":"$300 + 500 = 800$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"346 -> 300, 528 -> 500; 300 + 500 = 800.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
