INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46379dbe-fc86-4f4c-b614-3d1b203bb279', 'NC26.3.ANR.6', 3, 'numeric', 'Estimate the answer to a story', 'A truck carries 304 boxes. It drops off 98 boxes at the first stop and 107 boxes at the second stop. Round each number to the nearest hundred. About how many boxes are still on the truck?', '[]', '100', '300-100-100', '304 rounds to 300, 98 rounds to 100 and 107 rounds to 100. The estimate is $300 - 100 - 100 = 100$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"304 -> 300, 98 -> 100, 107 -> 100; 300 - 100 - 100 = 100. (Exact 99.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
