INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bfce4df-c6d7-4cf1-ba10-71efa4d8018a', 'NC26.3.ANR.6', 3, 'choice', 'Find a missing amount in a two-step story', 'Lia has 4 bags with 7 beads in each bag. She gives some beads to a friend and has 19 beads left. How many beads did she give away?', '["47","23","9","12"]', '9', '4*7-19', 'Lia started with $4 \times 7 = 28$ beads. She gave away $28 - 19 = 9$ beads. The choice 47 adds 28 and 19, 23 adds 4 and 19, and 12 subtracts 7 from 19.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 7 = 28 beads; 28 - 19 = 9 given away.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
