INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00e67e5f-a6c3-4718-8d17-2a35908ba46b', 'NC26.3.ANR.6', 3, 'numeric', 'Find a missing amount in a two-step story', 'Sam had some stickers. He got 6 more stickers and then gave 4 stickers to his sister. Now he has 20 stickers. How many stickers did Sam have at the start?', '[]', '18', '20+4-6', 'Work backward. Before giving 4 away he had $20 + 4 = 24$. Before getting 6 more he had $24 - 6 = 18$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s + 6 - 4 = 20, so s + 2 = 20, s = 18. Check: 18 + 6 = 24, 24 - 4 = 20.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
