INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94c34b6c-7a89-4804-a398-2b204561d353', 'NC26.3.ANR.6', 3, 'numeric', 'Find a missing amount in a two-step story', 'Nate had 52 dollars. He bought a hat for 18 dollars and a book. Now he has 9 dollars left. How many dollars did the book cost?', '[]', '25', '52-18-9', 'After the hat Nate had $52 - 18 = 34$ dollars. He has 9 dollars left, so the book cost $34 - 9 = 25$ dollars. Check: $18 + 25 + 9 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spent 52 - 9 = 43; book 43 - 18 = 25. Check: 52 - 18 - 25 = 9.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('636cab95-742d-4f69-bee2-c6824dd1c1f9', 'NC26.3.ANR.6', 3, 'choice', 'Decide what to find first, or decide with the total', 'Sue has 10 dollars. She wants to buy 3 pens that cost 2 dollars each and a notebook that costs 5 dollars. Does she have enough money?', '["Yes, she will have 1 dollar left","No, she needs 11 more dollars","No, she needs 1 more dollar","Yes, she has exactly enough"]', 'No, she needs 1 more dollar', NULL, 'The pens cost $3 \times 2 = 6$ dollars. With the notebook the total is $6 + 5 = 11$ dollars. Sue has 10 dollars, so she is $11 - 10 = 1$ dollar short.', 'checked', '{"lint":[],"solve":{"answer":"No, she needs 1 more dollar","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pens 3 x 2 = 6; plus notebook 5 = 11 dollars; 11 - 10 = 1, so she needs 1 more dollar.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cba2ba6-eb38-4bdd-bfb1-c1f5045f9f71', 'NC26.3.ANR.7', 1, 'choice', 'Unit fraction of a whole', 'A pizza is cut into 8 equal slices. Mia eats 1 slice. What fraction of the pizza did she eat?', '["$\\frac{1}{7}$","$\\frac{7}{8}$","$\\frac{8}{1}$","$\\frac{1}{8}$"]', '$\frac{1}{8}$', NULL, 'The pizza has 8 equal slices, so each slice is $\frac{1}{8}$ of the pizza. Mia ate 1 slice, so she ate $\frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 of 8 equal slices is 1/8 of the pizza.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
