INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44d9433d-1b43-4d7e-84c9-30e37330c05f', 'NC26.3.ANR.7', 1, 'numeric', 'Equivalent fractions: find the missing number', 'What number goes in the box to make the fractions equal? $\frac{1}{4} = \frac{\square}{8}$', '[]', '2', '1*8/4', 'Cutting each fourth into 2 equal parts makes eighths. One fourth is 2 eighths, so $\frac{1}{4} = \frac{2}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fourths to eighths: each fourth is 2 eighths, so 1/4 = 2/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
