INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f6f2fb6-ec9c-4407-80c3-deb6a49ccb37', 'NC26.3.ANR.7', 1, 'numeric', 'Compare fractions with the same numerator', 'Tom cuts a bar into 3 equal pieces. Ana cuts a bar of the same size into 6 equal pieces. Each of them takes 1 piece. Write the fraction that names the bigger piece. Write your answer like 1/2.', '[]', '1/3', '1/3', 'Cutting into fewer pieces makes bigger pieces. Tom''s piece is $\frac{1}{3}$ and Ana''s piece is $\frac{1}{6}$, so $\frac{1}{3}$ is bigger.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same bar; 1/3 > 1/6 since fewer pieces are bigger. Bigger piece: 1/3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
