INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('715f179c-f88d-467d-9849-5e65b653887a', 'NC26.3.ANR.7', 1, 'choice', 'Compare fractions with the same numerator', 'A cake is shared equally among 2 friends. Another cake of the same size is shared equally among 8 friends. Who gets the bigger share?', '["A friend in the group of 2","A friend in the group of 8","The shares are the same size","The shares cannot be compared"]', 'A friend in the group of 2', NULL, 'Each friend in the group of 2 gets $\frac{1}{2}$ of a cake and each friend in the group of 8 gets $\frac{1}{8}$ of a cake. One half is bigger than one eighth.', 'checked', '{"lint":[],"solve":{"answer":"A friend in the group of 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 of a cake > 1/8 of a same-size cake: a friend in the group of 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
