VALUES ('e9e803fe-e6fc-49e0-ae74-bf43ea6c248f', 'NC26.3.ANR.7', 1, 'choice', 'Compare a fraction with one half and one whole', 'Which fraction is less than $\frac{1}{2}$?', '["$\\frac{3}{4}$","$\\frac{2}{3}$","$\\frac{5}{6}$","$\\frac{1}{4}$"]', '$\frac{1}{4}$', NULL, 'One fourth is less than half of the whole. The others, $\frac{3}{4}$, $\frac{2}{3}$ and $\frac{5}{6}$, are each more than half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6, 2/3, 3/4 are all more than half; 1/4 < 1/2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
