INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbe3a66d-335d-4af4-9ee9-2b8c009db338', 'NC26.3.ANR.7', 1, 'choice', 'Compare a fraction with one half and one whole', 'A pizza is cut into 8 equal slices. Leo eats 4 slices. How does the part Leo ate compare to $\frac{1}{2}$ of the pizza?', '["It is less than $\\frac{1}{2}$ of the pizza","It is equal to $\\frac{1}{2}$ of the pizza","It is greater than $\\frac{1}{2}$ of the pizza","It is equal to 1 whole pizza"]', 'It is equal to $\frac{1}{2}$ of the pizza', NULL, '4 of the 8 equal slices is half of the pizza, so $\frac{4}{8} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"It is equal to $\\frac{1}{2}$ of the pizza","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2, so equal.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
