INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87185474-841a-4b50-8466-47107f2d3fa8', 'NC26.3.ANR.7', 1, 'choice', 'Put fractions in order', 'Which list puts $\frac{5}{8}$, $\frac{1}{8}$ and $\frac{3}{8}$ in order from least to greatest?', '["$\\frac{5}{8}$, $\\frac{3}{8}$, $\\frac{1}{8}$","$\\frac{1}{8}$, $\\frac{3}{8}$, $\\frac{5}{8}$","$\\frac{3}{8}$, $\\frac{1}{8}$, $\\frac{5}{8}$","$\\frac{1}{8}$, $\\frac{5}{8}$, $\\frac{3}{8}$"]', '$\frac{1}{8}$, $\frac{3}{8}$, $\frac{5}{8}$', NULL, 'All are eighths, so order the numerators 1, 3, 5 from least to greatest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$, $\\frac{3}{8}$, $\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same denominator; order numerators 1, 3, 5.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
