INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08cc439c-2901-46ff-9070-4902bbaf2219', 'NC26.3.ANR.7', 1, 'choice', 'Compare fractions with the symbols <, > and =', 'Choose the true statement about $\frac{2}{3}$ and $\frac{1}{3}$.', '["$\\frac{2}{3} < \\frac{1}{3}$","$\\frac{2}{3} = \\frac{1}{3}$","$\\frac{2}{3} > \\frac{1}{3}$","$\\frac{1}{3} > \\frac{2}{3}$"]', '$\frac{2}{3} > \frac{1}{3}$', NULL, 'Both fractions are thirds, and 2 thirds is more than 1 third, so $\frac{2}{3} > \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} > \\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same denominator; 2 > 1, so 2/3 > 1/3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
