VALUES ('e263d189-5770-41ee-9a10-2d19be7a527d', 'NC26.3.ANR.7', 2, 'numeric', 'Unit fraction: one equal part of a whole', 'Four friends share a sandwich so that each friend gets an equal part. What fraction of the sandwich does each friend get? Write your answer like 1/2.', '[]', '1/4', '1/4', 'The sandwich is shared in 4 equal parts, so each friend gets one part, which is $\frac{1}{4}$ of the sandwich.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared equally among 4: each gets 1/4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
