INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db519183-cc3e-4aa3-aa3f-395a93771325', 'NC26.3.ANR.7', 2, 'choice', 'Fraction shown by the shaded parts of a shape', 'A square is cut into 6 equal parts. 1 part is red, 2 parts are blue, and the rest are white. What fraction of the square is white?', '["$\\frac{3}{6}$","$\\frac{1}{6}$","$\\frac{2}{6}$","$\\frac{6}{3}$"]', '$\frac{3}{6}$', NULL, 'The red and blue parts are $1 + 2 = 3$ parts, so $6 - 3 = 3$ parts are white. The fraction is $\frac{3}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 - 1 - 2 = 3 white parts: 3/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
