INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f489cf4-bb63-457a-af3e-987d1b1e5243', 'NC26.3.ANR.7', 2, 'numeric', 'Fraction shown by the shaded parts of a shape', 'A garden bed is divided into 8 equal sections. Tomatoes grow in 3 sections, peppers grow in 2 sections, and the rest of the sections have beans. What fraction of the garden bed has beans? Write your answer like 1/2.', '[]', '3/8', '(8-3-2)/8', 'Tomatoes and peppers use $3 + 2 = 5$ sections, so $8 - 5 = 3$ sections have beans. The fraction is $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 3 - 2 = 3 sections of beans: 3/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
