INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a77ab56-1bb3-4518-9ff1-ea6a6b5a65b0', 'NC26.3.ANR.7', 2, 'choice', 'Fraction shown by the shaded parts of a shape', 'A pizza is cut into 8 equal slices. Max eats 2 slices and Nia eats 3 slices. What fraction of the pizza did the two children eat in all?', '["$\\frac{5}{16}$","$\\frac{3}{8}$","$\\frac{5}{8}$","$\\frac{2}{8}$"]', '$\frac{5}{8}$', NULL, 'Together they ate $2 + 3 = 5$ of the 8 equal slices, which is $\frac{5}{8}$. The denominator stays 8 because the slices are still eighths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 = 5 slices of 8: 5/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
