INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b315ac2-d095-4da2-837a-95a0dd1a010f', 'NC26.3.ANR.7', 2, 'numeric', 'Equivalent fractions: find the missing number', 'Lia uses 2 of the 4 equal pieces of a ribbon. Sam has a ribbon of the same length cut into 8 equal pieces. How many of Sam''s pieces equal the amount Lia used?', '[]', '4', '2*8/4', 'Each of Lia''s pieces is 2 of Sam''s pieces. So 2 pieces of Lia''s equal $2 \times 2 = 4$ of Sam''s pieces, and $\frac{2}{4} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4 = 4/8, so 4 of Sam''s pieces.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1f63bbc-7e6c-4055-b1dd-81d6da7d7a5c', 'NC26.3.ANR.7', 2, 'choice', 'Recognize equal fractions', 'Which fraction is equal to $\frac{2}{3}$?', '["$\\frac{3}{6}$","$\\frac{2}{6}$","$\\frac{4}{6}$","$\\frac{3}{4}$"]', '$\frac{4}{6}$', NULL, 'Cutting each third into 2 parts makes sixths, and 2 thirds become 4 sixths: $\frac{2}{3} = \frac{4}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6. 2/6 = 1/3, 3/6 = 1/2, 3/4 differ.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
