INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a666634a-e168-4f2d-ad92-53232fea88ce', 'NC26.3.ANR.7', 2, 'choice', 'Compare fractions with the same denominator', 'Which fraction is greater than $\frac{5}{8}$?', '["$\\frac{7}{8}$","$\\frac{4}{8}$","$\\frac{3}{8}$","$\\frac{5}{8}$"]', '$\frac{7}{8}$', NULL, 'All the fractions are eighths, so compare the numerators. Only 7 is greater than 5.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same denominator; only 7 > 5: 7/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
