INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fdf0c76-49b6-4793-9c31-3db90690a8ef', 'NC26.3.ANR.7', 2, 'numeric', 'Compare fractions with the same denominator', 'What whole number goes in the box to make this true? $\frac{4}{6} < \frac{\square}{6} < \frac{6}{6}$', '[]', '5', '5', 'The box must be a number greater than 4 and less than 6. The only whole number is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 < n < 6 with n whole: n = 5.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
