INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb67aa09-5fa2-4313-8af5-9d3fd5201a6f', 'NC26.3.ANR.7', 2, 'choice', 'Compare fractions with the same denominator', 'Mia ran $\frac{3}{6}$ of a track, Raj ran $\frac{5}{6}$ of it, and Ty ran $\frac{1}{6}$ of it. The track is the same for all three. Who ran the farthest?', '["Mia","Raj","Ty","They all ran the same distance"]', 'Raj', NULL, 'All the distances are in sixths, so compare numerators: 5 is greater than 3 and 1. Raj ran the farthest.', 'checked', '{"lint":[],"solve":{"answer":"Raj","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same track, sixths: 5/6 is greatest, so Raj.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
