INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8ecd3ec-d982-4bd3-a17f-b4758de802d7', 'NC26.3.ANR.7', 2, 'choice', 'Compare fractions with the same numerator', 'Lena ate $\frac{3}{8}$ of a pizza. Max ate $\frac{3}{4}$ of a pizza of the same size. Who ate more?', '["Lena","They ate the same amount","Max","It cannot be told"]', 'Max', NULL, 'Both ate 3 slices, but fourths are bigger than eighths. So 3 fourths is more than 3 eighths and Max ate more.', 'checked', '{"lint":[],"solve":{"answer":"Max","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator 3; fourths are bigger than eighths, so 3/4 > 3/8 (3/4 = 6/8). Max.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
