INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10897e15-8225-4c54-b5fe-cf14a5556ecc', 'NC26.3.ANR.7', 2, 'numeric', 'Compare fractions with the same numerator', 'Two bars are the same size. Bar X has 2 of its 3 equal parts colored. Bar Y has 2 of its 6 equal parts colored. Write the fraction that names the bar with less colored. Write your answer like 1/2.', '[]', '2/6', '2/6', 'Both have 2 parts colored, but sixths are smaller than thirds. So $\frac{2}{6}$ is less than $\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Equivalent 1/3 must be accepted (compare by value).","work":"X = 2/3, Y = 2/6. Same numerator; sixths smaller, so Y has less: 2/6 (= 1/3).","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
