INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8558f3f-7f54-4faf-bcb2-4bae00099966', 'NC26.3.ANR.7', 2, 'choice', 'Compare fractions with the same numerator', 'These fractions all have a numerator of 3. Which fraction is the least?', '["$\\frac{3}{4}$","$\\frac{3}{6}$","$\\frac{3}{8}$","$\\frac{3}{3}$"]', '$\frac{3}{8}$', NULL, 'With the same numerator, the larger the denominator, the smaller the parts. Eighths are the smallest parts, so $\frac{3}{8}$ is the least.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator; largest denominator gives least: 3/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
