INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28283efe-310b-4917-abfc-9ed0ebbdc852', 'NC26.3.ANR.7', 2, 'choice', 'Compare a fraction with one half and one whole', 'Which fraction is greater than $\frac{1}{2}$ and less than 1?', '["$\\frac{5}{6}$","$\\frac{1}{3}$","$\\frac{4}{8}$","$\\frac{6}{6}$"]', '$\frac{5}{6}$', NULL, '$\frac{5}{6}$ is more than half (half is $\frac{3}{6}$) and less than the whole. $\frac{1}{3}$ is less than half, $\frac{4}{8}$ equals half, and $\frac{6}{6}$ equals 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 < 1/2; 4/8 = 1/2; 6/6 = 1; 5/6 is between 3/6 and 6/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
