INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72d0bff9-9c36-4bc7-ac96-65cf7879c3ba', 'NC26.3.ANR.7', 3, 'choice', 'Meaning of the numerator and the denominator', 'Pam colored $\frac{2}{3}$ of a ribbon. Which statement describes the ribbon?', '["It was cut into 2 equal parts and 3 parts were colored","It was cut into 5 equal parts and 2 parts were colored","It was cut into 3 equal parts and 3 parts were colored","It was cut into 3 equal parts and 2 parts were colored"]', 'It was cut into 3 equal parts and 2 parts were colored', NULL, 'In $\frac{2}{3}$ the denominator 3 is the number of equal parts and the numerator 2 is the number of colored parts.', 'checked', '{"lint":[],"solve":{"answer":"It was cut into 3 equal parts and 2 parts were colored","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 means 3 equal parts with 2 of them colored.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa3d42b-a966-4e31-9b52-31ab9a7ea2e7', 'NC26.3.ANR.7', 3, 'numeric', 'Fraction shown by the shaded parts of a shape', 'A flag is cut into 6 equal stripes. 2 stripes are red, 2 stripes are white and the rest are blue. What fraction of the flag is not blue? Write your answer like 1/2.', '[]', '4/6', '(2+2)/6', 'The red and white stripes are $2 + 2 = 4$ stripes, and these are the stripes that are not blue. The fraction is $\frac{4}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"4/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Equivalent 2/3 must be accepted (compare by value).","work":"Blue stripes 6 - 2 - 2 = 2; not blue = 4 stripes: 4/6 (= 2/3).","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('726c3428-ffa8-4b29-83d8-71bfb57d8eeb', 'NC26.3.ANR.7', 3, 'choice', 'Fraction shown by the shaded parts of a shape', 'A chocolate bar has 8 equal squares. Pia eats 3 squares. Later she eats 2 more squares. What fraction of the bar is left?', '["$\\frac{5}{8}$","$\\frac{3}{8}$","$\\frac{2}{8}$","$\\frac{3}{5}$"]', '$\frac{3}{8}$', NULL, 'Pia eats $3 + 2 = 5$ squares, so $8 - 5 = 3$ squares are left. The fraction left is $\frac{3}{8}$. The fraction $\frac{5}{8}$ is the part she ate.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eaten 3 + 2 = 5 squares; left 8 - 5 = 3: 3/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('333aebc3-a732-43ac-b908-21fb6fc5c6dd', 'NC26.3.ANR.7', 3, 'numeric', 'Fraction at a point on a number line', 'A number line from 0 to 1 is split into 8 equal parts. Point A is at $\frac{3}{8}$ and point B is at $\frac{7}{8}$. How many equal parts are between point A and point B?', '[]', '4', '7-3', 'Point A is 3 parts from 0 and point B is 7 parts from 0. They are $7 - 3 = 4$ parts apart.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From 3/8 to 7/8 is 7 - 3 = 4 eighths, i.e. 4 equal parts.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67ccce69-0611-45f6-a07d-81f34d8a4822', 'NC26.3.ANR.7', 3, 'choice', 'Fraction at a point on a number line', 'A number line from 0 to 1 is split into 6 equal parts. A point is exactly 1 part to the left of 1. Which fraction names the point?', '["$\\frac{1}{6}$","$\\frac{6}{5}$","$\\frac{5}{6}$","$\\frac{4}{6}$"]', '$\frac{5}{6}$', NULL, 'The point 1 is 6 parts from 0. One part to the left is 5 parts from 0, so the point is at $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 = 6/6; one part to the left is 5/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98074e90-09cd-4148-ac9f-5f00339d9729', 'NC26.3.ANR.7', 3, 'numeric', 'Build a fraction from unit fractions', 'A whole is made of 6 pieces that are each $\frac{1}{6}$. Mia takes 4 pieces and her brother takes 1 piece. What fraction of the whole is left? Write your answer like 1/2.', '[]', '1/6', '(6-4-1)/6', 'The pieces taken are $4 + 1 = 5$, so $6 - 5 = 1$ piece is left. That piece is $\frac{1}{6}$ of the whole.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 - 4 - 1 = 1 piece left: 1/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a29e954f-1afa-48d4-b17c-c47ee4b83e43', 'NC26.3.ANR.7', 3, 'choice', 'Build a fraction from unit fractions', 'Ken has 5 pieces that are each $\frac{1}{8}$ of a whole. How many more pieces that are each $\frac{1}{8}$ does he need to make exactly 1 whole?', '["5","8","13","3"]', '3', '8-5', 'A whole is 8 pieces that are each $\frac{1}{8}$. Ken has 5, so he needs $8 - 5 = 3$ more.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 whole = 8/8; 8 - 5 = 3 more eighths.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d91595a9-e424-4562-a4f0-fb43002b0870', 'NC26.3.ANR.7', 3, 'numeric', 'A whole as a fraction, and fractions equal to whole numbers', 'A cook cuts each pizza into 6 equal slices. Each slice is $\frac{1}{6}$ of a pizza. How many slices make 3 whole pizzas?', '[]', '18', '3*6', 'Each whole pizza is 6 slices. Three pizzas are $3 \times 6 = 18$ slices. In fractions, $\frac{18}{6} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 slices per pizza; 3 pizzas: 6 + 6 + 6 = 18.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b0d575-7fb8-46dc-a269-ca6e857a99e2', 'NC26.3.ANR.7', 3, 'choice', 'A whole as a fraction, and fractions equal to whole numbers', 'Which fraction is equal to 3?', '["$\\frac{12}{4}$","$\\frac{12}{3}$","$\\frac{3}{6}$","$\\frac{8}{4}$"]', '$\frac{12}{4}$', NULL, '$\frac{12}{4}$ means 12 fourths, and every 4 fourths make 1 whole, so $12 \div 4 = 3$. The others equal 4, one half and 2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{12}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6 = 1/2; 8/4 = 2; 12/3 = 4; 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa0d1fcb-f22d-4c2c-b25a-a79c0bdedbf5', 'NC26.3.ANR.7', 3, 'choice', 'Equivalent fractions: find the missing number', 'Which number makes this equation true? $\frac{3}{6} = \frac{\square}{2}$', '["2","1","3","6"]', '1', '3/6*2', 'Six sixths make the whole, so half of the whole is 3 sixths. Half of the whole is also 1 of 2 equal parts, so $\frac{3}{6} = \frac{1}{2}$ and the box holds 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6 = 1/2, so the box is 1.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36b66ec5-1716-4919-888a-3dd6ec7cc6d0', 'NC26.3.ANR.7', 3, 'numeric', 'Equivalent fractions: find the missing number', 'Use what you know about equal fractions to find the missing number: $\frac{6}{8} = \frac{\square}{4}$', '[]', '3', '6/8*4', 'Two eighths make one fourth. So 6 eighths make $6 \div 2 = 3$ fourths, and $\frac{6}{8} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two eighths make a fourth; 6/8 = 3/4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efba5b26-ba2c-4618-9f89-0be60bfbe1ce', 'NC26.3.ANR.7', 3, 'numeric', 'Equivalent fractions: find the missing number', 'Kai ate $\frac{2}{6}$ of a sandwich. Another sandwich of the same size is cut into 3 equal parts. How many of those parts would Kai need to eat to have the same amount?', '[]', '1', '2/6*3', 'Two sixths equal one third, so $\frac{2}{6} = \frac{1}{3}$. Kai would need 1 of the 3 equal parts.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/6 = 1/3, so 1 of the 3 parts.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98203d99-27b0-4784-b2dd-0e4076ddc525', 'NC26.3.ANR.7', 3, 'numeric', 'Equivalent fractions: find the missing number', 'Fill in the missing denominator: $\frac{4}{8} = \frac{2}{\square}$', '[]', '4', '2/(4/8)', 'The numerator went from 4 to 2, which is cut in half, so halve the denominator too: $8 \div 2 = 4$. So $\frac{4}{8} = \frac{2}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2 = 2/4; denominator 4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0cc06aa-1941-49d8-bb49-915b8631499f', 'NC26.3.ANR.7', 3, 'choice', 'Recognize equal fractions', 'Which statement is true?', '["$\\frac{3}{4} = \\frac{3}{8}$","$\\frac{1}{3} = \\frac{1}{6}$","$\\frac{2}{4} = \\frac{2}{8}$","$\\frac{2}{3} = \\frac{4}{6}$"]', '$\frac{2}{3} = \frac{4}{6}$', NULL, 'Doubling the parts doubles both numbers of $\frac{2}{3}$ to give $\frac{4}{6}$. Fractions with the same numerator but different denominators, such as $\frac{3}{4}$ and $\frac{3}{8}$, are not equal.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} = \\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 6/8 not 3/8; 1/3 = 2/6 not 1/6; 2/4 = 4/8 not 2/8; 2/3 = 4/6 true.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2fe8189-6d25-474a-9e33-555863e245ab', 'NC26.3.ANR.7', 3, 'numeric', 'Recognize equal fractions', 'Dev cuts a sandwich into 6 equal pieces and eats 4 of them. Ana has a sandwich of the same size cut into 3 equal pieces. How many of Ana''s pieces must she eat to eat the same amount as Dev?', '[]', '2', '4/6*3', 'Dev ate $\frac{4}{6}$ of a sandwich. Two sixths make one third, so $\frac{4}{6} = \frac{2}{3}$. Ana must eat 2 of her 3 pieces.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dev ate 4/6 = 2/3, so Ana eats 2 of her 3 pieces.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad3be46f-5eb4-44af-b3c6-136eac3e9927', 'NC26.3.ANR.7', 3, 'choice', 'Recognize equal fractions', 'Which set shows three names for the same amount?', '["$\\frac{1}{2}$, $\\frac{2}{4}$, $\\frac{4}{6}$","$\\frac{1}{3}$, $\\frac{2}{6}$, $\\frac{3}{8}$","$\\frac{3}{4}$, $\\frac{4}{8}$, $\\frac{6}{8}$","$\\frac{1}{2}$, $\\frac{2}{4}$, $\\frac{4}{8}$"]', '$\frac{1}{2}$, $\frac{2}{4}$, $\frac{4}{8}$', NULL, '$\frac{1}{2}$, $\frac{2}{4}$ and $\frac{4}{8}$ are all one half. In each other set one fraction does not match: $\frac{4}{6}$ is two thirds, not one half; $\frac{3}{8}$ is not equal to $\frac{1}{3}$; and $\frac{4}{8}$ is one half, not three fourths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$, $\\frac{2}{4}$, $\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 2/4 = 4/8 all same. Others: 3/8 is not 1/3; 4/8 is not 3/4; 4/6 is not 1/2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7470c0ad-839a-4fa4-9017-4bebc7c169a3', 'NC26.3.ANR.7', 3, 'numeric', 'Compare fractions with the same denominator', 'How many of these fractions are greater than $\frac{3}{8}$? $\frac{1}{8}$, $\frac{4}{8}$, $\frac{7}{8}$, $\frac{3}{8}$, $\frac{5}{8}$, $\frac{2}{8}$', '[]', '3', '3', 'The numerators greater than 3 are 4, 7 and 5. So 3 of the fractions are greater than $\frac{3}{8}$. The fraction $\frac{3}{8}$ itself is not greater than $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greater than 3/8: 4/8, 7/8, 5/8 (3/8 itself is not greater). Count 3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c56cbf49-7f86-4d5e-bf75-be40fe4cfb77', 'NC26.3.ANR.7', 3, 'numeric', 'Compare fractions with the same denominator', 'A fraction has a denominator of 8. It is greater than $\frac{3}{8}$ and less than $\frac{5}{8}$. What is the fraction? Write your answer like 1/2.', '[]', '4/8', '4/8', 'The numerator must be greater than 3 and less than 5, so it is 4. The fraction is $\frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"4/8 equals 1/2, the example in the answer hint; a child typing 1/2 has the right value, so grading should compare by value.","work":"Eighths strictly between 3/8 and 5/8: only 4/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c9d8a5f-dc8c-44a0-ba0d-d25f5df5ed29', 'NC26.3.ANR.7', 3, 'choice', 'Compare fractions with the same numerator', 'Bar A is cut into 3 equal parts. Bar B is the same size as Bar A and is cut into 6 equal parts. Which statement is true?', '["Each part of Bar B is smaller than each part of Bar A.","Each part of Bar B is larger than each part of Bar A.","Each part of Bar B is the same size as each part of Bar A.","Bar B is longer than Bar A."]', 'Each part of Bar B is smaller than each part of Bar A.', NULL, 'Cutting the same whole into more parts makes smaller parts. Sixths are smaller than thirds.', 'checked', '{"lint":[],"solve":{"answer":"Each part of Bar B is smaller than each part of Bar A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same size bars; more parts means smaller parts. 1/6 < 1/3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9522849d-a9e2-41d3-bcb9-0798ef0f90d6', 'NC26.3.ANR.7', 3, 'numeric', 'Compare fractions with the same numerator', 'How many of the fractions $\frac{2}{2}$, $\frac{2}{3}$, $\frac{2}{4}$ and $\frac{2}{8}$ are less than $\frac{2}{3}$?', '[]', '2', '2', 'All have a numerator of 2, so compare the sizes of the parts. Fourths and eighths are smaller than thirds, so $\frac{2}{4}$ and $\frac{2}{8}$ are less than $\frac{2}{3}$. The fraction $\frac{2}{2}$ is greater, and $\frac{2}{3}$ is not less than itself.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator 2: 2/2 = 1 is greater; 2/3 is equal, not less; 2/4 and 2/8 are less. Count 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4100f93f-6e19-4242-84ce-15de3bc6d2ae', 'NC26.3.ANR.7', 3, 'choice', 'Compare a fraction with one half and one whole', 'Sam says that $\frac{3}{8}$ is greater than $\frac{1}{2}$ because 3 is greater than 1. Which statement is correct?', '["$\\frac{3}{8}$ is greater than $\\frac{1}{2}$, because 8 is greater than 2","$\\frac{3}{8}$ is greater than $\\frac{1}{2}$, because it has more parts","$\\frac{3}{8}$ is less than $\\frac{1}{2}$, because $\\frac{1}{2}$ is equal to $\\frac{4}{8}$","$\\frac{3}{8}$ is equal to $\\frac{1}{2}$, because both are less than 1"]', '$\frac{3}{8}$ is less than $\frac{1}{2}$, because $\frac{1}{2}$ is equal to $\frac{4}{8}$', NULL, 'The numerator and denominator must be compared together. One half equals four eighths, and 3 eighths is less than 4 eighths. So $\frac{3}{8}$ is less than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$ is less than $\\frac{1}{2}$, because $\\frac{1}{2}$ is equal to $\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8 and 3/8 < 4/8, so Sam is wrong; 3/8 < 1/2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f39566c-3833-40c8-b00d-5fc041f34f5f', 'NC26.3.ANR.7', 3, 'numeric', 'Compare a fraction with one half and one whole', 'A fraction has a denominator of 8. It is greater than $\frac{1}{2}$ and less than $\frac{6}{8}$. What is its numerator?', '[]', '5', '5', 'One half equals $\frac{4}{8}$. The numerator must be greater than 4 and less than 6, so it is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8; strictly between 4/8 and 6/8 is 5/8. Numerator 5.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d63143d-b758-43b2-9edd-f989cbcc9dec', 'NC26.3.ANR.7', 3, 'choice', 'Put fractions in order', 'Which list shows $\frac{1}{6}$, $\frac{1}{2}$, $\frac{1}{4}$ and $\frac{1}{3}$ in order from greatest to least?', '["$\\frac{1}{6}$, $\\frac{1}{4}$, $\\frac{1}{3}$, $\\frac{1}{2}$","$\\frac{1}{2}$, $\\frac{1}{4}$, $\\frac{1}{3}$, $\\frac{1}{6}$","$\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{1}{4}$, $\\frac{1}{6}$","$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{4}$, $\\frac{1}{6}$"]', '$\frac{1}{2}$, $\frac{1}{3}$, $\frac{1}{4}$, $\frac{1}{6}$', NULL, 'For unit fractions, the smaller the denominator, the bigger the fraction. So the order from greatest to least is $\frac{1}{2}$, $\frac{1}{3}$, $\frac{1}{4}$, $\frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{4}$, $\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit fractions: smaller denominator is greater. 1/2 > 1/3 > 1/4 > 1/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
