INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('422e0eb4-d724-45fb-bc01-8b1b5330740f', 'NC26.3.ANR.7', 3, 'numeric', 'Put fractions in order', 'Write the second greatest of these fractions: $\frac{3}{8}$, $\frac{1}{2}$, $\frac{7}{8}$ and $\frac{5}{8}$. Write your answer like 1/2.', '[]', '5/8', '5/8', 'One half equals $\frac{4}{8}$. In order from least to greatest: $\frac{3}{8}$, $\frac{4}{8}$ (one half), $\frac{5}{8}$, $\frac{7}{8}$. The second greatest is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8. Order: 7/8, 5/8, 4/8, 3/8. Second greatest 5/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('571a316b-cc0e-4365-992c-c24dca5f904f', 'NC26.3.ANR.7', 3, 'choice', 'Put fractions in order', 'Three runners ran parts of a track of the same length. Dee ran $\frac{5}{6}$ of it, Eli ran $\frac{1}{3}$ of it and Flo ran $\frac{1}{2}$ of it. Which list shows the runners from the shortest distance to the longest?', '["Flo, Eli, Dee","Eli, Flo, Dee","Dee, Flo, Eli","Eli, Dee, Flo"]', 'Eli, Flo, Dee', NULL, 'One third is less than one half, and five sixths is more than one half (one half is $\frac{3}{6}$). So the order is $\frac{1}{3}$ (Eli), $\frac{1}{2}$ (Flo), $\frac{5}{6}$ (Dee).', 'checked', '{"lint":[],"solve":{"answer":"Eli, Flo, Dee","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In sixths: Eli 1/3 = 2/6, Flo 1/2 = 3/6, Dee 5/6. Shortest to longest: Eli, Flo, Dee.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e2f325a-d86e-4b2d-8b06-a6041a0f0162', 'NC26.3.ANR.7', 3, 'choice', 'Compare fractions with the symbols <, > and =', 'Which comparison is true?', '["$\\frac{3}{6} = \\frac{1}{2}$","$\\frac{5}{8} > \\frac{3}{4}$","$\\frac{2}{3} < \\frac{2}{4}$","$\\frac{1}{8} > \\frac{1}{6}$"]', '$\frac{3}{6} = \frac{1}{2}$', NULL, 'Three sixths is half of the whole, so $\frac{3}{6} = \frac{1}{2}$. The others are false: $\frac{3}{4} = \frac{6}{8}$ is greater than $\frac{5}{8}$, thirds are bigger than fourths, and eighths are smaller than sixths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{6} = \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6 = 1/2 true. 2/3 > 2/4 so ''<'' false. 3/4 = 6/8 > 5/8 so false. 1/8 < 1/6 so false.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53ec4773-0d38-4f3f-9a63-2f7bb2635084', 'NC26.3.ANR.7', 3, 'choice', 'Compare fractions with the symbols <, > and =', 'One of these four comparisons is false. Which one?', '["$\\frac{3}{8} < \\frac{1}{2}$","$\\frac{4}{6} < \\frac{4}{8}$","$\\frac{2}{4} = \\frac{4}{8}$","$\\frac{5}{6} > \\frac{5}{8}$"]', '$\frac{4}{6} < \frac{4}{8}$', NULL, 'With the same numerator, sixths are bigger than eighths, so $\frac{4}{6} > \frac{4}{8}$ and the statement $\frac{4}{6} < \frac{4}{8}$ is false. The other three are true.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6} < \\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 > 4/8 (same numerator, sixths bigger), so ''4/6 < 4/8'' is false. 3/8 < 4/8 = 1/2 true; 2/4 = 4/8 true; 5/6 > 5/8 true.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8ad25a2-4671-4297-82c6-f2f5f5090432', 'NC26.3.ANR.7', 3, 'numeric', 'Compare fractions with the symbols <, > and =', 'How many of these four statements are true? $\frac{1}{4} < \frac{1}{3}$, $\frac{6}{8} > \frac{3}{4}$, $\frac{4}{4} = \frac{8}{8}$, $\frac{1}{2} > \frac{5}{8}$', '[]', '2', '2', '$\frac{1}{4} < \frac{1}{3}$ is true. $\frac{6}{8} > \frac{3}{4}$ is false because $\frac{6}{8} = \frac{3}{4}$. $\frac{4}{4} = \frac{8}{8}$ is true because both equal 1. $\frac{1}{2} > \frac{5}{8}$ is false because $\frac{1}{2} = \frac{4}{8}$. So 2 are true.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 < 1/3 true. 6/8 = 3/4, so ''>'' false. 4/4 = 8/8 = 1 true. 1/2 = 4/8 < 5/8, so false. True: 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
