INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6670db33-9f0e-457d-8ca0-abd60bcf4f98', 'NC26.3.SGMR.1', 2, 'choice', 'Right, acute and obtuse angles', 'At 3:00 the hands of a clock make a square corner. What kind of angle do the hands make at 2:00?', '["a right angle","an obtuse angle","a straight line","an acute angle"]', 'an acute angle', NULL, 'At 2:00 the hands are closer together than at 3:00, so the angle is smaller than a square corner. That is an acute angle.', 'checked', '{"lint":[],"solve":{"answer":"an acute angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At 2:00 the hands are 2 hour-marks apart, less than the 3 marks of a right angle (3:00): acute.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4257f717-bffd-410c-bb27-ee2da6ace799', 'NC26.3.SGMR.1', 2, 'numeric', 'Right, acute and obtuse angles', 'Four angles are described. Angle A is a square corner. Angles B and C are each smaller than a square corner. Angle D is wider than a square corner but is not a straight line. How many of the four angles are acute?', '[]', '2', NULL, 'An acute angle is smaller than a square corner. Angles B and C are acute. Angle A is a right angle and angle D is obtuse. So 2 angles are acute.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A right, B and C acute, D obtuse: 2 acute.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
