INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c2f731-0233-4d4b-8bc5-885e71f5422a', 'NC26.3.SGMR.1', 2, 'choice', 'Identify a quadrilateral from its features', 'A shape has 4 sides. Both pairs of opposite sides are parallel, but none of its angles are right angles. Which shape could it be?', '["a rectangle","a parallelogram that is not a rectangle","a square","a triangle"]', 'a parallelogram that is not a rectangle', NULL, 'A shape with two pairs of parallel sides is a parallelogram. A rectangle and a square have right angles, and a triangle has no parallel sides. So it is a parallelogram that is not a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"a parallelogram that is not a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pairs of parallel sides but no right angles: a parallelogram that is not a rectangle. Rectangle and square have right angles; triangle has 3 sides.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
