INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a3582f-b1b6-436e-95cf-3c0cda25b5b3', 'NC26.3.SGMR.1', 2, 'choice', 'Relate kinds of quadrilaterals', 'Dana says every shape with 4 sides is a square. Which shape shows that Dana is wrong?', '["a square","a triangle","a circle","a rectangle with two long sides and two short sides"]', 'a rectangle with two long sides and two short sides', NULL, 'The shape must have 4 sides and not be a square. A rectangle with long and short sides does that. A square would fit what Dana said, and a triangle and a circle do not have 4 sides.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle with two long sides and two short sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A counterexample must have 4 sides and not be a square: a rectangle with long and short sides. Circle and triangle do not have 4 sides.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
