INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1afb8fe0-cc91-4100-a4d4-6fb50e993f79', 'NC26.3.SGMR.1', 3, 'choice', 'Points, lines and line segments', 'Which statement about lines and line segments is true?', '["You can measure the length of a whole line, but not a line segment.","You can measure both a line and a line segment.","You can measure the length of a line segment, but not of a whole line, because a line never ends.","A line segment never ends, but a line has two endpoints."]', 'You can measure the length of a line segment, but not of a whole line, because a line never ends.', NULL, 'A line segment stops at both ends, so it has a length that can be measured. A line goes on forever, so it cannot be measured.', 'checked', '{"lint":[],"solve":{"answer":"You can measure the length of a line segment, but not of a whole line, because a line never ends.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A segment has a measurable length; a line never ends, so it cannot be measured.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5554d6-0e69-4195-8da6-515d29b91c6a', 'NC26.3.SGMR.1', 3, 'choice', 'Points, lines and line segments', 'Segment XY has endpoints X and Y. Point Z is on segment XY, between X and Y. Which statement is true?', '["Segment XZ is longer than segment XY.","Segment XZ is shorter than segment XY.","Segment XZ is the same length as segment XY.","Point Z is not on segment XY."]', 'Segment XZ is shorter than segment XY.', NULL, 'Segment XZ is only a part of segment XY, so it is shorter. Z is on the segment, so "Point Z is not on segment XY" is false.', 'checked', '{"lint":[],"solve":{"answer":"Segment XZ is shorter than segment XY.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Z is strictly between X and Y, so XZ is part of XY and shorter.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
