INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ae7dbf3-6007-4f8f-bfb9-91177bfcbdd9', 'NC26.3.SGMR.1', 3, 'choice', 'Right, acute and obtuse angles', 'The hands of a clock make a square corner at 3:00 and a straight line at 6:00. What kind of angle do the hands make at 4:00?', '["an acute angle","a right angle","an obtuse angle","a straight line"]', 'an obtuse angle', NULL, 'At 4:00 the hands are farther apart than at 3:00 but not as far as at 6:00. So the angle is wider than a square corner but not a straight line: it is obtuse.', 'checked', '{"lint":[],"solve":{"answer":"an obtuse angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:00 is between 3:00 (right) and 6:00 (straight): wider than a right angle, less than straight: obtuse.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
