INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a611ae03-af68-4339-92c0-86624bf45114', 'NC26.3.SGMR.1', 3, 'choice', 'Right, acute and obtuse angles', 'At which time do the hands of a clock make an obtuse angle?', '["2:00","5:00","3:00","1:00"]', '5:00', NULL, 'At 3:00 the hands make a square corner and at 6:00 they make a straight line, so the angle at 5:00 is wider than a square corner but not straight. That is obtuse. At 1:00 and 2:00 the angle is acute.', 'checked', '{"lint":[],"solve":{"answer":"5:00","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5:00 is 5 hour-marks apart, between 3 (right) and 6 (straight): obtuse. 1:00 and 2:00 are acute; 3:00 is right.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
