INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e80215af-b07b-47aa-916d-1624b48ef63b', 'NC26.3.SGMR.1', 3, 'numeric', 'Right, acute and obtuse angles', 'Look at the hands of a clock at 12:00, at 3:00, at 6:00 and at 9:00. At how many of these four times do the hands make a right angle?', '[]', '2', NULL, 'The hands make a right angle at 3:00 and at 9:00. At 6:00 they make a straight line and at 12:00 they lie on top of each other. So 2 of the times.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12:00 hands overlap; 3:00 right; 6:00 straight; 9:00 right. Answer 2.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
