INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99b9a0e6-8033-4f7a-9be0-5277ef5c036e', 'NC26.3.SGMR.1', 3, 'numeric', 'Right angles in shapes', 'Rina draws a rectangle. She cuts it into 2 smaller rectangles with one straight cut from the middle of the top side to the middle of the bottom side. How many right angles do the 2 smaller rectangles have in all?', '[]', '8', '2*4', 'The cut makes 2 rectangles. Each has 4 right angles. $2 \times 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A vertical cut from midpoint of top to midpoint of bottom is perpendicular to both, giving 2 rectangles with 4 right angles each: 8.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
