INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fb14612-ce98-4a9e-9943-91e340fc92f6', 'NC26.3.SGMR.1', 3, 'numeric', 'Sides, corners and parallel sides of quadrilaterals', 'Maya has a square, a rectangle, a rhombus and a trapezoid that has exactly one pair of parallel sides. How many of the 4 shapes have two pairs of parallel sides?', '[]', '3', NULL, 'The square, the rectangle and the rhombus each have 2 pairs of parallel sides. The trapezoid has only 1 pair. So 3 shapes.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle, rhombus have 2 pairs each; the trapezoid has 1. Answer 3.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
