INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b3e9f80-2358-4b53-a61b-bc5e90070ae6', 'NC26.3.SGMR.1', 3, 'numeric', 'Sides, corners and parallel sides of quadrilaterals', 'Maya has a square, a rectangle, a rhombus and a trapezoid. How many of these 4 shapes ALWAYS have four right angles?', '[]', '2', NULL, 'Every square and every rectangle has 4 right angles. A rhombus and a trapezoid can have angles that are not right angles. So 2 shapes always do.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square and rectangle always have 4 right angles; rhombus and trapezoid not always. Answer 2.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
