INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d021674d-497b-44e1-b4ba-2a4dd2284611', 'NC26.3.SGMR.1', 3, 'choice', 'Relate kinds of quadrilaterals', 'Which shape belongs in both groups: "shapes with 4 right angles" and "shapes with 4 equal sides"?', '["a rectangle that is not a square","a rhombus that is not a square","a square","a trapezoid with exactly one pair of parallel sides"]', 'a square', NULL, 'Only a square has both 4 right angles and 4 equal sides. The other rectangle has unequal sides, and the other rhombus has no right angles.', 'checked', '{"lint":[],"solve":{"answer":"a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has both 4 right angles and 4 equal sides.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
