INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d446ffe9-89ee-4a99-8efa-b077698bf1a2', 'NC26.3.SGMR.1', 3, 'choice', 'Relate kinds of quadrilaterals', 'Dev says a square is also a rhombus. Tara says a square is also a rectangle. Who is correct?', '["Only Dev is correct.","Only Tara is correct.","Neither is correct.","Both Dev and Tara are correct."]', 'Both Dev and Tara are correct.', NULL, 'A square has 4 equal sides, so it is a rhombus. It also has 4 right angles, so it is a rectangle. Both are correct.', 'checked', '{"lint":[],"solve":{"answer":"Both Dev and Tara are correct.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has 4 equal sides (rhombus) and 4 right angles (rectangle): both correct.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
