INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('165a0cf8-5de7-4fc5-9ea7-7533ff26255e', 'NC26.3.SGMR.1', 3, 'numeric', 'Quadrilateral or not', 'A pentagon has 5 sides and a hexagon has 6 sides. Tia draws 2 quadrilaterals, 1 pentagon and 1 hexagon. How many sides do her 4 shapes have in all?', '[]', '19', '2*4+5+6', 'The 2 quadrilaterals have $2 \times 4 = 8$ sides. Add the pentagon and the hexagon: $8 + 5 + 6 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 4 + 5 + 6 = 8 + 11 = 19.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
