INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc3f854a-9084-4db7-be43-1411bddf47ce', 'NC26.3.SGMR.1', 3, 'numeric', 'Quadrilateral or not', 'How many of these six shapes are quadrilaterals: a square, a triangle, a trapezoid, a pentagon, a rhombus, a hexagon?', '[]', '3', NULL, 'A quadrilateral has 4 sides. The square, the trapezoid and the rhombus have 4 sides. The triangle has 3, the pentagon has 5 and the hexagon has 6. So 3 shapes.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrilaterals: square, trapezoid, rhombus = 3. Triangle, pentagon, hexagon are not.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
