VALUES ('43f9ef40-3dca-4022-8f0f-28aa51de8d9f', 'NC26.3.SGMR.2', 3, 'choice', 'Elapsed time: find the end time', 'Nina starts cleaning at 4:25. She cleans her room for 20 minutes and then the kitchen for 30 minutes. What time does she finish?', '["5:05","5:25","4:55","5:15"]', '5:15', NULL, 'She cleans for $20 + 30 = 50$ minutes in all. 35 minutes after 4:25 is 5:00, and 15 more minutes makes 5:15.', 'checked', '{"lint":[],"solve":{"answer":"5:15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 30 = 50 min. 4:25 + 35 = 5:00, + 15 = 5:15.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
