VALUES ('72634be1-2b11-4482-b7b5-b67a300e33d4', 'NC26.3.SGMR.2', 3, 'choice', 'Elapsed time: find the start time', 'A school play ended at 8:10. It had two acts, one 20 minutes long and the other 25 minutes long, with no break. What time did the play begin?', '["7:25","7:15","7:35","7:45"]', '7:25', NULL, 'The play lasted $20 + 25 = 45$ minutes. Go back 10 minutes from 8:10 to 8:00, and 35 more minutes to 7:25.', 'checked', '{"lint":[],"solve":{"answer":"7:25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 25 = 45 min. 8:10 - 10 = 8:00, - 35 = 7:25.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
