INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('308d1a18-b6a9-419f-8c68-4ce477705b76', 'NC26.3.SGMR.2', 3, 'choice', 'Read a clock to the minute', 'The minute hand of a clock points to the 11. The hour hand is just before the 3. What time is it?', '["3:55","2:55","2:11","11:15"]', '2:55', NULL, 'The hour hand has not yet reached the 3, so the hour is 2. The minute hand on the 11 means $11 \times 5 = 55$ minutes. The time is 2:55.', 'checked', '{"lint":[],"solve":{"answer":"2:55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Minute hand at 11 = 55 minutes; hour hand just before 3 means still the 2 o''clock hour: 2:55.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
