INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76d9e127-b4c5-4435-85cd-384a030f8592', 'NC26.3.SGMR.2', 3, 'choice', 'Choose the best unit of measure', 'Dana measures the same ribbon in inches, in feet and in yards. Which measurement has the biggest number?', '["the one in feet","the one in yards","They are all the same number.","the one in inches"]', 'the one in inches', NULL, 'The smaller the unit, the more of them it takes to measure the same length. An inch is the smallest of the three units, so the number of inches is the biggest.', 'checked', '{"lint":[],"solve":{"answer":"the one in inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inches are the smallest unit, so it takes the most of them: the inches number is biggest.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
