INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85ef1531-d681-4da2-9302-ceebd69d7c79', 'NC26.3.SGMR.3', 2, 'choice', 'Area of a rectangle or square by multiplying side lengths', 'A rectangle is 4 inches long and 6 inches wide. Which statement is true?', '["Its area is 10 square inches","Its area is 24 square inches","Its area is 20 square inches","Its area is 48 square inches"]', 'Its area is 24 square inches', NULL, 'Area is length times width: $4 \times 6 = 24$ square inches. The value 10 is $4 + 6$, 20 is the distance around, and 48 is double the area.', 'checked', '{"lint":[],"solve":{"answer":"Its area is 24 square inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 square inches.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
