INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e13aff82-6229-4f9d-99cd-b24077f16a83', 'NC26.3.SGMR.3', 2, 'choice', 'Missing side length from the area', 'A rectangular garden has an area of 56 square meters and is 8 meters long. How many meters wide is the garden?', '["48","7","64","8"]', '7', '56/8', 'Width $= 56 \div 8 = 7$ meters. Check: $8 \times 7 = 56$. The choice 48 subtracts, 64 adds, and 8 repeats the length.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / 8 = 7 meters.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
