VALUES ('000dc940-b5d9-4d32-93c8-8df426c22feb', 'NC26.3.SGMR.3', 2, 'numeric', 'Missing side length from the area', 'A rectangular classroom rug has an area of 54 square feet. It is 9 feet wide. How many feet long is the rug?', '[]', '6', '54/9', 'Length $= 54 \div 9 = 6$ feet. Check: $9 \times 6 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 / 9 = 6 feet.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
