INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bd0112f-a519-447b-bc1c-e3e1ba593ea2', 'NC26.3.SGMR.3', 2, 'choice', 'Missing side length from the area', 'A rectangle has an area of 36 square inches. Which could be its length and width?', '["6 inches and 8 inches","5 inches and 7 inches","10 inches and 3 inches","9 inches and 4 inches"]', '9 inches and 4 inches', NULL, 'The length times the width must be 36. $9 \times 4 = 36$. The other pairs give $6 \times 8 = 48$, $5 \times 7 = 35$ and $10 \times 3 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"9 inches and 4 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x7=35, 9x4=36, 6x8=48, 10x3=30. Only 9 and 4.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
