VALUES ('ba145456-6fbf-45ce-b655-420b07152119', 'NC26.3.SGMR.3', 2, 'choice', 'Missing side length from the perimeter', 'A triangle has a perimeter of 34 inches. Two of its sides are 11 inches and 13 inches long. How many inches long is the third side?', '["24","10","58","21"]', '10', '34-11-13', 'The two known sides total $11 + 13 = 24$ inches. The third side is $34 - 24 = 10$ inches.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 + 13 = 24; 34 - 24 = 10 inches.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
