INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4761298-6bce-4547-ab89-ee10f8183c17', 'NC26.3.SGMR.3', 2, 'numeric', 'Missing side length from the perimeter', 'The perimeter of a rectangle is 32 inches. What is the sum of its length and its width in inches?', '[]', '16', '32/2', 'The perimeter is two lengths plus two widths, which is twice the sum of one length and one width. So length plus width is $32 \div 2 = 16$ inches.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2 x (length + width), so length + width = 32 / 2 = 16.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
