INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a9f03cc-3ed5-4c68-a361-94b78053667b', 'NC26.3.SGMR.3', 2, 'numeric', 'Area and perimeter together', 'Rectangle X is 5 units by 3 units. Rectangle Y is 6 units by 2 units. They have the same perimeter. How many more square units is the area of X than the area of Y?', '[]', '3', '5*3-6*2', 'X has area $5 \times 3 = 15$ square units. Y has area $6 \times 2 = 12$ square units. X has $15 - 12 = 3$ more square units.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 16 and 16 (confirmed). Areas: 15 and 12. 15 - 12 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
