VALUES ('bee4ec1d-fb7e-4f38-9a64-efe71feb11dc', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A floor is made of two rectangles joined together with no overlap. One rectangle is 6 feet by 4 feet. The other is 3 feet by 2 feet. What is the total area of the floor in square feet?', '[]', '30', '6*4+3*2', 'First rectangle: $6 \times 4 = 24$ square feet. Second rectangle: $3 \times 2 = 6$ square feet. Total: 24 + 6 = 30 square feet.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24; 3 x 2 = 6; 24 + 6 = 30 square feet.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16ec01b5-197a-4e5b-be09-406e20b105cb', 'NC26.3.SGMR.3', 3, 'choice', 'Same area, different perimeter', 'Rectangle A is 6 units by 2 units. Rectangle B is 4 units by 3 units. Both have an area of 12 square units. Which statement is true?', '["Rectangle B has the greater perimeter.","Rectangle A has the greater perimeter.","The perimeters are equal because the areas are equal.","The perimeters are equal because both have four sides."]', 'Rectangle A has the greater perimeter.', NULL, 'Perimeter of A: 6 + 2 + 6 + 2 = 16 units. Perimeter of B: 4 + 3 + 4 + 3 = 14 units. So A has the greater perimeter, even though the areas are equal.', 'checked', '{"lint":[],"solve":{"answer":"Rectangle A has the greater perimeter.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6+2+6+2 = 16. B: 4+3+4+3 = 14. A has the greater perimeter.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb1346d7-8f38-4837-8a98-2b1180ac602f', 'NC26.3.SGMR.3', 3, 'numeric', 'Area by tiling with unit squares', 'Dev covers a rectangle with 3 rows of 8 unit squares. Then he adds 2 more rows of 8 unit squares below, with no gaps. How many unit squares cover the rectangle now?', '[]', '40', '3*8+2*8', 'There are now $3 + 2 = 5$ rows with 8 squares in each row, so $5 \times 8 = 40$ unit squares. (Or $24 + 16 = 40$.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2 = 5 rows of 8: 5 x 8 = 40 (or 24 + 16).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a73b281-8d7b-45a8-a4a1-fc3ad7c6f208', 'NC26.3.SGMR.3', 3, 'numeric', 'Area by tiling with unit squares', 'Rectangle A is covered by 5 rows with 4 unit squares in each row. Rectangle B is covered by 3 rows with 7 unit squares in each row. How many more unit squares cover Rectangle B than Rectangle A?', '[]', '1', '3*7-5*4', 'Rectangle A uses $5 \times 4 = 20$ squares. Rectangle B uses $3 \times 7 = 21$ squares. Rectangle B uses $21 - 20 = 1$ more square.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5 x 4 = 20. B: 3 x 7 = 21. 21 - 20 = 1.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005ea449-5fee-4fb4-baac-eddb98faa9f6', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a rectangle or square by multiplying side lengths', 'A kitchen floor is 9 feet by 7 feet. A bathroom floor is 5 feet by 6 feet. How many more square feet is the area of the kitchen floor than the area of the bathroom floor?', '[]', '33', '9*7-5*6', 'The kitchen floor is $9 \times 7 = 63$ square feet. The bathroom floor is $5 \times 6 = 30$ square feet. The difference is $63 - 30 = 33$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kitchen 9 x 7 = 63; bathroom 5 x 6 = 30; 63 - 30 = 33.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da5f2d8d-91ef-481d-973d-7328e794bb9e', 'NC26.3.SGMR.3', 3, 'choice', 'Area of a rectangle or square by multiplying side lengths', 'Which expression does NOT give the area of a rectangle that is 6 units by 4 units?', '["$6 \\times 4$","$4 \\times 6$","$6 + 6 + 6 + 6$","$6 + 4$"]', '$6 + 4$', NULL, 'The area is 24 square units. $6 \times 4$ and $4 \times 6$ both equal 24, and $6 + 6 + 6 + 6$ is 4 groups of 6, which is also 24. But $6 + 4 = 10$ does not give the area.', 'checked', '{"lint":[],"solve":{"answer":"$6 + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 24. 4x6=24, 6x4=24, 6+6+6+6=24 (4 rows of 6), but 6+4=10. So 6+4 does not give the area.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60ec4b77-e53b-4b17-8e96-3579052d40b7', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a rectangle or square by multiplying side lengths', 'Ana covers a board with 4 square stickers that do not overlap. Each side of a sticker is 5 centimeters long. What is the total area of the stickers in square centimeters?', '[]', '100', '4*5*5', 'One sticker has area $5 \times 5 = 25$ square centimeters. Four stickers have area $4 \times 25 = 100$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each sticker 5 x 5 = 25 sq cm; 4 stickers: 4 x 25 = 100 sq cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
