INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('435ccbc6-320a-4792-a5cf-f27b29a90080', 'NC26.3.SGMR.3', 3, 'choice', 'Area of a rectangle or square by multiplying side lengths', 'A rectangular banner is 9 feet long. Its width is 4 feet shorter than its length. What is the area of the banner in square feet?', '["36","28","45","14"]', '45', '9*(9-4)', 'The width is $9 - 4 = 5$ feet. The area is $9 \times 5 = 45$ square feet. The choice 36 uses 4 as the width, 28 is the distance around, and 14 adds the sides.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width = 9 - 4 = 5 ft. Area = 9 x 5 = 45 square feet.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
