INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acaeca43-6d0b-4203-833f-41fb40169049', 'NC26.3.SGMR.3', 3, 'choice', 'Missing side length from the area', 'A rectangle has an area of 30 square units. Which pair of side lengths can NOT be its length and width?', '["5 units and 6 units","3 units and 10 units","4 units and 8 units","2 units and 15 units"]', '4 units and 8 units', NULL, 'The two sides must multiply to 30. $5 \times 6$, $3 \times 10$ and $2 \times 15$ all equal 30, but $4 \times 8 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"4 units and 8 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x15=30, 5x6=30, 3x10=30, 4x8=32. 4 and 8 cannot.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
