INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27f260f9-9884-487e-9b4a-192293c92f24', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A hallway is shaped like an L. One part is 10 feet long and 3 feet wide. The other part is 6 feet long and 3 feet wide. The two parts meet at a corner and do not overlap. What is the total area of the hallway in square feet?', '[]', '48', '10*3+6*3', 'The first part is $10 \times 3 = 30$ square feet. The second part is $6 \times 3 = 18$ square feet. Together: $30 + 18 = 48$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 3 = 30, 6 x 3 = 18, no overlap: 30 + 18 = 48.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
