INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efc8e74d-6f23-467a-9765-e9cf59a616c7', 'NC26.3.SGMR.3', 3, 'choice', 'Area of a shape split into rectangles', 'An L-shaped patio is made of a rectangle that is 9 feet by 2 feet and a rectangle that is 4 feet by 3 feet. The two rectangles touch along one side and do not overlap. What is the area of the patio in square feet?', '["18","36","27","30"]', '30', '9*2+4*3', 'The first rectangle has area $9 \times 2 = 18$ square feet. The second has area $4 \times 3 = 12$ square feet. Together: $18 + 12 = 30$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 2 = 18, 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
