INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f7b0184-df05-44ea-b4f0-c4013c77f0e1', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A board is 9 inches long and 7 inches wide. Mia saws it across into three pieces that are each 9 inches long. Two of the pieces are 2 inches wide and 3 inches wide. What is the area of the third piece in square inches?', '[]', '18', '9*7-9*2-9*3', 'The third piece is $7 - 2 - 3 = 2$ inches wide, so its area is $9 \times 2 = 18$ square inches. (Check: $63 - 18 - 27 = 18$.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Widths add to 7: third = 7 - 2 - 3 = 2 in. Area = 9 x 2 = 18 (check 63 - 18 - 27 = 18).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
