INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc71c2fd-c2f1-4391-a15f-41f424ae9ab6', 'NC26.3.SGMR.3', 3, 'choice', 'Missing side length from the perimeter', 'A rectangle has a perimeter of 22 units. Which could be its length and width?', '["7 units and 5 units","6 units and 4 units","8 units and 3 units","9 units and 4 units"]', '8 units and 3 units', NULL, 'The perimeter is $2 \times (\text{length} + \text{width})$, so the length and width must add to 11. $8 + 3 = 11$. The other pairs add to 12, 10 and 13.', 'checked', '{"lint":[],"solve":{"answer":"8 units and 3 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need length + width = 11. 9+4=13, 7+5=12, 6+4=10, 8+3=11. Only 8 and 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f24aa2c-2839-43cd-93a1-7fce8263d813', 'NC26.3.SGMR.3', 3, 'choice', 'Area or perimeter: which to find, and which units', 'Dara is building a rectangular play yard. She needs to buy fence for the edge and grass seed to cover the ground. Which pair is correct?', '["fence: area; seed: perimeter","fence: perimeter; seed: area","fence: area; seed: area","fence: perimeter; seed: perimeter"]', 'fence: perimeter; seed: area', NULL, 'The fence goes around the edge, so it needs the perimeter. The seed covers the ground, so it needs the area.', 'checked', '{"lint":[],"solve":{"answer":"fence: perimeter; seed: area","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fence around the edge: perimeter. Seed covering the ground: area.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ef84069-842d-426e-b736-e12831ea0b67', 'NC26.3.SGMR.3', 3, 'choice', 'Area and perimeter together', 'A rectangle covered by exactly 16 unit squares can be 16 by 1, 8 by 2 or 4 by 4 units. Which one has the smallest perimeter?', '["the 8 by 2 rectangle","the 16 by 1 rectangle","the 4 by 4 rectangle","They all have the same perimeter"]', 'the 4 by 4 rectangle', NULL, 'The perimeters are 16 units for 4 by 4, 20 units for 8 by 2, and 34 units for 16 by 1. The same area can have different perimeters.', 'checked', '{"lint":[],"solve":{"answer":"the 4 by 4 rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 16 by 1 = 34, 8 by 2 = 20, 4 by 4 = 16. Smallest: 4 by 4.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99be4f88-01e2-4179-849d-cf24d6203385', 'NC26.3.SGMR.3', 3, 'choice', 'Area and perimeter together', 'A square has a perimeter of 24 centimeters. What is its area in square centimeters?', '["24","6","12","36"]', '36', '(24/4)^2', 'Each side is $24 \div 4 = 6$ centimeters, so the area is $6 \times 6 = 36$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side = 24 / 4 = 6 cm. Area = 6 x 6 = 36 sq cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df97756f-a68e-48d5-8c29-3388c309cbcd', 'NC26.3.SGMR.3', 3, 'numeric', 'Area and perimeter together', 'A rectangle has an area of 21 square units and a length of 7 units. A square has the same perimeter as this rectangle. What is the area of the square in square units?', '[]', '25', '(2*(7+21/7)/4)^2', 'The rectangle''s width is $21 \div 7 = 3$ units, so its perimeter is $7 + 3 + 7 + 3 = 20$ units. The square''s sides are $20 \div 4 = 5$ units, so its area is $5 \times 5 = 25$ square units.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width = 21 / 7 = 3. Perimeter = 7 + 3 + 7 + 3 = 20. Square side = 20 / 4 = 5. Area = 25.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe08e2a6-662a-4840-a1b1-cc6582d7980e', 'NC26.3.SGMR.3', 3, 'choice', 'Area and perimeter together', 'Ming says, "A rectangle with a greater area always has a greater perimeter." Which pair of rectangles shows that Ming is wrong?', '["a 5 by 5 rectangle and a 3 by 4 rectangle","a 6 by 6 rectangle and a 2 by 5 rectangle","a 3 by 7 rectangle and a 2 by 3 rectangle","a 4 by 4 rectangle and a 1 by 9 rectangle"]', 'a 4 by 4 rectangle and a 1 by 9 rectangle', NULL, 'The 4 by 4 rectangle has the greater area (16 against 9) but the shorter perimeter (16 against 20). In each other pair, the rectangle with the greater area also has the longer perimeter.', 'checked', '{"lint":[],"solve":{"answer":"a 4 by 4 rectangle and a 1 by 9 rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need greater area with NOT greater perimeter. 5x5 (25, P20) vs 3x4 (12, P14): no. 6x6 (36, P24) vs 2x5 (10, P14): no. 4x4 (16, P16) vs 1x9 (9, P20): greater area, smaller perimeter, yes. 3x7 (21, P20) vs 2x3 (6, P10): no.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b1ee494-3d1e-4fe5-9587-aac6f9c60b34', 'NC26.3.SGMR.3', 3, 'numeric', 'Area and perimeter together', 'Rectangle A is 6 units by 5 units. Rectangle B has the same area as Rectangle A and is 10 units long. What is the perimeter of Rectangle B in units?', '[]', '26', '2*(10+6*5/10)', 'The area of A is $6 \times 5 = 30$ square units. Rectangle B is 10 units long, so its width is $30 \div 10 = 3$ units. Its perimeter is $10 + 3 + 10 + 3 = 26$ units.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area of A = 6 x 5 = 30. B: 10 long, width = 30 / 10 = 3. Perimeter = 10 + 3 + 10 + 3 = 26.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
