INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38463f57-d9f9-4198-909b-04efa099de56', 'NC26.3.RD.1', 1, 'choice', 'Read and use a frequency table', 'Students voted for a favorite color. A frequency table shows blue 8, red 5 and green 6. What does the 8 next to blue tell you?', '["Blue is the eighth color on the list","8 more students voted for blue than for red","8 students voted for colors other than blue","8 students voted for blue"]', '8 students voted for blue', NULL, 'A frequency table tells how many times each choice was picked. The 8 next to blue means 8 students voted for blue. Blue got 3 more votes than red (not 8 more), and the other colors got $5 + 6 = 11$ votes.', 'checked', '{"lint":[],"solve":{"answer":"8 students voted for blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In a frequency table the number beside a category is how many chose it: 8 students voted for blue.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
