INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f519813-2c86-43dc-92a0-3834ec91c587', 'NC26.3.RD.1', 1, 'choice', 'Tally marks and organizing a list of answers', 'In a tally chart, one full group counts 5 marks. Which entry shows 7 marks?', '["1 full group and 2 single marks","1 full group and 7 single marks","2 full groups","1 full group and 3 single marks"]', '1 full group and 2 single marks', NULL, 'One full group is 5, and 2 more single marks make $5 + 2 = 7$. The other entries show 12, 10 and 8 marks.', 'checked', '{"lint":[],"solve":{"answer":"1 full group and 2 single marks","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 = 8; 5 + 7 = 12; 5 + 2 = 7; 2 groups = 10. So 1 full group and 2 single marks.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
