INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0d4adc5-60cb-4295-bf1d-3a4876d7aa4f', 'NC26.3.RD.1', 1, 'choice', 'Make a graph: choose a scale or the number of symbols', 'Ana''s data are 10, 30, 20 and 40 votes. She wants a bar graph scale that lands exactly on every one of these numbers. Which scale should she use?', '["counting by 4s","counting by 7s","counting by 10s","counting by 100s"]', 'counting by 10s', NULL, 'Each number is a multiple of 10, so a scale that counts by 10s (0, 10, 20, 30, 40) lands exactly on all of them. Counting by 4s, 7s or 100s skips some of the numbers.', 'checked', '{"lint":[],"solve":{"answer":"counting by 10s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10, 20, 30, 40 are all multiples of 10; not of 4 (10), 7, or 100.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2f54e06-d5f6-4611-82b9-91ecff605a85', 'NC26.3.RD.1', 1, 'choice', 'Make a graph: choose a scale or the number of symbols', 'Which of these does a bar graph need so that people can read it?', '["a title, labels on the bars and a scale of numbers","only the bars","a key that says what each picture stands for","a list of everyone''s names"]', 'a title, labels on the bars and a scale of numbers', NULL, 'Readers need a title to know the topic, labels to know what each bar shows, and a scale to read the numbers. A key belongs on a picture graph.', 'checked', '{"lint":[],"solve":{"answer":"a title, labels on the bars and a scale of numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A readable bar graph needs a title, category labels and a numbered scale. A picture key is for picture graphs.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f16bb2df-2357-496e-aa90-60794a9515c7', 'NC26.3.RD.1', 1, 'numeric', 'Make a graph: choose a scale or the number of symbols', 'In a picture graph, each picture stands for 5 students. How many pictures should Rita draw for 30 students?', '[]', '6', '30/5', 'Each picture is 5 students, so Rita draws $30 \div 5 = 6$ pictures.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 / 5 = 6 pictures.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a061925-1704-4a8d-be53-bfff1f0298b9', 'NC26.3.RD.1', 1, 'choice', 'Pose a question that data can answer', 'Sam wants to find out which fruit his classmates like best. Which question should he ask each classmate?', '["Which fruit do you like best: apple, banana or grape?","How tall is a banana?","Do you like Sam?","What time does lunch start?"]', 'Which fruit do you like best: apple, banana or grape?', NULL, 'Sam''s question must be about his classmates'' favorite fruit and give choices he can count. The other questions do not tell him anything about favorite fruit.', 'checked', '{"lint":[],"solve":{"answer":"Which fruit do you like best: apple, banana or grape?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only one option asks about favorite fruit, with categories.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
