INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f63f943-734f-4ed5-9205-747bb5d63b15', 'NC26.3.RD.1', 1, 'choice', 'Plan and carry out data collection', 'Which is the first step of the data cycle?', '["Draw a conclusion","Ask a question that data can answer","Make a graph","Collect the data"]', 'Ask a question that data can answer', NULL, 'The data cycle starts with a question. Then you collect the data, show it in a table or graph, and draw conclusions.', 'checked', '{"lint":[],"solve":{"answer":"Ask a question that data can answer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The data cycle starts by posing a question that data can answer.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
