INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14b8ef4c-d67c-4a65-93e9-a1dcd5132add', 'NC26.3.RD.1', 1, 'choice', 'Plan and carry out data collection', 'Mia wants to know the favorite subject of the students in her class. Which group should she ask?', '["the students in her class","only her best friends","only the teachers","only the first graders"]', 'the students in her class', NULL, 'To learn about the students in her class, Mia should ask the students in her class.', 'checked', '{"lint":[],"solve":{"answer":"the students in her class","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To learn about her class, ask the students in her class.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
