INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('111149c7-69d2-4560-bfba-ede54c8a16b6', 'NC26.3.RD.1', 1, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows that 20 students chose pizza, 15 chose tacos and 5 chose salad. Which conclusion is true?', '["Nobody chose salad","Tacos got the most votes","More students chose pizza than salad","Pizza and tacos got the same number of votes"]', 'More students chose pizza than salad', NULL, 'Pizza has 20 and salad has 5, so more chose pizza. Five students did choose salad, pizza got more votes than tacos, and 20 is not the same as 15.', 'checked', '{"lint":[],"solve":{"answer":"More students chose pizza than salad","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pizza 20 > salad 5: true. Others false.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
