INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ebf18cf-b668-4718-9432-f873497331a7', 'NC26.3.RD.1', 1, 'choice', 'Draw conclusions and make predictions from data', 'Rosa''s table shows that 12 students picked soccer and 6 students picked golf. Which sentence is supported by the data?', '["Soccer was picked by twice as many students as golf","Golf was picked by more students than soccer","Everyone picked soccer","Soccer was picked by 6 students"]', 'Soccer was picked by twice as many students as golf', NULL, '12 is twice 6, so twice as many students picked soccer as picked golf. The other sentences do not match the table.', 'checked', '{"lint":[],"solve":{"answer":"Soccer was picked by twice as many students as golf","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2 x 6: soccer twice golf.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
