INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bdd29d0-a2a7-4f02-836b-413074d4cd5b', 'NC26.3.RD.1', 2, 'choice', 'Read and use a frequency table', 'A frequency table shows how many times each fruit was chosen: apples 7, pears 12, plums 5 and cherries 12. Which statement is true?', '["Apples were chosen the most","Pears and cherries were chosen the same number of times","Plums were chosen more often than apples","Cherries were chosen the fewest"]', 'Pears and cherries were chosen the same number of times', NULL, 'Pears and cherries both have 12, so they were chosen the same number of times. Apples (7) were not the most, plums (5) were chosen less often than apples (7), and cherries (12) were not the fewest.', 'checked', '{"lint":[],"solve":{"answer":"Pears and cherries were chosen the same number of times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pears 12 and cherries 12 are equal. Apples (7) not most; plums 5 < apples 7; cherries not fewest.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a77ea87d-5570-49e4-a62f-cdc6dceb616a', 'NC26.3.RD.1', 2, 'numeric', 'Tally marks and organizing a list of answers', 'Lila makes a tally chart of birds. Sparrows have 3 full groups of five and 2 single marks. Robins have 2 full groups of five and 4 single marks. How many more sparrows than robins did she count?', '[]', '3', '3*5+2-(2*5+4)', 'Sparrows: $3 \times 5 + 2 = 17$. Robins: $2 \times 5 + 4 = 14$. Lila counted $17 - 14 = 3$ more sparrows.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sparrows 3 x 5 + 2 = 17. Robins 2 x 5 + 4 = 14. 17 - 14 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75e3face-b776-4a07-93f2-c05f278628ad', 'NC26.3.RD.1', 2, 'numeric', 'Tally marks and organizing a list of answers', 'Twelve students named the pet they own. The answers were: dog, cat, dog, fish, cat, dog, bird, cat, dog, fish, dog, cat. How many students own a cat or a fish?', '[]', '6', NULL, 'Count the cats: 4 (the 2nd, 5th, 8th and 12th answers). Count the fish: 2 (the 4th and 10th). Together: $4 + 2 = 6$ students.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dog 5, cat 4 (positions 2,5,8,12), fish 2 (4,10), bird 1; total 12. Cat or fish = 4 + 2 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4014728-fa4a-4a31-82b3-d2e02309e7c8', 'NC26.3.RD.1', 2, 'choice', 'Tally marks and organizing a list of answers', 'Kai wrote down the colors of 10 cars: red, blue, red, white, red, blue, white, red, blue, red. Which frequency table is correct?', '["red 4, blue 3, white 3","red 5, blue 3, white 2","red 5, blue 2, white 3","red 6, blue 2, white 2"]', 'red 5, blue 3, white 2', NULL, 'Count each color: red appears 5 times, blue 3 times and white 2 times. The three counts add up to 10, the number of cars.', 'checked', '{"lint":[],"solve":{"answer":"red 5, blue 3, white 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"red at 1,3,5,8,10 = 5; blue at 2,6,9 = 3; white at 4,7 = 2. Total 10.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
