INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57781662-6aea-4da0-8857-b1253d97c2a1', 'NC26.3.RD.1', 2, 'choice', 'Read a scaled bar graph', 'A bar graph shows how many books four classes read. Ms. A''s bar ends at 25, Mr. B''s at 40, Ms. C''s at 35 and Mr. D''s at 30. Which classes read more than 30 books?', '["Mr. B and Ms. C","Mr. B and Mr. D","Ms. A and Mr. D","Ms. C and Mr. D"]', 'Mr. B and Ms. C', NULL, 'More than 30 means a number greater than 30. Mr. B read 40 and Ms. C read 35. Mr. D read exactly 30, which is not more than 30.', 'checked', '{"lint":[],"solve":{"answer":"Mr. B and Ms. C","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More than 30: Mr. B (40), Ms. C (35). Mr. D is exactly 30, not more.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
