INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9825d112-ab2d-4a8d-81a3-8ac0da561e7c', 'NC26.3.RD.1', 2, 'numeric', 'Read a picture graph with a key', 'In a picture graph, each book picture stands for 10 books. Row A has 6 pictures and Row B has 4 pictures. How many books do the two rows stand for together?', '[]', '100', '10*(6+4)', 'There are $6 + 4 = 10$ pictures, and each stands for 10 books: $10 \times 10 = 100$ books.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6 + 4) x 10 = 100 books.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
