VALUES ('1965f497-c7e2-4dfe-a123-c9f47fdf8e64', 'NC26.3.RD.1', 2, 'choice', 'Read a picture graph with a key', 'In a picture graph, each picture stands for 2 books. Ann''s row has 6 pictures, Bo''s row has 4 pictures and Cy''s row has 5 pictures. Who read 8 books?', '["Ann","Bo","Cy","No one"]', 'Bo', NULL, 'Bo''s 4 pictures stand for $4 \times 2 = 8$ books. Ann read $6 \times 2 = 12$ books and Cy read $5 \times 2 = 10$ books.', 'checked', '{"lint":[],"solve":{"answer":"Bo","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ann 12, Bo 4 x 2 = 8, Cy 10. Bo read 8.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
