INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb7f7154-08c9-41dc-af33-13ce20014a77', 'NC26.3.RD.1', 2, 'numeric', 'Read a picture graph with a key', 'In a picture graph, each cookie picture stands for 2 cookies, and half a picture stands for 1 cookie. Jo''s row has 6 whole pictures and 1 half picture. How many cookies does Jo''s row stand for?', '[]', '13', '6*2+1', 'The 6 whole pictures stand for $6 \times 2 = 12$ cookies. The half picture stands for 1 more. Total: $12 + 1 = 13$ cookies.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2 + 1 = 13 cookies.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
