INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae9df71a-915b-43d9-82fc-7f61df6e363d', 'NC26.3.RD.1', 2, 'choice', 'Two-step problems from a graph or table', 'In a picture graph, each picture stands for 5 students. The soccer row has 6 pictures, the tennis row has 4 pictures and the golf row has 3 pictures. How many students are shown in all?', '["13","65","50","35"]', '65', '(6+4+3)*5', 'There are $6 + 4 + 3 = 13$ pictures, and each stands for 5 students: $13 \times 5 = 65$. The choice 13 forgets the key; 50 and 35 each leave out a row.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 4 + 3 = 13 pictures; 13 x 5 = 65 (30 + 20 + 15).","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
