INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ddcc6fa-ec81-48c4-952c-567a7d5018c0', 'NC26.3.RD.1', 3, 'numeric', 'Read a picture graph with a key', 'A picture graph uses 1 picture for every 2 students. Mr. Lin redraws it so that 1 picture stands for 6 students. 24 students chose swimming. How many fewer pictures show swimming in the new graph than in the old graph?', '[]', '8', '24/2-24/6', 'Old graph: $24 \div 2 = 12$ pictures. New graph: $24 \div 6 = 4$ pictures. That is $12 - 4 = 8$ fewer pictures.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old: 24 / 2 = 12 pictures. New: 24 / 6 = 4 pictures. 12 - 4 = 8 fewer.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
