INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59c4f5bd-29bc-4cae-ae6e-15238d685470', 'NC26.3.RD.1', 3, 'choice', 'Read a picture graph with a key', 'In Graph 1, each picture stands for 10 students, and Row A has 3 pictures. In Graph 2, each picture stands for 5 students, and Row B has 5 pictures. Which statement is true?', '["Row B stands for more students because it has more pictures","Row A stands for more students than Row B","The two rows stand for the same number of students","Row A stands for 3 students"]', 'Row A stands for more students than Row B', NULL, 'Row A stands for $3 \times 10 = 30$ students and Row B stands for $5 \times 5 = 25$ students. Row A stands for more, even though it has fewer pictures.', 'checked', '{"lint":[],"solve":{"answer":"Row A stands for more students than Row B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Row A: 3 x 10 = 30. Row B: 5 x 5 = 25. A stands for more.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f04d76db-1b7a-49dd-a481-9f38006cec1b', 'NC26.3.RD.1', 3, 'numeric', 'Read a picture graph with a key', 'In a picture graph, each sun stands for 4 sunny days and half a sun stands for 2 days. May''s row has 3 whole suns and 1 half sun. June''s row has 2 whole suns. How many more sunny days did May have than June?', '[]', '6', '(3*4+2)-2*4', 'May: $3 \times 4 + 2 = 14$ days. June: $2 \times 4 = 8$ days. May had $14 - 8 = 6$ more sunny days.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"May 3 x 4 + 2 = 14. June 2 x 4 = 8. 14 - 8 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bc2d044-f6b0-4082-8f51-ab42c4790b5a', 'NC26.3.RD.1', 3, 'numeric', 'Read a picture graph with a key', 'In a picture graph, each picture stands for 5 books. Monday has 3 pictures, Tuesday has 5 pictures, Wednesday has 2 pictures, and Thursday has some pictures. The four rows stand for 60 books in all. How many pictures are in Thursday''s row?', '[]', '2', '60/5-3-5-2', 'The 60 books are $60 \div 5 = 12$ pictures in all. Monday to Wednesday use $3 + 5 + 2 = 10$ pictures, so Thursday has $12 - 10 = 2$ pictures.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 / 5 = 12 pictures in all. 3 + 5 + 2 = 10. Thursday 12 - 10 = 2.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab487cb4-26ad-4006-b9a6-b448417f9547', 'NC26.3.RD.1', 3, 'numeric', 'Compare categories: how many more or fewer', 'In a picture graph, each picture stands for 4 students and half a picture stands for 2 students. The dog row has 9 whole pictures. The cat row has 6 whole pictures and 1 half picture. How many more students chose dogs than cats?', '[]', '10', '9*4-(6*4+2)', 'Dogs: $9 \times 4 = 36$ students. Cats: $6 \times 4 + 2 = 26$ students. Dogs got $36 - 26 = 10$ more.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 9 x 4 = 36. Cats 6 x 4 + 2 = 26. 36 - 26 = 10.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f759c462-cefd-447f-b4a4-7cd988dc4a3b', 'NC26.3.RD.1', 3, 'choice', 'Compare categories: how many more or fewer', 'Two classes voted for a color. Class A: red 12, blue 9, green 14. Class B: red 10, blue 15, green 8. For which color did Class B get more votes than Class A?', '["red","green","all three colors","blue"]', 'blue', NULL, 'Compare each color. Red: 10 is less than 12. Blue: 15 is more than 9. Green: 8 is less than 14. Only blue had more votes in Class B.', 'checked', '{"lint":[],"solve":{"answer":"blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 10 < 12, blue 15 > 9, green 8 < 14. Only blue.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cbc69a4-3ad2-449f-85e1-45afd293bf4b', 'NC26.3.RD.1', 3, 'numeric', 'Compare categories: how many more or fewer', 'A bar graph''s scale counts by 20s. The bars end at 60 for Monday, 100 for Tuesday and 80 for Wednesday. Thursday''s bar is 20 shorter than Monday''s bar. How many fewer does Thursday show than Tuesday?', '[]', '60', '100-(60-20)', 'Thursday shows $60 - 20 = 40$. Tuesday shows 100. The difference is $100 - 40 = 60$ fewer.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thursday = 60 - 20 = 40. Tuesday 100. 100 - 40 = 60.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4363cf6-e7be-4778-817e-02772d12c6b6', 'NC26.3.RD.1', 3, 'numeric', 'Two-step problems from a graph or table', 'In a picture graph, each picture stands for 3 students. The dog row has 9 pictures, the cat row has 6 pictures and the fish row has 2 pictures. How many more students chose dogs than chose cats and fish together?', '[]', '3', '9*3-(6*3+2*3)', 'Dogs: $9 \times 3 = 27$. Cats and fish: $6 \times 3 + 2 \times 3 = 18 + 6 = 24$. The difference is $27 - 24 = 3$ students.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 27; cats 18 + fish 6 = 24. 27 - 24 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89af8976-bf08-4fc0-9a7a-25ca9b2488e6', 'NC26.3.RD.1', 3, 'numeric', 'Two-step problems from a graph or table', 'A bar graph''s scale counts by 4s. The bars show books read by four teams: Reds 24, Blues 16, Greens 20 and Yellows 12. The two teams that read the most books are joined into one team. How many books did the joined team read?', '[]', '44', '24+20', 'The two highest bars are Reds (24) and Greens (20). Joined: $24 + 20 = 44$ books.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top two: Reds 24 and Greens 20. 24 + 20 = 44.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
