INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b135b9a0-4f8b-4e94-a726-1be48eaaeade', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'Sam asked 10 students at the soccer field which sport they like best. Nine said soccer. Sam says, "Most students in our school like soccer best." What is wrong with his conclusion?', '["Nine is too small a number","He asked only students at the soccer field, so his data may not show the whole school","Soccer is not a sport","He should have asked fewer students"]', 'He asked only students at the soccer field, so his data may not show the whole school', NULL, 'Students at the soccer field are more likely to like soccer. Sam did not ask a fair group of the whole school, so he cannot conclude this about all students.', 'checked', '{"lint":[],"solve":{"answer":"He asked only students at the soccer field, so his data may not show the whole school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample (students at the soccer field) is biased and not the whole school.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ec846d0-9b1c-4e50-af8f-d60aedf0ff7a', 'NC26.3.RD.1', 3, 'numeric', 'Draw conclusions and make predictions from data', 'In a picture graph, each picture stands for 5 books. Monday has 4 pictures, Tuesday has 6 pictures and Wednesday has 8 pictures. If the pattern continues, how many books will Thursday''s row stand for?', '[]', '50', '10*5', 'The number of pictures goes up by 2 each day: 4, 6, 8, so Thursday will probably have 10 pictures. Ten pictures stand for $10 \times 5 = 50$ books.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pictures 4, 6, 8 grow by 2, so Thursday 10 pictures = 50 books (books 20, 30, 40, 50).","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48285590-c49a-4f98-bc7f-708e3f0ff59b', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows votes for a favorite season: spring 7, summer 14, fall 9 and winter 6. Which statement is true?', '["Fall got twice as many votes as winter","Winter and spring together got more votes than summer","Summer got 7 more votes than fall","Summer got twice as many votes as spring"]', 'Summer got twice as many votes as spring', NULL, '14 is twice 7. Twice winter is 12, not 9. Winter and spring together make 13, which is less than 14. Summer is $14 - 9 = 5$ more than fall, not 7.', 'checked', '{"lint":[],"solve":{"answer":"Summer got twice as many votes as spring","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Summer - fall = 5, not 7. Summer 14 = 2 x spring 7: true. Fall 9 is not 2 x 6. Winter + spring = 13 < 14.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41fa40c6-5e0d-47fc-9471-32343921c5de', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows how many students chose each lunch: pizza 18, salad 7 and sandwich 11. Which question can NOT be answered by looking at the graph?', '["How many more students chose pizza than salad?","Which lunch did the fewest students choose?","Why did so many students choose pizza?","How many students chose a lunch in all?"]', 'Why did so many students choose pizza?', NULL, 'The graph shows how many chose each lunch, but not the reasons. The other questions can be answered with the numbers on the graph.', 'checked', '{"lint":[],"solve":{"answer":"Why did so many students choose pizza?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The graph gives counts, not reasons: ''Why...'' cannot be answered. Total (36), difference (11) and fewest (salad) can.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('821e58ee-a321-4f01-84f9-5eee48ef2101', 'NC26.3.RD.1', 3, 'choice', 'Show a number of students with whole and half symbols', 'In a picture graph, each circle stands for 8 students, and half a circle stands for 4 students. 28 students chose art. Which shows the row for art?', '["3 whole circles and 1 half circle","3 whole circles and 2 half circles","7 whole circles","4 whole circles"]', '3 whole circles and 1 half circle', NULL, 'Each whole circle is 8 students. 3 whole circles are 3 x 8 = 24 students, and 28 - 24 = 4 students are left. 4 students is exactly 1 half circle. So the row has 3 whole circles and 1 half circle.', 'checked', '{"lint":[],"solve":{"answer":"3 whole circles and 1 half circle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 8 = 3 remainder 4, so 3 whole circles (24) and 1 half circle (4) = 28. Others: 4 whole = 32; 7 whole = 56; 3 whole + 2 halves = 24 + 8 = 32. Only one option equals 28.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
