INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab0f15dc-1580-4133-83cd-517774f44c6e', 'NC26.4.ANR.1', 3, 'numeric', 'Order numbers', 'Using each of the digits 2, 5, 7, 0 and 9 exactly once, what is the least five-digit number you can make?', '[]', '20579', '20579', 'A number cannot start with 0, so the smallest first digit is 2. Then use the rest from least to greatest: 0, 5, 7, 9. The number is 20,579.', 'checked', '{"lint":[],"solve":{"answer":"20579","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 0,2,5,7,9. First digit cannot be 0, so smallest nonzero 2 first, then 0,5,7,9: 20,579.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
