VALUES ('6155aff8-093b-4ad9-b3a7-e6072ed8682c', 'NC26.4.ANR.1', 3, 'numeric', 'Name a number in different units (tens, hundreds, thousands)', 'A number has 18 thousands, 3 hundreds and 5 ones. What is the number?', '[]', '18305', '18000+300+5', '18 thousands is 18,000. Add 3 hundreds (300) and 5 ones: 18,305.', 'checked', '{"lint":[],"solve":{"answer":"18305","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18,000 + 300 + 5 = 18,305.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
