INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f014ae-349b-439a-babf-616cf36dd767', 'NC26.4.ANR.1', 3, 'choice', 'Name a number in different units (tens, hundreds, thousands)', 'Which of these is NOT another name for $47{,}300$?', '["47 thousands + 3 hundreds","47 hundreds + 3 thousands","473 hundreds","4,730 tens"]', '47 hundreds + 3 thousands', NULL, '47 hundreds + 3 thousands = 4,700 + 3,000 = 7,700. The other three each equal 47,300.', 'checked', '{"lint":[],"solve":{"answer":"47 hundreds + 3 thousands","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 thousands + 3 hundreds = 47,300. 4,730 tens = 47,300. 47 hundreds + 3 thousands = 4,700 + 3,000 = 7,700 (not). 473 hundreds = 47,300.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
