INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b70c70b5-0812-4e99-9e7e-ace7d1637307', 'NC26.4.ANR.1', 3, 'choice', 'Name a number in different units (tens, hundreds, thousands)', 'What number is 7 ten-thousands plus 14 thousands?', '["21,000","70,140","84,000","7,014"]', '84,000', '70000+14000', '7 ten-thousands is 70,000 and 14 thousands is 14,000. 70,000 + 14,000 = 84,000.', 'checked', '{"lint":[],"solve":{"answer":"84,000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70,000 + 14,000 = 84,000.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
