INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd50d77e-26eb-424d-a601-91c6fbf931b7', 'NC26.4.ANR.1', 3, 'numeric', 'Use place value to build or find a number', 'I am a five-digit number. My ten-thousands digit is 6. My thousands digit is half of my ten-thousands digit. My hundreds digit is 0. My tens digit is 1 more than my thousands digit. My ones digit is 2 less than my ten-thousands digit. What number am I?', '[]', '63044', '60000+3000+0+40+4', 'Ten-thousands 6; thousands 3 (half of 6); hundreds 0; tens 4 (3 + 1); ones 4 (6 - 2). The number is 63,044.', 'checked', '{"lint":[],"solve":{"answer":"63044","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ten-thousands 6; thousands 6/2 = 3; hundreds 0; tens 3 + 1 = 4; ones 6 - 2 = 4. Number 63,044.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
