INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8938229-38e9-4ccc-9eb4-6dea9c6d3f6a', 'NC26.4.ANR.1', 3, 'numeric', 'Use place value to build or find a number', 'What is the least five-digit number that has a 7 in the thousands place and uses five different digits?', '[]', '17023', '17023', 'The ten-thousands digit cannot be 0, so the least choice is 1. The thousands digit is 7. Then use the least unused digits: 0 for the hundreds, 2 for the tens and 3 for the ones. The number is 17,023.', 'checked', '{"lint":[],"solve":{"answer":"17023","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ten-thousands: least nonzero digit not 7 = 1. Thousands = 7. Remaining places smallest unused digits in order: 0, 2, 3. Number 17,023 (digits 1,7,0,2,3 all different).","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4824224c-b7d5-45b0-b965-4d90197b4211', 'NC26.4.ANR.1', 3, 'choice', 'Use place value to build or find a number', 'A number is greater than $50{,}000$ and less than $60{,}000$. The digit in its thousands place is 8 and the digit in its hundreds place is 0. Which could be the number?', '["50,805","58,502","58,052","85,042"]', '58,052', '58052', 'Between 50,000 and 60,000 the first digit is 5. With thousands 8 and hundreds 0 we get 58,0__, so 58,052 fits.', 'checked', '{"lint":[],"solve":{"answer":"58,052","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must be 5x,xxx with thousands 8 and hundreds 0: 58,0xx. 58,502 has hundreds 5; 58,052 fits; 85,042 > 60,000; 50,805 has thousands 0.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
