INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fcf6c28-a7ec-4c98-8a50-cb349bd60250', 'NC26.4.ANR.1', 3, 'numeric', 'Value of each digit', 'The digit in the thousands place and the digit in the hundreds place of $36{,}420$ are swapped, making a new number. How much less than $36{,}420$ is the new number?', '[]', '1800', '36420-34620', 'The 6 is in the thousands place and the 4 is in the hundreds place. Swapping them gives $34{,}620$. The difference is $36{,}420 - 34{,}620 = 1{,}800$. Check by place value: the 6 loses 5,400 of value (6,000 down to 600), and the 4 gains 3,600 (400 up to 4,000), so the number drops by 1,800.', 'checked', '{"lint":[],"solve":{"answer":"1800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36,420: thousands digit 6, hundreds digit 4. Swapped: 34,620. 36,420 - 34,620 = 1,800.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
