INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f18a3e79-aedd-49ce-8576-060a69bc23dc', 'NC26.4.ANR.1', 3, 'choice', 'Number names (word form) and standard form', 'Which number is written in words as seventy thousand, three hundred two?', '["73,002","70,302","70,320","7,302"]', '70,302', '70302', 'Seventy thousand is 70,000, three hundred is 300 and two is 2. Put together, that is 70,302. The ten-thousands place holds the 7, the thousands place holds a 0, and the tens place holds a 0.', 'checked', '{"lint":[],"solve":{"answer":"70,302","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Seventy thousand = 70,000; three hundred two = 302. 70,302.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
