VALUES ('a84257a0-d6e3-4244-aa6f-05d0e6e9b0f3', 'NC26.4.ANR.2', 1, 'numeric', 'Add multi-digit numbers with the standard algorithm', 'Find the sum of $3{,}475$ and $1{,}218$.', '[]', '4693', '3475+1218', 'Ones: 5 + 8 = 13, write 3 and regroup 1 ten. Tens: 7 + 1 + 1 = 9. Hundreds: 4 + 2 = 6. Thousands: 3 + 1 = 4. The sum is 4,693.', 'checked', '{"lint":[],"solve":{"answer":"4693","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,475 + 1,218: ones 5+8=13 (write 3, carry 1); tens 7+1+1=9; hundreds 4+2=6; thousands 3+1=4. Sum 4,693.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
