INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94b7b9ca-8ebd-49b2-9133-b7280bf0390a', 'NC26.4.ANR.2', 1, 'choice', 'Understand regrouping in the algorithm', 'In $2{,}365 + 1{,}748$, the ones add up to 13 ones. How is 13 ones regrouped?', '["3 tens and 1 one","13 tens","1 hundred and 3 ones","1 ten and 3 ones"]', '1 ten and 3 ones', NULL, '10 ones make 1 ten, so 13 ones is 1 ten and 3 ones.', 'checked', '{"lint":[],"solve":{"answer":"1 ten and 3 ones","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 8 = 13 ones = 1 ten and 3 ones.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
