INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('618242f6-af96-4e14-b4bf-0442d1761e04', 'NC26.4.ANR.2', 1, 'numeric', 'Understand regrouping in the algorithm', 'To subtract $4{,}325 - 1{,}647$, you cannot take 7 ones from 5 ones. So you regroup 1 ten as 10 ones. How many ones are there after regrouping?', '[]', '15', '5+10', '5 ones + 10 ones = 15 ones, and now 15 - 7 can be done.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,325 has 2 tens and 5 ones. Regroup 1 ten as 10 ones: 5 + 10 = 15 ones.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
