INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9701c900-a8fa-4594-b3db-a788d7041814', 'NC26.4.ANR.2', 1, 'numeric', 'Connect earlier strategies to the standard algorithm', 'Rosa finds $2{,}413 + 3{,}265$ by adding each place separately: $2{,}000 + 3{,}000$, $400 + 200$, $10 + 60$ and $3 + 5$. What is the total of the four partial sums?', '[]', '5678', '5000+600+70+8', 'The partial sums are 5,000; 600; 70 and 8. Their total is 5,678.', 'checked', '{"lint":[],"solve":{"answer":"5678","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,000 + 600 + 70 + 8 = 5,678.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
