INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b41ee07-a11d-4c79-9130-4a3874db2e74', 'NC26.4.ANR.2', 1, 'choice', 'Connect earlier strategies to the standard algorithm', 'Ben adds $3{,}500 + 2{,}400$ by first finding $3{,}500 + 2{,}000 = 5{,}500$. What should he do next?', '["Add 2,400 to 5,500.","Add 400 to 3,500.","Add 400 to 5,500.","Subtract 400 from 5,500."]', 'Add 400 to 5,500.', NULL, '2,400 is 2,000 + 400. He has added the 2,000, so he still has to add the 400 to 5,500 to get 5,900.', 'checked', '{"lint":[],"solve":{"answer":"Add 400 to 5,500.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,400 = 2,000 + 400. After adding 2,000, add the remaining 400 to 5,500: 5,900.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
