INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b00b1c5-c9ad-45f6-b866-2fd8d9e5f80f', 'NC26.4.ANR.2', 1, 'choice', 'Find and fix a mistake in a calculation', 'Which equation is correct?', '["$2{,}500 + 1{,}800 = 3{,}300$","$2{,}500 + 1{,}800 = 4{,}200$","$2{,}500 + 1{,}800 = 4{,}300$","$2{,}500 + 1{,}800 = 3{,}200$"]', '$2{,}500 + 1{,}800 = 4{,}300$', NULL, 'Hundreds: 5 + 8 = 13 hundreds, which is 1 thousand and 3 hundreds. Thousands: 2 + 1 + 1 = 4. So the sum is 4,300.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}500 + 1{,}800 = 4{,}300$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,500 + 1,800 = 4,300.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
