VALUES ('2c302a22-2ab4-4469-94c8-6f3e94e8a6b8', 'NC26.4.ANR.2', 2, 'choice', 'Add multi-digit numbers with the standard algorithm', 'Use the standard algorithm to add $46{,}387 + 28{,}549$. What is the sum?', '["64,826","74,936","73,936","74,836"]', '74,936', '46387+28549', 'Ones: 7 + 9 = 16, write 6, regroup 1. Tens: 8 + 4 + 1 = 13, write 3, regroup 1. Hundreds: 3 + 5 + 1 = 9. Thousands: 6 + 8 = 14, write 4, regroup 1. Ten-thousands: 4 + 2 + 1 = 7. The sum is 74,936.', 'checked', '{"lint":[],"solve":{"answer":"74,936","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"46,387 + 28,549: ones 7+9=16 (6 c1); tens 8+4+1=13 (3 c1); hundreds 3+5+1=9; thousands 6+8=14 (4 c1); ten-thousands 4+2+1=7. Sum 74,936.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
