INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6056eb78-99d0-4d9f-9ba9-788bbe05c9db', 'NC26.4.ANR.2', 2, 'numeric', 'Understand regrouping in the algorithm', 'The number $7{,}205$ has 0 tens. To subtract $3{,}468$, you regroup 1 hundred as 10 tens, and then regroup 1 of those tens as 10 ones. How many tens are left in the tens place after both regroupings?', '[]', '9', '10-1', 'After the first regrouping there are 10 tens. Moving 1 ten to the ones place leaves 9 tens.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7,205: 2 hundreds, 0 tens, 5 ones. Regroup 1 hundred: 1 hundred, 10 tens. Regroup 1 ten: 9 tens, 15 ones. 9 tens left.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
