INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ec699c8-4a25-4f84-88e1-a75d5d80e5e7', 'NC26.4.ANR.2', 2, 'choice', 'Understand regrouping in the algorithm', 'Which subtraction needs no regrouping?', '["$6{,}478 - 2{,}345$","$6{,}475 - 2{,}386$","$6{,}478 - 2{,}495$","$6{,}478 - 2{,}579$"]', '$6{,}478 - 2{,}345$', NULL, 'In 6,478 - 2,345 each digit on top is at least the digit below it (8 and 5, 7 and 4, 4 and 3, 6 and 2). The others each have a place where the top digit is smaller.', 'checked', '{"lint":[],"solve":{"answer":"$6{,}478 - 2{,}345$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,475-2,386: ones 5<6. 6,478-2,345: 8>=5, 7>=4, 4>=3, 6>=2, no regrouping. 6,478-2,579: 8<9. 6,478-2,495: tens 7<9.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee950c2c-077c-4351-8d3a-b8f286ad5a37', 'NC26.4.ANR.2', 2, 'choice', 'Connect earlier strategies to the standard algorithm', 'Adding $4{,}725 + 3{,}617$ by partial sums, the hundreds give $700 + 600 = 1{,}300$. In the standard algorithm, what is done with these 13 hundreds?', '["Write 3 in the hundreds place and regroup 1 thousand.","Write 13 in the hundreds place.","Write 1 in the hundreds place and regroup 3 thousands.","Write 3 in the hundreds place and regroup 1 hundred."]', 'Write 3 in the hundreds place and regroup 1 thousand.', NULL, '13 hundreds is 1 thousand and 3 hundreds: write 3 in the hundreds place and add the 1 thousand to the thousands column.', 'checked', '{"lint":[],"solve":{"answer":"Write 3 in the hundreds place and regroup 1 thousand.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,725 + 3,617: ones 12 (carry 1 ten), tens 2+1+1=4, hundreds 7+6=13 hundreds = 1 thousand 3 hundreds: write 3, regroup 1 thousand.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
