INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc865e0-8373-4c4b-8b44-681dd3977fa5', 'NC26.4.ANR.2', 2, 'choice', 'Find and fix a mistake in a calculation', 'Leo wrote $52{,}000 - 17{,}348 = 45{,}348$. What mistake did he make?', '["He forgot to subtract the thousands.","In each place he subtracted the smaller digit from the larger digit instead of regrouping.","He added the digits in the ones place.","He regrouped but forgot to write the regrouped ten."]', 'In each place he subtracted the smaller digit from the larger digit instead of regrouping.', NULL, 'The correct answer is 34,652. Leo found the difference of the two digits in each place (4, 5, 3, 4, 8) instead of regrouping.', 'checked', '{"lint":[],"solve":{"answer":"In each place he subtracted the smaller digit from the larger digit instead of regrouping.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct 52,000 - 17,348 = 34,652. Leo: 5-1=4, then |2-7|=5, |0-3|=3, |0-4|=4, |0-8|=8 -> 45,348, i.e. smaller digit from larger in each place.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
