INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa6c14be-188d-443a-867d-66155c75ccf4', 'NC26.4.ANR.3', 1, 'choice', 'Identify a prime number', 'Which of these numbers is prime?', '["21","33","29","39"]', '29', '29', 'A prime number has exactly two factors, 1 and itself. 21 = 3 x 7, 33 = 3 x 11 and 39 = 3 x 13, so they are composite. 29 cannot be made by multiplying two smaller whole numbers, so 29 is prime.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 = 3 x 7, 33 = 3 x 11, 39 = 3 x 13 are composite; 29 has only factors 1 and 29, so prime.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26bcfb78-6a9d-4f69-8b52-102348fbe9f1', 'NC26.4.ANR.3', 1, 'choice', 'Identify a multiple', 'Which of these numbers is a multiple of 7?', '["37","35","53","57"]', '35', '35', 'Multiples of 7 are 7, 14, 21, 28, 35, 42, 49, 56, 63. Only 35 is in the list: 7 x 5 = 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35 = 7 x 5. 57 = 3 x 19, 37 prime, 53 prime: not multiples of 7.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f17961c-f1ca-45ca-94bc-15d4be4a1d96', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'Which of these is a factor of 18?', '["4","5","6","8"]', '6', '18/3', '$18 \div 6 = 3$ with nothing left over, so 6 is a factor of 18. Dividing 18 by 4, 5 or 8 always leaves a remainder.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 18: 1, 2, 3, 6, 9, 18. Of 8, 6, 4, 5 only 6 divides 18 (18 = 6 x 3).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2527b84-9ad5-4671-bb3e-6857e63e21a8', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'A factor pair of 24 is 4 and another number. What is the other number?', '["6","20","28","96"]', '6', '24/4', 'A factor pair multiplies to 24. Since $4 \times 6 = 24$, the other number is $24 \div 4 = 6$. The choice 20 subtracts, 28 adds and 96 multiplies by 4.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 4 = 6, so 4 and 6 is a factor pair.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5ce7449-5674-42e7-bcfd-a743a6465019', 'NC26.4.ANR.3', 1, 'numeric', 'Factors and factor pairs', 'How many factors does 10 have?', '[]', '4', NULL, 'The factors of 10 are 1, 2, 5 and 10, because $1 \times 10 = 10$ and $2 \times 5 = 10$. That is 4 factors.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 10: 1, 2, 5, 10. That is 4 factors.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec40a8f6-1f2e-4639-bf5d-5a6133b67688', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'Which pair of numbers is a factor pair of 16?', '["6 and 10","4 and 12","5 and 11","2 and 8"]', '2 and 8', NULL, 'A factor pair multiplies to 16, and $2 \times 8 = 16$. The other pairs add up to 16 but do not multiply to 16: $6 \times 10 = 60$, $4 \times 12 = 48$ and $5 \times 11 = 55$.', 'checked', '{"lint":[],"solve":{"answer":"2 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 8 = 16. 6 x 10 = 60, 5 x 11 = 55, 4 x 12 = 48.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b00eade0-ac96-427c-a2bc-e43d588427fa', 'NC26.4.ANR.3', 1, 'numeric', 'Factors and factor pairs', 'Eli makes a rectangle from 30 square tiles. Each row has 6 tiles, and every row is full. How many rows does he make?', '[]', '5', '30/6', 'The 30 tiles are in equal rows of 6, so the number of rows is $30 \div 6 = 5$. Check: $6 \times 5 = 30$, so 6 and 5 are a factor pair of 30.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 tiles / 6 per row = 5 rows.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('498a0155-3e93-4388-8695-267e8a56cf67', 'NC26.4.ANR.3', 1, 'choice', 'Prime and composite numbers', 'Which number is composite?', '["7","11","15","13"]', '15', '3*5', '$15 = 3 \times 5$, so 15 has factors besides 1 and itself. That makes it composite. The numbers 7, 11 and 13 each have only the factors 1 and themselves, so they are prime.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = 3 x 5 is composite; 13, 7, 11 are prime.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a33d1d4-b581-4b3f-93f8-b05f8a43b5d4', 'NC26.4.ANR.3', 1, 'choice', 'Prime and composite numbers', 'Which sentence describes a prime number?', '["A number greater than 1 whose only factors are 1 and itself","Any odd number greater than 1","A number with exactly three factors","Any number greater than 1 that ends in 1, 3, 7 or 9"]', 'A number greater than 1 whose only factors are 1 and itself', NULL, 'A prime number is greater than 1 and has exactly two factors, 1 and itself. Not every odd number is prime (9 is not), and neither is every number ending in 1, 3, 7 or 9 (21 is not).', 'checked', '{"lint":[],"solve":{"answer":"A number greater than 1 whose only factors are 1 and itself","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition of prime: greater than 1, only factors 1 and itself. Odd numbers like 9, numbers ending in 1 like 21, and numbers with 3 factors like 9 are not all prime.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88a81c51-2dad-49e7-a568-310c457fb304', 'NC26.4.ANR.3', 1, 'numeric', 'Prime and composite numbers', 'What is the smallest prime number?', '[]', '2', NULL, 'The number 1 is not prime, because it has only one factor. The number 2 has exactly two factors, 1 and 2, so 2 is the smallest prime number.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 is not prime; 2 has factors 1 and 2 only. Smallest prime is 2.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92b10380-6c02-41e6-8603-48fd67214b65', 'NC26.4.ANR.3', 1, 'choice', 'Prime and composite numbers', 'Is 9 prime or composite?', '["Prime, because it is odd","Prime, because it is a square number","Composite, because $3 \\times 3 = 9$","Neither prime nor composite, because it is odd"]', 'Composite, because $3 \times 3 = 9$', NULL, '9 has the factors 1, 3 and 9. Since it has a factor other than 1 and itself, it is composite. Being odd does not make a number prime.', 'checked', '{"lint":[],"solve":{"answer":"Composite, because $3 \\times 3 = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 3 x 3, so it has factor 3 besides 1 and 9: composite.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
