INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2befdff-417e-414b-8545-482f1c63f333', 'NC26.4.ANR.3', 2, 'choice', 'Factors and factor pairs', 'Which list shows all of the factors of 14?', '["2, 7, 14","1, 2, 7, 14","1, 2, 7","1, 2, 4, 7, 14"]', '1, 2, 7, 14', NULL, 'The factor pairs of 14 are $1 \times 14$ and $2 \times 7$, so the factors are 1, 2, 7 and 14. One wrong list leaves out 1, one leaves out 14, and 4 is not a factor of 14.', 'checked', '{"lint":[],"solve":{"answer":"1, 2, 7, 14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 = 1 x 14 = 2 x 7, so factors 1, 2, 7, 14. 4 is not a factor; the other lists miss 1 or 14.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
