INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('858785ab-84b7-45cc-80f1-82dbbad0297c', 'NC26.4.ANR.3', 2, 'choice', 'Factors and factor pairs', 'Which number is NOT a factor of 40?', '["5","12","8","10"]', '12', '12', '$40 \div 5 = 8$, $40 \div 8 = 5$ and $40 \div 10 = 4$ leave nothing over, so 5, 8 and 10 are factors of 40. $40 \div 12$ leaves a remainder of 4, so 12 is not a factor.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 40: 1, 2, 4, 5, 8, 10, 20, 40. 12 is not (40 / 12 = 3 r 4).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
