INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40b3fe8b-20f0-4243-9c24-49d19f3beef3', 'NC26.4.ANR.3', 2, 'choice', 'Prime and composite numbers', 'Maya says that 51 is prime. Which fact shows that she is wrong?', '["$1 \\times 51 = 51$","$51 - 1 = 50$","$51 \\div 2$ leaves a remainder of 1","$3 \\times 17 = 51$"]', '$3 \times 17 = 51$', NULL, 'A prime number has no factors besides 1 and itself. Since $3 \times 17 = 51$, the number 3 is a factor of 51, so 51 is composite. Every number equals 1 times itself, so $1 \times 51 = 51$ proves nothing.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 17 = 51$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 17 = 51 shows a factor other than 1 and 51, so 51 is composite.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
