VALUES ('12822c8e-e3d8-421e-8e07-dc01f1f626c4', 'NC26.4.ANR.3', 2, 'choice', 'Multiples', 'Which list shows only multiples of 8?', '["8, 16, 20, 32","8, 16, 24, 32","8, 18, 24, 32","4, 8, 12, 16"]', '8, 16, 24, 32', NULL, 'The multiples of 8 are 8, 16, 24, 32, 40, and so on. Each other list has a number that is not a multiple of 8: 20, 18, or 4 and 12.', 'checked', '{"lint":[],"solve":{"answer":"8, 16, 24, 32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8, 16, 24, 32 = 8x1..8x4. Others contain 20, 4, 12 or 18.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
