INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15f98269-f06f-45a6-afeb-99c394a719f0', 'NC26.4.ANR.3', 2, 'choice', 'Multiplicative comparison', 'A tree is 36 feet tall. A shrub is 4 feet tall. Which sentence is true?', '["The tree is 32 times as tall as the shrub","The tree is 9 times as tall as the shrub","The tree is 9 feet taller than the shrub","The shrub is 9 times as tall as the tree"]', 'The tree is 9 times as tall as the shrub', NULL, '$36 \div 4 = 9$, so the tree is 9 times as tall as the shrub. The difference, $36 - 4 = 32$, is how many feet taller the tree is, not how many times as tall.', 'checked', '{"lint":[],"solve":{"answer":"The tree is 9 times as tall as the shrub","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / 4 = 9, so the tree is 9 times as tall as the shrub (and 32 feet taller).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1d99a21-8861-466d-b6fd-e848eba158a5', 'NC26.4.ANR.3', 2, 'choice', 'Multiplicative comparison', 'Which equation can be used to find how many times as large 56 is as 8?', '["$8 + n = 56$","$56 \\times 8 = n$","$8 \\times n = 56$","$n \\div 56 = 8$"]', '$8 \times n = 56$', NULL, '"56 is $n$ times as large as 8" means 56 is $n$ groups of 8, so $8 \times n = 56$. Then $n = 56 \div 8 = 7$. The equation $8 + n = 56$ would mean 56 is $n$ more than 8.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times n = 56$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"How many times as large: 8 x n = 56 (n = 7). n / 56 = 8 gives 448; 8 + n is additive; 56 x 8 is a product.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
