VALUES ('3a24cd28-0925-47c3-b08d-4f675576bedc', 'NC26.4.ANR.3', 3, 'numeric', 'Remainders', 'A bakery packs 6 rolls in each bag. It has 38 rolls. How many more rolls does it need to fill the last bag?', '[]', '4', '6-(38-6*6)', '$6 \times 6 = 36$, so 6 full bags use 36 rolls and 2 rolls are left. The last bag has 2 rolls and needs $6 - 2 = 4$ more.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38 = 6 x 6 + 2; last bag has 2, needs 6 - 2 = 4 more.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1949fc3c-04fc-4586-aded-6e067e14e4ac', 'NC26.4.ANR.3', 3, 'numeric', 'Remainders', 'A whole number between 40 and 49 leaves a remainder of 3 when it is divided by 7. What is the number?', '[]', '45', '7*6+3', 'Multiples of 7 near this range are 42 and 49. The number is 3 more than a multiple of 7: $42 + 3 = 45$. Check: $45 \div 7 = 6$ remainder 3.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7k + 3: 38, 45, 52. Only 45 is between 40 and 49 (45 = 7 x 6 + 3).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da2385ad-c9f7-463e-ac42-05b4585986b5', 'NC26.4.ANR.3', 3, 'choice', 'Remainders', 'Which division has the greatest remainder?', '["$50 \\div 9$","$50 \\div 6$","$50 \\div 7$","$50 \\div 8$"]', '$50 \div 9$', NULL, '$50 \div 9 = 5$ remainder 5, $50 \div 6 = 8$ remainder 2, $50 \div 7 = 7$ remainder 1, and $50 \div 8 = 6$ remainder 2. The greatest remainder is 5.', 'checked', '{"lint":[],"solve":{"answer":"$50 \\div 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50/9 = 5 r 5; 50/6 = 8 r 2; 50/8 = 6 r 2; 50/7 = 7 r 1. Greatest remainder 5.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f84e3b2-76ff-4cce-85d2-7cfa0bdc6f4d', 'NC26.4.ANR.4', 1, 'numeric', 'Two-step problem: multiply then subtract', 'Ben has 5 packs of cards with 8 cards in each pack. He gives 6 cards to a friend. How many cards does Ben have left?', '[]', '34', '5*8-6', 'First find how many cards Ben starts with: 5 x 8 = 40. Then subtract the 6 he gives away: 40 - 6 = 34.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 8 = 40 cards; 40 - 6 = 34.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
