INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d31817c8-cec9-41f7-8203-2b613ddef06d', 'NC26.4.ANR.4', 1, 'choice', 'Two-step problem: add and subtract', 'Lena had 25 stickers. She got 12 more from a friend, then gave 9 to her brother. How many stickers does Lena have now?', '["46","22","28","37"]', '28', '25+12-9', 'First add: $25 + 12 = 37$. Then subtract: $37 - 9 = 28$. The choice 37 stops after the first step, 46 adds all three numbers, and 22 swaps the adding and the subtracting.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + 12 = 37; 37 - 9 = 28.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
