INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f240ae8d-8e05-4466-b8de-a7984bd46972', 'NC26.4.ANR.4', 1, 'choice', 'Two-step problem: add and subtract', 'A bus has 30 riders. At the first stop 8 riders get off. At the second stop 5 riders get on. How many riders are on the bus now?', '["27","17","33","43"]', '27', '30-8+5', '$30 - 8 = 22$ riders are left after the first stop. Then $22 + 5 = 27$ after the second stop.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 - 8 = 22; 22 + 5 = 27.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
