VALUES ('74aae06e-606e-47b6-8bf3-10ae697fd169', 'NC26.4.ANR.4', 1, 'choice', 'Two-step problem: divide, then add or subtract', 'A pack of 28 cards is split equally between 2 players. One player loses 3 cards. How many cards does that player have now?', '["25","14","11","17"]', '11', '28/2-3', 'Each player gets $28 \div 2 = 14$ cards. After losing 3, that player has $14 - 3 = 11$ cards.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 2 = 14; 14 - 3 = 11.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
