INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70cac8d6-5ea8-4305-8b75-5bb58dc58795', 'NC26.4.ANR.4', 1, 'choice', 'Equation with a letter: solve a two-step equation', 'Which value of $n$ makes $n \times 5 + 2 = 17$ true?', '["15","3","4","7"]', '3', '(17-2)/5', 'Take away 2: $17 - 2 = 15$, so $n \times 5 = 15$ and $n = 3$. Check: $3 \times 5 + 2 = 17$. The choice 15 stops before dividing by 5.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5n = 15; n = 3. Check 3 x 5 + 2 = 17.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
