INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7a751d3-134b-490f-bd36-1ac15abcfb61', 'NC26.4.ANR.4', 1, 'choice', 'Equation with a letter: find the unknown in one step', 'Which value of $w$ makes $w - 17 = 25$ true?', '["8","42","32","52"]', '42', '25+17', 'Undo the subtraction by adding: $w = 25 + 17 = 42$. Check: $42 - 17 = 25$. The choice 8 subtracts instead of adding.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w = 25 + 17 = 42.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
