INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b342a0d2-b9bf-42bc-8302-23024cceb4d0', 'NC26.4.ANR.4', 1, 'numeric', 'Check by estimation: sum or difference', 'Round each number to the nearest ten, then add: $38 + 53$. What is the estimate?', '[]', '90', '40+50', '38 rounds to 40 and 53 rounds to 50. The estimate is $40 + 50 = 90$.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38 -> 40, 53 -> 50; 40 + 50 = 90.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
