INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c97ec074-38f2-49bb-b973-95176ab71296', 'NC26.4.ANR.4', 1, 'numeric', 'Check by estimation: product', 'Round 39 to the nearest ten. Then use it to estimate $39 \times 2$.', '[]', '80', '40*2', '39 rounds to 40. The estimate is $40 \times 2 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"39 -> 40; 40 x 2 = 80.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
