INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38f5a4fb-1f37-41d2-85d1-0045fb7bbca7', 'NC26.4.ANR.4', 1, 'choice', 'Check by estimation: product', 'Which is the best estimate for $4 \times 61$?', '["24","240","400","65"]', '240', '4*60', '61 is close to 60, so the estimate is $4 \times 60 = 240$. The choice 65 adds, and 24 is too small by a factor of 10.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"61 -> 60; 4 x 60 = 240 (exact 244).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
