INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90dc0e89-0c3d-498a-be5c-cd04bcbed429', 'NC26.4.ANR.4', 2, 'choice', 'Two-step problem: add and subtract', 'Mia scored 87 points in the first game and 94 points in the second game. She wants 200 points in all after a third game. How many points does she need in the third game?', '["113","106","381","19"]', '19', '200-87-94', 'So far she has $87 + 94 = 181$ points. She needs $200 - 181 = 19$ more. The choices 113 and 106 each subtract only one game, and 381 adds everything.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"87 + 94 = 181; 200 - 181 = 19.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
