INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfd86051-20b1-44e0-903d-f73f476d98c7', 'NC26.4.ANR.4', 2, 'choice', 'Two-step problem: multiply, then add or subtract', 'A theater has 14 rows with 12 seats in each row. 38 seats are taken. How many seats are empty?', '["168","206","64","130"]', '130', '14*12-38', 'The theater has $14 \times 12 = 168$ seats. Empty seats: $168 - 38 = 130$.', 'checked', '{"lint":[],"solve":{"answer":"130","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 12 = 168; 168 - 38 = 130.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
