INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93bd1d69-461e-4a5b-aee1-3b69fac8650c', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: multiply, then add or subtract', 'Each bus carries 45 students. 7 buses are full, and 18 more students ride in vans. How many students go on the trip?', '[]', '333', '45*7+18', 'The buses carry $45 \times 7 = 315$ students. Add the van riders: $315 + 18 = 333$ students.', 'checked', '{"lint":[],"solve":{"answer":"333","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 x 7 = 315; 315 + 18 = 333.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
