INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6491ff4-db3d-4350-91c2-c73e558509c4', 'NC26.4.ANR.4', 2, 'choice', 'Two-step problem: multiply and divide', 'A florist makes 8 bunches with 9 flowers in each bunch. She puts all the flowers into vases with 6 flowers in each vase. How many vases does she fill?', '["72","17","12","9"]', '12', '8*9/6', 'She has $8 \times 9 = 72$ flowers. The number of vases is $72 \div 6 = 12$. The choice 72 stops after the first step.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 9 = 72 flowers; 72 / 6 = 12 vases.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
