INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e43b4881-3be1-49df-95e5-1ea748b09b91', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: multiply and divide', 'A teacher buys 5 packs of 12 pencils and shares all of the pencils equally among 6 students. How many pencils does each student get?', '[]', '10', '5*12/6', 'She has $5 \times 12 = 60$ pencils. Each student gets $60 \div 6 = 10$ pencils.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 12 = 60; 60 / 6 = 10.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
