INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35e4fe90-891d-428b-870c-f576b8112a85', 'NC26.4.ANR.4', 2, 'choice', 'Two-step problem with a remainder', 'Maria has 43 beads and buys 17 more. She makes bracelets with 8 beads each. How many bracelets can she make?', '["7","8","5","4"]', '7', '(43+17-4)/8', 'She has $43 + 17 = 60$ beads. Since $8 \times 7 = 56$, she can make 7 bracelets, with 4 beads left over, not enough for an eighth. The choice 5 divides only 43 by 8, and 4 is the number of beads left over.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"43 + 17 = 60; 60 = 8 x 7 + 4, so 7 bracelets.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('833ad1a3-6c5d-4632-bac0-c6774a5a9c3f', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: multiplicative comparison', 'Rita has 9 marbles. Sol has 6 times as many marbles as Rita. How many fewer marbles does Rita have than Sol?', '[]', '45', '9*6-9', 'Sol has $6 \times 9 = 54$ marbles. Rita has $54 - 9 = 45$ fewer marbles.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sol = 6 x 9 = 54; 54 - 9 = 45.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
