INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de7e0775-a168-46c0-9464-d90c6be5cec7', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: multiplicative comparison', 'The red bin holds 7 times as many toys as the blue bin. The red bin holds 63 toys. How many toys do the two bins hold together?', '[]', '72', '63+63/7', 'The blue bin holds $63 \div 7 = 9$ toys. Together the bins hold $63 + 9 = 72$ toys.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = 63 / 7 = 9; together 63 + 9 = 72.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
