INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a7a1bcb-908e-486e-aa2e-87a9b8e7317d', 'NC26.4.ANR.4', 2, 'choice', 'Equation with a letter: choose the equation for a story', 'There are 48 players on teams of 6 players each. After 2 teams leave, $t$ teams are left. Which equation matches the story?', '["$48 \\div 6 + 2 = t$","$48 - 6 - 2 = t$","$48 \\div (6 - 2) = t$","$48 \\div 6 - 2 = t$"]', '$48 \div 6 - 2 = t$', NULL, 'First find the number of teams: $48 \div 6$. Then 2 teams leave, so subtract 2: $48 \div 6 - 2 = t$. That gives $t = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$48 \\div 6 - 2 = t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 6 = 8 teams; minus 2 leaves t: 48 / 6 - 2 = t (t = 6). 48/(6-2) = 12 is wrong.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d868ff03-3e29-4dc9-ab06-57abb06e51ec', 'NC26.4.ANR.4', 2, 'choice', 'Equation with a letter: choose the equation for a story', 'Max had 150 dollars. He spent 35 dollars and then earned $e$ more dollars. Now he has 160 dollars. Which equation matches the story?', '["$150 - 35 + e = 160$","$150 + 35 + e = 160$","$150 - 35 - e = 160$","$150 - e + 35 = 160$"]', '$150 - 35 + e = 160$', NULL, 'Spending takes 35 away and earning adds $e$. So $150 - 35 + e = 160$. Solving gives $e = 45$.', 'checked', '{"lint":[],"solve":{"answer":"$150 - 35 + e = 160$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 - 35 + e = 160 (e = 45). 150 - e + 35 gives e = 25, a different story.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
