INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1afdcdb5-84e0-442d-83d4-f8135a96f42c', 'NC26.4.ANR.4', 2, 'choice', 'Equation with a letter: choose the equation for a story', 'Pia has 100 beads. She uses $b$ beads on a necklace. She puts the rest equally into 4 bags with 12 beads in each bag. Which equation matches the story?', '["$100 - b = 4 + 12$","$100 - b = 4 \\times 12$","$100 - 4 = b \\times 12$","$100 + b = 4 \\times 12$"]', '$100 - b = 4 \times 12$', NULL, 'After the necklace, $100 - b$ beads are left. The 4 bags hold $4 \times 12$ beads. So $100 - b = 4 \times 12$, which gives $b = 52$.', 'checked', '{"lint":[],"solve":{"answer":"$100 - b = 4 \\times 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rest is 100 - b, which is 4 bags of 12: 100 - b = 4 x 12 (b = 52).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b3c3fa5-6799-43f6-8557-92dda21e952d', 'NC26.4.ANR.4', 2, 'numeric', 'Equation with a letter: solve a two-step equation', 'Find the value of $x$: $8 \times x - 15 = 49$.', '[]', '8', '(49+15)/8', 'Undo the subtraction by adding 15: $49 + 15 = 64$, so $8 \times x = 64$. Then $x = 64 \div 8 = 8$. Check: $8 \times 8 - 15 = 49$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x = 49 + 15 = 64; x = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
