VALUES ('afc03830-085b-44e2-8643-3f42804c388d', 'NC26.4.ANR.4', 2, 'choice', 'Check by estimation: sum or difference', 'Estimate $4{,}816 + 2{,}193$ by rounding each number to the nearest thousand. Which estimate is correct?', '["$6{,}000$","$8{,}000$","$7{,}100$","$7{,}000$"]', '$7{,}000$', NULL, '$4{,}816$ rounds to $5{,}000$ and $2{,}193$ rounds to $2{,}000$. The estimate is $5{,}000 + 2{,}000 = 7{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"$7{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,816 -> 5,000; 2,193 -> 2,000; sum 7,000.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
