VALUES ('42972e09-ab2f-4602-8d46-2480d78e592f', 'NC26.4.ANR.4', 2, 'numeric', 'Check by estimation: product', 'Estimate $48 \times 21$ by rounding each number to the nearest ten.', '[]', '1000', '50*20', '48 rounds to 50 and 21 rounds to 20. The estimate is $50 \times 20 = 1{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 -> 50, 21 -> 20; 50 x 20 = 1,000.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
