VALUES ('30000b15-585d-4ed4-a531-e0ace2350a41', 'NC26.4.ANR.4', 2, 'choice', 'Check by estimation: product', 'A bus costs 288 dollars a day to rent. Which is the best estimate of the cost for 6 days, in dollars?', '["$1{,}800$","$180$","$1{,}200$","$2{,}400$"]', '$1{,}800$', NULL, '288 is close to 300, so the estimate is $300 \times 6 = 1{,}800$ dollars. The choice $1{,}200$ uses 200 and $2{,}400$ uses 400, which are not close to 288.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}800$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"288 -> 300; 300 x 6 = 1,800 (exact 1,728).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
