VALUES ('368e2c4e-f2ca-4d91-85bd-ecc071d1b6b0', 'NC26.4.ANR.4', 2, 'choice', 'Check by estimation: quotient', 'Which is the best estimate for $2{,}412 \div 6$?', '["$40$","$4{,}000$","$200$","$400$"]', '$400$', NULL, '$2{,}412$ is close to $2{,}400$, and $2{,}400 \div 6 = 400$. The choices $40$ and $4{,}000$ are off by a factor of 10.', 'checked', '{"lint":[],"solve":{"answer":"$400$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,412 is close to 2,400; 2,400 / 6 = 400 (exact 402).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
