INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5a093f1-47ff-43bd-807a-0fbde2d5db2d', 'NC26.4.ANR.4', 2, 'numeric', 'Check by estimation: a two-step answer', 'A farm has 31 rows of corn with 49 plants in each row. Deer eat 205 of the plants. Round 31 to 30, 49 to 50 and 205 to 200. Use them to estimate how many plants are left.', '[]', '1300', '30*50-200', 'The farm has about $30 \times 50 = 1{,}500$ plants. After the deer, about $1{,}500 - 200 = 1{,}300$ plants are left.', 'checked', '{"lint":[],"solve":{"answer":"1300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 50 = 1,500; 1,500 - 200 = 1,300 (exact 1,519 - 205 = 1,314).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
