INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ef4d1f6-e4ef-4161-a627-2732a71086e0', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem with a remainder', 'A baker makes 7 trays of 18 muffins. Each box holds 5 muffins. How many boxes are needed to hold all of the muffins?', '["25","26","27","21"]', '26', '(126-1)/5+1', 'The baker has $7 \times 18 = 126$ muffins. Since $5 \times 25 = 125$, 25 full boxes leave 1 muffin, which needs one more box. That is $25 + 1 = 26$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 18 = 126; 126 = 5 x 25 + 1, so 25 full boxes plus 1 more: 26.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86060201-f6b6-446a-a4b8-3b79d666eb12', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: multiplicative comparison', 'Ana has 6 times as many dollars as Ben. Together they have 56 dollars. How many dollars does Ben have?', '["8","48","50","28"]', '8', '56/7', 'Ben has 1 part and Ana has 6 parts, so there are $1 + 6 = 7$ equal parts in all. One part is $56 \div 7 = 8$ dollars, so Ben has 8 dollars. Ana has $6 \times 8 = 48$ dollars, which is the choice 48.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ben 1 part, Ana 6 parts: 7 parts = 56, 1 part = 8. Ben 8, Ana 48.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0123532d-8088-4ff3-92ad-10e75a037048', 'NC26.4.ANR.4', 3, 'choice', 'Equation with a letter: choose the equation for a story', 'Jin has 3 bags with $m$ marbles in each bag and 9 loose marbles. He has 36 marbles in all. Which equation does NOT match this story?', '["$3 \\times m + 9 = 36$","$36 - 9 = 3 \\times m$","$36 - 3 \\times m = 9$","$3 \\times m = 36 + 9$"]', '$3 \times m = 36 + 9$', NULL, 'The story says $3 \times m + 9 = 36$. The equations $36 - 9 = 3 \times m$ and $36 - 3 \times m = 9$ say the same thing in other ways. But $3 \times m = 36 + 9$ adds the loose marbles instead of taking them away.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times m = 36 + 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3m + 9 = 36 gives m = 9. 36 - 9 = 3m and 36 - 3m = 9 are equivalent. 3m = 36 + 9 gives m = 15: does not match.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('194026d5-448d-4526-a4ca-c69f6c49f46f', 'NC26.4.ANR.4', 3, 'choice', 'Equation with a letter: choose the equation for a story', 'Which story matches $(n - 6) \div 3 = 8$?', '["Pia had $n$ pencils. She gave away 6 and shared the rest equally among 3 friends. Each friend got 8.","Pia had $n$ pencils. She gave 6 pencils to each of 3 friends. She had 8 pencils left.","Pia had 6 pencils. She got $n$ more and shared them all equally among 3 friends. Each friend got 8.","Pia had $n$ pencils. She shared them equally among 6 friends and then gave each friend 3 more. Each friend had 8."]', 'Pia had $n$ pencils. She gave away 6 and shared the rest equally among 3 friends. Each friend got 8.', NULL, 'In $(n - 6) \div 3 = 8$, first 6 is taken away from $n$, then the rest is divided by 3, and the result is 8. Only the first story does this. Solving gives $n = 30$.', 'checked', '{"lint":[],"solve":{"answer":"Pia had $n$ pencils. She gave away 6 and shared the rest equally among 3 friends. Each friend got 8.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(n - 6) / 3 = 8: take 6 away, share rest among 3, each gets 8. B is n - 18 = 8; C is (6 + n) / 3 = 8; D is n / 6 + 3 = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f54e171e-8d52-4ca2-a90b-b42be88f46ff', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: solve a two-step equation', 'Find the value of $n$: $9 \times (n + 4) = 81$.', '[]', '5', '81/9-4', 'Divide by 9: $n + 4 = 81 \div 9 = 9$. Then $n = 9 - 4 = 5$. Check: $9 \times (5 + 4) = 81$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + 4 = 81 / 9 = 9; n = 5.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cd7971e-9572-4025-8140-49da23fa46fd', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: solve a two-step equation', 'Find the value of $n$: $(n - 8) \div 5 = 12$.', '[]', '68', '12*5+8', 'Undo the division: $n - 8 = 12 \times 5 = 60$. Then $n = 60 + 8 = 68$. Check: $(68 - 8) \div 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - 8 = 12 x 5 = 60; n = 68.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
