INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3d2cf9c-9250-4e82-ac56-1aa0f18530ab', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: solve a two-step equation', 'Find the value of $n$: $9 \times n - 4 \times 7 = 53$.', '[]', '9', '(53+4*7)/9', 'Work out $4 \times 7 = 28$. Then $9 \times n - 28 = 53$, so $9 \times n = 53 + 28 = 81$ and $n = 9$. Check: $81 - 28 = 53$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 7 = 28; 9n = 53 + 28 = 81; n = 9.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
