INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a25f56e6-c4bc-4967-a8d3-5976b51e7aa1', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: write and solve for a story', 'A school buys $b$ boxes of paper. Each box has 12 packs. After the school uses 15 packs, 81 packs are left. How many boxes did the school buy?', '[]', '8', '(81+15)/12', 'The equation is $12 \times b - 15 = 81$. Add 15: $12 \times b = 96$. Then $b = 96 \div 12 = 8$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12b - 15 = 81; 12b = 96; b = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('edc388fb-3c79-4af9-b9e1-6ac89121a418', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: write and solve for a story', 'Dina saves the same amount each week for 9 weeks. Then she spends 35 dollars on a gift and has 100 dollars left. How many dollars did she save each week?', '[]', '15', '(100+35)/9', 'Let $s$ be the dollars saved each week. The equation is $9 \times s - 35 = 100$. Add 35: $9 \times s = 135$. Then $s = 135 \div 9 = 15$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Saved 100 + 35 = 135 in 9 weeks; 135 / 9 = 15.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
