INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1c299f5-f80a-469e-8212-c5c828a22862', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: sum or difference', 'Mia estimates $6{,}382 - 2{,}718$ by rounding each number to the nearest thousand. What estimate does she get?', '["$4{,}000$","$3{,}700$","$3{,}000$","$9{,}000$"]', '$3{,}000$', NULL, '$6{,}382$ rounds to $6{,}000$ and $2{,}718$ rounds to $3{,}000$. The estimate is $6{,}000 - 3{,}000 = 3{,}000$. The choice $3{,}700$ rounds to the nearest hundred instead.', 'checked', '{"lint":[],"solve":{"answer":"$3{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,382 -> 6,000; 2,718 -> 3,000; 6,000 - 3,000 = 3,000.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
