VALUES ('dcafa3db-6690-4e9b-8efd-863b6ea1d2b9', 'NC26.4.ANR.5', 1, 'numeric', 'Compare decimals', 'Which of the numbers 0.2, 0.9, 0.5 and 0.1 is the greatest? Type that number.', '[]', '0.9', '9/10', 'Compare the tenths digits: 9 tenths is more than 5, 2 or 1 tenths. So 0.9 is the greatest.', 'checked', '{"lint":[],"solve":{"answer":"0.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tenths 2, 9, 5, 1; greatest 0.9.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
