VALUES ('e4374c74-e234-4897-bf06-1a1f19a58f3e', 'NC26.4.ANR.5', 1, 'choice', 'Place value in decimals', 'What is the value of the digit 4 in the number 0.04?', '["4 tenths","4 hundredths","4 ones","4 tens"]', '4 hundredths', NULL, 'The 4 is in the second place after the decimal point, the hundredths place. Its value is 4 hundredths.', 'checked', '{"lint":[],"solve":{"answer":"4 hundredths","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.04: 0 tenths, 4 hundredths.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
