VALUES ('c28fafc8-8950-4e68-83c5-284c22411e2b', 'NC26.4.ANR.5', 1, 'numeric', 'Find a number between two numbers', 'What decimal with one digit after the decimal point is between 0.2 and 0.4?', '[]', '0.3', '(0.2+0.4)/2', 'The only tenth between 0.2 and 0.4 is 0.3.', 'checked', '{"lint":[],"solve":{"answer":"0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tenths between 0.2 and 0.4: only 0.3.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
