INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('570aa56a-b13f-486b-9bb2-74c49c6e957c', 'NC26.4.ANR.5', 2, 'choice', 'Order fractions', 'Put these fractions in order, starting with the least: $\frac{1}{3}$, $\frac{5}{6}$ and $\frac{1}{2}$. Which list is right?', '["$\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{5}{6}$","$\\frac{5}{6}$, $\\frac{1}{2}$, $\\frac{1}{3}$","$\\frac{1}{3}$, $\\frac{5}{6}$, $\\frac{1}{2}$"]', '$\frac{1}{3}$, $\frac{1}{2}$, $\frac{5}{6}$', NULL, 'Use sixths: $\frac{1}{3} = \frac{2}{6}$, $\frac{1}{2} = \frac{3}{6}$ and $\frac{5}{6}$. Least to greatest: $\frac{2}{6}$, $\frac{3}{6}$, $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 2/6, 1/2 = 3/6, 5/6. Order 1/3, 1/2, 5/6.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3256dfe3-0fc0-4f81-9fd6-740244b1f0dd', 'NC26.4.ANR.5', 2, 'numeric', 'Order fractions', 'Which is the least fraction in this list: $\frac{3}{4}$, $\frac{5}{8}$, $\frac{7}{8}$ and $\frac{1}{2}$? Type that fraction.', '[]', '1/2', '1/2', 'Use eighths: $\frac{3}{4} = \frac{6}{8}$, $\frac{5}{8}$, $\frac{7}{8}$ and $\frac{1}{2} = \frac{4}{8}$. The least is $\frac{4}{8}$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In eighths: 6/8, 5/8, 7/8, 4/8. Least 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
