INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('664b2d24-537c-4a21-8bd7-306bd61fd03c', 'NC26.4.ANR.5', 2, 'choice', 'Order decimals', 'Which list shows 1.2, 1.02, 1.25 and 0.9 in order from greatest to least?', '["0.9, 1.02, 1.2, 1.25","1.25, 1.2, 1.02, 0.9","1.25, 1.02, 1.2, 0.9","1.2, 1.25, 1.02, 0.9"]', '1.25, 1.2, 1.02, 0.9', NULL, '0.9 is less than 1. Among the numbers that start with 1: 1.25 has 2 tenths and 5 hundredths, 1.2 has 2 tenths, and 1.02 has 0 tenths. Greatest to least: 1.25, 1.2, 1.02, 0.9.', 'checked', '{"lint":[],"solve":{"answer":"1.25, 1.2, 1.02, 0.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In hundredths: 1.20, 1.02, 1.25, 0.90. Greatest to least: 1.25, 1.2, 1.02, 0.9.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
