INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03d749a-0a92-40e5-a44a-bf11211b2c26', 'NC26.4.ANR.5', 3, 'numeric', 'Find a missing number in equivalent fractions', '$\frac{16}{24} = \frac{2}{n}$ The top and bottom of the first fraction were divided by the same number to get the second fraction. What is $n$?', '[]', '3', '24/(16/2)', 'The top number was divided by 8 ($16 \div 8 = 2$), so divide the bottom number by 8: $24 \div 8 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16/8 = 2, so divided by 8; 24/8 = 3.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eebbe539-ff99-4d3c-8681-da274bb7bd06', 'NC26.4.ANR.5', 3, 'numeric', 'Find a missing number in equivalent fractions', '$\frac{2}{5} = \frac{n}{15} = \frac{12}{m}$ What is the value of $n + m$?', '[]', '36', '2*(15/5)+5*(12/2)', 'From 5 to 15 is times 3, so $n = 2 \times 3 = 6$. From 2 to 12 is times 6, so $m = 5 \times 6 = 30$. Then $n + m = 6 + 30 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = n/15 -> x3 -> n = 6. 2/5 = 12/m -> x6 -> m = 30. n + m = 36.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('debabb23-0cc8-4506-9141-858f66fee0e7', 'NC26.4.ANR.5', 3, 'choice', 'Recognize equivalent fractions', 'Which equation is true?', '["$\\frac{5}{8} = \\frac{10}{20}$","$\\frac{4}{6} = \\frac{10}{15}$","$\\frac{3}{9} = \\frac{6}{12}$","$\\frac{7}{8} = \\frac{21}{32}$"]', '$\frac{4}{6} = \frac{10}{15}$', NULL, 'Both $\frac{4}{6}$ and $\frac{10}{15}$ simplify to $\frac{2}{3}$. $\frac{10}{20}$ is one half, not $\frac{5}{8}$. $\frac{6}{12}$ is one half, not $\frac{1}{3}$. $\frac{7}{8} = \frac{28}{32}$, not $\frac{21}{32}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6} = \\frac{10}{15}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/20 = 1/2 != 5/8; 3/9 = 1/3, 6/12 = 1/2 no; 7/8 = 21/24 != 21/32; 4/6 = 2/3 and 10/15 = 2/3 true.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
