INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e66a87d-5c75-40d6-867f-c53129ed9724', 'NC26.4.ANR.5', 3, 'choice', 'Recognize equivalent fractions', 'Three of these fractions name the same amount. Which one does not?', '["$\\frac{3}{5}$","$\\frac{6}{10}$","$\\frac{9}{15}$","$\\frac{12}{25}$"]', '$\frac{12}{25}$', NULL, '$\frac{3}{5}$, $\frac{6}{10}$ and $\frac{9}{15}$ are made by multiplying the top and bottom of $\frac{3}{5}$ by 1, 2 and 3. $\frac{12}{25}$ is different: $\frac{12}{20}$ would have matched.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{12}{25}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: denominator 25 is outside the usual Grade 4 set (2,3,4,5,6,8,10,12,100), though only recognising non-equivalence is needed.","work":"3/5 = 6/10 = 9/15 (x2, x3). 3/5 = 15/25, so 12/25 is the odd one.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9ecd71d-5cb3-4862-889e-8e5f1bd35541', 'NC26.4.ANR.5', 3, 'numeric', 'Equivalent fractions in a story', 'Leo ate $\frac{3}{4}$ of a loaf of bread. Kim has a loaf of the same size that is cut into 12 equal pieces. How many pieces of Kim''s loaf must she eat to have eaten the same amount as Leo?', '[]', '9', '3*(12/4)', 'There are $12 \div 4 = 3$ twelfths in each fourth. Three fourths is $3 \times 3 = 9$ twelfths, so $\frac{3}{4} = \frac{9}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 9/12 (x3), so 9 pieces.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b129b119-c368-4d60-b5dc-cae751b83578', 'NC26.4.ANR.5', 3, 'numeric', 'Compare a fraction with one half', 'For how many whole numbers $n$ from 1 to 11 is $\frac{n}{12}$ less than one half?', '[]', '5', '12/2-1', 'One half is $\frac{6}{12}$. The numbers $n = 1, 2, 3, 4, 5$ give fractions less than $\frac{6}{12}$. That is 5 numbers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 6/12, so n < 6: n = 1,2,3,4,5 -> 5 numbers.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64a106c5-beb0-42a4-9dcf-d8a42e4e0028', 'NC26.4.ANR.5', 3, 'numeric', 'Use the benchmarks 0, one half and 1', 'Look at these fractions: $\frac{1}{10}$, $\frac{4}{9}$, $\frac{5}{6}$, $\frac{11}{12}$ and $\frac{7}{12}$. How many of them are closer to one half than to 0 or to 1?', '[]', '2', NULL, '$\frac{4}{9}$ is just under half and $\frac{7}{12}$ is just over half, so they are closest to one half. $\frac{1}{10}$ is close to 0, and $\frac{5}{6}$ and $\frac{11}{12}$ are close to 1. So 2 fractions.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/10: near 0. 4/9: 1/18 from 1/2 -> half. 5/6: 1/6 from 1 vs 1/3 from 1/2 -> 1. 11/12 -> 1. 7/12: 1/12 from 1/2 -> half. Count = 2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c728d3bd-d2d9-437d-b86b-93c44f72b29f', 'NC26.4.ANR.5', 3, 'choice', 'Compare fractions with the same denominator or numerator', 'Eli says $\frac{1}{6}$ is greater than $\frac{1}{4}$ because 6 is greater than 4. What is wrong with Eli''s thinking?', '["With the same top number, more equal parts means smaller pieces, so $\\frac{1}{6}$ is less.","Nothing is wrong, because a greater bottom number always means a greater fraction.","Fractions with different bottom numbers cannot be compared.","The two fractions are equal, because both have 1 on top."]', 'With the same top number, more equal parts means smaller pieces, so $\frac{1}{6}$ is less.', NULL, 'Cutting a whole into 6 equal parts makes smaller pieces than cutting it into 4 equal parts. So one sixth is less than one fourth.', 'checked', '{"lint":[],"solve":{"answer":"With the same top number, more equal parts means smaller pieces, so $\\frac{1}{6}$ is less.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6 < 1/4: more equal parts makes smaller pieces.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7fae8809-8fe6-4e64-ae9c-90f0d13f19a9', 'NC26.4.ANR.5', 3, 'choice', 'Compare fractions with unlike denominators', 'Which of these four fractions is the greatest?', '["$\\frac{7}{8}$","$\\frac{5}{6}$","$\\frac{3}{4}$","$\\frac{2}{3}$"]', '$\frac{7}{8}$', NULL, 'Use a common denominator of 24: $\frac{5}{6} = \frac{20}{24}$, $\frac{7}{8} = \frac{21}{24}$, $\frac{3}{4} = \frac{18}{24}$ and $\frac{2}{3} = \frac{16}{24}$. The greatest is $\frac{7}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each is 1 piece short of 1: 1/6, 1/8, 1/3, 1/4 missing. Smallest missing piece 1/8, so 7/8 greatest.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6882600c-6564-47a7-a5c4-4bed0fac879e', 'NC26.4.ANR.5', 3, 'numeric', 'Compare fractions with unlike denominators', 'What is the least whole number $n$ for which $\frac{n}{5}$ is greater than $\frac{3}{4}$?', '[]', '4', NULL, 'Three fourths is $\frac{15}{20}$. Try $n = 3$: $\frac{3}{5} = \frac{12}{20}$, which is less. Try $n = 4$: $\frac{4}{5} = \frac{16}{20}$, which is greater than $\frac{15}{20}$. So $n = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 15/20, n/5 = 4n/20. Need 4n > 15 -> n >= 4. 4/5 = 16/20 > 15/20; 3/5 = 12/20 not.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5f858ea-191b-46be-bd25-dd60d3fa04d5', 'NC26.4.ANR.5', 3, 'choice', 'Order fractions', 'Four friends each ran part of a mile: Ana $\frac{2}{3}$, Ben $\frac{5}{6}$, Cal $\frac{1}{2}$ and Dee $\frac{3}{4}$. Which list gives the distances from shortest to longest?', '["$\\frac{1}{2}$, $\\frac{3}{4}$, $\\frac{2}{3}$, $\\frac{5}{6}$","$\\frac{1}{2}$, $\\frac{2}{3}$, $\\frac{3}{4}$, $\\frac{5}{6}$","$\\frac{5}{6}$, $\\frac{3}{4}$, $\\frac{2}{3}$, $\\frac{1}{2}$","$\\frac{2}{3}$, $\\frac{1}{2}$, $\\frac{3}{4}$, $\\frac{5}{6}$"]', '$\frac{1}{2}$, $\frac{2}{3}$, $\frac{3}{4}$, $\frac{5}{6}$', NULL, 'Use twelfths: $\frac{1}{2} = \frac{6}{12}$, $\frac{2}{3} = \frac{8}{12}$, $\frac{3}{4} = \frac{9}{12}$ and $\frac{5}{6} = \frac{10}{12}$. That order is 6, 8, 9, 10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$, $\\frac{2}{3}$, $\\frac{3}{4}$, $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twelfths: 2/3=8/12, 5/6=10/12, 1/2=6/12, 3/4=9/12. Order 1/2, 2/3, 3/4, 5/6.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4eeec440-32d5-48c5-8ce1-0cb9e4a4f55c', 'NC26.4.ANR.5', 3, 'numeric', 'Order fractions', 'Three fractions are $\frac{7}{12}$, $\frac{1}{2}$ and $\frac{2}{3}$. When they are put in order from least to greatest, which fraction is in the middle? Type that fraction.', '[]', '7/12', '7/12', 'Use twelfths: $\frac{7}{12}$, $\frac{1}{2} = \frac{6}{12}$ and $\frac{2}{3} = \frac{8}{12}$. The order is $\frac{6}{12}$, $\frac{7}{12}$, $\frac{8}{12}$, so $\frac{7}{12}$ is in the middle.', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twelfths: 7/12, 1/2=6/12, 2/3=8/12. Order 6/12, 7/12, 8/12; middle 7/12.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
