INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ecedf5a-1f00-4ec0-842d-d76d3410ce93', 'NC26.4.ANR.5', 3, 'numeric', 'Write hundredths as decimals', 'Convert the fraction $\frac{105}{100}$ to a decimal number.', '[]', '1.05', '105/100', '$\frac{105}{100}$ is 1 whole ($\frac{100}{100}$) and 5 hundredths, so it is 1.05.', 'checked', '{"lint":[],"solve":{"answer":"1.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"105/100 = 1 + 5/100 = 1.05.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
