INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0fa4134-5085-4782-9517-b61124be5780', 'NC26.4.ANR.5', 3, 'choice', 'Write a decimal as a fraction', 'Which of these is NOT another way to write 0.40?', '["$\\frac{4}{10}$","$\\frac{4}{100}$","$\\frac{40}{100}$","0.4"]', '$\frac{4}{100}$', NULL, '0.40 = 0.4 = $\frac{4}{10}$ = $\frac{40}{100}$. But $\frac{4}{100}$ is 0.04, which is much less.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{100}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.40 = 40/100 = 4/10 = 0.4. 4/100 = 0.04 is not.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
