VALUES ('e3cac011-c64e-48a6-8886-fc5fff27b68c', 'NC26.4.ANR.5', 3, 'choice', 'Rename fractions as hundredths', 'Which decimal is equal to $\frac{3}{4}$?', '["0.75","0.34","3.4","0.7"]', '0.75', '3/4', 'Multiply the top and bottom of $\frac{3}{4}$ by 25: $\frac{75}{100}$, which is 0.75.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 75/100 = 0.75.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
