INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a4fa39a-84f8-466f-8ac4-4c77e7d5b020', 'NC26.4.ANR.5', 3, 'choice', 'Compare decimals', 'Which statement is false?', '["$0.30 = 0.3$","$0.3 > 0.29$","$0.03 < 0.3$","$0.30 > 0.4$"]', '$0.30 > 0.4$', NULL, '0.30 is 30 hundredths and 0.4 is 40 hundredths, so 0.30 is less than 0.4. That makes "0.30 > 0.4" false. The other three statements are true.', 'checked', '{"lint":[],"solve":{"answer":"$0.30 > 0.4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.30 = 0.3 true; 0.30 > 0.40 false; 0.03 < 0.30 true; 0.30 > 0.29 true. False one: 0.30 > 0.4.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
