INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('878d6fbc-da51-42b6-9f0b-bd935169cf1d', 'NC26.4.ANR.5', 3, 'numeric', 'Order decimals', 'Look at these numbers: 0.7, 0.07, 0.77 and 0.17. Which one is the second greatest?', '[]', '0.7', '0.7', 'In hundredths they are 70, 7, 77 and 17. From greatest to least: 0.77, 0.7, 0.17, 0.07. The second greatest is 0.7.', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.70, 0.07, 0.77, 0.17. Order: 0.77, 0.70, 0.17, 0.07. Second greatest 0.7.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
