INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48e9d867-19d7-4e1f-a914-64db2e40b02f', 'NC26.4.ANR.5', 3, 'choice', 'Order decimals', 'Arrange the numbers 0.2, 0.19, 0.3 and 0.09 from smallest to largest. Which list is right?', '["0.2, 0.09, 0.19, 0.3","0.09, 0.2, 0.19, 0.3","0.3, 0.2, 0.19, 0.09","0.09, 0.19, 0.2, 0.3"]', '0.09, 0.19, 0.2, 0.3', NULL, 'In hundredths the numbers are 20, 19, 30 and 9. Least to greatest: 9, 19, 20, 30, which is 0.09, 0.19, 0.2, 0.3.', 'checked', '{"lint":[],"solve":{"answer":"0.09, 0.19, 0.2, 0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.20, 0.19, 0.30, 0.09 -> 0.09, 0.19, 0.2, 0.3.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
