INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b747dab-27c5-4cf5-83ff-ad39b59e6974', 'NC26.4.ANR.6', 1, 'choice', 'Decompose a fraction or a mixed number', 'Which shows $\frac{3}{8}$ as a sum of unit fractions?', '["$\\frac{1}{8} + \\frac{1}{8} + \\frac{1}{8}$","$\\frac{1}{8} + \\frac{1}{8}$","$\\frac{1}{3} + \\frac{1}{3} + \\frac{1}{3}$","$\\frac{3}{8} + \\frac{3}{8}$"]', '$\frac{1}{8} + \frac{1}{8} + \frac{1}{8}$', NULL, 'A unit fraction has 1 on top. Three eighths is three copies of $\frac{1}{8}$: $\frac{1}{8} + \frac{1}{8} + \frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8} + \\frac{1}{8} + \\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 1/8 + 1/8 + 1/8 (three unit fractions).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
