VALUES ('4c109b89-f73d-4023-87a8-37c73786b0fa', 'NC26.4.ANR.6', 1, 'choice', 'Multiply a fraction by a whole number', 'Which expression is equal to $\frac{6}{8}$?', '["$6 \\times \\frac{1}{8}$","$8 \\times \\frac{1}{6}$","$6 + \\frac{1}{8}$","$6 \\times 8$"]', '$6 \times \frac{1}{8}$', NULL, '$6 \times \frac{1}{8}$ means 6 pieces that are each one eighth, which is $\frac{6}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times \\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/8 = 6 x 1/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
