INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('415a6e98-6dbb-4499-8ff2-e93a075cf1ce', 'NC26.4.ANR.6', 2, 'numeric', 'Decompose a fraction or a mixed number', '$\frac{9}{10} = \frac{3}{10} + \frac{n}{10} + \frac{4}{10}$ What is $n$?', '[]', '2', '9-3-4', 'The three parts must make 9 tenths. $3 + 4 = 7$, so $n = 9 - 7 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 3 + n + 4, so n = 2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
