INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('886c2570-6fb9-49c6-a364-9a016e068c5e', 'NC26.4.ANR.6', 2, 'choice', 'Multiply a fraction by a whole number in a story', 'A board is $\frac{3}{5}$ meter long. Three boards of this size are laid end to end. How long is the line of boards, in meters?', '["$\\frac{9}{15}$","$1\\frac{1}{5}$","$1\\frac{4}{5}$","$\\frac{3}{15}$"]', '$1\frac{4}{5}$', NULL, '$3 \times \frac{3}{5} = \frac{9}{5}$. Five fifths make 1 meter, so $\frac{9}{5} = 1\frac{4}{5}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{4}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3/5 = 9/5 = 1 4/5 m.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
