INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d30e91f-9aad-4d88-9a76-0dea233e4039', 'NC26.4.ANR.6', 3, 'choice', 'Subtract mixed numbers with like denominators', 'What is $6 - 2\frac{1}{4}$?', '["$4\\frac{1}{4}$","$3\\frac{1}{4}$","$3\\frac{3}{4}$","$4\\frac{3}{4}$"]', '$3\frac{3}{4}$', NULL, 'Write 6 as $5\frac{4}{4}$. Then $5\frac{4}{4} - 2\frac{1}{4} = 3\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 5 4/4; 5 4/4 - 2 1/4 = 3 3/4.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
