VALUES ('271271e6-b9da-40dc-b644-7f232cc6b4b4', 'NC26.4.ANR.6', 3, 'choice', 'Multiply a fraction by a whole number', 'Which expression is NOT equal to $\frac{12}{5}$?', '["$12 \\times \\frac{1}{5}$","$6 \\times \\frac{2}{5}$","$4 \\times \\frac{3}{5}$","$2 \\times \\frac{5}{12}$"]', '$2 \times \frac{5}{12}$', NULL, '$12 \times \frac{1}{5}$, $6 \times \frac{2}{5}$ and $4 \times \frac{3}{5}$ all equal $\frac{12}{5}$. But $2 \times \frac{5}{12} = \frac{10}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times \\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2/5 = 12/5, 4 x 3/5 = 12/5, 12 x 1/5 = 12/5; 2 x 5/12 = 10/12, not 12/5.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
