INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d86f9abf-c24f-4cd6-8a92-4a98bbe8d0ba', 'NC26.4.ANR.6', 3, 'choice', 'Multiply a fraction by a whole number in a story', 'A path is made of 5 stones laid end to end. Each stone is $\frac{7}{12}$ foot long. How long is the path, in feet?', '["$2\\frac{11}{12}$","$\\frac{35}{60}$","$\\frac{12}{12}$","$5\\frac{7}{12}$"]', '$2\frac{11}{12}$', NULL, '$5 \times \frac{7}{12} = \frac{35}{12}$. Since $35 = 2 \times 12 + 11$, this is $2\frac{11}{12}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{11}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 7/12 = 35/12 = 2 11/12 ft.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
