INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8d56258-8290-4b37-8dd4-649805cf08ff', 'NC26.4.ANR.6', 3, 'choice', 'Find a fraction of a set in a story', 'In a class of 28 students, $\frac{3}{4}$ walk to school. How many students do NOT walk to school?', '["21","25","7","31"]', '7', '28-3/4*28', 'One fourth of 28 is 7, so three fourths is 21 students who walk. The rest, $28 - 21 = 7$ students, do not walk.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not walking = 1/4 of 28 = 7 (21 walk).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
