INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb433fe9-7614-4ada-b153-5c59a63c0855', 'NC26.4.ANR.6', 3, 'numeric', 'Find the whole when a fraction of it is known', '$\frac{1}{5}$ of the trees in an orchard are apple trees. There are 8 apple trees. How many trees are in the orchard?', '[]', '40', '8*5', 'If one fifth of the trees is 8 trees, then all 5 fifths are $5 \times 8 = 40$ trees.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 of the trees is 8, so all 5 fifths = 40.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5da8195-1183-4382-825d-e7ce099e4cc7', 'NC26.4.ANR.6', 3, 'numeric', 'Find the whole when a fraction of it is known', 'Ana has read $\frac{2}{3}$ of her book, which is 10 pages. How many pages are in the whole book?', '[]', '15', '10/(2/3)', 'Two thirds of the book is 10 pages, so one third is $10 \div 2 = 5$ pages. The whole book (3 thirds) is $3 \times 5 = 15$ pages.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 is 10 pages, so 1/3 is 5 pages; whole = 15.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a78d37cf-f49e-42b8-9118-1bc2ea9dfd8b', 'NC26.4.ANR.6', 3, 'numeric', 'Find a missing fraction in an equation', '$\frac{n}{8} + \frac{n}{8} = \frac{10}{8}$ The same number $n$ is used twice. What is $n$?', '[]', '5', '10/2', 'Two equal parts make 10 eighths, so each is $10 \div 2 = 5$ eighths. So $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + n = 10, n = 5.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68d578ef-1a94-40b9-9914-b06f6d789ab7', 'NC26.4.ANR.6', 3, 'numeric', 'Find a missing fraction in an equation', '$2 + \frac{n}{6} + 1\frac{4}{6} = 4$ What is $n$?', '[]', '2', '(4-2-1-4/6)*6', 'The wholes make $2 + 1 = 3$. To reach 4 we need 1 more whole, which is $\frac{6}{6}$. So $\frac{n}{6} + \frac{4}{6} = \frac{6}{6}$, and $n = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 1 4/6 = 3 4/6; 4 - 3 4/6 = 2/6; n = 2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0151cad5-a5f6-4996-ad90-528cfb62f0a9', 'NC26.4.ANR.6', 3, 'choice', 'Explain fraction operations', 'Which statement about the sum $\frac{3}{5} + \frac{4}{5}$ is true?', '["The sum is $\\frac{7}{10}$.","The sum is less than 1.","The sum is greater than 1.","The sum is $\\frac{12}{5}$."]', 'The sum is greater than 1.', NULL, '$\frac{3}{5} + \frac{4}{5} = \frac{7}{5}$, because the numerators add and the denominator stays 5. Since 7 fifths is more than 5 fifths, the sum is greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"The sum is greater than 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 + 4/5 = 7/5 > 1.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e8362aa-5d3f-4afd-8931-3e1cd39210a3', 'NC26.4.ANR.7', 1, 'numeric', 'Continue a pattern from its rule', 'A pattern starts at 4 and adds 6 each time: 4, 10, 16, 22, ... What is the next number in the pattern?', '[]', '28', '22+6', 'Add 6 to the last number: 22 + 6 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 + 6 = 28.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
