INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c088394f-f995-4181-a093-dda21b2870ec', 'NC26.4.ANR.7', 2, 'numeric', 'Repeating pattern: find the item at a position', 'A bracelet repeats this pattern of beads: red, red, blue, green, red, red, blue, green, and so on. How many red beads are in the first 12 beads?', '[]', '6', '12/4*2', 'Each group of 4 beads has 2 red beads. 12 beads make 3 groups, so there are 3 x 2 = 6 red beads.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group of 4 has 2 reds. 12 beads = 3 groups, 3x2 = 6.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
