INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a3fd7fe-18a0-4223-844b-c22dcee9b0b1', 'NC26.4.ANR.7', 2, 'choice', 'Tell growing patterns from repeating patterns', 'Maya makes four patterns with beads. Which of her patterns is a growing pattern?', '["red, blue, red, blue","round, square, round, square","1 bead, 3 beads, 5 beads, 7 beads","big, small, big, small"]', '1 bead, 3 beads, 5 beads, 7 beads', NULL, 'A growing pattern gets bigger by a rule. 1, 3, 5, 7 beads adds 2 more beads each time. The other patterns repeat the same two things.', 'checked', '{"lint":[],"solve":{"answer":"1 bead, 3 beads, 5 beads, 7 beads","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1, 3, 5, 7 beads grows by 2; the others repeat.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
