INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('992aa35e-94ab-48c2-a30f-9917db07d412', 'NC26.4.ANR.7', 2, 'choice', 'Tell growing patterns from repeating patterns', 'Which statement about the pattern 6, 9, 12, 15, 18 is true?', '["It is a repeating pattern that repeats 6, 9, 12.","It is a growing pattern that adds 6 each time.","It is a repeating pattern that repeats 15, 18.","It is a growing pattern that adds 3 each time."]', 'It is a growing pattern that adds 3 each time.', NULL, 'Each number is 3 more than the one before: 9 - 6 = 3, 12 - 9 = 3, and so on. No group of numbers comes around again, so it is a growing pattern that adds 3.', 'checked', '{"lint":[],"solve":{"answer":"It is a growing pattern that adds 3 each time.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences are 3; nothing repeats.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
