INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff64307c-559a-4387-b585-134a646157d0', 'NC26.4.ANR.7', 2, 'numeric', 'Tell growing patterns from repeating patterns', 'Pattern 1 is 5, 10, 15, 20. Pattern 2 is 3, 1, 3, 1. Pattern 3 is 2, 4, 8, 16. Pattern 4 is A, A, B, A, A, B. How many of these four patterns are repeating patterns?', '[]', '2', NULL, 'Pattern 2 repeats 3, 1 and Pattern 4 repeats A, A, B. Patterns 1 and 3 keep growing. So 2 patterns are repeating.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1: grows (add 5). 2: repeats 3, 1. 3: grows (double). 4: repeats A, A, B. Two repeat.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
