INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e238423e-72f9-4fca-b071-502952db9517', 'NC26.4.ANR.7', 2, 'choice', 'Features of a pattern', 'Which pattern has numbers that alternate between odd and even?', '["Start at 2 and add 5.","Start at 4 and add 6.","Start at 3 and add 4.","Start at 8 and add 10."]', 'Start at 2 and add 5.', NULL, 'Adding 5 (an odd number) flips odd and even each time: 2, 7, 12, 17. Adding 6, 4 or 10 (even numbers) keeps every number even or every number odd.', 'checked', '{"lint":[],"solve":{"answer":"Start at 2 and add 5.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 7, 12, 17: even, odd, even, odd. 3+4: all odd. 4+6: all even. 8+10: all even.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
