VALUES ('d7dbf77f-cce1-40cc-899d-f95724278769', 'NC26.4.ANR.7', 2, 'choice', 'Rule from inputs and outputs', 'The numbers that go into a machine are 2, 5 and 8. The numbers that come out are 7, 10 and 13. Which rule fits?', '["Add 3","Add 5","Add 7","Subtract 5"]', 'Add 5', NULL, '2 + 5 = 7, 5 + 5 = 10 and 8 + 5 = 13. The rule is "add 5".', 'checked', '{"lint":[],"solve":{"answer":"Add 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+5=7, 5+5=10, 8+5=13.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
