INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f4f565c-7df5-4d4c-9d07-a69620fc7fb4', 'NC26.4.ANR.7', 3, 'choice', 'Find the rule of a number pattern', 'Which rule describes the pattern 17, 29, 41, 53?', '["Add 11","Add 13","Add 12","Add 24"]', 'Add 12', NULL, '29 - 17 = 12, 41 - 29 = 12 and 53 - 41 = 12. The rule is "add 12".', 'checked', '{"lint":[],"solve":{"answer":"Add 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29-17=12, 41-29=12, 53-41=12.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
