INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7486cec8-7de2-4619-a54a-763b8acd2bc5', 'NC26.4.ANR.7', 3, 'numeric', 'Find the rule of a number pattern', 'Rani writes the pattern 1000, 850, 700, 550. Each number is the same amount less than the number before it. How much less?', '[]', '150', '1000-850', '1000 - 850 = 150, 850 - 700 = 150 and 700 - 550 = 150. Each number is 150 less.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1000-850=150, 850-700=150, 700-550=150.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
