INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e113130-c34a-42af-8a12-7f62f740da34', 'NC26.4.ANR.7', 3, 'choice', 'Growing shape pattern', 'In a growing pattern, Figure 2 has 11 tiles and Figure 4 has 19 tiles. The same number of tiles is added each time. How many tiles are in Figure 3?', '["13","15","17","14"]', '15', '(11+19)/2', 'From Figure 2 to Figure 4 is two steps that add 8 tiles in all, so each step adds 4. Figure 3 has 11 + 4 = 15 tiles.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From Figure 2 to 4 is two steps adding 8 in all, so 4 per step. Figure 3 = 11 + 4 = 15.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
