INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec5ca187-c238-4f29-949d-ac18a606b21d', 'NC26.4.ANR.7', 3, 'choice', 'Repeating pattern: find the item at a position', 'A repeating pattern goes square, triangle, circle, circle, star, and then starts over with square. What is the 47th shape?', '["Triangle","Square","Circle","Star"]', 'Triangle', NULL, 'The group has 5 shapes. 45 shapes make 9 full groups, so the 46th is a square and the 47th is a triangle.', 'checked', '{"lint":[],"solve":{"answer":"Triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group of 5: square, triangle, circle, circle, star. 47 = 9x5 + 2, so 2nd: triangle.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
