INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c4df0f8-b425-4d8e-a37a-245bdd8afc3c', 'NC26.4.ANR.7', 3, 'numeric', 'Repeating pattern: find the item at a position', 'A pattern repeats the numbers 2, 4, 6, 8, 2, 4, 6, 8, and so on. What is the sum of the first 10 numbers in the pattern?', '[]', '46', '2*(2+4+6+8)+2+4', 'Each group of 4 numbers adds to 2 + 4 + 6 + 8 = 20. The first 10 numbers are 2 full groups (40) and then 2 and 4 (6 more). 40 + 6 = 46.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group sum 2+4+6+8 = 20. First 10 = 2 groups (40) + 2 + 4 = 46.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
