INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f72b39b-df44-4c54-9d25-4d5bf7887ca7', 'NC26.4.ANR.7', 3, 'choice', 'Tell growing patterns from repeating patterns', 'Pattern X is 1, 2, 4, 7, 11. Pattern Y is 8, 3, 5, 8, 3, 5. Which pair of descriptions is correct?', '["X is repeating and Y is growing.","X is growing and Y is repeating.","Both are growing.","Both are repeating."]', 'X is growing and Y is repeating.', NULL, 'In X the numbers keep getting greater (the gaps are 1, 2, 3, 4), so it is growing. In Y the group 8, 3, 5 comes around again, so it is repeating.', 'checked', '{"lint":[],"solve":{"answer":"X is growing and Y is repeating.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: differences 1, 2, 3, 4, grows. Y: 8, 3, 5 repeats.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
