INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c16b57ad-28c7-4bfe-b536-360aacc3e0f9', 'NC26.4.ANR.7', 3, 'numeric', 'Tell growing patterns from repeating patterns', 'A repeating pattern has a group of 4 numbers that repeats. The group is written out over and over until 30 numbers have been written. How many numbers are in the last group, which is not complete?', '[]', '2', '30-4*7', '7 full groups use 4 x 7 = 28 numbers. 30 - 28 = 2 numbers are left, so the last group has 2 numbers.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 = 7x4 + 2. Seven full groups use 28 numbers; the last group has 2.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33cbff70-0874-49d5-84f3-df7472bba76c', 'NC26.4.ANR.7', 3, 'numeric', 'Features of a pattern', 'A pattern starts at 3 and follows the rule "add 6": 3, 9, 15, 21, ... What is the first number in the pattern that is greater than 100?', '[]', '105', '3+6*17', 'The numbers are 3 plus a multiple of 6. 3 + 6 x 16 = 99 is not greater than 100, but 3 + 6 x 17 = 105 is.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbers are 3 + 6k. 3 + 6x16 = 99, next is 105. First above 100 is 105.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
