INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5cf517-fab7-4efa-9b77-3526e0713b94', 'NC26.4.ANR.7', 3, 'numeric', 'Rule from inputs and outputs', 'A machine follows the rule "add 12". The number 50 comes out. What number went in?', '[]', '38', '50-12', 'Undo adding 12 by subtracting 12: 50 - 12 = 38. Check: 38 + 12 = 50.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Input + 12 = 50, input = 38.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
