INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('355b2d49-403e-45b5-954a-f8010fd8d6e2', 'NC26.4.SGMR.1', 3, 'choice', 'Degrees as parts of a circle', 'A full circle is 360 degrees. What fraction of a full circle is an angle of 45 degrees?', '["$\\frac{1}{8}$","$\\frac{1}{4}$","$\\frac{1}{6}$","$\\frac{1}{9}$"]', '$\frac{1}{8}$', NULL, '8 angles of 45 degrees make 8 x 45 = 360 degrees, a full circle. So 45 degrees is one eighth of a circle.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 x 8 = 360, so 45 is 1/8 of a circle.","run_id":"claude-code","at":"2026-10-17T19:20:19.100Z"}}', 'ai', NULL, NULL)
