INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f075f569-9792-4a47-a8fa-25faec977d94', 'NC26.4.SGMR.1', 3, 'numeric', 'Degrees as parts of a circle', 'One sprinkler sprays $\frac{1}{6}$ of a full circle and a second sprinkler sprays $\frac{1}{4}$ of a full circle. Their sprays do not overlap. A full circle is 360 degrees. How many degrees do the two sprays cover together?', '[]', '150', '360/6+360/4', 'One sixth of 360 is 60 degrees. One fourth of 360 is 90 degrees. Together 60 + 90 = 150 degrees.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6 of 360 = 60; 1/4 of 360 = 90. Together 150.","run_id":"claude-code","at":"2026-10-17T19:20:19.100Z"}}', 'ai', NULL, NULL)
