VALUES ('642174dd-fbe5-4e24-8d4f-dea1859eb92c', 'NC26.4.SGMR.1', 3, 'numeric', 'Benchmark angles: right, straight, full turn', 'How many right angles does it take to make 3 full turns?', '[]', '12', '3*4', 'One full turn is 4 right angles. 3 full turns are 3 x 4 = 12 right angles.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 right angles per turn, 3 turns: 12.","run_id":"claude-code","at":"2026-10-17T19:20:19.100Z"}}', 'ai', NULL, NULL)
