INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69c489e6-6357-4f32-a793-bd587b9c6660', 'NC26.4.SGMR.1', 3, 'choice', 'Benchmark angles: right, straight, full turn', 'Which statement is true?', '["Two right angles make a full turn.","A straight angle is the same as three right angles.","Four straight angles make a full turn.","Two straight angles make a full turn."]', 'Two straight angles make a full turn.', NULL, 'Two straight angles are 180 + 180 = 360 degrees, a full turn. Two right angles are only 180 degrees, three right angles are 270 degrees, and four straight angles are 720 degrees.', 'checked', '{"lint":[],"solve":{"answer":"Two straight angles make a full turn.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 180 = 360, a full turn. Two right angles = 180; straight = 2 right angles; four straight = 720.","run_id":"claude-code","at":"2026-10-17T19:20:19.100Z"}}', 'ai', NULL, NULL)
