INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e130533f-c1c8-406c-92d8-f7385dd5de68', 'NC26.4.SGMR.2', 1, 'numeric', 'Sort and count shapes by an attribute', 'Five shapes are a square, an equilateral triangle, a rectangle, a right triangle and a pentagon. How many of them are certain to have at least one right angle?', '[]', '3', NULL, 'A square has four right angles, a rectangle has four right angles and a right triangle has one. An equilateral triangle has three 60-degree angles, and a pentagon is not certain to have any right angle. So 3 shapes are certain to have one.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle and right triangle always have a right angle; an equilateral triangle never; a pentagon not necessarily. 3.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
