INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42eadc1a-db00-4d0e-9781-37a614213f7e', 'NC26.4.SGMR.2', 2, 'choice', 'Notation for a ray', 'Which symbol names the ray that starts at point P and passes through point Q?', '["$\\overrightarrow{QP}$","$\\overrightarrow{PQ}$","$\\overline{PQ}$","$\\overleftrightarrow{PQ}$"]', '$\overrightarrow{PQ}$', NULL, 'A ray has one endpoint and goes on forever in one direction. Its name starts with the endpoint and has an arrow pointing the way it goes: $\overrightarrow{PQ}$. $\overrightarrow{QP}$ starts at Q, $\overline{PQ}$ is a line segment and $\overleftrightarrow{PQ}$ is a line.', 'checked', '{"lint":[],"solve":{"answer":"$\\overrightarrow{PQ}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ray starting at P through Q: arrow over PQ pointing right, $\\overrightarrow{PQ}$.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ca9a181-6a62-4e0f-ad18-131242fcc131', 'NC26.4.SGMR.2', 2, 'choice', 'Notation for points, lines, rays and segments', 'Ray $\overrightarrow{XY}$ starts at point $X$ and passes through point $Y$. Which statement is true?', '["It has two endpoints, $X$ and $Y$.","It has one endpoint, $X$, and goes on forever past $Y$.","It has one endpoint, $Y$, and goes on forever past $X$.","It has no endpoints and goes on forever in both directions."]', 'It has one endpoint, $X$, and goes on forever past $Y$.', NULL, 'The first letter of a ray is its endpoint, so $X$ is the endpoint. The ray goes through $Y$ and keeps going.', 'checked', '{"lint":[],"solve":{"answer":"It has one endpoint, $X$, and goes on forever past $Y$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ray is named from its endpoint first: XY starts at X, passes Y and continues past Y.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('514cec09-35c9-437c-970a-466e97fefb45', 'NC26.4.SGMR.2', 2, 'choice', 'Notation for points, lines, rays and segments', 'Which symbol names the same line segment as $\overline{ST}$?', '["$\\overrightarrow{TS}$","$\\overleftrightarrow{ST}$","$\\overrightarrow{ST}$","$\\overline{TS}$"]', '$\overline{TS}$', NULL, 'A line segment has the same two endpoints whichever letter is written first, so $\overline{ST}$ and $\overline{TS}$ are the same segment. The other symbols are a ray, a line, and a different ray.', 'checked', '{"lint":[],"solve":{"answer":"$\\overline{TS}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A segment can be named with its endpoints in either order: $\\overline{ST}$ = $\\overline{TS}$. The others are rays or a line.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98b9f695-fcca-4cec-b437-8e670d45ad8a', 'NC26.4.SGMR.2', 2, 'numeric', 'Notation for points, lines, rays and segments', 'Points $A$, $B$ and $C$ are on one straight line in that order. How many different line segments can be named using two of these points as the endpoints?', '[]', '3', NULL, 'The segments are $\overline{AB}$, $\overline{BC}$ and $\overline{AC}$. That is 3 segments.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs of A, B, C: AB, BC, AC = 3 segments.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
