INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('873f2816-6bb5-47dd-91e0-551c6f5d5610', 'NC26.4.SGMR.2', 2, 'numeric', 'Classify a triangle by both its angles and its sides', 'Four triangles are described. A: angles of 30, 60 and 90 degrees, with three different side lengths. B: three angles of 60 degrees, with three equal sides. C: angles of 40, 40 and 100 degrees, with two equal sides. D: angles of 90, 45 and 45 degrees, with two equal sides. How many of the triangles have a right angle?', '[]', '2', NULL, 'A and D each have a 90 degree angle. B has only 60 degree angles and C has a 100 degree angle. So 2 triangles have a right angle.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A has 90, D has 90; B and C do not. Count = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
