INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('471eb28a-88e0-4a06-84fd-f16a0d2486ee', 'NC26.4.SGMR.2', 2, 'numeric', 'Parallel sides and right angles of a quadrilateral', 'Think about a square, a rectangle and a rhombus. How many of these three shapes always have four right angles?', '[]', '2', NULL, 'A square and a rectangle always have four right angles. A rhombus can lean over so that its angles are not right angles. So 2 shapes always have four right angles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square yes, rectangle yes, rhombus not always. Count = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
