INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4823f276-8823-406c-b64d-c7ae3a93d7a9', 'NC26.4.SGMR.2', 2, 'choice', 'Relationships among quadrilaterals', 'Which shape belongs to both the group of rectangles and the group of rhombuses?', '["a rectangle with two long sides and two short sides","a rhombus with no right angles","a parallelogram with unequal sides","a square"]', 'a square', NULL, 'A rectangle needs four right angles and a rhombus needs four equal sides. Only a square has both.', 'checked', '{"lint":[],"solve":{"answer":"a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has four right angles (rectangle) and four equal sides (rhombus).","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
