INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df0fa3a9-63fd-4dc0-a3ac-4a5c95464c0b', 'NC26.4.SGMR.2', 2, 'numeric', 'Relationships among quadrilaterals', 'Think about these four shapes: a square, a rectangle, a rhombus and a parallelogram. How many of them always have two pairs of parallel sides?', '[]', '4', NULL, 'Each of these four shapes has both pairs of opposite sides parallel. So all 4 do.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle, rhombus and parallelogram are all parallelograms: 4.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
