INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7755f7a8-726b-4558-9720-b4040bbedf1e', 'NC26.4.SGMR.2', 2, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'The perimeter of an equilateral triangle is 27 cm. How long is each side, in centimeters?', '[]', '9', '27/3', 'The three sides are equal, so each side is $27 \div 3 = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three equal sides: 27 / 3 = 9.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
