INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fb07628-d044-4f98-b4b4-1158a9979c5e', 'NC26.4.SGMR.2', 2, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'A picture frame is shaped like a parallelogram. Its long sides are 14 cm and its short sides are 6 cm. How many centimeters of wood go all the way around the frame?', '[]', '40', '2*(14+6)', 'Opposite sides of a parallelogram are equal, so the frame has two sides of 14 cm and two sides of 6 cm. The total is $14 + 14 + 6 + 6 = 40$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x14+2x6=28+12=40.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
