INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d1a92d0-aa30-405f-abd1-0a5227c7be47', 'NC26.4.SGMR.2', 3, 'choice', 'Notation for points, lines, rays and segments', 'A ray starts at point $T$ and passes through point $W$. A different ray starts at $W$ and passes through $T$. Which pair of symbols names them, in that order?', '["$\\overrightarrow{WT}$ and $\\overrightarrow{TW}$","$\\overline{TW}$ and $\\overline{WT}$","$\\overrightarrow{TW}$ and $\\overrightarrow{WT}$","$\\overleftrightarrow{TW}$ and $\\overleftrightarrow{WT}$"]', '$\overrightarrow{TW}$ and $\overrightarrow{WT}$', NULL, 'The endpoint of a ray is written first. The first ray starts at $T$, so it is $\overrightarrow{TW}$. The second starts at $W$, so it is $\overrightarrow{WT}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\overrightarrow{TW}$ and $\\overrightarrow{WT}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First ray starts at T through W: TW with arrow. Second starts at W through T: WT with arrow. Order: TW then WT.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
