INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8813fd2-5915-4d4f-90dd-80d66a3f3676', 'NC26.4.SGMR.2', 3, 'choice', 'Notation for points, lines, rays and segments', 'Which pair of symbols names the SAME figure?', '["$\\overrightarrow{AB}$ and $\\overrightarrow{BA}$","$\\overline{AB}$ and $\\overrightarrow{AB}$","$\\overrightarrow{AB}$ and $\\overleftrightarrow{AB}$","$\\overleftrightarrow{AB}$ and $\\overleftrightarrow{BA}$"]', '$\overleftrightarrow{AB}$ and $\overleftrightarrow{BA}$', NULL, 'The line through $A$ and $B$ is the same line whichever letter comes first. The two rays start at different points and go in opposite directions, and the other pairs mix different kinds of figure.', 'checked', '{"lint":[],"solve":{"answer":"$\\overleftrightarrow{AB}$ and $\\overleftrightarrow{BA}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line AB and line BA are the same line. Rays AB and BA differ; ray vs line differ; segment vs ray differ.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce16122d-d930-42df-890a-0d0457542eee', 'NC26.4.SGMR.2', 3, 'numeric', 'Notation for points, lines, rays and segments', 'Points $P$, $Q$, $R$ and $S$ are on one straight line in that order. How many different line segments can be named using two of these points as the endpoints?', '[]', '6', '3+2+1', 'List them in order: $\overline{PQ}$, $\overline{PR}$, $\overline{PS}$, then $\overline{QR}$, $\overline{QS}$, then $\overline{RS}$. That is $3 + 2 + 1 = 6$ segments.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs of 4 points: PQ, PR, PS, QR, QS, RS = 6.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('483655d3-2011-4f18-a705-b561c5a4df15', 'NC26.4.SGMR.2', 3, 'numeric', 'Notation for points, lines, rays and segments', 'Two points are marked on a flat page. How many different rays can be named that start at one of the points and pass through the other?', '[]', '2', NULL, 'Call the points $A$ and $B$. One ray starts at $A$ and passes through $B$, written $\overrightarrow{AB}$. The other starts at $B$ and passes through $A$, written $\overrightarrow{BA}$. That is 2 rays.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points A and B: ray starting at A through B, and ray starting at B through A = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cce57d3-8f2e-495f-b16b-62a2e3c809f5', 'NC26.4.SGMR.2', 3, 'choice', 'Notation for points, lines, rays and segments', 'Dev says that $\overrightarrow{PQ}$ and $\overrightarrow{QP}$ are the same ray. What is wrong with what he says?', '["They have the same endpoint.","They start at different points and go in opposite directions.","They are both line segments.","They are both lines."]', 'They start at different points and go in opposite directions.', NULL, 'The first letter of a ray is its endpoint. $\overrightarrow{PQ}$ starts at $P$ and $\overrightarrow{QP}$ starts at $Q$, so they go in opposite directions.', 'checked', '{"lint":[],"solve":{"answer":"They start at different points and go in opposite directions.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ray PQ starts at P toward Q; ray QP starts at Q toward P. Different endpoints, opposite directions.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16039c36-b2ef-438f-b2e2-f2955b88f585', 'NC26.4.SGMR.2', 3, 'choice', 'Classify a triangle by its angles', 'Which statement about triangles is true?', '["A triangle can have two obtuse angles.","A triangle can have at most one right angle.","Every triangle has a right angle.","An acute triangle has one angle greater than 90 degrees."]', 'A triangle can have at most one right angle.', NULL, 'Two right angles, or two obtuse angles, would use up too much turn for the third side to close the shape. A triangle has at most one right angle or obtuse angle, and an acute triangle has none.', 'checked', '{"lint":[],"solve":{"answer":"A triangle can have at most one right angle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two right angles would leave 0 for the third, so at most one right angle. Two obtuse impossible; not every triangle is right; acute has no angle over 90.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcfbacc4-f6f5-4b13-84ef-764b1c9949df', 'NC26.4.SGMR.2', 3, 'choice', 'Classify a triangle by its angles', 'Which triangle is obtuse?', '["angles of 45, 45 and 90 degrees","angles of 70, 60 and 50 degrees","angles of 80, 50 and 50 degrees","angles of 35, 35 and 110 degrees"]', 'angles of 35, 35 and 110 degrees', NULL, 'A triangle is obtuse when one angle is greater than 90 degrees. Only 35, 35, 110 has such an angle (110 degrees). The 45, 45, 90 triangle is a right triangle, and the other two are acute.', 'checked', '{"lint":[],"solve":{"answer":"angles of 35, 35 and 110 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"110 > 90, so 35, 35, 110 is obtuse. 80/50/50 and 70/60/50 acute; 45/45/90 right.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('312deafd-9782-458d-98d0-53c9329639d5', 'NC26.4.SGMR.2', 3, 'numeric', 'Classify a triangle by its angles', 'Six triangles have these angle measures. A: 55, 65, 60. B: 90, 30, 60. C: 100, 40, 40. D: 75, 75, 30. E: 50, 90, 40. F: 20, 20, 140. How many of the triangles are NOT acute?', '[]', '4', NULL, 'Acute triangles have all angles under 90 degrees: A and D. The others are not acute: B and E have a right angle, and C and F have an obtuse angle. That makes 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A acute, B right, C obtuse, D 75/75/30 acute, E right, F obtuse. Not acute: B, C, E, F = 4.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d999dc58-81d2-4db5-9794-27cc6054c306', 'NC26.4.SGMR.2', 3, 'numeric', 'Classify a triangle by its sides', 'Here are the side lengths, in centimeters, of eight triangles. A: 6, 6, 9. B: 5, 7, 9. C: 8, 8, 8. D: 10, 10, 4. E: 3, 5, 7. F: 12, 12, 12. G: 9, 9, 15. H: 4, 4, 4. How many of the triangles have at least two sides of equal length?', '[]', '6', NULL, 'Check each triangle for equal sides. A, C, D, F, G and H each have at least two equal sides. B and E have three different lengths. That makes 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 6,6,9 yes; B no; C 8,8,8 yes; D 10,10,4 yes; E no; F yes; G 9,9,15 yes; H yes. Count = 6.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41ccaffa-d995-491e-b6fe-d24bbb8c106b', 'NC26.4.SGMR.2', 3, 'choice', 'Classify a triangle by both its angles and its sides', 'Which triangle is both obtuse and isosceles?', '["angles of 90, 45 and 45 degrees, with two equal sides","angles of 60, 60 and 60 degrees, with three equal sides","angles of 100, 50 and 30 degrees, with no equal sides","angles of 100, 40 and 40 degrees, with two equal sides"]', 'angles of 100, 40 and 40 degrees, with two equal sides', NULL, 'Obtuse means one angle is over 90 degrees, and isosceles means exactly two sides are equal. Only the triangle with angles of 100, 40 and 40 degrees has both. The others are right isosceles (90, 45, 45), equilateral (60, 60, 60) and obtuse scalene (100, 50, 30).', 'checked', '{"lint":[],"solve":{"answer":"angles of 100, 40 and 40 degrees, with two equal sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Obtuse needs an angle > 90; isosceles needs two equal sides: 100, 40, 40 with two equal sides.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e45b2e80-5b74-4254-aae4-bd2eade484f2', 'NC26.4.SGMR.2', 3, 'numeric', 'Classify a triangle by both its angles and its sides', 'Five triangles are described. A: angles 100, 40, 40 with two equal sides. B: angles 70, 70, 40 with two equal sides. C: angles 90, 50, 40 with no equal sides. D: angles 60, 60, 60 with three equal sides. E: angles 120, 30, 30 with two equal sides. How many of the triangles have an obtuse angle AND two equal sides?', '[]', '2', NULL, 'A has a 100 degree angle and two equal sides. E has a 120 degree angle and two equal sides. B has no obtuse angle, C has no equal sides and is a right triangle, and D has no obtuse angle. So 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A obtuse + two equal: yes. B no obtuse. C right. D no. E 120 + two equal: yes. Count = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa92d568-3a9d-411d-8986-b9daf0dc0486', 'NC26.4.SGMR.2', 3, 'choice', 'Classify a triangle by both its angles and its sides', 'Rosa describes her triangle: one of its angles is bigger than 90 degrees, and its three sides all have different lengths. Which name fits?', '["acute scalene triangle","obtuse scalene triangle","obtuse isosceles triangle","right scalene triangle"]', 'obtuse scalene triangle', NULL, 'An angle bigger than 90 degrees makes it obtuse. Three different side lengths make it scalene.', 'checked', '{"lint":[],"solve":{"answer":"obtuse scalene triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle over 90: obtuse. All sides different: scalene.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
