INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b65dfe-45d4-48b1-a026-f14f50bf38ed', 'NC26.4.SGMR.2', 3, 'choice', 'Name a quadrilateral from its sides and angles', 'Ana draws a four-sided shape with four equal sides. Which fact would tell you that it must be a square?', '["Its opposite sides are parallel.","Its opposite angles are equal.","All four of its angles are right angles.","Its perimeter is 20 cm."]', 'All four of its angles are right angles.', NULL, 'Every shape with four equal sides (a rhombus) has parallel opposite sides and equal opposite angles. Only four right angles makes it a square. The perimeter does not decide the shape.', 'checked', '{"lint":[],"solve":{"answer":"All four of its angles are right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four equal sides is a rhombus; adding four right angles makes it a square. Parallel sides and equal opposite angles hold for any rhombus; perimeter says nothing.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1cb1e88-1a28-405f-95c7-78a08551e9b9', 'NC26.4.SGMR.2', 3, 'choice', 'Name a quadrilateral from its sides and angles', 'A parallelogram is drawn. Which fact would tell you that it must be a rectangle?', '["It has four right angles.","Its opposite sides are equal.","It has two pairs of parallel sides.","Its opposite angles are equal."]', 'It has four right angles.', NULL, 'Every parallelogram has equal opposite sides, two pairs of parallel sides, and equal opposite angles. Only having four right angles makes it a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"It has four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every parallelogram has equal opposite angles, two pairs of parallel sides and equal opposite sides. Four right angles makes it a rectangle.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be4da827-7cc1-4b22-8534-59794a274db0', 'NC26.4.SGMR.2', 3, 'choice', 'Parallel sides and right angles of a quadrilateral', 'Which statement is true about parallelograms and rectangles?', '["Only a parallelogram has four right angles.","Both have two pairs of parallel sides.","Only a rectangle has two pairs of parallel sides.","A rectangle has no right angles."]', 'Both have two pairs of parallel sides.', NULL, 'Both pairs of opposite sides are parallel in a parallelogram and in a rectangle. A rectangle has four right angles; a parallelogram might not have any.', 'checked', '{"lint":[],"solve":{"answer":"Both have two pairs of parallel sides.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangles and parallelograms have two pairs of parallel sides. A rectangle has right angles; a parallelogram need not.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11407056-6006-423f-9739-b56a893a2ae4', 'NC26.4.SGMR.2', 3, 'choice', 'Parallel sides and right angles of a quadrilateral', 'A quadrilateral has exactly one pair of parallel sides and two right angles. Which shape could it be?', '["rectangle","rhombus","parallelogram","trapezoid"]', 'trapezoid', NULL, 'Exactly one pair of parallel sides rules out a rectangle, a rhombus and a parallelogram, which all have two pairs. A trapezoid can have exactly one pair, and it can have two right angles.', 'checked', '{"lint":[],"solve":{"answer":"trapezoid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram, rhombus and rectangle have two parallel pairs. A right trapezoid has one pair and two right angles.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ab011dd-de65-406f-9d3a-cad3bad4cc4b', 'NC26.4.SGMR.2', 3, 'choice', 'Relationships among quadrilaterals', 'Lena is sorting quadrilaterals into groups. Which of these statements about the groups is true?', '["Every rhombus is also a square.","Every parallelogram is also a rectangle.","Every square is also a rhombus.","Every rectangle is also a rhombus."]', 'Every square is also a rhombus.', NULL, 'A square has four equal sides, so it is a rhombus. The other statements are false: a rhombus can lean over, a parallelogram may have no right angles, and a rectangle may have unequal sides.', 'checked', '{"lint":[],"solve":{"answer":"Every square is also a rhombus.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has four equal sides, so it is a rhombus. The others are false in general.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58165166-e79a-4521-8311-0bc349f0fc7e', 'NC26.4.SGMR.2', 3, 'choice', 'Relationships among quadrilaterals', 'Which statement is false?', '["Every rectangle is a parallelogram.","Every square is a parallelogram.","Every parallelogram is a rectangle.","Every rhombus is a parallelogram."]', 'Every parallelogram is a rectangle.', NULL, 'Rectangles, squares and rhombuses all have two pairs of parallel sides, so each is a parallelogram. But a parallelogram can have angles that are not right angles, so it is not always a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"Every parallelogram is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares, rectangles and rhombuses are all parallelograms; but a parallelogram need not have right angles. False: every parallelogram is a rectangle.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2846a251-263c-4350-8a28-01177d0aeb81', 'NC26.4.SGMR.2', 3, 'numeric', 'Relationships among quadrilaterals', 'Four statements are given. 1: Every square is a rectangle. 2: Every rectangle is a square. 3: Every rhombus is a parallelogram. 4: Every parallelogram is a rhombus. How many of the statements are true?', '[]', '2', NULL, 'Statements 1 and 3 are true. A rectangle can have unequal sides, so statement 2 is false. A parallelogram can have unequal sides, so statement 4 is false. So 2 statements are true.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 true, 2 false, 3 true, 4 false. Count = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('641251f4-a2fa-46ca-ad7d-f1268a0de3ac', 'NC26.4.SGMR.2', 3, 'choice', 'Relationships among quadrilaterals', 'Ella says, "A rectangle is never a parallelogram." Which reply is correct?', '["A rectangle is always a parallelogram, since both pairs of opposite sides are parallel.","She is right, because a rectangle has right angles.","She is right, because a parallelogram has equal sides.","A rectangle is a parallelogram only when it is a square."]', 'A rectangle is always a parallelogram, since both pairs of opposite sides are parallel.', NULL, 'A rectangle has two pairs of parallel sides, which is exactly what a parallelogram is. Having right angles does not stop a shape from being a parallelogram.', 'checked', '{"lint":[],"solve":{"answer":"A rectangle is always a parallelogram, since both pairs of opposite sides are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle has both pairs of opposite sides parallel, so it is always a parallelogram.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3688795-09f4-4cb6-9cde-14ace1b32b48', 'NC26.4.SGMR.2', 3, 'numeric', 'Sort and count shapes by an attribute', 'A box holds 4 triangles, 3 rectangles, 2 squares and 1 pentagon. How many sides do all the shapes in the box have in all?', '[]', '37', '4*3+3*4+2*4+5', 'Triangles: $4 \times 3 = 12$ sides. Rectangles: $3 \times 4 = 12$. Squares: $2 \times 4 = 8$. The pentagon has 5. Total: $12 + 12 + 8 + 5 = 37$.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x3 + 3x4 + 2x4 + 1x5 = 12 + 12 + 8 + 5 = 37.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360b8432-a9fd-498f-8d2f-8a7b638b8199', 'NC26.4.SGMR.2', 3, 'numeric', 'Sort and count shapes by an attribute', 'A teacher sorts 12 shapes. 4 of them are triangles and the rest are quadrilaterals. How many more sides do the quadrilaterals have, all together, than the triangles?', '[]', '20', '8*4-4*3', 'There are $12 - 4 = 8$ quadrilaterals with $8 \times 4 = 32$ sides in all. The 4 triangles have $4 \times 3 = 12$ sides. The difference is $32 - 12 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrilaterals: 12-4 = 8, 8x4 = 32 sides. Triangles: 4x3 = 12 sides. 32 - 12 = 20.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('718010d8-8ee2-4b52-94f2-03d2a0f9da1d', 'NC26.4.SGMR.2', 3, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'The perimeter of a rhombus is 52 cm. How long is each side, in centimeters?', '[]', '13', '52/4', 'All four sides of a rhombus are equal. Each side is $52 \div 4 = 13$ cm.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus has four equal sides: 52 / 4 = 13.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
