INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d063c49b-7eff-4e67-bb6c-bf54f3d2f5d6', 'NC26.4.SGMR.2', 3, 'choice', 'Side lengths and perimeter of triangles and quadrilaterals', 'A rectangle has a perimeter of 30 cm, and one of its sides is 9 cm long. What are the lengths of its other three sides?', '["21 cm, 9 cm and 21 cm","9 cm, 12 cm and 12 cm","9 cm, 6 cm and 6 cm","6 cm, 6 cm and 6 cm"]', '9 cm, 6 cm and 6 cm', NULL, 'The two 9 cm sides use $9 + 9 = 18$ cm. That leaves $30 - 18 = 12$ cm for the other two sides, which are equal, so each is 6 cm. The three other sides are 9, 6 and 6 cm.', 'checked', '{"lint":[],"solve":{"answer":"9 cm, 6 cm and 6 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides equal: another side is 9; 30 - 18 = 12, so the other two are 6 and 6. Sides: 9, 6, 6.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15154540-fd57-45de-91c5-5787ad3c48ee', 'NC26.4.SGMR.2', 3, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'A square and an equilateral triangle have sides of the same length. The perimeter of the triangle is 18 cm. What is the perimeter of the square, in centimeters?', '[]', '24', '18/3*4', 'Each side of the triangle is $18 \div 3 = 6$ cm. The square has sides of 6 cm too, so its perimeter is $4 \times 6 = 24$ cm.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle side = 18 / 3 = 6. Square perimeter = 4 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6696e986-1ccc-475b-9d00-19a2eeb4c71d', 'NC26.4.SGMR.2', 3, 'numeric', 'Parallel sides and right angles of a quadrilateral', 'Here are six shapes: a square, a rectangle, a rhombus, a kite, a parallelogram and a triangle. Some of them have two pairs of parallel sides. Of those shapes, how many do NOT always have four right angles?', '[]', '2', NULL, 'The shapes with two pairs of parallel sides are the square, the rectangle, the rhombus and the parallelogram. The kite and the triangle have none. A square and a rectangle always have four right angles. A rhombus and a parallelogram do not always have right angles. So 2 of them do not always have four right angles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pairs of parallel sides: square, rectangle, rhombus, parallelogram (kite and triangle do not). Of these, rhombus and parallelogram need not have four right angles: 2.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78715e9b-4164-4a91-8166-2473696c3884', 'NC26.4.SGMR.2', 3, 'numeric', 'Sort and count shapes by an attribute', 'A bag holds only triangles and quadrilaterals. There are 9 shapes in the bag, and together they have 31 sides. How many of the shapes are quadrilaterals?', '[]', '4', '31-3*9', 'A triangle has 3 sides and a quadrilateral has 4 sides. If all 9 shapes were triangles, there would be $9 \times 3 = 27$ sides. There are $31 - 27 = 4$ more sides, and each quadrilateral adds 1 extra side. So there are 4 quadrilaterals. Check: $5 \times 3 + 4 \times 4 = 15 + 16 = 31$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If all 9 were triangles: 27 sides. Each quadrilateral adds 1: 31-27=4 quadrilaterals (5 triangles: 15+16=31).","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aed160e-71cf-493b-9d39-e24a45b8fe26', 'NC26.4.SGMR.2', 3, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'An equilateral triangle has sides of 16 cm. A rhombus has the same perimeter as the triangle. How long is each side of the rhombus, in centimeters?', '[]', '12', '16*3/4', 'An equilateral triangle has three equal sides, so its perimeter is $3 \times 16 = 48$ centimeters. A rhombus has four equal sides, so each side is $48 \div 4 = 12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle perimeter 3x16=48; rhombus side 48/4=12.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
