VALUES ('bfbdac1d-d066-49e4-b596-40ed0b4991ec', 'NC26.4.SGMR.4', 1, 'choice', 'Find a missing side from the area', 'A rectangle has an area of 45 square units and a length of 9 units. Which equation can be used to find the width, $w$?', '["$9 \\times w = 45$","$9 + w = 45$","$w \\div 9 = 45$","$w - 9 = 45$"]', '$9 \times w = 45$', NULL, 'Length $\times$ width = area, so $9 \times w = 45$ and $w = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times w = 45$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = length x width, so 9 x w = 45 (w = 5). Other options use the wrong operation.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
