INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82a327d0-a905-4f71-901a-71a8276c0ff8', 'NC26.4.SGMR.4', 3, 'choice', 'Area of a rectangle in context', 'A rectangular parking lot is 67 meters long and 48 meters wide. What is its area in square meters?', '["230","115","3216","2680"]', '3216', '67*48', '$67 \times 48 = 67 \times 40 + 67 \times 8 = 2680 + 536 = 3216$ square meters. 2680 stops after the tens, 115 is the sum of the sides, and 230 is the perimeter.', 'checked', '{"lint":[],"solve":{"answer":"3216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"67 x 48 = 67 x 50 - 67 x 2 = 3350 - 134 = 3216 square meters. 2680 = 67 x 40 (partial product), 230 perimeter, 115 sum.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
