INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f012de5-5c10-442d-b513-9ad762b7c836', 'NC26.4.SGMR.4', 3, 'numeric', 'Perimeter of a rectangle in context', 'A rectangular field is 150 yards long and 75 yards wide. A fence post is placed every 5 yards all the way around the edge of the field, including one at each corner. How many posts are needed?', '[]', '90', '2*(150+75)/5', 'The distance around is $2 \times (150 + 75) = 450$ yards. A post every 5 yards gives $450 \div 5 = 90$ posts.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2 x (150 + 75) = 450 yards. Around a closed loop, posts every 5 yards: 450 / 5 = 90 posts. 150 and 75 are multiples of 5, so a post lands on each corner (consistent with the stem).","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
