INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('610c42d8-17f0-4e41-9ed0-f9c31110542b', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the perimeter', 'Fencing costs 4 dollars per foot. Leo spent 288 dollars to fence all the way around a rectangular pen that is 25 feet long. How many feet wide is the pen?', '[]', '11', '(288/4-2*25)/2', 'The fence is $288 \div 4 = 72$ feet long. The two lengths use 50 feet, leaving 22 feet for the two widths. One width is 11 feet.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 288 / 4 = 72 feet. Length + width = 36. Width = 36 - 25 = 11 feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7d83b17-5f79-40be-96cd-1aa57219195d', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the perimeter', 'A rectangle has a perimeter of 90 meters and a width of 18 meters. What is its area in square meters?', '[]', '486', '(90-2*18)/2*18', 'The two widths use 36 meters, leaving 54 meters for the two lengths, so the length is 27 meters. Area = $27 \times 18 = 486$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"486","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 45, so length = 45 - 18 = 27 m. Area = 27 x 18 = 270 + 216 = 486 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7809296-7cf0-4669-aba9-10117bc24ed9', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: add rectangles', 'A playground is made from three rectangles that do not overlap. They measure 20 m by 10 m, 15 m by 8 m, and 6 m by 5 m. What is the total area of the playground in square meters?', '[]', '350', '20*10+15*8+6*5', '$20 \times 10 = 200$, $15 \times 8 = 120$ and $6 \times 5 = 30$. Total: $200 + 120 + 30 = 350$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 x 10 + 15 x 8 + 6 x 5 = 200 + 120 + 30 = 350 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
