INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2bbbb16-3579-4b62-8f10-a391e3d008f5', 'NC26.4.SGMR.4', 3, 'choice', 'Area of a rectilinear figure: subtract a cut-out', 'A square rug with sides of 9 feet covers part of a rectangular floor that is 14 feet long and 12 feet wide. How many square feet of the floor are NOT covered by the rug?', '["87","81","249","168"]', '87', '14*12-9*9', 'Floor: $14 \times 12 = 168$. Rug: $9 \times 9 = 81$. Not covered: $168 - 81 = 87$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"87","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Floor 14 x 12 = 168; rug 9 x 9 = 81. Uncovered = 168 - 81 = 87 square feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
