INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7ddcdce-c9e0-4b53-a26d-aee9c2640f6d', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed area, changing perimeter', 'A rectangle has an area of 60 square inches and sides that are whole numbers of inches. What is the smallest perimeter it could have, in inches?', '[]', '32', '2*(6+10)', 'Pairs: 1 by 60, 2 by 30, 3 by 20, 4 by 15, 5 by 12, 6 by 10. The pair closest in size, 6 by 10, has the smallest perimeter: $2 \times (6 + 10) = 32$ inches.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs: 1x60 (122), 2x30 (64), 3x20 (46), 4x15 (38), 5x12 (34), 6x10 (32). Smallest = 32 inches.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
