INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d676839-8ac9-4242-8477-bd913ffe2431', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed area, changing perimeter', 'Two rectangular pens each have an area of 48 square meters. Pen A is 8 meters wide. Pen B is 3 meters wide. How many more meters of fence does pen B need than pen A?', '[]', '10', '2*(3+48/3)-2*(8+48/8)', 'Pen A is $48 \div 8 = 6$ m long, so its fence is $2 \times (8 + 6) = 28$ m. Pen B is $48 \div 3 = 16$ m long, so its fence is $2 \times (3 + 16) = 38$ m. Pen B needs $38 - 28 = 10$ more meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pen A: 8 x 6, perimeter 28. Pen B: 3 x 16, perimeter 38. B needs 38 - 28 = 10 more meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
