INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e0e95c7-f146-4d1a-bec8-76fb70fd70b0', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed perimeter, changing area', 'A farmer has 60 meters of fence and uses all of it for each pen. Pen 1 is rectangular and 20 meters long. Pen 2 is rectangular and 15 meters long. How many square meters greater is the area of the larger pen than the area of the smaller pen?', '[]', '25', '15*(30-15)-20*(30-20)', 'Length plus width is $60 \div 2 = 30$. Pen 1 is 10 wide: $20 \times 10 = 200$. Pen 2 is 15 wide: $15 \times 15 = 225$. The difference is $225 - 200 = 25$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 30. Pen 1: 20 x 10 = 200. Pen 2: 15 x 15 = 225. Difference = 25 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
