INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('663d5e09-2820-4f22-9cb1-b9e3ebc7d431', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed perimeter, changing area', 'A square and a rectangle have the same perimeter. The rectangle is 14 units long and 6 units wide. How many more square units of area does the square have than the rectangle?', '[]', '16', '10*10-14*6', 'The rectangle''s perimeter is $2 \times (14 + 6) = 40$, so the square''s sides are $40 \div 4 = 10$. Square: $10 \times 10 = 100$. Rectangle: $14 \times 6 = 84$. Difference: 16 square units.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle perimeter = 2 x (14 + 6) = 40, area 84. Square side = 40 / 4 = 10, area 100. Difference = 16 square units.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0378e4ed-44bb-4e24-8bc0-6ff529368f8e', 'NC26.4.SGMR.4', 3, 'choice', 'Fixed perimeter, changing area', 'A rectangle is 12 units long and 4 units wide. Its length is made 2 units shorter and its width is made 2 units longer. Which statement is true?', '["The perimeter stays the same; the area decreases by 12 square units","The perimeter stays the same; the area increases by 12 square units","The perimeter stays the same; the area stays the same","The perimeter decreases; the area increases by 12 square units"]', 'The perimeter stays the same; the area increases by 12 square units', NULL, 'Old: 12 by 4, perimeter 32, area 48. New: 10 by 6, perimeter 32, area 60. The perimeter is the same and the area goes up by $60 - 48 = 12$ square units.', 'checked', '{"lint":[],"solve":{"answer":"The perimeter stays the same; the area increases by 12 square units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original 12 x 4: perimeter 32, area 48. New 10 x 6: perimeter 32, area 60. Perimeter same, area up 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1854bc8f-7faf-406c-b7eb-91566f8c35f2', 'NC26.4.SGMR.4', 3, 'numeric', 'Choose area or perimeter for the situation', 'A rectangular garden is 15 meters long and 9 meters wide. Marta puts a fence around it and also spreads mulch over the whole garden. The fence costs 5 dollars per meter and the mulch costs 2 dollars per square meter. How many dollars do the fence and the mulch cost together?', '[]', '510', '2*(15+9)*5+15*9*2', 'Fence: the perimeter is $2 \times (15 + 9) = 48$ meters, which costs $48 \times 5 = 240$ dollars. Mulch: the area is $15 \times 9 = 135$ square meters, which costs $135 \times 2 = 270$ dollars. Together: $240 + 270 = 510$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"510","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2 x (15 + 9) = 48 m; fence = 48 x 5 = 240. Area = 15 x 9 = 135; mulch = 135 x 2 = 270. Total = 510 dollars.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23ebc935-4a82-4158-9f0e-e4ff5b811c6c', 'NC26.4.SGMR.4', 3, 'choice', 'Choose area or perimeter for the situation', 'Yard A is 30 feet by 10 feet. Yard B is 20 feet by 20 feet. Which statement is true?', '["They need the same amount of fence, but yard B has the greater area","Yard A needs more fence, and yard B has the greater area","They need the same amount of fence and have the same area","Yard B needs more fence and has the greater area"]', 'They need the same amount of fence, but yard B has the greater area', NULL, 'Both perimeters are 80 feet. Yard A has area $30 \times 10 = 300$ and yard B has area $20 \times 20 = 400$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"They need the same amount of fence, but yard B has the greater area","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: perimeter 2 x 40 = 80, area 300. B: perimeter 2 x 40 = 80, area 400. Same fence, B greater area.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
