INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a5001a3-386e-438d-8901-6258faeff68f', 'NC26.4.RD.1', 2, 'choice', 'Plan how to collect data', 'Four steps for working with data are listed. (1) Draw a conclusion. (2) Collect the data. (3) Ask a question. (4) Make a graph of the data. Which list shows the steps in the best order?', '["2, 3, 4, 1","3, 4, 2, 1","3, 2, 4, 1","1, 3, 2, 4"]', '3, 2, 4, 1', NULL, 'First ask a question (3), then collect the data (2), then make a graph (4), and last draw a conclusion (1).', 'checked', '{"lint":[],"solve":{"answer":"3, 2, 4, 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Data cycle: ask a question (3), collect data (2), make a graph (4), draw a conclusion (1): 3, 2, 4, 1.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
