INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70e294b5-99e3-460c-a115-832959507767', 'NC26.4.RD.1', 2, 'choice', 'Choose a graph or a scale', 'The bars of a bar graph will show 20, 35, 40 and 15 students. The scale will count by the same number on each line. Which scale lets every bar end exactly on a line?', '["Count by 5s","Count by 10s","Count by 4s","Count by 8s"]', 'Count by 5s', NULL, 'Every number must be a multiple of the scale. 20, 35, 40 and 15 are all multiples of 5. Counting by 10s misses 35 and 15, by 4s misses 35 and 15, and by 8s misses 20, 35 and 15.', 'checked', '{"lint":[],"solve":{"answer":"Count by 5s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20, 35, 40, 15 are all multiples of 5. By 10s fails for 35 and 15; by 8s fails for 20, 35, 15; by 4s fails for 35, 15. Count by 5s.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('690712de-9517-4865-af81-990fd6aeeb0f', 'NC26.4.RD.1', 2, 'choice', 'Frequency tables and tally marks', 'Students were asked how many hours they watched TV last night. 0 hours: 3 students. 1 hour: 8 students. 2 hours: 7 students. 3 hours: 2 students. How many students watched TV for 2 hours or more?', '["9","7","17","20"]', '9', '7+2', '2 hours or more means 2 hours and 3 hours: $7 + 2 = 9$ students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 hours or more: 2 hours 7 + 3 hours 2 = 9.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
