INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c5461e7-5d1a-44c1-a6a3-6c400e681eab', 'NC26.4.RD.1', 2, 'numeric', 'Frequency tables and tally marks', 'The numbers of letters in the first names of 10 students are 4, 5, 5, 3, 6, 5, 4, 5, 6 and 3. In a frequency table of this data, what is the frequency of 5?', '[]', '4', '4', 'Count the 5s in the list: there are four of them, so the frequency of 5 is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Data 4,5,5,3,6,5,4,5,6,3: the 5s are the 2nd, 3rd, 6th and 8th values, so frequency 4.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
