VALUES ('a36fab09-a4aa-4b23-b602-270a5d7329a5', 'NC26.4.RD.1', 2, 'numeric', 'Compare categories in a table', 'Students voted for a lunch. Pizza: 14. Tacos: 9. Pasta: 7. Salad: 4. How many students did NOT vote for pizza?', '[]', '20', '9+7+4', 'Add the other lunches: $9 + 7 + 4 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not pizza: 9 + 7 + 4 = 20.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
