INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44efbe39-6e0e-483c-9be8-a69aca7ff4f8', 'NC26.4.RD.1', 2, 'choice', 'Compare categories in a table', 'Students chose a favorite sport. Soccer: 14. Tennis: 9. Swimming: 14. Golf: 6. Which statement is true?', '["Tennis got the most votes","Soccer and swimming got the same number of votes","Golf got more votes than tennis","Swimming got more votes than soccer"]', 'Soccer and swimming got the same number of votes', NULL, 'Soccer and swimming both got 14 votes, so they tie. Tennis (9) did not get the most, golf (6) got fewer than tennis, and swimming did not get more than soccer.', 'checked', '{"lint":[],"solve":{"answer":"Soccer and swimming got the same number of votes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Soccer 14 and swimming 14 are equal. Tennis 9 is not most; golf 6 < tennis 9; swimming not more than soccer.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de22268d-57b9-4d30-a239-7dbb00e20343', 'NC26.4.RD.1', 2, 'numeric', 'Read or build a line plot', 'A line plot shows the number of days 18 students were absent this month. There are 7 Xs above 0, 6 Xs above 1 and 3 Xs above 2. The rest of the Xs are above 3. How many Xs are above 3?', '[]', '2', '18-(7+6+3)', 'The first three stacks have $7 + 6 + 3 = 16$ Xs. The rest are $18 - 16 = 2$ Xs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 6 + 3 = 16; 18 - 16 = 2 Xs above 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
