INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b226bbe-1b5a-4276-a91a-daec74219906', 'NC26.4.RD.1', 2, 'choice', 'Read or build a line plot', 'Mina made a line plot of how many cookies each of 9 friends ate: 2, 3, 3, 4, 4, 4, 5, 5, 6. Which statement describes her line plot?', '["There are 3 Xs above 3","There are 2 Xs above 6","There are 3 Xs above 4","There are 2 Xs above 2"]', 'There are 3 Xs above 4', NULL, 'The value 4 appears three times, so there are 3 Xs above 4. The value 3 appears twice, and 6 and 2 appear once each.', 'checked', '{"lint":[],"solve":{"answer":"There are 3 Xs above 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts: 2 once, 3 twice, 4 three times, 5 twice, 6 once. Only ''3 Xs above 4'' is true.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20f93a16-8244-43be-9fe9-0d963fcbc328', 'NC26.4.RD.1', 2, 'numeric', 'Read or build a line plot', 'A line plot shows the number of marbles in 10 bags. There are 2 Xs above 10, no Xs above 11, 5 Xs above 12 and 3 Xs above 13. How many of the bags have more than 11 marbles?', '[]', '8', '5+3', 'More than 11 means 12 or 13 marbles: $5 + 3 = 8$ bags.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More than 11: 12 and 13: 5 + 3 = 8 bags.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
