INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1ea249a-29d7-4a25-aa68-bac8e658de59', 'NC26.4.RD.1', 2, 'numeric', 'Line plot with fractional measurements', 'Eight pieces of ribbon are measured to the nearest half inch. Their lengths in inches are 1, $1\frac{1}{2}$, $1\frac{1}{2}$, 2, 2, 2, $2\frac{1}{2}$ and 3. What is the range of the lengths, in inches?', '[]', '2', '3-1', 'The longest is 3 inches and the shortest is 1 inch. Range = $3 - 1 = 2$ inches.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 3, least 1; range 3 - 1 = 2 inches.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
