INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18dbb445-86b3-4fde-8635-a1b6abfdff94', 'NC26.4.RD.1', 2, 'choice', 'Line plot with fractional measurements', 'A line plot shows the lengths of bean sprouts. There are 3 Xs above $\frac{1}{2}$ inch, 5 Xs above 1 inch and 4 Xs above $1\frac{1}{2}$ inches. How many sprouts are 1 inch long or longer?', '["9","12","5","4"]', '9', '5+4', 'Sprouts of 1 inch or more are the ones at 1 inch and at $1\frac{1}{2}$ inches: $5 + 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 inch or longer: 1 inch (5) + 1 1/2 inches (4) = 9.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
