INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b6b4742-bd8e-4e35-a0c3-8ac4a6282e2f', 'NC26.4.RD.1', 2, 'choice', 'Double bar graph: compare two data sets', 'A double bar graph shows the rainfall in inches in two towns. January: Town A 4, Town B 6. February: Town A 5, Town B 5. March: Town A 8, Town B 6. April: Town A 7, Town B 9. In which month did Town A get more rain than Town B?', '["March","January","February","April"]', 'March', NULL, 'In March, Town A (8) is greater than Town B (6). In January and April Town B is greater, and in February they are equal.', 'checked', '{"lint":[],"solve":{"answer":"March","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jan 4<6, Feb 5=5, Mar 8>6, Apr 7<9. Only March.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
