INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33e3ec63-a6c2-4b3f-a478-fc1f59593e8b', 'NC26.4.RD.1', 2, 'choice', 'Draw a conclusion from data', 'Class A''s test scores have a range of 8. Class B''s test scores have a range of 25. Which conclusion is correct?', '["Class A''s scores are more spread out than Class B''s","Class B''s scores are more spread out than Class A''s","Class B had the higher median score","Class A and Class B have the same spread"]', 'Class B''s scores are more spread out than Class A''s', NULL, 'The range shows how spread out the data are. A range of 25 is greater than 8, so Class B''s scores are more spread out. The ranges say nothing about which class has the higher median.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s scores are more spread out than Class A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger range means more spread: 25 > 8, so Class B is more spread out. Range says nothing about the median.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
