INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34ee50b3-cf61-4691-afed-dda41da60318', 'NC26.4.RD.1', 3, 'numeric', 'Choose a graph or a scale', 'The scale of a bar graph counts by 4s: 0, 4, 8, 12, 16, 20, 24. One bar ends exactly halfway between the lines for 20 and 24. What number does the bar show?', '[]', '22', '(20+24)/2', 'Halfway between 20 and 24 is $(20 + 24) \div 2 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halfway between 20 and 24 is 22.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
