INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cc6418b-a8ff-447b-80cb-720562efc23c', 'NC26.4.RD.1', 3, 'choice', 'Frequency tables and tally marks', 'A frequency table shows how many siblings students have. 0 siblings: 6 students. 1 sibling: 10 students. 2 siblings: 9 students. 3 siblings: 5 students. Which statement is true?', '["The most common number of siblings is 3","More students have 1 sibling than any other number of siblings","Exactly 15 students have 2 or more siblings","24 students were asked"]', 'More students have 1 sibling than any other number of siblings', NULL, '10 students have 1 sibling, which is the greatest count. 2 or more siblings is $9 + 5 = 14$ students, and the total asked is $6 + 10 + 9 + 5 = 30$ students.', 'checked', '{"lint":[],"solve":{"answer":"More students have 1 sibling than any other number of siblings","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6+10+9+5 = 30. Most common is 1 (10), not 3. Not 24 asked. 2 or more: 9+5 = 14, not 15. 1 sibling (10) is more than any other: true.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dabd86c-2b16-474f-956d-9781076a6fbe', 'NC26.4.RD.1', 3, 'numeric', 'Frequency tables and tally marks', 'A team''s goals per game are in a frequency table. 0 goals: 2 games. 1 goal: 4 games. 2 goals: 3 games. 3 goals: 1 game. How many goals did the team score in all?', '[]', '13', '0*2+1*4+2*3+3*1', 'Multiply each number of goals by its number of games and add: $0 \times 2 + 1 \times 4 + 2 \times 3 + 3 \times 1 = 0 + 4 + 6 + 3 = 13$ goals.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0x2 + 1x4 + 2x3 + 3x1 = 0 + 4 + 6 + 3 = 13 goals.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59baf9e6-c2b7-4d40-b9b4-9e9c5d7b1e77', 'NC26.4.RD.1', 3, 'numeric', 'Frequency tables and tally marks', 'The numbers of cavities found in 15 children are 0, 2, 1, 0, 3, 1, 0, 2, 1, 1, 0, 4, 1, 2 and 0. How many of the children had at least 2 cavities?', '[]', '5', '5', 'The values that are 2 or more are 2, 3, 2, 4 and 2. That is 5 children.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tally: 0 five times, 1 five times, 2 three times, 3 once, 4 once (total 15). At least 2: 3 + 1 + 1 = 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
