INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df007d9d-3d30-4777-8101-cdc8067728b9', 'NC26.4.RD.1', 3, 'numeric', 'Compare categories in a table', 'In a survey, 12 students chose tennis and 9 students chose volleyball. Basketball got 7 more votes than tennis. How many students chose tennis, volleyball or basketball?', '[]', '40', '12+9+(12+7)', 'Basketball: $12 + 7 = 19$ votes. All three: $12 + 9 + 19 = 40$ students.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Basketball 12 + 7 = 19. Total 12 + 9 + 19 = 40.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
