INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4690f49-565f-464e-80c7-a226c109add2', 'NC26.4.RD.1', 3, 'choice', 'Compare categories in a table', 'Students voted for a pet. Dog: 15. Cat: 12. Bird: 3. Fish: 6. Which statement is true?', '["Cats got twice as many votes as dogs","Birds and fish together got as many votes as cats","Dogs and cats together got more than twice as many votes as birds and fish together","Dogs got 5 more votes than cats"]', 'Dogs and cats together got more than twice as many votes as birds and fish together', NULL, 'Dogs and cats: $15 + 12 = 27$. Birds and fish: $3 + 6 = 9$, and twice 9 is 18, which is less than 27. Cats did not get twice the dogs, 9 is not 12, and dogs got 3 more than cats, not 5.', 'checked', '{"lint":[],"solve":{"answer":"Dogs and cats together got more than twice as many votes as birds and fish together","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs+cats = 27; birds+fish = 9; twice 9 = 18; 27 > 18 true. Birds+fish 9 vs cats 12 false. Dogs - cats = 3, not 5. Cats are not twice dogs.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6e7b08f-d20e-4626-a242-20c50c1630dc', 'NC26.4.RD.1', 3, 'choice', 'Read or build a line plot', 'A line plot shows the hours students slept. There are 2 Xs above 6, 4 Xs above 7, 7 Xs above 8, 3 Xs above 9 and 1 X above 10. Which statement is true?', '["The same number of students slept 7 hours and 9 hours","Fewer than 15 students are shown","Only 1 student slept 6 hours","More students slept 8 hours than any other number of hours"]', 'More students slept 8 hours than any other number of hours', NULL, 'The stack above 8 is the tallest (7). Hours 7 and 9 have 4 and 3 Xs. The total is $2 + 4 + 7 + 3 + 1 = 17$ students, and 2 students slept 6 hours.', 'checked', '{"lint":[],"solve":{"answer":"More students slept 8 hours than any other number of hours","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 2, 4, 7, 3, 1 (total 17). 6 hours had 2, not 1. 17 is not fewer than 15. 8 hours (7) is the most: true. 7 hours 4 vs 9 hours 3: not equal.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('545f98f9-53c1-4e94-a93e-fa7c4886ae42', 'NC26.4.RD.1', 3, 'numeric', 'Read or build a line plot', 'A line plot shows the number of apples picked by 12 children. There is 1 X above 2, 2 Xs above 3, 4 Xs above 4, 3 Xs above 5 and 2 Xs above 6. How many apples were picked altogether?', '[]', '51', '1*2+2*3+4*4+3*5+2*6', 'Multiply each number of apples by its number of Xs and add: $2 + 6 + 16 + 15 + 12 = 51$ apples.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1x2 + 2x3 + 4x4 + 3x5 + 2x6 = 2 + 6 + 16 + 15 + 12 = 51. (Children 1+2+4+3+2 = 12, consistent.)","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('371d4f5b-b3e5-48c0-801b-8baf140081f7', 'NC26.4.RD.1', 3, 'numeric', 'Read or build a line plot', 'A line plot of 20 quiz scores has Xs above 6, 7, 8 and 9 only. There are 3 Xs above 6. There are twice as many Xs above 7 as above 6. There are 5 Xs above 8. The rest are above 9. How many Xs are above 9?', '[]', '6', '20-(3+2*3+5)', 'Above 7 there are $2 \times 3 = 6$ Xs. Above 6, 7 and 8 there are $3 + 6 + 5 = 14$ Xs. The rest are $20 - 14 = 6$ Xs above 9.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Above 6: 3. Above 7: 2 x 3 = 6. Above 8: 5. Sum 14. Above 9: 20 - 14 = 6.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01720654-2c1a-47ac-a78e-2e02798ab9c4', 'NC26.4.RD.1', 3, 'numeric', 'Line plot with fractional measurements', 'A line plot shows the lengths of carrots in inches. The shortest carrot is $2\frac{1}{4}$ inches and the longest is $4\frac{3}{4}$ inches. What is the range of the lengths, in inches?', '[]', '2 1/2', '19/4-9/4', 'Range = $4\frac{3}{4} - 2\frac{1}{4} = 2\frac{2}{4} = 2\frac{1}{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 3/4 - 2 1/4 = 2 2/4 = 2 1/2 inches.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e84fb590-8845-4874-a69c-49c8dec2e196', 'NC26.4.RD.1', 3, 'numeric', 'Line plot with fractional measurements', 'Seven pieces of string measure $3\frac{1}{2}$, $2\frac{1}{4}$, $3\frac{1}{4}$, $2\frac{3}{4}$, $3\frac{1}{2}$, $2\frac{1}{2}$ and 3 inches. What is the median length, in inches?', '[]', '3', '3', 'In order: $2\frac{1}{4}$, $2\frac{1}{2}$, $2\frac{3}{4}$, 3, $3\frac{1}{4}$, $3\frac{1}{2}$, $3\frac{1}{2}$. The middle (fourth) value is 3 inches.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In order: 2 1/4, 2 1/2, 2 3/4, 3, 3 1/4, 3 1/2, 3 1/2. Seven values, middle (4th) is 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
