VALUES ('c987a433-e952-461e-b51d-2e40fdd95ef1', 'NC26.5.ANR.1', 1, 'numeric', 'Order of operations without parentheses', 'Evaluate $9 + 18 \div 3$.', '[]', '15', '9+18/3', 'Divide first: $18 \div 3 = 6$. Then add: $9 + 6 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 3 = 6, then 9 + 6 = 15.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
