INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47bc9040-ba42-4ad1-b7bb-fc0b123df20b', 'NC26.5.ANR.1', 1, 'choice', 'Compare the values of expressions', 'Which expression has a value of 20?', '["$2 + 3 \\times 4$","$2 \\times 3 + 4$","$(2 + 3) \\times 4$","$2 \\times 3 \\times 4$"]', '$(2 + 3) \times 4$', NULL, 'Find each value: $(2 + 3) \times 4 = 5 \times 4 = 20$; $2 + 3 \times 4 = 2 + 12 = 14$; $2 \times 3 + 4 = 6 + 4 = 10$; $2 \times 3 \times 4 = 24$. Only the first has a value of 20.', 'checked', '{"lint":[],"solve":{"answer":"$(2 + 3) \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+3) x 4 = 20; 2 + 3 x 4 = 14; 2 x 3 x 4 = 24; 2 x 3 + 4 = 10. Only the first is 20.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00388d18-11de-470d-b37b-8b0006542752', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a described calculation', 'Which expression shows "multiply 4 by 6, then add 7"?', '["$4 \\times 6 + 7$","$4 \\times (6 + 7)$","$(4 + 6) \\times 7$","$4 + 6 \\times 7$"]', '$4 \times 6 + 7$', NULL, 'Multiplying 4 by 6 gives $4 \times 6$, and then adding 7 gives $4 \times 6 + 7$. Because the multiplication comes first anyway, no parentheses are needed.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 6 + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply 4 by 6 gives 4 x 6, then add 7: 4 x 6 + 7 (order of operations does the product first).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3570583-9d02-4e43-8c7b-3f9c4ed25ab2', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a described calculation', 'Which expression means "subtract 3 from 10, then multiply by 2"?', '["$10 - 3 \\times 2$","$10 \\times 2 - 3$","$(10 + 3) \\times 2$","$(10 - 3) \\times 2$"]', '$(10 - 3) \times 2$', NULL, 'The subtraction $10 - 3$ happens first, so it needs parentheses: $(10 - 3) \times 2$. Without parentheses, $10 - 3 \times 2$ would multiply first.', 'checked', '{"lint":[],"solve":{"answer":"$(10 - 3) \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract 3 from 10 is 10 - 3, which must be grouped before multiplying by 2: (10 - 3) x 2.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3207577c-0895-416f-bbfe-4e936f788048', 'NC26.5.ANR.1', 1, 'numeric', 'Write an expression for a described calculation', 'Add 8 and 4, then divide the result by 3. What number do you get?', '[]', '4', '(8+4)/3', 'Add first: $8 + 4 = 12$. Then divide by 3: $12 \div 3 = 4$. As an expression this is $(8 + 4) \div 3$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 4 = 12; 12 / 3 = 4.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
