INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c12b21c3-445e-42a4-988e-1c4a12e8bf20', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a story', 'Sam has 3 bags with 5 apples in each bag. He also has 2 loose apples. Which expression gives the number of apples Sam has?', '["$3 \\times 5 + 2$","$3 + 5 \\times 2$","$3 \\times (5 + 2)$","$3 + 5 + 2$"]', '$3 \times 5 + 2$', NULL, 'There are $3 \times 5$ apples in the bags, and 2 more loose ones: $3 \times 5 + 2 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 5 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 bags of 5 is 3 x 5, plus 2 loose: 3 x 5 + 2 = 17.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21da7783-02f2-47b9-a97e-8310c60bb90e', 'NC26.5.ANR.1', 1, 'numeric', 'Write an expression for a story', 'A hall has 4 rows of 6 chairs. Then 5 more chairs are put at the back. How many chairs are in the hall?', '[]', '29', '4*6+5', 'The rows hold $4 \times 6 = 24$ chairs. Adding the 5 at the back gives $24 + 5 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 chairs, plus 5 = 29.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
