INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('334810cb-157d-4365-a21c-79d3a65502b8', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a story', 'Lila had 20 stickers. She gave 3 stickers to each of 4 friends. Which expression shows how many stickers she has left?', '["$(20 - 3) \\times 4$","$20 - 3 + 4$","$20 \\times 3 - 4$","$20 - 3 \\times 4$"]', '$20 - 3 \times 4$', NULL, 'She gave away $3 \times 4$ stickers, so she has $20 - 3 \times 4$ left.', 'checked', '{"lint":[],"solve":{"answer":"$20 - 3 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gave away 3 x 4 = 12; left 20 - 3 x 4 = 8.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
