INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d047b18a-2f7d-4059-8cda-4dd38aaa84ea', 'NC26.5.ANR.1', 1, 'choice', 'Interpret an expression without calculating', 'Which sentence describes $3 \times (4 + 2)$?', '["Multiply 3 and 4, then add 2","Add 4 and 2, then multiply by 3","Add 3 and 4, then multiply by 2","Add 3, 4 and 2"]', 'Add 4 and 2, then multiply by 3', NULL, 'The parentheses hold $4 + 2$, so that is done first. The sum is then multiplied by 3.', 'checked', '{"lint":[],"solve":{"answer":"Add 4 and 2, then multiply by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parentheses first: 4 + 2, then times 3.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
