INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bec54b55-ca47-4c92-a0c4-83bb3856a908', 'NC26.5.ANR.1', 1, 'choice', 'Interpret an expression without calculating', 'Which expression is 4 times as large as $7 + 5$?', '["$4 \\times 7 + 5$","$4 + 7 + 5$","$4 \\times (7 + 5)$","$(4 + 7) \\times 5$"]', '$4 \times (7 + 5)$', NULL, 'To make $7 + 5$ four times as large, multiply the whole sum by 4: $4 \times (7 + 5)$. Without parentheses, $4 \times 7 + 5$ would multiply only the 7.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times (7 + 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 times as large as (7 + 5) is 4 x (7 + 5). 4 x 7 + 5 only multiplies the 7.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6bb4ef9-8796-487e-9fbc-c8777df25be0', 'NC26.5.ANR.1', 1, 'numeric', 'Commutative property', 'What number goes in the box to make the equation true? $8 + 5 = 5 + \square$', '[]', '8', '(8+5)-5', 'Numbers can be added in either order. $8 + 5 = 5 + 8$, so the box is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy for Grade 5 (a first-grade addition fact); fine only as a warm-up item.","work":"Commutative property: 8 + 5 = 5 + 8, box = 8.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3edc7be7-75a4-4b8f-a4b7-62a341e37e5a', 'NC26.5.ANR.1', 1, 'choice', 'Commutative property', 'Which equation shows the commutative property of multiplication?', '["$6 \\times (9 \\times 2) = (6 \\times 9) \\times 2$","$6 \\times 1 = 6$","$6 \\times 9 = 9 \\times 6$","$6 \\times (9 + 2) = 6 \\times 9 + 6 \\times 2$"]', '$6 \times 9 = 9 \times 6$', NULL, 'The commutative property says the order of the numbers does not change a product: $6 \times 9 = 9 \times 6$. The others show the associative property, the identity property and the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 9 = 9 \\times 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Commutative property of multiplication swaps the order of factors: 6 x 9 = 9 x 6. A is associative, C identity, D distributive.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0783a17c-95ed-4b15-aa43-a055dfdc8339', 'NC26.5.ANR.1', 1, 'numeric', 'Commutative property', 'Mia knows that $17 \times 24$ equals 408. What is the value of $24 \times 17$?', '[]', '408', '17*24', 'Changing the order of the factors does not change the product. So $24 \times 17 = 17 \times 24 = 408$.', 'checked', '{"lint":[],"solve":{"answer":"408","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Commutative: 24 x 17 = 17 x 24 = 408. (Check 17 x 24 = 340 + 68 = 408.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3b129a-738e-4f32-bc8b-3a98de93adb3', 'NC26.5.ANR.1', 1, 'numeric', 'Associative property', 'What number goes in the box to make the equation true? $(4 + 7) + 3 = 4 + (\square + 3)$', '[]', '7', '(4+7)+3-4-3', 'Numbers can be grouped in different ways without changing the sum. On the left the numbers are 4, 7 and 3 in that order, so the box is 7. Both sides equal 14.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property: (4 + 7) + 3 = 4 + (7 + 3); box = 7. Check 14 = 14.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4cf22ef-6675-4c6a-9535-d7082f114b61', 'NC26.5.ANR.1', 1, 'numeric', 'Distributive property', 'What number goes in the box to make the equation true? $4 \times 12 = 4 \times 10 + 4 \times \square$', '[]', '2', '12-10', 'Split 12 into $10 + 2$. Then $4 \times 12 = 4 \times 10 + 4 \times 2$, so the box is 2. Both sides equal 48.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 10 + 2, so 4 x 12 = 4 x 10 + 4 x 2; box = 2. Check 48 = 40 + 8.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
