INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f2b0acf-8cc3-47c0-8f34-9126d2f1f9d5', 'NC26.5.ANR.1', 1, 'numeric', 'Identity and zero properties', 'What is the value of $86 \times 0$?', '[]', '0', '86*0', 'Any number times 0 is 0. So $86 \times 0 = 0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any number times 0 is 0.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
