INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86758f2a-0da3-4676-b566-6f4e63b7dee3', 'NC26.5.ANR.1', 2, 'numeric', 'Order of operations without parentheses', 'Evaluate $125 - 4 \times 25$.', '[]', '25', '125-4*25', 'Multiply first: $4 \times 25 = 100$. Then subtract: $125 - 100 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 25 = 100, then 125 - 100 = 25.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
