INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e717f6-5ce9-4c9e-a339-ed5a54a31ea4', 'NC26.5.ANR.1', 2, 'choice', 'Compare the values of expressions', 'Four expressions use the numbers 6, 2 and 3. Which one has the least value?', '["$6 + 2 \\times 3$","$(6 + 2) \\times 3$","$6 \\times 2 + 3$","$6 \\times (2 + 3)$"]', '$6 + 2 \times 3$', NULL, 'Find each value: $6 + 2 \times 3 = 12$; $(6 + 2) \times 3 = 24$; $6 \times 2 + 3 = 15$; $6 \times (2 + 3) = 30$. The least value is 12.', 'checked', '{"lint":[],"solve":{"answer":"$6 + 2 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2 + 3 = 15; 6 + 2 x 3 = 12; (6+2) x 3 = 24; 6 x (2+3) = 30. Least is 12.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77d812d2-b0a5-4979-a447-924a5c09b736', 'NC26.5.ANR.1', 2, 'choice', 'Compare the values of expressions', 'Which pair of expressions has the same value?', '["$2 + 3 \\times 4$ and $(2 + 3) \\times 4$","$2 + 3 \\times 4$ and $4 \\times 3 + 2$","$12 - 4 \\div 2$ and $(12 - 4) \\div 2$","$5 \\times 2 + 1$ and $5 \\times (2 + 1)$"]', '$2 + 3 \times 4$ and $4 \times 3 + 2$', NULL, '$2 + 3 \times 4 = 2 + 12 = 14$ and $4 \times 3 + 2 = 12 + 2 = 14$. In every other pair, the parentheses change the order of the steps and so change the value: 14 and 20, 10 and 4, 11 and 15.', 'checked', '{"lint":[],"solve":{"answer":"$2 + 3 \\times 4$ and $4 \\times 3 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 vs 20; 12 - 2 = 10 vs 8/2 = 4; 11 vs 15; 2 + 12 = 14 vs 12 + 2 = 14. Only the last pair match.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf4938a5-b835-4a0b-a411-abbda901a2ca', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a described calculation', 'Which expression means "divide 36 by the sum of 5 and 4"?', '["$36 \\div 5 + 4$","$(36 + 5) \\div 4$","$36 \\div (5 + 4)$","$36 \\times (5 + 4)$"]', '$36 \div (5 + 4)$', NULL, '"The sum of 5 and 4" is $5 + 4$, and it must be worked out before the division, so it goes in parentheses: $36 \div (5 + 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$36 \\div (5 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sum of 5 and 4 is (5 + 4); 36 divided by it is 36 / (5 + 4).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb75630d-578f-4230-b73a-eca3a0b7bddc', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a described calculation', 'Which expression means "6 less than the product of 8 and 5"?', '["$8 \\times 5 - 6$","$6 - 8 \\times 5$","$8 \\times (5 + 6)$","$8 \\times 5 + 6$"]', '$8 \times 5 - 6$', NULL, '"The product of 8 and 5" is $8 \times 5$, and "6 less than" that is $8 \times 5 - 6$.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 5 - 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product of 8 and 5 is 8 x 5; 6 less than that is 8 x 5 - 6.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab43bf40-e205-493e-a7c5-623701208aad', 'NC26.5.ANR.1', 2, 'numeric', 'Write an expression for a described calculation', 'Multiply 7 by the difference between 12 and 5. What is the result?', '[]', '49', '7*(12-5)', 'The difference between 12 and 5 is $12 - 5 = 7$. Then $7 \times 7 = 49$. As an expression this is $7 \times (12 - 5)$.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference 12 - 5 = 7; 7 x 7 = 49.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e75affe-fa81-4dbc-8db0-1012fd8a6879', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a story', 'A shop sells pens in packs of 8. Dev buys 5 packs and then uses 12 pens. Which expression shows how many pens he has left?', '["$5 + 8 - 12$","$5 \\times 8 - 12$","$5 \\times (8 + 12)$","$8 \\times 12 - 5$"]', '$5 \times 8 - 12$', NULL, 'Dev buys $5 \times 8$ pens and uses 12 of them, so he has $5 \times 8 - 12$ pens left. That is $40 - 12 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 8 - 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 packs of 8 = 5 x 8 = 40; uses 12: 5 x 8 - 12 = 28.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a9a1dca-5f3d-4ba2-9da1-184f73c44d41', 'NC26.5.ANR.1', 2, 'numeric', 'Write an expression for a story', 'Nia buys 3 notebooks that cost 4 dollars each and 2 pens that cost 3 dollars each. How many dollars does she spend in all?', '[]', '18', '3*4+2*3', 'The notebooks cost $3 \times 4 = 12$ dollars and the pens cost $2 \times 3 = 6$ dollars. In all she spends $12 + 6 = 18$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Notebooks 3 x 4 = 12, pens 2 x 3 = 6; 12 + 6 = 18.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4a91fae-86fe-493c-abf4-a45920b2bfed', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a story', 'Four friends share the cost of a 36 dollar game and a 12 dollar poster equally. Which expression shows how much each friend pays?', '["$36 + 12 \\div 4$","$36 \\div 4 + 12$","$(36 + 12) \\div 4$","$(36 + 12) \\times 4$"]', '$(36 + 12) \div 4$', NULL, 'The total cost is $36 + 12$, and it is shared among 4 friends, so each pays $(36 + 12) \div 4$. That is $48 \div 4 = 12$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$(36 + 12) \\div 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total cost 36 + 12 = 48, shared by 4: (36 + 12) / 4 = 12.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd467941-0dec-4ba4-9077-b98afa0e3fef', 'NC26.5.ANR.1', 2, 'choice', 'Interpret an expression without calculating', 'Without finding its value, which statement is true about $5 \times (123 + 456)$?', '["It is 5 times as large as $123 + 456$","It is 5 more than $123 + 456$","It is 5 less than $123 + 456$","It is one fifth of $123 + 456$"]', 'It is 5 times as large as $123 + 456$', NULL, 'The sum $123 + 456$ is multiplied by 5, so the expression is 5 times as large as the sum.', 'checked', '{"lint":[],"solve":{"answer":"It is 5 times as large as $123 + 456$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x (123 + 456) is 5 groups of the sum, so 5 times as large as 123 + 456.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2852333b-1361-4684-9de5-766d14ae5b14', 'NC26.5.ANR.1', 2, 'choice', 'Interpret an expression without calculating', 'Maya uses $4 \times 6 + 2 \times 3$ for the cost of 4 notebooks at 6 dollars each and 2 pens at 3 dollars each. What does $2 \times 3$ stand for?', '["The cost of the 4 notebooks","The cost of the 2 pens","The cost of all the items","The number of items bought"]', 'The cost of the 2 pens', NULL, 'The part $2 \times 3$ is 2 pens at 3 dollars each, so it is the cost of the 2 pens.', 'checked', '{"lint":[],"solve":{"answer":"The cost of the 2 pens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 pens at 3 dollars each: 2 x 3 is the cost of the 2 pens.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771e2694-04e0-4d58-ae9b-f9eb78fd4330', 'NC26.5.ANR.1', 2, 'choice', 'Commutative property', 'Which pair of expressions are equal because of the commutative property?', '["$25 \\times 4$ and $4 \\times 25$","$25 - 4$ and $25 + 4$","$25 \\div 5$ and $5 \\div 25$","$25 + 4$ and $25 \\times 4$"]', '$25 \times 4$ and $4 \times 25$', NULL, 'Only addition and multiplication can be done in either order. $25 \times 4 = 4 \times 25 = 100$. Subtracting and dividing cannot: $25 - 4 = 21$ is not $25 + 4 = 29$, and $25 \div 5 = 5$ is not $5 \div 25$. Also $25 + 4 = 29$ is not $25 \times 4 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"$25 \\times 4$ and $4 \\times 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 x 4 = 4 x 25 by the commutative property (both 100). The others are not equal.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c56a9155-ebe7-40cd-bfc3-8c101a5b54ad', 'NC26.5.ANR.1', 2, 'choice', 'Commutative property', 'Which equation is NOT true?', '["$12 + 5 = 5 + 12$","$12 \\times 5 = 5 \\times 12$","$12 + 0 = 0 + 12$","$12 \\div 4 = 4 \\div 12$"]', '$12 \div 4 = 4 \div 12$', NULL, 'Addition and multiplication can be done in either order. Division cannot: $12 \div 4 = 3$ but $4 \div 12$ is much less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$12 \\div 4 = 4 \\div 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 0 = 0 + 12 true; 17 = 17 true; 60 = 60 true; 12 / 4 = 3 but 4 / 12 = 1/3, so the division one is not true.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
