INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f9d2224-630a-487e-aa84-f482a790d96e', 'NC26.5.ANR.1', 2, 'choice', 'Associative property', 'Which equation shows the associative property of multiplication?', '["$2 \\times 5 \\times 7 = 7 \\times 5 \\times 2$","$2 \\times (5 + 7) = 2 \\times 5 + 2 \\times 7$","$(2 \\times 5) \\times 7 = 2 \\times (5 \\times 7)$","$2 \\times 5 = 5 \\times 2$"]', '$(2 \times 5) \times 7 = 2 \times (5 \times 7)$', NULL, 'The associative property says that changing how factors are grouped does not change the product. Both sides keep the order 2, 5, 7 and only move the parentheses.', 'checked', '{"lint":[],"solve":{"answer":"$(2 \\times 5) \\times 7 = 2 \\times (5 \\times 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property regroups: (2 x 5) x 7 = 2 x (5 x 7). A is distributive, B commutative, C reorders (commutative).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8da3bba-1e26-4643-b524-dac46ebfdaa9', 'NC26.5.ANR.1', 2, 'numeric', 'Associative property', 'To find $4 \times (7 \times 25)$ in her head, Mina first groups $4 \times 25$. What is the value of the whole expression?', '[]', '700', '4*25*7', 'Regroup the factors: $4 \times 25 = 100$ and $100 \times 7 = 700$. So the value is 700.', 'checked', '{"lint":[],"solve":{"answer":"700","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 25 = 100; 100 x 7 = 700.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a5671a1-e6d4-4d9a-a533-4e259cc7a1bd', 'NC26.5.ANR.1', 2, 'choice', 'Distributive property', 'Which expression is equal to $9 \times (10 - 2)$?', '["$9 \\times 10 - 2$","$9 \\times 10 \\times 2$","$(9 \\times 10) - (2 \\times 10)$","$9 \\times 10 - 9 \\times 2$"]', '$9 \times 10 - 9 \times 2$', NULL, 'The 9 multiplies both numbers in the parentheses: $9 \times 10 - 9 \times 2 = 90 - 18 = 72$, the same as $9 \times 8$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 10 - 9 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x (10 - 2) = 72 = 9 x 10 - 9 x 2 = 90 - 18. Others: 88, 70, 180.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c042d5b8-d4cd-4771-b48d-65d2a0acc513', 'NC26.5.ANR.1', 2, 'numeric', 'Distributive property', 'Sara finds $8 \times 49$ by thinking of it as $8 \times 50 - 8 \times 1$. What is the value?', '[]', '392', '8*50-8*1', '$8 \times 50 = 400$ and $8 \times 1 = 8$. Subtracting gives $400 - 8 = 392$.', 'checked', '{"lint":[],"solve":{"answer":"392","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 50 = 400; 8 x 1 = 8; 400 - 8 = 392.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4069dc8e-c037-44ad-9317-e85f4df9d74e', 'NC26.5.ANR.1', 2, 'choice', 'Distributive property', 'Which equation shows the distributive property?', '["$4 \\times (6 \\times 3) = (4 \\times 6) \\times 3$","$4 \\times (6 + 3) = 4 \\times 6 + 4 \\times 3$","$4 \\times 6 = 6 \\times 4$","$4 \\times 1 = 4$"]', '$4 \times (6 + 3) = 4 \times 6 + 4 \times 3$', NULL, 'The distributive property multiplies a number by each part of a sum: $4 \times (6 + 3) = 4 \times 6 + 4 \times 3$. The others show the associative, commutative and identity properties.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times (6 + 3) = 4 \\times 6 + 4 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distributive: 4 x (6 + 3) = 4 x 6 + 4 x 3 (36 = 24 + 12). B associative, C commutative, D identity.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a9c2404-cfd7-41e5-b5e7-89cbd0b020d6', 'NC26.5.ANR.1', 2, 'choice', 'Identity and zero properties', 'Which equation shows the identity property of multiplication?', '["$9 \\times 0 = 0$","$9 \\times 1 = 9$","$9 + 0 = 9$","$9 \\times 3 = 3 \\times 9$"]', '$9 \times 1 = 9$', NULL, 'The identity property of multiplication says that a number times 1 stays the same: $9 \times 1 = 9$. The equation $9 + 0 = 9$ is the identity property of addition, $9 \times 0 = 0$ is the zero property and $9 \times 3 = 3 \times 9$ is the commutative property.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 1 = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Identity property of multiplication: times 1 leaves the number unchanged, 9 x 1 = 9. 9 x 0 is the zero property, 9 + 0 additive identity, last commutative.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b32f92b2-8dcd-4b4c-b296-28c94f456481', 'NC26.5.ANR.1', 2, 'choice', 'Connect an expression to a representation', 'A rectangle is 9 units long and 6 units wide. It is cut into a rectangle that is 9 by 4 and a rectangle that is 9 by 2. Which expression gives the area of the large rectangle?', '["$9 \\times 4 + 2$","$9 \\times 4 + 9 \\times 2$","$9 + 4 \\times 2$","$(9 + 4) \\times 2$"]', '$9 \times 4 + 9 \times 2$', NULL, 'The area is the sum of the two parts: $9 \times 4 + 9 \times 2 = 36 + 18 = 54$. That is the same as $9 \times 6$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 4 + 9 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 9 x 6 = 54 = 9 x 4 + 9 x 2 = 36 + 18. Others: 17, 38, 26.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee0a5e90-1530-42b7-ad1b-61807db626ae', 'NC26.5.ANR.1', 2, 'numeric', 'Connect an expression to a representation', 'An area model for 7 times 24 is split into a rectangle that is 7 by 20 and a rectangle that is 7 by 4. What is the total area?', '[]', '168', '7*20+7*4', 'The parts have areas $7 \times 20 = 140$ and $7 \times 4 = 28$. The total is $140 + 28 = 168$.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 20 = 140; 7 x 4 = 28; 140 + 28 = 168.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae0ca73f-ae63-4d53-afcb-fb92c955bd26', 'NC26.5.ANR.1', 2, 'numeric', 'Find the missing number or sign', 'What number makes the equation true? $5 + 3 \times \square = 29$', '[]', '8', '(29-5)/3', 'Multiplication comes first, so $3 \times \square$ must be $29 - 5 = 24$. Then the box is $24 \div 3 = 8$. Check: $5 + 3 \times 8 = 5 + 24 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 x box = 29, so 3 x box = 24, box = 8. Check 5 + 24 = 29.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f95d15f6-d0c8-4bae-b5d5-b2155fd7a4f8', 'NC26.5.ANR.1', 2, 'choice', 'Find the missing number or sign', 'Which sign goes in the box to make the equation true? $20 \ \square \ 4 \times 2 = 12$', '["$+$","$-$","$\\times$","$\\div$"]', '$-$', NULL, 'Multiplication comes first: $4 \times 2 = 8$. We need $20 \ \square \ 8 = 12$, and $20 - 8 = 12$. So the sign is minus. The other signs give 28, 160 and 10.', 'checked', '{"lint":[],"solve":{"answer":"$-$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 2 = 8 is done first, so 20 ? 8 = 12 needs minus. Check others: 20 x 4 x 2 = 160, 20 + 8 = 28, 20 / 4 x 2 = 10 (left to right). Only minus.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21665b95-b736-4a34-85f7-625440aa9a58', 'NC26.5.ANR.1', 2, 'choice', 'Find the mistake in an evaluation', 'Kofi says that $4 + 6 \times 5$ equals 50. What did he do?', '["He multiplied 4 and 6 first, then added 5","He multiplied 6 and 5 first, then subtracted 4","He added 4 and 6 first, then multiplied by 5","He added all three numbers"]', 'He added 4 and 6 first, then multiplied by 5', NULL, 'Adding first gives $(4 + 6) \times 5 = 50$, which is Kofi''s answer. The correct way is to multiply first: $6 \times 5 = 30$, then $4 + 30 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"He added 4 and 6 first, then multiplied by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct value 4 + 30 = 34. 50 = (4 + 6) x 5, so he added 4 and 6 first. B gives 29, C 26, D 15.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037a88e1-019e-482d-b4df-d3a8b1e0c3bc', 'NC26.5.ANR.1', 3, 'numeric', 'Evaluate an expression with parentheses and two other operations', 'Find the value of $2 \times (15 - 6) + 4 \times 3$.', '[]', '30', '2*(15-6)+4*3', 'Parentheses first: $15 - 6 = 9$. Then multiply: $2 \times 9 = 18$ and $4 \times 3 = 12$. Then add: $18 + 12 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 - 6 = 9; 2 x 9 = 18; 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e6bf441-28e3-45a9-8463-bd6fdc8d7d29', 'NC26.5.ANR.1', 3, 'choice', 'Compare the values of expressions', 'Which expression has the greatest value?', '["$24 \\div 4 + 2$","$24 \\div (4 + 2)$","$(24 - 4) \\times 2$","$24 - 4 \\times 2$"]', '$(24 - 4) \times 2$', NULL, '$24 \div 4 + 2 = 8$, $24 \div (4 + 2) = 4$, $24 - 4 \times 2 = 16$, and $(24 - 4) \times 2 = 40$. The greatest is $(24 - 4) \times 2$.', 'checked', '{"lint":[],"solve":{"answer":"$(24 - 4) \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(24-4) x 2 = 40; 24/(4+2) = 4; 24 - 4x2 = 16; 24/4 + 2 = 8. Greatest is 40.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c2b990f-e1e9-4c7b-aba8-a56a1341fadb', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a situation', 'Each box holds 6 red pens and 4 blue pens. Which expression gives the number of pens in 3 boxes?', '["$3 \\times (6 + 4)$","$3 \\times 6 + 4$","$3 + 6 \\times 4$","$3 \\times 6 \\times 4$"]', '$3 \times (6 + 4)$', NULL, 'One box holds $6 + 4$ pens. Three boxes hold 3 times that: $3 \times (6 + 4) = 30$ pens. The other expressions multiply only one kind of pen by 3, or multiply all three numbers.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times (6 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each box has 6 + 4 = 10 pens; 3 boxes: 3 x (6 + 4) = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2db2f228-5704-49d1-ad40-007a5dd57a5c', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations without parentheses', 'What is the value of $3 \times 12 + 40 \div 8$?', '[]', '41', '3*12+40/8', 'Do the multiplication and the division first: $3 \times 12 = 36$ and $40 \div 8 = 5$. Then add: $36 + 5 = 41$.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 12 = 36 and 40 / 8 = 5; 36 + 5 = 41.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('958ecadb-cfca-459f-9df4-df74b0b78db2', 'NC26.5.ANR.1', 3, 'choice', 'Order of operations without parentheses', 'Which is the value of $90 \div 9 - 2 \times 4$?', '["2","32","18","8"]', '2', '90/9-2*4', 'Do the division and the multiplication first: $90 \div 9 = 10$ and $2 \times 4 = 8$. Then subtract: $10 - 8 = 2$. The choice 32 comes from working left to right ($8 \times 4$), 18 from adding 8 instead of subtracting, and 8 from taking away only 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 / 9 = 10 and 2 x 4 = 8; 10 - 8 = 2. (32 = (10 - 2) x 4.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ddbb4e8-06ea-4413-98b7-50fa53e2c672', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations without parentheses', 'Evaluate $7 \times 13 + 480 \div 12$.', '[]', '131', '7*13+480/12', 'Multiply and divide first: $7 \times 13 = 91$ and $480 \div 12 = 40$. Then add: $91 + 40 = 131$.', 'checked', '{"lint":[],"solve":{"answer":"131","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 13 = 91 and 480 / 12 = 40; 91 + 40 = 131.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88443329-bbc0-445c-8e8e-04581998f398', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations with parentheses', 'Evaluate $(14 - 6) \times (9 - 3)$.', '[]', '48', '(14-6)*(9-3)', 'Do each set of parentheses first: $14 - 6 = 8$ and $9 - 3 = 6$. Then multiply: $8 \times 6 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 - 6 = 8 and 9 - 3 = 6; 8 x 6 = 48.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
