INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c74850b-8cc6-4e27-817f-1526f1e1cf89', 'NC26.5.ANR.1', 3, 'choice', 'Order of operations with parentheses', 'Which is the value of $5 \times (24 \div 6 + 2)$?', '["22","30","15","20"]', '30', '5*(24/6+2)', 'Inside the parentheses, divide before adding: $24 \div 6 = 4$ and $4 + 2 = 6$. Then multiply: $5 \times 6 = 30$. The choice 22 comes from ignoring the parentheses ($5 \times 4 + 2$), 15 from computing $24 \div (6 + 2)$ first, and 20 from leaving out the $+ 2$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inside: 24 / 6 = 4, 4 + 2 = 6; 5 x 6 = 30. (22 = 5 x 4 + 2.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb9249f4-3ca1-498b-b4d3-252bfdd8f6e7', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations with parentheses', 'What is the value of $2 \times (50 - 3 \times 8)$?', '[]', '52', '2*(50-3*8)', 'Inside the parentheses, multiply before subtracting: $3 \times 8 = 24$ and $50 - 24 = 26$. Then multiply: $2 \times 26 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inside: 3 x 8 = 24, 50 - 24 = 26; 2 x 26 = 52.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('435f6c79-216c-487d-a6e5-5918041ecffd', 'NC26.5.ANR.1', 3, 'choice', 'Compare the values of expressions', 'Which statement is true?', '["$7 + 3 \\times 5 = (7 + 3) \\times 5$","$36 \\div 6 + 3 < 36 \\div (6 + 3)$","$20 - 3 \\times 4 < (20 - 3) \\times 4$","$4 \\times 5 - 2 = 4 \\times (5 - 2)$"]', '$20 - 3 \times 4 < (20 - 3) \times 4$', NULL, '$20 - 3 \times 4 = 8$ and $(20 - 3) \times 4 = 68$, and $8 < 68$ is true. The others are false: $7 + 3 \times 5 = 22$ but $(7 + 3) \times 5 = 50$; $36 \div 6 + 3 = 9$ but $36 \div (6 + 3) = 4$, and 9 is not less than 4; $4 \times 5 - 2 = 18$ but $4 \times (5 - 2) = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$20 - 3 \\times 4 < (20 - 3) \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 = 12? no. 22 = 50? no. 6 + 3 = 9 < 36/9 = 4? no. 20 - 12 = 8 < 17 x 4 = 68? yes. Only the last is true.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d17aa4a1-f364-4c67-a4f0-a38e3872c1f8', 'NC26.5.ANR.1', 3, 'numeric', 'Compare the values of expressions', 'Four expressions are listed: $4 + 5 \times 4$, $(4 + 5) \times 4$, $4 \times 5 + 4$ and $4 \times (5 + 4)$. How many of them have a value of 24?', '[]', '2', NULL, '$4 + 5 \times 4 = 4 + 20 = 24$; $(4 + 5) \times 4 = 36$; $4 \times 5 + 4 = 24$; $4 \times (5 + 4) = 36$. Two of the four have a value of 24.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 20 = 24 (yes); 9 x 4 = 36; 20 + 4 = 24 (yes); 4 x 9 = 36. Two of them.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e57d61ce-666e-47ee-a13b-b14443596f6e', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a described calculation', 'Which expression means "subtract 4 from twice the sum of 9 and 6"?', '["$2 \\times 9 + 6 - 4$","$2 \\times (9 + 6 - 4)$","$2 + (9 + 6) - 4$","$2 \\times (9 + 6) - 4$"]', '$2 \times (9 + 6) - 4$', NULL, '"The sum of 9 and 6" is $(9 + 6)$. "Twice" that is $2 \times (9 + 6)$. "Subtract 4 from" that gives $2 \times (9 + 6) - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times (9 + 6) - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice the sum of 9 and 6 is 2 x (9 + 6); subtract 4: 2 x (9 + 6) - 4.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('550d3dd4-6d91-4f0c-99d3-0d6f8dc3385e', 'NC26.5.ANR.1', 3, 'numeric', 'Write an expression for a described calculation', 'Divide 100 by the product of 5 and 4, then add 12. What number do you get?', '[]', '17', '100/(5*4)+12', 'The product of 5 and 4 is 20. Dividing gives $100 \div 20 = 5$. Adding 12 gives $5 + 12 = 17$. As an expression this is $100 \div (5 \times 4) + 12$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product 5 x 4 = 20; 100 / 20 = 5; 5 + 12 = 17.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
