VALUES ('4e62448b-e6eb-417e-b8c6-ac7333478a3b', 'NC26.5.ANR.2', 3, 'choice', 'Value of a digit in a decimal to the thousandths', 'Which number has a 5 in the hundredths place and a 3 in the thousandths place?', '["$12.135$","$12.513$","$12.351$","$12.153$"]', '$12.153$', NULL, 'The hundredths place is the second digit after the point and the thousandths place is the third. In $12.153$ these digits are 5 and 3. The others have 3 and 5, 1 and 3, or 5 and 1.', 'checked', '{"lint":[],"solve":{"answer":"$12.153$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12.351: 5 hundredths, 1 thousandth. 12.153: 1 tenth, 5 hundredths, 3 thousandths (yes). 12.135: 3 hundredths. 12.513: 1 hundredth.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
