VALUES ('60674bbb-1d1b-454a-afe2-9b7a8706771f', 'NC26.5.ANR.2', 3, 'choice', 'Decimals in words and standard form', 'Which decimal is the same as "twenty-two and twenty-two thousandths"?', '["22.22","22.0022","22.022","22.202"]', '22.022', NULL, 'Twenty-two thousandths needs three decimal places: $0.022$. So the number is $22.022$. The choice $22.22$ is twenty-two and twenty-two hundredths.', 'checked', '{"lint":[],"solve":{"answer":"22.022","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 + 22/1000 = 22.022.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
