INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e12a0f5f-9f56-4f85-91fa-fcd1f58d894d', 'NC26.5.ANR.2', 3, 'choice', 'Expanded form of a number', 'Which shows $24.305$ in expanded form using fractions?', '["$2 \\times 10 + 4 \\times 1 + 3 \\times \\frac{1}{10} + 5 \\times \\frac{1}{100}$","$2 \\times 10 + 4 \\times 1 + 3 \\times \\frac{1}{10} + 5 \\times \\frac{1}{1000}$","$2 \\times 10 + 4 \\times 1 + 3 \\times \\frac{1}{100} + 5 \\times \\frac{1}{1000}$","$2 \\times 100 + 4 \\times 10 + 3 \\times \\frac{1}{10} + 5 \\times \\frac{1}{1000}$"]', '$2 \times 10 + 4 \times 1 + 3 \times \frac{1}{10} + 5 \times \frac{1}{1000}$', NULL, 'In $24.305$ there are 2 tens, 4 ones, 3 tenths, 0 hundredths and 5 thousandths. So the 3 is multiplied by $\frac{1}{10}$ and the 5 by $\frac{1}{1000}$.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times 10 + 4 \\times 1 + 3 \\times \\frac{1}{10} + 5 \\times \\frac{1}{1000}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24.305 = 2 x 10 + 4 x 1 + 3 x 1/10 + 0 x 1/100 + 5 x 1/1000.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ba0a199-cf38-4d51-b8eb-83f902849dcb', 'NC26.5.ANR.2', 3, 'numeric', 'Expanded form of a number', 'What number is equal to $6 + 14 \times 0.1 + 5 \times 0.001$?', '[]', '7.405', '6+14*0.1+5*0.001', '$14 \times 0.1 = 1.4$ and $5 \times 0.001 = 0.005$. So the number is $6 + 1.4 + 0.005 = 7.405$.', 'checked', '{"lint":[],"solve":{"answer":"7.405","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 0.1 = 1.4; 5 x 0.001 = 0.005; 6 + 1.4 + 0.005 = 7.405.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
