INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a73d7bce-17c0-4af0-aa6d-c7ffca0985f3', 'NC26.5.ANR.2', 3, 'numeric', 'Expanded form of a number', 'A number is made of 3 millions, 15 hundreds and 8 tens. What is the number?', '[]', '3001580', '3*1000000+15*100+8*10', '3 millions is 3,000,000, 15 hundreds is 1,500 and 8 tens is 80. The sum is $3{,}000{,}000 + 1{,}500 + 80 = 3{,}001{,}580$.', 'checked', '{"lint":[],"solve":{"answer":"3001580","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,000,000 + 15 x 100 = 1,500 + 8 x 10 = 80: 3,001,580.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
