INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ff4ed03-915d-41ba-8c5b-5b7883830cf7', 'NC26.5.ANR.2', 3, 'choice', 'Equivalent decimals', 'Which list shows only decimals that are equal to each other?', '["0.5, 0.50, 0.500","0.5, 0.05, 0.005","0.3, 0.30, 0.03","1.2, 1.02, 1.20"]', '0.5, 0.50, 0.500', NULL, 'Only zeros at the END of a decimal can be added or dropped without changing its value. $0.5 = 0.50 = 0.500$. In the other lists a zero sits between the point and a digit, which changes the value.', 'checked', '{"lint":[],"solve":{"answer":"0.5, 0.50, 0.500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5 = 0.50 = 0.500 all equal. 1.02 differs from 1.2; 0.05, 0.005 differ; 0.03 differs.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
