INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35c17bbf-f049-422e-9d0d-223622ef6ecd', 'NC26.5.ANR.3', 1, 'choice', 'Multiply a three-digit number by a two-digit number', 'Pia multiplies $346 \times 27$ by breaking 27 into $20 + 7$. Her first partial product is $346 \times 7 = 2{,}422$. Which multiplication gives her second partial product?', '["$346 \\times 2$","$346 \\times 20$","$346 \\times 27$","$346 \\times 70$"]', '$346 \times 20$', NULL, 'Breaking 27 into $20 + 7$ gives two partial products: $346 \times 7$ and $346 \times 20$. The second one is $346 \times 20 = 6{,}920$.', 'checked', '{"lint":[],"solve":{"answer":"$346 \\times 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 = 20 + 7; first partial product uses 7, so the second uses 20: 346 x 20 = 6,920.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
