VALUES ('e50efa73-121a-4e40-801f-12ecef196ab3', 'NC26.5.ANR.3', 2, 'numeric', 'Multiply a three-digit number by a two-digit number', 'Find $467 \times 38$.', '[]', '17746', '467*38', '$467 \times 30 = 14{,}010$ and $467 \times 8 = 3{,}736$. Add: $14{,}010 + 3{,}736 = 17{,}746$.', 'checked', '{"lint":[],"solve":{"answer":"17746","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"467 x 38 = 467 x 30 + 467 x 8 = 14,010 + 3,736 = 17,746.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
