INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5889066-64ba-4c74-bbbe-8556d44639d1', 'NC26.5.ANR.3', 2, 'choice', 'Interpret a remainder in context', 'Jo has $1{,}000$ bottle caps and makes groups of 6. He finds that $1{,}000 \div 6 = 166$ R 4. What does the remainder 4 mean?', '["There are 4 groups of 6 bottle caps.","Each group has 4 bottle caps.","4 more groups can be made.","4 bottle caps are left over after 166 full groups are made."]', '4 bottle caps are left over after 166 full groups are made.', NULL, 'The quotient 166 is the number of full groups of 6. The remainder 4 is the number of bottle caps left over, too few to make another group.', 'checked', '{"lint":[],"solve":{"answer":"4 bottle caps are left over after 166 full groups are made.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"166 groups of 6 = 996 caps; 1,000 - 996 = 4 caps left over, not enough for another group.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
