INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('845e9117-eb8d-4b62-bb83-c2dce40bd4c9', 'NC26.5.ANR.3', 2, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A bakery makes 12 batches of 145 cookies. It sells $1{,}000$ cookies. How many cookies are left?', '[]', '740', '12*145-1000', '$12 \times 145 = 1{,}740$ cookies. Then $1{,}740 - 1{,}000 = 740$ cookies are left.', 'checked', '{"lint":[],"solve":{"answer":"740","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 145 = 1,740 cookies; 1,740 - 1,000 = 740 left.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
