INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85c1f8b1-3f4e-4ca6-ad03-fcfcaa32a1ae', 'NC26.5.ANR.3', 2, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A warehouse ships $3{,}600$ books in boxes of 8 books. Each box is sealed with 12 inches of tape. How many inches of tape are used?', '[]', '5400', '3600/8*12', '$3{,}600 \div 8 = 450$ boxes. $450 \times 12 = 5{,}400$ inches of tape.', 'checked', '{"lint":[],"solve":{"answer":"5400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,600 / 8 = 450 boxes; 450 x 12 = 5,400 inches of tape.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
