VALUES ('a26c66c1-b92e-4064-8faa-7de30a1f9063', 'NC26.5.ANR.3', 2, 'numeric', 'Solve a multi-step problem with multiplication and division', 'Ben has $2{,}400$ stickers. He gives 125 stickers to each of 12 friends. How many stickers does Ben have left?', '[]', '900', '2400-125*12', '$125 \times 12 = 1{,}500$ stickers given away. $2{,}400 - 1{,}500 = 900$ stickers are left.', 'checked', '{"lint":[],"solve":{"answer":"900","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 x 12 = 1,500 given away; 2,400 - 1,500 = 900 left.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
