INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('495e11c7-f69d-48a1-8678-38bd45d8e3a3', 'NC26.5.ANR.3', 3, 'numeric', 'Interpret a remainder in context', 'Each van holds 7 people and costs 15 dollars to rent. How many dollars does it cost to rent enough vans for $1{,}000$ people?', '[]', '2145', '(142+1)*15', '$1{,}000 \div 7 = 142$ with remainder 6, so 143 vans are needed. $143 \times 15 = 1{,}430 + 715 = 2{,}145$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2145","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 7 = 142 R 6 (7 x 142 = 994), so 143 vans needed. 143 x 15 = 2,145 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b793932e-c280-4cd4-b539-8b03849ba9bb', 'NC26.5.ANR.3', 3, 'numeric', 'Interpret a remainder in context', 'A factory packs bolts 9 to a box. It has $3{,}500$ bolts. After filling as many boxes as it can, how many more bolts would it need to fill one more box?', '[]', '1', '9-(3500-9*388)', '$9 \times 388 = 3{,}492$, so $3{,}500 - 3{,}492 = 8$ bolts are left over. One more box needs 9 bolts, so $9 - 8 = 1$ more bolt.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 388 = 3,492; 3,500 - 3,492 = 8 left over. A box needs 9, so 1 more bolt is needed.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3b99123-3433-4272-bad4-080eb8ae3d0b', 'NC26.5.ANR.3', 3, 'choice', 'Interpret a remainder in context', 'A shop has $1{,}205$ pencils and packs them in boxes of 8. Which question has an answer equal to the whole-number quotient of $1{,}205 \div 8$ plus 1?', '["How many full boxes can be packed?","How many pencils are left over after the full boxes are packed?","How many boxes are needed to hold all of the pencils?","If the pencils are shared equally among 8 boxes, how many go in each box?"]', 'How many boxes are needed to hold all of the pencils?', NULL, '$1{,}205 \div 8 = 150$ with remainder 5. Boxes needed to hold all of them: the 5 extra pencils need one more box, so $150 + 1 = 151$. The other questions are answered by 150, 5 and 150.', 'checked', '{"lint":[],"solve":{"answer":"How many boxes are needed to hold all of the pencils?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,205 / 8 = 150 R 5. Quotient + 1 = 151 = boxes needed to hold all pencils (150 full boxes plus one for the 5 left). Full boxes = 150; per box when shared among 8 boxes = 150 (R5); left over = 5.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ec2a2ef-daa7-44cf-82ad-5ba66479aebd', 'NC26.5.ANR.3', 3, 'numeric', 'Interpret a remainder in context', 'A baker has $1{,}000$ cookies. She fills as many boxes of 6 cookies as she can and sells each full box for 4 dollars. Leftover cookies are given away. How many dollars does she get?', '[]', '664', '166*4', '$1{,}000 \div 6 = 166$ with remainder 4, so she fills 166 boxes. $166 \times 4 = 664$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"664","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 6 = 166 R 4, so 166 full boxes. 166 x 4 = 664 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
