INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19bd63bf-a9d5-44c4-a66f-5e4b667faf94', 'NC26.5.ANR.3', 3, 'choice', 'Solve a multi-step problem with multiplication and division', 'A school buys 18 boxes of pencils with 144 pencils in each box. It keeps 400 pencils and shares the rest equally among 8 classes. How many pencils does each class get?', '["324","274","2,192","2,592"]', '274', '(18*144-400)/8', '$18 \times 144 = 2{,}592$ pencils. Take away the 400 kept: $2{,}592 - 400 = 2{,}192$. Share among 8 classes: $2{,}192 \div 8 = 274$ pencils each.', 'checked', '{"lint":[],"solve":{"answer":"274","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 x 144 = 2,592; 2,592 - 400 = 2,192; 2,192 / 8 = 274.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
