INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5c325a4-e885-471d-9f8f-9da0178c4625', 'NC26.5.ANR.3', 3, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A cyclist rides 125 kilometers each week for 16 weeks. A second cyclist rides the same total distance in 8 weeks, riding the same distance each week. How many kilometers does the second cyclist ride each week?', '[]', '250', '125*16/8', 'First cyclist: $125 \times 16 = 2{,}000$ kilometers. Second cyclist: $2{,}000 \div 8 = 250$ kilometers each week.', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 x 16 = 2,000 km; 2,000 / 8 = 250 km each week.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
