INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8376bfc2-a0f0-4fed-939e-36b0780a2d4d', 'NC26.5.ANR.3', 3, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A school sells 238 adult tickets for 12 dollars each and 175 student tickets for 8 dollars each. How many more dollars does it get from adult tickets than from student tickets?', '[]', '1456', '238*12-175*8', 'Adult tickets: $238 \times 12 = 2{,}856$ dollars. Student tickets: $175 \times 8 = 1{,}400$ dollars. The difference is $2{,}856 - 1{,}400 = 1{,}456$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1456","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"238 x 12 = 2,856; 175 x 8 = 1,400; 2,856 - 1,400 = 1,456.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
