INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42db74cd-c99f-4e03-bbec-9c5f6f247626', 'NC26.5.ANR.3', 3, 'choice', 'Estimate a product', 'Without finding any exact products, which is greater than $20{,}000$?', '["$312 \\times 48$","$523 \\times 41$","$189 \\times 62$","$401 \\times 39$"]', '$523 \times 41$', NULL, '$523 \times 41$ is more than $500 \times 40 = 20{,}000$. The others are less than $20{,}000$: $312 \times 48$ is less than $320 \times 50 = 16{,}000$, $189 \times 62$ is less than $200 \times 70 = 14{,}000$, and $401 \times 39$ is less than $410 \times 40 = 16{,}400$.', 'checked', '{"lint":[],"solve":{"answer":"$523 \\times 41$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"401 x 39 is about 400 x 40 = 16,000; 189 x 62 about 200 x 60 = 12,000; 312 x 48 about 300 x 50 = 15,000; 523 x 41 > 500 x 40 = 20,000 since both factors exceed 500 and 40. Only 523 x 41 (exact 21,443) is above 20,000; others are 15,639, 11,718, 14,976.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cbde47c-cf4d-44f8-b28c-5f699347ef38', 'NC26.5.ANR.3', 3, 'choice', 'Estimate a quotient', 'Without dividing exactly, which quotient is greater than $1{,}000$?', '["$5{,}400 \\div 6$","$8{,}100 \\div 7$","$7{,}360 \\div 8$","$4{,}800 \\div 5$"]', '$8{,}100 \div 7$', NULL, '$8{,}100 \div 7$ is more than $7{,}000 \div 7 = 1{,}000$. The others are less than $1{,}000$: $5{,}400 \div 6 = 900$, $7{,}360 \div 8 = 920$ and $4{,}800 \div 5 = 960$.', 'checked', '{"lint":[],"solve":{"answer":"$8{,}100 \\div 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,800 / 5 = 960; 5,400 / 6 = 900; 7,360 / 8 = 920 (all under 1,000 since dividend < 1,000 x divisor). 8,100 / 7: 7 x 1,000 = 7,000 < 8,100, so quotient > 1,000 (about 1,157).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bbf078b-c480-4bf3-985e-6a5adb4ef40e', 'NC26.5.ANR.3', 3, 'choice', 'Check and connect multiplication and division', 'Which equation correctly shows $3{,}000 \div 7$ with a remainder?', '["$3{,}000 = 7 \\times 429 + 4$","$3{,}000 = 7 \\times 428 + 40$","$3{,}000 = 7 \\times 482 + 4$","$3{,}000 = 7 \\times 428 + 4$"]', '$3{,}000 = 7 \times 428 + 4$', NULL, '$7 \times 428 = 2{,}996$ and $2{,}996 + 4 = 3{,}000$. The others do not equal $3{,}000$: $7 \times 429 + 4 = 3{,}007$, $7 \times 428 + 40 = 3{,}036$ and $7 \times 482 + 4 = 3{,}378$.', 'checked', '{"lint":[],"solve":{"answer":"$3{,}000 = 7 \\times 428 + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 428 = 2,996; 3,000 - 2,996 = 4, and 4 < 7. So 3,000 = 7 x 428 + 4. (7 x 429 + 4 = 3,007; 7 x 482 + 4 = 3,378; 7 x 428 + 40 = 3,036.)","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b40702d-d4cc-4ed3-8709-fb6cdd73a85c', 'NC26.5.ANR.3', 3, 'numeric', 'Check and connect multiplication and division', 'Ravi divides $4{,}000$ by a one-digit number. The quotient is 444 and the remainder is 4. What number did he divide by?', '[]', '9', '(4000-4)/444', 'The part of $4{,}000$ that was shared out is $4{,}000 - 4 = 3{,}996$. $3{,}996 \div 444 = 9$. Check: $9 \times 444 + 4 = 4{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,000 - 4 = 3,996 = divisor x 444; 3,996 / 444 = 9. Check 9 x 444 + 4 = 4,000 and 4 < 9.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
