VALUES ('fd7d87e4-f9ab-458f-8277-12e9b1c44581', 'NC26.5.ANR.4', 3, 'numeric', 'Solve a two-step problem with decimals', 'A bakery starts with 12 kilograms of flour. Each loaf uses 1.25 kilograms. It bakes 4 loaves in the morning and 3 loaves in the afternoon. How many kilograms of flour are left?', '[]', '3.25', '12-(4+3)*1.25', 'Loaves: $4 + 3 = 7$. Flour used: $7 \times 1.25 = 8.75$ kilograms. Left: $12 - 8.75 = 3.25$ kilograms.', 'checked', '{"lint":[],"solve":{"answer":"3.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 3 = 7 loaves; 4 x 1.25 = 5 and 3 x 1.25 = 3.75, so 8.75 kg used; 12 - 8.75 = 3.25 kg left.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('756f5ff6-1c55-4d32-9543-980798adaa94', 'NC26.5.ANR.4', 3, 'numeric', 'Solve a two-step problem with decimals', 'Isaac needs to fill a 5-liter jug. He pours in a 0.75-liter cup 4 times and a 0.5-liter cup 3 times. How many more liters does he need?', '[]', '0.5', '5-(4*0.75+3*0.5)', 'The big cup adds $4 \times 0.75 = 3$ liters and the small cup adds $3 \times 0.5 = 1.5$ liters, so $3 + 1.5 = 4.5$ liters. Still needed: $5 - 4.5 = 0.5$ liter.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 0.75 = 3; 3 x 0.5 = 1.5; 3 + 1.5 = 4.5 L poured; 5 - 4.5 = 0.5 L more.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff4228ca-03c1-4799-9c7b-6b5fbf5a9ef1', 'NC26.5.ANR.4', 3, 'choice', 'Solve a two-step problem with decimals', 'A school buys 4 packs of markers that cost 6.85 dollars each and 3 packs of paper that cost 4.5 dollars each. How many dollars does the school spend in all?', '["27.4","13.5","11.35","40.9"]', '40.9', '4*6.85+3*4.5', 'Markers: $4 \times 6.85 = 27.40$ dollars. Paper: $3 \times 4.5 = 13.50$ dollars. Total: $27.40 + 13.50 = 40.90$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"40.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6.85 = 27.40; 3 x 4.5 = 13.5; 27.4 + 13.5 = 40.9 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7716f02f-c191-4b3c-8ec3-d1be5a08bcae', 'NC26.5.ANR.4', 3, 'choice', 'Estimate with decimals', 'Which sum is closest to 20?', '["$12.1 + 7.95$","$9.8 + 8.9$","$5.5 + 11.9$","$10.4 + 10.9$"]', '$12.1 + 7.95$', NULL, '$9.8 + 8.9 = 18.7$, $12.1 + 7.95 = 20.05$, $5.5 + 11.9 = 17.4$ and $10.4 + 10.9 = 21.3$. The sum $12.1 + 7.95$ is closest to 20.', 'checked', '{"lint":[],"solve":{"answer":"$12.1 + 7.95$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9.8 + 8.9 = 18.7 (1.3 off); 10.4 + 10.9 = 21.3 (1.3 off); 5.5 + 11.9 = 17.4 (2.6 off); 12.1 + 7.95 = 20.05 (0.05 off). Closest: 12.1 + 7.95.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
