VALUES ('3dbe25f8-ff5e-4180-a9c7-c45f4d1ae914', 'NC26.5.ANR.4', 3, 'numeric', 'Estimate with decimals', 'A rope is 11.9 meters long and is cut into 4 equal pieces. Round 11.9 to the nearest whole number to estimate how many meters long each piece is.', '[]', '3', '12/4', '11.9 rounds to 12. $12 \div 4 = 3$ meters. (The exact length is 2.975 meters.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.9 -> 12; 12 / 4 = 3 m.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
