VALUES ('5bca4f97-75e0-4362-9dfe-9d800bd34b31', 'NC26.5.ANR.4', 3, 'choice', 'Estimate with decimals', 'Which is the most reasonable answer for $4 \times 3.08 + 2.95$?', '["6","12","15","150"]', '15', '4*3+3', '$4 \times 3.08$ is about $4 \times 3 = 12$, and 2.95 is about 3. $12 + 3 = 15$. (The exact value is 15.27.)', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3.08 is about 4 x 3 = 12; 2.95 is about 3; 12 + 3 = 15 (exact 12.32 + 2.95 = 15.27).","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
