INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eeade8b1-4821-48a6-a79d-cf5320c24f82', 'NC26.5.ANR.4', 3, 'choice', 'Reason about decimal operations', 'Which expression is equal to $4 \times 6.25$?', '["$4 \\times 6 + 0.25$","$4 \\times 6 \\times 0.25$","$4 \\times 6 + 4 \\times 0.25$","$6 + 4 \\times 0.25$"]', '$4 \times 6 + 4 \times 0.25$', NULL, '6.25 is $6 + 0.25$, so $4 \times 6.25 = 4 \times 6 + 4 \times 0.25 = 24 + 1 = 25$. The others equal 24.25, 6 and 7.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 6 + 4 \\times 0.25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6.25 = 4 x (6 + 0.25) = 4 x 6 + 4 x 0.25 = 24 + 1 = 25. Others: 24.25, 7, 6.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
