INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba2e5d22-a15a-46d1-b791-3b915d3fe3de', 'NC26.5.ANR.4', 3, 'numeric', 'Solve a two-step problem with decimals', 'An empty jug holds 5 liters. Sam pours in 3 cups that hold 0.45 liters each, and then Lena pours in 1.6 liters. How many more liters will fit in the jug?', '[]', '2.05', '5-3*0.45-1.6', 'Sam pours $3 \times 0.45 = 1.35$ liters. Together with Lena the jug holds $1.35 + 1.6 = 2.95$ liters. The jug has room for $5 - 2.95 = 2.05$ more liters.', 'checked', '{"lint":[],"solve":{"answer":"2.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x0.45=1.35; 1.35+1.6=2.95; 5-2.95=2.05.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
