VALUES ('4572d1ff-6dbc-442a-a2de-c06db54e8c45', 'NC26.5.ANR.5', 1, 'numeric', 'Add fractions with unlike denominators', 'Find $\frac{1}{2} + \frac{1}{4}$.', '[]', '3/4', '1/2+1/4', 'Rename $\frac{1}{2}$ as $\frac{2}{4}$. Then $\frac{2}{4} + \frac{1}{4} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 2/4; 2/4 + 1/4 = 3/4.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
