INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b397c53-3795-4343-a95e-47d67da88c66', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a fraction by a fraction', '$\frac{2}{3}$ of a garden is planted with vegetables. $\frac{3}{4}$ of the vegetable part is tomatoes. What fraction of the whole garden is tomatoes?', '["$\\frac{17}{12}$","$\\frac{1}{2}$","$\\frac{5}{7}$","$\\frac{6}{7}$"]', '$\frac{1}{2}$', NULL, 'Tomatoes are $\frac{3}{4}$ of $\frac{2}{3}$: $\frac{2}{3} \times \frac{3}{4}$ = $\frac{6}{12}$ = $\frac{1}{2}$ of the garden.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 of 2/3 = 3/4 × 2/3 = 6/12 = 1/2 of the garden.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
