INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('541f4edb-fe58-4460-88b3-63b46141958c', 'NC26.5.ANR.5', 2, 'numeric', 'Divide a whole number by a unit fraction', 'A water jug holds 6 liters. A cup holds $\frac{1}{5}$ liter. How many cups can be filled from the jug?', '[]', '30', '6/(1/5)', 'Each liter fills 5 cups, so 6 liters fill $6 \times 5 = 30$ cups.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 ÷ 1/5 = 6 × 5 = 30 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
