INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee88e62e-7bef-4db6-a2ea-2ed4f2773886', 'NC26.5.ANR.5', 2, 'choice', 'Divide a whole number by a unit fraction', 'Calculate $9 \div \frac{1}{4}$.', '["$2\\frac{1}{4}$","36","13","5"]', '36', '9/(1/4)', 'Each whole has 4 fourths, so 9 wholes have $9 \times 4 = 36$ fourths. The choice $2\frac{1}{4}$ is $9 \times \frac{1}{4}$, which is a different problem.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 ÷ 1/4 = 9 × 4 = 36.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
