INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24e71589-411c-40cf-b355-e8240d0235a5', 'NC26.5.ANR.5', 3, 'choice', 'Scaling: how a product compares with the number multiplied', 'Which fraction can replace n so that $\frac{3}{4}$ $\times$ n is greater than $\frac{3}{4}$?', '["$\\frac{7}{8}$","$\\frac{9}{8}$","$\\frac{4}{4}$","$\\frac{1}{2}$"]', '$\frac{9}{8}$', NULL, '$\frac{3}{4}$ multiplied by n is greater than $\frac{3}{4}$ only when n is greater than 1. $\frac{9}{8}$ is greater than 1. $\frac{4}{4}$ equals 1 (no change), and $\frac{7}{8}$ and $\frac{1}{2}$ are less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 × n > 3/4 needs n > 1. 4/4 = 1 (equal), 9/8 > 1 (works), 7/8 < 1, 1/2 < 1.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c14e2f6-ed47-4fcd-93e9-625f2dc0b23b', 'NC26.5.ANR.5', 3, 'numeric', 'Scaling: how a product compares with the number multiplied', 'Emma multiplies 15 by $\frac{4}{3}$. Jake multiplies 15 by $\frac{2}{3}$. How much greater is Emma''s product than Jake''s?', '[]', '10', '15*4/3-15*2/3', 'Emma: $\frac{4}{3}$ of 15 is $4 \times 5 = 20$. Jake: $\frac{2}{3}$ of 15 is $2 \times 5 = 10$. The difference is $20 - 10 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Emma: 15 × 4/3 = 20. Jake: 15 × 2/3 = 10. Difference 20 - 10 = 10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b4009ba-00c3-43de-b435-6e9eece486ea', 'NC26.5.ANR.5', 3, 'numeric', 'Divide a unit fraction by a whole number', 'A bucket holds $\frac{1}{4}$ gallon of paint. The paint is poured equally into 6 cups. How many gallons of paint are in each cup?', '[]', '1/24', '1/4/6', '$\frac{1}{4}$ $\div 6 = \frac{1}{24}$ gallon in each cup.', 'checked', '{"lint":[],"solve":{"answer":"1/24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 ÷ 6 = 1/24 gallon.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
