INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee673aa5-ca50-42ed-87e9-263e7379ffbe', 'NC26.5.ANR.5', 3, 'numeric', 'Divide a whole number by a unit fraction', 'A baker has 7 pounds of dough. Each roll uses $\frac{1}{8}$ pound of dough. How many rolls can the baker make?', '[]', '56', '7/(1/8)', 'Each pound makes 8 rolls, so 7 pounds make $7 \times 8 = 56$ rolls.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 ÷ 1/8 = 7 × 8 = 56 rolls.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
