INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e676387-b3d8-4c52-9ab9-4d5e904a24b2', 'NC26.5.ANR.5', 3, 'choice', 'Divide a whole number by a unit fraction', 'Which statement about $6 \div \frac{1}{2}$ is true?', '["The answer is 12, because each whole has 2 halves","The answer is 3, because dividing always makes a number smaller","The answer is 3, because half of 6 is 3","The answer is $\\frac{1}{12}$, because 6 is split into 2 parts"]', 'The answer is 12, because each whole has 2 halves', NULL, 'Each whole contains 2 halves, so 6 wholes contain $6 \times 2 = 12$ halves. Dividing by a fraction less than 1 makes the answer larger, not smaller.', 'checked', '{"lint":[],"solve":{"answer":"The answer is 12, because each whole has 2 halves","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 ÷ 1/2 asks how many halves are in 6: 6 × 2 = 12.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03602c9-757a-4fac-b962-fe34580d5e5c', 'NC26.5.ANR.6', 1, 'numeric', 'Extend an adding pattern', 'A pattern starts at 0 and adds 3 each time: 0, 3, 6, 9, ... What is the 6th number in the pattern?', '[]', '15', '0+5*3', 'Continue the pattern: 0, 3, 6, 9, 12, 15. The 6th number is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0, 3, 6, 9, 12, 15: the 6th number is 15.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
