VALUES ('5125651e-a809-4b72-a145-7e1cd6575673', 'NC26.5.ANR.6', 1, 'choice', 'Find the rule of a pattern from its terms', 'What is the rule for the pattern 4, 9, 14, 19, ...?', '["Add 4","Multiply by 2","Add 5","Add 9"]', 'Add 5', NULL, 'Each number is 5 more than the one before: $9 - 4 = 5$, $14 - 9 = 5$, $19 - 14 = 5$. The rule is "add 5".', 'checked', '{"lint":[],"solve":{"answer":"Add 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 4 = 5, 14 - 9 = 5, 19 - 14 = 5. Rule: add 5.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
