INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f350290-8d72-483b-b4a3-762b63dcfb93', 'NC26.5.ANR.6', 1, 'numeric', 'Patterns with two quantities in real situations', 'A tricycle has 3 wheels. So 1 tricycle has 3 wheels, 2 tricycles have 6 wheels, and 3 tricycles have 9 wheels. How many wheels do 7 tricycles have?', '[]', '21', '7*3', 'Each tricycle adds 3 wheels, so 7 tricycles have $7 \times 3 = 21$ wheels.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wheels = 3 x tricycles. 7 x 3 = 21.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4800311-46bb-4ccf-90d7-321c27186c3d', 'NC26.5.ANR.6', 1, 'choice', 'Patterns with two quantities in real situations', 'A pack holds 6 pencils. With 1, 2, 3, 4 packs there are 6, 12, 18, 24 pencils. Which statement describes the pencils and the packs?', '["The number of pencils is 6 times the number of packs","The number of pencils is 6 more than the number of packs","The number of packs is 6 times the number of pencils","The number of pencils is the same as the number of packs"]', 'The number of pencils is 6 times the number of packs', NULL, 'Match them up: $1 \to 6$, $2 \to 12$, $3 \to 18$, $4 \to 24$. The pencils are always 6 times the packs. "6 more" does not work: 2 packs would have 8 pencils.', 'checked', '{"lint":[],"solve":{"answer":"The number of pencils is 6 times the number of packs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 6 x 1, 12 = 6 x 2, 18 = 6 x 3, 24 = 6 x 4. Pencils = 6 times packs.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fa9624d-e72c-43b3-8420-889ff0d641c5', 'NC26.5.ANR.6', 1, 'numeric', 'Patterns with two quantities in real situations', 'Leo earns 9 dollars for 1 hour of work, 18 dollars for 2 hours, and 27 dollars for 3 hours. At this rate, how many dollars does he earn for 8 hours?', '[]', '72', '8*9', 'He earns 9 dollars each hour, so 8 hours earn $8 \times 9 = 72$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dollars = 9 x hours. 9 x 8 = 72.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7af413b7-3b7e-4c89-adeb-45327e0b679e', 'NC26.5.ANR.6', 1, 'numeric', 'Compare two patterns', 'Pattern A starts at 10 and adds 2 each time. Pattern B starts at 4 and adds 2 each time. How much greater is the 3rd number in Pattern A than the 3rd number in Pattern B?', '[]', '6', '(10+2*2)-(4+2*2)', 'Pattern A is 10, 12, 14, and Pattern B is 4, 6, 8. The 3rd numbers are 14 and 8, and $14 - 8 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 10, 12, 14. B: 4, 6, 8. 14 - 8 = 6.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2af9862c-00e3-4784-831d-c8f5452b09c6', 'NC26.5.ANR.6', 1, 'choice', 'Compare two patterns', 'Pattern A starts at 6 and adds 1 each time. Pattern B starts at 2 and adds 3 each time. Which statement is true about the 5th numbers?', '["The 5th number in A is greater than the 5th number in B","The 5th numbers in A and B are equal","The 5th number in B is equal to the 4th number in A","The 5th number in B is greater than the 5th number in A"]', 'The 5th number in B is greater than the 5th number in A', NULL, 'Pattern A: 6, 7, 8, 9, 10. Pattern B: 2, 5, 8, 11, 14. The 5th numbers are 10 and 14, so B is greater. The 4th number in A is 9, which is not 14.', 'checked', '{"lint":[],"solve":{"answer":"The 5th number in B is greater than the 5th number in A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6, 7, 8, 9, 10. B: 2, 5, 8, 11, 14. 5th: A = 10, B = 14, so B is greater. (B''s 5th 14 is not A''s 4th 9.)","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54ba3c76-58d4-48b7-9808-0588b5946c71', 'NC26.5.ANR.6', 1, 'numeric', 'Compare two patterns', 'Pattern A is 2, 4, 6, 8, 10. Pattern B is 1, 4, 7, 10, 13. Look at the numbers in the same position of each pattern. In which position are the two numbers equal?', '[]', '2', '2', 'Compare position by position: $2$ and $1$, then $4$ and $4$, then $6$ and $7$, then $8$ and $10$, then $10$ and $13$. The numbers are equal only in position 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs: (2,1), (4,4), (6,7), (8,10), (10,13). Equal at position 2.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
