INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dd51e2d-8edf-468d-897d-2d003f2c2665', 'NC26.5.ANR.6', 2, 'choice', 'Find the rule of a pattern from its terms', 'The numbers 7, 19, 31, 43 are the start of an adding pattern. By how much does the pattern grow each time?', '["12","11","13","24"]', '12', '19-7', '$19 - 7 = 12$, $31 - 19 = 12$ and $43 - 31 = 12$. The pattern grows by 12 each time.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19 - 7 = 12, 31 - 19 = 12, 43 - 31 = 12. Grows by 12.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
