INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a67429a1-ba71-4bb6-8897-be58dca10414', 'NC26.5.ANR.6', 3, 'choice', 'Generate an adding pattern from a rule', 'A pattern starts at 1.5 and the rule is "add 0.75". What is the 5th number in the pattern?', '["3.75","5.25","2.25","4.5"]', '4.5', '1.5+4*0.75', 'The pattern is 1.5, 2.25, 3, 3.75, 4.5. Four steps of 0.75 add $4 \times 0.75 = 3$, and $1.5 + 3 = 4.5$. The choice 3.75 is the 4th number.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5, 2.25, 3, 3.75, 4.5. The 5th number is 4.5 (1.5 + 4 x 0.75 = 1.5 + 3).","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
