INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ecd1715-627d-4bbd-bbce-6a8c564158f7', 'NC26.5.ANR.6', 3, 'numeric', 'Generate an adding pattern from a rule', 'A pattern starts with 47 and adds 38 each time. What is the first number in the pattern that is greater than 200?', '[]', '237', '47+5*38', 'The pattern is 47, 85, 123, 161, 199, 237. The number 199 is not greater than 200, so the first number greater than 200 is 237.', 'checked', '{"lint":[],"solve":{"answer":"237","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47, 85, 123, 161, 199, 237. 199 is not greater than 200; 237 is the first above 200.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
