INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b6622b0-9f8d-4cbd-b3ea-6b5cdc23c22b', 'NC26.5.ANR.6', 3, 'numeric', 'Generate a multiplying pattern from a rule', 'A pattern starts at 2 and multiplies by 3 each time. What is the sum of the first four numbers in the pattern?', '[]', '80', '2+6+18+54', 'The first four numbers are 2, 6, 18, 54. Their sum is $2 + 6 + 18 + 54 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 6, 18, 54. Sum = 2 + 6 + 18 + 54 = 80.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
