INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11b04404-3977-4cbd-84de-7ef84c4fd099', 'NC26.5.ANR.6', 3, 'numeric', 'Find a later term of an adding pattern', 'What is the 25th number in the pattern that starts at 3 and adds 4 each time?', '[]', '99', '3+24*4', 'The 25th number takes 24 steps of 4 from the start: $24 \times 4 = 96$, and $3 + 96 = 99$.', 'checked', '{"lint":[],"solve":{"answer":"99","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"nth number = 3 + 4(n - 1). 25th: 3 + 4 x 24 = 3 + 96 = 99.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
