INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('324a67fd-ae50-44b8-be54-ec779891fdcb', 'NC26.5.SGMR.1', 1, 'choice', 'Tell two categories apart', 'Which is true of a parallelogram but NOT true of a trapezoid that has exactly one pair of parallel sides?', '["It has four sides.","It has at least one pair of parallel sides.","It is a quadrilateral.","Both pairs of opposite sides are parallel."]', 'Both pairs of opposite sides are parallel.', NULL, 'Both shapes have four sides, are quadrilaterals and have at least one pair of parallel sides. Only the parallelogram has two pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Both pairs of opposite sides are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both have four sides, are quadrilaterals, and have at least one pair of parallel sides. Only the parallelogram has both pairs parallel.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
