INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eadbf8b3-dbe8-40fc-a047-6b0cfb9196bd', 'NC26.5.SGMR.1', 1, 'numeric', 'Combine clues to identify a shape', 'A mystery shape is both a rectangle and a rhombus. One of its sides is 5 cm long. How long is the side next to it, in centimeters?', '[]', '5', '5', 'A shape that is both a rectangle and a rhombus is a square, because it has four right angles and four equal sides. So the side next to the 5 cm side is also 5 cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangle and rhombus = square: all sides equal, 5 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
