INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e839f217-245a-4d6e-8d66-d4905eada1d6', 'NC26.5.SGMR.1', 1, 'numeric', 'Attributes carry down the hierarchy', 'Every parallelogram has opposite angles that are equal in size. A rectangle is a kind of parallelogram. One angle of a rectangle measures 90 degrees. How many degrees does the angle opposite it (across the shape from it) measure?', '[]', '90', NULL, 'A rectangle is a parallelogram, so its opposite angles are equal. The angle opposite a 90 degree angle is also 90 degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle is a parallelogram, opposite angles equal, so the opposite angle is 90.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
