INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92bb320a-c667-48ed-84b5-f57129cc6b29', 'NC26.5.SGMR.1', 1, 'numeric', 'Attributes carry down the hierarchy', 'A rhombus has one side that is 5 centimeters long. How many of its four sides are 5 centimeters long, counting that side?', '[]', '4', NULL, 'Every rhombus has four sides of equal length. If one side is 5 centimeters, all four sides are 5 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus has four equal sides, so all 4 are 5 cm.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
