INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('935a117f-58e8-442e-b3a0-8533a3ea8239', 'NC26.5.SGMR.1', 2, 'choice', 'Name a quadrilateral from its properties', 'A quadrilateral has two pairs of parallel sides, and its opposite sides are equal in length. It has no right angles, and its sides are not all equal. What is the most specific name for it?', '["Parallelogram","Rectangle","Rhombus","Square"]', 'Parallelogram', NULL, 'Two pairs of parallel sides makes it a parallelogram. It is not a rectangle (no right angles) or a rhombus (sides not all equal), so parallelogram is the most specific name.', 'checked', '{"lint":[],"solve":{"answer":"Parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pairs of parallel sides: parallelogram. No right angles: not rectangle/square. Sides not all equal: not rhombus. Most specific: parallelogram.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
