INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ff01ed9-8c1e-498a-87be-33f899bae6f2', 'NC26.5.SGMR.1', 2, 'choice', 'Name a quadrilateral from its properties', 'A game card says: "I have 4 sides. Both pairs of my opposite sides are parallel. All 4 of my sides are equal. I have no right angles." What is the most specific name of the shape on the card?', '["Square","Rectangle","Rhombus","Trapezoid"]', 'Rhombus', NULL, 'Four equal sides and two pairs of parallel sides make a rhombus. With no right angles it cannot be a square.', 'checked', '{"lint":[],"solve":{"answer":"Rhombus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pairs of parallel sides, 4 equal sides, no right angles: rhombus, not square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
