INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('535ccc0d-1db3-4ee9-a803-9cc57ff0ca20', 'NC26.5.SGMR.1', 2, 'numeric', 'Use attributes to find a measurement', 'A rhombus-shaped tile has a perimeter of 26 cm. How long is each side of the tile, in centimeters?', '[]', '6.5', '26/4', 'A rhombus has four equal sides, so each side is 26 divided by 4 = 6.5 cm.', 'checked', '{"lint":[],"solve":{"answer":"6.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Borderline alignment: mostly perimeter arithmetic, though it does require recalling that a rhombus has four equal sides.","work":"A rhombus has 4 equal sides: 26 / 4 = 6.5 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
