INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5038035d-7ab3-4ad7-96f9-c0ced69f88cc', 'NC26.5.SGMR.1', 2, 'numeric', 'Count shapes that have an attribute', 'Six quadrilaterals are described. A: sides 6, 6, 6, 6 cm; four right angles. B: sides 8, 3, 8, 3 cm; four right angles. C: sides 5, 5, 5, 5 cm; no right angles. D: sides 9, 4, 9, 4 cm; no right angles. E: sides 2, 2, 2, 2 cm; four right angles. F: exactly one pair of parallel sides. How many of the six are rectangles?', '[]', '3', NULL, 'A rectangle has four right angles. A, B and E have four right angles, so they are rectangles (A and E are squares). C and D have no right angles, and F has only one pair of parallel sides. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles need 4 right angles: A (square), B, E (square). C, D have no right angles; F is a trapezoid. 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3286bc0a-dc03-4905-acb8-ff06b18f7b79', 'NC26.5.SGMR.1', 2, 'choice', 'Tell two categories apart', 'Two quadrilaterals each have four right angles. Shape A has four equal sides. Shape B has sides of 5 cm, 3 cm, 5 cm and 3 cm. What are the most specific names for Shape A and Shape B?', '["A is a rectangle and B is a square.","A is a square and B is a rectangle.","A is a rhombus and B is a square.","A is a rectangle and B is a rhombus."]', 'A is a square and B is a rectangle.', NULL, 'Four right angles and four equal sides is a square. Four right angles with sides 5, 3, 5, 3 is a rectangle that is not a square.', 'checked', '{"lint":[],"solve":{"answer":"A is a square and B is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 4 right angles and 4 equal sides = square. B: 4 right angles, sides 5, 3, 5, 3 = rectangle (not square).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
