INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41846ef8-51e4-4411-be2f-3a09140b4d51', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that always have an attribute', 'Look at these four shapes: square, rectangle, rhombus, parallelogram. How many of them ALWAYS have four sides of equal length?', '[]', '2', NULL, 'A square and a rhombus always have four equal sides. A rectangle and a parallelogram only have equal opposite sides, so they do not always have four equal sides. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Always four equal sides: square and rhombus. Rectangle and parallelogram not always. Count = 2.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c0d1f37-902e-41c1-8961-e50b2734573a', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'Which of these four-sided shapes could NOT be called a parallelogram?', '["A rectangle with sides of 6 cm and 3 cm","A rhombus with 5 cm sides and no right angles","A square with 4 cm sides","A quadrilateral with exactly one pair of parallel sides"]', 'A quadrilateral with exactly one pair of parallel sides', NULL, 'A parallelogram needs two pairs of parallel sides. Rectangles, rhombuses and squares all have them. A shape with exactly one pair of parallel sides does not.', 'checked', '{"lint":[],"solve":{"answer":"A quadrilateral with exactly one pair of parallel sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles, squares and rhombuses all have two pairs of parallel sides, so all are parallelograms. A quadrilateral with exactly one pair of parallel sides is not.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('757b0b45-e1e3-4981-911a-cd94c9ba47b6', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'Which pair of clues is enough to be sure that a quadrilateral is a square?', '["It has 4 equal sides and 4 right angles","It has 4 equal sides and opposite sides parallel","It has 4 right angles and opposite sides equal","It has opposite sides parallel and opposite sides equal"]', 'It has 4 equal sides and 4 right angles', NULL, 'Four equal sides and four right angles together describe a square. The other pairs also fit shapes that are not squares: a rhombus, a rectangle and a parallelogram.', 'checked', '{"lint":[],"solve":{"answer":"It has 4 equal sides and 4 right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 4 equal sides + parallel = rhombus, maybe not square. B: 4 equal sides and 4 right angles = square. C: any parallelogram. D: rectangle, maybe not square. Answer B.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f9c5264-e4ac-429a-96cd-fdafb701a713', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'A quadrilateral has 4 equal sides. Which extra clue would make it a square?', '["Its opposite sides are parallel","It has 4 right angles","Its opposite sides are equal","It has two pairs of equal sides"]', 'It has 4 right angles', NULL, 'Every shape with four equal sides is a rhombus, and a rhombus already has parallel opposite sides, equal opposite sides and two pairs of equal sides. Only four right angles make it a square.', 'checked', '{"lint":[],"solve":{"answer":"It has 4 right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides = rhombus. Opposite sides parallel/equal and two pairs of equal sides are already true of every rhombus. Adding 4 right angles makes it a square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d07ad38-c9a2-43c4-a0c1-34d0ebea7d50', 'NC26.5.SGMR.1', 3, 'numeric', 'Name a quadrilateral from its properties', 'Five quadrilaterals are described. A has 4 right angles and sides of 5, 5, 5 and 5 cm. B has 4 right angles and sides of 6, 2, 6 and 2 cm. C has sides of 4, 4, 4 and 4 cm and no right angles. D has opposite sides parallel, sides of 7, 3, 7 and 3 cm, and no right angles. E has exactly one pair of parallel sides. How many of A, B, C, D and E are parallelograms?', '[]', '4', NULL, 'A is a square, B is a rectangle, C is a rhombus (four equal sides) and D has two pairs of parallel sides, so all four are parallelograms. E has only one pair of parallel sides. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: square, parallelogram. B: rectangle, parallelogram. C: 4 equal sides = rhombus, parallelogram. D: opposite sides parallel = parallelogram. E: exactly one pair = trapezoid, not. Count 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('891494be-9112-460d-a4d2-ff8e1bd87954', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'In a chart of quadrilaterals, the group of rhombuses and the group of rectangles overlap. Which kind of shape belongs to BOTH groups?', '["Parallelograms","Trapezoids","Quadrilaterals","Squares"]', 'Squares', NULL, 'Only a shape with four equal sides and four right angles is in both groups, and that is a square. Parallelograms and quadrilaterals are bigger groups, and a trapezoid is neither a rectangle nor a rhombus.', 'checked', '{"lint":[],"solve":{"answer":"Squares","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A shape that is both a rhombus (4 equal sides) and a rectangle (4 right angles) is a square. Parallelograms/quadrilaterals are larger groups, not all of which are in both.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3c7254-fff0-408a-b0bf-eb87ccc88cdf', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'Which of these statements is NOT true?', '["Every parallelogram is a rectangle.","Some rectangles are squares.","Some parallelograms are rhombuses.","Some rhombuses are rectangles."]', 'Every parallelogram is a rectangle.', NULL, 'A parallelogram with sides of 7 cm and 4 cm and no right angles is not a rectangle, so "Every parallelogram is a rectangle" is false. The other three are true: squares are rectangles, some parallelograms have four equal sides, and squares are rhombuses that are rectangles.', 'checked', '{"lint":[],"solve":{"answer":"Every parallelogram is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A parallelogram with no right angles is not a rectangle, so A is not true. B (squares), C (rhombuses), D (squares) are true.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a83f978-f414-4455-ba7f-6e73dea323a1', 'NC26.5.SGMR.1', 3, 'numeric', 'Which category fits inside another', 'Think about four kinds of shapes: squares, rectangles that are not squares, rhombuses that are not squares, and parallelograms that are neither rectangles nor rhombuses. How many of these four kinds are rectangles?', '[]', '2', NULL, 'Squares are rectangles, and so are the rectangles that are not squares. Rhombuses that are not squares have no right angles, and the last kind has none either. So 2 of the kinds are rectangles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares: rectangles (yes). Rectangles that are not squares: yes. Rhombuses that are not squares: no right angles, not rectangles. Other parallelograms: not rectangles. Count 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da200113-8493-4c24-947f-e967bda32f54', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'Rhombuses and rectangles are both groups inside the group of parallelograms. Which shape is a parallelogram but is in NEITHER the group of rhombuses nor the group of rectangles?', '["A square with sides of 4 cm","A parallelogram with sides of 8 cm and 5 cm and no right angles","A rectangle with sides of 9 cm and 2 cm","A rhombus with 6 cm sides and no right angles"]', 'A parallelogram with sides of 8 cm and 5 cm and no right angles', NULL, 'The first shape has sides that are not all equal (so it is not a rhombus) and no right angles (so it is not a rectangle). The other three are squares, rectangles or rhombuses.', 'checked', '{"lint":[],"solve":{"answer":"A parallelogram with sides of 8 cm and 5 cm and no right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 by 2 rectangle: rectangle. Rhombus: rhombus. Square: both. 8 by 5 with no right angles: parallelogram, sides not all equal (not rhombus), no right angles (not rectangle).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9006134-2df6-4d3c-addc-cf6ea16b2921', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Tom says: "A square has four equal sides, and a square is a parallelogram, so every parallelogram has four equal sides." Which sentence explains his mistake?', '["A square is not a kind of parallelogram.","A square does not have four equal sides.","No parallelogram has any equal sides.","What is true of a smaller group is not always true of the bigger group around it."]', 'What is true of a smaller group is not always true of the bigger group around it.', NULL, 'Attributes carry down from a bigger group to a smaller group, not up. A parallelogram with sides of 7 cm and 4 cm shows that parallelograms do not all have four equal sides.', 'checked', '{"lint":[],"solve":{"answer":"What is true of a smaller group is not always true of the bigger group around it.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Attributes pass down to subgroups, not up. Squares are a smaller group inside parallelograms, so a square''s four equal sides need not hold for all parallelograms. Option C.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20237fa5-62df-4816-bcac-a7c410f84398', 'NC26.5.SGMR.1', 3, 'numeric', 'Attributes carry down to subcategories', 'A hierarchy chart lists each attribute only once, at the biggest group that has it. Parallelograms have 2 listed attributes: two pairs of parallel sides, and opposite sides equal. Rectangles have 1 more listed attribute: four right angles. Rhombuses have 1 more listed attribute: four equal sides. A square is a kind of rectangle and a kind of rhombus. How many attributes does a square have in all?', '[]', '4', '2+1+1', 'A square gets the 2 attributes of parallelograms, the extra attribute of rectangles and the extra attribute of rhombuses. That is 2 + 1 + 1 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''how many attributes in all'' would be tighter as ''how many of the listed attributes'', since a square has other attributes (4 sides) not in the chart described.","work":"Square inherits parallelogram''s 2 listed attributes, plus rectangle''s 1 (right angles) and rhombus''s 1 (equal sides): 2 + 1 + 1 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('235024df-b315-47f7-bed5-a6d7b09af2e1', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Every rhombus has opposite sides that are equal in length. This is because every rhombus is a kind of ____, and every ____ has opposite sides equal in length. Which word fills both blanks?', '["parallelogram","rectangle","square","trapezoid"]', 'parallelogram', NULL, 'Every rhombus is a parallelogram, and every parallelogram has opposite sides equal, so the attribute carries down to rhombuses. Not every rhombus is a rectangle or a square, and a trapezoid does not have to have opposite sides equal.', 'checked', '{"lint":[],"solve":{"answer":"parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every rhombus is a parallelogram, and every parallelogram has opposite sides equal. Rhombus is not always a rectangle or square; trapezoid is wrong.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('779d450a-806a-4214-85cf-176e7d6eabca', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Which list has only attributes that EVERY rhombus has?', '["Four equal sides; four right angles","Four equal sides; opposite sides parallel","Opposite sides parallel; four right angles","Four right angles; exactly one pair of parallel sides"]', 'Four equal sides; opposite sides parallel', NULL, 'Every rhombus has four equal sides and two pairs of parallel sides. A rhombus does not have to have right angles, and it never has exactly one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Four equal sides; opposite sides parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every rhombus has 4 equal sides and opposite sides parallel. Right angles not required; exactly one pair parallel is false.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d9b0c7f-f69c-4676-bf33-be1c922ab581', 'NC26.5.SGMR.1', 3, 'choice', 'Always, sometimes or never true', 'Which of these claims can be proven false by finding just ONE shape that breaks it?', '["All rhombuses have four right angles.","Some squares are rhombuses.","All squares are rectangles.","Some rectangles are parallelograms."]', 'All rhombuses have four right angles.', NULL, 'A slanted rhombus with no right angles is a shape that breaks the first claim. The other claims are true, so no shape can break them.', 'checked', '{"lint":[],"solve":{"answer":"All rhombuses have four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only a false ''all'' claim is disproved by one counterexample. D is false: a rhombus with no right angles breaks it. A, B, C are true, so nothing breaks them.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87ea561a-bb56-433a-8662-137af51b3272', 'NC26.5.SGMR.1', 3, 'choice', 'Always, sometimes or never true', 'Tess draws a quadrilateral with 4 equal sides. Tess says it must have four right angles. Dev says it cannot have four right angles. Who is right?', '["Tess is right.","Neither: it might or might not have four right angles.","Dev is right.","Both are right."]', 'Neither: it might or might not have four right angles.', NULL, 'A shape with four equal sides is a rhombus. It is a square if it has four right angles, and a slanted rhombus if it does not, so both are possible.', 'checked', '{"lint":[],"solve":{"answer":"Neither: it might or might not have four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides = rhombus; it may be a square (4 right angles) or not. So neither must nor cannot holds.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44675c15-ada2-415a-ba40-5777c3a3760d', 'NC26.5.SGMR.1', 3, 'numeric', 'Always, sometimes or never true', 'Read six sentences. (1) A rhombus has opposite sides parallel. (2) A rhombus has 4 right angles. (3) A rectangle has 4 equal sides. (4) A parallelogram has opposite sides equal. (5) A square has 4 equal sides. (6) A rectangle has 4 right angles. How many of the sentences are true for EVERY shape of that kind?', '[]', '4', NULL, 'Sentences 1, 4, 5 and 6 are always true. Sentence 2 is false for a slanted rhombus, and sentence 3 is false for a 5 by 3 rectangle. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) true. (2) false. (3) false. (4) true. (5) true. (6) true. Count 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64fc1cd0-9e1e-4679-8f53-8ce6200f2e9d', 'NC26.5.SGMR.1', 3, 'numeric', 'Always, sometimes or never true', 'Maria draws every rectangle whose sides are whole numbers of centimeters and whose perimeter is 16 cm. A 1 cm by 7 cm rectangle counts, and a 7 cm by 1 cm rectangle is the same rectangle. How many of her rectangles are NOT squares?', '[]', '3', NULL, 'The side pairs that add to 8 are 1 and 7, 2 and 6, 3 and 5, and 4 and 4. That is 4 rectangles. Only the 4 by 4 rectangle is a square, so 3 are not squares.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 16: length + width = 8. Whole-number pairs: 1x7, 2x6, 3x5, 4x4. Squares: 4x4. Not squares: 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff0be521-92e5-4235-b113-a9ad45e51ebe', 'NC26.5.SGMR.1', 3, 'numeric', 'Use attributes to find a measurement', 'A quadrilateral is both a rectangle and a rhombus. Its perimeter is 52 cm. How long is each side, in centimeters?', '[]', '13', '52/4', 'A shape that is both a rectangle and a rhombus has four right angles and four equal sides, so it is a square. Each side is 52 divided by 4 = 13 cm.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangle and rhombus = square, 4 equal sides: 52 / 4 = 13 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0d1c35b-310b-4269-822d-43634aba223d', 'NC26.5.SGMR.1', 3, 'numeric', 'Use attributes to find a measurement', 'A parallelogram has a perimeter of 64 cm. One pair of opposite sides is 3 times as long as the other pair. How long is each of the longer sides, in centimeters?', '[]', '24', '64/8*3', 'If a shorter side is s, a longer side is 3s, and the perimeter is 2 x (s + 3s) = 8s. So 8s = 64 and s = 8. A longer side is 3 x 8 = 24 cm.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides equal: short + long = 32, long = 3 x short, so 4 x short = 32, short = 8, long = 24 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3afccef1-d5d6-425e-9860-2f0f29dada3b', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'A box holds 12 cutouts: 3 squares, 2 rectangles that are not squares, 4 rhombuses that are not squares, and 3 parallelograms that are neither rectangles nor rhombuses. How many of the cutouts are parallelograms that are NOT rectangles?', '[]', '7', '4+3', 'Every cutout is a parallelogram. The squares and the other rectangles (3 + 2 = 5) are rectangles. The rest are not: 4 rhombuses and 3 other parallelograms, which is 4 + 3 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelograms that are not rectangles: rhombuses that are not squares (4) + other parallelograms (3) = 7. Squares and rectangles are rectangles.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6015cd71-a07f-49be-9d10-66c95640f9f7', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'Dara draws six quadrilaterals: a square, a rectangle with sides of 9 cm and 5 cm, a rhombus with 7 cm sides and no right angles, a parallelogram with sides of 8 cm and 3 cm and no right angles, a rectangle with sides of 6 cm and 6 cm, and a trapezoid with exactly one pair of parallel sides. How many of the six shapes are squares?', '[]', '2', NULL, 'A square has four equal sides and four right angles. The first shape is a square, and the rectangle with sides of 6 cm and 6 cm also has four equal sides and four right angles. The other four are not squares. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares: the square, and the 6 by 6 rectangle (4 right angles, 4 equal sides). The 9 by 5 rectangle, rhombus with no right angles, parallelogram and trapezoid are not. 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcae5b68-5df3-448c-b6c0-1b9493964c0b', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'A mosaic has 20 tiles: 5 squares, 7 rectangles that are not squares, 3 rhombuses that are not squares, and the rest are parallelograms that are neither rectangles nor rhombuses. How many tiles do NOT have four equal sides?', '[]', '12', '7+(20-5-7-3)', 'The rest are 20 - 5 - 7 - 3 = 5 tiles. Tiles without four equal sides are the 7 rectangles that are not squares and those 5 parallelograms. That is 7 + 5 = 12 tiles.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other parallelograms: 20 - 5 - 7 - 3 = 5. Four equal sides: squares 5 + rhombuses 3 = 8. Not: 20 - 8 = 12 (7 rectangles + 5 parallelograms).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
