VALUES ('720cfd42-c462-496b-9757-ce40149fdcbe', 'NC26.5.SGMR.2', 1, 'choice', 'Ordered pairs from two number patterns', 'Which ordered pair comes next in the list $(0, 0)$, $(1, 3)$, $(2, 6)$, $(3, 9)$?', '["$(4, 10)$","$(4, 9)$","$(12, 4)$","$(4, 12)$"]', '$(4, 12)$', NULL, 'The x-coordinates go up by 1 and the y-coordinates go up by 3. The next pair is $(4, 12)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x +1, y +3: next (4, 12).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
