INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec5e9a16-d33c-46e7-af42-391f93c60161', 'NC26.5.SGMR.2', 1, 'choice', 'Ordered pairs from a real situation', 'In the point $(7, 21)$, x is the number of bags and y is the number of apples. Each bag holds 3 apples. What does the 21 tell you?', '["There are 21 bags.","There are 21 apples in all.","There are 21 apples in each bag.","There are 21 more apples than bags."]', 'There are 21 apples in all.', NULL, 'The y-coordinate is the number of apples. 7 bags of 3 apples is 7 x 3 = 21 apples in all.', 'checked', '{"lint":[],"solve":{"answer":"There are 21 apples in all.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y is the number of apples: 7 bags x 3 = 21 apples in all.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
