INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('992cab59-ff42-477a-9609-f735dc6efe74', 'NC26.5.SGMR.2', 2, 'numeric', 'Plot a point by moving from the origin', 'A game piece starts at $(1, 1)$. Each move takes it 2 units right and 3 units up. After 4 moves, what is the y-coordinate of the piece?', '[]', '13', '1+4*3', 'Each move adds 3 to the y-coordinate. After 4 moves it has gone up 4 x 3 = 12 units, so the y-coordinate is 1 + 12 = 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y starts at 1 and gains 3 per move: 1 + 4 x 3 = 13. (Position (9, 13).)","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
