INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab486ac9-5d52-417b-a01c-9f666a53473a', 'NC26.5.SGMR.2', 2, 'numeric', 'Points on an axis or on the same line', 'A horizontal line passes through the points $(3, 8)$ and $(11, y)$. What is the value of y?', '[]', '8', '8', 'Every point on a horizontal line has the same y-coordinate. The first point has y-coordinate 8, so y = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points on a horizontal line share their y-coordinate, so y = 8.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
