INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69ddfdcc-2f76-44d7-89b9-06ee7f0e44f2', 'NC26.5.SGMR.2', 2, 'choice', 'Points on an axis or on the same line', 'Which point is on the same vertical line as $(6, 1)$?', '["$(6, 9)$","$(9, 6)$","$(1, 6)$","$(7, 1)$"]', '$(6, 9)$', NULL, 'Points on one vertical line have the same x-coordinate. The x-coordinate of $(6, 1)$ is 6, and $(6, 9)$ also has x-coordinate 6.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same vertical line means x = 6. Only (6, 9).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
