INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b804fb15-e54e-4679-a16c-62d106ca4ba1', 'NC26.5.SGMR.2', 2, 'choice', 'Area and perimeter of rectangles on the plane', 'A rectangle has corners at $(2, 2)$, $(9, 2)$, $(9, 5)$ and $(2, 5)$. Which pair of numbers gives its length and width, in units?', '["7 and 3","9 and 5","7 and 5","11 and 7"]', '7 and 3', NULL, 'The length is 9 - 2 = 7 units and the width is 5 - 2 = 3 units.', 'checked', '{"lint":[],"solve":{"answer":"7 and 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 9 - 2 = 7, width 5 - 2 = 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
