INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('307aaa33-dab0-4c01-8b58-e0f421f4d604', 'NC26.5.SGMR.2', 2, 'choice', 'Area and perimeter of rectangles on the plane', 'Which rectangle has a perimeter of 14 units?', '["Corners $(0, 0)$, $(4, 0)$, $(4, 4)$, $(0, 4)$","Corners $(0, 0)$, $(5, 0)$, $(5, 2)$, $(0, 2)$","Corners $(0, 0)$, $(6, 0)$, $(6, 3)$, $(0, 3)$","Corners $(0, 0)$, $(7, 0)$, $(7, 1)$, $(0, 1)$"]', 'Corners $(0, 0)$, $(5, 0)$, $(5, 2)$, $(0, 2)$', NULL, 'The first rectangle is 5 by 2, so its perimeter is 2 x (5 + 2) = 14. The others are 4 by 4 (16), 6 by 3 (18) and 7 by 1 (16).', 'checked', '{"lint":[],"solve":{"answer":"Corners $(0, 0)$, $(5, 0)$, $(5, 2)$, $(0, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 6x3 -> 18; 7x1 -> 16; 4x4 -> 16; 5x2 -> 14. The last one.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
