INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173e03d4-7715-472a-8543-d8de3d1f0af7', 'NC26.5.SGMR.2', 2, 'numeric', 'Find a missing corner of a shape', 'Three corners of a rectangle are $(2, 1)$, $(7, 1)$ and $(2, 6)$. What is the sum of the coordinates of the fourth corner?', '[]', '13', '7+6', 'The fourth corner is level with $(2, 6)$ and above $(7, 1)$, so it is $(7, 6)$. The sum of its coordinates is 7 + 6 = 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right angle at (2,1) (sides along x and y). Fourth corner (7, 6). 7 + 6 = 13. No other right angle among the three points, so it is unique.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
