INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3eb4a7f-72d3-4210-accb-c792eb3efa6b', 'NC26.5.SGMR.2', 2, 'choice', 'Move a point and measure a path', 'A game piece moves from $(3, 3)$ to $(3, 10)$. Which describes the move?', '["7 units right","13 units up","7 units up and 7 units right","7 units up"]', '7 units up', NULL, 'The x-coordinate stays 3, so the piece did not move sideways. The y-coordinate went from 3 to 10, which is 7 units up.', 'checked', '{"lint":[],"solve":{"answer":"7 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x unchanged, y from 3 to 10: 7 units up.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
