INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95ad7361-8161-4de4-9c14-92037e602a02', 'NC26.5.SGMR.2', 2, 'choice', 'Move a point and measure a path', 'Pat moves a point from $(5, 9)$ to $(8, 4)$. Which describes the move?', '["3 units right and 5 units up","3 units right and 5 units down","5 units right and 3 units down","3 units left and 5 units down"]', '3 units right and 5 units down', NULL, 'The x-coordinate went from 5 to 8, which is 3 units right. The y-coordinate went from 9 to 4, which is 5 units down.', 'checked', '{"lint":[],"solve":{"answer":"3 units right and 5 units down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x 5 -> 8: right 3. y 9 -> 4: down 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
