INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6de252a2-065c-4ac6-8081-5b7931402d2b', 'NC26.5.SGMR.2', 3, 'numeric', 'Distance along a path on the coordinate plane', 'On a coordinate plane, a bug crawls in a straight line from $(2, 3)$ to $(7, 3)$ and then in a straight line to $(7, 9)$. How many units does it crawl in all?', '[]', '11', '(7-2)+(9-3)', 'First part: the y-coordinate stays 3, so the distance is $7 - 2 = 5$ units. Second part: the x-coordinate stays 7, so the distance is $9 - 3 = 6$ units. Total: $5 + 6 = 11$ units.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3) to (7,3): 5 units; (7,3) to (7,9): 6 units. Total 11.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71ba71db-a373-4f61-857a-7cf67dd50847', 'NC26.5.SGMR.2', 3, 'choice', 'Ordered pairs made from two patterns', 'Pattern 1 starts at 0 and adds 2. Pattern 2 starts at 0 and adds 6. Matching numbers form ordered pairs (Pattern 1 number, Pattern 2 number), such as $(0, 0)$ and $(2, 6)$. Which ordered pair is also one of these pairs?', '["$(12, 4)$","$(4, 8)$","$(6, 12)$","$(4, 12)$"]', '$(4, 12)$', NULL, 'Pattern 1: 0, 2, 4, 6. Pattern 2: 0, 6, 12, 18. The third numbers make the pair $(4, 12)$. The pair $(6, 12)$ is wrong because the pair for 6 is $(6, 18)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs are (2k, 6k): (0,0), (2,6), (4,12), (6,18)... (4,12) is one; (4,8), (12,4), (6,12) are not.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f17789d5-523b-41ca-a3fc-b3b81a0f60a1', 'NC26.5.SGMR.2', 3, 'choice', 'Find the missing corner of a rectangle', 'Three corners of a rectangle on a coordinate plane are $(2, 2)$, $(8, 2)$ and $(8, 5)$. What are the coordinates of the fourth corner?', '["$(5, 2)$","$(2, 5)$","$(2, 8)$","$(5, 8)$"]', '$(2, 5)$', NULL, 'The fourth corner is above $(2, 2)$ and left of $(8, 5)$. So it has x-coordinate 2 and y-coordinate 5: $(2, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides are horizontal/vertical. Corners use x in {2,8}, y in {2,5}: missing (2, 5).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('815d863b-c444-422d-91c6-45d88eaf9cd4', 'NC26.5.SGMR.2', 3, 'choice', 'Read the coordinates of a point', 'Point P is at $(12, 4)$ and point Q is at $(4, 12)$. Which statement is true?', '["P is farther from the y-axis than Q, and Q is farther from the x-axis than P.","P is farther from both axes than Q is.","P and Q are the same distance from the x-axis.","P and Q are the same point."]', 'P is farther from the y-axis than Q, and Q is farther from the x-axis than P.', NULL, 'P has x-coordinate 12 and Q has 4, so P is farther from the y-axis. Q has y-coordinate 12 and P has 4, so Q is farther from the x-axis. They are different points because the order of the numbers matters.', 'checked', '{"lint":[],"solve":{"answer":"P is farther from the y-axis than Q, and Q is farther from the x-axis than P.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 12 from y-axis, 4 from x-axis. Q: 4 from y-axis, 12 from x-axis. So P is farther from the y-axis and Q farther from the x-axis. Others false.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a470609-8fef-49ae-aca7-4946735793c5', 'NC26.5.SGMR.2', 3, 'numeric', 'Read the coordinates of a point', 'Point R is plotted so that its x-coordinate is 3 more than its y-coordinate, and the two coordinates add up to 15. What is the x-coordinate of R?', '[]', '9', '(15+3)/2', 'If y is the y-coordinate, x = y + 3, so y + y + 3 = 15. Then 2y = 12 and y = 6, so x = 9. Check: 9 is 3 more than 6, and 9 + 6 = 15.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = y + 3 and x + y = 15, so 2y + 3 = 15, y = 6, x = 9. Check: 9 - 6 = 3, 9 + 6 = 15.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('589cfd2f-0ee9-4a0a-842f-a4d7f3196752', 'NC26.5.SGMR.2', 3, 'numeric', 'Plot a point by moving from the origin', 'A marker starts at $(4, 1)$. It moves right 3 units, then up 5 units, then right 2 units, and then down 4 units. What is the sum of the x-coordinate and the y-coordinate of its final position?', '[]', '11', '4+3+2+1+5-4', 'The x-coordinate is 4 + 3 + 2 = 9. The y-coordinate is 1 + 5 - 4 = 2. The final position is $(9, 2)$, and 9 + 2 = 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,1) -> right 3 (7,1) -> up 5 (7,6) -> right 2 (9,6) -> down 4 (9,2). 9 + 2 = 11.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e68ae0a-f85a-4890-a06e-f1693f12e5e4', 'NC26.5.SGMR.2', 3, 'choice', 'Plot a point by moving from the origin', 'A frog starts at the origin and makes two jumps. Each jump goes some units right and some units up. Which pair of jumps lands the frog at $(5, 8)$?', '["Right 3 and up 4, then right 4 and up 2","Right 3 and up 4, then right 2 and up 4","Right 5 and up 4, then right 3 and up 4","Right 4 and up 8, then right 1 and up 1"]', 'Right 3 and up 4, then right 2 and up 4', NULL, 'Add the right moves and the up moves separately. 3 + 2 = 5 and 4 + 4 = 8 gives $(5, 8)$. The other pairs of jumps land at $(7, 6)$, $(8, 8)$ and $(5, 9)$.', 'checked', '{"lint":[],"solve":{"answer":"Right 3 and up 4, then right 2 and up 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need total right 5 and up 8. A: 3+2 = 5, 4+4 = 8. B: 8, 8. C: 5, 9. D: 7, 6. Only A.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c53ecc1c-949d-4cde-b27b-49ddcd639a6f', 'NC26.5.SGMR.2', 3, 'numeric', 'Points on an axis or on the same line', 'Point A is on the x-axis and point B is on the y-axis. A is 7 units from the origin and B is 4 units from the origin. What is the sum of the x-coordinate of A and the y-coordinate of B?', '[]', '11', '7+4', 'A is on the x-axis, so it is $(7, 0)$ and its x-coordinate is 7. B is on the y-axis, so it is $(0, 4)$ and its y-coordinate is 4. The sum is 7 + 4 = 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In the first quadrant A = (7, 0), B = (0, 4). 7 + 4 = 11.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014fef62-bbc9-4cb9-b8b4-11019095e252', 'NC26.5.SGMR.2', 3, 'numeric', 'Points on an axis or on the same line', 'Here are five points: $(0, 7)$, $(7, 0)$, $(0, 0)$, $(5, 5)$ and $(9, 0)$. How many of them are on the x-axis? The origin counts.', '[]', '3', NULL, 'A point is on the x-axis when its y-coordinate is 0. That is true for $(7, 0)$, $(0, 0)$ and $(9, 0)$. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"On the x-axis means y = 0: (7, 0), (0, 0), (9, 0). That is 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('920f5018-a985-479e-b983-ae55e3674acb', 'NC26.5.SGMR.2', 3, 'numeric', 'Distance along a horizontal or vertical line', 'Mina walks along a straight vertical path from $(6, 3)$ up to $(6, 15)$. She stops halfway. What is the y-coordinate of the place where she stops?', '[]', '9', '(3+15)/2', 'The path is 15 - 3 = 12 units long, so halfway is 6 units up from the start. The y-coordinate is 3 + 6 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Path length 15 - 3 = 12; half is 6; 3 + 6 = 9.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0149e4f-4057-4c0b-83d7-7aad84bd9d37', 'NC26.5.SGMR.2', 3, 'numeric', 'Distance along a horizontal or vertical line', 'On a plane where each unit is 1 mile, a runner goes from $(2, 4)$ right to $(10, 4)$. Then she turns around and runs 3 miles back to the left. How many miles from her starting point is she now?', '[]', '5', '10-2-3', 'She first goes 10 - 2 = 8 miles right of the start. Then she runs 3 miles back, so she is 8 - 3 = 5 miles from the start.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From x = 2 to x = 10 is 8 miles; back 3 to x = 7. Distance from start (2, 4) is 7 - 2 = 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59658d17-9922-47f3-bb98-a27a9540f005', 'NC26.5.SGMR.2', 3, 'choice', 'Distance along a horizontal or vertical line', 'Point M is on the same vertical line as $(4, 5)$ and is 9 units from it. M is in the first quadrant (no negative coordinates). Which point is M?', '["$(13, 5)$","$(4, 9)$","$(4, 14)$","$(9, 5)$"]', '$(4, 14)$', NULL, 'A point on the same vertical line has x-coordinate 4. Moving down 9 from y = 5 would go below the x-axis, so M is 9 units up: 5 + 9 = 14. M is $(4, 14)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 14)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same vertical line means x = 4; 9 units away gives y = 14 (or -4, excluded). (4, 14).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62963065-bfe4-4e71-92d5-dab94df1b964', 'NC26.5.SGMR.2', 3, 'numeric', 'Area and perimeter of rectangles on the plane', 'A rectangle has horizontal and vertical sides. One corner is at $(1, 2)$ and the corner opposite it is at $(9, 7)$. What is the perimeter of the rectangle, in units?', '[]', '26', '2*((9-1)+(7-2))', 'The rectangle is 9 - 1 = 8 units wide and 7 - 2 = 5 units tall. The perimeter is 2 x (8 + 5) = 26 units.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 9 - 1 = 8, height 7 - 2 = 5. Perimeter 2 x (8 + 5) = 26.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35a0a269-b691-4742-b7ac-4287b8d83cac', 'NC26.5.SGMR.2', 3, 'choice', 'Area and perimeter of rectangles on the plane', 'Rectangle A has corners $(1, 1)$, $(5, 1)$, $(5, 4)$ and $(1, 4)$. Rectangle B has corners $(6, 1)$, $(11, 1)$, $(11, 3)$ and $(6, 3)$. Which statement is true?', '["Rectangle B has the greater area, by 2 square units.","The two rectangles have the same area.","Rectangle A has the greater area, by 2 square units.","Rectangle A has the greater area, by 4 square units."]', 'Rectangle A has the greater area, by 2 square units.', NULL, 'Rectangle A is 4 by 3, so its area is 12 square units. Rectangle B is 5 by 2, so its area is 10 square units. A is greater by 2. (Both have perimeter 14, but that does not make the areas equal.)', 'checked', '{"lint":[],"solve":{"answer":"Rectangle A has the greater area, by 2 square units.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 4 x 3 = 12. B: 5 x 2 = 10. A greater by 2.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('118a9566-a99f-4ba2-b19e-43abe8644779', 'NC26.5.SGMR.2', 3, 'numeric', 'Area and perimeter of rectangles on the plane', 'The bottom side of a rectangle runs from $(2, 2)$ to $(8, 2)$. The area of the rectangle is 24 square units, and the rectangle extends upward from the bottom side. What is the y-coordinate of its top side?', '[]', '6', '2+24/(8-2)', 'The bottom side is 8 - 2 = 6 units long. The height is 24 divided by 6 = 4 units. The top side is 4 units above y = 2, so its y-coordinate is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom side 8 - 2 = 6; height 24 / 6 = 4; top y = 2 + 4 = 6.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9075e797-fa6f-45c8-85cc-8216222ac04a', 'NC26.5.SGMR.2', 3, 'numeric', 'Find a missing corner of a shape', 'Two corners of a square are $(3, 2)$ and $(3, 8)$. They are the ends of one side, and the square lies to the right of that side. What is the x-coordinate of the other two corners?', '[]', '9', '3+(8-2)', 'The side from $(3, 2)$ to $(3, 8)$ is 8 - 2 = 6 units long, so every side is 6 units. The other corners are 6 units to the right, at x = 3 + 6 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side length 8 - 2 = 6; to the right, x = 3 + 6 = 9.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b110a839-3795-4923-8553-aa5d65e15783', 'NC26.5.SGMR.2', 3, 'choice', 'Find a missing corner of a shape', 'Which set of points are the four corners of a rectangle whose sides are horizontal and vertical?', '["$(1, 1)$, $(5, 1)$, $(5, 4)$, $(2, 4)$","$(1, 1)$, $(5, 1)$, $(5, 4)$, $(1, 4)$","$(1, 1)$, $(5, 2)$, $(5, 4)$, $(1, 4)$","$(1, 1)$, $(4, 1)$, $(5, 4)$, $(1, 4)$"]', '$(1, 1)$, $(5, 1)$, $(5, 4)$, $(1, 4)$', NULL, 'The corners of such a rectangle share x-coordinates in pairs and y-coordinates in pairs. Only the first set has two points with y = 1, two with y = 4, two with x = 1 and two with x = 5.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 1)$, $(5, 1)$, $(5, 4)$, $(1, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need two x values and two y values each used twice. Only (1,1), (5,1), (5,4), (1,4) works; others have a stray 2 or 4.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f40e59d3-2270-4935-bb34-2d53bd6cd9bb', 'NC26.5.SGMR.2', 3, 'numeric', 'Move a point and measure a path', 'A truck drives from $(0, 2)$ right to $(6, 2)$, then up to $(6, 7)$, then left to $(1, 7)$. On a plane where each unit is 1 mile, how many miles does it drive in all?', '[]', '16', '6+5+5', 'The first part is 6 - 0 = 6 miles, the second is 7 - 2 = 5 miles, and the third is 6 - 1 = 5 miles. The total is 6 + 5 + 5 = 16 miles.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 5 + 5 = 16 miles.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
