INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1a9babd-379d-4e9e-8f2e-b1e292d57d37', 'NC26.5.SGMR.2', 3, 'numeric', 'Move a point and measure a path', 'A game character starts at $(2, 8)$. Each turn it moves 2 units right and 1 unit down. After how many turns is it at $(10, 4)$?', '[]', '4', '(10-2)/2', 'The x-coordinate goes from 2 to 10, which is 8 units, at 2 units a turn: 4 turns. Check the y-coordinate: 4 turns down 1 each is 4 units, so 8 - 4 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: 2 to 10 is 8, at 2 per turn = 4 turns; y: 8 to 4 is 4 down at 1 per turn = 4 turns. Consistent: 4.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
