INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2bd0942-7423-49f8-8e58-d424a2abcfd4', 'NC26.5.SGMR.2', 3, 'numeric', 'Move a point and measure a path', 'A hiker starts at $(2, 2)$. She walks 5 units right, 4 units up, 5 units left, and 4 units down. On a plane where each unit is 1 kilometer, how many kilometers does she walk in all?', '[]', '18', '5+4+5+4', 'She walks every part, even though she ends where she started. The total is 5 + 4 + 5 + 4 = 18 kilometers.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 4 + 5 + 4 = 18 km.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
