INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d45de92e-b5b2-471f-a6fc-ffd31f342fce', 'NC26.5.SGMR.3', 1, 'choice', 'Convert metric units of mass and capacity', 'A tank holds 9,000 milliliters of water. How many liters of water is that? (1 liter = 1,000 milliliters)', '["90","900","0.9","9"]', '9', '9000/1000', '$9{,}000 \div 1{,}000 = 9$ liters. The other choices divide by too small or too large a number.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9,000 mL / 1,000 mL/L = 9 L.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
