INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3979da2-b6c8-4da9-ba89-59b94e713e6d', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Sam changes 4 feet to inches. Will the number of inches be greater than 4 or less than 4?', '["Less than 4, because an inch is shorter than a foot","Greater than 4, because an inch is longer than a foot","Equal to 4, because both units measure length","Greater than 4, because an inch is shorter than a foot"]', 'Greater than 4, because an inch is shorter than a foot', NULL, 'An inch is shorter than a foot, so it takes more inches than feet to cover the same length. There will be more than 4 inches (in fact 48).', 'checked', '{"lint":[],"solve":{"answer":"Greater than 4, because an inch is shorter than a foot","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inches are smaller than feet, so it takes more of them: 4 ft = 48 in > 4. Only option 3 has the right result and the right reason.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f673ff8b-a308-475e-b312-056187247494', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Which answer is reasonable for changing 5 meters to centimeters?', '["About 0.05 centimeters","About 500 centimeters","About 5 centimeters","About 50 centimeters"]', 'About 500 centimeters', NULL, 'A centimeter is much shorter than a meter (100 of them make a meter), so 5 meters is about $5 \times 100 = 500$ centimeters. The other answers are far too small.', 'checked', '{"lint":[],"solve":{"answer":"About 500 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 m x 100 cm/m = 500 cm. \"About 500\" is the reasonable one.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e30f5a4-f118-4713-a33e-b5fd9feac35c', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Ivy changes 2 liters to milliliters and gets 0.002 milliliters. Why is her answer NOT reasonable?', '["A milliliter is much smaller than a liter, so there should be many more milliliters than liters","A liter is much smaller than a milliliter, so the answer should be even smaller","Liters cannot be changed to milliliters","Changing units never changes the number"]', 'A milliliter is much smaller than a liter, so there should be many more milliliters than liters', NULL, 'A milliliter is a tiny amount, so 2 liters must be a big number of milliliters (2,000). Ivy divided when she should have multiplied.', 'checked', '{"lint":[],"solve":{"answer":"A milliliter is much smaller than a liter, so there should be many more milliliters than liters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 L = 2,000 mL. A milliliter is smaller, so the number of mL must be larger than 2, not 0.002.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
