VALUES ('eca619ba-fdc1-4814-9557-879e3ab7b12d', 'NC26.5.SGMR.3', 1, 'choice', 'Compare measurements in different units', 'Which comparison is true? (1 foot = 12 inches)', '["3 feet is less than 30 inches","3 feet is greater than 30 inches","3 feet is equal to 30 inches","3 feet is equal to 3 inches"]', '3 feet is greater than 30 inches', NULL, '3 feet is $3 \times 12 = 36$ inches, and 36 is greater than 30.', 'checked', '{"lint":[],"solve":{"answer":"3 feet is greater than 30 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 ft = 36 in; 36 > 30.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
