INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e093022-5185-40e2-a829-091699b4c5ad', 'NC26.5.SGMR.3', 2, 'choice', 'Compare measurements in different units', 'Three ropes are 2 meters, 150 centimeters and 1,000 millimeters long. Which list puts them in order from shortest to longest?', '["2 meters, 150 centimeters, 1,000 millimeters","1,000 millimeters, 150 centimeters, 2 meters","150 centimeters, 1,000 millimeters, 2 meters","1,000 millimeters, 2 meters, 150 centimeters"]', '1,000 millimeters, 150 centimeters, 2 meters', NULL, 'In centimeters the ropes are 200, 150 and 100. From shortest to longest: 100 (1,000 millimeters), 150, 200 (2 meters).', 'checked', '{"lint":[],"solve":{"answer":"1,000 millimeters, 150 centimeters, 2 meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 m = 200 cm; 150 cm; 1,000 mm = 100 cm. Shortest to longest: 100, 150, 200 cm = 1,000 mm, 150 cm, 2 m.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
