INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84fb4a3f-8a5c-46e0-93d8-9e50f6228021', 'NC26.5.SGMR.3', 2, 'choice', 'Compare measurements in different units', 'A soup recipe needs 2 quarts of milk. Ana has 7 cups of milk. (1 quart = 4 cups) Does Ana have enough milk?', '["Yes, she has 1 extra cup","Yes, because 7 is greater than 2","No, she needs 1 more cup","No, she needs 5 more cups"]', 'No, she needs 1 more cup', NULL, '2 quarts is $2 \times 4 = 8$ cups. Ana has only 7 cups, so she needs $8 - 7 = 1$ more cup.', 'checked', '{"lint":[],"solve":{"answer":"No, she needs 1 more cup","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 qt x 4 = 8 cups needed; 8 - 7 = 1 more cup.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
