VALUES ('39097c38-4a74-408e-bcca-99f06187acd8', 'NC26.5.SGMR.3', 3, 'choice', 'Convert a smaller customary unit to a larger one', 'Which measurement is equal to 108 inches? (1 foot = 12 inches and 1 yard = 3 feet)', '["9 yards","3 yards","36 yards","324 yards"]', '3 yards', NULL, '$108 \div 12 = 9$ feet, and $9 \div 3 = 3$ yards. 9 is the number of FEET, so 9 yards stops one step early. 36 and 324 come from dividing or multiplying 108 by 3 only.', 'checked', '{"lint":[],"solve":{"answer":"3 yards","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"108 in / 12 = 9 ft; 9 ft / 3 = 3 yd.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
