VALUES ('744d7df2-6ebf-4231-a4a2-f5c208f690dd', 'NC26.5.SGMR.4', 2, 'choice', 'Volume of a composite solid', 'A block of cheese is 10 cm long, 6 cm wide and 4 cm tall. A piece that is 3 cm long, 6 cm wide and 2 cm tall is cut out of one end. How much cheese is left, in cubic centimeters?', '["36","276","204","240"]', '204', '10*6*4-3*6*2', 'The whole block is $10 \times 6 \times 4 = 240$ and the piece cut out is $3 \times 6 \times 2 = 36$. What is left: $240 - 36 = 204$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"204","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Block 10x6x4 = 240; piece 3x6x2 = 36; left 240 - 36 = 204.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec4b5546-67ac-4c1e-a92d-ab6283b2839b', 'NC26.5.SGMR.4', 2, 'numeric', 'Volume of a composite solid', 'A solid is made by joining a cube and a slab. The cube has edges that are each 5 cm long. The slab is 5 cm long, 5 cm wide and 2 cm tall. What is the volume of the solid, in cubic centimeters?', '[]', '175', '5*5*5+5*5*2', 'The cube is $5 \times 5 \times 5 = 125$ and the slab is $5 \times 5 \times 2 = 50$. Together: $125 + 50 = 175$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"175","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 5x5x5 = 125; slab 5x5x2 = 50; total 175 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e070488-dde7-4a1d-8e59-2edd33223b65', 'NC26.5.SGMR.4', 2, 'numeric', 'Pack a box with unit cubes in layers', 'A box is 10 centimeters long, 8 centimeters wide and 6 centimeters tall. How many 1-centimeter cubes fill the box with no gaps?', '[]', '480', '10*8*6', 'One layer has $10 \times 8 = 80$ cubes and there are 6 layers: $80 \times 6 = 480$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 8 x 6 = 480 cubes.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
