INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3edba592-e1e5-488c-ace4-f6a5cf294f94', 'NC26.5.SGMR.4', 2, 'numeric', 'Pack a box with unit cubes in layers', 'A crate is 12 inches long, 9 inches wide and 6 inches tall. It is packed with cubes that each have edges 3 inches long, with no gaps. How many cubes fit in the crate?', '[]', '24', '(12/3)*(9/3)*(6/3)', 'Along the length, $12 \div 3 = 4$ cubes fit. Along the width, $9 \div 3 = 3$ fit. In the height, $6 \div 3 = 2$ fit. So $4 \times 3 \times 2 = 24$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/3 = 4, 9/3 = 3, 6/3 = 2 cubes along each edge; 4 x 3 x 2 = 24 cubes (check: 648 / 27 = 24).","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('428961d1-75c6-4f12-ab1e-8c21ae390a69', 'NC26.5.SGMR.4', 2, 'choice', 'Pack a box with unit cubes in layers', 'A box is 7 centimeters long and 4 centimeters wide. It is filled with 1-centimeter cubes to a height of 3 centimeters. How many cubes are in the box?', '["14","28","12","84"]', '84', '7*4*3', 'One layer has $7 \times 4 = 28$ cubes and there are 3 layers: $28 \times 3 = 84$ cubes. Adding gives 14, and one layer alone is 28.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 4 x 3 = 84 cubes.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
