INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b1947f5-6711-4937-9fb2-ae0a205786be', 'NC26.5.SGMR.4', 2, 'numeric', 'Volume in a real-world problem', 'Water flows into an empty tank at 6 cubic feet each minute. The tank is 5 feet long, 4 feet wide and 3 feet deep. How many minutes does it take to fill the tank?', '[]', '10', '5*4*3/6', 'The tank holds $5 \times 4 \times 3 = 60$ cubic feet. At 6 cubic feet per minute, it takes $60 \div 6 = 10$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume 5 x 4 x 3 = 60 cubic feet; 60 / 6 = 10 minutes.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
