INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('392302bb-7051-4d0d-8408-2b942ec7a4c9', 'NC26.5.SGMR.4', 2, 'choice', 'Volume in a real-world problem', 'A sandbox is 8 feet long, 6 feet wide and 1 foot deep. A bag of sand holds 12 cubic feet. How many bags are needed to fill the sandbox exactly?', '["48","14","2","4"]', '4', '8*6*1/12', 'The sandbox holds $8 \times 6 \times 1 = 48$ cubic feet. Each bag holds 12, so $48 \div 12 = 4$ bags. The number 48 is the volume, not the number of bags.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 6 x 1 = 48 cubic feet; 48 / 12 = 4 bags.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
