INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43572954-3070-4777-ba1e-3695bc5df8ae', 'NC26.5.SGMR.4', 2, 'choice', 'Volume in a real-world problem', 'A raised garden bed is 6 feet long, 3 feet wide and 2 feet tall. Soil costs 3 dollars for each cubic foot. How many dollars does it cost to fill the bed with soil?', '["108","11","36","18"]', '108', '6*3*2*3', 'The bed holds $6 \times 3 \times 2 = 36$ cubic feet. At 3 dollars each, the cost is $36 \times 3 = 108$ dollars. The number 36 is the volume, before the price.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 3 x 2 = 36 cubic feet; 36 x 3 = 108 dollars.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
