INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e104eccd-56d2-4b48-889b-f45e6d6b3fdc', 'NC26.5.SGMR.4', 2, 'choice', 'Compare volumes and see how volume changes', 'Which two prisms have the same volume? (length by width by height)', '["2 by 6 by 5 and 3 by 4 by 5","3 by 4 by 5 and 3 by 4 by 6","2 by 6 by 5 and 2 by 3 by 5","4 by 4 by 4 and 4 by 4 by 5"]', '2 by 6 by 5 and 3 by 4 by 5', NULL, '$2 \times 6 \times 5 = 60$ and $3 \times 4 \times 5 = 60$. The other pairs have volumes 60 and 72, 60 and 30, and 64 and 80.', 'checked', '{"lint":[],"solve":{"answer":"2 by 6 by 5 and 3 by 4 by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x6x5 = 60 vs 2x3x5 = 30; 2x6x5 = 60 vs 3x4x5 = 60 (equal); 60 vs 72; 64 vs 80. Answer B.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
