INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360deb32-12f3-4d93-9ed8-830efc70e037', 'NC26.5.SGMR.4', 2, 'choice', 'Compare volumes and see how volume changes', 'The height of a box is made 3 times as tall. Its length and width stay the same. What happens to the volume of the box?', '["It stays the same","It is 9 times as great","It is 3 times as great","It is one third as great"]', 'It is 3 times as great', NULL, 'Each layer stays the same, but there are 3 times as many layers, so the volume is 3 times as great.', 'checked', '{"lint":[],"solve":{"answer":"It is 3 times as great","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = l x w x h; h x 3 makes V x 3.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9479be2c-ec9a-453d-90dd-85c10b47b37b', 'NC26.5.SGMR.4', 2, 'choice', 'Compare volumes and see how volume changes', 'Box A is 6 cm long, 4 cm wide and 3 cm tall. Box B is 5 cm long, 5 cm wide and 3 cm tall. How many more cubic centimeters does the larger box hold than the smaller box?', '["72","3","75","147"]', '3', '5*5*3-6*4*3', 'Box A holds $6 \times 4 \times 3 = 72$ and Box B holds $5 \times 5 \times 3 = 75$. The larger box holds $75 - 72 = 3$ more.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6x4x3 = 72; B: 5x5x3 = 75. 75 - 72 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
