INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('864bfa8c-4e2c-4c29-b638-32973ea50d6b', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume of a rectangular prism from length, width and height', 'The length of a box is 12 centimeters. Its width is half its length, and its height is 3 centimeters more than its width. What is its volume, in cubic centimeters?', '[]', '648', '12*(12/2)*(12/2+3)', 'The width is $12 \div 2 = 6$ cm and the height is $6 + 3 = 9$ cm. Then $V = 12 \times 6 \times 9 = 648$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"648","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 12, width 12/2 = 6, height 6 + 3 = 9. 12 x 6 x 9 = 648 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
