INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e5ffddd-486a-40aa-ba39-f1684c5a1ce8', 'NC26.5.SGMR.4', 3, 'choice', 'Volume of a rectangular prism from length, width and height', 'Which prism has the same volume as a prism that is 10 cm long, 6 cm wide and 4 cm tall? (length by width by height)', '["8 by 6 by 4","10 by 6 by 5","12 by 5 by 3","8 by 6 by 5"]', '8 by 6 by 5', NULL, 'The first prism has volume $10 \times 6 \times 4 = 240$. Only $8 \times 6 \times 5 = 240$ matches; the others are 192, 300 and 180.', 'checked', '{"lint":[],"solve":{"answer":"8 by 6 by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Target 10 x 6 x 4 = 240. 10x6x5 = 300; 8x6x5 = 240; 8x6x4 = 192; 12x5x3 = 180. Match: 8 by 6 by 5.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
