INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6843853-8cd9-4ac1-b0dd-be83afd06715', 'NC26.5.SGMR.4', 3, 'choice', 'Find a missing dimension from the volume', 'A cube-shaped box has a volume of 216 cubic inches. How long is each edge, in inches?', '["6","36","72","108"]', '6', '6', 'All three edges are equal, so we need a number that multiplies by itself three times to make 216. $6 \times 6 \times 6 = 216$, so each edge is 6 inches.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 6 x 6 = 216, so edge 6 inches.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
