INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60562f23-1a3b-47ff-8ffb-fe78d382a270', 'NC26.5.SGMR.4', 3, 'choice', 'Find a missing dimension from the volume', 'Which set of measurements gives a prism with a volume of 90 cubic centimeters? (length by width by height)', '["9 by 5 by 3","10 by 3 by 2","9 by 5 by 2","8 by 5 by 2"]', '9 by 5 by 2', NULL, '$9 \times 5 \times 2 = 90$. The others give 135, 60 and 80 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9 by 5 by 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x5x2 = 90; 8x5x2 = 80; 10x3x2 = 60; 9x5x3 = 135. Answer 9 by 5 by 2.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
