INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d141a46-d5b2-4f16-8343-7112717f2156', 'NC26.5.SGMR.4', 3, 'numeric', 'Find a missing dimension from the volume', 'A box with a volume of 480 cubic inches is 12 inches long and 8 inches wide. A shorter box has the same length and width, but is 2 inches shorter than the first box. What is the volume of the shorter box, in cubic inches?', '[]', '288', '12*8*(480/(12*8)-2)', 'The base area is $12 \times 8 = 96$ square inches, so the first box is $480 \div 96 = 5$ inches tall. The shorter box is $5 - 2 = 3$ inches tall, so its volume is $96 \times 3 = 288$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"288","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 12 x 8 = 96; height 480 / 96 = 5. Shorter height 3; 96 x 3 = 288.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
