INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac41395c-a3d8-439f-8970-659b95abaee2', 'NC26.5.SGMR.4', 3, 'numeric', 'Pack a box with unit cubes in layers', 'A box holds 120 one-inch cubes in 4 equal layers. Each layer has 6 rows. How many cubes are in each row?', '[]', '5', '120/4/6', 'Each layer holds $120 \div 4 = 30$ cubes. Each row holds $30 \div 6 = 5$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 / 4 = 30 per layer; 30 / 6 rows = 5 per row.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
