INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cd014db-a74e-4f59-9a48-c762fad57cb0', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'An aquarium is 40 centimeters long, 25 centimeters wide and 30 centimeters tall. It has water in it to a depth of 20 centimeters. How many more cubic centimeters of water are needed to fill it to the top?', '[]', '10000', '40*25*(30-20)', 'The empty space is a prism 40 cm long, 25 cm wide and $30 - 20 = 10$ cm tall. Its volume is $40 \times 25 \times 10 = 10{,}000$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Empty height 30 - 20 = 10 cm; 40 x 25 x 10 = 10,000 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
