INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1adbdf8a-2a40-4c85-9e1a-7fd3f2130f4f', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'A truck bed is 6 feet long, 4 feet wide and 3 feet tall. It is filled level to the top with gravel. Each cubic foot of gravel weighs 100 pounds. How many pounds does the gravel weigh?', '[]', '7200', '6*4*3*100', 'The truck bed holds $6 \times 4 \times 3 = 72$ cubic feet. Then $72 \times 100 = 7{,}200$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"7200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 3 = 72 cubic feet; 72 x 100 = 7,200 pounds.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
