INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('406b8165-765d-4e7d-b297-53201890ede4', 'NC26.5.SGMR.4', 3, 'choice', 'Compare volumes and see how volume changes', 'Which change makes the volume of a prism 6 times as great?', '["Multiply the length, the width and the height each by 2","Multiply the length by 3 and the width by 3","Multiply the length by 2 and the width by 3","Multiply the length by 6 and the width by 6"]', 'Multiply the length by 2 and the width by 3', NULL, '$2 \times 3 = 6$, so doubling the length and tripling the width gives 6 times the volume. The other changes give 8 times, 9 times and 36 times.', 'checked', '{"lint":[],"solve":{"answer":"Multiply the length by 2 and the width by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x6 and x6 gives x36; x2 and x3 gives x6; all x2 gives x8; x3 and x3 gives x9. Answer B.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
