INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6360fd27-f7d8-4e71-bab8-07734ff18548', 'NC26.5.RD.1', 1, 'choice', 'Recognize categorical data and data over time', 'Lena asked each classmate, "What is your favorite kind of pizza?" What kind of data will her answers be?', '["Data that change over time","Data measured with a ruler","Data that are all numbers","Categorical data"]', 'Categorical data', NULL, 'Kinds of pizza, such as cheese or pepperoni, are categories, not numbers. So Lena will collect categorical data.', 'checked', '{"lint":[],"solve":{"answer":"Categorical data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite kind of pizza is a category (cheese, pepperoni...), not a number or a time series. Categorical data.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
