INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9a9393b-b580-470d-888b-9d60b50845a0', 'NC26.5.RD.1', 1, 'numeric', 'Recognize categorical data and data over time', 'Students were asked, "What is your favorite season?" The answers were: summer, fall, summer, winter, spring, summer, fall. How many different categories were named?', '[]', '4', NULL, 'The seasons named are summer, fall, winter and spring. Summer and fall were each named more than once, but each is only one category. That makes 4 different categories.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distinct answers: summer, fall, winter, spring = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
