INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5dbb674-f901-497a-be12-c8181a6ab468', 'NC26.5.RD.1', 1, 'numeric', 'Make predictions from data over time', 'A plant is 10 cm tall now and grows 2 cm each week. If the pattern continues, how tall will it be after 3 more weeks, in centimeters?', '[]', '16', '10+3*2', 'In 3 weeks it grows $3 \times 2 = 6$ cm. The height will be $10 + 6 = 16$ cm.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 + 3 x 2 = 16 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
