INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b251f33c-5a5a-44a2-9701-db4af7e07cb6', 'NC26.5.RD.1', 1, 'numeric', 'Make predictions from data over time', 'The number of birds at a feeder in four hours was 20, 16, 12 and 8. If the pattern continues, how many birds will be at the feeder in the next hour?', '[]', '4', '8-4', 'The number of birds goes down by 4 each hour, so the next hour will have $8 - 4 = 4$ birds.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down 4 each hour: 8 - 4 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
