INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0bd9155-1ff4-4684-a57e-58ad7084ffe1', 'NC26.5.RD.1', 2, 'numeric', 'Choose the best graph for the data', 'A student made a line graph of the daily high temperature for 3 school weeks, Monday to Friday only. How many points are on the line graph?', '[]', '15', '3*5', 'There is one point for each school day. Three weeks of 5 days is $3 \times 5 = 15$ points.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 weeks x 5 days = 15 points.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
