INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74087d5a-d41b-43f6-973a-a0e6335c4e40', 'NC26.5.RD.1', 2, 'numeric', 'Read a line plot', 'A line plot shows the number of minutes it takes 11 students to walk to school. There are 2 X marks above 5, 4 above 10, 3 above 15, 1 above 20 and 1 above 25. How many students take more than 10 minutes?', '[]', '5', '3+1+1', 'More than 10 minutes means the values 15, 20 and 25. The X marks above them are $3 + 1 + 1 = 5$, so 5 students take more than 10 minutes.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check total 2+4+3+1+1 = 11. More than 10: 15 (3) + 20 (1) + 25 (1) = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cd1e36a-30fd-461b-88af-0517a8012127', 'NC26.5.RD.1', 2, 'numeric', 'Read a line plot', 'A line plot shows the number of books 9 students read this month: 3, 4, 4, 5, 5, 5, 6, 8, 8. How many more books did the student who read the most read than the student who read the least?', '[]', '5', '8-3', 'The most books read was 8 and the least was 3. The difference is $8 - 3 = 5$ books.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Most 8, least 3: 8 - 3 = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
