VALUES ('2f976554-05b5-44c3-844f-4f78a8e6249e', 'NC26.5.RD.1', 2, 'choice', 'Read a bar graph', 'A bar graph shows the number of books checked out: Monday 24, Tuesday 18, Wednesday 30, Thursday 21 and Friday 27. On which day were exactly 9 more books checked out than on Tuesday?', '["Wednesday","Friday","Thursday","Monday"]', 'Friday', NULL, 'Tuesday had 18 books, and $18 + 9 = 27$. Friday had 27 books. (Wednesday had 12 more, Thursday 3 more and Monday 6 more.)', 'checked', '{"lint":[],"solve":{"answer":"Friday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tuesday 18 + 9 = 27 = Friday.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
