INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a81fcaf8-1555-4886-8268-4d7a32381357', 'NC26.5.RD.1', 2, 'numeric', 'Read a line graph of data over time', 'A line graph shows the temperature in degrees Fahrenheit: 6 a.m., 41; 9 a.m., 47; noon, 58; 3 p.m., 64; 6 p.m., 55; 9 p.m., 46. By how many degrees did the temperature fall from 3 p.m. to 9 p.m.?', '[]', '18', '64-46', 'At 3 p.m. it was 64 degrees and at 9 p.m. it was 46 degrees. The fall was $64 - 46 = 18$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 p.m. 64, 9 p.m. 46: 64 - 46 = 18 degrees.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
