INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c1cecd3-e06e-4302-80a2-80b5917f2daa', 'NC26.5.RD.1', 2, 'choice', 'Make a graph: scale, labels and plotting', 'Marcus makes a bar graph for these numbers of votes: 12, 28, 36, 44 and 20. Which scale is best?', '["0 to 50, counting by 1s","0 to 50, counting by 10s","0 to 100, counting by 50s","0 to 20, counting by 5s"]', '0 to 50, counting by 10s', NULL, 'The scale must reach past the greatest number, 44, so 0 to 50 works. Counting by 10s gives a few lines that are easy to read. Counting by 1s has far too many lines, counting by 50s is too coarse, and a scale to 20 is too short for 44.', 'checked', '{"lint":[],"solve":{"answer":"0 to 50, counting by 10s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 44 needs a scale to at least 44. 0-20 too short; by 1s too many lines; by 50s too coarse; 0 to 50 by 10s fits.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0393b797-1db1-4689-9509-7e74ba6185ac', 'NC26.5.RD.1', 2, 'choice', 'Make a graph: scale, labels and plotting', 'Kai makes a line graph of a plant''s height. Weeks are along the bottom and height in centimeters is up the side. The plant was 40 cm tall in Week 3. Where should Kai plot the point?', '["Above Week 3 and across from 40 cm","Above Week 40 and across from 3 cm","Above Week 3 and across from 3 cm","Above Week 40 and across from 40 cm"]', 'Above Week 3 and across from 40 cm', NULL, 'The point goes above the Week 3 mark on the bottom axis and level with 40 on the side axis, because the week is on the bottom and the height is up the side.', 'checked', '{"lint":[],"solve":{"answer":"Above Week 3 and across from 40 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = Week 3 on the bottom, y = 40 cm up the side.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44d761bc-dffd-43e6-a0da-5550f277b5fd', 'NC26.5.RD.1', 2, 'choice', 'Draw conclusions from data', 'An ice cream stand sold 30, 45, 60 and 75 cones on Monday through Thursday. Which conclusion is supported by the data?', '["More cones were sold on Monday than on Thursday","The number of cones sold went up by the same amount each day","The stand sold more cones because the weather was hot","The stand sold 100 cones on Friday"]', 'The number of cones sold went up by the same amount each day', NULL, 'Each day is 15 more than the day before (30, 45, 60, 75). The data do not say why sales went up, and they say nothing about what happened on Friday.', 'checked', '{"lint":[],"solve":{"answer":"The number of cones sold went up by the same amount each day","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30, 45, 60, 75: up 15 each day. Friday and weather are not in the data; Monday < Thursday.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4d00db2-42ed-42f2-97ab-b5d1e0afedd5', 'NC26.5.RD.1', 2, 'numeric', 'Draw conclusions from data', 'Mr. Cruz recorded the number of students absent each day: Monday 4, Tuesday 2, Wednesday 3, Thursday 5 and Friday 1. On how many days were more than 2 students absent?', '[]', '3', NULL, 'More than 2 absent happened on Monday (4), Wednesday (3) and Thursday (5). That is 3 days.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More than 2: Monday 4, Wednesday 3, Thursday 5 = 3 days.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dc37dbd-2843-44fc-9139-1f2db69fb2ad', 'NC26.5.RD.1', 2, 'choice', 'Draw conclusions from data', 'In a survey of 40 fifth graders, 22 prefer reading, 10 prefer sports and 8 prefer art. Which conclusion is supported by the data?', '["Exactly half of the students prefer reading","More than half of the students prefer reading","Sports is the most popular choice","Art and sports together are more than reading"]', 'More than half of the students prefer reading', NULL, 'Half of 40 is 20, and 22 is more than 20. Sports (10) is not the most popular, and art and sports together are $8 + 10 = 18$, which is less than 22.', 'checked', '{"lint":[],"solve":{"answer":"More than half of the students prefer reading","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 40 is 20; 22 > 20, so more than half prefer reading. Sports+art = 18 < 22.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4762fa77-7567-44c6-b9b3-9acdca4b6ba7', 'NC26.5.RD.1', 2, 'numeric', 'Make predictions from data over time', 'A tank holds 500 liters at 8 a.m., 460 liters at 9 a.m., 420 liters at 10 a.m. and 380 liters at 11 a.m. If the pattern continues, how many liters will it hold at 2 p.m.?', '[]', '260', '380-3*40', 'The tank loses 40 liters each hour. From 11 a.m. to 2 p.m. is 3 more hours, so it loses $3 \times 40 = 120$ more liters. It will hold $380 - 120 = 260$ liters.', 'checked', '{"lint":[],"solve":{"answer":"260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down 40 per hour. 11 a.m. 380; noon 340; 1 p.m. 300; 2 p.m. 260.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50d5d968-7f31-4342-9abc-9bb0c9cf506a', 'NC26.5.RD.1', 2, 'choice', 'Make predictions from data over time', 'A bakery sold 12, 14, 16 and 18 muffins on Monday to Thursday. Which prediction for Friday is best supported by the data?', '["About 40 muffins","About 10 muffins","About 20 muffins","About 16 muffins"]', 'About 20 muffins', NULL, 'Sales went up by 2 muffins each day, so Friday should be about $18 + 2 = 20$ muffins. The other numbers do not follow the pattern.', 'checked', '{"lint":[],"solve":{"answer":"About 20 muffins","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Up 2 each day: 18 + 2 = 20, so about 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc9711b8-10fa-49cb-9d55-23c98ea7625a', 'NC26.5.RD.1', 2, 'numeric', 'Make predictions from data over time', 'A kitten weighed 3, 5, 7 and 9 pounds at 1, 2, 3 and 4 months old. If it keeps gaining weight in the same way, at what age in months will it weigh 15 pounds?', '[]', '7', '4+(15-9)/2', 'The kitten gains 2 pounds each month. To go from 9 to 15 pounds it needs 6 more pounds, which takes $6 \div 2 = 3$ more months. That is at $4 + 3 = 7$ months.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gains 2 lb per month: 9 at 4, 11 at 5, 13 at 6, 15 at 7 months.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56b4242a-2cb1-48c0-aa85-87355add4583', 'NC26.5.RD.1', 3, 'numeric', 'Add up the amounts in a line plot with fractions', 'A line plot shows the amount of juice, in cups, in 8 glasses: $\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{2}$, $\frac{3}{4}$, $\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{2}$, $\frac{3}{4}$. All of the juice is poured into one pitcher. How many cups of juice are in the pitcher?', '[]', '4', '4*(1/2)+2*(1/4)+2*(3/4)', 'There are 4 glasses of $\frac{1}{2}$ cup (2 cups in all), 2 glasses of $\frac{1}{4}$ cup ($\frac{1}{2}$ cup in all) and 2 glasses of $\frac{3}{4}$ cup ($1\frac{1}{2}$ cups in all). Total: $2 + \frac{1}{2} + 1\frac{1}{2} = 4$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four 1/2 = 2; two 1/4 = 1/2; two 3/4 = 3/2. Total 2 + 1/2 + 3/2 = 4 cups.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('541c0c3c-0c3d-433c-966a-6e076173b7f1', 'NC26.5.RD.1', 3, 'numeric', 'Make a prediction from data over time', 'A store counted its visitors each day. Day 1: 20. Day 2: 35. Day 3: 50. Day 4: 65. If the pattern continues, how many visitors will the store have on Day 7?', '[]', '110', '65+3*15', 'The number goes up by 15 each day ($35 - 20 = 15$, and so on). Day 5: 80, Day 6: 95, Day 7: 110.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 15 per day: Day 5 = 80, Day 6 = 95, Day 7 = 110.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eea01a11-ab1e-4310-a126-cf793c50222a', 'NC26.5.RD.1', 3, 'choice', 'Draw a true conclusion from a bar graph''s data', 'Students voted for a sport. Soccer got 18 votes, swimming 12 votes, tennis 8 votes and running 24 votes. Which statement is true?', '["Running got twice as many votes as swimming.","Soccer got 3 times as many votes as tennis.","Swimming and tennis together got more votes than running.","Tennis got half as many votes as soccer."]', 'Running got twice as many votes as swimming.', NULL, '$24 = 2 \times 12$, so running got twice as many as swimming. The others are false: $3 \times 8 = 24$, not 18; $12 + 8 = 20$, which is less than 24; and half of 18 is 9, not 8.', 'checked', '{"lint":[],"solve":{"answer":"Running got twice as many votes as swimming.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24 not 18; half of 18 is 9 not 8; 2 x 12 = 24 = running (true); 12 + 8 = 20 < 24.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1301903-0ba3-4fda-a051-db9a94f43fe5', 'NC26.5.RD.1', 3, 'choice', 'Recognize categorical data and data over time', 'Data set A is the type of shoe (sneaker, boot or sandal) worn by each of 30 students. Data set B is the number of students absent on each school day of a month. Which statement is true?', '["A is data that change over time and B is categorical data","Both A and B are categorical data","A is categorical data and B is data that change over time","Both A and B are data that change over time"]', 'A is categorical data and B is data that change over time', NULL, 'Types of shoes are categories, so A is categorical. The number absent is counted day after day, so B changes over time. Set A is collected once, so it does not change over time.', 'checked', '{"lint":[],"solve":{"answer":"A is categorical data and B is data that change over time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: shoe type is a category. B: absences on each school day of a month change over time.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dc38502-5348-450c-81dc-3317657b7189', 'NC26.5.RD.1', 3, 'numeric', 'Recognize categorical data and data over time', 'Mia collects data about her class: (1) the color of each student''s backpack, (2) each student''s height in inches, (3) the favorite sport of each student, (4) the number of brothers and sisters each student has, and (5) the favorite food of each student. For how many of these does she collect categorical data?', '[]', '3', '3', 'Backpack colors, favorite sports and favorite foods are categories. Heights and numbers of brothers and sisters are numbers. So 3 of the five give categorical data.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Categorical: backpack color, favorite sport, favorite food = 3. Numerical: height, number of siblings.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74cabee6-259f-4d9a-91a8-af0782954272', 'NC26.5.RD.1', 3, 'numeric', 'Recognize categorical data and data over time', 'A club asked its 12 members to name their favorite game. Chess got 5 votes and checkers got 3 votes. The rest of the members chose cards or puzzles, with the same number choosing each. How many members chose cards?', '[]', '2', '(12-5-3)/2', 'Chess and checkers got $5 + 3 = 8$ votes. That leaves $12 - 8 = 4$ members for cards and puzzles. They were split equally, so $4 \div 2 = 2$ members chose cards.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 5 - 3 = 4 left; split equally between cards and puzzles: 4 / 2 = 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('375d5bad-9c33-4920-b2be-930c075d4497', 'NC26.5.RD.1', 3, 'choice', 'Plan and collect data', 'Ruby wants to know which lunch the students in her school like best. The school has 5 grades. Which plan will give the best data?', '["Ask the 10 students at her lunch table","Ask 50 students in the fifth grade","Ask 10 students from each grade","Ask the cafeteria workers which lunch they think is best"]', 'Ask 10 students from each grade', NULL, 'Asking 10 students from every grade gives answers from the whole school. Asking only one table or only one grade leaves out many students, even if 50 are asked, and the cafeteria workers are not the students whose favorite we want.', 'checked', '{"lint":[],"solve":{"answer":"Ask 10 students from each grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The whole school has 5 grades; a sample from every grade (10 each) represents the school. The others are biased (one grade, one table, adults'' opinions).","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1604eec-c5f4-4523-9ba2-2cbcb26b2d66', 'NC26.5.RD.1', 3, 'numeric', 'Plan and collect data', 'A class will read a rain gauge at 9 a.m. every school day, Monday to Friday, for 4 weeks. The school is closed on 2 of those days. How many readings will the class take?', '[]', '18', '4*5-2', 'Four weeks of 5 school days is $4 \times 5 = 20$ days. The school is closed on 2 of them, so the class takes $20 - 2 = 18$ readings.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 days x 4 weeks = 20 school days; minus 2 closed = 18 readings.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8b92a15-df57-4bdc-88ce-355ecd4cea5d', 'NC26.5.RD.1', 3, 'choice', 'Plan and collect data', 'Which plan is best for finding out whether the number of students who buy lunch changes during a week?', '["Count the students who buy lunch on each school day for 3 weeks","Count the students who buy lunch on one Monday","Ask 5 students whether they buy lunch","Count the students who buy lunch on the first day of each month"]', 'Count the students who buy lunch on each school day for 3 weeks', NULL, 'To see a change from day to day, the counts must be taken on every school day, and more than one week of counts gives a better picture. One day, a few opinions, or one day each month cannot show changes within a week.', 'checked', '{"lint":[],"solve":{"answer":"Count the students who buy lunch on each school day for 3 weeks","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To see change during a week you need counts on each day; 3 weeks of daily counts does that.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
