INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('504889e3-8dc0-4cf4-89dd-d727af1c55ee', 'NC26.5.RD.1', 3, 'numeric', 'Read a line graph of data over time', 'Mara''s line graph shows the number of books she read each month: January 3, February 5, March 2, April 7, May 6 and June 4. For how many months did she read more books than in the month before?', '[]', '2', NULL, 'Compare each month with the one before: February (5 > 3) went up, March (2 < 5) went down, April (7 > 2) went up, May (6 < 7) went down and June (4 < 6) went down. The number went up in 2 months.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Feb 5 > 3 yes; Mar 2 < 5 no; Apr 7 > 2 yes; May 6 < 7 no; Jun 4 < 6 no. 2 months.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
