INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f36a4068-94b6-431f-86fe-ecfb038b9f3c', 'NC26.5.RD.1', 3, 'numeric', 'Read a line graph of data over time', 'A line graph shows Tara''s savings. Over the first 3 weeks her savings went from 45 dollars to 60 dollars. Over the next 2 weeks they went from 60 dollars to 38 dollars. How many more dollars did her savings fall in the last 2 weeks than they rose in the first 3 weeks?', '[]', '7', '(60-38)-(60-45)', 'In the first 3 weeks savings rose $60 - 45 = 15$ dollars. In the next 2 weeks they fell $60 - 38 = 22$ dollars. The fall was $22 - 15 = 7$ dollars more than the rise.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rose 60 - 45 = 15. Fell 60 - 38 = 22. 22 - 15 = 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02322695-8942-47df-807f-8ea086f9f38a', 'NC26.5.RD.1', 3, 'choice', 'Make a graph: scale, labels and plotting', 'Which scale puts every one of these values exactly on a labeled line: 50, 125, 200, 275 and 350?', '["0 to 350, counting by 50s","0 to 350, counting by 100s","0 to 350, counting by 20s","0 to 350, counting by 25s"]', '0 to 350, counting by 25s', NULL, 'Every value must be a multiple of the step. Each value is a multiple of 25. With steps of 50, the values 125 and 275 fall between lines. With steps of 100 and 20, many of the values do not land on a line either.', 'checked', '{"lint":[],"solve":{"answer":"0 to 350, counting by 25s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All values are multiples of 25 (50, 125, 200, 275, 350). 125 is not a multiple of 50 or 100; 50 not of 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
