INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('060c2f3f-bcf0-4005-a6ce-fb56703ceaac', 'NC26.5.RD.1', 3, 'numeric', 'Make a graph: scale, labels and plotting', 'Each square on the side of a bar graph stands for 6 students. The bars for three clubs are 5, 8 and 12 squares tall. How many students are in these three clubs in all?', '[]', '150', '(5+8+12)*6', 'The bars are $5 + 8 + 12 = 25$ squares in all. Each square is 6 students, so $25 \times 6 = 150$ students.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5 + 8 + 12) x 6 = 25 x 6 = 150.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
