INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6663bc0b-f798-4989-95aa-599d317782a6', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-whole ratio language', 'Of the 20 questions on a quiz, Sam answered 17 correctly. What is the ratio of correct answers to all of the questions?', '["$17 : 3$","$3 : 20$","$20 : 17$","$17 : 20$"]', '$17 : 20$', NULL, 'The whole is all 20 questions, so the ratio of correct answers to all the questions is $17 : 20$. ($17 : 3$ compares correct to incorrect answers, and $20 : 17$ has the order reversed.)', 'checked', '{"lint":[],"solve":{"answer":"$17 : 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct to all = 17 : 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
