INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e93d778-c097-4f48-92c8-7a4cc1b3aa22', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-whole ratio language', 'Which sentence describes the ratio $5 : 12$ of girls to all students?', '["5 girls for every 12 boys","12 of every 5 students are girls","5 of every 12 students are girls","5 of every 7 students are girls"]', '5 of every 12 students are girls', NULL, 'A part-to-whole ratio of $5 : 12$ means 5 out of every 12 students are girls. The 12 counts all the students, boys and girls together.', 'checked', '{"lint":[],"solve":{"answer":"5 of every 12 students are girls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls to all students 5 : 12 -> 5 of every 12 students are girls.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
