INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('639ac6fb-fe55-4a2e-9665-1d2c0afea99e', 'NC26.6.RPR.1', 1, 'choice', 'Moving between part-to-part and part-to-whole ratios', 'The ratio of boys to girls in a club is $2 : 3$. Every member of the club is a boy or a girl. What is the ratio of boys to all the students in the club?', '["$2 : 5$","$2 : 3$","$3 : 5$","$5 : 2$"]', '$2 : 5$', NULL, 'For every 2 boys there are 3 girls, so for every 2 boys there are $2 + 3 = 5$ students in all. The ratio of boys to all students is $2 : 5$.', 'checked', '{"lint":[],"solve":{"answer":"$2 : 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 = 5 parts; boys to all = 2 : 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
