INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e0f8061-fa4c-4244-929d-8804b105c3e6', 'NC26.6.RPR.1', 1, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'All the beads in a box are red or blue, and the ratio of red beads to blue beads is 1 to 2. The ratio of red beads to all the beads is 1 to what number?', '[]', '3', '1+2', 'For every 1 red bead there are 2 blue beads, so there are $1 + 2 = 3$ beads in all. The ratio of red to all is 1 to 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 2 = 3 parts; red to all = 1 to 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
