INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('263f225d-5f91-43da-8887-49f0c64093f5', 'NC26.6.RPR.1', 1, 'numeric', 'Finding a missing value in equivalent ratios', 'A recipe uses 3 cups of flour for every 4 cups of milk. How many cups of milk are needed for 9 cups of flour?', '[]', '12', '9/3*4', '9 cups of flour is $9 \div 3 = 3$ times as much as 3 cups, so use 3 times as much milk: $3 \times 4 = 12$ cups.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 flour = 3 x 3; milk 4 x 3 = 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e64401d1-8178-408d-87d9-13bb615a43cb', 'NC26.6.RPR.1', 1, 'numeric', 'Finding a missing value in equivalent ratios', 'The ratio of bags to apples is 1 to 6. At the same ratio, how many apples are in 5 bags?', '[]', '30', '5*6', 'Each bag has 6 apples, so 5 bags have $5 \times 6 = 30$ apples.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 : 6 = 5 : 30.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
