INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('434024bc-cea0-43be-a7fe-c5c07c5ad529', 'NC26.6.RPR.1', 1, 'numeric', 'Finding a missing value in equivalent ratios', 'A paint mix uses 2 cans of blue paint for every 5 cans of white paint. How many cans of blue paint go with 15 cans of white paint?', '[]', '6', '15/5*2', '15 cans of white is $15 \div 5 = 3$ groups of 5. Each group goes with 2 cans of blue, so $3 \times 2 = 6$ cans of blue.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 white = 5 x 3; blue 2 x 3 = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ad47271-7117-4215-b69a-f379371b7fc5', 'NC26.6.RPR.1', 1, 'choice', 'Recognizing and testing equivalent ratios', 'Which ratio is equivalent to $1 : 3$?', '["$2 : 4$","$3 : 1$","$2 : 6$","$1 : 6$"]', '$2 : 6$', NULL, 'Multiply both numbers of $1 : 3$ by 2 to get $2 : 6$. Adding 1 to both numbers gives $2 : 4$, which is not equivalent.', 'checked', '{"lint":[],"solve":{"answer":"$2 : 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 : 3 x 2 = 2 : 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
