INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0932ef1b-63b6-4bd2-ac5e-d518db42f113', 'NC26.6.RPR.1', 1, 'choice', 'Recognizing and testing equivalent ratios', 'Sam makes lemonade with 2 lemons for every 4 cups of water. Which mix uses the same ratio of lemons to water?', '["3 lemons and 5 cups of water","4 lemons and 6 cups of water","2 lemons and 8 cups of water","4 lemons and 8 cups of water"]', '4 lemons and 8 cups of water', NULL, '4 lemons and 8 cups doubles both amounts of 2 lemons and 4 cups, so the ratio stays the same. The other mixes do not multiply both amounts by the same number.', 'checked', '{"lint":[],"solve":{"answer":"4 lemons and 8 cups of water","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 : 4 = 1 : 2. 4 : 8 = 1 : 2. Others: 4:6, 3:5, 2:8 differ.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
