INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35e5e37d-5c7d-4a39-bee5-113220f0d5bb', 'NC26.6.RPR.1', 1, 'choice', 'Recognizing and testing equivalent ratios', 'Which of these ratios is NOT equivalent to $3 : 4$?', '["$6 : 8$","$5 : 6$","$9 : 12$","$12 : 16$"]', '$5 : 6$', NULL, '$6 : 8$, $9 : 12$ and $12 : 16$ come from multiplying 3 and 4 by 2, 3 and 4. $5 : 6$ does not match any multiple of $3 : 4$.', 'checked', '{"lint":[],"solve":{"answer":"$5 : 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6:8, 12:16, 9:12 all equal 3:4; 5:6 does not.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
