INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7b7425-20d5-440c-ab56-c0626dfb3835', 'NC26.6.RPR.1', 1, 'numeric', 'Writing a ratio in lowest terms', 'A bag has 4 red marbles and 12 blue marbles. The ratio of red marbles to blue marbles in lowest terms is 1 to n. What is n?', '[]', '3', '12/4', 'Divide both numbers by 4: $4 : 12$ becomes $1 : 3$. So $n = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 : 12 = 1 : 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
