INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d09ffb46-223f-488d-aeea-589c69b5db48', 'NC26.6.RPR.1', 1, 'choice', 'Writing a ratio in lowest terms', 'Which ratio is written in lowest terms?', '["$4 : 6$","$5 : 10$","$3 : 5$","$6 : 9$"]', '$3 : 5$', NULL, '3 and 5 have no common factor other than 1, so $3 : 5$ cannot be simplified. $4 : 6$ is $2 : 3$, $5 : 10$ is $1 : 2$ and $6 : 9$ is $2 : 3$.', 'checked', '{"lint":[],"solve":{"answer":"$3 : 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 and 5 share no factor; 5:10, 4:6, 6:9 reduce.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
