INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fee2fc32-1c8d-4d2f-95b4-8d4c6e52f7db', 'NC26.6.RPR.1', 1, 'numeric', 'Unit ratio (amount per 1)', 'A pack of 6 pencils costs 12 dollars. How many dollars does 1 pencil cost?', '[]', '2', '12/6', 'Divide the cost by the number of pencils: $12 \div 6 = 2$ dollars for 1 pencil.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 6 = 2 dollars.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
