VALUES ('d2a2edaf-f4e5-4a9c-8f7d-166963859b24', 'NC26.6.RPR.1', 1, 'choice', 'Unit ratio (amount per 1)', 'A machine fills 30 bottles in 5 minutes. How many bottles does it fill in 1 minute?', '["25","150","6","35"]', '6', '30/5', 'Divide: $30 \div 5 = 6$ bottles in 1 minute. (25 subtracts, 150 multiplies and 35 adds.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 / 5 = 6 bottles.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
