INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77c420cd-a8d6-48b3-961c-ea24f9d3615f', 'NC26.6.RPR.1', 1, 'choice', 'The two unit ratios of one relationship', 'A box holds 8 bags that have 24 apples in all, the same number in every bag. Which statement is true?', '["1 bag holds 3 apples","3 bags hold 1 apple","1 bag holds 16 apples","1 bag holds 32 apples"]', '1 bag holds 3 apples', NULL, 'Divide the apples among the bags: $24 \div 8 = 3$ apples in 1 bag. (16 subtracts and 32 adds.)', 'checked', '{"lint":[],"solve":{"answer":"1 bag holds 3 apples","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 8 = 3 apples per bag.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
