INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1953d0b5-76af-46f1-b869-fc357bc8f8df', 'NC26.6.RPR.1', 1, 'numeric', 'The two unit ratios of one relationship', 'Water flows from a tap at 3 liters per minute. How many minutes does it take to fill 1 liter? Write your answer as a fraction.', '[]', '1/3', '1/3', 'In 1 minute, 3 liters flow. So 1 liter takes $1 \div 3 = \frac{1}{3}$ of a minute.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 liters per 1 minute -> 1 liter per 1/3 minute.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
