INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39a251f2-7864-4665-ae51-bca928217c06', 'NC26.6.RPR.1', 1, 'choice', 'The two unit ratios of one relationship', 'A bus travels 40 miles in 1 hour. What is the other unit ratio for this bus?', '["40 hours for every 1 mile","$\\frac{1}{40}$ hour for every 1 mile","$\\frac{1}{40}$ mile for every 1 hour","1 hour for every 1 mile"]', '$\frac{1}{40}$ hour for every 1 mile', NULL, 'One unit ratio is 40 miles per 1 hour. The other is the time for 1 mile: $1 \div 40 = \frac{1}{40}$ hour for every 1 mile.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{40}$ hour for every 1 mile","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 miles : 1 hour -> 1 mile : 1/40 hour, i.e. 1/40 hour for every 1 mile.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
