INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f728eab-8768-4ea5-9439-5fc8efb5ad7a', 'NC26.6.RPR.1', 1, 'choice', 'Ratios of three quantities and totals', 'A bag has 2 red, 3 blue and 5 green marbles. What is the ratio of blue marbles to green marbles?', '["$3 : 10$","$2 : 3$","$5 : 3$","$3 : 5$"]', '$3 : 5$', NULL, 'Blue marbles first, then green: $3 : 5$. ($3 : 10$ compares blue to all the marbles, and $5 : 3$ has the order reversed.)', 'checked', '{"lint":[],"solve":{"answer":"$3 : 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue to green = 3 : 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
