INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63b152ed-0473-40e5-ac81-83239ca4bfbf', 'NC26.6.RPR.1', 1, 'numeric', 'Ratios of three quantities and totals', 'A box has 6 red pens, 4 black pens and 2 blue pens. For every 1 blue pen, how many red pens are there?', '[]', '3', '6/2', 'There are 6 red pens for 2 blue pens. Divide both by 2: 3 red pens for 1 blue pen.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red to blue 6 : 2 = 3 : 1. 3 red per blue.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
