INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2664b0d0-ce33-47eb-af78-a9ab1149148d', 'NC26.6.RPR.1', 1, 'choice', 'Ratios of three quantities and totals', 'A jar has 5 pennies, 3 nickels and 2 dimes. Which statement is true?', '["The ratio of nickels to all the coins is 3 to 7","The ratio of dimes to pennies is 5 to 2","The ratio of pennies to dimes is 2 to 5","The ratio of nickels to all the coins is 3 to 10"]', 'The ratio of nickels to all the coins is 3 to 10', NULL, 'All the coins: $5 + 3 + 2 = 10$, so nickels to all the coins is 3 to 10. Dimes to pennies is 2 to 5, and pennies to dimes is 5 to 2, so the other statements have the order reversed or leave out some coins.', 'checked', '{"lint":[],"solve":{"answer":"The ratio of nickels to all the coins is 3 to 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 10. Nickels to all 3 to 10 (true). 3 to 7 false; dimes to pennies is 2 to 5, pennies to dimes 5 to 2, so B and C reversed.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('569144e6-6d6a-4752-b943-2a540dd20815', 'NC26.6.RPR.1', 2, 'numeric', 'Unit ratio (amount per 1)', 'A car uses 6 gallons of gas to travel 150 miles. How many miles does the car travel on 1 gallon of gas?', '[]', '25', '150/6', 'Divide the miles by the gallons: $150 \div 6 = 25$. The car travels 25 miles on 1 gallon.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit rate: 150 / 6 = 25 miles per gallon.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
