INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d0fb514-5e4f-46a1-b36f-2747271fac86', 'NC26.6.RPR.1', 2, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'The animals at a vet are cats and dogs in the ratio 5 to 3. There are 40 animals in all. How many are cats?', '[]', '25', '40/8*5', 'Each group has $5 + 3 = 8$ animals. There are $40 \div 8 = 5$ groups. Each group has 5 cats, so there are $5 \times 5 = 25$ cats.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 parts = 40, 1 part = 5; cats 5 x 5 = 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42e521e4-a88d-426e-93c7-5419b1149682', 'NC26.6.RPR.1', 2, 'choice', 'Moving between part-to-part and part-to-whole ratios', 'The ratio of walkers to riders in a school is $4 : 11$. Every student either walks or rides. Which statement is true?', '["4 of every 11 students are walkers","11 of every 15 students are walkers","4 of every 15 students are walkers","4 of every 7 students are walkers"]', '4 of every 15 students are walkers', NULL, 'For every 4 walkers there are 11 riders, which makes $4 + 11 = 15$ students. So 4 of every 15 students are walkers. (11 of every 15 are riders.)', 'checked', '{"lint":[],"solve":{"answer":"4 of every 15 students are walkers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 11 = 15; walkers are 4 of every 15.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52fc65c9-30c8-4b25-a8b6-a7d99cee3101', 'NC26.6.RPR.1', 2, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'A shelf has fiction and nonfiction books in the ratio 7 to 5. There are 60 books in all. How many are nonfiction?', '[]', '25', '60/12*5', 'Each group has $7 + 5 = 12$ books. There are $60 \div 12 = 5$ groups. Each group has 5 nonfiction books, so there are $5 \times 5 = 25$ nonfiction books.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 parts = 60, 1 part = 5; nonfiction 5 x 5 = 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f1ed595-a60c-4bb9-9086-94251fdeefb1', 'NC26.6.RPR.1', 2, 'choice', 'Writing a ratio in different notations', 'Which of these does NOT show the ratio of 4 cups of rice to 9 cups of water?', '["$4 : 9$","$9 : 4$","4 to 9","$\\frac{4}{9}$"]', '$9 : 4$', NULL, 'Rice is named first, so the 4 comes first: $4 : 9$, 4 to 9 and $\frac{4}{9}$ all show it. $9 : 4$ has the order reversed.', 'checked', '{"lint":[],"solve":{"answer":"$9 : 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rice to water = 4 : 9 = 4 to 9 = 4/9. 9 : 4 is reversed.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9645d82f-26df-4893-8934-0bfdfb60500b', 'NC26.6.RPR.1', 2, 'numeric', 'Writing a ratio in different notations', 'The ratio of wins to losses is written $\frac{9}{4}$. For every 4 losses, how many wins are there?', '[]', '9', '9', 'In the fraction, the top is the number of wins and the bottom is the number of losses. So there are 9 wins for every 4 losses.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wins/losses = 9/4: 9 wins for every 4 losses.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99336bf4-16e6-40b3-bbe2-5e52cf5ec019', 'NC26.6.RPR.1', 2, 'choice', 'Writing a ratio in different notations', 'A bag has 5 red and 7 green marbles. Which shows the ratio of green marbles to all the marbles?', '["7 to 12","7 to 5","5 to 12","12 to 7"]', '7 to 12', NULL, 'All the marbles: $5 + 7 = 12$. The green marbles come first, so the ratio is 7 to 12. (7 to 5 compares green to red.)', 'checked', '{"lint":[],"solve":{"answer":"7 to 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 12; green to all = 7 to 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
