VALUES ('904d5029-bf72-4f66-ab6b-970b33899334', 'NC26.6.RPR.1', 2, 'numeric', 'Unit ratio (amount per 1)', 'A hose fills 45 liters in 6 minutes. How many liters does it fill in 1 minute?', '[]', '7.5', '45/6', 'Divide: $45 \div 6 = 7.5$ liters in 1 minute.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 / 6 = 7.5 liters.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
