INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a03a84da-ece6-4363-8ee4-2264e68f93a5', 'NC26.6.RPR.2', 1, 'choice', 'Converting units with ratio reasoning', 'A box of books weighs 64 ounces. There are 16 ounces in 1 pound. How many pounds does the box weigh?', '["48","1024","4","80"]', '4', '64/16', 'Every 16 ounces make 1 pound, so divide: $64 \div 16 = 4$ pounds. (48 subtracts, 1024 multiplies and 80 adds.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 / 16 = 4 pounds.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
