INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa443e9f-9454-4534-8ae6-8abaf291c96c', 'NC26.6.RPR.2', 1, 'choice', 'Independent and dependent variables', 'Ben earns 8 dollars for each hour he works. The amount he earns depends on the number of hours he works. Which quantity is the independent variable?', '["The amount of money Ben earns","The pay of 8 dollars per hour","Both are independent variables","The number of hours Ben works"]', 'The number of hours Ben works', NULL, 'The independent variable is the one that is chosen or changes on its own: the hours worked. The money earned depends on it, so it is the dependent variable. The 8 dollars per hour does not change.', 'checked', '{"lint":[],"solve":{"answer":"The number of hours Ben works","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Earnings depend on hours, so hours is the independent variable.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2d33278-6839-4889-9902-980ead9628b6', 'NC26.6.RPR.2', 1, 'choice', 'Independent and dependent variables', 'A car travels at a steady 50 miles per hour. The equation $d = 50t$ gives the distance $d$, in miles, after $t$ hours. Which variable is the dependent variable?', '["$t$, the time","$d$, the distance","$50$, the speed","Neither variable"]', '$d$, the distance', NULL, 'The distance depends on how long the car travels, so $d$ is the dependent variable and $t$ is the independent variable. The speed 50 is a fixed number, not a variable.', 'checked', '{"lint":[],"solve":{"answer":"$d$, the distance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 50t: distance depends on time, so d is dependent.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
