INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9563bc2-8b8a-46a1-a7f6-cbdb23a0aee2', 'NC26.6.RPR.2', 1, 'numeric', 'Finding the whole from a part and a percent', 'The band has 20 sixth graders. That is 50% of all the sixth graders in the school. How many sixth graders are in the school?', '[]', '40', '20/50*100', '20 is half of the sixth graders, so the whole group is twice as many: $20 \times 2 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 is 50% (half), so whole = 40.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44fb0c65-79fc-499b-85b4-50e361feb0c6', 'NC26.6.RPR.2', 1, 'numeric', 'Finding the whole from a part and a percent', 'Tara has read 8 pages of her book, which is 10% of the book. How many pages are in the whole book?', '[]', '80', '8/10*100', '10% is one tenth of the book, so the whole book is 10 times as long: $8 \times 10 = 80$ pages.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 is 10%, so 100% = 80 pages.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f291abd-3efa-4758-bf76-430ff5180ed0', 'NC26.6.RPR.2', 1, 'choice', 'Finding the whole from a part and a percent', 'A jar is 25% full when it has 5 cups of water in it. How many cups of water does the jar hold when it is full?', '["1.25","20","30","125"]', '20', '5*100/25', '25% is one fourth, so the full jar holds 4 times as much: $5 \times 4 = 20$ cups.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 cups is 25% (one quarter), so full = 20 cups.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8533f33e-9e3e-4033-bbb0-dc6a4cabd16b', 'NC26.6.RPR.2', 1, 'numeric', 'Finding the percent from a part and a whole', 'A bag has 20 marbles, and 5 of them are green. What percent of the marbles are green?', '[]', '25', '5/20*100', '$\frac{5}{20} = \frac{25}{100}$, so 25% of the marbles are green.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/20 = 25/100 = 25%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
