INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('773352b5-c620-4d17-9b5f-585ef4b7ced1', 'NC26.6.RPR.2', 1, 'numeric', 'Finding the percent from a part and a whole', 'A tray has 10 cookies. 3 of them are chocolate. What percent of the cookies are chocolate?', '[]', '30', '3/10*100', '$\frac{3}{10} = \frac{30}{100}$, so 30% of the cookies are chocolate.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 = 30/100 = 30%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
