INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf761273-2e4a-4fa3-920b-197f9474a91e', 'NC26.6.RPR.2', 2, 'choice', 'Finding a part (percent of a price)', 'A jacket costs 40 dollars. It is on sale for 15% off. How many dollars does the sale take off the price?', '["6","25","15","34"]', '6', '15/100*40', '15% of 40 is $\frac{15}{100} \times 40 = 6$. So the sale takes off 6 dollars. (The sale price would be 40 - 6 = 34 dollars, but the question asks for the amount taken off.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15% of 40 = 0.15 x 40 = 6 dollars off (sale price would be 34).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1633c6ed-129d-471c-bba9-64ad7801c162', 'NC26.6.RPR.2', 2, 'choice', 'Independent and dependent variables', 'A plant is 5 centimeters tall and grows 2 centimeters each day. The equation $h = 5 + 2d$ gives its height $h$, in centimeters, after $d$ days. Which statement is correct?', '["The height $h$ is the independent variable, because it is the larger number.","The number of days $d$ is the dependent variable, because it changes each day.","The height $h$ is the dependent variable, because it depends on the number of days.","Both $h$ and $d$ are independent variables, because both can be any number."]', 'The height $h$ is the dependent variable, because it depends on the number of days.', NULL, 'The height is found from the number of days, so the height $h$ depends on $d$. That makes $h$ the dependent variable and $d$ the independent variable.', 'checked', '{"lint":[],"solve":{"answer":"The height $h$ is the dependent variable, because it depends on the number of days.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 5 + 2d: d (days) is chosen/independent; h depends on d, so h is the dependent variable. Other options give wrong roles or wrong reasons.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ea067fc-a7fe-457a-b50b-cfa0d36163fb', 'NC26.6.RPR.2', 2, 'numeric', 'Ratio table: finding a missing value', 'A ratio table shows that 4 boxes of apples weigh 6 pounds. At this rate, how many pounds do 10 boxes of apples weigh?', '[]', '15', '6*10/4', 'Half of 4 boxes is 2 boxes, which weigh 3 pounds. 10 boxes is $4 + 4 + 2$ boxes, so the weight is $6 + 6 + 3 = 15$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 boxes : 6 lb = 2 : 3. 10 boxes = 5 x 2, so 5 x 3 = 15 lb.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c226b27-8e1c-410b-bbb5-e58eeed68413', 'NC26.6.RPR.2', 2, 'choice', 'Ratio table: finding a missing value', 'A ratio table lists three rows of (liters of paint, square meters covered): the first is 2 and 18, the second is 5 and a missing number, and the third is 10 and 90. What is the missing number?', '["21","45","36","9"]', '45', '5*18/2', 'Each liter covers $18 \div 2 = 9$ square meters, so 5 liters cover $5 \times 9 = 45$ square meters. (The number 9 is the amount for 1 liter, and 21 comes from adding 3 to 18.) This also fits the third row, since 10 liters cover 90.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/2 = 9 sq m per liter; 90/10 = 9 too. 5 liters -> 45.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b20af9b-734a-4d96-b272-98664df3211a', 'NC26.6.RPR.2', 2, 'numeric', 'Ratio table: finding a missing value', 'A ratio table for filling a pool has two rows. One row is 3 minutes and 24 gallons. The other row has a missing number of minutes and 72 gallons. How many minutes are in the missing row?', '[]', '9', '3*72/24', '72 gallons is $72 \div 24 = 3$ times as much as 24 gallons, so it takes 3 times as long: $3 \times 3 = 9$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/3 = 8 gal per min. 72/8 = 9 minutes.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2249e1c1-03f7-4a38-89bf-96581672f337', 'NC26.6.RPR.2', 2, 'numeric', 'Equivalent ratios in a context', 'Dee makes green paint by mixing 3 parts blue with 4 parts yellow. She uses 12 cups of yellow. How many cups of blue does she use?', '[]', '9', '12/4*3', '12 cups of yellow is $12 \div 4 = 3$ times the 4 parts, so she needs 3 times the 3 parts of blue: $3 \times 3 = 9$ cups.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue:yellow = 3:4. 12 yellow = 4 x 3, so blue = 3 x 3 = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53daef9d-6fe2-4301-829e-38a829e5a0f5', 'NC26.6.RPR.2', 2, 'choice', 'Equivalent ratios in a context', 'Which ratio is NOT equivalent to 6 to 8?', '["7 to 9","3 to 4","9 to 12","12 to 16"]', '7 to 9', NULL, '6 to 8 simplifies to 3 to 4. Both 9 to 12 and 12 to 16 also simplify to 3 to 4, but 7 to 9 does not (it is already in simplest form and is a different ratio).', 'checked', '{"lint":[],"solve":{"answer":"7 to 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6:8 = 3:4 = 12:16 = 9:12. 7:9 is not equivalent (7/9 != 3/4).","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cbde212-4b1e-4fa4-b7d0-490a823f4941', 'NC26.6.RPR.2', 2, 'numeric', 'Equivalent ratios in a context', 'The ratio of red marbles to blue marbles in a bag is 1 to 3. There are 24 marbles in all. How many marbles are red?', '[]', '6', '24/(1+3)*1', '1 part red and 3 parts blue make 4 equal parts in all. Each part is $24 \div 4 = 6$ marbles, so 6 marbles are red.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 3 = 4 parts; 24/4 = 6 per part; red = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1976c96-1130-4de4-b8ac-dda271ea18c5', 'NC26.6.RPR.2', 2, 'numeric', 'Double number line or graph of a ratio', 'A double number line pairs hours worked (top) with dollars earned (bottom). The top marks are 0, 2, 4 and 6, and the bottom marks are 0, 18, 36 and 54. How many hours match 90 dollars?', '[]', '10', '90/18*2', 'Every 2 hours earn 18 dollars, so 1 hour earns 9 dollars. Then 90 dollars takes $90 \div 9 = 10$ hours.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/2 = 9 dollars per hour. 90/9 = 10 hours.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b21eba2-8a54-43e1-be93-ddb3f711a0cd', 'NC26.6.RPR.2', 2, 'numeric', 'Double number line or graph of a ratio', 'The graph of a ratio relationship between feet of ribbon and its cost in dollars contains the points (3, 12) and (5, 20), written as (feet, dollars). What is the cost, in dollars, of 8 feet of ribbon?', '[]', '32', '8*12/3', 'From the point (3, 12), each foot costs $12 \div 3 = 4$ dollars (the point (5, 20) agrees). So 8 feet cost $8 \times 4 = 32$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/3 = 4 and 20/5 = 4 dollars per foot. 8 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b47c35b6-4d98-4d00-bd7a-c46956a3bc6e', 'NC26.6.RPR.2', 2, 'choice', 'Double number line or graph of a ratio', 'The graph of a ratio relationship contains the points (2, 5) and (4, 10), written as (cups of flour, cups of sugar). Which point is also on the graph?', '["(6, 13)","(6, 15)","(6, 12)","(8, 11)"]', '(6, 15)', NULL, 'The sugar is always $\frac{5}{2}$ times the flour. For 6 cups of flour, $6 \times \frac{5}{2} = 15$. So (6, 15) is on the graph. (6, 13) comes from adding 3 to 10, and (6, 12) uses a ratio of 2.', 'checked', '{"lint":[],"solve":{"answer":"(6, 15)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sugar = 2.5 x flour. (6, 15): 6 x 2.5 = 15. (8,11), (6,13), (6,12) fail.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30b94252-a115-42b8-919b-c0e0f7151542', 'NC26.6.RPR.2', 2, 'numeric', 'Converting units with ratio reasoning', 'A pitcher holds 2.5 liters of juice. There are 1000 milliliters in 1 liter. How many milliliters of juice does the pitcher hold?', '[]', '2500', '2.5*1000', 'Each liter is 1000 milliliters, so 2.5 liters is $2.5 \times 1000 = 2500$ milliliters.', 'checked', '{"lint":[],"solve":{"answer":"2500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5 x 1000 = 2500 mL.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0d5a563-879c-45c5-be36-7d425dff7a9b', 'NC26.6.RPR.2', 2, 'choice', 'Converting units with ratio reasoning', 'There are 2 pints in 1 quart and 4 quarts in 1 gallon. How many pints are in 3 gallons?', '["12","6","9","24"]', '24', '3*4*2', '3 gallons is $3 \times 4 = 12$ quarts, and 12 quarts is $12 \times 2 = 24$ pints. (12 stops at quarts, 6 skips the quarts, and 9 adds.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 gal = 12 qt = 24 pints.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7edc0e1c-2b28-4a76-97b1-114949f4981c', 'NC26.6.RPR.2', 2, 'numeric', 'Converting units with ratio reasoning', 'A video is 150 minutes long. There are 60 minutes in 1 hour. How many hours long is the video? Give your answer as a decimal.', '[]', '2.5', '150/60', '$150 \div 60 = 2.5$ hours. Check: 2 hours is 120 minutes and the other 30 minutes is half an hour.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/60 = 2.5 hours.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96ef6f25-7f39-4aa6-814d-4cb156cd2885', 'NC26.6.RPR.2', 2, 'choice', 'Converting units with ratio reasoning', 'A hose delivers 3 liters of water each minute. There are 60 minutes in 1 hour. How many liters of water does the hose deliver in 1 hour?', '["180","63","20","0.05"]', '180', '3*60', 'In 1 hour there are 60 minutes, and the hose delivers 3 liters in each one: $3 \times 60 = 180$ liters. (63 adds, 20 divides 60 by 3, and 0.05 divides 3 by 60.)', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 60 = 180 liters.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6f2cd1c-389a-4aef-805a-431fdf3a9b26', 'NC26.6.RPR.2', 2, 'choice', 'Independent and dependent variables', 'A gym charges a sign-up fee of 20 dollars plus 5 dollars for each visit. The total cost $c$, in dollars, depends on the number of visits $v$. Which equation shows this relationship?', '["$c = 20v + 5$","$c = 25v$","$c = 5v + 20$","$c = v + 25$"]', '$c = 5v + 20$', NULL, 'Each visit costs 5 dollars, so $v$ visits cost $5v$. The sign-up fee of 20 dollars is paid once, so the total is $c = 5v + 20$.', 'checked', '{"lint":[],"solve":{"answer":"$c = 5v + 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = 5 per visit times v plus 20 fee: c = 5v + 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e560cd2-b3bd-4091-bedd-818d2f2dd4c7', 'NC26.6.RPR.2', 2, 'numeric', 'Independent and dependent variables', 'The equation $c = 12 + 3n$ gives the cost $c$, in dollars, of renting skates for $n$ hours: a fee of 12 dollars plus 3 dollars for each hour. What is the cost, in dollars, for 5 hours?', '[]', '27', '12+3*5', 'Put $n = 5$ into the equation: $c = 12 + 3 \times 5 = 12 + 15 = 27$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = 12 + 3 x 5 = 12 + 15 = 27.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
