INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec9a4503-4392-4419-abf2-e27cce64bba8', 'NC26.6.RPR.2', 2, 'choice', 'Independent and dependent variables', 'A bus travels the same number of miles each hour. When the number of hours $h$ is 1, 2, 3 and 4, the total miles $m$ is 45, 90, 135 and 180. Which equation matches these values, with $m$ depending on $h$?', '["$m = h + 44$","$m = 45 + h$","$m = 45h$","$h = 45m$"]', '$m = 45h$', NULL, 'Each hour adds 45 miles, and $m$ is 45 times $h$ every time: $45 \times 3 = 135$. The equation $m = 45h$ fits. The others fail, for example $m = 45 + h$ gives 47 when $h = 2$.', 'checked', '{"lint":[],"solve":{"answer":"$m = 45h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m/h = 45 each time, so m = 45h. m = 45 + h gives 46 at h=1; h = 45m reversed; m = h + 44 gives 46 at h=2.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bec55c9b-760e-4ea0-8783-380960f4291f', 'NC26.6.RPR.2', 2, 'choice', 'Percent as a rate per 100', 'Which fraction in simplest form is the same as 40%?', '["$\\frac{4}{5}$","$\\frac{1}{40}$","$\\frac{3}{5}$","$\\frac{2}{5}$"]', '$\frac{2}{5}$', NULL, '40% is $\frac{40}{100}$. Divide the top and bottom by 20 to get $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40% = 40/100 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('516c49e3-43f7-4987-88f7-8a125e156110', 'NC26.6.RPR.2', 2, 'numeric', 'Percent as a rate per 100', 'In a survey, 9 out of every 25 people chose pears. At the same rate, how many out of every 100 people would choose pears?', '[]', '36', '9*100/25', '100 is 4 times 25, so multiply 9 by 4: $9 \times 4 = 36$ out of every 100 (which is 36%).', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/25 = 36/100 (x4). 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e65d79a-d3a3-498a-bf0d-17bd5c4e03de', 'NC26.6.RPR.2', 2, 'numeric', 'Percent as a rate per 100', 'The sales tax in a town is 6%. As a decimal, what number is the same as 6%? Give your answer as a decimal.', '[]', '0.06', '6/100', '6% means 6 per 100, which is $\frac{6}{100} = 0.06$.', 'checked', '{"lint":[],"solve":{"answer":"0.06","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6% = 6/100 = 0.06.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed73772c-2e6f-4bd6-8620-eaeae396fd67', 'NC26.6.RPR.2', 2, 'choice', 'Finding a part: percent of a quantity', 'The bill at a restaurant is 60 dollars. Zoe leaves a 15% tip. How many dollars is the tip?', '["9","4","45","900"]', '9', '60*15/100', '10% of 60 is 6 and 5% is 3, so 15% is $6 + 3 = 9$ dollars. (4 divides 60 by 15, 45 subtracts, and 900 multiplies without dividing by 100.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% of 60 = 6, 5% = 3, 15% = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9403893e-bedb-4f10-a5f5-f0a16f845c91', 'NC26.6.RPR.2', 2, 'numeric', 'Finding a part: percent of a quantity', 'A school has 480 students. 35% of them take the bus. How many students take the bus?', '[]', '168', '480*35/100', '35% of 480 is $\frac{35}{100} \times 480 = 0.35 \times 480 = 168$ students.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% = 48, 30% = 144, 5% = 24; 35% = 168.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f345b8e9-8df8-4c3e-8ddb-6c8107c2986b', 'NC26.6.RPR.2', 2, 'choice', 'Finding a part: percent of a quantity', 'A water bottle holds 64 ounces. It is 75% full. How many ounces of water are in the bottle?', '["16","48","75","4800"]', '48', '64*75/100', '75% is three fourths, and $64 \div 4 = 16$, so $3 \times 16 = 48$ ounces. (16 is only one fourth.)', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"75% of 64 = 3/4 x 64 = 48.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
