INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91fdbd7b-b9a3-4631-8f67-7034f4c35d30', 'NC26.6.RPR.2', 2, 'choice', 'Finding a part: percent of a quantity', 'In a class of 28 students, 25% are left-handed. How many students are left-handed?', '["21","3","53","7"]', '7', '28*25/100', '25% is one fourth, so $28 \div 4 = 7$ students are left-handed. (21 is the number who are not, 3 subtracts and 53 adds.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% of 28 = 28/4 = 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
