INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3740168e-1635-4a30-904a-968e39c391ac', 'NC26.6.RPR.2', 2, 'numeric', 'Finding a part: percent of a quantity', 'A test has 45 questions. Kim answered 80% of them correctly. How many questions did she answer correctly?', '[]', '36', '45*80/100', '80% of 45 is $0.8 \times 45 = 36$ questions.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80% of 45 = 0.8 x 45 = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
