INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc9d649a-cf1b-4d01-956c-ac649903ffae', 'NC26.6.RPR.2', 2, 'numeric', 'Finding the whole from a part and a percent', 'A store sold 18 bikes this week. That was 30% of all the bikes in the store. How many bikes were in the store?', '[]', '60', '18/30*100', '30% of the bikes is 18, so 10% is $18 \div 3 = 6$ bikes. The whole is 100%, which is $6 \times 10 = 60$ bikes.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 is 30%, so 10% = 6, 100% = 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
