INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f170949-ed3c-4b35-9148-e26652fe7227', 'NC26.6.RPR.2', 2, 'choice', 'Finding the whole from a part and a percent', 'A sweater is on sale for 12 dollars off. This is 20% of the original price. What was the original price, in dollars?', '["2.4","60","32","240"]', '60', '12/20*100', '20% is one fifth of the price, so the whole price is 5 times 12: $12 \times 5 = 60$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 is 20% (1/5), so original = 12 x 5 = 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d95da7d-995d-42e9-8306-5863e6f78750', 'NC26.6.RPR.2', 2, 'choice', 'Finding the whole from a part and a percent', 'The school band has 45 students. That is 15% of all the students at the school. How many students are at the school?', '["300","3","6.75","30"]', '300', '45/15*100', '15% of the students is 45, so 5% is $45 \div 3 = 15$. The whole school is 100%, which is $15 \times 20 = 300$ students. (3 forgets to multiply by 100.)', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 is 15%, so 5% = 15, 100% = 300.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
