INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd2cb2a6-7f64-4c9d-9b9f-e2272499bba7', 'NC26.6.RPR.2', 2, 'choice', 'Finding the percent from a part and a whole', 'A basketball player made 18 of her 24 free throws. What percent of her free throws did she make?', '["25%","18%","75%","6%"]', '75%', NULL, '$\frac{18}{24} = \frac{3}{4} = \frac{75}{100}$, so she made 75%. (25% is the part she missed.)', 'checked', '{"lint":[],"solve":{"answer":"75%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 3/4 = 75%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
