INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84a0f1be-9dd1-46e3-b99d-08b98fdbf8d2', 'NC26.6.RPR.2', 3, 'choice', 'Finding the percent from a part and a whole', 'Pat got 34 questions right on a 40-question quiz. What percent of the questions did Pat get wrong?', '["85%","15%","6%","34%"]', '15%', NULL, 'Pat missed $40 - 34 = 6$ questions. $\frac{6}{40} = \frac{15}{100}$, so 15% were wrong. (85% is the percent right.)', 'checked', '{"lint":[],"solve":{"answer":"15%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wrong = 40 - 34 = 6. 6/40 = 15/100 = 15%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('402dcfc2-09a2-4c32-81c7-520a45165ae5', 'NC26.6.RPR.2', 3, 'choice', 'Finding the percent from a part and a whole', 'Of 300 students, 120 chose pizza, 75 chose tacos and the rest chose salad. What percent of the students chose salad?', '["40%","25%","35%","65%"]', '35%', NULL, '$120 + 75 = 195$ students chose pizza or tacos, so $300 - 195 = 105$ chose salad. $\frac{105}{300} = \frac{35}{100}$, which is 35%. (40% chose pizza, 25% tacos and 65% chose something other than salad.)', 'checked', '{"lint":[],"solve":{"answer":"35%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Salad = 300 - 120 - 75 = 105. 105/300 = 35/100 = 35%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('867ee23e-e0a4-401e-8ee7-bf0f89f9a85d', 'NC26.6.RPR.2', 3, 'numeric', 'Finding the percent from a part and a whole', 'Marco ran 10 miles last week and 8 miles this week. This week''s distance is what percent of last week''s distance?', '[]', '80', '8/10*100', 'Compare this week to last week (the whole): $\frac{8}{10} = \frac{80}{100}$, so this week''s distance is 80% of last week''s.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/10 = 80/100 = 80%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c140fcea-3ff3-4e51-94a7-093b90111a1e', 'NC26.6.RPR.2', 3, 'numeric', 'Finding the percent from a part and a whole', 'A choir has 60 singers. 21 of them are in grade 6 and 15 are in grade 7. The rest are in grade 8. What percent of the singers are in grade 8?', '[]', '40', '(60-21-15)/60*100', '$60 - 21 - 15 = 24$ singers are in grade 8. $\frac{24}{60} = \frac{2}{5} = \frac{40}{100}$, so 40% are in grade 8.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 8 = 60 - 21 - 15 = 24. 24/60 = 40/100 = 40%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5a43c38-fcbb-4bdf-9dc9-0f991545931e', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 12 and 18?', '[]', '6', NULL, 'Factors of 12: 1, 2, 3, 4, 6, 12. Factors of 18: 1, 2, 3, 6, 9, 18. The greatest factor in both lists is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2^2 x 3, 18 = 2 x 3^2. GCF = 2 x 3 = 6.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5d3a8d3-3aec-46ed-aaf5-76f9e6565e31', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple', 'What is the least common multiple of 4 and 6?', '[]', '12', NULL, 'Multiples of 4: 4, 8, 12, 16, ... Multiples of 6: 6, 12, 18, ... The smallest number in both lists is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4: 4, 8, 12; of 6: 6, 12. LCM = 12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
