INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2ada9f7-58b0-4dd2-bf38-a7eca420c162', 'NC26.6.ANR.1', 1, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 20 written with an exponent?', '["$2 \\times 10$","$4 \\times 5$","$2^2 \\times 5$","$2 \\times 5^2$"]', '$2^2 \times 5$', NULL, '$20 = 2 \times 2 \times 5 = 2^2 \times 5$. The options $2 \times 10$ and $4 \times 5$ use numbers that are not prime, and $2 \times 5^2$ equals 50.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 = 2 x 2 x 5 = 2^2 x 5. 4 x 5 and 2 x 10 are not prime factorizations; 2 x 5^2 = 50.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdda5851-3396-40f6-b4ed-b317fbab78d8', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'The factors of 8 are 1, 2, 4 and 8. The factors of 12 are 1, 2, 3, 4, 6 and 12. What is the greatest factor that 8 and 12 share?', '[]', '4', NULL, 'The factors in both lists are 1, 2 and 4. The greatest of them is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common factors of 8 and 12: 1, 2, 4. Greatest 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90640374-f42b-41b3-a86f-d8ecf0f7da01', 'NC26.6.ANR.1', 1, 'choice', 'Greatest common factor of two numbers', 'Which is the greatest common factor of 16 and 24?', '["4","8","2","48"]', '8', '8', 'The factors of 16 are 1, 2, 4, 8, 16 and the factors of 24 are 1, 2, 3, 4, 6, 8, 12, 24. The common factors are 1, 2, 4 and 8, and the greatest is 8. (4 and 2 are common factors but not the greatest, and 48 is a common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 = 2^4, 24 = 2^3 x 3. GCF = 8.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1505d3cb-e3ab-41e2-8e3a-2843cc43e002', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'What is the largest number that divides evenly into both 9 and 27?', '[]', '9', NULL, '9 divides evenly into 9 ($9 \div 9 = 1$) and into 27 ($27 \div 9 = 3$). No larger number divides 9 evenly, so the answer is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 divides 27, so GCF(9, 27) = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a85d3e5-ca60-4939-a415-a13cb38346a1', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'Find the greatest common factor of 20 and 30.', '[]', '10', NULL, 'The factors of 20 are 1, 2, 4, 5, 10, 20. The factors of 30 are 1, 2, 3, 5, 6, 10, 15, 30. The common factors are 1, 2, 5 and 10, so the greatest is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 = 2^2 x 5, 30 = 2 x 3 x 5. GCF = 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
