INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e72eb08b-1835-4c9c-92ab-9dc14da0b414', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor in a problem', 'Mia has 8 red beads and 12 blue beads. She makes identical bracelets using all of the beads, with the same number of red beads and the same number of blue beads on each bracelet. What is the greatest number of bracelets she can make?', '[]', '4', NULL, 'The number of bracelets must divide both 8 and 12, so it is a common factor. The greatest common factor of 8 and 12 is 4. With 4 bracelets, each has 2 red beads and 3 blue beads.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bracelets must divide 8 and 12; GCF = 4 (2 red, 3 blue each).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
