INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35cff7a2-ed32-40e0-8dfa-16d1d0385993', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple of two numbers', 'Which is the least common multiple of 3 and 9?', '["27","18","3","9"]', '9', '9', '9 is a multiple of 3 ($3 \times 3 = 9$) and of 9, and no smaller number is a multiple of 9. So the least common multiple is 9. (27 and 18 are common multiples, but not the least. 3 is not a multiple of 9.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is a multiple of 3, so LCM = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf0b5201-6c87-4ab0-b771-4c2baaecab93', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple of two numbers', 'What is the least common multiple of 6 and 8?', '["48","24","14","2"]', '24', '24', 'Multiples of 6: 6, 12, 18, 24, 30, ... Multiples of 8: 8, 16, 24, 32, ... The first one in both lists is 24. (48 is also a common multiple but not the least; 14 is the sum; 2 is the greatest common factor.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 2 x 3, 8 = 2^3. LCM = 2^3 x 3 = 24.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
