INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9327c6b6-c7ca-420d-94d0-b3c52cd0a1e0', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple in a problem', 'Light A blinks every 2 seconds and light B blinks every 3 seconds. They just blinked together. In how many seconds will they next blink together?', '[]', '6', NULL, 'Light A blinks at 2, 4, 6, ... seconds and light B at 3, 6, 9, ... seconds. The first time in both lists is 6 seconds.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(2, 3) = 6 seconds.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
