INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e26a5e6-613d-42ee-8217-329ef17077a9', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple in a problem', 'A drum is hit every 5 beats and a bell rings every 10 beats. At the start they sound together. After how many beats do they next sound together?', '[]', '10', NULL, 'The drum sounds on beats 5, 10, 15, ... and the bell on beats 10, 20, ... The first beat in both is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(5, 10) = 10 beats.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
