INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3475a0f-0658-4194-8dac-7d72dec3242d', 'NC26.6.ANR.1', 1, 'numeric', 'Prime factorization in exponent form', 'Ben splits 24 into 4 and 6 to start a factor tree. Then he splits 4 into 2 and 2, and 6 into 2 and 3. How many times does the prime 2 appear in the prime factorization of 24?', '[]', '3', NULL, 'The primes at the ends of the tree are 2, 2, 2 and 3. The prime 2 appears 3 times, so $24 = 2^3 \times 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 2 x 2 x 2 x 3; the prime 2 appears 3 times.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e6ad400-1055-46d5-84b1-0bb7f0a503c7', 'NC26.6.ANR.1', 1, 'choice', 'Reading and evaluating exponent form', 'What is the value of $2^4$?', '["8","6","16","32"]', '16', '2^4', '$2^4$ means 4 factors of 2: $2 \times 2 \times 2 \times 2 = 16$. (8 is $2 \times 4$, 6 is $2 + 4$, and 32 is five factors of 2.)', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^4 = 2 x 2 x 2 x 2 = 16.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64589576-c40b-430b-975c-380277db1ed2', 'NC26.6.ANR.1', 1, 'choice', 'Reading and evaluating exponent form', 'Which expression is the same as $5^3$?', '["$5 \\times 3$","$5 \\times 5 \\times 5$","$3 \\times 3 \\times 3 \\times 3 \\times 3$","$5 + 5 + 5$"]', '$5 \times 5 \times 5$', NULL, 'The exponent 3 tells how many times the base 5 is used as a factor, so $5^3 = 5 \times 5 \times 5$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 5 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^3 = 5 x 5 x 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
