INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9f13cf8-a2f4-437d-8aec-cd4836402e8d', 'NC26.6.ANR.1', 1, 'choice', 'Using prime factorizations to find the GCF or LCM', 'Since $14 = 2 \times 7$ and $35 = 5 \times 7$, what is the greatest common factor of 14 and 35?', '["2","5","70","7"]', '7', '7', 'The only prime they share is 7, so the greatest common factor is 7. (2 and 5 each belong to only one number, and 70 is the least common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared prime: 7. GCF = 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
