INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d75fd3e5-b1cf-4b1a-a70f-f3eee2f595f4', 'NC26.6.ANR.1', 1, 'choice', 'Factoring a sum with the distributive property', 'Which expression equals $6 + 9$ written as a common factor times a sum?', '["$3(2 + 3)$","$3(2 + 9)$","$2(3 + 9)$","$6(1 + 9)$"]', '$3(2 + 3)$', NULL, '3 is a factor of both 6 and 9: $6 = 3 \times 2$ and $9 = 3 \times 3$. So $6 + 9 = 3(2 + 3)$, which is $3 \times 5 = 15$. Check that the others do not equal 15: 33, 24 and 60.', 'checked', '{"lint":[],"solve":{"answer":"$3(2 + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 9 = 3 x 2 + 3 x 3 = 3(2 + 3) = 15. Others: 2(12) = 24, 3(11) = 33, 6(10) = 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bac13449-021a-4235-8de8-93d45bf1cf33', 'NC26.6.ANR.1', 1, 'numeric', 'Factoring a sum with the distributive property', 'What number makes this true? $8 + 12 = 4(2 + ?)$', '[]', '3', '12/4', '$8 = 4 \times 2$ and $12 = 4 \times 3$, so $8 + 12 = 4(2 + 3)$. The missing number is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 12 = 4 x 2 + 4 x 3 = 4(2 + 3). ? = 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8032dfea-fee2-4fa8-bb0e-d235c598ed05', 'NC26.6.ANR.1', 1, 'numeric', 'Factoring a sum with the distributive property', 'You rewrite $10 + 15$ as the greatest common factor times a sum. What is the greatest common factor?', '[]', '5', NULL, 'The factors of 10 are 1, 2, 5, 10 and the factors of 15 are 1, 3, 5, 15. The greatest common factor is 5, so $10 + 15 = 5(2 + 3)$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(10, 15) = 5: 10 + 15 = 5(2 + 3).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
