INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('822b2dfd-08b1-46ac-acc4-a7b3d58c7715', 'NC26.6.ANR.1', 1, 'choice', 'Factoring a sum with the distributive property', 'Which sum is equal to $4(3 + 5)$?', '["$12 + 5$","$7 + 9$","$4 + 15$","$12 + 20$"]', '$12 + 20$', NULL, 'The distributive property multiplies 4 by each number inside: $4 \times 3 + 4 \times 5 = 12 + 20 = 32$. The others equal 17, 16 and 19.', 'checked', '{"lint":[],"solve":{"answer":"$12 + 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(3 + 5) = 12 + 20 = 32.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
