INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0502874-c168-4ade-b80c-c580ddb880ff', 'NC26.6.ANR.1', 1, 'choice', 'Relating factors and multiples', 'Which number is a multiple of both 3 and 4?', '["18","8","12","7"]', '12', '3*4', '12 is $3 \times 4$ and $4 \times 3$, so it is a multiple of both. 18 is a multiple of 3 only, 8 is a multiple of 4 only, and 7 is neither.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 3 x 4 = 4 x 3. 8 not multiple of 3; 18 not of 4; 7 neither.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f9cbb55-2ec8-478c-aeb8-057014502738', 'NC26.6.ANR.1', 1, 'choice', 'Relating factors and multiples', 'Which statement is true?', '["6 is a factor of 30","30 is a factor of 6","6 is a multiple of 30","12 is a factor of 30"]', '6 is a factor of 30', NULL, '$30 = 6 \times 5$, so 6 is a factor of 30 (and 30 is a multiple of 6). The reverse statements are false, and 30 cannot be divided evenly by 12.', 'checked', '{"lint":[],"solve":{"answer":"6 is a factor of 30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 / 6 = 5, so 6 is a factor of 30. 12 does not divide 30; the others are reversed.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ded606bc-363e-461a-8bfb-a462060892bf', 'NC26.6.ANR.1', 1, 'numeric', 'Relating factors and multiples', 'What is the smallest multiple of 7 that is greater than 30?', '[]', '35', '5*7', 'Multiples of 7: 7, 14, 21, 28, 35. 28 is less than 30 and 35 is the first that is greater, so the answer is 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 7: 28, 35. Smallest above 30 is 35.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e79c317-511c-4242-927d-3d996f8b1792', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 36 and 48?', '[]', '12', NULL, '$36 = 2^2 \times 3^2$ and $48 = 2^4 \times 3$. Both contain $2^2$ and $3$, so the greatest common factor is $2^2 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 2^2 x 3^2, 48 = 2^4 x 3. GCF = 2^2 x 3 = 12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53a6d10d-53e2-49d2-a282-44485c0a4e31', 'NC26.6.ANR.1', 2, 'numeric', 'Least common multiple in context', 'A bus leaves a stop every 12 minutes and a tram leaves every 15 minutes. Both leave at 8:00 a.m. How many minutes later will they next leave at the same time?', '[]', '60', NULL, 'The answer is the least common multiple of 12 and 15. Multiples of 15: 15, 30, 45, 60. Of these, 60 is the first that is also a multiple of 12 ($12 \times 5 = 60$). So they next leave together 60 minutes later.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(12, 15): 12 = 2^2 x 3, 15 = 3 x 5, LCM = 60 minutes.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfe2618e-78a1-4571-af34-a1610e53d1a0', 'NC26.6.ANR.1', 2, 'choice', 'Factoring a sum with the distributive property', 'Which expression shows $24 + 36$ rewritten as the greatest common factor times a sum?', '["$12(2 + 3)$","$12(24 + 36)$","$6(4 + 5)$","$12(2 + 36)$"]', '$12(2 + 3)$', NULL, 'The greatest common factor of 24 and 36 is 12. Divide each number by 12: $24 \div 12 = 2$ and $36 \div 12 = 3$. So $24 + 36 = 12(2 + 3)$. Check: $12 \times 5 = 60$ and $24 + 36 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"$12(2 + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(24, 36) = 12. 24 + 36 = 12(2 + 3) = 60. 6(4 + 5) also equals 60 but 6 is not the GCF; others do not equal 60.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77fc89fc-eb2e-4352-b8d3-9bd9ed2ebda2', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor of two numbers', 'What is the largest number that divides evenly into both 45 and 60?', '[]', '15', NULL, 'Factors of 45: 1, 3, 5, 9, 15, 45. Factors of 60: 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60. The greatest one in both lists is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 = 3^2 x 5, 60 = 2^2 x 3 x 5. GCF = 15.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfa596d3-1d77-4a75-b8cc-7636bff11e54', 'NC26.6.ANR.1', 2, 'choice', 'Greatest common factor of two numbers', 'Which pair of numbers has a greatest common factor of 6?', '["12 and 24","12 and 18","9 and 15","10 and 15"]', '12 and 18', NULL, 'The greatest common factor of 12 and 18 is 6. The other pairs have greatest common factors of 12, 3 and 5.', 'checked', '{"lint":[],"solve":{"answer":"12 and 18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(12,24) = 12; (10,15) = 5; (9,15) = 3; (12,18) = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
