INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30243777-7561-4768-b964-beb466649640', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor of two numbers', 'Find the greatest common factor of 32 and 56.', '[]', '8', NULL, 'Factors of 32: 1, 2, 4, 8, 16, 32. Factors of 56: 1, 2, 4, 7, 8, 14, 28, 56. The greatest one in both lists is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32 = 2^5, 56 = 2^3 x 7. GCF = 8.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
