INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97210452-52ee-46ec-938f-a14646221638', 'NC26.6.ANR.1', 2, 'choice', 'Greatest common factor in a problem', 'Lena has 36 red stickers and 54 blue stickers. She makes equal groups using all of the stickers, with the same number of red stickers and the same number of blue stickers in every group. What is the greatest number of groups she can make?', '["9","6","18","90"]', '18', '18', 'The number of groups must divide both 36 and 54, so the greatest is their greatest common factor. $36 = 2^2 \times 3^2$ and $54 = 2 \times 3^3$, so the GCF is $2 \times 3^2 = 18$. (9 and 6 are smaller common factors, and 90 is the sum.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 2^2 x 3^2, 54 = 2 x 3^3. GCF = 18 groups (2 red, 3 blue each).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59e518a7-a54c-4625-a5b8-8072e987ee3e', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor in a problem', 'A club has 40 sixth graders and 64 seventh graders. The club forms teams so that each team has the same number of sixth graders and the same number of seventh graders, and everyone is on a team. What is the greatest number of teams?', '[]', '8', NULL, 'The number of teams must divide both 40 and 64. The greatest common factor of 40 and 64 is 8, so there are 8 teams, each with 5 sixth graders and 8 seventh graders.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 = 2^3 x 5, 64 = 2^6. GCF = 8 teams.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b74682a0-1fc3-45ea-89fa-ea174b2b5b11', 'NC26.6.ANR.1', 2, 'numeric', 'Least common multiple of two numbers', 'What is the smallest number that is a multiple of both 9 and 12?', '[]', '36', NULL, 'Multiples of 12: 12, 24, 36, ... Multiples of 9: 9, 18, 27, 36, ... The first number in both lists is 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 3^2, 12 = 2^2 x 3. LCM = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
