INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cff58bac-2ae5-4413-9d36-6baa7b889f81', 'NC26.6.ANR.1', 2, 'choice', 'Least common multiple of two numbers', 'Which is the least common multiple of 6 and 10?', '["60","30","16","2"]', '30', '30', 'Multiples of 10: 10, 20, 30, ... The first one that is also a multiple of 6 is 30. (60 is a common multiple but not the least, 16 is the sum, and 2 is the greatest common factor.)', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 2 x 3, 10 = 2 x 5. LCM = 30.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
