INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f67e7487-b52d-420f-8cc0-c6e6aa4153b9', 'NC26.6.ANR.1', 2, 'numeric', 'Least common multiple of two numbers', 'Find the least common multiple of 7 and 9.', '[]', '63', '7*9', '7 and 9 have no common factor other than 1, so their least common multiple is their product: $7 \times 9 = 63$.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 and 9 share no factor; LCM = 63.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
