INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62dd89ae-5744-4176-8e7e-ddabdb657dc8', 'NC26.6.ANR.1', 2, 'choice', 'Least common multiple in a problem', 'Two runners start together at the start line of a loop. Rani runs one lap in 6 minutes and Ty runs one lap in 9 minutes. After how many minutes will they next be together at the start line?', '["18","54","3","15"]', '18', '18', 'They are together at the start line at times that are multiples of 6 and of 9. The least common multiple of 6 and 9 is 18 minutes. (54 is the product, 3 is the greatest common factor, and 15 is the sum.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(6, 9) = 18 minutes.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
