INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('feb3310b-4177-418e-a6aa-8d4b36779080', 'NC26.6.ANR.2', 1, 'choice', 'Adding fractions and mixed numbers', 'Add $\frac{3}{10} + \frac{1}{5}$. Which is the sum?', '["$\\frac{1}{2}$","$\\frac{4}{15}$","$\\frac{4}{10}$","$\\frac{3}{50}$"]', '$\frac{1}{2}$', NULL, 'Write $\frac{1}{5}$ as $\frac{2}{10}$. Then $\frac{3}{10} + \frac{2}{10} = \frac{5}{10}$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 = 2/10; 3/10 + 2/10 = 5/10 = 1/2. Only 1/2 equals 5/10 among the options.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
