VALUES ('f522c47a-407b-43d8-b2db-dc1b996a7aaf', 'NC26.6.ANR.2', 1, 'numeric', 'Subtracting fractions and mixed numbers', 'What is $\frac{7}{8} - \frac{1}{4}$?', '[]', '5/8', '7/8-1/4', 'Write $\frac{1}{4}$ as $\frac{2}{8}$. Then $\frac{7}{8} - \frac{2}{8} = \frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 2/8; 7/8 - 2/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
