INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('208f9ca3-21b7-4e9a-8ccd-a65bcad95e56', 'NC26.6.ANR.2', 1, 'choice', 'Subtracting fractions and mixed numbers', 'Subtract: $\frac{2}{3} - \frac{1}{6}$. Which is the difference?', '["$\\frac{1}{6}$","$\\frac{1}{2}$","$\\frac{5}{6}$","$\\frac{1}{3}$"]', '$\frac{1}{2}$', NULL, 'Write $\frac{2}{3}$ as $\frac{4}{6}$. Then $\frac{4}{6} - \frac{1}{6} = \frac{3}{6}$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6; 4/6 - 1/6 = 3/6 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
