INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06aa967b-343f-4ef4-8613-503c44502717', 'NC26.6.ANR.2', 1, 'numeric', 'Subtracting fractions and mixed numbers', 'Subtract $1\frac{1}{4}$ from $3\frac{3}{4}$. What is the difference?', '[]', '2 1/2', '(3+3/4)-(1+1/4)', 'Subtract the whole numbers: 3 - 1 = 2. Subtract the fractions: $\frac{3}{4} - \frac{1}{4} = \frac{2}{4} = \frac{1}{2}$. The difference is $2\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 3/4 - 1 1/4 = 2 2/4 = 2 1/2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
