VALUES ('fd5a8d02-ac5f-4f54-ba86-99c8c2359bfa', 'NC26.6.ANR.2', 1, 'numeric', 'Multiplying fractions', 'Find $\frac{2}{3}$ of 12.', '[]', '8', '2/3*12', 'One third of 12 is 4, so $\frac{2}{3}$ of 12 is 4 x 2 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 3 = 4; 4 x 2 = 8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
