INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1163e8ad-f67e-4734-a40c-2c5462f02475', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a whole number by a fraction', 'Mr. Lee has 4 pounds of rice and puts $\frac{1}{2}$ pound in each bag. How many bags can he fill?', '[]', '8', '4/(1/2)', 'Each pound fills 2 bags, so 4 pounds fill 4 x 2 = 8 bags. In symbols, $4 \div \frac{1}{2} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (1/2) = 4 x 2 = 8 bags.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
