INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce93fbf7-7c30-4ca2-8999-8cca4cfdc0a0', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a whole number by a fraction', 'Divide: $6 \div \frac{1}{3}$.', '[]', '18', '6/(1/3)', 'There are 3 thirds in each whole, so 6 wholes hold 6 x 3 = 18 thirds. So $6 \div \frac{1}{3} = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (1/3) = 6 x 3 = 18.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
