INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1d5c706-a2f7-44cc-82a8-8e3be6ccd863', 'NC26.6.ANR.2', 1, 'choice', 'Dividing a whole number by a fraction', 'A tank has 5 liters of juice. How many $\frac{1}{3}$-liter cups can be filled from it?', '["8","2","$\\frac{5}{3}$","15"]', '15', '5/(1/3)', 'Each liter fills 3 cups, so 5 liters fill 5 x 3 = 15 cups. That is $5 \div \frac{1}{3} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 / (1/3) = 5 x 3 = 15 cups.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
