INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee237c5d-3824-45a3-bc3b-1d17caf5124f', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a fraction by a whole number', 'What is $\frac{6}{7} \div 3$?', '[]', '2/7', '(6/7)/3', 'Share 6 sevenths into 3 equal groups: 2 sevenths in each group. So $\frac{6}{7} \div 3 = \frac{2}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"2/7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/7 / 3 = 6/21 = 2/7.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
