INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40040ae8-9b5c-4012-b2fb-cc9d54f8c548', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a fraction by a fraction', 'Find the quotient: $\frac{2}{3} \div \frac{1}{6}$.', '[]', '4', '(2/3)/(1/6)', '$\frac{2}{3} = \frac{4}{6}$. There are 4 sixths in 4 sixths, so the answer is 4: $\frac{2}{3} \div \frac{1}{6} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 / (1/6) = 2/3 x 6 = 12/3 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
