VALUES ('cc34ebd9-1217-4550-ad46-5fd6abfde07d', 'NC26.6.ANR.2', 1, 'numeric', 'One-step fraction word problem', 'A ribbon is $\frac{5}{6}$ meter long. Tom cuts off $\frac{1}{3}$ meter. How many meters of ribbon are left?', '[]', '1/2', '5/6-1/3', '$\frac{1}{3} = \frac{2}{6}$. Then $\frac{5}{6} - \frac{2}{6} = \frac{3}{6} = \frac{1}{2}$ meter.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 2/6; 5/6 - 2/6 = 3/6 = 1/2 meter.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
