INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb897176-60cd-4511-abe7-95a4c1b700d9', 'NC26.6.ANR.2', 1, 'choice', 'Checking reasonableness by estimating', 'Which is the best estimate of $5\frac{1}{8} - 2\frac{7}{8}$?', '["3","8","7","2"]', '2', NULL, '$5\frac{1}{8}$ is about 5 and $2\frac{7}{8}$ is about 3. Then 5 - 3 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/8 is about 5, 2 7/8 is about 3; 5 - 3 = 2. Exact: 2 1/4, nearest option 2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
