INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d6e030b-db47-4066-93d8-39a5a5f6a8ff', 'NC26.6.ANR.2', 1, 'choice', 'Checking reasonableness by estimating', 'Without multiplying, which product is greater than 6?', '["$6 \\times 1\\frac{1}{4}$","$6 \\times \\frac{1}{2}$","$6 \\times \\frac{3}{4}$","$6 \\times \\frac{5}{8}$"]', '$6 \times 1\frac{1}{4}$', NULL, 'Multiplying 6 by a number less than 1 gives less than 6. Only $1\frac{1}{4}$ is greater than 1, so $6 \times 1\frac{1}{4}$ is greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 1\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying 6 by a number greater than 1 gives more than 6; only 1 1/4 is greater than 1 (5/8, 1/2, 3/4 are less than 1).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
