INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b8a6853-5768-4982-a0b6-158ce395e032', 'NC26.6.ANR.2', 1, 'numeric', 'Finding a missing number in a fraction equation', 'What is the value of n in $n + \frac{1}{6} = \frac{5}{6}$?', '[]', '2/3', '5/6-1/6', 'Take $\frac{1}{6}$ away from $\frac{5}{6}$: $n = \frac{5}{6} - \frac{1}{6} = \frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 5/6 - 1/6 = 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
