INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('732f1541-2b12-4274-a509-cf79febd403b', 'NC26.6.ANR.2', 1, 'choice', 'Finding a missing number in a fraction equation', 'Which fraction makes this true: $\frac{1}{2} + ? = \frac{7}{8}$?', '["$\\frac{5}{8}$","$\\frac{6}{8}$","$\\frac{3}{8}$","$\\frac{1}{4}$"]', '$\frac{3}{8}$', NULL, '$\frac{1}{2} = \frac{4}{8}$. The missing part is $\frac{7}{8} - \frac{4}{8} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? = 7/8 - 1/2 = 7/8 - 4/8 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
