INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfe31ba1-dc21-4027-aa23-1f5889443760', 'NC26.6.ANR.2', 2, 'numeric', 'Adding fractions and mixed numbers', 'Find the sum: $2\frac{2}{3} + 1\frac{3}{4}$.', '[]', '4 5/12', '(2+2/3)+(1+3/4)', 'Whole numbers: 2 + 1 = 3. Fractions: $\frac{2}{3} = \frac{8}{12}$ and $\frac{3}{4} = \frac{9}{12}$, so $\frac{8}{12} + \frac{9}{12} = \frac{17}{12} = 1\frac{5}{12}$. The total is 3 + $1\frac{5}{12}$ = $4\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"4 5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 1 = 3; 2/3 + 3/4 = 8/12 + 9/12 = 17/12 = 1 5/12; total 4 5/12.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
