INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5b8e542-a962-4dbc-95eb-dbce0795c6f7', 'NC26.6.ANR.2', 2, 'choice', 'Adding fractions and mixed numbers', 'Mia adds $\frac{3}{8} + \frac{5}{12}$. Which is the sum?', '["$\\frac{8}{20}$","$\\frac{19}{24}$","$\\frac{14}{24}$","$\\frac{19}{48}$"]', '$\frac{19}{24}$', NULL, 'Use 24ths: $\frac{3}{8} = \frac{9}{24}$ and $\frac{5}{12} = \frac{10}{24}$. Then $\frac{9}{24} + \frac{10}{24} = \frac{19}{24}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{19}{24}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 24: 3/8 = 9/24, 5/12 = 10/24; sum 19/24.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
