VALUES ('af862611-1761-4653-ae96-14e8e24aad30', 'NC26.6.ANR.2', 2, 'choice', 'Subtracting fractions and mixed numbers', 'Which is the value of $3 - 1\frac{3}{5}$?', '["$2\\frac{3}{5}$","$2\\frac{2}{5}$","$1\\frac{3}{5}$","$1\\frac{2}{5}$"]', '$1\frac{2}{5}$', NULL, 'Regroup 3 as $2\frac{5}{5}$. Then $2\frac{5}{5} - 1\frac{3}{5} = 1\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 = 2 5/5; 2 5/5 - 1 3/5 = 1 2/5.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
