VALUES ('7b27a8c8-e869-4bf8-bbf3-345f1d85dc42', 'NC26.6.ANR.2', 2, 'choice', 'Dividing a fraction by a fraction', 'What is $\frac{3}{4} \div \frac{9}{10}$?', '["$\\frac{27}{40}$","$\\frac{5}{6}$","$1\\frac{1}{5}$","$\\frac{3}{5}$"]', '$\frac{5}{6}$', NULL, 'Multiply by the flip: $\frac{3}{4} \times \frac{10}{9} = \frac{30}{36} = \frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 / (9/10) = 3/4 x 10/9 = 30/36 = 5/6.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
