INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2961a45c-b33b-42c3-831e-6252d881e973', 'NC26.6.ANR.2', 2, 'choice', 'Interpreting a quotient', 'Which situation is modeled by $\frac{3}{4} \div \frac{1}{8}$?', '["$\\frac{3}{4}$ cup of juice is shared equally by 8 people. How much does each person get?","What is $\\frac{1}{8}$ of $\\frac{3}{4}$ cup of juice?","A ribbon $\\frac{3}{4}$ meter long is cut into pieces $\\frac{1}{8}$ meter long. How many pieces are there?","How much is left when $\\frac{1}{8}$ cup is taken from $\\frac{3}{4}$ cup of juice?"]', 'A ribbon $\frac{3}{4}$ meter long is cut into pieces $\frac{1}{8}$ meter long. How many pieces are there?', NULL, 'Cutting a length into equal pieces and asking how many pieces is division of the length by the piece size: $\frac{3}{4} \div \frac{1}{8} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"A ribbon $\\frac{3}{4}$ meter long is cut into pieces $\\frac{1}{8}$ meter long. How many pieces are there?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 / (1/8) asks how many 1/8s are in 3/4: the ribbon cut into 1/8-meter pieces. Sharing by 8 is 3/4 / 8; 1/8 of 3/4 is multiplication; taking 1/8 away is subtraction.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('141ab9e0-cfa3-493e-9ca0-7acc63303087', 'NC26.6.ANR.2', 2, 'choice', 'Interpreting a quotient', 'Joel has $\frac{7}{8}$ gallon of paint. Each fence panel needs $\frac{1}{4}$ gallon. He finds $\frac{7}{8} \div \frac{1}{4} = 3\frac{1}{2}$. What does the $\frac{1}{2}$ in $3\frac{1}{2}$ tell him?', '["He has $\\frac{1}{2}$ gallon of paint left over","He has enough paint for 3 whole panels and half of another","Each panel needs $\\frac{1}{2}$ gallon of paint","He will use up half of his paint"]', 'He has enough paint for 3 whole panels and half of another', NULL, 'The quotient counts panels: 3 whole panels and half of another panel. (3 panels use $\frac{3}{4}$ gallon, leaving $\frac{1}{8}$ gallon, which is half of a panel.)', 'checked', '{"lint":[],"solve":{"answer":"He has enough paint for 3 whole panels and half of another","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 / (1/4) = 7/8 x 4 = 7/2 = 3 1/2 panels. The 1/2 is half a panel''s worth: 3 panels use 3/4 gal, leaving 1/8 gal = half of 1/4. Not 1/2 gallon left over.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ded7721-c8ca-443a-9eb8-d47657a0ed5e', 'NC26.6.ANR.2', 2, 'numeric', 'Interpreting a quotient', 'A ribbon is $\frac{5}{6}$ meter long. It is cut into pieces that are each $\frac{1}{4}$ meter long. How many full pieces can be cut?', '[]', '3', NULL, '$\frac{5}{6} \div \frac{1}{4} = \frac{5}{6} \times 4 = \frac{20}{6} = 3\frac{1}{3}$. Only whole pieces count, so there are 3 full pieces. (3 pieces use $\frac{3}{4}$ meter; 4 pieces would need 1 meter.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 / (1/4) = 5/6 x 4 = 20/6 = 3 1/3, so 3 full pieces (3 x 1/4 = 3/4 m, 1/12 m left).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('364e98e5-9f5e-4b24-9606-7e1c6191fac5', 'NC26.6.ANR.2', 2, 'numeric', 'One-step fraction word problem', 'Ben ran $2\frac{3}{4}$ miles on Monday and $1\frac{5}{6}$ miles on Tuesday. How many miles did he run in all?', '[]', '4 7/12', '(2+3/4)+(1+5/6)', '$\frac{3}{4} = \frac{9}{12}$ and $\frac{5}{6} = \frac{10}{12}$. Fractions: $\frac{19}{12} = 1\frac{7}{12}$. Wholes: 2 + 1 = 3. Total: 3 + $1\frac{7}{12}$ = $4\frac{7}{12}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"4 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 1 = 3; 3/4 + 5/6 = 9/12 + 10/12 = 19/12 = 1 7/12; total 4 7/12 miles.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08093b59-dd7e-49b3-849c-61a2e3040200', 'NC26.6.ANR.2', 2, 'choice', 'One-step fraction word problem', 'A rope is $6\frac{1}{2}$ meters long. A piece $2\frac{3}{4}$ meters long is cut off. How long is the rest of the rope?', '["$3\\frac{3}{4}$","$4\\frac{1}{4}$","$9\\frac{1}{4}$","$3\\frac{1}{4}$"]', '$3\frac{3}{4}$', NULL, '$6\frac{1}{2} = \frac{26}{4}$ and $2\frac{3}{4} = \frac{11}{4}$. Then $\frac{26}{4} - \frac{11}{4} = \frac{15}{4} = 3\frac{3}{4}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 1/2 = 6 2/4 = 5 6/4; 5 6/4 - 2 3/4 = 3 3/4 meters.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50b9a45d-a484-41d0-9360-f4d128cc14d0', 'NC26.6.ANR.2', 2, 'numeric', 'Multi-step fraction word problem', 'Dana has $5\frac{1}{4}$ meters of ribbon. She uses $1\frac{1}{2}$ meters for a gift and cuts the rest into pieces $\frac{3}{4}$ meter long. How many pieces does she cut?', '[]', '5', '((5+1/4)-(1+1/2))/(3/4)', 'Ribbon left: $5\frac{1}{4} - 1\frac{1}{2} = 3\frac{3}{4}$ meters. Pieces: $3\frac{3}{4} \div \frac{3}{4} = \frac{15}{4} \div \frac{3}{4} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/4 - 1 1/2 = 5 1/4 - 1 2/4 = 3 3/4 = 15/4 m. 15/4 / (3/4) = 5 pieces.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
