INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e9196b-2b9c-4465-b7a4-5f02a15ac4df', 'NC26.6.ANR.2', 3, 'choice', 'Adding fractions and mixed numbers', 'What is $5\frac{5}{6} + 3\frac{7}{9}$?', '["$8\\frac{12}{15}$","$9\\frac{1}{3}$","$10\\frac{11}{18}$","$9\\frac{11}{18}$"]', '$9\frac{11}{18}$', NULL, 'Use 18ths: $\frac{5}{6} = \frac{15}{18}$ and $\frac{7}{9} = \frac{14}{18}$. Fractions: $\frac{29}{18} = 1\frac{11}{18}$. Wholes: 5 + 3 = 8. Total: 8 + $1\frac{11}{18}$ = $9\frac{11}{18}$.', 'checked', '{"lint":[],"solve":{"answer":"$9\\frac{11}{18}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 = 8; 5/6 + 7/9 = 15/18 + 14/18 = 29/18 = 1 11/18; total 9 11/18.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
