VALUES ('237d3320-df41-4c62-867b-e60870f0fed3', 'NC26.6.ANR.2', 3, 'choice', 'Dividing a fraction by a fraction', 'What is $\frac{11}{12} \div \frac{5}{6}$?', '["$\\frac{55}{72}$","$\\frac{10}{11}$","$\\frac{1}{10}$","$1\\frac{1}{10}$"]', '$1\frac{1}{10}$', NULL, '$\frac{11}{12} \times \frac{6}{5} = \frac{66}{60} = \frac{11}{10} = 1\frac{1}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{1}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/12 / (5/6) = 11/12 x 6/5 = 66/60 = 11/10 = 1 1/10.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
