INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82f1ffc2-d631-4a82-9add-443d62dc06d8', 'NC26.6.ANR.2', 3, 'numeric', 'Interpreting a quotient', 'Ellen has $3\frac{1}{2}$ cups of rice. Each serving uses $\frac{3}{4}$ cup. How many full servings can she make?', '[]', '4', NULL, '$3\frac{1}{2} \div \frac{3}{4} = \frac{7}{2} \times \frac{4}{3} = \frac{28}{6} = 4\frac{2}{3}$. Only whole servings count, so she can make 4 full servings.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 1/2 / (3/4) = 7/2 x 4/3 = 28/6 = 4 2/3, so 4 full servings.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95f247fa-be77-4a4c-90f5-14bad87a600b', 'NC26.6.ANR.2', 3, 'choice', 'Interpreting a quotient', 'Ravi has 4 meters of ribbon and cuts pieces $\frac{3}{4}$ meter long. He finds $4 \div \frac{3}{4} = 5\frac{1}{3}$. What does the $\frac{1}{3}$ tell him?', '["There are 5 full pieces, and the leftover ribbon is $\\frac{1}{3}$ meter long","Each piece is $5\\frac{1}{3}$ meters long","There are 5 full pieces, and the leftover ribbon is $\\frac{1}{3}$ of another piece","There are 5 full pieces, and $\\frac{1}{3}$ of the ribbon is not used"]', 'There are 5 full pieces, and the leftover ribbon is $\frac{1}{3}$ of another piece', NULL, '5 pieces use $\frac{15}{4}$ meters, leaving $\frac{1}{4}$ meter. That is one third of a $\frac{3}{4}$-meter piece, so the $\frac{1}{3}$ counts a part of a piece, not meters.', 'checked', '{"lint":[],"solve":{"answer":"There are 5 full pieces, and the leftover ribbon is $\\frac{1}{3}$ of another piece","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (3/4) = 16/3 = 5 1/3. 5 pieces use 15/4 m, leaving 1/4 m, which is 1/3 of a 3/4-m piece. Not 1/3 meter, not 1/3 of the ribbon (1/4 of 4 m is 1/16).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16e529fe-0313-43a2-8042-8edad4a40ab9', 'NC26.6.ANR.2', 3, 'choice', 'Interpreting a quotient', 'Which of these is NOT a situation that $\frac{2}{3} \div \frac{1}{6}$ describes?', '["How many $\\frac{1}{6}$-meter pieces can be cut from a rope $\\frac{2}{3}$ meter long?","A $\\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?","$\\frac{2}{3}$ of a pizza is cut into slices that are each $\\frac{1}{6}$ of the whole pizza. How many slices?","How many $\\frac{1}{6}$-cup scoops fit in $\\frac{2}{3}$ cup of rice?"]', 'A $\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?', NULL, 'The other three ask how many $\frac{1}{6}$s fit in $\frac{2}{3}$, which is $\frac{2}{3} \div \frac{1}{6} = 4$. Sharing $\frac{2}{3}$ among 6 people is $\frac{2}{3} \div 6 = \frac{1}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"A $\\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rope pieces, pizza slices of 1/6 each, and 1/6-cup scoops all ask how many 1/6s are in 2/3 (= 4). Sharing 2/3 liter among 6 people is 2/3 / 6 = 1/9, not 2/3 / (1/6).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d8df86e-48a8-49d6-9802-81d92efa96ef', 'NC26.6.ANR.2', 3, 'choice', 'One-step fraction word problem', 'A board $8\frac{3}{4}$ feet long is cut into 5 equal pieces. How long is each piece?', '["$43\\frac{3}{4}$","$3\\frac{3}{4}$","$1\\frac{3}{4}$","$1\\frac{3}{5}$"]', '$1\frac{3}{4}$', NULL, '$8\frac{3}{4} = \frac{35}{4}$. Then $\frac{35}{4} \div 5 = \frac{35}{20} = \frac{7}{4} = 1\frac{3}{4}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 3/4 = 35/4; 35/4 / 5 = 35/20 = 7/4 = 1 3/4 feet.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ca4810b-fde8-432d-b0d9-75b0986b3c4a', 'NC26.6.ANR.2', 3, 'numeric', 'Multi-step fraction word problem', 'Lena had $\frac{3}{4}$ of a tank of gas. She used $\frac{2}{5}$ of a tank on Monday and $\frac{1}{4}$ of a tank on Tuesday. What fraction of a tank is left?', '[]', '1/10', '3/4-2/5-1/4', 'Use 20ths: $\frac{15}{20} - \frac{8}{20} - \frac{5}{20} = \frac{2}{20} = \frac{1}{10}$ of a tank.', 'checked', '{"lint":[],"solve":{"answer":"1/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 20: 3/4 = 15/20, 2/5 = 8/20, 1/4 = 5/20; 15/20 - 8/20 - 5/20 = 2/20 = 1/10.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ba41f06-c2f9-441c-99bf-75d1aea2af7d', 'NC26.6.ANR.2', 3, 'numeric', 'Multi-step fraction word problem', 'A recipe for 12 muffins uses $2\frac{1}{4}$ cups of flour. Rosa has $6\frac{3}{4}$ cups of flour. How many muffins can she make if she uses all of her flour for this recipe?', '[]', '36', '((6+3/4)/(2+1/4))*12', '$6\frac{3}{4} \div 2\frac{1}{4} = \frac{27}{4} \div \frac{9}{4} = 3$, so she can make the recipe 3 times. 3 x 12 = 36 muffins.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 3/4 / 2 1/4 = 27/4 / 9/4 = 3 batches; 3 x 12 = 36 muffins.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
