INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d0ec8c8-43cb-48fa-af03-2bafd3ef4412', 'NC26.6.ANR.2', 3, 'numeric', 'Multi-step fraction word problem', 'A garden is $4\frac{1}{2}$ meters long and $2\frac{2}{3}$ meters wide. Tom plants one packet of seeds for every $\frac{3}{4}$ square meter. How many packets does he need?', '[]', '16', '((9/2)*(8/3))/(3/4)', 'Area: $4\frac{1}{2} \times 2\frac{2}{3} = \frac{9}{2} \times \frac{8}{3} = 12$ square meters. Packets: $12 \div \frac{3}{4} = 12 \times \frac{4}{3} = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 9/2 x 8/3 = 72/6 = 12 sq m. 12 / (3/4) = 12 x 4/3 = 16 packets.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39c59ffd-6686-4fca-956d-4e3b287927c2', 'NC26.6.ANR.2', 3, 'choice', 'Multi-step fraction word problem', 'Priya has 10 yards of ribbon. She uses $2\frac{1}{3}$ yards for each of 3 gifts. How many yards of ribbon are left?', '["$7\\frac{2}{3}$","7","$12\\frac{1}{3}$","3"]', '3', '10-3*(2+1/3)', 'Used: $3 \times 2\frac{1}{3} = 3 \times \frac{7}{3} = 7$ yards. Left: 10 - 7 = 3 yards.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 2 1/3 = 3 x 7/3 = 7 yards used; 10 - 7 = 3 yards left.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
