INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d7806fa-31b6-4e3e-92ee-10f2006eaec4', 'NC26.6.ANR.2', 3, 'choice', 'Multi-step fraction word problem', 'A bag of trail mix has $3\frac{1}{2}$ cups of nuts and $2\frac{1}{4}$ cups of raisins. Jo eats $\frac{1}{3}$ of the mix. How many cups of the mix does Jo eat?', '["$5\\frac{3}{4}$","$1\\frac{11}{12}$","$17\\frac{1}{4}$","$1\\frac{1}{6}$"]', '$1\frac{11}{12}$', NULL, 'Total mix: $3\frac{1}{2} + 2\frac{1}{4} = 5\frac{3}{4} = \frac{23}{4}$ cups. Jo eats $\frac{1}{3} \times \frac{23}{4} = \frac{23}{12} = 1\frac{11}{12}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{11}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mix = 3 1/2 + 2 1/4 = 5 3/4 = 23/4 cups. 1/3 x 23/4 = 23/12 = 1 11/12 cups.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3364ace0-9f3d-49d5-9282-dfacb1fd2287', 'NC26.6.ANR.2', 3, 'choice', 'Checking reasonableness by estimating', 'Which is the best estimate of $8\frac{1}{9} \div 1\frac{9}{10}$?', '["4","16","6","10"]', '4', NULL, '$8\frac{1}{9}$ is about 8 and $1\frac{9}{10}$ is about 2. Then $8 \div 2 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 1/9 is about 8, 1 9/10 is about 2; 8 / 2 = 4. Exact 73/9 x 10/19 = 730/171 = about 4.27.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
