VALUES ('20e6662e-04eb-4dc2-9182-f938816c23ac', 'NC26.6.ANR.3', 1, 'choice', 'Reasoning about decimal operations', 'Without calculating, which division has a quotient greater than 8?', '["$8 \\div 2.5$","$8 \\div 1.6$","$8 \\div 0.5$","$8 \\div 4$"]', '$8 \div 0.5$', NULL, 'Dividing by a number less than 1 gives a quotient greater than the number divided: $8 \div 0.5 = 16$. Dividing by a number greater than 1 gives less than 8.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\div 0.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dividing 8 by a number less than 1 gives more than 8; only 0.5 (8 / 0.5 = 16). Others: 3.2, 5, 2.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
