INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a9b2d59-167f-44e1-8395-741aa6622ed6', 'NC26.6.ANR.3', 2, 'choice', 'Reasoning about decimal operations', 'Sam found $4.8 \times 3.25 = 1.56$. Which statement about his answer is true?', '["It is correct, because multiplying by a decimal always gives a smaller number","It is too small, because $4.8 \\times 3$ is already more than 14","It is too big, because the product must be less than 4.8","It is too big, because 3.25 is greater than 3"]', 'It is too small, because $4.8 \times 3$ is already more than 14', NULL, '$4.8 \times 3 = 14.4$, and 3.25 is more than 3, so the product is more than 14.4. The answer 1.56 has the decimal point in the wrong place; the product is 15.6.', 'checked', '{"lint":[],"solve":{"answer":"It is too small, because $4.8 \\times 3$ is already more than 14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.8 x 3.25 = 15.6, so 1.56 is too small. 4.8 x 3 = 14.4 > 14, which shows this. A, B and C are false.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
