INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173beb18-e94d-4b85-a5cc-6be2678bc4a8', 'NC26.6.ANR.3', 3, 'choice', 'Multi-step decimal word problem', 'A train ticket costs 12.75 dollars. A group of 6 gets 1.50 dollars off each ticket. How many dollars does the group pay in all?', '["75","76.5","11.25","67.5"]', '67.5', '6*(12.75-1.5)', 'Price after the discount: $12.75 - 1.50 = 11.25$ dollars. For 6 tickets: $6 \times 11.25 = 67.50$, which is 67.5 dollars.', 'checked', '{"lint":[],"solve":{"answer":"67.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12.75 - 1.50 = 11.25 per ticket; 6 x 11.25 = 67.50 dollars.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
