INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1d928e6-1b7c-4c8e-a4d8-f8b27c2f9375', 'NC26.6.ANR.4', 2, 'choice', 'Checking reasonableness', 'Dana works out $-12 - 7$ and gets $-5$. Which statement shows that her answer cannot be right?', '["The answer must be between $-12$ and 0.","Subtracting 7 moves left from $-12$, so the answer must be less than $-12$.","The answer must be positive.","The answer must be exactly $-12$."]', 'Subtracting 7 moves left from $-12$, so the answer must be less than $-12$.', NULL, 'Taking away a positive number moves left on the number line, so the result is less than $-12$. The correct value is $-12 - 7 = -19$.', 'checked', '{"lint":[],"solve":{"answer":"Subtracting 7 moves left from $-12$, so the answer must be less than $-12$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-12 - 7 = -19. Subtracting a positive moves left, so the result is below -12; -5 is above -12, so it cannot be right. Other statements are false.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d878ce4-60e0-4a4c-a010-e8adb6abbda0', 'NC26.6.ANR.4', 2, 'numeric', 'Checking reasonableness', 'To check $-19 + 11$, a student rounds each number to the nearest ten and adds. What is the estimate the student gets?', '[]', '-10', '-20+10', '$-19$ rounds to $-20$ and 11 rounds to 10. The estimate is $-20 + 10 = -10$. The exact answer is $-8$, which is close.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-19 rounds to -20; 11 rounds to 10. -20 + 10 = -10.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aed28e50-a224-4be0-9e28-2f8804f59574', 'NC26.6.ANR.4', 2, 'choice', 'Checking reasonableness', 'Sam says $-4 \times (-5)$ is about $-20$. Which statement checks his estimate?', '["His estimate has the wrong sign: the product should be about 20.","His estimate is reasonable, because both numbers are negative.","His estimate is the wrong size: it should be about 9.","His estimate has the wrong sign and the wrong size."]', 'His estimate has the wrong sign: the product should be about 20.', NULL, 'Two negative factors give a positive product, and $4 \times 5 = 20$. So the product is $20$, and his size is right but his sign is wrong.', 'checked', '{"lint":[],"solve":{"answer":"His estimate has the wrong sign: the product should be about 20.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4)(-5) = 20 (neg x neg = pos). Size 20 is right, sign is wrong.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3354af8b-d273-4cdc-b154-4ac59248f622', 'NC26.6.ANR.4', 2, 'numeric', 'Integers in context', 'A hiker stands 12 meters above sea level. She walks down a trail that falls 17 meters. What is her elevation now, in meters?', '[]', '-5', '12-17', 'Falling 17 meters is subtracting 17: $12 - 17 = -5$. She is 5 meters below sea level.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 17 = -5 (5 meters below sea level).","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
