INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('735f06e2-0b58-46a0-aae2-b4edc784eb08', 'NC26.6.ANR.4', 2, 'numeric', 'Integers in context', 'The temperature was $-4$ degrees in the morning and 9 degrees in the afternoon. By how many degrees did it rise?', '[]', '13', '9-(-4)', 'The change is the later value minus the earlier value: $9 - (-4) = 9 + 4 = 13$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - (-4) = 13.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
