INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ded2d6c-69cf-4231-9405-999648771010', 'NC26.6.ANR.4', 2, 'choice', 'Integers in context', 'A team loses 3 points in each of 5 rounds. Which integer shows the team''s total change in score?', '["$15$","$-15$","$-8$","$-2$"]', '$-15$', '5*(-3)', 'Five losses of 3 points: $5 \times (-3) = -15$.', 'checked', '{"lint":[],"solve":{"answer":"$-15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x (-3) = -15.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
