INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4732f02-f87d-420b-aeca-58389179ec58', 'NC26.6.ANR.4', 3, 'numeric', 'Dividing and subtracting integers', 'What is $-12 \div 4 - (-7)$?', '[]', '4', '-12/4+7', 'First divide: $-12 \div 4 = -3$. Then $-3 - (-7) = -3 + 7 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-12 / 4 = -3. -3 - (-7) = -3 + 7 = 4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
