INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e842d582-c7f2-447e-a3a3-e12eb0c70fe2', 'NC26.6.ANR.4', 3, 'numeric', 'Reasoning with integer products and sums', 'Two integers have a product of $-20$ and a sum of $1$. What is the lesser of the two integers?', '[]', '-4', NULL, 'The product is negative, so one integer is positive and one is negative. The factor pairs of 20 are 1 and 20, 2 and 10, 4 and 5. Only 5 and $-4$ have a sum of 1 ($5 + (-4) = 1$), and $5 \times (-4) = -20$. The lesser integer is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor pairs of -20 with sum 1: 5 and -4 (5 x -4 = -20, 5 + -4 = 1). Others: 4,-5 sum -1; 10,-2 sum 8; 2,-10; 20,-1; 1,-20 - none sum 1. Lesser = -4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('503f1810-48db-4ed3-9ca0-3f0f97a7a497', 'NC26.6.ANR.4', 3, 'choice', 'Zero pairs and chip models', 'Nina starts with 2 negative chips and wants to subtract 5 negative chips, as in $-2 - (-5)$. She adds 3 zero pairs and then takes away 5 negative chips. What is left on the mat?', '["3 positive chips","3 negative chips","7 positive chips","5 negative chips"]', '3 positive chips', NULL, 'With 3 zero pairs there are 5 negative chips and 3 positive chips. Taking away the 5 negative chips leaves 3 positive chips, so $-2 - (-5) = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3 positive chips","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 negative + 3 zero pairs = 5 negative and 3 positive. Take away 5 negative: 3 positive remain. Check: -2 - (-5) = 3.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8422ba0-27b4-4bd7-8fa9-5ba75001c967', 'NC26.6.ANR.4', 3, 'numeric', 'Zero pairs and chip models', 'A mat holds 15 chips in all. After every zero pair is removed, 3 negative chips are left. How many positive chips were on the mat?', '[]', '6', '(15-3)/2', 'The 3 leftover negative chips are not in pairs. The other $15 - 3 = 12$ chips are in zero pairs, which is 6 pairs. So there were 6 positive chips (and 9 negative chips).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p + n = 15 and n - p = 3, so 2n = 18, n = 9, p = 6.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
