VALUES ('bfe19e9b-62d4-488f-b0a0-53ecadc78086', 'NC26.6.ANR.4', 3, 'numeric', 'Adding integers', 'What is $-17 + 9 + (-6) + 12$?', '[]', '-2', '-17+9-6+12', 'Add left to right: $-17 + 9 = -8$, then $-8 + (-6) = -14$, then $-14 + 12 = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-17 + 9 = -8; -8 + (-6) = -14; -14 + 12 = -2.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
