INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0633d812-e69c-4c61-ac42-b572bfd69872', 'NC26.6.ANR.4', 3, 'choice', 'Adding integers', 'Which sum has the greatest value?', '["$-9 + 15$","$7 + (-3)$","$-5 + 10$","$-12 + 20$"]', '$-12 + 20$', NULL, 'The sums are $-12 + 20 = 8$, $-9 + 15 = 6$, $7 + (-3) = 4$ and $-5 + 10 = 5$. The greatest is 8.', 'checked', '{"lint":[],"solve":{"answer":"$-12 + 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7+(-3) = 4; -5+10 = 5; -9+15 = 6; -12+20 = 8. Greatest is -12 + 20.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
