INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6c92a4d-530a-429b-82e3-360b7f568942', 'NC26.6.ANR.4', 3, 'choice', 'Subtraction as adding the opposite', 'Which expression does NOT have the same value as $9 - (-4)$?', '["$9 + (-4)$","$9 + 4$","$4 - (-9)$","$-4 - (-17)$"]', '$9 + (-4)$', NULL, '$9 - (-4) = 13$. The expressions $9 + 4$, $4 - (-9) = 13$ and $-4 - (-17) = 13$ all equal 13. But $9 + (-4) = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$9 + (-4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - (-4) = 13. 9+(-4) = 5; 4-(-9) = 13; 9+4 = 13; -4-(-17) = 13. Only 9 + (-4) differs.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2fd0cf5-a5af-416b-a86c-eef54647d530', 'NC26.6.ANR.4', 3, 'numeric', 'Subtraction as adding the opposite', 'Write $-5 - (-12) - 9$ as a sum of three integers, then find its value.', '[]', '-2', '-5+12-9', 'Subtracting $-12$ is adding 12, and subtracting 9 is adding $-9$. So the sum is $-5 + 12 + (-9) = 7 + (-9) = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 + 12 + (-9): -5 + 12 = 7; 7 - 9 = -2.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53e03fbc-cea4-447b-ae43-42a831a8a896', 'NC26.6.ANR.4', 3, 'numeric', 'Subtraction as adding the opposite', 'For what integer $n$ is $-7 - n = -7 + 10$ true?', '[]', '-10', '-10', 'The right side is 3. For $-7 - n$ to equal $-7 + 10$, subtracting $n$ must be the same as adding 10, so $n$ is the opposite of 10, which is $-10$. Check: $-7 - (-10) = 3$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7 - n = -7 + (-n) must equal -7 + 10, so -n = 10, n = -10. Check: -7 - (-10) = 3 = -7 + 10.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
