VALUES ('f5dd452b-176a-4bb3-81fa-772291c79e86', 'NC26.6.ANR.4', 3, 'choice', 'Multiplying integers', 'Which product is the greatest?', '["$(-3)(-6)$","$(-4)(-5)$","$(2)(9)$","$(-2)(-8)$"]', '$(-4)(-5)$', NULL, 'The products are $(-4)(-5) = 20$, $(-3)(-6) = 18$, $(2)(9) = 18$ and $(-2)(-8) = 16$. The greatest is 20.', 'checked', '{"lint":[],"solve":{"answer":"$(-4)(-5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2)(9) = 18; (-2)(-8) = 16; (-4)(-5) = 20; (-3)(-6) = 18. Greatest 20.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
