INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6078650-0776-4e39-b034-369189a30153', 'NC26.6.ANR.4', 3, 'numeric', 'Models for integer operations (number line and groups)', 'On a number line, Ravi starts at 2. He moves 9 units to the left, then 5 units to the right, then 8 units to the left. At what number does he stop?', '[]', '-10', '2-9+5-8', 'Left moves subtract and right moves add: $2 - 9 + 5 - 8$. That is $-7$ after the first move, $-2$ after the second and $-10$ after the third.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 - 9 = -7; -7 + 5 = -2; -2 - 8 = -10.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
