INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc38fb9b-7330-4ac2-bf81-d96bc0d9e7a4', 'NC26.6.ANR.4', 3, 'numeric', 'Checking reasonableness', 'Lena works out $-17 - (-6)$ and gets $-23$. What is the correct answer?', '[]', '-11', '-17+6', 'She added 17 and 6 instead of changing the subtraction into adding 6. Subtracting $-6$ is adding 6: $-17 + 6 = -11$.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-17 - (-6) = -17 + 6 = -11.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
