INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f0f382a-5171-4902-b5c1-34643c8f8f52', 'NC26.6.ANR.4', 3, 'choice', 'Integers in context', 'The temperature changed from $-13$ degrees to 6 degrees. Which statement is true?', '["It rose by 19 degrees.","It fell by 19 degrees.","It rose by 7 degrees.","It fell by 7 degrees."]', 'It rose by 19 degrees.', NULL, 'The change is the new value minus the old: $6 - (-13) = 19$. A positive change means the temperature rose by 19 degrees.', 'checked', '{"lint":[],"solve":{"answer":"It rose by 19 degrees.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 - (-13) = 19, and 6 > -13, so it rose by 19 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
