VALUES ('ca2661ea-02c3-4321-ad50-27555770628a', 'NC26.6.ANR.5', 1, 'choice', 'Inequality statements', 'Choose the true inequality.', '["$-5 < -9$","$5 < -9$","$-9 > 5$","$-5 > -9$"]', '$-5 > -9$', NULL, '$-5$ is to the right of $-9$ on the number line, so $-5 > -9$. A positive number is never less than a negative number.', 'checked', '{"lint":[],"solve":{"answer":"$-5 > -9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 is to the right of -9, so -5 > -9 is true; -9 > 5, -5 < -9, 5 < -9 are false.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
