VALUES ('4729860b-21eb-45d4-82d4-136f7512c003', 'NC26.6.ANR.5', 2, 'choice', 'Equivalent forms of fractions, mixed numbers and decimals', 'Which of these numbers is NOT equal to $\frac{3}{5}$?', '["$0.6$","$\\frac{6}{10}$","$0.35$","$\\frac{9}{15}$"]', '$0.35$', '0.35', '$\frac{3}{5} = \frac{6}{10} = \frac{9}{15} = 0.6$. The number 0.35 is thirty-five hundredths, which is less than $\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$0.35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 0.6 = 6/10 = 9/15. 0.35 is not 0.6.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
