INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e563933-3e16-464a-90fd-287a3e3e9c16', 'NC26.6.ANR.5', 2, 'choice', 'Equivalent forms of fractions, mixed numbers and decimals', 'Which decimal is equal to $4\frac{1}{4}$?', '["$4.14$","$4.25$","$4.4$","$4.025$"]', '$4.25$', '4.25', '$\frac{1}{4} = \frac{25}{100} = 0.25$, so $4\frac{1}{4} = 4.25$.', 'checked', '{"lint":[],"solve":{"answer":"$4.25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 0.25, so 4 1/4 = 4.25.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
