VALUES ('8c755dfc-bed1-4a2e-8443-e53e8201e5ed', 'NC26.6.ANR.5', 2, 'choice', 'Comparing two rational numbers', 'Which of these numbers is the least?', '["$-0.5$","$-\\frac{1}{4}$","$-\\frac{3}{4}$","$-0.2$"]', '$-\frac{3}{4}$', NULL, 'As decimals the numbers are $-0.75$, $-0.5$, $-0.25$ and $-0.2$. The farthest left is $-0.75$, so $-\frac{3}{4}$ is the least.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-0.75, -0.2, -0.5, -0.25: least (farthest left) is -0.75 = -3/4.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
