VALUES ('81207c06-d82c-420a-994b-627935f4b515', 'NC26.6.ANR.5', 2, 'choice', 'Ordering rational numbers', 'Arrange 0.6, 0.06, 0.66 and 0.606 from greatest to least. Which list is correct?', '["$0.66, 0.606, 0.6, 0.06$","$0.66, 0.6, 0.606, 0.06$","$0.06, 0.6, 0.606, 0.66$","$0.606, 0.66, 0.6, 0.06$"]', '$0.66, 0.606, 0.6, 0.06$', NULL, 'In thousandths they are 0.600, 0.060, 0.660 and 0.606. From greatest to least: 0.660, 0.606, 0.600, 0.060.', 'checked', '{"lint":[],"solve":{"answer":"$0.66, 0.606, 0.6, 0.06$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"As thousandths: 0.660, 0.606, 0.600, 0.060. Greatest to least: 0.66, 0.606, 0.6, 0.06.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
