VALUES ('0c34dc28-f2cc-42e8-8d3c-2f5780497f2c', 'NC26.6.ANR.5', 3, 'choice', 'Equivalent forms of fractions, mixed numbers and decimals', 'Which mixed number is equal to 3.125?', '["$3\\frac{1}{4}$","$3\\frac{1}{5}$","$3\\frac{1}{8}$","$3\\frac{1}{125}$"]', '$3\frac{1}{8}$', NULL, '0.125 is $\frac{125}{1000}$, which simplifies to $\frac{1}{8}$. So $3.125 = 3\frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.125 = 1/8, so 3.125 = 3 1/8.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
