VALUES ('ea4b604d-2794-429d-b1cf-95b376ac471a', 'NC26.6.ANR.5', 3, 'choice', 'Ordering rational numbers', 'Place $-\frac{3}{4}$, $-0.8$, $\frac{1}{5}$ and $-0.7$ on a number line from left to right. Which list gives the order?', '["$-0.8, -\\frac{3}{4}, -0.7, \\frac{1}{5}$","$-0.7, -\\frac{3}{4}, -0.8, \\frac{1}{5}$","$-\\frac{3}{4}, -0.8, -0.7, \\frac{1}{5}$","$\\frac{1}{5}, -0.7, -\\frac{3}{4}, -0.8$"]', '$-0.8, -\frac{3}{4}, -0.7, \frac{1}{5}$', NULL, 'As decimals the numbers are $-0.75$, $-0.8$, 0.2 and $-0.7$. From left to right (least to greatest): $-0.8$, $-0.75$, $-0.7$, 0.2.', 'checked', '{"lint":[],"solve":{"answer":"$-0.8, -\\frac{3}{4}, -0.7, \\frac{1}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3/4 = -0.75, 1/5 = 0.2. Left to right: -0.8, -0.75, -0.7, 0.2.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
