INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae99d20e-2bf4-4444-b26a-43c38596af93', 'NC26.6.ANR.5', 3, 'numeric', 'Rational numbers on the number line', 'A point is halfway between $-\frac{1}{2}$ and $\frac{3}{2}$ on a number line. What number is it?', '[]', '1/2', '(-1/2+3/2)/2', 'The halfway point is the average: $\left(-\frac{1}{2} + \frac{3}{2}\right) \div 2 = 1 \div 2 = \frac{1}{2}$. It is 1 unit from each end.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1/2 + 3/2) / 2 = 1 / 2 = 1/2. Check: 1 unit from each end.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
