INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df31cfd4-4cb8-4ba8-80a2-39963399fe23', 'NC26.6.ANR.5', 3, 'numeric', 'Inequality statements', 'How many integers are greater than $-2.5$ and less than 3.2?', '[]', '6', '6', 'The integers are $-2$, $-1$, 0, 1, 2 and 3. That is 6 integers.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Integers from -2 up to 3: -2, -1, 0, 1, 2, 3 = 6.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
