INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e59b2b5-0b7d-4bab-8ff2-646dd6b00dd8', 'NC26.6.ANR.5', 3, 'choice', 'Inequality statements', 'If $a = -3$ and $b = -\frac{1}{2}$, which statement is true?', '["$a > b$, because 3 is greater than $\\frac{1}{2}$.","$a = b$, because both are negative.","$a < b$, because $-3$ is farther to the left.","$a > b$, because $-3$ is farther from 0."]', '$a < b$, because $-3$ is farther to the left.', NULL, '$-3$ is to the left of $-\frac{1}{2}$ on the number line, so $a < b$. Being farther from 0 on the negative side means being less, not greater.', 'checked', '{"lint":[],"solve":{"answer":"$a < b$, because $-3$ is farther to the left.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3 < -0.5 because -3 is farther left. a = b false; a > b false (reasons confuse distance with size).","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('231f5d04-3fcd-4c66-aee5-e0d7e36008c5', 'NC26.6.ANR.5', 3, 'numeric', 'Inequality statements', 'What is the least integer $m$ for which $m > -\frac{7}{2}$ is true?', '[]', '-3', '-3', '$-\frac{7}{2} = -3.5$. The integers greater than $-3.5$ are $-3$, $-2$, $-1$, and so on, and the least is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7/2 = -3.5. Integers greater than -3.5: -3, -2, ... Least is -3.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1aa3992-402c-4aa8-be76-382a74dcc027', 'NC26.6.ANR.5', 3, 'choice', 'Inequality statements', 'Every number $x$ with $x > 5$ also satisfies which inequality?', '["$x > 4$","$x > 6$","$x < 6$","$x < 4$"]', '$x > 4$', NULL, 'A number greater than 5 is also greater than 4, so $x > 4$ always holds. The others can fail: $x = 5.5$ is not greater than 6, $x = 7$ is not less than 6, and no number greater than 5 is less than 4.', 'checked', '{"lint":[],"solve":{"answer":"$x > 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If x > 5 then x > 4. x < 6 fails for x = 7; x < 4 fails always; x > 6 fails for x = 5.5.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1524e3ec-3e4b-426f-a8c5-5157a1e2788e', 'NC26.6.ANR.5', 3, 'choice', 'Opposites', 'Which statement is true for every number $n$?', '["The opposite of $n$ is always negative.","The opposite of the opposite of $n$ is $n$.","The opposite of $n$ is always less than $n$.","$n$ and its opposite are always at different points on a number line."]', 'The opposite of the opposite of $n$ is $n$.', NULL, 'Taking the opposite twice returns you to the starting number. The other statements fail for $n = -2$ (its opposite is positive and greater) and for $n = 0$ (its own opposite).', 'checked', '{"lint":[],"solve":{"answer":"The opposite of the opposite of $n$ is $n$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(-n) = n always. Opposite of a negative is positive; opposite of a negative n is greater than n; n = 0 is its own opposite (same point).","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa51f70-4ed2-41cc-a536-d98aca973f7b', 'NC26.6.ANR.5', 3, 'numeric', 'Opposites', 'What is the sum of $-7.5$ and its opposite?', '[]', '0', '-7.5+7.5', 'The opposite of $-7.5$ is 7.5, and $-7.5 + 7.5 = 0$. A number and its opposite always add to 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7.5 + 7.5 = 0.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
