INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97f6d0a8-0a67-4993-b61e-bba7ddbd1332', 'NC26.6.ANR.5', 3, 'choice', 'The meaning of zero', 'Dara''s balance was 0 dollars. After one deposit and one withdrawal, her balance is 0 dollars again. Which could be true?', '["She deposited 12 dollars and withdrew 21 dollars.","She deposited 12 dollars and withdrew 2 dollars.","She deposited 21 dollars and withdrew 12 dollars.","She deposited 12 dollars and withdrew 12 dollars."]', 'She deposited 12 dollars and withdrew 12 dollars.', NULL, 'The balance returns to 0 only when the deposit and the withdrawal are equal. The other choices leave $-9$, 10 and 9 dollars.', 'checked', '{"lint":[],"solve":{"answer":"She deposited 12 dollars and withdrew 12 dollars.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Back to 0 requires deposit = withdrawal: 12 and 12. Others give 9, -9, 10.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da0e6a6-e957-41a8-8b20-f00ae90d2c11', 'NC26.6.ANR.5', 3, 'numeric', 'The meaning of zero', 'Taking ground level as 0, a kite is at 9 meters and a mole is at $-4$ meters. How many meters apart are they?', '[]', '13', '9-(-4)', 'The kite is 9 meters above 0 and the mole is 4 meters below it. They are $9 + 4 = 13$ meters apart.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - (-4) = 13 (9 above plus 4 below).","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
