INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acaf01bd-59b2-4a58-9cf9-ddf5c09f431d', 'NC26.6.ANR.5', 3, 'choice', 'Absolute value', 'Which list shows $-9$, $4$, $-6$ and $3$ in order from the least absolute value to the greatest absolute value?', '["$-9, -6, 3, 4$","$4, 3, -6, -9$","$3, 4, -6, -9$","$3, 4, -9, -6$"]', '$3, 4, -6, -9$', NULL, 'The absolute values are 9, 4, 6 and 3. From least to greatest: 3, 4, 6, 9, which belong to $3$, $4$, $-6$, $-9$.', 'checked', '{"lint":[],"solve":{"answer":"$3, 4, -6, -9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Absolute values: |-9| = 9, |4| = 4, |-6| = 6, |3| = 3. Least to greatest: 3, 4, -6, -9.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
