INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53f4c6a7-40c0-435a-a745-999eda13ee92', 'NC26.6.ANR.5', 3, 'choice', 'Absolute value', 'Choose the true statement about absolute values.', '["$|-\\frac{3}{4}| > |-0.8|$","$|-\\frac{1}{3}| < |-0.3|$","$|0.2| > |-0.25|$","$|-1.5| = |1\\frac{1}{2}|$"]', '$|-1.5| = |1\frac{1}{2}|$', NULL, 'Both $|-1.5|$ and $|1\frac{1}{2}|$ equal 1.5. The others are false: $0.75 < 0.8$, $\frac{1}{3} > 0.3$ and $0.2 < 0.25$.', 'checked', '{"lint":[],"solve":{"answer":"$|-1.5| = |1\\frac{1}{2}|$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.75 > 0.8 false; 0.2 > 0.25 false; 1.5 = 1.5 true; 0.333 < 0.3 false.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
