INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e68f37-8cbc-48e5-bd7f-a65174a954ff', 'NC26.6.ANR.6', 2, 'numeric', 'Whole-number exponents', 'Find the value of $2^4 + 3^2$.', '[]', '25', '2^4+3^2', '$2^4 = 2 \times 2 \times 2 \times 2 = 16$ and $3^2 = 3 \times 3 = 9$. Then $16 + 9 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^4 = 16, 3^2 = 9; 16 + 9 = 25.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
