INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acb3821b-03a8-4e4d-9bb5-dddb2c283418', 'NC26.6.ANR.6', 2, 'numeric', 'Order of operations', 'Evaluate $36 \div (4 + 5) \times 3$.', '[]', '12', '36/(4+5)*3', 'Parentheses first: $4 + 5 = 9$. Then work from left to right: $36 \div 9 = 4$ and $4 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 5 = 9; then left to right: 36 / 9 = 4; 4 x 3 = 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
