VALUES ('8352f813-bf3b-4e07-845c-a1e88fa7808f', 'NC26.6.ANR.6', 2, 'choice', 'Order of operations', 'What is the value of $18 - 2 \times 5 + 1$?', '["$81$","$6$","$9$","$7$"]', '$9$', '18-2*5+1', 'Multiply first: $2 \times 5 = 10$. Then work from left to right: $18 - 10 = 8$ and $8 + 1 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 5 = 10; 18 - 10 = 8; 8 + 1 = 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
