VALUES ('afa5707b-3b53-4b97-8ee7-9b76c379883c', 'NC26.6.ANR.6', 2, 'choice', 'Translating words to expressions', 'Which expression means "the sum of 6 times a number $p$ and 4"?', '["$6 + 4p$","$10p$","$6(p + 4)$","$6p + 4$"]', '$6p + 4$', NULL, '"6 times a number $p$" is $6p$, and the sum of that and 4 is $6p + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6p + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 times p is 6p; sum with 4 is 6p + 4.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
