INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5969def-e141-48ed-97f4-4a357e7b8e25', 'NC26.6.ANR.6', 2, 'choice', 'Translating words to expressions', 'Which expression means "a number $n$ divided by 4, increased by 7"?', '["$\\frac{n}{4 + 7}$","$4n + 7$","$\\frac{n}{4} + 7$","$\\frac{4}{n} + 7$"]', '$\frac{n}{4} + 7$', NULL, '"A number $n$ divided by 4" is $\frac{n}{4}$. "Increased by 7" means add 7 to it: $\frac{n}{4} + 7$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{n}{4} + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n divided by 4 is n/4; increased by 7 gives n/4 + 7.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
