INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d969e75f-5180-4897-a241-1f8951bab7c9', 'NC26.6.ANR.6', 2, 'choice', 'Translating words to expressions', 'Which phrase matches the expression $5(n - 2)$?', '["the difference of five times a number $n$ and 2","five times the difference of a number $n$ and 2","five more than the difference of a number $n$ and 2","the difference of a number $n$ and 10"]', 'five times the difference of a number $n$ and 2', NULL, 'The parentheses show that $n - 2$ is found first, and then it is multiplied by 5: five times the difference of $n$ and 2. "The difference of five times $n$ and 2" would be $5n - 2$.', 'checked', '{"lint":[],"solve":{"answer":"five times the difference of a number $n$ and 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(n - 2) is 5 times the difference n - 2.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea84a8eb-aeaf-4364-bc1d-3efe04984876', 'NC26.6.ANR.6', 2, 'choice', 'Parts of an expression', 'The expression $3(n + 8)$ is a product. What are its two factors?', '["3 and $n$","$3n$ and 8","3 and $n + 8$","$n$ and 8"]', '3 and $n + 8$', NULL, 'The expression multiplies 3 by the whole quantity $n + 8$. So the two factors are 3 and $n + 8$.', 'checked', '{"lint":[],"solve":{"answer":"3 and $n + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(n + 8) is 3 times the quantity (n + 8): factors 3 and n + 8.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
