VALUES ('6b999301-ba83-483e-8a0b-6c20b17cf5e3', 'NC26.6.ANR.6', 2, 'choice', 'Evaluating algebraic expressions', 'What is the value of $\frac{y + 10}{4}$ when $y = 6$?', '["$8.5$","$16$","$4$","$1.5$"]', '$4$', '(6+10)/4', 'Replace $y$ with 6. The numerator is $6 + 10 = 16$, and $16 \div 4 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6 + 10)/4 = 16/4 = 4.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
