INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b37f671-e0ed-459e-905f-d49502948903', 'NC26.6.ANR.6', 2, 'numeric', 'Equivalent expressions and properties', 'Find the number $n$ that makes $4(x + 5)$ and $4x + n$ equivalent for every value of $x$.', '[]', '20', '4*5', 'By the distributive property, $4(x + 5) = 4x + 4 \times 5 = 4x + 20$. So $n = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 5) = 4x + 20; n = 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6116d02-4218-4303-9d78-9324d67c0e25', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions and properties', 'Which expression is NOT equivalent to $2(3 + x)$?', '["$6 + 2x$","$3 + 2x$","$2x + 6$","$x + x + 6$"]', '$3 + 2x$', NULL, '$2(3 + x) = 6 + 2x$. The expressions $6 + 2x$, $2x + 6$ and $x + x + 6$ all equal $6 + 2x$. But $3 + 2x$ is different: the 2 was not multiplied by the 3.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3 + x) = 6 + 2x. 6 + 2x, x + x + 6, 2x + 6 are all equal to it; 3 + 2x is not.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4fba204-6a39-498d-ae67-6e283adaf63e', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions and properties', 'Which expression shows $12 + 20$ written with the greatest common factor factored out?', '["$2(6 + 10)$","$4(5 + 8)$","$4(3 + 5)$","$12(1 + 5)$"]', '$4(3 + 5)$', NULL, 'The greatest common factor of 12 and 20 is 4. Writing $12 = 4 \times 3$ and $20 = 4 \times 5$ gives $12 + 20 = 4(3 + 5)$. The expression $2(6 + 10)$ is also equal to 32, but 2 is not the greatest common factor.', 'checked', '{"lint":[],"solve":{"answer":"$4(3 + 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(12, 20) = 4; 12 + 20 = 4(3 + 5). 4(5 + 8) = 52, wrong; 2(6 + 10) uses 2, not the GCF; 12(1 + 5) = 72.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39e7a38e-4a24-49a1-95d9-1c8e8498af5d', 'NC26.6.ANR.6', 2, 'numeric', 'Equivalent expressions and properties', 'Aisha finds $6 \times 52$ by writing $6 \times 50 + 6 \times 2$. What is the product?', '[]', '312', '6*50+6*2', '$6 \times 50 = 300$ and $6 \times 2 = 12$. Then $300 + 12 = 312$.', 'checked', '{"lint":[],"solve":{"answer":"312","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 50 = 300, 6 x 2 = 12; 312.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bf48979-9d94-47c3-95e0-9946765f5b38', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations with exponents and parentheses', 'What is the value of $(9 - 3)^2 \div 4 + 2 \times 5$?', '[]', '19', '(9-3)^2/4+2*5', 'Parentheses first: $9 - 3 = 6$. Exponent: $6^2 = 36$. Then divide and multiply: $36 \div 4 = 9$ and $2 \times 5 = 10$. Finally add: $9 + 10 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9 - 3)^2 = 6^2 = 36. 36 / 4 = 9. 2 x 5 = 10. 9 + 10 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
