INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ff4d59e-d17a-4930-8afd-d91faa11dac7', 'NC26.6.ANR.6', 3, 'choice', 'Parts of an expression', 'Which expression is a sum of two products?', '["$5(a + 2b)$","$5a \\times 2b$","$\\frac{5a}{2b}$","$5a + 2b$"]', '$5a + 2b$', NULL, '$5a + 2b$ adds the product $5 \times a$ and the product $2 \times b$. The expression $5(a + 2b)$ is a product, $5a \times 2b$ is a product and $\frac{5a}{2b}$ is a quotient.', 'checked', '{"lint":[],"solve":{"answer":"$5a + 2b$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a + 2b is the sum of the products 5 x a and 2 x b. Others are a product, a product of a number and a sum, and a quotient.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
