INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a35808d-5954-43a3-a62b-1c446c2f3f2d', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating algebraic expressions', 'Find the value of $4x^2 - 3y$ when $x = 3$ and $y = 5$.', '[]', '21', '4*3^2-3*5', '$4x^2 = 4 \times 3^2 = 4 \times 9 = 36$ and $3y = 3 \times 5 = 15$. Then $36 - 15 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(3^2) - 3(5) = 4 x 9 - 15 = 36 - 15 = 21.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
