INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7732e957-cb36-41f7-8c40-4220e09de905', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating algebraic expressions', 'The surface area of a cube with edge length $s$ is $6s^2$. What is the surface area, in square feet, of a cube with edge length $\frac{1}{2}$ foot?', '[]', '3/2', '6*(1/2)^2', 'Replace $s$ with $\frac{1}{2}$: $6 \times \left(\frac{1}{2}\right)^2 = 6 \times \frac{1}{4} = \frac{6}{4} = \frac{3}{2}$ square feet, which is $1\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s^2 = (1/2)^2 = 1/4; 6 x 1/4 = 3/2 = 1.5 square feet.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fdb34e2-f831-47a1-b214-30570c23b1f3', 'NC26.6.ANR.6', 3, 'choice', 'Evaluating algebraic expressions', 'Jan evaluated $2n^2$ when $n = 3$ and got 36. Which describes her mistake?', '["She squared 3 and then added 2","She added 2 and 3 and then squared the sum","She squared 2 and then multiplied by 3","She multiplied 2 by 3 first and then squared the product"]', 'She multiplied 2 by 3 first and then squared the product', NULL, 'The exponent applies only to $n$, so $2n^2 = 2 \times 3^2 = 2 \times 9 = 18$. Jan got 36 because she computed $(2 \times 3)^2 = 6^2 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"She multiplied 2 by 3 first and then squared the product","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct: 2 x 3^2 = 18. 36 = (2 x 3)^2 = 6^2, so she multiplied first then squared. Other options give 25, 12, 11.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8d7ca2f-9d72-4d26-bc56-9c8547c9ac7c', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating algebraic expressions', 'Find the value of $\frac{2x + y}{z}$ when $x = 7$, $y = 4$ and $z = 3$.', '[]', '6', '(2*7+4)/3', 'The numerator is $2 \times 7 + 4 = 14 + 4 = 18$. Then $18 \div 3 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2 x 7 + 4)/3 = 18/3 = 6.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8818871c-b3bf-41a5-ba4e-c6cc800a4dd4', 'NC26.6.ANR.6', 3, 'choice', 'Equivalent expressions and properties', 'Which expression is equivalent to $3(2x + 4) + x$?', '["$7x + 4$","$6x + 12$","$19x$","$7x + 12$"]', '$7x + 12$', NULL, 'Distribute the 3: $3(2x + 4) = 6x + 12$. Then add the extra $x$ and combine like terms: $6x + 12 + x = 7x + 12$.', 'checked', '{"lint":[],"solve":{"answer":"$7x + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x + 4) = 6x + 12; plus x gives 7x + 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7bb04f-9baa-4cdf-89c8-4acc3e3be755', 'NC26.6.ANR.6', 3, 'numeric', 'Equivalent expressions and properties', 'Simplify $5y + 3 + 2y + 9$ to the form $ay + b$. What is $a + b$?', '[]', '19', '5+2+3+9', 'Combine the like terms: $5y + 2y = 7y$ and $3 + 9 = 12$. So the expression is $7y + 12$, and $a + b = 7 + 12 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5y + 2y = 7y, 3 + 9 = 12; 7y + 12; a + b = 19.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1939d080-c2e9-4449-ad0a-ed116caa620f', 'NC26.6.ANR.6', 3, 'choice', 'Equivalent expressions and properties', 'Dev says that $4(x + 3)$ and $4x + 3$ are equivalent. Which statement shows whether he is right?', '["He is right: for $x = 2$ both are 11","He is wrong: for $x = 2$ the first is 20 and the second is 11","He is right: the 4 is multiplied by both terms","He is wrong: for $x = 2$ the first is 11 and the second is 20"]', 'He is wrong: for $x = 2$ the first is 20 and the second is 11', NULL, 'Try $x = 2$: $4(2 + 3) = 4 \times 5 = 20$, but $4 \times 2 + 3 = 11$. The values differ, so the expressions are not equivalent. The correct distribution is $4(x + 3) = 4x + 12$.', 'checked', '{"lint":[],"solve":{"answer":"He is wrong: for $x = 2$ the first is 20 and the second is 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 2: 4(2 + 3) = 20; 4(2) + 3 = 11. Not equal, so he is wrong; first is 20, second 11.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3effdd3-0941-4afb-af68-781024764be0', 'NC26.6.ANR.6', 3, 'numeric', 'Equivalent expressions and properties', 'A student factors $6x + 15$ as $3(2x + n)$. What is $n$?', '[]', '5', '15/3', '$6x = 3 \times 2x$ and $15 = 3 \times 5$, so $6x + 15 = 3(2x + 5)$ and $n = 5$. Check: $3(2x + 5) = 6x + 15$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x + n) = 6x + 3n = 6x + 15, so 3n = 15, n = 5.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a6a6a74-e0ad-4ecd-8c64-839a2ec6ee95', 'NC26.6.ANR.6', 3, 'choice', 'Equivalent expressions and properties', 'Which expression is equivalent to $\frac{1}{2}(8a + 6)$?', '["$4a + 3$","$4a + 6$","$8a + 3$","$16a + 12$"]', '$4a + 3$', NULL, 'Half of $8a$ is $4a$ and half of 6 is 3, so $\frac{1}{2}(8a + 6) = 4a + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$4a + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(8a) + (1/2)(6) = 4a + 3.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
