VALUES ('866908a4-543d-4606-a621-a4c66fc0e25f', 'NC26.6.ANR.7', 1, 'choice', 'Solving equations with decimals and fractions', 'What is the solution of $c - 0.4 = 0.6$?', '["$0.2$","$1$","$0.24$","$10$"]', '$1$', '0.6+0.4', 'Add 0.4 to both sides: $c = 0.6 + 0.4 = 1$. Check: $1 - 0.4 = 0.6$.', 'checked', '{"lint":[],"solve":{"answer":"$1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = 0.6 + 0.4 = 1.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
