INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b313e80e-f3ec-4b5b-9a3d-bb7f2ebf54ec', 'NC26.6.ANR.7', 1, 'numeric', 'Writing and solving an equation from a story', 'Rosa had some marbles. After she found 8 more, she had 20 marbles. How many marbles did she have at first?', '[]', '12', '20-8', 'Let $m$ be the number she had at first. Then $m + 8 = 20$, so $m = 20 - 8 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m + 8 = 20, m = 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c31f063c-5828-45ab-b341-59ecccca8ae2', 'NC26.6.ANR.7', 1, 'choice', 'Writing and solving an equation from a story', 'Tia has $s$ stickers. She gives 5 of them away and has 9 left. Which equation matches this story?', '["$s + 5 = 9$","$5s = 9$","$s - 5 = 9$","$s - 9 = 5$"]', '$s - 5 = 9$', NULL, 'She starts with $s$ and gives away 5, so what is left is $s - 5$. That equals 9: $s - 5 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$s - 5 = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start s, give away 5, left 9: s - 5 = 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bd33b06-2de4-4a07-8f64-0423e7bdae3f', 'NC26.6.ANR.7', 1, 'numeric', 'Writing and solving an equation from a story', 'A rectangular garden has an area of 48 square feet and a length of 8 feet. What is its width, in feet?', '[]', '6', '48/8', 'Area is length times width, so $8w = 48$. Divide both sides by 8: $w = 6$ feet.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8w = 48, w = 6.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46f17354-b825-4165-9a8f-6decad068c7f', 'NC26.6.ANR.7', 1, 'choice', 'Writing and solving an equation from a story', 'Which story matches the equation $n + 6 = 15$?', '["Lee had some cards, gave away 6, and then had 15 cards","Lee has 6 cards in each of $n$ boxes, which is 15 cards in all","Lee shared 15 cards equally among 6 friends","Lee had some cards, got 6 more, and then had 15 cards"]', 'Lee had some cards, got 6 more, and then had 15 cards', NULL, 'In $n + 6 = 15$, an unknown number $n$ has 6 added to it and the result is 15. That is the story where Lee got 6 more cards. Giving cards away would be subtraction.', 'checked', '{"lint":[],"solve":{"answer":"Lee had some cards, got 6 more, and then had 15 cards","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + 6 = 15: some cards, got 6 more, had 15.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65414ecc-45b9-4f09-8d1a-3f1c87f7d435', 'NC26.6.ANR.7', 1, 'choice', 'Writing an inequality from a situation', 'Which inequality means "a number $x$ is greater than 5"?', '["$x > 5$","$x < 5$","$x \\ge 5$","$x = 5$"]', '$x > 5$', NULL, '"Greater than" is written with the symbol $>$, so the inequality is $x > 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x > 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greater than 5 (not equal): x > 5.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
