INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4882e92-5ec9-40be-b187-b80a8bac2f19', 'NC26.6.ANR.7', 1, 'choice', 'Writing an inequality from a situation', 'Which phrase means the same as $n \ge 8$?', '["$n$ is less than 8","$n$ is at least 8","$n$ is at most 8","$n$ is more than 8"]', '$n$ is at least 8', NULL, 'The symbol $\ge$ means "greater than or equal to", which is "at least". So $n \ge 8$ means $n$ is at least 8.', 'checked', '{"lint":[],"solve":{"answer":"$n$ is at least 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n >= 8 means n is at least 8.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c53569b-2f88-4976-a8e8-037898f3f9dd', 'NC26.6.ANR.7', 1, 'choice', 'Writing an inequality from a situation', 'A sign says "Riders must be taller than 40 inches." Let $h$ be a rider''s height in inches. Which inequality shows the heights that are allowed?', '["$h < 40$","$h \\ge 40$","$h = 40$","$h > 40$"]', '$h > 40$', NULL, '"Taller than 40" means greater than 40 and not equal to it, so $h > 40$.', 'checked', '{"lint":[],"solve":{"answer":"$h > 40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Taller than 40 (strict): h > 40.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78e8b2b7-e13d-4c49-b2ea-70e6b0f36793', 'NC26.6.ANR.7', 1, 'numeric', 'Writing an inequality from a situation', 'A bus can carry at most 30 passengers. What is the greatest number of passengers allowed on the bus?', '[]', '30', '30', '"At most 30" means 30 or fewer, written $p \le 30$. The greatest number allowed is 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At most 30 means p <= 30; greatest is 30.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
