INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d06d44bb-3375-45f7-a2ca-038255595397', 'NC26.6.ANR.7', 1, 'choice', 'Solutions and graphs of inequalities', 'Which list contains only solutions of the inequality $x < 6$?', '["2, 4, 6","5, 6, 7","1, 3, 5","0, 6, 12"]', '1, 3, 5', NULL, 'A solution must be less than 6. In the list 1, 3, 5 every number is less than 6. Each other list contains 6 or a number greater than 6, and 6 is not less than 6.', 'checked', '{"lint":[],"solve":{"answer":"1, 3, 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of 1, 3, 5 is below 6; every other list contains 6 or more.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2353bce4-47cc-40e8-a47c-6c2a3ce4c6bc', 'NC26.6.ANR.7', 1, 'choice', 'Solutions and graphs of inequalities', 'Which number is NOT a solution of $x \ge 3$?', '["$3$","$2$","$5$","$30$"]', '$2$', NULL, 'Solutions are 3 or greater. The numbers 3, 5 and 30 all work, but 2 is less than 3, so it is not a solution.', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 < 3, so 2 is not a solution; 30, 5, 3 are.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
