INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c3f816f-26c4-4b92-a747-294facb638b1', 'NC26.6.ANR.7', 2, 'choice', 'Checking a solution by substitution', 'Which value of $y$ is the solution of $y - 9 = 14$?', '["$5$","$126$","$14$","$23$"]', '$23$', '14+9', 'Check $y = 23$: $23 - 9 = 14$, which is true. The other values give $5 - 9$, $126 - 9 = 117$ and $14 - 9 = 5$, none of which is 14.', 'checked', '{"lint":[],"solve":{"answer":"$23$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 14 + 9 = 23; check 23 - 9 = 14.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
