INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38e8c019-10f9-4acd-9301-588bc45566e1', 'NC26.6.ANR.7', 2, 'numeric', 'Checking a solution by substitution', 'Which of the numbers 3, 5, 8 and 12 is a solution of $4a = 32$?', '[]', '8', '32/4', 'Try each: $4 \times 3 = 12$, $4 \times 5 = 20$, $4 \times 8 = 32$ and $4 \times 12 = 48$. Only $a = 8$ works.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 8 = 32; 4 x 3 = 12, 4 x 5 = 20, 4 x 12 = 48.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a66804b-8cb7-4aed-979b-18fb2e503301', 'NC26.6.ANR.7', 2, 'choice', 'Checking a solution by substitution', 'Ana, Ben and Cara each test a value in the equation $x + 8 = 20$. Ana tries 28, Ben tries 12 and Cara tries 160. Who found a solution?', '["Only Ana","Only Cara","All three of them","Only Ben"]', 'Only Ben', NULL, 'Test each value: $28 + 8 = 36$, $12 + 8 = 20$ and $160 + 8 = 168$. Only Ben''s value, 12, makes the equation true.', 'checked', '{"lint":[],"solve":{"answer":"Only Ben","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 + 8 = 36, 12 + 8 = 20, 160 + 8 = 168. Only Ben''s 12 works.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7fbd69f-4261-4d78-b22e-62ac3ecd7d6f', 'NC26.6.ANR.7', 2, 'choice', 'Checking a solution by substitution', 'Which value of $x$ makes both $x + 2 = 9$ and $3x = 21$ true?', '["$11$","$18$","$7$","$63$"]', '$7$', '9-2', 'For $x = 7$: $7 + 2 = 9$ and $3 \times 7 = 21$, so both are true. The other values fail at least one of them.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2 = 9 gives 7; 3x = 21 gives 7. x = 7.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
