VALUES ('40524005-b239-45db-8126-c3d1303a8984', 'NC26.6.ANR.7', 2, 'numeric', 'Solving addition and subtraction equations', 'Solve $x + 47 = 100$.', '[]', '53', '100-47', 'Subtract 47 from both sides: $x = 100 - 47 = 53$. Check: $53 + 47 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"53","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 100 - 47 = 53.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
