INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6177fbbc-57da-4a6b-b440-26a62462171a', 'NC26.6.ANR.7', 2, 'choice', 'Solving multiplication and division equations', 'Mei''s solution to an equation is $x = 9$. Which equation could she have solved?', '["$x \\div 4 = 36$","$4x = 36$","$x + 4 = 36$","$\\frac{x}{9} = 4$"]', '$4x = 36$', NULL, 'Put 9 in place of $x$: $4 \times 9 = 36$ is true. The others give $9 \div 4$, $9 + 4 = 13$ and $\frac{9}{9} = 1$, none of which matches.', 'checked', '{"lint":[],"solve":{"answer":"$4x = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/9 = 4 gives 36; 4x = 36 gives 9; x + 4 = 36 gives 32; x / 4 = 36 gives 144. Only 4x = 36.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('262b7c8e-8b49-4f04-90e3-a993d33c7d5f', 'NC26.6.ANR.7', 2, 'choice', 'Solving multiplication and division equations', 'Kai solves $\frac{x}{6} = 5$ and gets $x = \frac{5}{6}$. What should Kai have done?', '["Divided both sides by 6, which gives $x = \\frac{5}{6}$","Subtracted 6 from both sides, which gives $x = -1$","Added 6 to both sides, which gives $x = 11$","Multiplied both sides by 6, which gives $x = 30$"]', 'Multiplied both sides by 6, which gives $x = 30$', NULL, 'The variable is divided by 6, so the inverse operation is to multiply both sides by 6: $x = 5 \times 6 = 30$. Check: $30 \div 6 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"Multiplied both sides by 6, which gives $x = 30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/6 = 5: multiply both sides by 6, x = 30.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
