VALUES ('cabb7bf5-fd2b-4a76-b675-8719b1e7ca4a', 'NC26.6.ANR.7', 2, 'choice', 'Solving equations with decimals and fractions', 'Which value of $m$ is the solution of $m + 1.75 = 4.5$?', '["$2.75$","$6.25$","$3.75$","$2.25$"]', '$2.75$', '4.5-1.75', 'Subtract 1.75 from both sides: $m = 4.5 - 1.75 = 2.75$. Check: $2.75 + 1.75 = 4.5$.', 'checked', '{"lint":[],"solve":{"answer":"$2.75$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m = 4.5 - 1.75 = 2.75.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
