INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2805367c-cb42-47c4-9f7d-415c5b135c1a', 'NC26.6.ANR.7', 2, 'choice', 'Writing and solving an equation from a story', 'A ribbon is cut into 4 equal pieces, and each piece is 9 inches long. Which equation can be used to find the length $L$ of the whole ribbon, in inches?', '["$4L = 9$","$\\frac{L}{4} = 9$","$L + 4 = 9$","$L - 4 = 9$"]', '$\frac{L}{4} = 9$', NULL, 'The whole ribbon of length $L$ is divided into 4 equal pieces, so each piece is $\frac{L}{4}$, which equals 9. Then $L = 9 \times 4 = 36$ inches.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{L}{4} = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole length divided by 4 is 9: L/4 = 9 (L = 36).","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
