INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb8bba3-5d13-4f8e-ad5c-83c3ee90f1c1', 'NC26.6.ANR.7', 2, 'choice', 'Writing an inequality from a situation', 'You must be at least 13 years old to join a club. Let $a$ be a person''s age in years. Which inequality shows the ages that may join?', '["$a > 13$","$a \\le 13$","$a \\ge 13$","$a < 13$"]', '$a \ge 13$', NULL, '"At least 13" means 13 or more, so 13 is allowed. That is $a \ge 13$.', 'checked', '{"lint":[],"solve":{"answer":"$a \\ge 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 13: a >= 13.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
