VALUES ('83709ccc-48df-4084-8b91-6fce8d78eb48', 'NC26.6.ANR.7', 2, 'choice', 'Solutions and graphs of inequalities', 'Which of these numbers is a solution of $x \ge 2.5$?', '["$2.5$","$2.4$","$2$","$0.25$"]', '$2.5$', NULL, 'Solutions are 2.5 or greater. The number 2.5 is a solution because $\ge$ includes it. The others are less than 2.5.', 'checked', '{"lint":[],"solve":{"answer":"$2.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5 >= 2.5 is true; 0.25, 2.4, 2 are less.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
