INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3178367-dde8-48fb-b96b-3f0048f6a587', 'NC26.6.ANR.7', 3, 'numeric', 'Writing and solving an equation (decimals)', 'Four friends split the cost of a gift equally. Each friend pays 7.25 dollars. What was the cost of the gift, in dollars?', '[]', '29', '7.25*4', 'If the gift costs $c$ dollars, then $\frac{c}{4} = 7.25$. Multiply both sides by 4: $c = 7.25 \times 4 = 29$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c / 4 = 7.25, so c = 4 x 7.25 = 29 dollars.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fd6abfb-40f4-41f6-9768-6ea409844359', 'NC26.6.ANR.7', 3, 'choice', 'Checking a solution by substitution', 'Maria says that $x = 4$ is the solution of $\frac{x}{2} = 8$. Which shows how to check her answer?', '["Substitute 4 for $x$: $4 \\times 2 = 8$, so she is right","Substitute 4 for $x$: $\\frac{4}{2} = 2$, which is not 8, so she is wrong","Substitute 8 for $x$: $\\frac{8}{2} = 4$, so she is right","Substitute 4 for $x$: $\\frac{4}{2} = 2$, so she is right"]', 'Substitute 4 for $x$: $\frac{4}{2} = 2$, which is not 8, so she is wrong', NULL, 'Replace $x$ with 4 in $\frac{x}{2}$: $\frac{4}{2} = 2$, and 2 is not 8. So $x = 4$ is not a solution. The solution is $x = 16$, because $\frac{16}{2} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"Substitute 4 for $x$: $\\frac{4}{2} = 2$, which is not 8, so she is wrong","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Substitute 4: 4/2 = 2, not 8, so she is wrong (the solution is 16).","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1567dd4d-2cbd-4881-81ce-7d91106da51f', 'NC26.6.ANR.7', 3, 'numeric', 'Checking a solution by substitution', 'Which of the numbers 0.5, 1.5, 2.5 and 3.5 is the solution of $x + 1.25 = 3.75$?', '[]', '2.5', '3.75-1.25', 'Try each: $0.5 + 1.25 = 1.75$, $1.5 + 1.25 = 2.75$, $2.5 + 1.25 = 3.75$ and $3.5 + 1.25 = 4.75$. Only 2.5 works.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 3.75 - 1.25 = 2.5; check 2.5 + 1.25 = 3.75.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75af697f-2662-4c99-b121-293095e3cbc9', 'NC26.6.ANR.7', 3, 'choice', 'Checking a solution by substitution', 'Which equation does NOT have $x = 6$ as a solution?', '["$5x = 35$","$x + 9 = 15$","$x \\div 2 = 3$","$x - 1 = 5$"]', '$5x = 35$', NULL, 'Put 6 in each: $6 + 9 = 15$ is true, $6 \div 2 = 3$ is true, $6 - 1 = 5$ is true, but $5 \times 6 = 30$, not 35. So $5x = 35$ is the one that does not have 6 as a solution.', 'checked', '{"lint":[],"solve":{"answer":"$5x = 35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 6: 5 x 6 = 30, not 35; 6 - 1 = 5 true; 6 / 2 = 3 true; 6 + 9 = 15 true.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09ad4147-ce85-45a3-9b22-0210b8dbae6f', 'NC26.6.ANR.7', 3, 'choice', 'Checking a solution by substitution', 'Which value of $m$ is a solution of $m - \frac{1}{4} = \frac{3}{4}$?', '["$\\frac{1}{2}$","$\\frac{3}{16}$","$\\frac{3}{4}$","$1$"]', '$1$', '3/4+1/4', 'Check $m = 1$: $1 - \frac{1}{4} = \frac{3}{4}$, which is true. For $m = \frac{3}{4}$ the left side is $\frac{3}{4} - \frac{1}{4} = \frac{1}{2}$, so it fails.', 'checked', '{"lint":[],"solve":{"answer":"$1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m = 3/4 + 1/4 = 1.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
