INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5637d317-7a5f-476f-94d8-ab02901797dd', 'NC26.6.ANR.7', 3, 'choice', 'Solving equations with decimals and fractions', 'Which equation has the solution $x = 1\frac{1}{2}$?', '["$x - \\frac{1}{2} = 2$","$x + \\frac{1}{2} = 2$","$2x = 1$","$\\frac{x}{2} = 3$"]', '$x + \frac{1}{2} = 2$', NULL, 'Put $1\frac{1}{2}$ in place of $x$: $1\frac{1}{2} + \frac{1}{2} = 2$ is true. The others give $1$, $1\frac{1}{2} - \frac{1}{2} = 1$, $2 \times 1\frac{1}{2} = 3$ and $\frac{3}{4}$, none of which matches.', 'checked', '{"lint":[],"solve":{"answer":"$x + \\frac{1}{2} = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solutions: x/2 = 3 gives 6; x - 1/2 = 2 gives 2 1/2; 2x = 1 gives 1/2; x + 1/2 = 2 gives 1 1/2.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
