INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73569468-63ea-4115-993c-0a8f8b55b9b5', 'NC26.6.ANR.7', 3, 'numeric', 'Writing and solving an equation from a story', 'Eli saved the same amount of money each week for 12 weeks and saved 270 dollars in all. How many dollars did he save each week?', '[]', '22.5', '270/12', 'Let $s$ be the amount saved each week. Then $12s = 270$, so $s = 270 \div 12 = 22.5$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"22.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12w = 270, w = 22.5 (22.50 dollars).","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
