INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63b31791-71ff-469c-bb97-44975308920b', 'NC26.6.ANR.7', 3, 'numeric', 'Solutions and graphs of inequalities', 'What is the greatest whole number that is a solution of $x < 12.5$?', '[]', '12', '12', 'Solutions must be less than 12.5. The whole number 12 is less than 12.5, but 13 is not. So the greatest whole-number solution is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 12.5; greatest whole number is 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
