INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6af7bf43-c9c1-4bfd-8e14-70cc65c8f2a9', 'NC26.6.ANR.7', 3, 'choice', 'Solutions and graphs of inequalities', 'A number line graph has an open circle at 3.5 and an arrow pointing to the right. Which of these numbers is a solution of the inequality it shows?', '["$3.5$","$3.4$","$3.6$","$0$"]', '$3.6$', NULL, 'The graph shows $x > 3.5$. A solution must be greater than 3.5, and 3.5 itself is not included. Only 3.6 is greater than 3.5.', 'checked', '{"lint":[],"solve":{"answer":"$3.6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Open circle at 3.5, arrow right: x > 3.5. Of 3.5, 0, 3.4, 3.6 only 3.6 works.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b8ecd6-0f95-43c8-abbf-d490b4088865', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a triangle from its base and height', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area in square centimeters?', '[]', '30', '1/2*10*6', 'The area of a triangle is half of the base times the height: $\frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x base x height = 1/2 x 10 x 6 = 30.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
