INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5401f0c0-8b36-44ee-b944-cfd56316e183', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a triangle from its base and height', 'Which expression gives the area of a triangle with base $b$ and height $h$?', '["$\\frac{1}{2} \\times b \\times h$","$b \\times h$","$b + h$","$2 \\times b \\times h$"]', '$\frac{1}{2} \times b \times h$', NULL, 'A triangle is half of a rectangle or parallelogram with the same base and height. So its area is half of the base times the height, $\frac{1}{2} \times b \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2} \\times b \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle is half of a parallelogram with the same base and height: A = 1/2 x b x h.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d4796b8-f08f-4324-b38b-1a2a052d02e1', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a triangle from its base and height', 'A triangle has a base of 12 centimeters and a height of 3 centimeters. What is its area in square centimeters?', '["36","18","15","6"]', '18', '1/2*12*3', 'Area $= \frac{1}{2} \times 12 \times 3 = 18$ square centimeters. A result of 36 forgets to take half, and 15 adds instead of multiplying.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 12 x 3 = 18.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
