INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50af29b0-7b55-4b83-9a31-dfa9de3e021b', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a parallelogram from its base and height', 'Which expression gives the area of a parallelogram with base $b$ and height $h$?', '["$b \\times h$","$\\frac{1}{2} \\times b \\times h$","$b + h$","$2 \\times (b + h)$"]', '$b \times h$', NULL, 'A parallelogram can be cut and rearranged into a rectangle with the same base and height, so its area is $b \times h$. Half of that is a triangle, and $2 \times (b + h)$ is a perimeter formula.', 'checked', '{"lint":[],"solve":{"answer":"$b \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram rearranges into a rectangle b by h: A = b x h.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
