INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d257b68a-13e8-49f8-b40f-2a4d6304f771', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a parallelogram from its base and height', 'A parallelogram and a rectangle each have a base of 7 centimeters and a height of 4 centimeters. Which statement is true?', '["The parallelogram has the greater area.","They have the same area.","The rectangle has the greater area.","The parallelogram has half the area of the rectangle."]', 'They have the same area.', NULL, 'Both areas are base times height, $7 \times 4 = 28$ square centimeters. A parallelogram can be cut and slid into a rectangle without changing its area.', 'checked', '{"lint":[],"solve":{"answer":"They have the same area.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both have area 7 x 4 = 28 square cm, so equal.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
