INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('505ff322-c889-4472-bb41-c685484b161c', 'NC26.6.SGMR.1', 1, 'numeric', 'Finding a missing base or height from the area', 'A parallelogram has an area of 56 square centimeters and a base of 8 centimeters. What is its height in centimeters?', '[]', '7', '56/8', 'Area $=$ base $\times$ height, so height $=$ area $\div$ base $= 56 \div 8 = 7$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / 8 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfc2af64-f6d3-4d25-b392-b8f223c783d2', 'NC26.6.SGMR.1', 1, 'choice', 'Finding a missing base or height from the area', 'A triangular banner has an area of 12 square inches. Its height is 4 inches. How long is its base, in inches?', '["6","3","24","48"]', '6', '2*12/4', 'Half of base times height is 12, so base times height is 24. The base is $24 \div 4 = 6$ inches. A result of 3 forgets that the area is only half of base times height.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 1/2 x b x 4 = 2b, so b = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe10f1c-4b3a-4b41-8fa2-8d07d3c1bdd0', 'NC26.6.SGMR.1', 1, 'choice', 'Finding a missing base or height from the area', 'A triangle has a base of 10 centimeters and an area of 35 square centimeters. Which equation can be used to find its height $h$, in centimeters?', '["$10 \\times h = 35$","$\\frac{1}{2} \\times 10 \\times h = 35$","$\\frac{1}{2} \\times (10 + h) = 35$","$10 + h = 35$"]', '$\frac{1}{2} \times 10 \times h = 35$', NULL, 'The area of a triangle is $\frac{1}{2} \times$ base $\times$ height, so $\frac{1}{2} \times 10 \times h = 35$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2} \\times 10 \\times h = 35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x base x height: 1/2 x 10 x h = 35 (h = 7).","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87e81533-01a6-4f8f-b8b2-afc5e0576eba', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a composite figure made of rectangles', 'A shape is made of two rectangles that do not overlap. One is 5 centimeters by 4 centimeters. The other is 3 centimeters by 2 centimeters. What is the total area of the shape in square centimeters?', '[]', '26', '5*4+3*2', 'The areas are $5 \times 4 = 20$ and $3 \times 2 = 6$. The total is $20 + 6 = 26$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 4 + 3 x 2 = 20 + 6 = 26.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8abdcbf8-9640-4727-b060-efc87c963d12', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a composite figure made of rectangles', 'A rectangular rug is 10 feet by 6 feet. A square of cloth, 2 feet on each side, is cut out of the rug. What is the area of the rug that is left, in square feet?', '["56","64","58","4"]', '56', '10*6-2*2', 'The rug has area $10 \times 6 = 60$ and the hole has area $2 \times 2 = 4$. What is left is $60 - 4 = 56$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 6 - 2 x 2 = 60 - 4 = 56.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('780092a9-62b2-49c9-a56b-cd0000bdd399', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a composite figure made of rectangles', 'Two square tiles lie side by side without overlapping. One has sides of 4 centimeters and the other has sides of 6 centimeters. What is the total area of the two tiles in square centimeters?', '[]', '52', '4*4+6*6', 'The small tile has area $4 \times 4 = 16$ and the large tile has area $6 \times 6 = 36$. Together: $16 + 36 = 52$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 4 + 6 x 6 = 16 + 36 = 52.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3db0508-713e-48cb-b200-f3aee907b833', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a composite figure that includes triangles', 'A figure is made of a rectangle and a triangle that do not overlap. The rectangle is 7 centimeters long and 3 centimeters wide. The triangle has a base of 6 centimeters and a height of 4 centimeters. What is the total area of the figure in square centimeters?', '[]', '33', '7*3+1/2*6*4', 'The rectangle has area $7 \times 3 = 21$. The triangle has area $\frac{1}{2} \times 6 \times 4 = 12$. The total is $21 + 12 = 33$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 7 x 3 = 21; triangle 1/2 x 6 x 4 = 12; total 33.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f51f7abe-8221-470f-90bb-10cf20b317f1', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a composite figure that includes triangles', 'A square piece of paper is 10 centimeters on each side. A right triangle with legs of 6 centimeters and 4 centimeters is cut off one corner. What is the area of the paper that is left, in square centimeters?', '["112","76","94","88"]', '88', '10*10-1/2*6*4', 'The square has area $10 \times 10 = 100$. The triangle that is cut off has area $\frac{1}{2} \times 6 \times 4 = 12$. What is left is $100 - 12 = 88$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square 100; triangle 1/2 x 6 x 4 = 12; 100 - 12 = 88.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f70426cc-9be6-4984-9951-54ba7272c416', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a composite figure that includes triangles', 'A shape is made of a rectangle 6 cm by 5 cm and a triangle with a base of 6 cm and a height of 2 cm, joined along the 6 cm side. Which expression gives its total area in square centimeters?', '["$6 \\times 5 + \\frac{1}{2} \\times 6 \\times 2$","$6 \\times 5 + 6 \\times 2$","$\\frac{1}{2} \\times (6 \\times 5 + 6 \\times 2)$","$6 \\times 5 - \\frac{1}{2} \\times 6 \\times 2$"]', '$6 \times 5 + \frac{1}{2} \times 6 \times 2$', NULL, 'Add the rectangle, $6 \times 5$, to the triangle, which is half of base times height: $\frac{1}{2} \times 6 \times 2$. That gives 30 + 6 = 36 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 5 + \\frac{1}{2} \\times 6 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 5 plus triangle 1/2 x 6 x 2 (joined, not cut out): 30 + 6 = 36.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b985957-e0a1-4815-8050-bfc8d2e9aef0', 'NC26.6.SGMR.1', 1, 'numeric', 'Composing and decomposing shapes', 'Two identical triangles fit together to make a rectangle. The rectangle has an area of 36 square centimeters. What is the area of one triangle in square centimeters?', '[]', '18', '36/2', 'The two identical triangles share the rectangle''s area equally, so one triangle has area $36 \div 2 = 18$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / 2 = 18.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bec19eda-c4af-489e-91fa-d1e476421d5e', 'NC26.6.SGMR.1', 1, 'choice', 'Composing and decomposing shapes', 'A parallelogram is cut by a straight line from one top corner straight down to the base. The cut-off triangle is slid to the other end to make a rectangle. How does the rectangle''s area compare with the parallelogram''s area?', '["The rectangle''s area is greater.","The rectangle''s area is smaller.","They are equal.","The rectangle''s area is double."]', 'They are equal.', NULL, 'Cutting and sliding a piece does not add or remove any area. The rectangle has the same base and height as the parallelogram, so the areas are equal.', 'checked', '{"lint":[],"solve":{"answer":"They are equal.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cutting and sliding a piece neither adds nor removes area, so the areas are equal.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97128de2-43bf-4e24-a1d2-a606d41665b7', 'NC26.6.SGMR.1', 1, 'numeric', 'Composing and decomposing shapes', 'A square piece of paper has sides of 8 centimeters. It is cut along both of its diagonals into four identical triangles. What is the area of one triangle in square centimeters?', '[]', '16', '8*8/4', 'The square has area $8 \times 8 = 64$ square centimeters. Four identical triangles share it equally, so each has area $64 \div 4 = 16$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square area 64; four identical triangles: 64 / 4 = 16. (Check: legs half-diagonals; base 8, height 4: 1/2 x 8 x 4 = 16.)","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc37a82-94ec-48c8-9b2f-99ec5c7e504e', 'NC26.6.SGMR.1', 1, 'numeric', 'Solving area problems in context', 'A triangular garden has a base of 6 meters and a height of 4 meters. One bag of grass seed covers 3 square meters. How many bags are needed to cover the whole garden?', '[]', '4', '1/2*6*4/3', 'The garden has area $\frac{1}{2} \times 6 \times 4 = 12$ square meters. Each bag covers 3, so $12 \div 3 = 4$ bags are needed.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x 6 x 4 = 12; 12 / 3 = 4 bags.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('188b9cc4-cd35-4506-a63b-02549d190fe7', 'NC26.6.SGMR.1', 1, 'choice', 'Solving area problems in context', 'Which unit is best for measuring the area of a classroom floor?', '["Meters","Square meters","Cubic meters","Square millimeters"]', 'Square meters', NULL, 'Area is measured in square units. A classroom floor is large, so square meters fit. Meters measure length, cubic meters measure volume, and square millimeters are far too small.', 'checked', '{"lint":[],"solve":{"answer":"Square meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area needs square units; a floor is meters-sized, so square meters.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6953475-3681-4942-8693-ca7fc302f459', 'NC26.6.SGMR.1', 1, 'numeric', 'Solving area problems in context', 'A wall has a patch shaped like a parallelogram that needs paint. The patch has a base of 5 feet and a height of 4 feet. One small can of paint covers 10 square feet. How many cans are needed?', '[]', '2', '5*4/10', 'The patch has area $5 \times 4 = 20$ square feet. One can covers 10 square feet, so $20 \div 10 = 2$ cans are needed.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 5 x 4 = 20; 20 / 10 = 2 cans.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29e9a5bc-46df-4143-9b33-9fb19edb0cd0', 'NC26.6.SGMR.1', 1, 'choice', 'How area changes when a measurement changes', 'A rectangle has a length of 6 centimeters and a width of 4 centimeters. The length is doubled and the width stays the same. What happens to the area?', '["It stays the same.","It doubles.","It becomes 4 times as large.","It increases by 6 square centimeters."]', 'It doubles.', NULL, 'The area goes from $6 \times 4 = 24$ to $12 \times 4 = 48$ square centimeters. Doubling one measurement doubles the area.', 'checked', '{"lint":[],"solve":{"answer":"It doubles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 6 x 4 = 24; new 12 x 4 = 48, which is double.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f1f25ed-36f1-40aa-8cec-91d37f8d6669', 'NC26.6.SGMR.1', 1, 'numeric', 'How area changes when a measurement changes', 'A parallelogram has a base of 6 inches and a height of 5 inches. The base is changed to 12 inches and the height stays 5 inches. What is the area of the new parallelogram in square inches?', '[]', '60', '12*5', 'The new area is base times height: $12 \times 5 = 60$ square inches. (The old area was 30, so the area doubled.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 5 = 60.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bee4bb64-5709-41af-9e06-36401fbaadeb', 'NC26.6.SGMR.1', 1, 'choice', 'How area changes when a measurement changes', 'Triangle A has a base of 8 centimeters and a height of 6 centimeters. Triangle B has the same base and a height of 12 centimeters. How does the area of B compare with the area of A?', '["B has the same area as A.","B has half the area of A.","B has twice the area of A.","B has 6 square centimeters more area than A."]', 'B has twice the area of A.', NULL, 'Triangle A has area $\frac{1}{2} \times 8 \times 6 = 24$ and triangle B has area $\frac{1}{2} \times 8 \times 12 = 48$. B has twice the area of A.', 'checked', '{"lint":[],"solve":{"answer":"B has twice the area of A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 1/2 x 8 x 6 = 24; B = 1/2 x 8 x 12 = 48; B is twice A (24 more, not 6).","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5d51b5-8f70-47d7-8d66-9f09b20cac15', 'NC26.6.SGMR.1', 1, 'choice', 'Choosing the right measurements and checking an answer', 'Which measurement is the height of a parallelogram?', '["The length of a slanted side","The distance between a base and the opposite side, measured at a right angle","The distance around the parallelogram","The length of the longest side"]', 'The distance between a base and the opposite side, measured at a right angle', NULL, 'The height is measured at a right angle to the base, from the base to the opposite side. A slanted side is longer than the height, so it cannot be used in its place.', 'checked', '{"lint":[],"solve":{"answer":"The distance between a base and the opposite side, measured at a right angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height is the perpendicular distance between a base and the opposite side.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df6fa304-9514-4e6f-bb9b-461bf733ea0f', 'NC26.6.SGMR.1', 1, 'choice', 'Choosing the right measurements and checking an answer', 'Marcus found the area of a triangle with a base of 14 centimeters and a height of 6 centimeters by calculating $14 \times 6 = 84$. What did Marcus forget to do?', '["Add 14 and 6","Double 84","Take half of 84","Divide 84 by 14"]', 'Take half of 84', NULL, 'The area of a triangle is half of base times height. Half of 84 is 42 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"Take half of 84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle area is 1/2 x b x h = 42; he forgot to halve 84.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5f31735-cbab-479d-a0a0-7a9aff0e6962', 'NC26.6.SGMR.1', 1, 'choice', 'Choosing the right measurements and checking an answer', 'A right triangle has sides of 6 cm, 8 cm and 10 cm. Which two sides can be used as the base and the height to find its area?', '["6 cm and 10 cm","8 cm and 10 cm","Any two of the sides","6 cm and 8 cm"]', '6 cm and 8 cm', NULL, 'In a right triangle, the two sides that meet at the right angle are at right angles to each other, so one is the base and the other is the height. The area is $\frac{1}{2} \times 6 \times 8 = 24$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6 cm and 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In a right triangle the two legs (6 and 8, the shorter sides; 10 is the hypotenuse) are perpendicular, so they serve as base and height. Area 24.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8524823d-2407-4a70-8931-07b0169fc153', 'NC26.6.SGMR.1', 2, 'numeric', 'Finding a triangle''s height from its area and base', 'A triangle has an area of 40 square centimeters and a base of 10 centimeters. What is its height in centimeters?', '[]', '8', '2*40/10', 'Area $= \frac{1}{2} \times \text{base} \times \text{height}$, so $40 = \frac{1}{2} \times 10 \times h = 5h$. Then $h = 40 \div 5 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 = 1/2 x 10 x h = 5h, so h = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('525030dc-570f-4012-abbc-e0f46232152b', 'NC26.6.SGMR.1', 2, 'choice', 'Parallelogram area uses the height, not the slanted side', 'A parallelogram has a base of 10 centimeters. Its slanted side is 6 centimeters long, and its height (measured at a right angle to the base) is 5 centimeters. What is its area in square centimeters?', '["$60$","$25$","$50$","$16$"]', '$50$', '10*5', 'Area is base times height: $10 \times 5 = 50$ square centimeters. The slanted side is not the height, so $10 \times 6 = 60$ is wrong. (25 halves the product as if it were a triangle, and 16 adds $10 + 6$.)', 'checked', '{"lint":[],"solve":{"answer":"$50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = base x perpendicular height = 10 x 5 = 50. The slanted side (6) is not used.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('874e264c-f4af-452c-88bc-caedfa61f8b9', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a composite figure made of two rectangles', 'An L-shaped patio is made from two rectangles that do not overlap. One rectangle is 8 meters by 5 meters. The other is 4 meters by 3 meters. What is the total area of the patio in square meters?', '["$52$","$28$","$20$","$12$"]', '$52$', '8*5+4*3', 'Add the areas of the two rectangles: $8 \times 5 = 40$ and $4 \times 3 = 12$, so the total is $40 + 12 = 52$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"$52$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 5 = 40 and 4 x 3 = 12; total 40 + 12 = 52.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('639d9254-5d58-4409-a174-90c2114cafd6', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a triangle from its base and height', 'A triangular sail has a bottom edge 9 feet long. The sail is 12 feet tall, measured straight up from the bottom edge. What is the area of the sail in square feet?', '[]', '54', '1/2*9*12', 'The base is 9 feet and the height is 12 feet. Area $= \frac{1}{2} \times 9 \times 12 = 54$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 9, height 12 (perpendicular). 1/2 x 9 x 12 = 54.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
