INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3e51863-a826-43bb-879d-7c4d1dd8a1c4', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a triangle from its base and height', 'Which triangle has an area of 30 square centimeters?', '["Base 6 cm, height 5 cm","Base 8 cm, height 8 cm","Base 12 cm, height 5 cm","Base 7 cm, height 9 cm"]', 'Base 12 cm, height 5 cm', NULL, 'Half of 12 times 5 is 30. The triangle with base 6 and height 5 has a product of 30, but its area is half of that, 15. The other two have areas 32 and 31.5.', 'checked', '{"lint":[],"solve":{"answer":"Base 12 cm, height 5 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x9/2 = 31.5; 8x8/2 = 32; 12x5/2 = 30; 6x5/2 = 15. Only 12 and 5 gives 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2d3048c-ba97-4807-81f2-f052b6afa7f5', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a triangle from its base and height', 'A triangular garden bed has a base of 7.5 meters and a height of 4 meters. What is its area in square meters?', '[]', '15', '1/2*7.5*4', 'Area $= \frac{1}{2} \times 7.5 \times 4$. Half of 4 is 2, and $7.5 \times 2 = 15$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 7.5 x 4 = 15.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
