INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fab5fe2-65ef-409e-a79c-d5bc43234efa', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a parallelogram from its base and height', 'A field is shaped like a parallelogram. One side along a road is 25 meters long, and the distance from that side to the opposite side is 14 meters. What is the area of the field in square meters?', '[]', '350', '25*14', 'The base is 25 meters and the height is 14 meters. Area $= 25 \times 14 = 350$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 25, height (distance between the parallel sides) 14. 25 x 14 = 350.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
