INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32b912cd-b96d-45f7-b44c-eda180812392', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a parallelogram from its base and height', 'Which is the area, in square centimeters, of a parallelogram with a base of 4.5 centimeters and a height of 6 centimeters?', '["54","13.5","27","10.5"]', '27', '4.5*6', 'Area $= 4.5 \times 6 = 27$ square centimeters. Half of 27 is 13.5, which would be a triangle, and 10.5 is the sum of the two numbers.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.5 x 6 = 27.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
