INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcce9a69-9507-4916-a853-c1e2459f2eda', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a trapezoid', 'A table top is shaped like a trapezoid. Its two parallel edges are 12 decimeters and 8 decimeters long, and they are 6 decimeters apart. What is the area of the table top in square decimeters?', '[]', '60', '1/2*(12+8)*6', 'Area $= \frac{1}{2} \times (12 + 8) \times 6 = \frac{1}{2} \times 20 \times 6 = 60$ square decimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: decimeters are rarely used in US Grade 6 work; centimeters or feet would read more naturally. Does not affect the answer.","work":"1/2 x (12 + 8) x 6 = 10 x 6 = 60.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
