INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c560713e-62ea-40f7-b2c8-06a3cf081d79', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a trapezoid', 'A trapezoid has parallel sides of 9 meters and 15 meters. Its height is 7 meters. What is its area in square meters?', '["168","105","84","63"]', '84', '1/2*(9+15)*7', 'Area $= \frac{1}{2} \times (9 + 15) \times 7 = 12 \times 7 = 84$ square meters. A result of 168 forgets to take half, and 105 and 63 use only one of the parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (9 + 15) x 7 = 12 x 7 = 84.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
