INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66163fd4-ddf8-4f7f-93a8-d45d778bbdb2', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a trapezoid', 'A flower bed is shaped like a trapezoid. The fence along the wall is 17 feet long, and the fence on the opposite side, which is parallel to the wall, is 11 feet long. The bed is 10 feet wide from one fence to the other. What is the area of the flower bed in square feet?', '[]', '140', '1/2*(17+11)*10', 'The parallel sides are 17 and 11 feet, and the height is 10 feet. Area $= \frac{1}{2} \times 28 \times 10 = 140$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel sides 17 and 11, distance between them 10. 1/2 x 28 x 10 = 140.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
