INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45daf670-2025-4fc4-a535-9ee11cab0162', 'NC26.6.SGMR.1', 2, 'numeric', 'Finding a missing base or height from the area', 'A lawn is shaped like a parallelogram. Its area is 195 square meters and its base is 15 meters. What is the distance between the base and the opposite side, in meters?', '[]', '13', '195/15', 'The distance between the base and the opposite side is the height. Height $=$ area $\div$ base $= 195 \div 15 = 13$ meters.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 195 / 15 = 13.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
