INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70acb23e-d684-4439-8841-0a967c0ee897', 'NC26.6.SGMR.1', 2, 'choice', 'Finding a missing base or height from the area', 'A triangle has an area of 60 square centimeters and a height of 8 centimeters. What is the length of its base in centimeters?', '["7.5","68","15","3.75"]', '15', '2*60/8', 'Base $\times$ height $= 2 \times 60 = 120$, so the base is $120 \div 8 = 15$ centimeters. A result of 7.5 forgets to double the area first.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = 1/2 x b x 8 = 4b, so b = 15.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63e5224d-f1b2-402a-ab2d-52788b16326d', 'NC26.6.SGMR.1', 2, 'numeric', 'Finding a missing base or height from the area', 'A triangular sail has an area of 33 square feet and a height of 6 feet. How long is its base in feet?', '[]', '11', '2*33/6', 'Twice the area is $2 \times 33 = 66$, which equals base times height. So the base is $66 \div 6 = 11$ feet.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"33 = 1/2 x b x 6 = 3b, so b = 11.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff2722a0-567d-4590-b899-c5c7e2699cfa', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a composite figure made of rectangles', 'An L-shaped room is made by taking a rectangle 12 meters long and 9 meters wide and cutting a rectangle 5 meters by 4 meters out of one corner. What is the area of the room in square meters?', '[]', '88', '12*9-5*4', 'The full rectangle has area $12 \times 9 = 108$. The corner that is cut out has area $5 \times 4 = 20$. The room has area $108 - 20 = 88$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 9 - 5 x 4 = 108 - 20 = 88.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('989f475b-d9fe-4457-a370-b32fa65043cb', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a composite figure made of rectangles', 'A shape is made of three rectangles that do not overlap. Their sizes are 6 by 3, 4 by 4 and 5 by 2 (all in centimeters). What is the total area of the shape in square centimeters?', '["34","44","28","24"]', '44', '6*3+4*4+5*2', 'The areas are $6 \times 3 = 18$, $4 \times 4 = 16$ and $5 \times 2 = 10$. The total is $18 + 16 + 10 = 44$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x3 + 4x4 + 5x2 = 18 + 16 + 10 = 44.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('301321f3-00f1-4f43-90e8-9e3172533693', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a composite figure made of rectangles', 'A picture frame is a rectangle 14 inches long and 10 inches wide. The opening in the middle is a rectangle 10 inches long and 6 inches wide. What is the area of the frame itself, not counting the opening, in square inches?', '[]', '80', '14*10-10*6', 'The whole rectangle has area $14 \times 10 = 140$. The opening has area $10 \times 6 = 60$. The frame is $140 - 60 = 80$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 10 - 10 x 6 = 140 - 60 = 80.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
