INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb7ee1d-e6c2-4e16-b295-58b9c75d8e3b', 'NC26.6.SGMR.1', 2, 'choice', 'Composing and decomposing shapes', 'A parallelogram has a base of 12 centimeters and a height of 5 centimeters. A straight cut along a diagonal divides it into two identical triangles. What is the area of one triangle in square centimeters?', '["60","17","15","30"]', '30', '12*5/2', 'The parallelogram has area $12 \times 5 = 60$. The two triangles are identical, so each has half of that, 30 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram 12 x 5 = 60; half is 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
