INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0fe2b6d-3b0c-4eee-a3a1-548245342956', 'NC26.6.SGMR.1', 2, 'numeric', 'Solving area problems in context', 'A wall is shaped like a trapezoid. Its top edge is 4 meters long, its bottom edge is 8 meters long, and its height is 5 meters. One liter of paint covers 6 square meters. How many liters are needed to paint the wall once?', '[]', '5', '1/2*(4+8)*5/6', 'The wall has area $\frac{1}{2} \times (4 + 8) \times 5 = 30$ square meters. At 6 square meters per liter, $30 \div 6 = 5$ liters are needed.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x (4 + 8) x 5 = 30; 30 / 6 = 5 liters.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35d9c1c8-bae1-4193-b385-a81882479c9c', 'NC26.6.SGMR.1', 2, 'numeric', 'How area changes when a measurement changes', 'A triangle has a base of 6 centimeters and a height of 10 centimeters. Both the base and the height are doubled. How many times as large is the area of the new triangle as the area of the original triangle?', '[]', '4', '(1/2*12*20)/(1/2*6*10)', 'The original area is $\frac{1}{2} \times 6 \times 10 = 30$. The new triangle has base 12 and height 20, so its area is $\frac{1}{2} \times 12 \times 20 = 120$. Since $120 \div 30 = 4$, the new area is 4 times as large.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original 1/2 x 6 x 10 = 30; new 1/2 x 12 x 20 = 120; 120 / 30 = 4.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75e8fa1d-037a-4437-8992-fc94b2a3c230', 'NC26.6.SGMR.1', 2, 'choice', 'How area changes when a measurement changes', 'The base of a parallelogram is 9 centimeters and its height is 6 centimeters. The base is made one-third as long and the height stays the same. What is the area of the new parallelogram in square centimeters?', '["162","36","27","18"]', '18', '9/3*6', 'The new base is $9 \div 3 = 3$ centimeters. The new area is $3 \times 6 = 18$ square centimeters, one-third of the original 54.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New base 9 / 3 = 3; area 3 x 6 = 18.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
