INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05732ff8-b231-4abd-8358-76b9dd5b9e79', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a polygon made of a rectangle and a triangle', 'A lot is shaped like a rectangle with a triangle attached along one of its 10-meter sides. The rectangle is 10 meters by 6 meters. The triangle has a base of 10 meters and a height of 4 meters. What is the total area of the lot in square meters?', '[]', '80', '10*6+1/2*10*4', 'Rectangle: $10 \times 6 = 60$. Triangle: $\frac{1}{2} \times 10 \times 4 = 20$. Total: $60 + 20 = 80$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60. Triangle 1/2 x 10 x 4 = 20. Total 80.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aea86c61-d900-485f-895b-8b6348f00cc0', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a triangle from its base and height', 'Triangle P has a base of 14 centimeters and a height of 9 centimeters. Triangle Q has a base of 10 centimeters and a height of 12 centimeters. How many square centimeters larger is the area of triangle P than the area of triangle Q?', '[]', '3', '1/2*14*9-1/2*10*12', 'Triangle P: $\frac{1}{2} \times 14 \times 9 = 63$. Triangle Q: $\frac{1}{2} \times 10 \times 12 = 60$. The difference is $63 - 60 = 3$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 1/2 x 14 x 9 = 63. Q = 1/2 x 10 x 12 = 60. 63 - 60 = 3.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0d905b0-c88a-4f2c-bbce-69540d0c770c', 'NC26.6.SGMR.1', 3, 'choice', 'Area of a triangle from its base and height', 'Which of these triangles has the greatest area?', '["Base 12 m, height 5 m","Base 7 m, height 9 m","Base 15 m, height 4 m","Base 6.5 m, height 10 m"]', 'Base 6.5 m, height 10 m', NULL, 'The areas are 30, 31.5, 30 and 32.5 square meters. The triangle with base 6.5 m and height 10 m has the greatest area, $\frac{1}{2} \times 6.5 \times 10 = 32.5$.', 'checked', '{"lint":[],"solve":{"answer":"Base 6.5 m, height 10 m","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15x4/2 = 30; 7x9/2 = 31.5; 6.5x10/2 = 32.5; 12x5/2 = 30. Greatest 32.5.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7632b9b5-49fd-48a3-a220-6f07c6d50a63', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a triangle from its base and height', 'The base of a triangle is 2.4 meters. Its height is 3.5 meters. What is the area of the triangle in square meters?', '[]', '4.2', '1/2*2.4*3.5', '$\frac{1}{2} \times 2.4 = 1.2$, and $1.2 \times 3.5 = 4.2$. The area is 4.2 square meters.', 'checked', '{"lint":[],"solve":{"answer":"4.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4 x 3.5 = 8.4; half is 4.2.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
