INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b440ef3-4069-4092-8733-8f1fa55bd6c7', 'NC26.6.SGMR.1', 3, 'choice', 'Area of a parallelogram from its base and height', 'A rhombus has sides of 10 centimeters. The distance between two opposite sides is 8 centimeters. What is the area of the rhombus in square centimeters?', '["40","100","18","80"]', '80', '10*8', 'A rhombus is a parallelogram. Use one side as the base (10 cm) and the distance between opposite sides as the height (8 cm): $10 \times 8 = 80$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus is a parallelogram: base 10, height 8, area 80. (Height 8 <= side 10, consistent.)","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
