INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f5535d6-4ad7-4612-85da-69b19dc3aecd', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a parallelogram from its base and height', 'A parallelogram has a base of 2.5 meters and a height of 3.2 meters. What is its area in square meters?', '[]', '8', '2.5*3.2', 'Area $= 2.5 \times 3.2$. Since $25 \times 32 = 800$ and there are two decimal places in total, the area is 8 square meters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5 x 3.2 = 8.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
