INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e01e9d0-734b-42fd-956a-592e0c4ee849', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a parallelogram from its base and height', 'A parallelogram has a base of 14 inches and a height of 9 inches. A rectangle has the same area as the parallelogram and a length of 18 inches. What is the width of the rectangle in inches?', '[]', '7', '14*9/18', 'The parallelogram''s area is $14 \times 9 = 126$ square inches. The rectangle has length times width equal to 126, so its width is $126 \div 18 = 7$ inches.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram area 14 x 9 = 126. Width = 126 / 18 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
