INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f8058c-e152-49e9-977e-6dedc3be1605', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has an area of 54 square centimeters. Its parallel sides are 5 centimeters and 13 centimeters long. What is its height in centimeters?', '[]', '6', '54*2/(5+13)', 'Area $= \frac{1}{2} \times (5 + 13) \times h = 9h$. So $9h = 54$ and $h = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 = 1/2 x (5 + 13) x h = 9h, so h = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dba538ca-111d-45a3-af17-303d6fd129d3', 'NC26.6.SGMR.1', 3, 'choice', 'Area of a trapezoid', 'Which trapezoid has the greatest area?', '["Parallel sides 6 cm and 10 cm, height 7 cm","Parallel sides 4 cm and 12 cm, height 8 cm","Parallel sides 9 cm and 9 cm, height 6 cm","Parallel sides 5 cm and 7 cm, height 11 cm"]', 'Parallel sides 5 cm and 7 cm, height 11 cm', NULL, 'The areas are 56, 64, 54 and 66 square centimeters. The trapezoid with parallel sides 5 and 7 and height 11 has area $\frac{1}{2} \times 12 \times 11 = 66$, the greatest.', 'checked', '{"lint":[],"solve":{"answer":"Parallel sides 5 cm and 7 cm, height 11 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a ''trapezoid'' with parallel sides 9 cm and 9 cm is a parallelogram; under the exclusive definition some students learn, it is not a trapezoid. It is a distractor, so the key is unaffected.","work":"9,9,h6: 9 x 6 = 54. 4,12,h8: 8 x 8 = 64. 5,7,h11: 6 x 11 = 66. 6,10,h7: 8 x 7 = 56. Greatest 66.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80cd97bd-c57a-4d02-820c-6afd8a07db1c', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has a top side of 6 centimeters. Its bottom side, which is parallel to the top, is twice as long as the top side. The height is 5 centimeters. What is the area of the trapezoid in square centimeters?', '[]', '45', '1/2*(6+2*6)*5', 'The bottom side is $2 \times 6 = 12$ centimeters. Area $= \frac{1}{2} \times (6 + 12) \times 5 = 9 \times 5 = 45$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom = 2 x 6 = 12. 1/2 x (6 + 12) x 5 = 9 x 5 = 45.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcd4b672-b093-40d1-b401-992b09e45811', 'NC26.6.SGMR.1', 3, 'numeric', 'Finding a missing base or height from the area', 'A triangle has an area of 36 square centimeters and a base of 9 centimeters. A parallelogram has the same height as the triangle and a base of 5 centimeters. What is the area of the parallelogram in square centimeters?', '[]', '40', '(2*36/9)*5', 'The triangle''s height is $2 \times 36 \div 9 = 8$ centimeters. The parallelogram has height 8 and base 5, so its area is $5 \times 8 = 40$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle: 36 = 1/2 x 9 x h, so h = 8. Parallelogram: 5 x 8 = 40.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
