INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b74ac9b2-5354-43f8-9492-6f0e499eeb64', 'NC26.6.SGMR.1', 3, 'numeric', 'Finding a missing base or height from the area', 'A rectangle has an area of 96 square inches and a width of 8 inches. A triangle has a base equal to the length of the rectangle and an area of 42 square inches. What is the height of the triangle in inches?', '[]', '7', '2*42/(96/8)', 'The rectangle''s length is $96 \div 8 = 12$ inches, so the triangle''s base is 12. Base $\times$ height $= 2 \times 42 = 84$, so the height is $84 \div 12 = 7$ inches.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle length = 96 / 8 = 12. Triangle: 42 = 1/2 x 12 x h = 6h, so h = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
