INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db776ae2-abbc-4e2e-9cf2-0269fd33a947', 'NC26.6.SGMR.1', 3, 'choice', 'Finding a missing base or height from the area', 'A parallelogram has an area of 7.2 square meters and a height of 1.2 meters. What is the length of its base in meters?', '["8.64","3.6","8.4","6"]', '6', '7.2/1.2', 'Base $=$ area $\div$ height $= 7.2 \div 1.2 = 6$ meters. (Check: $6 \times 1.2 = 7.2$.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.2 / 1.2 = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e34fbfe7-075f-427f-a0e2-9db6c5af866f', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a composite figure made of rectangles', 'A wall is 8 meters long and 3 meters high. It has a door that is 2 meters high and 1 meter wide, and two windows that are each 1.5 meters wide and 1 meter high. Paint will cover everything except the door and the windows. What is the area to be painted, in square meters?', '[]', '19', '8*3-2*1-2*1.5*1', 'The wall has area $8 \times 3 = 24$. The door takes $2 \times 1 = 2$ and the two windows take $2 \times 1.5 \times 1 = 3$. The painted area is $24 - 2 - 3 = 19$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wall 8 x 3 = 24. Door 2 x 1 = 2. Windows 2 x (1.5 x 1) = 3. 24 - 2 - 3 = 19.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb564d1-d03f-4279-963b-bbeddf14d11c', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a composite figure made of rectangles', 'A rectangular garden is 9 meters long and 5 meters wide. A sidewalk 2 meters wide goes all the way around the garden. What is the area of the sidewalk in square meters?', '[]', '72', '(9+4)*(5+4)-9*5', 'The sidewalk adds 2 meters on each side, so the garden and sidewalk together form a rectangle $9 + 4 = 13$ meters by $5 + 4 = 9$ meters, with area $13 \times 9 = 117$. Subtract the garden, $9 \times 5 = 45$: $117 - 45 = 72$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer rectangle (9+4) by (5+4) = 13 x 9 = 117. Garden 9 x 5 = 45. Sidewalk 117 - 45 = 72.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf44e898-1b1e-4b87-8ee9-f1cb458320c5', 'NC26.6.SGMR.1', 3, 'choice', 'Area of a composite figure made of rectangles', 'A T-shaped figure is made of two rectangles that do not overlap. The top bar is 12 centimeters long and 3 centimeters wide. The stem below it is 3 centimeters wide and 7 centimeters long. What is the area of the figure in square centimeters?', '["36","21","57","84"]', '57', '12*3+3*7', 'The top bar has area $12 \times 3 = 36$ and the stem has area $3 \times 7 = 21$. The total is $36 + 21 = 57$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bar 12 x 3 = 36; stem 3 x 7 = 21; total 57.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ed1fb97-6698-455c-bc9e-6458025f5b6e', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a composite figure that includes triangles', 'A rectangular lot is 14 meters by 10 meters. Two opposite corners are cut off, and each piece that is cut off is a right triangle with legs of 4 meters and 3 meters. What is the area of the lot that is left, in square meters?', '[]', '128', '14*10-2*(1/2*4*3)', 'The rectangle has area $14 \times 10 = 140$. Each triangle has area $\frac{1}{2} \times 4 \times 3 = 6$, so the two triangles take away 12. The lot has area $140 - 12 = 128$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lot 14 x 10 = 140; each corner 1/2 x 4 x 3 = 6, two = 12; 140 - 12 = 128.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('143db3d5-76f1-4670-8061-9ebd72374c3d', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a composite figure that includes triangles', 'A triangle with a base of 10 centimeters and a height of 7 centimeters is joined along its base to a trapezoid. The trapezoid has parallel sides of 10 centimeters and 6 centimeters and a height of 4 centimeters, and its 10-centimeter side is the shared edge. What is the total area of the shape in square centimeters?', '[]', '67', '1/2*10*7+1/2*(10+6)*4', 'The triangle has area $\frac{1}{2} \times 10 \times 7 = 35$. The trapezoid has area $\frac{1}{2} \times (10 + 6) \times 4 = 32$. The total is $35 + 32 = 67$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle 1/2 x 10 x 7 = 35; trapezoid 1/2 x (10 + 6) x 4 = 32; total 67.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4807b61d-3ce3-499b-8c0d-9a12d2dbaff6', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a composite figure that includes triangles', 'A shape is made of a rectangle 9 centimeters long and 6 centimeters wide, with a triangle on top whose base is the 9-centimeter side. The total area of the shape is 72 square centimeters. What is the height of the triangle in centimeters?', '[]', '4', '(72-9*6)*2/9', 'The rectangle has area $9 \times 6 = 54$, so the triangle has area $72 - 54 = 18$. Base $\times$ height $= 2 \times 18 = 36$, so the height is $36 \div 9 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 9 x 6 = 54; triangle 72 - 54 = 18 = 1/2 x 9 x h, so h = 4.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('259c311f-66fc-4e9f-a47c-a57d477bd4b9', 'NC26.6.SGMR.1', 3, 'numeric', 'Composing and decomposing shapes', 'A four-sided shape has a diagonal that is 12 centimeters long. The diagonal splits the shape into two triangles. The corner of one triangle is 5 centimeters from the diagonal, and the corner of the other triangle is 7 centimeters from the diagonal, both measured at right angles. What is the area of the four-sided shape in square centimeters?', '[]', '72', '1/2*12*5+1/2*12*7', 'Use the diagonal as the base of both triangles. Their areas are $\frac{1}{2} \times 12 \times 5 = 30$ and $\frac{1}{2} \times 12 \times 7 = 42$. The shape has area $30 + 42 = 72$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangles on the 12 cm diagonal: 1/2 x 12 x 5 = 30 and 1/2 x 12 x 7 = 42; total 72.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('090abdf1-f7aa-4bc9-aa91-34ad6402891a', 'NC26.6.SGMR.1', 3, 'numeric', 'Composing and decomposing shapes', 'A rectangular sheet is 20 centimeters long and 12 centimeters wide. A right triangle with legs of 5 centimeters and 4 centimeters is cut off each of the four corners. What is the area of the sheet that is left, in square centimeters?', '[]', '200', '20*12-4*(1/2*5*4)', 'The sheet has area $20 \times 12 = 240$. Each corner triangle has area $\frac{1}{2} \times 5 \times 4 = 10$, and four of them take away 40. What is left is $240 - 40 = 200$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sheet 20 x 12 = 240; each corner 1/2 x 5 x 4 = 10, four = 40; 240 - 40 = 200. Corners fit (5+5 <= 12, 4+4 <= 20).","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9494799d-5d09-4c46-8ed0-6617f0ea1119', 'NC26.6.SGMR.1', 3, 'numeric', 'Composing and decomposing shapes', 'Eight identical triangles, each with an area of 15 square centimeters, are put together without gaps or overlaps to make a rectangle. The rectangle is 12 centimeters long. What is its width in centimeters?', '[]', '10', '8*15/12', 'The rectangle''s area is $8 \times 15 = 120$ square centimeters. Length times width is 120, so the width is $120 \div 12 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total area 8 x 15 = 120; width = 120 / 12 = 10.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
