INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63a81aea-e979-4d89-a1db-9bb6aeade611', 'NC26.6.SGMR.1', 3, 'numeric', 'Solving area problems in context', 'A rectangular lot is 20 meters by 12 meters. A road cuts off one corner, and the piece that is cut off is a right triangle with legs of 8 meters and 6 meters. The rest of the lot is sold for 3 dollars per square meter. How many dollars is the rest of the lot worth?', '[]', '648', '(20*12-1/2*8*6)*3', 'The lot has area $20 \times 12 = 240$. The corner has area $\frac{1}{2} \times 8 \times 6 = 24$, so $240 - 24 = 216$ square meters are left. At 3 dollars each, $216 \times 3 = 648$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"648","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lot 20 x 12 = 240; corner 1/2 x 8 x 6 = 24; rest 216; 216 x 3 = 648.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50885ef1-cd21-4739-b4e6-bbd7c064403f', 'NC26.6.SGMR.1', 3, 'choice', 'Solving area problems in context', 'A field is shaped like a trapezoid. Its parallel sides are 70 meters and 50 meters long, and they are 40 meters apart. One bag of fertilizer covers 400 square meters. How many bags are needed to cover the whole field?', '["6","12","24","3"]', '6', '1/2*(70+50)*40/400', 'The field has area $\frac{1}{2} \times (70 + 50) \times 40 = 2400$ square meters. Each bag covers 400, so $2400 \div 400 = 6$ bags are needed.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x (70 + 50) x 40 = 60 x 40 = 2400; 2400 / 400 = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
