INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fb6350e-938d-41de-8446-72eaf29c0d0b', 'NC26.6.SGMR.2', 1, 'choice', 'Reflecting a point across the x-axis or the y-axis', 'A point is reflected across the x-axis. What happens to its coordinates?', '["The x-coordinate stays the same and the y-coordinate changes sign.","The y-coordinate stays the same and the x-coordinate changes sign.","Both coordinates change sign.","The two coordinates swap places."]', 'The x-coordinate stays the same and the y-coordinate changes sign.', NULL, 'The x-axis is a horizontal line. A point and its reflection are the same distance from it on opposite sides, so the x-coordinate stays and the y-coordinate becomes its opposite.', 'checked', '{"lint":[],"solve":{"answer":"The x-coordinate stays the same and the y-coordinate changes sign.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across the x-axis keeps x and negates y.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
