INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('568f6b88-dd0c-410d-be72-80ebbf278c24', 'NC26.6.SGMR.2', 1, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A square has vertices at $(-2, -2)$, $(1, -2)$, $(1, 1)$ and $(-2, 1)$. What is its perimeter in units?', '[]', '12', '4*3', 'The bottom side runs from $x = -2$ to $x = 1$, which is 3 units. All four sides are 3 units, so the perimeter is $4 \times 3 = 12$ units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 1 - (-2) = 3; perimeter 12.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
