INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bd09e9a-d287-4fb6-9203-32d458f53280', 'NC26.6.SGMR.2', 1, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'One side of a rectangle goes from $(-2, 1)$ to $(3, 1)$. The rectangle extends 2 units upward from that side. What is its area in square units?', '[]', '10', '(3+2)*2', 'The side is $3 - (-2) = 5$ units long and the rectangle is 2 units tall. The area is $5 \times 2 = 10$ square units.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 3 - (-2) = 5; height 2; area 10.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
