INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0b0f54c-b95e-4e08-8d28-8a942c729c32', 'NC26.6.SGMR.2', 1, 'numeric', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A triangle has vertices at $(2, -1)$, $(2, 5)$ and $(5, 5)$. What is its area in square units?', '[]', '9', '1/2*6*3', 'One side is vertical, from $y = -1$ to $y = 5$, which is 6 units. Another is horizontal, from $x = 2$ to $x = 5$, which is 3 units. They meet at a right angle at $(2, 5)$, so the area is $\frac{1}{2} \times 6 \times 3 = 9$ square units.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right angle at (2,5): vertical leg 5 - (-1) = 6, horizontal leg 5 - 2 = 3. Area 9.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('841035e8-c10e-4dfe-8e6d-94d6e03353e5', 'NC26.6.SGMR.2', 1, 'choice', 'Finding a missing vertex or a point from conditions', 'Three corners of a square are $(0, 0)$, $(4, 0)$ and $(4, 4)$. What is the fourth corner?', '["$(0, -4)$","$(-4, 4)$","$(0, 4)$","$(4, -4)$"]', '$(0, 4)$', NULL, 'The corner opposite $(4, 0)$ is above $(0, 0)$ and level with $(4, 4)$. It has x-coordinate 0 and y-coordinate 4, so it is $(0, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right angle at (4,0); fourth corner completes the square: (0, 4).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
