INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b04d426-46e3-459d-9ba8-6e314deb5933', 'NC26.6.SGMR.2', 1, 'numeric', 'Finding a missing vertex or a point from conditions', 'Point $A$ is at $(2, 3)$. Point $B$ is 5 units to the right of $A$ on the same horizontal line. What is the x-coordinate of $B$?', '[]', '7', '2+5', 'Moving 5 units right adds 5 to the x-coordinate: $2 + 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 5 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
