INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06335979-db24-4e04-a960-801a6d0f45b4', 'NC26.6.SGMR.2', 2, 'choice', 'Naming the quadrant or axis of a point', 'The point $P$ is at $(-8, 5)$. Which statement is true?', '["P is to the right of the y-axis and above the x-axis.","P is to the left of the y-axis and below the x-axis.","P is to the right of the y-axis and below the x-axis.","P is to the left of the y-axis and above the x-axis."]', 'P is to the left of the y-axis and above the x-axis.', NULL, 'A negative x-coordinate puts a point to the left of the y-axis. A positive y-coordinate puts it above the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"P is to the left of the y-axis and above the x-axis.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = -8 < 0: left of y-axis; y = 5 > 0: above x-axis.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
