INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5032069-8eb9-40f0-851a-554a29f5278b', 'NC26.6.SGMR.2', 2, 'numeric', 'Reading ordered pairs and plotting by moves', 'A game piece is on the point $(-2, 3)$. It moves 5 units right and 6 units down. What is the y-coordinate of the point where it stops?', '[]', '-3', '3-6', 'Moving down 6 units lowers the y-coordinate: $3 - 6 = -3$. (The 5 units right changes only the x-coordinate, from $-2$ to 3.)', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y: 3 - 6 = -3. (x: -2 + 5 = 3.)","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
