INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f557b38b-9de4-479b-b520-b28a45e0b630', 'NC26.6.SGMR.2', 2, 'choice', 'Reflecting a point across the x-axis or the y-axis', 'The point $A$ is reflected across the y-axis to give the point $B$ at $(-7, -1)$. What are the coordinates of $A$?', '["$(-7, 1)$","$(7, 1)$","$(7, -1)$","$(-1, -7)$"]', '$(7, -1)$', NULL, 'A reflection across the y-axis changes the sign of the x-coordinate, so undoing it changes the sign again. $A$ is $(7, -1)$.', 'checked', '{"lint":[],"solve":{"answer":"$(7, -1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect B back across the y-axis: (7, -1).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19ed2a3b-4f88-473d-aa9f-7c4f11b0a5eb', 'NC26.6.SGMR.2', 2, 'choice', 'Reflections across both axes and what they preserve', 'The point $(-5, 3)$ is reflected across the x-axis, and the new point is then reflected across the y-axis. What are the coordinates of the final point?', '["$(-5, -3)$","$(5, 3)$","$(5, -3)$","$(3, -5)$"]', '$(5, -3)$', NULL, 'Across the x-axis: $(-5, 3)$ becomes $(-5, -3)$. Across the y-axis: $(-5, -3)$ becomes $(5, -3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-5,3) -> (-5,-3) -> (5,-3).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3b35849-c4e4-44c4-918e-3bb9d4ad8e39', 'NC26.6.SGMR.2', 2, 'numeric', 'Reflections across both axes and what they preserve', 'A triangle has vertices at $(1, 2)$, $(4, 2)$ and $(4, 6)$. It is reflected across the x-axis. What is the area of the reflected triangle in square units?', '[]', '6', '1/2*3*4', 'A reflection does not change the size or shape of a figure. The original triangle has a horizontal side from 1 to 4 (length 3) and a vertical side from 2 to 6 (length 4), so its area is $\frac{1}{2} \times 3 \times 4 = 6$. The reflected triangle also has area 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right triangle: legs 4 - 1 = 3 and 6 - 2 = 4. Area 1/2 x 3 x 4 = 6; a reflection keeps the area.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03db14a-619e-46ca-bdac-6925c5b968f0', 'NC26.6.SGMR.2', 2, 'numeric', 'Reflections across both axes and what they preserve', 'The point $(-4, 7)$ is reflected across the y-axis, and the new point is then reflected across the x-axis. What is the sum of the two coordinates of the final point?', '[]', '-3', '4-7', 'Across the y-axis: $(-4, 7)$ becomes $(4, 7)$. Across the x-axis: $(4, 7)$ becomes $(4, -7)$. The sum is $4 + (-7) = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4,7) -> (4,7) -> (4,-7). Sum 4 + (-7) = -3.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb26278c-9a7e-4170-9cfb-9413a3332126', 'NC26.6.SGMR.2', 2, 'choice', 'Distance between points that share a coordinate', 'Point $P$ is at $(-5, 3)$ and point $Q$ is at $(-5, -4)$. How many units apart are they?', '["1","9","7","12"]', '7', '3+4', 'The points are on opposite sides of the x-axis. The distance from $P$ to the axis is 3 and from $Q$ to the axis is 4, so the distance is $3 + 4 = 7$ units.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x: |3| + |-4| = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
