INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60ebf5cd-f9ff-4466-9d04-abcfa5390415', 'NC26.6.SGMR.2', 2, 'choice', 'Distance between points that share a coordinate', 'Which pair of points is exactly 10 units apart?', '["$(-2, 5)$ and $(-2, -4)$","$(3, -6)$ and $(3, 6)$","$(-7, -1)$ and $(1, -1)$","$(-2, 5)$ and $(8, 5)$"]', '$(-2, 5)$ and $(8, 5)$', NULL, '$(-2, 5)$ and $(8, 5)$ share a y-coordinate, and $2 + 8 = 10$. The other pairs are 9, 12 and 8 units apart.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, 5)$ and $(8, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12; 9; 8 - (-2) = 10; 1 - (-7) = 8. Only (-2,5) and (8,5).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
