INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('703ec746-8bc2-4b7c-adea-cab7ea25a22e', 'NC26.6.SGMR.2', 2, 'choice', 'Distance from a point to an axis', 'Which point is closest to the x-axis?', '["$(-2, 5)$","$(0, 3)$","$(8, -1)$","$(-6, -4)$"]', '$(8, -1)$', NULL, 'The distance from the x-axis is the size of the y-coordinate: 1, 5, 3 and 4 for the four points. $(8, -1)$ is closest.', 'checked', '{"lint":[],"solve":{"answer":"$(8, -1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|y| values: 4, 3, 1, 5. Smallest is (8, -1).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
