INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99cc3ea3-feac-462a-a7fd-2231665bdf65', 'NC26.6.SGMR.2', 2, 'choice', 'Area of a rectangle or square on the coordinate plane', 'A rectangle has sides parallel to the axes. Which pair of opposite corners gives a rectangle with an area of 24 square units?', '["$(-3, -3)$ and $(2, 2)$","$(0, 0)$ and $(6, 4)$","$(1, 1)$ and $(7, 6)$","$(-5, 0)$ and $(-1, 8)$"]', '$(0, 0)$ and $(6, 4)$', NULL, 'The areas are $6 \times 4 = 24$, $5 \times 5 = 25$, $6 \times 5 = 30$ and $4 \times 8 = 32$ square units. Only $(0, 0)$ and $(6, 4)$ give 24.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 0)$ and $(6, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x5 = 25; 6x4 = 24; 6x5 = 30; 4x8 = 32. Only (0,0) and (6,4).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
