INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c93ec87b-1bb0-44e5-b14c-ff802f512fcf', 'NC26.6.SGMR.2', 2, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'The sides of a rectangle are parallel to the axes. One of its diagonals runs from $(-6, -2)$ to $(1, 3)$. What is the area of the rectangle in square units?', '[]', '35', '(1+6)*(3+2)', 'The rectangle is $1 - (-6) = 7$ units wide and $3 - (-2) = 5$ units tall. The area is $7 \times 5 = 35$ square units.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 1 - (-6) = 7; height 3 - (-2) = 5; area 35.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
