INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c91f7419-9b55-43ad-8228-a4a3c147aba4', 'NC26.6.SGMR.2', 2, 'numeric', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A parallelogram has vertices at $(0, 0)$, $(5, 0)$, $(7, 3)$ and $(2, 3)$. What is its area in square units?', '[]', '15', '5*3', 'The bottom side from $(0, 0)$ to $(5, 0)$ is the base, 5 units long. The top side is 3 units above it, so the height is 3. Area $= 5 \times 3 = 15$ square units.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 5 (on y = 0), height 3: area 15.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
