INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2ded65c-07f6-4b36-a204-00053f13baee', 'NC26.6.SGMR.2', 2, 'choice', 'Finding a missing vertex or a point from conditions', 'A rectangle has sides parallel to the axes. Three of its vertices are $A(-6, -2)$, $B(-6, 3)$ and $C(1, 3)$. What are the coordinates of the fourth vertex, $D$?', '["$(1, 2)$","$(-1, -2)$","$(-2, 1)$","$(1, -2)$"]', '$(1, -2)$', NULL, '$D$ is below $C$ and to the right of $A$. It shares the x-coordinate of $C$ (1) and the y-coordinate of $A$ ($-2$), so it is $(1, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB vertical (x = -6), BC horizontal (y = 3). D has C''s x and A''s y: (1, -2).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
