INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e568bbb5-8ff8-4986-9fbf-9f40e174bf81', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a right triangle on the coordinate plane', 'A triangle has vertices at $(-3, -2)$, $(5, -2)$ and $(5, 4)$. What is its area in square units?', '[]', '24', '1/2*8*6', 'The side from $(-3, -2)$ to $(5, -2)$ is horizontal and is $5 - (-3) = 8$ units long. The side from $(5, -2)$ to $(5, 4)$ is vertical and is $4 - (-2) = 6$ units long. They meet at a right angle, so the area is $\frac{1}{2} \times 8 \times 6 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base along y = -2 from x = -3 to 5: 8. Height along x = 5 from y = -2 to 4: 6. Right triangle area = 1/2 x 8 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cee0f6ae-049b-4116-975e-039804bc3bfd', 'NC26.6.SGMR.2', 3, 'choice', 'Finding the fourth vertex of a rectangle', 'Three vertices of a rectangle are $(-3, 4)$, $(5, 4)$ and $(5, -2)$. The sides are parallel to the axes. What is the fourth vertex?', '["$(3, -2)$","$(-3, -2)$","$(-3, 2)$","$(-2, -3)$"]', '$(-3, -2)$', NULL, 'The fourth vertex shares its x-coordinate with $(-3, 4)$, which is $-3$, and its y-coordinate with $(5, -2)$, which is $-2$. So it is $(-3, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-3, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Missing corner takes x from (-3, 4) and y from (5, -2): (-3, -2).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0960f1fa-b512-4971-958e-29202d003fdb', 'NC26.6.SGMR.2', 3, 'numeric', 'Naming the quadrant or axis of a point', 'Here are six points: $(0, 5)$, $(-3, 0)$, $(4, -4)$, $(-6, -2)$, $(0, 0)$ and $(1, 8)$. How many of them do not lie in any quadrant?', '[]', '3', '3', 'A point is in no quadrant when it is on an axis, which means at least one coordinate is 0. Those points are $(0, 5)$, $(-3, 0)$ and $(0, 0)$, so the answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points on an axis lie in no quadrant: (0,5), (-3,0), (0,0). Count 3.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('527b34f7-4f6d-48a4-9d01-4053ff6303da', 'NC26.6.SGMR.2', 3, 'choice', 'Naming the quadrant or axis of a point', 'The point $(x, y)$ is in Quadrant II. In which quadrant is the point $(x, -y)$? Quadrant I is where both coordinates are positive, and the quadrants are numbered I, II, III, IV going counterclockwise from there.', '["Quadrant I","Quadrant III","Quadrant II","Quadrant IV"]', 'Quadrant III', NULL, 'In Quadrant II, x is negative and y is positive, so $-y$ is negative. The new point has a negative x-coordinate and a negative y-coordinate, which is Quadrant III.', 'checked', '{"lint":[],"solve":{"answer":"Quadrant III","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant II: x < 0, y > 0. Then (x, -y) has x < 0 and -y < 0: Quadrant III.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08dbc7b9-4016-4ef3-bd8c-d9d06423b46d', 'NC26.6.SGMR.2', 3, 'numeric', 'Reading ordered pairs and plotting by moves', 'Ann starts at the point $(-6, 2)$. She moves 9 units right and 8 units down, and then 5 units left. What is the x-coordinate of the point where she stops?', '[]', '-2', '-6+9-5', 'Only the horizontal moves change the x-coordinate: $-6 + 9 = 3$, and $3 - 5 = -2$. Ann stops with an x-coordinate of $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: -6 + 9 - 5 = -2.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c33fd46b-63d3-409f-a316-bf37a3e915d2', 'NC26.6.SGMR.2', 3, 'choice', 'Reading ordered pairs and plotting by moves', 'A point is 3 units to the left of the y-axis. It is twice as far below the x-axis as it is left of the y-axis. Which ordered pair names the point?', '["$(3, -6)$","$(-3, -6)$","$(-6, -3)$","$(-3, 6)$"]', '$(-3, -6)$', NULL, 'Left of the y-axis by 3 gives $x = -3$. Twice as far below the x-axis is $2 \times 3 = 6$ units below, so $y = -6$.', 'checked', '{"lint":[],"solve":{"answer":"$(-3, -6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 left: x = -3. Twice as far below: 6 below, y = -6. (-3, -6).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d82bd9-3ac7-4bc4-8450-54200364b800', 'NC26.6.SGMR.2', 3, 'choice', 'Reading ordered pairs and plotting by moves', 'Dana starts at $(-3, -3)$ on a grid. She moves 8 units right, 10 units up, 4 units left and 2 units down. Where does she end?', '["$(1, 9)$","$(9, 5)$","$(1, 5)$","$(5, 1)$"]', '$(1, 5)$', NULL, 'Horizontal: $-3 + 8 - 4 = 1$. Vertical: $-3 + 10 - 2 = 5$. Dana ends at $(1, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: -3 + 8 - 4 = 1; y: -3 + 10 - 2 = 5. (1, 5).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066a227c-c165-43df-a25b-03eeae5d5229', 'NC26.6.SGMR.2', 3, 'numeric', 'Reflecting a point across the x-axis or the y-axis', 'When the point $(a, b)$ is reflected across the y-axis, the new point is $(-2, 7)$. What is the value of $a + b$?', '[]', '9', '2+7', 'Reflecting across the y-axis changes the sign of the x-coordinate, so $a = 2$. The y-coordinate does not change, so $b = 7$. Then $a + b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a, b) -> (-a, b) = (-2, 7): a = 2, b = 7. a + b = 9.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a72c02e3-8a71-4979-ae3e-c52c7ca08bc5', 'NC26.6.SGMR.2', 3, 'choice', 'Reflecting a point across the x-axis or the y-axis', 'Which point stays in exactly the same place when it is reflected across the x-axis?', '["$(0, 6)$","$(-6, 6)$","$(6, 6)$","$(6, 0)$"]', '$(6, 0)$', NULL, 'A point stays put only if it is on the line of reflection. The points on the x-axis have a y-coordinate of 0, and $(6, 0)$ is the only one listed. For example, $(0, 6)$ moves to $(0, -6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unchanged under x-axis reflection only if y = 0: (6, 0).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bb2574d-8c4e-47be-9f35-3fd441ce0386', 'NC26.6.SGMR.2', 3, 'numeric', 'Reflecting a point across the x-axis or the y-axis', 'The point $P$ is reflected across the y-axis, and the new point has an x-coordinate of $-8$. The same point $P$ is reflected across the x-axis, and that new point has a y-coordinate of $-3$. What is the x-coordinate of $P$ minus the y-coordinate of $P$?', '[]', '5', '8-3', 'The y-axis reflection flipped the sign of x, so $P$ has $x = 8$. The x-axis reflection flipped the sign of y, so $P$ has $y = 3$. Then $8 - 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis: -x = -8, so x = 8. Across x-axis: -y = -3, so y = 3. x - y = 5.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dcb4372-21c1-465b-9c8c-5d075efa5f04', 'NC26.6.SGMR.2', 3, 'choice', 'Reflections across both axes and what they preserve', 'The point $A$ is reflected across the x-axis, and the new point is then reflected across the y-axis. The final point is $(4, -7)$. What are the coordinates of $A$?', '["$(4, 7)$","$(-4, -7)$","$(4, -7)$","$(-4, 7)$"]', '$(-4, 7)$', NULL, 'Work backwards. Undo the y-axis reflection: $(4, -7)$ becomes $(-4, -7)$. Undo the x-axis reflection: $(-4, -7)$ becomes $(-4, 7)$. Check: $(-4, 7)$ goes to $(-4, -7)$, then to $(4, -7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-4, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both reflections negate both coordinates: A = (-4, 7). Check: (-4,7) -> (-4,-7) -> (4,-7).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efc03e5d-0dc8-4d5f-8222-12321466dfa0', 'NC26.6.SGMR.2', 3, 'numeric', 'Reflections across both axes and what they preserve', 'A point with a positive x-coordinate is reflected across the y-axis. The original point and the new point are 14 units apart. What is the x-coordinate of the original point?', '[]', '7', '14/2', 'The y-axis is halfway between the point and its reflection, and each is the same distance from it. So each is $14 \div 2 = 7$ units from the y-axis. The original x-coordinate is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) and (-x, y) are 2x apart: 2x = 14, x = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbb35203-5d2d-4e08-bcc4-7a5047e84f7e', 'NC26.6.SGMR.2', 3, 'choice', 'Reflections across both axes and what they preserve', 'Which point stays in the same place when it is reflected across the x-axis and then across the y-axis?', '["$(0, 0)$","$(0, 5)$","$(5, 0)$","$(5, 5)$"]', '$(0, 0)$', NULL, 'Both reflections change signs, and only 0 is its own opposite. The point must have both coordinates 0. For example, $(0, 5)$ goes to $(0, -5)$ and then stays $(0, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two reflections send (x, y) to (-x, -y); fixed only at (0, 0). (5,0)->(-5,0), (5,5)->(-5,-5), (0,5)->(0,-5).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98623723-1e7d-4fcb-b3bf-f895f3b2ca1a', 'NC26.6.SGMR.2', 3, 'numeric', 'Distance between points that share a coordinate', 'A hiker walks from $(-7, -2)$ straight to $(-7, 5)$ and then straight to $(4, 5)$. How many units does the hiker walk in all?', '[]', '18', '(5+2)+(7+4)', 'The first part is vertical: from $-2$ to 5 is $2 + 5 = 7$ units. The second part is horizontal: from $-7$ to 4 is $7 + 4 = 11$ units. The total is $7 + 11 = 18$ units.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical leg 5 - (-2) = 7; horizontal leg 4 - (-7) = 11. Total 18.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5993b8c-d583-4264-b403-12a6b698df1b', 'NC26.6.SGMR.2', 3, 'choice', 'Distance between points that share a coordinate', 'The number $a$ is positive. How many units apart are the points $(-a, 4)$ and $(a, 4)$?', '["$2a$","$a$","$0$","$a + 4$"]', '$2a$', NULL, 'The points have the same y-coordinate and are on opposite sides of the y-axis, each $a$ units from it. The distance is $a + a = 2a$.', 'checked', '{"lint":[],"solve":{"answer":"$2a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y; distance a - (-a) = 2a.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcc8777c-48f2-4b22-8a93-4149fef6d44c', 'NC26.6.SGMR.2', 3, 'numeric', 'Distance between points that share a coordinate', 'A triangle has vertices $A(-3, 2)$, $B(5, 2)$ and $C(5, -4)$. What is the sum of the lengths of side $AB$ and side $BC$, in units?', '[]', '14', '(3+5)+(2+4)', 'Side $AB$ is horizontal: $3 + 5 = 8$ units. Side $BC$ is vertical: from 2 down to $-4$ is $2 + 4 = 6$ units. The sum is $8 + 6 = 14$ units.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB: 5 - (-3) = 8. BC: 2 - (-4) = 6. Sum 14.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd5df4e4-faf6-4983-8df9-c88ece01b177', 'NC26.6.SGMR.2', 3, 'numeric', 'Distance from a point to an axis', 'A point in Quadrant III has an x-coordinate of $-9$. The point is 4 units farther from the x-axis than it is from the y-axis. What is its y-coordinate?', '[]', '-13', '0-(9+4)', 'The distance from the y-axis is 9, so the distance from the x-axis is $9 + 4 = 13$. In Quadrant III the y-coordinate is negative, so it is $-13$.', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance from y-axis 9; from x-axis 9 + 4 = 13. Quadrant III: y = -13.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2622895-73ad-44f0-95d6-b2a776e32180', 'NC26.6.SGMR.2', 3, 'choice', 'Distance from a point to an axis', 'Which point is exactly as far from the x-axis as it is from the y-axis?', '["$(-6, 6)$","$(6, -3)$","$(4, -8)$","$(-7, 0)$"]', '$(-6, 6)$', NULL, 'The point $(-6, 6)$ is 6 units from each axis. The others are 6 and 3, 4 and 8, and 7 and 0 units from the two axes.', 'checked', '{"lint":[],"solve":{"answer":"$(-6, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need |x| = |y|: (-7,0) 7 vs 0; (-6,6) 6 vs 6; (4,-8) 8 vs 4; (6,-3) 3 vs 6. Only (-6, 6).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
