INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eac37065-78d6-4cd8-97d3-6b718baf252d', 'NC26.6.SGMR.2', 3, 'choice', 'Perimeter of a polygon on the coordinate plane', 'Four rectangles have sides parallel to the axes and are given by two opposite corners. Which rectangle has the greatest perimeter?', '["Corners $(0, 0)$ and $(8, 3)$","Corners $(-2, -2)$ and $(3, 3)$","Corners $(-5, 1)$ and $(3, 5)$","Corners $(-10, 0)$ and $(2, 1)$"]', 'Corners $(-10, 0)$ and $(2, 1)$', NULL, 'The sizes are $12 \times 1$, $8 \times 3$, $5 \times 5$ and $8 \times 4$, with perimeters 26, 22, 20 and 24. The first, with corners $(-10, 0)$ and $(2, 1)$, is greatest.', 'checked', '{"lint":[],"solve":{"answer":"Corners $(-10, 0)$ and $(2, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x3: 22. 8x4: 24. 5x5: 20. 12x1: 26. Greatest 26.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2124607-1402-4f60-9a2f-d5ebfbed1e7f', 'NC26.6.SGMR.2', 3, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A rectangle has two vertices at $(-3, -1)$ and $(4, -1)$. Its perimeter is 30 units, and its other two vertices are above these two. What is the y-coordinate of the other two vertices?', '[]', '7', '-1+(30/2-7)', 'The known side is $4 - (-3) = 7$ units long. Half the perimeter is 15, so the other side is $15 - 7 = 8$ units. Going up 8 from $y = -1$ gives $y = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 4 - (-3) = 7. 2(7 + h) = 30, h = 8. y = -1 + 8 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93334619-d59b-49f6-a110-e71506c5047a', 'NC26.6.SGMR.2', 3, 'choice', 'Area of a rectangle or square on the coordinate plane', 'A square has two neighboring corners at $(-2, -5)$ and $(-2, 3)$. What is the area of the square in square units?', '["32","16","64","8"]', '64', '8*8', 'The two corners are joined by a side of length $3 - (-5) = 8$ units. The area is $8 \times 8 = 64$ square units.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 3 - (-5) = 8; area 64.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e396230-1d9c-4fce-a8b3-f50c11e2514b', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'A shape is made of two rectangles that share part of a side and do not overlap. The first has opposite corners at $(0, 0)$ and $(6, 4)$. The second has opposite corners at $(6, 0)$ and $(9, 2)$. What is the total area in square units?', '[]', '30', '6*4+3*2', 'The first rectangle is $6 \times 4 = 24$ square units. The second is $(9 - 6) \times (2 - 0) = 3 \times 2 = 6$ square units. The total is $24 + 6 = 30$ square units.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 6 x 4 = 24; second 3 x 2 = 6; total 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
