INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f65b6265-8c37-4ec2-947b-0b7ddc44ca1a', 'NC26.6.SGMR.3', 1, 'numeric', 'Counting faces, edges and vertices of prisms and pyramids', 'A triangular prism has two triangle bases joined by rectangles. How many faces does it have in all?', '[]', '5', '2+3', 'The 2 triangle bases each have 3 sides, and each side is joined by one rectangle, so there are 3 rectangles. The solid has $2 + 3 = 5$ faces.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 triangles + 3 rectangles = 5 faces.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db83f6a8-9065-4421-be92-f545798134b7', 'NC26.6.SGMR.3', 1, 'choice', 'Counting faces, edges and vertices of prisms and pyramids', 'Which of these solids has exactly 6 faces?', '["Triangular pyramid","Triangular prism","Rectangular prism","Pentagonal prism"]', 'Rectangular prism', NULL, 'A rectangular prism has 2 bases and 4 rectangles, which is 6 faces. A triangular pyramid has 4 faces, a triangular prism has $2 + 3 = 5$ faces and a pentagonal prism has $2 + 5 = 7$ faces.', 'checked', '{"lint":[],"solve":{"answer":"Rectangular prism","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangular prism 6; triangular prism 5; triangular pyramid 4; pentagonal prism 7.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94fd528b-e512-4b83-af62-d305c8d6deb4', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a cube', 'A wooden cube has edges of 4 centimeters. Every face is painted. What total area is painted, in square centimeters?', '[]', '96', '6*4^2', 'Each face is a square with area $4 \times 4 = 16$ square centimeters. A cube has 6 faces, so the painted area is $6 \times 16 = 96$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 faces x 4 x 4 = 6 x 16 = 96.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b05a481-a47a-49d3-8de2-1bff7c6de47b', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a cube', 'Each face of a cube has an area of 9 square inches. What is the surface area of the cube, in square inches?', '["54","36","27","81"]', '54', '6*9', 'A cube has 6 faces that all have the same area, so the surface area is $6 \times 9 = 54$ square inches. Using 4 faces would give 36, and 81 is $9 \times 9$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 9 = 54.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('627161de-6419-4538-beca-36c623076c3c', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'The faces of a rectangular prism come in three matching pairs. The areas of the three different faces are 12, 8 and 6 square centimeters. What is the surface area of the prism, in square centimeters?', '[]', '52', '2*(12+8+6)', 'Each of the three faces appears twice. The surface area is $2 \times (12 + 8 + 6) = 2 \times 26 = 52$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12 + 8 + 6) = 2 x 26 = 52.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7ad8ea8-fd6b-4ae0-9a8f-e60c288b3c90', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a rectangular prism', 'A rectangular prism is 5 inches long, 2 inches wide and 1 inch tall. Which expression gives its surface area in square inches?', '["$2(5 \\times 2) + 2(5 \\times 1) + 2(2 \\times 1)$","$5 \\times 2 \\times 1$","$(5 \\times 2) + (5 \\times 1) + (2 \\times 1)$","$2(5 + 2 + 1)$"]', '$2(5 \times 2) + 2(5 \times 1) + 2(2 \times 1)$', NULL, 'The prism has three kinds of faces, each appearing twice: $5 \times 2$, $5 \times 1$ and $2 \times 1$. Adding the areas of all 6 faces gives the first expression. The product $5 \times 2 \times 1$ is the volume, and the other two expressions leave out faces or do not multiply to find areas.', 'checked', '{"lint":[],"solve":{"answer":"$2(5 \\times 2) + 2(5 \\times 1) + 2(2 \\times 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SA = 2lw + 2lh + 2wh = 2(5x2) + 2(5x1) + 2(2x1) = 34. Other options: 16, 17, 10.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24c9246a-281d-41d6-9346-d8f6fcae8891', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'A small box is 5 centimeters long, 3 centimeters wide and 2 centimeters tall. How many square centimeters of paper cover the whole box?', '[]', '62', '2*(5*3+5*2+3*2)', 'The faces are $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$ square centimeters, each twice. The surface area is $2 \times (15 + 10 + 6) = 2 \times 31 = 62$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5x3 + 5x2 + 3x2) = 2(15 + 10 + 6) = 62.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72aa0267-2cab-4757-bf5e-9024ed2366b7', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'The top of a rectangular prism measures 6 centimeters by 3 centimeters. What is the combined area of the top and the bottom, in square centimeters?', '[]', '36', '2*6*3', 'The top and bottom are matching rectangles. Each has an area of $6 \times 3 = 18$ square centimeters, so together they cover $2 \times 18 = 36$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top = 6 x 3 = 18; bottom same; 36.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
