INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2962b605-6075-451a-9b54-0f920d72f47c', 'NC26.6.SGMR.3', 1, 'numeric', 'Total area of the faces in a net', 'A net of a triangular prism has 2 triangles with an area of 6 square centimeters each and 3 rectangles with areas of 10, 12 and 14 square centimeters. What is the total area of the net, in square centimeters?', '[]', '48', '2*6+10+12+14', 'The triangles together have an area of $2 \times 6 = 12$ square centimeters. The rectangles together have $10 + 12 + 14 = 36$. The net has a total area of $12 + 36 = 48$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 6 + 10 + 12 + 14 = 12 + 36 = 48.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
