INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54e1e699-10b3-42ca-9dc6-bcfc371874a1', 'NC26.6.SGMR.3', 1, 'choice', 'Total area of the faces in a net', 'A net for a cube is made of 6 squares, and each square has sides of 4 centimeters. What is the total area of the net, in square centimeters?', '["64","96","24","16"]', '96', '6*4^2', 'Each square has an area of $4 \times 4 = 16$ square centimeters, and there are 6 of them, so the total area is $6 \times 16 = 96$ square centimeters. The number 64 is the volume, 24 is $6 \times 4$ and 16 is one face.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 4 = 96.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
