INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a55273ad-dce2-4bd4-ae08-ed73d5268980', 'NC26.6.SGMR.3', 1, 'numeric', 'Total area of the faces in a net', 'A net for a box is made of six rectangles. Their areas are 20, 20, 15, 15, 12 and 12 square centimeters. What is the total area of the net, in square centimeters?', '[]', '94', '20+20+15+15+12+12', 'Add the areas of all six rectangles: $20 + 20 + 15 + 15 + 12 + 12 = 94$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"94","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20+20+15+15+12+12 = 94 (consistent with a 5x4x3 box).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
