INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bad6213-02a0-43cf-ab28-a92fe648a142', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a triangular prism', 'A triangular prism has triangle ends with sides of 3 centimeters, 4 centimeters and 5 centimeters. The prism is 6 centimeters long. What is the combined area of its three rectangular faces, in square centimeters?', '[]', '72', '(3+4+5)*6', 'The three rectangles are $3 \times 6 = 18$, $4 \times 6 = 24$ and $5 \times 6 = 30$ square centimeters. Together they are $18 + 24 + 30 = 72$ square centimeters. This is the same as the perimeter of the triangle times the length: $12 \times 6 = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles 3x6 + 4x6 + 5x6 = (3+4+5) x 6 = 72.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
