INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c89f6f9-8337-46b5-9384-6064dad45810', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a pyramid', 'A triangular pyramid has four faces that are identical triangles. Each face has an area of 15 square centimeters. What is the surface area of the pyramid, in square centimeters?', '["60","45","30","15"]', '60', '4*15', 'The surface area is the total of the areas of all 4 faces: $4 \times 15 = 60$ square centimeters. The value 45 counts only 3 faces, 30 counts 2 and 15 counts 1.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 15 = 60.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
