INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29f06a0d-b0f4-4843-aca3-c02d1641aef2', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a rectangular prism with whole-number edges', 'A storage cube has an edge of 4 feet. What is its volume, in cubic feet?', '[]', '64', '4^3', 'The volume of a cube is edge times edge times edge: $4 \times 4 \times 4 = 64$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^3 = 64.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
