VALUES ('e62aaa8e-3892-4795-977b-925f49910a37', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a rectangular prism with whole-number edges', 'A juice box is 10 centimeters long, 5 centimeters wide and 2 centimeters tall. What is its volume, in cubic centimeters?', '[]', '100', '10*5*2', 'Volume is length times width times height: $10 \times 5 \times 2 = 100$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 5 x 2 = 100.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
