INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91f7afce-bd21-4efc-b0cc-ad8e5193267a', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a rectangular prism with fractional edges', 'A thin box is $\frac{1}{2}$ foot long, $\frac{1}{2}$ foot wide and 4 feet tall. What is its volume, in cubic feet?', '[]', '1', '1/2*1/2*4', 'Volume is length times width times height: $\frac{1}{2} \times \frac{1}{2} \times 4 = \frac{1}{4} \times 4 = 1$ cubic foot.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 1/2 x 4 = 1.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
