INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96650ebd-4c71-40c1-aa88-431966421781', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism has a base with an area of $\frac{3}{4}$ square meter and a height of 8 meters. What is its volume, in cubic meters?', '[]', '6', '3/4*8', 'Volume is the area of the base times the height: $\frac{3}{4} \times 8 = 6$ cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x 8 = 6.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
