INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93df6b64-710f-46fc-a0ac-6b06db5b7602', 'NC26.6.SGMR.3', 1, 'choice', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism is $2\frac{1}{2}$ inches long, 3 inches wide and 4 inches tall. Which expression gives its volume in cubic inches?', '["$2\\frac{1}{2} + 3 + 4$","$2\\frac{1}{2} \\times 3 \\times 4$","$2 \\times 3 \\times 4$","$2\\frac{1}{2} \\times 3 + 4$"]', '$2\frac{1}{2} \times 3 \times 4$', NULL, 'Volume is length times width times height, so multiply all three edges: $2\frac{1}{2} \times 3 \times 4$. Adding the edges does not find volume, dropping the $\frac{1}{2}$ changes the length, and adding the 4 at the end leaves out the height.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{1}{2} \\times 3 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = l x w x h = 2 1/2 x 3 x 4 (= 30).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
