INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35a21166-aa2e-4283-9fa7-72d1586703bc', 'NC26.6.SGMR.3', 1, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A cube with 1-inch edges is filled with smaller cubes. Each small cube has an edge of $\frac{1}{2}$ inch. How many small cubes fill the large cube?', '[]', '8', '2*2*2', 'Along each 1-inch edge, 2 small cubes of $\frac{1}{2}$ inch fit. So the large cube holds $2 \times 2 \times 2 = 8$ small cubes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 per edge: 2 x 2 x 2 = 8.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
