INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84bf2683-39c3-4e8f-8ca2-75690bbc1b2f', 'NC26.6.SGMR.3', 1, 'choice', 'Counting unit cubes with fractional edges that fill a prism', 'A cube with edges of 1 foot is filled exactly with small cubes whose edges are each $\frac{1}{3}$ foot. How many small cubes are needed?', '["9","27","3","$\\frac{1}{27}$"]', '27', '3^3', 'Along each 1-foot edge, 3 small cubes fit. The large cube holds $3 \times 3 \times 3 = 27$ small cubes. The value 9 is one layer, 3 is one row, and $\frac{1}{27}$ is the volume of one small cube, not the number of cubes.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 per edge: 3^3 = 27.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96f0e507-5d03-4613-addf-1dd79a5fe2e8', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Mia wants to know how much wrapping paper she needs to cover a box. Which measure should she find?', '["The volume of the box","The perimeter of the top","The length of one edge","The surface area of the box"]', 'The surface area of the box', NULL, 'Wrapping paper covers the outside of the box, and the total area of all the faces is the surface area. Volume tells how much space is inside the box.', 'checked', '{"lint":[],"solve":{"answer":"The surface area of the box","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Covering = surface area.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47b13acd-9348-4ec6-af66-8dec79c0a7ba', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Which unit is best for measuring the volume of a rectangular prism?', '["Square centimeters","Centimeters","Cubic centimeters","Grams"]', 'Cubic centimeters', NULL, 'Volume counts the cubes that fill a solid, so it is measured in cubic units such as cubic centimeters. Square centimeters measure area and centimeters measure length.', 'checked', '{"lint":[],"solve":{"answer":"Cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume is in cubic units: cubic centimeters.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e214189-8a1c-4ffb-a917-2955857fadcc', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Which job needs a volume, not a surface area?', '["Finding how much paint covers the outside of a shed","Finding how much sand fills a sandbox","Finding how much paper wraps a present","Finding how much cloth covers a box"]', 'Finding how much sand fills a sandbox', NULL, 'Filling a sandbox takes the space inside, which is volume. Painting a shed, wrapping a present and covering a box all cover an outside surface, which is surface area.', 'checked', '{"lint":[],"solve":{"answer":"Finding how much sand fills a sandbox","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Filling a sandbox is volume; the others cover outsides (surface area).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a550aa7-6eed-4a9f-a672-ed07fa0bd390', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a prism with fractional edges', 'A small cube has edges that are each $\frac{1}{2}$ inch long. What is its volume in cubic inches?', '[]', '1/8', '1/2*1/2*1/2', 'Volume is length times width times height: $\frac{1}{2} \times \frac{1}{2} \times \frac{1}{2} = \frac{1}{8}$ cubic inch.', 'checked', '{"lint":[],"solve":{"answer":"1/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/2)^3 = 1/8 cubic inch.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
