INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('212dce95-f54f-49e3-b795-977501654fbd', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a cube', 'A large cube-shaped box has edges of 2.5 meters. What is its surface area, in square meters?', '["25","15.625","15","37.5"]', '37.5', '6*2.5^2', 'One face has an area of $2.5 \times 2.5 = 6.25$ square meters. There are 6 faces, so the surface area is $6 \times 6.25 = 37.5$ square meters. The number 15.625 is the volume, 25 uses only 4 faces and 15 is $6 \times 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"37.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2.5^2 = 6 x 6.25 = 37.5.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0df8d953-0e84-4904-9682-47085b688180', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a rectangular prism', 'A gift box is 12 inches long, 8 inches wide and 4 inches tall. How many square inches of wrapping paper are needed to cover the whole box with no overlap?', '[]', '352', '2*(12*8+12*4+8*4)', 'The faces are $12 \times 8 = 96$, $12 \times 4 = 48$ and $8 \times 4 = 32$ square inches, each twice. The paper needed is $2 \times (96 + 48 + 32) = 2 \times 176 = 352$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"352","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12x8 + 12x4 + 8x4) = 2(96 + 48 + 32) = 2 x 176 = 352.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ccd7bf3-682b-4b35-b625-d09139a18ce5', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'Ben finds the surface area of a box that is 7 centimeters long, 4 centimeters wide and 3 centimeters tall. He gets 84 square centimeters. What mistake did Ben make?', '["He found the area of only the top and bottom","He found the volume instead of the surface area","He found the area of only the four side faces","He added the length, width and height"]', 'He found the volume instead of the surface area', NULL, 'Ben multiplied $7 \times 4 \times 3 = 84$, which is the volume. The surface area is $2 \times (28 + 21 + 12) = 122$ square centimeters. The top and bottom alone give 56, the four sides alone give 66, and adding the three edges gives 14, so none of those match his 84.', 'checked', '{"lint":[],"solve":{"answer":"He found the volume instead of the surface area","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 4 x 3 = 84 = volume. True SA = 2(28+21+12) = 122; top+bottom 56; four sides 66; sum of dimensions 14. So he found the volume.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0418a2ab-43c3-441d-bbea-7596e5bf3049', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A classroom is 8 meters long, 6 meters wide and 3 meters tall. The four walls will be painted. What is the total area of the walls, in square meters? (Ignore doors and windows.)', '["132","180","84","42"]', '84', NULL, 'Two walls are $8 \times 3 = 24$ square meters each and two walls are $6 \times 3 = 18$ square meters each. The total is $2 \times 24 + 2 \times 18 = 48 + 36 = 84$ square meters. The number 132 also counts the ceiling, 180 counts all six faces, and 42 counts only one wall of each size.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walls: 2(8x3) + 2(6x3) = 48 + 36 = 84.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b9881a2-56b7-4fea-b8de-2d48e68d52bb', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A rectangular prism is 8 centimeters long, 3 centimeters wide and 2 centimeters tall. What is its surface area, in square centimeters?', '["92","46","48","44"]', '92', '2*(8*3+8*2+3*2)', 'The faces are $8 \times 3 = 24$, $8 \times 2 = 16$ and $3 \times 2 = 6$ square centimeters, each twice. The surface area is $2 \times (24 + 16 + 6) = 2 \times 46 = 92$ square centimeters. The value 46 counts each pair once, 48 is the volume, and 44 leaves out the top and bottom.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(8x3 + 8x2 + 3x2) = 2(24 + 16 + 6) = 92.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
