INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('490957a6-3eea-43ba-af4f-1a41eb3b133b', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a triangular prism', 'A tent is shaped like a triangular prism. Each triangular end has a base of 6 feet, a height of 4 feet and two slanted sides of 5 feet each. The tent is 9 feet long. How many square feet of fabric cover all five faces, including the floor?', '[]', '168', '2*(6*4/2)+2*(5*9)+6*9', 'Each triangular end has an area of $\frac{1}{2} \times 6 \times 4 = 12$ square feet, so the two ends total 24. Each slanted side is $5 \times 9 = 45$ square feet, so the two total 90. The floor is $6 \times 9 = 54$ square feet. The fabric needed is $24 + 90 + 54 = 168$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 4) = 24; floor 6x9 = 54; slanted sides 2 x 5x9 = 90; total 168. (3-4-5 checks.)","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
