INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da9af884-d865-4c45-b059-4a00bebe1b0c', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a pyramid', 'The roof of a gazebo is shaped like a square pyramid with no base. Each of its 4 triangular faces has a base of 10 feet and a height of 7 feet. What is the area of the roof, in square feet?', '[]', '140', '4*(10*7/2)', 'Each triangular face has an area of $\frac{1}{2} \times 10 \times 7 = 35$ square feet. The roof has 4 of them, so its area is $4 \times 35 = 140$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2 x 10 x 7) = 4 x 35 = 140.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
