INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d93e611d-f7fd-4272-910d-d5a09e4247bf', 'NC26.6.SGMR.3', 2, 'choice', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism is $\frac{1}{2}$ meter long, $\frac{3}{4}$ meter wide and 6 meters tall. What is its volume, in cubic meters?', '["$2\\frac{1}{4}$","$\\frac{3}{8}$","$7\\frac{1}{4}$","3"]', '$2\frac{1}{4}$', NULL, 'Multiply the three edges: $\frac{1}{2} \times \frac{3}{4} \times 6 = \frac{3}{8} \times 6 = \frac{18}{8} = 2\frac{1}{4}$ cubic meters. The value $\frac{3}{8}$ leaves out the height, 3 leaves out the width, and $7\frac{1}{4}$ adds the three edges.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 3/4 x 6 = 3/8 x 6 = 18/8 = 9/4 = 2 1/4.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
