INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c646113d-e3cd-454e-a736-e699423fbf5f', 'NC26.6.RD.1', 1, 'choice', 'Probability values from 0 to 1', 'Which of these numbers could be the probability of an event?', '["0.35","1.2","$-0.5$","$\\frac{5}{4}$"]', '0.35', NULL, 'A probability is never less than 0 and never greater than 1. The number 0.35 is between 0 and 1. The number 1.2 and $\frac{5}{4}$ are greater than 1, and $-0.5$ is less than 0.', 'checked', '{"lint":[],"solve":{"answer":"0.35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Probabilities lie in [0, 1]. 0.35 works; 5/4 and 1.2 exceed 1; -0.5 is negative.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
