INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b87f12a4-8118-425e-8be5-3c63083dc4c1', 'NC26.6.RD.1', 1, 'numeric', 'Probability values from 0 to 1', 'A bag has only yellow marbles. One marble is picked at random. What is the probability that it is yellow?', '[]', '1', NULL, 'Every marble is yellow, so the event is certain. The probability of a certain event is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All marbles yellow: certain, P = 1.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
