INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b939ac82-b113-42cb-9c1d-36851755efaf', 'NC26.6.RD.1', 1, 'numeric', 'Probability values from 0 to 1', 'A fair six-sided die has faces numbered 1 to 6. It is rolled once. What is the probability of rolling a 9?', '[]', '0', NULL, 'No face shows a 9, so the event is impossible. The probability of an impossible event is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No face shows 9: impossible, P = 0.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
