INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14360868-e33f-495b-83ab-9363dba02ef2', 'NC26.6.RD.1', 1, 'choice', 'Probability values from 0 to 1', 'Which number is the probability of an event that is equally likely to happen or not to happen?', '["$1$","$0$","$\\frac{1}{2}$","$\\frac{1}{4}$"]', '$\frac{1}{2}$', NULL, 'Equally likely to happen or not means half the time it happens, so the probability is $\frac{1}{2}$. A probability of 1 is certain, 0 is impossible, and $\frac{1}{4}$ is less likely than not.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equally likely to happen or not: 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dba6ee4-89ef-4d00-8afd-0b5f44405cf3', 'NC26.6.RD.1', 1, 'numeric', 'Theoretical probability from equally likely outcomes', 'A box holds 4 yellow crayons and 6 green crayons. Without looking, Ravi takes one crayon. What is the probability that it is yellow? Give your answer as a fraction.', '[]', '2/5', '4/10', 'There are $4 + 6 = 10$ crayons, and 4 of them are yellow. The probability is $\frac{4}{10} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 yellow of 10: 4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c804ffd2-9213-47f5-80c8-8060d2af87a0', 'NC26.6.RD.1', 1, 'numeric', 'Theoretical probability from equally likely outcomes', 'A fruit bowl has 3 apples, 2 bananas and 5 oranges. One piece of fruit is chosen at random. What is the probability that it is a banana? Give your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 2 + 5 = 10$ pieces of fruit, and 2 are bananas. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 bananas of 10 fruits: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
