INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ec48d6b-8b25-4fdc-9f09-de938b3a2dd0', 'NC26.6.RD.1', 1, 'choice', 'Theoretical probability from equally likely outcomes', 'A jar has 20 jelly beans: 8 cherry, 7 lemon and 5 grape. One jelly bean is picked at random. What is the probability that it is lemon?', '["$\\frac{7}{13}$","$\\frac{1}{3}$","$\\frac{7}{20}$","$\\frac{13}{20}$"]', '$\frac{7}{20}$', NULL, '7 of the 20 jelly beans are lemon, so the probability is $\frac{7}{20}$. The value $\frac{7}{13}$ compares lemon with the other beans, $\frac{1}{3}$ treats the three flavors as equally likely, and $\frac{13}{20}$ is the probability of not lemon.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 lemon of 20: 7/20.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('604dc64f-db9d-4fe7-8a5e-eb3593e776ad', 'NC26.6.RD.1', 1, 'choice', 'Theoretical probability from equally likely outcomes', 'A bag has 2 red, 3 blue and 5 green marbles. One marble is picked at random. What is the probability that it is green?', '["$\\frac{1}{3}$","$\\frac{3}{10}$","$\\frac{1}{5}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, 'The bag holds $2 + 3 + 5 = 10$ marbles, and 5 are green. The probability is $\frac{5}{10} = \frac{1}{2}$. The value $\frac{1}{3}$ treats the three colors as equally likely, $\frac{3}{10}$ is blue and $\frac{1}{5}$ is red.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 green of 10: 5/10 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16b5bf40-792e-44a1-8f97-b4d5ebd8a2e1', 'NC26.6.RD.1', 1, 'numeric', 'Probability with dice, coins and numbered cards', 'A fair six-sided die has faces numbered 1 to 6. It is rolled once. What is the probability of rolling an even number? Give your answer as a fraction.', '[]', '1/2', '3/6', 'The even numbers on the die are 2, 4 and 6, which is 3 outcomes out of 6. The probability is $\frac{3}{6} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even: 2, 4, 6 = 3 of 6: 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
