INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('995b0501-93cb-416b-83f4-50cb4404dcb4', 'NC26.6.RD.1', 1, 'numeric', 'Probability that an event does not happen', 'The probability that it rains tomorrow is $\frac{3}{10}$. What is the probability that it does not rain? Give your answer as a fraction.', '[]', '7/10', '1-3/10', 'Either it rains or it does not rain, and the two probabilities add to 1. So the probability of no rain is $1 - \frac{3}{10} = \frac{7}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 3/10 = 7/10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7584eb71-ee01-46ee-86d7-1a192a36cd02', 'NC26.6.RD.1', 1, 'choice', 'Probability that an event does not happen', 'The probability that Lena wins a game is 0.6. What is the probability that she does not win?', '["0.6","1.6","0.4","0.5"]', '0.4', '1-0.6', 'The probabilities of winning and of not winning add to 1. So the probability of not winning is $1 - 0.6 = 0.4$. The value 1.6 adds instead of subtracting, and a probability can never be greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 0.6 = 0.4.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bd1d44-6a5b-4145-9f68-f71838f9b5c7', 'NC26.6.RD.1', 1, 'choice', 'Probability with a spinner of equal sections', 'A spinner has 8 equal sections numbered 1 to 8. What is the probability that it lands on 5?', '["$\\frac{5}{8}$","$\\frac{1}{5}$","$\\frac{7}{8}$","$\\frac{1}{8}$"]', '$\frac{1}{8}$', NULL, 'Only 1 of the 8 equal sections is numbered 5, so the probability is $\frac{1}{8}$. The value $\frac{7}{8}$ is the probability of not landing on 5.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One section of 8: 1/8.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
