INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfa90a13-08a7-475b-ae04-6edc3cbd69cc', 'NC26.6.RD.1', 1, 'numeric', 'Probability with a spinner of equal sections', 'A spinner is divided into 6 equal sections. Two sections are painted red, one is painted blue and three are painted yellow. What is the probability that the spinner lands on yellow? Give your answer as a fraction.', '[]', '1/2', '3/6', '3 of the 6 equal sections are yellow, so the probability is $\frac{3}{6} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 yellow of 6: 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
