INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0624c045-8999-4377-b6ca-61daf0d96a13', 'NC26.6.RD.1', 1, 'choice', 'Writing a probability as a fraction, decimal or percent', 'A probability of 25% is the same as which fraction?', '["$\\frac{1}{25}$","$\\frac{2}{5}$","$\\frac{1}{2}$","$\\frac{1}{4}$"]', '$\frac{1}{4}$', NULL, '25% means 25 out of 100, which is $\frac{25}{100} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% = 25/100 = 1/4.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
