INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcb1cc71-414c-44be-bfe7-e368d3b60de9', 'NC26.6.RD.1', 1, 'numeric', 'Writing a probability as a fraction, decimal or percent', 'A bag has 2 red marbles and 8 blue marbles. One marble is picked at random. What is the probability of picking red, as a percent? Give just the number, without the percent sign.', '[]', '20', '2/10*100', 'There are 10 marbles and 2 are red, so the probability is $\frac{2}{10} = 0.2$. As a percent, that is 20 percent.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/10 = 0.2 = 20%.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
