INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7399613-2325-49de-841d-13bf13303ae4', 'NC26.6.RD.1', 1, 'choice', 'Experimental probability from results', 'Ken rolled a die 30 times. The number 4 came up on 6 of the rolls. What is the experimental probability of rolling a 4?', '["$\\frac{1}{5}$","$\\frac{1}{6}$","$\\frac{2}{15}$","$\\frac{1}{4}$"]', '$\frac{1}{5}$', NULL, 'Experimental probability is the number of times the event happened divided by the number of trials: $\frac{6}{30} = \frac{1}{5}$. The value $\frac{1}{6}$ is the theoretical probability, $\frac{2}{15}$ uses 4 instead of 6, and $\frac{1}{4}$ compares 6 with the 24 rolls that were not a 4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/30 = 1/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b15651d6-6938-48bb-a33a-f47456d89d00', 'NC26.6.RD.1', 1, 'numeric', 'Predicting how many times an event will happen', 'A fair coin is tossed 100 times. About how many times would you expect it to land heads up?', '[]', '50', '1/2*100', 'The probability of heads is $\frac{1}{2}$, so you expect about $\frac{1}{2} \times 100 = 50$ heads.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 100 = 50.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae4328c-6990-489e-94a7-0b98dd1be60f', 'NC26.6.RD.1', 1, 'choice', 'Predicting how many times an event will happen', 'A fair six-sided die is rolled 60 times. About how many times would you expect a 3 to come up?', '["6","20","30","10"]', '10', '60/6', 'The probability of rolling a 3 is $\frac{1}{6}$, so you expect about $\frac{1}{6} \times 60 = 10$ threes. The value 6 is the number of faces, not the number of threes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6 x 60 = 10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
