INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d9df91e-f931-4315-be4c-fc3557f29477', 'NC26.6.RD.1', 2, 'numeric', 'Probability that an event does not happen', 'A bag has 5 red, 3 green and 2 yellow marbles. One marble is picked without looking. What is the probability that it is NOT green? Give your answer as a fraction.', '[]', '7/10', '7/10', 'There are $5 + 3 + 2 = 10$ marbles. The marbles that are not green number $5 + 2 = 7$, so the probability is $\frac{7}{10}$. (Another way: $1 - \frac{3}{10} = \frac{7}{10}$.)', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 10; not green = 5 + 2 = 7. P = 7/10.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bfe6c6d-afda-4d37-b109-136ed34cf251', 'NC26.6.RD.1', 2, 'choice', 'Describing a probability close to 0 in words', 'The probability of rain tomorrow is $0.05$. Which statement best describes this?', '["Rain is certain not to happen","Rain is very unlikely but not impossible","Rain is as likely as not","Rain is very likely"]', 'Rain is very unlikely but not impossible', NULL, 'A probability of 0.05 is very close to 0, so the event is very unlikely. It is not exactly 0, so it is not impossible.', 'checked', '{"lint":[],"solve":{"answer":"Rain is very unlikely but not impossible","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05 is close to 0 but greater than 0: very unlikely, not impossible.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dae7068b-91fc-4e9f-9272-9baa6825b74e', 'NC26.6.RD.1', 2, 'numeric', 'Experimental probability from a trial', 'Ana tosses a fair coin 50 times and gets heads 28 times. What is the experimental probability of getting heads, as a decimal?', '[]', '0.56', '28/50', 'Experimental probability is the number of times the event happened divided by the number of trials: $\frac{28}{50} = 0.56$.', 'checked', '{"lint":[],"solve":{"answer":"0.56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 50 = 0.56.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf629d92-5cd0-42f2-b558-41198489c07d', 'NC26.6.RD.1', 2, 'choice', 'Describing likelihood with probability words', 'A bag has 9 red marbles and 1 blue marble. One marble is picked without looking. Which statement best describes picking a red marble?', '["It is certain","It is unlikely","It is likely, but not certain","It is impossible"]', 'It is likely, but not certain', NULL, '9 of the 10 marbles are red, so a red marble is very likely. It is not certain, because the blue marble could be picked.', 'checked', '{"lint":[],"solve":{"answer":"It is likely, but not certain","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(red) = 9/10: likely, not certain (a blue is possible).","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd72f22b-442e-400d-9bd9-2b499b781012', 'NC26.6.RD.1', 2, 'choice', 'Describing likelihood with probability words', 'Which statement best describes an event with a probability of 0.5?', '["It is certain to happen","It is impossible","It is very unlikely to happen","It is equally likely to happen or not to happen"]', 'It is equally likely to happen or not to happen', NULL, 'A probability of 0.5 is one half. The event has the same chance of happening as of not happening, so the two are equally likely.', 'checked', '{"lint":[],"solve":{"answer":"It is equally likely to happen or not to happen","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5 = 1/2: equally likely to happen or not.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff31ab74-38fc-4aec-8e1b-347deae5da78', 'NC26.6.RD.1', 2, 'choice', 'Probability values from 0 to 1', 'Four events have probabilities of 0.8, $\frac{1}{4}$, 0.5 and $\frac{1}{10}$. Which list puts them in order from least to greatest?', '["$\\frac{1}{10}$, $\\frac{1}{4}$, $0.5$, $0.8$","$\\frac{1}{4}$, $\\frac{1}{10}$, $0.5$, $0.8$","$0.8$, $0.5$, $\\frac{1}{4}$, $\\frac{1}{10}$","$\\frac{1}{10}$, $0.5$, $\\frac{1}{4}$, $0.8$"]', '$\frac{1}{10}$, $\frac{1}{4}$, $0.5$, $0.8$', NULL, 'Write each as a decimal: $\frac{1}{10} = 0.1$ and $\frac{1}{4} = 0.25$. From least to greatest the order is 0.1, 0.25, 0.5, 0.8, which is $\frac{1}{10}$, $\frac{1}{4}$, 0.5, 0.8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{10}$, $\\frac{1}{4}$, $0.5$, $0.8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/10 = 0.1, 1/4 = 0.25, 0.5, 0.8. Order: 1/10, 1/4, 0.5, 0.8.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('975523e6-2c74-42aa-88e9-eae62fb81e79', 'NC26.6.RD.1', 2, 'choice', 'Probability values from 0 to 1', 'Sam says the probability of picking a red marble from a bag is $\frac{5}{4}$. Which statement explains why Sam must be wrong?', '["A probability must be written as a decimal","A probability must be less than $\\frac{1}{2}$","A probability can never be a fraction","A probability can never be greater than 1"]', 'A probability can never be greater than 1', NULL, 'The fraction $\frac{5}{4}$ is greater than 1. A probability is always between 0 and 1, including 0 and 1. Probabilities can be written as fractions, decimals or percents, and they can be greater than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"A probability can never be greater than 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/4 > 1, and no probability exceeds 1.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1edf96e3-7c99-4e9d-ba62-6f7f5729e92c', 'NC26.6.RD.1', 2, 'numeric', 'Theoretical probability from equally likely outcomes', 'A bag has 5 red marbles, 3 blue marbles and 7 yellow marbles. One marble is picked at random. What is the probability that it is red or blue? Give your answer as a fraction.', '[]', '8/15', '(5+3)/15', 'The bag holds $5 + 3 + 7 = 15$ marbles. The red and blue marbles together number $5 + 3 = 8$. The probability is $\frac{8}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"8/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 = 8 red or blue of 15: 8/15.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f1d1bb1-f226-44c7-a6e7-f7d26c909c20', 'NC26.6.RD.1', 2, 'numeric', 'Theoretical probability from equally likely outcomes', 'The letters of the word MATHEMATICS are written on 11 tiles, one letter on each tile, and put in a bag. One tile is picked at random. What is the probability that the letter is a vowel? (The vowels are A, E, I, O and U.) Give your answer as a fraction.', '[]', '4/11', '4/11', 'The tiles show M, A, T, H, E, M, A, T, I, C, S. The vowels are A, E, A and I, which is 4 tiles out of 11. The probability is $\frac{4}{11}$.', 'checked', '{"lint":[],"solve":{"answer":"4/11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M-A-T-H-E-M-A-T-I-C-S: vowels A, E, A, I = 4 of 11 tiles: 4/11.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ca19858-5773-4577-b1c1-9e472a9c8b52', 'NC26.6.RD.1', 2, 'choice', 'Theoretical probability from equally likely outcomes', 'Which bag gives a probability of $\frac{1}{3}$ of picking a red marble at random?', '["1 red marble and 3 blue marbles","2 red marbles and 4 blue marbles","3 red marbles and 5 blue marbles","2 red marbles and 3 blue marbles"]', '2 red marbles and 4 blue marbles', NULL, 'With 2 red and 4 blue there are 6 marbles, and $\frac{2}{6} = \frac{1}{3}$. The other bags give $\frac{1}{4}$, $\frac{3}{8}$ and $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2 red marbles and 4 blue marbles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4, 3/8, 2/5, 2/6 = 1/3. Only 2 red and 4 blue.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de3a2a02-8abc-495d-bd5f-ff3eb7f35c49', 'NC26.6.RD.1', 2, 'numeric', 'Probability with dice, coins and numbered cards', 'A fair 12-sided die has faces numbered 1 to 12. It is rolled once. What is the probability of rolling a prime number? Give your answer as a fraction.', '[]', '5/12', '5/12', 'The prime numbers from 1 to 12 are 2, 3, 5, 7 and 11. That is 5 outcomes out of 12, so the probability is $\frac{5}{12}$. The number 1 is not prime.', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes 1-12: 2, 3, 5, 7, 11 = 5. P = 5/12.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e1b6bb-6509-443a-8571-38e9ccd840da', 'NC26.6.RD.1', 2, 'choice', 'Probability with dice, coins and numbered cards', 'Cards numbered 1 to 20 are placed face down. One card is picked at random. What is the probability that its number is a multiple of 5?', '["$\\frac{1}{4}$","$\\frac{1}{5}$","$\\frac{1}{20}$","$\\frac{4}{5}$"]', '$\frac{1}{5}$', NULL, 'The multiples of 5 from 1 to 20 are 5, 10, 15 and 20, which is 4 cards out of 20. The probability is $\frac{4}{20} = \frac{1}{5}$. The value $\frac{4}{5}$ is the probability of a card that is not a multiple of 5.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 5: 5, 10, 15, 20 = 4 of 20 = 1/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1069c743-731f-497e-a890-069c8ae678e0', 'NC26.6.RD.1', 2, 'numeric', 'Probability with dice, coins and numbered cards', 'A fair six-sided die has faces numbered 1 to 6. It is rolled once. What is the probability that the number rolled is a factor of 6? Give your answer as a fraction.', '[]', '2/3', '4/6', 'The factors of 6 are 1, 2, 3 and 6, and all four are on the die. That is 4 outcomes out of 6, so the probability is $\frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 6: 1, 2, 3, 6 = 4 of 6 = 2/3.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ab1ae46-69de-4e60-b8f6-58c297c21afd', 'NC26.6.RD.1', 2, 'numeric', 'Probability that an event does not happen', 'The probability that a school bus is late on a given day is 15%. What is the probability, as a percent, that the bus is NOT late? Give just the number, without the percent sign.', '[]', '85', '100-15', 'The bus is either late or not late, and the two percents add to 100%. The probability that it is not late is $100 - 15 = 85$ percent.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100% - 15% = 85%.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0005303f-3983-4ed4-a3d9-c86f56be5b02', 'NC26.6.RD.1', 2, 'choice', 'Probability that an event does not happen', 'Which pair of numbers could be the probability that an event happens and the probability that the same event does not happen?', '["0.35 and 0.75","$\\frac{1}{3}$ and $\\frac{1}{3}$","0.35 and 0.65","$\\frac{2}{5}$ and $\\frac{2}{3}$"]', '0.35 and 0.65', NULL, 'The two probabilities must add to 1. We have $0.35 + 0.65 = 1$. The other pairs add to 1.1, to $\frac{2}{3}$, and to $\frac{16}{15}$, which are not 1.', 'checked', '{"lint":[],"solve":{"answer":"0.35 and 0.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complements sum to 1: 0.35 + 0.65 = 1. Others: 2/3, 1.1, 16/15.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('476808d2-06af-40ee-bd05-5e94a402dfe1', 'NC26.6.RD.1', 2, 'numeric', 'Probability with a spinner of equal sections', 'A spinner has 16 equal sections numbered 1 to 16. What is the probability that it lands on a number greater than 12 or less than 3? Give your answer as a fraction.', '[]', '3/8', '(4+2)/16', 'The numbers greater than 12 are 13, 14, 15 and 16, which is 4 sections. The numbers less than 3 are 1 and 2, which is 2 sections. That is $4 + 2 = 6$ sections out of 16, so the probability is $\frac{6}{16} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greater than 12: 13-16 (4); less than 3: 1, 2 (2). 6/16 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14483bbe-8377-4718-a4d4-4678c27598cf', 'NC26.6.RD.1', 2, 'choice', 'Probability with a spinner of equal sections', 'A fair spinner has 6 equal sections numbered 1 to 6. Which statement is true?', '["Landing on 2 is as likely as landing on 5","Landing on 6 is more likely than landing on 1","Landing on an even number is less likely than landing on an odd number","Landing on a number less than 3 is more likely than landing on a number greater than 3"]', 'Landing on 2 is as likely as landing on 5', NULL, 'All the sections are equal, so each number has the same chance and landing on 2 is as likely as landing on 5. There are 3 even and 3 odd numbers, so even and odd are equally likely. Two numbers are less than 3 and three numbers are greater than 3, so less than 3 is less likely.', 'checked', '{"lint":[],"solve":{"answer":"Landing on 2 is as likely as landing on 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each number 1/6, so 2 and 5 equally likely. 6 vs 1 equal; even = odd = 1/2; <3 is 2/6 < >3 is 3/6.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('423be32f-2bd7-4bac-8da6-2d1697485195', 'NC26.6.RD.1', 2, 'numeric', 'Writing a probability as a fraction, decimal or percent', 'The probability that a spinner lands on blue is $\frac{7}{20}$. Write this probability as a decimal.', '[]', '0.35', '7/20', '$\frac{7}{20} = \frac{35}{100} = 0.35$.', 'checked', '{"lint":[],"solve":{"answer":"0.35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/20 = 35/100 = 0.35.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca41eaa0-7f6d-4c61-8367-763960811380', 'NC26.6.RD.1', 2, 'choice', 'Writing a probability as a fraction, decimal or percent', 'Which of these is NOT equal to the probability 0.4?', '["40%","$\\frac{1}{4}$","$\\frac{2}{5}$","$\\frac{4}{10}$"]', '$\frac{1}{4}$', NULL, 'The value 0.4 is 40 percent and is also $\frac{4}{10} = \frac{2}{5}$. The fraction $\frac{1}{4}$ equals 0.25, so it is not equal to 0.4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4 = 40% = 2/5 = 4/10; 1/4 = 0.25 is not.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5c517a2-25ab-4333-a9f2-da54c7e04bfc', 'NC26.6.RD.1', 2, 'numeric', 'Experimental probability from results', 'A basketball player made 18 of her last 24 free throws. Based on this, what is the experimental probability that she makes her next free throw? Give your answer as a decimal.', '[]', '0.75', '18/24', 'The experimental probability is $\frac{18}{24} = \frac{3}{4} = 0.75$.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 3/4 = 0.75.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
