INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a810092a-a5d3-4faa-aa05-4fe522a1e0d6', 'NC26.6.RD.1', 2, 'choice', 'Experimental probability from results', 'Ming draws a marble from a bag, records its color and puts it back. After 50 draws, 30 were red and the rest were blue. What is the experimental probability of drawing a blue marble?', '["$\\frac{3}{5}$","$\\frac{2}{3}$","$\\frac{2}{5}$","$\\frac{1}{2}$"]', '$\frac{2}{5}$', NULL, 'Blue was drawn $50 - 30 = 20$ times out of 50, so the experimental probability is $\frac{20}{50} = \frac{2}{5}$. The value $\frac{3}{5}$ is for red, and $\frac{2}{3}$ compares blue with red.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = 50 - 30 = 20. 20/50 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b22deaf6-4ec0-4b2d-b22b-6daf05c16042', 'NC26.6.RD.1', 2, 'numeric', 'Experimental probability from results', 'A die was rolled 100 times. The results were: 1 came up 14 times, 2 came up 18 times, 3 came up 15 times, 4 came up 20 times, 5 came up 16 times and 6 came up 17 times. What is the experimental probability of rolling an even number? Give your answer as a decimal.', '[]', '0.55', '(18+20+17)/100', 'The even numbers are 2, 4 and 6, which came up $18 + 20 + 17 = 55$ times out of 100 rolls. The experimental probability is $\frac{55}{100} = 0.55$.', 'checked', '{"lint":[],"solve":{"answer":"0.55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even: 2 (18) + 4 (20) + 6 (17) = 55 of 100 = 0.55. (Counts total 100: 14+18+15+20+16+17.)","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37dedb8e-1292-4ba8-bf65-7e261ade8ef4', 'NC26.6.RD.1', 2, 'numeric', 'Predicting how many times an event will happen', 'A factory finds that the probability a light bulb is defective is 0.04. In a box of 250 bulbs, about how many bulbs would you expect to be defective?', '[]', '10', '0.04*250', 'Multiply the probability by the number of bulbs: $0.04 \times 250 = 10$ bulbs.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.04 x 250 = 10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6127636-b642-4ce3-99b8-97f5c1116454', 'NC26.6.RD.1', 2, 'choice', 'Predicting how many times an event will happen', 'A spinner has 5 equal sections. Two of the sections are red. The spinner is spun 150 times. About how many times would you expect it to land on red?', '["30","75","60","100"]', '60', '2/5*150', 'The probability of red is $\frac{2}{5}$, so you expect about $\frac{2}{5} \times 150 = 60$ reds. The value 30 uses $\frac{1}{5}$, 75 uses $\frac{1}{2}$ and 100 uses $\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 x 150 = 60.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('552a1568-34de-4c1b-b7f0-abc673dfd926', 'NC26.6.RD.1', 2, 'numeric', 'Comparing experimental and theoretical probability', 'A fair coin is tossed 50 times and lands heads up 29 times. What is the experimental probability of heads minus the theoretical probability of heads? Give your answer as a decimal.', '[]', '0.08', '29/50-1/2', 'The experimental probability is $\frac{29}{50} = 0.58$. The theoretical probability is $\frac{1}{2} = 0.5$. The difference is $0.58 - 0.5 = 0.08$.', 'checked', '{"lint":[],"solve":{"answer":"0.08","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29/50 = 0.58; 0.58 - 0.5 = 0.08.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3d9b73d-869d-4880-b594-c48bcbd0c26e', 'NC26.6.RD.1', 2, 'choice', 'Comparing experimental and theoretical probability', 'A spinner has 4 equal sections: red, blue, green and yellow. It was spun 40 times. It landed on red 8 times, blue 14 times, green 10 times and yellow 8 times. For which color is the experimental probability greater than the theoretical probability?', '["Blue","Red","Green","Yellow"]', 'Blue', NULL, 'The theoretical probability of each color is $\frac{1}{4}$, which is 10 spins out of 40. Blue came up 14 times, which is more than 10. Green came up exactly 10 times, so it is equal, and red and yellow came up 8 times, which is fewer.', 'checked', '{"lint":[],"solve":{"answer":"Blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Theoretical 1/4 = 10 of 40. Red 8, blue 14, green 10, yellow 8. Only blue is above.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fae2dc9d-2ba1-4ee3-ab68-51f4f6fb47ad', 'NC26.6.RD.1', 2, 'choice', 'What a probability does and does not tell us', 'A fair coin has landed on heads 4 times in a row. What is true about the next toss?', '["The chance of heads is still $\\frac{1}{2}$, because every toss has the same chances","Tails is more likely, because it is due","Heads is more likely, because it is on a streak","Heads is impossible, because the streak has to end"]', 'The chance of heads is still $\frac{1}{2}$, because every toss has the same chances', NULL, 'A fair coin does not remember earlier tosses. Each toss has the same chance of heads, $\frac{1}{2}$, no matter what came before.', 'checked', '{"lint":[],"solve":{"answer":"The chance of heads is still $\\frac{1}{2}$, because every toss has the same chances","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tosses are independent; P(H) stays 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebf9cfc1-c696-4a23-9f98-cdc3069bce23', 'NC26.6.RD.1', 2, 'choice', 'What a probability does and does not tell us', 'The weather report says the probability of rain on Tuesday is 0.7. Which statement is the best way to say what this means?', '["It will rain for 70% of the day","It will definitely rain on Tuesday","Rain is likely on Tuesday, but it might not happen","Rain is unlikely on Tuesday"]', 'Rain is likely on Tuesday, but it might not happen', NULL, 'A probability of 0.7 is greater than $\frac{1}{2}$ but less than 1, so rain is likely but not certain. The probability does not say how long it will rain.', 'checked', '{"lint":[],"solve":{"answer":"Rain is likely on Tuesday, but it might not happen","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.7 is likely but not certain.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc3f4d75-66d8-409f-8c92-b32856c4edb7', 'NC26.6.RD.1', 2, 'numeric', 'Finding a number of outcomes from a probability', 'The probability of picking a red marble from a bag at random is $\frac{2}{5}$. The bag holds 30 marbles. How many marbles are red?', '[]', '12', '2/5*30', 'Red marbles are $\frac{2}{5}$ of the 30 marbles: $\frac{2}{5} \times 30 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 x 30 = 12.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54553a8e-2619-4199-84c5-b46e642252b8', 'NC26.6.RD.1', 2, 'choice', 'Finding a number of outcomes from a probability', 'A box holds 24 raffle tickets. The probability of picking a winning ticket at random is $\frac{1}{6}$. How many of the tickets are NOT winning tickets?', '["20","4","6","18"]', '20', '24-24/6', 'Winning tickets are $\frac{1}{6}$ of 24, which is 4 tickets. The tickets that are not winners number $24 - 4 = 20$. The value 4 is the number of winners.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Winning: 1/6 x 24 = 4; not winning: 20.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80c4ed99-6552-49d8-9c80-17ed60b3e232', 'NC26.6.RD.1', 2, 'choice', 'How adding or removing items changes a probability', 'A bag has 3 red marbles and 5 blue marbles. One more red marble is added. What happens to the probability of picking a red marble at random?', '["It decreases","It stays the same","It becomes $\\frac{1}{2}$","It increases"]', 'It increases', NULL, 'Before, the probability of red is $\frac{3}{8} = 0.375$. After adding a red marble it is $\frac{4}{9}$, about 0.44. The probability goes up, but it is still less than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"It increases","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375 becomes 4/9 ~ 0.444: increases (not 1/2).","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1306ec42-066a-4ab9-a33d-1cef0f4926c0', 'NC26.6.RD.1', 2, 'choice', 'Comparing the probabilities of two events', 'Four spinners each have equal sections. Which spinner has the greatest probability of landing on blue?', '["1 blue section out of 4","3 blue sections out of 10","3 blue sections out of 8","2 blue sections out of 5"]', '2 blue sections out of 5', NULL, 'Write each as a decimal: $\frac{1}{4} = 0.25$, $\frac{3}{10} = 0.3$, $\frac{2}{5} = 0.4$ and $\frac{3}{8} = 0.375$. The greatest is 0.4, which is 2 blue sections out of 5.', 'checked', '{"lint":[],"solve":{"answer":"2 blue sections out of 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3, 0.4, 0.25, 0.375. Greatest: 2 out of 5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acfe20a4-78dc-46c0-8b5d-a53d8e4a7235', 'NC26.6.RD.1', 2, 'choice', 'Comparing the probabilities of two events', 'Event A has a probability of $\frac{3}{8}$ and event B has a probability of 0.4. Which statement is true?', '["Event A is more likely than event B","Event B is more likely than event A","The events are equally likely","It is impossible to compare the two events"]', 'Event B is more likely than event A', NULL, 'Write $\frac{3}{8}$ as a decimal: $3 \div 8 = 0.375$. Since 0.4 is greater than 0.375, event B is more likely.', 'checked', '{"lint":[],"solve":{"answer":"Event B is more likely than event A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375 < 0.4: B more likely.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d06742f1-0385-452f-9190-4dd6c1229243', 'NC26.6.RD.1', 3, 'numeric', 'Comparing an experiment with theory', 'A spinner has 4 equal sections numbered 1, 2, 3 and 4. Leo spins it 80 times and it lands on 3 a total of 26 times. How many more times than the theoretical probability predicts did it land on 3?', '[]', '6', '26-80/4', 'The theoretical probability of landing on 3 is $\frac{1}{4}$, so in 80 spins you would expect $\frac{1}{4} \times 80 = 20$ times. It landed on 3 a total of 26 times, which is $26 - 20 = 6$ more times than expected.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Wording is slightly awkward (''than the theoretical probability predicts''); clearer: ''How many more times did it land on 3 than the theoretical probability predicts?'' Answer is still unambiguous.","work":"P(3) = 1/4; predicted 80 x 1/4 = 20. Actual 26; 26 - 20 = 6 more.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36d2ce14-37a9-4a8f-b3a0-ff5c55935b24', 'NC26.6.RD.1', 3, 'numeric', 'Finding how many items to add to reach a target probability', 'A bag has 4 red marbles and 6 blue marbles. How many blue marbles must be added so that the probability of picking a red marble is $\frac{1}{4}$?', '[]', '6', '4/(1/4)-10', 'The number of red marbles stays at 4. For the probability to be $\frac{1}{4}$, the bag needs $4 \div \frac{1}{4} = 16$ marbles in all. It now has 10, so add $16 - 10 = 6$ blue marbles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red stays 4. Need 4 / total = 1/4, so total = 16. Currently 10, so add 6 blue. Check 4/16 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcc79f24-b1b2-41e2-9846-84507e887ef5', 'NC26.6.RD.1', 3, 'choice', 'Comparing the probabilities of several events', 'Which event has the greatest probability? In each event, every outcome is equally likely.', '["Rolling a number greater than 2 on a fair six-sided die","Tossing a fair coin and getting tails","Picking a prime number from cards numbered 1 to 10","Picking a red marble from a bag with 3 red and 7 blue marbles"]', 'Rolling a number greater than 2 on a fair six-sided die', NULL, 'Rolling a number greater than 2: 3, 4, 5 or 6, so $\frac{4}{6} \approx 0.67$. Tails: $\frac{1}{2} = 0.5$. A prime from 1 to 10 (2, 3, 5, 7): $\frac{4}{10} = 0.4$. A red marble: $\frac{3}{10} = 0.3$. The die has the greatest probability.', 'checked', '{"lint":[],"solve":{"answer":"Rolling a number greater than 2 on a fair six-sided die","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Die > 2: {3,4,5,6} = 4/6 = 2/3. Primes 1-10: 2,3,5,7 = 4/10 = 0.4. Red: 3/10 = 0.3. Tails: 1/2. Greatest is 2/3.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f89c5bd-89b6-4122-bd0a-b97d954b767a', 'NC26.6.RD.1', 3, 'choice', 'Describing likelihood with probability words', 'Four events are listed. A: Rolling a 9 on a fair six-sided die. B: Rolling a 5 on a fair six-sided die. C: Tossing a fair coin and getting tails. D: Rolling a number less than 7 on a fair six-sided die. Which list puts the events in order from least likely to most likely?', '["B, A, C, D","A, B, C, D","A, C, B, D","D, C, B, A"]', 'A, B, C, D', NULL, 'Event A is impossible, with a probability of 0. Event B has a probability of $\frac{1}{6}$. Event C has a probability of $\frac{1}{2}$. Event D is certain, with a probability of 1. From least to most likely the order is A, B, C, D.', 'checked', '{"lint":[],"solve":{"answer":"A, B, C, D","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0; B: 1/6; C: 1/2; D: 1. Least to most: A, B, C, D.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3727c6f8-0eaf-414b-b31a-bb15a241d5c0', 'NC26.6.RD.1', 3, 'numeric', 'Probability values from 0 to 1', 'A spinner has equal-size sections. The probability of landing on any one section is at least 0.05. What is the greatest number of sections the spinner could have?', '[]', '20', '1/0.05', 'With $n$ equal sections, the probability of each section is $\frac{1}{n}$. We need $\frac{1}{n}$ to be at least $0.05 = \frac{1}{20}$. That works when $n$ is 20 or less, so the greatest number of sections is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each section has P = 1/n >= 0.05 = 1/20, so n <= 20. Greatest n = 20.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('928a8e12-aece-4537-a7b5-ef1041eb7493', 'NC26.6.RD.1', 3, 'numeric', 'Theoretical probability from equally likely outcomes', 'A bag has red marbles and blue marbles in the ratio 2 to 3. There are 20 marbles in all. One marble is picked at random. What is the probability that it is red? Give your answer as a fraction.', '[]', '2/5', '2/(2+3)', 'The ratio 2 to 3 means 2 of every 5 marbles are red. With 20 marbles, that is 8 red and 12 blue. The probability of red is $\frac{8}{20} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red = 2/5 of 20 = 8. P = 8/20 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eec63a6c-2d3d-4b78-93b8-ecd8be37500f', 'NC26.6.RD.1', 3, 'numeric', 'Theoretical probability from equally likely outcomes', 'A bag has 26 tiles, one for each letter of the alphabet. One tile is picked at random. What is the probability that its letter is one of the letters in the word MATHEMATICS? Give your answer as a fraction.', '[]', '4/13', '8/26', 'The different letters in MATHEMATICS are M, A, T, H, E, I, C and S. That is 8 letters, because the repeated M, A and T count only once. The probability is $\frac{8}{26} = \frac{4}{13}$.', 'checked', '{"lint":[],"solve":{"answer":"4/13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distinct letters in MATHEMATICS: M, A, T, H, E, I, C, S = 8. P = 8/26 = 4/13.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eebea90d-bb93-43a5-ac70-c4a97a5c31ce', 'NC26.6.RD.1', 3, 'numeric', 'Theoretical probability from equally likely outcomes', 'In a class of 30 students, 12 play soccer and 8 play basketball. No student plays both sports. One student is chosen at random. What is the probability that the student plays neither sport? Give your answer as a fraction.', '[]', '1/3', '(30-12-8)/30', 'The students who play a sport number $12 + 8 = 20$, so $30 - 20 = 10$ students play neither. The probability is $\frac{10}{30} = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Neither: 30 - 12 - 8 = 10. P = 10/30 = 1/3.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e66526e2-4d04-437b-92dd-a57bf4c71f66', 'NC26.6.RD.1', 3, 'choice', 'Probability with dice, coins and numbered cards', 'A card is picked at random from cards numbered 1 to 30. What is the probability that its number is divisible by both 2 and 3?', '["$\\frac{1}{2}$","$\\frac{1}{3}$","$\\frac{5}{6}$","$\\frac{1}{6}$"]', '$\frac{1}{6}$', NULL, 'A number divisible by both 2 and 3 is a multiple of 6. The multiples of 6 from 1 to 30 are 6, 12, 18, 24 and 30, which is 5 cards out of 30. The probability is $\frac{5}{30} = \frac{1}{6}$. The value $\frac{1}{2}$ counts only multiples of 2 and $\frac{1}{3}$ counts only multiples of 3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 2 and 3 = multiples of 6: 6, 12, 18, 24, 30 = 5 of 30 = 1/6.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f16467be-a35e-4ce9-ad80-8daa34d1a61c', 'NC26.6.RD.1', 3, 'choice', 'Probability with dice, coins and numbered cards', 'Mia says that rolling a 6 on a fair six-sided die is less likely than rolling an even number. Which reason shows that Mia is correct?', '["Only 1 of the 6 faces shows a 6, but 3 of the 6 faces show an even number","A 6 is the greatest number on the die, so it is the hardest to roll","Even numbers are larger than odd numbers, so they come up more often","A 6 is an even number, so both events are equally likely"]', 'Only 1 of the 6 faces shows a 6, but 3 of the 6 faces show an even number', NULL, 'The probability of rolling a 6 is $\frac{1}{6}$. The probability of an even number is $\frac{3}{6} = \frac{1}{2}$ because 2, 4 and 6 are even. Since $\frac{1}{6}$ is less than $\frac{1}{2}$, Mia is correct. The size of a number does not change its chance on a fair die.', 'checked', '{"lint":[],"solve":{"answer":"Only 1 of the 6 faces shows a 6, but 3 of the 6 faces show an even number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(6) = 1/6 < P(even) = 3/6. The first reason is the correct one.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85bd92e7-7dff-41a2-9d22-14e56f4b42e9', 'NC26.6.RD.1', 3, 'numeric', 'Probability that an event does not happen', 'A spinner can land only on red, blue or green. The probability of red is $\frac{1}{2}$ and the probability of blue is $\frac{1}{3}$. What is the probability of green? Give your answer as a fraction.', '[]', '1/6', '1-1/2-1/3', 'The three probabilities add to 1. Red and blue together are $\frac{1}{2} + \frac{1}{3} = \frac{5}{6}$, so green is $1 - \frac{5}{6} = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 1/2 - 1/3 = 6/6 - 3/6 - 2/6 = 1/6.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40e096c3-d44d-4fb2-8794-37c09d973c09', 'NC26.6.RD.1', 3, 'numeric', 'Probability that an event does not happen', 'A bag holds 24 marbles. The probability of picking a red marble at random is $\frac{3}{8}$. How many of the marbles are not red?', '[]', '15', '24*(1-3/8)', 'The probability of not red is $1 - \frac{3}{8} = \frac{5}{8}$. Then $\frac{5}{8}$ of 24 marbles is $5 \times 3 = 15$ marbles. Check: red marbles are $\frac{3}{8} \times 24 = 9$, and $24 - 9 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red = 3/8 x 24 = 9; not red = 15.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
