INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f429233d-034b-47ad-8e61-ee55e0bd64ae', 'NC26.6.RD.1', 3, 'numeric', 'Probability with a spinner of equal sections', 'A spinner has 12 equal sections. The probability of landing on red is $\frac{1}{4}$ and the probability of landing on blue is $\frac{1}{3}$. All the other sections are green. How many sections are green?', '[]', '5', '12-12*1/4-12*1/3', 'Red takes $\frac{1}{4}$ of 12, which is 3 sections. Blue takes $\frac{1}{3}$ of 12, which is 4 sections. The green sections are $12 - 3 - 4 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 12/4 = 3; blue 12/3 = 4; green 12 - 7 = 5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6941226c-05d5-482c-8b54-0a39a0d52f9a', 'NC26.6.RD.1', 3, 'choice', 'Probability with a spinner of equal sections', 'A fair spinner has 12 equal sections numbered 1 to 12. Which event has a probability of $\frac{1}{2}$?', '["Landing on a prime number","Landing on a number greater than 6","Landing on a multiple of 3","Landing on a number less than 6"]', 'Landing on a number greater than 6', NULL, 'The numbers greater than 6 are 7 to 12, which is 6 sections out of 12, or $\frac{1}{2}$. There are 5 primes (2, 3, 5, 7 and 11), 4 multiples of 3 (3, 6, 9 and 12) and 5 numbers less than 6 (1 to 5), so those events are not $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"Landing on a number greater than 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prime: 2,3,5,7,11 = 5/12. >6: 7-12 = 6/12 = 1/2. <6: 5/12. Multiple of 3: 4/12. Only ''greater than 6''.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e8cd164-bc01-420d-aa61-28f6f989e330', 'NC26.6.RD.1', 3, 'numeric', 'Writing a probability as a fraction, decimal or percent', 'A fair spinner has equal sections. The probability of landing on any one section is 12.5%. How many sections does the spinner have?', '[]', '8', '100/12.5', 'Each section has a probability of $12.5\% = 0.125 = \frac{1}{8}$. With $n$ equal sections each has probability $\frac{1}{n}$, so the spinner has 8 sections.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12.5% = 1/8, so 8 sections.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0e8115d-f6fa-4081-8c89-73c5b649c176', 'NC26.6.RD.1', 3, 'numeric', 'Writing a probability as a fraction, decimal or percent', 'A spinner lands on blue with a probability of $\frac{7}{8}$. What is this probability as a percent? Give just the number, without the percent sign.', '[]', '87.5', '7/8*100', '$\frac{7}{8} = 7 \div 8 = 0.875$. As a percent, that is $0.875 \times 100 = 87.5$ percent.', 'checked', '{"lint":[],"solve":{"answer":"87.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 = 0.875 = 87.5%.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bb84a03-b0d2-4ab0-856a-87def2d1488d', 'NC26.6.RD.1', 3, 'numeric', 'Experimental probability from results', 'A spinner was spun 40 times and landed on red 12 times. It was then spun 10 more times and landed on red 8 times. Using all of the spins, what is the experimental probability of landing on red? Give your answer as a fraction.', '[]', '2/5', '(12+8)/(40+10)', 'In all there were $40 + 10 = 50$ spins, and red came up $12 + 8 = 20$ times. The experimental probability is $\frac{20}{50} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 12 + 8 = 20 of 40 + 10 = 50: 20/50 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18ef7239-01e4-4de9-80c0-65ccd5a5b8ba', 'NC26.6.RD.1', 3, 'numeric', 'Experimental probability from results', 'A team won 14 of its first 20 games. How many of its next 30 games must it win so that its experimental probability of winning, over all 50 games, is $\frac{3}{5}$?', '[]', '16', '3/5*50-14', 'For a probability of $\frac{3}{5}$ over 50 games the team needs $\frac{3}{5} \times 50 = 30$ wins in all. It already has 14, so it must win $30 - 14 = 16$ of the next 30 games.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 x 50 = 30 wins in all; 30 - 14 = 16 of the next 30.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c528e73-140d-456c-925c-0a1c304950e2', 'NC26.6.RD.1', 3, 'numeric', 'Predicting how many times an event will happen', 'A bag has 3 red marbles, 4 blue marbles and 3 green marbles. A marble is picked at random, its color is noted, and it is put back. This is done 200 times. About how many times would you expect the marble picked to NOT be blue?', '[]', '120', '200*(1-4/10)', 'There are 10 marbles, so the probability of blue is $\frac{4}{10}$ and the probability of not blue is $1 - \frac{4}{10} = \frac{6}{10}$. Then $\frac{6}{10} \times 200 = 120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not blue: 6 of 10 = 3/5. 3/5 x 200 = 120.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('082a8653-617b-4942-9178-626572f588dd', 'NC26.6.RD.1', 3, 'choice', 'Predicting how many times an event will happen', 'A fair spinner has 8 equal sections numbered 1 to 8. It is spun 120 times. Which is the best prediction for the number of times it lands on a prime number?', '["15","60","30","90"]', '60', '4/8*120', 'The prime numbers from 1 to 8 are 2, 3, 5 and 7, so the probability of a prime is $\frac{4}{8} = \frac{1}{2}$. Then $\frac{1}{2} \times 120 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes 1-8: 2, 3, 5, 7 = 4/8 = 1/2. 1/2 x 120 = 60.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a45166d1-9e60-42cc-acc2-0c59984cdd54', 'NC26.6.RD.1', 3, 'numeric', 'Comparing experimental and theoretical probability', 'The theoretical probability of a spinner landing on blue is $\frac{3}{10}$. Sara spins it 50 times, and the experimental probability of blue turns out to be 0.4. How many more times did it land on blue than the theory predicts?', '[]', '5', '0.4*50-3/10*50', 'Theory predicts $\frac{3}{10} \times 50 = 15$ blues. An experimental probability of 0.4 means $0.4 \times 50 = 20$ blues. That is $20 - 15 = 5$ more.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Theory: 0.3 x 50 = 15. Actual: 0.4 x 50 = 20. 20 - 15 = 5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26aa6bbb-6c69-4568-8918-a5592a75e86b', 'NC26.6.RD.1', 3, 'choice', 'Comparing experimental and theoretical probability', 'Group A tosses a fair coin 10 times and gets 7 heads. Group B tosses the same coin 200 times and gets 104 heads. Which statement is true?', '["Group A''s experimental probability of heads is closer to the theoretical probability than Group B''s","Both groups have the same experimental probability of heads","The coin must not be fair, because Group A got more heads than tails","Group B''s experimental probability of heads is closer to the theoretical probability than Group A''s"]', 'Group B''s experimental probability of heads is closer to the theoretical probability than Group A''s', NULL, 'The theoretical probability of heads is $\frac{1}{2} = 0.5$. Group A has $\frac{7}{10} = 0.7$, which is 0.2 away. Group B has $\frac{104}{200} = 0.52$, which is only 0.02 away. A fair coin can give 7 heads in 10 tosses, so Group A''s result does not show the coin is unfair.', 'checked', '{"lint":[],"solve":{"answer":"Group B''s experimental probability of heads is closer to the theoretical probability than Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 7/10 = 0.7 (0.2 off). B: 104/200 = 0.52 (0.02 off). B is closer.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba2674d2-3560-4357-ba6f-3c42f27c080d', 'NC26.6.RD.1', 3, 'numeric', 'Comparing experimental and theoretical probability', 'A fair six-sided die is rolled 120 times and a 2 comes up 25 times. What is the experimental probability of rolling a 2 minus the theoretical probability of rolling a 2? Give your answer as a fraction.', '[]', '1/24', '25/120-1/6', 'The experimental probability is $\frac{25}{120} = \frac{5}{24}$. The theoretical probability is $\frac{1}{6} = \frac{4}{24}$. The difference is $\frac{5}{24} - \frac{4}{24} = \frac{1}{24}$.', 'checked', '{"lint":[],"solve":{"answer":"1/24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25/120 = 5/24; theoretical 1/6 = 4/24; difference 1/24.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21466528-26e1-4214-95d4-8f929a660b9c', 'NC26.6.RD.1', 3, 'choice', 'What a probability does and does not tell us', 'Dev rolls a fair six-sided die 6 times. Which statement is true?', '["He will roll a 4 exactly once","He might roll no 4 at all, even though each roll has a $\\frac{1}{6}$ chance of being a 4","He cannot roll a 4 twice","He must roll each number from 1 to 6 exactly once"]', 'He might roll no 4 at all, even though each roll has a $\frac{1}{6}$ chance of being a 4', NULL, 'Probability tells what is likely over many rolls, not exactly what happens in 6 rolls. Dev could roll no 4s, one 4 or several 4s.', 'checked', '{"lint":[],"solve":{"answer":"He might roll no 4 at all, even though each roll has a $\\frac{1}{6}$ chance of being a 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each roll independent with P(4) = 1/6; zero 4s in 6 rolls is possible ((5/6)^6 ~ 0.33). Others false.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a40657de-f51f-42e8-bec5-dbe15299a566', 'NC26.6.RD.1', 3, 'choice', 'What a probability does and does not tell us', 'A fair coin is tossed again and again. Which statement is true?', '["The number of heads and tails will always be exactly equal","As the number of tosses grows, the experimental probability of heads usually gets closer to $\\frac{1}{2}$","The experimental probability of heads moves farther from $\\frac{1}{2}$ as the tosses grow","The experimental probability of heads is exactly $\\frac{1}{2}$ after 100 tosses"]', 'As the number of tosses grows, the experimental probability of heads usually gets closer to $\frac{1}{2}$', NULL, 'With a small number of tosses the experimental probability can be far from $\frac{1}{2}$. As the number of tosses grows, it usually settles closer to the theoretical probability of $\frac{1}{2}$, but it need not be exactly $\frac{1}{2}$ at any point.', 'checked', '{"lint":[],"solve":{"answer":"As the number of tosses grows, the experimental probability of heads usually gets closer to $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Law of large numbers: relative frequency tends toward 1/2; not exact, not guaranteed equal counts.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c8cb637-9bf9-4f8a-8bf8-39bd14c325d2', 'NC26.6.RD.1', 3, 'numeric', 'Finding a number of outcomes from a probability', 'A bag has 5 blue marbles and some red marbles. The probability of picking a blue marble at random is $\frac{1}{4}$. How many red marbles are in the bag?', '[]', '15', '5*4-5', 'If 5 marbles are $\frac{1}{4}$ of the bag, the bag holds $5 \times 4 = 20$ marbles. The red marbles number $20 - 5 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 is 1/4 of total, so total 20; red = 15.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c533f4d-e272-4fcb-ad6c-8e14636a1804', 'NC26.6.RD.1', 3, 'numeric', 'Finding a number of outcomes from a probability', 'A jar holds 60 beans that are red, black or white. The probability of picking a red bean at random is $\frac{1}{4}$ and the probability of picking a black bean is $\frac{1}{3}$. How many beans are white?', '[]', '25', '60-60/4-60/3', 'Red beans are $\frac{1}{4}$ of 60, which is 15. Black beans are $\frac{1}{3}$ of 60, which is 20. The white beans number $60 - 15 - 20 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 60/4 = 15; black 60/3 = 20; white 60 - 35 = 25.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b74ee85d-aba5-4137-b8ca-b0c570b1f940', 'NC26.6.RD.1', 3, 'choice', 'Finding a number of outcomes from a probability', 'A bag has 20 marbles. The probability of picking a blue marble at random is greater than $\frac{1}{2}$ but less than $\frac{3}{4}$. How many blue marbles could be in the bag?', '["8","10","12","15"]', '12', NULL, 'Half of 20 is 10 and three fourths of 20 is 15, so the number of blue marbles must be more than 10 and less than 15. The number 12 fits, since $\frac{12}{20} = 0.6$. With 10 marbles the probability is exactly $\frac{1}{2}$ and with 15 it is exactly $\frac{3}{4}$, and 8 is too few.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 10 < blue < 15 (1/2 x 20 = 10, 3/4 x 20 = 15). 8 no, 10 no (= 1/2), 15 no (= 3/4), 12 yes (0.6).","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a560e8fe-3ce3-4a39-8c46-bb18222e0448', 'NC26.6.RD.1', 3, 'numeric', 'How adding or removing items changes a probability', 'A bag has 3 red marbles and 9 blue marbles. How many red marbles must be added so that the probability of picking a red marble is $\frac{1}{2}$?', '[]', '6', '9-3', 'The probability is $\frac{1}{2}$ when there are as many red marbles as blue marbles. There are 9 blue, so there must be 9 red. Adding $9 - 3 = 6$ red marbles gives $\frac{9}{18} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 + x)/(12 + x) = 1/2: 6 + 2x = 12 + x, x = 6 (9 red, 9 blue).","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('094ab2b5-1087-4793-968f-b6839eea66c1', 'NC26.6.RD.1', 3, 'numeric', 'How adding or removing items changes a probability', 'A bag has 4 green marbles and 8 yellow marbles. How many yellow marbles must be removed so that the probability of picking a green marble is $\frac{1}{2}$?', '[]', '4', '8-4', 'The probability of green is $\frac{1}{2}$ when there are as many yellow marbles as green. There are 4 green, so 4 yellow must be left. Remove $8 - 4 = 4$ yellow marbles to get $\frac{4}{8} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need yellow = green = 4: remove 8 - 4 = 4. P = 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('772c51bd-26b5-47c1-a29a-867c5214c682', 'NC26.6.RD.1', 3, 'choice', 'How adding or removing items changes a probability', 'A bag has 6 red marbles and 6 blue marbles. Three red marbles are removed. What is the new probability of picking a red marble at random?', '["$\\frac{1}{4}$","$\\frac{1}{2}$","$\\frac{1}{3}$","$\\frac{2}{3}$"]', '$\frac{1}{3}$', NULL, 'After removing 3 red marbles there are 3 red and 6 blue, which is 9 marbles in all. The probability of red is $\frac{3}{9} = \frac{1}{3}$. The value $\frac{1}{4}$ forgets to take the 3 marbles out of the total.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 red, 6 blue: 3/9 = 1/3.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('581fdbbd-9d62-40a2-b3d8-24c5bc7c36db', 'NC26.6.RD.1', 3, 'choice', 'Comparing the probabilities of two events', 'A card is chosen at random from cards numbered 1 to 15. Which event is the most likely?', '["The number is a multiple of 3","The number is prime","The number is odd","The number is greater than 8"]', 'The number is odd', NULL, 'Odd numbers: 1, 3, 5, 7, 9, 11, 13 and 15 is 8 cards. Multiples of 3: 3, 6, 9, 12 and 15 is 5 cards. Primes: 2, 3, 5, 7, 11 and 13 is 6 cards. Greater than 8: 9 to 15 is 7 cards. Eight out of 15 is the most, so odd is the most likely.', 'checked', '{"lint":[],"solve":{"answer":"The number is odd","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-15: prime 6 (2,3,5,7,11,13); odd 8; >8: 7 (9-15); multiple of 3: 5. Odd is most likely.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4b4a525-6695-49f2-8441-c9a1b94d1c43', 'NC26.6.RD.1', 3, 'numeric', 'Comparing the probabilities of two events', 'Bag A has 3 red marbles and 7 blue marbles. Bag B has 2 red marbles and 3 blue marbles. One marble is picked at random from a bag. How much greater is the probability of picking red from Bag B than from Bag A? Give your answer as a fraction.', '[]', '1/10', '2/5-3/10', 'Bag A has 10 marbles, so the probability of red is $\frac{3}{10}$. Bag B has 5 marbles, so the probability of red is $\frac{2}{5} = \frac{4}{10}$. The difference is $\frac{4}{10} - \frac{3}{10} = \frac{1}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"1/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B: 2/5 = 4/10; A: 3/10. 4/10 - 3/10 = 1/10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0c88353-dc0f-4afc-b854-a491816a65c0', 'NC26.6.RD.2', 1, 'choice', 'Telling a statistical question from other questions', 'Which of these is a statistical question?', '["How many pets do the students in a sixth-grade class have?","How many pets does Sam have?","How old is the teacher of the sixth-grade class?","What time does school start on Monday?"]', 'How many pets do the students in a sixth-grade class have?', NULL, 'A statistical question is one where you expect the answers to vary, so you need data from a group. Each student in a class may have a different number of pets. The other questions each have one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many pets do the students in a sixth-grade class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects variability in the answers. Pets of students in a class vary; the others have a single answer.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
