INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddf63034-b115-4f68-9966-34d0ea96d207', 'NC26.6.RD.2', 1, 'numeric', 'Sample size and the share of the population asked', 'Sam wants his sample to be $\frac{1}{4}$ of the 36 students in his class. How many students should he ask?', '[]', '9', '1/4*36', '$\frac{1}{4}$ of 36 is $36 \div 4 = 9$ students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 of 36 = 9.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
