INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('baf5ce72-30fa-48eb-a089-9226f24c2870', 'NC26.6.RD.2', 1, 'numeric', 'Organizing data in a frequency table', 'Twelve students named their favorite color: red, blue, red, green, blue, red, blue, red, green, red, blue, red. How many students named red?', '[]', '6', '1+1+1+1+1+1', 'Count the reds in the list: there are 6 of them. The frequency table would show red: 6, blue: 4, green: 2.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"red at positions 1, 3, 6, 8, 10, 12 = 6 (blue 4, green 2, total 12 check).","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
