INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3c5878d-452b-4ab5-b7e6-df7b85f9f410', 'NC26.6.RD.2', 1, 'numeric', 'Organizing data in a frequency table', 'Ten students got these scores on a quiz: 8, 9, 7, 8, 10, 9, 8, 7, 9, 8. How many students scored 8?', '[]', '4', '1+1+1+1', 'Count the 8s in the list: there are 4. The frequency table would show 7: 2, 8: 4, 9: 3, 10: 1.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scores: 8,9,7,8,10,9,8,7,9,8. 8s at positions 1, 4, 7, 10 = 4.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
