INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1887352d-e07c-4342-a3f1-1e4000a33c6e', 'NC26.6.RD.2', 1, 'choice', 'Spotting a biased survey question', 'Mrs. Ford wants to know whether students want a longer recess. Which survey question is worded fairly?', '["Don''t you think that recess is far too short for students to play?","Would you like recess to be longer, shorter or the same as it is now?","Wouldn''t you agree that a longer recess would be great for everyone?","Most students already want a longer recess, so would you like one too?"]', 'Would you like recess to be longer, shorter or the same as it is now?', NULL, 'A fair question gives all the choices and does not hint at a best one. The question with three choices does that. The other three push people toward saying that recess should be longer.', 'checked', '{"lint":[],"solve":{"answer":"Would you like recess to be longer, shorter or the same as it is now?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Offering longer, shorter or same without leading language is neutral; the others push toward yes.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c539baa4-ef7b-4d73-a6ae-3aff5ae65108', 'NC26.6.RD.2', 1, 'choice', 'Spotting a biased survey question', 'A survey asks, "Everyone loves our delicious new salad bar, don''t you?" Which statement tells why this is a biased survey question?', '["It asks about food, and food questions are always biased","Its wording pushes people to give the answer of yes to it","It asks everyone in the school instead of only a smaller sample","It ends with a question mark instead of a period or a statement"]', 'Its wording pushes people to give the answer of yes to it', NULL, 'A biased question is worded so that it pushes people toward one answer. Here, "everyone loves" and "delicious" push people to say yes. Asking about food, asking everyone, or ending with a question mark do not make a question biased.', 'checked', '{"lint":[],"solve":{"answer":"Its wording pushes people to give the answer of yes to it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: option D wording ''give the answer of yes to it'' is a little clumsy, but the key is clear.","work":"''Everyone loves our delicious...don''t you?'' leads respondents toward yes.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('956da284-0a4f-4697-a190-e3c24ba487b5', 'NC26.6.RD.2', 1, 'choice', 'Spotting a biased way of choosing a sample', 'Tara wants to know how many hours a day students at her school use screens. She asks only the students in the computer club. Why might her sample be biased?', '["She asked too many students for a survey, which makes the results less accurate","She asked students instead of teachers, who also use screens during the day","Nothing is wrong with her sample, because computer club members are students at her school","Computer club members probably use screens more often than most other students"]', 'Computer club members probably use screens more often than most other students', NULL, 'A sample is biased when it leaves out or overrepresents part of the population. Computer club members probably use screens more than other students, so the sample would make the school''s screen time look higher than it is.', 'checked', '{"lint":[],"solve":{"answer":"Computer club members probably use screens more often than most other students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Computer club members likely use screens more than typical students, so the sample is not representative.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3be73a55-4f7f-4ade-85c8-dcd8a4b07a0e', 'NC26.6.RD.2', 1, 'choice', 'Spotting a biased way of choosing a sample', 'A town wants to know whether residents want a new bike path. The survey is handed out only at a bike shop. Which statement is true?', '["The sample is fair because the shop is in the same town where the new bike path would be built","The sample is likely biased because bike shop customers favor bike paths","The sample is fair because bike paths are for everyone, including people who do not ride","The sample is fair as long as enough people at the bike shop fill out the survey form"]', 'The sample is likely biased because bike shop customers favor bike paths', NULL, 'People at a bike shop ride bikes more than most residents, so they are more likely to want a bike path. The sample does not match the town as a whole.', 'checked', '{"lint":[],"solve":{"answer":"The sample is likely biased because bike shop customers favor bike paths","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bike shop customers likely favor bike paths, so the sample is biased.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f22a6e-0549-480b-bb9d-d00ddaa610f9', 'NC26.6.RD.2', 1, 'choice', 'Choosing a representative or random sample', 'Which sentence best tells what it means for a sample to be representative?', '["It is made up only of people who volunteered to answer the questions","It is as small as it can possibly be, so that it is quick to collect","It has about the same mix of people or things as the whole population it comes from","It includes only the people who care the most about the topic being studied"]', 'It has about the same mix of people or things as the whole population it comes from', NULL, 'A representative sample looks like the whole population, with about the same mix of people or things. Volunteers, tiny samples and the most interested people can give a different mix.', 'checked', '{"lint":[],"solve":{"answer":"It has about the same mix of people or things as the whole population it comes from","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A representative sample mirrors the mix of the population.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a20e191-4170-40d3-beda-a4db7781596c', 'NC26.6.RD.2', 1, 'choice', 'Sample size and the share of the population asked', 'A school has 800 students. Which random sample is likely to give the best picture of what all the students think?', '["A random sample of 8 students chosen from the list, which is 1 out of every 100","A random sample of 4 students chosen by lottery, which is 1 out of every 200 students","A random sample of 80 students, which is 1 out of every 10 students","A random sample of 16 students, which is 1 out of every 50 students in school"]', 'A random sample of 80 students, which is 1 out of every 10 students', NULL, 'A larger random sample is more likely to match the whole population than a smaller one. Of the choices, 80 students (1 out of every 10) is the largest sample.', 'checked', '{"lint":[],"solve":{"answer":"A random sample of 80 students, which is 1 out of every 10 students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All random; the largest (80) gives the most reliable picture.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e59b151-8b96-4402-a220-bf7a62540450', 'NC26.6.RD.2', 1, 'choice', 'Deciding what data to collect and record', 'Kofi wants to answer the question "How many letters are in the first names of the students in my grade?" What should he record for each student?', '["The student''s favorite letter of the alphabet to write down","The number of students in the grade who have first names","The student''s age in years on the day of the survey","The number of letters in each student''s own first name"]', 'The number of letters in each student''s own first name', NULL, 'To answer the question, he needs one number for each student: how many letters are in that student''s first name. The other things are not what the question asks about.', 'checked', '{"lint":[],"solve":{"answer":"The number of letters in each student''s own first name","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Answering the question needs the number of letters in each student''s first name.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be0706ec-b494-464d-8c67-c35856c7297b', 'NC26.6.RD.2', 1, 'choice', 'Deciding what data to collect and record', 'Lena wants to answer "How far do the students in my class live from school?" What should she record for each student?', '["The distance from the student''s home to school, in miles","The student''s favorite way to travel to school, such as bus or walking","The total number of students in the class, as a number such as 24 students","The color of the student''s backpack that is carried to school each day"]', 'The distance from the student''s home to school, in miles', NULL, 'The question is about distance, so Lena records how far each student''s home is from school. The other choices record things the question does not ask about.', 'checked', '{"lint":[],"solve":{"answer":"The distance from the student''s home to school, in miles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The distance from home to school for each student answers ''how far''.","run_id":"claude-code","at":"2026-10-18T03:34:26.846Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb3da64-bb0b-47f5-8fae-9f5c748ac7e8', 'NC26.6.RD.2', 2, 'choice', 'Spotting a biased survey question', 'Mr. Cole wants to know where students like to read. Which survey question is worded in a way that pushes people toward one answer?', '["Where do you like to read best: the library, a classroom, or home?","Everyone loves the fantastic new library, so isn''t it the best place to read?","How many times a week do you read at the library?","What is your favorite place to read?"]', 'Everyone loves the fantastic new library, so isn''t it the best place to read?', NULL, 'The question that says "Everyone loves the fantastic new library" tells people what answer to give, so it is biased. The other questions are neutral.', 'checked', '{"lint":[],"solve":{"answer":"Everyone loves the fantastic new library, so isn''t it the best place to read?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question that states ''Everyone loves the fantastic new library'' leads respondents to agree; it is the biased one.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afd60d88-824e-478d-8216-4969ae2c439f', 'NC26.6.RD.2', 2, 'numeric', 'Organizing survey results in a frequency table', 'A survey of 25 students asked how many brothers and sisters each has. The results were: 0 siblings, 4 students; 1 sibling, 9 students; 2 siblings, 8 students; 3 siblings, 4 students. How many students have at least 2 siblings?', '[]', '12', '8+4', '"At least 2" means 2 or more. Add the students with 2 siblings and with 3 siblings: $8 + 4 = 12$ students.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 2 siblings: 2 siblings (8) + 3 siblings (4) = 12. Totals check: 4 + 9 + 8 + 4 = 25.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8e6d13-0b1a-4e7e-ba1a-2937fbbdd31c', 'NC26.6.RD.2', 2, 'choice', 'Choosing a representative sample', 'A school has 600 students. The principal wants to know the favorite lunch of all students. Which way of choosing 40 students to ask is most likely to give a representative sample?', '["Ask the first 40 students in the pizza line","Ask the 40 students on the soccer team","Ask 40 students who volunteer in the cafeteria","Choose 40 names at random from a list of all students"]', 'Choose 40 names at random from a list of all students', NULL, 'A random choice from the list of everyone gives every student the same chance of being asked. The other groups all favor certain kinds of students.', 'checked', '{"lint":[],"solve":{"answer":"Choose 40 names at random from a list of all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random selection from the full list gives every student an equal chance; the other methods are biased groups.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d77bdd-3c5f-4e9f-a458-8abd39b2900f', 'NC26.6.RD.2', 2, 'choice', 'Telling a statistical question from other questions', 'A neighborhood group is studying traffic near the school. Which of these is a statistical question?', '["How many lanes does the road in front of the school have?","What is the speed limit on the road in front of the school?","How many cars pass the school each hour during the morning?","How many cars are parked outside the school right now?"]', 'How many cars pass the school each hour during the morning?', NULL, 'The number of cars passing changes from hour to hour, so answering the question takes data from many hours. The number of lanes and the speed limit are single facts, and the number of cars parked right now is one count at one moment.', 'checked', '{"lint":[],"solve":{"answer":"How many cars pass the school each hour during the morning?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lanes, speed limit and cars parked right now each have one answer. Cars passing each hour during the morning varies hour to hour/day to day: statistical.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34afff1e-c373-4107-b30d-9cd0db49d0b4', 'NC26.6.RD.2', 2, 'numeric', 'Telling a statistical question from other questions', 'A coach writes five questions. 1. How many goals did the team score in each game this season? 2. How many goals did Dev score in last Friday''s game? 3. How long does it take each player to run one lap of the track? 4. How many players are on the team''s roster today? 5. How far does each player live from school, in miles? How many of the five questions are statistical questions?', '[]', '3', '3', 'Questions 1, 3 and 5 expect different answers from game to game or player to player, so they are statistical. Question 2 asks about one player in one game and question 4 has one answer. That makes 3 statistical questions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1: goals in each game vary across games -> yes. 2: one player, one game -> no. 3: lap time of each player varies -> yes. 4: roster today is one number -> no. 5: distance for each player varies -> yes. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc7fff11-aaf2-4c54-b670-834bae49eb7c', 'NC26.6.RD.2', 2, 'numeric', 'Population and sample', 'A town has $8{,}000$ residents. A survey about the new library hours is given to 200 of them. How many residents are in the population but not in the sample?', '[]', '7800', '8000-200', 'The population is all $8{,}000$ residents and the sample is 200 of them. Residents not in the sample number $8{,}000 - 200 = 7{,}800$.', 'checked', '{"lint":[],"solve":{"answer":"7800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population 8,000, sample 200. Not in sample: 8000 - 200 = 7800.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a9b5ca0-0190-4866-a3ef-c2492cab103b', 'NC26.6.RD.2', 2, 'choice', 'Population and sample', 'A researcher wants to learn about the heights of all the sixth graders in North Carolina. She measures 150 sixth graders from five schools. Which statement is correct?', '["The 150 sixth graders are the population, and all sixth graders in North Carolina are the sample.","The five schools are the population, and the 150 sixth graders are the sample.","All sixth graders in North Carolina are the population, and the 150 she measures are a sample.","The heights are the population, and the 150 sixth graders are the sample."]', 'All sixth graders in North Carolina are the population, and the 150 she measures are a sample.', NULL, 'The population is the whole group she wants to learn about, which is all sixth graders in North Carolina. The 150 students she measures are a part of that group, so they are a sample.', 'checked', '{"lint":[],"solve":{"answer":"All sixth graders in North Carolina are the population, and the 150 she measures are a sample.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population: all NC sixth graders; sample: the 150 measured. C.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06393d36-8713-43e4-9fa6-1debe25f9a31', 'NC26.6.RD.2', 2, 'numeric', 'Population and sample', 'A factory makes $2{,}400$ light bulbs in a day. An inspector tests 1 out of every 20 bulbs. How many bulbs are in the inspector''s sample?', '[]', '120', '2400/20', 'Testing 1 out of every 20 bulbs means one twentieth of the bulbs. $2{,}400 \div 20 = 120$ bulbs.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 of every 20 bulbs: 2400 / 20 = 120 bulbs in the sample.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f16d6ba3-79cd-4516-85cb-65b7317a8cf9', 'NC26.6.RD.2', 2, 'choice', 'Spotting a biased survey question', 'A survey asks, "How much do you enjoy our wonderful school library?" Which rewording takes the bias out?', '["How would you rate our school library: poor, fair, good or excellent?","How much do you enjoy our school library, which has the best books in town?","How much do you love our school library?","How wonderful is our school library to you?"]', 'How would you rate our school library: poor, fair, good or excellent?', NULL, 'The word "wonderful" pushes people toward a positive answer. The rewording that offers a range of ratings, from poor to excellent, does not hint at an answer. The others keep or add words that push toward a high opinion.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate our school library: poor, fair, good or excellent?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A \"love\" and D \"wonderful\" still lead; C adds praise. B gives a balanced rating scale with no loaded word.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5c93507-e7b0-445b-9996-f573ce83cddc', 'NC26.6.RD.2', 2, 'numeric', 'Spotting a biased survey question', 'A club asks five survey questions about hiking. 1. Do you prefer hiking, biking or swimming? 2. Do you agree that hiking is boring and nobody likes it? 3. How many times did you go hiking last month? 4. Isn''t swimming way better than hiking? 5. Hiking is great exercise, isn''t it? How many of the five questions are biased?', '[]', '3', '3', 'Questions 2, 4 and 5 are worded to push people toward one answer. Questions 1 and 3 are fair. That makes 3 biased questions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 neutral. 2 leading (\"boring and nobody likes it\"). 3 neutral count. 4 leading (\"Isn''t swimming way better\"). 5 leading (\"great exercise, isn''t it\"). Biased = 3.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a445e40f-a811-4070-b7c1-6e75e6191821', 'NC26.6.RD.2', 2, 'choice', 'Spotting a biased way of choosing a sample', 'A school wants to know what lunch time students prefer. Which plan is MOST likely to give a biased sample?', '["Ask every 10th student on an alphabetical list of all students","Draw 50 names from a box holding every student''s name","Ask only the students who are first in the lunch line","Ask 10 students chosen at random from each grade"]', 'Ask only the students who are first in the lunch line', NULL, 'Students who are first in the lunch line are probably the ones who prefer an early lunch, so the sample leaves out other students'' opinions. The other plans give every student a fair chance of being asked.', 'checked', '{"lint":[],"solve":{"answer":"Ask only the students who are first in the lunch line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B, C, D are systematic/random. First students in the lunch line are a convenience group (e.g. hungriest or earliest), likely biased: A.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca4914bf-18fe-4599-95b9-96eb7c8b1361', 'NC26.6.RD.2', 2, 'numeric', 'Spotting a biased way of choosing a sample', 'A school has 400 students, and 90 of them ride a bus. Pablo surveys only the students waiting at the bus stop. What fraction of the school''s students could possibly be in his sample? Write your answer as a fraction.', '[]', '9/40', '90/400', 'Only the 90 bus riders can be in the sample. The fraction is $\frac{90}{400} = \frac{9}{40}$, so most students have no chance of being asked.', 'checked', '{"lint":[],"solve":{"answer":"9/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only bus riders wait at the bus stop: 90 of 400. 90/400 = 9/40.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3efd1a70-feec-4d80-a433-7610022d4a70', 'NC26.6.RD.2', 2, 'numeric', 'Choosing a representative or random sample', 'A school has 300 sixth graders, 200 seventh graders and 100 eighth graders. The principal wants a sample of 60 students whose grades match the school''s. How many of the 60 should be sixth graders?', '[]', '30', '300/600*60', 'The school has $300 + 200 + 100 = 600$ students, and sixth graders are $\frac{300}{600} = \frac{1}{2}$ of them. Half of the 60 students in the sample should be sixth graders: $\frac{1}{2} \times 60 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 300 + 200 + 100 = 600. Sixth graders are 300/600 = 1/2, so 1/2 x 60 = 30.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a35fad0-9796-4f8a-aaa6-6fdc68c4c712', 'NC26.6.RD.2', 2, 'numeric', 'Sample size and the share of the population asked', 'A club has 80 members. A sample must include at least 10% of the members. What is the smallest number of members that can be in the sample?', '[]', '8', '0.1*80', '10% of 80 is $0.1 \times 80 = 8$, so the sample needs at least 8 members.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% of 80 = 8; the sample must be at least 8, so the smallest is 8.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
