INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f085755-77bd-4ab0-8a9a-e1af990c0b9d', 'NC26.6.RD.3', 1, 'numeric', 'Finding the five key values of a data set', 'Kai records the number of push-ups he does on five days: 14, 9, 12, 20, 11. What is the median?', '[]', '12', '12', 'Put the numbers in order: 9, 11, 12, 14, 20. The middle one, the 3rd, is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 9, 11, 12, 14, 20: median 12.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
