INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be8a6b7b-f9c2-441f-8d67-26c920e0833d', 'NC26.6.RD.4', 1, 'choice', 'How adding, removing or changing a value affects the mean and median', 'Priya''s quiz scores are 7, 8 and 9, and her mean is 8. On her next quiz she scores 10. What happens to her mean?', '["It goes down","It stays the same","It becomes 10","It goes up"]', 'It goes up', NULL, 'The new score of 10 is greater than the old mean of 8, so it pulls the mean up. The new mean is $(7 + 8 + 9 + 10) \div 4 = 8.5$.', 'checked', '{"lint":[],"solve":{"answer":"It goes up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New total 34 over 4 = 8.5 > 8, so it goes up.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0e0f51b-c2dc-4a68-b3a4-48887997375d', 'NC26.6.RD.4', 1, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'Every value in a data set is increased by 5. The mean of the old data set was 12. What is the mean of the new data set?', '[]', '17', '12+5', 'Adding 5 to every value moves the balance point up by 5 too, so the new mean is $12 + 5 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 5 to every value adds 5 to the mean: 17.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f8ee56b-069f-4d41-853d-c2a784bd79d8', 'NC26.6.RD.4', 1, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'The median of the five ages 14, 18, 21, 25 and 32 is 21. If the 32 is changed to 90, what is the new median?', '[]', '21', '21', 'The middle value is still the 3rd one in order, 21. Changing the greatest value does not change which value is in the middle, so the median stays 21.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14, 18, 21, 25, 90: middle still 21.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b3d46ec-8661-472a-89cf-12a4ec44eaca', 'NC26.6.RD.4', 1, 'numeric', 'Comparing the variability of two data sets', 'A data set is 12, 18, 7, 25 and 14. What is its range?', '[]', '18', '25-7', 'The range is the greatest value minus the least value: $25 - 7 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 25, min 7; range 18.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
