INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1194bb6-0b12-49da-8056-32cd8e4aa974', 'NC26.6.RD.4', 2, 'numeric', 'Finding a mean', 'Over one week, Mei counted her steps each day. In thousands of steps, the counts were 8, 6, 9, 7, 10, 8 and 8. What was the mean number of steps per day, in thousands?', '[]', '8', '(8+6+9+7+10+8+8)/7', 'The counts add up to $8+6+9+7+10+8+8 = 56$ thousand steps over 7 days. The mean is $56 \div 7 = 8$ thousand steps.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8+6+9+7+10+8+8 = 56; 56/7 = 8.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
