INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6890483-ce05-4b16-9e23-db8de404a604', 'NC26.6.RD.4', 2, 'choice', 'Finding a mean', 'Which data set has a mean of 9?', '["6, 8, 10, 13","4, 7, 9, 14","7, 9, 11, 12","5, 7, 10, 14"]', '5, 7, 10, 14', NULL, 'A mean of 9 with 4 values means a total of 36. $5+7+10+14 = 36$. The other sets add up to 37, 34 and 39.', 'checked', '{"lint":[],"solve":{"answer":"5, 7, 10, 14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need sum 36. Sums: 39, 36, 37, 34. Only 5, 7, 10, 14.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
