INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3632621c-81fc-4190-a599-78ec01e65c76', 'NC26.6.RD.4', 2, 'numeric', 'Finding a median', 'Six students counted the pencils in their cases: 9, 4, 12, 7, 15 and 6. What is the median number of pencils?', '[]', '8', '(7+9)/2', 'Put the counts in order: 4, 6, 7, 9, 12, 15. With 6 values, the median is halfway between the 3rd and 4th values, 7 and 9: $(7 + 9) \div 2 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order: 4, 6, 7, 9, 12, 15. Median (7+9)/2 = 8.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
