INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('737843b6-8ae1-490a-ae76-a57263d7d352', 'NC26.6.RD.4', 2, 'numeric', 'Finding a median', 'A cafe counted its customers each hour: 12, 18, 15, 22, 18, 9 and 25. What is the median number of customers per hour?', '[]', '18', '18', 'In order, the counts are 9, 12, 15, 18, 18, 22, 25. With 7 values, the median is the 4th value, 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order: 9,12,15,18,18,22,25. 4th value 18.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
