INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca97e743-5fa7-4f9f-833d-c97b88341009', 'NC26.6.RD.4', 2, 'numeric', 'Using a mean to find a missing value or a total', 'The mean of four numbers is 15. One of the numbers is 24, and the other three are all equal. What is each of the three equal numbers?', '[]', '12', '(4*15-24)/3', 'Four numbers with a mean of 15 add up to $4 \times 15 = 60$. Without the 24, the other three add up to $60 - 24 = 36$, so each is $36 \div 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 60; 60-24 = 36; 36/3 = 12.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
