INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ca6143d-d603-4931-bc75-30409b9e5dd6', 'NC26.6.RD.4', 2, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'The mean of five numbers is 8. Every number is doubled. What is the mean of the new numbers?', '[]', '16', '8*2', 'Doubling every number doubles their total and so doubles the mean: $8 \times 2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling every value doubles the total and the mean: 16.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
