INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99dabb3c-9a87-4abf-b5f7-bc6528806d31', 'NC26.6.RD.4', 2, 'choice', 'How adding, removing or changing a value affects the mean and median', 'The numbers 4, 6, 8, 10 and 12 have a mean of 8. The 12 is changed to 27. What is the new mean?', '["8","23","11","13.75"]', '11', '(4+6+8+10+27)/5', 'The new numbers 4, 6, 8, 10 and 27 add up to 55, and $55 \div 5 = 11$. (The total went up by $27 - 12 = 15$, so the mean went up by $15 \div 5 = 3$.)', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old total 40; +15 gives 55; 55/5 = 11.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
