INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d78955d8-4578-443e-8691-e5f17e6193a8', 'NC26.6.RD.4', 2, 'choice', 'How adding, removing or changing a value affects the mean and median', 'A data set is 6, 7, 8, 9 and 10. The value 40 is added to the set. Which statement is true?', '["The mean goes up by more than the median does","The median goes up by more than the mean does","The mean and the median both stay the same","The mean and the median go up by the same amount"]', 'The mean goes up by more than the median does', NULL, 'Before: the mean is 8 and the median is 8. After: the mean is $80 \div 6 \approx 13.3$ and the median is $(8 + 9) \div 2 = 8.5$. The mean rose by about 5.3, but the median rose by only 0.5.', 'checked', '{"lint":[],"solve":{"answer":"The mean goes up by more than the median does","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old mean 8, median 8. New: total 80/6 = 13.33 (up 5.33); median (8+9)/2 = 8.5 (up 0.5). Mean rises more.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8faec7dc-d346-4b4b-9942-42fc0f67c06a', 'NC26.6.RD.4', 2, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'The ages of five aunts and uncles are 30, 34, 38, 41 and 45. A sixth relative who is 52 years old joins the list. What is the median age of the six?', '[]', '39.5', '(38+41)/2', 'The six ages in order are 30, 34, 38, 41, 45, 52. The median is halfway between the 3rd and 4th values, 38 and 41: $(38 + 41) \div 2 = 39.5$.', 'checked', '{"lint":[],"solve":{"answer":"39.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30, 34, 38, 41, 45, 52: median (38+41)/2 = 39.5.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
