INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('478ef43a-67e4-45e1-bf67-9c80fdeac2e1', 'NC26.6.RD.4', 2, 'numeric', 'Comparing the variability of two data sets', 'Data set P is 14, 18, 22, 25, 31. Data set Q is 20, 22, 25, 27, 29. How many units greater is the range of P than the range of Q?', '[]', '8', '(31-14)-(29-20)', 'The range of P is $31 - 14 = 17$. The range of Q is $29 - 20 = 9$. The difference is $17 - 9 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 31-14 = 17; range Q = 29-20 = 9; difference 8.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
