INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d52d2f5-5f12-4841-942a-27e60e5f3f63', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'The yearly pay of seven workers at a shop, in thousands of dollars, is 28, 30, 30, 32, 33, 35 and 150. The mean is about 48 and the median is 32. Which statement is best?', '["The median is better, because the 150 pulls the mean far above the pay of most workers","The mean is better, because it uses every value and is the greater number","The mean and the median describe a typical pay equally well","Neither is useful, because the seven pay values are different"]', 'The median is better, because the 150 pulls the mean far above the pay of most workers', NULL, 'Six of the seven workers earn between 28 and 35 thousand dollars, so a typical pay is about 32. The one pay of 150 pulls the mean up to about 48, which is higher than what any of those six earn.', 'checked', '{"lint":[],"solve":{"answer":"The median is better, because the 150 pulls the mean far above the pay of most workers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 338/7 = 48.3 (about 48); median 32. The 150 is an outlier pulling the mean above 6 of 7 workers, so the median is better.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3c4b93-7a11-41dd-a0a6-516ac2a0a8ce', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'For which data set is the median a better description of the center than the mean?', '["10, 11, 12, 13, 14","5, 6, 7, 8, 9","3, 4, 4, 5, 90","21, 22, 22, 23, 24"]', '3, 4, 4, 5, 90', NULL, 'In the first set the value 90 is far from the others, so the mean (21.2) is higher than four of the five values, while the median (4) is typical. The other sets have values close together, so the mean and the median agree.', 'checked', '{"lint":[],"solve":{"answer":"3, 4, 4, 5, 90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 3, 4, 4, 5, 90 has an outlier (mean 21.2 vs median 4). Others are symmetric, mean = median.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('298ad5ba-8db5-4a54-947d-8d6edd84a70a', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'A student''s five math quiz scores are 40, 78, 80, 82 and 85. The mean is 73 and the median is 80. Which measure better describes this student''s typical score, and why?', '["The mean of 73, because it is the middle score when the scores are in order","The median of 80, because the one very low score of 40 pulls the mean below the other four scores","The median of 80, because it is the total of all five scores divided by 5","The mean of 73, because it is higher than most of the five scores"]', 'The median of 80, because the one very low score of 40 pulls the mean below the other four scores', NULL, 'Four of the five scores are between 78 and 85, so a typical score is about 80. The very low score of 40 pulls the mean down to 73, which is below four of the five scores. The median is the middle score; the mean is the total divided by 5.', 'checked', '{"lint":[],"solve":{"answer":"The median of 80, because the one very low score of 40 pulls the mean below the other four scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 365/5 = 73, median 80. Outlier 40 pulls mean below the other four scores (78,80,82,85); median is typical.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3312d8f3-1946-4d39-8266-ba5d03423090', 'NC26.6.RD.4', 3, 'numeric', 'How adding a value changes a mean', 'The mean of 5 numbers is 20. A sixth number, 32, is added to the set. What is the mean of all 6 numbers?', '[]', '22', '(5*20+32)/6', 'The first 5 numbers add to $5 \times 20 = 100$. With 32 added the total is $132$ for 6 numbers, and $132 \div 6 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of 5 = 100. Add 32: 132. Mean = 132 / 6 = 22.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1524faa6-be56-41e4-9b6e-37a7c2098710', 'NC26.6.RD.4', 3, 'numeric', 'How an outlier changes the mean', 'A data set is 4, 5, 6, 7 and 8. The 8 is changed to 38. By how much does the mean increase?', '[]', '6', '(4+5+6+7+38)/5-(4+5+6+7+8)/5', 'The original total is $30$, so the mean is $30 \div 5 = 6$. The new total is $60$, so the new mean is $60 \div 5 = 12$. The mean increases by $12 - 6 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum rises by 38 - 8 = 30; mean rises by 30 / 5 = 6 (from 6 to 12).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f174fcfc-0ec6-4670-bf94-864497c47c36', 'NC26.6.RD.4', 3, 'choice', 'Building a data set with a given mean and median', 'Which set of numbers has a mean of 10 and a median of 8?', '["$8, 8, 9, 12, 13$","$5, 8, 10, 13, 14$","$4, 6, 8, 9, 10$","$6, 8, 8, 12, 16$"]', '$6, 8, 8, 12, 16$', NULL, 'For $6, 8, 8, 12, 16$: the total is 50, so the mean is $50 \div 5 = 10$, and the middle number is 8. The set $8, 8, 9, 12, 13$ has mean 10 but median 9; $5, 8, 10, 13, 14$ has mean 10 but median 10; and $4, 6, 8, 9, 10$ has median 8 but a mean of 7.4.', 'checked', '{"lint":[],"solve":{"answer":"$6, 8, 8, 12, 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 50, mean 10, median 9. B: sum 50, mean 10, median 10. C: sum 37, mean 7.4. D: 6+8+8+12+16 = 50, mean 10, median 8. Only D.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82292d27-c853-4295-8a87-b82946b37249', 'NC26.6.RD.4', 3, 'choice', 'The mean as a balance point or fair share', 'Five values have a mean of 30. Four of them are 4 below the mean, 7 below the mean, 6 above the mean and 3 above the mean. Where is the fifth value?', '["2 below the mean","At the mean","2 above the mean","9 above the mean"]', '2 above the mean', NULL, 'The distances must balance. Below the mean: $4 + 7 = 11$. Above the mean so far: $6 + 3 = 9$. The fifth value must add $11 - 9 = 2$ more on the above side, so it is 2 above the mean (the value 32).', 'checked', '{"lint":[],"solve":{"answer":"2 above the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations must sum to 0: -4 -7 +6 +3 = -2, so the fifth deviation is +2: 2 above the mean (value 32).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
