INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9180bc88-a176-4470-b8b5-9625fe669041', 'NC26.6.RD.5', 1, 'choice', 'Drawing an inference from the center of a data set', 'Dev''s mean time for one lap of the track was 100 seconds last week and 90 seconds this week. What can Dev conclude?', '["Every lap was faster this week than last week","His laps were faster, on average, this week","His laps were slower, on average, this week","He ran fewer laps this week than last week"]', 'His laps were faster, on average, this week', NULL, 'A smaller mean time means faster laps on average, so his laps were faster on average this week. A mean cannot show that every single lap was faster, and it says nothing about how many laps he ran.', 'checked', '{"lint":[],"solve":{"answer":"His laps were faster, on average, this week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower mean lap time (90 < 100) means faster on average; not every lap, and nothing about number of laps.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3b8323b-7946-4f5c-a46b-9e9edec2e7b1', 'NC26.6.RD.5', 1, 'numeric', 'Drawing an inference from the center of a data set', 'The median age of the 9 players on a team is 12. At least how many of the players are 12 years old or older?', '[]', '5', '(9+1)/2', 'The median of 9 ordered values is the 5th value, and the 5th through 9th values are all at least as large as the median. So at least $(9 + 1) \div 2 = 5$ players are 12 or older.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 ordered ages: median is the 5th = 12, so the 5th through 9th are at least 12: at least 5 players.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('364e64c4-46f4-4d13-b566-a64d10f8c6e1', 'NC26.6.RD.5', 1, 'numeric', 'Drawing an inference from variability', 'Two swimmers each swam three races. Swimmer 1''s times were 9, 10 and 11 seconds. Swimmer 2''s times were 4, 10 and 16 seconds. How many seconds greater is the range of Swimmer 2''s times than the range of Swimmer 1''s times?', '[]', '10', '(16-4)-(11-9)', 'Swimmer 1''s range is $11 - 9 = 2$. Swimmer 2''s range is $16 - 4 = 12$. The difference is $12 - 2 = 10$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range 1: 11-9 = 2; range 2: 16-4 = 12; difference 10.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c47b6e7-1aac-4fcc-b894-1cd57e069e7c', 'NC26.6.RD.5', 1, 'numeric', 'Summarizing a distribution with center, spread and unusual values', 'A report says, "The 15 puppies weighed between 8 and 29 pounds, with a median of 15 pounds." What is the range of the puppies'' weights, in pounds?', '[]', '21', '29-8', 'The range is the greatest value minus the least value: $29 - 8 = 21$ pounds. The median is not needed.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29 - 8 = 21.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
