INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41a90414-7701-4bc7-a878-c5cd2e0aa3e0', 'NC26.6.RD.5', 1, 'choice', 'Summarizing a distribution with center, spread and unusual values', 'Which pair of measures gives both a center and a spread of a data set?', '["The mean and the median","The range and the IQR","The least value and the greatest value","The median and the range"]', 'The median and the range', NULL, 'The median tells the center and the range tells the spread. The mean and the median are both centers, the range and the IQR are both spreads, and the least and greatest values describe only the spread.', 'checked', '{"lint":[],"solve":{"answer":"The median and the range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median is a centre, range a spread. Others: two extremes, two centres, two spreads.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c027424-9c08-435d-b446-7eaa25f8aac8', 'NC26.6.RD.5', 1, 'numeric', 'Summarizing a distribution with center, spread and unusual values', 'Zoe says that the typical number of siblings is the median. She asked seven classmates and got 0, 1, 1, 2, 2, 2 and 3. What typical number of siblings should she report?', '[]', '2', '2', 'The values are in order and there are 7 of them, so the median is the 4th value, which is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 ordered values; 4th = 2.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
