INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d65d15c-d881-4a5d-84c5-1d0c2c33d168', 'NC26.6.RD.5', 1, 'numeric', 'Describing clusters, gaps and outliers of a data set', 'Eight values are 10, 11, 11, 12, 12, 13, 25 and 26. There is a gap in the data between 13 and 25. How many of the values are 13 or less?', '[]', '6', '8-2', 'The values 10, 11, 11, 12, 12 and 13 are on the lower side of the gap, which is 6 values. The other 2 values, 25 and 26, are on the upper side.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10, 11, 11, 12, 12, 13: 6 values.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
