INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('624b0c9c-6b9a-47bd-8718-76eb3d935185', 'NC26.6.RD.5', 1, 'numeric', 'Describing clusters, gaps and outliers of a data set', 'Nine students slept 5, 6, 6, 7, 7, 7, 8, 8 and 9 hours. How many of the nine students slept within 1 hour of 7 hours, that is, from 6 hours to 8 hours?', '[]', '7', '9-2', 'The students who slept 6, 6, 7, 7, 7, 8 or 8 hours are within 1 hour of 7, which is 7 students. Only the 5 and the 9 are farther away.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,6,7,7,7,8,8 are within 6-8: 7 students.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
