INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e6704b0-1df5-480f-a46e-4b4f941c6e5f', 'NC26.6.RD.5', 1, 'numeric', 'Reflecting on the question and the methods of an investigation', 'A student stands at the school door and surveys every 5th student who walks out. A total of 100 students walk out. How many students does she survey?', '[]', '20', '100/5', 'Every 5th student means 1 student out of every 5, so she surveys $100 \div 5 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students 5, 10, ..., 100: 100/5 = 20.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
