INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae3ba5b4-a00c-4684-b3cf-c5f6cc68a41a', 'NC26.6.RD.5', 1, 'numeric', 'Calculating the summary an investigation needs', 'Eight students each recorded how many pieces of fruit they ate yesterday, and the mean was 5. How many pieces of fruit did the 8 students eat in all?', '[]', '40', '8*5', 'Total = mean $\times$ number of students $= 8 \times 5 = 40$ pieces of fruit.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 * 5 = 40.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
