INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f2909a8-5414-4cfe-a31a-b04654dd05f6', 'NC26.7.RPR.1', 1, 'choice', 'What stays constant in a proportional relationship', 'In a proportional relationship, the value of $x$ is doubled. What happens to $y$?', '["$y$ is doubled","$y$ is increased by 2","$y$ stays the same","$y$ is cut in half"]', '$y$ is doubled', NULL, 'In a proportional relationship $y$ is always the same multiple of $x$. If $x$ is doubled, then $y$ is doubled too.', 'checked', '{"lint":[],"solve":{"answer":"$y$ is doubled","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = kx, so 2x gives 2kx = 2y: y doubles.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c79291e-85a6-4ce2-9720-f8d5804075e4', 'NC26.7.RPR.1', 1, 'numeric', 'What stays constant in a proportional relationship', 'In a proportional relationship, $y = 4$ when $x = 3$. What is $y$ when $x = 9$?', '[]', '12', '4/3*9', '$x$ goes from 3 to 9, which is 3 times as much, so $y$ is 3 times as much: $4 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x goes 3 to 9 (times 3), so y goes 4 to 12. k = 4/3, 9 x 4/3 = 12.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a354274-7a20-4988-8613-4b0b869f1faa', 'NC26.7.RPR.1', 1, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table shows the cost of tickets: 3 tickets cost 12 dollars, 5 tickets cost 20 dollars and 8 tickets cost 32 dollars. The cost is proportional to the number of tickets. What is the constant of proportionality, in dollars per ticket?', '[]', '4', '12/3', 'Divide the cost by the number of tickets: $12 \div 3 = 4$. Check: $20 \div 5 = 4$ and $32 \div 8 = 4$. The constant of proportionality is 4 dollars per ticket.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/3 = 20/5 = 32/8 = 4 dollars per ticket.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('133af7cd-3c7b-413b-934b-0b4e1b7e120a', 'NC26.7.RPR.1', 1, 'choice', 'Constant of proportionality from a table or ordered pairs', 'The pairs $(x, y)$ of a proportional relationship are $(4, 6)$, $(8, 12)$ and $(10, 15)$. The constant of proportionality is the number $k$ in $y = kx$. What is $k$?', '["$\\frac{2}{3}$","$\\frac{3}{2}$","$2$","$6$"]', '$\frac{3}{2}$', NULL, '$k = y \div x = 6 \div 4 = \frac{3}{2}$. Check with $12 \div 8$ and $15 \div 10$, which are also $\frac{3}{2}$. ($\frac{2}{3}$ is $x \div y$, and 2 is $y - x$ for the first pair.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 6/4 = 12/8 = 15/10 = 3/2.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('374c1679-f2b2-4ca0-8c63-e3342f8a5381', 'NC26.7.RPR.1', 1, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A proportional relationship includes the point $(5, 35)$. In $y = kx$, what is the value of $k$?', '[]', '7', '35/5', 'Since $y = kx$, $k = y \div x = 35 \div 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 35/5 = 7.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
