INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b854fd1c-221c-426e-9d63-ab763847a2e8', 'NC26.7.RPR.1', 1, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table of a proportional relationship lists $x$ = 10, 20 and 30, with $y$ = 4, 8 and 12. What is the constant of proportionality of $y$ to $x$?', '[]', '0.4', '4/10', '$k = y \div x = 4 \div 10 = 0.4$. Check: $8 \div 20 = 0.4$ and $12 \div 30 = 0.4$.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 4/10 = 8/20 = 12/30 = 0.4.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
