INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2ef5185-a732-4fcf-98df-8705a4e04152', 'NC26.7.RPR.1', 1, 'choice', 'Constant of proportionality from a table or ordered pairs', 'Omar works 2, 4 and 6 hours and earns 30, 60 and 90 dollars. The pay is proportional to the hours. What is the constant of proportionality of pay to hours?', '["$28$","$30$","$\\frac{1}{15}$","$15$"]', '$15$', '30/2', 'Pay divided by hours: $30 \div 2 = 15$, $60 \div 4 = 15$ and $90 \div 6 = 15$. The constant is 15 dollars per hour. ($\frac{1}{15}$ is hours divided by pay.)', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pay/hours = 30/2 = 60/4 = 90/6 = 15.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
