INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8fb73cb-41aa-4218-b053-9a3de8d743c3', 'NC26.7.RPR.1', 1, 'numeric', 'Unit rate with fractions', 'A printer prints 12 pages in $\frac{1}{3}$ of a minute. How many pages does it print in 1 minute?', '[]', '36', '12/(1/3)', 'In 1 minute there are 3 thirds of a minute, so the printer prints $12 \times 3 = 36$ pages. (This is $12 \div \frac{1}{3} = 36$.)', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / (1/3) = 36 pages per minute.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
