INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f34ebd1c-8eae-4632-b29c-18a9f0abdb46', 'NC26.7.RPR.1', 1, 'numeric', 'Unit rate with fractions', 'A pipe fills $\frac{1}{2}$ of a bucket in 2 minutes. What fraction of the bucket does it fill in 1 minute?', '[]', '1/4', '(1/2)/2', 'In 1 minute it fills half as much as in 2 minutes: $\frac{1}{2} \div 2 = \frac{1}{4}$ of the bucket.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)/2 = 1/4 of the bucket per minute.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
