INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66fee1fc-7521-4037-8132-163af604fc32', 'NC26.7.RPR.1', 1, 'choice', 'Unit rate with fractions', 'A runner covers $\frac{1}{4}$ mile in 2 minutes. Which expression gives the number of miles the runner covers in 1 minute?', '["$2 \\div \\frac{1}{4}$","$\\frac{1}{4} \\div 2$","$\\frac{1}{4} \\times 2$","$2 - \\frac{1}{4}$"]', '$\frac{1}{4} \div 2$', NULL, 'The unit rate is miles divided by minutes: $\frac{1}{4} \div 2 = \frac{1}{8}$ mile per minute. ($2 \div \frac{1}{4}$ would be minutes per mile.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4} \\div 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Miles per minute = miles / minutes = (1/4) / 2 = 1/8.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
