INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4380ec84-386d-436a-b5c9-0ebfefa487ca', 'NC26.7.RPR.1', 1, 'choice', 'Unit rate with fractions', 'A recipe uses $\frac{3}{4}$ cup of sugar to make 3 cakes. How much sugar is used for 1 cake?', '["$\\frac{1}{4}$ cup","$\\frac{3}{4}$ cup","$\\frac{9}{4}$ cups","4 cups"]', '$\frac{1}{4}$ cup', NULL, 'Share the sugar among the 3 cakes: $\frac{3}{4} \div 3 = \frac{1}{4}$ cup for each cake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$ cup","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4) / 3 = 1/4 cup per cake.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
