INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0adceb1f-9c5c-4256-8e75-8325972d1fba', 'NC26.7.RPR.1', 1, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(3, 12)$ is on the graph of a proportional relationship between the hours $x$ Kim works and the dollars $y$ she earns. What does the point mean?', '["In 12 hours, Kim earns 3 dollars","In 3 hours, Kim earns 12 dollars","Kim earns 12 dollars each hour","Kim earns 3 dollars each hour"]', 'In 3 hours, Kim earns 12 dollars', NULL, 'A point $(x, y)$ means $x$ hours go with $y$ dollars, so $(3, 12)$ means 3 hours earn 12 dollars. That is $12 \div 3 = 4$ dollars for each hour.', 'checked', '{"lint":[],"solve":{"answer":"In 3 hours, Kim earns 12 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) = (3 hours, 12 dollars): in 3 hours she earns 12 dollars (rate 4 per hour, so the 3 and 12 per hour options are wrong).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17999180-15fa-4e93-ad72-c0218c2a48e8', 'NC26.7.RPR.1', 1, 'numeric', 'Interpret a point of a proportional relationship in context', 'The graph of a proportional relationship between the pounds of grapes $x$ and the cost $y$ in dollars passes through the point $(1, 3.25)$. What is the cost, in dollars, of 4 pounds of grapes?', '[]', '13', '3.25*4', 'The point $(1, 3.25)$ says 1 pound costs 3.25 dollars. For 4 pounds the cost is $3.25 \times 4 = 13$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit rate 3.25 dollars per pound; 4 x 3.25 = 13.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('305e16da-6226-40c8-98e0-1367fc1e7c49', 'NC26.7.RPR.1', 1, 'choice', 'Interpret a point of a proportional relationship in context', 'The graph of a proportional relationship between the hours $x$ spent walking and the miles $y$ walked passes through the point $(0, 0)$. What does that point mean?', '["After 0 hours, 0 miles have been walked","The walker walks 0 miles every hour","The walk lasts 0 hours","The walker is 0 miles from home at all times"]', 'After 0 hours, 0 miles have been walked', NULL, 'The point $(0, 0)$ means that when $x = 0$ hours, $y = 0$ miles. Before any time has passed, no distance has been walked.', 'checked', '{"lint":[],"solve":{"answer":"After 0 hours, 0 miles have been walked","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0, 0) = 0 hours, 0 miles: before any walking, no distance covered.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3c8a014-c334-497f-a6bc-f1b43c7a52b8', 'NC26.7.RPR.1', 1, 'numeric', 'Interpret a point of a proportional relationship in context', 'A proportional relationship between the number of packs $x$ and the number of pens $y$ includes the point $(2, 14)$. How many pens are in 5 packs?', '[]', '35', '14/2*5', 'The point $(2, 14)$ says 2 packs have 14 pens, so 1 pack has $14 \div 2 = 7$ pens. Five packs have $7 \times 5 = 35$ pens.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/2 = 7 pens per pack; 5 x 7 = 35.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8490ee53-7b54-4ed0-a67f-4e567eb0bfac', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate from two fractional quantities', 'Ben reads $\frac{3}{4}$ of a chapter in $\frac{1}{2}$ hour. At this rate, how many chapters does he read in 1 hour?', '[]', '3/2', '(3/4)/(1/2)', 'The unit rate is $\frac{3}{4} \div \frac{1}{2} = \frac{3}{4} \times 2 = \frac{3}{2}$, which is $1\frac{1}{2}$ chapters per hour.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4) / (1/2) = 3/4 x 2 = 3/2 = 1.5 chapters per hour.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6b29c43-f5f4-4c38-963b-4c1003b70a48', 'NC26.7.RPR.1', 2, 'choice', 'Write an equation y = kx for a proportional situation', 'Ribbon is sold at a constant price per meter. 4 meters cost 10 dollars. Which equation gives the cost $y$, in dollars, of $x$ meters of ribbon?', '["$y = 4x$","$y = x + 6$","$y = 0.4x$","$y = 2.5x$"]', '$y = 2.5x$', NULL, 'The price for 1 meter is $10 \div 4 = 2.5$ dollars, so $k = 2.5$ and $y = 2.5x$. Check: $x = 4$ gives $y = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2.5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit price = 10/4 = 2.5 dollars per meter, proportional, so y = 2.5x. Check: 2.5 x 4 = 10.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c0ec78d-9909-43ad-ba3b-129d682ba211', 'NC26.7.RPR.1', 2, 'numeric', 'Interpret a point on a proportional relationship in context', 'A proportional relationship between hours worked $x$ and pay $y$, in dollars, includes the point $(4, 52)$. How many dollars is the pay for 1 hour of work?', '[]', '13', '52/4', 'The point $(4, 52)$ means 4 hours earn 52 dollars. The pay for 1 hour is the unit rate $52 \div 4 = 13$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 52/4 = 13 dollars per hour.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d6e53dc-c9bc-46ee-a1c8-02365d239fb5', 'NC26.7.RPR.1', 2, 'choice', 'What stays constant in a proportional relationship', 'Dana bikes at a constant speed. Her distance $d$, in miles, after $t$ hours is $d = 12t$. Which statement is true?', '["She bikes for 12 hours in all","She bikes 12 miles in all","She bikes 12 miles each hour","She starts 12 miles from home"]', 'She bikes 12 miles each hour', NULL, 'In $d = 12t$ the distance is 12 times the time, so the number 12 is the miles she bikes in each hour. It does not tell how long she bikes in all or where she starts.', 'checked', '{"lint":[],"solve":{"answer":"She bikes 12 miles each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 12t: the rate is 12 miles per hour. Time and total distance are not given; d = 0 at t = 0, so she starts at home.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c6d0d45-a3d0-4647-a0bd-ea6a842d9ef8', 'NC26.7.RPR.1', 2, 'numeric', 'What stays constant in a proportional relationship', 'In a proportional relationship, $y \div x$ is the same for every pair. One pair is $(6, 15)$ and another pair is $(10, y)$. What is $y$?', '[]', '25', '15/6*10', '$y \div x = 15 \div 6 = 2.5$ for every pair. So $y = 2.5 \times 10 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 15/6 = 2.5; y = 2.5 x 10 = 25.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d27906c9-65ea-432b-a693-896e97034a88', 'NC26.7.RPR.1', 2, 'choice', 'What stays constant in a proportional relationship', 'Which statement is true for every proportional relationship between $x$ and $y$?', '["$y - x$ is the same for every pair","$y \\div x$ is the same for every pair","$y$ is always greater than $x$","$x$ is always a factor of $y$"]', '$y \div x$ is the same for every pair', NULL, 'The quotient $y \div x$ is the constant of proportionality, so it is the same for every pair. The difference $y - x$ changes, $y$ can be less than $x$ (for example $y = 0.5x$), and $x$ need not divide $y$ (for example $y = 1.5x$).', 'checked', '{"lint":[],"solve":{"answer":"$y \\div x$ is the same for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Proportional means y = kx, so y/x = k for every pair (x not 0). Differences vary; x need not be a factor; k < 1 makes y < x.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b74e5379-4a11-4bc3-98d9-4e893e95a028', 'NC26.7.RPR.1', 2, 'numeric', 'What stays constant in a proportional relationship', 'Gasoline costs the same amount for each gallon. 6 gallons cost 21 dollars. How many dollars do 10 gallons cost?', '[]', '35', '21/6*10', 'One gallon costs $21 \div 6 = 3.5$ dollars. Ten gallons cost $3.5 \times 10 = 35$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21/6 = 3.5 dollars per gallon; 10 x 3.5 = 35.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66bbe301-a8a1-4718-ba8e-8564b22af9d5', 'NC26.7.RPR.1', 2, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'In a proportional relationship, $y = 10$ when $x = 3$, $y = 20$ when $x = 6$ and $y = 30$ when $x = 9$. What is the constant of proportionality $k$ in $y = kx$? Give it as a fraction.', '[]', '10/3', '10/3', '$k = y \div x = 10 \div 3 = \frac{10}{3}$. Check: $20 \div 6 = \frac{10}{3}$ and $30 \div 9 = \frac{10}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"10/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 10/3 = 20/6 = 30/9 = 10/3.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1f19890-7819-4d16-8088-833b20752925', 'NC26.7.RPR.1', 2, 'choice', 'Constant of proportionality from a table or ordered pairs', 'Which set of pairs $(x, y)$ shows a proportional relationship with a constant of proportionality of 2.5?', '["$(2, 4.5)$, $(4, 6.5)$, $(6, 8.5)$","$(5, 2)$, $(10, 4)$, $(15, 6)$","$(2, 5)$, $(4, 10)$, $(6, 14)$","$(2, 5)$, $(4, 10)$, $(6, 15)$"]', '$(2, 5)$, $(4, 10)$, $(6, 15)$', NULL, 'Check $y \div x$ for each pair. In the first set it is $5 \div 2$, $10 \div 4$ and $15 \div 6$, all 2.5. The second set always has $y = x + 2.5$, the third has a constant of 0.4, and in the fourth $14 \div 6$ is not 2.5.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$, $(4, 10)$, $(6, 15)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need y/x = 2.5 for all. A: 2.25, 1.625 no. B: 0.4 no. C: 5/2, 10/4, 15/6 all 2.5 yes. D: 14/6 not 2.5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b6c2137-8961-44e3-a390-a65eb382d2fa', 'NC26.7.RPR.1', 2, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'In a proportional relationship, $y = 28$ when $x = 8$, and $y = 42$ when $x = 12$. What is the constant of proportionality?', '[]', '3.5', '28/8', '$k = 28 \div 8 = 3.5$. Check: $42 \div 12 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28/8 = 3.5, 42/12 = 3.5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9e6991a-4e8a-4cf5-aebd-1ae7cb9c7101', 'NC26.7.RPR.1', 2, 'choice', 'Constant of proportionality from a table or ordered pairs', 'Omar reads 6 pages in 15 minutes, 12 pages in 30 minutes and 18 pages in 45 minutes. The pages are proportional to the minutes. What is the constant of proportionality of pages to minutes?', '["0.4","2.5","9","21"]', '0.4', '6/15', 'Pages divided by minutes: $6 \div 15 = 0.4$, $12 \div 30 = 0.4$ and $18 \div 45 = 0.4$. (2.5 is minutes divided by pages, 9 is $15 - 6$, and 21 is $15 + 6$.)', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pages = k x minutes: k = 6/15 = 12/30 = 18/45 = 0.4 pages per minute. (2.5 is minutes per page, the reverse.) Same ''of y to x'' convention as Q16/Q17.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8128e5f4-d16a-444f-b581-6ed9aff95748', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', 'A hiker walks $1\frac{1}{2}$ miles in $\frac{3}{4}$ of an hour at a steady pace. How many miles does the hiker walk in 1 hour?', '[]', '2', '1.5/0.75', 'Unit rate = miles divided by hours = $1\frac{1}{2} \div \frac{3}{4} = \frac{3}{2} \times \frac{4}{3} = 2$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/2) / (3/4) = (3/2)(4/3) = 2 miles per hour.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d60e4993-33a7-4bb3-b22b-8f5b887379be', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', 'A recipe uses $\frac{2}{3}$ cup of oil for every $\frac{1}{2}$ of a batch. How many cups of oil are needed for 1 whole batch?', '[]', '4/3', '(2/3)/(1/2)', '$\frac{2}{3} \div \frac{1}{2} = \frac{2}{3} \times 2 = \frac{4}{3}$ cups, which is $1\frac{1}{3}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3) / (1/2) = 4/3 cups per batch.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da34cb50-8859-4b67-9e41-1c762c0d3ab7', 'NC26.7.RPR.1', 2, 'choice', 'Unit rate with fractions', 'A painter covers $\frac{2}{3}$ of a wall with $\frac{1}{4}$ gallon of paint. How many walls can be covered with 1 gallon of paint?', '["$\\frac{3}{8}$","$\\frac{8}{3}$","$\\frac{1}{6}$","$\\frac{11}{12}$"]', '$\frac{8}{3}$', NULL, 'Walls per gallon is $\frac{2}{3} \div \frac{1}{4} = \frac{2}{3} \times 4 = \frac{8}{3}$. ($\frac{3}{8}$ is gallons per wall, $\frac{1}{6}$ is the product and $\frac{11}{12}$ is the sum.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3) / (1/4) = 8/3 walls per gallon.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b1b8ee0-37d0-4475-a88c-b9d845fe0bce', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', '$\frac{3}{4}$ pound of cheese costs 6 dollars. How many dollars does 1 pound of the cheese cost?', '[]', '8', '6/(3/4)', '$6 \div \frac{3}{4} = 6 \times \frac{4}{3} = 8$ dollars per pound. (Check: $\frac{3}{4}$ of 8 is 6.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (3/4) = 8 dollars per pound.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
