INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dccbf4f-af2e-4f2a-877e-b8d7500719fb', 'NC26.7.RPR.1', 2, 'choice', 'Unit rate with fractions', 'A machine fills $\frac{1}{2}$ of a tank in 3 minutes. How many minutes does it take to fill 1 whole tank at this rate?', '["$1.5$","$3.5$","$\\frac{1}{6}$","$6$"]', '$6$', '3/(1/2)', 'A whole tank is twice as much as half a tank, so it takes twice as long: $3 \div \frac{1}{2} = 6$ minutes. ($\frac{1}{6}$ is the fraction of a tank filled each minute.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half a tank in 3 min, so a whole tank in 3 / (1/2) = 6 min.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
