INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d14a19d3-3287-4913-ab2d-aa530fbea898', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', 'A bamboo plant grows $\frac{3}{8}$ inch in $\frac{1}{4}$ of a day. How many inches does it grow in 1 day?', '[]', '3/2', '(3/8)/(1/4)', '$\frac{3}{8} \div \frac{1}{4} = \frac{3}{8} \times 4 = \frac{12}{8} = \frac{3}{2}$ inches, which is $1\frac{1}{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/8) / (1/4) = 3/2 = 1.5 inches per day.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ddfe7ec-237d-4a47-9abd-7eb8a94dca28', 'NC26.7.RPR.1', 2, 'choice', 'Test whether a relationship is proportional', 'Which equation represents a proportional relationship?', '["$y = 0.75x$","$y = 0.75 + x$","$y = 2x + 3$","$y = 8 - x$"]', '$y = 0.75x$', NULL, 'A proportional relationship has the form $y = kx$: $y$ is a constant times $x$ with nothing added or subtracted. Only $y = 0.75x$ has that form.', 'checked', '{"lint":[],"solve":{"answer":"$y = 0.75x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only y = 0.75x has the form y = kx; the others have a constant added or subtracted.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4e1b64d-cf9a-4b87-a133-ebac510b5010', 'NC26.7.RPR.1', 2, 'choice', 'Test whether a relationship is proportional', 'Which description of a graph shows a proportional relationship?', '["A straight line that crosses the $y$-axis at $(0, 3)$","A straight line that passes through the origin","A curve that passes through the origin","A straight line that passes through $(1, 0)$"]', 'A straight line that passes through the origin', NULL, 'The graph of a proportional relationship is a straight line through the origin $(0, 0)$. A line crossing the $y$-axis at $(0, 3)$ or passing through $(1, 0)$ does not go through the origin, and a curve is not a straight line.', 'checked', '{"lint":[],"solve":{"answer":"A straight line that passes through the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A proportional graph is a straight line through the origin. (0,3) and (1,0) lines miss the origin; a curve is not proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
