INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b12a2922-ff5e-4bdc-acf4-2f200149ab26', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'In a proportional relationship, $y = 2.4$ when $x = 0.6$. What is the constant of proportionality $k$ in $y = kx$?', '[]', '4', '2.4/0.6', '$k = y \div x = 2.4 \div 0.6 = 4$. (Multiply both by 10 to get $24 \div 6 = 4$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2.4/0.6 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
