INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04282769-46d8-432a-af30-84eea38b747b', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table for a proportional relationship lists $y = 11.2$ when $x = 2$, $y = 28$ when $x = 5$ and $y = 44.8$ when $x = 8$. What is the constant of proportionality?', '[]', '5.6', '11.2/2', '$k = 11.2 \div 2 = 5.6$. Check: $28 \div 5 = 5.6$ and $44.8 \div 8 = 5.6$.', 'checked', '{"lint":[],"solve":{"answer":"5.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.2/2 = 5.6, 28/5 = 5.6, 44.8/8 = 5.6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc306e3a-0993-4aa3-9853-c3d4412c3297', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A proportional relationship has the pairs $(\frac{1}{3}, \frac{5}{6})$, $(\frac{2}{3}, \frac{5}{3})$ and $(1, \frac{5}{2})$. What is the constant of proportionality?', '[]', '5/2', '(5/6)/(1/3)', '$k = y \div x$. For the first pair, $\frac{5}{6} \div \frac{1}{3} = \frac{5}{6} \times 3 = \frac{5}{2}$. The last pair gives $\frac{5}{2} \div 1 = \frac{5}{2}$ as well.', 'checked', '{"lint":[],"solve":{"answer":"5/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5/6)/(1/3) = 5/2; (5/3)/(2/3) = 5/2; (5/2)/1 = 5/2.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46e9a4f9-c7a8-409d-9451-f5b455876d40', 'NC26.7.RPR.1', 3, 'choice', 'Constant of proportionality from a table or ordered pairs', 'In the proportional relationship $y = 2.5x$, $x$ can also be written as a multiple of $y$: $x = ky$. What is $k$?', '["2.5","1.5","0.4","0.25"]', '0.4', '1/2.5', 'Divide both sides of $y = 2.5x$ by 2.5 to get $x = \frac{1}{2.5}y = 0.4y$. So $k = 0.4$. (2.5 is the constant the other way around, and the others do not come from $1 \div 2.5$.)', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = y/2.5 = 0.4y, so k = 0.4.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d921df74-acd8-4a34-a3ce-61a30fc7cc26', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'Lena walks $\frac{3}{4}$ mile in 15 minutes at a steady pace. At this rate, how many miles does she walk in 1 hour?', '[]', '3', '(3/4)/(15/60)', '15 minutes is $\frac{1}{4}$ of an hour. Miles per hour = $\frac{3}{4} \div \frac{1}{4} = 3$ miles. (Or: 1 hour is 4 times 15 minutes, so $\frac{3}{4} \times 4 = 3$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 hour = 60 min = 4 x 15 min; 4 x 3/4 = 3 miles.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6562b913-e80c-4db8-b092-4246f64d9ec4', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'A tap fills $1\frac{1}{2}$ liters in $\frac{3}{8}$ of a minute. At this rate, how many liters does it fill in $2\frac{1}{2}$ minutes?', '[]', '10', '1.5/(3/8)*2.5', 'Liters per minute = $1\frac{1}{2} \div \frac{3}{8} = \frac{3}{2} \times \frac{8}{3} = 4$. In $2\frac{1}{2}$ minutes the tap fills $4 \times 2.5 = 10$ liters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = (3/2) / (3/8) = 4 liters per minute; 4 x 5/2 = 10 liters.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bba91a6d-b8d1-4953-a2b8-a28a3f045198', 'NC26.7.RPR.1', 3, 'choice', 'Unit rate with fractions', 'A car uses $\frac{3}{5}$ gallon of gas to travel 12 miles. Which statement is correct?', '["The car travels $\\frac{1}{20}$ mile on 1 gallon","The car travels 7.2 miles on 1 gallon","The car travels 20 miles on 1 gallon","The car travels 12 miles on 1 gallon"]', 'The car travels 20 miles on 1 gallon', NULL, 'Miles per gallon = $12 \div \frac{3}{5} = 12 \times \frac{5}{3} = 20$. ($\frac{1}{20}$ is gallons per mile, and 7.2 is $12 \times \frac{3}{5}$.)', 'checked', '{"lint":[],"solve":{"answer":"The car travels 20 miles on 1 gallon","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / (3/5) = 20 miles per gallon.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75f59001-8d86-4309-8906-b0d0ae68b632', 'NC26.7.RPR.1', 3, 'choice', 'Unit rate with fractions', 'Which rate is the same as walking $\frac{2}{3}$ mile in $\frac{1}{4}$ hour?', '["$\\frac{1}{6}$ mile in 1 hour","$\\frac{3}{8}$ mile in 1 hour","$\\frac{2}{3}$ mile in 1 hour","4 miles in $1\\frac{1}{2}$ hours"]', '4 miles in $1\frac{1}{2}$ hours', NULL, 'The speed is $\frac{2}{3} \div \frac{1}{4} = \frac{8}{3}$ miles per hour. For 4 miles in $1\frac{1}{2}$ hours, $4 \div \frac{3}{2} = \frac{8}{3}$ as well. The others are $\frac{1}{6}$, $\frac{3}{8}$ and $\frac{2}{3}$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"4 miles in $1\\frac{1}{2}$ hours","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)/(1/4) = 8/3 mi per hour. A: 2/3. B: 4/(3/2) = 8/3 yes. C: 3/8. D: 1/6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d90811d5-310a-4dd4-bc92-1dcdd7b42d23', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'Pat reads $\frac{1}{6}$ of a book in $\frac{1}{4}$ of an hour. At this rate, how many hours will it take Pat to read the whole book?', '[]', '3/2', '(1/4)/(1/6)', 'The whole book is 6 times $\frac{1}{6}$ of the book, so it takes 6 times as long: $6 \times \frac{1}{4} = \frac{3}{2}$ hours, which is $1\frac{1}{2}$ hours.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole book = 6 sixths; 6 x 1/4 = 3/2 = 1.5 hours. (Rate 2/3 book per hour; 1 / (2/3) = 1.5.)","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a71297c-03f1-48cd-95a9-1d5123c2e134', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'Maria looks at the pairs $(1, 5)$, $(2, 9)$, $(3, 13)$ and $(4, 17)$. She says $y$ is proportional to $x$ because $y$ goes up by the same amount, 4, each time $x$ goes up by 1. Which is correct?', '["She is right, because the change in $y$ is always the same","She is wrong, because $y$ must stay the same when $x$ goes up","She is right, because $y$ is always greater than $x$","She is wrong, because $y \\div x$ is not the same for every pair"]', 'She is wrong, because $y \div x$ is not the same for every pair', NULL, '$y \div x$ is $5$, $4.5$, $\frac{13}{3}$ and $4.25$, which are not equal. The relationship is $y = 4x + 1$, a straight line that does not pass through the origin. A constant change in $y$ alone does not make a relationship proportional.', 'checked', '{"lint":[],"solve":{"answer":"She is wrong, because $y \\div x$ is not the same for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 5, 4.5, 13/3, 4.25: not constant (y = 4x + 1, not through origin). She is wrong for that reason.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a83a22f-f33e-48e3-948a-8e0ca7ce937c', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'The pairs $(6, 4)$, $(9, 6)$ and $(15, 10)$ are given. Which statement, true for every pair, shows that $y$ is proportional to $x$?', '["$y \\div x$ equals $\\frac{2}{3}$","$y$ is larger when $x$ is larger","$x - y$ is the same","$x$ is a multiple of 3"]', '$y \div x$ equals $\frac{2}{3}$', NULL, '$4 \div 6$, $6 \div 9$ and $10 \div 15$ all equal $\frac{2}{3}$, which is what proportional means. The other statements do not show it: $x - y$ is 2, 3 and 5 (not the same), and "larger $x$ gives larger $y$" and "$x$ is a multiple of 3" do not show a constant ratio.', 'checked', '{"lint":[],"solve":{"answer":"$y \\div x$ equals $\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 = 6/9 = 10/15 = 2/3, constant, which shows proportionality. x - y = 2, 3, 5 not same. ''x multiple of 3'' and ''y larger when x larger'' are true but do not show proportionality.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c00b1e32-4d43-4539-8c9e-f8fff91c714b', 'NC26.7.RPR.1', 3, 'numeric', 'Test whether a relationship is proportional', 'A table has the pairs $(0.4, 1)$, $(1.2, 3)$ and $(x, 7.5)$. If $y$ is proportional to $x$, what is $x$?', '[]', '3', '7.5/(1/0.4)', '$y \div x = 1 \div 0.4 = 2.5$ (and $3 \div 1.2 = 2.5$). So $7.5 = 2.5x$ and $x = 7.5 \div 2.5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 1/0.4 = 3/1.2 = 2.5; x = 7.5/2.5 = 3.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('693bc279-94a4-4bef-9e90-3e9138473a9d', 'NC26.7.RPR.1', 3, 'numeric', 'Test whether a relationship is proportional', 'The pairs $(2, 9)$, $(4, 17)$ and $(6, 25)$ are not proportional. If $y$ were proportional to $x$ and passed through $(2, 9)$, its $y$ at $x = 6$ would be greater than 25. By how much?', '[]', '2', '9/2*6-25', 'If $y$ were proportional through $(2, 9)$, then $y \div x = 4.5$ and at $x = 6$ we would get $y = 4.5 \times 6 = 27$. That is $27 - 25 = 2$ more than 25.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Through (2,9): k = 4.5; at x = 6, y = 27. 27 - 25 = 2.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df217bd6-f941-49b3-af38-72c3013b0c7b', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'Which equation does NOT represent a proportional relationship?', '["$y = \\frac{x + 2}{3}$","$y = \\frac{x}{3}$","$y = 1.2x$","$y = \\frac{2x}{5}$"]', '$y = \frac{x + 2}{3}$', NULL, '$y = \frac{x + 2}{3}$ is the same as $y = \frac{1}{3}x + \frac{2}{3}$, which has $\frac{2}{3}$ added, so $y = \frac{2}{3}$ when $x = 0$ and $y \div x$ is not constant. The others are $y = kx$ with $k = \frac{1}{3}$, $1.2$ and $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{x + 2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2x, 2x/5 = 0.4x, x/3 are all kx. (x + 2)/3 = x/3 + 2/3 has a constant term: not proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f0b37c4-586d-439f-a90f-db7743df8285', 'NC26.7.RPR.1', 3, 'choice', 'Write and use an equation y = kx', 'The graph of a proportional relationship passes through the point $(5, 12)$. Which equation represents the relationship?', '["$y = \\frac{5}{12}x$","$y = 2.4x$","$y = 7x$","$y = 60x$"]', '$y = 2.4x$', NULL, '$k = y \div x = 12 \div 5 = 2.4$, so $y = 2.4x$. Check with the point: $2.4 \times 5 = 12$. ($y = 7x$ uses the difference $12 - 5$ as the constant.)', 'checked', '{"lint":[],"solve":{"answer":"$y = 2.4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 12/5 = 2.4, so y = 2.4x.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5d548d-9a70-45a3-ae1a-fa769ace9b71', 'NC26.7.RPR.1', 3, 'numeric', 'Write and use an equation y = kx', 'A proportional relationship is given by $y = \frac{5}{8}x$. What is $x$ when $y = 15$?', '[]', '24', '15/(5/8)', 'Put $y = 15$ into the equation: $15 = \frac{5}{8}x$. Multiply both sides by $\frac{8}{5}$: $x = 15 \times \frac{8}{5} = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = (5/8)x, x = 15 x 8/5 = 24.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('824c6e65-a9c5-4c4b-b46f-af88403492d6', 'NC26.7.RPR.1', 3, 'choice', 'Write and use an equation y = kx', 'A pool fills at 12 gallons per minute, so the gallons $g$ in the pool after $m$ minutes is $g = 12m$. Which equation gives the minutes $m$ in terms of the gallons $g$?', '["$m = \\frac{g}{12}$","$m = 12g$","$m = g - 12$","$m = \\frac{12}{g}$"]', '$m = \frac{g}{12}$', NULL, 'Divide both sides of $g = 12m$ by 12 to get $m = \frac{g}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$m = \\frac{g}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g = 12m, so m = g/12.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba35d294-500d-48ac-a467-5fc224703483', 'NC26.7.RPR.1', 3, 'numeric', 'Write and use an equation y = kx', 'The price $p$, in dollars, of $n$ pencils is $p = 0.35n$. How many more dollars do 12 pencils cost than 8 pencils?', '[]', '1.4', '0.35*12-0.35*8', '12 pencils cost $0.35 \times 12 = 4.20$ dollars and 8 pencils cost $0.35 \times 8 = 2.80$ dollars. The difference is $4.20 - 2.80 = 1.40$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 0.35 = 4.20, 8 x 0.35 = 2.80; difference 1.40 (= 4 x 0.35).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48cfd2da-4ccb-482c-888f-f7c5c1a17629', 'NC26.7.RPR.1', 3, 'numeric', 'Compare proportional relationships', 'Tap A fills $2\frac{1}{2}$ liters in $\frac{1}{2}$ of a minute. Tap B fills $4\frac{1}{2}$ liters in $\frac{3}{4}$ of a minute. How many more liters per minute does the faster tap fill than the slower tap?', '[]', '1', '4.5/(3/4)-2.5/(1/2)', 'Tap A: $2\frac{1}{2} \div \frac{1}{2} = 5$ liters per minute. Tap B: $4\frac{1}{2} \div \frac{3}{4} = \frac{9}{2} \times \frac{4}{3} = 6$ liters per minute. Tap B is faster, by $6 - 5 = 1$ liter per minute.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: (5/2)/(1/2) = 5 L/min. B: (9/2)/(3/4) = 6 L/min. 6 - 5 = 1.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088f4b2c-c4c2-4eda-8d14-0b8a6ca8549a', 'NC26.7.RPR.1', 3, 'choice', 'Compare proportional relationships', 'Runner P runs $d$ kilometers in $m$ minutes, where $d = 0.15m$. Runner Q runs 2.4 kilometers in 15 minutes. Runner R runs 3.5 kilometers in 25 minutes. All run at constant speeds. Who runs the most kilometers each minute?', '["Runner P","Runner R","Runner Q","Runners P and Q tie"]', 'Runner Q', NULL, 'P runs 0.15 kilometer each minute. Q runs $2.4 \div 15 = 0.16$ kilometer each minute. R runs $3.5 \div 25 = 0.14$ kilometer each minute. Q is the fastest.', 'checked', '{"lint":[],"solve":{"answer":"Runner Q","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 0.15 km/min. Q: 2.4/15 = 0.16. R: 3.5/25 = 0.14. Q is fastest.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6cca3a8-2bf7-40bc-a8aa-7fa0bb10d3fd', 'NC26.7.RPR.1', 3, 'choice', 'Compare proportional relationships', 'The graph of Line 1 passes through the origin and $(4, 10)$. The graph of Line 2 passes through the origin and $(10, 24)$. Which statement is true?', '["Line 2 has the greater constant of proportionality, 24 compared with 10","The two lines have the same constant of proportionality","Line 1 has the greater constant of proportionality, 2.5 compared with 2.4","Line 2 has the greater constant of proportionality, 10 compared with 4"]', 'Line 1 has the greater constant of proportionality, 2.5 compared with 2.4', NULL, 'Line 1: $k = 10 \div 4 = 2.5$. Line 2: $k = 24 \div 10 = 2.4$. Line 1 has the greater constant of proportionality. Comparing the points'' numbers directly does not compare the constants.', 'checked', '{"lint":[],"solve":{"answer":"Line 1 has the greater constant of proportionality, 2.5 compared with 2.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 1: k = 10/4 = 2.5. Line 2: k = 24/10 = 2.4. Line 1 greater.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
