INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('989a81ae-7ce4-40ca-a2b4-6f2ba1928c2c', 'NC26.7.RPR.1', 3, 'numeric', 'Compare proportional relationships', 'Plan A charges 0.07 dollar for each text message. Plan B charges 3 dollars for every 50 messages. Tina sends 500 messages. How many dollars cheaper is Plan B than Plan A?', '[]', '5', '0.07*500-3/50*500', 'Plan A: $0.07 \times 500 = 35$ dollars. Plan B: $3 \div 50 = 0.06$ dollar per message, so $0.06 \times 500 = 30$ dollars. Plan B is $35 - 30 = 5$ dollars cheaper.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 500 x 0.07 = 35. B: 500/50 = 10 groups x 3 = 30. 35 - 30 = 5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037ef9e9-9410-47f5-a8eb-9055ac151f21', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(1.5, 9)$ is on the graph of a proportional relationship between the hours $x$ and the gallons $y$ of water a pump moves. Which statement is true?', '["The pump moves 9 gallons each hour","The pump moves 13.5 gallons each hour","The pump moves 6 gallons each hour","The pump moves 1.5 gallons each hour"]', 'The pump moves 6 gallons each hour', NULL, '1.5 hours move 9 gallons, so each hour the pump moves $9 \div 1.5 = 6$ gallons. (13.5 is $1.5 \times 9$.)', 'checked', '{"lint":[],"solve":{"answer":"The pump moves 6 gallons each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/1.5 = 6 gallons per hour.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1aacc9e-813b-41cb-af08-371f6f6b4513', 'NC26.7.RPR.1', 3, 'numeric', 'Interpret a point of a proportional relationship in context', 'The point $(\frac{2}{3}, 5)$ is on the graph of a proportional relationship. What is the value of $y$ when $x = 1$?', '[]', '7.5', '5/(2/3)', '$k = y \div x = 5 \div \frac{2}{3} = 5 \times \frac{3}{2} = 7.5$. When $x = 1$, $y = 7.5 \times 1 = 7.5$.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 5 / (2/3) = 15/2 = 7.5; at x = 1, y = 7.5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22ea0768-07d5-4891-bb02-ee4120b8941a', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'Which pair of points can both be on the graph of one proportional relationship?', '["$(4, 6)$ and $(14, 16)$","$(4, 6)$ and $(6, 4)$","$(4, 6)$ and $(10, 14)$","$(4, 6)$ and $(14, 21)$"]', '$(4, 6)$ and $(14, 21)$', NULL, 'Both points must have the same $y \div x$. For $(4, 6)$ it is $1.5$, and for $(14, 21)$ it is $21 \div 14 = 1.5$. The others have $y \div x$ of $\frac{8}{7}$ (adding 2 to both), $\frac{2}{3}$ (the numbers swapped) and $1.4$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 6)$ and $(14, 21)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,6): y/x = 1.5. (14,21): 1.5 yes. (14,16): 8/7 no. (10,14): 1.4 no. (6,4): 2/3 no.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b35d5d8-8451-4e4b-b30e-9bea26301e5e', 'NC26.7.RPR.1', 3, 'numeric', 'Interpret a point of a proportional relationship in context', 'The point $(12, 7.2)$ is on the graph of a proportional relationship between the ounces $x$ of cheese and the cost $y$ in dollars. What is the cost of 25 ounces of the cheese?', '[]', '15', '7.2/12*25', '$12$ ounces cost 7.2 dollars, so 1 ounce costs $7.2 \div 12 = 0.6$ dollar. For 25 ounces: $0.6 \times 25 = 15$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 7.2/12 = 0.6 dollars per ounce; 25 x 0.6 = 15.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
