VALUES ('52f95859-78ba-4f0c-a7d4-53ba77352fd0', 'NC26.7.RPR.2', 1, 'numeric', 'Commission', 'A salesperson earns a commission of 5% of her sales. She sells 800 dollars of goods. How many dollars is her commission?', '[]', '40', '800*0.05', '5% of 800 is $800 \times 0.05 = 40$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05 x 800 = 40.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
