INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b68e3e06-2017-4cb1-a764-fa9fce37eb5c', 'NC26.7.RPR.2', 1, 'choice', 'Percent increase and decrease', 'A plant grows from 10 cm tall to 12 cm tall. What is the percent increase in its height?', '["2%","12%","17%","20%"]', '20%', NULL, 'The increase is $12 - 10 = 2$ cm. As a fraction of the original 10 cm it is $2 \div 10 = 0.2$, which is 20%. (17% comes from dividing by the new height, 12.)', 'checked', '{"lint":[],"solve":{"answer":"20%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 2; 2/10 = 20%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
