INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4af04500-412f-4c4a-aa02-805b19dae515', 'NC26.7.RPR.2', 2, 'choice', 'Find an actual size from a scale drawing', 'A floor plan uses 1 inch for every 5 feet. The kitchen is 2.4 inches by 3 inches on the plan. What are the real measurements of the kitchen?', '["12 feet by 15 feet","7.4 feet by 8 feet","1.2 feet by 1.5 feet","12 feet by 3 feet"]', '12 feet by 15 feet', NULL, 'Multiply each length by 5: $2.4 \times 5 = 12$ feet and $3 \times 5 = 15$ feet.', 'checked', '{"lint":[],"solve":{"answer":"12 feet by 15 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4 x 5 = 12 ft, 3 x 5 = 15 ft.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
