INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d3c647-350a-4e7a-a2d2-9052bac8b666', 'NC26.7.RPR.2', 2, 'numeric', 'Construct a scale drawing or find a scale', 'A rectangular garden is 18 feet long and 12 feet wide. A scale drawing of the garden uses the scale 1 inch : 3 feet. What is the perimeter of the garden on the drawing, in inches?', '[]', '20', '2*(18/3+12/3)', 'On the drawing the length is $18 \div 3 = 6$ inches and the width is $12 \div 3 = 4$ inches. The perimeter is $2 \times (6 + 4) = 20$ inches.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing: 18/3 = 6 in by 12/3 = 4 in. Perimeter 2(6 + 4) = 20 in.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e01e50-415a-463d-b038-128a140b678b', 'NC26.7.RPR.2', 2, 'choice', 'Construct a scale drawing or find a scale', 'Two cities are 150 kilometers apart in real life and 6 centimeters apart on a map. Which scale does the map use?', '["1 cm : 25 km","1 cm : 900 km","1 cm : 144 km","1 cm : 0.04 km"]', '1 cm : 25 km', NULL, '6 centimeters stand for 150 kilometers, so 1 centimeter stands for $150 \div 6 = 25$ kilometers. The scale is 1 cm : 25 km.', 'checked', '{"lint":[],"solve":{"answer":"1 cm : 25 km","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/6 = 25 km per cm: 1 cm : 25 km.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
