INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c1840fd-8dee-4af1-ae40-5f31e5182a45', 'NC26.7.RPR.2', 2, 'numeric', 'Construct a scale drawing or find a scale', 'A map uses the scale 3 cm : 5 km. Two towns are 12 km apart in real life. How many centimeters apart are the towns on the map?', '[]', '7.2', '12/5*3', '12 km is $12 \div 5 = 2.4$ times 5 km. So the towns are $2.4 \times 3 = 7.2$ centimeters apart on the map.', 'checked', '{"lint":[],"solve":{"answer":"7.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 km = 12/5 = 2.4 groups of 5 km; 2.4 x 3 = 7.2 cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca32635c-8382-4ccd-862d-542e6fc200b6', 'NC26.7.RPR.2', 2, 'choice', 'Construct a scale drawing or find a scale', 'A drawing uses the scale 2 cm : 10 m. Which scale is equivalent to it?', '["1 cm : 20 m","1 cm : 5 m","4 cm : 5 m","5 cm : 1 m"]', '1 cm : 5 m', NULL, 'Divide both parts of $2 : 10$ by 2 to get $1 : 5$, so 1 cm stands for 5 m. The others stand for 20 m, 1.25 m and 0.2 m for each centimeter.', 'checked', '{"lint":[],"solve":{"answer":"1 cm : 5 m","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 cm : 10 m = 1 cm : 5 m (divide both by 2). Others: 5 cm:1 m, 1 cm:20 m, 4 cm:5 m differ.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8294486-b3d8-4d8f-8ac1-4237f6fa9b49', 'NC26.7.RPR.2', 2, 'numeric', 'How a scale changes area', 'A rectangle on a scale drawing is 4 cm by 2.5 cm. The scale is 1 cm : 10 m. What is the real area of the rectangle, in square meters?', '[]', '1000', '(4*10)*(2.5*10)', 'The real rectangle is $4 \times 10 = 40$ meters by $2.5 \times 10 = 25$ meters. Its area is $40 \times 25 = 1000$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real 40 m by 25 m; area 1000 square meters.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
