INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5ceaaca-9ca0-4da0-91a2-35325bc7c9f0', 'NC26.7.RPR.2', 2, 'numeric', 'How a scale changes area', 'On a scale drawing, a field has an area of 20 square centimeters. The scale is 1 cm : 5 m. What is the real area of the field, in square meters?', '[]', '500', '20*5^2', 'Each square centimeter of the drawing stands for $5 \times 5 = 25$ square meters. So the field has an area of $20 \times 25 = 500$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 sq cm on drawing = 5 x 5 = 25 sq m; 20 x 25 = 500.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca90fa4d-5a4a-4686-a0a2-ecb62ccb7818', 'NC26.7.RPR.2', 2, 'choice', 'How a scale changes area', 'A photo is enlarged so that each side is 3 times as long as before. The new area is how many times the old area?', '["3","6","27","9"]', '9', '3^2', 'The length and the width are both multiplied by 3, so the area is multiplied by $3 \times 3 = 9$. (3 forgets that both sides change, and 27 multiplies by 3 three times.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3 = 9 times the area.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cf46116-b477-469c-931d-bf49539534d2', 'NC26.7.RPR.2', 2, 'choice', 'How a scale changes area', 'A floor plan uses the scale 1 inch : 4 feet. A rug is 2 inches by 3 inches on the plan. What is the real area of the rug?', '["24 square feet","96 square feet","48 square feet","6 square feet"]', '96 square feet', NULL, 'The real rug is $2 \times 4 = 8$ feet by $3 \times 4 = 12$ feet, so its area is $8 \times 12 = 96$ square feet. (24 multiplies the plan area of 6 by only 4.)', 'checked', '{"lint":[],"solve":{"answer":"96 square feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real 8 ft by 12 ft = 96 square feet.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91fa16c9-c26f-41c2-8f2d-81876f9c01a2', 'NC26.7.RPR.2', 2, 'numeric', 'Sales tax and tip', 'The sales tax on a 30 dollar purchase is 2.40 dollars. What is the sales tax rate, as a percent?', '[]', '8', '2.4/30*100', 'The rate is the tax divided by the price: $2.40 \div 30 = 0.08$, which is 8%.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.40/30 = 0.08 = 8%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75539800-b22e-4c6a-893e-b95989312190', 'NC26.7.RPR.2', 2, 'choice', 'Sales tax and tip', 'A meal costs 25 dollars. How many dollars is an 18% tip on the meal?', '["0.45","45","7","4.5"]', '4.5', '25*0.18', '18% of 25 is $25 \times 0.18 = 4.5$ dollars, which is 4.50 dollars.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.18 x 25 = 4.5.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
