INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6dda40d-b35d-46ea-b708-fe0f1b0691d2', 'NC26.7.RPR.2', 2, 'numeric', 'Sales tax and tip', 'A video game costs 50 dollars before tax. With sales tax added, the total is 53.50 dollars. What is the sales tax rate, as a percent?', '[]', '7', '(53.5-50)/50*100', 'The tax is $53.50 - 50 = 3.50$ dollars. The rate is $3.50 \div 50 = 0.07$, which is 7%.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tax = 3.50; 3.50/50 = 0.07 = 7%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
