INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1449c56-a68c-4aad-94d8-98a3c6996ddd', 'NC26.7.RPR.2', 2, 'numeric', 'Markup and discount', 'The price of a tablet is cut from 250 dollars to 200 dollars. What is the percent discount?', '[]', '20', '(250-200)/250*100', 'The discount is $250 - 200 = 50$ dollars. As a fraction of the original price it is $50 \div 250 = 0.2$, which is 20%.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cut 50; 50/250 = 20%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
