INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bf16309-97fe-43a5-980c-02b19ee68a98', 'NC26.7.RPR.2', 2, 'numeric', 'Percent increase and decrease', 'A stock price rose from 80 dollars to 92 dollars. What is the percent increase?', '[]', '15', '(92-80)/80*100', 'The increase is $92 - 80 = 12$ dollars. As a fraction of the original 80 it is $12 \div 80 = 0.15$, which is 15%.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 12; 12/80 = 0.15 = 15%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
