INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5bd2c4d-fe7e-41bd-b5b7-67f01179c708', 'NC26.7.RPR.2', 2, 'choice', 'Percent increase and decrease', 'A car is worth 12,000 dollars. Its value falls by 15% in one year. What is the value of the car after one year, in dollars?', '["1,800","10,200","13,800","11,985"]', '10,200', '12000-12000*0.15', '15% of 12,000 is $12000 \times 0.15 = 1800$ dollars. The new value is $12000 - 1800 = 10200$ dollars. (1,800 is only the decrease.)', 'checked', '{"lint":[],"solve":{"answer":"10,200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12000 x 0.85 = 10200.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
