INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e62e87b-a182-4153-b061-cd28d2938f41', 'NC26.7.RPR.2', 3, 'numeric', 'Convert measurement units', 'A pipe leaks 2.4 liters every 15 minutes. How many liters leak in 1 day (24 hours) at this rate?', '[]', '230.4', '2.4*4*24', 'There are four 15-minute periods in an hour, so the pipe leaks $2.4 \times 4 = 9.6$ liters each hour. In 24 hours it leaks $9.6 \times 24 = 230.4$ liters.', 'checked', '{"lint":[],"solve":{"answer":"230.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 h = 1440 min = 96 periods of 15 min; 96 x 2.4 = 230.4 liters.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
