INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc082623-89e7-460a-8cd4-00b61f10ebfe', 'NC26.7.RPR.2', 3, 'numeric', 'Convert measurement units', 'A sprinter runs 100 meters in 12.5 seconds at a steady speed. What is the sprinter''s speed in kilometers per hour? (1 kilometer = 1000 meters)', '[]', '28.8', '100/12.5*3600/1000', 'The speed is $100 \div 12.5 = 8$ meters per second. In one hour (3600 seconds) that is $8 \times 3600 = 28800$ meters, which is $28800 \div 1000 = 28.8$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"28.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100/12.5 = 8 m/s. Per hour: 8 x 3600 = 28800 m = 28.8 km. 28.8 km/h.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51f4c527-4500-4bd4-b49f-69d1e78f2f0a', 'NC26.7.RPR.2', 3, 'choice', 'Convert measurement units', 'Which length is the same as 2 yards 6 inches? (1 yard = 36 inches)', '["72 inches","30 inches","78 inches","42 inches"]', '78 inches', NULL, '2 yards is $2 \times 36 = 72$ inches. Adding the 6 inches gives $72 + 6 = 78$ inches. (30 uses 12 inches for a yard, and 42 counts only 1 yard.)', 'checked', '{"lint":[],"solve":{"answer":"78 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 36 + 6 = 78 inches.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78ab1b37-fa39-455d-8de2-f07f24c98563', 'NC26.7.RPR.2', 3, 'numeric', 'Find an actual size from a scale drawing', 'On a map, 1.5 centimeters stand for 20 kilometers. Two towns are 6.3 centimeters apart on the map. How many kilometers apart are the towns?', '[]', '84', '20/1.5*6.3', '6.3 centimeters is $6.3 \div 1.5 = 4.2$ times 1.5 centimeters. So the real distance is $4.2 \times 20 = 84$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.3/1.5 = 4.2 units; 4.2 x 20 = 84 km.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30b2da9a-a0ca-4962-8679-6c2c0761807f', 'NC26.7.RPR.2', 3, 'numeric', 'Find an actual size from a scale drawing', 'On a map, 1 centimeter stands for 2.5 kilometers. A trail runs 4.2 centimeters east and then 3.8 centimeters north on the map. What is the real length of the trail, in kilometers?', '[]', '20', '(4.2+3.8)*2.5', 'The trail is $4.2 + 3.8 = 8$ centimeters long on the map. The real length is $8 \times 2.5 = 20$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trail on map = 4.2 + 3.8 = 8 cm (path length, not straight-line). 8 x 2.5 = 20 km.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a2ca495-1dd3-4446-8938-61fcd4033f9e', 'NC26.7.RPR.2', 3, 'choice', 'Find an actual size from a scale drawing', 'A drawing of an insect uses a scale of 6 cm : 1 cm, so 6 cm on the drawing stand for 1 cm in real life. The insect is 9 cm long on the drawing. How long is the real insect, in centimeters?', '["54","15","1.5","3"]', '1.5', '9/6', 'The drawing is 6 times as large as the insect, so the insect is $9 \div 6 = 1.5$ centimeters long. (54 multiplies, 15 adds and 3 subtracts.)', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/6 = 1.5 cm real.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
