INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8483d62b-3f5e-4d56-b971-e72f395c30f2', 'NC26.7.RPR.2', 3, 'choice', 'Find an actual size from a scale drawing', 'A scale drawing uses the scale 1 inch : 8 feet. Which statement is true?', '["A line 3.5 inches long on the drawing stands for 11.5 feet","A line 3.5 inches long on the drawing stands for 28 feet","A line 40 feet long is drawn 4 inches long","A line 16 feet long is drawn 128 inches long"]', 'A line 3.5 inches long on the drawing stands for 28 feet', NULL, 'Each inch stands for 8 feet, so 3.5 inches stand for $3.5 \times 8 = 28$ feet. A 40-foot line is $40 \div 8 = 5$ inches long on the drawing, and a 16-foot line is $16 \div 8 = 2$ inches long.', 'checked', '{"lint":[],"solve":{"answer":"A line 3.5 inches long on the drawing stands for 28 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 in = 8 ft. 40 ft -> 5 in (A false). 3.5 in -> 28 ft (B false, C true). 16 ft -> 2 in (D false).","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eda2b8b0-540a-45e8-8e0a-4cceaa9a846a', 'NC26.7.RPR.2', 3, 'numeric', 'Construct a scale drawing or find a scale', 'A real fence is 17.5 feet long. A scale drawing uses the scale 1.5 inches : 5 feet. How long is the fence on the drawing, in inches?', '[]', '5.25', '17.5/5*1.5', '17.5 feet is $17.5 \div 5 = 3.5$ times 5 feet. So the fence is $3.5 \times 1.5 = 5.25$ inches long on the drawing.', 'checked', '{"lint":[],"solve":{"answer":"5.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17.5/5 = 3.5; 3.5 x 1.5 = 5.25 inches.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59408889-68ac-49d9-9ce9-a49a51070395', 'NC26.7.RPR.2', 3, 'choice', 'Construct a scale drawing or find a scale', 'On Map A, 1 cm stands for 8 km. On Map B, 1 cm stands for 2 km. Two towns are 3 cm apart on Map A. How many centimeters apart are the towns on Map B?', '["0.75","6","12","24"]', '12', '3*8/2', 'On Map A the real distance is $3 \times 8 = 24$ km. On Map B each centimeter stands for 2 km, so the towns are $24 \div 2 = 12$ cm apart. (24 is the real distance, and 6 and 0.75 mix the scales up.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real = 3 x 8 = 24 km. On Map B: 24/2 = 12 cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e133c738-3a77-47c6-86bb-86bf675d10c8', 'NC26.7.RPR.2', 3, 'numeric', 'Construct a scale drawing or find a scale', 'A rectangular field is 45 meters long and 30 meters wide. On a scale drawing of the field, the length is 9 centimeters. How wide is the field on the drawing, in centimeters?', '[]', '6', '9/45*30', 'The 45 meters are shown by 9 centimeters, so 1 centimeter stands for $45 \div 9 = 5$ meters. The width of 30 meters is $30 \div 5 = 6$ centimeters on the drawing.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 m -> 9 cm, so 1 cm : 5 m. 30/5 = 6 cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f919cd22-a032-46bd-844a-b1bb8c2e96ea', 'NC26.7.RPR.2', 3, 'numeric', 'How a scale changes area', 'A map uses the scale 1 cm : 4 km. A lake covers 6.5 square centimeters on the map. What is the real area of the lake, in square kilometers?', '[]', '104', '6.5*4^2', 'Each square centimeter on the map stands for $4 \times 4 = 16$ square kilometers. The lake is $6.5 \times 16 = 104$ square kilometers.', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 sq cm = 4 x 4 = 16 sq km; 6.5 x 16 = 104.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
