INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3ec7e3a-481d-4267-817a-ebe70a0fdab0', 'NC26.7.RPR.2', 3, 'choice', 'Sales tax and tip', 'A group''s bill is 64 dollars before tax. The sales tax is 7%, and the tip is 20% of the cost before tax. Four friends split the total equally. How many dollars does each friend pay?', '["81.28","20.32","17.12","19.20"]', '20.32', '(64+64*0.07+64*0.2)/4', 'The tax is $64 \times 0.07 = 4.48$ and the tip is $64 \times 0.20 = 12.80$. The total is $64 + 4.48 + 12.80 = 81.28$ dollars. Each friend pays $81.28 \div 4 = 20.32$ dollars. (81.28 is the whole bill, 17.12 leaves out the tip and 19.20 leaves out the tax.)', 'checked', '{"lint":[],"solve":{"answer":"20.32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tax 0.07 x 64 = 4.48; tip 0.20 x 64 = 12.80; total 81.28; /4 = 20.32.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
