INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad71a0f6-8399-479f-b593-24e483353cba', 'NC26.7.RPR.2', 3, 'numeric', 'Commission', 'Maya is paid 120 dollars a week plus a commission of 4% of her sales. How many dollars of sales does she need in a week to earn 200 dollars in all?', '[]', '2000', '(200-120)/0.04', 'She needs $200 - 120 = 80$ dollars from commission. 4% of her sales must be 80 dollars, so her sales are $80 \div 0.04 = 2000$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Needs 200 - 120 = 80 commission; 80/0.04 = 2000 dollars of sales.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
