INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5452e77-2c49-47d7-8c16-9093a9c51772', 'NC26.7.RPR.2', 3, 'numeric', 'Percent increase and decrease', 'After a 12% decrease, a number is 66. What was the number before the decrease?', '[]', '75', '66/0.88', 'After a 12% decrease the number is 88% of the original, so the original is $66 \div 0.88 = 75$. Check: 12% of 75 is 9, and $75 - 9 = 66$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.88n = 66, n = 75.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
