INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c37adc7b-9b37-4aff-b4bb-7317538efc23', 'NC26.7.RPR.2', 3, 'choice', 'Percent increase and decrease', 'A hiker''s pack weighs 8 pounds. After adding supplies, it weighs 11 pounds. What is the percent increase in its weight?', '["37.5%","27.3%","3%","73%"]', '37.5%', NULL, 'The increase is $11 - 8 = 3$ pounds. As a fraction of the original 8 pounds it is $3 \div 8 = 0.375$, which is 37.5%. (27.3% comes from dividing by the new weight, 11.)', 'checked', '{"lint":[],"solve":{"answer":"37.5%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 3; 3/8 = 0.375 = 37.5%. (27.3% is 3/11, wrong base.)","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
