INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66eac68e-d92f-401d-97c7-7785ad5b8547', 'NC26.7.RPR.2', 3, 'choice', 'Percent increase and decrease', 'Which is the greater percent increase: from 40 to 50, or from 20 to 26?', '["From 40 to 50, which is a 25% increase","The two increases are equal","From 40 to 50, because 10 is more than 6","From 20 to 26, which is a 30% increase"]', 'From 20 to 26, which is a 30% increase', NULL, 'From 40 to 50 the increase is 10, and $10 \div 40 = 0.25$, a 25% increase. From 20 to 26 the increase is 6, and $6 \div 20 = 0.30$, a 30% increase. The second is greater, even though its increase is smaller in size.', 'checked', '{"lint":[],"solve":{"answer":"From 20 to 26, which is a 30% increase","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 to 50: 10/40 = 25%. 20 to 26: 6/20 = 30%. The second is greater.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0e34c2a-0071-4c02-841f-4a071f15d61a', 'NC26.7.RPR.2', 3, 'numeric', 'Percent increase and decrease', 'A recipe changes the sugar from $\frac{2}{5}$ cup to $\frac{3}{5}$ cup. What is the percent increase?', '[]', '50', '(3/5-2/5)/(2/5)*100', 'The increase is $\frac{3}{5} - \frac{2}{5} = \frac{1}{5}$ cup. As a fraction of the original $\frac{2}{5}$ cup it is $\frac{1}{5} \div \frac{2}{5} = \frac{1}{2}$, which is 50%.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 1/5; (1/5)/(2/5) = 1/2 = 50%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
