INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5e472e8-e0c8-45a3-bf51-05d7228e6d29', 'NC26.7.RPR.3', 1, 'choice', 'Compare sectors of a circle graph', 'Sector A of a circle graph measures 60 degrees and sector B measures 120 degrees. Which statement is true?', '["Sector A stands for twice as much as sector B.","Sectors A and B stand for the same amount.","Sector B stands for 1.5 times as much as sector A.","Sector B stands for twice as much as sector A."]', 'Sector B stands for twice as much as sector A.', NULL, '$120 \div 60 = 2$, so sector B is twice as large as sector A and stands for twice as much.', 'checked', '{"lint":[],"solve":{"answer":"Sector B stands for twice as much as sector A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120/60 = 2, and in one circle graph the amount is proportional to the angle, so B stands for twice as much as A.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
