VALUES ('3ec0b0d7-4562-4d7f-96bb-6b48c2868e7e', 'NC26.7.RPR.3', 1, 'choice', 'Find circumference from radius', 'A circular playground has a radius of 10 meters. Use 3.14 for $\pi$. What is its circumference, in meters?', '["31.4","62.8","314","20"]', '62.8', '2*3.14*10', '$2 \times 3.14 \times 10 = 62.8$ meters. (31.4 forgets the 2, and 314 is $3.14 \times 10 \times 10$.)', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 10 = 62.8 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
