INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb6621b1-bf56-4c06-83a1-a0f2ad9f5b38', 'NC26.7.RPR.3', 1, 'numeric', 'Find diameter or radius from circumference', 'A round swimming pool has a circumference of 31.4 meters. Use 3.14 for $\pi$. What is the diameter of the pool, in meters?', '[]', '10', '31.4/3.14', 'Circumference $= \pi \times$ diameter, so diameter $= 31.4 \div 3.14 = 10$ meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = C / pi = 31.4 / 3.14 = 10 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
