INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bb771a7-78ab-4cc1-88d7-f027215a9b4a', 'NC26.7.RPR.3', 1, 'choice', 'Find diameter or radius from circumference', 'A circle has a circumference of 25.12 centimeters. Use 3.14 for $\pi$. What is its diameter, in centimeters?', '["4","12.56","21.98","8"]', '8', '25.12/3.14', 'Diameter $= 25.12 \div 3.14 = 8$ centimeters. (4 is the radius, 12.56 is half the circumference, and 21.98 subtracts.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 25.12 / 3.14 = 8 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
