INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77029a9b-64af-4247-86be-712242e6ca66', 'NC26.7.RPR.3', 1, 'numeric', 'Solve a problem using circumference', 'A bicycle wheel has a circumference of 2 meters. How far does the bicycle travel when the wheel makes 10 full turns, in meters?', '[]', '20', '2*10', 'Each full turn moves the bicycle one circumference, 2 meters. 10 turns is $10 \times 2 = 20$ meters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each full turn rolls one circumference, 2 m; 10 turns = 20 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
