INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d130348-3656-4a3e-a199-dc4ba49f63c6', 'NC26.7.RPR.3', 1, 'choice', 'Solve a problem using circumference', 'A circular track has a circumference of 400 meters. A runner goes around it 3 times. How many meters does the runner run?', '["1200","403","400","120"]', '1200', '400*3', 'Each lap is 400 meters, so 3 laps is $3 \times 400 = 1200$ meters.', 'checked', '{"lint":[],"solve":{"answer":"1200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy: with the circumference given it is only 400 x 3, so it uses almost no circle reasoning. Acceptable as an entry-level item, but weak evidence for the standard.","work":"One lap = 400 m; 3 laps = 1200 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
