INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b95ed23-8dbf-44b6-971c-3b8bee9f52fa', 'NC26.7.RPR.3', 2, 'numeric', 'Find a missing sector of a circle graph', 'In a circle graph about pets, dogs take 135 degrees, cats take 90 degrees and fish take 45 degrees. The rest of the circle is birds. What percent of the circle is birds?', '[]', '25', '(360-135-90-45)/360*100', '$135 + 90 + 45 = 270$, so birds take $360 - 270 = 90$ degrees. $\frac{90}{360} = 25\%$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"135 + 90 + 45 = 270; birds = 360 - 270 = 90 degrees; 90/360 = 25%.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
