INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46f15df0-39d8-49be-9ed6-d9697924f394', 'NC26.7.RPR.3', 2, 'choice', 'Know that circumference divided by diameter is pi', 'Maya measures a round can. Its circumference is 25.1 centimeters and its diameter is 8 centimeters. She divides 25.1 by 8. Which number is closest to her answer?', '["0.32","17.1","200.8","3.14"]', '3.14', '3.14', '$25.1 \div 8 = 3.1375$, which is close to $\pi \approx 3.14$. (0.32 divides the other way, 17.1 subtracts, and 200.8 multiplies.)', 'checked', '{"lint":[],"solve":{"answer":"3.14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25.1 / 8 = 3.1375, closest to 3.14.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
