INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('430dfc0d-686d-40e5-a6e1-aadda76013cb', 'NC26.7.RPR.3', 2, 'choice', 'Find circumference from diameter', 'A circular fountain has a diameter of 2.5 meters. Use 3.14 for $\pi$. What is its circumference, in meters?', '["3.925","19.625","5.64","7.85"]', '7.85', '3.14*2.5', '$3.14 \times 2.5 = 7.85$ meters. (3.925 uses the radius, 19.625 squares the diameter, and 5.64 adds.)', 'checked', '{"lint":[],"solve":{"answer":"7.85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 2.5 = 7.85 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
