INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf89f59d-965e-45ae-a51e-e1959b06947b', 'NC26.7.RPR.3', 2, 'choice', 'Find circumference from radius', 'A circular fountain has a radius of 1.5 meters. Use 3.14 for $\pi$. What is its circumference, in meters?', '["4.71","9.42","7.065","18.84"]', '9.42', '2*3.14*1.5', '$2 \times 3.14 \times 1.5 = 9.42$ meters. (4.71 forgets the 2, 7.065 is $3.14 \times 1.5 \times 1.5$, and 18.84 uses 3 as the radius.)', 'checked', '{"lint":[],"solve":{"answer":"9.42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 1.5 = 9.42 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
