INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac031e8c-d52d-4ab0-b3ba-46852211de61', 'NC26.7.RPR.3', 2, 'choice', 'Find diameter or radius from circumference', 'A bicycle wheel has a circumference of 188.4 centimeters. Use 3.14 for $\pi$. What is the radius of the wheel, in centimeters?', '["30","60","94.2","15"]', '30', '188.4/(2*3.14)', 'Diameter $= 188.4 \div 3.14 = 60$ centimeters, and the radius is half of that: 30 centimeters. (60 is the diameter, not the radius.)', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 188.4 / 3.14 = 60 cm; r = 30 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
