INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b76247e8-7bec-4236-88a7-22dac8c71cdf', 'NC26.7.RPR.3', 2, 'choice', 'Find diameter or radius from circumference', 'The distance around a circular pond is 44 meters. Use $\frac{22}{7}$ for $\pi$. What is the diameter of the pond, in meters?', '["7","28","14","66"]', '14', '44/(22/7)', 'Diameter $= 44 \div \frac{22}{7} = 44 \times \frac{7}{22} = 14$ meters. (7 is the radius, 28 doubles the diameter, and 66 adds 22.)', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 44 / (22/7) = 44 x 7/22 = 14 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
