INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39ec12f2-6707-4e9e-93a4-d77f0f5f12ba', 'NC26.7.RPR.3', 2, 'numeric', 'Find diameter or radius from circumference', 'A tree trunk is nearly a circle, and its circumference is 125.6 centimeters. Use 3.14 for $\pi$. What is the diameter of the trunk, in centimeters?', '[]', '40', '125.6/3.14', 'Diameter $= 125.6 \div 3.14 = 40$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 125.6 / 3.14 = 40 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
