INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72f06015-c2d9-43dc-9b36-53b98fecbee8', 'NC26.7.RPR.3', 3, 'choice', 'Convert a percent or fraction to degrees in a circle graph', 'One category in a circle graph is 7% of the data. What is the angle of that sector, in degrees?', '["2.52","25.2","252","7"]', '25.2', '0.07*360', '$0.07 \times 360 = 25.2$ degrees. (2.52 and 252 misplace the decimal point, and 7 treats the percent as degrees.)', 'checked', '{"lint":[],"solve":{"answer":"25.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.07 x 360 = 25.2 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
