INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7d73350-9284-48f8-911b-207c139f95d6', 'NC26.7.RPR.3', 3, 'choice', 'Convert degrees to a percent or fraction of a circle graph', 'Two sectors of a circle graph measure 63 degrees and 81 degrees. Together, what percent of the circle do the two sectors cover?', '["40","17.5","22.5","144"]', '40', '(63+81)/360*100', '$63 + 81 = 144$ degrees. $\frac{144}{360} = 0.4 = 40\%$. (17.5 and 22.5 are the percents for each sector alone, and 144 is the angle, not a percent.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63 + 81 = 144 degrees; 144/360 = 0.4 = 40%.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
