INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('845586b8-deaa-4daf-853b-d2dbbd45ef3a', 'NC26.7.RPR.3', 3, 'choice', 'Convert degrees to a percent or fraction of a circle graph', 'A sector of a circle graph measures 210 degrees. Which fraction of the whole circle is that sector?', '["5/12","7/10","7/12","3/5"]', '7/12', '210/360', '$\frac{210}{360}$ simplifies by dividing both numbers by 30, giving $\frac{7}{12}$. (5/12 is the fraction of the circle left over.)', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"210/360 = 21/36 = 7/12.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
