INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d323034d-eb31-41f0-aa7c-269b8b8a01f4', 'NC26.7.RPR.3', 3, 'choice', 'Use a circle graph sector to find a count', 'A circle graph shows how 1200 customers paid. The cash sector measures 54 degrees and the card sector measures 198 degrees. How many more customers paid by card than by cash?', '["480","660","180","144"]', '480', '(198-54)/360*1200', 'The card sector is $198 - 54 = 144$ degrees larger. $\frac{144}{360} = \frac{2}{5}$ of the customers, and $\frac{2}{5} \times 1200 = 480$. (660 is the card customers, 180 is the cash customers, and 144 is the difference in degrees.)', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Card: 198/360 x 1200 = 660. Cash: 54/360 x 1200 = 180. Difference 660 - 180 = 480 (or 144/360 x 1200 = 480).","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e9a12af-65d8-4e3f-acd8-5ddb4f54dec6', 'NC26.7.RPR.3', 3, 'choice', 'Use a circle graph sector to find a count', 'A circle graph shows 480 survey responses. The sector for "never" is 15% of the circle and the sector for "sometimes" is 35% of the circle. The only other sector is "often". How many responses were "often"?', '["240","72","168","312"]', '240', '(1-0.15-0.35)*480', '"Often" is $100\% - 15\% - 35\% = 50\%$ of the circle, and 50% of 480 is 240. (72 is "never", 168 is "sometimes", and 312 is the responses that were not "sometimes".)', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Often = 100% - 15% - 35% = 50%; 0.5 x 480 = 240.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddfa4d6d-903d-44ee-992c-18230778a42a', 'NC26.7.RPR.3', 3, 'numeric', 'Use a circle graph sector to find a count', 'A circle graph shows the favorite subjects of 54 students. The sector for art measures 140 degrees. How many students chose art?', '[]', '21', '140/360*54', '$\frac{140}{360} \times 54$: first $54 \div 360 = 0.15$, then $0.15 \times 140 = 21$ students.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"140/360 = 7/18; 7/18 x 54 = 7 x 3 = 21 students.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
