INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89692bea-20d1-4a94-97f8-9454f9dfb113', 'NC26.7.RPR.3', 3, 'numeric', 'Use a circle graph sector to find the whole', 'A sector of 150 degrees on a circle graph stands for 35 customers. How many customers does the whole graph stand for?', '[]', '84', '35*360/150', '150 degrees is $\frac{150}{360} = \frac{5}{12}$ of the circle. If $\frac{5}{12}$ of the customers is 35, then $\frac{1}{12}$ is 7 and the whole is $7 \times 12 = 84$.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/360 = 5/12 is 35 customers; 1/12 is 7; whole = 7 x 12 = 84.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
