INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('194d7e57-7e03-423e-b32a-c5b7c0668b71', 'NC26.7.RPR.3', 3, 'choice', 'Use a circle graph sector to find the whole', 'In a circle graph, a sector that is $\frac{3}{8}$ of the whole circle stands for 27 students. How many students does the whole graph stand for?', '["216","72","30","9"]', '72', '27/(3/8)', 'If $\frac{3}{8}$ of the whole is 27, then $\frac{1}{8}$ is $27 \div 3 = 9$, and the whole is $9 \times 8 = 72$ students.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 is 27, so 1/8 is 9; whole = 9 x 8 = 72.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
