INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ee86646-ef1e-4a23-9777-b458e924ff94', 'NC26.7.RPR.3', 3, 'numeric', 'Use a circle graph sector to find the whole', 'In a circle graph, the soccer sector is 18% of the circle and the swimming sector is 32% of the circle. 28 more students chose swimming than soccer. How many students does the whole graph stand for?', '[]', '200', '28/0.14', 'Swimming is $32\% - 18\% = 14\%$ larger than soccer, and that difference is 28 students. The whole is $28 \div 0.14 = 200$ students.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Swimming - soccer = 32% - 18% = 14% of the whole = 28 students; whole = 28 / 0.14 = 200.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4ca4586-b445-4407-87ba-23805830fda9', 'NC26.7.RPR.3', 3, 'numeric', 'Find a missing sector of a circle graph', 'In a circle graph, one sector is 3 times as large as another sector, and the two sectors together are 40% of the circle. How many degrees does the larger sector measure?', '[]', '108', '0.4*360*3/4', '40% of 360 is 144 degrees. The sectors are in the ratio 3 to 1, so the larger one is $\frac{3}{4}$ of 144, which is 108 degrees.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Together 40% of 360 = 144 degrees. Parts 1:3, so 4 parts = 144, 1 part = 36; larger = 3 x 36 = 108 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb40dc2a-0f59-4fb6-a5ad-bd9d7935949e', 'NC26.7.RPR.3', 3, 'choice', 'Find a missing sector of a circle graph', 'A circle graph has four sectors. Sector A is $\frac{1}{4}$ of the circle, sector B is $\frac{1}{3}$ of the circle, and sector C is $\frac{1}{6}$ of the circle. How many degrees does sector D measure?', '["270","120","90","60"]', '90', '(1-1/4-1/3-1/6)*360', '$\frac{1}{4} + \frac{1}{3} + \frac{1}{6} = \frac{3}{12} + \frac{4}{12} + \frac{2}{12} = \frac{9}{12} = \frac{3}{4}$. So D is $\frac{1}{4}$ of 360, which is 90 degrees. (270 is the other three sectors together.)', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 + 1/3 + 1/6 = 3/12 + 4/12 + 2/12 = 9/12 = 3/4. D = 1/4 of 360 = 90 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b42ad21-4213-4fcf-8ed2-080128c557e4', 'NC26.7.RPR.3', 3, 'numeric', 'Compare sectors of a circle graph', 'In a circle graph, one sector is 25% of the circle and stands for 30 students. Another sector measures 150 degrees. How many students does the other sector stand for?', '[]', '50', '30/90*150', '25% of the circle is 90 degrees, and it stands for 30 students, so each 90 degrees is 30 students. 150 degrees stands for $30 \div 90 \times 150 = 50$ students.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% = 90 degrees stands for 30 students, so 3 degrees per student... i.e. 1 student per 3 degrees. 150 degrees -> 150/3 = 50 students. (Whole = 120; 150/360 x 120 = 50.)","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98fbefe1-08b3-4334-bcb1-f13a4e2b4faf', 'NC26.7.RPR.3', 3, 'choice', 'Compare sectors of a circle graph', 'In a circle graph, sector P is $\frac{1}{6}$ of the circle and sector Q measures 80 degrees. Which statement is true?', '["Sector Q is 20 degrees larger than sector P.","Sector P is 20 degrees larger than sector Q.","Sectors P and Q are the same size.","Sector Q is 80 degrees larger than sector P."]', 'Sector Q is 20 degrees larger than sector P.', NULL, 'Sector P is $\frac{1}{6} \times 360 = 60$ degrees. Sector Q is 80 degrees, which is $80 - 60 = 20$ degrees larger.', 'checked', '{"lint":[],"solve":{"answer":"Sector Q is 20 degrees larger than sector P.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 1/6 of 360 = 60 degrees; Q = 80 degrees. Q is 20 degrees larger than P.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6a8e10c-7cc2-4f87-b1b3-6995fc5c902a', 'NC26.7.RPR.3', 3, 'choice', 'Know that circumference divided by diameter is pi', 'Circle A has a circumference of 18.84 centimeters and a diameter of 6 centimeters. Circle B has a circumference of 43.96 centimeters and a diameter of 14 centimeters. Which statement is true?', '["Circle B has the greater circumference divided by diameter, because its circumference is greater.","Circle A has the greater circumference divided by diameter, because its diameter is smaller.","For both circles, circumference divided by diameter is 3.14.","The two values of circumference divided by diameter differ by 25.12."]', 'For both circles, circumference divided by diameter is 3.14.', NULL, '$18.84 \div 6 = 3.14$ and $43.96 \div 14 = 3.14$. The ratio is the same for every circle, whatever its size. (25.12 is the difference of the two circumferences.)', 'checked', '{"lint":[],"solve":{"answer":"For both circles, circumference divided by diameter is 3.14.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18.84 / 6 = 3.14; 43.96 / 14 = 3.14. Both ratios are 3.14; they do not differ.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e0b9b7e-0b87-45d8-99c4-85dd5e363d74', 'NC26.7.RPR.3', 3, 'numeric', 'Relate radius and diameter', 'The diameter of a circle is 5 centimeters longer than its radius. What is the diameter, in centimeters?', '[]', '10', '5*2', 'The diameter is twice the radius, so it is longer than the radius by exactly one radius. That means the radius is 5 centimeters, and the diameter is $2 \times 5 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 2r, so d - r = r = 5; d = 10 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8b31533-de54-4449-9dfc-9f23a1348844', 'NC26.7.RPR.3', 3, 'numeric', 'Find circumference from diameter', 'A circular pool has a diameter of 12.5 feet. Use 3.14 for $\pi$. A rope is wrapped once around the pool, and 1.5 feet more is added for a knot. How long is the rope, in feet?', '[]', '40.75', '3.14*12.5+1.5', 'Around the pool: $3.14 \times 12.5 = 39.25$ feet. Adding the knot, $39.25 + 1.5 = 40.75$ feet.', 'checked', '{"lint":[],"solve":{"answer":"40.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 12.5 = 39.25 ft; rope = 39.25 + 1.5 = 40.75 ft.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac893eab-1b3f-4401-977f-b55ff4fa3980', 'NC26.7.RPR.3', 3, 'choice', 'Find circumference from diameter', 'A circle has a diameter of 16 centimeters. A second circle has a diameter half as long. Use 3.14 for $\pi$. What is the circumference of the second circle, in centimeters?', '["50.24","12.56","100.48","25.12"]', '25.12', '3.14*16/2', 'The second diameter is $16 \div 2 = 8$ centimeters, so its circumference is $3.14 \times 8 = 25.12$ centimeters. (50.24 is the first circle, 12.56 halves twice, and 100.48 doubles.)', 'checked', '{"lint":[],"solve":{"answer":"25.12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second diameter = 16/2 = 8 cm; C = 3.14 x 8 = 25.12 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('833f80e1-1050-4662-9519-2710ef90706c', 'NC26.7.RPR.3', 3, 'numeric', 'Find circumference from radius', 'Two circles have the same center. The inner circle has a radius of 6 centimeters and the outer circle has a radius of 9 centimeters. Use 3.14 for $\pi$. How many centimeters longer is the circumference of the outer circle than the circumference of the inner circle?', '[]', '18.84', '2*3.14*(9-6)', 'Outer: $2 \times 3.14 \times 9 = 56.52$. Inner: $2 \times 3.14 \times 6 = 37.68$. The difference is $56.52 - 37.68 = 18.84$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"18.84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer C = 2 x 3.14 x 9 = 56.52; inner C = 2 x 3.14 x 6 = 37.68; difference = 18.84 cm (= 2 x 3.14 x 3).","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b016ba85-6ddb-4754-945c-d005691f7657', 'NC26.7.RPR.3', 3, 'numeric', 'Find circumference from radius', 'A round tabletop has a radius of $1\frac{3}{4}$ feet. Use $\frac{22}{7}$ for $\pi$. What is the distance around the tabletop, in feet?', '[]', '11', '2*22/7*(1+3/4)', '$1\frac{3}{4} = \frac{7}{4}$. Circumference $= 2 \times \frac{22}{7} \times \frac{7}{4} = \frac{44}{4} = 11$ feet.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 7/4 ft; d = 7/2; C = 22/7 x 7/2 = 11 ft.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f92e9a92-e746-422d-8f7f-dc6b229b367c', 'NC26.7.RPR.3', 3, 'choice', 'Find circumference from radius', 'Circle A has a radius of 4 centimeters. Circle B has a radius twice as long. Which statement about their circumferences is true?', '["The circumference of circle B is four times the circumference of circle A.","The circumference of circle B is 4 centimeters more than the circumference of circle A.","The circumference of circle B is twice the circumference of circle A.","The two circles have the same circumference."]', 'The circumference of circle B is twice the circumference of circle A.', NULL, 'The circumference is $2\pi r$, so doubling the radius doubles the circumference. For A it is $8\pi$ and for B it is $16\pi$. (Four times is what happens to the area, not the circumference.)', 'checked', '{"lint":[],"solve":{"answer":"The circumference of circle B is twice the circumference of circle A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r is proportional to r. Radius doubles (4 -> 8), so circumference doubles: 8pi vs 16pi. (Difference is 8pi, not 4.)","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d8ffcd1-d673-4e24-959a-1aa546314c19', 'NC26.7.RPR.3', 3, 'choice', 'Find diameter or radius from circumference', 'A circle has a circumference of 100.48 inches. Use 3.14 for $\pi$. What is the radius of the circle, in inches?', '["32","8","50.24","16"]', '16', '100.48/(2*3.14)', 'Diameter $= 100.48 \div 3.14 = 32$ inches, so the radius is $32 \div 2 = 16$ inches. (32 is the diameter, 8 halves twice, and 50.24 is half the circumference.)', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 100.48 / 3.14 = 32 in; r = 16 in.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b6c9bf-dd89-4411-b551-19ac8a7a9f8d', 'NC26.7.RPR.3', 3, 'numeric', 'Find diameter or radius from circumference', 'The distance around a circular garden is 75.36 meters. A straight path goes across the garden through its center. Use 3.14 for $\pi$. How long is the path, in meters?', '[]', '24', '75.36/3.14', 'A path through the center is a diameter. $75.36 \div 3.14 = 24$ meters.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The path through the center is a diameter: 75.36 / 3.14 = 24 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('124e3fa7-0ee8-4d99-97e9-b95f3c327f23', 'NC26.7.RPR.3', 3, 'numeric', 'Find diameter or radius from circumference', 'Circle A has a circumference of 31.4 centimeters. Circle B has a diameter that is 4 centimeters longer than the diameter of circle A. Use 3.14 for $\pi$. What is the diameter of circle B, in centimeters?', '[]', '14', '31.4/3.14+4', 'Diameter of A $= 31.4 \div 3.14 = 10$ centimeters. Circle B is 4 centimeters more: $10 + 4 = 14$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d_A = 31.4 / 3.14 = 10 cm; d_B = 10 + 4 = 14 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
