INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82108f31-22af-45b9-a92e-3744ac8b50ee', 'NC26.7.RPR.3', 3, 'numeric', 'Solve a problem using circumference', 'A wheel has a radius of 25 centimeters. Use 3.14 for $\pi$. How many full turns does the wheel make while rolling 15.7 meters in a straight line?', '[]', '10', '15.7*100/(2*3.14*25)', 'One turn is $2 \times 3.14 \times 25 = 157$ centimeters. The distance is $15.7 \times 100 = 1570$ centimeters. $1570 \div 157 = 10$ turns.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 25 = 157 cm = 1.57 m. 15.7 m / 1.57 m = 10 turns (or 1570 cm / 157 cm = 10).","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0829315-4447-42ad-994f-405602d1932e', 'NC26.7.RPR.3', 3, 'choice', 'Solve a problem using circumference', 'A circular track has a radius of 50 meters. Use 3.14 for $\pi$. Sam runs 5 laps and Lena runs 3 laps. How many more meters does Sam run than Lena?', '["628","314","1570","2512"]', '628', '2*3.14*50*(5-3)', 'One lap is $2 \times 3.14 \times 50 = 314$ meters. Sam runs 2 more laps than Lena: $2 \times 314 = 628$ meters. (314 is one lap, 1570 is Sam''s distance, and 2512 is the two runners together.)', 'checked', '{"lint":[],"solve":{"answer":"628","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 50 = 314 m. Sam runs 2 more laps: 2 x 314 = 628 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40f00ba3-f652-41ef-b9c9-906c9d411c7b', 'NC26.7.RPR.3', 3, 'numeric', 'Solve a problem using circumference', 'A circular pond has a diameter of 21 meters. Use $\frac{22}{7}$ for $\pi$. Posts are placed evenly all the way around the edge of the pond, 3 meters apart, so that the last post is 3 meters from the first. How many posts are needed?', '[]', '22', '22/7*21/3', 'The distance around the pond is $\frac{22}{7} \times 21 = 66$ meters. With a post every 3 meters all the way around, $66 \div 3 = 22$ posts.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 22/7 x 21 = 66 m. Around a closed loop with posts 3 m apart (last post 3 m from the first), number of posts = number of gaps = 66 / 3 = 22.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
