VALUES ('d1e8b1a7-0a94-4a8c-9e33-2096c7eed40e', 'NC26.7.ANR.1', 2, 'numeric', 'Add and subtract integers', 'Evaluate $-15 - (-23)$.', '[]', '8', '-15+23', 'Subtracting a negative is the same as adding its opposite: $-15 - (-23) = -15 + 23 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-15 - (-23) = -15 + 23 = 8.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
