VALUES ('6160da01-328d-4e0f-9418-b0f74553fa49', 'NC26.7.ANR.1', 2, 'choice', 'Multiply and divide integers', 'Which product is negative?', '["$(-1) \\times (-1) \\times (-6)$","$(-2) \\times (-7)$","$(-3) \\times 4 \\times (-5)$","$8 \\times 0 \\times (-4)$"]', '$(-1) \times (-1) \times (-6)$', NULL, '$(-1) \times (-1) \times (-6) = -6$. The others are $14$, $60$ and $0$.', 'checked', '{"lint":[],"solve":{"answer":"$(-1) \\times (-1) \\times (-6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1)(-1)(-6) = -6 (negative); (-3)(4)(-5) = 60; (-2)(-7) = 14; 8 x 0 x (-4) = 0 (not negative).","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
