INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d944deea-65b9-4d59-9ea5-2a32b1339dd7', 'NC26.7.ANR.1', 2, 'choice', 'Convert a fraction to a decimal', 'Which list shows the numbers in order from least to greatest? $\frac{3}{5}$, 0.65, $\frac{5}{8}$', '["$\\frac{3}{5}$, $\\frac{5}{8}$, 0.65","$\\frac{3}{5}$, 0.65, $\\frac{5}{8}$","0.65, $\\frac{5}{8}$, $\\frac{3}{5}$","$\\frac{5}{8}$, $\\frac{3}{5}$, 0.65"]', '$\frac{3}{5}$, $\frac{5}{8}$, 0.65', NULL, 'As decimals, $\frac{3}{5} = 0.6$, $\frac{5}{8} = 0.625$ and the third number is 0.65. From least to greatest: 0.6, 0.625, 0.65.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$, $\\frac{5}{8}$, 0.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 0.6, 5/8 = 0.625, 0.65. Least to greatest: 3/5, 5/8, 0.65.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
