INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8e08741-4fab-450a-8827-8163ef101016', 'NC26.7.ANR.1', 2, 'numeric', 'Tell terminating decimals from repeating decimals', 'The decimal for $\frac{4}{11}$ is $0.363636\ldots$ with the pattern 36 repeating. What is the 25th digit after the decimal point?', '[]', '3', NULL, 'The digits go 3, 6, 3, 6, ... The odd places hold 3 and the even places hold 6. Place 25 is odd, so the digit is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits after the point: odd positions are 3, even positions are 6. 25 is odd, so the 25th digit is 3.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
