INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da4a7f8-e9d2-4921-8802-2b496805510a', 'NC26.7.ANR.1', 2, 'choice', 'Check reasonableness by estimating', 'Lena adds $\frac{7}{8} + \frac{9}{10}$ and gets $\frac{16}{18}$. Which statement shows why her answer is not reasonable?', '["The sum of two fractions must be a whole number, and $\\frac{16}{18}$ is not.","Each fraction is close to 1, so the sum should be close to 2, but $\\frac{16}{18}$ is less than 1.","Fractions are added by multiplying, so the sum should be $\\frac{63}{80}$.","Her answer is greater than 1, but each of the two fractions is less than 1."]', 'Each fraction is close to 1, so the sum should be close to 2, but $\frac{16}{18}$ is less than 1.', NULL, '$\frac{7}{8}$ and $\frac{9}{10}$ are each a little less than 1, so their sum is a little less than 2. The answer $\frac{16}{18}$ is less than 1, which cannot be right. (The correct sum is $\frac{71}{40}$.)', 'checked', '{"lint":[],"solve":{"answer":"Each fraction is close to 1, so the sum should be close to 2, but $\\frac{16}{18}$ is less than 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 and 9/10 are each close to 1, so the sum is close to 2 (exact 1 31/40), but 16/18 < 1. A is false (sums need not be whole), B is wrong (fractions are not added by multiplying), C is false (16/18 is less than 1). D is correct.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0aab52a-b5e3-4a56-882a-219305c68fcf', 'NC26.7.ANR.1', 2, 'numeric', 'Check reasonableness by estimating', 'To estimate $-19.8 \div 4.1$, round $-19.8$ to $-20$ and 4.1 to 4. What is the estimate?', '[]', '-5', '-20/4', '$-20 \div 4 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-20 / 4 = -5.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae5e9d0-8a33-4d8a-acc5-f1b229b1b375', 'NC26.7.ANR.1', 2, 'choice', 'Check reasonableness by estimating', 'Which is the best estimate of $-\frac{11}{12} \times 7.8$?', '["-8","8","-0.8","-80"]', '-8', '-1*8', '$-\frac{11}{12}$ is close to $-1$ and 7.8 is close to 8, so the product is close to $-8$. (8 loses the sign, and -0.8 and -80 misplace the decimal point.)', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-11/12 ~ -1; -1 x 7.8 ~ -8 (exact -7.15). Best estimate -8.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28331bd3-a455-49c7-865e-1e4b00f1e02c', 'NC26.7.ANR.1', 2, 'choice', 'Use the order of operations with rational numbers', 'Evaluate $\frac{3}{4} + \frac{1}{2} \times \left(-\frac{5}{6}\right)$.', '["-25/24","7/6","5/12","1/3"]', '1/3', '3/4+1/2*(-5/6)', 'Multiply first: $\frac{1}{2} \times \left(-\frac{5}{6}\right) = -\frac{5}{12}$. Then $\frac{9}{12} - \frac{5}{12} = \frac{4}{12} = \frac{1}{3}$. (-25/24 adds first, and 7/6 loses the negative sign.)', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (-5/6) = -5/12; 3/4 - 5/12 = 9/12 - 5/12 = 4/12 = 1/3.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd8f3716-2579-4689-860c-c5331e48bac0', 'NC26.7.ANR.1', 2, 'numeric', 'Solve a problem with rational numbers', 'A bank account has a balance of $-45.50$ dollars. A deposit of 120 dollars is made, and then a payment of 38.75 dollars is taken out. What is the new balance, in dollars?', '[]', '35.75', '-45.5+120-38.75', '$-45.50 + 120 = 74.50$. Then $74.50 - 38.75 = 35.75$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"35.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-45.50 + 120 = 74.50; 74.50 - 38.75 = 35.75 dollars.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff392fd8-f8d6-48cc-bc19-ef95a0f907cc', 'NC26.7.ANR.1', 2, 'choice', 'Solve a problem with rational numbers', 'One batch of muffins needs $2\frac{1}{4}$ cups of flour. How many cups are needed for $2\frac{1}{2}$ batches?', '["4 1/8","4 3/4","6 1/4","5 5/8"]', '5 5/8', '9/4*5/2', '$2\frac{1}{4} \times 2\frac{1}{2} = \frac{9}{4} \times \frac{5}{2} = \frac{45}{8} = 5\frac{5}{8}$ cups. (4 1/8 multiplies the whole parts and fraction parts separately, and 4 3/4 adds.)', 'checked', '{"lint":[],"solve":{"answer":"5 5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/4 x 5/2 = 45/8 = 5 5/8 cups.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b886bba-3d62-40b1-a2f5-718cfe0b4d9c', 'NC26.7.ANR.1', 2, 'numeric', 'Solve a problem with rational numbers', 'The price of a share changed by $-1.25$ dollars each day for 5 days, and then rose by 2.4 dollars on the sixth day. What was the total change in the price, in dollars?', '[]', '-3.85', '-1.25*5+2.4', 'Five days of $-1.25$ is $-6.25$. Adding the rise: $-6.25 + 2.4 = -3.85$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"-3.85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x (-1.25) = -6.25; -6.25 + 2.4 = -3.85 dollars.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25f9806c-3ed1-4b1d-b0cc-350ac46778bf', 'NC26.7.ANR.1', 3, 'numeric', 'Evaluate with mixed numbers and several operations', 'Use the order of operations to find the value of $2\frac{1}{2} - 3\frac{3}{4} \div \left(-1\frac{1}{2}\right)$.', '[]', '5', '5/2-(15/4)/(-3/2)', 'Divide first: $3\frac{3}{4} \div \left(-1\frac{1}{2}\right) = \frac{15}{4} \times \left(-\frac{2}{3}\right) = -\frac{5}{2}$. Then $2\frac{1}{2} - \left(-\frac{5}{2}\right) = \frac{5}{2} + \frac{5}{2} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Division first: 3 3/4 / (-1 1/2) = (15/4) x (-2/3) = -30/12 = -5/2. Then 2 1/2 - (-5/2) = 5/2 + 5/2 = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af598a9-f169-4c9f-8a71-020501851feb', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'Which is the best estimate of $\frac{-39.8 \times 2.1}{4.2}$?', '["-20","-80","20","-200"]', '-20', '-20', 'Round: $-39.8 \approx -40$ and $2.1 \approx 2$, and $4.2 \approx 4$. Then $\frac{-40 \times 2}{4} = -20$. The answer is negative, and about 20 in size.', 'checked', '{"lint":[],"solve":{"answer":"-20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.1/4.2 = 1/2, so value = -39.8/2 = -19.9, about -20. Estimate: -40 x 2 / 4 = -20.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72f10b05-972f-47b5-906e-8310e6b7e7ba', 'NC26.7.ANR.1', 3, 'numeric', 'Solve a problem with mixed rational numbers', 'A diver is at $-12.5$ meters, which is 12.5 meters below the surface. She rises $3\frac{1}{4}$ meters and then dives down 5.75 meters. What is her final position, in meters?', '[]', '-15', '-12.5+3.25-5.75', 'Start at $-12.5$. Rising adds: $-12.5 + 3.25 = -9.25$. Diving subtracts: $-9.25 - 5.75 = -15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-12.5 + 3.25 = -9.25; -9.25 - 5.75 = -15 meters.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
