INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0029ad3-a65e-4346-9e92-9bac2405fbf9', 'NC26.7.ANR.1', 3, 'choice', 'Add and subtract integers', 'The difference of two integers, found by subtracting the second from the first, is $-17$. The first integer is $-8$. What is the second integer?', '["-9","-25","9","25"]', '9', '-8+17', 'We need $-8 - b = -17$. Then $b = -8 + 17 = 9$. Check: $-8 - 9 = -17$. (25 and $-25$ come from adding or subtracting the wrong way, and $-9$ loses the sign.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-8 - x = -17, so x = -8 + 17 = 9. Check: -8 - 9 = -17.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
