INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d689eda-9e59-46a8-9d93-316bb86c98d0', 'NC26.7.ANR.1', 3, 'numeric', 'Add and subtract fractions and mixed numbers', 'A tank holds $12\frac{1}{2}$ liters of water. Dan takes out $3\frac{3}{4}$ liters and then pours in $1\frac{7}{8}$ liters. How many liters are in the tank now?', '[]', '10 5/8', '25/2-15/4+15/8', 'In eighths: $\frac{100}{8} - \frac{30}{8} + \frac{15}{8} = \frac{85}{8} = 10\frac{5}{8}$ liters.', 'checked', '{"lint":[],"solve":{"answer":"10 5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 1/2 - 3 3/4 = 8 3/4; 8 3/4 + 1 7/8 = 8 6/8 + 1 7/8 = 9 13/8 = 10 5/8 L (10.625).","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
