INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6f84be5-3a6b-473c-a943-c08dd92e7ffa', 'NC26.7.ANR.1', 3, 'choice', 'Multiply and divide fractions and mixed numbers', 'Which value is equal to $\frac{3}{4} \div \left(-\frac{9}{16}\right)$?', '["4/3","-27/64","-3/4","-4/3"]', '-4/3', '3/4/(-9/16)', '$\frac{3}{4} \times \left(-\frac{16}{9}\right) = -\frac{48}{36} = -\frac{4}{3}$. (4/3 loses the sign, and -27/64 multiplies instead of dividing.)', 'checked', '{"lint":[],"solve":{"answer":"-4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x (-16/9) = -48/36 = -4/3.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
