INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9453249c-32d9-4056-b453-9a8cec3aea57', 'NC26.7.ANR.1', 3, 'choice', 'Add and subtract decimals', 'What is the value of $5.2 - 8.75 + (-3.6)$?', '["7.15","0.05","-3.55","-7.15"]', '-7.15', '5.2-8.75-3.6', '$5.2 - 8.75 = -3.55$, and $-3.55 + (-3.6) = -7.15$. (-3.55 leaves out the last term.)', 'checked', '{"lint":[],"solve":{"answer":"-7.15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.2 - 8.75 = -3.55; -3.55 + (-3.6) = -7.15.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
