INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3252e5be-dc30-46e9-8f4f-47772b56eaac', 'NC26.7.ANR.1', 3, 'choice', 'Add and subtract decimals', 'Which expression has the same value as $-4.3 - (-2.8)$?', '["$-4.3 - 2.8$","$-4.3 + 2.8$","$4.3 - 2.8$","$2.8 - (-4.3)$"]', '$-4.3 + 2.8$', NULL, 'Subtracting $-2.8$ is the same as adding 2.8, so $-4.3 - (-2.8) = -4.3 + 2.8 = -1.5$. The other three have the values $-7.1$, $1.5$ and $7.1$.', 'checked', '{"lint":[],"solve":{"answer":"$-4.3 + 2.8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4.3 - (-2.8) = -4.3 + 2.8 = -1.5. Others: -7.1, 1.5, 7.1.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb7e19ea-5553-465e-9d60-a5bb9e2a38ee', 'NC26.7.ANR.1', 3, 'numeric', 'Multiply and divide decimals', 'Find $(-1.2) \times 0.35 \times (-5)$.', '[]', '2.1', '-1.2*0.35*-5', 'Two negative factors make a positive product. $1.2 \times 0.35 = 0.42$ and $0.42 \times 5 = 2.1$.', 'checked', '{"lint":[],"solve":{"answer":"2.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1.2)(0.35) = -0.42; (-0.42)(-5) = 2.1.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
