VALUES ('5a31ca80-9069-4d96-846a-b48faba23004', 'NC26.7.ANR.1', 3, 'choice', 'Multiply and divide decimals', 'What is $-0.072 \div 0.09$?', '["-8","-0.8","-0.008","0.8"]', '-0.8', '-0.072/0.09', 'Multiply both numbers by 1000: $-72 \div 90 = -0.8$. (-8 misplaces the decimal point, and 0.8 loses the sign.)', 'checked', '{"lint":[],"solve":{"answer":"-0.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-0.072 / 0.09 = -7.2 / 9 = -0.8.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
