VALUES ('7dd00d89-4574-4905-a43c-ddfab9656448', 'NC26.7.ANR.1', 3, 'numeric', 'Convert a fraction to a decimal', 'Write $2\frac{7}{40}$ as a decimal.', '[]', '2.175', '2+7/40', '$7 \div 40 = 0.175$, so $2\frac{7}{40} = 2.175$.', 'checked', '{"lint":[],"solve":{"answer":"2.175","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/40 = 175/1000 = 0.175, so 2 7/40 = 2.175.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
