INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c66bcaf-14b6-4f1c-a593-fbbcb04eeac5', 'NC26.7.ANR.1', 3, 'choice', 'Convert a fraction to a decimal', 'Which decimal is equal to $-\frac{17}{25}$?', '["-0.17","-1.47","-6.8","-0.68"]', '-0.68', '-17/25', '$\frac{17}{25} = \frac{68}{100} = 0.68$, so $-\frac{17}{25} = -0.68$. (-0.17 uses only the top, and -1.47 divides 25 by 17.)', 'checked', '{"lint":[],"solve":{"answer":"-0.68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17/25 = 68/100 = 0.68, so -0.68.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
