INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c70a9ebc-566c-46e5-80cc-fd457a91df06', 'NC26.7.ANR.1', 3, 'numeric', 'Tell terminating decimals from repeating decimals', 'The decimal for $\frac{7}{30}$ is $0.2333\ldots$ with the 3 repeating forever. What is the sum of the first 10 digits after the decimal point?', '[]', '29', '2+9*3', 'The first digit is 2 and the next nine digits are all 3. The sum is $2 + 9 \times 3 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 10 digits: 2, then nine 3s. Sum = 2 + 9 x 3 = 29.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
