INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d55314a-8481-4df2-adfd-29e6f76ba8b4', 'NC26.7.ANR.1', 3, 'choice', 'Tell terminating decimals from repeating decimals', 'Which pair of fractions has decimals that both repeat forever?', '["$\\frac{1}{4}$ and $\\frac{2}{3}$","$\\frac{3}{5}$ and $\\frac{7}{9}$","$\\frac{1}{3}$ and $\\frac{5}{6}$","$\\frac{1}{8}$ and $\\frac{4}{15}$"]', '$\frac{1}{3}$ and $\frac{5}{6}$', NULL, '$\frac{1}{3} = 0.\overline{3}$ and $\frac{5}{6} = 0.8\overline{3}$ both repeat. In the other pairs, $\frac{1}{4} = 0.25$, $\frac{3}{5} = 0.6$ and $\frac{1}{8} = 0.125$ stop.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$ and $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 0.333..., 5/6 = 0.8333... both repeat. 1/4 = 0.25, 1/8 = 0.125, 3/5 = 0.6 terminate, so the other pairs fail.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f2b24c9-3eaf-4971-9a57-d610a7159dd7', 'NC26.7.ANR.1', 3, 'numeric', 'Write a rational number as a quotient of integers', 'Write $-2.35$ as a mixed number in simplest form.', '[]', '-2 7/20', '-2.35', '$0.35 = \frac{35}{100} = \frac{7}{20}$, so $-2.35 = -2\frac{7}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"-2 7/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.35 = 2 35/100 = 2 7/20, so -2.35 = -2 7/20.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
