INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee857f0c-47d2-4079-81fc-128d736f8c94', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'A student calculates $-48.3 \div 6.9$ and gets $-70$. Which is the best way to see that this answer is not reasonable?', '["A negative divided by a positive is positive.","48 divided by 7 is about 7, so the answer should be about $-7$.","48 divided by 7 is about 70, so the answer is close.","The answer should be positive because 48.3 is greater than 6.9."]', '48 divided by 7 is about 7, so the answer should be about $-7$.', NULL, 'Round to $-48 \div 7$, which is a little less than 7 in size, and the sign is negative. So the answer should be about $-7$, not $-70$. (The exact value is $-7$.)', 'checked', '{"lint":[],"solve":{"answer":"48 divided by 7 is about 7, so the answer should be about $-7$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48.3 / 6.9 ~ 48 / 7 ~ 7 (exact 7), and negative / positive is negative, so about -7, not -70. Option A is false (48/7 is not 70); B and C state wrong sign rules.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9a2dbf2-d0f0-461e-a68f-1aa84f1853e5', 'NC26.7.ANR.1', 3, 'numeric', 'Check reasonableness by estimating', 'Mia estimates $\frac{29.7 \times 4.1}{5.9}$ by rounding 29.7 to 30, 4.1 to 4 and 5.9 to 6. What is her estimate?', '[]', '20', '30*4/6', '$\frac{30 \times 4}{6} = \frac{120}{6} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 4 / 6 = 120 / 6 = 20.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
