INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7290cb5d-5af0-4e79-a1ec-ddd499fdf909', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'Which expression gives the best estimate of $-\frac{15}{16} \div 0.51$?', '["$-1 \\div 0.5$","$-1 \\div 5$","$1 \\div 0.5$","$-15 \\div 0.5$"]', '$-1 \div 0.5$', NULL, '$-\frac{15}{16}$ is close to $-1$ and 0.51 is close to 0.5, so the estimate is $-1 \div 0.5 = -2$. The other expressions change the size or the sign.', 'checked', '{"lint":[],"solve":{"answer":"$-1 \\div 0.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-15/16 ~ -1 and 0.51 ~ 0.5, so -1 / 0.5 (= -2; exact about -1.84). -15 / 0.5 is far too big, 1 / 0.5 has the wrong sign, -1 / 5 uses the wrong divisor.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acbee50f-b5a9-4642-aa1f-5125e8c244cd', 'NC26.7.ANR.1', 3, 'choice', 'Use the order of operations with rational numbers', 'What is the value of $2.5 - 1.5 \times (4 - 6.4)$?', '["6.1","-2.4","-9.9","-1.1"]', '6.1', '2.5-1.5*(4-6.4)', 'Parentheses first: $4 - 6.4 = -2.4$. Then multiply: $1.5 \times (-2.4) = -3.6$. Finally $2.5 - (-3.6) = 6.1$.', 'checked', '{"lint":[],"solve":{"answer":"6.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - 6.4 = -2.4; 1.5 x (-2.4) = -3.6; 2.5 - (-3.6) = 6.1.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f8826f0-958a-4bc0-b0ec-04e726c3fe70', 'NC26.7.ANR.1', 3, 'numeric', 'Use the order of operations with rational numbers', 'Evaluate $\left(-\frac{3}{4}\right)^2 \div \frac{9}{8} - 1$.', '[]', '-1/2', '(-3/4)^2/(9/8)-1', '$\left(-\frac{3}{4}\right)^2 = \frac{9}{16}$. Then $\frac{9}{16} \div \frac{9}{8} = \frac{9}{16} \times \frac{8}{9} = \frac{1}{2}$. Finally $\frac{1}{2} - 1 = -\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3/4)^2 = 9/16; 9/16 / (9/8) = 9/16 x 8/9 = 1/2; 1/2 - 1 = -1/2.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8de7552-b986-43d5-be39-9831fd3cc195', 'NC26.7.ANR.1', 3, 'numeric', 'Use the order of operations with rational numbers', 'Evaluate $\frac{-2.4 + 0.6 \times 5}{-0.3}$.', '[]', '-2', '(-2.4+0.6*5)/(-0.3)', 'In the top, multiply first: $0.6 \times 5 = 3$, so the top is $-2.4 + 3 = 0.6$. Then $0.6 \div (-0.3) = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator: 0.6 x 5 = 3; -2.4 + 3 = 0.6. 0.6 / (-0.3) = -2.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
