INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1251c8f-3322-466a-9dcd-4dfd5273ba94', 'NC26.7.ANR.1', 3, 'choice', 'Solve a problem with rational numbers', 'A tank is $\frac{5}{6}$ full. Jo uses $\frac{1}{4}$ of the water in the tank. What fraction of the whole tank is now full?', '["7/12","5/24","5/8","1/12"]', '5/8', '5/6*(1-1/4)', 'What is left is $1 - \frac{1}{4} = \frac{3}{4}$ of the water, so $\frac{3}{4} \times \frac{5}{6} = \frac{15}{24} = \frac{5}{8}$ of the tank. (7/12 takes $\frac{1}{4}$ of the tank, and 5/24 is the amount used.)', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She uses 1/4 of the water, leaving 3/4 of it: 3/4 x 5/6 = 15/24 = 5/8 of the tank.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a357227-68a6-4c5e-a758-1f7ac2aa7755', 'NC26.7.ANR.1', 3, 'choice', 'Solve a problem with rational numbers', 'A 9.5-meter ribbon is cut into pieces that are each 1.2 meters long. After as many whole pieces as possible are cut, how many meters of ribbon are left over?', '["8.4","7","1.1","0.9"]', '1.1', '9.5-7*1.2', '$9.5 \div 1.2$ is about 7.9, so 7 whole pieces can be cut. They use $7 \times 1.2 = 8.4$ meters, leaving $9.5 - 8.4 = 1.1$ meters. (8.4 is the ribbon used, 7 is the number of pieces, and 0.9 reads the decimal part of 7.9 as meters.)', 'checked', '{"lint":[],"solve":{"answer":"1.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9.5 / 1.2 = 7.9..., so 7 whole pieces use 7 x 1.2 = 8.4 m; left over 9.5 - 8.4 = 1.1 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f4e1f03-231b-404f-ad26-07b2a2fd2bf4', 'NC26.7.ANR.1', 3, 'numeric', 'Solve a problem with rational numbers', 'A hiker walks $2\frac{1}{2}$ miles in $\frac{3}{4}$ of an hour. At the same steady speed, how many miles does she walk in 1 hour?', '[]', '3 1/3', '5/2/(3/4)', '$2\frac{1}{2} \div \frac{3}{4} = \frac{5}{2} \times \frac{4}{3} = \frac{20}{6} = 3\frac{1}{3}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"3 1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Speed = 2 1/2 / (3/4) = 5/2 x 4/3 = 20/6 = 10/3 = 3 1/3 miles per hour.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbd83b50-7a18-4409-8a6f-810a53034d43', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which expression is equivalent to $4x + 7 + 2x - 3$?', '["$6x + 4$","$13x$","$6x + 10$","$6x - 4$"]', '$6x + 4$', NULL, 'Combine the $x$ terms: $4x + 2x = 6x$. Combine the numbers: $7 - 3 = 4$. The result is $6x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 2x = 6x; 7 - 3 = 4. So 6x + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b65b4f4-55c6-495b-bbea-b17f29480c0a', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'The expression $3(x + 4)$ is equivalent to $3x + k$. What is the value of $k$?', '[]', '12', '3*4', 'Distribute: $3(x + 4) = 3x + 3 \times 4 = 3x + 12$, so $k = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 4) = 3x + 12, so k = 12.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf151c3-713f-4b6d-9f40-1921aadeb945', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $6x + 9$?', '["$6(x + 3)$","$3(2x + 9)$","$3(x + 3)$","$3(2x + 3)$"]', '$3(2x + 3)$', NULL, '6 and 9 have the common factor 3. $6x \div 3 = 2x$ and $9 \div 3 = 3$, so $6x + 9 = 3(2x + 3)$. Multiplying back gives $6x + 9$.', 'checked', '{"lint":[],"solve":{"answer":"$3(2x + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+3) = 3x+9 no; 3(2x+9) = 6x+27 no; 3(2x+3) = 6x+9 yes; 6(x+3) = 6x+18 no.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d554de3a-0085-4f85-80fe-4cb9fe7c9a7c', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which expression is equivalent to $7x + 2x$?', '["$9x$","$14x$","$5x$","$9x^2$"]', '$9x$', NULL, '$7x$ and $2x$ are like terms, so add their coefficients: 7 + 2 = 9. The result is $9x$. (14x multiplies the coefficients, 5x subtracts them, and 9x^2 wrongly changes the exponent.)', 'checked', '{"lint":[],"solve":{"answer":"$9x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x + 2x = (7+2)x = 9x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be082eec-cf8f-4e24-b51a-5d68e822dfa8', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'Mia writes $6n + 8 - 2n$ in simplest form as $an + 8$. What is the value of $a$?', '[]', '4', '6-2', 'Combine the like terms $6n$ and $-2n$: 6 - 2 = 4. So $6n + 8 - 2n = 4n + 8$ and a = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6n - 2n = 4n, so 6n + 8 - 2n = 4n + 8; a = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1a6a96c-0e06-4cde-9e7f-ff96d8904ef8', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which two terms are like terms?', '["$3x$ and $5$","$3x$ and $5x$","$3x$ and $3y$","$3x$ and $3x^2$"]', '$3x$ and $5x$', NULL, 'Like terms have exactly the same variable part. $3x$ and $5x$ both have $x$, so they are like terms and can be combined. A number alone, a different letter, or $x^2$ is a different kind of term.', 'checked', '{"lint":[],"solve":{"answer":"$3x$ and $5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Like terms have the same variable to the same power: 3x and 5x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c534e05d-8472-4a71-a65f-0d105fc1523c', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'What is the coefficient of $y$ in the simplified form of $10y - 4y + 3$?', '[]', '6', '10-4', '$10y - 4y = 6y$, so the simplified form is $6y + 3$. The coefficient of $y$ is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10y - 4y + 3 = 6y + 3; coefficient 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
