INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a7e9dc-50c1-4418-90af-d831f516b62c', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'A square has sides that each measure $x$ units. Its perimeter is $x + x + x + x$, which is equivalent to $kx$. What is the value of $k$?', '[]', '4', '1+1+1+1', 'Adding $x$ four times gives 4 groups of $x$, which is $4x$. So k = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + x + x = 4x; k = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd302a88-b18c-4bc3-825f-4efa6a1d81cd', 'NC26.7.ANR.2', 1, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $4(n + 3)$?', '["$4n + 3$","$n + 12$","$4n + 7$","$4n + 12$"]', '$4n + 12$', NULL, 'Multiply 4 by each term inside the parentheses: 4 times $n$ is $4n$ and 4 times 3 is 12. The result is $4n + 12$. (4n + 3 forgets to multiply the 3.)', 'checked', '{"lint":[],"solve":{"answer":"$4n + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(n + 3) = 4n + 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('220da562-c828-4a49-b2d6-74242357a9bc', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'In the equation $5(x + 3) = 5x + k$, the number $k$ makes both sides equal for every value of $x$. What is $k$?', '[]', '15', '5*3', 'By the distributive property, $5(x + 3) = 5x + 5 \times 3 = 5x + 15$. So k = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x + 3) = 5x + 15, so k = 15.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('694868cd-60aa-4f58-b647-0aa7c500777a', 'NC26.7.ANR.2', 1, 'choice', 'Expand with the distributive property', 'A rectangle is 6 units wide and $(y + 2)$ units long. Which expression, written without parentheses, gives its area in square units?', '["$6y + 2$","$y + 12$","$6y + 12$","$6y + 8$"]', '$6y + 12$', NULL, 'Area is width times length: $6(y + 2)$. Distribute the 6: 6 times $y$ is $6y$ and 6 times 2 is 12, so the area is $6y + 12$.', 'checked', '{"lint":[],"solve":{"answer":"$6y + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 6(y + 2) = 6y + 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cae6892-7dc3-44fa-ae8d-18619c50a6fe', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'Using the distributive property, $2(x + 9)$ can be written as $ax + b$. What is the value of $a + b$?', '[]', '20', '2+2*9', '$2(x + 9) = 2x + 18$, so a = 2 and b = 18. Then a + b = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x + 9) = 2x + 18; a = 2, b = 18; a + b = 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d298040c-480d-4b10-920f-d41f56bc4f49', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $5x + 10$?', '["$5(x + 10)$","$10(x + 5)$","$x(5 + 10)$","$5(x + 2)$"]', '$5(x + 2)$', NULL, 'Both terms have a factor of 5: $5x = 5 \times x$ and $10 = 5 \times 2$. So $5x + 10 = 5(x + 2)$. Check by distributing: $5(x + 2) = 5x + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$5(x + 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x + 2) = 5x + 10. Others: 5x+50, 15x, 10x+50.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c0c3e3-ff01-43af-8ce5-37c0174da0dc', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'To factor $12x + 20$, Lena first looks for the greatest common factor of 12 and 20. What is it?', '[]', '4', NULL, 'The factors of 12 are 1, 2, 3, 4, 6, 12 and the factors of 20 are 1, 2, 4, 5, 10, 20. The greatest factor in both lists is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 12: 1,2,3,4,6,12; of 20: 1,2,4,5,10,20. GCF = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d109f3ab-960a-4ec3-ad85-47c40d923c92', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'Fill in the missing number: $4x + 20 = 4(x + k)$. What is the value of $k$?', '[]', '5', '20/4', 'Since 4 times k must equal 20, k = 20 / 4 = 5. Check: $4(x + 5) = 4x + 20$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + k) = 4x + 4k = 4x + 20, so 4k = 20, k = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c70c362-897b-4ffe-9b36-c3aaad655006', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $3a + 3b$?', '["$3ab$","$6(a + b)$","$3(a + b)$","$a + b + 3$"]', '$3(a + b)$', NULL, 'Both terms have a factor of 3, so $3a + 3b = 3(a + b)$. (3ab multiplies instead of adding, and 6(a + b) = 6a + 6b.)', 'checked', '{"lint":[],"solve":{"answer":"$3(a + b)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a + 3b = 3(a + b).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('785b4bca-ca54-481c-8b34-4ca2666cb4c9', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'Fill in the missing number so that $10 + 5y = 5(k + y)$ for every value of $y$. What is $k$?', '[]', '2', '10/5', 'The number 10 is 5 times 2, so $10 + 5y = 5(2 + y)$ and k = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(k + y) = 5k + 5y = 10 + 5y, so 5k = 10, k = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65a20628-8b99-47c5-a45d-a9b97fe9769b', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Which expression is NOT equivalent to $2x + 6$?', '["$8x$","$2(x + 3)$","$6 + 2x$","$x + x + 6$"]', '$8x$', NULL, '$2(x + 3) = 2x + 6$, $6 + 2x$ is the same sum in a different order, and $x + x + 6 = 2x + 6$. But $2x + 6$ cannot be combined into $8x$, because $2x$ and 6 are not like terms. The answer is $8x$.', 'checked', '{"lint":[],"solve":{"answer":"$8x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 2x (commutative), 2(x+3) = 2x+6, x+x+6 = 2x+6 are equivalent; 8x is not (unlike terms cannot combine).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bc236d1-6b3e-4ddd-8955-0c499c58951a', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Ana, Ben and Cy each simplify $3x + 4x$. Ana gets $7x$, Ben gets $12x$ and Cy gets $7x^2$. Who is correct?', '["Ben","Ana","Cy","Ana and Ben"]', 'Ana', NULL, 'Like terms are combined by adding their coefficients: 3 + 4 = 7, and the variable part stays $x$. So $3x + 4x = 7x$ and only Ana is correct.', 'checked', '{"lint":[],"solve":{"answer":"Ana","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 4x = 7x. Ana is right; Ben multiplied, Cy multiplied the variables.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed2f43c2-9d4e-45fa-8d38-27c68b6e3071', 'NC26.7.ANR.2', 1, 'numeric', 'Decide whether two expressions are equivalent', 'Both $4(x + 2)$ and $4x + 8$ have the same value for every number $x$. What is that value when $x = 3$?', '[]', '20', '4*(3+2)', 'Using the first form, $4(3 + 2) = 4 \times 5 = 20$. Using the second, $4 \times 3 + 8 = 12 + 8 = 20$. The values match.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(3 + 2) = 20; 4(3) + 8 = 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96560063-efae-4196-80e9-0dc216329340', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Which equation is true for every value of $x$?', '["$3(x + 1) = 3x + 3$","$3(x + 1) = 3x + 1$","$3(x + 1) = x + 3$","$3(x + 1) = 3x + x + 1$"]', '$3(x + 1) = 3x + 3$', NULL, 'Distribute the 3 on the left: $3(x + 1) = 3x + 3$, which matches the right side exactly. In the other equations the two sides differ for most values of $x$ (try x = 2).', 'checked', '{"lint":[],"solve":{"answer":"$3(x + 1) = 3x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 1) = 3x + 3 for every x. Others fail, e.g. x = 1: 6 vs 4, 6 vs 5, 6 vs 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a44d5a9f-6cf3-4366-aadf-0b890082ea1d', 'NC26.7.ANR.2', 1, 'choice', 'Expressions with fraction or decimal coefficients', 'Which expression is equivalent to $0.5x + 0.5x$?', '["$0.25x$","$x$","$0.5x$","$1.5x$"]', '$x$', NULL, 'Add the coefficients: 0.5 + 0.5 = 1, so the sum is 1 group of $x$, which is $x$.', 'checked', '{"lint":[],"solve":{"answer":"$x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5x + 0.5x = 1x = x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
