INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05109b40-938f-4079-bb8e-b2de35c310c0', 'NC26.7.ANR.2', 1, 'numeric', 'Use the distributive property to write an equivalent expression', 'The expression $3(x + 4)$ is equivalent to $3x + \square$. What number goes in the box?', '[]', '12', '3*4', 'Multiply each part inside the parentheses by 3: $3(x + 4) = 3 \times x + 3 \times 4 = 3x + 12$. The number in the box is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+4)=3x+12.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80fc6ada-e220-4b6b-bd9c-16a84c850639', 'NC26.7.ANR.2', 2, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $2(3x - 4) + 5x$?', '["$11x - 4$","$11x - 8$","$11x + 8$","$x - 8$"]', '$11x - 8$', NULL, 'Distribute: $2(3x - 4) = 6x - 8$. Add $5x$: $6x + 5x - 8 = 11x - 8$.', 'checked', '{"lint":[],"solve":{"answer":"$11x - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3x - 4) = 6x - 8; plus 5x gives 11x - 8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d65d561-3dfe-493d-8cb4-b02ac3332335', 'NC26.7.ANR.2', 2, 'numeric', 'Distribute a negative factor', 'The expression $-2(x - 3) + 4x$ is equivalent to $2x + k$. What is the value of $k$?', '[]', '6', '(-2)*(-3)', 'Distribute: $-2(x - 3) = -2x + 6$. Then $-2x + 6 + 4x = 2x + 6$, so $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(x - 3) = -2x + 6; plus 4x gives 2x + 6, so k = 6.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f843ccb6-cea1-470c-8557-c47d31625ddb', 'NC26.7.ANR.2', 2, 'numeric', 'Factor a linear expression and read the factors', 'The expression $12x + 18$ can be written as $6(ax + b)$. What is the value of $a + b$?', '[]', '5', '12/6+18/6', '$12x \div 6 = 2x$ and $18 \div 6 = 3$, so $12x + 18 = 6(2x + 3)$. Then $a = 2$, $b = 3$ and $a + b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(ax + b) = 6ax + 6b = 12x + 18, so a = 2, b = 3 (unique). a + b = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c0d937c-651e-4f82-afa2-6cf0b2b307d6', 'NC26.7.ANR.2', 2, 'numeric', 'Combine like terms', 'How many terms does the simplest form of $3x + 2 + 5x - 2$ have?', '[]', '1', NULL, 'Combine the $x$ terms: 3x + 5x = 8x. Combine the numbers: 2 - 2 = 0. The simplest form is $8x$, which has just 1 term.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 5x = 8x; 2 - 2 = 0. Simplest form 8x has 1 term.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abb29681-c7fd-404b-b7ca-f5d73c35b1b7', 'NC26.7.ANR.2', 2, 'choice', 'Combine like terms', 'Which expression is equivalent to $4a - 7 + 3a + 10$?', '["$7a - 3$","$7a + 17$","$7a - 17$","$7a + 3$"]', '$7a + 3$', NULL, 'Combine the $a$ terms: 4a + 3a = 7a. Combine the numbers: -7 + 10 = 3. The result is $7a + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$7a + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a + 3a = 7a; -7 + 10 = 3: 7a + 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92f9df2b-433f-4497-a926-51f13da944c3', 'NC26.7.ANR.2', 2, 'numeric', 'Combine like terms', 'The expression $9x - 4 - 6x - 5$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '-9', '-4-5', 'The numbers are -4 and -5, which combine to -9. (The $x$ terms give 9x - 6x = 3x.) So $9x - 4 - 6x - 5 = 3x - 9$ and b = -9.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x - 6x = 3x; -4 - 5 = -9: 3x - 9, b = -9.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8221185e-5d2e-471e-813b-14ea4bed8654', 'NC26.7.ANR.2', 2, 'choice', 'Combine like terms', 'Which expression is equivalent to $5x + 3y - 2x + y$?', '["$3x + 4y$","$3x + 2y$","$7x + 4y$","$3x + 3y$"]', '$3x + 4y$', NULL, 'Combine the $x$ terms: 5x - 2x = 3x. Combine the $y$ terms: 3y + y = 4y (remember $y$ means 1y). The result is $3x + 4y$.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 4y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 2x = 3x; 3y + y = 4y: 3x + 4y.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('674f6224-fae8-45bd-ba30-a99559a92a06', 'NC26.7.ANR.2', 2, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $-3(x + 4)$?', '["$-3x + 12$","$3x - 12$","$-3x - 12$","$-3x + 4$"]', '$-3x - 12$', NULL, 'Multiply -3 by each term: (-3)(x) = -3x and (-3)(4) = -12. The result is $-3x - 12$.', 'checked', '{"lint":[],"solve":{"answer":"$-3x - 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3(x) + (-3)(4) = -3x - 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6fbd0c3-88a4-4428-b3af-b3eb4f1eb7b4', 'NC26.7.ANR.2', 2, 'numeric', 'Expand with the distributive property', 'The expression $-4(2x - 5)$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '20', '(-4)*(-5)', 'Multiply -4 by each term: (-4)(2x) = -8x and (-4)(-5) = +20. So $-4(2x - 5) = -8x + 20$ and b = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4(2x) = -8x; -4(-5) = 20: -8x + 20, b = 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1af77eb0-1121-43fb-9766-bcdbe28f7624', 'NC26.7.ANR.2', 2, 'choice', 'Expand with the distributive property', 'Which expression, written without parentheses, gives the area of a rectangle that is 5 units wide and $(x - 2)$ units long?', '["$5x - 2$","$5x - 10$","$5x + 10$","$x - 10$"]', '$5x - 10$', NULL, 'Area is width times length: $5(x - 2)$. Distribute the 5: $5x - 10$.', 'checked', '{"lint":[],"solve":{"answer":"$5x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x - 2) = 5x - 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
