INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c06bec2-b5c9-4a98-9fc2-0a446c8b05eb', 'NC26.7.ANR.2', 2, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $3(x + 2) + 4x$?', '["$7x + 2$","$7x + 6$","$12x$","$7x + 5$"]', '$7x + 6$', NULL, 'Distribute: $3(x + 2) = 3x + 6$. Then add $4x$: $3x + 6 + 4x = 7x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$7x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 6 + 4x = 7x + 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c3c2d08-4584-4be2-88db-6686316076c0', 'NC26.7.ANR.2', 2, 'numeric', 'Distribute and combine like terms', 'The expression $5(x + 1) + 2(x + 3)$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '18', '5+2+5*1+2*3', 'Distribute: $5(x + 1) = 5x + 5$ and $2(x + 3) = 2x + 6$. Add: 5x + 2x = 7x and 5 + 6 = 11, so the expression is $7x + 11$. Then a + b = 7 + 11 = 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 5 + 2x + 6 = 7x + 11; a + b = 18.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e1c531b-999e-41c9-a9bc-452f2f47b8dd', 'NC26.7.ANR.2', 2, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $6x - 2(x + 5)$?', '["$4x + 10$","$4x - 5$","$8x - 10$","$4x - 10$"]', '$4x - 10$', NULL, 'Distribute -2: (-2)(x) = -2x and (-2)(5) = -10. Then $6x - 2x - 10 = 4x - 10$. (4x + 10 loses the sign on the 10.)', 'checked', '{"lint":[],"solve":{"answer":"$4x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 2x - 10 = 4x - 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66ff1f60-c487-4dfe-bd44-3ceba39834a2', 'NC26.7.ANR.2', 2, 'numeric', 'Distribute and combine like terms', 'Maya simplifies $7 + 2(3x - 1)$ and writes the result as $ax + b$. What is the value of $b$?', '[]', '5', '7-2', 'Distribute the 2 first: $2(3x - 1) = 6x - 2$. Then $7 + 6x - 2 = 6x + 5$, so b = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 6x - 2 = 6x + 5; b = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40d22fad-5a0d-4202-ade0-1bfa415062d6', 'NC26.7.ANR.2', 2, 'choice', 'Factor out a common factor', 'Which expression shows $8x + 20$ with its greatest common factor factored out?', '["$4(2x + 5)$","$2(4x + 10)$","$4(2x + 20)$","$8(x + 20)$"]', '$4(2x + 5)$', NULL, 'The greatest common factor of 8 and 20 is 4. Factor it out: $8x + 20 = 4(2x + 5)$. (2(4x + 10) is also equal to 8x + 20, but it only takes out 2, not the greatest common factor.)', 'checked', '{"lint":[],"solve":{"answer":"$4(2x + 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(8, 20) = 4; 8x + 20 = 4(2x + 5). 2(4x + 10) is equivalent but 2 is not the greatest common factor; others are not equivalent.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1bb7da4-576f-40e3-abf6-b17852bbb560', 'NC26.7.ANR.2', 2, 'numeric', 'Factor out a common factor', 'The expression $15x - 25$ can be written as $5(ax - b)$, where a and b are positive whole numbers. What is the value of $a + b$?', '[]', '8', '15/5+25/5', 'Divide each term by 5: 15x / 5 = 3x and 25 / 5 = 5. So $15x - 25 = 5(3x - 5)$, a = 3 and b = 5, and a + b = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15x - 25 = 5(3x - 5); a = 3, b = 5; a + b = 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1817d85-7f91-4668-825e-a2682fd94d36', 'NC26.7.ANR.2', 2, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $6x + 6$?', '["$6(x + 6)$","$x(6 + 6)$","$6(x + 1)$","$6x + 1$"]', '$6(x + 1)$', NULL, 'Both terms have a factor of 6, and the second term is 6 = 6 times 1. So $6x + 6 = 6(x + 1)$. (6(x + 6) = 6x + 36.)', 'checked', '{"lint":[],"solve":{"answer":"$6(x + 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(x + 1) = 6x + 6. 6(x+6) = 6x+36, x(6+6) = 12x, 6x + 1 differ.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74cf56b7-f821-4ae7-ab34-af72498a704e', 'NC26.7.ANR.2', 2, 'numeric', 'Factor out a common factor', 'The expression $14x + 21$ can be written as $7(ax + b)$. What is the value of $a \times b$?', '[]', '6', '(14/7)*(21/7)', 'Divide each term by 7: 14x / 7 = 2x and 21 / 7 = 3. So $14x + 21 = 7(2x + 3)$, $a = 2$, $b = 3$ and $a \times b = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14x + 21 = 7(2x + 3); a = 2, b = 3; a x b = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('687298bf-556b-440b-94e5-538de38e070d', 'NC26.7.ANR.2', 2, 'choice', 'Decide whether two expressions are equivalent', 'Which pair of expressions is equivalent?', '["$2(x + 5)$ and $2x + 10$","$4(x + 1)$ and $4x + 1$","$3(x - 1)$ and $3x - 1$","$5(2x + 1)$ and $7x + 6$"]', '$2(x + 5)$ and $2x + 10$', NULL, 'Distribute in the first expression of each pair. $2(x + 5) = 2x + 10$, which matches. In the other pairs, the distributed form is $4x + 4$, $3x - 3$ and $10x + 5$, which do not match.', 'checked', '{"lint":[],"solve":{"answer":"$2(x + 5)$ and $2x + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x + 5) = 2x + 10. Others: 4x+4 vs 4x+1; 10x+5 vs 7x+6; 3x-3 vs 3x-1.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a572771e-e908-42a7-85b8-bfbcff25c559', 'NC26.7.ANR.2', 2, 'choice', 'Decide whether two expressions are equivalent', 'Which expression is NOT equivalent to $5x - 10$?', '["$5(x - 2)$","$-10 + 5x$","$5(x + 2)$","$10(0.5x - 1)$"]', '$5(x + 2)$', NULL, '$5(x - 2) = 5x - 10$, $-10 + 5x$ is the same sum in another order, and $10(0.5x - 1) = 5x - 10$. But $5(x + 2) = 5x + 10$, which is different.', 'checked', '{"lint":[],"solve":{"answer":"$5(x + 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x-2) = 5x-10; 10(0.5x - 1) = 5x - 10; -10 + 5x = 5x - 10; 5(x + 2) = 5x + 10, not equivalent.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa0bfeac-1ef4-4778-9e2f-b994634295f7', 'NC26.7.ANR.2', 2, 'numeric', 'Decide whether two expressions are equivalent', 'What value of $k$ makes $2(3x + k)$ equivalent to $6x + 14$?', '[]', '7', '14/2', 'Distribute: $2(3x + k) = 6x + 2k$. For this to equal $6x + 14$, 2k = 14, so k = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3x + k) = 6x + 2k = 6x + 14, so k = 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1d2d0f5-979c-4a44-a8f1-6d62fc7b04e5', 'NC26.7.ANR.2', 2, 'choice', 'Expressions with fraction or decimal coefficients', 'Which expression is equivalent to $\frac{1}{3}(9x - 6)$?', '["$3x - 6$","$9x - 2$","$3x + 2$","$3x - 2$"]', '$3x - 2$', NULL, 'Multiply each term by one third: (1/3)(9x) = 3x and (1/3)(6) = 2. So $\frac{1}{3}(9x - 6) = 3x - 2$. (3x - 6 only divides the first term.)', 'checked', '{"lint":[],"solve":{"answer":"$3x - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)(9x) = 3x; (1/3)(-6) = -2: 3x - 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fd79528-3859-43a1-991f-60e4e54cd603', 'NC26.7.ANR.2', 2, 'numeric', 'Expressions with fraction or decimal coefficients', 'The expression $0.5(6x + 4)$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '5', '0.5*6+0.5*4', 'Half of 6x is 3x and half of 4 is 2, so $0.5(6x + 4) = 3x + 2$. Then a + b = 3 + 2 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5(6x) + 0.5(4) = 3x + 2; a + b = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76e64b53-0373-4700-9574-e6b7696e84f5', 'NC26.7.ANR.2', 2, 'numeric', 'Expressions with fraction or decimal coefficients', 'Combine the like terms: $\frac{1}{2}x + \frac{1}{4}x$ is the same as $kx$. What is the value of $k$? Give your answer as a fraction.', '[]', '3/4', '1/2+1/4', 'Rewrite with a common denominator: $\frac{1}{2} = \frac{2}{4}$. Then $\frac{2}{4} + \frac{1}{4} = \frac{3}{4}$, so k = 3/4.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 + 1/4 = 2/4 + 1/4 = 3/4; k = 3/4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbda67c0-f704-406e-ab5e-816af7322291', 'NC26.7.ANR.2', 2, 'choice', 'Write an expression for a situation', 'A video game costs $g$ dollars. Lena buys 3 of them and then uses a coupon that takes 5 dollars off the total. Which expression shows what she pays, in dollars?', '["$3(g - 5)$","$3g - 5$","$3g + 5$","$g - 5$"]', '$3g - 5$', NULL, 'Three games cost $3g$ dollars. The coupon takes 5 dollars off the total, so she pays $3g - 5$. (3(g - 5) would take 5 dollars off each game.)', 'checked', '{"lint":[],"solve":{"answer":"$3g - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 games cost 3g; 5 off the total: 3g - 5. 3(g - 5) would take 5 off each game.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('811aa85b-ec49-4ab6-b821-8fb0bb6c540f', 'NC26.7.ANR.2', 2, 'numeric', 'Write an expression for a situation', 'A rectangle has length $(2w + 1)$ and width $w$. Its perimeter in simplest form is $aw + b$. What is the value of $a + b$?', '[]', '8', '6+2', 'The perimeter is $2(2w + 1) + 2w$. Distribute: $4w + 2 + 2w = 6w + 2$. So a = 6, b = 2 and a + b = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 2(2w + 1) + 2w = 4w + 2 + 2w = 6w + 2; a + b = 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8141912c-2010-4e68-8871-cdcca680577d', 'NC26.7.ANR.2', 2, 'choice', 'Write an expression for a situation', 'Tia has $x$ stickers. Ben has 3 more than twice as many as Tia. Which expression shows how many stickers the two of them have together?', '["$3x + 3$","$2x + 3$","$3x + 6$","$x + 6$"]', '$3x + 3$', NULL, 'Ben has $2x + 3$ stickers. Together: $x + (2x + 3) = 3x + 3$. (2x + 3 is only Ben.)', 'checked', '{"lint":[],"solve":{"answer":"$3x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ben has 2x + 3; together x + 2x + 3 = 3x + 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5b9b35d-2d4d-43c9-bdbd-9ad4e6b2e267', 'NC26.7.ANR.2', 2, 'choice', 'What an equivalent form shows in context', 'A store raises every price by 10 percent. A price of $p$ dollars becomes $p + 0.1p$ dollars. Which expression is equivalent to the new price?', '["$0.1p$","$1.01p$","$1.1p$","$p + 0.1$"]', '$1.1p$', NULL, '$p$ means 1 times $p$, so $p + 0.1p = (1 + 0.1)p = 1.1p$. The new price is 110 percent of the old one.', 'checked', '{"lint":[],"solve":{"answer":"$1.1p$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p + 0.1p = (1 + 0.1)p = 1.1p.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8582d343-6da7-4355-8838-5eb8e0388521', 'NC26.7.ANR.2', 2, 'numeric', 'What an equivalent form shows in context', 'Five friends each pay 3 dollars per hour plus a 4 dollar entry fee. After $h$ hours, the total they pay in dollars is $5(3h + 4)$, which equals $15h + 20$. How many dollars do they pay in all if they stay for 0 hours?', '[]', '20', '5*(3*0+4)', 'With $h = 0$, the hourly part is 0 and only the entry fees remain: $15 \times 0 + 20 = 20$. The 20 in $15h + 20$ is the total of the five entry fees (5 times 4).', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15(0) + 20 = 20 (the five entry fees, 5 x 4).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbba0b97-268f-4703-9338-ea5737eea3d2', 'NC26.7.ANR.2', 2, 'choice', 'What an equivalent form shows in context', 'A club''s total cost in dollars for $n$ members is $8n + 24$. Ava rewrites it as $8(n + 3)$. What does the form $8(n + 3)$ show?', '["The cost is 8 dollars for $n$ people plus 3 dollars","The cost is 8 dollars for each of $n + 3$ people","There are 8 members and 3 helpers","Each person pays $n + 3$ dollars"]', 'The cost is 8 dollars for each of $n + 3$ people', NULL, 'In $8(n + 3)$, 8 is multiplied by $n + 3$, so it is 8 dollars for each of $n + 3$ people: the $n$ members and 3 more people. Distributing gives $8n + 24$, the same total.', 'checked', '{"lint":[],"solve":{"answer":"The cost is 8 dollars for each of $n + 3$ people","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8(n + 3) reads as 8 dollars for each of n + 3 people (the n members plus 3 more). Option A describes 8n + 3; C would be n(n+3)-like; D misreads the numbers.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f3e784c-4555-4405-8f8d-e50b37eb838b', 'NC26.7.ANR.2', 2, 'choice', 'Name the property of operations', 'Which property is shown by $(x + 3) + 5 = x + (3 + 5)$?', '["Commutative property of addition","Distributive property","Identity property of addition","Associative property of addition"]', 'Associative property of addition', NULL, 'The numbers stay in the same order, but the grouping (which two are added first) changes. That is the associative property of addition.', 'checked', '{"lint":[],"solve":{"answer":"Associative property of addition","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grouping changes, order does not: associative property of addition.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fbfa277-da32-4a30-9a51-0f1e85ec5b6a', 'NC26.7.ANR.2', 2, 'choice', 'Add and subtract linear expressions', 'Which expression is equivalent to $(7x + 5) - (2x + 3)$?', '["$5x + 8$","$9x + 8$","$5x + 2$","$5x - 2$"]', '$5x + 2$', NULL, 'Subtract each term of the second expression: $7x - 2x = 5x$ and $5 - 3 = 2$. So the result is $5x + 2$. (5x + 8 adds the 3 instead of subtracting it.)', 'checked', '{"lint":[],"solve":{"answer":"$5x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x + 5 - 2x - 3 = 5x + 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('278d8f2c-cb2c-442f-bfd0-21e7bc8a2504', 'NC26.7.ANR.2', 2, 'numeric', 'Add and subtract linear expressions', 'The expression $(9x + 4) - (5x + 1)$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '7', '9-5+4-1', 'Subtracting the parentheses subtracts every term: $9x - 5x = 4x$ and $4 - 1 = 3$. So the expression is $4x + 3$ and a + b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x + 4 - 5x - 1 = 4x + 3; a + b = 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('109e2fb4-78d1-409c-9d44-abf53749af99', 'NC26.7.ANR.2', 3, 'choice', 'Write a total in context as one simplified expression', 'Tickets to a show cost $t$ dollars each, and every purchase has a 2-dollar service fee. Mia buys 3 tickets and Sam buys 4 tickets, in separate purchases. Which expression is equivalent to the total they pay together, in dollars?', '["$7t + 2$","$12t + 4$","$7t + 4$","$7t$"]', '$7t + 4$', NULL, 'Mia pays $3t + 2$ and Sam pays $4t + 2$. Together: $(3t + 2) + (4t + 2) = 7t + 4$. Each of the two purchases has its own fee, so the fees add to 4.', 'checked', '{"lint":[],"solve":{"answer":"$7t + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia pays 3t + 2, Sam pays 4t + 2 (each purchase has its own fee). Total = 7t + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bc7f811-76c6-4032-8564-77d08db4ba61', 'NC26.7.ANR.2', 3, 'numeric', 'Simplify an expression with two distributions', 'The expression $3(2x - 5) - 4(x - 2)$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '-7', '3*(-5)-4*(-2)', '$3(2x - 5) = 6x - 15$ and $-4(x - 2) = -4x + 8$. Add: $6x - 4x - 15 + 8 = 2x - 7$. So $b = -7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x - 5) = 6x - 15; -4(x - 2) = -4x + 8. Sum = 2x - 7, so b = -7.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fe28c6b-d961-4ff2-8c5e-90c7f1c0ee50', 'NC26.7.ANR.2', 3, 'choice', 'Simplify an expression with fraction coefficients', 'Which expression is equivalent to $\frac{1}{2}(6x - 10) + \frac{3}{4}(8x + 4)$?', '["$9x - 7$","$9x + 2$","$9x - 1$","$9x - 2$"]', '$9x - 2$', NULL, '$\frac{1}{2}(6x - 10) = 3x - 5$ and $\frac{3}{4}(8x + 4) = 6x + 3$. Add: $3x + 6x - 5 + 3 = 9x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$9x - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(6x - 10) = 3x - 5; (3/4)(8x + 4) = 6x + 3. Sum = 9x - 2.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa208908-00c7-4e7f-a97f-94bd4a7a48ee', 'NC26.7.ANR.2', 3, 'choice', 'Combine like terms', 'Which expression is equivalent to $2.4x - 1.5 + 0.6x + 3.5$?', '["$3x + 2$","$3x - 2$","$3x + 5$","$1.8x + 2$"]', '$3x + 2$', NULL, 'Combine the $x$ terms: 2.4 + 0.6 = 3.0, so 3x. Combine the numbers: -1.5 + 3.5 = 2. The result is $3x + 2$. (1.8x subtracts the coefficients.)', 'checked', '{"lint":[],"solve":{"answer":"$3x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4x + 0.6x = 3x; -1.5 + 3.5 = 2: 3x + 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('279f61eb-7781-4e57-8424-b682717cc9e2', 'NC26.7.ANR.2', 3, 'numeric', 'Combine like terms', 'The expression $5a - 3b + 2a + 7b$ is equivalent to $ma + nb$. What is the value of $m + n$?', '[]', '11', '5+2-3+7', 'Combine the $a$ terms: 5a + 2a = 7a. Combine the $b$ terms: -3b + 7b = 4b. So the expression is $7a + 4b$, m = 7, n = 4 and m + n = 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a + 2a = 7a; -3b + 7b = 4b; m + n = 11.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71a1bf97-2a10-4640-ad2a-a34507a2b147', 'NC26.7.ANR.2', 3, 'numeric', 'Combine like terms', 'When $8 - 3x - 5 + 7x - 1$ is written in the form $ax + b$, what is the value of $a \times b$?', '[]', '8', '(7-3)*(8-5-1)', 'Combine the $x$ terms: -3x + 7x = 4x. Combine the numbers: 8 - 5 - 1 = 2. So the expression is $4x + 2$, $a = 4$, $b = 2$ and $a \times b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x + 7x = 4x; 8 - 5 - 1 = 2: 4x + 2; a x b = 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e5fb534-7c68-448b-8979-3bc4accf028d', 'NC26.7.ANR.2', 3, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $-2(3x - 4)$?', '["$-6x - 8$","$-6x + 8$","$6x - 8$","$-6x + 4$"]', '$-6x + 8$', NULL, 'Multiply -2 by each term: (-2)(3x) = -6x and (-2)(-4) = +8. The result is $-6x + 8$.', 'checked', '{"lint":[],"solve":{"answer":"$-6x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(3x) = -6x; -2(-4) = 8: -6x + 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('358512fe-1607-497f-b4f3-2422840c672d', 'NC26.7.ANR.2', 3, 'numeric', 'Expand with the distributive property', 'The expression $-(4x - 7)$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '7', '-(-7)', 'The minus sign in front of the parentheses changes the sign of every term inside: $-(4x - 7) = -4x + 7$. So b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(4x - 7) = -4x + 7; b = 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('883a0e9a-b6bc-48d7-bdcb-e1a5e75c7ded', 'NC26.7.ANR.2', 3, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $-\frac{1}{2}(8x - 6)$?', '["$-4x - 3$","$4x - 3$","$-4x + 6$","$-4x + 3$"]', '$-4x + 3$', NULL, 'Multiply each term by -1/2: (-1/2)(8x) = -4x and (-1/2)(-6) = +3. The result is $-4x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$-4x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1/2(8x) = -4x; -1/2(-6) = 3: -4x + 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6768c8f-fa56-4443-9e3f-f744ef2fa90d', 'NC26.7.ANR.2', 3, 'numeric', 'Distribute and combine like terms', 'After $5(2x + 1) - 3(x + 4)$ is simplified, what is the constant term (the number with no variable)?', '[]', '-7', '5*1-3*4', 'Distribute: $5(2x + 1) = 10x + 5$ and $-3(x + 4) = -3x - 12$. Together, $10x + 5 - 3x - 12 = 7x - 7$. The constant term is 5 - 12 = -7.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x + 5 - 3x - 12 = 7x - 7; constant -7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42c79a51-e37f-465b-9eca-c8bcbac70412', 'NC26.7.ANR.2', 3, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $2(3x + 4) - 5(x - 1) + 6$?', '["$x + 9$","$11x + 19$","$x + 19$","$x + 13$"]', '$x + 19$', NULL, 'Distribute: $2(3x + 4) = 6x + 8$ and $-5(x - 1) = -5x + 5$. Then $6x + 8 - 5x + 5 + 6 = x + 19$. (x + 9 forgets that -5 times -1 is +5.)', 'checked', '{"lint":[],"solve":{"answer":"$x + 19$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 8 - 5x + 5 + 6 = x + 19.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46d7ebb6-fea2-49d9-9aef-63a3e2a9a64c', 'NC26.7.ANR.2', 3, 'numeric', 'Distribute and combine like terms', 'The expression $-3(x - 4) + 2(2x + 1)$ is equivalent to $x + k$. What is the value of $k$?', '[]', '14', '(-3)*(-4)+2*1', 'Distribute: $-3(x - 4) = -3x + 12$ and $2(2x + 1) = 4x + 2$. Then $-3x + 12 + 4x + 2 = x + 14$, so k = 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x + 12 + 4x + 2 = x + 14; k = 14.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cff14491-f9ff-478b-8fb5-4648a1c3ab12', 'NC26.7.ANR.2', 3, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $\frac{1}{2}(4x - 8) - (x - 3)$?', '["$x - 7$","$x + 1$","$3x - 7$","$x - 1$"]', '$x - 1$', NULL, 'Half of the first group is $2x - 4$. The minus sign changes both terms of the second group: $-(x - 3) = -x + 3$. Then $2x - 4 - x + 3 = x - 1$.', 'checked', '{"lint":[],"solve":{"answer":"$x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 4 - x + 3 = x - 1.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65db60af-1ad2-4b4c-8917-8b3ef58430a8', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Factor -3 out of $-6x - 9$. Which expression is the result?', '["$-3(2x - 3)$","$-3(2x + 3)$","$3(2x + 3)$","$-3(2x + 9)$"]', '$-3(2x + 3)$', NULL, 'Factor out -3: (-6x) / (-3) = 2x and (-9) / (-3) = 3. So $-6x - 9 = -3(2x + 3)$. Check: $-3(2x + 3) = -6x - 9$.', 'checked', '{"lint":[],"solve":{"answer":"$-3(2x + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6x - 9 = -3(2x) + (-3)(3) = -3(2x + 3).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f41dd5f-ee4a-4bfb-81a0-45f6877665bc', 'NC26.7.ANR.2', 3, 'numeric', 'Factor out a common factor', 'The expression $18x - 45$ can be written as $9(ax - b)$, where a and b are positive whole numbers. What is the value of $a + b$?', '[]', '7', '18/9+45/9', 'Divide each term by 9: 18x / 9 = 2x and 45 / 9 = 5. So $18x - 45 = 9(2x - 5)$, a = 2, b = 5 and a + b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18x - 45 = 9(2x - 5); a = 2, b = 5; sum 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a20712be-7d82-4eae-9e4f-b1df31657290', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Which expression is NOT a way to write $12x + 30$?', '["$12(x + 30)$","$6(2x + 5)$","$3(4x + 10)$","$2(6x + 15)$"]', '$12(x + 30)$', NULL, '$6(2x + 5) = 12x + 30$, $3(4x + 10) = 12x + 30$ and $2(6x + 15) = 12x + 30$. But $12(x + 30) = 12x + 360$, so it is the one that is not equal.', 'checked', '{"lint":[],"solve":{"answer":"$12(x + 30)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(2x+5), 3(4x+10), 2(6x+15) all give 12x + 30; 12(x + 30) = 12x + 360.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71c6e653-f692-4f9b-a65e-23786d977aab', 'NC26.7.ANR.2', 3, 'numeric', 'Factor out a common factor', 'The expression $\frac{3}{4}x + \frac{3}{2}$ can be written as $\frac{3}{4}(x + k)$. What is the value of $k$?', '[]', '2', '(3/2)/(3/4)', 'Factor out 3/4. The first term gives $x$. For the second term, $\frac{3}{4} \times k = \frac{3}{2}$, so k = (3/2) / (3/4) = 2. Check: $\frac{3}{4}(x + 2) = \frac{3}{4}x + \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)k = 3/2, k = (3/2)(4/3) = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4838e900-853f-4599-a96a-1f56d71d77a3', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $15x + 20y$?', '["$5(3x + 20y)$","$5(x + y)$","$5(3x + 4y)$","$15(x + 20y)$"]', '$5(3x + 4y)$', NULL, 'The greatest common factor of 15 and 20 is 5. Divide each term by 5: 15x / 5 = 3x and 20y / 5 = 4y. So $15x + 20y = 5(3x + 4y)$.', 'checked', '{"lint":[],"solve":{"answer":"$5(3x + 4y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF 5: 15x + 20y = 5(3x + 4y). Others expand to 15x+300y, 5x+5y, 15x+100y.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abef06f6-841b-47db-859a-dce6d75f9c60', 'NC26.7.ANR.2', 3, 'choice', 'Decide whether two expressions are equivalent', 'Leo tests $x = 1$: both $4(x + 1)$ and $3x + 5$ equal 8. Leo says the two expressions are equivalent. Which statement is true?', '["They are equivalent: both give 8 when $x = 1$","They are equivalent: one test value is enough to prove it","They are equivalent, because $4(x + 1)$ means $4x + 1$","They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11"]', 'They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11', NULL, 'Equivalent expressions must have the same value for every $x$. When $x = 2$, $4(2 + 1) = 12$ but $3 \times 2 + 5 = 11$, so they are not equivalent. Matching at one value (here $x = 1$) does not prove equivalence, and $4(x + 1) = 4x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 1) = 4x + 4, 3x + 5 differ. x = 2: 4(3) = 12, 3(2) + 5 = 11. So not equivalent; the third statement is true.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6beb3214-f0dc-49d1-8946-07a644b06d3f', 'NC26.7.ANR.2', 3, 'numeric', 'Decide whether two expressions are equivalent', 'For what value of $k$ are $4(x + k)$ and $4x - 28$ equivalent?', '[]', '-7', '-28/4', 'Distribute: $4(x + k) = 4x + 4k$. For this to equal $4x - 28$, 4k = -28, so k = -7.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + k) = 4x + 4k = 4x - 28, so k = -7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9df2b81f-e617-42f4-bab4-87ef303627af', 'NC26.7.ANR.2', 3, 'choice', 'Decide whether two expressions are equivalent', 'Which statement about $x + x$ and $x^2$ is true?', '["They have the same value when $x = 2$, but they are not equivalent","They are equivalent, because they have the same value when $x = 2$","They are equivalent, because $x + x$ means $x$ times $x$","They are not equivalent, because they have different values when $x = 0$"]', 'They have the same value when $x = 2$, but they are not equivalent', NULL, '$x + x = 2x$, not $x^2$. When $x = 2$, both are 4, but when $x = 3$, $x + x = 6$ and $x^2 = 9$. Equivalent expressions must match for every value, so they are not equivalent. (When $x = 0$ both are 0.)', 'checked', '{"lint":[],"solve":{"answer":"They have the same value when $x = 2$, but they are not equivalent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x = 2x. At x = 2: 4 and 4 (same). At x = 0: 0 and 0 (same, so option A''s reason is false). At x = 1: 2 vs 1, so not equivalent. Option D is true.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51720886-ba2d-42f7-ae90-42d5d4a1d35e', 'NC26.7.ANR.2', 3, 'numeric', 'Expressions with fraction or decimal coefficients', 'The expression $0.4(5x - 10) + 1.5x$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '-0.5', '3.5-4', 'Distribute: $0.4(5x - 10) = 2x - 4$. Then $2x - 4 + 1.5x = 3.5x - 4$, so a = 3.5 and b = -4. Then a + b = -0.5.', 'checked', '{"lint":[],"solve":{"answer":"-0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4(5x) = 2x; 0.4(-10) = -4; 2x - 4 + 1.5x = 3.5x - 4; a + b = -0.5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3927c93-59fb-48bc-a320-8eaf69a7b93f', 'NC26.7.ANR.2', 3, 'choice', 'Expressions with fraction or decimal coefficients', 'Which expression is equivalent to $\frac{2}{3}(9x + 6) - 4$?', '["$6x + 2$","$6x$","$6x + 8$","$9x + 2$"]', '$6x$', NULL, 'Distribute 2/3: (2/3)(9x) = 6x and (2/3)(6) = 4. Then $6x + 4 - 4 = 6x$.', 'checked', '{"lint":[],"solve":{"answer":"$6x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)(9x) = 6x; (2/3)(6) = 4; 6x + 4 - 4 = 6x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd81b7e7-af9c-43d5-84a7-edd4c5bdca1a', 'NC26.7.ANR.2', 3, 'choice', 'Expressions with fraction or decimal coefficients', 'Which expression is equivalent to $\frac{x}{2} + \frac{x}{3}$?', '["$\\frac{5x}{6}$","$\\frac{2x}{5}$","$\\frac{x}{5}$","$\\frac{x}{6}$"]', '$\frac{5x}{6}$', NULL, 'Use the common denominator 6: $\frac{x}{2} = \frac{3x}{6}$ and $\frac{x}{3} = \frac{2x}{6}$. Adding gives $\frac{5x}{6}$. (Adding the numerators and the denominators separately gives the wrong results.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5x}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 + x/3 = 3x/6 + 2x/6 = 5x/6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd246706-1a2b-4ded-afd7-b9bcb2de17cc', 'NC26.7.ANR.2', 3, 'numeric', 'Write an expression for a situation', 'Plan A costs $25 + 0.1t$ dollars for $t$ text messages. Plan B costs $15 + 0.1t$ dollars for the same number of text messages. How many more dollars does Plan A cost than Plan B?', '[]', '10', '25-15', 'Subtract: $(25 + 0.1t) - (15 + 0.1t) = 25 - 15 + 0.1t - 0.1t = 10$. The difference is 10 dollars, whatever the number of text messages.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(25 + 0.1t) - (15 + 0.1t) = 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f7209c5-1196-4ca2-8ba7-b2ec0252553b', 'NC26.7.ANR.2', 3, 'numeric', 'Write an expression for a situation', 'A triangle has sides of length $x$, $(2x + 3)$ and $(3x - 1)$ centimeters. Its perimeter is $ax + b$ centimeters. What is the value of $a + b$?', '[]', '8', '6+2', 'Add the three sides: $x + (2x + 3) + (3x - 1)$. The $x$ terms give x + 2x + 3x = 6x and the numbers give 3 - 1 = 2. So the perimeter is $6x + 2$ and a + b = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3 + 3x - 1 = 6x + 2; a + b = 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a049f297-0053-461b-9169-3150655efea2', 'NC26.7.ANR.2', 3, 'choice', 'Write an expression for a situation', 'Jon saves $j$ dollars each week. Mia saves 5 dollars more each week than Jon. Which expression shows the total the two of them save in 4 weeks?', '["$4j + 20$","$8j + 20$","$8j + 5$","$2j + 5$"]', '$8j + 20$', NULL, 'Mia saves $j + 5$ each week. In 4 weeks Jon saves $4j$ and Mia saves $4(j + 5) = 4j + 20$. Together: $4j + 4j + 20 = 8j + 20$.', 'checked', '{"lint":[],"solve":{"answer":"$8j + 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Per week together j + (j + 5) = 2j + 5; in 4 weeks 4(2j + 5) = 8j + 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee712aea-4dc4-4339-87a7-b20045d11ebb', 'NC26.7.ANR.2', 3, 'choice', 'Write an expression for a situation', 'A shop takes 20 percent off every price $p$ and then takes 5 dollars off with a coupon. Which expression shows the final price in dollars?', '["$0.2p - 5$","$0.8p + 5$","$0.8p - 5$","$0.8(p - 5)$"]', '$0.8p - 5$', NULL, 'Taking 20 percent off leaves 80 percent of the price, which is $0.8p$. The coupon then takes off 5 dollars: $0.8p - 5$. (0.8(p - 5) would apply the coupon first.)', 'checked', '{"lint":[],"solve":{"answer":"$0.8p - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 percent off leaves 0.8p; then 5 off: 0.8p - 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f43d7169-42c9-427c-9eac-956c6057c14a', 'NC26.7.ANR.2', 3, 'choice', 'What an equivalent form shows in context', 'The total cost for a group is $6d + 12$ dollars. Each of 3 friends pays an equal share. Which expression shows one friend''s share in dollars?', '["$2d + 12$","$6d + 4$","$18d + 36$","$2d + 4$"]', '$2d + 4$', NULL, 'Divide every term by 3: 6d / 3 = 2d and 12 / 3 = 4. One share is $2d + 4$ dollars. (2d + 12 divides only the first term.)', 'checked', '{"lint":[],"solve":{"answer":"$2d + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6d + 12)/3 = 2d + 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb08e20c-156f-4783-962b-c88a0eba7666', 'NC26.7.ANR.2', 3, 'numeric', 'What an equivalent form shows in context', 'A garden has two rectangular beds. One is 4 feet wide and $(x + 6)$ feet long. The other is 3 feet wide and $x$ feet long. The total area is $4(x + 6) + 3x$ square feet, which is equivalent to $7x + 24$. What is the total area when $x = 2$?', '[]', '38', '7*2+24', 'Check the equivalence: $4(x + 6) + 3x = 4x + 24 + 3x = 7x + 24$. With $x = 2$: $7 \times 2 + 24 = 14 + 24 = 38$ square feet. (The first form gives $4 \times 8 + 3 \times 2 = 38$ too.)', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7(2) + 24 = 38. Check: 4(8) + 3(2) = 32 + 6 = 38.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3401cc4a-e2fe-4813-a21a-e57e57de9cba', 'NC26.7.ANR.2', 3, 'choice', 'Name the property of operations', 'Which equation shows the associative property of multiplication?', '["$3 + x = x + 3$","$3(4x) = (3 \\times 4)x$","$3(x + 4) = 3x + 12$","$3 \\times 1 = 3$"]', '$3(4x) = (3 \times 4)x$', NULL, 'The associative property of multiplication changes the grouping of the factors: 3(4x) = (3 times 4)x. The equation 3 + x = x + 3 is the commutative property of addition, 3(x + 4) = 3x + 12 is the distributive property, and 3 times 1 = 3 is the identity property of multiplication.', 'checked', '{"lint":[],"solve":{"answer":"$3(4x) = (3 \\times 4)x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(4x) = (3 x 4)x regroups factors: associative property of multiplication. Others: identity, distributive, commutative of addition.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8281e32c-3f49-479b-a1e1-52e6e544e228', 'NC26.7.ANR.2', 3, 'choice', 'Add and subtract linear expressions', 'Which expression is equivalent to $(5 - 2x) - (3 - 6x)$?', '["$4x + 8$","$-8x + 2$","$-8x + 8$","$4x + 2$"]', '$4x + 2$', NULL, 'Subtract every term of the second group: $5 - 2x - 3 + 6x$. The numbers give 5 - 3 = 2 and the $x$ terms give -2x + 6x = 4x. The result is $4x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$4x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2x - 3 + 6x = 4x + 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17496d80-0622-4e35-9512-663b5fe3ce89', 'NC26.7.ANR.2', 3, 'numeric', 'Add and subtract linear expressions', 'The expression $(3x - 4) - 2(x - 5)$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '7', '3-2-4+10', 'Distribute -2: $-2(x - 5) = -2x + 10$. Then $3x - 4 - 2x + 10 = x + 6$, so a = 1, b = 6 and a + b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 4 - 2x + 10 = x + 6; a + b = 1 + 6 = 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee6466c9-755e-4866-9bdb-417131bc6832', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'Solve for $x$: $3x + 5 = 20$.', '[]', '5', '(20-5)/3', 'Subtract 5 from both sides: $3x = 15$. Divide by 3: $x = 5$. Check: $3 \times 5 + 5 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6425c32e-261a-43ac-b28f-415b9cf4c033', 'NC26.7.ANR.3', 1, 'choice', 'Solve a one-step inequality', 'Which inequality shows all the solutions of $x + 7 < 12$?', '["$x < 5$","$x > 5$","$x < 19$","$x > 19$"]', '$x < 5$', NULL, 'Subtract 7 from both sides: $x < 5$. The direction of the inequality does not change.', 'checked', '{"lint":[],"solve":{"answer":"$x < 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract 7: x < 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4840c986-bcca-4616-80ff-286248fd0c30', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation with division', 'Solve for $x$: $\frac{x}{4} - 3 = 2$.', '[]', '20', '(2+3)*4', 'Add 3 to both sides: $\frac{x}{4} = 5$. Multiply both sides by 4: $x = 20$. Check: $20 \div 4 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/4 = 5, x = 20.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
