INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9386c0f2-4e06-4559-a251-d1cd60558763', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'Maya solves $5n - 4 = 21$. What is the value of $n$?', '[]', '5', '(21+4)/5', 'Add 4 to both sides: $5n = 25$. Divide both sides by 5: $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5n = 25; n = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
