INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f14df50-f5f3-45fb-a7ee-0eae411c6b8e', 'NC26.7.ANR.3', 1, 'numeric', 'Solve an equation with parentheses', 'Solve for $x$: $3(x + 1) = 15$.', '[]', '4', '15/3-1', 'Divide both sides by 3: $x + 1 = 5$. Subtract 1: $x = 4$. Check: $3(4 + 1) = 15$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 1 = 5; x = 4. Check 3(5) = 15.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
