INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('535fe32a-d395-42e1-84e8-828067d0906c', 'NC26.7.ANR.3', 1, 'numeric', 'Write and solve an equation from a situation', 'Leo has 8 dollars. He saves 3 dollars each week. After how many weeks will he have exactly 23 dollars?', '[]', '5', '(23-8)/3', 'After $w$ weeks Leo has $8 + 3w$ dollars. Solve $8 + 3w = 23$: subtract 8 to get $3w = 15$, then divide by 3 to get $w = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 3w = 23; 3w = 15; w = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
