INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59d4ab8c-d43e-443f-afa7-a06928b5e436', 'NC26.7.ANR.3', 1, 'numeric', 'Write and solve an equation from a situation', 'Maria buys 4 pencils that each cost the same and an eraser that costs 2 dollars. She pays 10 dollars in all. How many dollars does one pencil cost?', '[]', '2', '(10-2)/4', 'Let $p$ be the price of one pencil. Then $4p + 2 = 10$. Subtract 2: $4p = 8$. Divide by 4: $p = 2$. One pencil costs 2 dollars.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4p + 2 = 10; 4p = 8; p = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
