INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c8d3578-fc68-47e4-bf4d-9d8065cb33f7', 'NC26.7.ANR.3', 1, 'numeric', 'Write and solve an equation from a situation', 'A phone plan costs 12 dollars a month plus 4 dollars for each extra gigabyte. One month the bill was 32 dollars. How many extra gigabytes were used?', '[]', '5', '(32-12)/4', 'Let $g$ be the extra gigabytes. Then $12 + 4g = 32$. Subtract 12: $4g = 20$. Divide by 4: $g = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 4g = 32; 4g = 20; g = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
