INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('761e9cb6-eaee-4e86-a122-dd5965ce2a1d', 'NC26.7.ANR.3', 1, 'choice', 'Write and solve an equation from a situation', 'Which equation matches the sentence "The sum of twice a number $n$ and 9 is 21"?', '["$2n + 9 = 21$","$2(n + 9) = 21$","$2 + n + 9 = 21$","$2n - 9 = 21$"]', '$2n + 9 = 21$', NULL, 'Twice the number is $2n$. The sum of $2n$ and 9 is $2n + 9$, and it is equal to 21. (2(n + 9) would double the sum.)', 'checked', '{"lint":[],"solve":{"answer":"$2n + 9 = 21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice n is 2n; sum with 9: 2n + 9 = 21.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
