INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ac1bef-15b3-408d-82c3-bc899d5f26e6', 'NC26.7.ANR.3', 1, 'choice', 'Solve an inequality', 'Which inequality shows all the solutions of $x - 3 > 5$?', '["$x > 8$","$x < 8$","$x > 2$","$x < 2$"]', '$x > 8$', NULL, 'Add 3 to both sides: $x > 8$. The direction of the sign does not change. (x > 2 subtracts 3 instead of adding it.)', 'checked', '{"lint":[],"solve":{"answer":"$x > 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 3: x > 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
