INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56548ebc-ba47-4b6a-81d8-ea06fc849e44', 'NC26.7.ANR.3', 1, 'choice', 'Solve an inequality', 'What are all the solutions of $3x < 12$?', '["$x > 4$","$x < 9$","$x < 4$","$x < 15$"]', '$x < 4$', NULL, 'Divide both sides by 3: $x < 4$. (x < 9 subtracts 3, and x < 15 adds 3.)', 'checked', '{"lint":[],"solve":{"answer":"$x < 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 3: x < 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
