INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4adb3495-eb87-42de-9126-108339056ee5', 'NC26.7.ANR.3', 1, 'choice', 'Write an inequality from a situation', 'A bus holds at most 40 people. Which inequality shows the number of people $p$ that can be on the bus?', '["$p < 40$","$p \\le 40$","$p \\ge 40$","$p > 40$"]', '$p \le 40$', NULL, '"At most 40" means 40 or fewer, so $p \le 40$. (p < 40 would leave out a full bus of exactly 40.)', 'checked', '{"lint":[],"solve":{"answer":"$p \\le 40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At most 40 means 40 or fewer: p <= 40.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
