INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afa6106a-be93-4868-bdb7-c48509ee132b', 'NC26.7.ANR.3', 1, 'choice', 'Decide whether a value is a solution', 'Which number is a solution of $x + 4 > 10$?', '["8","3","5","6"]', '8', '8', 'Test each number. 8 + 4 = 12, which is greater than 10. But 3 + 4 = 7, 5 + 4 = 9 and 6 + 4 = 10 are not greater than 10.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x > 6. Of 3, 6, 8, 5 only 8 works (6 + 4 = 10 is not > 10).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eaf604fc-8b69-4ab6-9771-9442e4cdf99e', 'NC26.7.ANR.3', 1, 'choice', 'Decide whether a value is a solution', 'Which number makes the equation $3x - 2 = 10$ true?', '["2","10","12","4"]', '4', '(10+2)/3', 'Test 4: $3 \times 4 - 2 = 12 - 2 = 10$, which is true. The other numbers give 4, 28 and 34.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 12; x = 4. Check 12 - 2 = 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b798b4b7-a175-4b84-9f4f-7d7feb8262f3', 'NC26.7.ANR.3', 1, 'choice', 'Choose an equation or an inequality', 'Which sentence is best modeled by an inequality?', '["A recipe needs exactly 3 cups of flour","Pam has 12 apples","A basket holds at most 12 apples","Tom bought 5 apples for 10 dollars"]', 'A basket holds at most 12 apples', NULL, '"At most 12" allows 12 or any smaller number, so it is modeled by an inequality. The other sentences each name one exact amount.', 'checked', '{"lint":[],"solve":{"answer":"A basket holds at most 12 apples","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''At most 12'' describes a range of values: inequality. The others are exact amounts.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e8d91dd-4ffb-4e11-a102-6681a84efa25', 'NC26.7.ANR.3', 1, 'choice', 'Choose an equation or an inequality', 'A video rental costs a 2 dollar fee plus 3 dollars for each day $d$. Rae pays exactly 14 dollars. Which can be used to find the number of days?', '["The inequality $3d + 2 < 14$","The equation $3d + 2 = 14$","The inequality $3d + 2 > 14$","The equation $3(d + 2) = 14$"]', 'The equation $3d + 2 = 14$', NULL, 'Rae pays exactly 14 dollars, so the cost $3d + 2$ must equal 14. Use the equation $3d + 2 = 14$. (An inequality would allow other amounts, and 3(d + 2) charges the fee 3 times.)', 'checked', '{"lint":[],"solve":{"answer":"The equation $3d + 2 = 14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exactly 14 dollars: equation. 2 fee + 3 per day: 3d + 2 = 14 (d = 4).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('637493d2-8ea4-4acf-a6cf-ec288653f464', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with parentheses', 'Solve for $x$: $4(x - 3) = 28$.', '[]', '10', '28/4+3', 'Divide both sides by 4: $x - 3 = 7$. Add 3: $x = 10$. Check: $4 \times 7 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 3 = 7, x = 10. Check: 4 x 7 = 28.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05703b48-942d-4406-83f7-a5316572714c', 'NC26.7.ANR.3', 2, 'choice', 'Solve a two-step inequality', 'What are all the solutions of $2x + 7 > 15$?', '["$x > 11$","$x > 6$","$x < 4$","$x > 4$"]', '$x > 4$', NULL, 'Subtract 7: $2x > 8$. Divide by 2: $x > 4$. Dividing by a positive number keeps the direction of the inequality.', 'checked', '{"lint":[],"solve":{"answer":"$x > 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x > 8, x > 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
