INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46ad5fb6-98f9-41cf-ab0f-f4aa34a50d91', 'NC26.7.ANR.3', 2, 'choice', 'Solve a two-step equation', 'Which value of $x$ solves $6x + 9 = 3$?', '["1","2","-1","-6"]', '-1', '(3-9)/6', 'Subtract 9 from both sides: $6x = -6$. Divide by 6: $x = -1$. (1 loses the negative sign, 2 comes from adding 9, and -6 forgets to divide by 6.)', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x = -6; x = -1.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
