VALUES ('0ce12ce4-5bbb-45c5-92a2-0449454a441a', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Solve for $x$: $-\frac{3}{4}x = 9$.', '[]', '-12', '9/(-3/4)', 'Multiply both sides by -4/3 (the reciprocal of -3/4): $x = 9 \times (-\frac{4}{3}) = -12$. Check: $-\frac{3}{4} \times (-12) = 9$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 9 x (-4/3) = -12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
