INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1caf0ab-6fd2-4a39-94c9-627a61c05d0d', 'NC26.7.ANR.3', 2, 'numeric', 'Write and solve an equation from a situation', 'A bakery charges a 3 dollar delivery fee plus 2.50 dollars for each muffin. One order cost 18 dollars in all. How many muffins were in the order?', '[]', '6', '(18-3)/2.5', 'Let $m$ be the number of muffins. Then $2.5m + 3 = 18$. Subtract 3: $2.5m = 15$. Divide by 2.5: $m = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2.5m = 18; 2.5m = 15; m = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
