INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0820bc50-3d92-4ccd-9d3a-c22d8273650a', 'NC26.7.ANR.3', 2, 'numeric', 'Write and solve an equation from a situation', 'Twice a number, decreased by 7, equals 15. What is the number?', '[]', '11', '(15+7)/2', 'Write the sentence as an equation: $2n - 7 = 15$. Add 7: $2n = 22$. Divide by 2: $n = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n - 7 = 15; 2n = 22; n = 11.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eaa2c8ec-578b-47ba-b8f3-29f8a8a94c79', 'NC26.7.ANR.3', 2, 'choice', 'Write and solve an equation from a situation', 'Tom has 45 dollars. After he buys 3 notebooks that each cost $n$ dollars, he has 24 dollars left. Which equation can be used to find $n$?', '["$45 + 3n = 24$","$45 - 3n = 24$","$3n - 45 = 24$","$45 - n = 24$"]', '$45 - 3n = 24$', NULL, 'The notebooks cost $3n$ dollars in all, and this is taken away from 45: $45 - 3n = 24$. (45 - n = 24 uses the price of only one notebook.)', 'checked', '{"lint":[],"solve":{"answer":"$45 - 3n = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 minus the cost 3n leaves 24: 45 - 3n = 24 (n = 7).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20ea4444-596d-422d-95ea-70e1e1bc63bc', 'NC26.7.ANR.3', 2, 'numeric', 'Write and solve an equation from a situation', 'A rectangle is 5 centimeters wide and has a perimeter of 34 centimeters. What is its length in centimeters?', '[]', '12', '(34-2*5)/2', 'The perimeter is twice the length plus twice the width. With length $n$: $2n + 2 \times 5 = 34$, so $2n + 10 = 34$. Subtract 10: $2n = 24$. Divide by 2: $n = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5 + L) = 34; 5 + L = 17; L = 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('511057d7-da28-4182-9cc7-d0e72884a126', 'NC26.7.ANR.3', 2, 'choice', 'Solve an inequality', 'What are all the solutions of $3x - 4 < 11$?', '["$x < 5$","$x > 5$","$x < 7$","$x < 15$"]', '$x < 5$', NULL, 'Add 4 to both sides: $3x < 15$. Divide by 3: $x < 5$. (x < 7 subtracts 4 instead of adding it, and x < 15 forgets to divide by 3.)', 'checked', '{"lint":[],"solve":{"answer":"$x < 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x < 15; x < 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
