INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('228ed69e-c6ae-4fc6-9ba3-0d8d61affe35', 'NC26.7.ANR.3', 2, 'choice', 'Write an inequality from a situation', 'A school needs at least 120 volunteers. It has 45 now, and each of $c$ classes will add 5 more. Which inequality shows this?', '["$45 + 5c \\le 120$","$45c + 5 \\ge 120$","$45 + 5c \\ge 120$","$5c \\ge 120 + 45$"]', '$45 + 5c \ge 120$', NULL, 'The number of volunteers will be $45 + 5c$. "At least 120" means 120 or more: $45 + 5c \ge 120$.', 'checked', '{"lint":[],"solve":{"answer":"$45 + 5c \\ge 120$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 now + 5 per class, at least 120: 45 + 5c >= 120.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ad351fa-d00f-48db-a134-e4b9118fa68f', 'NC26.7.ANR.3', 2, 'numeric', 'Interpret the solution of an inequality in context', 'A phone plan costs 15 dollars plus 0.10 dollars per text message. Eli can spend at most 25 dollars in a month. What is the greatest number of text messages he can send?', '[]', '100', NULL, 'The cost is $15 + 0.1t \le 25$. Subtract 15: $0.1t \le 10$. Divide by 0.1: $t \le 100$. The greatest number is 100.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 0.10t <= 25; 0.10t <= 10; t <= 100. Greatest 100.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca561373-162f-4326-8014-6dd4c69210f8', 'NC26.7.ANR.3', 2, 'choice', 'Interpret the solution of an inequality in context', 'A club solves an inequality for the number of tickets $t$ and gets $t \ge 8.5$. Tickets are sold one at a time. What is the least number of tickets that works?', '["8","8.5","10","9"]', '9', '9', 'The number of tickets must be a whole number that is at least 8.5. Eight is too small, and 8.5 is not a whole number, so the least is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t must be a whole number at least 8.5: least is 9.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('697edc56-f225-4105-82d5-e4090fcf26e7', 'NC26.7.ANR.3', 2, 'numeric', 'Interpret the solution of an inequality in context', 'A rope is 50 meters long. Pieces that are 3 meters long are cut from it, and at least 5 meters of rope must be left over. What is the greatest number of pieces that can be cut?', '[]', '15', NULL, 'The pieces use $3p$ meters and at least 5 meters must remain, so $3p + 5 \le 50$. Subtract 5: $3p \le 45$. Divide by 3: $p \le 15$. The greatest number is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 3p >= 5; 3p <= 45; p <= 15. 15 pieces use 45 m, leaving 5 m. Greatest 15.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca13087e-706f-406d-b22b-4bbddba9577e', 'NC26.7.ANR.3', 2, 'choice', 'Graph an inequality on a number line', 'The solution of $2x + 6 > 2$ is graphed on a number line. Which description matches the graph?', '["An open circle at $-2$ with the line shaded to the right","A closed circle at $-2$ with the line shaded to the right","An open circle at $-2$ with the line shaded to the left","An open circle at $2$ with the line shaded to the right"]', 'An open circle at $-2$ with the line shaded to the right', NULL, 'Subtract 6: $2x > -4$. Divide by 2: $x > -2$. The sign is "greater than", so the circle is open at -2, and the shading is to the right.', 'checked', '{"lint":[],"solve":{"answer":"An open circle at $-2$ with the line shaded to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x > -4; x > -2: open circle at -2, shaded right.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8e874d8-065f-41f4-8153-784d4e141e76', 'NC26.7.ANR.3', 2, 'choice', 'Graph an inequality on a number line', 'The solution of $3x - 5 \le 10$ is graphed on a number line. Which description matches the graph?', '["A closed circle at $5$ with the line shaded to the left","A closed circle at $5$ with the line shaded to the right","An open circle at $5$ with the line shaded to the left","A closed circle at $15$ with the line shaded to the left"]', 'A closed circle at $5$ with the line shaded to the left', NULL, 'Add 5: $3x \le 15$. Divide by 3: $x \le 5$. The sign is "less than or equal to", so the circle is closed at 5, and the shading is to the left.', 'checked', '{"lint":[],"solve":{"answer":"A closed circle at $5$ with the line shaded to the left","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x <= 15; x <= 5: closed circle at 5, shaded left.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91b4d8bf-5fff-457f-b1f1-348663f67f2e', 'NC26.7.ANR.3', 2, 'numeric', 'Graph an inequality on a number line', 'The graph of an inequality has a closed circle at $4$, and the line to the right of $4$ is shaded. How many of the whole numbers from 1 through 8 are solutions?', '[]', '5', NULL, 'The graph shows $x \ge 4$. The whole numbers from 1 through 8 that are 4 or greater are 4, 5, 6, 7 and 8. That is 5 numbers.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x >= 4; from 1 to 8: 4, 5, 6, 7, 8 = 5 numbers.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08bc2323-c1b6-404a-aa65-27d9d34b400a', 'NC26.7.ANR.3', 2, 'choice', 'Decide whether a value is a solution', 'Which number is a solution of $2x - 3 \le 7$?', '["6","5","8","10"]', '5', '5', 'Test each number. For 5: $2 \times 5 - 3 = 7$, and 7 is less than or equal to 7, so 5 works. For 6, 8 and 10 the left side is 9, 13 and 17, which are greater than 7.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x <= 10; x <= 5. Of 8, 6, 10, 5 only 5 works.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('160d4b58-9116-40ce-bb1d-9a1d65f07474', 'NC26.7.ANR.3', 2, 'choice', 'Decide whether a value is a solution', 'Which equation has $x = -3$ as its solution?', '["$2x + 7 = 13$","$2x - 7 = 1$","$2x + 7 = -1$","$2x + 7 = 1$"]', '$2x + 7 = 1$', NULL, 'Substitute $x = -3$ into each equation. For $2x + 7 = 1$: $2 \times (-3) + 7 = -6 + 7 = 1$, which is true. In the others, the left side is not equal to the right side when $x = -3$: in $2x + 7 = 13$ it is 1, in $2x - 7 = 1$ it is -13, and in $2x + 7 = -1$ it is 1.', 'checked', '{"lint":[],"solve":{"answer":"$2x + 7 = 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(-3) + 7 = 1, so 2x + 7 = 1. Others: x = 3, x = -4, x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2d3bb14-1520-457b-89ab-8d8cbce04cbc', 'NC26.7.ANR.3', 2, 'choice', 'Choose an equation or an inequality', 'Amy has 12 dollars and earns 5 dollars for each hour $h$ she babysits. She wants to have exactly 52 dollars. Which should she use to find the number of hours?', '["The equation $12 + 5h = 52$","The inequality $12 + 5h < 52$","The inequality $12 + 5h > 52$","The equation $12h + 5 = 52$"]', 'The equation $12 + 5h = 52$', NULL, 'She wants exactly 52 dollars, so the money $12 + 5h$ must equal 52. Use the equation $12 + 5h = 52$. Solving gives $5h = 40$ and $h = 8$.', 'checked', '{"lint":[],"solve":{"answer":"The equation $12 + 5h = 52$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exactly 52: equation 12 + 5h = 52 (h = 8).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd975bd3-8d64-4e41-b576-a5509c3f36b0', 'NC26.7.ANR.3', 2, 'choice', 'Choose an equation or an inequality', 'A rental van can carry no more than 900 pounds. It already holds 240 pounds of supplies. Each box that is added weighs 30 pounds. Which inequality shows all the numbers of boxes $b$ that can be added without going over the limit?', '["$240 + 30b \\ge 900$","$240b + 30 \\le 900$","$240 + 30b \\le 900$","$30b - 240 \\le 900$"]', '$240 + 30b \le 900$', NULL, 'The total weight is the 240 pounds already there plus 30 pounds for each of the $b$ boxes, so $240 + 30b$. "No more than 900" means this is at most 900, which gives $240 + 30b \le 900$. The other expressions put the 240 and the 30 in the wrong places or reverse the inequality.', 'checked', '{"lint":[],"solve":{"answer":"$240 + 30b \\le 900$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total weight 240 + 30b must not exceed 900: 240 + 30b <= 900.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d68ced4c-c735-4810-b2cc-92fc2dc9ff77', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with a fraction coefficient', 'Solve for $x$: $\frac{2}{3}x - 5 = 7$.', '[]', '18', '(7+5)*3/2', 'Add 5: $\frac{2}{3}x = 12$. Multiply by the reciprocal $\frac{3}{2}$: $x = 12 \times \frac{3}{2} = 18$. Check: $\frac{2}{3} \times 18 - 5 = 12 - 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)x = 12, x = 12 x 3/2 = 18.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('516c2b2d-79db-45da-8924-545e3013d198', 'NC26.7.ANR.3', 3, 'choice', 'Choose the inequality that fits a situation', 'A taxi ride costs a 3-dollar starting fee plus 2 dollars for each mile. Kim has at most 25 dollars to spend. Which inequality can be used to find the number of miles $m$ she can ride?', '["$3 + 2m \\ge 25$","$2 + 3m \\le 25$","$3 + 2m = 25$","$3 + 2m \\le 25$"]', '$3 + 2m \le 25$', NULL, 'The cost is the fee plus 2 dollars per mile: $3 + 2m$. "At most 25 dollars" means the cost is less than or equal to 25, so $3 + 2m \le 25$.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 2m \\le 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = 3 + 2m, at most 25 means cost <= 25: 3 + 2m <= 25.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3542622a-e99e-4ffa-be15-543600dc436f', 'NC26.7.ANR.3', 3, 'choice', 'Find a solution of an inequality with parentheses', 'Which value is a solution of $3(x - 2) > 12$?', '["3","4","6","7"]', '7', '7', 'Divide by 3: $x - 2 > 4$. Add 2: $x > 6$. Only 7 is greater than 6. (At $x = 6$ the two sides are equal, $12 > 12$ is false.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 2 > 4, x > 6. Options: 6 (gives 12, not > 12), 4, 3 no; 7 gives 15 > 12 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69b415d3-14c2-4214-9c58-cfc5adef9ba7', 'NC26.7.ANR.3', 3, 'numeric', 'Solve a two-step equation', 'Solve for $x$: $9 - 4x = 33$.', '[]', '-6', '(33-9)/(-4)', 'Subtract 9 from both sides: $-4x = 24$. Divide both sides by -4: $x = -6$. Check: $9 - 4 \times (-6) = 9 + 24 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4x = 24; x = -6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71b7b4da-6aef-4444-88ea-85357f5d393b', 'NC26.7.ANR.3', 3, 'numeric', 'Solve a two-step equation', 'Solve for $x$: $6 - \frac{x}{3} = 10$.', '[]', '-12', '(10-6)*(-3)', 'Subtract 6 from both sides: $-\frac{x}{3} = 4$. Multiply both sides by -3: $x = -12$. Check: $6 - \frac{-12}{3} = 6 + 4 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x/3 = 4; x = -12. Check 6 - (-4) = 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8130e537-a947-494f-8ea9-3ea05fa143cb', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with parentheses', 'What is the solution of $-3(x + 4) = 15$?', '[]', '-9', '15/(-3)-4', 'Divide both sides by -3: $x + 4 = -5$. Subtract 4: $x = -9$. Check: $-3(-9 + 4) = -3 \times (-5) = 15$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 4 = -5; x = -9.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
