INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d48cea1-2d09-425b-8c66-56b0b46ae0b3', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'What value of $x$ makes $0.25x - 1.5 = 2$ true?', '[]', '14', '(2+1.5)/0.25', 'Add 1.5 to both sides: $0.25x = 3.5$. Divide by 0.25 (the same as multiplying by 4): $x = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25x = 3.5; x = 14.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
