INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('761dd10f-6ffb-46fc-b757-fb5fedfd8037', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a figure with a part removed', 'From a square with sides of 8 centimeters, a triangle with a base of 8 centimeters and a height of 5 centimeters is cut away. What area is left, in square centimeters?', '["24","59","20","44"]', '44', '8*8 - 1/2*8*5', 'Square: 8 $\times$ 8 = 64. Triangle: $\frac{1}{2} \times 8 \times 5 = 20$. Left: 64 $-$ 20 = 44 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 - 1/2 x 8 x 5 = 64 - 20 = 44.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
