INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a40fc26d-a4bd-4f72-a866-48265636d9bf', 'NC26.7.SGMR.1', 1, 'choice', 'Perimeter of a composite figure', 'Two squares, each with sides of 4 centimeters, are placed side by side and touch along a full side to make one rectangle. What is the distance around the rectangle, in centimeters?', '["32","24","16","12"]', '24', '2*(2*4+4)', 'The rectangle is 8 cm long and 4 cm wide. Distance around = $2 \times (8 + 4) = 24$ centimeters. (The touching sides are inside the figure, so they do not count.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 8 x 4. Perimeter 2(8 + 4) = 24.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
