INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c58334b-7f6b-42d3-9895-e8ad4a28a544', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a triangle', 'A triangle has sides of 5 centimeters, 12 centimeters and 13 centimeters. The 5 centimeter and 12 centimeter sides meet at a right angle. What is the area of the triangle, in square centimeters?', '["60","30","32.5","78"]', '30', '1/2*5*12', 'The two sides that meet at the right angle are the base and the height. The longest side, 13 centimeters, is not used. Area = $\frac{1}{2} \times 5 \times 12 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 5 and 12 sides are perpendicular, so they are base and height: 1/2 x 5 x 12 = 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81f798ad-e285-44c6-a200-ab9da6a23dee', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a parallelogram or trapezoid', 'A parallelogram has a base of 10 centimeters, a slanted side of 6 centimeters and a height of 5 centimeters. What is its area, in square centimeters?', '["60","30","25","50"]', '50', '10*5', 'The height is the straight-up distance, not the slanted side. Area = 10 $\times$ 5 = 50 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = base x height = 10 x 5 = 50; the slanted side 6 is a distractor.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
