INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4bac7e0-cebf-49bd-9899-ba0375b9a928', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a parallelogram or trapezoid', 'The top of a small table is a trapezoid. Its parallel edges are 1.2 meters and 0.8 meters long, and the distance between them is 0.5 meters. What is the area of the top, in square meters?', '[]', '0.5', '1/2*(1.2+0.8)*0.5', 'Area = $\frac{1}{2} \times (1.2 + 0.8) \times 0.5 = \frac{1}{2} \times 2 \times 0.5 = 0.5$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (1.2 + 0.8) x 0.5 = 1/2 x 2 x 0.5 = 0.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
