INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54fe666e-a857-4856-895b-3de82380bf5f', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a parallelogram or trapezoid', 'A parallelogram has an area of 84 square centimeters and a base of 12 centimeters. How tall is it, in centimeters?', '["1008","72","7","14"]', '7', '84/12', 'Area = base $\times$ height, so height = 84 $\div$ 12 = 7 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 84 / 12 = 7.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
