INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('718c51c6-9813-43b0-8fd8-f09c31db8325', 'NC26.7.SGMR.1', 2, 'choice', 'Circumference of a circle', 'A circular running track has a diameter of 50 meters. Nira jogs once all the way around it. Use 3.14 for $\pi$. How many meters does she jog?', '["157","314","78.5","1962.5"]', '157', '3.14*50', 'Distance around = $\pi \times$ diameter = $3.14 \times 50 = 157$ meters.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 50 = 157.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
