INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee7b56e1-d542-415f-9b1a-ca5ac93ffe89', 'NC26.7.SGMR.1', 2, 'choice', 'Circumference of a circle', 'A circular pond has a radius of 7 meters. Use $\frac{22}{7}$ for $\pi$. How long is the edge of the pond, in meters?', '["22","154","88","44"]', '44', '2*(22/7)*7', 'Circumference = $2 \times \pi \times r = 2 \times \frac{22}{7} \times 7 = 44$ meters.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 22/7 x 7 = 44.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
