INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b8604d9-90e4-4e49-87d2-13fe2196c2ed', 'NC26.7.SGMR.1', 2, 'numeric', 'Circumference of a circle', 'A circular rug has a radius of 1.5 meters. Fringe is sewn all the way around its edge. Use 3.14 for $\pi$. How many meters of fringe are needed?', '[]', '9.42', '2*3.14*1.5', 'The fringe goes around the circumference: $2 \times 3.14 \times 1.5 = 9.42$ meters.', 'checked', '{"lint":[],"solve":{"answer":"9.42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 1.5 = 9.42.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
