INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b709307-39fb-46df-8d92-099dbe2daa20', 'NC26.7.SGMR.1', 2, 'numeric', 'Pi as the ratio of circumference to diameter', 'The circumference of a coin is 18.84 millimeters. Use 3.14 for $\pi$. What is the radius of the coin, in millimeters?', '[]', '3', '18.84/(2*3.14)', 'Circumference = $2 \times \pi \times$ radius, so radius = 18.84 $\div$ (2 $\times$ 3.14) = 18.84 $\div$ 6.28 = 3 millimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 18.84 / 3.14 = 6, so r = 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
