INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33c8786b-8bb2-4e74-867a-7090f42d7e1a', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a circle', 'A pizza has a diameter of 14 inches. Use 3.14 for $\pi$. What is the area of the top of the pizza, in square inches?', '["615.44","43.96","21.98","153.86"]', '153.86', '3.14*(14/2)^2', 'The radius is 14 $\div$ 2 = 7 inches. Area = $3.14 \times 7 \times 7 = 153.86$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"153.86","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 7. A = 3.14 x 49 = 153.86.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
