INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('637dbaf6-3272-4cd7-bf38-ffc76ec427b1', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a circle', 'A circular rug has a radius of 2.5 meters. Use 3.14 for $\pi$. How many square meters of floor does the rug cover?', '[]', '19.625', '3.14*2.5^2', 'Area = $\pi r^2 = 3.14 \times 2.5 \times 2.5 = 3.14 \times 6.25 = 19.625$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"19.625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3.14 x 2.5^2 = 3.14 x 6.25 = 19.625.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
