INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77681571-f205-4432-9515-ce5de754dba8', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a composite figure by adding parts', 'A stage is a rectangle 10 meters wide and 6 meters deep, with a half circle added on one of the 10-meter sides. The diameter of the half circle is that 10-meter side. Use 3.14 for $\pi$. What is the area of the stage, in square meters?', '["138.5","99.25","217","75.7"]', '99.25', '10*6 + 1/2*3.14*(10/2)^2', 'Rectangle: 10 $\times$ 6 = 60. The half circle has radius 5, so its area is $\frac{1}{2} \times 3.14 \times 5^2 = 39.25$. Total = 99.25 square meters.', 'checked', '{"lint":[],"solve":{"answer":"99.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60. Half circle r = 5: 1/2 x 3.14 x 25 = 39.25. Total 99.25.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ea79ad9-3ff9-42e3-b538-6c885b8794e9', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by adding parts', 'A U-shaped path is made of three rectangles that do not overlap. The two side pieces are each 9 meters long and 2 meters wide. The bottom piece joins them and is 5 meters long and 2 meters wide. What is the total area of the path, in square meters?', '[]', '46', '2*9*2 + 5*2', 'Each side piece: 9 $\times$ 2 = 18, so the two sides are 36. Bottom piece: 5 $\times$ 2 = 10. Total = 46 square meters.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides: 2 x (9 x 2) = 36. Bottom 5 x 2 = 10. Total 46.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c300280-2c5e-4497-ac41-737e78423f67', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A metal washer is a circle with a radius of 10 millimeters, with a circle of radius 4 millimeters cut out of its center. Use 3.14 for $\pi$. What is the area of the metal, in square millimeters?', '["263.76","113.04","364.24","50.24"]', '263.76', '3.14*10^2 - 3.14*4^2', 'Big circle: $3.14 \times 10^2 = 314$. Hole: $3.14 \times 4^2 = 50.24$. Metal: 314 $-$ 50.24 = 263.76 square millimeters.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (100 - 16) = 3.14 x 84 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('670a1d2e-f030-4cc7-90b6-9acb40ed0e73', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A rectangular piece of cardboard is 20 centimeters by 12 centimeters. Four circles, each with a radius of 2 centimeters, are cut out of it. Use 3.14 for $\pi$. What is the area of the cardboard that is left, in square centimeters?', '["227.44","39.04","189.76","50.24"]', '189.76', '20*12 - 4*3.14*2^2', 'Cardboard: 20 $\times$ 12 = 240. Each circle: $3.14 \times 2^2 = 12.56$; four circles: 50.24. Left: 240 $-$ 50.24 = 189.76 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"189.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"240 - 4 x (3.14 x 4) = 240 - 50.24 = 189.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a538d2fd-8cbb-4755-8dce-e9605d1637d8', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a figure with a part removed', 'A square room has sides of 10 feet. A round rug with a diameter of 8 feet lies flat on the floor. Use 3.14 for $\pi$. How many square feet of the floor are not covered by the rug?', '[]', '49.76', '10*10 - 3.14*(8/2)^2', 'Floor: 10 $\times$ 10 = 100. The rug has radius 4, so its area is $3.14 \times 4^2 = 50.24$. Not covered: 100 $-$ 50.24 = 49.76 square feet.', 'checked', '{"lint":[],"solve":{"answer":"49.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Floor 100. Rug r = 4: 3.14 x 16 = 50.24. Uncovered 49.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c482c6fb-d94c-4992-b2fe-8aa47eb1f661', 'NC26.7.SGMR.1', 2, 'choice', 'Perimeter of a composite figure', 'A square with sides of 6 centimeters has an equilateral triangle (all sides 6 centimeters) attached to its top side. What is the distance around the whole figure, in centimeters?', '["42","24","36","30"]', '30', '3*6 + 2*6', 'The side where the triangle is attached is inside the figure. Around the outside there are 3 sides of the square and 2 sides of the triangle: 5 sides of 6 cm, so 30 cm.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared side is inside. Outer edges: 3 square sides + 2 triangle sides = 5 x 6 = 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
