INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d285403-28be-4bbc-a397-d36d8195c11e', 'NC26.7.SGMR.1', 2, 'numeric', 'Perimeter of a composite figure', 'A garden bed is a rectangle 10 meters long and 4 meters wide, with a half circle added to one of the 4-meter ends. The diameter of the half circle is that 4-meter end. Use 3.14 for $\pi$. A fence runs all the way around the outside of the bed. How many meters of fence are needed?', '[]', '30.28', '10 + 10 + 4 + 1/2*3.14*4', 'The fence has two sides of 10 m, one straight end of 4 m, and the curved end. The curve is half a circle: $\frac{1}{2} \times 3.14 \times 4 = 6.28$ m. Total = 10 + 10 + 4 + 6.28 = 30.28 meters.', 'checked', '{"lint":[],"solve":{"answer":"30.28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straight edges: 10 + 10 + 4 = 24. Half circle arc: 1/2 x 3.14 x 4 = 6.28. Total 30.28.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2145baf-7e1e-4a7b-bab1-75aa31a4f368', 'NC26.7.SGMR.1', 2, 'numeric', 'Area problems in context: covering and cost', 'A round patio has a radius of 3 meters. Paving costs 4 dollars per square meter. Use 3.14 for $\pi$. How many dollars does it cost to pave the patio?', '[]', '113.04', '3.14*3^2*4', 'Area = $3.14 \times 3^2 = 28.26$ square meters. Cost = 28.26 $\times$ 4 = 113.04 dollars.', 'checked', '{"lint":[],"solve":{"answer":"113.04","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 3.14 x 9 = 28.26. Cost 28.26 x 4 = 113.04.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb6996c9-8db8-478a-84a5-4e1023373d94', 'NC26.7.SGMR.1', 2, 'numeric', 'Area problems in context: covering and cost', 'A garden bed is a trapezoid. Its parallel sides are 14 feet and 10 feet long, and they are 5 feet apart. Each bag of mulch covers 20 square feet. How many bags are needed to cover the bed once?', '[]', '3', '1/2*(14+10)*5/20', 'Area of the bed: $\frac{1}{2} \times (14 + 10) \times 5 = 60$ square feet. Bags: 60 $\div$ 20 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x 24 x 5 = 60. Bags 60 / 20 = 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('923e17d2-bb51-473b-b079-07699639e550', 'NC26.7.SGMR.1', 2, 'numeric', 'Area problems in context: covering and cost', 'A wall is 12 feet long and 9 feet tall. It has a window that is 3 feet by 4 feet and a door that is 3 feet by 7 feet, and neither is painted. Paint costs 2 dollars per square foot. How many dollars does it cost to paint the rest of the wall?', '[]', '150', '(12*9 - 3*4 - 3*7)*2', 'Wall: 12 $\times$ 9 = 108. Window: 3 $\times$ 4 = 12. Door: 3 $\times$ 7 = 21. Painted area: 108 $-$ 12 $-$ 21 = 75 square feet. Cost: 75 $\times$ 2 = 150 dollars.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wall 108 - window 12 - door 21 = 75 sq ft. Cost 75 x 2 = 150.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a34c7f9b-aaeb-4403-a9ca-2d6314a72798', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a rectangle with a half circle on top', 'A window is a rectangle 6 feet wide and 8 feet tall, with a half circle on top. The half circle''s diameter is the 6-foot width of the window. Use 3.14 for $\pi$. What is the total area of the window, in square feet?', '[]', '62.13', '6*8+3.14*3^2/2', 'Rectangle: $6 \times 8 = 48$ square feet. The half circle has radius $6 \div 2 = 3$ feet, so its area is $\frac{1}{2} \times 3.14 \times 3^2 = 14.13$ square feet. Total: $48 + 14.13 = 62.13$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"62.13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 8 = 48. Half circle r = 3: (1/2)(3.14)(9) = 14.13. Total = 62.13.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9946127-8080-4bb1-a340-d8716cbb1b5d', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a ring around a circle', 'A circular pond has a radius of 4 meters. A path 2 meters wide goes all the way around the pond. Use 3.14 for $\pi$. What is the area of the path, in square meters?', '[]', '62.8', '3.14*6^2-3.14*4^2', 'The pond and path together form a circle of radius $4 + 2 = 6$ meters: $3.14 \times 36 = 113.04$. The pond alone: $3.14 \times 16 = 50.24$. The path: $113.04 - 50.24 = 62.8$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer radius 4 + 2 = 6. Path = 3.14 x (36 - 16) = 3.14 x 20 = 62.8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8950f60d-eb52-4047-836f-30a22ecf4f37', 'NC26.7.SGMR.1', 3, 'choice', 'How doubling the radius changes the area of a circle', 'One pizza has a radius of 6 inches and another has a radius of 12 inches. The area of the larger pizza is how many times the area of the smaller pizza?', '["4","2","8","6"]', '4', '(12/6)^2', 'The area is $\pi r^2$. The radius doubles, so the area is multiplied by $2^2 = 4$. Check: $\pi \times 12^2 = 144\pi$ and $\pi \times 6^2 = 36\pi$, and $144 \div 36 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Areas scale with r^2: (12/6)^2 = 4. (144 pi / 36 pi = 4.)","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce84a709-7fc4-4f30-90b1-b4919ef78e8c', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a triangle', 'A triangle has an area of 43.2 square centimeters and a base of 7.2 centimeters. What is its height, in centimeters?', '[]', '12', '2*43.2/7.2', 'Height = $2 \times$ area $\div$ base = $2 \times 43.2 \div 7.2 = 86.4 \div 7.2 = 12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 2 x 43.2 / 7.2 = 86.4 / 7.2 = 12.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25b9b69f-40d6-4d5c-8f51-f3e69732acd1', 'NC26.7.SGMR.1', 3, 'choice', 'Area of a triangle', 'Triangle P has a base of 10 centimeters and a height of 9 centimeters. Triangle Q has a base of 15 centimeters and a height of 6 centimeters. Which statement is true?', '["Triangle P has the greater area because its height is greater.","Triangle Q has the greater area because its base is longer.","The two triangles have the same area.","Triangle Q has the greater area because 15 + 6 is more than 10 + 9."]', 'The two triangles have the same area.', NULL, 'Triangle P: $\frac{1}{2} \times 10 \times 9 = 45$ square centimeters. Triangle Q: $\frac{1}{2} \times 15 \times 6 = 45$ square centimeters. The areas are equal.', 'checked', '{"lint":[],"solve":{"answer":"The two triangles have the same area.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 1/2 x 10 x 9 = 45. Q: 1/2 x 15 x 6 = 45. Equal.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d08d0dec-c41d-468a-988d-57a4a1675e28', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a triangle', 'A triangle has a base of 6 meters and a height of 10 meters. Its base is stretched to 12 meters while its height stays 10 meters. By how many square meters does the area grow?', '[]', '30', '1/2*12*10 - 1/2*6*10', 'Old area: $\frac{1}{2} \times 6 \times 10 = 30$. New area: $\frac{1}{2} \times 12 \times 10 = 60$. The area grows by 60 $-$ 30 = 30 square meters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before: 1/2 x 6 x 10 = 30. After: 1/2 x 12 x 10 = 60. Growth 60 - 30 = 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12066343-6637-4c66-8a37-6135a7cc7817', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A trapezoid has an area of 70 square centimeters and a height of 7 centimeters. One of its parallel sides is 6 centimeters long. How long is the other parallel side, in centimeters?', '[]', '14', '2*70/7 - 6', 'Area = $\frac{1}{2} \times$ (sum of parallel sides) $\times$ height, so the sum of the parallel sides is $2 \times 70 \div 7 = 20$ centimeters. The other side is 20 $-$ 6 = 14 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70 = 1/2 (6 + b) x 7, so 6 + b = 20, b = 14.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153a80f8-8a6d-49c3-933b-161a5a6357f7', 'NC26.7.SGMR.1', 3, 'choice', 'Area of a parallelogram or trapezoid', 'Which of these four shapes has the greatest area?', '["A trapezoid with parallel sides of 5 cm and 13 cm and a height of 7 cm","A parallelogram with a base of 11 cm and a height of 5 cm","A trapezoid with parallel sides of 7 cm and 9 cm and a height of 6 cm","A rectangle that is 8 cm long and 7 cm wide"]', 'A trapezoid with parallel sides of 5 cm and 13 cm and a height of 7 cm', NULL, 'Parallelogram: $11 \times 5 = 55$. Trapezoid with sides 7 and 9: $\frac{1}{2} \times 16 \times 6 = 48$. Trapezoid with sides 5 and 13: $\frac{1}{2} \times 18 \times 7 = 63$. Rectangle: $8 \times 7 = 56$. The greatest area is 63 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"A trapezoid with parallel sides of 5 cm and 13 cm and a height of 7 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trapezoid A: 1/2 x 18 x 7 = 63. Rectangle: 56. Trapezoid C: 1/2 x 16 x 6 = 48. Parallelogram: 55. Greatest is 63.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5f5c47-70d1-4105-8a34-d1aa5b357a75', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A parallelogram has an area of 91 square inches and a base of 13 inches. A rectangle has the same height as the parallelogram, and its base is 5 inches longer than the parallelogram''s base. What is the area of the rectangle, in square inches?', '[]', '126', '(13+5)*(91/13)', 'Height of the parallelogram = 91 $\div$ 13 = 7 inches. The rectangle''s base is 13 + 5 = 18 inches, so its area is 18 $\times$ 7 = 126 square inches.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 91 / 13 = 7. Rectangle base = 13 + 5 = 18. Area = 18 x 7 = 126.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bd0eafe-9425-469d-ad40-cbd9a7d347dd', 'NC26.7.SGMR.1', 3, 'numeric', 'Circumference of a circle', 'A wheel has a diameter of 60 centimeters. It rolls along the ground for 10 full turns. Use 3.14 for $\pi$. How far does it travel, in centimeters?', '[]', '1884', '3.14*60*10', 'One turn covers the circumference: $3.14 \times 60 = 188.4$ centimeters. In 10 turns it travels 188.4 $\times$ 10 = 1884 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"1884","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = 3.14 x 60 = 188.4. Ten turns = 1884.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bb5ed99-408f-41fc-b6cb-5bf0779abff9', 'NC26.7.SGMR.1', 3, 'numeric', 'Circumference of a circle', 'A wheel has a diameter of 0.5 meter. Use 3.14 for $\pi$. How many full turns does the wheel make to roll exactly 7.85 meters?', '[]', '5', '7.85/(3.14*0.5)', 'One turn covers $3.14 \times 0.5 = 1.57$ meters. Number of turns = 7.85 $\div$ 1.57 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = 3.14 x 0.5 = 1.57 m. 7.85 / 1.57 = 5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3213070b-faf2-4216-b98b-a2c0eb38bf65', 'NC26.7.SGMR.1', 3, 'choice', 'Circumference of a circle', 'A circle has a diameter of 10 centimeters. A square has sides of 8 centimeters. Use 3.14 for $\pi$. Which has the longer distance around, and by how much?', '["The circle, by 0.6 centimeters","The square, by 16.3 centimeters","The square, by 0.6 centimeters","The circle, by 15.4 centimeters"]', 'The square, by 0.6 centimeters', NULL, 'Circle: $3.14 \times 10 = 31.4$ centimeters. Square: $4 \times 8 = 32$ centimeters. The square is longer by 32 $-$ 31.4 = 0.6 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"The square, by 0.6 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circle: 3.14 x 10 = 31.4. Square: 4 x 8 = 32. Square longer by 32 - 31.4 = 0.6.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
