INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d9ffa0f-79d3-47aa-aef1-a20ab94add97', 'NC26.7.SGMR.1', 3, 'choice', 'Perimeter of a composite figure', 'A running track has two straight sides, each 40 meters long, joined at the ends by two half circles. Each half circle has a diameter of 20 meters. Use 3.14 for $\pi$. How far is it once around the track, in meters?', '["205.6","111.4","102.8","142.8"]', '142.8', '2*40 + 3.14*20', 'The two half circles together make one full circle with diameter 20 m: $3.14 \times 20 = 62.8$ m. Add the two straight sides: 80 + 62.8 = 142.8 meters.', 'checked', '{"lint":[],"solve":{"answer":"142.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straights 80. Two half circles = one circle d = 20: 62.8. Total 142.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('457617be-cfcb-4b73-904b-5fb5991a38f3', 'NC26.7.SGMR.1', 3, 'numeric', 'Perimeter of a composite figure', 'An L-shaped room is a 12-foot by 9-foot rectangle with a 5-foot by 4-foot rectangle cut out of one corner. How many feet of baseboard go along all the walls of the room, all the way around?', '[]', '42', '2*(12+9)', 'Cutting a rectangle out of a corner does not change the distance around: the walls still total the same as the original rectangle. $2 \times (12 + 9) = 42$ feet.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cutting a corner rectangle leaves the perimeter equal to the full rectangle''s: sides 12, 9, 7, 5, 5, 4 (sum 42) = 2(12 + 9) = 42.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89ce18b3-712f-47d9-bcc2-2e0f339d7f14', 'NC26.7.SGMR.1', 3, 'numeric', 'Perimeter of a composite figure', 'A flower bed is shaped like a quarter of a circle. Its two straight edges are each 10 feet long (the radius of the circle), and its curved edge is one fourth of the circle''s circumference. Use 3.14 for $\pi$. How many feet of edging go along all three edges?', '[]', '35.7', '10 + 10 + 1/4*2*3.14*10', 'Curved edge = $\frac{1}{4} \times 2 \times 3.14 \times 10 = 15.7$ feet. Total = 10 + 10 + 15.7 = 35.7 feet.', 'checked', '{"lint":[],"solve":{"answer":"35.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two radii 20. Arc = 1/4 x 2 x 3.14 x 10 = 15.7. Total 35.7.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2df7c22-d850-4b5a-b4da-70458d74b908', 'NC26.7.SGMR.1', 3, 'numeric', 'Area problems in context: covering and cost', 'A pizza has a radius of 5 inches and costs 7.85 dollars. Use 3.14 for $\pi$. How many dollars does the pizza cost for each square inch of pizza?', '[]', '0.1', '7.85/(3.14*5^2)', 'Area = $3.14 \times 5^2 = 78.5$ square inches. Cost per square inch = 7.85 $\div$ 78.5 = 0.1 dollars.', 'checked', '{"lint":[],"solve":{"answer":"0.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 3.14 x 25 = 78.5. 7.85 / 78.5 = 0.1 dollars per sq in.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b78c19be-31db-40ad-a66d-8e3e959e1514', 'NC26.7.SGMR.1', 3, 'numeric', 'Area problems in context: covering and cost', 'A rectangular yard is 20 meters long and 15 meters wide. A circular pond with a radius of 5 meters is in the yard. Grass seed is spread on everything except the pond and costs 2 dollars per square meter. Use 3.14 for $\pi$. How many dollars does the grass seed cost?', '[]', '443', '(20*15 - 3.14*5^2)*2', 'Yard: 20 $\times$ 15 = 300. Pond: $3.14 \times 5^2 = 78.5$. Seeded area: 300 $-$ 78.5 = 221.5. Cost: 221.5 $\times$ 2 = 443 dollars.', 'checked', '{"lint":[],"solve":{"answer":"443","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Yard 300 - pond 3.14 x 25 = 78.5 gives 221.5. Cost 221.5 x 2 = 443.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2181b22e-2410-41b2-afc5-0b51b1769136', 'NC26.7.SGMR.1', 3, 'choice', 'Area problems in context: covering and cost', 'A square floor has sides of 8 meters. A round floor has a diameter of 10 meters. Use 3.14 for $\pi$. Tile costs the same for each square meter. Which floor needs more tile, and by how many square meters?', '["The round floor, by 14.5 square meters","The square floor, by 14.5 square meters","The round floor, by 250 square meters","The square floor, by 32.6 square meters"]', 'The round floor, by 14.5 square meters', NULL, 'Square floor: 8 $\times$ 8 = 64 square meters. Round floor: radius 5, area $3.14 \times 5^2 = 78.5$ square meters. The round floor needs more, by 14.5 square meters.', 'checked', '{"lint":[],"solve":{"answer":"The round floor, by 14.5 square meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square 64. Round r = 5: 78.5. Round larger by 14.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0391ce-1839-47ce-999d-fd1d4dc216ba', 'NC26.7.SGMR.2', 1, 'numeric', 'Volume from base area and height', 'The base of a right prism has an area of 12 square centimeters. The prism is 7 centimeters tall. What is its volume in cubic centimeters?', '[]', '84', '12*7', 'A right prism is the base layer repeated for the whole height. Volume = area of base $\times$ height = $12 \times 7 = 84$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = base area x height = 12 x 7 = 84.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44f62f3b-6391-4e0b-af81-edf3b800e6b0', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a cube', 'A cube has edges that are each 5 centimeters long. What is its surface area in square centimeters?', '["125","150","30","100"]', '150', '6*5*5', 'A cube has 6 faces. Each face is a square with area $5 \times 5 = 25$ square centimeters. Surface area = $6 \times 25 = 150$. (125 is the volume, 30 is $6 \times 5$, and 100 counts only 4 faces.)', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 faces, each 5 x 5 = 25; SA = 6 x 25 = 150.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('424cb64e-15d5-4845-b6b2-dedefa028864', 'NC26.7.SGMR.2', 1, 'numeric', 'Find the height from the volume', 'A rectangular box has a volume of 90 cubic centimeters. Its base measures 6 centimeters by 5 centimeters. How tall is the box in centimeters?', '[]', '3', '90/(6*5)', 'The base has area $6 \times 5 = 30$ square centimeters. Volume = base area $\times$ height, so height = $90 \div 30 = 3$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area 6 x 5 = 30; height = 90 / 30 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
