VALUES ('a951af9a-6790-4a25-8ff5-e49e74a0c792', 'NC26.7.SGMR.2', 1, 'choice', 'Volume of a cylinder', 'Which formula gives the volume of a cylinder with radius $r$ and height $h$?', '["$V = 2\\pi r h$","$V = \\pi r h$","$V = \\pi r^2 h$","$V = \\pi r^2 + h$"]', '$V = \pi r^2 h$', NULL, 'The base is a circle of area $\pi r^2$, and the volume is the base area times the height: $V = \pi r^2 h$.', 'checked', '{"lint":[],"solve":{"answer":"$V = \\pi r^2 h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area pi r^2 times height h.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
