VALUES ('a8da76ef-ef70-4776-9336-57d8a0c60643', 'NC26.7.SGMR.2', 1, 'choice', 'Volume of a cylinder', 'A round candle is a cylinder with a radius of 5 centimeters and a height of 2 centimeters. Use 3.14 for $\pi$. What is its volume, in cubic centimeters?', '["157","62.8","31.4","628"]', '157', '3.14*5^2*2', 'Volume = $\pi r^2 h = 3.14 \times 5 \times 5 \times 2 = 157$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x 25 x 2 = 157.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
