INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efa23d83-3f91-4ca0-81f0-6b1d490396be', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a rectangular prism or cube', 'The faces of a rectangular box come in three matching pairs. The top and bottom are each 12 square inches, the front and back are each 8 square inches, and the two sides are each 6 square inches. What is the total surface area of the box, in square inches?', '["26","52","576","40"]', '52', '2*12+2*8+2*6', 'Add all six faces: 2 $\times$ 12 + 2 $\times$ 8 + 2 $\times$ 6 = 24 + 16 + 12 = 52 square inches.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12 + 8 + 6) = 52. (Consistent with a 4 x 3 x 2 box.)","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
