INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('764564fc-6814-4762-a495-20d1b64ca732', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The net of a closed box is made of six rectangles: two that are 5 cm by 3 cm, two that are 5 cm by 2 cm, and two that are 3 cm by 2 cm. What is the total area of the net, in square centimeters?', '["62","31","30","124"]', '62', '2*5*3+2*5*2+2*3*2', 'Add the areas of all six rectangles: 2 $\times$ 15 + 2 $\times$ 10 + 2 $\times$ 6 = 30 + 20 + 12 = 62 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(15) + 2(10) + 2(6) = 62.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
