INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11700154-11d2-48af-9140-831017637a34', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a rectangular prism', 'How many 1-centimeter cubes fit exactly inside a box that is 10 cm long, 7 cm wide and 5 cm tall?', '["22","70","350","175"]', '350', '10*7*5', 'The number of 1-centimeter cubes equals the volume in cubic centimeters: 10 $\times$ 7 $\times$ 5 = 350.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 7 x 5 = 350 unit cubes.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
