VALUES ('c4851448-1fce-4e95-9c51-ef626ebf8d9d', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a rectangular prism', 'A classroom is 9 meters long, 7 meters wide and 3 meters high. How many cubic meters of air does the room hold?', '["19","189","63","378"]', '189', '9*7*3', 'Volume = 9 $\times$ 7 $\times$ 3 = 63 $\times$ 3 = 189 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"189","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 7 x 3 = 189.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
