INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('820ae5a7-683c-4cce-ad3f-fa19da1351cd', 'NC26.7.SGMR.2', 2, 'choice', 'Volume as layers of the base', 'Maya builds a rectangular prism from unit cubes. The bottom layer is 7 cubes long and 3 cubes wide. She stacks 4 layers like it. How many cubes does she use?', '["14","21","84","28"]', '84', '7*3*4', 'One layer has 7 $\times$ 3 = 21 cubes. With 4 layers she uses 21 $\times$ 4 = 84 cubes.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Layer 7 x 3 = 21; 4 layers = 84.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
