INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdf849dd-470a-47d6-9a22-0fd3817137b9', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a triangular or trapezoidal prism', 'A small tent is shaped like a triangular prism. Each triangular end has a base of 4 meters and a height of 3 meters, and the tent is 5 meters long. How many cubic meters of space are inside the tent?', '["60","30","10","12"]', '30', '1/2*4*3*5', 'Area of a triangular end = $\frac{1}{2} \times 4 \times 3 = 6$ square meters. Volume = 6 $\times$ 5 = 30 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"End area 1/2 x 4 x 3 = 6; V = 6 x 5 = 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
