INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69e00057-c5bf-44db-84dc-88c2c12e5f9e', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a cylinder', 'A cylinder has a radius of 7 centimeters and a height of 6 centimeters. Use $\frac{22}{7}$ for $\pi$. What is its volume, in cubic centimeters?', '[]', '924', '(22/7)*7^2*6', 'Volume = $\pi r^2 h = \frac{22}{7} \times 7 \times 7 \times 6 = 924$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"924","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22/7 x 49 x 6 = 154 x 6 = 924.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
