INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d19685d-41a0-4181-b16c-55174d3991b8', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area of a rectangular prism or cube', 'An aquarium is a glass rectangular box with no top. Its base is 40 cm by 25 cm and it is 30 cm tall. How many square centimeters of glass are used?', '[]', '4900', '40*25 + 2*40*30 + 2*25*30', 'Base: 40 $\times$ 25 = 1000. Two long sides: 2 $\times$ 40 $\times$ 30 = 2400. Two short sides: 2 $\times$ 25 $\times$ 30 = 1500. Total = 4900 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4900","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 40 x 25 = 1000; 2(40 x 30) = 2400; 2(25 x 30) = 1500. Total 4900.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7417b8cd-ab07-4487-9e3f-638ecd2e3a70', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The ends of a prism are right triangles with sides of 6 cm, 8 cm and 10 cm. The prism is 5 cm long. What is its total surface area, in square centimeters?', '[]', '168', '2*(1/2*6*8) + (6+8+10)*5', 'Two triangular ends: 2 $\times$ $\frac{1}{2} \times 6 \times 8$ = 48. Three rectangles together: (6 + 8 + 10) $\times$ 5 = 24 $\times$ 5 = 120. Total = 48 + 120 = 168 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 8) = 48. Sides (6 + 8 + 10) x 5 = 120. Total 168.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bc9c0ab-dc72-4f05-b667-1703897ee735', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area as the sum of the faces (nets and triangular prisms)', 'A tent has two triangular ends and two rectangular sloping sides, and no floor. Each triangular end has a base of 6 m and a height of 4 m, and its two slanted sides are 5 m each. Each rectangular sloping side measures 5 m by 8 m. How many square meters of fabric are used for the two ends and the two sloping sides?', '["152","104","80","128"]', '104', '2*(1/2*6*4)+2*5*8', 'Two triangular ends: 2 $\times$ $\frac{1}{2} \times 6 \times 4$ = 24. Two sloping sides: 2 $\times$ 5 $\times$ 8 = 80. Total = 24 + 80 = 104 square meters. (A floor of 6 $\times$ 8 = 48 would add more.)', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 4) = 24. Sloping sides 2 x 40 = 80. Total 104.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82b5f163-3e98-4d2b-9d47-e063878f6586', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The three rectangular faces of a triangular prism unfold into one long rectangle. The triangular ends have sides of 7 cm, 8 cm and 9 cm, and the prism is 10 cm long. What is the area of the long rectangle, in square centimeters?', '["24","240","504","120"]', '240', '(7+8+9)*10', 'The long rectangle is as wide as the distance around the triangle, 7 + 8 + 9 = 24 cm, and 10 cm tall. Area = 24 $\times$ 10 = 240 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Long rectangle = perimeter of triangle x length = 24 x 10 = 240.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1e36b0e-b5e4-4110-bc5f-cfa933307230', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a cylinder', 'A closed cylinder has a radius of 3 cm and a height of 8 cm. Use 3.14 for $\pi$. What is its total surface area, in square centimeters?', '["207.24","150.72","56.52","178.98"]', '207.24', '2*3.14*3^2+2*3.14*3*8', 'Two circular ends: 2 $\times$ 3.14 $\times$ $3^2$ = 56.52. Curved side: 2 $\times$ 3.14 $\times$ 3 $\times$ 8 = 150.72. Total = 207.24 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"207.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 3.14 x 9 = 56.52. Side 2 x 3.14 x 3 x 8 = 150.72. Total 207.24.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
