INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ebd9088-03a5-4fd1-a1d7-b86e5d6fe7c0', 'NC26.7.SGMR.2', 2, 'numeric', 'Unknown dimension from volume or surface area', 'A rectangular prism has a base that is 8 cm by 5 cm and a volume of 340 cubic centimeters. How tall is the prism, in centimeters?', '[]', '8.5', '340/(8*5)', 'Base area = 8 $\times$ 5 = 40 square centimeters. Height = 340 $\div$ 40 = 8.5 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"340 / 40 = 8.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
