INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a591f190-ea10-4a03-89f3-cf856f30b5c3', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a composite solid', 'A trophy has a base that is a rectangular block 10 cm by 6 cm by 4 cm. A cylinder with a radius of 3 cm and a height of 2 cm stands on top of it. Use 3.14 for $\pi$. What is the volume of the whole trophy, in cubic centimeters?', '[]', '296.52', '10*6*4 + 3.14*3^2*2', 'Block: 10 $\times$ 6 $\times$ 4 = 240. Cylinder: $3.14 \times 3^2 \times 2 = 56.52$. Total = 240 + 56.52 = 296.52 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"296.52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Block 240. Cylinder 3.14 x 9 x 2 = 56.52. Total 296.52.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bce48620-16b6-41c9-8733-6addd05b2ae0', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a composite solid', 'A shed is a rectangular prism 6 m long, 4 m wide and 3 m tall, with a roof that is a triangular prism. Each triangular end of the roof has a base of 4 m and a height of 1.5 m, and the roof is 6 m long. What is the volume of the whole shed, including the roof space, in cubic meters?', '["90","108","75","144"]', '90', '6*4*3+1/2*4*1.5*6', 'Rectangular part: 6 $\times$ 4 $\times$ 3 = 72. Roof: $\frac{1}{2} \times 4 \times 1.5 = 3$ square meters for one end, and 3 $\times$ 6 = 18 cubic meters. Total = 72 + 18 = 90 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Box 6 x 4 x 3 = 72. Roof 1/2 x 4 x 1.5 x 6 = 18. Total 90.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b47da22c-66c4-49b4-81c3-8b6adccbffaa', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a composite solid', 'The base of a prism is an L-shape made from a 10 cm by 4 cm rectangle and a 6 cm by 3 cm rectangle that touch along an edge and do not overlap. The prism is 5 cm tall. What is its volume, in cubic centimeters?', '[]', '290', '(10*4 + 6*3)*5', 'Area of the L-shaped base = 10 $\times$ 4 + 6 $\times$ 3 = 40 + 18 = 58. Volume = 58 $\times$ 5 = 290 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"290","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area 40 + 18 = 58. V = 58 x 5 = 290.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb2262ac-5cee-45ce-a87f-bdb3ad456a1b', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a composite solid', 'Two cubes with edges of 3 cm are glued together face to face. What is the surface area of the new solid, in square centimeters?', '["108","54","90","99"]', '90', '2*6*3^2-2*3^2', 'Each cube has a surface area of 6 $\times$ $3^2$ = 54. Two cubes have 108. The two glued faces (3 $\times$ 3 = 9 each) are hidden, so subtract 2 $\times$ 9 = 18. Surface area = 90 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Makes a 3 x 3 x 6 box: 2(9 + 18 + 18) = 90.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bdec067-de26-4ede-b2db-878c0df3edf0', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a composite solid', 'A cube with edges of 3 cm is glued to the end of a rectangular box that is 3 cm by 3 cm by 6 cm, so that the 3 cm by 3 cm faces match exactly. What is the surface area of the new solid, in square centimeters?', '["126","144","90","54"]', '126', '2*(3*3+3*9+3*9)', 'The new solid is a box 3 cm by 3 cm by 9 cm. Surface area = 2(3 $\times$ 3 + 3 $\times$ 9 + 3 $\times$ 9) = 2(9 + 27 + 27) = 126 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Makes a 3 x 3 x 9 box: 2(9 + 27 + 27) = 126.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
