INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4400b9d-a37f-4a8b-a045-c40a0ded31c1', 'NC26.7.SGMR.2', 3, 'choice', 'Volume of a rectangular prism', 'A rectangular prism has a volume of 120 cubic centimeters. Which could be its length, width and height?', '["10 cm by 6 cm by 4 cm","7 cm by 5 cm by 4 cm","8 cm by 5 cm by 3 cm","6 cm by 5 cm by 5 cm"]', '8 cm by 5 cm by 3 cm', NULL, '$8 \times 5 \times 3 = 120$. The others give $10 \times 6 \times 4 = 240$, $7 \times 5 \times 4 = 140$ and $6 \times 5 \times 5 = 150$.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 5 cm by 3 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x5x4 = 140; 8x5x3 = 120; 6x5x5 = 150; 10x6x4 = 240. Only 8 by 5 by 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
