INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dd445e5-c415-4bb0-8018-c10977be3c83', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume as layers of the base', 'A solid is built from layers of unit cubes. The bottom 3 layers have 40 cubes each, and the top 2 layers have 28 cubes each. How many cubes are in the solid?', '[]', '176', '40*3 + 28*2', 'Bottom layers: 40 $\times$ 3 = 120. Top layers: 28 $\times$ 2 = 56. Total = 120 + 56 = 176 cubes.', 'checked', '{"lint":[],"solve":{"answer":"176","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 40 + 2 x 28 = 120 + 56 = 176.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
