INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5f8b7c1-f9b8-42c7-a98c-e455f2f0e1f8', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a triangular or trapezoidal prism', 'A box for chocolates is a triangular prism. Each triangular end has a base of 4.5 centimeters and a height of 4 centimeters, and the box is 30 centimeters long. What is the volume of the box, in cubic centimeters?', '[]', '270', '1/2*4.5*4*30', 'Area of a triangular end = $\frac{1}{2} \times 4.5 \times 4 = 9$ square centimeters. Volume = 9 $\times$ 30 = 270 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"270","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"End area 1/2 x 4.5 x 4 = 9; V = 9 x 30 = 270.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
