INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d643098-2c68-4d0b-8e51-2003167c44f9', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a cylinder', 'A full cylindrical can has a radius of 10 cm and a height of 20 cm. All of the water in it is poured into an empty rectangular tank whose base is 20 cm by 10 cm. Use 3.14 for $\pi$. How deep is the water in the tank, in centimeters?', '[]', '31.4', '3.14*10^2*20/(20*10)', 'Volume of water = $3.14 \times 10^2 \times 20 = 6280$ cubic cm. Base of the tank = 20 $\times$ 10 = 200 square cm. Depth = 6280 $\div$ 200 = 31.4 cm.', 'checked', '{"lint":[],"solve":{"answer":"31.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Can: 3.14 x 100 x 20 = 6280. Tank base 200. Depth 6280 / 200 = 31.4.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3baeac0b-fe61-4b82-95e3-978aad72feae', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a cylinder', 'A metal pipe is a hollow cylinder 10 cm long. Its outer radius is 5 cm, and the hole through it has a radius of 4 cm. Use 3.14 for $\pi$. What is the volume of the metal in the pipe, in cubic centimeters?', '[]', '282.6', '3.14*(5^2 - 4^2)*10', 'Outer cylinder: $3.14 \times 5^2 \times 10 = 785$. Hole: $3.14 \times 4^2 \times 10 = 502.4$. Metal = 785 $-$ 502.4 = 282.6 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"282.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (25 - 16) x 10 = 3.14 x 90 = 282.6.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd7b2295-8873-49fc-90ec-2f3c92e32c11', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a rectangular prism or cube', 'A shed is a rectangular box that is 4 meters long, 3 meters wide and 2.5 meters tall. The four walls and the flat roof are painted, but not the floor. What is the area painted, in square meters?', '[]', '47', '2*4*2.5 + 2*3*2.5 + 4*3', 'Long walls: 2 $\times$ 4 $\times$ 2.5 = 20. Short walls: 2 $\times$ 3 $\times$ 2.5 = 15. Roof: 4 $\times$ 3 = 12. Total = 47 square meters.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walls 2(4 x 2.5) + 2(3 x 2.5) = 20 + 15 = 35; roof 12. Total 47.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cba33488-9bf3-42ec-9cff-8a0ed5eff57c', 'NC26.7.SGMR.2', 3, 'choice', 'Surface area of a rectangular prism or cube', 'Which box has the greatest surface area?', '["12 cm by 2 cm by 1 cm","4 cm by 4 cm by 3 cm","5 cm by 3 cm by 3 cm","7 cm by 3 cm by 2 cm"]', '7 cm by 3 cm by 2 cm', NULL, '$7 \times 3 \times 2$: $2(21 + 14 + 6) = 82$. $12 \times 2 \times 1$: $2(24 + 12 + 2) = 76$. $4 \times 4 \times 3$: $2(16 + 12 + 12) = 80$. $5 \times 3 \times 3$: $2(15 + 15 + 9) = 78$. The greatest is 82 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7 cm by 3 cm by 2 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x3x3: 2(15+15+9) = 78. 12x2x1: 2(24+12+2) = 76. 4x4x3: 2(16+12+12) = 80. 7x3x2: 2(21+14+6) = 82. Greatest 82.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31caca73-03ed-41a6-b1f2-814efb466581', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The ends of a prism are triangles with sides of 5 cm, 5 cm and 6 cm. The height of each triangle, measured to the 6 cm side, is 4 cm. The prism is 10 cm long. What is its total surface area, in square centimeters?', '[]', '184', '2*(1/2*6*4) + (5+5+6)*10', 'Each triangular end: $\frac{1}{2} \times 6 \times 4 = 12$, so two ends are 24. The three rectangles together: (5 + 5 + 6) $\times$ 10 = 160. Total = 24 + 160 = 184 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"184","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 4) = 24. Sides 16 x 10 = 160. Total 184.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b771b316-63ab-4373-8e0b-66320c3a757c', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area as the sum of the faces (nets and triangular prisms)', 'A triangular prism has right-triangle ends with sides of 9 cm, 12 cm and 15 cm, and it is 20 cm long. It sits on a table on its 15 cm by 20 cm rectangular face, and every other face is painted. What is the painted area, in square centimeters?', '[]', '528', '2*(1/2*9*12) + (9+12+15)*20 - 15*20', 'Two ends: 2 $\times$ $\frac{1}{2} \times 9 \times 12$ = 108. Rectangles: (9 + 12 + 15) $\times$ 20 = 720. Total surface = 828. The face on the table, 15 $\times$ 20 = 300, is not painted: 828 $-$ 300 = 528 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"528","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 9 x 12) = 108. Rectangles 9 x 20 = 180 and 12 x 20 = 240 (15 x 20 face unpainted). 108 + 180 + 240 = 528.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a9746f0-9c9e-4842-a796-4601d122a711', 'NC26.7.SGMR.2', 3, 'choice', 'Surface area of a cylinder', 'A closed cylinder has a radius of 4 cm and a height of 10 cm. What is its total surface area, in square centimeters, in terms of $\pi$?', '["$80\\pi$","$32\\pi$","$112\\pi$","$160\\pi$"]', '$112\pi$', NULL, 'Two circular ends: $2 \times \pi \times 4^2 = 32\pi$. Curved side: $2 \times \pi \times 4 \times 10 = 80\pi$. Total = $112\pi$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$112\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 16 pi = 32 pi. Side 2 pi x 4 x 10 = 80 pi. Total 112 pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c4381e-4d5b-45e3-84d5-efd8b9a3310c', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a cylinder', 'A closed cylindrical tank has a radius of 2 meters and a height of 5 meters. Its whole outside is painted with paint that costs 3 dollars per square meter. Use 3.14 for $\pi$. How many dollars does the paint cost?', '[]', '263.76', '(2*3.14*2^2 + 2*3.14*2*5)*3', 'Ends: 2 $\times$ 3.14 $\times$ $2^2$ = 25.12. Curved side: 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Surface area = 87.92 square meters. Cost = 87.92 $\times$ 3 = 263.76 dollars.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 3.14 x 4 = 25.12. Side 2 x 3.14 x 2 x 5 = 62.8. Total 87.92. Cost 87.92 x 3 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57c394a1-4700-4e5e-945e-678bbcd0056d', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a cylinder', 'The curved side of a cylinder has an area of 188.4 square centimeters, and the cylinder is 10 centimeters tall. Use 3.14 for $\pi$. What is the radius of the cylinder, in centimeters?', '[]', '3', '188.4/(2*3.14*10)', 'Curved side = 2 $\times$ 3.14 $\times$ radius $\times$ height, so the radius is 188.4 $\div$ (2 $\times$ 3.14 $\times$ 10) = 188.4 $\div$ 62.8 = 3 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circumference = 188.4 / 10 = 18.84 = 2 x 3.14 x r, so r = 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea675f5e-7e2f-40d4-8fea-64f54df21151', 'NC26.7.SGMR.2', 3, 'numeric', 'Unknown dimension from volume or surface area', 'A closed rectangular box has a base that is 5 cm by 4 cm. Its total surface area is 94 square centimeters. How tall is the box, in centimeters?', '[]', '3', '(94 - 2*5*4)/(2*(5+4))', 'Top and bottom: 2 $\times$ 5 $\times$ 4 = 40. The four sides must have area 94 $-$ 40 = 54. The four sides have a total width of 2 $\times$ (5 + 4) = 18, so the height is 54 $\div$ 18 = 3 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(20) + 2(5h) + 2(4h) = 40 + 18h = 94, so 18h = 54, h = 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('683d094a-4ff1-4dcc-b949-8227d3691d9d', 'NC26.7.SGMR.2', 3, 'numeric', 'Unknown dimension from volume or surface area', 'A rectangular tank has a base that is 50 cm by 30 cm. It holds 45 liters of water. One liter is 1000 cubic centimeters. How deep is the water, in centimeters?', '[]', '30', '45*1000/(50*30)', 'Volume of water = 45 $\times$ 1000 = 45000 cubic centimeters. Base area = 50 $\times$ 30 = 1500. Depth = 45000 $\div$ 1500 = 30 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 L = 45000 cm^3. Base 1500. Depth 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
