INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5431aa2a-b217-4d58-bcdc-ccbfe888be76', 'NC26.7.SGMR.2', 3, 'choice', 'Unknown dimension from volume or surface area', 'Which solid has a volume of 150 cubic centimeters?', '["A rectangular prism that is 6 cm by 5 cm by 10 cm","A triangular prism whose ends have a base of 6 cm and a height of 5 cm, and which is 10 cm long","A cylinder with a radius of 5 cm and a height of 2 cm, using 3.14 for $\\pi$","A cube with edges of 5 cm"]', 'A triangular prism whose ends have a base of 6 cm and a height of 5 cm, and which is 10 cm long', NULL, 'Triangular prism: $\frac{1}{2} \times 6 \times 5 \times 10 = 150$. The rectangular prism is $6 \times 5 \times 10 = 300$, the cylinder is $3.14 \times 25 \times 2 = 157$, and the cube is $5^3 = 125$.', 'checked', '{"lint":[],"solve":{"answer":"A triangular prism whose ends have a base of 6 cm and a height of 5 cm, and which is 10 cm long","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rect 300; cube 125; cylinder 3.14 x 25 x 2 = 157; triangular prism 1/2 x 6 x 5 x 10 = 150.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d713b282-413f-4707-9437-907aefbf3c3a', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A cake has three round layers (cylinders) stacked on each other. Each layer is 5 cm tall. The radii of the layers are 6 cm, 4 cm and 2 cm. Use 3.14 for $\pi$. What is the total volume of the cake, in cubic centimeters?', '[]', '879.2', '3.14*5*(6^2 + 4^2 + 2^2)', 'Layer volumes: $3.14 \times 6^2 \times 5 = 565.2$, $3.14 \times 4^2 \times 5 = 251.2$ and $3.14 \times 2^2 \times 5 = 62.8$. Total = 879.2 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"879.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (36 + 16 + 4) x 5 = 3.14 x 280 = 879.2.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044540df-be75-4969-a1ea-89045af5faf7', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A building is a rectangular prism 12 m long, 8 m wide and 6 m tall. Its roof is a triangular prism 12 m long, with triangular ends that have a base of 8 m and a height of 3 m. A chimney shaped like a 2 m by 2 m by 3 m box stands on the roof. What is the volume of the building, roof and chimney together, in cubic meters?', '[]', '732', '12*8*6 + 1/2*8*3*12 + 2*2*3', 'Rectangular part: 12 $\times$ 8 $\times$ 6 = 576. Roof: $\frac{1}{2} \times 8 \times 3 \times 12 = 144$. Chimney: 2 $\times$ 2 $\times$ 3 = 12. Total = 576 + 144 + 12 = 732 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"732","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a box cannot stand flat on a sloped roof without part of it overlapping the roof; the intended reading (just add 12) is clear at this grade.","work":"Building 12 x 8 x 6 = 576. Roof 1/2 x 8 x 3 x 12 = 144. Chimney 2 x 2 x 3 = 12. Total 732.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f35d131f-5840-481d-861c-35da5b6e5e2a', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A tower is made of two prisms stacked on each other. Both have a base that is 5 cm by 4 cm. The lower prism is 3 cm tall. The whole tower has a volume of 100 cubic centimeters. How tall is the upper prism, in centimeters?', '[]', '2', '100/(5*4) - 3', 'Base area = 5 $\times$ 4 = 20 square centimeters. The whole tower is 100 $\div$ 20 = 5 cm tall. The upper prism is 5 $-$ 3 = 2 centimeters tall.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower 20 x 3 = 60. Upper 100 - 60 = 40. Height 40 / 20 = 2.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20567c4c-dbc9-4a39-9f0f-a292c9e63731', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a composite solid', 'A cube with edges of 2 cm sits in the middle of the top face of a cube with edges of 4 cm. What is the surface area of the combined solid, in square centimeters?', '[]', '112', '6*4^2 + 4*2^2', 'The top of the small cube covers 2 $\times$ 2 = 4 square cm of the big cube, but it shows the same amount on its own top. So the flat surfaces total 6 $\times$ $4^2$ = 96, and the four sides of the small cube add 4 $\times$ 4 = 16. Total = 112 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"112","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Big cube 96 (hidden 4 on top replaced by small cube''s top). Add small cube''s 4 sides 4 x 4 = 16. Total 112.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70bcf5e0-89be-440d-a08c-f4ec73705522', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a composite solid', 'The base of a prism is an L-shape with six sides of 6 cm, 2 cm, 4 cm, 3 cm, 2 cm and 5 cm (in order around the L). The area of the L is 18 square centimeters. The prism is 4 cm tall. What is its total surface area, in square centimeters?', '[]', '124', '2*18 + (6+2+4+3+2+5)*4', 'Top and bottom: 2 $\times$ 18 = 36. The distance around the L is 6 + 2 + 4 + 3 + 2 + 5 = 22 cm, so the sides total 22 $\times$ 4 = 88. Total = 36 + 88 = 124 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"124","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 6 + 2 + 4 + 3 + 2 + 5 = 22 (L checks: 6 = 4 + 2, 5 = 2 + 3, area 12 + 6 = 18). SA = 2 x 18 + 22 x 4 = 36 + 88 = 124.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2c0959e-6525-4388-b094-f3cf01dddfd0', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a composite solid', 'A cube with edges of 6 cm has a square hole 2 cm by 2 cm drilled straight through the middle, from one face to the opposite face. What is the surface area of the solid that is left, including the inside of the hole, in square centimeters?', '[]', '256', '6*6^2 - 2*2^2 + 4*2*6', 'The cube has 6 $\times$ $6^2$ = 216. Two faces lose a 2 by 2 square: $-$ 2 $\times$ 4 = $-$ 8. The inside of the hole has 4 walls, each 2 by 6: 4 $\times$ 12 = 48. Total = 256 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"256","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"216 - 2 x 4 = 208 outside. Hole walls 4 x (2 x 6) = 48. Total 256.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b05a0673-8d88-4242-9dd6-8e3a54255c9f', 'NC26.7.SGMR.2', 3, 'choice', 'Surface area of a composite solid', 'Two cylinders are stacked with the same center line. The bottom cylinder has a radius of 4 cm and a height of 3 cm. The top cylinder has a radius of 2 cm and a height of 5 cm. What is the surface area of the combined solid, in square centimeters, in terms of $\pi$?', '["$84\\pi$","$76\\pi$","$56\\pi$","$44\\pi$"]', '$76\pi$', NULL, 'The bottom cylinder alone has $2\pi(4^2) + 2\pi(4)(3) = 32\pi + 24\pi = 56\pi$. The top cylinder covers a circle of the bottom cylinder but shows an equal circle on its own top, so only its curved side is new: $2\pi(2)(5) = 20\pi$. Total = $56\pi + 20\pi = 76\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$76\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flat parts: bottom 16 pi + exposed ring 12 pi + small top 4 pi = 32 pi. Sides: 2 pi x 4 x 3 = 24 pi and 2 pi x 2 x 5 = 20 pi. Total 76 pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('244808c7-ddbf-4d46-aa3e-a1ff30a9412c', 'NC26.7.SGMR.2', 3, 'choice', 'How changing dimensions changes volume', 'The height of a cylinder is doubled and its radius is cut in half. What happens to the volume?', '["It stays the same","It becomes twice as large","It becomes half as large","It becomes one fourth as large"]', 'It becomes half as large', NULL, 'Volume = $\pi r^2 h$. Halving $r$ multiplies the volume by $\frac{1}{2} \times \frac{1}{2} = \frac{1}{4}$, and doubling $h$ multiplies it by 2. Together: $\frac{1}{4} \times 2 = \frac{1}{2}$, so the volume is half as large.', 'checked', '{"lint":[],"solve":{"answer":"It becomes half as large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^2 x 2 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3c8b34f-6fb0-43fc-9294-b334bd50a5d3', 'NC26.7.SGMR.2', 3, 'numeric', 'How changing dimensions changes volume', 'A rectangular prism has a volume of 40 cubic centimeters. Its length is doubled, its width is tripled and its height is cut in half. What is the volume of the new prism, in cubic centimeters?', '[]', '120', '40*2*3/2', 'The volume is multiplied by 2 $\times$ 3 $\times$ $\frac{1}{2}$ = 3. New volume = 40 $\times$ 3 = 120 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 x 2 x 3 x 1/2 = 120.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cb1fa44-be45-47ba-b33a-bc37ae0581e5', 'NC26.7.SGMR.2', 3, 'numeric', 'How changing dimensions changes volume', 'A cube has edges of 3 cm. Every edge is made twice as long. By how many square centimeters does the surface area of the cube increase?', '[]', '162', '6*(2*3)^2 - 6*3^2', 'Old surface area: 6 $\times$ $3^2$ = 54. New edge: 6 cm, so the new surface area is 6 $\times$ $6^2$ = 216. Increase = 216 $-$ 54 = 162 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"162","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 6 x 9 = 54. New edge 6: 6 x 36 = 216. Increase 162.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
