INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4af28b0-bdd7-4f3e-b272-8c9f5d80b916', 'NC26.7.SGMR.3', 1, 'choice', 'Complementary angles: find the missing angle', 'What is the measure, in degrees, of the complement of an angle that measures $71^\circ$?', '["109","161","45","19"]', '19', '90-71', 'The complement is the angle that adds with $71^\circ$ to make $90^\circ$: $90 - 71 = 19$. The choice 109 is the supplement ($180 - 71$), 161 adds $90 + 71$, and 45 assumes the two angles are equal.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement of 71 = 90 - 71 = 19.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
