INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c2c9c77-6d10-43d8-b734-8125ccae3f7e', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles: find the missing angle', 'A wooden shelf bracket is fixed in a square corner of a wall (a right angle). It splits the corner into two angles. One of the angles is $40^\circ$. What is the other angle, in degrees?', '[]', '50', '90-40', 'A square corner is $90^\circ$, so the two parts add up to $90^\circ$. The other angle is $90 - 40 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The two angles fill a right angle: 90 - 40 = 50.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
