INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e737354-5147-4906-a28b-90ebaf0a4a78', 'NC26.7.SGMR.3', 1, 'choice', 'Complementary angles: find the missing angle', 'Which statement about complementary angles is true?', '["Their measures add up to $180^\\circ$.","Their measures are always equal.","Their measures add up to $90^\\circ$.","Their measures add up to $360^\\circ$."]', 'Their measures add up to $90^\circ$.', NULL, 'Complementary angles are two angles whose measures add up to $90^\circ$, a right angle. Angles that add up to $180^\circ$ are supplementary. Complementary angles need not be equal (for example $30^\circ$ and $60^\circ$).', 'checked', '{"lint":[],"solve":{"answer":"Their measures add up to $90^\\circ$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complementary angles sum to 90 degrees by definition. 180 is supplementary; 360 is a full turn; they need not be equal.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbb7fcd1-e65c-47d1-8d02-e0e830c9f4d8', 'NC26.7.SGMR.3', 1, 'numeric', 'Supplementary angles: find the missing angle', 'Angle $M$ and angle $N$ are supplementary, which means that together they make a straight angle. Angle $M$ measures $125^\circ$. How many degrees is angle $N$?', '[]', '55', '180-125', 'Supplementary angles add up to $180^\circ$. So angle $N$ is $180 - 125 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M + N = 180, N = 180 - 125 = 55.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
