INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fa33ec2-869d-417e-8ccb-e87b88e21265', 'NC26.7.SGMR.3', 1, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOB$ measures $30^\circ$ and the angle next to it, angle $BOC$, measures $45^\circ$. They share ray $OB$ and do not overlap. What is the measure of angle $AOC$ in degrees?', '[]', '75', '30+45', 'The two adjacent angles together make angle $AOC$, so $30 + 45 = 75$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent, non-overlapping: AOC = 30 + 45 = 75.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
