VALUES ('a6df2475-c186-4a10-8855-d27118c5d76b', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles with expressions (equation)', 'Two angles are complementary. One measures $(x + 20)^\circ$ and the other measures $50^\circ$. What is $x$?', '[]', '20', '90-50-20', 'Complementary angles add up to 90: $(x + 20) + 50 = 90$. So $x + 70 = 90$ and $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 20 + 50 = 90, x = 20.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
