INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be7f58cc-45bd-472a-8c47-1bf24a9404d3', 'NC26.7.SGMR.3', 1, 'choice', 'Vertical angles with expressions (equation)', 'Two vertical angles measure $(3x)^\circ$ and $75^\circ$. What is $x$?', '["35","225","25","72"]', '25', '75/3', 'Vertical angles are equal, so $3x = 75$ and $x = 75 \div 3 = 25$. The choice 35 treats the angles as supplementary ($3x + 75 = 180$ would give 35), 225 multiplies instead of dividing, and 72 subtracts 3.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 75, x = 25.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31a53aa2-88d6-4380-b1b9-37cb5161e36c', 'NC26.7.SGMR.3', 1, 'choice', 'Choose the equation for an unknown angle', 'Two angles are complementary. One measures $x^\circ$ and the other measures $32^\circ$. Which equation can be used to find $x$?', '["$x + 32 = 180$","$x + 32 = 90$","$x = 32$","$x - 32 = 90$"]', '$x + 32 = 90$', NULL, 'Complementary angles add up to 90, so $x + 32 = 90$. The equation with 180 is for supplementary angles, and $x = 32$ would be for vertical angles.', 'checked', '{"lint":[],"solve":{"answer":"$x + 32 = 90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complementary: x + 32 = 90.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a5691a-7596-491a-9462-59bb0676282f', 'NC26.7.SGMR.3', 1, 'choice', 'Choose the equation for an unknown angle', 'Angles $A$ and $B$ lie side by side along a straight line. Angle $A$ measures $x^\circ$ and angle $B$ measures $110^\circ$. Which equation can be used to find $x$?', '["$x + 110 = 90$","$x = 110$","$x + 110 = 180$","$x + 110 = 360$"]', '$x + 110 = 180$', NULL, 'Angles along a straight line add up to 180, so $x + 110 = 180$. The others use 90 (complementary), equal angles (vertical), or 360 (a full turn).', 'checked', '{"lint":[],"solve":{"answer":"$x + 110 = 180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Along a straight line: x + 110 = 180.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e81ccab2-d183-4e4d-ae3c-b93b359b55b4', 'NC26.7.SGMR.3', 1, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross. One of the four angles measures $50^\circ$. What is the measure, in degrees, of an angle that is next to it?', '[]', '130', '180-50', 'An angle next to it makes a straight line with it, so the two add up to $180^\circ$: $180 - 50 = 130$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"130","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angle = 180 - 50 = 130.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54e641b4-e71a-491e-9458-668c405550e4', 'NC26.7.SGMR.3', 1, 'choice', 'Intersecting lines: several angles, several steps', 'Two lines cross and make four angles. One of the angles measures $90^\circ$. What are the measures of the other three angles?', '["$90^\\circ$, $90^\\circ$ and $90^\\circ$","$45^\\circ$, $45^\\circ$ and $90^\\circ$","$90^\\circ$, $90^\\circ$ and $180^\\circ$","$30^\\circ$, $30^\\circ$ and $30^\\circ$"]', '$90^\circ$, $90^\circ$ and $90^\circ$', NULL, 'The angle across from it is also $90^\circ$. The angles next to it are $180 - 90 = 90$ degrees. So all four angles are right angles (the lines are perpendicular).', 'checked', '{"lint":[],"solve":{"answer":"$90^\\circ$, $90^\\circ$ and $90^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angle 90; adjacent ones 180 - 90 = 90. All 90.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f376150-5e0b-4ee1-bd1b-bed9557a624b', 'NC26.7.SGMR.3', 1, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross. One angle measures $135^\circ$. What is the measure of the smallest of the four angles in degrees?', '[]', '45', '180-135', 'The angle across from it is $135^\circ$. The two angles next to it are $180 - 135 = 45$ degrees each. The smallest angle is 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles are 135, 45, 135, 45. Smallest 45.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff5dd237-37dc-47dd-8724-d0232ce391ff', 'NC26.7.SGMR.3', 1, 'numeric', 'Angles around a point', 'Four angles meet at a point and fill the whole way around it, with no gaps and no overlaps. Three of them measure $90^\circ$, $120^\circ$ and $70^\circ$. What is the measure of the fourth angle in degrees?', '[]', '80', '360-90-120-70', 'Angles that fill the whole way around a point add up to $360^\circ$. The three known angles add up to $90 + 120 + 70 = 280$. The fourth is $360 - 280 = 80$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Around a point 360: 360 - (90 + 120 + 70) = 360 - 280 = 80.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b1d0d1-e6ff-49b7-a9d8-209c4a800b01', 'NC26.7.SGMR.3', 2, 'numeric', 'Equation for complementary angles', 'Two complementary angles measure $3x^\circ$ and $(2x + 10)^\circ$. What is the measure of the larger angle in degrees?', '[]', '48', '3*(90-10)/5', 'Complementary angles add to 90, so $3x + 2x + 10 = 90$. Then $5x = 80$ and $x = 16$. The angles are $3 \times 16 = 48$ and $2 \times 16 + 10 = 42$. The larger angle is 48 degrees.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2x + 10 = 90, 5x = 80, x = 16. Angles 48 and 42. Larger is 48.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('591750a4-9689-42dc-8f3d-9b2bd856b202', 'NC26.7.SGMR.3', 2, 'numeric', 'Equation for vertical angles', 'Two lines cross. A pair of vertical angles measure $(4x + 5)^\circ$ and $(6x - 15)^\circ$. What is the measure of each of these two angles in degrees?', '[]', '45', '4*((5+15)/2)+5', 'Vertical angles are equal, so $4x + 5 = 6x - 15$. Then $20 = 2x$ and $x = 10$. Each angle measures $4 \times 10 + 5 = 45$ degrees. Check: $6 \times 10 - 15 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 5 = 6x - 15, 20 = 2x, x = 10. Each angle 4(10) + 5 = 45 = 6(10) - 15.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b426014d-93c1-4576-abb4-36d8bd1c2791', 'NC26.7.SGMR.3', 2, 'choice', 'Angles that form a straight line', 'Three adjacent angles together form a straight line. Two of them measure $50^\circ$ and $75^\circ$, and the third measures $x^\circ$. What is $x$?', '["125","15","235","55"]', '55', '180-50-75', 'Angles that form a straight line add to $180^\circ$. So $50 + 75 + x = 180$, and $x = 180 - 125 = 55$. (125 is the sum of the two known angles, 235 subtracts that from 360, and 15 subtracts from 90.)', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 + 75 + x = 180, x = 55.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
