INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f18c0f7f-1ced-48b9-ad2d-29e7832d27d7', 'NC26.7.SGMR.3', 2, 'choice', 'Complementary angles: find the missing angle', 'Angle $R$ has a complement that measures $38^\circ$. What is the measure of angle $R$ in degrees?', '["142","52","38","128"]', '52', '90-38', 'Angle $R$ and $38^\circ$ add up to $90^\circ$, so angle $R$ is $90 - 38 = 52$ degrees. The choice 142 is $180 - 38$, 38 repeats the given angle, and 128 is $90 + 38$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R + 38 = 90, so R = 52.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
