INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd0833c1-72db-41d6-ae62-4ca577d3877d', 'NC26.7.SGMR.3', 2, 'choice', 'Complementary angles: find the missing angle', 'Which pair of angle measures is complementary?', '["$47^\\circ$ and $43^\\circ$","$47^\\circ$ and $133^\\circ$","$57^\\circ$ and $43^\\circ$","$47^\\circ$ and $47^\\circ$"]', '$47^\circ$ and $43^\circ$', NULL, 'Complementary angles add up to $90^\circ$. $47 + 43 = 90$. The pair $47^\circ$ and $133^\circ$ adds to 180 (supplementary), $57^\circ$ and $43^\circ$ adds to 100, and $47^\circ$ and $47^\circ$ adds to 94.', 'checked', '{"lint":[],"solve":{"answer":"$47^\\circ$ and $43^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47+43 = 90 (yes); 47+47 = 94; 57+43 = 100; 47+133 = 180 (supplementary). Only 47 and 43.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6000584-00b9-4121-a672-cbce7019bdd2', 'NC26.7.SGMR.3', 2, 'choice', 'Supplementary angles: find the missing angle', 'Two angles are supplementary. One of them measures $87^\circ$. How many degrees larger is the larger angle than the smaller angle?', '["93","3","87","6"]', '6', '(180-87)-87', 'The other angle is $180 - 87 = 93$ degrees. The larger angle is $93$ and the smaller is $87$, so the difference is $93 - 87 = 6$. The choice 93 is just the other angle, 3 is half the difference, and 87 is the given angle.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other angle = 180 - 87 = 93. Difference 93 - 87 = 6.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d855275-2aad-4a31-bc62-a32a249eeb3b', 'NC26.7.SGMR.3', 2, 'choice', 'Supplementary angles: find the missing angle', 'Which of these pairs of angle measures could be a pair of supplementary angles?', '["$64^\\circ$ and $26^\\circ$","$64^\\circ$ and $126^\\circ$","$64^\\circ$ and $116^\\circ$","$74^\\circ$ and $116^\\circ$"]', '$64^\circ$ and $116^\circ$', NULL, 'Supplementary angles add up to $180^\circ$. $64 + 116 = 180$. The pair $64^\circ$ and $26^\circ$ adds to 90, and the other two pairs add to 190.', 'checked', '{"lint":[],"solve":{"answer":"$64^\\circ$ and $116^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"74+116 = 190; 64+126 = 190; 64+26 = 90; 64+116 = 180. Only the last.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4da13b4-70c5-4386-a46f-a0e05cea2e48', 'NC26.7.SGMR.3', 2, 'numeric', 'Vertical angles: find the measure', 'A pair of scissors is opened. The two handles make an angle of $34^\circ$ at the pivot. The two blades make the vertical angle on the other side of the pivot. How many degrees is the angle between the blades?', '[]', '34', '34', 'The handles and the blades are parts of the same two crossing lines, so the angle between the blades is vertical to the angle between the handles. Vertical angles are equal: $34^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blades'' angle is vertical to the handles'' angle, so equal: 34.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('becc2f3d-ec19-499d-9cae-37339f8526eb', 'NC26.7.SGMR.3', 2, 'choice', 'Vertical angles: find the measure', 'Two lines cross, and one of the angles measures $100^\circ$. Which statement is true?', '["The angle across from it measures $80^\\circ$.","The angle across from it measures $100^\\circ$.","The angles next to it measure $100^\\circ$.","All four angles measure $100^\\circ$."]', 'The angle across from it measures $100^\circ$.', NULL, 'The angle across from it is its vertical angle, so it is also $100^\circ$. The angles next to it are supplementary to it: $180 - 100 = 80$ degrees. The four angles cannot all be $100^\circ$ because they add up to $360^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"The angle across from it measures $100^\\circ$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angle is equal: 100. Adjacent angles are 80, so ''next to it 100'' and ''all four 100'' are false; across is not 80.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('538d7442-bb85-4e26-a630-7e01bdb5a331', 'NC26.7.SGMR.3', 2, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Mia draws three rays from one point on a straight line. They make four angles along the line. Three of the angles measure $28^\circ$, $47^\circ$ and $59^\circ$. What is the measure of the fourth angle in degrees?', '[]', '46', '180-28-47-59', 'All four angles along the line add up to $180^\circ$. The three known angles add up to $28 + 47 + 59 = 134$. The fourth angle is $180 - 134 = 46$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four angles along the line sum to 180: 180 - (28 + 47 + 59) = 180 - 134 = 46.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da27ef1b-ec37-4be2-ba5c-d9916a2a9fcf', 'NC26.7.SGMR.3', 2, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Two rays are drawn from a point on a straight line, making three angles along the line. The first angle is $25^\circ$. The second angle is $15^\circ$ more than the first angle. What is the measure of the third angle in degrees?', '[]', '115', '180-25-(25+15)', 'The second angle is $25 + 15 = 40$ degrees. The three angles add up to $180^\circ$, so the third angle is $180 - 25 - 40 = 115$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"115","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 25, second 25 + 15 = 40. Third = 180 - 65 = 115.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('babb47fc-b765-47ad-90e8-d83eb78229b0', 'NC26.7.SGMR.3', 2, 'choice', 'Adjacent angles along a straight line (sum 180)', 'Angles 1, 2 and 3 lie side by side along a straight line. Angle 1 is $52^\circ$ and angle 3 is $71^\circ$. What is the measure of angle 2 in degrees?', '["128","57","109","123"]', '57', '180-52-71', 'The three angles add up to $180^\circ$. So angle 2 is $180 - 52 - 71 = 57$ degrees. The choice 128 only subtracts 52, 109 only subtracts 71, and 123 adds the two known angles.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 52 - 71 = 57.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
