INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb56762d-6896-4c69-a8d3-e8f37f56f430', 'NC26.7.SGMR.3', 2, 'numeric', 'Adjacent angles that make up a larger angle', 'Ray $QR$ lies inside angle $PQS$. Angle $PQR$ measures $38^\circ$ and angle $RQS$ measures $27^\circ$ more than angle $PQR$. What is the measure of angle $PQS$ in degrees?', '[]', '103', '38+(38+27)', 'Angle $RQS$ is $38 + 27 = 65$ degrees. Angle $PQS$ is the sum of its two parts: $38 + 65 = 103$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"103","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"RQS = 38 + 27 = 65. PQS = 38 + 65 = 103.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
