INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153b0fda-c421-4aaf-977f-1e8a87fabe1f', 'NC26.7.SGMR.3', 2, 'choice', 'Adjacent angles that make up a larger angle', 'Rays from the same point split a $150^\circ$ angle into three adjacent angles. The first two measure $42^\circ$ and $57^\circ$. What is the measure of the third angle in degrees?', '["99","108","51","93"]', '51', '150-42-57', 'The three angles add up to $150^\circ$: $150 - 42 - 57 = 51$. The choice 99 is $42 + 57$, 108 is $150 - 42$, and 93 is $150 - 57$.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 - 42 - 57 = 51.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
