INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbb5c1f7-68f8-4c53-9958-1f6f2de7f18a', 'NC26.7.SGMR.3', 2, 'choice', 'Name and compare angle relationships', 'Lines $AB$ and $CD$ cross at point $O$, which lies between $A$ and $B$ and between $C$ and $D$. Which angle is vertical to angle $AOC$?', '["angle $COB$","angle $AOD$","angle $AOB$","angle $BOD$"]', 'angle $BOD$', NULL, 'Vertical angles are across from each other. Ray $OB$ is opposite ray $OA$, and ray $OD$ is opposite ray $OC$, so the angle across from angle $AOC$ is angle $BOD$. Angles $COB$ and $AOD$ are next to angle $AOC$, and angle $AOB$ is a straight angle.', 'checked', '{"lint":[],"solve":{"answer":"angle $BOD$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC uses rays OA and OC; the opposite rays are OB and OD, so the vertical angle is BOD. AOB is a straight angle; COB and AOD are adjacent to AOC.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e939ddf2-3901-434f-a952-6c43a79d6f38', 'NC26.7.SGMR.3', 2, 'choice', 'Name and compare angle relationships', 'Angle $P$ and angle $Q$ are supplementary. Angle $Q$ and angle $R$ are supplementary. Which statement must be true?', '["Angle $P$ and angle $R$ have equal measures.","Angle $P$ and angle $R$ are supplementary.","Angle $P$ and angle $R$ are complementary.","Angle $P$ is larger than angle $R$."]', 'Angle $P$ and angle $R$ have equal measures.', NULL, 'Angle $P = 180 - Q$ and angle $R = 180 - Q$, so angles $P$ and $R$ are equal. They add up to $2(180 - Q)$, which need not be 180 or 90, and neither one has to be larger.', 'checked', '{"lint":[],"solve":{"answer":"Angle $P$ and angle $R$ have equal measures.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 180 - Q and R = 180 - Q, so P = R. Complementary/supplementary would need specific values; P larger is false.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
