INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('205a6418-5b66-494c-8052-c36c680ddbe6', 'NC26.7.SGMR.3', 3, 'choice', 'Supplementary angles: find the missing angle', 'Angle $A$ and angle $B$ are supplementary, and angle $A$ is an acute angle. Which statement must be true about angle $B$?', '["Angle $B$ is an acute angle.","Angle $B$ is a right angle.","Angle $B$ is smaller than angle $A$.","Angle $B$ is an obtuse angle."]', 'Angle $B$ is an obtuse angle.', NULL, 'Angle $A$ is less than $90^\circ$, so angle $B = 180 - A$ is greater than $90^\circ$ and less than $180^\circ$. That makes it obtuse. It is larger than $A$, and it is a right angle only if $A$ is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Angle $B$ is an obtuse angle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 < A < 90, B = 180 - A, so 90 < B < 180: B is obtuse. B is larger than A, not smaller; not acute; not right.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1901c4ee-ce31-4b2b-9b15-119524c42204', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles has a sum of $146^\circ$. What is the measure, in degrees, of each of the other two angles?', '["73","107","34","214"]', '107', '180-146/2', 'Each angle of the first pair is $146 \div 2 = 73$ degrees. An angle next to it is $180 - 73 = 107$ degrees, and the other pair are vertical angles with the same measure. The choice 73 is one of the first pair, 34 is $180 - 146$, and 214 is $360 - 146$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical pair equal, each 146/2 = 73. Each of the other two = 180 - 73 = 107.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b657eb9-3e18-4170-afb1-2b84de80201a', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles measures $d^\circ$ in all (the two angles together). Which expression gives the measure of each of the other two angles?', '["$180 - d$","$\\frac{d}{2}$","$180 - \\frac{d}{2}$","$360 - d$"]', '$180 - \frac{d}{2}$', NULL, 'Each angle of the first pair measures $\frac{d}{2}$. An angle next to it is $180 - \frac{d}{2}$, and the other pair are vertical angles with that measure. The expression $360 - d$ is the total of the other two angles, not each one.', 'checked', '{"lint":[],"solve":{"answer":"$180 - \\frac{d}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of the pair = d/2. Each other angle = 180 - d/2 (equivalently (360 - d)/2).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97a3a124-3c6b-4b9d-8290-70697a916677', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Four angles lie side by side along a straight line. Each angle is $10^\circ$ larger than the angle before it. What is the measure of the largest angle in degrees?', '[]', '60', '(180-60)/4+30', 'Call the smallest angle $a$. The angles are $a$, $a + 10$, $a + 20$ and $a + 30$, and they add up to $180$. So $4a + 60 = 180$, $4a = 120$ and $a = 30$. The largest angle is $30 + 30 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + (a+10) + (a+20) + (a+30) = 180, 4a + 60 = 180, a = 30. Largest = 60.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61888406-14be-44d2-b943-7904ef4c1cfb', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Rays split a straight angle into three angles. The second angle is twice the first, and the third angle is three times the first. What is the measure of the third angle in degrees?', '[]', '90', '180/6*3', 'If the first angle is $x$, the angles are $x$, $2x$ and $3x$, which add up to $6x = 180$. So $x = 30$, and the third angle is $3 \times 30 = 90$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, x = 30. Third = 3x = 90.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65b9bd85-3d19-4b89-89c5-b7330c38e138', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOD$ measures $126^\circ$. Rays $OB$ and $OC$ lie inside it, in that order from $OA$. Angle $AOB$ measures $30^\circ$, and angle $BOC$ is $12^\circ$ larger than angle $AOB$. What is the measure of angle $COD$ in degrees?', '[]', '54', '126-30-(30+12)', 'Angle $BOC$ is $30 + 12 = 42$ degrees. The three angles add up to angle $AOD$, so angle $COD$ is $126 - 30 - 42 = 54$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BOC = 30 + 12 = 42. COD = 126 - 30 - 42 = 54.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5947aaf9-41a4-4177-85f2-6d76c21b8d60', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOC$ measures $84^\circ$ and ray $OB$ lies inside it. Angle $AOB$ is $12^\circ$ more than twice angle $BOC$. What is the measure of angle $AOB$ in degrees?', '[]', '60', '(84-12)/3*2+12', 'Let angle $BOC$ be $y$. Then angle $AOB$ is $2y + 12$, and $y + 2y + 12 = 84$. So $3y = 72$ and $y = 24$. Angle $AOB$ is $2 \times 24 + 12 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Let BOC = y, AOB = 2y + 12. 3y + 12 = 84, y = 24. AOB = 60.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c5b61d4-bd01-4638-8402-6878af07a5e3', 'NC26.7.SGMR.3', 3, 'choice', 'Name and compare angle relationships', 'Two lines cross and make four angles. Which statement is always true?', '["All four angles are equal.","Two angles that are next to each other are equal.","Two angles that are next to each other add up to $180^\\circ$.","Two angles that are across from each other add up to $180^\\circ$."]', 'Two angles that are next to each other add up to $180^\circ$.', NULL, 'Angles next to each other along one of the lines make a straight angle, so they add up to $180^\circ$. The four angles are all equal only when the lines are perpendicular, and angles across from each other are equal (so they add up to 180 only if each is 90).', 'checked', '{"lint":[],"solve":{"answer":"Two angles that are next to each other add up to $180^\\circ$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles at a crossing form a linear pair: always 180. Opposite angles sum to 180 only if each is 90; all equal only when perpendicular; adjacent equal only when perpendicular.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca1760e1-c998-43c6-ad5d-b6f2304f1c2e', 'NC26.7.SGMR.3', 3, 'choice', 'Name and compare angle relationships', 'Which of these is impossible?', '["two complementary angles that are both obtuse","two supplementary angles that are both right angles","two vertical angles that are both obtuse","two complementary angles that are each $45^\\circ$"]', 'two complementary angles that are both obtuse', NULL, 'Obtuse angles are greater than $90^\circ$, so two of them add up to more than 180 and cannot be complementary (which needs a sum of 90). Two right angles are supplementary, vertical angles of $120^\circ$ are both obtuse, and $45 + 45 = 90$.', 'checked', '{"lint":[],"solve":{"answer":"two complementary angles that are both obtuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two obtuse angles sum to more than 180, so cannot sum to 90: impossible. 90+90 = 180 possible; 45+45 = 90 possible; vertical angles both obtuse possible (e.g., 120 and 120).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e717b51-1d1d-41eb-8b64-74809105850a', 'NC26.7.SGMR.3', 3, 'numeric', 'Complementary angles with expressions (equation)', 'An angle measures $(6x - 4)^\circ$ and its complement measures $(2x + 14)^\circ$. How many degrees larger is the bigger of the two angles than the smaller one?', '[]', '22', '(6*10-4)-(2*10+14)', 'The angles add up to 90: $(6x - 4) + (2x + 14) = 90$, so $8x + 10 = 90$, $8x = 80$ and $x = 10$. The angles are $6 \times 10 - 4 = 56$ and $2 \times 10 + 14 = 34$ degrees. The difference is $56 - 34 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x + 10 = 90, x = 10. Angles 56 and 34. Difference 22.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('853b925a-c455-40f9-83e5-bbcedf2e4aba', 'NC26.7.SGMR.3', 3, 'numeric', 'Complementary angles with expressions (equation)', 'Angle $A$ measures $(3x + 2)^\circ$ and angle $B$ measures $(5x - 8)^\circ$. The two angles are complementary. What is the measure of the supplement of angle $A$ in degrees?', '[]', '142', '180-(3*12+2)', 'The angles add up to 90: $(3x + 2) + (5x - 8) = 90$, so $8x - 6 = 90$, $8x = 96$ and $x = 12$. Angle $A$ is $3 \times 12 + 2 = 38$ degrees. Its supplement is $180 - 38 = 142$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"142","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x - 6 = 90, x = 12. A = 38, B = 52. Supplement of A = 180 - 38 = 142.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f304b2e-4343-4e6d-9706-4f409509ed10', 'NC26.7.SGMR.3', 3, 'choice', 'Supplementary angles and straight lines with expressions (equation)', 'Three angles lie side by side along a straight line. They measure $x^\circ$, $(2x + 10)^\circ$ and $(3x - 10)^\circ$. What is the measure of the largest angle in degrees?', '["70","30","90","80"]', '80', '3*30-10', 'The angles add up to 180: $x + (2x + 10) + (3x - 10) = 180$, so $6x = 180$ and $x = 30$. The angles are 30, 70 and 80 degrees. The largest is 80. The choice 70 is the middle angle, 30 is $x$, and 90 is $3x$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 10 + 3x - 10 = 180, 6x = 180, x = 30. Angles 30, 70, 80. Largest 80.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdaf07ec-9938-4c99-8fd1-fc2b78e829b7', 'NC26.7.SGMR.3', 3, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'A straight line is split into two angles that measure $(5x + 7)^\circ$ and $(7x - 19)^\circ$. What is the positive difference between the two angles in degrees?', '[]', '6', '(7*16-19)-(5*16+7)', 'The angles add up to 180: $(5x + 7) + (7x - 19) = 180$, so $12x - 12 = 180$, $12x = 192$ and $x = 16$. The angles are $5 \times 16 + 7 = 87$ and $7 \times 16 - 19 = 93$ degrees. The difference is $93 - 87 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''A straight line is split into two angles'' is loose; ''A ray splits a straight angle into two angles'' would be precise. Meaning is still clear.","work":"Sum 180: 12x - 12 = 180, x = 16. Angles 87 and 93. Difference 6.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24552019-d6be-4a80-97ae-c9b831770eba', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles with expressions (equation)', 'Two lines cross. One angle measures $(9x - 20)^\circ$ and the angle across from it measures $(6x + 25)^\circ$. What is the measure of an angle next to either of them, in degrees?', '["115","15","295","65"]', '65', '180-(9*15-20)', 'Vertical angles are equal: $9x - 20 = 6x + 25$, so $3x = 45$ and $x = 15$. Each of these angles is $9 \times 15 - 20 = 115$ degrees. An angle next to one of them is $180 - 115 = 65$ degrees. The choice 115 is the vertical pair itself, 15 is $x$, and 295 is $180 + 115$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x - 20 = 6x + 25, 3x = 45, x = 15. Angle = 115. Adjacent angle = 180 - 115 = 65.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09f2dbd7-2059-446a-8432-e1e46e6598f7', 'NC26.7.SGMR.3', 3, 'numeric', 'Vertical angles with expressions (equation)', 'Two lines cross. One angle measures $(3x + 10)^\circ$ and its vertical angle measures $(5x - 20)^\circ$. What is the sum of the measures of the other two angles in degrees?', '[]', '250', '360-2*(3*15+10)', 'Vertical angles are equal: $3x + 10 = 5x - 20$, so $30 = 2x$ and $x = 15$. Each of these angles is $3 \times 15 + 10 = 55$ degrees. The four angles add up to 360, so the other two add up to $360 - 2 \times 55 = 250$ degrees. (Each is $180 - 55 = 125$.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 10 = 5x - 20, x = 15. Angle = 55. Others each 125, sum 250 (= 360 - 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6497bc2-0915-4229-8fe0-0f59baad0375', 'NC26.7.SGMR.3', 3, 'choice', 'Choose the equation for an unknown angle', 'Two lines cross. One angle measures $(2x + 10)^\circ$ and an angle next to it measures $(3x - 5)^\circ$. Which equation can be used to find $x$?', '["$(2x + 10) + (3x - 5) = 180$","$2x + 10 = 3x - 5$","$(2x + 10) + (3x - 5) = 90$","$(2x + 10) + (3x - 5) = 360$"]', '$(2x + 10) + (3x - 5) = 180$', NULL, 'Angles next to each other where two lines cross are supplementary, so they add up to 180. The equation $2x + 10 = 3x - 5$ would be for vertical angles, 90 is for complements, and 360 is for all four angles.', 'checked', '{"lint":[],"solve":{"answer":"$(2x + 10) + (3x - 5) = 180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles at a crossing are a linear pair: (2x + 10) + (3x - 5) = 180 (x = 35, angles 80 and 100).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d78c8de3-0350-4148-ae36-f096d859d31f', 'NC26.7.SGMR.3', 3, 'choice', 'Choose the equation for an unknown angle', 'The supplement of an angle is $15^\circ$ less than four times the angle''s complement. If the angle measures $x^\circ$, which equation can be used to find $x$?', '["$180 - x = 4(90 - x) + 15$","$180 - x = 4(90 - x) - 15$","$90 - x = 4(180 - x) - 15$","$180 - x = 4x - 15$"]', '$180 - x = 4(90 - x) - 15$', NULL, 'The supplement is $180 - x$ and the complement is $90 - x$. "$15$ less than four times the complement" is $4(90 - x) - 15$. So $180 - x = 4(90 - x) - 15$. The other choices add 15, swap supplement and complement, or use the angle itself instead of its complement.', 'checked', '{"lint":[],"solve":{"answer":"$180 - x = 4(90 - x) - 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Supplement 180 - x; complement 90 - x; ''15 less than four times the complement'' = 4(90 - x) - 15. Check: x = 55 gives 125 = 4(35) - 15.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33f3207e-45a4-47a1-8600-ff6dd21c39ec', 'NC26.7.SGMR.3', 3, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross. One angle is $30^\circ$ more than an angle next to it. What is the measure of the larger of these two angles in degrees?', '[]', '105', '(180+30)/2', 'Let the smaller angle be $a$. The larger is $a + 30$, and they are next to each other so $a + (a + 30) = 180$. Then $2a = 150$ and $a = 75$. The larger angle is $75 + 30 = 105$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (x + 30) = 180, x = 75. Larger = 105.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47920abb-a2b1-4f18-ae9e-e5789d528b7b', 'NC26.7.SGMR.3', 3, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross. One angle is $30^\circ$ less than twice the measure of an angle next to it. What is the measure of the smaller of the two angles in degrees?', '[]', '70', '(180+30)/3', 'Let one angle be $a$. The angle next to it is $2a - 30$. They add up to 180: $a + 2a - 30 = 180$, so $3a = 210$ and $a = 70$. The other angle is $2 \times 70 - 30 = 110$. The smaller is 70 degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Let neighbour = y, angle = 2y - 30. y + 2y - 30 = 180, y = 70, angle = 110. Smaller = 70.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7abf7ebb-fdc3-47b8-81e9-9717b88a68b7', 'NC26.7.SGMR.3', 3, 'numeric', 'Intersecting lines: several angles, several steps', 'Lines $AB$ and $CD$ cross at point $O$, which lies between $A$ and $B$ and between $C$ and $D$. Angle $AOC$ measures $(4x - 6)^\circ$ and angle $COB$ measures $(2x + 30)^\circ$. What is the sum of the measures of angle $AOC$ and angle $BOD$ in degrees?', '[]', '196', '2*(4*26-6)', 'Angles $AOC$ and $COB$ are next to each other, so $(4x - 6) + (2x + 30) = 180$. Then $6x + 24 = 180$, $6x = 156$ and $x = 26$. Angle $AOC$ is $4 \times 26 - 6 = 98$ degrees. Angle $BOD$ is vertical to it, so it is also 98. The sum is $98 + 98 = 196$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"196","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC and COB are a linear pair: 6x + 24 = 180, x = 26. AOC = 98, COB = 82. BOD is vertical to AOC = 98. Sum = 196.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49ac379e-f206-4705-a870-f86c22b9a122', 'NC26.7.SGMR.3', 3, 'choice', 'Intersecting lines: several angles, several steps', 'Two lines cross. Sam says, "If one of the four angles is acute, then exactly two of the angles are acute." Which sentence tells whether Sam is correct?', '["No. Only the one angle is acute, and all the other angles are obtuse.","Yes. The angle across from it is also acute, and the other two are obtuse.","No. All four angles are acute when one of the angles is acute.","No. Three of the angles are acute when one of the angles is acute."]', 'Yes. The angle across from it is also acute, and the other two are obtuse.', NULL, 'The angle across from an acute angle is equal to it, so it is acute too. An angle next to an acute angle is $180$ minus an acute angle, which is more than 90, so the other two angles are obtuse. Sam is correct.', 'checked', '{"lint":[],"solve":{"answer":"Yes. The angle across from it is also acute, and the other two are obtuse.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If one angle is acute, its vertical angle is equal (acute) and the two neighbours are 180 minus it (obtuse). Exactly two acute: Sam is right.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3e9de5c-113a-43a8-863b-a6f6c1ab4ff5', 'NC26.7.SGMR.3', 3, 'numeric', 'Intersecting lines: several angles, several steps', 'Lines $AB$ and $CD$ cross at point $O$, which lies between $A$ and $B$ and between $C$ and $D$. Ray $OE$ lies inside angle $AOC$. Angle $AOE$ measures $25^\circ$ and angle $EOC$ measures $40^\circ$. What is the measure of angle $BOC$ in degrees?', '[]', '115', '180-(25+40)', 'Angle $AOC$ is made of angles $AOE$ and $EOC$, so it is $25 + 40 = 65$ degrees. Angle $BOC$ is next to angle $AOC$ along line $AB$, so it is $180 - 65 = 115$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"115","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC = 25 + 40 = 65. BOC is adjacent to AOC on line AB: 180 - 65 = 115.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8722293-3708-4193-8358-93343052290d', 'NC26.7.SGMR.3', 3, 'choice', 'An angle compared with its complement or supplement', 'The supplement of an angle is three times the angle''s complement. What is the measure of the angle in degrees?', '["135","30","45","60"]', '45', '90/2', 'Let the angle be $x$. Then $180 - x = 3(90 - x)$, so $180 - x = 270 - 3x$, $2x = 90$ and $x = 45$. Check: the supplement is 135 and the complement is 45, and $3 \times 45 = 135$. The choice 135 is the supplement itself. For 60, the supplement (120) is four times the complement (30), not three times.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - x = 3(90 - x), 180 - x = 270 - 3x, 2x = 90, x = 45 (supplement 135 = 3 x 45).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d58c8a48-36dd-483b-a0e5-15eea540d453', 'NC26.7.SGMR.3', 3, 'numeric', 'An angle compared with its complement or supplement', 'The complement of an angle is $10^\circ$ less than one third of the angle''s supplement. What is the measure of the angle in degrees?', '[]', '60', '120/2', 'Let the angle be $x$. Its complement is $90 - x$ and its supplement is $180 - x$. So $90 - x = \frac{180 - x}{3} - 10$. Multiply by 3: $270 - 3x = 180 - x - 30$, so $120 = 2x$ and $x = 60$. Check: the complement is 30 and the supplement is 120, and $\frac{120}{3} - 10 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - x = (180 - x)/3 - 10. Times 3: 270 - 3x = 180 - x - 30 = 150 - x, so 2x = 120, x = 60. Check: complement 30, supplement 120, 120/3 - 10 = 30.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88137a8c-95c5-44f9-899c-405b1d221761', 'NC26.7.SGMR.3', 3, 'choice', 'An angle compared with its complement or supplement', 'For any angle that is smaller than $90^\circ$, how does the angle''s supplement compare with its complement?', '["The supplement is always $180^\\circ$ greater than the complement.","The supplement is always twice the complement.","The supplement and the complement are always equal.","The supplement is always $90^\\circ$ greater than the complement."]', 'The supplement is always $90^\circ$ greater than the complement.', NULL, 'For an angle $x$, the supplement is $180 - x$ and the complement is $90 - x$. Their difference is $(180 - x) - (90 - x) = 90$, whatever $x$ is.', 'checked', '{"lint":[],"solve":{"answer":"The supplement is always $90^\\circ$ greater than the complement.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(180 - x) - (90 - x) = 90 for every x, so the supplement is always 90 greater.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('873dd5de-360f-4cf7-a00b-db4d72d76f1f', 'NC26.7.SGMR.3', 3, 'numeric', 'An angle compared with its complement or supplement', 'The complement and the supplement of an angle add up to $210^\circ$. What is the measure of the angle in degrees?', '[]', '30', '(270-210)/2', 'Let the angle be $x$. Then $(90 - x) + (180 - x) = 210$, so $270 - 2x = 210$, $2x = 60$ and $x = 30$. Check: the complement is 60, the supplement is 150, and $60 + 150 = 210$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(90 - x) + (180 - x) = 210, 270 - 2x = 210, x = 30.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b6c6469-3cc1-4247-8ba3-2f48c30d30ad', 'NC26.7.SGMR.3', 3, 'numeric', 'Angles around a point', 'Three straight lines cross at the same point, forming six angles. Each angle has an equal angle directly across from it. Going once around the point, the first three angles measure $35^\circ$, $62^\circ$ and $x^\circ$. What is $x$?', '[]', '83', '180-35-62', 'The six angles add up to 360, and the second three are equal to the first three (they are across from them). So the first three add up to $360 \div 2 = 180$. Then $35 + 62 + x = 180$ and $x = 83$.', 'checked', '{"lint":[],"solve":{"answer":"83","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The six angles in order are 35, 62, x, 35, 62, x (each opposite its equal). Also 35 + 62 + x = 180 since three consecutive angles span a straight line. x = 180 - 97 = 83.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08349673-5ad4-4f5f-85de-6f3662a7340c', 'NC26.7.RD.1', 1, 'numeric', 'Theoretical probability of one event', 'A bag has 3 red marbles, 5 blue marbles and 2 green marbles. One marble is drawn at random. What is the probability that it is green? Write your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 5 + 2 = 10$ marbles and 2 of them are green. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 marbles, 2 green: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d1a249a-5f2f-46fe-b0dd-8366def5c8c8', 'NC26.7.RD.1', 1, 'numeric', 'Size of a sample space', 'A fair coin is flipped and a fair six-sided die is rolled. How many outcomes are in the sample space?', '[]', '12', '2*6', 'The coin can land 2 ways and the die can land 6 ways. Every coin result pairs with every die result: $2 \times 6 = 12$ outcomes, such as (heads, 1) and (tails, 6).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 6 = 12 outcomes.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53c9a2c4-f81c-4352-861d-b71295135871', 'NC26.7.RD.1', 1, 'choice', 'Probability of two heads', 'A fair coin is flipped two times. What is the probability of getting two heads?', '["1/2","1/3","1/4","3/4"]', '1/4', '1/4', 'List the equally likely outcomes: HH, HT, TH, TT. Only HH is two heads, so the probability is $\frac{1}{4}$. (1/3 wrongly counts HT and TH as one outcome; 3/4 is the chance of at least one head.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HH, HT, TH, TT: 1 of 4 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9471d544-0870-453f-9120-8e6aca61cabf', 'NC26.7.RD.1', 1, 'choice', 'Theoretical probability of a single event', 'A fair six-sided die is rolled once. What is the probability of rolling a number greater than 4?', '["1/3","1/2","1/6","2/3"]', '1/3', '2/6', 'The numbers greater than 4 are 5 and 6, so 2 of the 6 equally likely outcomes work. The probability is $\frac{2}{6} = \frac{1}{3}$. (1/2 wrongly counts the 4 as well, 1/6 counts only one number, and 2/3 is the chance of rolling 4 or less.)', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbers greater than 4 on a die: 5 and 6, so 2 of 6 outcomes. 2/6 = 1/3.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea22d1d6-12c6-44f3-b6c6-efbcc390f6e6', 'NC26.7.RD.1', 1, 'choice', 'Theoretical probability of a single event', 'A fair spinner has 8 equal sections numbered 1 to 8. What is the probability that it lands on an even number?', '["1/4","1/2","3/8","1/8"]', '1/2', '4/8', 'The even numbers are 2, 4, 6 and 8, which is 4 of the 8 equally likely sections. The probability is $\frac{4}{8} = \frac{1}{2}$. (1/8 counts one section, 3/8 leaves out the 8, and 1/4 counts only 2 sections.)', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even numbers 1-8: 2, 4, 6, 8, so 4 of 8 equal sections. 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c34d689-acda-4d78-9782-2b99508494c0', 'NC26.7.RD.1', 1, 'numeric', 'Probability when outcomes are not equally likely', 'A spinner is split into three sections that are red, blue and green. The red section covers $\frac{1}{2}$ of the spinner and the blue section covers $\frac{1}{4}$. What is the probability that the spinner lands on green? Write your answer as a fraction.', '[]', '1/4', '1-1/2-1/4', 'The probabilities of all the outcomes add to 1. Red and blue together are $\frac{1}{2} + \frac{1}{4} = \frac{3}{4}$, so green is $1 - \frac{3}{4} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Probabilities sum to 1. Green = 1 - 1/2 - 1/4 = 1/4.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb9d6a7d-961f-410a-b420-03a16c291288', 'NC26.7.RD.1', 1, 'choice', 'Probability when outcomes are not equally likely', 'A bag has 2 red marbles and 8 blue marbles. Tia says, "There are 2 colors, so the probability of drawing a red marble is $\frac{1}{2}$." What is the actual probability of drawing a red marble?', '["1/2","1/4","1/5","1/8"]', '1/5', '2/10', 'The marbles are not equally split between the colors. There are $2 + 8 = 10$ marbles and 2 are red, so the probability is $\frac{2}{10} = \frac{1}{5}$. (1/2 is Tia''s mistake of counting colors instead of marbles; 1/4 compares the 2 red marbles to the 8 blue ones, and 1/8 uses only the blue count.)', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 marbles, 2 red: 2/10 = 1/5. Colors are not equally likely, so Tia is wrong.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1e83bdf-a52f-44d2-b27f-669d9fba45c5', 'NC26.7.RD.1', 1, 'numeric', 'Probability when outcomes are not equally likely', 'A weighted coin lands on heads with probability $\frac{3}{5}$. What is the probability that it lands on tails? Write your answer as a fraction.', '[]', '2/5', '1-3/5', 'Heads and tails are the only outcomes, so their probabilities add to 1. The probability of tails is $1 - \frac{3}{5} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tails = 1 - 3/5 = 2/5.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4333ee9-57f9-4370-93a1-89f4d127d520', 'NC26.7.RD.1', 1, 'numeric', 'Counting the outcomes of a compound event', 'A lunch special comes with one sandwich (turkey, cheese or egg) and one fruit (apple or banana). How many different lunches are possible?', '[]', '6', '3*2', 'Each of the 3 sandwiches can be paired with either of the 2 fruits. The number of lunches is $3 \times 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 sandwiches x 2 fruits = 6 lunches.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41463144-2193-4879-94f2-3e79371f0d46', 'NC26.7.RD.1', 1, 'choice', 'Counting the outcomes of a compound event', 'A fair coin is flipped and a spinner with 4 equal sections numbered 1 to 4 is spun. How many outcomes are in the sample space?', '["6","4","16","8"]', '8', '2*4', 'The coin has 2 results and the spinner has 4 results, and every coin result can go with every spinner result. The sample space has $2 \times 4 = 8$ outcomes, such as (heads, 3). (6 adds instead of multiplying; 16 multiplies 4 by 4.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 coin outcomes x 4 spinner outcomes = 8.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('755e8c41-a11a-4852-81f4-9fc084ac1880', 'NC26.7.RD.1', 1, 'numeric', 'Counting the outcomes of a compound event', 'A fair die is rolled two times, and the two results are recorded in order. How many outcomes are in the sample space?', '[]', '36', '6*6', 'The first roll can be any of 6 numbers and so can the second roll. The number of outcomes is $6 \times 6 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: says ''a fair die'' without ''six-sided'', unlike the other questions; the usual reading gives 36, but stating six-sided would remove any doubt.","work":"Assuming a standard six-sided die: 6 x 6 = 36 ordered outcomes.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('440f94f7-d768-4141-98b2-6c7a47dfc4be', 'NC26.7.RD.1', 1, 'choice', 'Listing a sample space', 'Nia spins a spinner with 3 equal sections labeled A, B and C, and then she flips a fair coin. What is the probability that the spinner lands on B and the coin lands on tails?', '["1/3","1/2","1/6","1/5"]', '1/6', '1/3*1/2', 'List the outcomes: A-heads, A-tails, B-heads, B-tails, C-heads, C-tails. There are 6 equally likely outcomes and only B-tails works, so the probability is $\frac{1}{6}$. (1/3 uses only the spinner, 1/2 uses only the coin, and 1/5 adds the 3 and the 2.)', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(B) = 1/3, P(tails) = 1/2, independent: 1/3 x 1/2 = 1/6.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf9847e-9c9a-4f25-b63f-6bf3027d6453', 'NC26.7.RD.1', 1, 'choice', 'Listing a sample space', 'A penny and a dime are tossed at the same time. Which list shows every outcome in the sample space, where H is heads and T is tails? (The first letter is the penny and the second letter is the dime.)', '["HH, HT, TT","HH, TT","HT, TH","HH, HT, TH, TT"]', 'HH, HT, TH, TT', NULL, 'The penny can be H or T, and for each of those the dime can be H or T. That gives HH, HT, TH and TT. HT and TH are different outcomes because it matters which coin shows heads.', 'checked', '{"lint":[],"solve":{"answer":"HH, HT, TH, TT","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Penny H or T, dime H or T: HH, HT, TH, TT (4 outcomes). Other lists omit outcomes.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4993c335-56a8-4f74-b0cd-61f6bc0f3d61', 'NC26.7.RD.1', 1, 'numeric', 'Listing a sample space', 'Ben picks one shirt (red or blue) and one hat (green, yellow or black) at random. What is the probability that his outfit includes the blue shirt? Write your answer as a fraction.', '[]', '1/2', '3/6', 'List the outfits: red-green, red-yellow, red-black, blue-green, blue-yellow, blue-black. That is 6 outcomes and 3 of them have the blue shirt. The probability is $\frac{3}{6} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample space 2 x 3 = 6 outfits; blue shirt in 3 of them: 3/6 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2326d4e1-5782-4d6a-b2e8-8e256bea6c4f', 'NC26.7.RD.1', 1, 'choice', 'Using a table of outcomes', 'Two fair six-sided dice are rolled and the numbers are added. All 36 outcomes are written in a table, with one die down the side and the other across the top. What is the probability that the sum is 2?', '["1/12","1/36","1/11","1/6"]', '1/36', '1/36', 'A sum of 2 happens in only one cell of the table, when both dice show 1. The probability is $\frac{1}{36}$. (1/11 wrongly treats the 11 possible sums as equally likely.)', 'checked', '{"lint":[],"solve":{"answer":"1/36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 2 only from (1,1): 1 of 36 outcomes = 1/36.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9223658f-56b0-4145-b2bf-101753cbacfc', 'NC26.7.RD.1', 1, 'numeric', 'Using a table of outcomes', 'Two fair 4-sided dice, each numbered 1 to 4, are rolled and the numbers are added. The 16 outcomes are written in a table with one die down the side and the other across the top. What is the probability that the sum is 5? Write your answer as a fraction.', '[]', '1/4', '4/16', 'A sum of 5 comes from 1 and 4, 2 and 3, 3 and 2, or 4 and 1, which is 4 cells of the 16. The probability is $\frac{4}{16} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 5: (1,4), (2,3), (3,2), (4,1) = 4 of 16 = 1/4.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab529119-4e31-4367-a60f-e6334443a68f', 'NC26.7.RD.1', 1, 'numeric', 'Using a tree diagram', 'Zoe draws a tree diagram for choosing a snack and a drink. The first stage has 4 branches, one for each snack. From the end of each of those branches, 3 more branches show the drinks. How many complete paths does the tree have?', '[]', '12', '4*3', 'Each of the 4 first branches continues with 3 second branches. The number of complete paths is $4 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 first-stage branches, each with 3 second-stage branches: 4 x 3 = 12 paths.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
