INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17c74c95-420c-4856-a07e-46ad7354aeab', 'NC26.7.RD.1', 1, 'numeric', 'Using a tree diagram', 'In a tree diagram for a game, the first branch "win" has probability $\frac{3}{4}$. From the end of that branch, the second branch "win again" has probability $\frac{1}{2}$. What is the probability of the path win, then win again? Write your answer as a fraction.', '[]', '3/8', '3/4*1/2', 'To find the probability of a path, multiply the probabilities along its branches: $\frac{3}{4} \times \frac{1}{2} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply along the path: 3/4 x 1/2 = 3/8.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('faf56015-0077-4d88-8c59-125adfaadd33', 'NC26.7.RD.1', 1, 'choice', 'Using a tree diagram', 'A tree diagram shows the probabilities of the outcomes of one stage on its branches. When the probabilities on all the branches that start from the same point are added, what should the sum be?', '["1","0","2","1/2"]', '1', '1', 'The branches from one point show every possible outcome of that stage, so their probabilities must add to 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Branches from one point cover all outcomes of that stage, so their probabilities sum to 1.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df1e8569-53e4-4e19-85f4-d4d98ea35a19', 'NC26.7.RD.1', 1, 'choice', 'Compound events with replacement', 'A fair coin is flipped and a fair six-sided die is rolled. What is the probability of getting heads and a 6?', '["1/8","1/6","1/12","2/3"]', '1/12', '1/2*1/6', 'The coin and the die do not affect each other, so multiply: $\frac{1}{2} \times \frac{1}{6} = \frac{1}{12}$. (1/8 adds the 2 and 6 outcomes, 1/6 ignores the coin, and 2/3 adds the two probabilities.)', 'checked', '{"lint":[],"solve":{"answer":"1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 1/6 = 1/12.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b721be3-65b5-488b-8689-2eeb6a75a15e', 'NC26.7.RD.1', 1, 'choice', 'Compound events with replacement', 'A spinner has 5 equal sections and 2 of them are red. The spinner is spun two times. What is the probability that it lands on red both times?', '["2/5","4/25","4/5","2/25"]', '4/25', '2/5*2/5', 'Each spin is red with probability $\frac{2}{5}$, and the spins do not affect each other. Multiply: $\frac{2}{5} \times \frac{2}{5} = \frac{4}{25}$. (2/5 is the chance for one spin, 4/5 adds, and 2/25 forgets to multiply the tops.)', 'checked', '{"lint":[],"solve":{"answer":"4/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(red) = 2/5 each spin, independent: 2/5 x 2/5 = 4/25.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48337be9-04aa-48bb-bf8e-5efb50761333', 'NC26.7.RD.1', 1, 'numeric', 'Compound events without replacement', 'A bag has 1 red marble and 1 blue marble. One marble is drawn and kept out of the bag, and then the other marble is drawn. What is the probability that the first marble is red and the second marble is blue? Write your answer as a fraction.', '[]', '1/2', '1/2*1/1', 'The two orders are red then blue, and blue then red, and they are equally likely. Only red then blue works, so the probability is $\frac{1}{2}$. (Or: the first is red with probability $\frac{1}{2}$, and then the second must be blue, which has probability 1.)', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(first red) = 1/2; then only blue remains, P(second blue) = 1. 1/2 x 1 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1517cd4e-d0f7-418c-a628-7a156046f75c', 'NC26.7.RD.1', 1, 'choice', 'Compound events without replacement', 'Three tickets labeled A, B and C are in a hat. Two tickets are drawn one after the other, and the first ticket is NOT put back. How many different ordered outcomes are there?', '["9","3","5","6"]', '6', '3*2', 'There are 3 choices for the first ticket and then 2 left for the second, so $3 \times 2 = 6$ outcomes: AB, AC, BA, BC, CA, CB. (9 would be right only if the first ticket were put back.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 choices for first, 2 for second: 3 x 2 = 6 (AB, AC, BA, BC, CA, CB).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0641689-b241-470a-ac74-aeff593285b7', 'NC26.7.RD.1', 1, 'numeric', 'Compound events without replacement', 'A bag has 2 red marbles and 2 blue marbles. Kai draws one marble and it is red. He does not put it back. He then draws a second marble. What is the probability that the second marble is red? Write your answer as a fraction.', '[]', '1/3', '1/3', 'After a red marble is removed, 3 marbles are left: 1 red and 2 blue. The chance that the second marble is red is $\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After one red is removed: 1 red, 2 blue left. P(red) = 1/3.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d2ec6bf-f772-46be-8455-d944675c1554', 'NC26.7.RD.1', 1, 'choice', 'Designing a simulation', 'A game has a 50% chance of winning each round. Which of these can be used to simulate one round?', '["Flip a fair coin; heads means a win","Roll a fair six-sided die; 1 or 2 means a win","Spin a spinner with 5 equal sections; 1 or 2 means a win","Pick a random digit from 0 to 9; 0, 1, 2 or 3 means a win"]', 'Flip a fair coin; heads means a win', NULL, 'A fair coin lands heads half of the time, which matches a 50% chance. The die rule gives $\frac{2}{6}$, about 33%. The spinner rule gives $\frac{2}{5} = 40\%$, and the digit rule gives $\frac{4}{10} = 40\%$.', 'checked', '{"lint":[],"solve":{"answer":"Flip a fair coin; heads means a win","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 0-3: 4/10 = 0.4. Spinner 2/5 = 0.4. Die 1 or 2: 1/3. Coin heads: 1/2 = 50%. Only the coin works.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa7eb3a3-9c6e-45ff-9079-a78c06707cd8', 'NC26.7.RD.1', 1, 'numeric', 'Designing a simulation', 'A student uses random digits from 0 to 9, each equally likely, to simulate an event with probability 0.4. How many of the ten digits should stand for the event happening?', '[]', '4', '0.4*10', 'Each digit has a $\frac{1}{10}$ chance. To get a probability of 0.4, which is $\frac{4}{10}$, the event should use 4 of the 10 digits.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4 x 10 digits = 4 digits.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adc13b32-b08d-4f10-a2d5-136218c85e91', 'NC26.7.RD.1', 1, 'choice', 'Designing a simulation', 'A student uses random digits from 0 to 9 to simulate rolling a fair six-sided die. The digits 1 to 6 stand for the faces of the die. What should the student do when a 0, 7, 8 or 9 comes up?', '["Count it as a 6","Count it as a 1","Stop and start the whole simulation over","Ignore it and use the next digit"]', 'Ignore it and use the next digit', NULL, 'Only the digits 1 to 6 match the die, and each is equally likely. Digits that do not stand for a face are skipped. Counting an extra digit as a 6 or a 1 would make that face more likely than the others.', 'checked', '{"lint":[],"solve":{"answer":"Ignore it and use the next digit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To keep 1-6 equally likely, discard 0, 7, 8, 9 and use the next digit. Counting them as 1 or 6 would bias those faces; restarting is wasteful and unnecessary.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f3d4406-5189-4d16-91ac-e9335f1aec20', 'NC26.7.RD.1', 1, 'numeric', 'Experimental probability from trials and simulations', 'A fair coin was flipped 20 times and landed on heads 9 times. What is the experimental probability of heads? Write your answer as a fraction.', '[]', '9/20', '9/20', 'The experimental probability is the number of times the event happened divided by the number of trials: $\frac{9}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 heads / 20 flips = 9/20.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a822358a-7c41-4d51-b479-ac698f05ad52', 'NC26.7.RD.1', 1, 'choice', 'Experimental probability from trials and simulations', 'Rina dropped a paper cup 50 times. It landed on its side 14 times. Based on this experiment, what is the experimental probability that the cup lands on its side?', '["7/25","7/18","18/25","7/50"]', '7/25', '14/50', 'The cup landed on its side 14 times in 50 drops, so the experimental probability is $\frac{14}{50} = \frac{7}{25}$. (7/18 compares 14 to the 36 other drops, and 18/25 is the chance it did NOT land on its side.)', 'checked', '{"lint":[],"solve":{"answer":"7/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/50 = 7/25.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7ecf846-3b41-4dbd-a101-aa11721fbdb5', 'NC26.7.RD.1', 1, 'numeric', 'Experimental probability from trials and simulations', 'A spinner was spun 40 times and landed on blue 10 times. Based on these results, about how many times would you expect it to land on blue in 200 spins?', '[]', '50', '10/40*200', 'The experimental probability of blue is $\frac{10}{40} = \frac{1}{4}$. In 200 spins you would expect $\frac{1}{4} \times 200 = 50$ blues.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/40 = 1/4; 1/4 x 200 = 50.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b63f9e22-1362-4170-a65d-e0181f6a2e9f', 'NC26.7.RD.1', 1, 'choice', 'Expected results and the effect of more trials', 'A fair coin has landed on heads 5 times in a row. What is the probability that the next flip is heads?', '["0","1/2","1","1/64"]', '1/2', '1/2', 'A coin has no memory. Every flip of a fair coin has probability $\frac{1}{2}$ of heads, no matter what came before. (1/64 is the chance of six heads in a row before any flips are made.)', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flips are independent; a fair coin still has P(heads) = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('288c68d4-5ef6-4216-89f1-1def352a3deb', 'NC26.7.RD.1', 1, 'numeric', 'Expected results and the effect of more trials', 'A fair six-sided die is rolled 600 times. About how many times would you expect it to land on 4?', '[]', '100', '600/6', 'The probability of rolling a 4 is $\frac{1}{6}$. In 600 rolls you would expect about $\frac{1}{6} \times 600 = 100$ fours.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6 x 600 = 100.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20e2b4c5-fd8b-4ced-8e20-abaef016edc0', 'NC26.7.RD.1', 1, 'choice', 'Expected results and the effect of more trials', 'The theoretical probability that a spinner lands on red is $\frac{1}{4}$. Which experiment is most likely to give an experimental probability closest to $\frac{1}{4}$?', '["Spinning it 4 times","Spinning it 8 times","Spinning it 400 times","Spinning it 20 times"]', 'Spinning it 400 times', NULL, 'The more trials in an experiment, the closer the experimental probability usually gets to the theoretical probability. Of the choices, 400 spins is the most trials.', 'checked', '{"lint":[],"solve":{"answer":"Spinning it 400 times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More trials make experimental probability approach theoretical; 400 spins is the largest sample.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29038d30-2b12-42d6-9ccc-d60c95c1f8c0', 'NC26.7.RD.1', 2, 'numeric', 'List a sample space of three flips', 'A fair coin is flipped 3 times. What is the probability of getting exactly 1 head? Write your answer as a fraction.', '[]', '3/8', '3/8', 'List all 8 equally likely outcomes: HHH, HHT, HTH, HTT, THH, THT, TTH, TTT. Exactly one head happens in HTT, THT and TTH, which is 3 outcomes. The probability is $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 outcomes; exactly one head: HTT, THT, TTH = 3. 3/8.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('443cb9e2-6c9e-4b0e-8f52-00b00531aab8', 'NC26.7.RD.1', 2, 'numeric', 'Compound event with replacement', 'A bag has 2 red marbles and 3 blue marbles. A marble is drawn at random, its color is noted, and it is put back in the bag. Then a second marble is drawn. What is the probability that both marbles are blue? Write your answer as a fraction.', '[]', '9/25', '3/5*3/5', 'Because the first marble is put back, each draw has the same chance of blue: $\frac{3}{5}$. The chance of two blues is $\frac{3}{5} \times \frac{3}{5} = \frac{9}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"9/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With replacement: 3/5 x 3/5 = 9/25.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('568c7602-38a2-433f-9da2-e2096b6245d8', 'NC26.7.RD.1', 2, 'choice', 'Experiments approach theory with more trials', 'Mia flips a fair coin 10 times and gets 7 heads. Then she flips it 1,000 times. Which statement is true?', '["The fraction of heads will probably be close to $\\frac{1}{2}$","The fraction of heads will probably stay close to $\\frac{7}{10}$","The fraction of heads will be exactly $\\frac{1}{2}$","The fraction of heads will probably be below $\\frac{1}{2}$ to even things out"]', 'The fraction of heads will probably be close to $\frac{1}{2}$', NULL, 'A fair coin has a theoretical probability of $\frac{1}{2}$ for heads. With many more flips, the fraction of heads usually gets close to $\frac{1}{2}$, although it will rarely be exactly $\frac{1}{2}$. The coin does not remember the first 10 flips, so it does not try to even things out.', 'checked', '{"lint":[],"solve":{"answer":"The fraction of heads will probably be close to $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fair coin: with many trials the relative frequency approaches 1/2; it is not guaranteed exact, and the coin has no memory. Choose ''probably close to 1/2''.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a07f2da1-86ed-4493-b43b-08b5507bb057', 'NC26.7.RD.1', 2, 'choice', 'Theoretical probability of a single event', 'The letters of the word MISSISSIPPI are written on 11 cards, one letter per card, and the cards are mixed up. One card is drawn at random. What is the probability that it shows the letter S?', '["4/11","1/4","4/7","1/11"]', '4/11', '4/11', 'MISSISSIPPI has 1 M, 4 I''s, 4 S''s and 2 P''s, which is 11 letters. Four of the 11 cards show S, so the probability is $\frac{4}{11}$. (1/4 treats the 4 different letters as equally likely, and 4/7 compares the S''s to the other 7 letters.)', 'checked', '{"lint":[],"solve":{"answer":"4/11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MISSISSIPPI: M1, I4, S4, P2 = 11 letters. S: 4/11.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a11a5b7d-ec37-450d-aebd-03f27e4c40d7', 'NC26.7.RD.1', 2, 'choice', 'Theoretical probability of a single event', 'A box holds 24 cards numbered 1 to 24. One card is drawn at random. What is the probability that the number is a multiple of 6?', '["1/4","1/8","1/6","1/24"]', '1/6', '4/24', 'The multiples of 6 from 1 to 24 are 6, 12, 18 and 24, which is 4 cards. The probability is $\frac{4}{24} = \frac{1}{6}$. (1/4 uses 6 out of 24, 1/8 misses the 24, and 1/24 counts only the card 6.)', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 6 up to 24: 6, 12, 18, 24 = 4. 4/24 = 1/6.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35c07a18-dec8-4c0b-af25-d23df3635cbb', 'NC26.7.RD.1', 2, 'numeric', 'Theoretical probability of a single event', 'A fair 12-sided die has faces numbered 1 to 12. What is the probability of rolling a prime number? Write your answer as a fraction.', '[]', '5/12', '5/12', 'The prime numbers from 1 to 12 are 2, 3, 5, 7 and 11. (1 is not prime.) That is 5 of the 12 equally likely faces, so the probability is $\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes 1-12: 2, 3, 5, 7, 11 = 5. 5/12.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c8d5d3b-2d7c-4374-bd77-7662e7631dc3', 'NC26.7.RD.1', 2, 'numeric', 'Probability when outcomes are not equally likely', 'A spinner has 8 equal sections: 4 are red, 3 are blue and 1 is yellow. What is the probability that the spinner lands on blue or yellow? Write your answer as a fraction.', '[]', '1/2', '(3+1)/8', 'The colors are not equally likely, but the sections are. Blue and yellow together cover $3 + 1 = 4$ of the 8 sections, so the probability is $\frac{4}{8} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue or yellow: 3 + 1 = 4 of 8 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f59cfcff-189c-4e85-8c1e-862d96d22224', 'NC26.7.RD.1', 2, 'choice', 'Probability when outcomes are not equally likely', 'A spinner lands on A with probability 0.45 and on B with probability 0.35. It can only land on A, B or C. What is the probability that it does NOT land on B?', '["0.35","0.55","0.8","0.65"]', '0.65', '1-0.35', 'The probability of not landing on B is $1 - 0.35 = 0.65$. (0.35 is the probability of B itself, 0.55 is $1 - 0.45$, and 0.8 is the sum of the two given probabilities.)', 'checked', '{"lint":[],"solve":{"answer":"0.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(not B) = 1 - 0.35 = 0.65 (= 0.45 + P(C) where P(C) = 0.2).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
