INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd20bae0-bf95-442b-b3d6-f6cfb506a7e0', 'NC26.7.RD.1', 2, 'choice', 'Probability when outcomes are not equally likely', 'Which list could be the probabilities of the three outcomes of a spinner?', '["0.5, 0.3, 0.3","0.5, 0.3, 0.2","0.4, 0.3, 0.2","0.6, 0.5, 0.1"]', '0.5, 0.3, 0.2', NULL, 'The probabilities of all the outcomes must add to 1. $0.5 + 0.3 + 0.2 = 1.0$. The other lists add to 1.1, 0.9 and 1.2.', 'checked', '{"lint":[],"solve":{"answer":"0.5, 0.3, 0.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 0.9, 1.1, 1.2, 1.0. Only 0.5, 0.3, 0.2 sums to 1.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7886a948-2ae7-4770-82c1-9ffa2e465691', 'NC26.7.RD.1', 2, 'numeric', 'Counting the outcomes of a compound event', 'A restaurant offers 4 appetizers, 5 main dishes and 3 desserts. A meal has one of each. How many different meals are possible?', '[]', '60', '4*5*3', 'Multiply the number of choices at each step: $4 \times 5 \times 3 = 60$ meals.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 5 x 3 = 60.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc85ac34-7ee8-4bd6-956f-77dbdede3ccb', 'NC26.7.RD.1', 2, 'choice', 'Counting the outcomes of a compound event', 'A code has 2 letters chosen from A, B, C, D and E, followed by 1 digit from 0 to 9. A letter may be used twice. How many different codes are possible?', '["100","250","20","50"]', '250', '5*5*10', 'There are 5 choices for the first letter, 5 for the second and 10 for the digit. The number of codes is $5 \times 5 \times 10 = 250$. (20 adds the choices, and 50 uses only one letter.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 5 letters (repetition allowed) x 10 digits = 250.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7e48322-c534-4a26-832f-93526033fe28', 'NC26.7.RD.1', 2, 'choice', 'Counting the outcomes of a compound event', 'A game spinner has 3 equal sections: red, yellow and blue. It is spun 3 times in a row, and the colors are recorded in order. How many outcomes are in the sample space?', '["9","81","27","6"]', '27', '3*3*3', 'Each spin has 3 possible colors, so the number of outcomes is $3 \times 3 \times 3 = 27$. (9 uses only two spins, 81 uses four spins, and 6 is $3 + 3$.)', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3 x 3 = 27 ordered outcomes.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03a9fcc-0a12-4183-8dd8-3cff2f493d7e', 'NC26.7.RD.1', 2, 'numeric', 'Listing a sample space', 'Three friends each toss a fair coin once, and the three results are recorded. What is the probability that at least two of the coins land heads? Write your answer as a fraction.', '[]', '1/2', '4/8', 'List the 8 equally likely outcomes: HHH, HHT, HTH, HTT, THH, THT, TTH, TTT. Two or more heads happen in HHH, HHT, HTH and THH, which is 4 outcomes. The probability is $\frac{4}{8} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 outcomes. At least 2 heads: HHT, HTH, THH, HHH = 4. 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84b9b4eb-8efc-4495-9d0f-afb5c58f5924', 'NC26.7.RD.1', 2, 'choice', 'Listing a sample space', 'A family has two children. Assume a boy and a girl are equally likely each time. What is the probability that the family has one boy and one girl?', '["1/2","1/3","1/4","2/3"]', '1/2', '2/4', 'List the equally likely outcomes in birth order: BB, BG, GB, GG. Two of the four have one boy and one girl, so the probability is $\frac{2}{4} = \frac{1}{2}$. (1/3 wrongly counts BG and GB as one outcome.)', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BB, BG, GB, GG equally likely; one of each: BG, GB = 2/4 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a178cbd-86be-44cf-8d86-c86a9042176c', 'NC26.7.RD.1', 2, 'numeric', 'Listing a sample space', 'A spinner with 5 equal sections numbered 1 to 5 is spun two times. What is the probability that the first number is less than the second number? Write your answer as a fraction.', '[]', '2/5', '10/25', 'There are $5 \times 5 = 25$ outcomes. The ones with first less than second are 12, 13, 14, 15, 23, 24, 25, 34, 35 and 45, which is 10 outcomes. The probability is $\frac{10}{25} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 ordered pairs. First < second: for first=1: 4, 2: 3, 3: 2, 4: 1 = 10. 10/25 = 2/5.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97dbaa8e-5890-43a8-b34f-c76fb2d48d59', 'NC26.7.RD.1', 2, 'choice', 'Using a table of outcomes', 'Two fair six-sided dice are rolled and the numbers are added. All 36 outcomes are listed in a table. What is the probability that the sum is 9?', '["1/12","1/6","1/4","1/9"]', '1/9', '4/36', 'A sum of 9 comes from 3 and 6, 4 and 5, 5 and 4, or 6 and 3, which is 4 cells of the 36. The probability is $\frac{4}{36} = \frac{1}{9}$. (1/12 misses one of the four pairs.)', 'checked', '{"lint":[],"solve":{"answer":"1/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 9: (3,6), (4,5), (5,4), (6,3) = 4 of 36 = 1/9.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bfd3d3e-0069-479a-8a9b-1a974eb26467', 'NC26.7.RD.1', 2, 'choice', 'Using a table of outcomes', 'When two fair six-sided dice are rolled and the numbers are added, which sum is the most likely?', '["6","12","7","9"]', '7', '7', 'In the table of all 36 outcomes, a sum of 7 appears 6 times, more than any other sum. A sum of 6 appears 5 times, a sum of 9 appears 4 times, and a sum of 12 appears only once.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7 has 6 ways, more than any other sum (6 and 8 have 5, 9 has 4, 12 has 1).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
