INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb3ef483-5030-47fe-b278-3fc118523016', 'NC26.7.RD.1', 2, 'numeric', 'Using a table of outcomes', 'Two fair six-sided dice are rolled. What is the probability that the two numbers differ by exactly 3? Write your answer as a fraction.', '[]', '1/6', '6/36', 'The pairs that differ by 3 are (1, 4), (2, 5), (3, 6), (4, 1), (5, 2) and (6, 3), which is 6 of the 36 outcomes. The probability is $\frac{6}{36} = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differ by 3: (1,4), (2,5), (3,6) and reversed = 6 of 36 = 1/6.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c18310d0-512f-4e3b-b773-54899335a364', 'NC26.7.RD.1', 2, 'numeric', 'Using a tree diagram', 'A game has two rounds. Zack wins each round with probability $\frac{3}{4}$, and the rounds do not affect each other. A tree diagram shows win or lose for each round. What is the probability that he wins both rounds? Write your answer as a fraction.', '[]', '9/16', '3/4*3/4', 'On the path win, then win, multiply the branch probabilities: $\frac{3}{4} \times \frac{3}{4} = \frac{9}{16}$.', 'checked', '{"lint":[],"solve":{"answer":"9/16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x 3/4 = 9/16.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
