INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da0c5a8c-65b1-4f4c-bd27-2ead541980ee', 'NC26.7.RD.2', 1, 'choice', 'Population and sample', 'A principal asks 30 of the 600 students in a school which lunch they like best. What is the population in this survey?', '["all 600 students in the school","the 30 students who were asked","the principal who asked the question","the different lunches on the menu"]', 'all 600 students in the school', NULL, 'The population is the whole group we want to learn about: all 600 students. The 30 students who were asked are the sample.', 'checked', '{"lint":[],"solve":{"answer":"all 600 students in the school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population = the whole group of interest: all 600 students. The 30 are the sample.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
