INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3595f2d-d037-4a1d-9689-3da56f9be3cb', 'NC26.7.RD.2', 1, 'numeric', 'Population and sample', 'A town has 4,500 households. A researcher asks 90 of the households about recycling. How many households are in the sample?', '[]', '90', '90', 'The sample is the part of the population that is asked. Here 90 households are asked, so the sample has 90 households.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample = the 90 households asked.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
