INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8722a8f-66e1-4743-99f3-54f5c15d1dae', 'NC26.7.RD.2', 1, 'numeric', 'Population and sample', 'A school has 480 students. A sample of 48 students is asked about a new bike rack. What fraction of the population is in the sample? Write your answer as a fraction.', '[]', '1/10', '48/480', 'The fraction is $\frac{48}{480}$. Dividing the top and bottom by 48 gives $\frac{1}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"1/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48/480 = 1/10.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df8beb64-ac17-41b3-91ed-18ce8a435de8', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'A school wants to find out how many hours of sleep its students get. Which sample is most likely to be biased?', '["Students whose names are drawn from a hat that holds all names","Students picked by a computer from the full school list","Students chosen with a spinner that has a section for each student","The students who are on the school''s early-morning running team"]', 'The students who are on the school''s early-morning running team', NULL, 'A runner who trains early may sleep differently from other students, so the team does not represent everyone. The other samples give every student the same chance of being chosen.', 'checked', '{"lint":[],"solve":{"answer":"The students who are on the school''s early-morning running team","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Early-morning runners likely have different sleep habits than other students: biased. The other three are random from the full list.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa3b4bec-48de-495f-aa9f-ae2bb8ca1268', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'A survey about favorite fruit is given only to students who are waiting in the fruit line at lunch. Why is this sample biased?', '["Lunch time is too short for students to finish a survey.","Students in the fruit line are likely to like fruit more than others.","Students who stand in a line are not allowed to answer surveys.","Fruit is a healthy food, so the survey asks about the wrong kind of thing."]', 'Students in the fruit line are likely to like fruit more than others.', NULL, 'The students were chosen because they were getting fruit, so they probably like fruit more than students who were not in that line. The sample favors one kind of answer, which is bias.', 'checked', '{"lint":[],"solve":{"answer":"Students in the fruit line are likely to like fruit more than others.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students choosing fruit likely like fruit more, so the sample over-represents fruit lovers.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c5f71b4-4244-479f-8df3-897bc11508ca', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'Mr. Lin asks his own 25 students whether they like homework, to find out what all 800 students in the school think. What is wrong with this sample?', '["It uses students from only one class, so it may not fit the whole school.","The number 25 is an odd number, so the sample cannot be random.","He should have asked the teachers in his school instead of the students.","Homework is not a good topic to ask students about in a survey."]', 'It uses students from only one class, so it may not fit the whole school.', NULL, 'One class may be different from the rest of the school, so its answers may not match what all 800 students think. A sample should be chosen from the whole population.', 'checked', '{"lint":[],"solve":{"answer":"It uses students from only one class, so it may not fit the whole school.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One class may not represent all 800 students (convenience sample).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d84511c7-eef5-4551-9006-0afcc2a97366', 'NC26.7.RD.2', 1, 'choice', 'Choose a random sampling method', 'A teacher wants a random sample of 5 students from her class of 25. Which method gives every student the same chance of being chosen?', '["Pick the 5 students who are sitting nearest to the front","Pick the first 5 students who raise their hands in class","Write each name on a card, mix the cards well, and draw 5","Pick the 5 students that she likes best in the class"]', 'Write each name on a card, mix the cards well, and draw 5', NULL, 'Drawing names from a well-mixed pile gives every student the same chance. The other methods favor certain students.', 'checked', '{"lint":[],"solve":{"answer":"Write each name on a card, mix the cards well, and draw 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shuffled name cards give each student an equal chance; the others depend on seat, hand-raising or preference.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82c65c7a-e329-44b6-a140-1477290dcafe', 'NC26.7.RD.2', 1, 'choice', 'Choose a random sampling method', 'Which of these gives a random sample of a school''s 300 students?', '["Take the first 30 students who arrive at school today","Take 30 students who are all in the same classroom","Take 30 students from the school''s honor roll list","Use a computer to pick 30 student ID numbers at random"]', 'Use a computer to pick 30 student ID numbers at random', NULL, 'A computer choosing ID numbers at random gives every student the same chance. The other groups are made of students who are alike in some way.', 'checked', '{"lint":[],"solve":{"answer":"Use a computer to pick 30 student ID numbers at random","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random selection of ID numbers by computer is random; the others are convenience or restricted groups.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9762fccc-69ec-4fb2-8a0d-e16edbf0ad95', 'NC26.7.RD.2', 1, 'choice', 'Choose a random sampling method', 'What makes a sample random?', '["The person doing the survey picks members who seem typical.","Every member of the population has an equal chance to be chosen.","Only people who volunteer to answer are included in the sample.","All of the members of the sample must be exactly the same age."]', 'Every member of the population has an equal chance to be chosen.', NULL, 'In a random sample, chance alone decides who is chosen and each member has the same chance.', 'checked', '{"lint":[],"solve":{"answer":"Every member of the population has an equal chance to be chosen.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random means each member has an equal chance of being chosen.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b7764b9-ba24-46d9-8c22-a85f3a1818d5', 'NC26.7.RD.2', 1, 'choice', 'Why a random sample represents a population, and how samples vary', 'Why do people often use a random sample instead of asking everyone in a large population?', '["It saves time and money, and can still show what the population is like.","A sample is always exactly the same as the whole population it came from.","Asking every person in a large population is always against the law.","A sample never has any errors, even though it is small."]', 'It saves time and money, and can still show what the population is like.', NULL, 'Asking everyone in a large population takes a lot of time and money. A random sample is a smaller group that can still give a good picture of the whole, though not a perfect one.', 'checked', '{"lint":[],"solve":{"answer":"It saves time and money, and can still show what the population is like.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sampling saves time and money while still representing the population; samples are not exact and censuses are not illegal.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('213df4e3-31df-45d3-a528-92d2040d83b2', 'NC26.7.RD.2', 1, 'choice', 'Why a random sample represents a population, and how samples vary', 'Why is a random sample likely to give a fair picture of the whole population?', '["The people are chosen because they tend to agree with the person asking.","The people who are chosen all come from the same place.","The sample is always the largest sample that is possible.","Everyone has the same chance of being chosen, so no group is favored."]', 'Everyone has the same chance of being chosen, so no group is favored.', NULL, 'When chance picks the members, no group is more likely to be chosen than another, so the sample tends to look like the population.', 'checked', '{"lint":[],"solve":{"answer":"Everyone has the same chance of being chosen, so no group is favored.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal chance means no group is systematically favored.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4c8bb13-4e48-419e-aaa6-1ff769ec4ee7', 'NC26.7.RD.2', 1, 'numeric', 'Estimate a population count or percent from a random sample', 'A school has 500 students. In a random sample of 50 students, 10 walk to school. Based on the sample, about how many of the 500 students walk to school?', '[]', '100', '10/50*500', '$\frac{10}{50} = \frac{1}{5}$ of the sample walk. So about $\frac{1}{5}$ of the 500 students walk: $500 \div 5 = 100$ students.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/50 = 1/5; 1/5 x 500 = 100.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be23d15b-7c7f-4ec7-bba9-8756da776edb', 'NC26.7.RD.2', 1, 'numeric', 'Estimate a population count or percent from a random sample', 'In a random sample of 25 library books, 5 are checked out. About what percent of all the library''s books are checked out?', '[]', '20', '5/25*100', '$\frac{5}{25} = \frac{20}{100} = 20\%$. So about 20 percent of the library''s books are checked out.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/25 = 0.2 = 20%.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a22c840a-feee-4add-a9d1-c4e8a6667a3a', 'NC26.7.RD.2', 1, 'numeric', 'Estimate a population mean or median from a sample', 'A random sample of 5 backpacks has weights of 8, 10, 12, 9 and 11 pounds. What is the mean weight of the sample in pounds?', '[]', '10', '(8+10+12+9+11)/5', 'Add the weights: $8 + 10 + 12 + 9 + 11 = 50$. Divide by 5: $50 \div 5 = 10$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Only computes a sample mean (a grade 6 skill); no inference is asked. Weakly aligned but acceptable as a step in using samples.","work":"Sum 8+10+12+9+11 = 50; mean 50/5 = 10.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47e9b905-30fe-4eb1-861c-b8cfd410d7b9', 'NC26.7.RD.2', 1, 'numeric', 'Simulate a sample with random numbers or a device', 'To pick one student at random from a class numbered 1 to 20, a teacher reads random numbers from a list: 34, 07, 21, 15. She uses the first number on the list that is from 1 to 20. What number is it?', '[]', '7', '7', '34 is more than 20, so she skips it. 07 is the number 7, which is from 1 to 20. So student number 7 is chosen.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34 is out of range; 07 is in 1-20, so 7.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8571e8-849c-48f9-bbcf-681bc6f7f53d', 'NC26.7.RD.2', 1, 'choice', 'Simulate a sample with random numbers or a device', 'Which tool could be used to simulate choosing at random among exactly 6 equally likely choices?', '["a fair coin","a spinner with 5 equal sections","a fair six-sided number cube","a deck of 8 different cards"]', 'a fair six-sided number cube', NULL, 'A number cube has 6 faces that are equally likely, one for each choice. A coin has 2 outcomes, the spinner 5, and the deck 8.', 'checked', '{"lint":[],"solve":{"answer":"a fair six-sided number cube","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fair six-sided cube gives 6 equally likely outcomes; coin 2, spinner 5, cards 8.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7570054-d9aa-4846-aa20-94f903eb8c89', 'NC26.7.RD.2', 1, 'numeric', 'Organize and count data from two groups', 'Students in a morning class and in an afternoon class each said whether they walk (W) or ride (R) to school. The morning class answered: W, R, R, W, W, R, W, W. How many students in the morning class walk?', '[]', '5', '5', 'Count the W answers: W, W, W, W, W. There are 5 of them.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"W, R, R, W, W, R, W, W: W at positions 1, 4, 5, 7, 8 = 5.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac8ec9aa-6e97-405a-84c3-6c21191b0ed6', 'NC26.7.RD.2', 1, 'numeric', 'Organize and count data from two groups', 'In Room A, 12 students like soccer and 8 like swimming. In Room B, 9 students like soccer and 11 like swimming. How many students in the two rooms together like swimming?', '[]', '19', '8+11', 'Add the swimming fans in the two rooms: $8 + 11 = 19$ students.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Swimming: 8 + 11 = 19.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2b38d26-c980-4dd4-a0a1-9bdeeb61484a', 'NC26.7.RD.2', 1, 'choice', 'Organize and count data from two groups', 'A teacher collects yes-or-no answers from two groups of students. Which way of organizing the data makes it easiest to compare the groups?', '["One long list of the names of all the students in both groups","A table with a row for each group and columns for yes and no","A single total that adds up all the yes answers from both groups","A list of the room numbers where the two groups meet"]', 'A table with a row for each group and columns for yes and no', NULL, 'A table with a row for each group and a column for each answer shows the counts for both groups side by side, so they are easy to compare.', 'checked', '{"lint":[],"solve":{"answer":"A table with a row for each group and columns for yes and no","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A two-way table (group by yes/no) shows each group''s counts side by side.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ded80a77-6b87-48b8-821e-26c4392f6574', 'NC26.7.RD.2', 1, 'numeric', 'Compare two groups with fractions, means, medians or ranges', 'The mean number of books read this month is 5 for Group P and 8 for Group Q. How many more books did each student in Group Q read, on average, than each student in Group P?', '[]', '3', '8-5', 'Subtract the means: $8 - 5 = 3$ books.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy (one subtraction). Wording ''each student in Group Q read, on average, than each student in Group P'' is a little awkward; ''on average, how many more books did a student in Group Q read'' reads better.","work":"8 - 5 = 3.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('effef4dc-5663-42a0-b211-b1df7416a83f', 'NC26.7.RD.2', 1, 'numeric', 'Compare two groups with fractions, means, medians or ranges', 'The median reading time of a sample of fifth graders is 15 minutes a day. The median reading time of a sample of seventh graders is 21 minutes a day. How many minutes longer is the seventh graders'' median?', '[]', '6', '21-15', 'Subtract the medians: $21 - 15 = 6$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 - 15 = 6.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cfc5613-0d2a-4f72-bd28-f102d60fec2b', 'NC26.7.RD.2', 1, 'choice', 'Judge a conclusion drawn from a sample', 'A random sample of 30 students finds that 24 like pizza. Which conclusion is the most reasonable about all the students in the school?', '["Exactly 80 percent of the students like pizza.","Every student likes pizza.","Most of the students probably like pizza.","No student dislikes pizza."]', 'Most of the students probably like pizza.', NULL, '$\frac{24}{30} = 80\%$ of the sample like pizza, so most students in the school probably do. But a sample only estimates, so we cannot say exactly 80 percent, or all students.', 'checked', '{"lint":[],"solve":{"answer":"Most of the students probably like pizza.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/30 = 80% in the sample suggests most students probably like pizza; ''exactly 80%'', ''every'' and ''no student dislikes'' overclaim.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2563ee69-a522-4113-84cf-01a2f496bc65', 'NC26.7.RD.2', 1, 'choice', 'Word a survey question fairly', 'Which survey question is worded fairly?', '["Wouldn''t you agree that pizza is much tastier than tacos?","Everyone loves pizza, so you do too, right?","Isn''t it silly to choose tacos over pizza?","Which lunch do you like better, pizza or tacos?"]', 'Which lunch do you like better, pizza or tacos?', NULL, 'A fair question does not push the person toward an answer. The first question offers two choices without a hint. The others lead people to say "pizza".', 'checked', '{"lint":[],"solve":{"answer":"Which lunch do you like better, pizza or tacos?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only ''Which lunch do you like better, pizza or tacos?'' is neutral; the others lead toward pizza.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81af24f4-e7f1-457c-a362-77e17683e093', 'NC26.7.RD.2', 2, 'numeric', 'Predict a population from a sample', 'A random sample of 60 students from a school of 1,200 students was asked whether they like the new lunch menu. Of the 60 students, 45 said yes. Based on the sample, about how many of the 1,200 students like the new lunch menu?', '[]', '900', '45/60*1200', 'In the sample, $\frac{45}{60} = \frac{3}{4}$ said yes. A random sample is likely to match the whole school, so about $\frac{3}{4}$ of 1,200 students like the menu: $\frac{3}{4} \times 1200 = 900$.', 'checked', '{"lint":[],"solve":{"answer":"900","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45/60 = 3/4; 3/4 x 1200 = 900.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1379e58e-3b90-4020-abae-494bfe478a60', 'NC26.7.RD.2', 2, 'choice', 'Spot a biased sample', 'To find out how all 500 students at a school feel about a new music class, a survey is given to 100 students as they leave a band concert. Why might the results be biased?', '["100 students is too few for any survey to be fair","Students at a band concert are more likely to like music than other students","The survey should have been given to teachers instead","The students were asked as they left, not as they arrived"]', 'Students at a band concert are more likely to like music than other students', NULL, 'A sample is biased when some members of the population are more likely to be chosen or to answer a certain way. People at a band concert probably like music more than the average student. A sample of 100 out of 500 is large enough, and when they were asked does not matter.', 'checked', '{"lint":[],"solve":{"answer":"Students at a band concert are more likely to like music than other students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is drawn from concert-goers, who are more likely to favour music: selection bias.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('550e8a37-cb35-4f9c-ae13-60cad38f4775', 'NC26.7.RD.2', 2, 'choice', 'Compare two groups using fractions', 'In a random sample, 18 of 20 sixth graders and 21 of 30 seventh graders said they like the school lunch. Which group had the greater fraction who like the lunch?', '["The seventh graders","Neither; the fractions are equal","Neither; the sample sizes are different","The sixth graders"]', 'The sixth graders', NULL, 'Compare the fractions, not the counts. Sixth graders: $\frac{18}{20} = 0.9$. Seventh graders: $\frac{21}{30} = 0.7$. The sixth graders have the greater fraction, even though fewer of them were asked. Groups of different sizes can be compared using fractions or percents.', 'checked', '{"lint":[],"solve":{"answer":"The sixth graders","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sixth: 18/20 = 0.9. Seventh: 21/30 = 0.7. Sixth graders greater.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('545d302e-bcbc-4838-82a0-76e7926389e3', 'NC26.7.RD.2', 2, 'choice', 'Recognize a statistical question', 'Which of these questions is statistical?', '["How much did Sam spend on his school lunch last Monday?","How much do students at our school spend on lunch each day?","What is the price of one school lunch at our school today?","How many students bought a school lunch last Monday?"]', 'How much do students at our school spend on lunch each day?', NULL, 'Students spend different amounts, so we would need data from many students and the answers would vary. The other three questions each have a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How much do students at our school spend on lunch each day?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spending by students at the school varies: statistical. Sam''s spending, today''s price and last Monday''s count are single values.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd72c427-f25a-41f1-9116-34c1f2f7c4a0', 'NC26.7.RD.2', 2, 'numeric', 'Recognize a statistical question', 'Four questions are listed. (1) How old is each student in Room 4? (2) What is the capital of North Carolina? (3) How many hours do the students at our school sleep on school nights? (4) How many days are in October? How many of these four questions are statistical questions?', '[]', '2', '2', 'Questions (1) and (3) ask about many students, and the answers vary, so they are statistical. Questions (2) and (4) each have a single answer. So 2 of the questions are statistical.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) ages vary: statistical. (2) one answer. (3) sleep varies: statistical. (4) 31: one answer. Count = 2.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a432a3d0-2ab1-4763-938f-a4e13092ae15', 'NC26.7.RD.2', 2, 'choice', 'Write or choose a question that compares two groups', 'Zoe wants to compare the daily screen time of students who play a sport with that of students who do not. What should she ask each student she surveys?', '["Which sport do you play most often, and how many teams are you on this year?","How many hours of screen time do you have daily, and do you play a sport?","What is your favorite game or app to use on a screen at home?","Do you think students should have more or less screen time?"]', 'How many hours of screen time do you have daily, and do you play a sport?', NULL, 'To compare two groups, she needs each student''s screen time and also which group the student is in (plays a sport or not). The other questions leave out at least one of these.', 'checked', '{"lint":[],"solve":{"answer":"How many hours of screen time do you have daily, and do you play a sport?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She needs the screen-time measurement and the grouping variable (sport or not) from each student.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71f6e81e-75ee-4a42-b924-eabb3db9cb4e', 'NC26.7.RD.2', 2, 'choice', 'Write or choose a question that compares two groups', 'A librarian wants to compare how many books sixth graders and seventh graders borrow in a month. Which plan collects the data needed?', '["Ask only the seventh graders how many books they borrowed this month","Count all of the books that are on the shelves of the school library","Ask some students in each grade how many books they borrowed this month","Ask the librarian how many books she herself borrowed this month"]', 'Ask some students in each grade how many books they borrowed this month', NULL, 'The data must come from both grades, and it must be the number of books each student borrowed. Only the first plan does that.', 'checked', '{"lint":[],"solve":{"answer":"Ask some students in each grade how many books they borrowed this month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need borrowing data from both sixth and seventh graders: ask students in each grade.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d92b7275-718c-4f69-b04a-e0e36594b4c6', 'NC26.7.RD.2', 2, 'choice', 'Population and sample', 'A bakery makes 2,000 muffins in a day. The manager weighs 25 of them to check the size. Which statement is correct?', '["The population is the 25 muffins that were weighed, and the sample is the 2,000 muffins.","The population is the 2,000 muffins, and the sample is the 25 that were weighed.","The 2,000 muffins and the 25 weighed muffins are both populations.","The 2,000 muffins and the 25 weighed muffins are both samples."]', 'The population is the 2,000 muffins, and the sample is the 25 that were weighed.', NULL, 'The population is the whole group being studied, here all 2,000 muffins. The 25 muffins that were weighed are a part of it, so they are the sample.', 'checked', '{"lint":[],"solve":{"answer":"The population is the 2,000 muffins, and the sample is the 25 that were weighed.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population: all 2,000 muffins; sample: the 25 weighed.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f144ecc-8408-4c85-bd02-218bdc962d59', 'NC26.7.RD.2', 2, 'choice', 'Spot and explain bias in a sample', 'A website posts a poll that asks, "Do you enjoy using this website?" Only people who visit the site can vote. Why might the results be biased?', '["Polls that are posted on websites always give results that are wrong.","The poll should have asked people more than one question.","Too many people voted, so the results cannot be correct.","People who visit the site are more likely to enjoy it than others."]', 'People who visit the site are more likely to enjoy it than others.', NULL, 'The people who answer are the people who chose to visit the site, so they are probably fans. That makes the sample biased toward "yes".', 'checked', '{"lint":[],"solve":{"answer":"People who visit the site are more likely to enjoy it than others.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only site visitors vote; they are likely to enjoy it more than the general population (self-selected).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bcf2080-0633-4e24-a449-776040e3688e', 'NC26.7.RD.2', 2, 'numeric', 'Spot and explain bias in a sample', 'A school wants to know the favorite music of all its students. Four plans for choosing 30 students are listed. A: ask the 30 students in the school band. B: choose 30 names at random from the list of all students. C: ask the first 30 students who volunteer after an announcement. D: use a computer to pick 30 student ID numbers at random. How many of the four plans are likely to give a biased sample?', '[]', '2', '2', 'Plan A is biased because band students may like different music from other students. Plan C is biased because volunteers may have stronger opinions than other students. Plans B and D give every student the same chance. So 2 plans are likely to be biased.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A (band members) biased; C (volunteers) biased; B and D random. 2 biased.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc122102-58b2-4853-811c-417149639252', 'NC26.7.RD.2', 2, 'choice', 'Spot and explain bias in a sample', 'A teacher puts out a survey about the cafeteria, and students fill it out only if they want to. Only 12 of 200 students answer, and most answers are negative. Why can the teacher not conclude that most students dislike the cafeteria?', '["The number 12 is an even number, so the results cannot be used.","Surveys can never be used to learn what students think about their school.","Students with strong opinions are more likely to answer, so it may be biased.","Students are not able to judge whether a school cafeteria is good or bad."]', 'Students with strong opinions are more likely to answer, so it may be biased.', NULL, 'People who choose to answer often feel strongly, so they may not be typical. Only 12 of 200 answered, and they chose themselves, so the results may not show what most students think.', 'checked', '{"lint":[],"solve":{"answer":"Students with strong opinions are more likely to answer, so it may be biased.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Voluntary response: people with strong (often negative) opinions answer, so the 12 may not represent the 200.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1211c00-b847-4412-8697-06c42063cf10', 'NC26.7.RD.2', 2, 'choice', 'Choose a random sampling method', 'A town wants to choose a random sample of 12 of its 60 parks to inspect. Which method works?', '["Write the parks'' names on slips, mix them in a bowl, and draw 12","Inspect the 12 parks that are closest to the town hall","Inspect the 12 parks that have the most land in the whole town","Inspect the 12 parks that residents have complained about"]', 'Write the parks'' names on slips, mix them in a bowl, and draw 12', NULL, 'Drawing from a bowl gives all 60 parks the same chance. The other plans choose parks for a reason, so they are not random.', 'checked', '{"lint":[],"solve":{"answer":"Write the parks'' names on slips, mix them in a bowl, and draw 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing slips from a mixed bowl is random; the others select by complaints, size or location.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('876b359f-e4ba-42e4-8f85-6c634f93c045', 'NC26.7.RD.2', 2, 'choice', 'Choose a random sampling method', 'A class has 24 students, each with a list number from 1 to 24. Which method does NOT give every student an equal chance of being chosen?', '["Draw one name from a hat that holds a slip for each of the 24 students","Use a random-number tool to pick a whole number from 1 to 24","Roll a number cube and choose the student whose list number is rolled","Spin a spinner with 24 equal sections, one for each student"]', 'Roll a number cube and choose the student whose list number is rolled', NULL, 'A number cube only shows 1 to 6, so students 7 to 24 can never be chosen. Each of the other methods gives each of the 24 students the same chance.', 'checked', '{"lint":[],"solve":{"answer":"Roll a number cube and choose the student whose list number is rolled","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A number cube gives only 1-6, so students 7-24 can never be chosen. The other methods cover all 24 equally.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61d79ffe-fe96-472c-941c-3850d7d4b7c6', 'NC26.7.RD.2', 2, 'choice', 'Why a random sample represents a population, and how samples vary', 'Ten students each take a random sample of 20 marbles from the same bag and record the fraction that are red. The fractions are not all the same. What does this show?', '["Some of the students must have made mistakes when counting the marbles.","The number of red marbles in the bag changed between samples.","Different random samples from one population can give different results.","Random samples cannot be used to estimate anything about a bag."]', 'Different random samples from one population can give different results.', NULL, 'Chance decides which marbles are drawn, so each sample can have a slightly different fraction of red marbles. This variation is expected.', 'checked', '{"lint":[],"solve":{"answer":"Different random samples from one population can give different results.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sampling variability: different random samples give different results.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fad1fbd5-182d-4fec-9203-8c8831f56683', 'NC26.7.RD.2', 2, 'numeric', 'Why a random sample represents a population, and how samples vary', 'Two random samples of 40 students each are taken at the same school. In one sample, 24 students walk to school. In the other sample, 28 students walk to school. By how many percentage points do the two sample results differ?', '[]', '10', '(28-24)/40*100', 'The first sample is $\frac{24}{40} = 60\%$ and the second is $\frac{28}{40} = 70\%$. They differ by $70 - 60 = 10$ percentage points. Random samples vary like this.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/40 = 60%; 28/40 = 70%. Difference 10 percentage points.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88deccd1-b6ed-4b2a-9450-68a1ae0107cd', 'NC26.7.RD.2', 2, 'numeric', 'Estimate a population count or percent from a random sample', 'A random sample of 80 light bulbs from a factory''s 4,000 bulbs finds 6 that are defective. About how many of the 4,000 bulbs are likely to be defective?', '[]', '300', '6/80*4000', 'The sample has $\frac{6}{80}$ defective. $4000 \div 80 = 50$, so the factory has about $6 \times 50 = 300$ defective bulbs.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/80 x 4000 = 6 x 50 = 300.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b36897f1-6bb8-415f-ba63-05886b3d7952', 'NC26.7.RD.2', 2, 'numeric', 'Estimate a population count or percent from a random sample', 'A random sample of 150 voters from a town of 6,000 voters finds that 90 support building a new park. About how many of the 6,000 voters support the new park?', '[]', '3600', '90/150*6000', '$\frac{90}{150} = \frac{3}{5}$ of the sample support it. $\frac{3}{5} \times 6000 = 3600$ voters.', 'checked', '{"lint":[],"solve":{"answer":"3600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90/150 = 0.6; 0.6 x 6000 = 3600.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6117ba6a-22f6-4fc1-ac0b-0209fe8cfb5c', 'NC26.7.RD.2', 2, 'choice', 'Estimate a population count or percent from a random sample', 'In a random sample of 40 students, 12 say they ride the bus. The school has 900 students. Which is the best estimate of the number of students at the school who ride the bus?', '["108","30","480","270"]', '270', '12/40*900', '$\frac{12}{40} = 0.3$, or 30 percent, so about $0.3 \times 900 = 270$ students ride the bus. The choice 108 treats 12 as a percent, 30 is the percent itself, and 480 multiplies 12 by 40.', 'checked', '{"lint":[],"solve":{"answer":"270","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/40 = 0.3; 0.3 x 900 = 270.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34a6c07d-8eae-4545-9c64-fa86b4a2efea', 'NC26.7.RD.2', 2, 'numeric', 'Estimate a population mean or median from a sample', 'A random sample of 6 seventh graders read 4, 7, 5, 9, 6 and 5 books this year. Use the sample to estimate the mean number of books read this year by all the seventh graders at the school.', '[]', '6', '(4+7+5+9+6+5)/6', 'The mean of the sample is $(4 + 7 + 5 + 9 + 6 + 5) \div 6 = 36 \div 6 = 6$ books. A random sample''s mean is a good estimate of the population''s mean.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4+7+5+9+6+5 = 36; mean 36/6 = 6. Sample mean estimates the population mean: 6.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51af22e7-d179-4b9e-8f19-f76534765b41', 'NC26.7.RD.2', 2, 'numeric', 'Estimate a population mean or median from a sample', 'The numbers of minutes late for a random sample of 7 buses were 2, 5, 0, 9, 4, 6 and 3. What is the median of the sample? (The median is a good estimate of the typical lateness of all the school''s buses.)', '[]', '4', '4', 'Put the numbers in order: 0, 2, 3, 4, 5, 6, 9. The middle value, the fourth of seven, is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered: 0, 2, 3, 4, 5, 6, 9. Median (4th of 7) = 4.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69a1cf92-e8d1-4653-8a0f-a696df28656f', 'NC26.7.RD.2', 2, 'numeric', 'Simulate a sample with random numbers or a device', 'A basketball player makes 70% of her free throws. To simulate one shot, a random digit from 0 to 9 is used: the digits 0 through 6 mean "make" and the digits 7 through 9 mean "miss". For 10 simulated shots, the random digits are 3, 8, 1, 9, 5, 0, 7, 8, 6, 4. How many of the 10 simulated shots are makes?', '[]', '6', '6', 'Count the digits from 0 to 6: 3, 1, 5, 0, 6 and 4. The digits 8, 9, 7 and 8 are misses. So 6 of the 10 shots are makes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Makes are digits 0-6: 3 (make), 8, 1 (make), 9, 5 (make), 0 (make), 7, 8, 6 (make), 4 (make). 6 makes.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67d418bd-bd83-42b9-b77d-5b99c08c82e2', 'NC26.7.RD.2', 2, 'numeric', 'Simulate a sample with random numbers or a device', 'A shop knows that about 40% of the people who visit buy something. A random digit from 0 to 9 simulates one visitor. How many of the ten digits should stand for "buys" so that the simulation matches 40%?', '[]', '4', '10*40/100', 'There are 10 digits, all equally likely. 40% of 10 is $0.4 \times 10 = 4$, so 4 of the digits should stand for "buys".', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40% of 10 digits = 4 digits.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8885ef7e-9724-4960-bc5f-36f35cf7010d', 'NC26.7.RD.2', 2, 'numeric', 'Simulate a sample with random numbers or a device', 'A game gives a prize 1 time out of every 4 plays. A spinner with 12 equal sections is used to simulate one play. How many of the sections should be marked "prize"?', '[]', '3', '12/4', 'A prize happens $\frac{1}{4}$ of the time, so $\frac{1}{4}$ of the 12 sections should be marked: $12 \div 4 = 3$ sections.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 of 12 = 3 sections.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f418ffbd-4a21-4892-bbc3-59c53ef2ca21', 'NC26.7.RD.2', 2, 'numeric', 'Organize and count data from two groups', 'Two classes each recorded how many pets each student owns. Class 1: 0, 1, 1, 2, 3, 1, 0, 2. Class 2: 2, 2, 3, 1, 4, 2, 0. How many students in the two classes together own exactly 2 pets?', '[]', '5', '2+3', 'In Class 1 the number 2 appears 2 times. In Class 2 it appears 3 times. So $2 + 3 = 5$ students own exactly 2 pets.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 1: 0,1,1,2,3,1,0,2 -> two 2s. Class 2: 2,2,3,1,4,2,0 -> three 2s. Total 5.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2be90605-7cbf-42de-b534-a82bef47cba5', 'NC26.7.RD.2', 2, 'numeric', 'Organize and count data from two groups', 'In a survey, 24 of 40 sixth graders and 35 of 50 seventh graders said they prefer pizza. What fraction of all the students surveyed prefer pizza?', '[]', '59/90', '(24+35)/(40+50)', 'Students who prefer pizza: $24 + 35 = 59$. Students surveyed: $40 + 50 = 90$. The fraction is $\frac{59}{90}$.', 'checked', '{"lint":[],"solve":{"answer":"59/90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(24 + 35)/(40 + 50) = 59/90 (already in lowest terms).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d5183b9-6636-40ea-9c5c-ca07361c01fc', 'NC26.7.RD.2', 2, 'numeric', 'Compare two groups with fractions, means, medians or ranges', 'In a random sample of 36 sixth graders, 27 say they want a longer recess. In a random sample of 25 seventh graders, 17 say they want a longer recess. By how many percentage points is the percent of sixth graders who want it greater than the percent of seventh graders?', '[]', '7', '27/36*100-17/25*100', 'Sixth graders: $\frac{27}{36} = 75\%$. Seventh graders: $\frac{17}{25} = 68\%$. The difference is $75 - 68 = 7$ percentage points. Using percents lets us compare groups of different sizes.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27/36 = 75%; 17/25 = 68%; difference 7 percentage points.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9728707-d48c-4ffe-8db2-c3ef290cfe3f', 'NC26.7.RD.2', 2, 'choice', 'Compare two groups with fractions, means, medians or ranges', 'Group A has the scores 6, 8, 9, 10 and 12. Group B has the scores 5, 7, 11, 13 and 14. Which statement is true?', '["Group B has the greater median and the greater mean.","Group A has the greater median and the greater mean.","The two groups have the same mean but different medians.","Group A has a greater range than Group B has."]', 'Group B has the greater median and the greater mean.', NULL, 'Group A: median 9, mean $45 \div 5 = 9$, range $12 - 6 = 6$. Group B: median 11, mean $50 \div 5 = 10$, range $14 - 5 = 9$. So Group B has the greater median and mean, and also the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Group B has the greater median and the greater mean.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: median 9, mean 45/5 = 9, range 6. B: median 11, mean 50/5 = 10, range 9. B has greater median and mean; A''s range is smaller; means differ.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('582c7f37-32eb-44b9-8618-d43428cf639f', 'NC26.7.RD.2', 2, 'numeric', 'Combine several random samples', 'Four random samples of 30 people each are taken from the same population. The numbers of people who say "yes" are 11, 14, 12 and 13. Using all four samples together, estimate the fraction of the population who would say "yes". Write your answer as a fraction.', '[]', '5/12', '(11+14+12+13)/(4*30)', 'Together there are $11 + 14 + 12 + 13 = 50$ "yes" answers out of $4 \times 30 = 120$ people. The fraction is $\frac{50}{120} = \frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total yes 11 + 14 + 12 + 13 = 50 of 120 = 5/12.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f6b4e6d-464a-40e8-9809-cb88bef41650', 'NC26.7.RD.2', 2, 'numeric', 'Combine several random samples', 'Two random samples are taken from the same population. In the first sample, 12 of 40 people say yes. In the second sample, 24 of 60 people say yes. Using both samples together, what fraction of the population would you estimate say yes? Write your answer as a fraction.', '[]', '9/25', '(12+24)/(40+60)', 'Together there are $12 + 24 = 36$ people who say yes out of $40 + 60 = 100$ people. The fraction is $\frac{36}{100} = \frac{9}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"9/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12 + 24)/(40 + 60) = 36/100 = 9/25.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1936c87a-8e31-42ea-a75e-c0fbbf97db03', 'NC26.7.RD.2', 2, 'choice', 'Judge a conclusion drawn from a sample', 'A random sample of 50 students from a school of 1,000 students finds that 30 ride the bus. Which statement is the best conclusion?', '["Exactly 600 of the 1,000 students ride the bus every day.","Only 30 students at the school ride the bus.","Fewer than half of the students ride the bus.","About 600 of the 1,000 students probably ride the bus."]', 'About 600 of the 1,000 students probably ride the bus.', NULL, '$\frac{30}{50} = 60\%$ of the sample ride the bus, so about 60% of 1,000, or 600, probably do. A sample gives an estimate, not an exact count.', 'checked', '{"lint":[],"solve":{"answer":"About 600 of the 1,000 students probably ride the bus.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/50 = 60%; 0.6 x 1000 = about 600, an estimate not exact.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98685e99-36ef-4f7f-b0e3-1b544f4773de', 'NC26.7.RD.2', 2, 'choice', 'Judge a conclusion drawn from a sample', 'In random samples, 12 of 15 sixth graders and 24 of 40 seventh graders like the new library hours. Which conclusion is best supported?', '["Every sixth grader likes the hours more than every seventh grader does.","The samples suggest, but do not prove, that sixth graders like the hours more.","Seventh graders like the hours more, since 24 is a greater number than 12.","The samples show nothing at all, since the two samples are different sizes."]', 'The samples suggest, but do not prove, that sixth graders like the hours more.', NULL, 'Sixth graders: $\frac{12}{15} = 80\%$. Seventh graders: $\frac{24}{40} = 60\%$. The sixth graders in the samples like the hours more. Samples can only suggest what is true for everyone. Different sample sizes are fine when we compare fractions or percents.', 'checked', '{"lint":[],"solve":{"answer":"The samples suggest, but do not prove, that sixth graders like the hours more.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/15 = 80% vs 24/40 = 60%. Compare rates, not counts; the samples suggest sixth graders like the hours more but do not prove it.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98e6f671-5079-492d-a008-4095580fecbb', 'NC26.7.RD.2', 2, 'choice', 'Word a survey question fairly', 'A survey asks, "Our wonderful new park has great playground equipment. How much do you enjoy the park?" Why is this question a problem?', '["The wording pushes people toward a positive answer.","The question is about a park instead of about a school.","The question is too short to give useful results.","The question does not ask about the people who use the park."]', 'The wording pushes people toward a positive answer.', NULL, 'Calling the park "wonderful" with "great" equipment suggests the answer the writer wants. A fair question would ask about the park without praising it.', 'checked', '{"lint":[],"solve":{"answer":"The wording pushes people toward a positive answer.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Wonderful'' and ''great'' lead respondents toward a positive answer.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a1d182d-70f8-408c-b2ac-923a1a5e3d4e', 'NC26.7.RD.2', 2, 'numeric', 'Word a survey question fairly', 'Three survey questions are listed. (1) Which do you prefer, cats or dogs? (2) Don''t you agree that dogs are better than cats? (3) Dogs are wonderful, so which pet do you like better? How many of these three questions are worded fairly?', '[]', '1', '1', 'Question (1) gives both choices without a hint. Question (2) leads people to agree, and question (3) praises dogs first. So only 1 question is worded fairly.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) neutral; (2) leading; (3) leading. 1 fair.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56f57a6e-3bca-46f4-ba09-d6710c08cfb5', 'NC26.7.RD.2', 3, 'numeric', 'Combine several random samples', 'A jar holds 500 marbles, some red and the rest blue. Four different random samples of 20 marbles each have 4, 6, 5 and 5 red marbles. Use all four samples together to estimate how many red marbles are in the jar.', '[]', '125', '(4+6+5+5)/(4*20)*500', 'Together the samples hold $4 \times 20 = 80$ marbles, and $4 + 6 + 5 + 5 = 20$ of them are red. That is $\frac{20}{80} = \frac{1}{4}$. A quarter of 500 marbles is $500 \div 4 = 125$.', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red in samples: 4 + 6 + 5 + 5 = 20 of 80 = 1/4. Estimate 1/4 x 500 = 125.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52647ad4-c596-419d-961f-eb746b092dfc', 'NC26.7.RD.2', 3, 'choice', 'Sample size and reliability', 'Two students each want to estimate the fraction of 900 students who like the school mascot. Ana asks 15 students chosen at random. Ben asks 150 students chosen at random. Whose estimate is likely to be closer to the true fraction, and why?', '["Ana''s, because a smaller sample has less bias","Neither, because random samples are never close to the truth","Ben''s, because a larger random sample varies less","They are equally likely to be close, because both samples are random"]', 'Ben''s, because a larger random sample varies less', NULL, 'Both samples are random, so neither is biased. But a small sample can easily land far from the true fraction by chance, while a larger random sample tends to stay close to it. Ben''s sample of 150 is more likely to give a good estimate.', 'checked', '{"lint":[],"solve":{"answer":"Ben''s, because a larger random sample varies less","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples have less sampling variability, so Ben''s estimate is likely closer.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9613b346-9cc6-4a41-9add-c5b7e6556ae7', 'NC26.7.RD.2', 3, 'numeric', 'Draw a random sample with random numbers', 'Mr. Lee numbers his 30 students from 01 to 30. He reads two-digit numbers in order from a list of random numbers. He keeps each number that is from 01 to 30 and is not already chosen, and he stops when 4 students are chosen. The list is 31, 17, 45, 08, 17, 30, 09, 25. What is the number of the fourth student chosen?', '[]', '9', '9', 'Go through the list in order. 31 is too big, so skip it. 17 is kept (first). 45 is too big. 08 is kept (second). 17 has already been chosen, so skip it. 30 is kept (third). 09 is kept (fourth). The fourth student is number 09, which is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Student may type 09; the key should accept 9 and 09 as the same number.","work":"31 skip; 17 first; 45 skip; 08 second; 17 repeat skip; 30 third; 09 fourth. Stop.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54e57bce-151b-4fe7-942b-c4809b6bf39e', 'NC26.7.RD.2', 3, 'choice', 'Recognize a statistical question', 'Which question can be answered by collecting data that will vary from student to student?', '["Which sport did Lena play with her cousins at the park last Saturday?","How many players are allowed on the field for one soccer team at a time?","What is the name of the ball that is used in a basketball game?","Which sport do seventh graders at our school like best: soccer or golf?"]', 'Which sport do seventh graders at our school like best: soccer or golf?', NULL, 'Different seventh graders may name different sports, so we must ask many students and the answers vary. A statistical question can have a category as its answer. The other questions have one answer each.', 'checked', '{"lint":[],"solve":{"answer":"Which sport do seventh graders at our school like best: soccer or golf?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Seventh graders'' favorite of soccer/golf varies student to student. The others have a single answer (ball name, Lena''s one sport, a fixed rule).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab47aeea-16a1-4a34-84a6-279f99a1d46c', 'NC26.7.RD.2', 3, 'choice', 'Write or choose a question that compares two groups', 'Mr. Reed wants to know whether students who eat breakfast do better on spelling quizzes than students who do not. Which data should he collect from each student?', '["Only the score that the student earned on the spelling quiz","Only whether or not the student eats breakfast in the morning","The student''s favorite breakfast food and favorite school subject","Whether the student eats breakfast, and the student''s quiz score"]', 'Whether the student eats breakfast, and the student''s quiz score', NULL, 'He needs to sort the students into two groups (breakfast or no breakfast) and also to have a score for each student. Scores alone cannot be split into groups, and groups alone give nothing to compare.', 'checked', '{"lint":[],"solve":{"answer":"Whether the student eats breakfast, and the student''s quiz score","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To compare groups he needs the group (breakfast or not) and the outcome (quiz score) for each student.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8c57aea-5982-4863-afa9-645ddaabc47a', 'NC26.7.RD.2', 3, 'choice', 'Write or choose a question that compares two groups', 'Which statistical question can be answered by collecting measurements from two groups?', '["Is the typical 100-meter time shorter for seventh graders than sixth graders?","Are the seventh graders at our school more athletic than the sixth graders are?","Who is the fastest seventh grader at our school this school year?","Do the sixth graders at our school enjoy running in gym class?"]', 'Is the typical 100-meter time shorter for seventh graders than sixth graders?', NULL, 'The first question names a measurement (time to run 100 meters), two groups and a comparison of typical values. "More athletic" is not measured, the fastest student is one person, and the last question is about only one group.', 'checked', '{"lint":[],"solve":{"answer":"Is the typical 100-meter time shorter for seventh graders than sixth graders?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100-meter times are measurements from two groups. ''Fastest'' has one answer; ''more athletic'' is not a measurement; enjoyment is one group.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c409ae43-3fa0-4ba5-9b7a-5af31117ca5a', 'NC26.7.RD.2', 3, 'numeric', 'Population and sample', 'A city has 12,000 residents. A survey is sent to a random sample of 150 residents. What percent of the residents are in the sample?', '[]', '1.25', '150/12000*100', 'The sample is $\frac{150}{12000}$ of the population. $150 \div 12000 = 0.0125$, which is $1.25$ percent.', 'checked', '{"lint":[],"solve":{"answer":"1.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/12000 = 0.0125 = 1.25%.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fc587cb-c8bf-41c1-9893-290be8522a39', 'NC26.7.RD.2', 3, 'choice', 'Spot and explain bias in a sample', 'A researcher wants to estimate how many hours per week students at a school exercise. She surveys students at the school gym on a Saturday morning. Which change would most reduce bias?', '["Choose students at random from a list of all the students","Survey many more students who are at the gym on Saturdays","Survey the students at the gym on both Saturday and Sunday","Survey only the students who are on a school sports team"]', 'Choose students at random from a list of all the students', NULL, 'The bias comes from where the students are found: people at the gym probably exercise more than other students. A random choice from the list of all students gives each student the same chance. Surveying more people from the gym keeps the same bias.', 'checked', '{"lint":[],"solve":{"answer":"Choose students at random from a list of all the students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gym-goers exercise more. Random selection from the full list removes the selection bias; more gym-goers or sports-team students keep it.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8d38b5b-0f77-4c79-b7d2-9f4e505936ea', 'NC26.7.RD.2', 3, 'choice', 'Spot and explain bias in a sample', 'Two surveys estimate how many hours per week the students at a middle school spend on sports. Survey A asks 100 students picked at random from a list of all students. Survey B asks 400 students who stay for the after-school sports clubs. Which statement is true?', '["Survey B is probably better, because it asks more students than Survey A.","Survey A is probably better, because it is random even though it is smaller.","The two surveys are equally good, because they ask about the same topic.","Survey A is probably biased, because it asks fewer students than Survey B."]', 'Survey A is probably better, because it is random even though it is smaller.', NULL, 'Students in the sports clubs probably spend more time on sports than other students, so Survey B is biased, however many students it includes. Survey A gives every student the same chance of being chosen. A bigger sample does not fix bias.', 'checked', '{"lint":[],"solve":{"answer":"Survey A is probably better, because it is random even though it is smaller.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B surveys only sports-club students: biased toward more sports regardless of size. A is random, so better.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afd4d70c-e7c8-4db9-a345-078c0a181ca0', 'NC26.7.RD.2', 3, 'choice', 'Spot and explain bias in a sample', 'A researcher chooses 50 students at random for a survey, but 30 of them do not return it. She uses only the 20 surveys that were returned. What problem might this cause?', '["There is no problem, because the first 50 students were chosen at random.","The survey now has too many questions for the 20 students who answered.","The results are correct as long as all 20 students are in the same grade.","The 20 who returned it may not be like the 30 who did not, so it may be biased."]', 'The 20 who returned it may not be like the 30 who did not, so it may be biased.', NULL, 'Students who answer a survey can differ from students who do not. Using only the returned surveys can leave out a kind of student, even though the first 50 were random, so the results may be biased.', 'checked', '{"lint":[],"solve":{"answer":"The 20 who returned it may not be like the 30 who did not, so it may be biased.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nonresponse bias: those who returned it may differ from those who did not.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e0c3f04-1a69-4e79-ba4e-6b00c56baaf8', 'NC26.7.RD.2', 3, 'choice', 'Choose a random sampling method', 'A middle school has 200 students in grade 6, 150 in grade 7 and 150 in grade 8. The student council wants a random sample of 50 students in which each grade is represented in proportion to its size. Which plan does this?', '["Choose 16 students at random from grade 6, 17 from grade 7 and 17 from grade 8","Choose 20 students at random from grade 6, 15 from grade 7 and 15 from grade 8","Choose all 50 students at random from the students who are in grade 7","Choose the first 50 students that you see in the lunch line"]', 'Choose 20 students at random from grade 6, 15 from grade 7 and 15 from grade 8', NULL, 'Grade 6 has $\frac{200}{500} = 40\%$ of the students, so it should give 40% of 50 = 20 students. Grades 7 and 8 each have 30%, which is 15 students. The other plans are not in proportion or are not random.', 'checked', '{"lint":[],"solve":{"answer":"Choose 20 students at random from grade 6, 15 from grade 7 and 15 from grade 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 500. Shares: 200/500 = 40% -> 20; 150/500 = 30% -> 15; 15. Sum 50.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d6f31ce-fb57-4077-a648-912de056fe8c', 'NC26.7.RD.2', 3, 'numeric', 'Choose a random sampling method', 'A school has 400 students in grade 6, 300 in grade 7 and 300 in grade 8. A random sample of 60 students is to be chosen so that each grade is represented in proportion to its size. How many students should be chosen from grade 7?', '[]', '18', '60*300/1000', 'Grade 7 has 300 of the 1,000 students, which is $\frac{300}{1000} = 30\%$. So 30% of 60 is $0.3 \times 60 = 18$ students.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 1000. Grade 7 share 300/1000 = 0.3; 0.3 x 60 = 18.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdda0bc8-0933-4747-9dc3-8f7d10fbbb96', 'NC26.7.RD.2', 3, 'choice', 'Why a random sample represents a population, and how samples vary', 'Dev takes many random samples of 10 candies from a huge bowl, and Mia takes many random samples of 100 candies from the same bowl. Each records the fraction of sour candies. Whose fractions will most likely be closer to each other?', '["Mia''s, because larger random samples vary less from sample to sample.","Dev''s, because smaller random samples vary less from sample to sample.","They are equally close, because all of the samples are random.","Neither, because the fractions will be exactly the same each time."]', 'Mia''s, because larger random samples vary less from sample to sample.', NULL, 'A small random sample can easily have a very different share of sour candies by chance. A larger random sample tends to stay closer to the true share, so Mia''s fractions are closer together.', 'checked', '{"lint":[],"solve":{"answer":"Mia''s, because larger random samples vary less from sample to sample.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples have less sampling variability, so Mia''s fractions cluster more closely.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f21e6016-fe64-4439-a0bd-4b37fbe68650', 'NC26.7.RD.2', 3, 'choice', 'Why a random sample represents a population, and how samples vary', 'Mia wants to estimate the fraction of 2,000 students who walk to school. She takes a random sample of 80. A friend says that if she doubles the sample to 160, the estimate will be exactly right. Is the friend correct?', '["Yes. A sample of 160 is bigger than 80, so the estimate will be exact.","No. A larger random sample always gives a worse estimate than a small one.","No. A larger random sample is usually better, but it is still not exact.","Yes. The number 160 is a multiple of 80, so it works out exactly."]', 'No. A larger random sample is usually better, but it is still not exact.', NULL, 'A larger random sample tends to be closer to the true fraction, but it is still only a sample. Only asking all 2,000 students would give the exact fraction.', 'checked', '{"lint":[],"solve":{"answer":"No. A larger random sample is usually better, but it is still not exact.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A larger sample tends to be closer but is still an estimate, never guaranteed exact.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d94f7f5-c46b-4c86-991e-fc8716a27e58', 'NC26.7.RD.2', 3, 'choice', 'Why a random sample represents a population, and how samples vary', 'Which statement about random samples is correct?', '["A random sample always has exactly the same percents as the population does.","A sample can, by chance, differ from the population in the share of a group.","A random sample can never include members from a large group in the population.","A random sample is always biased, even when chance picks the members."]', 'A sample can, by chance, differ from the population in the share of a group.', NULL, 'Because chance picks the members, a sample can have somewhat more or fewer members of a group than the population has. That is why estimates from samples are approximate.', 'checked', '{"lint":[],"solve":{"answer":"A sample can, by chance, differ from the population in the share of a group.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"By chance a random sample can differ from the population in a group''s share; the other statements are false.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a716c7de-8442-4cb7-a9db-1111eea82dc4', 'NC26.7.RD.2', 3, 'numeric', 'Estimate a population count or percent from a random sample', 'In a random sample of 120 students from a district, 45 say they prefer online homework and the rest prefer paper homework. The district has 8,400 students. About how many more students in the district prefer paper homework than prefer online homework?', '[]', '2100', '(120-45)/120*8400-45/120*8400', 'Online: $\frac{45}{120} \times 8400 = 3150$ students. Paper: $\frac{75}{120} \times 8400 = 5250$ students. The difference is $5250 - 3150 = 2100$.', 'checked', '{"lint":[],"solve":{"answer":"2100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Online 45/120 = 0.375 -> 3150. Paper 75/120 = 0.625 -> 5250. Difference 2100 (= 30/120 x 8400).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ac84cb4-06e4-4000-87e0-50912917b58d', 'NC26.7.RD.2', 3, 'numeric', 'Estimate a population count or percent from a random sample', 'A biologist catches 50 fish from a pond, tags them and puts them back. Later she catches a random sample of 40 fish and finds that 5 of them are tagged. About how many fish are in the pond?', '[]', '400', '50*40/5', '$\frac{5}{40}$ of the sample are tagged, so about $\frac{1}{8}$ of all the fish in the pond are tagged. The 50 tagged fish are $\frac{1}{8}$ of the pond, so the pond has about $50 \times 8 = 400$ fish.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tagged share in sample 5/40 = 1/8 estimates 50/N. N = 50 x 8 = 400.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e360fcff-e34a-44f8-9585-bb402ca43926', 'NC26.7.RD.2', 3, 'numeric', 'Estimate a population count or percent from a random sample', 'A manager checks a random sample of 45 of the 1,800 packages in a warehouse and finds 3 that are damaged. Each damaged package costs 12 dollars to replace. About how many dollars would it cost to replace all the damaged packages in the warehouse?', '[]', '1440', '3/45*1800*12', '$\frac{3}{45} = \frac{1}{15}$ of the packages are damaged. $1800 \div 15 = 120$ damaged packages. At 12 dollars each, that is $120 \times 12 = 1440$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1440","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/45 = 1/15 damaged; 1800/15 = 120 damaged; 120 x 12 = 1440 dollars.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5105fe2-46ab-4a99-b2b3-f050beb399d7', 'NC26.7.RD.2', 3, 'numeric', 'Estimate a population mean or median from a sample', 'A random sample of 25 seventh graders from a school of 400 seventh graders has a mean of 40 minutes of homework per night. Estimate the total number of minutes of homework done by all 400 seventh graders in one night.', '[]', '16000', '40*400', 'Estimate that the mean for the whole school is also 40 minutes. For 400 students, the total is about $40 \times 400 = 16{,}000$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"16000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimated mean 40 min per student x 400 students = 16000 minutes.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0608a313-5390-498a-93f0-ecdc43d0c829', 'NC26.7.RD.2', 3, 'numeric', 'Simulate a sample with random numbers or a device', 'Eli numbers the 24 students in his class from 01 to 24. To choose a random sample of 3 students, he reads random two-digit numbers: 47, 12, 88, 05, 12, 31, 19, 22. He skips any number that is not from 01 to 24 and any number he has already chosen. What is the sum of the numbers of the three students chosen?', '[]', '36', '12+5+19', '47 is too big, so skip it. 12 is chosen. 88 is too big. 05 is chosen. 12 is a repeat, so skip it. 31 is too big. 19 is chosen, which makes three students. The sum is $12 + 5 + 19 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 skip; 12 chosen; 88 skip; 05 chosen; 12 repeat skip; 31 skip; 19 chosen (3 found). Sum 12 + 5 + 19 = 36.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af0c79ce-84cc-4efe-9b2d-046c4c5a3320', 'NC26.7.RD.2', 3, 'numeric', 'Simulate a sample with random numbers or a device', 'A basketball player makes 40% of her shots. In a simulation, the digits 0 through 3 mean "make" and the digits 4 through 9 mean "miss". One trial is 5 simulated shots. Five trials gave these digits. Trial 1: 6, 2, 9, 8, 7. Trial 2: 1, 7, 3, 4, 5. Trial 3: 0, 3, 8, 9, 6. Trial 4: 5, 9, 7, 4, 8. Trial 5: 2, 0, 1, 3, 9. In how many of the 5 trials did the player make at least 2 shots?', '[]', '3', '3', 'Count the makes (digits 0 to 3) in each trial: Trial 1 has 1 (the 2). Trial 2 has 2 (1 and 3). Trial 3 has 2 (0 and 3). Trial 4 has 0. Trial 5 has 4 (2, 0, 1, 3). Trials 2, 3 and 5 have at least 2 makes, so the answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Makes are 0-3. T1: 2 only -> 1. T2: 1, 3 -> 2. T3: 0, 3 -> 2. T4: none -> 0. T5: 2, 0, 1, 3 -> 4. At least 2: T2, T3, T5 = 3.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee582f0c-e5ac-4668-96db-8e2862c2cbb3', 'NC26.7.RD.2', 3, 'choice', 'Simulate a sample with random numbers or a device', 'Mia guesses on all 10 questions of a true-or-false quiz. She wants to estimate the chance of getting at least 8 right by guessing. She will use a fair coin, with heads meaning a right answer. Which plan is best?', '["Flip the coin 10 times one time and check whether there are at least 8 heads in all","Flip the coin until 8 heads in a row appear, then count the number of flips","Flip the coin 8 times for one quiz and count how many heads there are","Flip 10 times for one quiz, repeat many times, and count quizzes with at least 8 heads"]', 'Flip 10 times for one quiz, repeat many times, and count quizzes with at least 8 heads', NULL, 'One simulated quiz is 10 flips. A single quiz is not enough to estimate a chance, so she should repeat it many times and see how often at least 8 heads come up.', 'checked', '{"lint":[],"solve":{"answer":"Flip 10 times for one quiz, repeat many times, and count quizzes with at least 8 heads","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One trial = 10 flips (one quiz); repeat many trials and find the share with at least 8 heads.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfd88bf8-2ced-4e88-9297-7f92b572e029', 'NC26.7.RD.2', 3, 'numeric', 'Organize and count data from two groups', 'Group A and Group B each recorded the shoe sizes of 8 students. Group A: 6, 7, 7, 8, 6, 7, 9, 7. Group B: 7, 8, 8, 6, 9, 8, 7, 8. What fraction of all 16 students wear size 7 or smaller? Write your answer as a fraction.', '[]', '9/16', '9/16', 'In Group A, six sizes are 7 or smaller (6, 7, 7, 6, 7, 7). In Group B, three are (7, 6, 7). That is $6 + 3 = 9$ students out of 16, so the fraction is $\frac{9}{16}$.', 'checked', '{"lint":[],"solve":{"answer":"9/16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6,7,7,8,6,7,9,7 -> size 7 or less: 6 students. B: 7,8,8,6,9,8,7,8 -> 3 students. 9/16.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('443728e3-3c09-4706-b978-428e5a3f8f9c', 'NC26.7.RD.2', 3, 'numeric', 'Organize and count data from two groups', 'A school asked 120 sixth graders and 90 seventh graders whether they like a new schedule. 75 percent of the sixth graders and 60 percent of the seventh graders said yes. How many students said yes in all?', '[]', '144', '120*75/100+90*60/100', 'Sixth graders: $0.75 \times 120 = 90$ said yes. Seventh graders: $0.60 \times 90 = 54$ said yes. In all, $90 + 54 = 144$ students said yes.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.75 x 120 = 90; 0.60 x 90 = 54; total 144.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e428b397-00a3-44ca-a34b-2b7137c6d06b', 'NC26.7.RD.2', 3, 'numeric', 'Compare two groups with fractions, means, medians or ranges', 'A sample of 9 seventh graders has a mean of 14 minutes of daily reading. A sample of 6 sixth graders has a mean of 11 minutes of daily reading. What is the mean of all 15 students together, in minutes?', '[]', '12.8', '(9*14+6*11)/15', 'Total minutes for the seventh graders: $9 \times 14 = 126$. For the sixth graders: $6 \times 11 = 66$. All 15 students: $126 + 66 = 192$ minutes. The mean is $192 \div 15 = 12.8$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"12.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 14 = 126; 6 x 11 = 66; total 192; 192/15 = 12.8.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('481d2806-e6af-4767-871a-e60f25f94391', 'NC26.7.RD.2', 3, 'numeric', 'Compare two groups with fractions, means, medians or ranges', 'Group A heights in inches: 52, 55, 49, 58, 56. Group B heights in inches: 50, 61, 47, 59, 53. How many inches greater is the range of Group B than the range of Group A?', '[]', '5', '(61-47)-(58-49)', 'Group A range: $58 - 49 = 9$. Group B range: $61 - 47 = 14$. Group B''s range is $14 - 9 = 5$ inches greater.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A = 58 - 49 = 9. Range B = 61 - 47 = 14. Difference 5.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbcb9dc6-4f16-427c-af9c-4016824312e1', 'NC26.7.RD.2', 3, 'choice', 'Compare two groups with fractions, means, medians or ranges', 'A random sample from class A has a mean quiz score of 85, and a random sample from class B has a mean of 80. Sam says class A did better. What extra information would best help decide whether the 5-point difference is meaningful?', '["How spread out the scores are in each sample","The first names of the students in each sample","The time of day when each class took the quiz","The color of the paper that the quiz was printed on"]', 'How spread out the scores are in each sample', NULL, 'If the scores in each group are spread out a lot, a 5-point difference between the means may be small by comparison. If they are tightly grouped, 5 points may be a clear difference. So knowing the variation is useful.', 'checked', '{"lint":[],"solve":{"answer":"How spread out the scores are in each sample","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whether a difference of means is meaningful depends on the variability (spread) within each sample.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba074eb2-04c2-4d51-b684-0022fb1b3bc1', 'NC26.7.RD.2', 3, 'numeric', 'Combine several random samples', 'Three random samples are taken from the same population. In the first, 8 of 20 people prefer tea. In the second, 14 of 30 prefer tea. In the third, 18 of 50 prefer tea. Using all three samples together, what fraction of the population would you estimate prefer tea? Write your answer as a fraction.', '[]', '2/5', '(8+14+18)/(20+30+50)', 'Together, $8 + 14 + 18 = 40$ people prefer tea out of $20 + 30 + 50 = 100$ people. The fraction is $\frac{40}{100} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8 + 14 + 18)/(20 + 30 + 50) = 40/100 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d393887-82eb-4158-a266-eed76fd31659', 'NC26.7.RD.2', 3, 'numeric', 'Combine several random samples', 'A town has 2,500 voters. Two random samples of voters were asked about a new library. In the first sample, 30 of 60 voters said yes. In the second sample, 54 of 90 voters said yes. Using both samples together, about how many of the town''s voters would say yes?', '[]', '1400', '(30+54)/(60+90)*2500', 'Together, $30 + 54 = 84$ voters said yes out of $60 + 90 = 150$. That is $\frac{84}{150} = 0.56$. Then $0.56 \times 2500 = 1400$ voters.', 'checked', '{"lint":[],"solve":{"answer":"1400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined (30 + 54)/(60 + 90) = 84/150 = 0.56. 0.56 x 2500 = 1400.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e79e75d4-a5b1-4b12-a83e-962b43e1ab31', 'NC26.7.RD.2', 3, 'choice', 'Judge a conclusion drawn from a sample', 'A random sample of 100 people shows that 52 prefer plan A. Another random sample of 100 shows that 46 prefer plan A. Maya says that more than half of all the people prefer plan A. Which response is best?', '["She is right, because the first sample has 52, which is more than half.","Both samples are close to half and differ, so we cannot be sure about plan A.","She is wrong, because the second sample has 46, which is less than half.","At least one of the samples must be wrong, because the two samples differ."]', 'Both samples are close to half and differ, so we cannot be sure about plan A.', NULL, 'The two samples give 52% and 46%, which are both close to half and not the same. Random samples vary, so these results cannot show that more than half prefer plan A, or that fewer than half do.', 'checked', '{"lint":[],"solve":{"answer":"Both samples are close to half and differ, so we cannot be sure about plan A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52% and 46% straddle 50% (combined 49%); sampling variability means we cannot be sure whether more than half prefer A.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e289560-1d50-427e-80b5-61de46723ac9', 'NC26.7.RD.2', 3, 'choice', 'Judge a conclusion drawn from a sample', 'The mean amount of sleep in a random sample of 30 eighth graders is 7.5 hours a night. A student writes: "All seventh graders sleep about 7.5 hours a night." What is wrong with this conclusion?', '["The number 7.5 is not a whole number, so it cannot be used to describe sleep.","A sample of 30 students is too large for the mean to be useful.","The sample was of eighth graders, so it says little about seventh graders.","A mean can never be used to describe the students in any group."]', 'The sample was of eighth graders, so it says little about seventh graders.', NULL, 'A sample can describe the population it was taken from. These are eighth graders, so the result may not hold for seventh graders, who may sleep differently.', 'checked', '{"lint":[],"solve":{"answer":"The sample was of eighth graders, so it says little about seventh graders.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is from eighth graders, a different population; it does not support a claim about seventh graders.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('256333dc-6317-4aa1-8cb8-2842fbad3d0b', 'NC26.7.RD.2', 3, 'choice', 'Word a survey question fairly', 'Survey 1 asks, "Do you want a pool at our school?" and 60 percent say yes. Survey 2 asks, "Nearby schools all have beautiful pools, and ours has none. Do you want a pool at our school?" and 90 percent say yes. What is the best explanation for the difference?', '["The wording of Survey 2 leads people toward answering yes.","Survey 2 asked many more people than Survey 1 did.","Survey 1 is biased because its wording is shorter.","Percents from two different surveys can never be compared."]', 'The wording of Survey 2 leads people toward answering yes.', NULL, 'Survey 2 adds sentences that make not having a pool sound bad, which nudges people to say yes. The wording, not the people''s real opinion, may explain the higher percent.', 'checked', '{"lint":[],"solve":{"answer":"The wording of Survey 2 leads people toward answering yes.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Survey 2''s preamble is leading wording that pushes toward yes.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4897954f-aa7d-4110-a535-c3804db0a0fc', 'NC26.7.RD.2', 3, 'numeric', 'Simulating samples', 'Students simulate choosing 20 students at random by reading random digits from 0 to 9. The digits 0, 1 and 2 stand for "walks to school", and every other digit stands for "does not walk". The 20 digits are 3, 8, 1, 0, 9, 4, 2, 7, 6, 5, 0, 2, 8, 3, 9, 1, 4, 6, 7, 2. What percent of the 20 simulated students walk to school?', '[]', '35', '7/20*100', 'Count the digits that are 0, 1 or 2: 1, 0, 2, 0, 2, 1, 2, which is 7 digits. So 7 of the 20 simulated students walk, and $\frac{7}{20} = \frac{35}{100}$, which is 35%.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 0,1,2 in the list: 1,0,2,0,2,1,2 = 7 of 20. 7/20 = 35%.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f20f125b-8913-4f35-a57e-fff48d21b6a3', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centres of two data sets', 'Data set A has the values 2, 3, 3, 4, 5. Data set B has the values 6, 7, 7, 8, 9. How much greater is the median of B than the median of A?', '[]', '4', '7-3', 'The values are already in order. The middle value of A is 3. The middle value of B is 7. The difference is $7 - 3 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median A = 3, median B = 7; 7 - 3 = 4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79ee8411-d6fa-4f41-bb67-c52c75071c77', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two data sets', 'Data set P has the values 10, 12, 14, 16, 18. Data set Q has the values 4, 10, 14, 18, 24. Both have a median of 14. Which statement about their spread is correct?', '["Q is more spread out, since its values go from 4 to 24","P is more spread out, since its values go from 10 to 18","They have the same spread, since the medians are equal","They have the same spread, since both have 5 values"]', 'Q is more spread out, since its values go from 4 to 24', NULL, 'The range of P is $18 - 10 = 8$ and the range of Q is $24 - 4 = 20$. Q''s values are farther apart, so Q is more spread out. Having the same center or the same number of values does not make the spread equal.', 'checked', '{"lint":[],"solve":{"answer":"Q is more spread out, since its values go from 4 to 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 8, range Q = 20; Q more spread out.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a5f6e01-25de-4aef-9413-ca23d773ce90', 'NC26.7.RD.3', 1, 'choice', 'Recognize an outlier in a distribution', 'Most of the values in a data set are between 20 and 30, but one value is 75. What do we call the value 75?', '["The median","The mode","An outlier","The mean"]', 'An outlier', NULL, 'A value that is far away from the rest of the data is called an outlier. The value 75 is much larger than the values between 20 and 30.', 'checked', '{"lint":[],"solve":{"answer":"An outlier","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A value far from the rest is an outlier.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1341ba47-d7f9-4c5f-9b6c-cdf0b8a6b635', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centers of two distributions', 'Ravi practiced piano for 15, 20, 25, 30, 35 minutes on five days. Lena practiced for 25, 30, 35, 40, 45 minutes on five days. How many minutes greater is Lena''s mean practice time than Ravi''s?', '[]', '10', '(25+30+35+40+45)/5-(15+20+25+30+35)/5', 'Ravi''s mean is (15 + 20 + 25 + 30 + 35) / 5 = 125 / 5 = 25 minutes. Lena''s mean is (25 + 30 + 35 + 40 + 45) / 5 = 175 / 5 = 35 minutes. The difference is 35 - 25 = 10 minutes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ravi: 15+20+25+30+35=125, mean 25. Lena: 25+30+35+40+45=175, mean 35. 35-25=10.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86d79e66-b142-40f8-bbf2-3cfa558fa928', 'NC26.7.RD.3', 1, 'choice', 'Compare the centers of two distributions', 'The median jump distance for a group of boys is 140 centimeters. The median jump distance for a group of girls is 152 centimeters. Which statement is correct?', '["The girls'' distances are spread out 12 centimeters more than the boys'' distances.","Every girl jumped 12 centimeters farther than every boy.","The center of the girls'' distances is 12 centimeters greater than the center of the boys'' distances.","The center of the boys'' distances is 12 centimeters greater than the center of the girls'' distances."]', 'The center of the girls'' distances is 12 centimeters greater than the center of the boys'' distances.', NULL, 'A median is a measure of center. 152 - 140 = 12, so the girls'' center is 12 centimeters greater. Medians say nothing about spread, and they do not mean that every girl jumped farther than every boy.', 'checked', '{"lint":[],"solve":{"answer":"The center of the girls'' distances is 12 centimeters greater than the center of the boys'' distances.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians are measures of center: 152-140=12, girls'' center greater. Spread not given; ''every girl'' not supported; boys'' option reversed.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c66b9c5-1c28-462d-89a6-e766ff7dace6', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centers of two distributions', 'A dot plot of last week''s daily high temperatures has a median of 61 degrees. This week''s dot plot has exactly the same shape, but every temperature is 7 degrees higher. What is the median of this week''s temperatures?', '[]', '68', '61+7', 'Moving every value up by 7 moves the center up by 7 as well, and nothing else changes. The new median is 61 + 7 = 68 degrees.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shifting every value by +7 shifts the median by 7: 61+7=68.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('653b7e21-2de9-46e5-9bd4-e06a4b4dbaee', 'NC26.7.RD.3', 1, 'choice', 'Compare the centers of two distributions', 'Set 1 is 3, 5, 8, 9, 10. Set 2 is 2, 6, 7, 7, 12. Which statement about the medians is correct?', '["Set 1''s median is 1 greater than Set 2''s median.","Set 2''s median is 2 greater than Set 1''s median.","Set 2''s median is 3 greater than Set 1''s median.","The two medians are equal."]', 'Set 1''s median is 1 greater than Set 2''s median.', NULL, 'Both lists are already in order. The middle value of Set 1 is 8 and the middle value of Set 2 is 7, so Set 1''s median is 1 greater. (Comparing the greatest values gives 2, and comparing the ranges gives 3, but neither is a median.)', 'checked', '{"lint":[],"solve":{"answer":"Set 1''s median is 1 greater than Set 2''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 1 sorted 3,5,8,9,10 median 8. Set 2 sorted 2,6,7,7,12 median 7. 8-7=1, Set 1 greater by 1.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f957b71-ecca-4d3f-8359-8d2eaec95d6b', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two distributions', 'A dot plot of Class A''s quiz scores has dots only at 7, 8 and 9. A dot plot of Class B''s quiz scores has dots from 3 all the way to 10. Which statement is correct?', '["Class A''s scores are more spread out than Class B''s scores.","The scores of the two classes are equally spread out.","Class B''s scores are more spread out than Class A''s scores.","The spread cannot be compared unless the two means are known."]', 'Class B''s scores are more spread out than Class A''s scores.', NULL, 'Class A''s dots cover only 9 - 7 = 2 units, while Class B''s dots cover 10 - 3 = 7 units. The wider the dots stretch, the greater the spread, and this can be seen without knowing the means.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s scores are more spread out than Class A''s scores.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class A spans 7-9 (range 2); Class B spans 3-10 (range 7). B more spread out. Spread does not need means.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bec72865-e054-48cd-b3d6-2b506605d5f0', 'NC26.7.RD.3', 1, 'numeric', 'Compare the spread of two distributions', 'On one number line, the dots of Plot A go from 12 to 20, and the dots of Plot B go from 5 to 30. How much greater is the range of Plot B than the range of Plot A?', '[]', '17', '(30-5)-(20-12)', 'The range of A is 20 - 12 = 8. The range of B is 30 - 5 = 25. The difference is 25 - 8 = 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A 20-12=8; range B 30-5=25; 25-8=17.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a516800d-e782-47c3-8f20-50754cf7b487', 'NC26.7.RD.3', 1, 'numeric', 'Compare the spread of two distributions', 'Monday''s temperatures, in degrees, at five times of the day were 55, 58, 61, 66, 70. Tuesday''s were 52, 57, 60, 64, 65. How much greater is Monday''s range than Tuesday''s range?', '[]', '2', '(70-55)-(65-52)', 'Monday''s range is 70 - 55 = 15 degrees. Tuesday''s range is 65 - 52 = 13 degrees. The difference is 15 - 13 = 2 degrees.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Monday 70-55=15; Tuesday 65-52=13; 15-13=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77b14d26-871f-4995-87b9-6e6fae449195', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two distributions', 'Which of these describes a data set with a small spread?', '["The values are all large numbers.","The values are all close together.","The values are listed in order from least to greatest.","The data set has only a few values."]', 'The values are all close together.', NULL, 'Spread tells how far apart the values are. A small spread means the values are close together. Having large values, being in order, or having few values says nothing about spread.', 'checked', '{"lint":[],"solve":{"answer":"The values are all close together.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Small spread means values are close together.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('784636a7-f680-4710-a2cf-510a7c542cab', 'NC26.7.RD.3', 1, 'choice', 'Describe the shape of a distribution', 'A dot plot has 1 dot at 1, 2 dots at 2, 4 dots at 3, 2 dots at 4 and 1 dot at 5. Which describes its shape?', '["Skewed to the right, with its peak at 1","Symmetric, with its peak at 3","Flat, with the same number of dots at each value","Symmetric, with its peak at 4"]', 'Symmetric, with its peak at 3', NULL, 'The counts 1, 2, 4, 2, 1 go up to the tallest stack at 3 and then come back down in the same way, so the shape is symmetric about 3, where the peak is.', 'checked', '{"lint":[],"solve":{"answer":"Symmetric, with its peak at 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 1,2,4,2,1 mirror around 3 with tallest at 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acaf3a10-0e6b-4135-8405-70499370a4c5', 'NC26.7.RD.3', 1, 'choice', 'Describe the shape of a distribution', 'A dot plot has 3 dots at 2, 4 dots at 3, no dots at 4 or 5, 5 dots at 6 and 3 dots at 7. Which statement describes it?', '["There is one cluster, with an outlier at 7.","The shape is flat, with no gaps.","There is a gap between 2 and 3.","There are two clusters, with a gap between 3 and 6."]', 'There are two clusters, with a gap between 3 and 6.', NULL, 'The dots at 2 and 3 form one cluster and the dots at 6 and 7 form another. Nothing is at 4 or 5, so there is a gap between 3 and 6.', 'checked', '{"lint":[],"solve":{"answer":"There are two clusters, with a gap between 3 and 6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dots at 2,3 and at 6,7 with none at 4,5: two clusters separated by a gap between 3 and 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54d7973a-93cb-45ef-b1c0-637f7a287754', 'NC26.7.RD.3', 1, 'numeric', 'Describe the shape of a distribution', 'A dot plot of the number of brothers and sisters students have shows 4 dots at 0, 9 dots at 1, 6 dots at 2, 3 dots at 3 and 1 dot at 4. At which number is the peak, the tallest stack of dots?', '[]', '1', '1', 'The stacks have 4, 9, 6, 3 and 1 dots. The tallest stack, with 9 dots, is at 1, so the peak is at 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Stacks 4,9,6,3,1; tallest (9) at 1.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
