INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f946218a-aecf-4eb8-84c2-ae42385a38fa', 'NC26.7.RD.3', 1, 'choice', 'Plot two distributions on one number line', 'Set A is 3, 5, 8, 9. Set B is 6, 10, 12, 14. You want to show both sets as dot plots on one number line. Which number line can show every value?', '["From 0 to 10, with a mark at every whole number","From 3 to 9, with a mark at every whole number","From 0 to 15, with a mark at every whole number","From 6 to 14, with a mark at every whole number"]', 'From 0 to 15, with a mark at every whole number', NULL, 'The values run from 3 to 14. Only a number line from 0 to 15 includes both 3 and 14. From 0 to 10 and from 3 to 9 leave out 12 and 14, and from 6 to 14 leaves out 3 and 5.', 'checked', '{"lint":[],"solve":{"answer":"From 0 to 15, with a mark at every whole number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All values from 3 to 14; only 0 to 15 contains them all.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
