INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('904cb2b7-5f47-45bb-8e12-a32066ce590d', 'NC26.7.RD.3', 1, 'numeric', 'Plot two distributions on one number line', 'Plot A has dots at 4, 5, 5 and 7. Plot B has dots at 5, 6, 7, 7 and 7. Both plots are drawn on one number line. How many dots are at 7 in all?', '[]', '4', '1+3', 'Plot A has 1 dot at 7 and Plot B has 3 dots at 7. In all there are 1 + 3 = 4 dots at 7.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A has one 7, B has three 7s: 4.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
