INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0700ab9d-6219-44b9-8656-f4b9c0079160', 'NC26.7.RD.3', 1, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of seconds students took to run a lap. The row for stem 3 has leaves 0, 2, 5. The row for stem 4 has leaves 1, 1, 7, 9. The row for stem 5 has leaves 2, 6. How many students are shown?', '[]', '9', '3+4+2', 'Each leaf is one student. Stem 3 has 3 leaves, stem 4 has 4 leaves and stem 5 has 2 leaves, so 3 + 4 + 2 = 9 students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leaves 3+4+2=9.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e44b8943-5e06-4b69-bf46-7ba22032134e', 'NC26.7.RD.3', 1, 'numeric', 'Read a stem-and-leaf plot', 'In a stem-and-leaf plot of ages, stem 1 has leaves 1, 4, 4, 6; stem 2 has leaves 0, 3, 4, 4, 4, 9; and stem 3 has leaves 2, 5. A stem of 2 and a leaf of 4 means 24. Which age appears most often?', '[]', '24', '24', 'The leaf 4 appears three times on stem 2, so 24 appears 3 times. 14 appears twice and every other age appears once. The most common age is 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ages 11,14,14,16,20,23,24,24,24,29,32,35. 24 appears 3 times, most.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca867a8a-0a37-4339-8371-8e8a433bb994', 'NC26.7.RD.3', 1, 'choice', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot of lengths has the key 3 | 1 means 3.1 meters. One row is: 3 | 1 2 8. Which list shows the lengths in that row?', '["3.1, 3.2, 3.8","31, 32, 38","3.1, 2.8","0.31, 0.32, 0.38"]', '3.1, 3.2, 3.8', NULL, 'The stem is the ones digit and each leaf is the tenths digit. The row 3 | 1 2 8 stands for 3.1, 3.2 and 3.8 meters.', 'checked', '{"lint":[],"solve":{"answer":"3.1, 3.2, 3.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Key 3|1 = 3.1, so 3|1 2 8 = 3.1, 3.2, 3.8.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
