INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96889d62-d4c3-4bf7-bd62-3527dbbeff43', 'NC26.7.RD.3', 1, 'numeric', 'Read a histogram or grouped frequency table', 'A histogram shows how many books students read last year. The bars are 0 to 4 books: 5 students; 5 to 9 books: 12 students; 10 to 14 books: 8 students; 15 to 19 books: 3 students. How many students are shown?', '[]', '28', '5+12+8+3', 'Add the heights of the bars: 5 + 12 + 8 + 3 = 28 students.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+12+8+3=28.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
