INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0ea7c65-5598-40d7-a3a3-730b48b7abeb', 'NC26.7.RD.3', 1, 'choice', 'Read a histogram or grouped frequency table', 'A histogram shows the daily high temperatures over 30 days. The bars are 50 to 59 degrees: 4 days; 60 to 69 degrees: 9 days; 70 to 79 degrees: 12 days; 80 to 89 degrees: 5 days. Which interval has the most days?', '["60 to 69 degrees","80 to 89 degrees","50 to 59 degrees","70 to 79 degrees"]', '70 to 79 degrees', NULL, 'The tallest bar belongs to the interval with the greatest count. The counts are 4, 9, 12 and 5, so the interval with 12 days, 70 to 79 degrees, is the tallest.', 'checked', '{"lint":[],"solve":{"answer":"70 to 79 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 4,9,12,5; most is 12 at 70-79.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
