INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b7517f1-ff67-4f7f-b89b-98e31c5be05a', 'NC26.7.RD.3', 1, 'numeric', 'Read a box plot from its five-number summary', 'A box plot of the minutes students took to get to school has a minimum of 5, a first quartile of 12, a median of 18, a third quartile of 27 and a maximum of 41. What is the interquartile range, the length of the box?', '[]', '15', '27-12', 'The interquartile range is the third quartile minus the first quartile: 27 - 12 = 15 minutes.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27-12=15.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
