INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('591d51b3-2834-4b86-a8b5-f16ef96813af', 'NC26.7.RD.3', 2, 'choice', 'Compare the spread of two distributions', 'Set M has a range of 30 and an interquartile range of 8. Set N has a range of 22 and an interquartile range of 12. Which statement is correct?', '["Set M is more spread out by both measures, because its range is greater.","Set N is more spread out by both measures, because its IQR is greater.","The two sets are equally spread out, because their ranges and IQRs are close.","The middle half of the values is more spread out in Set N, though Set M has the greater range."]', 'The middle half of the values is more spread out in Set N, though Set M has the greater range.', NULL, 'Set M has the greater range (30 > 22), but Set N has the greater IQR (12 > 8). So the whole data set is more stretched out in M, while the middle half of the values is more spread out in N. Neither set is greater by both measures.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of the values is more spread out in Set N, though Set M has the greater range.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR (middle half spread): N 12 > M 8. Range: M 30 > N 22. So measures disagree.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa35108-282c-4483-8bc3-19d29bba6c6e', 'NC26.7.RD.3', 2, 'choice', 'Describe the shape of a distribution', 'A dot plot shows how many books 14 students read last month: 5 dots at 1, 4 dots at 2, 3 dots at 3, 1 dot at 7 and 1 dot at 9. Which describes the shape?', '["Most values are low, with a tail stretching toward the high values.","Most values are high, with a tail stretching toward the low values.","The values are balanced evenly on both sides of the center.","The values form two clusters of equal size."]', 'Most values are low, with a tail stretching toward the high values.', NULL, 'The tallest stacks are at the low values 1, 2 and 3, and a few dots trail off toward 7 and 9. A tail toward the high values is called skewed to the right.', 'checked', '{"lint":[],"solve":{"answer":"Most values are low, with a tail stretching toward the high values.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Most dots at 1-3, a few far out at 7 and 9: right tail toward high values.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('caf49b84-5695-415d-b96f-239e11baaf74', 'NC26.7.RD.3', 2, 'numeric', 'Describe the shape of a distribution', 'A dot plot of 18 values has 2 dots at 10, 3 dots at 11, 4 dots at 12, 3 dots at 13, 5 dots at 20 and 1 dot at 21. There is a gap between 13 and 20 that splits the dots into two clusters. How many dots are in the lower cluster?', '[]', '12', '2+3+4+3', 'The lower cluster is the dots from 10 to 13: 2 + 3 + 4 + 3 = 12 dots. (The upper cluster has 5 + 1 = 6 dots, and 12 + 6 = 18.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower cluster 10-13: 2+3+4+3=12 (total check 12+5+1=18).","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c49f497-fcd8-4ad4-8766-17d5d6dcf744', 'NC26.7.RD.3', 2, 'choice', 'Describe the shape of a distribution', 'A dot plot has the values 1, 2, 3, 4 and 5 on its number line. Each choice gives the number of dots at 1, 2, 3, 4 and 5, in that order. Which choice gives a symmetric shape?', '["5, 4, 3, 2, 1","1, 2, 3, 4, 5","1, 3, 5, 3, 1","2, 5, 1, 4, 3"]', '1, 3, 5, 3, 1', NULL, 'A symmetric shape matches on the two sides of its center. 1, 3, 5, 3, 1 reads the same forward and backward. 5, 4, 3, 2, 1 and 1, 2, 3, 4, 5 slope one way, and 2, 5, 1, 4, 3 has no matching sides.', 'checked', '{"lint":[],"solve":{"answer":"1, 3, 5, 3, 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,3,5,3,1 reads the same both ways about 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7ddf78b-8f88-4aaf-b051-2e5363ac97bc', 'NC26.7.RD.3', 2, 'choice', 'Describe the shape of a distribution', 'A dot plot has 3 dots at each of the values 1, 2, 3, 4, 5 and 6. Which describes its shape?', '["Skewed to the left, with a tail toward 1.","Flat: every value has the same number of dots, and there is no single peak.","One cluster with an outlier at 6.","A peak in the middle, with fewer dots at each end."]', 'Flat: every value has the same number of dots, and there is no single peak.', NULL, 'Every value from 1 to 6 has exactly 3 dots, so no stack is taller than another. The shape is flat (uniform), with no peak, no gap and no outlier.', 'checked', '{"lint":[],"solve":{"answer":"Flat: every value has the same number of dots, and there is no single peak.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal counts everywhere: flat/uniform, no peak.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c140b73-999c-48ab-89be-e3d54a36b412', 'NC26.7.RD.3', 2, 'choice', 'Judge the overlap of two distributions', 'Set A is 22, 24, 25, 27, 28. Set B is 26, 28, 29, 30, 32. Which statement is correct?', '["The sets do not overlap at all.","The sets overlap a little, and Set B''s values are generally greater.","The sets overlap a little, and Set A''s values are generally greater.","The sets overlap almost completely, and Set A''s values are generally greater."]', 'The sets overlap a little, and Set B''s values are generally greater.', NULL, 'Set A goes up to 28 and Set B starts at 26, so the sets share the values from 26 to 28: a small overlap. Set B''s median, 29, is greater than Set A''s median, 25, so B''s values are generally greater.', 'checked', '{"lint":[],"solve":{"answer":"The sets overlap a little, and Set B''s values are generally greater.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 22-28 (median 25), B 26-32 (median 29). Overlap only 26-28; B generally greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66684e2b-0a88-4279-b870-28b427df7367', 'NC26.7.RD.3', 2, 'numeric', 'Judge the overlap of two distributions', 'Without extra water, six sunflowers had heights, in centimeters, of 11, 12, 14, 15, 17, 18. With extra water, six sunflowers had heights of 15, 17, 19, 20, 22, 24. How many of the heights with extra water are inside the interval from the least to the greatest height without extra water?', '[]', '2', '2', 'Without extra water the heights run from 11 to 18. Of the heights with extra water, only 15 and 17 are between 11 and 18 (19 and above are too tall). So 2 of them are inside.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Without water: 11 to 18. With water values in [11,18]: 15, 17. Count 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abe60706-b708-4a04-89b5-a004da2a2287', 'NC26.7.RD.3', 2, 'choice', 'Judge the overlap of two distributions', 'Set A''s values run from 30 to 70 with a median of 50. Set B''s values run from 34 to 74 with a median of 54. Which statement is correct?', '["The sets overlap a lot, so the 4-point difference in medians is small compared with the spread.","Set B is clearly higher, because its median is greater.","The sets do not overlap, because their medians are different.","The sets overlap only a little, because the medians are not equal."]', 'The sets overlap a lot, so the 4-point difference in medians is small compared with the spread.', NULL, 'Both sets stretch across about 40 units, and they share all the values from 34 to 70. A 4-point difference between medians is small next to that spread, so the sets overlap a lot even though the medians are different.', 'checked', '{"lint":[],"solve":{"answer":"The sets overlap a lot, so the 4-point difference in medians is small compared with the spread.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges 30-70 and 34-74 overlap 34-70 (most of both). Median gap 4 vs range 40: small difference.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3164b8fa-a4fc-4ced-808d-7b7d8c38e499', 'NC26.7.RD.3', 2, 'choice', 'Plot two distributions on one number line', 'Why should two dot plots that are being compared be drawn on the same number line, with the same scale?', '["So both plots will have the same number of dots.","So both plots will have the same mean.","So both plots will have the same range.","So the positions of the dots can be compared directly."]', 'So the positions of the dots can be compared directly.', NULL, 'Only when both plots use the same scale does a dot that is farther right mean a greater value in either plot. The number of dots, the mean and the range depend on the data, not on how the line is drawn.', 'checked', '{"lint":[],"solve":{"answer":"So the positions of the dots can be compared directly.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same scale lets dot positions be compared directly; it does not change means, ranges or counts.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78ff1744-92a9-4a6a-9515-ac1bc5d8510f', 'NC26.7.RD.3', 2, 'choice', 'Plot two distributions on one number line', 'Group A''s heights run from 140 to 185 centimeters. Group B''s heights run from 152 to 190 centimeters. Which is the best number line for drawing both dot plots?', '["From 0 to 200, with a mark every 50 centimeters","From 150 to 200, with a mark every 10 centimeters","From 140 to 190, with a mark every 5 centimeters","From 140 to 185, with a mark every 5 centimeters"]', 'From 140 to 190, with a mark every 5 centimeters', NULL, 'The line must reach from the least value, 140, to the greatest value, 190, and marks every 5 centimeters make it easy to place the dots. From 0 to 200 with marks every 50 is too coarse, and the other two lines cut off the heights from 140 to 149 or the heights above 185.', 'checked', '{"lint":[],"solve":{"answer":"From 140 to 190, with a mark every 5 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 140 to 190. 150-200 misses 140-149; 140-185 misses 186-190; 0-200 by 50s too coarse. Best: 140-190 by 5s.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dfc0738-67fb-4f86-82ee-e11edeb0b6a5', 'NC26.7.RD.3', 2, 'numeric', 'Plot two distributions on one number line', 'Plot A has dots at 2, 4, 4, 6. Plot B has dots at 3, 4, 5, 5, 9. The two plots are drawn together on one number line, so there are 9 dots in all. What is the median of the 9 values?', '[]', '4', '4', 'Put all 9 values in order: 2, 3, 4, 4, 4, 5, 5, 6, 9. The middle (5th) value is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined sorted 2,3,4,4,4,5,5,6,9; median 5th value = 4.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
