INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76a8f804-814a-430e-8b07-98666a5e8338', 'NC26.7.RD.3', 3, 'numeric', 'Plot two distributions on one number line', 'Class 1''s 5 scores have a mean of 8. Class 2''s 3 scores have a mean of 12. When all 8 scores are put on one number line, what is the mean of all of them?', '[]', '9.5', '(5*8+3*12)/8', 'Class 1 adds to 5 x 8 = 40 and Class 2 adds to 3 x 12 = 36. All 8 scores add to 76, so the mean is 76 / 8 = 9.5. (It is not 10, the mean of 8 and 12, because Class 1 has more scores.)', 'checked', '{"lint":[],"solve":{"answer":"9.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total (5*8)+(3*12)=40+36=76; 76/8=9.5.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ae016ff-a04f-4d33-b8c8-0ede74fc0ea7', 'NC26.7.RD.3', 3, 'choice', 'Plot two distributions on one number line', 'Set A has values from 0.2 to 1.4. Set B has values from 0.5 to 2.6. Which number line, with the marks shown, can display every value from both sets?', '["From 0.2 to 1.4, with a mark every 0.2","From 0 to 3, with a mark every 0.5","From 0 to 2, with a mark every 0.5","From 0.5 to 2.6, with a mark every 0.5"]', 'From 0 to 3, with a mark every 0.5', NULL, 'The values run from 0.2 up to 2.6. A number line from 0 to 3 covers all of them. The line ending at 1.4 and the line ending at 2 cut off the greater values of Set B, and the line starting at 0.5 cuts off 0.2.', 'checked', '{"lint":[],"solve":{"answer":"From 0 to 3, with a mark every 0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 0.2 to 2.6. 0.2-1.4 and 0-2 miss 2.6; 0.5-2.6 misses 0.2. 0 to 3 covers all.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b5f9f5b-3b01-4265-9b14-61f5825d60e2', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the masses of 11 rocks in kilograms. The key is 1 | 8 means 1.8 kilograms. Stem 1 has leaves 2, 5, 8, 8. Stem 2 has leaves 0, 1, 4, 4, 7. Stem 3 has leaves 3, 6. What is the median mass in kilograms?', '[]', '2.1', '21/10', 'The 11 masses in order are 1.2, 1.5, 1.8, 1.8, 2.0, 2.1, 2.4, 2.4, 2.7, 3.3, 3.6. The middle value is the 6th, which is 2.1 kilograms.', 'checked', '{"lint":[],"solve":{"answer":"2.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2,1.5,1.8,1.8,2.0,2.1,2.4,2.4,2.7,3.3,3.6 (11). Median 6th = 2.1.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4927b7b1-0473-43a1-91b0-153c71beb3d5', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of cups of juice a shop sold each day. The key is 12 | 3 means 123. Stem 12 has leaves 3, 8. Stem 13 has leaves 0, 4, 4, 9. Stem 14 has leaves 2, 5, 6. Stem 15 has leaf 1. What is the range of the sales?', '[]', '28', '151-123', 'The least value is 123 (stem 12, leaf 3) and the greatest is 151 (stem 15, leaf 1). The range is 151 - 123 = 28 cups.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Least 123, greatest 151; 151-123=28.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
