INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0815b226-e008-4721-a586-ec4fef019561', 'NC26.7.RD.3', 3, 'choice', 'Read a stem-and-leaf plot', 'Two teams'' points in nine games are shown in a back-to-back stem-and-leaf plot. Team X: stem 3 has leaves 2, 6, 8; stem 4 has leaves 0, 1, 5, 5, 7; stem 5 has leaf 2. Team Y: stem 3 has leaf 1; stem 4 has leaves 4, 6; stem 5 has leaves 0, 3, 5, 7, 8, 9. A stem of 3 and a leaf of 2 means 32. Which statement is true?', '["Team X''s median is 12 greater than Team Y''s median.","Team Y''s median is 12 greater than Team X''s median.","Team X has the greater range of the two teams.","Both teams have the same median."]', 'Team Y''s median is 12 greater than Team X''s median.', NULL, 'Team X''s scores in order: 32, 36, 38, 40, 41, 45, 45, 47, 52, so the median is 41 and the range is 20. Team Y''s: 31, 44, 46, 50, 53, 55, 57, 58, 59, so the median is 53 and the range is 28. Y''s median is 53 - 41 = 12 greater, and Y has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Team Y''s median is 12 greater than Team X''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 32,36,38,40,41,45,45,47,52, median 41, range 20. Y: 31,44,46,50,53,55,57,58,59, median 53, range 28. Y median 12 greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef5a8816-1ed8-4e9f-a4de-f21237054c27', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows six ages. Stem 2 has leaves 1, 4. Stem 3 has leaves 0, 5, 8. Stem 4 has leaf 4. A stem of 2 and a leaf of 1 means 21. What is the mean age?', '[]', '32', '(21+24+30+35+38+44)/6', 'The ages are 21, 24, 30, 35, 38 and 44. They add to 192, and 192 / 6 = 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21+24+30+35+38+44=192; 192/6=32.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
