INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dbeb479-a7d2-459a-ac55-16b89cfddaea', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'A dot plot of the heights of 20 people at a youth center shows one cluster of dots from 50 to 56 inches and a second cluster from 66 to 72 inches, with no dots between 57 and 65 inches. Which is the most reasonable conclusion?', '["The data must contain mistakes, because heights should form one cluster.","The people probably come from two groups, such as children and adults, with different typical heights.","Most of the people are about 61 inches tall, the middle of the plot.","The people are all about the same height, because the dots are close together."]', 'The people probably come from two groups, such as children and adults, with different typical heights.', NULL, 'Two separate clusters with a gap between them suggest two different groups mixed together. Nobody is about 61 inches tall, since there are no dots there, and the dots are not all close together.', 'checked', '{"lint":[],"solve":{"answer":"The people probably come from two groups, such as children and adults, with different typical heights.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two separated clusters suggest two groups (e.g. children and adults) with different typical heights.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca0be6f7-979d-4439-84a8-291cbf3b6b49', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'Set 1 is 10, 20, 20, 20, 20, 30. Set 2 is 10, 10, 10, 30, 30, 30. Maia says, "Both sets have a range of 20 and a mean of 20, so they are spread out in the same way." Which reply is correct?', '["She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.","She is right: sets with the same range and mean must be spread out in the same way.","She is not right: Set 1 has the greater range.","She is not right: the two sets have different means."]', 'She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.', NULL, 'Both sets have a range of 20 and a mean of 20. But four of Set 1''s six values equal 20, while every value of Set 2 is 10 away from 20. Set 2''s values are typically much farther from the mean, so Set 2 is more spread out.', 'checked', '{"lint":[],"solve":{"answer":"She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 1 sum 120, mean 20, range 20; Set 2 sum 120, mean 20, range 20. Set 1 mostly at 20; Set 2 every value 10 from 20. Distributions differ.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15d980f6-c67a-4c5f-8107-f65a86e63874', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'Box plot X has a minimum of 30, a first quartile of 52, a median of 60, a third quartile of 70 and a maximum of 80. Box plot Y has a minimum of 20, a first quartile of 35, a median of 50, a third quartile of 55 and a maximum of 65. Which statement is true?', '["Every value in Plot X is greater than Plot Y''s median.","Plot Y''s median is greater than Plot X''s first quartile.","Half of Plot Y''s values are greater than Plot X''s median.","At least three quarters of Plot X''s values are greater than Plot Y''s median."]', 'At least three quarters of Plot X''s values are greater than Plot Y''s median.', NULL, 'Plot Y''s median is 50 and Plot X''s first quartile is 52, so at least three quarters of X''s values are above 50. But X''s minimum is 30, so not every value is. 50 is less than 52, so Plot Y''s median is not greater than Plot X''s first quartile. Y''s third quartile is 55, below X''s median of 60, so fewer than a quarter of Y''s values are above 60.', 'checked', '{"lint":[],"solve":{"answer":"At least three quarters of Plot X''s values are greater than Plot Y''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Y median 50. X Q1=52>50, so at least 75% of X values >50. Others: Y Q3 55 < X median 60 (false); 50<52 (false); X min 30<50 (false).","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b30f388-6b93-430b-8029-3a3cb382e94a', 'NC26.7.RD.3', 3, 'numeric', 'Compare two distributions on one number line', 'Dot plots of two classes'' quiz scores share one number line. Class X has scores 52, 55, 58, 60, 63 and 70, and its median is 59. Class Y has scores 48, 61, 62, 66, 71 and 73. How many more of Class Y''s scores than of Class X''s scores are greater than 59?', '[]', '2', '5-3', 'In Class X, the scores greater than 59 are 60, 63 and 70, which is 3 scores. In Class Y, the scores greater than 59 are 61, 62, 66, 71 and 73, which is 5 scores. The difference is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X median (58+60)/2=59 checks. X above 59: 60, 63, 70 = 3. Y above 59: 61, 62, 66, 71, 73 = 5. 5-3=2.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
