INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e27b648-d819-456b-9165-215e6e38c2da', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'A weather station recorded these temperatures in degrees on eight mornings: 52, 55, 50, 58, 49, 56, 53, 51. Find the mean absolute deviation (MAD) of the temperatures.', '[]', '2.5', '(8+16+24+40+32+24+0+16)/64', 'The mean is 424 / 8 = 53. The distances from 53 are 1, 2, 3, 5, 4, 3, 0 and 2, which add to 20. The MAD is 20 / 8 = 2.5 degrees.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 424, mean 53. Distances 1,2,3,5,4,3,0,2 = 20; 20/8 = 2.5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
