INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f53f147-2c17-4486-a65c-204cf3458fac', 'NC26.7.RD.4', 2, 'choice', 'Find the mean absolute deviation', 'The mean absolute deviation of a data set is 0. Which statement must be true?', '["All of the values are 0.","The mean and the median are both 0.","All of the values are equal.","The values are listed in order."]', 'All of the values are equal.', NULL, 'A MAD of 0 means the average distance from the mean is 0, and distances cannot be negative, so every distance is 0. That happens only when every value equals the mean, so all the values are equal (but not necessarily 0).', 'checked', '{"lint":[],"solve":{"answer":"All of the values are equal.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD 0 means every distance from the mean is 0, so all values equal the mean (need not be 0).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cffc428-639d-400b-8762-20b0d809336a', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'Find the mean absolute deviation (MAD) of the quiz scores 5, 9, 10, 12 and 14.', '[]', '2.4', '(25+5+0+10+20)/25', 'The mean is 50 / 5 = 10. The distances from 10 are 5, 1, 0, 2 and 4, which add to 12. The MAD is 12 / 5 = 2.4.', 'checked', '{"lint":[],"solve":{"answer":"2.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 50, mean 10. Distances 5,1,0,2,4 = 12; 12/5 = 2.4.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23b90afc-2276-42a6-b14f-607691661d6f', 'NC26.7.RD.4', 2, 'choice', 'Interpret range, IQR and MAD', 'A set of test scores has a mean of 80 and a mean absolute deviation (MAD) of 2. Which statement is correct?', '["Every score is between 78 and 82.","The range of the scores is 2.","The middle score is 2 points above 80.","The scores are typically about 2 points away from 80."]', 'The scores are typically about 2 points away from 80.', NULL, 'A MAD of 2 means the scores are 2 points from the mean on average. Some scores can be farther away, so not every score has to be between 78 and 82, and the MAD is not the range.', 'checked', '{"lint":[],"solve":{"answer":"The scores are typically about 2 points away from 80.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD 2 means scores are typically about 2 points from 80; it does not bound every score or give the range.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d535e8b3-01a7-4d08-baec-f4da58278c0a', 'NC26.7.RD.4', 2, 'choice', 'Interpret range, IQR and MAD', 'Which of these measures of spread uses every value in the data set?', '["The mean absolute deviation","The range","The interquartile range","The greatest value"]', 'The mean absolute deviation', NULL, 'The MAD finds the distance of every value from the mean. The range uses only the greatest and least values, and the IQR uses only the quartiles. (The greatest value is not a measure of spread.)', 'checked', '{"lint":[],"solve":{"answer":"The mean absolute deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD averages every value''s distance from the mean; range uses only extremes; IQR only quartiles.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0badaef-9169-45d4-b2f7-de71834552fd', 'NC26.7.RD.4', 2, 'numeric', 'Interpret range, IQR and MAD', 'The times of a group of runners have a mean of 40 seconds and a MAD of 5 seconds. One runner took 47 seconds. How many seconds farther from the mean than the average distance is this runner''s time?', '[]', '2', '(47-40)-5', 'This runner is 47 - 40 = 7 seconds from the mean. The average distance is the MAD, 5 seconds. So 7 - 5 = 2 seconds farther than average.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Runner''s distance 47-40=7; average distance (MAD) 5; 7-5=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3f41df5-50cd-42ed-8d8b-4676b562f4a5', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'A data set is 12, 13, 13, 14, 15, 15, 16, 48. Which measure of spread is least affected by the value 48?', '["The range","The interquartile range","The mean absolute deviation","All three are affected equally"]', 'The interquartile range', NULL, 'The range jumps to 36 because of the 48, and the mean (18.25) is pulled up, which raises the MAD. The IQR uses only the middle half of the values: Q1 = 13 and Q3 = 15.5, so IQR = 2.5, and it hardly notices the 48.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q1=(13+13)/2=13, Q3=(15+15)/2=15; IQR does not depend on 48''s size. Range and MAD do.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b975a1b-00e4-4b81-9cc5-57fb862f5ea3', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'A coach wants to know how far, on average, her players'' sprint times are from the team''s mean time. Which measure should she use?', '["The range","The interquartile range","The mean absolute deviation","The median"]', 'The mean absolute deviation', NULL, 'The MAD is, by definition, the average distance of the values from the mean. The range and the IQR describe the spread of the ends and of the middle half, and the median is a measure of center.', 'checked', '{"lint":[],"solve":{"answer":"The mean absolute deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Average distance from the mean = MAD.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dcaf6a8-aefb-4699-a478-c52c361f226f', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'For which situation are the median and the interquartile range the better choice to describe the data?', '["The heights of 25 same-age students, which cluster evenly around the average","The number of minutes a train arrives early or late, which is balanced around zero","The weights of 30 identical bags of rice, which are all very close to the labeled weight","The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70"]', 'The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70', NULL, 'The median and IQR are used when data are skewed or have extreme values. The two grandparents are extreme values that would distort the mean and the MAD. The other three situations are roughly symmetric without extreme values, so the mean and the MAD describe them well.', 'checked', '{"lint":[],"solve":{"answer":"The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Party ages are skewed by two 70-year-olds: median and IQR resist extremes. Others are symmetric.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfbc1292-8b80-43ab-b7ee-a85a26158659', 'NC26.7.RD.4', 2, 'numeric', 'Compare two data sets using center and spread', 'Two machines fill boxes. The weights, in ounces, of five boxes from Machine A are 18, 21, 24, 27, 30, and from Machine B are 22, 23, 24, 25, 26. Both sets have a mean of 24. The MAD of Machine A''s weights is how many times the MAD of Machine B''s weights?', '[]', '3', '((30+15+0+15+30)/25)/((10+5+0+5+10)/25)', 'Machine A: distances from 24 are 6, 3, 0, 3, 6, which add to 18, so MAD = 18 / 5 = 3.6. Machine B: distances are 2, 1, 0, 1, 2, which add to 6, so MAD = 6 / 5 = 1.2. Since 3.6 / 1.2 = 3, A''s MAD is 3 times B''s MAD.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A distances 6,3,0,3,6 = 18, MAD 3.6. B distances 2,1,0,1,2 = 6, MAD 1.2. 3.6/1.2 = 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0718805a-2ee8-48b3-a0bf-866281c60873', 'NC26.7.RD.4', 2, 'choice', 'Compare two data sets using center and spread', 'Class 1''s test scores have a median of 78 and an IQR of 6. Class 2''s test scores have a median of 82 and an IQR of 16. Which statement is correct?', '["Class 2''s scores are typically higher, and they vary less.","Class 1''s scores are typically higher, and they vary more.","Class 1''s scores are typically higher, but they vary less.","Class 2''s scores are typically higher, but they vary more."]', 'Class 2''s scores are typically higher, but they vary more.', NULL, 'The median of Class 2 (82) is greater than that of Class 1 (78), so its scores are typically higher. The IQR of Class 2 (16) is greater than that of Class 1 (6), so its middle half is more spread out: its scores vary more.', 'checked', '{"lint":[],"solve":{"answer":"Class 2''s scores are typically higher, but they vary more.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 median 82 > 78 (typically higher) and IQR 16 > 6 (varies more).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('392d0fba-e741-409b-9a37-d1e54b7d7e26', 'NC26.7.RD.4', 2, 'numeric', 'Compare two data sets using center and spread', 'Tomato plants in Garden A produced 10, 12, 15, 19, 22, 30 tomatoes. Tomato plants in Garden B produced 14, 16, 17, 20, 21, 23 tomatoes. The IQR of Garden A is how many times the IQR of Garden B?', '[]', '2', '((22)-(12))/((21)-(16))', 'Garden A in order: Q1 = 12 and Q3 = 22, so IQR = 10. Garden B in order: Q1 = 16 and Q3 = 21, so IQR = 5. Since 10 / 5 = 2, the IQR of A is 2 times the IQR of B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 10,12,15 | 19,22,30: Q1 12, Q3 22, IQR 10. B: 14,16,17 | 20,21,23: Q1 16, Q3 21, IQR 5. 10/5 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7523f028-5ee2-4f11-b2c1-c224f51c637b', 'NC26.7.RD.4', 2, 'choice', 'Describe the effect of an extreme value', 'The mean of five values is 20. A sixth value, 50, is added. What is the mean of all six values?', '["35","25","30","150"]', '25', '(5*20+50)/6', 'The five values add to 5 x 20 = 100. With 50 the total is 150. The mean of six values is 150 / 6 = 25. The one extreme value raised the mean by 5. (35 is the mean of 20 and 50, which ignores that there are five values at around 20, and 150 is the total.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 5*20=100, +50 = 150; 150/6 = 25.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bbae04b-c016-42ca-b8ff-4ebb811d8f8a', 'NC26.7.RD.4', 2, 'numeric', 'Describe the effect of an extreme value', 'The median of the data 4, 6, 7, 9, 10 is 7. A sixth value, 100, is added. What is the median of the six values?', '[]', '8', '(7+9)/2', 'The six values in order are 4, 6, 7, 9, 10, 100. The median is the mean of the 3rd and 4th values: (7 + 9) / 2 = 8. Even a value as extreme as 100 moved the median by only 1.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,6,7,9,10,100: median (7+9)/2 = 8.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('348a53c7-a31c-4204-8c92-f911d55cacef', 'NC26.7.RD.4', 2, 'choice', 'Describe the effect of an extreme value', 'In the data set 3, 5, 6, 8, 9, 11, 12, 14, the greatest value, 14, is changed to 60. Which statement is true?', '["The range, the mean and the median all increase.","Only the range increases; the mean stays the same.","The mean and the IQR increase, but the range stays the same.","The range and the mean increase, but the median and the IQR stay the same."]', 'The range and the mean increase, but the median and the IQR stay the same.', NULL, 'The range goes from 14 - 3 = 11 to 60 - 3 = 57, and the mean rises from 68 / 8 = 8.5 to 114 / 8 = 14.25. The median (8 + 9) / 2 = 8.5 and the quartiles (5.5 and 11.5) use only the middle values, so the median and the IQR (6) do not change.', 'checked', '{"lint":[],"solve":{"answer":"The range and the mean increase, but the median and the IQR stay the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before: median (8+9)/2=8.5, Q1=(5+6)/2=5.5, Q3=(11+12)/2=11.5. Changing 14 to 60 leaves median, Q1, Q3 unchanged; range and mean increase.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c89641bb-93e8-4c11-94a5-2c2451723254', 'NC26.7.RD.4', 2, 'numeric', 'Find a missing value from a measure', 'The range of five values is 18. Four of the values are 23, 31, 27 and 35, and the fifth value is the least. What is the fifth value?', '[]', '17', '35-18', 'The greatest value is 35. The range is 18, so the least value is 35 - 18 = 17. Check: 17 is less than the other four values, and 35 - 17 = 18.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest of the five is 35 (fifth is least). Least = 35-18 = 17 (below 23, consistent).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee403412-aded-4afb-92c7-e00377eb4487', 'NC26.7.RD.4', 2, 'numeric', 'Find a missing value from a measure', 'A data set has a least value of 8 and a range of 12. A new value is added that is greater than every other value, and the range becomes 20. What is the new value?', '[]', '28', '8+20', 'The new value is the new greatest value, and the least value is still 8. The range is 20, so the new value is 8 + 20 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old greatest 8+12=20. New value is new greatest: 8+20 = 28.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ba08298-4cb6-4bf4-bb44-e8cfc34514e9', 'NC26.7.RD.4', 2, 'numeric', 'Find a measure from a frequency table or dot plot', 'A frequency table shows the number of points scored in eight games: 3 points 2 times, 5 points 1 time, 7 points 2 times, 9 points 1 time and 11 points 2 times. What is the interquartile range of the scores?', '[]', '6', '((9+11)/2)-((3+5)/2)', 'List all 8 scores in order: 3, 3, 5, 7, 7, 9, 11, 11. The lower half 3, 3, 5, 7 has median (3 + 5) / 2 = 4 (Q1). The upper half 7, 9, 11, 11 has median (9 + 11) / 2 = 10 (Q3). The IQR is 10 - 4 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 3,3,5,7 | 7,9,11,11: Q1 (3+5)/2=4, Q3 (9+11)/2=10, IQR 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63bca8f0-17a9-40f6-abe0-1970216ced79', 'NC26.7.RD.4', 2, 'choice', 'Find a measure from a frequency table or dot plot', 'A dot plot has 1 dot at 1, 2 dots at 3, 4 dots at 5, 2 dots at 7 and 1 dot at 9. The mean of the 10 values is 5. What is the mean absolute deviation (MAD)?', '["2.4","1.6","3.2","16"]', '1.6', '(40+20+20+0+0+0+0+20+20+40)/100', 'The distances from 5 are: 4 (one dot), 2 (two dots at 3), 0 (four dots), 2 (two dots at 7) and 4 (one dot). They add to 4 + 2 x 2 + 0 + 2 x 2 + 4 = 16. The MAD is 16 / 10 = 1.6. (2.4 ignores how many dots are at each value, 3.2 divides the 16 by 5 instead of 10, and 16 is the total before dividing.)', 'checked', '{"lint":[],"solve":{"answer":"1.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances: 1*4 + 2*2 + 4*0 + 2*2 + 1*4 = 16; 16/10 = 1.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4bca99d-30cd-4c18-91c7-f081809b36c9', 'NC26.7.RD.4', 2, 'choice', 'Find a measure from a frequency table or dot plot', 'Plot P has 3 dots at each of 4, 6 and 8. Plot Q has 2 dots at 4, 5 dots at 6 and 2 dots at 8. Both plots have a mean of 6 and a range of 4. Which plot has the greater MAD?', '["Plot P, because more of its dots are far from the mean.","Plot Q, because it has the tallest stack of dots.","Neither: they have the same MAD, because the mean and the range are the same.","Plot Q, because it has more dots at the mean."]', 'Plot P, because more of its dots are far from the mean.', NULL, 'Plot P: the distances from 6 are 2 (three dots), 0 (three dots) and 2 (three dots), which add to 12, so MAD = 12 / 9 = 4/3. Plot Q: 2 (two dots), 0 (five dots) and 2 (two dots) add to 8, so MAD = 8 / 9. P has the greater MAD. Equal means and ranges do not make equal MADs.', 'checked', '{"lint":[],"solve":{"answer":"Plot P, because more of its dots are far from the mean.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 3*2 + 0 + 3*2 = 12, MAD 12/9 ~ 1.33. Q: 2*2 + 0 + 2*2 = 8, MAD 8/9 ~ 0.89. P greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e6d444-ec08-4608-97cf-aef1f039dc9b', 'NC26.7.RD.4', 3, 'choice', 'Effect of an extreme value', 'The value 30 is added to the data set 4, 5, 6, 7, 8. Which statement is true?', '["The median increases a lot, but the range changes only a little","Neither the range nor the median changes","The range increases a lot, but the median changes only a little","The range and the median increase by the same amount"]', 'The range increases a lot, but the median changes only a little', NULL, 'Before: the range is $8 - 4 = 4$ and the median is 6. After adding 30 the data are 4, 5, 6, 7, 8, 30. The range is $30 - 4 = 26$, an increase of 22. The median is $(6 + 7) \div 2 = 6.5$, an increase of only 0.5.', 'checked', '{"lint":[],"solve":{"answer":"The range increases a lot, but the median changes only a little","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before: range 4, median 6. After: 4, 5, 6, 7, 8, 30: range 26, median 6.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b00d53e-1c8d-4729-9b5e-5de29c8146be', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using MAD', 'Set A is 6, 8, 10, 12, 14. Set B is 2, 6, 10, 14, 18. Both sets have a mean of 10. The MAD of Set B is how many times the MAD of Set A?', '[]', '2', '((8+4+0+4+8)/5)/((4+2+0+2+4)/5)', 'Set A: the distances from 10 are 4, 2, 0, 2, 4. Their mean is $12 \div 5 = 2.4$. Set B: the distances from 10 are 8, 4, 0, 4, 8. Their mean is $24 \div 5 = 4.8$. Since $4.8 \div 2.4 = 2$, the MAD of B is 2 times the MAD of A.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: distances 4, 2, 0, 2, 4; MAD 12/5 = 2.4. B: 8, 4, 0, 4, 8; MAD 24/5 = 4.8. Ratio 2.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0baf79a5-681b-49ef-8d0f-9740724297c7', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using IQR', 'Set X is 3, 5, 6, 8, 9, 12, 14, 17. Set Y is 10, 11, 12, 13, 14, 15, 16, 17. How much greater is the interquartile range of Set X than the interquartile range of Set Y?', '[]', '3.5', '((12+14)/2-(5+6)/2)-((15+16)/2-(11+12)/2)', 'Set X: the lower half is 3, 5, 6, 8 with first quartile $(5 + 6) \div 2 = 5.5$. The upper half is 9, 12, 14, 17 with third quartile $(12 + 14) \div 2 = 13$. IQR = $13 - 5.5 = 7.5$. Set Y: the lower half is 10, 11, 12, 13 with first quartile 11.5. The upper half is 14, 15, 16, 17 with third quartile 15.5. IQR = $15.5 - 11.5 = 4$. The difference is $7.5 - 4 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: lower 3, 5, 6, 8 -> Q1 5.5; upper 9, 12, 14, 17 -> Q3 13; IQR 7.5. Y: lower 10-13 -> 11.5; upper 14-17 -> 15.5; IQR 4. Difference 3.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d91afd68-b639-4c69-bee6-7498d41ff098', 'NC26.7.RD.4', 3, 'numeric', 'Find the range of a data set', 'Set A has a range of 14 and a least value of 6. Set B has a least value of 10 and a greatest value of 31. All the values of both sets are put together. What is the range of the combined values?', '[]', '25', '31-6', 'The greatest value of Set A is 6 + 14 = 20, which is less than 31. So the combined greatest value is 31 and the combined least value is 6. The range is 31 - 6 = 25.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: least 6, greatest 6+14=20. B: 10 to 31. Combined 6 to 31: 25.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('211945f3-db14-4744-b1c7-5ade31f3b8fb', 'NC26.7.RD.4', 3, 'numeric', 'Find the range of a data set', 'Six values have a range of 9, and their least value is 11. A seventh value, 23, is added. What is the range of the seven values?', '[]', '12', '23-11', 'The greatest of the six values is 11 + 9 = 20. The new value, 23, is greater than 20, so it is the new greatest value. The range is 23 - 11 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Six values run 11 to 20. Adding 23: 23-11=12.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e97fb085-52e5-469f-bb61-bcc84e6a4ea9', 'NC26.7.RD.4', 3, 'numeric', 'Find the interquartile range', 'Ten students finished a puzzle in the following numbers of seconds: 45, 38, 52, 41, 60, 47, 55, 36, 49, 58. What is the interquartile range of the times?', '[]', '14', '(55)-(41)', 'In order: 36, 38, 41, 45, 47, 49, 52, 55, 58, 60. The lower half 36, 38, 41, 45, 47 has median 41 (Q1). The upper half 49, 52, 55, 58, 60 has median 55 (Q3). The IQR is 55 - 41 = 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 36,38,41,45,47 | 49,52,55,58,60: Q1=41, Q3=55, IQR 14.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9ccf8c-988d-4dd7-ae51-a8dfc115c090', 'NC26.7.RD.4', 3, 'choice', 'Find the interquartile range', 'The interquartile range of a data set is 12 and its range is 30. The IQR is what fraction of the range?', '["5/2","2/5","3/5","2/7"]', '2/5', NULL, 'The fraction is IQR / range = 12 / 30, which simplifies to 2/5. (5/2 turns it upside down, 3/5 is (30 - 12) / 30, and 2/7 is 12 / (30 + 12).)', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/30 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6141298-0589-43d7-9fcc-846555754f2c', 'NC26.7.RD.4', 3, 'choice', 'Find the interquartile range', 'Data Set A has an interquartile range of 10. Data Set B has an interquartile range of 6. Which statement must be true?', '["The middle half of the values covers a wider interval in Set A than in Set B.","Set A has the greater range.","Set A has the greater median.","Set A has more values than Set B."]', 'The middle half of the values covers a wider interval in Set A than in Set B.', NULL, 'The IQR is the length of the interval holding the middle half of the values, so Set A''s middle half is wider. Nothing is known about the extremes (range), the median, or how many values there are.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of the values covers a wider interval in Set A than in Set B.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR is the width of the interval holding the middle half; 10 > 6. Median, count and range not determined.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
