INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09d10498-2ba1-416f-ae7b-1583d4dfec44', 'NC26.7.RD.5', 2, 'choice', 'Draw a conclusion the data support', 'Maya chose a random sample of 30 sixth graders and a random sample of 30 seventh graders at her school. The sixth graders slept a mean of 9.4 hours a night and the seventh graders slept a mean of 8.6 hours. Which conclusion is best supported?', '["Every seventh grader at the school sleeps less than every sixth grader","Seventh graders at the school probably sleep less than sixth graders on average","All seventh graders in the country sleep exactly 8.6 hours","Growing older makes students need less sleep"]', 'Seventh graders at the school probably sleep less than sixth graders on average', NULL, 'Random samples let us make a careful statement about the whole grades at that school: the seventh graders probably sleep less on average, with some chance variation. The data cannot show that every student differs, cannot describe other schools, and cannot explain why the difference exists.', 'checked', '{"lint":[],"solve":{"answer":"Seventh graders at the school probably sleep less than sixth graders on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random samples of 30 support a tentative inference about the school''s grades; not causation, not the country, not every student.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3abae52c-db48-4eab-b73f-b05d4a339626', 'NC26.7.RD.5', 2, 'choice', 'Communicate a comparison in words', 'Minutes to read a chapter. Boys: 12, 14, 15, 15, 19. Girls: 11, 12, 13, 14, 15. Which sentence is a correct report?', '["The boys'' median is 2 minutes greater, and the girls'' range is 3 minutes greater","The girls'' median is 2 minutes greater, and the boys'' range is 3 minutes greater","The boys'' median is 2 minutes greater, and the boys'' range is 3 minutes greater","The boys'' median is 3 minutes greater, and the boys'' range is 2 minutes greater"]', 'The boys'' median is 2 minutes greater, and the boys'' range is 3 minutes greater', NULL, 'Boys: the median is 15 and the range is 19 - 12 = 7. Girls: the median is 13 and the range is 15 - 11 = 4. The boys'' median is 15 - 13 = 2 greater and the boys'' range is 7 - 4 = 3 greater.', 'checked', '{"lint":[],"solve":{"answer":"The boys'' median is 2 minutes greater, and the boys'' range is 3 minutes greater","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys median 15, range 19-12=7. Girls median 13, range 15-11=4. Boys median 2 greater, boys range 3 greater.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec6ed2a3-03bb-44ab-8e86-055208d37e36', 'NC26.7.RD.5', 2, 'choice', 'Communicate a comparison in words', 'Group A has a mean of 35 and a MAD of 4. Group B has a mean of 35 and a MAD of 11. Which sentence best reports the comparison?', '["Both groups scored 35, so the groups are the same","On average both groups scored 35, but Group B''s scores are more spread out (MAD 11 compared with 4)","Group B scored higher than Group A, because its MAD is higher","Group A scored 35 and Group B scored 11"]', 'On average both groups scored 35, but Group B''s scores are more spread out (MAD 11 compared with 4)', NULL, 'The means are equal, so the typical score is the same. The MADs differ, so the spread is not: Group B''s scores are farther from 35 on average. A good report mentions both.', 'checked', '{"lint":[],"solve":{"answer":"On average both groups scored 35, but Group B''s scores are more spread out (MAD 11 compared with 4)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same mean 35; B''s MAD 11 > 4, so B more spread out.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74049a25-3aa7-409e-865e-f4c7625dcdf0', 'NC26.7.RD.5', 2, 'choice', 'Reflect on sampling and sample size', 'A principal wants to know how many hours students at her school sleep. She asks only the students who arrive before 7 a.m. Why may this give a poor estimate?', '["The sample is too large to give a mean","She should have asked about days, not hours","Students who arrive early all sleep the same number of hours","Early arrivers may sleep differently from other students, so the sample may not be representative"]', 'Early arrivers may sleep differently from other students, so the sample may not be representative', NULL, 'Students who arrive before 7 a.m. are not chosen at random: they may get up earlier and sleep less than most students. A sample that leaves out many students is biased and may not represent the school.', 'checked', '{"lint":[],"solve":{"answer":"Early arrivers may sleep differently from other students, so the sample may not be representative","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Early arrivers are a biased subgroup whose sleep may differ.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86a071ff-c709-420f-ab11-37400822a295', 'NC26.7.RD.5', 2, 'choice', 'Reflect on sampling and sample size', 'One student compared 10 random seventh graders with 10 random eighth graders and found the mean times on homework differed by 1 hour. A second student used 100 random students from each grade and found a difference of 0.2 hour. Which statement is most reasonable?', '["The smaller samples are more reliable, because they are easier to check","Both samples are equally reliable, because both are random","The larger samples probably give a more reliable picture of the difference","Neither result tells us anything about the grades"]', 'The larger samples probably give a more reliable picture of the difference', NULL, 'Random samples of 100 are less affected by chance than random samples of 10, so they usually estimate the true difference more reliably. Both results say something about the grades, but the larger samples say more.', 'checked', '{"lint":[],"solve":{"answer":"The larger samples probably give a more reliable picture of the difference","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples vary less, so the 100-per-grade result is more reliable.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('358f41fe-3862-4fd4-865d-9ed1b848a695', 'NC26.7.RD.5', 2, 'choice', 'Reflect on the question and the method', 'Ana measures the long jumps of one group in centimeters. Ben measures the long jumps of a second group in inches. What should they do before comparing the groups?', '["Compare the numbers as they are, because a larger number always means a longer jump","Use only the greatest value from each group","Write both sets of measurements in the same unit","Use the range for one group and the mean for the other"]', 'Write both sets of measurements in the same unit', NULL, 'Numbers measured in different units cannot be compared directly: 60 inches is longer than 100 centimeters. Both groups must be measured in the same unit, and both must be summarized with the same statistics.', 'checked', '{"lint":[],"solve":{"answer":"Write both sets of measurements in the same unit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Measurements must be in the same unit to compare.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4528982-1039-49e3-b864-50d8f9aa6e8c', 'NC26.7.RD.5', 2, 'choice', 'Reflect on the question and the method', 'A student wants to compare how two groups rate the school lunch. Which survey question is worded most fairly?', '["How would you rate the school lunch from 1 (poor) to 5 (excellent)?","Don''t you think the school lunch is terrible?","Isn''t the school lunch the best part of your day?","Most students hate the lunch, so what score do you give it?"]', 'How would you rate the school lunch from 1 (poor) to 5 (excellent)?', NULL, 'A fair question does not push people toward an answer. The three other questions suggest what the answer should be, which would bias the results.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the school lunch from 1 (poor) to 5 (excellent)?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 1-5 rating question is neutral; the others are leading.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7523a38-a917-49f2-aa5f-5721365bc40a', 'NC26.7.RD.5', 2, 'numeric', 'Use samples to compare two populations', 'A random sample of 40 students at North School found that 12 ride a bike to school. A random sample of 50 students at South School found that 20 ride a bike. North School has 500 students and South School has 600. Based on the samples, about how many more students ride a bike at South School than at North School?', '[]', '90', '(20/50)*600-(12/40)*500', 'North: 12 / 40 = 30 percent, and 30 percent of 500 is 150 students. South: 20 / 50 = 40 percent, and 40 percent of 600 is 240 students. The estimated difference is 240 - 150 = 90 students.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"North: 12/40=0.3, 0.3*500=150. South: 20/50=0.4, 0.4*600=240. 240-150=90.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('302fb59f-891b-4989-8939-f3f8c36ea4b9', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison of two groups', 'Plants in the sun had a median height of 24 cm and an IQR of 4 cm. Plants in the shade had a median height of 15 cm and an IQR of 5 cm. Which statement best summarizes the comparison?', '["Sun plants were typically 9 cm taller, and varied much more than shade plants","Sun plants were typically 9 cm taller, and both groups varied by a similar amount","Shade plants were typically 9 cm taller, and both groups varied by a similar amount","The groups were typically the same height, but shade plants varied more"]', 'Sun plants were typically 9 cm taller, and both groups varied by a similar amount', NULL, 'The medians differ by $24 - 15 = 9$ cm, with the sun plants taller. The IQRs, 4 cm and 5 cm, are close compared with a 9 cm difference, so the spread is similar. Only "Sun plants were typically 9 cm taller, and both groups varied by a similar amount" reports both correctly.', 'checked', '{"lint":[],"solve":{"answer":"Sun plants were typically 9 cm taller, and both groups varied by a similar amount","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sun median 24 vs shade 15: sun 9 cm taller. IQRs 4 and 5: similar spread.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b61172c-72c9-42e0-9e40-a4e62aadb6dd', 'NC26.7.RD.5', 3, 'numeric', 'Difference of means in units of MAD', 'Group A has the values 8, 10 and 12. Group B has the values 12, 14 and 16. The difference between the two means is how many times the mean absolute deviation (MAD) of Group A?', '[]', '3', '(14-10)/((2+0+2)/3)', 'Mean of A is 10 and mean of B is 14, so the difference is 4. The distances of A''s values from 10 are 2, 0 and 2, so the MAD of A is $4 \div 3 = \frac{4}{3}$. Then $4 \div \frac{4}{3} = 3$, so the difference is 3 times the MAD.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means 10 and 14; difference 4. MAD A: distances 2, 0, 2; 4/3. 4 / (4/3) = 3.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efbd67df-b751-42ba-bcb1-99d1025b621a', 'NC26.7.RD.5', 3, 'numeric', 'Compare the means of two groups', 'Group A has 4 students with a mean score of 70 points. Group B has 6 students with a mean score of 80 points. What is the mean score of all 10 students together?', '[]', '76', '(4*70+6*80)/10', 'Group A scored 4 x 70 = 280 points in total and Group B scored 6 x 80 = 480 points. Together that is 760 points for 10 students, so the mean is 760 / 10 = 76 points. (It is not 75, because Group B has more students.)', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*70=280, 6*80=480, total 760, 760/10=76.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af46e886-56b6-4255-a905-4178acb159cb', 'NC26.7.RD.5', 3, 'numeric', 'Compare the medians of two groups', 'Group P has the values 4, 7, 10, 12, 15 and 21. Group Q has seven values in order: 5, 8, 10, $x$, 14, 16 and 20. The two groups have the same median. What is the value of $x$?', '[]', '11', '(10+12)/2', 'Group P has 6 values, so its median is the mean of the 3rd and 4th values: (10 + 12) / 2 = 11. Group Q has 7 values, so its median is the 4th value, which is $x$. For the medians to match, $x$ = 11. (11 fits between 10 and 14, so the list stays in order.)', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P median (6 values) = (10+12)/2 = 11. Q median is the 4th value x, so x=11 (fits 10<=11<=14).","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('289f2582-5f9f-48dc-ab3c-ce258a37f944', 'NC26.7.RD.5', 3, 'numeric', 'Compare the medians of two groups', 'A group has 11 values listed from least to greatest, and the median is 30. At least how many of the 11 values are 30 or greater?', '[]', '6', '(11+1)/2', 'With 11 values in order, the median is the 6th value. So the 6th value is 30, and the 7th through 11th values are at least 30. That makes at least 6 values (the 6th to the 11th) that are 30 or greater.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median of 11 ordered values is the 6th, =30. The 6th through 11th values are all >=30: 6 values guaranteed.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b47a922-29ba-4289-b822-78af51f47275', 'NC26.7.RD.5', 3, 'numeric', 'Compare the ranges of two groups', 'Data set 1 has a least value of 13 and a range of 24. Data set 2 has the same greatest value as data set 1, but its range is only 9. What is the least value of data set 2?', '[]', '28', '13+24-9', 'The greatest value of data set 1 is 13 + 24 = 37. Data set 2 also has a greatest value of 37, and its range is 9, so its least value is 37 - 9 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 1 greatest = 13+24 = 37. Set 2 least = 37-9 = 28.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f999a890-0a8c-4d47-ae6a-023e01093c46', 'NC26.7.RD.5', 3, 'numeric', 'Compare the IQRs of two groups', 'Both lists have 9 values and are in order. Group P: 3, 6, 7, 9, 12, 14, 15, 18, 22. Group Q: 5, 7, 8, 9, 10, 11, 12, 13, 16. To find the quartiles, leave out the median, then take the median of the 4 values below it and of the 4 values above it. By how much does the IQR of Group P exceed the IQR of Group Q?', '[]', '5', '((15+18)/2-(6+7)/2)-((12+13)/2-(7+8)/2)', 'Group P: the median is 12. Lower four values 3, 6, 7, 9 have median 6.5; upper four values 14, 15, 18, 22 have median 16.5; IQR = 16.5 - 6.5 = 10. Group Q: the median is 10. Lower four values 5, 7, 8, 9 have median 7.5; upper four values 11, 12, 13, 16 have median 12.5; IQR = 12.5 - 7.5 = 5. The difference is 10 - 5 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: median 12; lower 3,6,7,9 -> 6.5; upper 14,15,18,22 -> 16.5; IQR 10. Q: median 10; lower 5,7,8,9 -> 7.5; upper 11,12,13,16 -> 12.5; IQR 5. 10-5=5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('642ae2dd-79e1-4dc0-8c53-176ff8ff3818', 'NC26.7.RD.5', 3, 'numeric', 'Compare the IQRs of two groups', 'Group S has an IQR of 18 and a first quartile of 42. Group T has an IQR of 12 and a third quartile of 70. How much greater is the third quartile of Group T than the third quartile of Group S?', '[]', '10', '70-(42+18)', 'The third quartile equals the first quartile plus the IQR. For Group S: 42 + 18 = 60. Group T''s third quartile is 70. The difference is 70 - 60 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S: Q3 = 42+18 = 60. T: Q3 = 70. 70-60=10.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f0e6b27-fcfd-4274-8bf6-6025ddc07a74', 'NC26.7.RD.5', 3, 'numeric', 'Compare the mean absolute deviations of two groups', 'A group has four values and a mean of 20. Three of the values are 14, 18 and 24. What is the MAD of the group?', '[]', '4', '(6+2+4+4)/4', 'The four values add to 4 x 20 = 80. The three known values add to 56, so the fourth value is 80 - 56 = 24. The distances from the mean of 20 are 6, 2, 4 and 4. The MAD is (6 + 2 + 4 + 4) / 4 = 16 / 4 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4*20=80; fourth value 80-14-18-24=24. Deviations 6,2,4,4 = 16; MAD 16/4=4.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd71cfae-5a71-4861-b79b-694b815605aa', 'NC26.7.RD.5', 3, 'choice', 'Compare the mean absolute deviations of two groups', 'Every value in a data set is increased by 5. What happens to the mean and to the MAD of the data set?', '["The mean increases by 5 and the MAD stays the same","The mean and the MAD both increase by 5","The mean stays the same and the MAD increases by 5","The mean and the MAD both stay the same"]', 'The mean increases by 5 and the MAD stays the same', NULL, 'Adding 5 to every value moves the whole data set up by 5, so the mean goes up by 5. But every value is still the same distance from the mean as before, so the MAD does not change. Example: 4, 8, 9, 15 has mean 9 and MAD 3; 9, 13, 14, 20 has mean 14 and MAD 3.', 'checked', '{"lint":[],"solve":{"answer":"The mean increases by 5 and the MAD stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shifting every value by 5 shifts the mean by 5; distances from the mean are unchanged, so MAD unchanged.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e3e2b0b-807d-4820-a8ba-789f35b1defe', 'NC26.7.RD.5', 3, 'choice', 'Describe the centre and spread together', 'Group A has a median of 20 and an IQR of 6. Group B has a median of 24 and an IQR of 14. Which statement is true?', '["Group A has the higher median, but its middle half is more than twice as spread out as Group B''s","Group B has the higher median, but its middle half is more than twice as spread out as Group A''s","Group B has the higher median, and its middle half is less spread out than Group A''s","Group A has the higher median, and its middle half is less spread out than Group B''s"]', 'Group B has the higher median, but its middle half is more than twice as spread out as Group A''s', NULL, 'Group B''s median (24) is higher than Group A''s (20). Group B''s IQR is 14 and Group A''s is 6, so B''s middle half is more spread out; 14 is more than 2 x 6 = 12, so it is more than twice as spread out.', 'checked', '{"lint":[],"solve":{"answer":"Group B has the higher median, but its middle half is more than twice as spread out as Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B median 24 > 20. B IQR 14 > 2*6=12, so more than twice as spread.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9336d545-db80-4e79-a0dc-dda166f20031', 'NC26.7.RD.5', 3, 'choice', 'Describe the centre and spread together', 'Which pair of groups has the same center (median) but different spread (IQR)?', '["Group 1: median 15, IQR 4; Group 2: median 15, IQR 9","Group 1: median 15, IQR 4; Group 2: median 19, IQR 4","Group 1: median 15, IQR 4; Group 2: median 19, IQR 9","Group 1: median 15, IQR 4; Group 2: median 4, IQR 15"]', 'Group 1: median 15, IQR 4; Group 2: median 15, IQR 9', NULL, 'Same median and different IQR is needed. Only the first pair has two medians of 15 with IQRs of 4 and 9. The other pairs have different medians.', 'checked', '{"lint":[],"solve":{"answer":"Group 1: median 15, IQR 4; Group 2: median 15, IQR 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need equal medians, different IQRs: median 15 both, IQR 4 vs 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c87bb22-aa21-4b6c-9ba3-10d6604438cc', 'NC26.7.RD.5', 3, 'numeric', 'Compare a difference in centres with the variability', 'Group A has the values 20, 22, 26 and 28. Group B has a mean of 36 and the same MAD as Group A. The means of the two groups are how many MADs apart?', '[]', '4', '(36-((20+22+26+28)/4))/((4+2+2+4)/4)', 'Group A''s mean is 96 / 4 = 24. Its distances from 24 are 4, 2, 2 and 4, so its MAD is 12 / 4 = 3. Group B has the same MAD, 3. The means are 36 - 24 = 12 apart, which is 12 / 3 = 4 MADs.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 96, mean 24; deviations 4,2,2,4 =12; MAD 3. Means 36-24=12; 12/3=4.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ff58233-33d7-4b30-b961-04beb135d4b2', 'NC26.7.RD.5', 3, 'numeric', 'Compare a difference in centres with the variability', 'Two groups have the same MAD. Their means are 25 and 40, and that is exactly 3 MADs apart. What is the MAD?', '[]', '5', '(40-25)/3', 'The means are 40 - 25 = 15 apart. That equals 3 MADs, so one MAD is 15 / 3 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-25=15 = 3*MAD, MAD=5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f80737c8-e90d-42ec-8671-125a67adc28d', 'NC26.7.RD.5', 3, 'choice', 'Choose the better measure of centre', 'Group A has the values 48, 49, 50, 51, 52. Group B has the values 40, 44, 45, 46, 75. Both groups have a mean of 50. Which statement is true?', '["The mean describes a typical value equally well in both groups, because the means are equal","The median of Group B is greater than the median of Group A","The mean describes a typical value less well in Group B than in Group A","The range of Group B is smaller than the range of Group A"]', 'The mean describes a typical value less well in Group B than in Group A', NULL, 'Group A''s median is 50, matching its mean. Group B''s median is 45, and four of its five values are 46 or less, so the mean of 50 is pulled up by the value 75 and is not typical. Group B has the lower median and the greater range (35 compared with 4).', 'checked', '{"lint":[],"solve":{"answer":"The mean describes a typical value less well in Group B than in Group A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B: sum 250, mean 50, median 45, range 35. A: median 50, range 4. B''s mean 50 is above four of its five values, so it describes B less well. Other options false.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc6619fb-8c44-4fbf-af4c-6547a3d62804', 'NC26.7.RD.5', 3, 'numeric', 'Effect of an outlier on the mean and median', 'A group has the values 12, 14, 15, 16, 18 and 45. By how much does the mean decrease when the value 45 is removed?', '[]', '5', '((12+14+15+16+18+45)/6)-((12+14+15+16+18)/5)', 'With 45: the total is 120 and the mean is 120 / 6 = 20. Without 45: the total is 75 and the mean is 75 / 5 = 15. The mean decreases by 20 - 15 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 120, mean 20. Without 45: 75/5=15. Decrease 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fb85002-d91d-454b-ae5d-f1b959528bb8', 'NC26.7.RD.5', 3, 'choice', 'Effect of an outlier on the mean and median', 'A data set has the values 8, 10, 11, 12, 14, 15, 20. The greatest value, 20, is changed to 50. Which measure does NOT change?', '["The median","The mean","The range","The MAD"]', 'The median', NULL, 'The median is the 4th value, 12, before and after, since the changed value is still the greatest. The mean rises (from 12.9 to about 17.1), the range rises (from 12 to 42), and the MAD also changes because the mean and the greatest distance both change.', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median is the 4th value, 12, unchanged. Mean (90/7 -> 120/7), MAD and range (12 -> 42) all change.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bc3adcb-200f-44ae-b407-f0f43bdd92e7', 'NC26.7.RD.5', 3, 'choice', 'Describe the shape of a distribution', 'Group A has the values 10, 11, 12, 12, 13, 14. Group B has the values 1, 2, 3, 30, 31, 32. Which statement is true?', '["Group A has two clusters with a gap between them","Group B has two clusters with a gap, and its mean and median fall in the gap","Group B has one cluster, and its mean and median lie within it","Group A has the greater range"]', 'Group B has two clusters with a gap, and its mean and median fall in the gap', NULL, 'Group B''s values form two clusters (1 to 3 and 30 to 32) with a large gap between them. Its mean is 99 / 6 = 16.5 and its median is (3 + 30) / 2 = 16.5, and both fall in the gap, where there are no data. Group A forms one tight cluster, and its range (4) is far less than Group B''s (31).', 'checked', '{"lint":[],"solve":{"answer":"Group B has two clusters with a gap, and its mean and median fall in the gap","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: one cluster, range 4. B: clusters 1-3 and 30-32; mean 99/6=16.5, median (3+30)/2=16.5, both in the gap.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47538e50-98ac-4e30-bc14-ac22023c3edd', 'NC26.7.RD.5', 3, 'numeric', 'Describe the shape of a distribution', 'The data 1, 2, 3, 3, 4, 4, 11 are skewed to the right. How much greater is the mean than the median?', '[]', '1', '((1+2+3+3+4+4+11)/7)-3', 'The mean is 28 / 7 = 4. The median (4th value) is 3. The mean is 4 - 3 = 1 greater than the median, as is usual when a few large values pull the mean toward the right.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 28, mean 4. Median = 4th value = 3. 4-3=1.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21591c47-f62f-4978-95db-d9b245d2af84', 'NC26.7.RD.5', 3, 'numeric', 'Compare the share of each group above a cutoff', 'In Group A, 40 students took a test and 45 percent scored above 70. In Group B, 80 students took the test and 30 percent scored above 70. How many more students in Group B than in Group A scored above 70?', '[]', '6', '0.3*80-0.45*40', 'Group A: 45 percent of 40 is 0.45 x 40 = 18 students. Group B: 30 percent of 80 is 0.30 x 80 = 24 students. Group B has 24 - 18 = 6 more students above 70, even though a smaller percent of Group B scored above 70.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0.45*40=18. B: 0.30*80=24. 24-18=6.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3e34e7b-edd6-469d-9c3a-ef52c8800f8a', 'NC26.7.RD.5', 3, 'choice', 'Compare the share of each group above a cutoff', 'Group A has 30 students and 24 of them scored above 70. Group B has 60 students and 30 of them scored above 70. Sam says Group B did better because 30 is more than 24. Which statement is correct?', '["Sam is wrong: 80 percent of Group A scored above 70, but only 50 percent of Group B did","Sam is right: more students in Group B scored above 70","Sam is wrong: the same percent of each group scored above 70","Sam is right: Group B is bigger, so its score is more reliable"]', 'Sam is wrong: 80 percent of Group A scored above 70, but only 50 percent of Group B did', NULL, 'The groups have different sizes, so compare percents. Group A: 24 / 30 = 80 percent. Group B: 30 / 60 = 50 percent. A greater share of Group A scored above 70.', 'checked', '{"lint":[],"solve":{"answer":"Sam is wrong: 80 percent of Group A scored above 70, but only 50 percent of Group B did","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 24/30=80%. B: 30/60=50%. Groups differ in size, so compare percents; Sam is wrong.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a02a7537-4e01-4e12-a5be-667b06ecbc53', 'NC26.7.RD.5', 3, 'choice', 'Draw a conclusion the data support', 'Four pairs of groups each have means that differ by 6 points. Which pair gives the strongest evidence that the two groups really differ?', '["Each group has a MAD of 1","Each group has a MAD of 3","Each group has a MAD of 6","Each group has a MAD of 10"]', 'Each group has a MAD of 1', NULL, 'A difference in means is more convincing when it is large compared with the variation within the groups. A difference of 6 is 6 MADs when the MAD is 1, 2 MADs when it is 3, 1 MAD when it is 6, and only 0.6 of a MAD when it is 10.', 'checked', '{"lint":[],"solve":{"answer":"Each group has a MAD of 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A difference of 6 is 6 MADs when MAD=1, the largest relative to variability: strongest evidence.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b19757b-49b9-434b-9731-af397f0f04a5', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison in words', 'A student writes: "Team A is better because its mean score is 5 higher." Team A''s MAD is 20 and Team B''s MAD is 3. What should the report add?', '["Nothing more: the means alone show which team is better","That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","That Team A is more consistent, since its MAD is larger","That Team B scored more in total, since its MAD is smaller"]', 'That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3', NULL, 'A comparison of centres alone leaves out how spread out the scores are. Team A''s MAD of 20 is far larger than Team B''s MAD of 3, so A''s scores vary a lot and its mean is not very typical of its games. A larger MAD means less consistent, and the MAD does not tell us anything about total scores.', 'checked', '{"lint":[],"solve":{"answer":"That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A difference of 5 is small against A''s MAD of 20; the report should note A''s far greater variability.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfe9f7e9-e488-4eb5-b236-a8e1b8960889', 'NC26.7.RD.5', 3, 'numeric', 'Communicate a comparison in words', 'Nine girls ran a race in 31, 27, 35, 29, 33, 28, 36, 30, 34 seconds. Nine boys ran it in 38, 33, 41, 36, 35, 40, 34, 37, 39 seconds. A report says: "The median time of the girls was ___ seconds less than the median time of the boys." What number goes in the blank?', '[]', '6', '37-31', 'Girls in order: 27, 28, 29, 30, 31, 33, 34, 35, 36; the median (5th value) is 31. Boys in order: 33, 34, 35, 36, 37, 38, 39, 40, 41; the median (5th value) is 37. The difference is 37 - 31 = 6 seconds.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls sorted 27,28,29,30,31,33,34,35,36: median 31. Boys sorted 33,34,35,36,37,38,39,40,41: median 37. 37-31=6.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a8c63bf-bb0e-40d2-b092-f886ab6aefdc', 'NC26.7.RD.5', 3, 'choice', 'Reflect on sampling and sample size', 'Mia and Leo each take a random sample from the same school to estimate the mean number of books its students read in a month. Mia uses 5 students and Leo uses 50 students. Which statement is most likely true?', '["Leo''s estimate is more likely to be close to the school''s true mean","Mia''s estimate is more likely to be close, because her sample is smaller","Both estimates are equally likely to be close, because both samples are random","Leo''s estimate is exactly equal to the school''s true mean"]', 'Leo''s estimate is more likely to be close to the school''s true mean', NULL, 'A larger random sample varies less from one sample to the next, so it is more likely to be close to the true mean. But even a large sample estimate is usually not exactly equal to the true mean.', 'checked', '{"lint":[],"solve":{"answer":"Leo''s estimate is more likely to be close to the school''s true mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random sample has less sampling variability, so Leo''s estimate is more likely close (not exact).","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8bc41b0-0f67-4034-a552-80b7195bbf8f', 'NC26.7.RD.5', 3, 'choice', 'Reflect on sampling and sample size', 'A class posts an online poll on its website and anyone can answer. Of the 80 people who answer, most say they love the new school schedule. Why may these results not represent all students?', '["80 answers is too many to be reliable","Online polls always ask the questions in the wrong order","The mean of an online poll is always equal to its median","People with strong opinions are more likely to answer, so the sample is not random"]', 'People with strong opinions are more likely to answer, so the sample is not random', NULL, 'In an open poll, people choose whether to answer, and those with strong feelings are more likely to do so. A voluntary sample is not random and may not represent all students. A larger number of answers does not fix that.', 'checked', '{"lint":[],"solve":{"answer":"People with strong opinions are more likely to answer, so the sample is not random","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Voluntary-response sample: those with strong views answer, not random.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45feb8a7-f8be-4894-aba4-59ca249415da', 'NC26.7.RD.5', 3, 'choice', 'Reflect on the question and the method', 'Jess grows 5 plants under Brand X light in a sunny room and 5 plants under Brand Y light in a shaded room. The Brand X plants grow taller. Which change to her method would best let her conclude that the light caused the difference?', '["Grow more plants in the sunny room","Measure the Brand X plants more often","Report only the tallest plant from each group","Grow both groups in the same room with the same water, changing only the light"]', 'Grow both groups in the same room with the same water, changing only the light', NULL, 'To compare two groups fairly, only the thing being tested should differ. In her method the room also differs, so the room could explain the height. Using the same room and the same water isolates the light.', 'checked', '{"lint":[],"solve":{"answer":"Grow both groups in the same room with the same water, changing only the light","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Room (sun vs shade) is a confounder; hold everything else constant and vary only the light.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f8e5263-38a1-4d44-b74f-db098d6fe725', 'NC26.7.RD.5', 3, 'choice', 'Reflect on the question and the method', 'A student finds that Class A''s mean quiz score is 2 points higher than Class B''s, and that each class has a MAD of 10. What is the best next step?', '["Report that Class A is clearly better","Collect more data from larger random samples, because the difference is small compared with the variability","Throw out the scores that are far from the mean","Report only the range of each class"]', 'Collect more data from larger random samples, because the difference is small compared with the variability', NULL, 'The means are only 2 / 10 = 0.2 of a MAD apart, which is small compared with how much the scores vary. This could easily be chance, so more data from larger random samples is the sensible step. Dropping data points or reporting one statistic would not fix that.', 'checked', '{"lint":[],"solve":{"answer":"Collect more data from larger random samples, because the difference is small compared with the variability","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference 2 is only 0.2 MAD; inconclusive, so gather more data.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e20c763-78fe-49da-8077-0f142c41c68e', 'NC26.7.RD.5', 3, 'numeric', 'Use samples to compare two populations', 'Random samples suggest that students at School A read a mean of 3 books a month and students at School B read a mean of 5 books a month. School A has 450 students and School B has 300 students. Based on these estimates, how many more books are read in a month by all the students at School B than by all the students at School A?', '[]', '150', '5*300-3*450', 'School A: 3 x 450 = 1,350 books. School B: 5 x 300 = 1,500 books. School B students read 1,500 - 1,350 = 150 more books in total, even though School B has fewer students.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 3*450=1350. B: 5*300=1500. 1500-1350=150.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b7c2bd2-8b62-49a3-bce1-68857a4fee0e', 'NC26.7.RD.5', 3, 'numeric', 'Use samples to compare two populations', 'In a random sample of 50 people from Town X, 35 prefer the new park plan. In a random sample of 80 people from Town Y, 40 prefer it. Town X has 2,000 residents and Town Y has 1,500. Based on the samples, about how many more residents of Town X than of Town Y prefer the plan?', '[]', '650', '(35/50)*2000-(40/80)*1500', 'Town X: 35 / 50 = 70 percent, and 70 percent of 2,000 is 1,400 residents. Town Y: 40 / 80 = 50 percent, and 50 percent of 1,500 is 750 residents. The estimated difference is 1,400 - 750 = 650 residents.', 'checked', '{"lint":[],"solve":{"answer":"650","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 35/50=0.7, 0.7*2000=1400. Y: 40/80=0.5, 0.5*1500=750. 1400-750=650.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec7c547b-51b1-48fc-8a4b-32c9172dc2aa', 'NC26.7.RD.5', 3, 'choice', 'Use samples to compare two populations', 'Two different random samples of 20 students from the same school gave mean amounts of sleep of 8.4 hours and 8.9 hours. Which is the best explanation for the difference?', '["One of the samples must have been chosen incorrectly","The school''s true mean changed between the samples","One of the students made an arithmetic mistake","Different random samples usually give slightly different means"]', 'Different random samples usually give slightly different means', NULL, 'Random samples contain different students, so their means vary a little by chance. A small difference like this is normal and does not mean that anything went wrong.', 'checked', '{"lint":[],"solve":{"answer":"Different random samples usually give slightly different means","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sampling variability: different random samples give slightly different means.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bea94d8-4256-435c-9471-1fee1a9c7866', 'NC26.7.RD.5', 3, 'numeric', 'Compare the means of two groups', 'Group P has the values 12, 18, 9 and 21. Group Q has five values: 10, 12, 17, 20 and $x$. The two groups have the same mean. What is the value of $x$?', '[]', '16', '15*5-(10+12+17+20)', 'The mean of Group P is $(12 + 18 + 9 + 21) \div 4 = 60 \div 4 = 15$. Group Q has 5 values and the same mean, so they must add to $15 \times 5 = 75$. The four known values add to $10 + 12 + 17 + 20 = 59$. So $x = 75 - 59 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P mean 60/4=15. Q needs sum 5x15=75; 10+12+17+20=59; x=75-59=16.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072c6387-2267-4e3b-8a69-378d0438a0af', 'NC26.7.RD.5', 3, 'numeric', 'Compare the variability of two groups with the IQR', 'Two groups of students timed how many minutes they took to finish a puzzle. Group A: 3, 7, 9, 12, 17, 20. Group B: 10, 12, 13, 15, 17, 19. Each list is in order. The quartiles are the medians of the lower half and the upper half of the data. The IQR of Group A is how many times the IQR of Group B?', '[]', '2', '(17-7)/(17-12)', 'Group A: the lower half is 3, 7, 9 so Q1 = 7, and the upper half is 12, 17, 20 so Q3 = 17. The IQR is 17 - 7 = 10. Group B: the lower half is 10, 12, 13 so Q1 = 12, and the upper half is 15, 17, 19 so Q3 = 17. The IQR is 17 - 12 = 5. Then 10 / 5 = 2, so the IQR of Group A is 2 times the IQR of Group B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group A (6 values): lower half 3, 7, 9 -> Q1 = 7; upper half 12, 17, 20 -> Q3 = 17; IQR = 10. Group B: lower half 10, 12, 13 -> Q1 = 12; upper half 15, 17, 19 -> Q3 = 17; IQR = 5. Ratio 10 / 5 = 2.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c997d68-a63b-4cda-a2f8-6bcbf25d49ab', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve a linear equation with the variable on both sides', 'Solve for $x$: $5x + 3 = 2x + 15$', '[]', '4', '(15-3)/(5-2)', 'Subtract $2x$ from both sides: $3x + 3 = 15$. Subtract 3 from both sides: $3x = 12$. Divide by 3: $x = 4$. Check: $5(4) + 3 = 23$ and $2(4) + 15 = 23$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 3 = 2x + 15 -> 3x = 12 -> x = 4. Check: 23 = 23.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a90734e-30cc-4df9-9446-4f3fadcf7b23', 'NC26.8.ANFR.1', 1, 'choice', 'Write an equation from a situation with two quantities', 'Maya has 5 dollars and saves 2 dollars each week. Leo has 11 dollars and saves 1 dollar each week. Let $w$ be the number of weeks. Which equation says that they have the same amount of money after $w$ weeks?', '["$2 + 5w = 1 + 11w$","$5 + 2w = 11 + w$","$5 + 2w = 11w$","$5 + 11 = 2w + w$"]', '$5 + 2w = 11 + w$', NULL, 'After $w$ weeks Maya has $5 + 2w$ dollars (5 to start, 2 more each week). Leo has $11 + w$ dollars. "The same amount" means the two are equal: $5 + 2w = 11 + w$.', 'checked', '{"lint":[],"solve":{"answer":"$5 + 2w = 11 + w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maya after w weeks: 5 + 2w. Leo: 11 + 1w = 11 + w. Same amount: 5 + 2w = 11 + w. Other options mix up the start and the rate.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084c344b-7ea5-4dd8-bc0a-7dfe6b9bf52e', 'NC26.8.ANFR.1', 1, 'numeric', 'Find the whole numbers that satisfy an inequality with the variable on both sides', 'What is the greatest whole number $x$ that makes $4x - 5 < x + 7$ true?', '[]', '3', '12/3-1', 'Subtract $x$ from both sides: $3x - 5 < 7$. Add 5: $3x < 12$. Divide by 3: $x < 4$. The greatest whole number less than 4 is 3. Check: for $x = 3$, $4(3) - 5 = 7$ and $3 + 7 = 10$, and $7 < 10$. For $x = 4$ both sides equal 11, so 4 does not work.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 < x + 7 -> 3x < 12 -> x < 4. Greatest whole number below 4 is 3. Check x=3: 7 < 10 true; x=4: 11 < 11 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52efaf6a-9a7e-4840-a4c9-d7a9acc5c1b7', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation with the variable on both sides', 'Solve for $x$: $8x - 6 = 5x + 9$', '[]', '5', '(15)/(3)', 'Move the $x$ terms to one side and the numbers to the other: $3x = 15$. Divide both sides by $3$: $x = 5$. Check: with $x = 5$ both sides equal $34$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x - 5x = 9 + 6 -> 3x = 15 -> x = 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
