INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('495e7f47-0be4-464c-b2b1-9eb5ecf86cf1', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation with the variable on both sides', 'What value of $x$ makes this equation true? $13 + 2x = 5x - 8$', '[]', '7', '((0-21))/((0-3))', 'Simplify each side: $2x + 13 = 5x - 8$. Move the $x$ terms to one side and the numbers to the other: $-3x = -21$. Divide both sides by $-3$: $x = 7$. Check: with $x = 7$ both sides equal $27$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 + 8 = 5x - 2x -> 21 = 3x -> x = 7. Check: 27 = 27.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
