INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c820933-7f84-4816-872f-e469861dd4fb', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation with the variable on both sides', 'Which value of $x$ makes $2x + 9 = 5x$ true?', '["$-3$","$3$","$\\frac{9}{7}$","$7$"]', '$3$', '9/3', 'Move the $x$ terms to one side and the numbers to the other: $-3x = -9$. Divide both sides by $-3$: $x = 3$. Check: with $x = 3$ both sides equal $15$. The other choices come from moving terms the wrong way, for example adding $2x$ and $5x$ together.', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 3x -> x = 3. Check: 15 = 15.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
