INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74ebc0e1-51f4-40c9-91b5-240d541a3846', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation that needs the distributive property', 'Find the value of $x$ that solves $3x = 2(x + 7)$.', '[]', '14', '(14)/(1)', 'Simplify each side: $3x = 2x + 14$. Move the $x$ terms to one side and the numbers to the other: $x = 14$. Check: with $x = 14$ both sides equal $42$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 2x + 14 -> x = 14. Check: 42 = 42.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
