VALUES ('1546e754-c16b-4c48-8003-498806fc5d80', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve for $x$: $1.5x - 2.4 = 0.3x + 3.6$', '[]', '5', '(6)/(6/5)', 'Move the $x$ terms to one side and the numbers to the other: $1.2x = 6$. Divide both sides by $1.2$: $x = 5$. Check: with $x = 5$ both sides equal $5.1$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2x = 6 -> x = 5. Check: 5.1 = 5.1.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
