INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e58cc75b-c339-470a-aaa2-1293c260a740', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation with fraction or decimal coefficients', 'Which equation is equivalent to $\frac{x}{4} + \frac{1}{2} = \frac{x}{2} - 1$ and has no fractions?', '["$x + 2 = 2x - 1$","$x + 1 = 2x - 4$","$x + 2 = 2x - 4$","$x + 2 = x - 4$"]', '$x + 2 = 2x - 4$', NULL, 'Multiply every term on both sides by 4: $4 \cdot \frac{x}{4} = x$, $4 \cdot \frac{1}{2} = 2$, $4 \cdot \frac{x}{2} = 2x$ and $4 \cdot (-1) = -4$. The result is $x + 2 = 2x - 4$. The other choices forget to multiply a term by 4 or multiply a term by the wrong amount.', 'checked', '{"lint":[],"solve":{"answer":"$x + 2 = 2x - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply by 4: x + 2 = 2x - 4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64e48150-1813-46b6-8842-06c56067a09c', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Solve $2(x + 3) = 2x + 5$ and decide how many solutions it has.', '["Exactly one solution","Infinitely many solutions","Exactly two solutions","No solution"]', 'No solution', NULL, 'Simplify each side: $2x + 6 = 2x + 5$. Move the $x$ terms to one side and the numbers to the other: $0 = -1$. The $x$ terms cancel and what is left is never true, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 6 = 2x + 5 -> 6 = 5, false: no solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffc830de-791f-4f09-9740-752c0a769380', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Which statement about $4x + 8 = 4(x + 2)$ is true?', '["It is true for every value of $x$","It is true for exactly one value of $x$","It is true for no value of $x$","It is true for exactly two values of $x$"]', 'It is true for every value of $x$', NULL, 'Simplify each side: $4x + 8 = 4x + 8$. Move the $x$ terms to one side and the numbers to the other: $0 = 0$. The $x$ terms cancel and what is left is always true, so every number is a solution.', 'checked', '{"lint":[],"solve":{"answer":"It is true for every value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 2) = 4x + 8, identical: every value.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b600dbe7-aff1-4297-91b8-3f221440fbf2', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'How many solutions does the equation $7x + 2 = 5x + 2$ have?', '["No solution","Infinitely many solutions","Exactly two solutions","Exactly one solution"]', 'Exactly one solution', NULL, 'Move the $x$ terms to one side and the numbers to the other: $2x = 0$. Divide both sides by $2$: $x = 0$. Check: with $x = 0$ both sides equal $2$. The only solution is $x = 0$, so there is exactly one solution (the constants match, but the $x$ terms do not).', 'checked', '{"lint":[],"solve":{"answer":"Exactly one solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x = 0 -> x = 0: exactly one solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f98fca26-1354-44b5-bdbd-b8e22f896a30', 'NC26.8.ANFR.1', 2, 'numeric', 'Find the value that gives no or infinitely many solutions', 'For what value of $k$ does $5x + k = 5(x - 3)$ have infinitely many solutions?', '[]', '-15', '5*(0-3)', 'Expand the right side: $5(x - 3) = 5x - 15$. The equation $5x + k = 5x - 15$ is true for every $x$ exactly when $k = -15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x - 3) = 5x - 15, so k = -15.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b54a4c58-38c5-4333-9d63-06b7e93d8a5e', 'NC26.8.ANFR.1', 2, 'choice', 'Find the value that gives no or infinitely many solutions', 'The equation $4x - 9 = 4x + m$ has infinitely many solutions. What is the value of $m$?', '["$9$","$0$","$-9$","$4$"]', '$-9$', '0-9', 'Both sides have $4x$. For the equation to be true for every $x$, the numbers must match too, so $m = -9$. With any other value of $m$ the equation has no solution.', 'checked', '{"lint":[],"solve":{"answer":"$-9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Constants must match: m = -9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffdce7bd-6083-4cd8-8d34-9f17632a31c4', 'NC26.8.ANFR.1', 2, 'choice', 'Write an equation for a situation', 'A rectangle has length $x + 6$ and width 3. A square has side length $x$. Which equation says that the rectangle and the square have the same perimeter?', '["$3(x + 6) = 4x$","$x + 6 + 3 = 4x$","$2(x + 6) + 3 = 4x$","$2(x + 6) + 2(3) = 4x$"]', '$2(x + 6) + 2(3) = 4x$', NULL, 'The perimeter of the rectangle is twice the length plus twice the width: $2(x + 6) + 2(3)$. The perimeter of the square is $4x$. So the equation is $2(x + 6) + 2(3) = 4x$. The other choices find an area, add each side once, or count the width only once.', 'checked', '{"lint":[],"solve":{"answer":"$2(x + 6) + 2(3) = 4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle perimeter 2(x + 6) + 2(3); square 4x.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a9335ef-06a7-4401-8b3e-256a79a10b62', 'NC26.8.ANFR.1', 2, 'choice', 'Write an equation for a situation', 'A candle 20 cm tall burns down 2 cm each hour. A second candle 15 cm tall burns down 1 cm each hour. Let $h$ be the number of hours. Which equation says that the two candles are the same height?', '["$20 - 2h = 15 - h$","$20 + 2h = 15 + h$","$20 - 2h = 15 + h$","$20 - 2h = 15$"]', '$20 - 2h = 15 - h$', NULL, 'After $h$ hours the first candle is $20 - 2h$ cm tall and the second is $15 - h$ cm tall. Setting them equal gives $20 - 2h = 15 - h$. The candles get shorter, so the terms with $h$ are subtracted.', 'checked', '{"lint":[],"solve":{"answer":"$20 - 2h = 15 - h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights 20 - 2h and 15 - h.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('391cc9c0-5a3b-4cc4-9250-374e0277381d', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve a problem with an equation', 'Plan A costs 15 dollars a month plus 0.10 dollars for each text. Plan B costs 5 dollars a month plus 0.20 dollars for each text. For how many texts in a month do the two plans cost the same?', '[]', '100', '((0-10))/((0-1/10))', 'For $t$ texts, Plan A costs $15 + 0.10t$ dollars and Plan B costs $5 + 0.20t$ dollars. Set them equal: $15 + 0.10t = 5 + 0.20t$. Then $10 = 0.10t$, so $t = 100$. Check: $15 + 10 = 25$ and $5 + 20 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 0.10t = 5 + 0.20t -> 10 = 0.10t -> t = 100. Both cost $25.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('517eca9f-c1ff-4c28-9fcf-9834fbb7dd7f', 'NC26.8.ANFR.1', 2, 'choice', 'Solve a problem with an equation', 'Pool X has 100 liters and is filled at 20 liters per minute. Pool Y has 300 liters and is filled at 10 liters per minute. After how many minutes do the two pools hold the same amount?', '["$10$","$30$","$40$","$20$"]', '$20$', '(300-100)/(20-10)', 'After $m$ minutes the pools hold $100 + 20m$ and $300 + 10m$ liters. Setting them equal: $10m = 200$, so $m = 20$ minutes. Check: $100 + 400 = 500$ and $300 + 200 = 500$.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 + 20t = 300 + 10t -> 10t = 200 -> t = 20. Both 500 L.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48389a4e-9da7-4388-912a-ec8ba567884c', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality with the variable on both sides', 'Which inequality is equivalent to $8x - 5 \ge 3x + 20$?', '["$x \\le 5$","$x \\ge 3$","$x \\ge 5$","$x \\ge \\frac{25}{11}$"]', '$x \ge 5$', NULL, 'Move the $x$ terms to one side and the numbers to the other: $5x \ge 25$. Divide both sides by $5$: $x \ge 5$. The other choices reverse the sign, move the 5 the wrong way, or add the $x$ terms.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x >= 25 -> x >= 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d39ea7e9-9458-4e89-a5f0-dc7a0c7c7eee', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an inequality with the variable on both sides', 'What is the smallest integer $x$ that satisfies $9 + 5x > 2x - 6$?', '[]', '-4', '(0-6-9)/3+1', 'Simplify each side: $5x + 9 > 2x - 6$. Move the $x$ terms to one side and the numbers to the other: $3x > -15$. Divide both sides by $3$: $x > -5$. Since $x$ must be greater than $-5$, the smallest integer is $-4$. (Check: $9 + 5(-4) = -11 > 2(-4) - 6 = -14$.)', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x > -15 -> x > -5; smallest integer -4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c0c4762-f727-4b24-a8b7-cfb655bcca6b', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an inequality that needs a sign reversal', 'What is the least integer $x$ that satisfies $4 - 3x < 2x + 19$?', '[]', '-2', '0-15/5+1', 'Simplify each side: $-3x + 4 < 2x + 19$. Move the $x$ terms to one side and the numbers to the other: $-5x < 15$. Divide both sides by $-5$. Dividing by a negative number reverses the inequality: $x > -3$. Since $x$ must be greater than $-3$, the least integer is $-2$. (Check: $4 - 3(-2) = 10 < 2(-2) + 19 = 15$.)', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - 19 < 5x -> -15 < 5x -> x > -3; least integer -2.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f3f7799-2684-461d-a932-0dc8aa5857fd', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality that needs a sign reversal', 'Which inequality shows all of the solutions of $10 - 4x \le 6x - 20$?', '["$x \\le 3$","$x \\ge 3$","$x \\ge -3$","$x \\le -3$"]', '$x \ge 3$', NULL, 'Simplify each side: $-4x + 10 \le 6x - 20$. Move the $x$ terms to one side and the numbers to the other: $-10x \le -30$. Divide both sides by $-10$. Dividing by a negative number reverses the inequality: $x \ge 3$. The other choices forget to reverse the sign or make a sign error with the numbers.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 <= 10x -> x >= 3.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29da59f1-1d93-4bd7-ac08-b98efb14175a', 'NC26.8.ANFR.1', 2, 'choice', 'Write an inequality for a situation', 'Ava has 100 dollars and spends 6 dollars each week. Ben has 40 dollars and saves 4 dollars each week. Let $w$ be the number of weeks. Which inequality says that Ava still has more money than Ben?', '["$100 + 6w > 40 - 4w$","$100 - 6w < 40 + 4w$","$100 - 6w > 40 + 4w$","$100 - 6w > 40 - 4w$"]', '$100 - 6w > 40 + 4w$', NULL, 'After $w$ weeks Ava has $100 - 6w$ dollars (she spends) and Ben has $40 + 4w$ dollars (he saves). "More than" means $>$. The other choices mix up who spends and who saves, or use the wrong sign.', 'checked', '{"lint":[],"solve":{"answer":"$100 - 6w > 40 + 4w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ava 100 - 6w, Ben 40 + 4w; Ava more: 100 - 6w > 40 + 4w.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('972992b4-5ea9-412c-a78d-5844637f9f01', 'NC26.8.ANFR.1', 2, 'choice', 'Write an inequality for a situation', 'Which sentence matches the inequality $2n - 7 > n + 4$?', '["7 more than twice a number is greater than 4 more than the number","7 less than twice a number is greater than 4 less than the number","7 less than twice a number is less than 4 more than the number","7 less than twice a number is greater than 4 more than the number"]', '7 less than twice a number is greater than 4 more than the number', NULL, '$2n - 7$ is 7 less than twice a number, $n + 4$ is 4 more than the number, and $>$ means "is greater than". The other choices change "less" to "more", change "more" to "less", or reverse the comparison.', 'checked', '{"lint":[],"solve":{"answer":"7 less than twice a number is greater than 4 more than the number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n - 7 is 7 less than twice n; n + 4 is 4 more than n; > is greater than.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca9f1e0c-111f-48ca-b39d-1496a8a94aba', 'NC26.8.ANFR.1', 2, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'How many integers from $-5$ to $5$, including both $-5$ and $5$, satisfy $2x + 1 > 4x - 5$?', '[]', '8', '8', 'Move the $x$ terms to one side and the numbers to the other: $-2x > -6$. Divide both sides by $-2$. Dividing by a negative number reverses the inequality: $x < 3$. The integers from $-5$ to $5$ that are less than 3 are $-5, -4, -3, -2, -1, 0, 1, 2$, which is 8 integers.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 > 2x -> x < 3. Integers -5..2: 8 values.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97666d2e-f706-49a6-86ca-f32bae602cdf', 'NC26.8.ANFR.1', 2, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'What is the sum of all of the positive integers that satisfy $3x + 4 \le 2x + 9$?', '[]', '15', '1+2+3+4+5', 'Move the $x$ terms to one side and the numbers to the other: $x \le 5$. The positive integers that are 5 or less are 1, 2, 3, 4 and 5, and their sum is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x <= 5; positive integers 1..5; sum 15.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4d1280f-bf5f-454b-90f4-0f55f508a04b', 'NC26.8.ANFR.1', 2, 'choice', 'Find the error in a solution', 'Li solved $2(x - 4) = x + 3$. Step 1: $2x - 4 = x + 3$. Step 2: $x = 7$. Where is her first mistake?', '["Step 1; the 4 was not multiplied by 2","Step 2; $x$ should have been subtracted from the right side only","There is no mistake","Step 1; 2 should have been added to $x - 4$"]', 'Step 1; the 4 was not multiplied by 2', NULL, 'In Step 1 the 2 must multiply both terms in the parentheses: $2(x - 4) = 2x - 8$, not $2x - 4$. The correct work is $2x - 8 = x + 3$, so $x = 11$. Step 2 is correct for the equation she wrote, but that equation was wrong.', 'checked', '{"lint":[],"solve":{"answer":"Step 1; the 4 was not multiplied by 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x - 4) = 2x - 8, not 2x - 4. Step 1 is the first mistake (correct x = 11).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c3f72d2-75f8-4d61-9659-788c838ea3bf', 'NC26.8.ANFR.1', 2, 'choice', 'Find the error in a solution', 'Omar solved $-3x + 4 < 10$. Step 1: $-3x < 6$. Step 2: $x < -2$. What mistake did he make?', '["In Step 1, he should have added 4 to both sides","In Step 2, he should have written $x < 2$","There is no mistake","In Step 2, he did not reverse the inequality sign when dividing by $-3$"]', 'In Step 2, he did not reverse the inequality sign when dividing by $-3$', NULL, 'Step 1 is correct (subtract 4 from both sides). In Step 2 he divided both sides by $-3$, which reverses the inequality, so the answer is $x > -2$. (Check: $x = 0$ gives $4 < 10$, which is true, and $0 > -2$.)', 'checked', '{"lint":[],"solve":{"answer":"In Step 2, he did not reverse the inequality sign when dividing by $-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Step 1 correct: -3x < 6. Dividing by -3 must reverse: x > -2. He kept <.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a26c0a01-6af0-4ef3-8ae0-87293c6d1595', 'NC26.8.ANFR.1', 2, 'choice', 'Check a solution and justify the steps', 'Which property justifies the step from $3(x + 2) = 9$ to $3x + 6 = 9$?', '["The commutative property of addition","The associative property of multiplication","The distributive property","The identity property of addition"]', 'The distributive property', NULL, 'The 3 outside the parentheses is multiplied by each term inside: $3(x + 2) = 3 \cdot x + 3 \cdot 2 = 3x + 6$. That is the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"The distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6 is the distributive property.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e26f99e-67b3-4ea4-8885-9455f67ae762', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with fraction coefficients on both sides', 'Solve for $x$: $\frac{1}{2}x + 3 = \frac{1}{4}x + 8$', '[]', '20', '(8-3)/(1/2-1/4)', 'Subtract $\frac{1}{4}x$ from both sides: $\frac{1}{4}x + 3 = 8$. Subtract 3: $\frac{1}{4}x = 5$. Multiply by 4: $x = 20$. Check: $\frac{1}{2}(20) + 3 = 13$ and $\frac{1}{4}(20) + 8 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)x - (1/4)x = 8 - 3 -> (1/4)x = 5 -> x = 20. Check: 10 + 3 = 13 = 5 + 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
