INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e681b5fe-f845-4835-aa48-75298f41a336', 'NC26.8.ANFR.2', 1, 'choice', 'Use a function rule to find an output or an input', 'A function''s rule is: the output is the input divided by 2. Which pair (input, output) fits this rule?', '["$(10, 5)$","$(10, 20)$","$(10, 8)$","$(10, 12)$"]', '$(10, 5)$', NULL, 'Divide the input by 2: $10 \div 2 = 5$, so the pair is $(10, 5)$. The pair $(10, 20)$ multiplies by 2, $(10, 8)$ subtracts 2 and $(10, 12)$ adds 2.', 'checked', '{"lint":[],"solve":{"answer":"$(10, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 / 2 = 5, so (10, 5).","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
