INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f442f263-a7a9-4359-ab85-f69575bfabf2', 'NC26.8.ANFR.2', 1, 'choice', 'Decide whether a function is increasing or decreasing', 'Which statement describes a decreasing function?', '["As the input gets larger, the output stays the same","As the input gets smaller, the output gets smaller","As the input gets larger, the output gets smaller","The output is always a negative number"]', 'As the input gets larger, the output gets smaller', NULL, 'A decreasing function has outputs that go down as the inputs go up. An output that stays the same describes a constant function, an output that gets smaller as the input gets smaller describes an increasing function, and a decreasing function can still have positive outputs.', 'checked', '{"lint":[],"solve":{"answer":"As the input gets larger, the output gets smaller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Decreasing: as input increases, output decreases. Option D describes increasing; A and B are not decreasing.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fe5e7d9-8e36-4e45-b921-1d25f94de8d5', 'NC26.8.ANFR.2', 1, 'numeric', 'Find where a function increases or decreases', 'The temperature at 6 AM, 7 AM, 8 AM, 9 AM and 10 AM was 50, 54, 53, 59 and 63 degrees. Over how many of the four one-hour steps did the temperature increase?', '[]', '3', '1+0+1+1', 'Compare each hour with the one before. 50 to 54 goes up, 54 to 53 goes down, 53 to 59 goes up and 59 to 63 goes up. The temperature increased in 3 of the 4 steps.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50->54 up, 54->53 down, 53->59 up, 59->63 up. 3 increases.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('761028c4-a8d9-44fd-a58d-d3a4e0ad7670', 'NC26.8.ANFR.2', 1, 'choice', 'Find where a function increases or decreases', 'Imagine the graph of the depth of the water in a pool. The pool is filled for 3 hours, stays full for 2 hours, and is then emptied for 3 hours (hours 0 to 8). During which hours is the depth decreasing?', '["From hour 0 to hour 3","From hour 5 to hour 8","From hour 3 to hour 5","From hour 0 to hour 8"]', 'From hour 5 to hour 8', NULL, 'The depth goes up during the first 3 hours, stays the same from hour 3 to hour 5, and goes down from hour 5 to hour 8 while the pool is emptied.', 'checked', '{"lint":[],"solve":{"answer":"From hour 5 to hour 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Filling 0-3 (increasing), full 3-5 (constant), emptying 5-8 (decreasing).","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38bb9754-9271-4341-b362-338891426878', 'NC26.8.ANFR.2', 1, 'choice', 'Find where a function increases or decreases', 'The money in a jar was 10 dollars in week 0, 14 dollars in week 1, 14 dollars in week 2 and 8 dollars in week 3. Over which one-week step did the amount decrease?', '["From week 0 to week 1","From week 1 to week 2","From week 2 to week 3","From week 0 to week 2"]', 'From week 2 to week 3', NULL, 'From week 0 to week 1 the amount goes up (10 to 14), from week 1 to week 2 it stays the same (14 to 14), and from week 2 to week 3 it goes down (14 to 8).', 'checked', '{"lint":[],"solve":{"answer":"From week 2 to week 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10->14 up, 14->14 same, 14->8 down. Week 2 to week 3. (Week 0 to 2 is not a one-week step and is a rise.)","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
