INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('929a6e6e-0df5-4520-be80-e63ae9eb6a58', 'NC26.8.ANFR.2', 1, 'numeric', 'Tell linear from non-linear using pairs or a table', 'A function has the outputs 4, 7, 10 and 13 for the inputs 0, 1, 2 and 3. By how much does the output go up each time the input goes up by 1?', '[]', '3', '7-4', 'Each output is 3 more than the one before: $7 - 4 = 3$, $10 - 7 = 3$ and $13 - 10 = 3$. The output goes up by 3 each time, so the function is linear.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, 7, 10, 13: up 3 each time.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
