INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9048560f-c51a-48be-a8ef-d9b439d63768', 'NC26.8.ANFR.2', 1, 'choice', 'Match a real situation to the shape of its graph', 'A ball is thrown straight up and then falls back to the ground. Imagine the graph of its height against time. Which describes the graph?', '["It falls to a lowest point and then rises","It stays at the same height","It rises to a peak and then falls","It rises steadily and never falls"]', 'It rises to a peak and then falls', NULL, 'The ball goes up, reaches its highest point, and comes back down. The height rises to a peak and then falls.', 'checked', '{"lint":[],"solve":{"answer":"It rises to a peak and then falls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height rises to a maximum and then falls back to the ground.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
