INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a31db364-3faf-44c8-9b96-0372060216df', 'NC26.8.ANFR.2', 1, 'numeric', 'Describe the pattern of change in a non-linear function', 'The outputs of a function for the inputs 1, 2, 3 and 4 are 2, 4, 8 and 16. Each output is double the one before it. What is the output for the input 6?', '[]', '64', '16*2*2', 'Keep doubling: the input 5 gives $16 \times 2 = 32$ and the input 6 gives $32 \times 2 = 64$.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 4, 8, 16, then 32 at input 5, 64 at input 6.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
