INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfcdac1f-103b-494e-a029-28437def46da', 'NC26.8.ANFR.3', 1, 'choice', 'Write the equation of a line from its slope and y-intercept', 'Which equation is for a line with slope 2 and $y$-intercept $-4$?', '["$y = 2x - 4$","$y = -4x + 2$","$y = 2x + 4$","$y = -2x - 4$"]', '$y = 2x - 4$', NULL, 'Use $y = mx + b$ with $m = 2$ and $b = -4$: $y = 2x - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b with m = 2, b = -4: y = 2x - 4.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef5d83d3-3511-461b-bb14-5c6832b1d11d', 'NC26.8.ANFR.3', 1, 'choice', 'Identify a linear function and its form', 'Which equation is written in slope-intercept form?', '["$2x + y = 5$","$y - 5 = 2x$","$y = 2x + 5$","$x = 2y + 5$"]', '$y = 2x + 5$', NULL, 'Slope-intercept form is $y = mx + b$, with $y$ alone on one side. Only $y = 2x + 5$ is in that form: its slope is 2 and its $y$-intercept is 5. The other equations have $y$ mixed with other terms or have $x$ alone.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope-intercept form is y = mx + b with y alone on the left. Only y = 2x + 5 is in that form (the others are equivalent rearrangements or a different line).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aeeb0e35-1b27-4f33-a262-16e072fe3350', 'NC26.8.ANFR.3', 1, 'choice', 'Identify a linear function and its form', 'The graph of a function is a straight line. Which statement must be true about the function?', '["The output changes by the same amount for every equal change in the input","The output is always positive","The output gets larger as the input gets larger","The graph passes through the point $(0, 0)$"]', 'The output changes by the same amount for every equal change in the input', NULL, 'A straight line has a constant slope, so the output changes by the same amount each time the input changes by the same amount. A line can go down, can have negative outputs, and need not pass through $(0, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"The output changes by the same amount for every equal change in the input","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A non-vertical straight-line graph has a constant rate of change, so equal input changes give equal output changes. It may be negative, decreasing, or miss the origin.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ee8fe57-fd2d-4872-b4a1-6a2bccfa2576', 'NC26.8.ANFR.3', 1, 'numeric', 'Read the slope and y-intercept from an equation', 'The line $y = 2x - 8$ crosses the $y$-axis at the point $(0, b)$. What is $b$?', '[]', '-8', '-8', 'In $y = mx + b$ the number added at the end is the $y$-intercept. Here it is $-8$. Check: when $x = 0$, $y = 2 \times 0 - 8 = -8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = -8, so b = -8.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fcd33cf-b058-4cfb-a251-dac0e941396e', 'NC26.8.ANFR.3', 1, 'choice', 'Read the slope and y-intercept from an equation', 'Which equation has a slope of $-2$?', '["$y = 7x - 2$","$y = 2x - 7$","$y = -2x + 7$","$y = -7x + 2$"]', '$y = -2x + 7$', NULL, 'The slope is the number multiplying $x$. In $y = -2x + 7$ it is $-2$. In the other equations the numbers multiplying $x$ are 7, 2 and $-7$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -2x + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slopes: 7, -7, 2, -2. y = -2x + 7.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
