INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67d9b89c-9908-42ff-bd87-86afb04db39d', 'NC26.8.ANFR.3', 1, 'numeric', 'Read the slope and y-intercept from an equation', 'In the equation $y = \frac{1}{2}x + 6$, what number is the slope?', '[]', '1/2', '1/2', 'The slope is the number that multiplies $x$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In y = mx + b, m = 1/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
