INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba7a6e33-1336-4638-a138-51477dcaa621', 'NC26.8.ANFR.3', 1, 'choice', 'Find the slope of a line from points or a table', 'Which pair of points lies on a line with a slope of 2?', '["$(1, 1)$ and $(3, 2)$","$(1, 1)$ and $(2, 4)$","$(1, 1)$ and $(3, 1)$","$(1, 1)$ and $(2, 3)$"]', '$(1, 1)$ and $(2, 3)$', NULL, 'The slope between $(1, 1)$ and $(2, 3)$ is $\frac{3 - 1}{2 - 1} = 2$. The other pairs have slopes $\frac{1}{2}$, 3 and 0.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 1)$ and $(2, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From (1,1): to (2,3) slope 2; to (2,4) slope 3; to (3,2) slope 1/2; to (3,1) slope 0. Answer A.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7565fb4-4c33-4d42-a5a1-cf63f0a97a02', 'NC26.8.ANFR.3', 1, 'numeric', 'Find the slope of a line from points or a table', 'A line passes through the points $(4, 6)$ and $(9, 6)$. What is its slope?', '[]', '0', '(6-6)/(9-4)', 'Both points have the same $y$-value, so the line is horizontal and the rise is 0. The slope is $\frac{0}{5} = 0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y-value, change in y 0: slope 0.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
