INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ce4c5fe-9866-41d7-a094-d5eb86ab5e34', 'NC26.8.ANFR.3', 1, 'numeric', 'Find the y-intercept from a slope and a point, or from points', 'A linear function has the $x$-values 0, 1 and 2 with the $y$-values 4, 6 and 8. What is its $y$-intercept?', '[]', '4', '4', 'The $y$-intercept is the value of $y$ when $x = 0$. The table shows $y = 4$ at $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
