INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37138d49-aeab-49a4-9541-d3b354244922', 'NC26.8.ANFR.3', 1, 'choice', 'Find the y-intercept from a slope and a point, or from points', 'A line passes through $(0, -3)$ and $(2, 1)$. At which point does it cross the $y$-axis?', '["$(0, -3)$","$(-3, 0)$","$(0, 1)$","$(1, 0)$"]', '$(0, -3)$', NULL, 'A point on the $y$-axis has $x = 0$. The given point $(0, -3)$ has $x = 0$, so the line crosses the $y$-axis there.', 'checked', '{"lint":[],"solve":{"answer":"$(0, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0, -3) has x = 0, so it is the y-axis crossing.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
