INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8c42e08-2ea4-405d-90a7-f3a13d257fb4', 'NC26.8.ANFR.3', 1, 'choice', 'Interpret the slope and y-intercept in a situation', 'A phone''s battery level is $y = 100 - 8x$ percent after $x$ hours of use. What does the $-8$ tell us?', '["The battery starts at 8 percent","The battery lasts 8 hours","The battery level rises by 8 percent each hour","The battery level drops by 8 percent each hour"]', 'The battery level drops by 8 percent each hour', NULL, 'The number multiplying $x$ is the slope, $-8$. It is a change of $-8$ percent for each hour, a drop of 8 percent each hour. The starting level is the 100.', 'checked', '{"lint":[],"solve":{"answer":"The battery level drops by 8 percent each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope -8: the level drops 8 percent per hour.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
