INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8f8d4bc-43e5-4b3e-b907-908aa2932097', 'NC26.8.ANFR.3', 1, 'choice', 'Interpret the slope and y-intercept in a situation', 'The equation $y = 5x + 20$ gives the total cost in dollars of $x$ visits to a gym. Which situation does it describe?', '["The gym charges 5 dollars to join and 20 dollars per visit","The gym charges 20 dollars to join and 5 dollars per visit","The gym charges 25 dollars per visit","The gym charges 20 dollars in all, however many visits"]', 'The gym charges 20 dollars to join and 5 dollars per visit', NULL, 'The 5 multiplies the number of visits, so it is the cost per visit. The 20 is added once, so it is the joining fee.', 'checked', '{"lint":[],"solve":{"answer":"The gym charges 20 dollars to join and 5 dollars per visit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercept 20 is a one-time fee; slope 5 per visit.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
