INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dec63a8c-6a69-4312-93af-21ea396e496f', 'NC26.8.ANFR.3', 1, 'choice', 'Graph a line: points, intercepts and steepness', 'Which point lies on the line $y = 2x + 1$?', '["$(3, 5)$","$(3, 6)$","$(3, 8)$","$(3, 7)$"]', '$(3, 7)$', NULL, 'A point is on the line when its coordinates make the equation true. For $x = 3$: $y = 2 \times 3 + 1 = 7$, so $(3, 7)$ is on the line.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 3: y = 7. (3, 7).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
