INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39888687-40ec-450c-801b-ddec017c8115', 'NC26.8.ANFR.3', 1, 'choice', 'Graph a line: points, intercepts and steepness', 'A line crosses the $y$-axis at $(0, 3)$ and has a slope of 2. Going 1 unit right and 2 units up from $(0, 3)$ reaches another point of the line. Which point is it?', '["$(1, 4)$","$(2, 4)$","$(1, 5)$","$(3, 5)$"]', '$(1, 5)$', NULL, 'A slope of 2 means up 2 for each 1 to the right. From $(0, 3)$, 1 to the right is $x = 1$ and 2 up is $y = 5$. The point is $(1, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0 + 1, 3 + 2) = (1, 5).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360a3398-e671-4bea-899a-a8eb08824ca1', 'NC26.8.ANFR.3', 1, 'numeric', 'Graph a line: points, intercepts and steepness', 'The line $y = 3x - 12$ crosses the $x$-axis at the point $(a, 0)$. What is $a$?', '[]', '4', '12/3', 'On the $x$-axis $y = 0$. Set $3x - 12 = 0$, so $3x = 12$ and $x = 4$. So $a = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a - 12 = 0, a = 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c33620f-4384-4cd6-a6f5-8c57c43409b6', 'NC26.8.ANFR.3', 1, 'choice', 'Graph a line: points, intercepts and steepness', 'The line $y = 3x$ passes through the origin. Which point is also on this line?', '["$(12, 4)$","$(4, 12)$","$(4, 7)$","$(4, 3)$"]', '$(4, 12)$', NULL, 'When $x = 4$, $y = 3 \times 4 = 12$, so $(4, 12)$ is on the line. The point $(12, 4)$ has its coordinates the wrong way round.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3(4) = 12: (4, 12).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('878ecee4-46cd-4087-94af-0aa279e69563', 'NC26.8.ANFR.3', 1, 'choice', 'Compare two linear functions shown in different ways', 'Function A is $y = 4x + 1$. Function B has the $(x, y)$ pairs $(0, 2)$, $(1, 5)$ and $(2, 8)$. Which statement is true?', '["Function B has the greater slope","The two functions have the same slope","Function A has the greater $y$-intercept","Function A has the greater slope"]', 'Function A has the greater slope', NULL, 'The slope of A is 4. For B, $y$ goes up by 3 each time $x$ goes up by 1, so its slope is 3. The $y$-intercepts are 1 for A and 2 for B (the value at $x = 0$), so B has the greater $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"Function A has the greater slope","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: slope 4, intercept 1. B: slope 3, intercept 2. A has the greater slope; B the greater intercept.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef4ab75f-27ff-4382-bdca-6c47cf069996', 'NC26.8.ANFR.3', 1, 'numeric', 'Compare two linear functions shown in different ways', 'Function A is $y = 3x + 2$. Function B has a slope of 5 and a $y$-intercept of $-1$. How much greater is the slope of Function B than the slope of Function A?', '[]', '2', '5-3', 'The slope of A is 3 and the slope of B is 5, so B''s slope is $5 - 3 = 2$ greater.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 3 = 2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36cee51b-5b41-419e-8000-38781189e6db', 'NC26.8.ANFR.3', 1, 'choice', 'Compare two linear functions shown in different ways', 'Function A is $y = 2x + 9$. Function B is the line through $(0, 12)$ and $(1, 14)$. Function C is the line through $(0, 7)$ and $(3, 13)$. Which function has the greatest $y$-intercept?', '["Function B","Function A","Function C","All three have the same $y$-intercept"]', 'Function B', NULL, 'Function A has a $y$-intercept of 9. Function B passes through $(0, 12)$, so its $y$-intercept is 12. Function C passes through $(0, 7)$, so its is 7. The greatest is 12, Function B.', 'checked', '{"lint":[],"solve":{"answer":"Function B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercepts: A 9, B 12, C 7. Greatest is B.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
