INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c84ae9e2-f0aa-4545-be0f-e7bee119f8de', 'NC26.8.ANFR.3', 1, 'numeric', 'Compare two linear functions shown in different ways', 'Gym A charges 30 dollars to join and 10 dollars per month. Gym B charges 50 dollars to join and 5 dollars per month. How many dollars more is the joining fee at Gym B than at Gym A?', '[]', '20', '50-30', 'The joining fees are 30 and 50 dollars, so Gym B charges $50 - 30 = 20$ dollars more to join.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 30 = 20.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
