INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('033fa2fd-7664-44fe-ba3f-f614ed509ec9', 'NC26.8.ANFR.3', 1, 'choice', 'Rewrite an equation in slope-intercept form', 'Which equation is $y - 3 = 2x$ written in the form $y = mx + b$?', '["$y = 2x - 3$","$y = 2x + 3$","$y = -2x + 3$","$y = 3x + 2$"]', '$y = 2x + 3$', NULL, 'Add 3 to both sides: $y = 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 3: y = 2x + 3.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
