INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46d1a625-5871-4e59-a8a5-d4475c01c8bd', 'NC26.8.ANFR.3', 1, 'choice', 'Rewrite an equation in slope-intercept form', 'The equation $2x + y = 9$ can be written as $y = mx + b$. What is $m$?', '["-2","2","9","-9"]', '-2', '-2', 'Subtract $2x$ from both sides: $y = -2x + 9$. So $m = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -2x + 9, m = -2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
