INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a820287-334d-4be2-878e-f32ad3243ac8', 'NC26.8.ANFR.3', 2, 'numeric', 'Find the slope of the line through two points', 'What is the slope of the line through the points $(2, 9)$ and $(5, 0)$?', '[]', '-3', '(0-9)/(5-2)', 'Slope is the change in $y$ divided by the change in $x$: $\frac{0 - 9}{5 - 2} = \frac{-9}{3} = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (0 - 9)/(5 - 2) = -9/3 = -3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a4cb05e-e921-4ef7-8978-f87ed029ded0', 'NC26.8.ANFR.3', 2, 'choice', 'Interpret the slope of a linear model in context', 'A plumber''s charge in dollars is given by $y = 45x + 30$, where $x$ is the number of hours worked. What does the 45 tell us?', '["A fixed fee charged once for coming to the job","The total charge for 30 hours of work","The number of hours worked","The charge for each hour of work"]', 'The charge for each hour of work', NULL, 'The slope 45 is the change in the charge for each 1 hour of work. The 30 is the fixed fee, charged even for 0 hours.', 'checked', '{"lint":[],"solve":{"answer":"The charge for each hour of work","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In y = 45x + 30, 45 multiplies the hours, so it is the rate per hour; 30 is the fixed fee.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e62970f-b1d8-4a08-90d0-258605705147', 'NC26.8.ANFR.3', 2, 'choice', 'Find the equation of a linear function from a list of pairs', 'A linear function has these $(x, y)$ pairs: (0, 4), (2, 10), (4, 16). Which equation matches it?', '["$y = 6x + 4$","$y = 3x + 4$","$y = 4x + 3$","$y = 3x - 4$"]', '$y = 3x + 4$', NULL, 'When $x = 0$, $y = 4$, so the $y$-intercept is 4. When $x$ goes up by 2, $y$ goes up by 6, so the slope is $\frac{6}{2} = 3$. The equation is $y = 3x + 4$. Check: $x = 4$ gives $3(4) + 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (10 - 4)/(2 - 0) = 3; intercept 4 (from (0,4)). y = 3x + 4. Check (4,16): 12 + 4 = 16.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfb4fa4c-0b22-4a77-9083-6936382d99de', 'NC26.8.ANFR.3', 2, 'numeric', 'Identify a linear function and its form', 'How many of these equations are linear? $2x + y = 6$, $y = x^2 + 2x$, $3y = 2x + 9$, $y = 4^x$, $y - x = 8$', '[]', '3', '1+0+1+0+1', 'An equation is linear when it can be written as $y = mx + b$. The equations $2x + y = 6$, $3y = 2x + 9$ and $y - x = 8$ can all be rearranged that way. The equations with $x^2$ and $4^x$ cannot. So 3 are linear.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + y = 6 (y = -2x + 6) linear; y = x^2 + 2x not; 3y = 2x + 9 linear; y = 4^x not; y - x = 8 linear. 3.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c323675-5555-4fa9-9720-cdd458fcaffd', 'NC26.8.ANFR.3', 2, 'choice', 'Identify a linear function and its form', 'A table gives the $x$-values 2, 4, 6 and 8 and the $y$-values 1, 4, 9 and 16. Which statement is correct?', '["It is linear, because $y$ keeps increasing","It is not linear, because $y$ goes up by a different amount each time","It is linear, because $x$ increases by 2 each time","It is linear, because $y$ starts at 1"]', 'It is not linear, because $y$ goes up by a different amount each time', NULL, 'The input goes up by 2 each time, but $y$ goes up by 3, then 5, then 7. The change is not constant, so the function is not linear. An increasing output or a steady step in $x$ is not enough.', 'checked', '{"lint":[],"solve":{"answer":"It is not linear, because $y$ goes up by a different amount each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x steps by 2; y changes 3, 5, 7: unequal changes for equal x steps, so not linear.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbe610b1-d1e2-4116-9aee-0ce5ec4186e2', 'NC26.8.ANFR.3', 2, 'numeric', 'Read the slope and y-intercept from an equation', 'A line has the equation $y = 8 - 5x$. By how much does $y$ change when $x$ increases by 1? Use a negative number if $y$ goes down.', '[]', '-5', '-5', 'Rewrite as $y = -5x + 8$. The slope is $-5$, so each time $x$ goes up by 1, $y$ changes by $-5$. It goes down by 5.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -5x + 8: slope -5, so y changes by -5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a42c67c9-d88e-4c60-a6a4-346348254bbe', 'NC26.8.ANFR.3', 2, 'choice', 'Read the slope and y-intercept from an equation', 'Which pair gives the slope and the $y$-intercept of the line $y = 6 - \frac{2}{3}x$?', '["Slope 6, $y$-intercept $-\\frac{2}{3}$","Slope $-\\frac{2}{3}$, $y$-intercept 6","Slope $\\frac{2}{3}$, $y$-intercept 6","Slope $-\\frac{2}{3}$, $y$-intercept $-6$"]', 'Slope $-\frac{2}{3}$, $y$-intercept 6', NULL, 'Write the equation as $y = -\frac{2}{3}x + 6$. The number multiplying $x$ is the slope, $-\frac{2}{3}$, and the number added is the $y$-intercept, 6. The order of the terms does not change which is which.', 'checked', '{"lint":[],"solve":{"answer":"Slope $-\\frac{2}{3}$, $y$-intercept 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -(2/3)x + 6: slope -2/3, y-intercept 6.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6badc36-6e09-4020-aab0-8302c352279c', 'NC26.8.ANFR.3', 2, 'numeric', 'Read the slope and y-intercept from an equation', 'A line is given by $y = 0.5x - 7.5$. What is the value of $y$ where the line meets the $y$-axis?', '[]', '-7.5', '-7.5', 'The line meets the $y$-axis where $x = 0$. Then $y = 0.5 \times 0 - 7.5 = -7.5$. This is the $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"-7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = -7.5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4837216-2112-4370-982f-40a69e57e6f2', 'NC26.8.ANFR.3', 2, 'choice', 'Write the equation of a line in slope-intercept form', 'A linear function has the $(x, y)$ pairs $(1, 5)$, $(2, 8)$ and $(3, 11)$. Which equation matches it?', '["$y = 3x + 5$","$y = 3x + 2$","$y = 3x - 1$","$y = 2x + 3$"]', '$y = 3x + 2$', NULL, '$y$ goes up by 3 each time $x$ goes up by 1, so the slope is 3. Then $y = 3x + b$; with $(1, 5)$, $5 = 3 + b$ and $b = 2$. The equation $y = 2x + 3$ fits $(1, 5)$ but not $(2, 8)$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (8-5)/1 = 3; 5 = 3(1) + b, b = 2: y = 3x + 2. Check (3, 11).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa8a1de2-6552-4a5d-8963-c3d4884b3e59', 'NC26.8.ANFR.3', 2, 'numeric', 'Write the equation of a line in slope-intercept form', 'A line passes through $(0, -5)$ and $(3, 1)$. What is the value of $y$ on this line when $x = 10$?', '[]', '15', '(1-(-5))/3*10-5', 'The slope is $\frac{1 - (-5)}{3 - 0} = 2$ and the $y$-intercept is $-5$, so $y = 2x - 5$. When $x = 10$, $y = 2 \times 10 - 5 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (1 - (-5))/3 = 2; y = 2x - 5; at x = 10, y = 15.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8978b55-c655-4be4-8af0-5424f0ba9a83', 'NC26.8.ANFR.3', 2, 'choice', 'Write the equation of a line in slope-intercept form', 'A candle is 30 centimeters tall and burns down 2 centimeters each hour. Which equation gives its height $h$, in centimeters, after $t$ hours?', '["$h = 2t - 30$","$h = 30 + 2t$","$h = 2 - 30t$","$h = 30 - 2t$"]', '$h = 30 - 2t$', NULL, 'The candle starts at 30 centimeters and loses 2 centimeters each hour, so $h = 30 - 2t$.', 'checked', '{"lint":[],"solve":{"answer":"$h = 30 - 2t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Starts 30, decreases 2 per hour: h = 30 - 2t.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26549524-de8d-4388-8029-41c867d4314f', 'NC26.8.ANFR.3', 2, 'choice', 'Find the slope of a line from points or a table', 'What is the slope of the line through $(-2, 4)$ and $(6, -12)$?', '["-2","2","-1/2","-8"]', '-2', '(-12-4)/(6-(-2))', 'Slope = $\frac{-12 - 4}{6 - (-2)} = \frac{-16}{8} = -2$. Be careful with the signs when subtracting negative numbers.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-12 - 4)/(6 - (-2)) = -16/8 = -2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
