INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11e1ed56-0410-49a5-9f28-09bfa5b49e0f', 'NC26.8.ANFR.3', 2, 'choice', 'Find the slope of a line from points or a table', 'A table gives the $x$-values 2, 4, 6 and 8 and the $y$-values 11, 8, 5 and 2 of a linear function. What is the slope?', '["$-3$","$\\frac{3}{2}$","$-\\frac{3}{2}$","$-\\frac{2}{3}$"]', '$-\frac{3}{2}$', NULL, 'When $x$ goes up by 2, $y$ changes by $-3$. The slope is the change in $y$ over the change in $x$: $\frac{-3}{2} = -\frac{3}{2}$. The choice $-3$ forgets that $x$ went up by 2 each time.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y drops 3 when x rises 2: slope -3/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('685459e6-8104-4b37-9bdf-d2688d4ed71f', 'NC26.8.ANFR.3', 2, 'numeric', 'Find the slope of a line from points or a table', 'A line passes through $(3, -1)$ and $(7, 5)$. What is its slope?', '[]', '3/2', '(5-(-1))/(7-3)', 'Slope = $\frac{5 - (-1)}{7 - 3} = \frac{6}{4} = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5 - (-1))/(7 - 3) = 6/4 = 3/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab3f7df7-60c1-40fb-9933-602902b1b4b4', 'NC26.8.ANFR.3', 2, 'numeric', 'Find the y-intercept from a slope and a point, or from points', 'A linear function has the $x$-values 2, 4 and 6 with the $y$-values 11, 17 and 23. What is its $y$-intercept?', '[]', '5', '11-(17-11)/(4-2)*2', 'The slope is $\frac{17 - 11}{4 - 2} = 3$. Going back from $x = 2$ to $x = 0$ takes 2 steps of 3, so $y$ at $x = 0$ is $11 - 6 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 6/2 = 3; 11 = 3(2) + b, b = 5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60e10ded-e44b-4503-8d1c-742de4494074', 'NC26.8.ANFR.3', 2, 'numeric', 'Find the y-intercept from a slope and a point, or from points', 'A plant is 14 centimeters tall after 3 weeks and grows 2 centimeters each week. How tall, in centimeters, was it at the start (week 0)?', '[]', '8', '14-2*3', 'In 3 weeks the plant grew $3 \times 2 = 6$ centimeters. So at the start it was $14 - 6 = 8$ centimeters tall.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 - 3(2) = 8.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16395e33-a9f9-4f56-ab0b-7a2814b9270a', 'NC26.8.ANFR.3', 2, 'choice', 'Find the y-intercept from a slope and a point, or from points', 'A line passes through $(1, 4)$ and $(3, 10)$. What is its $y$-intercept?', '["3","7","10","1"]', '1', '4-(10-4)/(3-1)*1', 'The slope is $\frac{10 - 4}{3 - 1} = 3$. Using $y = 3x + b$ and the point $(1, 4)$: $4 = 3 + b$, so $b = 1$. The choice 3 is the slope, not the $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (10-4)/2 = 3; 4 = 3 + b, b = 1.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('333740d7-dfdb-4e16-83c4-a9361cd212f7', 'NC26.8.ANFR.3', 2, 'choice', 'Interpret the slope and y-intercept in a situation', 'A car''s distance from home after $x$ hours is $y = 55x + 20$ miles. Which statement is true?', '["The car started 55 miles from home and moves away at 20 miles per hour","The car started at home and moves away at 75 miles per hour","The car started 20 miles from home and moves away at 55 miles per hour","The car started 20 miles from home and moves toward home at 55 miles per hour"]', 'The car started 20 miles from home and moves away at 55 miles per hour', NULL, 'The $y$-intercept, 20, is the starting distance. The slope, 55, is the speed. It is positive, so the car moves away from home.', 'checked', '{"lint":[],"solve":{"answer":"The car started 20 miles from home and moves away at 55 miles per hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercept 20 (start 20 miles away), slope +55 (distance grows 55 per hour, moving away).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25befd4a-d6aa-48f2-8fb8-3f0b34e90f83', 'NC26.8.ANFR.3', 2, 'numeric', 'Interpret the slope and y-intercept in a situation', 'A candle''s height is $y = 24 - 1.5x$ centimeters after $x$ hours. After how many hours has the candle burned out completely (when $y = 0$)?', '[]', '16', '24/1.5', 'Set $24 - 1.5x = 0$. Then $1.5x = 24$ and $x = 24 \div 1.5 = 16$ hours.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 - 1.5x = 0, x = 16.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23e7ada5-f68c-4d78-8ebf-e8e193235ef6', 'NC26.8.ANFR.3', 2, 'numeric', 'Interpret the slope and y-intercept in a situation', 'A school collects cans. After $x$ days the total number of cans is $y = 12x + 30$. How many more cans are collected in 9 days than in 4 days?', '[]', '60', '(12*9+30)-(12*4+30)', 'After 9 days: $12 \times 9 + 30 = 138$ cans. After 4 days: $12 \times 4 + 30 = 78$ cans. The difference is $138 - 78 = 60$ cans. (It is also 5 more days at 12 cans a day.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12(9) + 30 - (12(4) + 30) = 12(5) = 60.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40385f9c-9e94-4e79-a2a1-62a699950d28', 'NC26.8.ANFR.3', 2, 'numeric', 'Interpret the slope and y-intercept in a situation', 'A shop''s profit was 120 dollars on day 2 and 180 dollars on day 5, and it grew by the same amount each day. By how many dollars did the profit grow each day?', '[]', '20', '(180-120)/(5-2)', 'The profit grew by $180 - 120 = 60$ dollars over $5 - 2 = 3$ days. That is $60 \div 3 = 20$ dollars a day.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(180 - 120)/(5 - 2) = 60/3 = 20.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b77fe09a-d3ea-4d07-b78c-920880fbc9d7', 'NC26.8.ANFR.3', 2, 'choice', 'Graph a line: points, intercepts and steepness', 'Which line is the steepest?', '["$y = -5x + 2$","$y = 3x + 1$","$y = \\frac{x}{2} + 8$","$y = 4x - 7$"]', '$y = -5x + 2$', NULL, 'The steepness of a line is the size of its slope, ignoring the sign. The slopes are $-5$, 3, $\frac{1}{2}$ and 4. The line with the biggest size is $-5$, which is steep and goes down.', 'checked', '{"lint":[],"solve":{"answer":"$y = -5x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Steepness means the absolute value of the slope; a student who reads \"steepest\" as \"greatest slope\" picks y = 4x - 7. Correct as written, but it hinges on that distinction.","work":"Steepness is the size of the slope: |3| = 3, 1/2, |-5| = 5, 4. Steepest is y = -5x + 2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24924cba-a6c6-4861-b381-6d76b58a442b', 'NC26.8.ANFR.3', 2, 'numeric', 'Graph a line: points, intercepts and steepness', 'A line passes through $(1, 4)$ and has a slope of 3. What is the $y$-value of the point on the line where $x = 6$?', '[]', '19', '4+3*(6-1)', 'From $x = 1$ to $x = 6$ is 5 steps to the right. Each step raises $y$ by 3, so $y$ goes up $5 \times 3 = 15$ from 4 to 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 4 + 3(6 - 1) = 19.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d98d9f8e-d73c-4f9d-8d0d-f4cc2f2a9839', 'NC26.8.ANFR.3', 2, 'choice', 'Graph a line: points, intercepts and steepness', 'Which point is NOT on the line $y = -2x + 6$?', '["$(0, 6)$","$(3, 0)$","$(4, -3)$","$(5, -4)$"]', '$(4, -3)$', NULL, 'Test each point. For $x = 4$ the equation gives $y = -8 + 6 = -2$, not $-3$, so $(4, -3)$ is not on the line. The points $(0, 6)$, $(3, 0)$ and $(5, -4)$ all fit.', 'checked', '{"lint":[],"solve":{"answer":"$(4, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0,6): 6 yes. (4,-3): -8 + 6 = -2, not -3. (3,0): 0 yes. (5,-4): -10 + 6 = -4 yes. Not on the line: (4, -3).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('608f2b53-489f-46a2-b4f4-553081189674', 'NC26.8.ANFR.3', 2, 'numeric', 'Graph a line: points, intercepts and steepness', 'A line crosses the $y$-axis at $(0, 8)$ and the $x$-axis at $(4, 0)$. What is its slope?', '[]', '-2', '(0-8)/(4-0)', 'Slope = $\frac{0 - 8}{4 - 0} = \frac{-8}{4} = -2$. The line goes down as $x$ goes up.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0 - 8)/(4 - 0) = -2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
