INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a8644e6-e9fa-4664-83be-5eced161b57a', 'NC26.8.ANFR.3', 2, 'numeric', 'Graph a line: points, intercepts and steepness', 'The graph of $y = -2x + 10$ meets the $x$-axis where $x$ equals what number?', '[]', '5', '10/2', 'On the $x$-axis $y = 0$. Set $-2x + 10 = 0$. Then $2x = 10$ and $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 10 = 0, x = 5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
