INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de03f338-8adc-44ab-8313-31f0f3d2677f', 'NC26.8.ANFR.3', 2, 'choice', 'Compare two linear functions shown in different ways', 'Bike shop A charges $y = 8x + 5$ dollars for $x$ hours. Shop B charges a 10 dollar fee plus 6 dollars for each hour. For a 4-hour rental, which shop is cheaper, and by how much?', '["Shop A, by 3 dollars","Shop B, by 3 dollars","Shop B, by 5 dollars","Shop A, by 5 dollars"]', 'Shop B, by 3 dollars', NULL, 'Shop A: $8 \times 4 + 5 = 37$ dollars. Shop B: $10 + 6 \times 4 = 34$ dollars. Shop B is cheaper by $37 - 34 = 3$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"Shop B, by 3 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 8(4) + 5 = 37. B: 10 + 6(4) = 34. B cheaper by 3.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f758766-daca-4959-8fd5-bb5fc55d5f52', 'NC26.8.ANFR.3', 2, 'choice', 'Compare two linear functions shown in different ways', 'Car A''s distance is $d = 50t$ miles after $t$ hours. Car B travels 60 miles in 1 hour, 120 miles in 2 hours and 180 miles in 3 hours at a steady speed. Which car is faster, and by how much?', '["Car A, by 10 miles per hour","Car B, by 60 miles per hour","Car B, by 10 miles per hour","Car A, by 50 miles per hour"]', 'Car B, by 10 miles per hour', NULL, 'Car A''s speed is the slope of $d = 50t$, which is 50 miles per hour. Car B goes 60 miles each hour, so its speed is 60 miles per hour. Car B is faster by $60 - 50 = 10$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"Car B, by 10 miles per hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 50 mph. B: 60 mph. B faster by 10.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e924a15f-9ed4-4562-a2f2-901a4f406785', 'NC26.8.ANFR.3', 2, 'numeric', 'Compare two linear functions shown in different ways', 'Function A is $y = -3x + 6$. Function B has the $(x, y)$ pairs $(0, 10)$, $(2, 8)$ and $(4, 6)$. How much greater is the $y$-intercept of Function B than the $y$-intercept of Function A?', '[]', '4', '10-6', 'The $y$-intercept of A is 6. The $y$-intercept of B is the value of $y$ at $x = 0$, which is 10. The difference is $10 - 6 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A intercept 6, B intercept 10 (pair (0, 10)). 10 - 6 = 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88b341a4-1d23-4e82-bc7a-8ba3f6a27006', 'NC26.8.ANFR.3', 2, 'numeric', 'Rewrite an equation in slope-intercept form', 'What is the slope of the line $2y = 8x + 6$?', '[]', '4', '8/2', 'Divide both sides by 2: $y = 4x + 3$. The slope is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 4x + 3, slope 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9c7883a-7c8d-4343-a72a-a403b836f0ab', 'NC26.8.ANFR.3', 2, 'choice', 'Rewrite an equation in slope-intercept form', 'Which equation is $3x + 2y = 12$ written in slope-intercept form?', '["$y = \\frac{3}{2}x + 6$","$y = -3x + 6$","$y = -\\frac{3}{2}x + 12$","$y = -\\frac{3}{2}x + 6$"]', '$y = -\frac{3}{2}x + 6$', NULL, 'Subtract $3x$: $2y = -3x + 12$. Then divide everything by 2: $y = -\frac{3}{2}x + 6$. Dividing only one term is the usual mistake.', 'checked', '{"lint":[],"solve":{"answer":"$y = -\\frac{3}{2}x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2y = -3x + 12, y = -(3/2)x + 6.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d81abe9-a597-4d58-9a52-0f291bb31b5b', 'NC26.8.ANFR.3', 2, 'numeric', 'Rewrite an equation in slope-intercept form', 'What is the $y$-intercept of the line $x - y = 5$?', '[]', '-5', '-5', 'Solve for $y$. Subtract $x$: $-y = -x + 5$. Multiply by $-1$: $y = x - 5$. The $y$-intercept is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = x - 5, y-intercept -5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('738858c2-92f9-450b-a2c6-03ecb376e0c2', 'NC26.8.ANFR.3', 2, 'numeric', 'Rewrite an equation in slope-intercept form', 'The equation of a line is $y = \frac{6x + 9}{3}$. What is the sum of its slope and its $y$-intercept?', '[]', '5', '6/3+9/3', 'Divide each term by 3: $y = 2x + 3$. The slope is 2 and the $y$-intercept is 3, so their sum is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2x + 3: slope 2 + intercept 3 = 5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1835b01-541b-44a4-9c8c-7206463f4a4f', 'NC26.8.ANFR.3', 3, 'numeric', 'Compare the rates of change of two linear functions shown in different ways', 'Function A is $y = 5x - 1$. Function B is the line through the points $(1, 2)$ and $(4, 11)$. How much greater is the slope of Function A than the slope of Function B?', '[]', '2', '5-(11-2)/(4-1)', 'The slope of A is 5. The slope of B is $\frac{11 - 2}{4 - 1} = \frac{9}{3} = 3$. The difference is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope A = 5. Slope B = (11 - 2)/(4 - 1) = 9/3 = 3. Difference 5 - 3 = 2.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba59d9de-7544-4f44-9bf0-932eaadf80fc', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the y-intercept of a line from its slope and one point', 'A line has slope $-3$ and passes through the point $(4, 1)$. What is its $y$-intercept?', '[]', '13', '1+3*4', 'Write $y = -3x + b$. Put in the point: $1 = -3(4) + b = -12 + b$. Then $b = 1 + 12 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -3x + b; 1 = -3(4) + b = -12 + b -> b = 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af4a0305-d0d7-49aa-82d3-9d978c782b05', 'NC26.8.ANFR.3', 3, 'numeric', 'Find where a line crosses the x-axis', 'At what value of $x$ does the line $y = \frac{3}{4}x - 6$ cross the $x$-axis?', '[]', '8', '6/(3/4)', 'The line crosses the $x$-axis where $y = 0$: $0 = \frac{3}{4}x - 6$. Add 6: $\frac{3}{4}x = 6$. Multiply by $\frac{4}{3}$: $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Crosses x-axis where y = 0: (3/4)x = 6 -> x = 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014b7a82-a5e0-46fe-b0ca-9eb9c83c28e2', 'NC26.8.ANFR.3', 3, 'numeric', 'Identify a linear function and its form', 'A linear function has the $(x, y)$ pairs $(1, 5)$, $(3, 11)$, $(4, 14)$ and $(8, k)$. What is $k$?', '[]', '26', '14+(11-5)/(3-1)*(8-4)', 'The rate of change is constant: from $x = 1$ to $x = 3$ the output goes up by 6 in 2 steps, which is 3 per step. From $x = 4$ to $x = 8$ there are 4 steps, so the output goes up by $4 \times 3 = 12$ to $14 + 12 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-5)/(3-1) = 3; y = 3x + 2 (check (4,14)). k = 3(8) + 2 = 26.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f75066e-888a-455d-807f-e1f3e4a52343', 'NC26.8.ANFR.3', 3, 'choice', 'Identify a linear function and its form', 'Which three points lie on one straight line?', '["$(0, 1), (2, 5), (3, 8)$","$(0, 0), (1, 2), (2, 5)$","$(2, 1), (4, 2), (8, 5)$","$(1, 2), (3, 8), (5, 14)$"]', '$(1, 2), (3, 8), (5, 14)$', NULL, 'Three points lie on a line when the slope between the first two equals the slope between the next two. For $(1, 2), (3, 8), (5, 14)$ both slopes are 3. In the others the slopes differ: 2 and 3; 2 and 3; $\frac{1}{2}$ and $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 2), (3, 8), (5, 14)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: slopes 6/2 = 3 and 6/2 = 3, collinear. B: 2 then 3. C: 1/2 then 3/4. D: 2 then 3. Only A.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbd545dc-a746-4caf-8832-76c625d7cb1d', 'NC26.8.ANFR.3', 3, 'choice', 'Identify a linear function and its form', 'Which statement is true about the function $y = 5 - 2(x - 3)$?', '["It is linear, with slope $-2$ and $y$-intercept 5","It is linear, with slope $-2$ and $y$-intercept $-1$","It is linear, with slope 2 and $y$-intercept 11","It is linear, with slope $-2$ and $y$-intercept 11"]', 'It is linear, with slope $-2$ and $y$-intercept 11', NULL, 'Distribute the $-2$: $5 - 2(x - 3) = 5 - 2x + 6 = -2x + 11$. So the slope is $-2$ and the $y$-intercept is 11. Forgetting that $-2 \times (-3) = 6$ gives the wrong intercept.', 'checked', '{"lint":[],"solve":{"answer":"It is linear, with slope $-2$ and $y$-intercept 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 5 - 2x + 6 = -2x + 11: slope -2, y-intercept 11.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b47ab66f-273f-4357-8cd9-98657ac90074', 'NC26.8.ANFR.3', 3, 'choice', 'Read the slope and y-intercept from an equation', 'Which equation has a slope that is 4 greater than the slope of $y = -3x + 1$ and has the same $y$-intercept?', '["$y = 4x + 1$","$y = -7x + 1$","$y = x + 5$","$y = x + 1$"]', '$y = x + 1$', NULL, 'The slope of $y = -3x + 1$ is $-3$, and $-3 + 4 = 1$. The $y$-intercept stays 1. So the equation is $y = 1x + 1 = x + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$y = x + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope -3 + 4 = 1, intercept 1: y = x + 1.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3652723-6afd-4111-b808-88a6ac1489c1', 'NC26.8.ANFR.3', 3, 'numeric', 'Read the slope and y-intercept from an equation', 'For what value of $k$ does the line $y = (k - 2)x + 7$ have a slope of $-4$?', '[]', '-2', '-4+2', 'The slope is the number multiplying $x$, which is $k - 2$. Set $k - 2 = -4$. Add 2: $k = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k - 2 = -4, k = -2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8b46df9-d833-4cef-b504-5e3585ab56a3', 'NC26.8.ANFR.3', 3, 'numeric', 'Read the slope and y-intercept from an equation', 'The line $y = mx + m$ passes through the point $(2, 12)$. What is its slope $m$?', '[]', '4', '12/3', 'Put $x = 2$ and $y = 12$ into the equation: $12 = 2m + m = 3m$. So $m = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2m + m = 3m, m = 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de5d74a5-f1b5-4ba2-a7fb-1b8c98c8d9b2', 'NC26.8.ANFR.3', 3, 'choice', 'Write the equation of a line in slope-intercept form', 'A line passes through $(0, 8)$ and has the same slope as the line through $(1, 2)$ and $(3, 8)$. Which equation represents the line?', '["$y = 3x + 8$","$y = 8x + 3$","$y = 3x + 2$","$y = 6x + 8$"]', '$y = 3x + 8$', NULL, 'The slope of the line through $(1, 2)$ and $(3, 8)$ is $\frac{8 - 2}{3 - 1} = 3$. The new line has slope 3 and $y$-intercept 8, so $y = 3x + 8$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (8-2)/(3-1) = 3; through (0, 8): y = 3x + 8.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a2a5da7-33e7-4981-9248-7b7d02ac47ed', 'NC26.8.ANFR.3', 3, 'numeric', 'Write the equation of a line in slope-intercept form', 'A line has the same slope as $y = 2x + 1$ and the same $y$-intercept as $y = 5 - 3x$. What is the value of $y$ on that line when $x = 4$?', '[]', '13', '2*4+5', 'The slope of $y = 2x + 1$ is 2. The $y$-intercept of $y = 5 - 3x$ is 5. So the line is $y = 2x + 5$, and when $x = 4$, $y = 2 \times 4 + 5 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 2, intercept 5: y = 2x + 5; at x = 4, y = 13.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5619d1aa-5c39-496d-b709-0d60b5e038da', 'NC26.8.ANFR.3', 3, 'choice', 'Write the equation of a line in slope-intercept form', 'A line passes through $(0, -2)$ and $(4, 4)$. Which equation represents the line?', '["$y = \\frac{2}{3}x - 2$","$y = \\frac{3}{2}x + 2$","$y = \\frac{3}{2}x - 2$","$y = 6x - 2$"]', '$y = \frac{3}{2}x - 2$', NULL, 'The slope is $\frac{4 - (-2)}{4 - 0} = \frac{6}{4} = \frac{3}{2}$. The line crosses the $y$-axis at $-2$. So $y = \frac{3}{2}x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{3}{2}x - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (4 - (-2))/(4 - 0) = 6/4 = 3/2; intercept -2: y = (3/2)x - 2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e4b050-ebb7-4605-9293-39ced787b2cb', 'NC26.8.ANFR.3', 3, 'numeric', 'Write the equation of a line in slope-intercept form', 'A phone plan costs 15 dollars a month plus 0.10 dollars for each text. The monthly cost is $y = 0.10x + 15$ dollars for $x$ texts. One month the bill is 23 dollars. How many texts were sent?', '[]', '80', '(23-15)/0.1', 'Set $0.10x + 15 = 23$. Subtract 15: $0.10x = 8$. Divide by 0.10: $x = 80$ texts.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.10x + 15 = 23, 0.10x = 8, x = 80.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4427af65-a8d2-4fd0-b790-d024e7c0102e', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the slope of a line from points or a table', 'A line through $(a, 3)$ and $(5, 11)$ has a slope of 2. What is $a$?', '[]', '1', '5-(11-3)/2', 'Slope = $\frac{11 - 3}{5 - a} = 2$, so $\frac{8}{5 - a} = 2$ and $5 - a = 4$. Then $a = 1$. Check: from $(1, 3)$ to $(5, 11)$ the rise is 8 and the run is 4, so the slope is 2.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(11 - 3)/(5 - a) = 2, so 5 - a = 4, a = 1.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdbe0fd9-9c32-4f2d-bd22-743bb3502337', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the slope of a line from points or a table', 'The line through $(-3, 2)$ and $(1, k)$ has a slope of $\frac{3}{4}$. What is $k$?', '[]', '5', '2+(3/4)*(1-(-3))', 'From $x = -3$ to $x = 1$ the run is 4. The rise is $\frac{3}{4} \times 4 = 3$, so $k = 2 + 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k - 2)/(1 - (-3)) = (k - 2)/4 = 3/4, so k - 2 = 3, k = 5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb99f9bc-915d-4921-9282-071648f2bf35', 'NC26.8.ANFR.3', 3, 'choice', 'Find the slope of a line from points or a table', 'Each line below passes through the two points given. Which line has the greatest slope?', '["$(0, 4)$ and $(5, 6)$","$(1, 1)$ and $(3, 7)$","$(2, 9)$ and $(4, 1)$","$(-1, -1)$ and $(1, 2)$"]', '$(1, 1)$ and $(3, 7)$', NULL, 'The slopes are $\frac{7 - 1}{3 - 1} = 3$; $\frac{6 - 4}{5 - 0} = \frac{2}{5}$; $\frac{1 - 9}{4 - 2} = -4$; and $\frac{2 - (-1)}{1 - (-1)} = \frac{3}{2}$. The greatest is 3.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 1)$ and $(3, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2/5. B: 6/2 = 3. C: 3/2. D: -8/2 = -4. Greatest 3: B.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d753dfe-7aec-49e2-a060-d332b33654be', 'NC26.8.ANFR.3', 3, 'choice', 'Find the y-intercept from a slope and a point, or from points', 'A line passes through $(-2, 9)$ and $(4, -3)$. What is its $y$-intercept?', '["13","5","-5","-2"]', '5', '9-(-3-9)/(4-(-2))*(-2)', 'The slope is $\frac{-3 - 9}{4 - (-2)} = \frac{-12}{6} = -2$. Using $y = -2x + b$ and $(-2, 9)$: $9 = -2 \times (-2) + b = 4 + b$, so $b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (-3 - 9)/(4 - (-2)) = -12/6 = -2; 9 = -2(-2) + b = 4 + b, b = 5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a6ea6d3-ffc5-447b-a936-b016e55add5a', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the y-intercept from a slope and a point, or from points', 'The graph of a linear function climbs 3 units for every 4 units it goes to the right, and it includes the point $(8, 1)$. At what value of $y$ does the graph cross the $y$-axis?', '[]', '-5', '1-(3/4)*8', 'Use $y = \frac{3}{4}x + b$ with $(8, 1)$: $1 = \frac{3}{4} \times 8 + b = 6 + b$. So $b = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 3/4; 1 = (3/4)(8) + b = 6 + b, b = -5.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8adda506-fe44-44a0-902c-6cd7cd6b9294', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the y-intercept from a slope and a point, or from points', 'A line crosses the $y$-axis at $-1$ and also passes through $(4, 5)$. What is its slope?', '[]', '3/2', '(5-(-1))/4', 'The line also passes through $(0, -1)$. Going from $(0, -1)$ to $(4, 5)$ the rise is 6 and the run is 4, so the slope is $\frac{6}{4} = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Through (0, -1) and (4, 5): slope 6/4 = 3/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61cd8a6c-03b5-4115-8b7f-12824760f2a0', 'NC26.8.ANFR.3', 3, 'numeric', 'Interpret the slope and y-intercept in a situation', 'A plant was 9 centimeters tall after 2 weeks and 21 centimeters tall after 6 weeks, and it grows at a steady rate. How tall, in centimeters, will it be after 10 weeks?', '[]', '33', '21+(21-9)/(6-2)*(10-6)', 'From week 2 to week 6 it grew 12 centimeters in 4 weeks, which is 3 centimeters a week. From week 6 to week 10 is 4 more weeks, so it grows $4 \times 3 = 12$ more centimeters: $21 + 12 = 33$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate (21 - 9)/(6 - 2) = 3 cm/week; at 10 weeks: 21 + 4(3) = 33.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d60375f-3e4d-4935-8c3f-7bf3bb353e1e', 'NC26.8.ANFR.3', 3, 'choice', 'Interpret the slope and y-intercept in a situation', 'A tank drains at a steady rate. It holds 70 liters after 3 minutes and 50 liters after 7 minutes. Which statement is true?', '["It started with 85 liters and loses 5 liters each minute","It started with 70 liters and loses 5 liters each minute","It started with 85 liters and loses 20 liters each minute","It started with 55 liters and gains 5 liters each minute"]', 'It started with 85 liters and loses 5 liters each minute', NULL, 'In 4 minutes the tank lost 20 liters, which is 5 liters each minute. Going back 3 minutes from 70 liters adds $3 \times 5 = 15$ liters, so it held $70 + 15 = 85$ liters at the start.', 'checked', '{"lint":[],"solve":{"answer":"It started with 85 liters and loses 5 liters each minute","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate (50 - 70)/(7 - 3) = -5 L/min; start 70 + 3(5) = 85. Starts 85, loses 5 per minute.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f9bcff1-7dc8-46ab-9d7c-53610813282e', 'NC26.8.ANFR.3', 3, 'choice', 'Interpret the slope and y-intercept in a situation', 'A hot-air balloon''s height is $y = 600 - 40x$ meters after $x$ minutes of descending. What does the point $(15, 0)$ on the line tell us?', '["After 15 minutes the balloon reaches the ground","The balloon starts 15 meters high","The balloon descends 15 meters each minute","The balloon is 600 meters high after 15 minutes"]', 'After 15 minutes the balloon reaches the ground', NULL, 'The point $(15, 0)$ means that when $x = 15$ minutes, the height $y$ is 0 meters. Check: $600 - 40 \times 15 = 0$. So the balloon reaches the ground after 15 minutes.', 'checked', '{"lint":[],"solve":{"answer":"After 15 minutes the balloon reaches the ground","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 15: y = 600 - 600 = 0 height, so it reaches the ground after 15 minutes.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d2a593e-df1b-4d83-a95e-5df88012ce74', 'NC26.8.ANFR.3', 3, 'choice', 'Interpret the slope and y-intercept in a situation', 'The profit from selling $x$ tickets is $y = 9x - 45$ dollars. What does the $-45$ tell us?', '["Each ticket loses 45 dollars","The profit is $-45$ dollars when no tickets are sold","45 tickets must be sold to break even","Each ticket sells for 45 dollars"]', 'The profit is $-45$ dollars when no tickets are sold', NULL, 'The $y$-intercept is the value of $y$ when $x = 0$. With no tickets sold, the profit is $-45$ dollars: the costs are not yet covered. The 9 is the profit per ticket, and break-even happens at $9x - 45 = 0$, which is 5 tickets.', 'checked', '{"lint":[],"solve":{"answer":"The profit is $-45$ dollars when no tickets are sold","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = -45: profit is -45 with no tickets (break-even is 5 tickets, not 45).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7bd83a-d235-4227-bb6c-65d31edb92b1', 'NC26.8.ANFR.3', 3, 'numeric', 'Graph a line: points, intercepts and steepness', 'A line has a slope of $\frac{2}{3}$ and passes through $(6, 5)$. At what value of $x$ does it cross the $x$-axis?', '[]', '-3/2', '6-5/(2/3)', 'The line is $y - 5 = \frac{2}{3}(x - 6)$. It crosses the $x$-axis when $y = 0$: $-5 = \frac{2}{3}(x - 6)$, so $x - 6 = -5 \times \frac{3}{2} = -7.5$ and $x = -1.5$, which is $-\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 = (2/3)(6) + b, b = 1; y = (2/3)x + 1 = 0 gives x = -3/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07a7cfa6-290c-4438-8a61-00ffeaa2c8d3', 'NC26.8.ANFR.3', 3, 'choice', 'Graph a line: points, intercepts and steepness', 'The line $y = mx + 3$ passes through the point $(4, 15)$. Which point is also on this line?', '["$(1, 4)$","$(1, 12)$","$(1, 15)$","$(1, 6)$"]', '$(1, 6)$', NULL, 'Put $(4, 15)$ into the equation: $15 = 4m + 3$, so $4m = 12$ and $m = 3$. The line is $y = 3x + 3$. When $x = 1$, $y = 6$, so $(1, 6)$ is on the line.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = 4m + 3, m = 3; y = 3x + 3, at x = 1, y = 6. (1, 6).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75a9d01e-45e9-4ded-b052-6cb9bbe150b5', 'NC26.8.ANFR.3', 3, 'numeric', 'Graph a line: points, intercepts and steepness', 'A line passes through $(0, 6)$ and $(4, 0)$. What is the $y$-value of the point on the line where $x = 10$?', '[]', '-9', '6+(0-6)/(4-0)*10', 'The slope is $\frac{0 - 6}{4 - 0} = -\frac{3}{2}$ and the $y$-intercept is 6, so $y = -\frac{3}{2}x + 6$. When $x = 10$, $y = -15 + 6 = -9$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (0 - 6)/4 = -3/2; y = -1.5x + 6; at x = 10: -15 + 6 = -9.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
