INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b222fb44-c07d-40cf-8d3e-c096518a1b7f', 'NC26.8.ANFR.4', 1, 'choice', 'Place a square or cube root between whole numbers', 'Which of these numbers lies between 7 and 8?', '["$\\sqrt{40}$","$\\sqrt{70}$","$\\sqrt{64}$","$\\sqrt{52}$"]', '$\sqrt{52}$', NULL, '$7^2 = 49$ and $8^2 = 64$, so a number between 7 and 8 has a square between 49 and 64. $\sqrt{52}$ qualifies. $\sqrt{40}$ is about 6.3, $\sqrt{70}$ is about 8.4, and $\sqrt{64} = 8$ exactly.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{52}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 49 < n < 64. sqrt(70) > 8, sqrt(40) < 7, sqrt(64) = 8 exactly (not strictly between). sqrt(52) is between 7 and 8.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
