INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e920a66c-8d98-4228-8b6e-9bdc0205c298', 'NC26.8.ANFR.4', 2, 'numeric', 'Recognise an irrational number', 'How many of the numbers $\sqrt{12}$, $\sqrt{36}$, $\sqrt{45}$, $\sqrt{64}$, $\sqrt{80}$ and $\sqrt{100}$ are irrational?', '[]', '3', NULL, '36, 64 and 100 are perfect squares, so those roots are rational (6, 8 and 10). 12, 45 and 80 are not perfect squares, so $\sqrt{12}$, $\sqrt{45}$ and $\sqrt{80}$ are irrational. That is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36, 64, 100 are perfect squares (6, 8, 10). 12, 45, 80 are not, so sqrt(12), sqrt(45), sqrt(80) are irrational. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('500d0d01-5245-43d4-a186-3bd136fc6629', 'NC26.8.ANFR.4', 2, 'numeric', 'Recognise an irrational number', 'What is the least whole number greater than 30 whose square root is a rational number?', '[]', '36', '6^2', 'The square root of a whole number is rational only if the number is a perfect square. The perfect squares near 30 are $25 = 5^2$ and $36 = 6^2$. The least one greater than 30 is 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A whole number has a rational square root only if it is a perfect square. 31-35 are not; 36 = 6^2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28636008-1eb3-44e3-ad8a-3f7284e728be', 'NC26.8.ANFR.4', 2, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Which statement describes the decimal $0.272727\ldots$ (the digits 27 repeat forever)?', '["It is irrational, because it never ends","It is irrational, because it is not a whole number","It is rational, because it ends after two digits","It is rational, because its digits repeat in a pattern"]', 'It is rational, because its digits repeat in a pattern', NULL, 'A decimal that repeats a block of digits forever is rational. It does not end, but repeating is enough. (Here $0.\overline{27} = \frac{3}{11}$.)', 'checked', '{"lint":[],"solve":{"answer":"It is rational, because its digits repeat in a pattern","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.2727... = 27/99 = 3/11; a repeating decimal is rational. It does not end, so the second option''s reason is wrong.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70a0de63-6e15-430c-b452-9c39d611801c', 'NC26.8.ANFR.4', 2, 'numeric', 'Use a decimal expansion to tell rational from irrational', 'How many of the numbers $\frac{1}{8}$, $\frac{2}{3}$, $\sqrt{7}$ and $\frac{5}{11}$ have a decimal that either ends or repeats?', '[]', '3', NULL, 'Every fraction of integers has a decimal that ends or repeats: $\frac{1}{8} = 0.125$, $\frac{2}{3} = 0.\overline{6}$ and $\frac{5}{11} = 0.\overline{45}$. $\sqrt{7}$ is irrational, so its decimal does neither. That is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 = 0.125 ends; 2/3 = 0.666... repeats; sqrt(7) irrational, neither; 5/11 = 0.4545... repeats. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('002b312c-bf13-4725-a4e0-bbeb0fe982c2', 'NC26.8.ANFR.4', 2, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Which fraction is equal to a decimal that ends?', '["$\\frac{3}{8}$","$\\frac{1}{3}$","$\\frac{5}{6}$","$\\frac{4}{9}$"]', '$\frac{3}{8}$', NULL, '$\frac{3}{8} = 0.375$ ends. $\frac{1}{3} = 0.\overline{3}$, $\frac{5}{6} = 0.8\overline{3}$ and $\frac{4}{9} = 0.\overline{4}$ all repeat forever.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375 ends (denominator only 2s). 1/3, 5/6, 4/9 repeat (denominators with factor 3).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ba88f95-3406-47ea-ad74-06a1e6493285', 'NC26.8.ANFR.4', 2, 'numeric', 'Describe how the subsets of the real numbers relate', 'Zero is not a natural number, because the natural numbers start at 1. Zero is in some of these four sets: whole numbers, integers, rational numbers, irrational numbers. How many of those four sets contain 0?', '[]', '3', NULL, '$0$ is a whole number, an integer and a rational number ($\frac{0}{1}$). It is not irrational. That is 3 sets.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 is whole, an integer, rational (0/1); not irrational. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1573f4e5-8409-4ec0-8178-f7caed4fb1a4', 'NC26.8.ANFR.4', 2, 'choice', 'Describe how the subsets of the real numbers relate', 'Which statement is false?', '["Every integer is a rational number","Every rational number is an integer","Every natural number is a whole number","Every irrational number is a real number"]', 'Every rational number is an integer', NULL, '$\frac{1}{2}$ is rational but is not an integer, so that statement is false. The other three are true.', 'checked', '{"lint":[],"solve":{"answer":"Every rational number is an integer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 is rational but not an integer, so ''Every rational number is an integer'' is false. The other three are true.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa69a6d3-f78a-44ce-ac87-f3e68be11757', 'NC26.8.ANFR.4', 2, 'choice', 'Place a square or cube root between whole numbers', 'Between which two consecutive whole numbers does $\sqrt[3]{20}$ lie?', '["2 and 3","1 and 2","3 and 4","6 and 7"]', '2 and 3', NULL, '$2^3 = 8$ and $3^3 = 27$. Since 20 is between 8 and 27, $\sqrt[3]{20}$ is between 2 and 3.', 'checked', '{"lint":[],"solve":{"answer":"2 and 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8 < 20 < 27 = 3^3, so cube root of 20 is between 2 and 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ad24486-c450-42f4-a92c-48b3eb465ab0', 'NC26.8.ANFR.4', 2, 'numeric', 'Place a square or cube root between whole numbers', 'A square garden has an area of 90 square feet. Its side length is between two consecutive whole numbers of feet. What is the larger of the two numbers?', '[]', '10', '10', 'The side length is $\sqrt{90}$. Since $9^2 = 81$ and $10^2 = 100$, it is between 9 and 10. The larger number is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side = sqrt(90); 81 < 90 < 100, so 9 < side < 10. Larger is 10.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51fe4591-34c6-4071-986e-bd6431e1c6cd', 'NC26.8.ANFR.4', 2, 'numeric', 'Place a square or cube root between whole numbers', 'What is the greatest whole number $n$ for which $\sqrt{n}$ is less than 9?', '[]', '80', '9^2-1', '$\sqrt{81} = 9$, which is not less than 9. The next number down, 80, has $\sqrt{80}$ a little less than 9. So the greatest is 80.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(n) < 9 means n < 81. Greatest whole n = 80.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80c69e72-aba0-4b85-9975-e1826d60bf1f', 'NC26.8.ANFR.4', 2, 'choice', 'Place a square or cube root between whole numbers', 'Which statement about $\sqrt{135}$ is true?', '["It is between 12 and 13","It is between 13 and 14","It is between 11 and 12","It is between 67 and 68"]', 'It is between 11 and 12', NULL, '$11^2 = 121$ and $12^2 = 144$. Since 135 is between 121 and 144, $\sqrt{135}$ is between 11 and 12.', 'checked', '{"lint":[],"solve":{"answer":"It is between 11 and 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11^2 = 121 < 135 < 144 = 12^2, so between 11 and 12.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
