INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8515428a-7112-4700-b0d8-911cab4010da', 'NC26.8.ANFR.4', 2, 'numeric', 'Estimate an irrational number to the nearest tenth', 'A square patio has an area of 13 square meters. To the nearest tenth of a meter, how long is each side?', '[]', '3.6', NULL, 'The side is $\sqrt{13}$. $3.6^2 = 12.96$ and $3.7^2 = 13.69$, and 13 is much closer to 12.96, so $\sqrt{13} \approx 3.6$.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side = sqrt(13). 3.6^2 = 12.96, 3.65^2 = 13.3225 > 13, so sqrt(13) is about 3.606, rounds to 3.6.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('380742d2-1af1-4c1d-9d4d-606f439cff36', 'NC26.8.ANFR.4', 2, 'choice', 'Estimate an irrational number to the nearest tenth', 'Without a calculator, which is the best estimate of $\sqrt{85}$ to the nearest tenth?', '["9.4","9.2","8.5","42.5"]', '9.2', NULL, '$9^2 = 81$ and $10^2 = 100$, so $\sqrt{85}$ is a little above 9. $9.2^2 = 84.64$ is very close to 85, while $9.4^2 = 88.36$ is too big.', 'checked', '{"lint":[],"solve":{"answer":"9.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9.2^2 = 84.64, 9.25^2 = 85.5625 > 85, so sqrt(85) is about 9.22, rounds to 9.2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30f5c13c-4e90-43d2-b94f-6faf80e91fd2', 'NC26.8.ANFR.4', 2, 'numeric', 'Estimate an irrational number to the nearest tenth', 'What is $\sqrt[3]{30}$, rounded to the nearest tenth?', '[]', '3.1', NULL, '$3^3 = 27$ and $4^3 = 64$, so $\sqrt[3]{30}$ is just above 3. $3.1^3 = 29.791$, which is very close to 30, so the answer is $3.1$.', 'checked', '{"lint":[],"solve":{"answer":"3.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^3 = 27, 3.1^3 = 29.791, 3.15^3 = 31.256 > 30, so cube root of 30 is about 3.107, rounds to 3.1.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17075c82-dba6-4faf-aad0-44ed1ff3a1e7', 'NC26.8.ANFR.4', 2, 'choice', 'Estimate an irrational number to the nearest tenth', 'Mark says $\sqrt{30}$ is about 5.2 and Dee says it is about 5.5. Which statement is correct?', '["Mark is closer, because 5.2 is smaller than 5.5","They are equally close, because both are below 6","Neither is close, because $\\sqrt{30}$ is above 6","Dee is closer, because $5.5^2 = 30.25$ is very near 30"]', 'Dee is closer, because $5.5^2 = 30.25$ is very near 30', NULL, '$5.5^2 = 30.25$ is only $0.25$ away from 30, but $5.2^2 = 27.04$ is almost 3 away. So 5.5 is the better estimate. Also $\sqrt{30}$ is less than 6, since $6^2 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"Dee is closer, because $5.5^2 = 30.25$ is very near 30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.5^2 = 30.25 (0.25 off); 5.2^2 = 27.04 (2.96 off). sqrt(30) is about 5.477, so Dee is closer.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddc2a26b-856e-4e85-9a9d-34a93b27a7b2', 'NC26.8.ANFR.4', 2, 'numeric', 'Estimate an irrational number to the nearest tenth', 'Using $\sqrt{2} \approx 1.414$, find $5\sqrt{2}$ as a decimal.', '[]', '7.07', '5*1.414', '$5 \times 1.414 = 7.07$.', 'checked', '{"lint":[],"solve":{"answer":"7.07","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 1.414 = 7.07.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
