INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d752f3-c15a-4f04-b710-da21f5b1d7e3', 'NC26.8.ANFR.4', 2, 'choice', 'Compare and order real numbers', 'Which list has $\sqrt{5}$, $2.4$ and $\frac{5}{2}$ in order from least to greatest?', '["$2.4,\\ \\sqrt{5},\\ \\frac{5}{2}$","$\\frac{5}{2},\\ 2.4,\\ \\sqrt{5}$","$\\sqrt{5},\\ \\frac{5}{2},\\ 2.4$","$\\sqrt{5},\\ 2.4,\\ \\frac{5}{2}$"]', '$\sqrt{5},\ 2.4,\ \frac{5}{2}$', NULL, '$\sqrt{5}$ is about $2.24$ (since $2.2^2 = 4.84$), $2.4$ is $2.4$, and $\frac{5}{2} = 2.5$. So the order is $\sqrt{5},\ 2.4,\ \frac{5}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{5},\\ 2.4,\\ \\frac{5}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(5) about 2.236 (2.2^2 = 4.84, 2.3^2 = 5.29); 2.4; 5/2 = 2.5. Order: sqrt(5), 2.4, 5/2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee2fa260-0234-488a-b075-e785f27f4f19', 'NC26.8.ANFR.4', 2, 'numeric', 'Compare and order real numbers', 'How many of the numbers $\sqrt{2}$, $\sqrt{5}$, $\sqrt{8}$, $\sqrt{11}$ and $\sqrt{14}$ are greater than 3?', '[]', '2', NULL, '$3 = \sqrt{9}$, so a square root is greater than 3 when the number inside is greater than 9. That is true for 11 and 14 only, so 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(n) > 3 means n > 9: sqrt(11), sqrt(14). Count = 2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0a122d4-6502-4b44-a611-8caf78410662', 'NC26.8.ANFR.4', 2, 'numeric', 'Approximate an expression with pi', 'A circular pool has a radius of 5 meters. Use 3.14 for $\pi$. What is the area of the pool, in square meters?', '[]', '78.5', '3.14*5^2', '$A = \pi r^2 \approx 3.14 \times 5^2 = 3.14 \times 25 = 78.5$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"78.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3.14 x 5^2 = 3.14 x 25 = 78.5.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
