VALUES ('d82a3a94-95ce-4083-8897-3916f1a7ad38', 'NC26.8.ANFR.4', 2, 'choice', 'Approximate an expression with pi', 'Between which two whole numbers does $2\pi$ lie?', '["5 and 6","7 and 8","3 and 4","6 and 7"]', '6 and 7', NULL, '$2\pi \approx 2 \times 3.14 = 6.28$, which is between 6 and 7.', 'checked', '{"lint":[],"solve":{"answer":"6 and 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 pi is about 6.28, between 6 and 7.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
