INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0cd0191-da93-4b66-9b36-7fa2b4bcfc8c', 'NC26.8.ANFR.4', 2, 'choice', 'Approximate an expression with pi', 'A circle has a diameter of 8 inches. Maya uses 3 for $\pi$ to estimate its circumference with $C = \pi d$. Which statement is true?', '["Her estimate is 24 inches, which is a little less than the true circumference","Her estimate is 24 inches, which is a little more than the true circumference","Her estimate is 48 inches, which is a little less than the true circumference","Her estimate is 48 inches, which is a little more than the true circumference"]', 'Her estimate is 24 inches, which is a little less than the true circumference', NULL, 'Her estimate is $3 \times 8 = 24$ inches. The true circumference is $8\pi \approx 25.1$ inches. Since 3 is a little less than $\pi$, her estimate is a little too small.', 'checked', '{"lint":[],"solve":{"answer":"Her estimate is 24 inches, which is a little less than the true circumference","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24. True C = 8 pi, about 25.13, so 24 is a little less.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
