INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f505465-2bf2-470c-8a17-bc25d51e63ee', 'NC26.8.ANFR.5', 1, 'choice', 'Multiply powers with the same base', 'Which expression is equal to $x^4 \cdot x^6$?', '["$x^{24}$","$x^{2}$","$2x^{10}$","$x^{10}$"]', '$x^{10}$', NULL, 'When you multiply powers with the same base, you add the exponents: $x^4 \cdot x^6 = x^{4+6} = x^{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: x^(4+6) = x^10.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
