INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09af7667-a9eb-4b06-ab15-4effc55b46dd', 'NC26.8.ANFR.5', 1, 'numeric', 'Multiply powers with the same base', 'If $4^3 \times 4^2 = 4^n$, what is $n$?', '[]', '5', '3+2', 'Add the exponents: $4^3 \times 4^2 = 4^{3+2} = 4^5$, so $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^3 x 4^2 = 4^(3+2) = 4^5, so n = 5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
