VALUES ('add1c64a-a279-4f3e-9164-e6e00a9d1755', 'NC26.8.ANFR.5', 1, 'choice', 'Multiply powers with the same base', 'Write $10^2 \times 10^3$ as a single power of 10. Which choice is correct?', '["$10^{6}$","$10^{5}$","$100^{5}$","$10^{1}$"]', '$10^{5}$', NULL, 'The base is the same, so add the exponents: $10^2 \times 10^3 = 10^{2+3} = 10^5$ (that is 100,000).', 'checked', '{"lint":[],"solve":{"answer":"$10^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^2 x 10^3 = 10^(2+3) = 10^5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
