INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e70656b-9b95-47a8-aa52-ca3f470b1be4', 'NC26.8.ANFR.5', 1, 'numeric', 'Divide powers with the same base', '$\frac{7^9}{7^6} = 7^n$. What is the value of $n$?', '[]', '3', '9-6', 'When you divide powers with the same base, you subtract the exponents: $7^{9-6} = 7^3$, so $n = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^(9-6) = 7^3, n = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
