VALUES ('b4bad922-2be0-43ec-a6ab-49608749edca', 'NC26.8.ANFR.5', 1, 'choice', 'Solve x squared or x cubed equals a number', 'Which equation has $x = 6$ as a solution?', '["$x^2 = 12$","$x^2 = 36$","$x^3 = 18$","$x^3 = 36$"]', '$x^2 = 36$', NULL, 'Put $x = 6$ in each equation. $6^2 = 36$, so $x^2 = 36$ works. But $6^2$ is not 12, and $6^3 = 216$, which is not 18 or 36.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6^2 = 36, so x^2 = 36. 6^3 = 216, not 18 or 36; 6^2 is not 12.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
