VALUES ('c73e0b05-7e76-43a5-a780-be51406fa68a', 'NC26.8.ANFR.5', 1, 'numeric', 'Convert between scientific notation and standard form', 'A town has $2.4 \times 10^{5}$ people. How many people live in the town?', '[]', '240000', '2.4*10^5', '$10^5 = 100{,}000$, so $2.4 \times 100{,}000 = 240{,}000$ people.', 'checked', '{"lint":[],"solve":{"answer":"240000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4 x 100,000 = 240,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
