VALUES ('fdc6ebde-dcfe-464f-9684-0e69c5f2eb6b', 'NC26.8.ANFR.5', 1, 'choice', 'Convert between scientific notation and standard form', 'Which choice shows $4{,}500{,}000$ in scientific notation?', '["$4.5 \\times 10^{7}$","$4.5 \\times 10^{5}$","$4.5 \\times 10^{6}$","$4.05 \\times 10^{6}$"]', '$4.5 \times 10^{6}$', NULL, 'Move the decimal point 6 places left to get $4.5$, so the number is $4.5 \times 10^6$.', 'checked', '{"lint":[],"solve":{"answer":"$4.5 \\times 10^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,500,000 = 4.5 x 1,000,000 = 4.5 x 10^6.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
