VALUES ('a6c7e303-5451-4cc1-947a-7beee131b20e', 'NC26.8.ANFR.5', 1, 'choice', 'Compare numbers in scientific notation', 'Which number is less than $5 \times 10^{4}$?', '["$2 \\times 10^{5}$","$9 \\times 10^{4}$","$5 \\times 10^{5}$","$8 \\times 10^{3}$"]', '$8 \times 10^{3}$', NULL, '$5 \times 10^4 = 50{,}000$. Then $8 \times 10^3 = 8000$ is less. The others are $200{,}000$, $90{,}000$ and $500{,}000$, all greater.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 10^{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 10^4 = 50,000. 8 x 10^3 = 8,000 is less; 500,000, 90,000, 200,000 are greater.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
