VALUES ('42953dff-f032-4e1a-a558-2ecf3591e603', 'NC26.8.ANFR.5', 1, 'numeric', 'Compute with numbers in scientific notation', 'A machine makes $5 \times 10^{4}$ nails each day. How many nails does it make in 10 days?', '[]', '500000', '5*10^4*10', '$5 \times 10^4 = 50{,}000$ nails a day. In 10 days: $50{,}000 \times 10 = 500{,}000$ nails.', 'checked', '{"lint":[],"solve":{"answer":"500000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 10^4 x 10 = 5 x 10^5 = 500,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
