INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ca25e8f-0c81-47bd-b122-acd9eb977c62', 'NC26.8.ANFR.5', 1, 'choice', 'Compute with numbers in scientific notation', 'Multiply $1.5 \times 10^{2}$ by $2 \times 10^{3}$. Which choice shows the product in scientific notation?', '["$3 \\times 10^{6}$","$3 \\times 10^{5}$","$3.5 \\times 10^{5}$","$3 \\times 10^{-1}$"]', '$3 \times 10^{5}$', NULL, 'Multiply the numbers: $1.5 \times 2 = 3$. Add the exponents: $2 + 3 = 5$. The product is $3 \times 10^5$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 10^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1.5 x 2) x 10^(2+3) = 3 x 10^5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
