INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e50d25d-359c-446d-b65c-721f63788853', 'NC26.8.ANFR.5', 1, 'numeric', 'Evaluate a square root or cube root', 'A cube-shaped box has a volume of 343 cubic inches. How long is each edge of the box, in inches?', '[]', '7', '7', 'The volume of a cube is edge $\times$ edge $\times$ edge. Since $7 \times 7 \times 7 = 343$, each edge is 7 inches. (This is the cube root of 343.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^3=343, edge 7.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
