INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e51559-eed4-437a-ba9b-1f4bfaaaa55b', 'NC26.8.ANFR.5', 2, 'choice', 'Compare numbers in scientific notation', 'Which number is the greatest?', '["$9.2 \\times 10^{5}$","$7.9 \\times 10^{4}$","$4.5 \\times 10^{6}$","$3.1 \\times 10^{5}$"]', '$4.5 \times 10^{6}$', NULL, 'Compare the powers of 10 first. $10^6$ is the largest power, so $4.5 \times 10^6 = 4{,}500{,}000$ is greater than $9.2 \times 10^5 = 920{,}000$, $3.1 \times 10^5 = 310{,}000$ and $7.9 \times 10^4 = 79{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"$4.5 \\times 10^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values: 310,000; 79,000; 920,000; 4,500,000. Greatest is 4.5 x 10^6.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a95dcc8-6c98-4029-aef0-3a25dd47360e', 'NC26.8.ANFR.5', 2, 'choice', 'Multiply powers with the same base', 'A student writes $6^4 \times 6^3 = 36^7$. Which statement is correct?', '["It is wrong: the base stays 6, so the answer is $6^7$","It is correct, because $6 \\times 6 = 36$","It is wrong: the answer is $6^{12}$","It is wrong: the answer is $36^{12}$"]', 'It is wrong: the base stays 6, so the answer is $6^7$', NULL, 'When you multiply powers with the same base, the base does not change and the exponents are added: $6^4 \times 6^3 = 6^{4+3} = 6^7$.', 'checked', '{"lint":[],"solve":{"answer":"It is wrong: the base stays 6, so the answer is $6^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6^4 x 6^3 = 6^7: the base stays 6 and exponents add. 36^7 = 6^14, so the student is wrong; 6^12 and 36^12 are also wrong.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
