INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5582096f-852e-4f1d-9d24-8e2a8df45fdd', 'NC26.8.ANFR.5', 2, 'choice', 'Divide powers with the same base', '$\frac{4^{3}}{4^{5}}$ can be written as which power of 4?', '["$4^{2}$","$4^{8}$","$4^{-2}$","$4^{-8}$"]', '$4^{-2}$', NULL, 'Subtract the exponents: $3 - 5 = -2$, so $\frac{4^3}{4^5} = 4^{-2}$.', 'checked', '{"lint":[],"solve":{"answer":"$4^{-2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^(3-5) = 4^-2.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
