INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a21dc9dc-9d88-49ef-a95a-49c79861c749', 'NC26.8.ANFR.5', 2, 'numeric', 'Divide powers with the same base', 'The quotient $\frac{3^{n}}{3^{4}}$ equals $3^{6}$. Find $n$.', '[]', '10', '6+4', 'Subtracting exponents gives $n - 4 = 6$, so $n = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - 4 = 6, so n = 10.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
