VALUES ('925576cb-8269-4948-83d5-83d17f03b6bf', 'NC26.8.ANFR.5', 2, 'choice', 'Solve x squared or x cubed equals a number', 'Solve $x^3 = -8$.', '["$x = -2$","$x = 2$","$x = -4$","$x = 2$ or $x = -2$"]', '$x = -2$', NULL, '$(-2) \times (-2) \times (-2) = -8$, so $x = -2$. A cube has just one real solution, so there is no second answer.', 'checked', '{"lint":[],"solve":{"answer":"$x = -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2)^3 = -8; 2^3 = 8, so only x = -2.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
