INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b3e6bc7-e0e3-40ce-af99-deef2698bdc8', 'NC26.8.ANFR.5', 3, 'numeric', 'Multiply powers with the same base', '$3^a \times 3^{2a} = 3^{12}$. What is the value of $a$?', '[]', '4', '12/3', 'Adding the exponents gives $a + 2a = 3a$, so $3a = 12$ and $a = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^(a + 2a) = 3^(3a) = 3^12, so 3a = 12, a = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
