INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a600e345-64ed-4822-8499-d4ca1be00edf', 'NC26.8.ANFR.5', 3, 'choice', 'Combine exponent properties', 'Simplify $\frac{(a^3)^4}{a^5 \cdot a^2}$. Which power of $a$ is the result?', '["$a^{0}$","$a^{19}$","$a^{-5}$","$a^{5}$"]', '$a^{5}$', NULL, 'The top is $(a^3)^4 = a^{12}$. The bottom is $a^5 \cdot a^2 = a^7$. Then $\frac{a^{12}}{a^7} = a^5$.', 'checked', '{"lint":[],"solve":{"answer":"$a^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a^3)^4 = a^12; a^5 x a^2 = a^7; a^(12-7) = a^5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
