INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11413a6c-c347-410c-a5a9-38e5bfb97b32', 'NC26.8.ANFR.5', 3, 'choice', 'Evaluate a square root or cube root', 'Which choice equals $\sqrt[3]{\frac{8}{125}}$?', '["$\\frac{2}{5}$","$\\frac{2}{125}$","$\\frac{8}{5}$","$\\frac{4}{25}$"]', '$\frac{2}{5}$', NULL, 'Take the cube root of the top and of the bottom: $\sqrt[3]{8} = 2$ and $\sqrt[3]{125} = 5$, so the value is $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube root of 8/125 = (cube root 8)/(cube root 125) = 2/5. Check (2/5)^3 = 8/125.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1437ae5e-3999-4edb-9c69-5429ec9f4c4e', 'NC26.8.ANFR.5', 3, 'numeric', 'Solve x squared or x cubed equals a number', 'The equation $x^2 + 5 = 86$ has two solutions. What is the positive one?', '[]', '9', NULL, 'Subtract 5: $x^2 = 81$. The positive solution is $x = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 86 - 5 = 81, x = +/-9. Positive one: 9.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
