INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fcc6872-be87-4d45-b2f7-6b632e156713', 'NC26.8.SGMR.1', 1, 'choice', 'Properties kept by rigid transformations', 'A triangle is reflected across the $y$-axis. Which statement about the image is true?', '["It has the same size and the same shape as the original triangle.","It has the same shape as the original but is smaller.","It has the same shape as the original but is larger.","It has the same size as the original but a different shape."]', 'It has the same size and the same shape as the original triangle.', NULL, 'A reflection is a rigid transformation. It keeps every side length and every angle, so the image is congruent to the original: same size and same shape.', 'checked', '{"lint":[],"solve":{"answer":"It has the same size and the same shape as the original triangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A reflection is a rigid transformation: it keeps all lengths and angles, so the image is congruent (same size and shape).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
