INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45eefdbd-03e7-4893-9b08-492f1ef6a558', 'NC26.8.SGMR.1', 1, 'choice', 'Properties kept by rigid transformations', 'A triangle is turned $90^\circ$ about the origin. Which statement is true about the new triangle compared with the original triangle?', '["Every side keeps its length, but the angles become larger","Every vertex keeps the same coordinates as before","Every angle keeps its size, but the sides become longer","Every side keeps its length and every angle keeps its size"]', 'Every side keeps its length and every angle keeps its size', NULL, 'A turn is a rigid transformation, so it moves the figure without changing its size or shape. The sides and the angles stay the same. The vertices move to new places, so their coordinates change.', 'checked', '{"lint":[],"solve":{"answer":"Every side keeps its length and every angle keeps its size","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rotation is a rigid motion: lengths and angles preserved (coordinates change).","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
