INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2303a48-e299-4851-a21b-4c230c19c918', 'NC26.8.SGMR.1', 2, 'choice', 'Combine two translations', 'Point D is at (1, 1). It is translated 4 units to the right and 3 units up, and then translated 6 units to the left and 5 units up. Where is D now?', '["(11, 9)","(-1, 9)","(-5, 6)","(-1, -1)"]', '(-1, 9)', NULL, 'Add up the moves. Horizontally: $+4$ then $-6$ gives $-2$, so $x = 1 - 2 = -1$. Vertically: $+3$ then $+5$ gives $+8$, so $y = 1 + 8 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"(-1, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,1) -> (1+4, 1+3) = (5, 4) -> (5-6, 4+5) = (-1, 9).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d1b5239-c56a-4134-a77d-0448f00b7046', 'NC26.8.SGMR.1', 2, 'numeric', 'Combine two translations', 'A robot starts at (3, -4). It moves 9 units up and 2 units left. Then it moves 3 units down and 8 units right. What is the $y$-coordinate of its final position?', '[]', '2', '-4+9-3', 'Only the up and down moves change $y$: $-4 + 9 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,-4): up 9, left 2 -> (1, 5); down 3, right 8 -> (9, 2). y = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('531e8a59-24b1-41ed-8408-587bd6648337', 'NC26.8.SGMR.1', 2, 'choice', 'Use a translation rule', 'Which rule describes a translation of 2 units to the left and 7 units up?', '["$(x, y) \\to (x + 2, y - 7)$","$(x, y) \\to (x - 7, y + 2)$","$(x, y) \\to (x + 2, y + 7)$","$(x, y) \\to (x - 2, y + 7)$"]', '$(x, y) \to (x - 2, y + 7)$', NULL, 'Left 2 means subtract 2 from $x$. Up 7 means add 7 to $y$. The rule is $(x, y) \to (x - 2, y + 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (x - 2, y + 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 2 subtracts 2 from x, up 7 adds 7 to y: (x - 2, y + 7).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('734e3db7-8f72-40dc-ab44-952e007972b9', 'NC26.8.SGMR.1', 2, 'numeric', 'Translate a polygon', 'A triangle has vertices (-3, 2), (1, 2) and (-3, 6). It is translated 4 units to the right and 3 units down. What is the sum of the coordinates of the image of the vertex (1, 2)?', '[]', '4', '(1+4)+(2-3)', 'The vertex (1, 2) moves to $(1 + 4, 2 - 3) = (5, -1)$. The sum is $5 + (-1) = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, 2) -> (1+4, 2-3) = (5, -1). Sum 5 + (-1) = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19083be2-f2a0-4f49-b775-8de30d46fb25', 'NC26.8.SGMR.1', 2, 'choice', 'Translate a polygon', 'Parallelogram PQRS has vertices P(-2, 1), Q(2, 1), R(4, 4) and S(0, 4). It is translated 3 units to the left and 2 units down. Which point is the image of R?', '["(7, 2)","(1, 6)","(1, 2)","(7, 6)"]', '(1, 2)', NULL, 'R is at (4, 4). Left 3 gives $x = 4 - 3 = 1$. Down 2 gives $y = 4 - 2 = 2$. So R'' is (1, 2).', 'checked', '{"lint":[],"solve":{"answer":"(1, 2)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R(4, 4) -> (4-3, 4-2) = (1, 2).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f9cd53d-5754-40e1-a438-9cfe64cf27d1', 'NC26.8.SGMR.1', 2, 'numeric', 'Reflect a point across an axis', 'The point (-6, 5) is reflected across the $y$-axis. How many units apart are the point and its image?', '[]', '12', '6+6', 'The image is (6, 5). Both points are 6 units from the $y$-axis, on opposite sides, so they are $6 + 6 = 12$ units apart.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-6, 5) -> (6, 5). Same y, distance |6 - (-6)| = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
