VALUES ('83202a27-8a01-4eff-b431-0da9d3e69d50', 'NC26.8.SGMR.1', 2, 'choice', 'Reflect a point across an axis', 'A point is 4 units to the right of the $y$-axis and 3 units above the $x$-axis. It is reflected across the $x$-axis. Where is the image?', '["(-4, 3)","(-4, -3)","(4, -3)","(3, -4)"]', '(4, -3)', NULL, 'The point is (4, 3). Across the $x$-axis, $y$ changes sign: the image is (4, -3).', 'checked', '{"lint":[],"solve":{"answer":"(4, -3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Point is (4, 3). Across x-axis -> (4, -3).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
