INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ed12f19-3b85-463a-90e9-d634c3fba51c', 'NC26.8.SGMR.1', 2, 'choice', 'Identify a single transformation', 'Quadrilateral WXYZ has vertices W(1, 1), X(4, 1), Y(4, 3) and Z(1, 3). Its image has vertices W''(-1, 1), X''(-1, 4), Y''(-3, 4) and Z''(-3, 1). Which transformation maps WXYZ onto its image?', '["A rotation of $90^\\circ$ clockwise about the origin","A reflection across the $y$-axis","A reflection across the $x$-axis","A rotation of $90^\\circ$ counterclockwise about the origin"]', 'A rotation of $90^\circ$ counterclockwise about the origin', NULL, 'Test $(x, y) \to (-y, x)$: W(1, 1) goes to (-1, 1), X(4, 1) goes to (-1, 4), and so on. Every vertex matches, so it is a $90^\circ$ counterclockwise rotation about the origin.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ counterclockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CCW (-y, x): W(1,1)->(-1,1), X(4,1)->(-1,4), Y(4,3)->(-3,4), Z(1,3)->(-3,1): all match. Across y-axis X would be (-4,1); 90 CW W would be (1,-1); across x-axis W would be (1,-1).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32b5b183-94fe-40d3-a697-97c7233dfc67', 'NC26.8.SGMR.1', 2, 'choice', 'Identify a single transformation', 'Which single translation takes A(2, -3) to A''(-1, 4)?', '["A translation of 3 units to the right and 7 units up","A translation of 3 units to the left and 7 units up","A translation of 3 units to the left and 1 unit up","A translation of 1 unit to the left and 4 units up"]', 'A translation of 3 units to the left and 7 units up', NULL, 'The $x$-coordinate changed by $-1 - 2 = -3$ (3 units left). The $y$-coordinate changed by $4 - (-3) = 7$ (7 units up).', 'checked', '{"lint":[],"solve":{"answer":"A translation of 3 units to the left and 7 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change: x 2 -> -1 is 3 left; y -3 -> 4 is 7 up.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa688865-69b1-4ca7-b812-4e0ebfdb3904', 'NC26.8.SGMR.1', 2, 'numeric', 'Identify a single transformation', 'A translation moves the point (-7, 4) to the point (-2, -3). How many units down does it move every point?', '[]', '7', '4-(-3)', 'The $y$-coordinate went from 4 to -3, a drop of $4 - (-3) = 7$ units. So every point moves 7 units down (and 5 units right).', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y changes 4 -> -3: down 7.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
