INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b05e0a4-6903-4e7b-a47c-3e3518f8f489', 'NC26.8.SGMR.1', 2, 'choice', 'Describe a sequence of two transformations', 'A triangle with vertices (2, 0), (5, 0) and (2, 2) is moved in two steps and ends up with vertices (0, -2), (0, 1), (-2, -2). Which pair of steps, in this order, does that?', '["A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 4 units down","A rotation of $90^\\circ$ clockwise about the origin, then a translation of 4 units down","A translation of 4 units down, then a rotation of $90^\\circ$ counterclockwise about the origin","A reflection across the $y$-axis, then a translation of 4 units down"]', 'A rotation of $90^\circ$ counterclockwise about the origin, then a translation of 4 units down', NULL, 'Rotate $90^\circ$ counterclockwise with $(x, y) \to (-y, x)$: (0, 2), (0, 5), (-2, 2). Then move 4 units down: (0, -2), (0, 1), (-2, -2).', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 4 units down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CCW (-y, x): (2,0)->(0,2), (5,0)->(0,5), (2,2)->(-2,2); 4 down: (0,-2), (0,1), (-2,-2). Matches. 90 CW first gives (0,-2)->(0,-6); translating first then CCW gives (4,2)...; reflecting gives (-2,-4).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42d283c0-46dd-41b3-86b1-3208f76c09a9', 'NC26.8.SGMR.1', 2, 'choice', 'Read and write coordinate rules', 'Which rule describes a rotation of $90^\circ$ counterclockwise about the origin?', '["$(x, y) \\to (y, -x)$","$(x, y) \\to (-y, x)$","$(x, y) \\to (-x, -y)$","$(x, y) \\to (-y, -x)$"]', '$(x, y) \to (-y, x)$', NULL, 'Test the point (1, 0). A counterclockwise quarter turn takes it to (0, 1). Only $(x, y) \to (-y, x)$ does that.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (-y, x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, 0) goes to (0, 1) under 90 CCW; (-y, x) does that. Rule (-y, x).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70c1a9b9-d332-4bc2-9c60-7555970d7e03', 'NC26.8.SGMR.1', 2, 'numeric', 'Read and write coordinate rules', 'A rotation follows the rule $(x, y) \to (y, -x)$. What is the sum of the coordinates of the image of (-3, 8)?', '[]', '11', '8+3', 'Replace $x = -3$ and $y = 8$: $(y, -x) = (8, 3)$. The sum is $8 + 3 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(y, -x) on (-3, 8) = (8, 3). Sum 11.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e401d5bd-95c9-4251-8ba5-358b7422bd9e', 'NC26.8.SGMR.1', 2, 'choice', 'Work backwards from the image', 'After being reflected across the $x$-axis, a point is at (-4, -9). Where was the point before the reflection?', '["(-4, 9)","(4, -9)","(4, 9)","(-4, -9)"]', '(-4, 9)', NULL, 'Reflecting again across the $x$-axis undoes the reflection: (-4, -9) goes back to (-4, 9).', 'checked', '{"lint":[],"solve":{"answer":"(-4, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect (-4, -9) back across x-axis: (-4, 9). Check: (-4, 9) -> (-4, -9).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7922f63-0e28-4930-a0a2-480225fd9619', 'NC26.8.SGMR.1', 2, 'numeric', 'Work backwards from the image', 'A point is rotated $90^\circ$ counterclockwise about the origin. Its image is (-3, -8). What was the $x$-coordinate of the original point?', '[]', '-8', '-8', 'The rotation sends $(x, y)$ to $(-y, x)$. So the image''s $y$-coordinate, -8, is the original $x$, and the image''s $x$-coordinate, -3, is $-y$, so $y = 3$. The original point is (-8, 3).', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"CCW: (x, y) -> (-y, x) = (-3, -8), so x = -8 (and y = 3). Check: (-8, 3) -> (-3, -8).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('690ec3e7-e2c9-452b-a723-5d6979f26018', 'NC26.8.SGMR.1', 2, 'numeric', 'Find a missing value from a transformation', 'A point at (-2, 5) is translated $a$ units to the right and $b$ units down. It ends at (4, -1). What is the value of $a + b$?', '[]', '12', '(4-(-2))+(5-(-1))', 'Horizontally, $-2 + a = 4$, so $a = 6$. Vertically, $5 - b = -1$, so $b = 6$. Then $a + b = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2 + a = 4 so a = 6; 5 - b = -1 so b = 6. a + b = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aff3ed8f-afe3-438b-b71b-e6f9084a4b3c', 'NC26.8.SGMR.1', 3, 'numeric', 'Combine a rotation and a translation', 'Point R is at (-2, 6). It is rotated $90^\circ$ clockwise about the origin and then moved 3 units to the left. What is the $x$-coordinate of its final image?', '[]', '3', '6-3', 'A $90^\circ$ clockwise rotation about the origin takes $(x, y)$ to $(y, -x)$, so (-2, 6) goes to (6, 2). Moving 3 units left subtracts 3 from $x$: (3, 2). The $x$-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 degrees clockwise: (x, y) -> (y, -x). (-2, 6) -> (6, 2). Left 3: (3, 2). x-coordinate 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('959de84a-8848-4c94-900f-07e128803bda', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image of a vertex from a given translation', 'A triangle has vertices (1, 1), (4, 1) and (1, 5). It is translated so that the vertex (4, 1) moves to (-2, 6). What is the $y$-coordinate of the image of the vertex (1, 5)?', '[]', '10', '5+(6-1)', 'The vertex (4, 1) moves to (-2, 6), which is 6 units left and 5 units up. Every point moves the same way, so (1, 5) moves to (-5, 10). Its $y$-coordinate is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector: (-2 - 4, 6 - 1) = (-6, 5). (1, 5) -> (-5, 10). y-coordinate 10.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0d1f98-14cb-444b-9414-e3adc8974983', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'Triangle ABC has vertices A(1, 2), B(3, 2) and C(1, 5). Its image has vertices A''(-1, -2), B''(-3, -2) and C''(-1, -5). Which sequence of transformations maps the triangle onto its image?', '["A reflection across the $x$-axis, then a translation 2 units left","A reflection across the $y$-axis only","A reflection across the $x$-axis, then a reflection across the $y$-axis","A rotation of $90^\\circ$ clockwise about the origin"]', 'A reflection across the $x$-axis, then a reflection across the $y$-axis', NULL, 'Reflecting across the $x$-axis takes A(1, 2) to (1, -2), B to (3, -2) and C to (1, -5). Reflecting that across the $y$-axis gives (-1, -2), (-3, -2) and (-1, -5), which match the image. The translation option works for A but takes B to (1, -2), not (-3, -2).', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis, then a reflection across the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Map is (x, y) -> (-x, -y). Reflect over x-axis (x,-y) then y-axis (-x,-y): matches all three. Rotation 90 cw: A -> (2,-1), no. x-reflection then 2 left: B(3,2) -> (1,-2), not (-3,-2). y-reflection only: A -> (-1,2), no.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd2e3c91-38f2-4ee2-9368-3f28f731a73a', 'NC26.8.SGMR.1', 3, 'choice', 'Combine two translations', 'Two translations are applied one after the other. The first moves a figure 5 units to the right and 2 units down. The second moves it 9 units to the left and 6 units down. Which single translation has the same effect?', '["A translation of 4 units to the right and 8 units down","A translation of 14 units to the left and 8 units down","A translation of 4 units to the left and 8 units down","A translation of 4 units to the left and 4 units down"]', 'A translation of 4 units to the left and 8 units down', NULL, 'Horizontally: $+5$ and $-9$ combine to $-4$ (4 units left). Vertically: $-2$ and $-6$ combine to $-8$ (8 units down).', 'checked', '{"lint":[],"solve":{"answer":"A translation of 4 units to the left and 8 units down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal: +5 - 9 = -4 (4 left). Vertical: -2 - 6 = -8 (8 down). Single translation 4 left, 8 down.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3247d5-88c2-424c-a101-56d47d4b8d7e', 'NC26.8.SGMR.1', 3, 'numeric', 'Combine two translations', 'A point at (3, -2) is translated 2 units left and 6 units up. It is then translated 5 units left and some number of units up, and it ends at (-4, 9). How many units up was the second translation?', '[]', '5', '9-(-2+6)', 'After the first translation the point is at (1, 4). The second translation moves it 5 left, to $x = -4$ (this matches), and up to $y = 9$. That is $9 - 4 = 5$ units up.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,-2) -> (1, 4). Then 5 left: x = 1 - 5 = -4 (matches). y: 4 + u = 9, so u = 5.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e166fc0-40f4-4d09-8391-01ac5356af03', 'NC26.8.SGMR.1', 3, 'numeric', 'Use a translation rule', 'The rule $(x, y) \to (x + 6, y - 4)$ is applied to the point (-3, 5), and then applied again to the result. What is the sum of the coordinates of the final point?', '[]', '6', '(-3+12)+(5-8)', 'Applying the rule twice adds $2 \times 6 = 12$ to $x$ and subtracts $2 \times 4 = 8$ from $y$: $(-3 + 12, 5 - 8) = (9, -3)$. The sum is $9 + (-3) = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3,5) -> (3, 1) -> (9, -3). Sum 9 + (-3) = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca88bc92-f86b-473f-b3cd-04c9f78dff55', 'NC26.8.SGMR.1', 3, 'numeric', 'Translate a polygon', 'A rectangle has vertices (2, 1), (8, 1), (8, 5) and (2, 5). It is translated so that its center lands on the origin. What is the $x$-coordinate of the image of the vertex (8, 5)?', '[]', '3', '8-(2+8)/2', 'The center is halfway across and halfway up: $\left(\frac{2 + 8}{2}, \frac{1 + 5}{2}\right) = (5, 3)$. The translation moves it 5 left and 3 down, so (8, 5) goes to (3, 2). The $x$-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Center = midpoint of diagonal (2,1)-(8,5) = (5, 3). Translate by (-5, -3): (8,5) -> (3, 2). x = 3.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69da2c39-0c5b-465f-a638-672fdec21be9', 'NC26.8.SGMR.1', 3, 'numeric', 'Reflect a point across an axis', 'Point P is above the $x$-axis. It is reflected across the $x$-axis to P''. The distance from P to P'' is 18 units. What is the $y$-coordinate of P?', '[]', '9', '18/2', 'P and P'' are the same distance from the $x$-axis, on opposite sides, so each is half of 18 units away. P is 9 units above the axis, so its $y$-coordinate is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = (x, y), y > 0; P'' = (x, -y). Distance = 2y = 18, so y = 9.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fc87d87-61bd-4bb1-a80a-81c9499d8f6a', 'NC26.8.SGMR.1', 3, 'numeric', 'Reflect a polygon', 'A triangle has vertices (0, 0), (4, 0) and (0, 3). It is reflected across the $y$-axis. The triangle and its image together make one larger triangle. What is the area of the larger triangle, in square units?', '[]', '12', '8*3/2', 'The image has vertices (0, 0), (-4, 0) and (0, 3). Together the two triangles have a base from (-4, 0) to (4, 0), which is 8 units long, and a height of 3 units. The area is $\frac{1}{2} \times 8 \times 3 = 12$ square units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image vertices (0,0), (-4,0), (0,3). Together they form the triangle (-4,0), (4,0), (0,3): base 8, height 3, area = 8*3/2 = 12. (Check: 2 * (4*3/2) = 12.)","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9a6f77d-71b8-4ae8-a3e4-5ca636f39626', 'NC26.8.SGMR.1', 3, 'choice', 'Rotate a point 90 degrees about the origin', 'A point in Quadrant IV is rotated $90^\circ$ counterclockwise about the origin. In which quadrant is its image?', '["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"]', 'Quadrant I', NULL, 'In Quadrant IV, $x$ is positive and $y$ is negative. The counterclockwise rule $(x, y) \to (-y, x)$ gives a new $x$ of $-y$, which is positive, and a new $y$ of $x$, which is positive. Both are positive, so the image is in Quadrant I. For example, (3, -2) goes to (2, 3).', 'checked', '{"lint":[],"solve":{"answer":"Quadrant I","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"QIV (+, -) -> (-y, x) = (+, +): Quadrant I.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e1145f6-49be-4b73-a401-1b6effb97dc9', 'NC26.8.SGMR.1', 3, 'choice', 'Rotate a polygon 90 degrees about the origin', 'Triangle ABC has vertices A(1, 2), B(4, 2) and C(1, 6). It is rotated $90^\circ$ counterclockwise about the origin. Which statement about the image A''B''C'' is true?', '["Side A''B'' is horizontal and 3 units long.","Side A''B'' is vertical and 3 units long.","Side A''B'' is vertical and 4 units long.","Side A''B'' is horizontal and 4 units long."]', 'Side A''B'' is vertical and 3 units long.', NULL, 'The image vertices are A''(-2, 1), B''(-2, 4) and C''(-6, 1). A''B'' has the same $x$-coordinate at both ends, so it is vertical, and its length is $4 - 1 = 3$. (A horizontal side turns into a vertical side, and its length does not change.)', 'checked', '{"lint":[],"solve":{"answer":"Side A''B'' is vertical and 3 units long.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-y, x): A(1,2)->(-2,1), B(4,2)->(-2,4). Same x, so A''B'' is vertical, length 4 - 1 = 3. (AB was horizontal, length 3.)","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('092e334d-c053-4a4e-88f7-a988ce18a622', 'NC26.8.SGMR.1', 3, 'numeric', 'Rotate a polygon 90 degrees about the origin', 'A rectangle has vertices (-5, 2), (-1, 2), (-1, 4) and (-5, 4). It is rotated $90^\circ$ counterclockwise about the origin. What is the sum of the $x$-coordinates of the four vertices of the image?', '[]', '-12', '-(2+2+4+4)', 'Use $(x, y) \to (-y, x)$. The new $x$-coordinate of each vertex is the opposite of its old $y$-coordinate: -2, -2, -4, -4. Their sum is -12.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-y, x): image x-coordinates are -y: -2, -2, -4, -4. Sum = -12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8204e490-4e40-47fe-ae59-2d0de01aee53', 'NC26.8.SGMR.1', 3, 'numeric', 'Identify a single transformation', 'A translation maps the point (-2, 5) to the point (3, 1). The same translation maps the point (4, -6) to a new point. What is the sum of the coordinates of the new point?', '[]', '-1', '(4+5)+(-6-4)', 'The translation adds 5 to $x$ and subtracts 4 from $y$. So (4, -6) goes to (9, -10). The sum is $9 + (-10) = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation: (+5, -4). (4, -6) -> (9, -10). Sum -1.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b9497c6-4d8e-4b87-afb5-461d54bfa3ab', 'NC26.8.SGMR.1', 3, 'choice', 'Identify a single transformation', 'Segment AB has endpoints A(4, 1) and B(6, 3). Its image has endpoints A''(1, -4) and B''(3, -6). Which transformation maps AB onto A''B''?', '["A rotation of $90^\\circ$ counterclockwise about the origin","A reflection across the $x$-axis","A rotation of $90^\\circ$ clockwise about the origin","A translation of 3 units to the left and 5 units down"]', 'A rotation of $90^\circ$ clockwise about the origin', NULL, 'Test $(x, y) \to (y, -x)$: A(4, 1) goes to (1, -4) and B(6, 3) goes to (3, -6), so it is a $90^\circ$ clockwise rotation about the origin. A translation of 3 units left and 5 units down fits A but moves B to (3, -2), not (3, -6).', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ clockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CW (y, -x): A(4,1)->(1,-4), B(6,3)->(3,-6): both match. Translation 3 left 5 down sends B to (3,-2), no. 90 CCW sends A to (-1,4); across x-axis sends A to (4,-1).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aefb2d46-3bdb-42ae-ab8c-a03cbcdcbc34', 'NC26.8.SGMR.1', 3, 'numeric', 'Properties kept by rigid transformations', 'A segment has endpoints (2, 1) and (6, 4). It is rotated $90^\circ$ counterclockwise about the origin and then reflected across the $x$-axis. How long is the final image of the segment, in units?', '[]', '5', NULL, 'Both transformations are rigid, so the length does not change. The original segment goes 4 units across and 3 units up, so its length is $\sqrt{4^2 + 3^2} = \sqrt{25} = 5$ units.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original length = sqrt(4^2 + 3^2) = 5. Rotations and reflections keep length: 5.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
