INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d2d5b12-ef67-4686-93c8-48a4e7bc0141', 'NC26.8.SGMR.1', 3, 'choice', 'Properties kept by rigid transformations', 'In quadrilateral ABCD, side AB is parallel to side CD. The quadrilateral is rotated about the origin. Which statement must be true about the image?', '["Side A''B'' is perpendicular to side C''D''.","Side A''B'' and side C''D'' are both horizontal.","Side A''B'' is parallel to side C''D''.","Side A''B'' has the same length as side C''D''."]', 'Side A''B'' is parallel to side C''D''.', NULL, 'A rotation keeps angles, so lines that were parallel stay parallel. The sides need not be horizontal, and AB and CD need not be equal in length, so only "Side A''B'' is parallel to side C''D''" must be true.', 'checked', '{"lint":[],"solve":{"answer":"Side A''B'' is parallel to side C''D''.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotations take parallel lines to parallel lines, so A''B'' is parallel to C''D''. Equal lengths not guaranteed (trapezoid); perpendicular and horizontal not generally true.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d0d31b-27d4-4a96-88dc-78beb4e69e05', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image after two transformations', 'The point (5, -2) is rotated $90^\circ$ clockwise about the origin and then moved 4 units to the left and 1 unit up. What is the $x$-coordinate of the final point?', '[]', '-6', '-2-4', 'The rotation uses $(x, y) \to (y, -x)$ and gives (-2, -5). Moving 4 units left gives (-6, -4). The $x$-coordinate is -6.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5, -2) -> 90 CW (y, -x) = (-2, -5) -> 4 left, 1 up = (-6, -4). x = -6.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('909aeadc-77ec-47b1-a1fd-d9c2046fb162', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image after two transformations', 'The point (2, -7) is reflected across the $x$-axis and then rotated $90^\circ$ counterclockwise about the origin. What is the $y$-coordinate of the final point?', '[]', '2', '2', 'The reflection gives (2, 7). The rotation uses $(x, y) \to (-y, x)$ and gives (-7, 2). The $y$-coordinate is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2, -7) -> across x-axis (2, 7) -> 90 CCW (-y, x) = (-7, 2). y = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
