INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('431f956b-2fc0-4e07-8a66-496f89d5e7cc', 'NC26.8.SGMR.1', 3, 'choice', 'Find the image after two transformations', 'A point at (-6, 3) is translated 4 units to the right and 5 units up, and then reflected across the $y$-axis. Which point is the final image?', '["(-2, 8)","(2, 8)","(10, 8)","(-2, -8)"]', '(2, 8)', NULL, 'The translation gives (-2, 8). The reflection across the $y$-axis changes the sign of $x$ and gives (2, 8).', 'checked', '{"lint":[],"solve":{"answer":"(2, 8)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-6, 3) -> (-2, 8) -> across y-axis (2, 8).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
