INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb64a76a-adf1-4572-b7a4-dfe4966618cf', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image after two transformations', 'The point (3, -5) is rotated $90^\circ$ clockwise about the origin. The result is rotated $90^\circ$ clockwise about the origin again. What is the sum of the coordinates of the final point?', '[]', '2', '-3+5', 'The first rotation uses $(x, y) \to (y, -x)$ and gives (-5, -3). The second gives (-3, 5). The sum is $-3 + 5 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3, -5) -> CW (y, -x) = (-5, -3) -> CW again (-3, 5). Sum 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
