INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b41b165-4b08-4a8b-8fa0-31c4be2e052f', 'NC26.8.SGMR.2', 1, 'choice', 'Tell an enlargement from a reduction', 'A dilation has a scale factor of $\frac{2}{5}$. What does this dilation do to a figure?', '["It makes the figure larger.","It leaves the figure the same size.","It turns the figure without changing its size.","It makes the figure smaller."]', 'It makes the figure smaller.', NULL, 'A scale factor between 0 and 1 shrinks a figure. $\frac{2}{5}$ is less than 1, so the image is smaller.', 'checked', '{"lint":[],"solve":{"answer":"It makes the figure smaller.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 < 2/5 < 1, so the figure shrinks.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
