VALUES ('88fc89ab-a49f-4e8a-af1c-ba04e50e4d27', 'NC26.8.SGMR.2', 1, 'choice', 'Tell an enlargement from a reduction', 'Which scale factor makes a figure larger?', '["0.6","1.2","1/4","1"]', '1.2', '1.2', 'A scale factor greater than 1 makes a figure larger. Of the choices, only 1.2 is greater than 1. A scale factor of 1 leaves the size the same, and the others shrink it.', 'checked', '{"lint":[],"solve":{"answer":"1.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A factor greater than 1 enlarges: 1.2. (0.6 and 1/4 shrink; 1 keeps size.)","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
