INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42d21629-4610-4aae-8ff6-abe91cdc9e95', 'NC26.8.SGMR.2', 1, 'numeric', 'Dilation from a center', 'A point is 10 cm from the center of a dilation. The scale factor is $\frac{1}{2}$. How far from the center is its image, in centimeters?', '[]', '5', '10/2', 'Multiply the distance by the scale factor: $10 \times \frac{1}{2} = 5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 * 1/2 = 5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08fff591-8fd5-4781-8aec-4c5c06f6a1db', 'NC26.8.SGMR.2', 1, 'numeric', 'Dilate a segment', 'A segment runs from (0, 0) to (5, 0). It is dilated about the origin with a scale factor of 3. How long is the image of the segment, in units?', '[]', '15', '5*3', 'The image runs from (0, 0) to (15, 0), so it is 15 units long.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 5 * 3 = 15 (image from (0,0) to (15,0)).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb64a0c4-ad5d-4eb8-8ba2-12aefa460f24', 'NC26.8.SGMR.2', 1, 'numeric', 'Describe a dilation', 'Every side of a triangle is made 6 times as long, and the angles stay the same. This is a dilation. What is its scale factor?', '[]', '6', '6', 'The scale factor is the number by which every length is multiplied, which is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each length multiplied by 6, so scale factor 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18acb48e-362c-4593-b6a1-df379ad23ab9', 'NC26.8.SGMR.2', 1, 'numeric', 'Work backwards to the original figure', 'A dilation with a scale factor of 2 produces a segment that is 18 cm long. How long was the original segment, in centimeters?', '[]', '9', '18/2', 'The image is twice as long as the original, so the original is $18 \div 2 = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 2 = 9.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd400459-eb12-448b-898f-90f6bae19754', 'NC26.8.SGMR.2', 1, 'choice', 'Recognize a dilation', 'Which change to a triangle is a dilation?', '["The triangle slides 3 units to the right.","Every side of the triangle becomes 3 times as long, and the angles stay the same.","The triangle flips over the $y$-axis.","The triangle turns $90^\\circ$ about the origin."]', 'Every side of the triangle becomes 3 times as long, and the angles stay the same.', NULL, 'A dilation changes the size of a figure by multiplying all lengths by the same scale factor. Sliding, flipping and turning do not change the size.', 'checked', '{"lint":[],"solve":{"answer":"Every side of the triangle becomes 3 times as long, and the angles stay the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A dilation multiplies all lengths by one factor and keeps angles: the 3-times-as-long option. Others are rigid motions.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae7be4a9-d4ef-4133-9299-5d0229284285', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a point by a scale factor less than 1', 'Point B is at (12, -9). It is dilated about the origin with a scale factor of $\frac{1}{3}$. What are the coordinates of its image?', '["(4, -3)","(36, -27)","(9, -6)","(4, 3)"]', '(4, -3)', NULL, 'Multiply both coordinates by $\frac{1}{3}$: $12 \times \frac{1}{3} = 4$ and $-9 \times \frac{1}{3} = -3$. The image is (4, -3).', 'checked', '{"lint":[],"solve":{"answer":"(4, -3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12/3, -9/3) = (4, -3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8453267-9601-40a2-b26c-83ee850cb4df', 'NC26.8.SGMR.2', 2, 'numeric', 'Find a scale factor from the coordinates of a point and its image', 'A dilation about the origin takes the point (4, 6) to the point (10, 15). What is the scale factor?', '[]', '5/2', '10/4', 'Each coordinate is multiplied by the scale factor $k$. From $4k = 10$ we get $k = \frac{10}{4} = \frac{5}{2}$. Check: $6 \times \frac{5}{2} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/4 = 2.5 and 15/6 = 2.5, consistent. Scale factor 2.5.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5804e0f7-3add-4fe3-973e-2355b998bea4', 'NC26.8.SGMR.2', 2, 'numeric', 'Find the perimeter of a dilated triangle', 'A triangle has sides of 6 cm, 8 cm and 10 cm. It is dilated with a scale factor of 1.5. What is the perimeter of the new triangle, in centimeters?', '[]', '36', '(6+8+10)*1.5', 'The original perimeter is $6 + 8 + 10 = 24$ cm. Every length is multiplied by 1.5, so the new perimeter is $24 \times 1.5 = 36$ cm. (The new sides are 9, 12 and 15, which also add to 36.)', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original perimeter 6 + 8 + 10 = 24; times 1.5 = 36. (Sides 9, 12, 15.)","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('892baa66-2ed1-422b-823e-6d75d069d14a', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a point about the origin', 'A dilation about the origin with a scale factor of 2.5 is applied to the point (4, -6). What are the coordinates of the image?', '["(10, -15)","(6.5, -3.5)","(10, -6)","(-10, 15)"]', '(10, -15)', NULL, 'Multiply each coordinate by 2.5: $(4 \times 2.5, -6 \times 2.5) = (10, -15)$.', 'checked', '{"lint":[],"solve":{"answer":"(10, -15)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4, -6) * 2.5 = (10, -15).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c62e96ba-ad36-41cd-b882-131bfed773a7', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilate a point by a scale factor less than 1', 'The point (-8, 20) is dilated about the origin with a scale factor of $\frac{3}{4}$. What is the sum of the coordinates of the image?', '[]', '9', '3/4*(-8)+3/4*20', 'The image is $\left(-8 \times \frac{3}{4}, 20 \times \frac{3}{4}\right) = (-6, 15)$. The sum is $-6 + 15 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-8, 20) * 3/4 = (-6, 15). Sum 9.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
