INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85e1e86b-a5e1-422e-9e53-5af643da4436', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilate a point by a scale factor less than 1', 'A dilation about the origin has a scale factor of 0.4. It maps the point (15, -5) to a new point. What is the $y$-coordinate of the new point?', '[]', '-2', '0.4*(-5)', 'Multiply by 0.4: $-5 \times 0.4 = -2$. The new point is (6, -2).', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 0.4 * (-5) = -2.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
