INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d6f582e-43cb-4cd1-ba20-3aa42f60c15c', 'NC26.8.SGMR.2', 2, 'numeric', 'Find a scale factor from two lengths', 'Triangle ABC has sides of 12 cm, 16 cm and 20 cm. Triangle A''B''C'' is a dilation of it, with sides of 9 cm, 12 cm and 15 cm. What is the scale factor from ABC to A''B''C''?', '[]', '3/4', '9/12', 'Divide a new side by its matching old side: $9 \div 12 = \frac{3}{4}$. The other pairs give the same value: $12 \div 16$ and $15 \div 20$ are also $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 = 12/16 = 15/20 = 3/4.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('770f057b-2caf-4384-bd55-946e7380d979', 'NC26.8.SGMR.2', 2, 'choice', 'Find a scale factor from two lengths', 'A square has sides of 6 cm. It is dilated, and the image square has a perimeter of 60 cm. What is the scale factor?', '["10","0.4","54","2.5"]', '2.5', '60/24', 'The original perimeter is $4 \times 6 = 24$ cm. The scale factor is $60 \div 24 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image side = 60 / 4 = 15 cm. Scale factor 15 / 6 = 2.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('485731f6-e49b-4964-87fe-9ea9c593d0e7', 'NC26.8.SGMR.2', 2, 'choice', 'Find a scale factor from a point and its image', 'A dilation about the origin takes the point (8, -12) to the point (2, -3). What is the scale factor?', '["4","6","1/4","1/2"]', '1/4', '2/8', 'New $x$ divided by old $x$: $2 \div 8 = \frac{1}{4}$. Check with $y$: $-3 \div -12 = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/8 = 1/4 and -3/-12 = 1/4.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
