INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('539cde1f-8caf-4726-bad7-2c37a0c8efa9', 'NC26.8.SGMR.2', 2, 'choice', 'Find a scale factor from a point and its image', 'When a triangle is dilated about the origin, the vertex (9, 15) moves to (6, 10). What is the scale factor?', '["2/3","3/2","3","1/3"]', '2/3', '6/9', 'New $x$ divided by old $x$: $6 \div 9 = \frac{2}{3}$. Check with $y$: $10 \div 15 = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/9 = 10/15 = 2/3.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
