INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e9566ff-e329-4c6b-aff7-21d0d015c03a', 'NC26.8.SGMR.2', 2, 'numeric', 'Find an unknown side using the scale factor', 'A photo is 10 cm wide and 15 cm tall. It is dilated to make a poster whose width is 40 cm. How tall is the poster, in centimeters?', '[]', '60', '15*40/10', 'The scale factor is $40 \div 10 = 4$. The poster is $15 \times 4 = 60$ cm tall.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 40/10 = 4; height 15 * 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9ece0e2-7520-4ecf-9166-bc1c14f1add4', 'NC26.8.SGMR.2', 2, 'numeric', 'Find an unknown side using the scale factor', 'A triangle has sides of 5 cm, 12 cm and 13 cm. A dilation of it has two sides of 7.5 cm and 18 cm. How long is the third side of the image, in centimeters?', '[]', '19.5', '13*7.5/5', 'The scale factor is $7.5 \div 5 = 1.5$ (and $18 \div 12 = 1.5$). The third side is $13 \times 1.5 = 19.5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"19.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.5/5 = 1.5 and 18/12 = 1.5 (no other pairing gives a common factor). Third side 13 * 1.5 = 19.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f70b933-1c95-4a5f-9cda-afcab8308900', 'NC26.8.SGMR.2', 2, 'choice', 'Dilation from a center', 'Point Q is 6 cm from the center of a dilation, and its image Q'' is 15 cm from the center on the same ray. What is the scale factor?', '["2.5","9","90","0.4"]', '2.5', '15/6', 'The scale factor is the new distance divided by the old distance: $15 \div 6 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/6 = 2.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a21add6-8344-4ac2-b274-f636ecf07f6f', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilation from a center', 'The center of a dilation is point O. Point R is 10 cm from O, and its image R'' is 4 cm from O. What is the scale factor? Give your answer as a fraction.', '[]', '2/5', '4/10', 'New distance divided by old distance: $4 \div 10 = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50055532-e5cc-4e76-82a0-23169203aefe', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a segment', 'The segment with endpoints (2, 1) and (2, 7) is dilated about the origin with a scale factor of 4. How long is the image segment, in units?', '["6","28","10","24"]', '24', '(7-1)*4', 'The image has endpoints (8, 4) and (8, 28). Its length is $28 - 4 = 24$ units. (The original is 6 units long, and 6 times 4 is 24.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original length 7 - 1 = 6; image (8,4)-(8,28), length 24.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42225b2b-6e6f-4ab0-ad98-4de1fc3c9970', 'NC26.8.SGMR.2', 2, 'choice', 'Describe a dilation', 'Triangle ABC has vertices A(2, 2), B(4, 2) and C(2, 6). Triangle A''B''C'' has vertices A''(6, 6), B''(12, 6), C''(6, 18). Which dilation about the origin maps ABC onto A''B''C''?', '["A dilation with a scale factor of 4","A dilation with a scale factor of $\\frac{1}{3}$","A dilation with a scale factor of 3","A dilation with a scale factor of 2"]', 'A dilation with a scale factor of 3', NULL, 'Divide an image coordinate by the matching original coordinate: $6 \div 2 = 3$, $12 \div 4 = 3$, $18 \div 6 = 3$. The scale factor is 3.', 'checked', '{"lint":[],"solve":{"answer":"A dilation with a scale factor of 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A(2,2)->(6,6), B(4,2)->(12,6), C(2,6)->(6,18): each coordinate times 3.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd6ff4cd-157e-4f5f-852c-2b235ad32ae0', 'NC26.8.SGMR.2', 2, 'numeric', 'Describe a dilation', 'A rectangle with vertices (0, 0), (4, 0), (4, 3) and (0, 3) is dilated about the origin. The image has vertices (0, 0), (10, 0), (10, 7.5) and (0, 7.5). What is the scale factor?', '[]', '2.5', '10/4', 'Divide an image coordinate by the matching original coordinate: $10 \div 4 = 2.5$. Check with the height: $7.5 \div 3 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/4 = 2.5 and 7.5/3 = 2.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb35181-8ff7-42bc-a1da-c9fd9ec2d37d', 'NC26.8.SGMR.2', 2, 'choice', 'Work backwards to the original figure', 'A dilation about the origin has a scale factor of 3. The image of a point is (12, -18). What is the sum of the coordinates of the original point?', '["-6","-18","2","-2"]', '-2', '(12-18)/3', 'Divide each coordinate by 3 to undo the dilation: the original point is (4, -6). The sum is $4 + (-6) = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original = (12/3, -18/3) = (4, -6). Sum -2.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2a1d349-9b91-4f6f-bb49-22206cc7a5bb', 'NC26.8.SGMR.2', 2, 'choice', 'Work backwards to the original figure', 'After a dilation about the origin with a scale factor of $\frac{1}{4}$, a point is at (3, -2). Which point was dilated?', '["(3/4, -1/2)","(12, -8)","(12, -2)","(-12, 8)"]', '(12, -8)', NULL, 'The dilation multiplied the coordinates by $\frac{1}{4}$, so multiply by 4 to undo it: $(3 \times 4, -2 \times 4) = (12, -8)$.', 'checked', '{"lint":[],"solve":{"answer":"(12, -8)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original = (3, -2) * 4 = (12, -8).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a6ba20b-9226-4945-a6ae-407f1e724f99', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate twice in a row', 'The point (2, 3) is dilated about the origin with a scale factor of 2. The image is then dilated about the origin with a scale factor of 3. What is the $x$-coordinate of the final image?', '["7","6","12","10"]', '12', '2*2*3', 'After the first dilation: $(4, 6)$. After the second: $(12, 18)$. The $x$-coordinate is 12. (The two factors multiply: $2 \times 3 = 6$, and $2 \times 6 = 12$.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3) -> (4,6) -> (12,18). x = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afd02d9e-a693-4e55-8e51-27e65e61d8ba', 'NC26.8.SGMR.2', 2, 'choice', 'Recognize a dilation', 'A rectangle with vertices (0, 0), (2, 0), (2, 1) and (0, 1) becomes a rectangle with vertices (0, 0), (6, 0), (6, 2) and (0, 2). Is this a dilation about the origin?', '["Yes, with a scale factor of 3.","Yes, with a scale factor of 2.","No, because the width and the height were not multiplied by the same number.","No, because a dilation cannot change a rectangle."]', 'No, because the width and the height were not multiplied by the same number.', NULL, 'The width went from 2 to 6, which is multiplied by 3. The height went from 1 to 2, which is multiplied by 2. A dilation multiplies every length by the same scale factor, so this is not a dilation.', 'checked', '{"lint":[],"solve":{"answer":"No, because the width and the height were not multiplied by the same number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 2 -> 6 (times 3), height 1 -> 2 (times 2). Different factors, not a dilation.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0a5ee8e-8e1b-4b33-8edf-6fab4aec25fd', 'NC26.8.SGMR.2', 2, 'choice', 'Recognize a dilation', 'Which rule describes a dilation about the origin with a scale factor of 3?', '["$(x, y) \\to (3x, 3y)$","$(x, y) \\to (x + 3, y + 3)$","$(x, y) \\to (3x, y)$","$(x, y) \\to \\left(\\frac{x}{3}, \\frac{y}{3}\\right)$"]', '$(x, y) \to (3x, 3y)$', NULL, 'A dilation multiplies both coordinates by the scale factor. Adding 3 would slide the figure instead, and multiplying only $x$ would stretch it in one direction.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (3x, 3y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilation about origin, factor 3: (3x, 3y).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2767b9ab-774c-4abb-80b5-dfb76abf8e92', 'NC26.8.SGMR.2', 2, 'choice', 'Find a missing value in a dilation', 'A dilation about the origin with a scale factor of 4 takes the point $(a, 3)$ to the point $(20, 12)$. What is the value of $a$?', '["80","5","16","3"]', '5', '20/4', 'The original $x$-coordinate times 4 equals 20, so $a = 20 \div 4 = 5$. Check: $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a = 20, a = 5 (and 4 * 3 = 12 checks).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9914d394-f8eb-49aa-93a7-41df1ee50c4c', 'NC26.8.SGMR.2', 3, 'numeric', 'Find the area of a dilated triangle', 'A triangle has vertices (0, 0), (4, 0) and (0, 3). It is dilated about the origin with a scale factor of 2. What is the area of the image, in square units?', '[]', '24', '(4*2)*(3*2)/2', 'The image has vertices (0, 0), (8, 0) and (0, 6). It is a right triangle with legs 8 and 6, so its area is $\frac{1}{2} \times 8 \times 6 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image vertices (0,0), (8,0), (0,6): right triangle with legs 8 and 6, area = 1/2 x 8 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b22abd7a-209a-4870-bd6b-a59eff474faa', 'NC26.8.SGMR.2', 3, 'numeric', 'Find the scale factor of a dilation and apply it to another point', 'A dilation about the origin takes the point (6, 9) to the point (4, 6). The same dilation takes the point (15, -3) to a new point. What is the sum of the two coordinates of the new point?', '[]', '8', '(15-3)*4/6', 'The scale factor is $\frac{4}{6} = \frac{2}{3}$ (check: $9 \times \frac{2}{3} = 6$). The point (15, -3) goes to $(15 \times \frac{2}{3}, -3 \times \frac{2}{3}) = (10, -2)$. The sum of the coordinates is $10 + (-2) = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 4/6 = 6/9 = 2/3. (15, -3) -> (10, -2). Sum 10 + (-2) = 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a05a9a9b-4824-4421-bae6-5924156c3f99', 'NC26.8.SGMR.2', 3, 'numeric', 'Use a scale factor found from one pair of sides to find another side', 'A triangle has sides of 9 cm, 12 cm and 15 cm. A dilation makes a new triangle whose shortest side is 6 cm. What is the length of the longest side of the new triangle, in centimeters?', '[]', '10', '15*6/9', 'The shortest side goes from 9 to 6, so the scale factor is $\frac{6}{9} = \frac{2}{3}$. The longest side becomes $15 \times \frac{2}{3} = 10$ cm.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest 9 -> 6, scale factor 2/3. Longest 15 x 2/3 = 10.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afc93fef-0f7d-40e9-a7e2-da9760039033', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate a polygon about the origin', 'A quadrilateral has vertices (4, 2), (8, 2), (10, 6) and (6, 6). It is dilated about the origin with a scale factor of $\frac{3}{2}$. Which list gives the vertices of the image?', '["(6, 2), (12, 2), (15, 6), (9, 6)","(6, 3), (12, 3), (15, 9), (9, 9)","(8, 4), (16, 4), (20, 12), (12, 12)","(12, 6), (24, 6), (30, 18), (18, 18)"]', '(6, 3), (12, 3), (15, 9), (9, 9)', NULL, 'Multiply each coordinate by $\frac{3}{2}$: (6, 3), (12, 3), (15, 9), (9, 9).', 'checked', '{"lint":[],"solve":{"answer":"(6, 3), (12, 3), (15, 9), (9, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Times 3/2: (4,2)->(6,3), (8,2)->(12,3), (10,6)->(15,9), (6,6)->(9,9).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3b615e8-930e-4fde-9cd1-482681e849a1', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate a polygon about the origin', 'A triangle has vertices (-2, 4), (6, 0) and (-4, -8). Which list gives the vertices of its image after a dilation about the origin with a scale factor of $\frac{1}{2}$?', '["(-4, 8), (12, 0), (-8, -16)","(-1, 4), (3, 0), (-2, -8)","(-1, 2), (3, 0), (-2, -4)","(1, 2), (3, 0), (2, 4)"]', '(-1, 2), (3, 0), (-2, -4)', NULL, 'Halve every coordinate, keeping the signs: (-1, 2), (3, 0), (-2, -4).', 'checked', '{"lint":[],"solve":{"answer":"(-1, 2), (3, 0), (-2, -4)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halve each coordinate: (-1, 2), (3, 0), (-2, -4).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
