INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fec200da-ecf8-4d6d-84ff-e36131f87920', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate twice in a row', 'A segment is 12 cm long. It is dilated with a scale factor of $\frac{2}{3}$. The image is dilated with a scale factor of $\frac{3}{4}$. How long is the final segment, in centimeters?', '["6","8","9","12"]', '6', '12*2/3*3/4', 'After the first dilation: $12 \times \frac{2}{3} = 8$ cm. After the second: $8 \times \frac{3}{4} = 6$ cm.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 * 2/3 = 8; 8 * 3/4 = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
