INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fde318ec-b5c6-4e66-abfc-8c3939d9aada', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate twice in a row', 'A triangle is dilated about the origin with a scale factor of 4. The image is then dilated about the origin with a scale factor of $\frac{1}{2}$. Which single dilation gives the same result?', '["A scale factor of 4.5","A scale factor of 8","A scale factor of $\\frac{1}{8}$","A scale factor of 2"]', 'A scale factor of 2', NULL, 'The scale factors multiply: $4 \times \frac{1}{2} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"A scale factor of 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 * 1/2 = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ff83e9f-ccca-475c-94f6-3c06e7881818', 'NC26.8.SGMR.2', 3, 'numeric', 'Dilate twice in a row', 'A triangle has an area of 10 square units. It is dilated with a scale factor of 2, and the image is dilated with a scale factor of 3. What is the area of the final triangle, in square units?', '[]', '360', '10*(2*3)^2', 'The two scale factors multiply to $2 \times 3 = 6$. Area is multiplied by the square of the scale factor: $10 \times 6^2 = 360$ square units.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total factor 2 * 3 = 6; area scales by 36: 10 * 36 = 360.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa49cc5-d2eb-47e2-81b6-91448db2ee74', 'NC26.8.SGMR.2', 3, 'choice', 'Recognize a dilation', 'Triangle ABC has vertices A(1, 2), B(3, 2) and C(1, 5). Which set of points could be the vertices of its image after a dilation about the origin?', '["(2, 4), (6, 4), (2, 5)","(2, 2), (6, 2), (2, 5)","(3, 4), (5, 4), (3, 7)","(2, 4), (6, 4), (2, 10)"]', '(2, 4), (6, 4), (2, 10)', NULL, 'A dilation multiplies every coordinate by the same number. Only (2, 4), (6, 4), (2, 10) comes from multiplying all the coordinates by 2. The others multiply only some coordinates or add instead of multiply.', 'checked', '{"lint":[],"solve":{"answer":"(2, 4), (6, 4), (2, 10)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2),(3,2),(1,5) times 2 = (2,4),(6,4),(2,10). Others: A and B scale x and y differently; C is a translation by (2,2).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97f78d40-bc95-45b4-9dc4-402f467f758b', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A dilation about the origin takes the point $(6, m)$ to the point $(15, 10)$. What is the value of $m$?', '[]', '4', '10/(15/6)', 'The scale factor is $15 \div 6 = 2.5$. Then $m \times 2.5 = 10$, so $m = 10 \div 2.5 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 15/6 = 2.5; m = 10/2.5 = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bccec2fd-ecc2-4d4e-95ae-d348f2870f33', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A dilation about the origin takes (4, -6) to (10, -15). The same dilation takes (6, $h$) to (15, 20). What is the value of $h$?', '[]', '8', '20/(10/4)', 'The scale factor is $10 \div 4 = 2.5$ (and $15 \div 6 = 2.5$). Then $h \times 2.5 = 20$, so $h = 20 \div 2.5 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 10/4 = -15/-6 = 2.5. 6 * 2.5 = 15 checks; h = 20 / 2.5 = 8.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f6508d0-6a39-47c4-95a1-305f948c1a52', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A right triangle has vertices $(0, 0)$, $(8, 0)$ and $(0, c)$, where $c$ is greater than 0. It is dilated about the origin with a scale factor of 3, and the image has an area of 108 square units. What is the value of $c$?', '[]', '3', '108/9/4', 'The image has vertices $(0, 0)$, $(24, 0)$ and $(0, 3c)$. Its area is $\frac{1}{2} \times 24 \times 3c = 36c$. Setting $36c = 108$ gives $c = 3$. Check: the original area is $\frac{1}{2} \times 8 \times 3 = 12$, and $12 \times 3^2 = 108$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original area 8c/2=4c. Scale 3 multiplies area by 9: 36c=108, c=3.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dec18ce-a043-4363-9e5d-096cdee9f20f', 'NC26.8.SGMR.3', 1, 'choice', 'Use the side-length condition for a triangle', 'Which three lengths, in centimeters, can be the sides of a triangle?', '["3, 4, 8","2, 3, 5","4, 4, 9","5, 6, 10"]', '5, 6, 10', NULL, 'The two shorter sides must add up to more than the longest side. $5 + 6 = 11 > 10$ works. $3 + 4 = 7 < 8$, $2 + 3 = 5$ (equal, not more), and $4 + 4 = 8 < 9$ all fail.', 'checked', '{"lint":[],"solve":{"answer":"5, 6, 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4=7 < 8 no; 2+3=5 = 5 no (flat); 4+4=8 < 9 no; 5+6=11 > 10 yes (and 5+10>6, 6+10>5).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
