INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a969673-d4cd-4a9b-a47f-7fd6c760e0f0', 'NC26.8.SGMR.3', 1, 'choice', 'Range of the third side', 'A triangle has two sides of 5 cm and 6 cm. Which length can NOT be the third side, in centimeters?', '["2","6","10","11"]', '11', NULL, 'The third side must be less than $5 + 6 = 11$ and more than $6 - 5 = 1$. So 2, 6 and 10 can all work, but 11 would make the sides lie flat.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must satisfy 1 < x < 11. 2, 6, 10 all fit; 11 = 5+6 gives a flat figure. Cannot be 11.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
