INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4018f07-4dbb-4d37-aa26-7acebe8070aa', 'NC26.8.SGMR.3', 1, 'choice', 'Isosceles triangles and the side condition', 'An isosceles triangle has two equal sides of 5 cm. Which could be the length of the third side, in centimeters?', '["8","10","12","15"]', '8', NULL, 'The third side must be less than $5 + 5 = 10$. Only 8 is less than 10. A 10 cm side would make the two 5 cm sides lie flat along it.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must be less than 5+5 = 10 (and more than 0). 10, 12, 15 fail; 8 works (5+5=10>8).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
