VALUES ('e2081115-f11a-4225-9b8a-5cabad70d6d3', 'NC26.8.SGMR.3', 1, 'choice', 'Missing angle from the 180 degree sum', 'Two angles of a triangle measure $52^\circ$ and $61^\circ$. What is the measure of the third angle, in degrees?', '["67","113","119","128"]', '67', '180-52-61', '$52 + 61 = 113$, and $180 - 113 = 67$. The number 113 is the sum of the two angles, 119 is $180 - 61$ and 128 is $180 - 52$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 52 - 61 = 180 - 113 = 67.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
