INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b13e309-46b6-4c24-a6e4-5f63a0a7d124', 'NC26.8.SGMR.3', 2, 'choice', 'Missing angle from the 180 degree sum', 'An isosceles triangle has a top angle of $40^\circ$ between its two equal sides. What is the measure of one of the other two angles, in degrees?', '["40","70","80","140"]', '70', '(180-40)/2', 'The other two angles are equal and share $180 - 40 = 140$ degrees, so each is $140 \div 2 = 70$ degrees. The number 140 forgets to split between the two angles.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The other two angles are equal: (180 - 40)/2 = 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
