INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dab1a991-f807-4d71-9ab9-2af40dd7de64', 'NC26.8.SGMR.3', 2, 'numeric', 'Missing angle from the 180 degree sum', 'In a right triangle, one acute angle measures $37^\circ$. What is the measure of the other acute angle, in degrees?', '[]', '53', '90-37', 'The right angle is $90^\circ$, so the two acute angles share $180 - 90 = 90$ degrees. The other is $90 - 37 = 53$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"53","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acute angles of a right triangle sum to 90: 90 - 37 = 53.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
