INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24e83b46-f690-4ece-950c-55bc715393af', 'NC26.8.SGMR.3', 2, 'choice', 'Which angle measures can form a triangle', 'Which statement about the angles of a triangle is true?', '["A triangle can have two right angles","A triangle can have one obtuse angle and two acute angles","A triangle can have two obtuse angles","A triangle can have one right angle and one obtuse angle"]', 'A triangle can have one obtuse angle and two acute angles', NULL, 'An obtuse angle is more than $90^\circ$ and a right angle is exactly $90^\circ$. Two angles of these kinds would already add to more than $180^\circ$ with the third angle still to come. One obtuse angle with two acute angles is possible, for example $100^\circ$, $40^\circ$ and $40^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"A triangle can have one obtuse angle and two acute angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two obtuse or two right angles, or right+obtuse, already reach 180 or more, leaving nothing for a third angle. One obtuse with two acute (e.g. 100, 40, 40) works.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2228f4d4-94e5-4141-a1da-ad7a6b023071', 'NC26.8.SGMR.3', 2, 'numeric', 'How many triangles fit the given measures', 'A triangle has angles of $40^\circ$ and $60^\circ$, and the side between those two angles is 7 cm long. How many different triangles fit this description?', '[]', '1', NULL, 'Two angles and the side between them fix the triangle: the third angle is $80^\circ$ and the rest follows. There is exactly 1 triangle.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two angles and the included side (ASA) fix the triangle; 40+60 < 180. Exactly one.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('649d4238-92aa-4b51-9188-026c8d95e83d', 'NC26.8.SGMR.3', 2, 'choice', 'How many triangles fit the given measures', 'Priya wants two classmates to build exactly the same triangle from her instructions. Which instructions should she give?', '["Two angles of $50^\\circ$ and $60^\\circ$","Two sides of 5 cm and 7 cm, and the $60^\\circ$ angle between them","One side of 8 cm and one angle of $40^\\circ$","Three angles of $50^\\circ$, $60^\\circ$ and $70^\\circ$"]', 'Two sides of 5 cm and 7 cm, and the $60^\circ$ angle between them', NULL, 'Two sides and the angle between them leave only one way to close the triangle. Two angles, or one side and one angle, leave sizes or shapes free, and three angles allow triangles of many sizes.', 'checked', '{"lint":[],"solve":{"answer":"Two sides of 5 cm and 7 cm, and the $60^\\circ$ angle between them","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two sides and the included angle (SAS) fix one triangle. Three angles or two angles give many sizes; one side and one angle give many.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c94c556b-931c-4127-b8e1-70925683f657', 'NC26.8.SGMR.3', 2, 'numeric', 'How many triangles fit the given measures', 'A triangle has angles of $50^\circ$ and $60^\circ$. A side of 9 cm is opposite the $50^\circ$ angle. How many different triangles fit this description?', '[]', '1', NULL, 'The third angle is $180 - 50 - 60 = 70$ degrees. Two angles and a side fix the triangle, and 9 cm opposite the $50^\circ$ angle sets the size. There is exactly 1 triangle.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third angle 70. Angles fixed and the side opposite 50 is 9 cm: AAS fixes one triangle (scale is set by that side).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3eb5f5e0-2f26-4969-8143-2cca6ccd5fae', 'NC26.8.SGMR.3', 2, 'choice', 'How many triangles fit the given measures', 'Four sets of directions for drawing a triangle are given. Which set leads to no triangle at all?', '["Sides of 4 cm, 5 cm and 6 cm","Angles of $20^\\circ$, $60^\\circ$ and $100^\\circ$","Sides of 3 cm, 3 cm and 8 cm","Angles of $40^\\circ$ and $70^\\circ$ with a 5 cm side between them"]', 'Sides of 3 cm, 3 cm and 8 cm', NULL, '$3 + 3 = 6 < 8$, so those sides cannot make a triangle. The sides 4, 5, 6 work ($9 > 6$), the angles $20 + 60 + 100 = 180$ work, and two angles with the side between them always work when they add to less than $180^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Sides of 3 cm, 3 cm and 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+3 = 6 < 8: no triangle. 20+60+100 = 180 works; 4,5,6 works; 40+70 < 180 with included side works. Answer: sides 3, 3, 8.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efdb59c8-48bc-4af6-bf88-9fc87ff1abd1', 'NC26.8.SGMR.3', 2, 'choice', 'Reason with a model, a rule or a claim', 'Ana says, "The sticks of 7 cm, 9 cm and 16 cm will make a triangle, because 7 + 9 is greater than 16." Which statement about Ana is correct?', '["Ana is wrong, because 7 + 9 equals 16 and is not greater than 16","Ana is right, because 16 is the longest side","Ana is right, because all three lengths are different","Ana is wrong, because 7 + 16 is less than 9"]', 'Ana is wrong, because 7 + 9 equals 16 and is not greater than 16', NULL, '$7 + 9 = 16$, which is equal to 16, not greater. The sticks would lie flat, so there is no triangle. Ana is wrong, and her reason fails because of that.', 'checked', '{"lint":[],"solve":{"answer":"Ana is wrong, because 7 + 9 equals 16 and is not greater than 16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 9 = 16, equal to the longest stick, not greater; Ana''s claim ''7 + 9 is greater than 16'' is false and no triangle forms.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abb3e2da-9c3e-4bad-a77a-82514a6b5f8f', 'NC26.8.SGMR.3', 2, 'choice', 'Reason with a model, a rule or a claim', 'Two students each build a triangle from sticks of 6 cm, 7 cm and 8 cm. What is true about their triangles?', '["They can have different angles, as a four-stick frame can lean","They must be the same size and shape, because three side lengths fix a triangle","They can have different angles, depending on which stick is laid at the bottom","They can be the same size but not the same shape"]', 'They must be the same size and shape, because three side lengths fix a triangle', NULL, 'A triangle made from three given sticks is rigid: it cannot lean or change its angles. Any two such triangles are exactly the same size and shape (one may just be turned or flipped over).', 'checked', '{"lint":[],"solve":{"answer":"They must be the same size and shape, because three side lengths fix a triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three side lengths determine a unique triangle (SSS): both triangles are congruent, same size and shape, whichever side is at the bottom.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fd62ecf-93c1-4014-aee6-b1e34e1a9d51', 'NC26.8.SGMR.3', 2, 'choice', 'Reason with a model, a rule or a claim', 'Which statement is true?', '["Any two obtuse angles can be two of the angles of a triangle","Any two right angles can be two of the angles of a triangle","Any two acute angles can be two of the angles of a triangle","Any two angles can be two of the angles of a triangle"]', 'Any two acute angles can be two of the angles of a triangle', NULL, 'Each acute angle is less than $90^\circ$, so two acute angles add to less than $180^\circ$ and a third angle is left over. Two obtuse angles, or two right angles, already add to $180^\circ$ or more.', 'checked', '{"lint":[],"solve":{"answer":"Any two acute angles can be two of the angles of a triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two acute angles sum to less than 180, leaving a positive third angle, so it always works. Two right or two obtuse angles reach 180 or more; ''any two angles'' fails for e.g. 100 and 100.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('664b95f6-d233-4ffb-a20d-f9e39ce17c70', 'NC26.8.SGMR.3', 2, 'numeric', 'Reason with a model, a rule or a claim', 'Two sticks, 5 cm and 8 cm long, are joined at one end by a hinge. A string connects their free ends to make the third side of a triangle. The hinge can open to any angle between $0^\circ$ and $180^\circ$, but not to exactly $0^\circ$ or $180^\circ$. The string is a whole number of centimeters long. What is the longest string that can still make a triangle, in centimeters?', '[]', '12', '5+8-1', 'When the hinge is almost flat (nearly $180^\circ$), the string is nearly $5 + 8 = 13$ cm, but it must be less than 13 cm. The greatest whole number is 12 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hinge angle strictly between 0 and 180 means the string is strictly between 8-5 = 3 and 8+5 = 13. Longest whole number 12.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aa38b38-8ab4-4c4b-aa4d-01a9cf121daf', 'NC26.8.SGMR.3', 3, 'numeric', 'Count the possible whole-number lengths of a third side', 'Two sides of a triangle are 8 cm and 11 cm long. The third side is a whole number of centimeters. How many different lengths are possible for the third side?', '[]', '15', '(8+11-1)-(11-8+1)+1', 'The third side must be greater than $11 - 8 = 3$ and less than $8 + 11 = 19$. The whole numbers from 4 to 18 work, and there are $18 - 4 + 1 = 15$ of them.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 - 8 < s < 11 + 8 -> 3 < s < 19, so s = 4, 5, ..., 18: 18 - 4 + 1 = 15 lengths.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c85fbb4-46b6-472a-b112-5dbc809d40cd', 'NC26.8.SGMR.3', 3, 'numeric', 'Use an algebra equation with the angle sum of a triangle', 'The angles of a triangle measure $x$ degrees, $(2x + 10)$ degrees and $(3x - 10)$ degrees. What is the measure of the largest angle, in degrees?', '[]', '80', '3*(180/6)-10', 'The angles add to 180: $x + (2x + 10) + (3x - 10) = 6x = 180$, so $x = 30$. The angles are $30$, $2(30) + 10 = 70$ and $3(30) - 10 = 80$. The largest is 80 degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 10 + 3x - 10 = 6x = 180 -> x = 30. Angles 30, 70, 80. Largest 80.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3cc5c2-4b6b-44fb-b18b-36ffc666598f', 'NC26.8.SGMR.3', 3, 'choice', 'Decide how many triangles fit given sides and the angle between them', 'A triangle has one side of 10 cm and another side of 12 cm, and the angle between those two sides is $30^\circ$. How many triangles with different shapes or sizes can be built with these measurements?', '["Exactly two","None","Exactly one","Infinitely many"]', 'Exactly one', NULL, 'Two sides and the angle between them fix the third side and the other two angles, so only one triangle (up to identical size and shape) can be built.', 'checked', '{"lint":[],"solve":{"answer":"Exactly one","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two sides and the included angle (SAS) fix the triangle: exactly one.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2aa8bd33-dc7b-4677-aa33-8f2c412604eb', 'NC26.8.SGMR.3', 3, 'numeric', 'Side lengths: can they form a triangle?', 'Five sets of side lengths, in centimeters, are listed: 1.2, 1.5, 2.8; 2.4, 3.1, 5.4; 0.9, 0.9, 1.9; 4.5, 5, 9.4; 3.2, 3.2, 6.4. How many of the sets can be the sides of a triangle?', '[]', '2', NULL, '$1.2 + 1.5 = 2.7 < 2.8$ fails. $2.4 + 3.1 = 5.5 > 5.4$ works. $0.9 + 0.9 = 1.8 < 1.9$ fails. $4.5 + 5 = 9.5 > 9.4$ works. $3.2 + 3.2 = 6.4$, not more than 6.4, fails. Two sets work.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2+1.5=2.7<2.8 no. 2.4+3.1=5.5>5.4 yes. 0.9+0.9=1.8<1.9 no. 4.5+5=9.5>9.4 yes. 3.2+3.2=6.4=6.4 no. Two sets.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
