INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9764b3a-d6c3-4378-b1b7-8db26853e087', 'NC26.8.SGMR.4', 1, 'numeric', 'Linear pairs and vertical angles', 'Angle $A$ and angle $B$ are supplementary. Angle $A$ measures $125^\circ$. What is the measure of angle $B$, in degrees?', '[]', '55', '180-125', 'Supplementary angles add to $180^\circ$. So angle $B$ is $180 - 125 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Supplementary: 180 - 125 = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
