INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de3c853f-709c-48d8-8968-7632b65b7be5', 'NC26.8.SGMR.4', 1, 'numeric', 'Corresponding angles and parallel lines', 'Parallel lines $\ell$ and $m$ are crossed by a line $t$. Angle $a$ is at $\ell$ and angle $b$ is at $m$, and they are corresponding angles. Angle $a$ measures $75^\circ$. What is the measure of angle $b$, in degrees?', '[]', '75', NULL, 'When parallel lines are crossed by a transversal, corresponding angles are equal. So angle $b$ measures 75 degrees.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles on parallel lines are equal: 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
