INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d2f5bfc-5c5f-4560-84b8-8f6ab77c6e66', 'NC26.8.SGMR.4', 1, 'choice', 'Corresponding angles and parallel lines', 'A road crosses two parallel railroad tracks. At the first track, one of the angles formed measures $132^\circ$. What is the measure of the corresponding angle at the second track, in degrees?', '["42","48","66","132"]', '132', NULL, 'The tracks are parallel, so corresponding angles are equal: 132 degrees. The number 48 is the angle next to it on a straight line ($180 - 132$).', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles are equal: 132.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
