INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96e8c29e-665f-4792-9041-ed2525d9b855', 'NC26.8.SGMR.4', 1, 'numeric', 'Corresponding angles and parallel lines', 'Parallel lines are crossed by a transversal. Two corresponding angles measure $(x+30)^\circ$ and $80^\circ$. What is the value of $x$?', '[]', '50', '80-30', 'Corresponding angles are equal, so $x + 30 = 80$ and $x = 50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 30 = 80, x = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
