INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45d5df1f-04e9-47d0-ab78-98ad80e6477c', 'NC26.8.SGMR.4', 1, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Two parallel lines are crossed by a transversal. Two alternate interior angles are formed, one at each line. One of them measures $105^\circ$. What is the measure of the other, in degrees?', '["15","75","105","255"]', '105', NULL, 'Alternate interior angles formed by parallel lines are equal, so the other angle is also 105 degrees. The number 75 is the angle next to it on a straight line.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior angles are equal: 105.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
