INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3df6f5cc-c520-4e2f-81a6-dd443ac6bfff', 'NC26.8.SGMR.4', 1, 'choice', 'Same-side interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Which pair of angles is NOT always equal in measure?', '["Same-side interior angles","Corresponding angles","Alternate interior angles","Alternate exterior angles"]', 'Same-side interior angles', NULL, 'Corresponding, alternate interior and alternate exterior angles are equal when the lines are parallel. Same-side interior angles add to $180^\circ$, so they are equal only when each is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Same-side interior angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior, corresponding and alternate exterior angles are equal; same-side interior angles are supplementary, equal only when both are 90.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d74ad7-456c-4abb-b1b5-c111eb17f620', 'NC26.8.SGMR.4', 1, 'numeric', 'Choose the angle relationship from the positions', 'Parallel lines $\ell$ (the upper line) and $m$ (the lower line) are crossed by a transversal $t$. Angle $p$ is at $\ell$, above $\ell$ and to the left of $t$. Angle $q$ is at $m$, above $m$ and to the left of $t$. Angle $p$ measures $(2x+10)^\circ$ and angle $q$ measures $70^\circ$. What is the value of $x$?', '[]', '30', '(70-10)/2', 'Angles $p$ and $q$ are in matching positions, so they are corresponding angles and are equal: $2x + 10 = 70$. Then $2x = 60$ and $x = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both above their line and left of t: corresponding angles, equal. 2x + 10 = 70, x = 30.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1bfbcce-1163-4dac-876f-a2c720ecfd7e', 'NC26.8.SGMR.4', 1, 'choice', 'Choose the angle relationship from the positions', 'Parallel lines are crossed by a transversal. Two same-side interior angles measure $(3x)^\circ$ and $(x+40)^\circ$. Which equation can be used to find $x$?', '["$3x=x+40$","$3x+(x+40)=90$","$3x+(x+40)=360$","$3x+(x+40)=180$"]', '$3x+(x+40)=180$', NULL, 'Same-side interior angles formed by parallel lines are supplementary: they add to $180^\circ$. So $3x + (x+40) = 180$, which gives $x = 35$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+(x+40)=180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angles are supplementary: 3x + (x+40) = 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20966e94-9782-48f9-bce5-bc091e694def', 'NC26.8.SGMR.4', 1, 'choice', 'Tell whether lines are parallel from angle measures', 'Two lines are crossed by a transversal. A pair of corresponding angles each measure $65^\circ$. What can you conclude about the two lines?', '["The two lines are parallel","The two lines are perpendicular","The two lines are not parallel","Nothing, because more angles are needed"]', 'The two lines are parallel', NULL, 'If corresponding angles are equal, the lines are parallel. This is the reverse of the rule for parallel lines. One equal pair of corresponding angles is enough.', 'checked', '{"lint":[],"solve":{"answer":"The two lines are parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal corresponding angles mean the lines are parallel (converse of the corresponding angles property).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e2a980f-6068-4452-b37c-0a2ae9d41f74', 'NC26.8.SGMR.4', 1, 'numeric', 'Multi-step angle problems with parallel lines', 'A transversal crosses two parallel lines, forming eight angles. One of the eight angles measures $50^\circ$. How many of the other seven angles also measure $50^\circ$?', '[]', '3', NULL, 'Four of the eight angles measure $50^\circ$ (the given one, its vertical angle, and the two corresponding angles at the other line). The other four measure $130^\circ$. So three of the other seven angles also measure 50 degrees.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The eight angles are four of 50 and four of 130. Besides the given one, 3 others measure 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51a0be54-4b47-4edd-ae41-c8783a33e1e2', 'NC26.8.SGMR.4', 1, 'numeric', 'Multi-step angle problems in triangles and around points', 'Three angles fit together along a straight line. Two of them measure $35^\circ$ and $90^\circ$. What is the measure of the third angle, in degrees?', '[]', '55', '180-35-90', 'Angles along a straight line add to $180^\circ$. The third angle is $180 - 35 - 90 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles along a straight line sum to 180: 180 - 35 - 90 = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
