INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e794afc-8d3e-4724-86f1-9b7a743c10d0', 'NC26.8.SGMR.4', 1, 'choice', 'Multi-step angle problems in triangles and around points', 'Four angles fit together around a point. Three of them measure $90^\circ$, $120^\circ$ and $75^\circ$. What is the measure of the fourth angle, in degrees?', '["285","165","150","75"]', '75', '360-90-120-75', 'Angles around a point add to $360^\circ$. $90 + 120 + 75 = 285$, and $360 - 285 = 75$ degrees. The number 285 is the sum of the three angles.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles around a point sum to 360: 360 - 90 - 120 - 75 = 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
