INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5546ac1-c07d-4d8b-aa38-6bf7c394b146', 'NC26.8.SGMR.4', 2, 'numeric', 'Unknown angles in a triangle (algebra)', 'The angles of a triangle measure $(x+10)^\circ$, $(2x)^\circ$ and $(x+30)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '70', '2*(180-40)/4', 'The angles add up to $180$: $(x+10) + 2x + (x+30) = 4x + 40 = 180$, so $4x = 140$ and $x = 35$. The angles are $45^\circ$, $70^\circ$ and $65^\circ$. The largest is $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+10) + 2x + (x+30) = 180 -> 4x + 40 = 180 -> x = 35. Angles: 45, 70, 65. Largest = 70.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8aa47413-92fe-4336-b197-26e143899abc', 'NC26.8.SGMR.4', 2, 'numeric', 'Alternate interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two alternate interior angles measure $(3x+5)^\circ$ and $65^\circ$. What is the value of $x$?', '[]', '20', '(65-5)/3', 'Alternate interior angles are equal when the lines are parallel. So $3x + 5 = 65$. Subtract 5: $3x = 60$. Divide by 3: $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior angles are congruent: 3x + 5 = 65 -> 3x = 60 -> x = 20.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06f64e13-493f-4479-a52c-24a49bbcc5ec', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two angles on the same side of the transversal and between the parallel lines measure $(2x+10)^\circ$ and $(x+20)^\circ$. What is the value of $x$?', '["10","50","60","70"]', '50', '(180-30)/3', 'Same-side interior angles add up to $180^\circ$ when the lines are parallel. So $(2x+10) + (x+20) = 180$, which gives $3x + 30 = 180$. Then $3x = 150$ and $x = 50$. The angles are $110^\circ$ and $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angles are supplementary: (2x+10) + (x+20) = 180 -> 3x + 30 = 180 -> x = 50. Check: 110 + 70 = 180.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a27984ce-20f3-434c-b082-37cc793029b9', 'NC26.8.SGMR.4', 2, 'numeric', 'Angle sum of a triangle', 'In triangle $ABC$, angle $C$ measures $60^\circ$ and angle $A$ is twice as large as angle $B$. What is the measure of angle $A$, in degrees?', '[]', '80', '(180-60)/3*2', 'Angles $A$ and $B$ share $180 - 60 = 120$ degrees. Since $A$ is twice $B$, they are 3 equal parts: $B = 120 \div 3 = 40$ degrees and $A = 2 \times 40 = 80$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A + B = 180 - 60 = 120 with A = 2B: 3B = 120, B = 40, A = 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f586d33-a1b4-4dd8-a13f-162f4fe8fe53', 'NC26.8.SGMR.4', 2, 'choice', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $(2x)^\circ$, $(3x)^\circ$ and $(4x)^\circ$. What is the measure of the smallest angle, in degrees?', '["20","40","60","80"]', '40', '2*180/9', '$2x + 3x + 4x = 9x = 180$, so $x = 20$. The smallest angle is $2x = 40$ degrees. The number 20 is the value of $x$, and 60 and 80 are the other two angles.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3x + 4x = 9x = 180, x = 20. Smallest angle 2x = 40 (angles 40, 60, 80).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eecb2c27-bc61-460e-8861-3d4a40ff7ecd', 'NC26.8.SGMR.4', 2, 'numeric', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $(x+15)^\circ$, $(2x-5)^\circ$ and $(3x+2)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '86', '3*28+2', '$(x+15) + (2x-5) + (3x+2) = 6x + 12 = 180$, so $6x = 168$ and $x = 28$. The angles are $43^\circ$, $51^\circ$ and $86^\circ$, so the largest is 86 degrees.', 'checked', '{"lint":[],"solve":{"answer":"86","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+15)+(2x-5)+(3x+2) = 6x + 12 = 180, x = 28. Angles 43, 51, 86 (sum 180). Largest 86.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a86159e-14f2-4d45-86f7-a9e05a3090f5', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angle from the two far interior angles', 'In triangle $PQR$, side $QR$ is extended past $R$ to a point $S$. Angle $P$ measures $58^\circ$ and angle $Q$ measures $47^\circ$. What is the measure of angle $PRS$, in degrees?', '["75","105","122","133"]', '105', '58+47', 'Angle $PRS$ is the exterior angle at $R$, so it equals $P + Q = 58 + 47 = 105$ degrees. The number 75 is the interior angle $R$ ($180 - 105$), 122 is $180 - 58$ and 133 is $180 - 47$.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PRS is the exterior angle at R: P + Q = 58 + 47 = 105.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e50c730e-b3cf-4a33-8c6c-9a359fe70e91', 'NC26.8.SGMR.4', 2, 'numeric', 'Exterior angle from the two far interior angles', 'A triangle has angles of $64^\circ$, $57^\circ$ and $59^\circ$. A side is extended to make an exterior angle at the vertex of the $59^\circ$ angle. What is the measure of that exterior angle, in degrees?', '[]', '121', '64+57', 'The exterior angle equals the sum of the two interior angles not next to it: $64 + 57 = 121$ degrees. Check: $180 - 59 = 121$.', 'checked', '{"lint":[],"solve":{"answer":"121","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 59 = 121 (= 64 + 57).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
