INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7ccc79-f8f4-43dc-96f7-3a6662d90004', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angle from the two far interior angles', 'Which statement about an exterior angle of a triangle is always true?', '["It is always an obtuse angle","It always equals the interior angle next to it","It is always smaller than each interior angle that is not next to it","It equals the sum of the two interior angles that are not next to it"]', 'It equals the sum of the two interior angles that are not next to it', NULL, 'The exterior angle and the interior angle next to it form a straight line, so the exterior angle is $180^\circ$ minus that interior angle, which equals the other two interior angles added together. It can be acute, it is not equal to its neighbour in general, and it is larger than each of the two far angles.', 'checked', '{"lint":[],"solve":{"answer":"It equals the sum of the two interior angles that are not next to it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle theorem: it equals the sum of the two remote interior angles. It is acute when the interior angle is obtuse, it is supplementary (not equal) to the adjacent interior angle, and it is larger than each remote angle.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a6e25f4-e322-4b0c-b2b0-e0eeee822f81', 'NC26.8.SGMR.4', 2, 'numeric', 'Interior angle from an exterior angle', 'A triangle has an exterior angle of $140^\circ$. One of the two interior angles not next to it measures $90^\circ$. What is the measure of the other one, in degrees?', '[]', '50', '140-90', 'The exterior angle equals the sum of the two interior angles not next to it. So the other angle is $140 - 90 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior = sum of the two remote interior angles: 140 - 90 = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a90064d0-d1ff-48a9-ac86-32b7418239d4', 'NC26.8.SGMR.4', 2, 'choice', 'Interior angle from an exterior angle', 'In triangle $ABC$, the exterior angle at $A$ measures $100^\circ$ and angle $B$ measures $30^\circ$. What is the measure of angle $C$, in degrees?', '["50","70","80","130"]', '70', '100-30', 'The exterior angle at $A$ equals $B + C$, so $C = 100 - 30 = 70$ degrees. (Check: the interior angle at $A$ is $80^\circ$, and $80 + 30 + 70 = 180$.)', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at A = B + C: 100 = 30 + C, C = 70. Check: interior A = 80, 80+30+70 = 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7355aab-b037-43de-bf27-f937627e19de', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angles with algebra', 'The exterior angle of a triangle measures $(3x+15)^\circ$. The two interior angles not next to it measure $(x+20)^\circ$ and $(x+45)^\circ$. What is the measure of the exterior angle, in degrees?', '["165","70","50","15"]', '165', '3*50+15', '$3x + 15 = (x+20) + (x+45) = 2x + 65$, so $x = 50$. The exterior angle is $3 \times 50 + 15 = 165$ degrees. The number 50 is only $x$, and 70 is one of the far angles.', 'checked', '{"lint":[],"solve":{"answer":"165","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 15 = (x+20) + (x+45) = 2x + 65, x = 50. Exterior = 3(50) + 15 = 165 (remote angles 70 and 95).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa90d7f6-8753-4751-bb88-7ea06862f6ea', 'NC26.8.SGMR.4', 2, 'choice', 'Linear pairs and vertical angles', 'Two lines cross. One angle measures $(3x)^\circ$ and the angle directly opposite it measures $(x+50)^\circ$. What is the value of $x$?', '["25","50","75","130"]', '25', '50/2', 'Opposite angles are equal, so $3x = x + 50$. Then $2x = 50$ and $x = 25$. (The angle itself is $75^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles equal: 3x = x + 50, 2x = 50, x = 25 (both 75).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cf2fdf8-2c82-40c1-964b-453a1476cc9c', 'NC26.8.SGMR.4', 2, 'choice', 'Linear pairs and vertical angles', 'Two lines cross, forming four angles. One angle is 4 times as large as an angle next to it. What is the measure of the smaller of these two angles, in degrees?', '["144","72","45","36"]', '36', '180/5', 'Angles next to each other where two lines cross add to $180^\circ$. With parts of 1 and 4, that is 5 equal parts: $180 \div 5 = 36$ degrees. The larger angle is $4 \times 36 = 144$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles form a linear pair: x + 4x = 180, x = 36 (other 144). Smaller 36.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370d6118-c34b-47b5-80b2-df78edb9559a', 'NC26.8.SGMR.4', 2, 'choice', 'Corresponding angles and parallel lines', 'Two parallel lines are crossed by a transversal. Two corresponding angles measure $(4x-15)^\circ$ and $(2x+25)^\circ$. What is the value of $x$?', '["10","20","40","65"]', '20', '(25+15)/2', 'Corresponding angles are equal: $4x - 15 = 2x + 25$, so $2x = 40$ and $x = 20$. (Each angle is $65^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 15 = 2x + 25, 2x = 40, x = 20 (both 65).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f93a12f-825c-4b5c-8ff8-c5979ae3a00d', 'NC26.8.SGMR.4', 2, 'numeric', 'Corresponding angles and parallel lines', 'Parallel lines are crossed by a transversal. An angle of $64^\circ$ at the upper line has a corresponding angle at the lower line. Angle $z$ forms a linear pair with that corresponding angle. What is the measure of angle $z$, in degrees?', '[]', '116', '180-64', 'The corresponding angle at the lower line is also $64^\circ$. A linear pair adds to $180^\circ$, so angle $z$ is $180 - 64 = 116$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"116","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angle at the lower line is 64; z forms a linear pair with it: 180 - 64 = 116.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce6cb0d-cff5-4069-9023-b771fb97f7ce', 'NC26.8.SGMR.4', 2, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate interior angles measure $(2x+14)^\circ$ and $(4x-26)^\circ$. What is the value of $x$?', '["10","20","32","40"]', '20', '(14+26)/2', 'Alternate interior angles are equal: $2x + 14 = 4x - 26$, so $2x = 40$ and $x = 20$. The number 32 would come from wrongly adding the angles to $180^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 14 = 4x - 26, 2x = 40, x = 20 (both 54).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87dbae6b-76ca-4779-be7a-7f3f009cee06', 'NC26.8.SGMR.4', 2, 'numeric', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate exterior angles measure $(5x-8)^\circ$ and $(3x+16)^\circ$. What is the measure of each of these angles, in degrees?', '[]', '52', '5*12-8', 'Alternate exterior angles are equal: $5x - 8 = 3x + 16$, so $2x = 24$ and $x = 12$. Each angle is $5 \times 12 - 8 = 52$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 8 = 3x + 16, 2x = 24, x = 12. Each angle 5(12) - 8 = 52.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c7326e4-4c08-47e4-85d3-32508dfd2523', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two same-side interior angles measure $(3x+10)^\circ$ and $(2x+20)^\circ$. What is the measure of the larger of the two angles, in degrees?', '["30","40","80","100"]', '100', '3*30+10', 'Same-side interior angles add to $180^\circ$: $(3x+10) + (2x+20) = 5x + 30 = 180$, so $x = 30$. The angles are $100^\circ$ and $80^\circ$, and the larger is 100. (If they were set equal, $x$ would be 10 and each angle 40: wrong.)', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+10) + (2x+20) = 5x + 30 = 180, x = 30. Angles 100 and 80. Larger 100.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bd37854-0c27-4c70-bbc9-f9a9018c16d6', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Two same-side interior angles formed by parallel lines and a transversal differ by $20^\circ$. What is the measure of the smaller angle, in degrees?', '["80","90","100","160"]', '80', '(180-20)/2', 'The two angles add to $180^\circ$ and differ by 20. Taking 20 off the total leaves $160^\circ$ shared equally, so the smaller is $160 \div 2 = 80$ degrees and the larger is 100.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + b = 180, a - b = 20: b = 80 (a = 100). Smaller 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b27ebae-5c4b-47d3-bc28-104ebd4290ae', 'NC26.8.SGMR.4', 2, 'choice', 'Choose the angle relationship from the positions', 'Parallel lines $\ell$ (the upper line) and $m$ (the lower line) are crossed by a transversal $t$. Angle $p$ is at $\ell$, below $\ell$ and to the left of $t$. Angle $q$ is at $m$, above $m$ and to the right of $t$. Angle $p$ measures $(3x-5)^\circ$ and angle $q$ measures $(x+35)^\circ$. What is the measure of angle $p$, in degrees?', '["20","55","125","160"]', '55', '3*20-5', 'Both angles are between the parallel lines and on opposite sides of the transversal, so they are alternate interior angles and are equal: $3x - 5 = x + 35$, so $x = 20$. Angle $p$ is $3 \times 20 - 5 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p is below l (interior) left of t; q is above m (interior) right of t: alternate interior angles, equal. 3x - 5 = x + 35, x = 20. p = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8750e179-07a6-4182-9e81-d0dc5b175af6', 'NC26.8.SGMR.4', 2, 'numeric', 'Choose the angle relationship from the positions', 'Parallel lines $\ell$ (the upper line) and $m$ (the lower line) are crossed by a transversal $t$. Angle $p$ is at $\ell$, below $\ell$ and to the left of $t$. Angle $q$ is at $m$, above $m$ and to the left of $t$. Angle $p$ measures $(2x+20)^\circ$ and angle $q$ measures $(x+40)^\circ$. What is the measure of the smaller of the two angles, in degrees?', '[]', '80', '40+40', 'Both angles are between the parallel lines and on the same side of the transversal, so they are same-side interior angles and add to $180^\circ$: $(2x+20) + (x+40) = 3x + 60 = 180$, so $x = 40$. The angles are $100^\circ$ and $80^\circ$, and the smaller is 80.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p below l and q above m are both between the lines, both left of t: same-side interior, supplementary. (2x+20) + (x+40) = 3x + 60 = 180, x = 40. p = 100, q = 80. Smaller 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('862bed0b-6d00-4e38-b51c-2cb7543d996d', 'NC26.8.SGMR.4', 2, 'choice', 'Tell whether lines are parallel from angle measures', 'Lines $a$ and $b$ are crossed by a transversal. Which pair of angle measures shows that $a$ and $b$ are parallel?', '["Alternate interior angles of $70^\\circ$ and $110^\\circ$","Same-side interior angles of $70^\\circ$ and $70^\\circ$","Corresponding angles of $70^\\circ$ and $110^\\circ$","Alternate interior angles of $70^\\circ$ and $70^\\circ$"]', 'Alternate interior angles of $70^\circ$ and $70^\circ$', NULL, 'Lines are parallel when alternate interior (or corresponding) angles are equal, or when same-side interior angles add to $180^\circ$. Only alternate interior angles of $70^\circ$ and $70^\circ$ meet one of these tests. Same-side angles of 70 and 70 add to 140.', 'checked', '{"lint":[],"solve":{"answer":"Alternate interior angles of $70^\\circ$ and $70^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal alternate interior angles prove the lines parallel. Same-side interior 70 + 70 = 140 is not 180; corresponding 70 and 110 are unequal; alternate interior 70 and 110 are unequal.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdb2b520-0747-4437-bd96-66612a543b3b', 'NC26.8.SGMR.4', 2, 'numeric', 'Tell whether lines are parallel from angle measures', 'Lines $\ell$ and $m$ are crossed by a transversal. A pair of alternate interior angles measure $(5x-9)^\circ$ and $(3x+17)^\circ$. For what value of $x$ are the lines $\ell$ and $m$ parallel?', '[]', '13', '(17+9)/2', 'The lines are parallel when alternate interior angles are equal: $5x - 9 = 3x + 17$, so $2x = 26$ and $x = 13$. (Each angle is $56^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel when alternate interior angles are equal: 5x - 9 = 3x + 17, 2x = 26, x = 13 (both 56).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('851a4e47-5e10-4bab-b4fb-9628f1a29d08', 'NC26.8.SGMR.4', 2, 'numeric', 'Multi-step angle problems with parallel lines', 'A transversal crosses two parallel lines. At one crossing, one angle is 3 times as large as an angle next to it, and the two angles form a linear pair. What is the measure of the smaller of the two angles, in degrees?', '[]', '45', '180/4', 'A linear pair adds to $180^\circ$. With parts 1 and 3, there are 4 equal parts: $180 \div 4 = 45$ degrees. The smaller angle is 45 degrees (and the larger is 135).', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear pair: x + 3x = 180, x = 45 (other 135).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78508744-569b-4ce1-afcd-c4432342a433', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'Parallel lines $\ell$ and $m$ are crossed by a transversal. Angle 1 is at $\ell$ and measures $52^\circ$. Angle 2 is the corresponding angle of angle 1, at $m$. Angle 3 forms a linear pair with angle 2. What is the measure of angle 3, in degrees?', '["38","52","128","142"]', '128', '180-52', 'Corresponding angles are equal, so angle 2 is $52^\circ$. Angle 3 forms a linear pair with angle 2, so it is $180 - 52 = 128$ degrees. The number 52 stops after the first step.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle 2 = 52 (corresponding). Angle 3 = 180 - 52 = 128.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ca61266-ce5a-4a14-ad33-dce76721b989', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'A line is drawn through vertex $A$ of triangle $ABC$, parallel to side $BC$. On this line, the angle between the line and side $AB$ measures $48^\circ$ on one side of $A$, and the angle between the line and side $AC$ measures $65^\circ$ on the other side of $A$. Both of these angles lie outside the triangle. What is the measure of angle $BAC$, in degrees?', '["48","65","67","113"]', '67', '180-48-65', 'The two outside angles and angle $BAC$ fit together along the straight line through $A$, so they add to $180^\circ$. Angle $BAC$ is $180 - 48 - 65 = 67$ degrees. (Check: by alternate interior angles, $B = 48^\circ$ and $C = 65^\circ$, and $48 + 65 + 67 = 180$.) The number 113 is only $48 + 65$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The line through A is parallel to BC, so the 48 angle at AB equals angle B and the 65 angle at AC equals angle C (alternate interior). The three angles at A along the line sum to 180: BAC = 180 - 48 - 65 = 67.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67cd3cd7-4df0-4391-ae0e-7e54991892fa', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'Parallel lines are crossed by a transversal. Angle $a$ is an interior angle at the upper line and measures $75^\circ$. Which angle must measure $105^\circ$?', '["The same-side interior angle of angle $a$","The angle vertical to angle $a$","The alternate interior angle of angle $a$","The corresponding angle of angle $a$"]', 'The same-side interior angle of angle $a$', NULL, 'Vertical, alternate interior and corresponding angles of angle $a$ are all equal to $75^\circ$ when the lines are parallel. The same-side interior angle is supplementary to angle $a$: $180 - 75 = 105$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"The same-side interior angle of angle $a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angle is supplementary: 180 - 75 = 105. Corresponding, vertical and alternate interior angles are all 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c81ca848-4d40-4fb4-a5d8-e64fa90c9b07', 'NC26.8.SGMR.4', 2, 'numeric', 'Multi-step angle problems with parallel lines', 'In triangle $ABC$, point $D$ is on side $AB$ and point $E$ is on side $AC$, and $DE$ is parallel to $BC$. Angle $ADE$ measures $62^\circ$ and angle $C$ measures $48^\circ$. What is the measure of angle $A$, in degrees?', '[]', '70', '180-62-48', 'Since $DE$ is parallel to $BC$, angle $ADE$ and angle $B$ are corresponding angles, so $B = 62^\circ$. Then $A = 180 - 62 - 48 = 70$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DE parallel to BC, so angle ADE = angle B = 62 (corresponding). A = 180 - 62 - 48 = 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9919ecdf-ec2f-464a-9650-588dd43aeaa2', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems in triangles and around points', 'In triangle $ABC$, the exterior angle at $A$ measures $140^\circ$ and angles $B$ and $C$ are equal. What is the measure of angle $B$, in degrees?', '["20","40","70","140"]', '70', '140/2', 'The exterior angle at $A$ equals $B + C$. Since $B = C$, each is $140 \div 2 = 70$ degrees. (Check: angle $A$ is $180 - 140 = 40^\circ$, and $40 + 70 + 70 = 180$.)', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at A = B + C = 140, B = C, so B = 70 (interior A = 40).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
