VALUES ('f4ce6fde-de6f-42fa-a068-4f957440be44', 'NC26.8.SGMR.4', 3, 'numeric', 'Linear pairs and vertical angles', 'Two lines cross. Two angles that form a linear pair measure $(4x+20)^\circ$ and $(2x+10)^\circ$. What is the measure of the smaller of the two angles, in degrees?', '[]', '60', '2*25+10', '$(4x+20) + (2x+10) = 6x + 30 = 180$, so $x = 25$. The angles are $120^\circ$ and $60^\circ$, and the smaller is 60 degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4x+20) + (2x+10) = 6x + 30 = 180, x = 25. Angles 120 and 60. Smaller 60.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47fc5457-bdbf-47dc-b0fa-7334b7bd2f8d', 'NC26.8.SGMR.4', 3, 'choice', 'Corresponding angles and parallel lines', 'Parallel lines $\ell$ and $m$ are crossed by a transversal. Two corresponding angles measure $(3x+7)^\circ$ and $(5x-33)^\circ$. What is the measure of each of these angles, in degrees?', '["133","113","67","20"]', '67', '3*20+7', 'Corresponding angles are equal: $3x + 7 = 5x - 33$, so $2x = 40$ and $x = 20$. Each angle is $3 \times 20 + 7 = 67$ degrees. The number 20 is only $x$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 7 = 5x - 33, 2x = 40, x = 20. Each angle 3(20) + 7 = 67.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
