INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddadb9ac-5ddd-4348-948a-294891780bc1', 'NC26.8.SGMR.4', 3, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate interior angles measure $(6x-14)^\circ$ and $(4x+16)^\circ$. What is the measure of an angle that forms a linear pair with either of them, in degrees?', '["15","76","104","165"]', '104', '180-(6*15-14)', 'Alternate interior angles are equal: $6x - 14 = 4x + 16$, so $x = 15$. Each of these angles is $6 \times 15 - 14 = 76$ degrees, and an angle forming a linear pair with it is $180 - 76 = 104$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 14 = 4x + 16, x = 15. Each is 76. Linear pair: 180 - 76 = 104.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
