INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bae38b0b-4134-4646-9bdf-0a453864d97e', 'NC26.8.SGMR.4', 3, 'numeric', 'Same-side interior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two same-side interior angles measure $(4x-12)^\circ$ and $(2x+6)^\circ$. What is the measure of the smaller angle, in degrees?', '[]', '68', '2*31+6', '$(4x-12) + (2x+6) = 6x - 6 = 180$, so $6x = 186$ and $x = 31$. The angles are $4 \times 31 - 12 = 112$ and $2 \times 31 + 6 = 68$ degrees. The smaller is 68.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4x-12) + (2x+6) = 6x - 6 = 180, x = 31. Angles 112 and 68. Smaller 68.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
