INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17725289-2196-437a-a097-bb5b4e0f0390', 'NC26.8.SGMR.5', 1, 'numeric', 'Verify the theorem and squares on the sides', 'Three square gardens are built along the three sides of a right-triangle-shaped lot. The gardens beside the two shorter sides cover 25 square yards and 144 square yards. How many square yards does the garden beside the longest side cover?', '[]', '169', '25+144', 'The area of the square on the hypotenuse equals the sum of the areas of the squares on the legs: $25 + 144 = 169$ square yards.', 'checked', '{"lint":[],"solve":{"answer":"169","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square on longest side (hypotenuse) = 25 + 144 = 169 sq yd.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a983c08-5291-441d-9027-a7c799c56cc6', 'NC26.8.SGMR.5', 1, 'choice', 'Verify the theorem and squares on the sides', 'Which equation shows that the side lengths 6, 8 and 10 satisfy the Pythagorean Theorem?', '["$6^2 + 10^2 = 8^2$","$6 + 8 = 10$","$8^2 + 10^2 = 6^2$","$6^2 + 8^2 = 10^2$"]', '$6^2 + 8^2 = 10^2$', NULL, 'The two shorter sides are the legs and 10 is the hypotenuse. $6^2 + 8^2 = 36 + 64 = 100 = 10^2$, so the equation $6^2 + 8^2 = 10^2$ is true. The other equations are false.', 'checked', '{"lint":[],"solve":{"answer":"$6^2 + 8^2 = 10^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 + 64 = 100, i.e. 6^2 + 8^2 = 10^2 (legs squared sum to hypotenuse squared).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95df067d-c03c-4b4b-9fea-be03c431c0c9', 'NC26.8.SGMR.5', 1, 'choice', 'Find the hypotenuse (exact number)', 'The legs of a right triangle measure 7 cm and 24 cm. How long is the hypotenuse, in centimeters?', '["17","25","31","625"]', '25', NULL, '$7^2 + 24^2 = 49 + 576 = 625$, and $\sqrt{625} = 25$. The hypotenuse is 25 cm.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 49 + 576 = 625, c = 25.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b114de07-87f6-44bd-82e2-ff04253c81a1', 'NC26.8.SGMR.5', 1, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A hiker walks 12 km due east, then turns and walks 16 km due north. How far, in a straight line, is the hiker from the start, in kilometers?', '[]', '20', NULL, 'The two walks are the legs of a right triangle and the straight line back is the hypotenuse. $12^2 + 16^2 = 144 + 256 = 400$, and $\sqrt{400} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"East and north are perpendicular: d^2 = 144 + 256 = 400, d = 20 km.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1dae8c-e3d3-48db-a85b-8311e5742b8a', 'NC26.8.SGMR.5', 1, 'choice', 'Find the hypotenuse (exact number)', 'A right triangle has legs of 5 inches and 12 inches. Which is the length of the hypotenuse, in inches?', '["169","17","13","7"]', '13', NULL, '$5^2 + 12^2 = 25 + 144 = 169$, and $\sqrt{169} = 13$. The hypotenuse is 13 inches. (17 comes from adding the legs, and 169 is the square of the hypotenuse, not its length.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 25 + 144 = 169, c = 13.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
