INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b264c495-c2d7-444b-978f-0eb0c99fea4b', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 26 cm and one leg of 10 cm. How long is the other leg, in centimeters?', '[]', '24', NULL, '$26^2 - 10^2 = 676 - 100 = 576$, and $\sqrt{576} = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 676 - 100 = 576, b = 24.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
