INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26e305c8-43e7-4d70-b93e-a1ab45887e50', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a side as a square root or a rounded decimal', 'The legs of a right triangle are 4 cm and 6 cm long. If $c$ is the length of the hypotenuse in centimeters, what is the value of $c^2$?', '[]', '52', '4^2+6^2', '$c^2 = 4^2 + 6^2 = 16 + 36 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 16 + 36 = 52.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
