INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0681c7d2-de39-4895-a838-8d302c9ec73e', 'NC26.8.SGMR.5', 1, 'choice', 'Find a side as a square root or a rounded decimal', 'The two shorter sides of a right triangle measure 2 inches and 3 inches. What is the length of the longest side?', '["$\\sqrt{13}$ inches","5 inches","13 inches","$\\sqrt{5}$ inches"]', '$\sqrt{13}$ inches', NULL, 'The longest side is the hypotenuse. $c^2 = 2^2 + 3^2 = 4 + 9 = 13$, so $c = \sqrt{13}$ inches. (5 comes from adding the sides; 13 is $c^2$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{13}$ inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 4 + 9 = 13, c = sqrt(13) inches.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
