INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d210cd4-11e8-42c2-8087-69c40a3838fe', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a side as a square root or a rounded decimal', 'The hypotenuse of a right triangle is 7 cm and one leg is 4 cm. What is the square of the length of the other leg, in square centimeters?', '[]', '33', '7^2-4^2', '$7^2 = 4^2 + b^2$, so $b^2 = 49 - 16 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 49 - 16 = 33.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
