INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35d4ad0c-80e5-4242-b793-55cb932f3130', 'NC26.8.SGMR.5', 1, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A ramp rises 5 feet while it covers a horizontal distance of 12 feet. How long is the sloping surface of the ramp, in feet?', '[]', '13', NULL, 'The rise and the horizontal distance are the legs of a right triangle, and the ramp surface is the hypotenuse. $5^2 + 12^2 = 25 + 144 = 169$, and $\sqrt{169} = 13$ feet.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise and run perpendicular: s^2 = 25 + 144 = 169, s = 13.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
