INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcba4d54-7702-453e-97f6-bde4851b69e3', 'NC26.8.SGMR.5', 2, 'numeric', 'Find the hypotenuse (exact number)', 'A rectangle is 33 cm long and 56 cm wide. How long is a diagonal of the rectangle, in centimeters?', '[]', '65', NULL, 'A diagonal cuts the rectangle into two right triangles, with the diagonal as the hypotenuse. $33^2 + 56^2 = 1089 + 3136 = 4225$, and $\sqrt{4225} = 65$ cm.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 1089 + 3136 = 4225, d = 65.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3731be46-ffae-4f8b-a977-649c4421e5fc', 'NC26.8.SGMR.5', 2, 'numeric', 'Find a leg (exact number)', 'The hypotenuse of a right triangle is 41 cm and one leg is 9 cm. How long is the other leg, in centimeters?', '[]', '40', NULL, '$41^2 - 9^2 = 1681 - 81 = 1600$, and $\sqrt{1600} = 40$ cm.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 1681 - 81 = 1600, b = 40.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
