INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c618e51-00f8-4603-83b2-d9de7f74dc89', 'NC26.8.SGMR.5', 2, 'choice', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 2.5 m and one leg of 2 m. Which is the length of the other leg, in meters?', '["4.5","2.25","1.5","0.5"]', '1.5', NULL, '$2.5^2 - 2^2 = 6.25 - 4 = 2.25$, and $\sqrt{2.25} = 1.5$ meters. (0.5 is the difference of the sides; 2.25 is the square of the leg.)', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 6.25 - 4 = 2.25, b = 1.5.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
