INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5266f1c0-8a68-4d43-8ab9-8b25b26d5629', 'NC26.8.SGMR.5', 3, 'numeric', 'Find a side as a square root or a rounded decimal', 'A right triangle has a hypotenuse of 15 inches and one leg of 11 inches. To the nearest tenth of an inch, how long is the other leg?', '[]', '10.2', NULL, '$15^2 - 11^2 = 225 - 121 = 104$, and $\sqrt{104} \approx 10.20$, which is 10.2 inches to the nearest tenth.', 'checked', '{"lint":[],"solve":{"answer":"10.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 225 - 121 = 104, sqrt(104) = 10.198..., 10.2.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbbd2238-c48f-4b5c-be90-86fc7bd2ca06', 'NC26.8.SGMR.5', 3, 'choice', 'Find a side as a square root or a rounded decimal', 'The legs of a right triangle are 10 cm and 11 cm. Which is the best estimate of the hypotenuse, to the nearest tenth of a centimeter?', '["221","21","14.9","14.1"]', '14.9', NULL, '$10^2 + 11^2 = 100 + 121 = 221$. Since $14.9^2 \approx 222$ and $14.8^2 \approx 219$, $\sqrt{221} \approx 14.87$, which is 14.9 to the nearest tenth. (21 is the sum of the legs; 221 is $c^2$; 14.1 is $\sqrt{200}$.)', 'checked', '{"lint":[],"solve":{"answer":"14.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 100 + 121 = 221, sqrt(221) = 14.866..., 14.9.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d72b2aa-3422-44fb-9511-66597e1a02a2', 'NC26.8.SGMR.5', 3, 'choice', 'Converse: is the triangle a right triangle?', 'Only one of these lists could be the side lengths, in meters, of a right triangle. Which one?', '["0.9, 1.2, 1.5","0.8, 1.1, 1.4","0.6, 0.7, 1.0","1.2, 1.5, 2.1"]', '0.9, 1.2, 1.5', NULL, 'Test the largest number as the hypotenuse. $0.9^2 + 1.2^2 = 0.81 + 1.44 = 2.25 = 1.5^2$, so 0.9, 1.2, 1.5 works. The others fail: $0.8^2 + 1.1^2 = 1.85$ (not 1.96); $0.6^2 + 0.7^2 = 0.85$ (not 1); $1.2^2 + 1.5^2 = 3.69$ (not 4.41).', 'checked', '{"lint":[],"solve":{"answer":"0.9, 1.2, 1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.9,1.2,1.5: 0.81+1.44=2.25=1.5^2 yes. 1.2,1.5,2.1: 3.69 vs 4.41. 0.8,1.1,1.4: 1.85 vs 1.96. 0.6,0.7,1.0: 0.85 vs 1.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cc80c50-4201-4bc7-ad81-e6650b360972', 'NC26.8.SGMR.5', 3, 'numeric', 'Converse: is the triangle a right triangle?', 'A triangle has sides of 9 cm, 12 cm and $x$ cm, where $x$ is a whole number. Only one value of $x$ makes it a right triangle. What is $x$?', '[]', '15', NULL, 'If $x$ is the hypotenuse, $x^2 = 81 + 144 = 225$ and $x = 15$. If 12 were the hypotenuse, $x^2 = 144 - 81 = 63$, which is not a perfect square, and 9 cannot be the hypotenuse because it is shorter than 12. So $x = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x hypotenuse: sqrt(81+144) = 15 (whole). x a leg: sqrt(144-81) = sqrt63, not whole. So x = 15.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8dd2835-4654-4dab-908a-424052b2c524', 'NC26.8.SGMR.5', 3, 'choice', 'Converse: is the triangle a right triangle?', 'Zoe measured four triangles, and only one of them has a right angle. Their side lengths, in centimeters, are listed. Which triangle has a right angle?', '["14, 48, 51","9, 40, 42","20, 48, 51","13, 84, 85"]', '13, 84, 85', NULL, '$13^2 + 84^2 = 169 + 7056 = 7225 = 85^2$, so 13, 84, 85 is a right triangle. For the others: $14^2 + 48^2 = 2500$, not $51^2 = 2601$; $9^2 + 40^2 = 1681$, not $42^2 = 1764$; $20^2 + 48^2 = 2704$, not $51^2 = 2601$.', 'checked', '{"lint":[],"solve":{"answer":"13, 84, 85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13,84,85: 169+7056=7225=85^2 yes. 14,48,51: 2500 vs 2601. 9,40,42: 1681 vs 1764. 20,48,51: 2704 vs 2601.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fbb6439-5a30-4f7b-bc9c-1a4c569ac396', 'NC26.8.SGMR.5', 3, 'choice', 'Converse: is the triangle a right triangle?', 'A carpenter checks a corner by marking points 45 cm and 60 cm from the corner along the two edges. The distance between the two marks is 77 cm. Is the corner square (a right angle)?', '["No; a square corner needs a distance of 75 cm","Yes; the distance should be 77 cm for a square corner","No; a square corner needs a distance of 105 cm","Yes; any distance between 75 cm and 105 cm means a square corner"]', 'No; a square corner needs a distance of 75 cm', NULL, 'For a square corner the marks must be $\sqrt{45^2 + 60^2} = \sqrt{2025 + 3600} = \sqrt{5625} = 75$ cm apart. The measured 77 cm is not 75 cm, so the corner is not square.', 'checked', '{"lint":[],"solve":{"answer":"No; a square corner needs a distance of 75 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45^2 + 60^2 = 2025 + 3600 = 5625 = 75^2. A square corner needs 75 cm; 77 cm means not square.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1f37d1f-4d32-45d0-b860-e36103ac3aa0', 'NC26.8.SGMR.5', 3, 'numeric', 'Distance on the coordinate plane', 'On a coordinate plane, point $P$ is at $(-4, -7)$ and point $Q$ is at $(4, 8)$. What is the distance from $P$ to $Q$, in units?', '[]', '17', NULL, 'The horizontal change is $4 - (-4) = 8$ and the vertical change is $8 - (-7) = 15$. The distance is $\sqrt{8^2 + 15^2} = \sqrt{289} = 17$ units.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 8, dy = 15: d = sqrt(64 + 225) = 17.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37318fc7-0a23-4123-8b73-a0e6e8f6d161', 'NC26.8.SGMR.5', 3, 'numeric', 'Distance on the coordinate plane', 'Point $A$ is at $(1, 2)$ and point $B$ is at $(4, y)$, where $y$ is greater than 2. The distance from $A$ to $B$ is 5 units. What is $y$?', '[]', '6', '2+4', 'The horizontal change is $4 - 1 = 3$. If the distance is 5, the vertical change $v$ satisfies $3^2 + v^2 = 5^2$, so $v^2 = 16$ and $v = 4$. Since $y$ is greater than 2, $y = 2 + 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 3, d = 5, so dy = 4; y = 2 + 4 = 6.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5299756-eeee-49f7-b1d4-504de7c1a9e3', 'NC26.8.SGMR.5', 3, 'choice', 'Distance on the coordinate plane', 'Which of these points is farthest from the origin $(0, 0)$?', '["$(5, 5)$","$(-6, 4)$","$(7, 0)$","$(-3, -6)$"]', '$(-6, 4)$', NULL, 'Compare $x^2 + y^2$ (the square of the distance). $(-6, 4)$: $36 + 16 = 52$. $(5, 5)$: $50$. $(7, 0)$: $49$. $(-3, -6)$: $9 + 36 = 45$. The largest is 52, so $(-6, 4)$ is farthest.', 'checked', '{"lint":[],"solve":{"answer":"$(-6, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squared distances: (5,5) 50, (-6,4) 52, (-3,-6) 45, (7,0) 49. Largest 52.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('797411d6-79db-4c36-a3f3-6c73a8fed0a2', 'NC26.8.SGMR.5', 3, 'choice', 'Distance on the coordinate plane', 'A triangle has corners at $(0, 0)$, $(4, 3)$ and $(-3, 4)$. Which statement is true?', '["It is a right triangle, with the right angle at $(4, 3)$","It is a right triangle, with the right angle at $(-3, 4)$","It is a right triangle, with the right angle at $(0, 0)$","It is not a right triangle"]', 'It is a right triangle, with the right angle at $(0, 0)$', NULL, 'The side from $(0, 0)$ to $(4, 3)$ has length $\sqrt{16 + 9} = 5$. The side from $(0, 0)$ to $(-3, 4)$ has length $\sqrt{9 + 16} = 5$. The third side, from $(4, 3)$ to $(-3, 4)$, has length $\sqrt{7^2 + 1^2} = \sqrt{50}$. Since $5^2 + 5^2 = 50$, the triangle is right, and the right angle is between the two sides of length 5, at $(0, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"It is a right triangle, with the right angle at $(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"OA = 5, OB = 5, AB^2 = 49 + 1 = 50 = 25 + 25. Right angle opposite AB, at (0,0) (slopes 3/4 and -4/3).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d160b78-d2e5-480f-8915-cb6fdacfbbeb', 'NC26.8.SGMR.5', 3, 'numeric', 'Distance on the coordinate plane', 'A triangle on a coordinate plane has corners at $(0, 0)$, $(8, 0)$ and $(8, 15)$. What is its perimeter, in units?', '[]', '40', '8+15+17', 'The sides along the axes have lengths 8 and 15. The third side is the hypotenuse: $\sqrt{8^2 + 15^2} = \sqrt{289} = 17$. The perimeter is $8 + 15 + 17 = 40$ units.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 8 and 15, hypotenuse sqrt(64+225) = 17. Perimeter 8 + 15 + 17 = 40.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7978a906-b591-455f-9165-e4a51ca83d4d', 'NC26.8.SGMR.5', 3, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A baseball diamond is a square with sides of 90 feet. To the nearest tenth of a foot, how far is it in a straight line from home plate to second base, the opposite corner?', '[]', '127.3', NULL, 'The diagonal of a square is the hypotenuse of a right triangle with both legs 90 ft. $90^2 + 90^2 = 16200$, so the distance is $\sqrt{16200} \approx 127.28$, which is 127.3 feet to the nearest tenth.', 'checked', '{"lint":[],"solve":{"answer":"127.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 8100 + 8100 = 16200, d = 90 sqrt2 = 127.279..., 127.3.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a21f62e-286e-4828-aa9b-05ca4be68df0', 'NC26.8.SGMR.5', 3, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A 25-foot ladder leans against a vertical wall with its base 7 feet from the wall. Then the base is pulled 8 feet farther from the wall, and the ladder still touches the wall. How many feet does the top of the ladder slide down?', '[]', '4', '24-20', 'At first the top is $\sqrt{25^2 - 7^2} = \sqrt{576} = 24$ feet up. After the move the base is $7 + 8 = 15$ feet away, so the top is $\sqrt{25^2 - 15^2} = \sqrt{400} = 20$ feet up. It slides $24 - 20 = 4$ feet.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start: top at sqrt(625 - 49) = 24. Base moves to 15: top at sqrt(625 - 225) = 20. Slides 24 - 20 = 4 ft.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('236592a1-beb9-43f3-8be4-0262141ff509', 'NC26.8.SGMR.5', 3, 'choice', 'Pythagorean Theorem in a real-world problem', 'Two cyclists leave the same spot at the same time. One rides north at 12 kilometers per hour and the other rides east at 16 kilometers per hour. How far apart, in a straight line, are they after 2 hours, in kilometers?', '["20","40","56","1600"]', '40', NULL, 'After 2 hours one has gone $2 \times 12 = 24$ km north and the other $2 \times 16 = 32$ km east. The distance between them is the hypotenuse: $24^2 + 32^2 = 576 + 1024 = 1600$, and $\sqrt{1600} = 40$ km. (20 km is the distance after only 1 hour.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After 2 h: 24 km and 32 km at right angles. d = sqrt(576 + 1024) = 40.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23d973ab-aee4-4573-b22c-e8027d04698e', 'NC26.8.SGMR.5', 3, 'numeric', 'Pythagorean Theorem in a real-world problem', 'The diagonal of a square is 14 cm long. What is the area of the square, in square centimeters?', '[]', '98', '14^2/2', 'Let each side be $s$. The diagonal is the hypotenuse of a right triangle with legs $s$ and $s$, so $s^2 + s^2 = 14^2 = 196$. Then $s^2 = 98$, and the area of the square is $s^2 = 98$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"98","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s^2 + s^2 = 196, so s^2 = 98 = area.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f44cda0-7d64-48c3-974b-9a5209c4f266', 'NC26.8.SGMR.5', 3, 'choice', 'Multi-step problems with right triangles', 'An isosceles triangle has two sides of 13 cm and a base of 10 cm. What is the area of the triangle, in square centimeters?', '["130","120","65","60"]', '60', '10*12/2', 'The height to the base splits the base into two parts of 5 cm. The height is $\sqrt{13^2 - 5^2} = \sqrt{144} = 12$ cm. The area is $\frac{1}{2} \times 10 \times 12 = 60$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Altitude to base bisects it: h = sqrt(169 - 25) = 12. Area = 10 x 12 / 2 = 60.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fae0925-41af-45f5-92da-979aaa4a37b8', 'NC26.8.SGMR.5', 3, 'choice', 'Multi-step problems with right triangles', 'The shorter leg of a right triangle is 15 cm and the hypotenuse is 39 cm. What is the perimeter of the triangle, in centimeters?', '["36","54","75","90"]', '90', '15+36+39', 'The other leg is $\sqrt{39^2 - 15^2} = \sqrt{1521 - 225} = \sqrt{1296} = 36$ cm. The perimeter is $15 + 36 + 39 = 90$ cm. (54 leaves out the missing leg, 75 leaves out the given leg, and 36 is only the missing leg.)', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other leg sqrt(1521 - 225) = 36. Perimeter 15 + 36 + 39 = 90.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('676a2874-4dcc-4554-bb1d-4ca83f95cb2b', 'NC26.8.SGMR.5', 3, 'choice', 'Multi-step problems with right triangles', 'An isosceles trapezoid has parallel sides of 9 cm and 25 cm. Its two equal slanted sides are each 17 cm long. What is the area of the trapezoid, in square centimeters?', '["510","289","255","136"]', '255', '(9+25)/2*15', 'The bases differ by $25 - 9 = 16$, so each end sticks out 8 cm. The height is $\sqrt{17^2 - 8^2} = \sqrt{225} = 15$ cm. The area is $\frac{1}{2}(9 + 25) \times 15 = 17 \times 15 = 255$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"255","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each overhang (25 - 9)/2 = 8; height sqrt(289 - 64) = 15. Area (9 + 25)/2 x 15 = 255.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('234b6d85-8ab2-4c68-86b5-ed2ed2efec58', 'NC26.8.SGMR.5', 3, 'choice', 'Multi-step problems with right triangles', 'A rectangle has a diagonal of 25 cm and a perimeter of 62 cm. Which pair could be its length and width?', '["24 cm and 7 cm","20 cm and 11 cm","15 cm and 16 cm","25 cm and 6 cm"]', '24 cm and 7 cm', NULL, 'All four pairs have a perimeter of 62 cm, so test the diagonal: $\sqrt{l^2 + w^2}$ must be 25. $24^2 + 7^2 = 576 + 49 = 625 = 25^2$, so 24 and 7 works. The others give $20^2 + 11^2 = 521$, $15^2 + 16^2 = 481$ and $25^2 + 6^2 = 661$, none of which is 625.', 'checked', '{"lint":[],"solve":{"answer":"24 cm and 7 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L + W = 31 and L^2 + W^2 = 625. 24 + 7 = 31, 576 + 49 = 625. Others: 15,16 gives 481; 25,6 gives 661; 20,11 gives 521.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1116e3f-ed6a-48d9-b8fb-562531207815', 'NC26.8.SGMR.5', 3, 'numeric', 'Multi-step problems with right triangles', 'The legs of a right triangle differ in length by 1 cm, and the hypotenuse is 29 cm. How long is the shorter leg, in centimeters?', '[]', '20', NULL, 'Try pairs of legs that differ by 1: the legs $x$ and $x + 1$ must satisfy $x^2 + (x + 1)^2 = 841$. With $x = 20$: $400 + 441 = 841$. So the shorter leg is 20 cm.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Solving needs a quadratic (Math 1) or guess-and-check near 29/sqrt2 = 20.5; workable in Grade 8 by trial, but at the top of the grade.","work":"x^2 + (x+1)^2 = 841 -> x^2 + x - 420 = 0 -> x = 20 (20, 21, 29: 400 + 441 = 841).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53d6aac8-d156-4b91-900f-e91c84f6daf6', 'NC26.8.SGMR.6', 1, 'numeric', 'Pyramid volume compared with a prism', 'A prism and a pyramid have the same base and the same height. The volume of the prism is 90 cubic centimeters. What is the volume of the pyramid, in cubic centimeters?', '[]', '30', '90/3', 'A pyramid holds one third of the volume of a prism with the same base and height. $90 \div 3 = 30$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pyramid volume = 1/3 of prism with same base and height: 90 / 3 = 30.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31ed1ad2-41d9-45d8-935e-ff7ce21ff7b5', 'NC26.8.SGMR.6', 1, 'choice', 'Cone volume compared with a cylinder', 'A cone and a cylinder have the same radius and the same height. The volume of the cylinder is $60\pi$ cubic centimeters. What is the volume of the cone?', '["$30\\pi$ cubic centimeters","$60\\pi$ cubic centimeters","$20\\pi$ cubic centimeters","$180\\pi$ cubic centimeters"]', '$20\pi$ cubic centimeters', NULL, 'A cone holds one third of the volume of a cylinder with the same radius and height. $\frac{1}{3} \times 60\pi = 20\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$20\\pi$ cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone volume = 1/3 of cylinder with same radius and height: 60pi / 3 = 20pi.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('973dc9be-e8da-442a-b2e5-6443770c4824', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a square pyramid', 'A square pyramid has a base edge of 6 cm and a height of 10 cm. What is its volume, in cubic centimeters?', '[]', '120', '1/3*6^2*10', 'The base area is $6 \times 6 = 36$ square centimeters. Volume $= \frac{1}{3} \times 36 \times 10 = 120$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(6^2)(10) = (1/3)(36)(10) = 120.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
