INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5b86ae7-176e-456b-ba5f-275093c098d5', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a pyramid', 'A pyramid has a base with an area of 30 square centimeters and a height of 9 centimeters. What is its volume, in cubic centimeters?', '[]', '90', '30*9/3', 'The volume of a pyramid is $\frac{1}{3} \times (\text{base area}) \times (\text{height}) = \frac{1}{3} \times 30 \times 9 = 90$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)Bh = (1/3)(30)(9) = 90.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
