INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('791f8e16-35a3-4b27-902a-410c5f10a029', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a cone', 'A cone has a radius of 6 cm and a height of 5 cm. Its volume is $k\pi$ cubic centimeters. What is the value of $k$?', '[]', '60', '6^2*5/3', 'The volume of a cone is $\frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (6^2)(5) = \frac{1}{3} \times 36 \times 5 \times \pi = 60\pi$. So $k = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi(36)(5) = 60pi, k = 60.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
