INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44409f87-32d3-49c5-a20a-d480365048d6', 'NC26.8.SGMR.6', 1, 'choice', 'Volume of a cone', 'Which formula gives the volume of a cone with radius $r$ and height $h$?', '["$V = \\pi r^2 h$","$V = \\frac{1}{3}\\pi r^2 h$","$V = \\frac{1}{3}\\pi r h$","$V = \\frac{1}{3}\\pi r^2$"]', '$V = \frac{1}{3}\pi r^2 h$', NULL, 'A cone holds one third as much as a cylinder with the same radius and height. A cylinder has volume $\pi r^2 h$, so the cone has $V = \frac{1}{3}\pi r^2 h$.', 'checked', '{"lint":[],"solve":{"answer":"$V = \\frac{1}{3}\\pi r^2 h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi r^2 h.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
