INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a8cee5d-bbeb-42ef-9c3e-d5c5bd58a642', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a sphere', 'A sphere has a radius of 1 inch. Its volume is $k\pi$ cubic inches. What is $k$? Write it as a fraction.', '[]', '4/3', '4/3*1^3', '$V = \frac{4}{3}\pi r^3 = \frac{4}{3}\pi (1^3) = \frac{4}{3}\pi$. So $k = \frac{4}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)pi(1)^3 = (4/3)pi, k = 4/3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
