INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('454bf7a4-8ae8-41c7-b0db-b642015ddf93', 'NC26.8.SGMR.6', 1, 'numeric', 'Surface area of a pyramid', 'The four triangular faces of a square pyramid each have an area of 15 square centimeters. Its square base has an area of 25 square centimeters. What is the total surface area of the pyramid, in square centimeters?', '[]', '85', '4*15+25', 'The surface area is the base plus the four triangular faces: $25 + 4 \times 15 = 25 + 60 = 85$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SA = 4(15) + 25 = 85.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
