INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d00b4ab6-c28c-4d59-9d92-851199a0fa6b', 'NC26.8.SGMR.6', 1, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A cone-shaped paper cup is filled with sand. The sand is poured into a cylinder with the same radius and the same height as the cup. The cup is filled again and poured in again, and so on. How many full cups of sand are needed to fill the cylinder?', '[]', '3', NULL, 'The cone has one third of the cylinder''s volume, so it takes 3 full cones to fill the cylinder.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone is 1/3 of the cylinder with same base and height, so 3 cups.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('299eabe7-98bf-4554-b590-9c10d60f572f', 'NC26.8.SGMR.6', 1, 'numeric', 'Find a missing dimension from a volume', 'A pyramid has a volume of 60 cubic centimeters and a base area of 20 square centimeters. What is its height, in centimeters?', '[]', '9', '60*3/20', 'Use $V = \frac{1}{3}Bh$: $60 = \frac{1}{3} \times 20 \times h$. Multiply both sides by 3: $180 = 20h$, so $h = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = (1/3)(20)h -> h = 9.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c03721f-e26b-43b0-a234-67534c425b75', 'NC26.8.SGMR.6', 1, 'numeric', 'Find a missing dimension from a volume', 'A cone has a volume of $27\pi$ cubic centimeters and a base area of $9\pi$ square centimeters. What is its height, in centimeters?', '[]', '9', '27*3/9', 'Use $V = \frac{1}{3}Bh$: $27\pi = \frac{1}{3} \times 9\pi \times h$. Multiply both sides by 3: $81\pi = 9\pi h$, so $h = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27pi = (1/3)(9pi)h = 3pi h -> h = 9.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aafb343a-51bc-4f08-bfa1-029ff0c095ec', 'NC26.8.SGMR.6', 1, 'choice', 'Find a missing dimension from a volume', 'A pyramid has a volume of 48 cubic centimeters and a height of 6 centimeters. What is the area of its base, in square centimeters?', '["8","12","24","144"]', '24', '48*3/6', 'Use $V = \frac{1}{3}Bh$: $48 = \frac{1}{3} \times B \times 6 = 2B$, so $B = 24$ square centimeters. (8 forgets the one third.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 = (1/3)B(6) = 2B -> B = 24.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
