INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3168ef24-4a23-4b26-a26c-05029504497b', 'NC26.8.SGMR.6', 1, 'numeric', 'How changing dimensions changes volume', 'A cone has a volume of 20 cubic centimeters. A taller cone has the same radius but twice the height. What is the volume of the taller cone, in cubic centimeters?', '[]', '40', '20*2', 'The volume of a cone is proportional to its height when the radius stays the same. Twice the height gives twice the volume: $20 \times 2 = 40$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume is proportional to height with r fixed: 2 x 20 = 40.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c36af2b7-3f2c-4ffa-a70a-7d8d32640ff1', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a pyramid', 'A square pyramid has a base edge of 3 meters and a height of 7 meters. What is its volume, in cubic meters?', '[]', '21', '3*3*7/3', 'The base area is $3 \times 3 = 9$ square meters. The volume is $\frac{1}{3} \times 9 \times 7 = 21$ cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B = 9; V = (1/3)(9)(7) = 21.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31b271cf-a623-45f8-b640-07a9375ed228', 'NC26.8.SGMR.6', 1, 'choice', 'Volume of a cone', 'A cone has a radius of 4 cm and a height of 3 cm. What is its volume, in cubic centimeters?', '["$16\\pi$","$48\\pi$","$4\\pi$","$24\\pi$"]', '$16\pi$', NULL, '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (4^2)(3) = \frac{1}{3} \times 16 \times 3 \times \pi = 16\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$16\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi(16)(3) = 16pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3024b948-8e6f-445d-8a22-cc0fc76ed7b8', 'NC26.8.SGMR.6', 1, 'numeric', 'Surface area of a pyramid', 'A pyramid has a base that is a regular hexagon. How many triangular faces does the pyramid have?', '[]', '6', NULL, 'A hexagon has 6 sides, and each side of the base meets one triangular face. So the pyramid has 6 triangular faces (and 7 faces in all, counting the base).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hexagon has 6 edges, so 6 triangular faces meet at the apex.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66f30c68-469f-4106-8045-6fd7f90a65bb', 'NC26.8.SGMR.6', 1, 'choice', 'Volume problems in context', 'A cone-shaped cup and a cylinder-shaped cup have the same radius and the same height. Both are filled to the top with juice. Which statement is true?', '["The cone holds 3 times as much juice as the cylinder","The cone and the cylinder hold the same amount of juice","The cylinder holds 3 times as much juice as the cone","The cylinder holds 2 times as much juice as the cone"]', 'The cylinder holds 3 times as much juice as the cone', NULL, 'A cone has one third of the volume of a cylinder with the same radius and height, so the cylinder holds 3 times as much.', 'checked', '{"lint":[],"solve":{"answer":"The cylinder holds 3 times as much juice as the cone","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder = pi r^2 h = 3 x (1/3)pi r^2 h.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17456b82-c872-4ec1-b74c-fa8792a4388e', 'NC26.8.SGMR.6', 1, 'numeric', 'Find a missing dimension from a volume', 'A cone has a volume of $12\pi$ cubic centimeters and a radius of 3 centimeters. What is its height, in centimeters?', '[]', '4', '12*3/9', 'Use $V = \frac{1}{3}\pi r^2 h$: $12\pi = \frac{1}{3}\pi (3^2) h = 3\pi h$. So $h = 12 \div 3 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12pi = (1/3)pi(9)h = 3pi h -> h = 4.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0ff6c1f-16bb-49f8-953b-24694fbc327c', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a sphere', 'Use 3 as an estimate for $\pi$. About how many cubic centimeters is the volume of a sphere with a radius of 2 cm?', '[]', '32', '4/3*3*2^3', 'Use $V = \frac{4}{3}\pi r^3$ with $\pi \approx 3$: $\frac{4}{3} \times 3 \times 2^3 = 4 \times 8 = 32$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)(3)(8) = 32.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d995d1b1-37a0-4c76-afc4-c1beae593e44', 'NC26.8.SGMR.6', 2, 'numeric', 'Surface area of a square pyramid', 'A square pyramid has a base edge of 10 cm. The height of each triangular face (the slant height) is 13 cm. What is the total surface area of the pyramid, in square centimeters?', '[]', '360', '10^2+4*(1/2*10*13)', 'The square base has area $10 \times 10 = 100$. Each triangular face has area $\frac{1}{2} \times 10 \times 13 = 65$, and there are 4 of them, so $4 \times 65 = 260$. The total is $100 + 260 = 360$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base = 10^2 = 100. Each triangular face = (1/2)(10)(13) = 65; four faces = 260. Total = 100 + 260 = 360.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc496dbe-4174-4cf7-b81c-db5591659c7a', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'A cone has a radius of 3 cm and a height of 8 cm. What is its volume, in cubic centimeters?', '["$24\\pi$","$72\\pi$","$8\\pi$","$36\\pi$"]', '$24\pi$', NULL, 'Volume $= \frac{1}{3}\pi r^2 h = \frac{1}{3} \times \pi \times 3^2 \times 8 = \frac{1}{3} \times 72\pi = 24\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$24\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi r^2 h = (1/3)pi(9)(8) = 24pi.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
