INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6789a578-40ec-4273-afff-bc1b603596c3', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a pyramid', 'The base of a pyramid is a square with a perimeter of 24 inches. The pyramid is 10 inches tall. What is its volume, in cubic inches?', '[]', '120', '(24/4)^2*10/3', 'Each side of the square base is $24 \div 4 = 6$ inches, so the base area is $6^2 = 36$ square inches. The volume is $\frac{1}{3} \times 36 \times 10 = 120$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 24/4 = 6, B = 36; V = (1/3)(36)(10) = 120.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
