INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4339507-c550-480a-bbad-8e1dcf39c59f', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'A cone has a base with a diameter of 10 cm and a height of 6 cm. What is its volume, in cubic centimeters?', '["$200\\pi$","$150\\pi$","$10\\pi$","$50\\pi$"]', '$50\pi$', NULL, 'The radius is half the diameter: $10 \div 2 = 5$ cm. $V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (5^2)(6) = 50\pi$ cubic centimeters. (200 uses the diameter as the radius.)', 'checked', '{"lint":[],"solve":{"answer":"$50\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 5; V = (1/3)pi(25)(6) = 50pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
