INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('314dc427-148a-4232-9824-97bd246e73e8', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a cone', 'A cone has a radius of 4 cm and a height of 9 cm. Use 3.14 for $\pi$. What is the volume of the cone, in cubic centimeters?', '[]', '150.72', '3.14*16*9/3', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times 3.14 \times 16 \times 9 = 3.14 \times 48 = 150.72$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"150.72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(16)(9) = 3.14 x 48 = 150.72.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
