INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1bc6453-b9a9-4f53-ac9c-694866984a51', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'The circular base of a cone has a circumference of $12\pi$ cm, and the cone is 5 cm tall. What is its volume, in cubic centimeters?', '["$60\\pi$","$240\\pi$","$180\\pi$","$30\\pi$"]', '$60\pi$', NULL, 'The circumference is $2\pi r = 12\pi$, so the radius is 6 cm. $V = \frac{1}{3}\pi (6^2)(5) = \frac{1}{3} \times 36 \times 5 \times \pi = 60\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$60\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2pi r = 12pi -> r = 6; V = (1/3)pi(36)(5) = 60pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
