INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5af7b86-c1ea-4310-b4fb-5e95b3376d26', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a sphere', 'A marble is a sphere with a radius of 1.5 cm. Use 3.14 for $\pi$. What is the volume of the marble, in cubic centimeters?', '[]', '14.13', '4/3*3.14*1.5^3', '$V = \frac{4}{3}\pi r^3 = \frac{4}{3} \times 3.14 \times 1.5^3 = \frac{4}{3} \times 3.14 \times 3.375 = 3.14 \times 4.5 = 14.13$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14.13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)(3.14)(1.5^3) = (4/3)(3.14)(3.375) = 3.14 x 4.5 = 14.13.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
