INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c52d071-e481-446a-9c9a-a1a484501ecd', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a sphere', 'Which expression gives the volume of a sphere with a diameter of 8 cm?', '["$\\frac{4}{3}\\pi(4)^3$","$\\frac{4}{3}\\pi(8)^3$","$\\frac{4}{3}\\pi(4)^2$","$\\frac{1}{3}\\pi(4)^3$"]', '$\frac{4}{3}\pi(4)^3$', NULL, 'The radius is half of the diameter, so $r = 4$ cm. The volume is $\frac{4}{3}\pi r^3 = \frac{4}{3}\pi(4)^3$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{3}\\pi(4)^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4; V = (4/3)pi(4)^3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
