INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ae03fed-0f56-4752-83e4-4086bb17944b', 'NC26.8.SGMR.6', 2, 'choice', 'Surface area of a pyramid', 'A square pyramid has a base edge of 14 m and a slant height of 9 m. What is the combined area of its four triangular faces (not counting the base), in square meters?', '["63","252","448","504"]', '252', '4*14*9/2', 'Each triangular face is $\frac{1}{2} \times 14 \times 9 = 63$ square meters, so four faces are $4 \times 63 = 252$ square meters. (63 is one face; 504 forgets the one half; 448 adds the base.)', 'checked', '{"lint":[],"solve":{"answer":"252","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2)(14)(9) = 252.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
