INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ff1757f-e37f-4f85-8637-5a22945b5cbf', 'NC26.8.SGMR.6', 2, 'choice', 'Surface area of a pyramid', 'Which expression gives the total surface area of a square pyramid with a base edge of 8 m and a slant height of 6 m?', '["$8^2 + \\frac{1}{2}(8)(6)$","$4 \\cdot \\frac{1}{2}(8)(6)$","$8^2 + 4 \\cdot \\frac{1}{2}(8)(6)$","$8^2 + 4(8)(6)$"]', '$8^2 + 4 \cdot \frac{1}{2}(8)(6)$', NULL, 'The base is a square with area $8^2$. Each of the 4 triangular faces has area $\frac{1}{2}(8)(6)$. The total is $8^2 + 4 \cdot \frac{1}{2}(8)(6)$.', 'checked', '{"lint":[],"solve":{"answer":"$8^2 + 4 \\cdot \\frac{1}{2}(8)(6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 8^2 plus four triangles 4 x (1/2)(8)(6).","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
