INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21adabd0-4742-4d3f-a425-0a2b6acbc1f2', 'NC26.8.SGMR.6', 2, 'numeric', 'Surface area of a pyramid', 'A pyramid with a triangular base has four faces (including the base) that are all identical triangles. Each triangle has a base of 6 cm and a height of 5 cm. What is the total surface area of the pyramid, in square centimeters?', '[]', '60', '4*6*5/2', 'Each face has area $\frac{1}{2} \times 6 \times 5 = 15$ square centimeters. There are 4 identical faces, so the total is $4 \times 15 = 60$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2)(6)(5) = 60. (Consistent: isosceles 6, sqrt34, sqrt34 is acute, so a tetrahedron with four such faces exists.)","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
