INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0605c9bd-bb48-4d38-9210-1c76ce5c0164', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A cylinder with a radius of 5 cm and a height of 12 cm has a volume of $300\pi$ cubic centimeters. A cone has the same radius and the same height. What is the volume of the cone, in cubic centimeters?', '["$900\\pi$","$150\\pi$","$300\\pi$","$100\\pi$"]', '$100\pi$', NULL, 'A cone has one third of the volume of a cylinder with the same radius and height: $300\pi \div 3 = 100\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$100\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone = 300pi / 3 = 100pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d5679fd-1826-4f10-ae83-db8e4ac84ed1', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A prism and a pyramid both have a base area of 36 square centimeters and a height of 10 centimeters. How many cubic centimeters more volume does the prism have than the pyramid?', '["120","180","240","360"]', '240', '36*10-36*10/3', 'The prism has volume $36 \times 10 = 360$ and the pyramid has $\frac{1}{3} \times 360 = 120$. The difference is $360 - 120 = 240$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prism 360, pyramid 120; difference 240.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58f3cda7-7c98-4374-9c5e-a31e2e46ad28', 'NC26.8.SGMR.6', 2, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A pyramid is 15 cm tall and has a volume of 100 cubic centimeters. A prism has the same base as the pyramid and is 6 cm tall. What is the volume of the prism, in cubic centimeters?', '[]', '120', '100*3/15*6', 'From $100 = \frac{1}{3} \times B \times 15 = 5B$, the base area is $B = 20$ square centimeters. The prism has volume $B \times 6 = 20 \times 6 = 120$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = (1/3)B(15) = 5B -> B = 20. Prism 20 x 6 = 120.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53ceabe1-bab9-48be-8bf0-19833d981943', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a sphere, a cone and a cylinder', 'A cylinder has radius $r$ and height $2r$. A sphere has radius $r$. What fraction of the cylinder''s volume is the sphere''s volume?', '["$\\frac{2}{3}$","$\\frac{1}{3}$","$\\frac{1}{2}$","$\\frac{3}{4}$"]', '$\frac{2}{3}$', NULL, 'The cylinder''s volume is $\pi r^2 (2r) = 2\pi r^3$. The sphere''s volume is $\frac{4}{3}\pi r^3$. The ratio is $\frac{4/3}{2} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sphere (4/3)pi r^3, cylinder pi r^2(2r) = 2pi r^3. Ratio (4/3)/2 = 2/3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a31f227-02e3-4ebf-be13-248d83415d45', 'NC26.8.SGMR.6', 2, 'choice', 'Find a missing dimension from a volume', 'A cone has a radius of 5 cm and a volume of $100\pi$ cubic centimeters. What is its height, in centimeters?', '["4","12","20","60"]', '12', '100*3/25', 'Use $V = \frac{1}{3}\pi r^2 h$: $100\pi = \frac{1}{3}\pi (25) h$. So $300 = 25h$ and $h = 12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100pi = (1/3)pi(25)h -> h = 12.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f14e8adf-674c-485b-9858-188a2e64606e', 'NC26.8.SGMR.6', 2, 'numeric', 'Find a missing dimension from a volume', 'A square pyramid has a volume of 96 cubic centimeters and a height of 8 centimeters. What is the length of one edge of its base, in centimeters?', '[]', '6', NULL, 'Use $V = \frac{1}{3}Bh$: $96 = \frac{1}{3} \times B \times 8$, so $B = 96 \times 3 \div 8 = 36$ square centimeters. The base is a square with area 36, so each edge is $\sqrt{36} = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96 = (1/3)s^2(8) -> s^2 = 36 -> s = 6.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31148311-be4a-4261-8571-cc013a3d8f33', 'NC26.8.SGMR.6', 2, 'choice', 'Find a missing dimension from a volume', 'A sphere has a volume of $36\pi$ cubic inches. What is its radius, in inches?', '["27","9","6","3"]', '3', NULL, 'Set $\frac{4}{3}\pi r^3 = 36\pi$. Then $\frac{4}{3}r^3 = 36$, so $r^3 = 27$ and $r = 3$ inches.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36pi = (4/3)pi r^3 -> r^3 = 27 -> r = 3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5af14d8a-a105-475f-ac58-61bf494b3106', 'NC26.8.SGMR.6', 2, 'numeric', 'Find a missing dimension from a volume', 'A pyramid has a rectangular base that is 6 m by 10 m. Its volume is 160 cubic meters. What is its height, in meters?', '[]', '8', '160*3/(6*10)', 'The base area is $6 \times 10 = 60$ square meters. From $160 = \frac{1}{3} \times 60 \times h = 20h$, $h = 8$ meters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"160 = (1/3)(60)h = 20h -> h = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d83985dd-21dc-43c3-8b80-5be3e17a5181', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume problems in context', 'A pile of gravel is shaped like a cone. It is 6 feet tall and its base has a radius of 5 feet. Use 3.14 for $\pi$. How many cubic feet of gravel are in the pile?', '[]', '157', '3.14*25*6/3', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times 3.14 \times 25 \times 6 = 3.14 \times 50 = 157$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(25)(6) = 3.14 x 50 = 157.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33578371-71ce-47a4-989d-e63247ee642f', 'NC26.8.SGMR.6', 2, 'choice', 'Volume problems in context', 'A paper cone for roasted nuts is 9 inches tall, and its opening has a radius of 5 inches. When it is filled to the top, how many cubic inches does it hold?', '["$75\\pi$","$225\\pi$","$300\\pi$","$15\\pi$"]', '$75\pi$', NULL, '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (5^2)(9) = \frac{1}{3} \times 25 \times 9 \times \pi = 75\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$75\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi(25)(9) = 75pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('589c47aa-0d36-4374-a0d5-7420cdaeb805', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume problems in context', 'A solid wooden pyramid has a square base 5 cm on each side and is 12 cm tall. Each cubic centimeter of the wood has a mass of 0.6 grams. What is the mass of the pyramid, in grams?', '[]', '60', '5*5*12/3*0.6', 'The volume is $\frac{1}{3} \times 25 \times 12 = 100$ cubic centimeters. The mass is $100 \times 0.6 = 60$ grams.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(25)(12) = 100 cm^3; mass 100 x 0.6 = 60 g.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45de4111-b000-4e01-8bae-745a7d55e9b5', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a composite solid', 'A storage bin is a cylinder with a cone-shaped roof. The cylinder has a radius of 3 m and a height of 5 m. The cone has the same radius and a height of 3 m. Use 3.14 for $\pi$. What is the total volume of the bin, in cubic meters?', '[]', '169.56', '3.14*9*5+3.14*9*3/3', 'Cylinder: $3.14 \times 3^2 \times 5 = 141.3$. Cone: $\frac{1}{3} \times 3.14 \times 3^2 \times 3 = 28.26$. Total: $141.3 + 28.26 = 169.56$ cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"169.56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi(9)(5) = 45pi; cone (1/3)pi(9)(3) = 9pi; total 54pi = 54 x 3.14 = 169.56.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b97e9712-1739-4744-9ea1-b814312218ab', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a composite solid', 'A solid is made by placing a square pyramid on top of a cube. The cube has edges of 6 cm. The pyramid''s base is the top face of the cube, and the pyramid is 4 cm tall. What is the volume of the whole solid, in cubic centimeters?', '["48","264","288","360"]', '264', '216+36*4/3', 'Cube: $6^3 = 216$. Pyramid: $\frac{1}{3} \times 6^2 \times 4 = 48$. Total: $216 + 48 = 264$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"264","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 216 + pyramid (1/3)(36)(4) = 48 -> 264.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93f0fdc1-9d67-4b11-8ebe-858cae8f0555', 'NC26.8.SGMR.6', 2, 'choice', 'How changing dimensions changes volume', 'The radius of a sphere is doubled. The volume of the new sphere is how many times the volume of the original sphere?', '["2","4","6","8"]', '8', '2^3', 'Volume depends on the cube of the radius, $r^3$. Doubling $r$ multiplies the volume by $2^3 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V scales with r^3: 2^3 = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cae3f0f2-3005-43a4-ba77-60f1edc26676', 'NC26.8.SGMR.6', 2, 'numeric', 'How changing dimensions changes volume', 'A cone has a volume of 12 cubic centimeters. A second cone has the same height but a radius 3 times as long. What is the volume of the second cone, in cubic centimeters?', '[]', '108', '12*9', 'Volume depends on the square of the radius. Tripling the radius multiplies the volume by $3^2 = 9$: $12 \times 9 = 108$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V scales with r^2 at fixed h: 12 x 9 = 108.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e4b674e-7981-4bfe-885d-edc4e57f0f44', 'NC26.8.SGMR.6', 2, 'numeric', 'Compare a sphere, a cone and a cylinder', 'A sphere and a cylinder have the same radius, and the cylinder''s height is equal to the sphere''s diameter. The cylinder has a volume of $90\pi$ cubic centimeters. The sphere has a volume of $k\pi$ cubic centimeters. What is $k$?', '[]', '60', '90*2/3', 'With height $2r$, the sphere is $\frac{2}{3}$ of the cylinder: $\frac{4}{3}\pi r^3$ compared with $2\pi r^3$. So $k = 90 \times \frac{2}{3} = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi r^2(2r) = 2pi r^3 = 90pi -> pi r^3 = 45pi. Sphere (4/3)(45pi) = 60pi, k = 60.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12730f45-9959-4656-9c81-6c34d590c3f8', 'NC26.8.SGMR.6', 3, 'numeric', 'Find the height of a cone from its volume', 'A cone has a radius of 4 cm and a volume of $48\pi$ cubic centimeters. What is its height, in centimeters?', '[]', '9', '48*3/16', 'Volume $= \frac{1}{3}\pi r^2 h$, so $48\pi = \frac{1}{3} \times \pi \times 16 \times h$. Divide by $\pi$ and multiply by 3: $144 = 16h$, so $h = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)pi(4^2)h = 48pi -> (16/3)h = 48 -> h = 9.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b35fb82-6d60-4e66-b910-527112a24194', 'NC26.8.SGMR.6', 3, 'choice', 'Sphere inside a cylinder', 'A sphere fits exactly inside a cylinder: it touches the top, the bottom and the curved side of the cylinder. The volume of the cylinder is $54\pi$ cubic centimeters. What is the volume of the sphere, in cubic centimeters?', '["$18\\pi$","$27\\pi$","$72\\pi$","$36\\pi$"]', '$36\pi$', NULL, 'The cylinder has radius $r$ and height $2r$, so its volume is $\pi r^2 (2r) = 2\pi r^3 = 54\pi$. Then $r^3 = 27$ and $r = 3$. The sphere has volume $\frac{4}{3}\pi (3^3) = 36\pi$ cubic centimeters. (It is $\frac{2}{3}$ of the cylinder: $\frac{2}{3} \times 54\pi = 36\pi$.)', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder has radius r and height 2r: 2pi r^3 = 54pi -> r^3 = 27 -> r = 3. Sphere = (4/3)pi(27) = 36pi (equivalently 2/3 of the cylinder).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc135c39-c281-4779-8ebf-0674fa44e14b', 'NC26.8.SGMR.6', 3, 'numeric', 'Surface area of a pyramid using its height', 'A square pyramid has a base edge of 16 cm and a height of 15 cm, measured straight up from the center of the base to the top. What is its total surface area, in square centimeters?', '[]', '800', '16^2+4*(1/2*16*17)', 'First find the slant height (the height of a triangular face). It is the hypotenuse of a right triangle with legs 15 and $16 \div 2 = 8$: $\sqrt{15^2 + 8^2} = \sqrt{289} = 17$. The base has area $16^2 = 256$. Each triangular face has area $\frac{1}{2} \times 16 \times 17 = 136$, and $4 \times 136 = 544$. The total is $256 + 544 = 800$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slant height: from base centre to midpoint of an edge is 8; slant = sqrt(15^2 + 8^2) = sqrt(225 + 64) = sqrt(289) = 17. Lateral = 4 * (1/2)(16)(17) = 4 * 136 = 544. Base = 16^2 = 256. Total = 800.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9852751-7954-4333-9ab8-85b8d53f06c7', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume of a pyramid', 'A square pyramid has a base edge of 10 cm and a slant height of 13 cm. Its height is the straight-up distance from the center of the base to the tip. What is the volume of the pyramid, in cubic centimeters?', '[]', '400', '100*12/3', 'The slant height, the height and half of the base edge (5 cm) form a right triangle. The height is $\sqrt{13^2 - 5^2} = \sqrt{144} = 12$ cm. The volume is $\frac{1}{3} \times 10^2 \times 12 = 400$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = sqrt(13^2 - 5^2) = 12; V = (1/3)(100)(12) = 400.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85fcd999-0654-43ea-811f-d1c453fcbf54', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a pyramid', 'A pyramid has a rectangular base. The length of the base is twice its width, and the width is 6 cm. The pyramid is 7 cm tall. What is its volume, in cubic centimeters?', '["504","252","168","84"]', '168', '6*12*7/3', 'The length is $2 \times 6 = 12$ cm, so the base area is $6 \times 12 = 72$ square centimeters. The volume is $\frac{1}{3} \times 72 \times 7 = 168$ cubic centimeters. (84 uses a square base.)', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 12, W = 6, B = 72; V = (1/3)(72)(7) = 168.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4692108b-70fc-4198-a24c-eeb1376066ed', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a pyramid', 'A pyramid has a triangular base with a base of 14 cm and a height of 9 cm. The pyramid itself is 10 cm tall. What is its volume, in cubic centimeters?', '["210","315","420","630"]', '210', '14*9/2*10/3', 'The base is a triangle with area $\frac{1}{2} \times 14 \times 9 = 63$ square centimeters. The volume is $\frac{1}{3} \times 63 \times 10 = 210$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B = (1/2)(14)(9) = 63; V = (1/3)(63)(10) = 210.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('693eb32c-6654-4d63-82ec-16e696a27432', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a cone', 'A cone has a radius of 5 cm and a slant height of 13 cm. Its height is the straight-up distance from the center of the base to the tip. What is the volume of the cone, in cubic centimeters?', '["$\\frac{325}{3}\\pi$","$100\\pi$","$300\\pi$","$65\\pi$"]', '$100\pi$', NULL, 'The radius, the height and the slant height form a right triangle, so the height is $\sqrt{13^2 - 5^2} = 12$ cm. $V = \frac{1}{3}\pi (5^2)(12) = 100\pi$ cubic centimeters. (Using 13 as the height gives the wrong value.)', 'checked', '{"lint":[],"solve":{"answer":"$100\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = sqrt(169 - 25) = 12; V = (1/3)pi(25)(12) = 100pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
