INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f79413c-8c52-4ce4-882a-6f19fbe6d486', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume of a cone', 'A cone-shaped cup has a radius of 6 cm and a height of 10 cm. Use 3.14 for $\pi$, and remember that 1 cubic centimeter holds 1 milliliter. How many full 50-milliliter servings can be poured from a full cup?', '[]', '7', NULL, 'The volume is $\frac{1}{3} \times 3.14 \times 6^2 \times 10 = 376.8$ cubic centimeters, which is 376.8 milliliters. $376.8 \div 50 = 7.536$, so 7 full servings can be poured.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(36)(10) = 376.8 mL; 376.8 / 50 = 7.536, so 7 full servings.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db1561d9-a63b-4b81-a541-183e8694a186', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a sphere', 'A bowl is shaped like half of a sphere (a hemisphere) with a radius of 9 inches. When the bowl is filled to the top, what is the volume of water in it, in cubic inches?', '["$972\\pi$","$243\\pi$","$486\\pi$","$54\\pi$"]', '$486\pi$', NULL, 'A full sphere has volume $\frac{4}{3}\pi (9^3) = 972\pi$. The bowl is half of that: $972\pi \div 2 = 486\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$486\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hemisphere = (2/3)pi r^3 = (2/3)pi(729) = 486pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d455712b-1dcb-473f-b633-5d631ec3f386', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume of a sphere', 'A ball is a sphere with a radius of 10.5 cm. Use $\frac{22}{7}$ for $\pi$. What is the volume of the ball, in cubic centimeters?', '[]', '4851', '4/3*22/7*10.5^3', 'Since $10.5 = \frac{21}{2}$, $10.5^3 = 1157.625$. $V = \frac{4}{3} \times \frac{22}{7} \times 1157.625$. First $\frac{22}{7} \times 1157.625 = 3638.25$, then $\frac{4}{3} \times 3638.25 = 4851$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4851","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10.5^3 = 1157.625; (4/3)(1157.625) = 1543.5; x 22/7 = 220.5 x 22 = 4851.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('607b2e28-b368-40e0-9d83-4088388983e3', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume of a sphere', 'The volume of a sphere is $\frac{256}{3}\pi$ cubic centimeters. What is the diameter of the sphere, in centimeters?', '[]', '8', NULL, 'Set $\frac{4}{3}\pi r^3 = \frac{256}{3}\pi$. Then $4r^3 = 256$, so $r^3 = 64$ and $r = 4$ cm. The diameter is $2 \times 4 = 8$ cm.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4/3)pi r^3 = (256/3)pi -> r^3 = 64 -> r = 4; d = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff1cbe4e-2fb0-43fb-99ac-3b376f5b0c7b', 'NC26.8.SGMR.6', 3, 'choice', 'Surface area of a pyramid', 'A pyramid has a rectangular base that is 18 cm by 10 cm. The two triangular faces on the 18 cm edges each have a slant height of 13 cm. The two triangular faces on the 10 cm edges each have a slant height of 15 cm. What is the total surface area of the pyramid, in square centimeters?', '["372","384","564","948"]', '564', '18*10+18*13+10*15', 'Base: $18 \times 10 = 180$. Two faces on the 18 cm edges: $2 \times \frac{1}{2} \times 18 \times 13 = 234$. Two faces on the 10 cm edges: $2 \times \frac{1}{2} \times 10 \times 15 = 150$. Total: $180 + 234 + 150 = 564$ square centimeters. (384 leaves out the base.)', 'checked', '{"lint":[],"solve":{"answer":"564","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 180; 2 x (1/2)(18)(13) = 234; 2 x (1/2)(10)(15) = 150. Total 564. (Consistent: h = 12 gives sqrt(144+25) = 13 and sqrt(144+81) = 15.)","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35f19ef6-b9e9-4d8a-91c4-05c181360572', 'NC26.8.SGMR.6', 3, 'numeric', 'Surface area of a pyramid', 'A square pyramid has a base edge of 6 cm and a total surface area of 96 square centimeters. What is the slant height of each triangular face, in centimeters?', '[]', '5', '(96-36)/12', 'The base area is $6^2 = 36$, so the four triangular faces have a combined area of $96 - 36 = 60$ square centimeters. Each face has area $\frac{1}{2} \times 6 \times s = 3s$, so $4 \times 3s = 60$, which gives $12s = 60$ and $s = 5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96 = 36 + 4(1/2)(6)l = 36 + 12l -> l = 5.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57694cab-709b-4d96-82b3-be496a90b559', 'NC26.8.SGMR.6', 3, 'choice', 'Surface area of a pyramid', 'A square pyramid has a base edge of 24 cm and a height of 16 cm, measured straight up from the center of the base to the tip. What is its total surface area, in square centimeters?', '["2496","1536","1344","960"]', '1536', '24*24+4*24*20/2', 'Half of the base edge is 12 cm, so the slant height is $\sqrt{16^2 + 12^2} = \sqrt{400} = 20$ cm. Base: $24^2 = 576$. Four faces: $4 \times \frac{1}{2} \times 24 \times 20 = 960$. Total: $576 + 960 = 1536$ square centimeters. (1344 uses the height 16 as the slant height; 960 leaves out the base.)', 'checked', '{"lint":[],"solve":{"answer":"1536","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slant = sqrt(16^2 + 12^2) = 20. Lateral 4(1/2)(24)(20) = 960; base 576; total 1536.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('165a47d9-eae8-41c4-bc01-f348c45b88de', 'NC26.8.SGMR.6', 3, 'numeric', 'Surface area of a pyramid', 'A square pyramid has a base edge of 24 cm and a volume of 960 cubic centimeters. What is the combined area of its four triangular faces, in square centimeters?', '[]', '624', '4*24*13/2', 'The base area is $24^2 = 576$, so $960 = \frac{1}{3} \times 576 \times h = 192h$ and $h = 5$ cm. The slant height is $\sqrt{5^2 + 12^2} = 13$ cm (half of the base edge is 12 cm). The four faces have area $4 \times \frac{1}{2} \times 24 \times 13 = 624$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"624","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"960 = (1/3)(576)h = 192h -> h = 5. Slant sqrt(25 + 144) = 13. Lateral 4(1/2)(24)(13) = 624.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afb6111b-18a4-4bc5-abdf-858816d8767a', 'NC26.8.SGMR.6', 3, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A cone is 12 cm tall and a cylinder is 4 cm tall. Their bases have the same area. Which statement is true?', '["The cone has 3 times the volume of the cylinder","The cylinder has 3 times the volume of the cone","The cone has more volume because it is taller","They have the same volume"]', 'They have the same volume', NULL, 'Let the base area be $B$. The cone has volume $\frac{1}{3} \times B \times 12 = 4B$. The cylinder has volume $B \times 4 = 4B$. They are equal.', 'checked', '{"lint":[],"solve":{"answer":"They have the same volume","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)B(12) = 4B; cylinder B(4) = 4B. Equal.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b96b734-efb8-4d48-9a74-4d4c68ab7043', 'NC26.8.SGMR.6', 3, 'numeric', 'Compare a sphere, a cone and a cylinder', 'Three identical balls, each with radius $r$, just fit one above another inside a cylindrical tube. The tube has radius $r$ and height $6r$. What fraction of the tube''s volume do the three balls fill? Write your answer as a fraction.', '[]', '2/3', '3*4/3/6', 'Each ball has volume $\frac{4}{3}\pi r^3$, so three balls have $4\pi r^3$. The tube has volume $\pi r^2 (6r) = 6\pi r^3$. The fraction filled is $\frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Balls 3(4/3)pi r^3 = 4pi r^3; tube pi r^2(6r) = 6pi r^3. Fraction 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('766a4301-db5c-4191-ba3b-86bac8f25d2a', 'NC26.8.SGMR.6', 3, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A cylinder has a volume of 90 cubic centimeters. A cone has the same radius as the cylinder and twice the height. What is the volume of the cone, in cubic centimeters?', '["30","60","90","180"]', '60', '90*2/3', 'A cone with the same radius and the same height would have $90 \div 3 = 30$ cubic centimeters. This cone is twice as tall, so its volume is $2 \times 30 = 60$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)pi r^2(2h) = (2/3)(pi r^2 h) = (2/3)(90) = 60.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76c2b5a5-c0e6-4942-80ed-c636f3d78d53', 'NC26.8.SGMR.6', 3, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A cone with a radius of 4 cm and a height of 6 cm has the same volume as a cylinder with a radius of 2 cm. What is the height of the cylinder, in centimeters?', '[]', '8', '(4^2*6/3)/2^2', 'The cone has volume $\frac{1}{3}\pi (4^2)(6) = 32\pi$. The cylinder has volume $\pi (2^2) h = 4\pi h$. Setting $4\pi h = 32\pi$ gives $h = 8$ cm.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)pi(16)(6) = 32pi = pi(4)h -> h = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae7d645e-e249-4261-9d5e-c5530d4ccbab', 'NC26.8.SGMR.6', 3, 'choice', 'Compare a sphere, a cone and a cylinder', 'A cone, a sphere and a cylinder all have radius $r$. The cone and the cylinder both have height $2r$. Which gives the ratio of their volumes in the order cone : sphere : cylinder?', '["1 : 2 : 3","1 : 3 : 2","3 : 2 : 1","1 : 1 : 3"]', '1 : 2 : 3', NULL, 'Cone: $\frac{1}{3}\pi r^2 (2r) = \frac{2}{3}\pi r^3$. Sphere: $\frac{4}{3}\pi r^3$. Cylinder: $\pi r^2 (2r) = 2\pi r^3 = \frac{6}{3}\pi r^3$. The volumes are in the ratio $2 : 4 : 6$, which is $1 : 2 : 3$.', 'checked', '{"lint":[],"solve":{"answer":"1 : 2 : 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)pi r^2(2r) = (2/3)pi r^3; sphere (4/3)pi r^3; cylinder 2pi r^3. 2/3 : 4/3 : 2 = 1 : 2 : 3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a93b8ad6-c3fe-49e6-92ad-1d0e3a242708', 'NC26.8.SGMR.6', 3, 'choice', 'Compare a sphere, a cone and a cylinder', 'Two balls, each with a radius of 3 cm, just fit one above the other in a cylindrical tube that has a radius of 3 cm and a height of 12 cm. What is the volume of the empty space in the tube around the balls, in cubic centimeters?', '["$72\\pi$","$108\\pi$","$18\\pi$","$36\\pi$"]', '$36\pi$', NULL, 'The tube has volume $\pi (3^2)(12) = 108\pi$. Each ball has volume $\frac{4}{3}\pi (3^3) = 36\pi$, so two balls have $72\pi$. The empty space is $108\pi - 72\pi = 36\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tube pi(9)(12) = 108pi; balls 2(4/3)pi(27) = 72pi; empty 36pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44c62d60-30be-4b28-abdc-b1676e5809d4', 'NC26.8.SGMR.6', 3, 'numeric', 'Find a missing dimension from a volume', 'A cone has a height of 8 cm and a volume of $96\pi$ cubic centimeters. What is its radius, in centimeters?', '[]', '6', NULL, 'Use $V = \frac{1}{3}\pi r^2 h$: $96\pi = \frac{1}{3}\pi r^2 (8)$. Then $288 = 8r^2$, so $r^2 = 36$ and $r = 6$ cm.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96pi = (1/3)pi r^2(8) -> r^2 = 36 -> r = 6.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cab75eb-b590-4c2a-93e8-ac18620429a5', 'NC26.8.SGMR.6', 3, 'choice', 'Find a missing dimension from a volume', 'A solid metal cylinder with a radius of 4 cm is melted and recast into a sphere with a radius of 6 cm, with no metal lost. How tall, in centimeters, was the cylinder?', '["9","13.5","18","72"]', '18', '4/3*6^3/4^2', 'The sphere has volume $\frac{4}{3}\pi (6^3) = 288\pi$. The cylinder had the same volume: $\pi (4^2) h = 16\pi h = 288\pi$, so $h = 18$ cm.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sphere (4/3)pi(216) = 288pi = pi(16)h -> h = 18.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fe50a34-1413-4c97-8241-3cad0da1336d', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume problems in context', 'A water tank is shaped like a cone that points downward. The top is a circle with a radius of 3 m, and the tank is 6 m deep. Use 3.14 for $\pi$. When the tank is full, how many liters of water does it hold? (1 cubic meter holds 1000 liters.)', '[]', '56520', '3.14*9*6/3*1000', 'The volume is $\frac{1}{3} \times 3.14 \times 3^2 \times 6 = 56.52$ cubic meters. In liters that is $56.52 \times 1000 = 56{,}520$ liters.', 'checked', '{"lint":[],"solve":{"answer":"56520","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(9)(6) = 3.14 x 18 = 56.52 m^3 = 56520 L.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616f3c7c-7401-486d-989c-7d0fc83a01e5', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume problems in context', 'A cylindrical jug has a radius of 6 cm and a height of 10 cm. Cone-shaped cups each have a radius of 3 cm and a height of 4 cm. How many cups can be filled completely from one full jug, with nothing left over?', '[]', '30', '(6^2*10)/(3^2*4/3)', 'The jug holds $\pi (6^2)(10) = 360\pi$ cubic centimeters. Each cup holds $\frac{1}{3}\pi (3^2)(4) = 12\pi$ cubic centimeters. $360\pi \div 12\pi = 30$ cups.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jug pi(36)(10) = 360pi; cup (1/3)pi(9)(4) = 12pi; 360/12 = 30.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('835f5f0c-0f1e-4589-8e98-7a16428e4d1c', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a composite solid', 'An ice-cream cone is a cone with a radius of 3 inches and a height of 9 inches. A scoop of ice cream shaped like a hemisphere (half a sphere) with a radius of 3 inches sits exactly on top of its opening. What is the combined volume of the cone and the scoop, in cubic inches?', '["$45\\pi$","$63\\pi$","$99\\pi$","$27\\pi$"]', '$45\pi$', NULL, 'Cone: $\frac{1}{3}\pi (3^2)(9) = 27\pi$. Hemisphere: $\frac{1}{2} \times \frac{4}{3}\pi (3^3) = 18\pi$. Total: $27\pi + 18\pi = 45\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$45\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)pi(9)(9) = 27pi; hemisphere (2/3)pi(27) = 18pi; total 45pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1666854b-ba8c-426b-b8a3-b195a56817c7', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a composite solid', 'A solid cylinder has a radius of 4 cm and a height of 6 cm. A cone-shaped hole with the same radius and the same height is drilled out of one end. What is the volume of the solid that is left, in cubic centimeters?', '["$128\\pi$","$32\\pi$","$96\\pi$","$64\\pi$"]', '$64\pi$', NULL, 'Cylinder: $\pi (4^2)(6) = 96\pi$. Cone: $\frac{1}{3}\pi (4^2)(6) = 32\pi$. What is left: $96\pi - 32\pi = 64\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$64\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi(16)(6) = 96pi; cone 32pi; left 64pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf4fa4b1-8fcc-4ef1-8f16-0ce8ebc3e20a', 'NC26.8.SGMR.6', 3, 'numeric', 'Volume of a composite solid', 'A toy rocket has a cylinder-shaped body with a radius of 6 cm and a height of 10 cm. A cone-shaped nose with the same radius and a height of 9 cm sits on top. Use 3.14 for $\pi$. What is the total volume of the rocket, in cubic centimeters?', '[]', '1469.52', '3.14*(36*10+36*9/3)', 'Body: $3.14 \times 6^2 \times 10 = 3.14 \times 360$. Nose: $\frac{1}{3} \times 3.14 \times 6^2 \times 9 = 3.14 \times 108$. Total: $3.14 \times (360 + 108) = 3.14 \times 468 = 1469.52$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"1469.52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi(36)(10) = 360pi; cone (1/3)pi(36)(9) = 108pi; total 468pi = 468 x 3.14 = 1469.52.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
