INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e923b4c4-c4de-4eef-8eb0-f291288e698c', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a composite solid', 'A medicine capsule is a cylinder with a radius of 2 mm and a length of 6 mm, with a hemisphere of radius 2 mm attached to each end. What is the volume of the capsule, in cubic millimeters?', '["$\\frac{104}{3}\\pi$","$24\\pi$","$\\frac{32}{3}\\pi$","$\\frac{136}{3}\\pi$"]', '$\frac{104}{3}\pi$', NULL, 'Cylinder: $\pi (2^2)(6) = 24\pi$. The two hemispheres together make one sphere: $\frac{4}{3}\pi (2^3) = \frac{32}{3}\pi$. Total: $24\pi + \frac{32}{3}\pi = \frac{72}{3}\pi + \frac{32}{3}\pi = \frac{104}{3}\pi$ cubic millimeters.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{104}{3}\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi(4)(6) = 24pi; two hemispheres = sphere (4/3)pi(8) = 32pi/3. Total 72pi/3 + 32pi/3 = 104pi/3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a1520b8-5c16-45af-9a6e-6230994c0459', 'NC26.8.SGMR.6', 3, 'choice', 'Volume of a composite solid', 'A hollow is cut into a solid cube with edges of 6 cm by removing a square pyramid. The pyramid''s base is the top face of the cube, and its height is 6 cm. What is the volume of the solid that remains, in cubic centimeters?', '["72","144","180","288"]', '144', '216-36*6/3', 'Cube: $6^3 = 216$. Pyramid removed: $\frac{1}{3} \times 6^2 \times 6 = 72$. What remains: $216 - 72 = 144$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 216 - pyramid (1/3)(36)(6) = 72 -> 144.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb6a4985-72e6-4758-8785-64e3fbcec71e', 'NC26.8.SGMR.6', 3, 'choice', 'How changing dimensions changes volume', 'The radius of a cone is doubled and its height is cut in half. What happens to the volume of the cone?', '["The volume stays the same","The volume is multiplied by 4","The volume doubles","The volume is cut in half"]', 'The volume doubles', NULL, 'Volume depends on $r^2$ and on $h$. Doubling $r$ multiplies the volume by $2^2 = 4$, and halving $h$ multiplies it by $\frac{1}{2}$. Together: $4 \times \frac{1}{2} = 2$, so the volume doubles.', 'checked', '{"lint":[],"solve":{"answer":"The volume doubles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)pi(2r)^2(h/2) = 2 x (1/3)pi r^2 h: doubles.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c85515b-05f5-456f-b420-5d8509335516', 'NC26.8.SGMR.6', 3, 'choice', 'How changing dimensions changes volume', 'The volume of a large sphere is 64 times the volume of a small sphere. The radius of the large sphere is how many times the radius of the small sphere?', '["32","16","8","4"]', '4', NULL, 'Volume depends on $r^3$, so the radius is multiplied by the number whose cube is 64. Since $4^3 = 64$, the radius of the large sphere is 4 times the radius of the small one. (16 would give $16^3 = 4096$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume ratio = (radius ratio)^3 = 64 -> radius ratio 4.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('040046b4-4b41-4a83-ad77-1190e39aee79', 'NC26.8.SGMR.6', 3, 'choice', 'How changing dimensions changes volume', 'The radius of a sphere increases from 2 cm to 6 cm. By what factor does the volume of the sphere increase?', '["3","9","18","27"]', '27', '(6/2)^3', 'The radius is multiplied by $6 \div 2 = 3$. Volume depends on $r^3$, so the volume is multiplied by $3^3 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radius x3, volume x3^3 = 27.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8abf898-e74a-4f4f-b8cf-8deeafbe7a1d', 'NC26.8.RD.1', 1, 'choice', 'Identify mutually exclusive events', 'A number cube with faces numbered 1 to 6 is rolled once. Which pair of events is mutually exclusive?', '["Rolling an even number and rolling an odd number","Rolling an even number and rolling a number greater than 3","Rolling a prime number and rolling an odd number","Rolling a number less than 4 and rolling an odd number"]', 'Rolling an even number and rolling an odd number', NULL, 'Mutually exclusive events cannot both happen on the same roll. A number cannot be both even and odd. The other pairs share an outcome: 4 and 6 are even and greater than 3; 3 and 5 are prime and odd; 1 and 3 are less than 4 and odd.', 'checked', '{"lint":[],"solve":{"answer":"Rolling an even number and rolling an odd number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even {2,4,6} and odd {1,3,5} share nothing: mutually exclusive. Others overlap: even & >3 share 4,6; <4 & odd share 1,3; prime & odd share 3,5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cc5ff25-0c1b-45e6-bcab-0077d7ed8115', 'NC26.8.RD.1', 1, 'numeric', 'Probability of one event or another (mutually exclusive)', 'A bag holds 4 red marbles, 3 blue marbles and 5 green marbles. One marble is drawn at random. What is the probability that it is red or blue?', '[]', '7/12', '(4+3)/12', 'There are $4 + 3 + 5 = 12$ marbles. A marble cannot be both red and blue, so add: $\frac{4}{12} + \frac{3}{12} = \frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 marbles; red or blue = 4 + 3 = 7. P = 7/12.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1175d36a-b86f-48b4-84ff-9f6131fd9f46', 'NC26.8.RD.1', 1, 'numeric', 'Probability of an "or" event on a spinner', 'A spinner has 10 equal sections numbered 1 to 10. It is spun once. What is the probability that it lands on a number less than 3 or greater than 8?', '[]', '2/5', '4/10', 'Numbers less than 3: 1 and 2. Numbers greater than 8: 9 and 10. No number is in both lists, so 4 of the 10 outcomes work. The probability is $\frac{4}{10} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 3: {1,2}; greater than 8: {9,10}; disjoint. 4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08a92863-e8bc-4f28-92c3-a4674f4e1eed', 'NC26.8.RD.1', 1, 'choice', 'Tell mutually exclusive events from inclusive events', 'One student is chosen at random from a middle school. Which pair of events is mutually exclusive?', '["The student is a girl; the student plays soccer","The student has a dog; the student has a cat","The student is in 6th grade; the student is in 8th grade","The student likes math; the student likes art"]', 'The student is in 6th grade; the student is in 8th grade', NULL, 'Mutually exclusive events cannot both happen at once. A student is in only one grade, so one student cannot be in both 6th grade and 8th grade. A student can be a girl and play soccer, have a dog and a cat, or like both math and art, so those pairs can happen together.', 'checked', '{"lint":[],"solve":{"answer":"The student is in 6th grade; the student is in 8th grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A student cannot be in 6th and 8th grade at once, so those events cannot both happen. Girl/soccer, math/art, dog/cat can all overlap.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf0ac5e2-2546-4b4c-9bd3-06e50019610c', 'NC26.8.RD.1', 1, 'choice', 'Tell mutually exclusive events from inclusive events', 'Which statement describes two events that are mutually exclusive?', '["They cannot both happen on the same trial","They always happen at the same time","They have the same probability","Their probabilities always add up to 1"]', 'They cannot both happen on the same trial', NULL, 'Mutually exclusive events have no outcomes in common, so they cannot both happen on one trial. Having the same probability, or adding up to 1, is not what the words mean.', 'checked', '{"lint":[],"solve":{"answer":"They cannot both happen on the same trial","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mutually exclusive means the events cannot both occur on the same trial. Adding to 1 is only for complements; the others are false.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e112658-3475-40af-804b-460e0ed334fa', 'NC26.8.RD.1', 1, 'numeric', 'Tell mutually exclusive events from inclusive events', 'A spinner has 8 equal sections numbered 1 to 8. Event A is landing on an even number. Event B is landing on a number greater than 5. How many of the sections are in both event A and event B?', '[]', '2', '2', 'Event A: 2, 4, 6, 8. Event B: 6, 7, 8. The sections in both are 6 and 8, which is 2 sections.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = {2,4,6,8}; B = {6,7,8}. Both: {6,8} -> 2 sections.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36eecf9c-c794-4c9a-ae1f-5c52da9eab97', 'NC26.8.RD.1', 1, 'choice', 'Tell mutually exclusive events from inclusive events', 'A card is picked at random from cards numbered 1 to 9. Which pair of events is inclusive, meaning both events can happen on the same pick?', '["An even number; an odd number","An even number; a number greater than 6","A number less than 4; a number greater than 6","The number 3; the number 7"]', 'An even number; a number greater than 6', NULL, 'The number 8 is even and also greater than 6, so both events can happen on one pick. No number is both even and odd, both less than 4 and greater than 6, or both 3 and 7.', 'checked', '{"lint":[],"solve":{"answer":"An even number; a number greater than 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"<4 = {1,2,3} and >6 = {7,8,9}: no overlap. Even/odd: none. 3 vs 7: none. Even = {2,4,6,8} and >6 = {7,8,9}: 8 is in both -> inclusive.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce81bb0b-c61c-4358-b301-be947628661d', 'NC26.8.RD.1', 1, 'choice', 'Tell mutually exclusive events from inclusive events', 'One day of the week is chosen at random. Which pair of events is NOT mutually exclusive?', '["The day is a Monday; the day is a Friday","The day is a Tuesday; the day is a Thursday","The day is a Sunday; the day is a Wednesday","The day is on a weekend; the day is a Saturday"]', 'The day is on a weekend; the day is a Saturday', NULL, 'Saturday is a weekend day, so both events happen when Saturday is chosen. The other pairs name two different days, so they cannot happen together.', 'checked', '{"lint":[],"solve":{"answer":"The day is on a weekend; the day is a Saturday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A Saturday is a weekend day, so \"weekend\" and \"Saturday\" can both happen. The other pairs are different single days.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f68e596-d96a-4f0d-9c27-3a066eef86c1', 'NC26.8.RD.1', 1, 'numeric', 'Tell mutually exclusive events from inclusive events', 'Events A and B are mutually exclusive. The probability of A is 0.3 and the probability of B is 0.5. What is the probability that A and B both happen on the same trial?', '[]', '0', '0', 'Mutually exclusive events cannot both happen on the same trial, so the probability that both happen is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mutually exclusive events cannot both happen, so P(A and B) = 0.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
