INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a00aa9b4-47c7-46d3-bb4d-1a6e2dbdd3e4', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'A fruit bowl holds 5 apples, 3 pears and 2 oranges. One piece of fruit is picked at random. What is the probability that it is a pear or an orange?', '[]', '1/2', '(3+2)/(5+3+2)', 'A piece of fruit cannot be a pear and an orange at once, so add the counts: 3 pears + 2 oranges = 5 pieces out of 10. The probability is 5/10 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pear or orange: 3 + 2 = 5 of 10 pieces. P = 5/10 = 1/2.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c69eaca8-b879-45de-8939-b4d1e6abf661', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'The probability that Dana walks to school is 0.4 and the probability that she rides the bus is 0.35. She does only one of these on any day. What is the probability that she walks or rides the bus?', '["0.05","0.14","0.25","0.75"]', '0.75', '0.4+0.35', 'She cannot walk and ride the bus on the same day, so add: 0.4 + 0.35 = 0.75.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She does only one per day, so the events are mutually exclusive: 0.4 + 0.35 = 0.75.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba6cc70a-7361-4a80-a54d-2ad00f0da319', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'A spinner has 8 equal sections: 3 are red, 2 are blue, 2 are green and 1 is yellow. What is the probability that the spinner lands on blue or yellow?', '[]', '3/8', '(2+1)/8', 'Blue and yellow sections are different sections. There are 2 + 1 = 3 of them among 8 equal sections, so the probability is 3/8.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 2 sections + yellow 1 section = 3 of 8 equal sections: 3/8.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43152640-30ea-4359-8463-30b95f948e77', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'The 8 letters of the word TRIANGLE are written on 8 tiles, one letter on each tile. One tile is drawn at random. What is the probability that it is a vowel or the letter L?', '["$\\frac{3}{8}$","$\\frac{1}{8}$","$\\frac{1}{2}$","$\\frac{3}{64}$"]', '$\frac{1}{2}$', NULL, 'The vowels are I, A and E (3 tiles). The letter L is 1 more tile, and L is not a vowel. So 3 + 1 = 4 tiles out of 8 give 4/8 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"TRIANGLE: T,R,I,A,N,G,L,E. Vowels I, A, E = 3 tiles; L = 1 tile; no overlap. 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab6e7a06-45e5-4dc7-9c5a-096507856c1e', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'In a survey, each student chose one favorite lunch. 30% chose pizza, 25% chose pasta, and the rest chose other foods. What percent of the students chose pizza or pasta?', '[]', '55', '30+25', 'Each student chose only one lunch, so the groups do not overlap. Add: 30% + 25% = 55%.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each student chose one lunch, so the choices are mutually exclusive: 30% + 25% = 55%.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('705a2379-e0ba-4abe-be98-e92926a4b34c', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'A spinner lands on blue with probability $\frac{1}{4}$ and on green with probability $\frac{1}{6}$. It cannot land on both at once. What is the probability that it lands on blue or green?', '["$\\frac{1}{5}$","$\\frac{5}{12}$","$\\frac{1}{24}$","$\\frac{1}{12}$"]', '$\frac{5}{12}$', NULL, 'The events are mutually exclusive, so add: $\frac{1}{4}$ + $\frac{1}{6}$ = $\frac{3}{12}$ + $\frac{2}{12}$ = $\frac{5}{12}$. Adding the tops and the bottoms separately, or multiplying, is a mistake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 + 1/6 = 3/12 + 2/12 = 5/12.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a07e1d3-a82a-436b-b9e2-ac2fbcfd0951', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'Events A and B are mutually exclusive. Which expression gives the probability that A or B happens?', '["$P(A) + P(B)$","$P(A) \\times P(B)$","$P(A) - P(B)$","$P(A) \\div P(B)$"]', '$P(A) + P(B)$', NULL, 'For mutually exclusive events, no outcome is counted in both, so the probability that A or B happens is found by adding: P(A) + P(B).', 'checked', '{"lint":[],"solve":{"answer":"$P(A) + P(B)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"For mutually exclusive events P(A or B) = P(A) + P(B).","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89a6f082-a9c1-40ab-8f5c-b987b2f60a2f', 'NC26.8.RD.1', 1, 'choice', 'Probability of A or B when the events overlap', 'A fair number cube is rolled once. What is the probability of rolling an even number or a number greater than 4?', '["$\\frac{5}{6}$","$\\frac{1}{6}$","$\\frac{1}{3}$","$\\frac{2}{3}$"]', '$\frac{2}{3}$', NULL, 'Even numbers: 2, 4, 6. Numbers greater than 4: 5, 6. Together the outcomes are 2, 4, 5, 6, which is 4 different outcomes (6 is in both lists and is counted once). The probability is 4/6 = 2/3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even {2,4,6}, greater than 4 {5,6}. Union {2,4,5,6} = 4 outcomes. 4/6 = 2/3. (Check: 3/6 + 2/6 - 1/6 = 4/6.)","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74a9a75d-309f-415a-8fe1-933b9d64e4eb', 'NC26.8.RD.1', 1, 'numeric', 'Probability of A or B when the events overlap', 'In a class of 25 students, 15 have a brother, 10 have a sister, and 5 have both a brother and a sister. How many students have a brother or a sister (or both)?', '[]', '20', '15+10-5', 'Adding 15 and 10 counts the 5 students who have both twice. Subtract them once: 15 + 10 - 5 = 20 students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Brother or sister = 15 + 10 - 5 = 20.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
