INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d4dc106-4cf3-4479-9b51-0d2bdfd0a919', 'NC26.8.RD.4', 1, 'numeric', 'Find the mean and deviations from the mean', 'A data set has a mean of 7 and contains the value 3. What is the square of the distance from 3 to the mean?', '[]', '16', '(3-7)^2', 'The distance from 3 to 7 is 4 (the deviation is -4). Squared: 4 x 4 = 16.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance |3-7| = 4; squared 16.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('209c2b80-d3f8-4c62-8590-e3e4c5f69e7b', 'NC26.8.RD.4', 1, 'numeric', 'Compute a variance', 'A cashier served 4, 4, 4 and 8 customers in four 10-minute periods. The mean is 5. What is the variance of these counts? (The variance is the mean of the squared distances from the mean.)', '[]', '3', '((4-20/4)^2+(4-20/4)^2+(4-20/4)^2+(8-20/4)^2)/4', 'Distances from 5: -1, -1, -1, 3. Squared: 1, 1, 1, 9. The sum is 12, and 12 / 4 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations -1,-1,-1,3; squares 1,1,1,9 sum 12; 12/4 = 3.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5d3c320-8f00-40a7-9892-caf9ec430340', 'NC26.8.RD.4', 1, 'numeric', 'Compute a variance', 'A snail crawled 2, 2, 6 and 6 meters on four days. The mean is 4 meters. Find the variance of these distances. (The variance is the mean of the squared distances from the mean.)', '[]', '4', '((2-16/4)^2+(2-16/4)^2+(6-16/4)^2+(6-16/4)^2)/4', 'Each value is 2 away from 4, so each squared distance is 4. The mean of four 4s is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations -2,-2,2,2; squares 4 each, sum 16; 16/4 = 4.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('492b8117-e1a3-40cb-aab4-ba88327103bb', 'NC26.8.RD.4', 1, 'numeric', 'Compute a variance', 'All five of Jo''s quiz scores were 9. What is the variance of her scores?', '[]', '0', '0', 'Every score equals the mean, 9, so every distance from the mean is 0. The variance is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All values equal the mean 9, every deviation 0, variance 0.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
