INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bbcf40b-1cbe-43c8-989a-72f2c3c1a8b9', 'NC26.8.RD.4', 1, 'numeric', 'Compute a standard deviation', 'Two bus trips took 3 hours and 7 hours. The mean is 5 hours. What is the standard deviation of the two trip times, in hours? (The standard deviation is the square root of the variance, which is the mean of the squared distances from the mean.)', '[]', '2', '2', 'Distances from 5 are -2 and 2; squared they are 4 and 4. The variance is 4, and its square root is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations -2, 2; squares 4, 4; variance 4; SD 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
