INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e2f88cc-15cc-4727-95c1-4e8fa0862073', 'NC26.8.RD.4', 1, 'choice', 'Relate variance and standard deviation', 'Which statement correctly relates the variance and the standard deviation of a data set?', '["The standard deviation is the square of the variance","The standard deviation is the square root of the variance","The standard deviation is half of the variance","The variance is the square root of the standard deviation"]', 'The standard deviation is the square root of the variance', NULL, 'Squaring the standard deviation gives the variance, so taking the square root of the variance gives the standard deviation.', 'checked', '{"lint":[],"solve":{"answer":"The standard deviation is the square root of the variance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD = sqrt(variance).","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b21ef6a-89a3-4a1d-99ac-0103dab69393', 'NC26.8.RD.4', 1, 'numeric', 'Relate variance and standard deviation', 'A calculator reports a variance of 144 for a list of race times. What is the standard deviation of the times?', '[]', '12', '12', 'The standard deviation is the square root of the variance. The square root of 144 is 12, because 12 x 12 = 144.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(144) = 12.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57870a07-ee29-4126-8cc7-7d25af7cd978', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'Class A and Class B both have a mean test score of 80. Class A''s scores run from 78 to 82. Class B''s scores run from 60 to 100. Which class most likely has the larger standard deviation?', '["Class A, since its scores are closer to the mean","Class B, since its scores are more spread out","Class A, since its scores are all about equal","Neither, since the two means are the same"]', 'Class B, since its scores are more spread out', NULL, 'The standard deviation measures spread around the mean. Class B''s scores are much more spread out, so its standard deviation is larger.', 'checked', '{"lint":[],"solve":{"answer":"Class B, since its scores are more spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same mean; B spans 60-100 vs A 78-82, so B is more spread out and most likely has the larger SD.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9bde321-e8d9-496b-8edb-62724230fc98', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'Each list has a mean of 5. Which list has the smallest standard deviation?', '["3, 5, 5, 7","1, 3, 7, 9","0, 0, 10, 10","5, 5, 5, 5"]', '5, 5, 5, 5', NULL, 'The list 5, 5, 5, 5 has no spread at all: every value is the mean, so its standard deviation is 0. The others are spread out by different amounts.', 'checked', '{"lint":[],"solve":{"answer":"5, 5, 5, 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,5,5,5 has SD 0, the smallest possible; others are positive.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088a4127-834d-47d9-acad-6b5b10bac521', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'What does a larger standard deviation tell you about a data set?', '["The values are more spread out from the mean","The mean of the values is larger","The data set has more values in it","The values are all larger numbers"]', 'The values are more spread out from the mean', NULL, 'Standard deviation measures how far values typically are from the mean. A larger one means more spread, not a larger mean or more values.', 'checked', '{"lint":[],"solve":{"answer":"The values are more spread out from the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger SD means values lie farther from the mean on average.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('788e5e60-861e-40b6-b41b-d60415b87ff0', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'A data set has a standard deviation of 0. What must be true?', '["The mean of the values is 0","Half of the values are 0","All the values are the same","All the values are different"]', 'All the values are the same', NULL, 'A standard deviation of 0 means no value is any distance from the mean, so every value equals the mean.', 'checked', '{"lint":[],"solve":{"answer":"All the values are the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD 0 means every squared distance is 0, so every value equals the mean: all the same.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a04275b8-bd4e-4cb9-8c9c-8a1025a04004', 'NC26.8.RD.4', 1, 'choice', 'Effect of changing every value on mean and spread', 'Mr. Ray adds 8 points to every score on a quiz. What happens to the standard deviation of the scores?', '["It increases by 8","It is multiplied by 8","It stays the same","It decreases by 8"]', 'It stays the same', NULL, 'Adding the same number to every value slides the whole data set up. The distances between values do not change, so the spread stays the same.', 'checked', '{"lint":[],"solve":{"answer":"It stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding a constant shifts every value and the mean equally; deviations unchanged, SD unchanged.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8f3b37-0659-41c8-aad5-fa909b543cbc', 'NC26.8.RD.4', 1, 'numeric', 'Effect of changing every value on mean and spread', 'Every plant in a garden grows exactly 10 centimeters taller. Before the growth, the mean height was 25 centimeters. What is the mean height afterward, in centimeters?', '[]', '35', '25+10', 'Adding 10 to every height adds 10 to the mean: 25 + 10 = 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 10 to every value adds 10 to the mean: 25 + 10 = 35.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
