INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('256c9638-f153-47f9-a350-6e7093aee244', 'NC26.8.RD.4', 1, 'choice', 'Effect of an outlier', 'Which statement best describes an outlier in a data set?', '["A value far away from most of the other values","The value that appears most often","The value exactly in the middle","The value equal to the mean"]', 'A value far away from most of the other values', NULL, 'An outlier is an unusually large or small value that sits far from the rest of the data.', 'checked', '{"lint":[],"solve":{"answer":"A value far away from most of the other values","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An outlier lies far from most of the other values.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
