VALUES ('aca43df5-b676-4c9d-a22b-08190e775994', 'NC26.8.RD.4', 1, 'numeric', 'Effect of an outlier', 'Which value in this list is the outlier? Give that value. 12, 14, 13, 15, 14, 60', '[]', '60', NULL, 'Most values are between 12 and 15. The value 60 is far from all of them, so it is the outlier.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values cluster 12-15; 60 is far away.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
