INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c609906-011c-46ee-b6ad-d605412bae56', 'NC26.8.RD.4', 1, 'choice', 'Effect of an outlier', 'A data set has a standard deviation of 3. A new, extremely large value is added, far above all the others. What most likely happens to the standard deviation?', '["It gets smaller","It stays exactly the same","It becomes 0","It gets larger"]', 'It gets larger', NULL, 'The new value is far from the mean, so its squared distance is very large. That makes the mean squared distance, and so the standard deviation, larger.', 'checked', '{"lint":[],"solve":{"answer":"It gets larger","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A value far from the mean adds a large squared distance; SD grows.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
