INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b3f9c4a-0c51-4d2d-a725-fc1ff00b9c91', 'NC26.8.RD.4', 1, 'choice', 'Choose a measure of spread', 'Which of these is a measure of spread?', '["Mean","Range","Median","Mode"]', 'Range', NULL, 'The mean, median and mode describe the centre of a data set. The range, the largest minus the smallest value, describes spread.', 'checked', '{"lint":[],"solve":{"answer":"Range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mode, mean, median are centre; range is spread.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
