INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2af3e91b-c0a7-4286-a8d8-3608492ceb0e', 'NC26.8.RD.4', 1, 'choice', 'Choose a measure of spread', 'Which pair has one measure of centre and one measure of spread?', '["Mean and median","Median and standard deviation","Mode and mean","Range and standard deviation"]', 'Median and standard deviation', NULL, 'The median is a measure of centre and the standard deviation is a measure of spread. The other pairs are two centres or two spreads.', 'checked', '{"lint":[],"solve":{"answer":"Median and standard deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median (centre) + SD (spread). Others: two centres, two centres, two spreads.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
