INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('694a11bb-3780-47dc-9929-cc884a60cb7c', 'NC26.8.RD.4', 1, 'numeric', 'Interpret standard deviation in context', 'A set of test scores has a mean of 40 and a standard deviation of 5. How many standard deviations above the mean is a score of 50?', '[]', '2', '(50-40)/5', 'The score is 50 - 40 = 10 points above the mean. One standard deviation is 5 points, so 10 / 5 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(50 - 40)/5 = 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
