INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('985484ca-2f7e-4ef8-8b54-c645412ca121', 'NC26.8.RD.4', 1, 'choice', 'Interpret standard deviation in context', 'Heights in a class have a mean of 100 centimeters and a standard deviation of 10 centimeters. What height is exactly 1 standard deviation below the mean?', '["110 centimeters","100 centimeters","89 centimeters","90 centimeters"]', '90 centimeters', NULL, 'One standard deviation below the mean is 100 - 10 = 90 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"90 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 10 = 90 cm.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
