INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96ac6eef-7b61-4a9d-8369-e1c69e50fbd7', 'NC26.8.RD.4', 1, 'choice', 'Compare distributions by centre and spread', 'Two bakeries both have a mean wait of 5 minutes. Bakery P has a standard deviation of 1 minute and Bakery Q has a standard deviation of 3 minutes. Which has the more consistent wait?', '["Bakery P, because its waits vary less","Bakery Q, because its waits vary more","Both, because the means are equal","Bakery Q, because its standard deviation is larger"]', 'Bakery P, because its waits vary less', NULL, 'The smaller the standard deviation, the less the waits vary, so Bakery P is more consistent.', 'checked', '{"lint":[],"solve":{"answer":"Bakery P, because its waits vary less","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smaller SD = more consistent: P (1 min).","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f6935ab-ab42-46b0-aae1-17c148253361', 'NC26.8.RD.4', 1, 'numeric', 'Compute a standard deviation', 'A set of 6 bike-ride lengths has squared distances from the mean that add up to 150. What is the standard deviation of the ride lengths? (The standard deviation is the square root of the mean of the squared distances from the mean: divide by the number of values.)', '[]', '5', NULL, 'The mean of the squared distances is 150 / 6 = 25. The standard deviation is the square root of 25, which is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Variance = 150/6 = 25. SD = sqrt(25) = 5.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86df02fd-6b50-46f6-b547-23377be36378', 'NC26.8.RD.4', 2, 'numeric', 'Compute a standard deviation', 'The data set 2, 4, 4, 4, 5, 5, 7, 9 has a mean of 5. What is its standard deviation? (The standard deviation is the square root of the mean of the squared distances from the mean.)', '[]', '2', '(9+1+1+1+0+0+4+16)/8/2', 'The distances from 5 are 3, 1, 1, 1, 0, 0, 2 and 4. Their squares are 9, 1, 1, 1, 0, 0, 4 and 16, which add up to 32. The mean of the squares is $32 \div 8 = 4$. The standard deviation is $\sqrt{4} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations from 5: -3, -1, -1, -1, 0, 0, 2, 4; squares 9, 1, 1, 1, 0, 0, 4, 16; sum 32; mean 32/8 = 4; SD = sqrt(4) = 2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfd65034-058e-42e4-afd5-6d4377481b58', 'NC26.8.RD.4', 2, 'choice', 'Effect of adding a constant on center and spread', 'Every value in a data set is increased by 10. What happens to the mean and to the standard deviation of the data set?', '["The mean and the standard deviation both go up by 10","The mean goes up by 10 and the standard deviation stays the same","The mean stays the same and the standard deviation goes up by 10","The mean goes up by 10 and the standard deviation is multiplied by 10"]', 'The mean goes up by 10 and the standard deviation stays the same', NULL, 'Adding 10 to every value slides the whole data set up by 10, so the mean goes up by 10. The distances between the values and the mean do not change, so the standard deviation stays the same.', 'checked', '{"lint":[],"solve":{"answer":"The mean goes up by 10 and the standard deviation stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 10 shifts every value and the mean by 10; distances from the mean are unchanged, so SD stays the same.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('957bc7f5-314b-4bbf-a1de-1f32d4689903', 'NC26.8.RD.4', 2, 'choice', 'Compare standard deviations without computing', 'Three data sets each have five values and a mean of 10. Set 1: 9, 10, 10, 10, 11. Set 2: 6, 8, 10, 12, 14. Set 3: 0, 5, 10, 15, 20. Which set has the greatest standard deviation?', '["Set 1","Set 3","Set 2","All three have the same standard deviation, because the means are equal"]', 'Set 3', NULL, 'The standard deviation is larger when values are farther from the mean. Set 3''s values are the farthest from 10, and Set 1''s are the closest. Equal means do not mean equal standard deviations.', 'checked', '{"lint":[],"solve":{"answer":"Set 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 3 has values farthest from 10 (deviations 10, 5, 0, 5, 10) versus Set 2 (4, 2, 0, 2, 4) and Set 1 (1, 0, 0, 0, 1). Set 3 greatest SD.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b346b20-8e7e-48ca-a0bc-0fb6ce20d482', 'NC26.8.RD.4', 2, 'choice', 'Find the mean and deviations from the mean', 'For any data set, the signed deviations are each value minus the mean. What is the sum of all the signed deviations?', '["It is always the mean","It is always the variance","It is always 0","It is always the number of values"]', 'It is always 0', NULL, 'The values above the mean and the values below the mean balance exactly, so the signed deviations always add to 0.', 'checked', '{"lint":[],"solve":{"answer":"It is always 0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum(x - mean) = Sum x - n*mean = 0.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a34b7a0-80a0-4336-9711-c48bf173ec31', 'NC26.8.RD.4', 2, 'numeric', 'Find the mean and deviations from the mean', 'A data set of 4 values has a mean of 10. Three of the values are 3, 5 and 4 away from the mean, with deviations of -3, 5 and -4. What is the deviation of the fourth value?', '[]', '2', '3-5+4', 'The four deviations must add to 0. The three known ones add to -3 + 5 - 4 = -2, so the fourth deviation is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations sum to 0: -3 + 5 - 4 + d = 0, d = 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2aaf873-c64d-4afa-ac82-c8d1962ffbbb', 'NC26.8.RD.4', 2, 'numeric', 'Compute a variance', 'Ana ran four sprints in 2, 6, 6 and 10 seconds. What is the variance of her times? (The variance is the mean of the squared distances from the mean.)', '[]', '8', '((2-24/4)^2+(6-24/4)^2+(6-24/4)^2+(10-24/4)^2)/4', 'The mean is 24 / 4 = 6. Distances: -4, 0, 0, 4. Squared: 16, 0, 0, 16. The sum is 32, and 32 / 4 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 24/4 = 6; deviations -4,0,0,4; squares 16,0,0,16 = 32; 32/4 = 8.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0ea134f-7e40-4054-a871-a34b9472e9a5', 'NC26.8.RD.4', 2, 'numeric', 'Compute a variance', 'A team scored 1, 2, 3, 4 and 5 goals in five games. Find the variance of the goals. (The variance is the mean of the squared distances from the mean.)', '[]', '2', '((1-15/5)^2+(2-15/5)^2+(3-15/5)^2+(4-15/5)^2+(5-15/5)^2)/5', 'The mean is 15 / 5 = 3. Distances: -2, -1, 0, 1, 2. Squared: 4, 1, 0, 1, 4. The sum is 10, and 10 / 5 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 3; squares 4,1,0,1,4 = 10; 10/5 = 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('179b57d1-7288-44ca-8e24-1527464a502e', 'NC26.8.RD.4', 2, 'choice', 'Compute a variance', 'Four friends have 3, 3, 5 and 9 stickers. What is the variance of their sticker counts? (The variance is the mean of the squared distances from the mean.)', '["24","4.8","6","5"]', '6', '((3-20/4)^2+(3-20/4)^2+(5-20/4)^2+(9-20/4)^2)/4', 'The mean is 20 / 4 = 5. Squared distances: 4, 4, 0, 16. The sum is 24, and 24 / 4 = 6. (24 is the sum of the squares, 4.8 divides by 5 instead of 4, and 5 is the mean.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 20/4 = 5; deviations -2,-2,0,4; squares 4,4,0,16 = 24; 24/4 = 6.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
