INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77258e15-360f-4580-a0ad-4432c60cd049', 'NC26.8.RD.4', 2, 'numeric', 'Effect of changing every value on mean and spread', 'Ms. Lee adds 5 bonus points to every student''s score. Before the bonus, the mean was 72 and the standard deviation was 8. What is the mean after the bonus?', '[]', '77', '72+5', 'Adding 5 to every score adds 5 to the mean: 72 + 5 = 77. (The standard deviation stays 8.)', 'checked', '{"lint":[],"solve":{"answer":"77","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 + 5 = 77.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
