INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fbbc35c-98a5-4362-8df4-be9c5b2f6dea', 'NC26.8.RD.4', 2, 'numeric', 'Effect of an outlier', 'Five friends used 8, 9, 10, 11 and 12 gigabytes of data in a month. A sixth friend, who streams a lot, used 52 gigabytes. What is the mean for all six friends, in gigabytes?', '[]', '17', '(8+9+10+11+12+52)/6', 'The total is 8 + 9 + 10 + 11 + 12 + 52 = 102. Dividing by 6 gives 17. The one large value pulls the mean far above the first five.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8+9+10+11+12 = 50; +52 = 102; 102/6 = 17.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0f1653a-8ee7-4205-91dc-75b93dfe9fbc', 'NC26.8.RD.4', 2, 'choice', 'Effect of an outlier', 'One extremely large outlier is added to a data set. Which statement is most likely true?', '["The median changes a lot more than the mean does","The mean and the median both stay exactly the same","The mean and the median change by the same amount","The mean changes a lot more than the median does"]', 'The mean changes a lot more than the median does', NULL, 'The mean uses the size of every value, so an extreme value drags it. The median depends only on the order of the values, so it moves little.', 'checked', '{"lint":[],"solve":{"answer":"The mean changes a lot more than the median does","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The mean is pulled toward the outlier; the median moves at most one position.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('350e10b4-cb70-4637-9092-28c3e0d7d490', 'NC26.8.RD.4', 2, 'numeric', 'Effect of an outlier', 'Sam was absent for a quiz and got 0. His class''s other scores were 72, 76, 78 and 74. What is the mean of those four scores, with the 0 left out?', '[]', '75', '(72+76+78+74)/4', 'The four scores add to 72 + 76 + 78 + 74 = 300. Dividing by 4 gives 75.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72+76+78+74 = 300; 300/4 = 75.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99cdf1d1-a9a1-41c6-bad8-884cd7e9bab3', 'NC26.8.RD.4', 2, 'numeric', 'Effect of an outlier', 'A club''s members are 14, 15, 15, 17, 18 and 71 years old. The 71-year-old is the coach. By how much does the range of the ages decrease if the coach is left out?', '[]', '53', '(71-14)-(18-14)', 'With the coach the range is 71 - 14 = 57. Without the coach it is 18 - 14 = 4. The range decreases by 57 - 4 = 53.', 'checked', '{"lint":[],"solve":{"answer":"53","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With coach: 71-14 = 57. Without: 18-14 = 4. Decrease 53.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3377a0fa-8cd6-47eb-967b-f14285228e6d', 'NC26.8.RD.4', 2, 'choice', 'Choose a measure of spread', 'House prices in a town are mostly between 150 and 250 thousand dollars, but a few mansions cost over 2 million dollars. Which measure best describes how much typical prices vary?', '["The IQR, since extreme prices hardly affect it","The range, since it shows the mansions too","The standard deviation, since it uses every price","The variance, since it squares the distances"]', 'The IQR, since extreme prices hardly affect it', NULL, 'A few extreme prices stretch the range, the variance and the standard deviation. The IQR uses only the middle half of the prices, so it describes typical variation.', 'checked', '{"lint":[],"solve":{"answer":"The IQR, since extreme prices hardly affect it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Extreme mansions distort range, variance and SD; IQR is resistant.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2c91c90-bf76-4385-8ace-692cd3e1650b', 'NC26.8.RD.4', 2, 'choice', 'Choose a measure of spread', 'A coach wants a measure of spread that uses every value in the data set. Which should she choose?', '["The range","The IQR","The standard deviation","The median"]', 'The standard deviation', NULL, 'The range uses only the smallest and largest values and the IQR uses only the quartiles. The median is a measure of centre. The standard deviation uses every value.', 'checked', '{"lint":[],"solve":{"answer":"The standard deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range uses 2 values, IQR quartiles, median is centre; SD uses every value.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8765fcdb-effe-4232-b1f8-fad04b048560', 'NC26.8.RD.4', 2, 'choice', 'Choose a measure of spread', 'Why is the IQR called a resistant measure of spread?', '["It uses every value in the data, so extremes are simply averaged out","It is always larger than the standard deviation for the same data","It uses only the middle half of the values, so extremes hardly matter","It is always equal to the range when the data are symmetric"]', 'It uses only the middle half of the values, so extremes hardly matter', NULL, 'The IQR is the distance between the quartiles, so it ignores the lowest quarter and the highest quarter of the data, where outliers sit.', 'checked', '{"lint":[],"solve":{"answer":"It uses only the middle half of the values, so extremes hardly matter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3 - Q1, based on the middle half, so extremes hardly affect it.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('caffe1c8-ff79-41a0-ab58-c3c1fa6cc263', 'NC26.8.RD.4', 2, 'choice', 'Interpret standard deviation in context', 'A set of times has a mean of 20 minutes and a standard deviation of 3 minutes. Which time is within 1 standard deviation of the mean?', '["22 minutes","26 minutes","15 minutes","29 minutes"]', '22 minutes', NULL, 'Within 1 standard deviation means between 20 - 3 = 17 and 20 + 3 = 23 minutes. Only 22 is in that range.', 'checked', '{"lint":[],"solve":{"answer":"22 minutes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Within 1 SD: 17 to 23. Only 22 fits (15, 26, 29 outside).","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98a75319-253d-4308-9209-f2594c0f162b', 'NC26.8.RD.4', 2, 'choice', 'Interpret standard deviation in context', 'A set of scores has a mean of 64 and a standard deviation of 6. A score of 79 is how many standard deviations above the mean?', '["15","0.4","90","2.5"]', '2.5', '15/6', 'The score is 79 - 64 = 15 points above the mean. Each standard deviation is 6 points, so 15 / 6 = 2.5.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(79 - 64)/6 = 15/6 = 2.5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0aa29e5-f8fd-49cd-a166-395efd907c11', 'NC26.8.RD.4', 2, 'numeric', 'Interpret standard deviation in context', 'Scores on an exam have a mean of 500 and a standard deviation of 40. What score is 2.5 standard deviations above the mean?', '[]', '600', '500+2.5*40', '2.5 standard deviations is 2.5 x 40 = 100 points. Add to the mean: 500 + 100 = 600.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500 + 2.5*40 = 600.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07a5e82f-6b7b-4d9f-85bb-3f89201d53bf', 'NC26.8.RD.4', 2, 'choice', 'Compare distributions by centre and spread', 'Route A has a mean trip time of 20 minutes and a standard deviation of 2 minutes. Route B has a mean of 18 minutes and a standard deviation of 7 minutes. Which statement is true?', '["Route A is faster on average and more predictable","Route B is faster on average but less predictable","Route B is faster on average and more predictable","Route A is slower on average and less predictable"]', 'Route B is faster on average but less predictable', NULL, 'Route B has the smaller mean, so it is faster on average. Route B has the larger standard deviation, so its times vary more and are less predictable.', 'checked', '{"lint":[],"solve":{"answer":"Route B is faster on average but less predictable","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B mean 18 < 20 (faster), SD 7 > 2 (less predictable). A is slower but more predictable, so other options false.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2651f7b3-b385-47b4-ad7d-7332d131cd99', 'NC26.8.RD.4', 2, 'choice', 'Use technology output for spread', 'A student enters six test scores into a calculator. It shows a mean of 84 and a standard deviation of 0. What does this tell you?', '["The scores are 0 and 84","All six scores are 84","The scores add up to 0","Half the scores are above 84"]', 'All six scores are 84', NULL, 'A standard deviation of 0 means no score differs from the mean, so every score equals the mean, 84.', 'checked', '{"lint":[],"solve":{"answer":"All six scores are 84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD 0 means all values equal the mean, 84.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11d81ddf-b1f3-4903-bbd0-5f07dd50f269', 'NC26.8.RD.4', 2, 'numeric', 'Use technology output for spread', 'A spreadsheet reports that the squared distances from the mean of 12 test scores add up to 300. The variance is the mean of the squared distances from the mean (divide by the number of scores, 12). What is the variance of the 12 scores?', '[]', '25', '300/12', 'Variance = (sum of squared distances) / (number of values) = 300 / 12 = 25.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Variance = 300/12 = 25.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
