INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f8c1362-c609-4038-b68d-4c5f6c4e1d83', 'NC26.8.RD.4', 3, 'numeric', 'Compare standard deviations of two data sets', 'Data set X is 6, 6, 14, 14. Data set Y is 8, 8, 12, 12. Both sets have a mean of 10. How much greater is the standard deviation of X than the standard deviation of Y?', '[]', '2', '(16+16+16+16)/4/4-(4+4+4+4)/4/2', 'In X, every value is 4 away from the mean, so every squared distance is 16, the variance is 16 and the standard deviation is 4. In Y, every value is 2 away, so every squared distance is 4, the variance is 4 and the standard deviation is 2. The difference is $4 - 2 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: every value is 4 from 10, so SD = 4. Y: every value is 2 from 10, so SD = 2. Difference = 2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d89e636-2b6f-4c12-91ca-4b223bf528e1', 'NC26.8.RD.4', 3, 'numeric', 'Use the mean and standard deviation to compare two scores', 'On a test, the mean score is 70 and the standard deviation is 5. Mia''s score is 2 standard deviations above the mean. Leo''s score is 1.5 standard deviations below the mean. How many points higher is Mia''s score than Leo''s score?', '[]', '17.5', '(70+2*5)-(70-1.5*5)', 'Mia''s score is $70 + 2 \times 5 = 80$. Leo''s score is $70 - 1.5 \times 5 = 62.5$. The difference is $80 - 62.5 = 17.5$ points.', 'checked', '{"lint":[],"solve":{"answer":"17.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia = 70 + 2(5) = 80. Leo = 70 - 1.5(5) = 62.5. Difference = 17.5 (= 3.5 * 5).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70d82f6d-b628-434f-b766-0a2f3cd97145', 'NC26.8.RD.4', 3, 'choice', 'Choose a measure of spread when there are outliers', 'A data set has a few extremely large values that are far from the rest of the data. Which measure of spread is least affected by those extreme values?', '["The range","The variance","The interquartile range","The standard deviation"]', 'The interquartile range', NULL, 'The range, the variance and the standard deviation all use the extreme values, so a few very large values change them a lot. The interquartile range uses only the middle half of the data, so it is hardly affected.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The IQR uses only the middle 50% of the data, so extreme values barely affect it; range, variance and SD all use the extremes.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73a25b3c-4f08-4e88-84f1-d62dc23103cc', 'NC26.8.RD.4', 3, 'numeric', 'Compute a variance', 'Four numbers are 4, 8, 8 and x. Their mean is 7. What is the variance of the four numbers? (The variance is the mean of the squared distances from the mean.)', '[]', '3', '((4-28/4)^2+(8-28/4)^2+(8-28/4)^2+(8-28/4)^2)/4', 'The sum is 4 x 7 = 28, so x = 28 - 4 - 8 - 8 = 8. Distances from 7: -3, 1, 1, 1. Squared: 9, 1, 1, 1. The sum is 12, and 12 / 4 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 28 so x = 28 - 20 = 8. Values 4,8,8,8; deviations -3,1,1,1; squares 9,1,1,1 = 12; 12/4 = 3.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4df7f3b6-4cd5-4164-a361-f9417d440ba4', 'NC26.8.RD.4', 3, 'choice', 'Compute a variance', 'Five weekly savings amounts were 2, 3, 5, 8 and 12 dollars. What is the variance of the amounts? (The variance is the mean of the squared distances from the mean.)', '["66","16.5","3.6","13.2"]', '13.2', '((2-30/5)^2+(3-30/5)^2+(5-30/5)^2+(8-30/5)^2+(12-30/5)^2)/5', 'The mean is 30 / 5 = 6. Distances: -4, -3, -1, 2, 6. Squared: 16, 9, 1, 4, 36. The sum is 66, and 66 / 5 = 13.2.', 'checked', '{"lint":[],"solve":{"answer":"13.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 30/5 = 6; deviations -4,-3,-1,2,6; squares 16,9,1,4,36 = 66; 66/5 = 13.2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('486e60ff-93d2-4ae9-a8e8-f2b7d758a469', 'NC26.8.RD.4', 3, 'numeric', 'Compute a variance', 'In a survey, 3 students read 2 books, 4 students read 5 books and 3 students read 8 books. What is the variance of the number of books read by the 10 students? (The variance is the mean of the squared distances from the mean.)', '[]', '5.4', '(3*(2-5)^2+4*(5-5)^2+3*(8-5)^2)/10', 'The mean is (3 x 2 + 4 x 5 + 3 x 8) / 10 = 50 / 10 = 5. Squared distances: 9 for each of the three 2s, 0 for the 5s, 9 for each of the three 8s. The sum is 54, and 54 / 10 = 5.4.', 'checked', '{"lint":[],"solve":{"answer":"5.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean (6+20+24)/10 = 5; squared distances 3*9 + 4*0 + 3*9 = 54; 54/10 = 5.4.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5d69e33-8291-4825-8641-ec70ff2d16da', 'NC26.8.RD.4', 3, 'numeric', 'Compute a standard deviation', 'Four metal rods measure 16, 28, 32 and 44 centimeters. Find the standard deviation of their lengths, in centimeters. (The standard deviation is the square root of the variance, which is the mean of the squared distances from the mean.)', '[]', '10', '10', 'The mean is 120 / 4 = 30. Distances: -14, -2, 2, 14. Squared: 196, 4, 4, 196. The sum is 400, and 400 / 4 = 100. The square root of 100 is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 120/4 = 30; deviations -14,-2,2,14; squares 196,4,4,196 = 400; variance 100; SD 10.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1dbda19-3c4d-4d26-8c27-08210a2e2067', 'NC26.8.RD.4', 3, 'numeric', 'Compute a standard deviation', 'A club''s seven members are 11, 12, 13, 14, 15, 16 and 17 years old. What is the standard deviation of their ages, in years? (The standard deviation is the square root of the variance, which is the mean of the squared distances from the mean.)', '[]', '2', '2', 'The mean is 14. Distances: -3, -2, -1, 0, 1, 2, 3. Squared: 9, 4, 1, 0, 1, 4, 9. The sum is 28, and 28 / 7 = 4. The square root of 4 is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 14; squares 9,4,1,0,1,4,9 = 28; 28/7 = 4; SD 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
