INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9781e37f-d4be-44c2-8e04-c901298a5976', 'NC26.8.RD.4', 3, 'numeric', 'Compute a standard deviation', 'The overnight low temperatures on four nights were -7, -1, 1 and 7 degrees. What is the standard deviation of these temperatures, in degrees? (The standard deviation is the square root of the variance, which is the mean of the squared distances from the mean.)', '[]', '5', '5', 'The mean is 0. Squared distances: 49, 1, 1, 49. The sum is 100, and 100 / 4 = 25. The standard deviation is the square root of 25, which is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 0; squares 49,1,1,49 = 100; variance 25; SD 5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
