INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a669f160-89c4-4918-bba5-4c02751ad1bc', 'NC26.8.RD.4', 3, 'numeric', 'Relate variance and standard deviation', 'A data set has a variance of 0.49. What is its standard deviation?', '[]', '0.7', '0.7', 'The standard deviation is the square root of the variance. Since 0.7 x 0.7 = 0.49, the standard deviation is 0.7.', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(0.49) = 0.7.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
