INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93a3b7c5-34fb-4af4-9031-b1ab3079c7f2', 'NC26.8.RD.4', 3, 'choice', 'Choose a measure of spread', 'A data set has a range of 80, an IQR of 6 and a standard deviation of 25, because of one extreme value. Which measure best describes how much the typical values vary?', '["The range of 80","The standard deviation of 25","The IQR of 6","The mean of the values"]', 'The IQR of 6', NULL, 'The range and standard deviation are inflated by the extreme value. The IQR uses only the middle half of the data, so it reflects the typical variation.', 'checked', '{"lint":[],"solve":{"answer":"The IQR of 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One extreme value inflates range and SD; IQR of 6 describes typical variation. The mean is not a spread measure.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b58e0d1a-4cee-4931-b94e-7ec2e97adb05', 'NC26.8.RD.4', 3, 'choice', 'Interpret standard deviation in context', 'Mia scored 82 on a test with a mean of 70 and a standard deviation of 6. Leo scored 90 on a different test with a mean of 80 and a standard deviation of 10. Who did better compared with their own test takers?', '["Leo, because his score of 90 is the higher of the two scores","Mia and Leo did equally well, since both scored above their means","Mia, who is 2 standard deviations above her mean while Leo is 1","Leo, because his test has the larger standard deviation"]', 'Mia, who is 2 standard deviations above her mean while Leo is 1', NULL, 'Mia is 12 / 6 = 2 standard deviations above her mean. Leo is 10 / 10 = 1 standard deviation above his. Mia did better relative to her group.', 'checked', '{"lint":[],"solve":{"answer":"Mia, who is 2 standard deviations above her mean while Leo is 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia (82-70)/6 = 2; Leo (90-80)/10 = 1. Mia did better relatively.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34306139-6839-47f3-9614-eb26beea5292', 'NC26.8.RD.4', 3, 'numeric', 'Interpret standard deviation in context', 'The scores on a test have a mean of 85 and a standard deviation of 7.5. What score is 2 standard deviations below the mean?', '[]', '70', '85-2*7.5', '2 standard deviations is 2 x 7.5 = 15 points. Below the mean: 85 - 15 = 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"85 - 2*7.5 = 70.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2d1b39d-c804-4820-8622-468d7593ef3f', 'NC26.8.RD.4', 3, 'numeric', 'Interpret standard deviation in context', 'Weights of packages have a mean of 60 kilograms and a standard deviation of 12 kilograms. What is the smallest weight that is within 2 standard deviations of the mean, in kilograms?', '[]', '36', '60-2*12', '2 standard deviations is 2 x 12 = 24 kilograms. The smallest weight within that distance of the mean is 60 - 24 = 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 - 2*12 = 36 (inclusive boundary).","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fb7a87b-d364-406a-ad8f-9b075cb7eca7', 'NC26.8.RD.4', 3, 'choice', 'Compare distributions by centre and spread', 'Baker P sold 12, 12, 20 and 20 loaves on four days. Baker Q sold 15, 15, 17 and 17 loaves. Which statement is true?', '["Both have a mean of 16, and P has the greater standard deviation, 4 against 1","Both have a mean of 16, and Q has the greater standard deviation, 4 against 1","Q has the greater mean, and P has the greater standard deviation","P has the greater mean, but they have the same standard deviation"]', 'Both have a mean of 16, and P has the greater standard deviation, 4 against 1', NULL, 'Both sets total 64, so both means are 16. P''s values are 4 from the mean (standard deviation 4). Q''s are 1 from the mean (standard deviation 1).', 'checked', '{"lint":[],"solve":{"answer":"Both have a mean of 16, and P has the greater standard deviation, 4 against 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: mean 64/4 = 16, deviations +-4, SD 4. Q: mean 64/4 = 16, deviations +-1, SD 1.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f9ca727-bc55-4413-9e0a-c32a38687f6f', 'NC26.8.RD.4', 3, 'numeric', 'Compare distributions by centre and spread', 'Hannah ran a mile in 12 minutes in a group with a mean of 9 minutes and a standard deviation of 1 minute. Eli ran in 14 minutes in a group with a mean of 11 minutes and a standard deviation of 3 minutes. How many more standard deviations above its group''s mean is Hannah''s time than Eli''s?', '[]', '2', '3/1-3/3', 'Hannah is 3 minutes above her mean, which is 3 / 1 = 3 standard deviations. Eli is 3 minutes above his, which is 3 / 3 = 1 standard deviation. The difference is 3 - 1 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hannah (12-9)/1 = 3; Eli (14-11)/3 = 1; difference 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e870b5b7-41c2-42ce-b7fe-af52d44f2101', 'NC26.8.RD.4', 3, 'numeric', 'Compare distributions by centre and spread', 'Two lists both have a mean of 10. List A is 7, 9, 10, 11, 13 and list B is 4, 8, 10, 12, 16. The standard deviation of B is how many times the standard deviation of A?', '[]', '2', '4/2', 'List A: squared distances 9, 1, 0, 1, 9, so the variance is 20 / 5 = 4 and the standard deviation is 2. List B: squared distances 36, 4, 0, 4, 36, so the variance is 80 / 5 = 16 and the standard deviation is 4. The ratio is 4 / 2 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A deviations -3,-1,0,1,3, squares sum 20. B deviations -6,-2,0,2,6 = 2x A''s, squares sum 80. SD ratio sqrt(80/20) = 2.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbd6a807-f11d-40e0-931f-e0ec8e392262', 'NC26.8.RD.4', 3, 'choice', 'Use technology output for spread', 'A calculator shows a mean of 52 and a standard deviation of 4.5 for a list of numbers. The same list is entered again with 3 added to every value. What will the calculator show?', '["Mean 55 and standard deviation 7.5","Mean 52 and standard deviation 4.5","Mean 52 and standard deviation 7.5","Mean 55 and standard deviation 4.5"]', 'Mean 55 and standard deviation 4.5', NULL, 'Adding 3 to every value moves the mean up by 3, to 55, and leaves the spread, so the standard deviation, at 4.5.', 'checked', '{"lint":[],"solve":{"answer":"Mean 55 and standard deviation 4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 3 shifts mean to 55; SD unchanged 4.5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0635bce6-a669-41f0-a556-2305cfd5d978', 'NC26.8.RD.4', 3, 'numeric', 'Use technology output for spread', 'A spreadsheet reports a variance of 20.25 for a set of lengths in centimeters. What is the standard deviation of the lengths, in centimeters?', '[]', '4.5', '4.5', 'The standard deviation is the square root of the variance. Since 4.5 x 4.5 = 20.25, it is 4.5.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(20.25) = 4.5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d14c186-36cb-4299-96ae-cb6751b6a982', 'NC26.8.RD.4', 3, 'choice', 'Compare spread without computing', 'Set A is 2, 10 and set B is 2, 6, 10. (The standard deviation is the square root of the mean of the squared distances from the mean: divide by the number of values.) Which statement about the two standard deviations is true?', '["They are equal, since both sets have the same mean, which is 6","Set B''s is greater, since set B has one more value than set A","They are equal, since both sets have the same range, which is 8","Set A''s is greater, since set B''s new value is at the mean"]', 'Set A''s is greater, since set B''s new value is at the mean', NULL, 'Both sets have a mean of 6. Set A: squared distances are 16 and 16, mean 16, standard deviation 4. Set B: squared distances are 16, 0 and 16, mean 32/3 (about 10.7), standard deviation about 3.3. The extra value 6 sits exactly at the mean, so it adds no spread but counts in the average, pulling the standard deviation down. Set A''s is greater. Having the same mean or the same range does not make the standard deviations equal.', 'checked', '{"lint":[],"solve":{"answer":"Set A''s is greater, since set B''s new value is at the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: mean 6, squared distances 16,16, variance 16, SD 4. B: mean 6, squared distances 16,0,16, variance 32/3 ~ 10.67, SD ~ 3.27. A''s SD is greater; adding a value at the mean lowers the spread. Options 1 and 3 claim equal (false), option 2 claims B greater (false).","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('200cc912-1a67-4e3f-b8a2-bb9c919f275f', 'NC26.8.RD.5', 1, 'numeric', 'Compare the means of several populations', 'The mean test scores of students at three schools are 72 for School A, 78 for School B and 75 for School C. How many points higher is the greatest mean than the least mean?', '[]', '6', '78-72', 'The greatest mean is 78 (School B) and the least is 72 (School A). $78 - 72 = 6$ points.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 78 - least 72 = 6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68be8afd-ce4c-4f84-a27e-1f924fc957e1', 'NC26.8.RD.5', 1, 'choice', 'Draw a conclusion supported by group means', 'A survey finds the mean number of minutes students exercise each day. Class 1 has a mean of 25, Class 2 has a mean of 40 and Class 3 has a mean of 32. Which statement is supported by these means?', '["On average, Class 2 students exercise more than Class 1 students","Every student in Class 2 exercises more than every student in Class 1","On average, Class 3 students exercise more than Class 2 students","Class 1 students vary the most in how long they exercise"]', 'On average, Class 2 students exercise more than Class 1 students', NULL, 'Class 2''s mean (40) is greater than Class 1''s mean (25), so on average Class 2 students exercise more. Means say nothing about every individual student or about how much the students vary.', 'checked', '{"lint":[],"solve":{"answer":"On average, Class 2 students exercise more than Class 1 students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 mean 40 > Class 1 mean 25, so on average Class 2 exercises more. Means say nothing about variability or every individual.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f427040-ef4c-4dcc-8904-247344396ddc', 'NC26.8.RD.5', 1, 'numeric', 'Mean of three equal-sized groups', 'Three groups of 10 students each took a typing test. The mean scores, in words per minute, were 70 for Group A, 80 for Group B and 90 for Group C. What is the mean score of all 30 students?', '[]', '80', '(70+80+90)/3', 'The groups are the same size, so the overall mean is the mean of the three group means: $\frac{70+80+90}{3} = \frac{240}{3} = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal group sizes: (10*70 + 10*80 + 10*90)/30 = 2400/30 = 80.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31f3a912-fee7-48e7-8330-bb938ffe8345', 'NC26.8.RD.5', 1, 'choice', 'Compare the means of several populations', 'Four clubs recorded how many books each member read last month. The means were 4 books for the Chess Club, 7 for the Art Club, 5 for the Drama Club and 3 for the Robotics Club. Which club had the greatest mean?', '["Chess Club","Art Club","Drama Club","Robotics Club"]', 'Art Club', NULL, 'Compare the four means: 4, 7, 5 and 3. The greatest is 7, which belongs to the Art Club.', 'checked', '{"lint":[],"solve":{"answer":"Art Club","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means: Chess 4, Art 7, Drama 5, Robotics 3. Greatest is 7, the Art Club.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
