INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35d8b364-df22-4cbb-a7f7-e6af9dc852a9', 'NC26.8.RD.5', 1, 'numeric', 'Compare the means of several populations', 'The mean heights of sunflowers grown in Garden 1, Garden 2 and Garden 3 are $150$ cm, $162$ cm and $171$ cm. The mean height in Garden 3 is how many centimeters greater than the mean height in Garden 1?', '[]', '21', '171-150', 'Subtract the two means: $171 - 150 = 21$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"171 - 150 = 21 cm.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
