INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67e75d72-0ab3-47e7-8d94-eed6d640e551', 'NC26.8.RD.5', 1, 'numeric', 'Compare the spread of several populations', 'Two bakeries counted the loaves sold on five days. Bakery A: 40, 55, 48, 52, 45. Bakery B: 30, 70, 50, 62, 38. How much greater is the range for Bakery B than the range for Bakery A?', '[]', '25', '(70-30)-(55-40)', 'Bakery A: $55 - 40 = 15$. Bakery B: $70 - 30 = 40$. The difference is $40 - 15 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 55 - 40 = 15. B: 70 - 30 = 40. 40 - 15 = 25.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2a93cc6-73c6-4db3-99d3-eb90a7e9874a', 'NC26.8.RD.5', 1, 'numeric', 'Compare percents when group sizes differ', 'In a class of 20 students, 15 walk to school. What percent of the class walks to school?', '[]', '75', '15/20*100', '$15 \div 20 = 0.75$, which is 75 percent.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 / 20 = 0.75 = 75%.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a527f0b3-c552-4320-b2e8-429dc1d9bd1c', 'NC26.8.RD.5', 1, 'choice', 'Compare percents when group sizes differ', 'Three classes were asked whether they have a pet. In Class A, 8 of 10 students said yes. In Class B, 15 of 20 said yes. In Class C, 30 of 50 said yes. Which class had the greatest percent of students who said yes?', '["Class A","Class B","Class C","All three classes had the same percent"]', 'Class A', NULL, 'Class A: $8 \div 10 = 80\%$. Class B: $15 \div 20 = 75\%$. Class C: $30 \div 50 = 60\%$. Class C has the most "yes" answers, 30, but Class A has the greatest percent.', 'checked', '{"lint":[],"solve":{"answer":"Class A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 8/10 = 80%, B 15/20 = 75%, C 30/50 = 60%. A is greatest.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9e4797f-9d9e-414b-9338-b21f2d67d968', 'NC26.8.RD.5', 1, 'numeric', 'Compare percents when group sizes differ', 'In a survey of 200 people, 35 percent said they prefer tea to coffee. How many of the 200 people prefer tea?', '[]', '70', '0.35*200', '35 percent of 200 is $0.35 \times 200 = 70$ people.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.35 x 200 = 70.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4888be43-be09-41c0-8198-8ba90681ada6', 'NC26.8.RD.5', 1, 'choice', 'Choose and justify a measure of center', 'Five quiz scores are 70, 72, 74, 76 and 78, so the mean and the median are both 74. A sixth score of 100 is added. Which statement is true about the new mean and median?', '["The new median is greater than the new mean.","The new mean and the new median are both still 74.","The new mean and the new median are equal.","The new mean is greater than the new median."]', 'The new mean is greater than the new median.', NULL, 'New mean: $(370 + 100) \div 6 \approx 78.3$. New median: the middle two of 70, 72, 74, 76, 78, 100 are 74 and 76, so the median is 75. The very high score pulls the mean up more than the median.', 'checked', '{"lint":[],"solve":{"answer":"The new mean is greater than the new median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New set 70, 72, 74, 76, 78, 100: sum 470, mean about 78.3; median (74 + 76) / 2 = 75. Mean > median.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6551b2f-dd08-46a6-8f45-14b71fa605ea', 'NC26.8.RD.5', 1, 'numeric', 'Choose and justify a measure of center', 'A list of values is 2, 4, 6, 8 and 20. How much greater is the mean of the list than its median?', '[]', '2', '(2+4+6+8+20)/5-6', 'The mean is $(2 + 4 + 6 + 8 + 20) \div 5 = 40 \div 5 = 8$. The median is the middle value, 6. The difference is $8 - 6 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 40 / 5 = 8. Median 6. 8 - 6 = 2.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12d84c27-7d39-463d-b455-2063b0835fb9', 'NC26.8.RD.5', 1, 'numeric', 'Choose and justify a measure of center', 'Five workers'' hourly pay rates, in dollars, are 10, 12, 14, 16 and 18. The greatest rate changes from 18 to 60. What is the median of the five new rates, in dollars?', '[]', '14', '14', 'The new rates in order are 10, 12, 14, 16, 60. The middle one is 14. The median did not change when the greatest value changed, because only the middle position matters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New rates 10, 12, 14, 16, 60: median still 14.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32ac76b4-f610-49bd-96aa-23f629ed7425', 'NC26.8.RD.5', 1, 'choice', 'Draw conclusions and recommend a plan from the data', 'A school compares three tutoring programs by the mean improvement in test score: Program A 6 points, Program B 9 points and Program C 4 points. The school can pay for only one. Which recommendation is best supported by these results?', '["Choose Program A, because it was listed first.","Choose Program C, because it had the least improvement and so is the best value.","Choose Program B, because its students improved the most on average.","Choose no program, because the means are different."]', 'Choose Program B, because its students improved the most on average.', NULL, 'The goal is improvement, and Program B has the greatest mean improvement, 9 points. Order of listing and a smaller improvement are not reasons to choose a program.', 'checked', '{"lint":[],"solve":{"answer":"Choose Program B, because its students improved the most on average.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Program B had the greatest mean improvement (9); the other reasons are irrelevant or illogical.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ab25e01-9e11-4485-8afe-3e8a25e0fb17', 'NC26.8.RD.5', 1, 'choice', 'Draw conclusions and recommend a plan from the data', 'The mean trip time was 20 minutes on Route A and 14 minutes on Route C. Which reason for recommending Route C over Route A is supported by these data?', '["It has more stops along the way.","It was built more recently.","It is listed after Route A.","Its mean trip time is 6 minutes shorter."]', 'Its mean trip time is 6 minutes shorter.', NULL, 'Only the trip times are given: $20 - 14 = 6$ minutes shorter on Route C. Nothing in the data says anything about stops, the year it was built or the order of a list.', 'checked', '{"lint":[],"solve":{"answer":"Its mean trip time is 6 minutes shorter.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 - 14 = 6 minutes shorter on average; the other reasons are not in the data.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('452befa9-2606-4f9c-ba6c-850a70cd95d3', 'NC26.8.RD.5', 1, 'numeric', 'Draw conclusions and recommend a plan from the data', 'A school compares three study programs. The mean gain in test score was 8 points for Program A, 11 points for Program B and 5 points for Program C. If 40 students join the program with the greatest mean gain, how many points in total would the school expect them to gain altogether?', '[]', '440', '40*11', 'Program B has the greatest mean gain, 11 points. For 40 students the expected total is $40 \times 11 = 440$ points.', 'checked', '{"lint":[],"solve":{"answer":"440","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest mean gain is Program B, 11 points. 40 x 11 = 440.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7daf7d54-35fa-48b2-a238-3758ce0f67ad', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'A student wants to compare how many hours students at her school sleep. Which sample is most likely to represent all the students at the school?', '["10 students chosen at random from a list of every student","The first 10 students in the lunch line","The 10 members of the chess club","The 10 friends of the person doing the survey"]', '10 students chosen at random from a list of every student', NULL, 'A random sample from the whole school gives every student the same chance to be chosen. The other groups are chosen by something that may be linked to how much they sleep.', 'checked', '{"lint":[],"solve":{"answer":"10 students chosen at random from a list of every student","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from a list of every student is the representative one; the others are convenience or self-similar groups.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('baca44b5-1410-46c3-a227-cdeef28837fa', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'Which survey question is the fairest way to find out how many hours students sleep?', '["Don''t you agree that students should sleep 9 hours?","Students who sleep too little fail tests. How many hours do you sleep?","How many hours did you sleep last night?","Do you like to sleep a lot?"]', 'How many hours did you sleep last night?', NULL, 'A fair question does not push people toward an answer and asks for the number you want to know. The first question asks for hours directly. The others lead the answer or ask for something else.', 'checked', '{"lint":[],"solve":{"answer":"How many hours did you sleep last night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The neutral, specific question is \"How many hours did you sleep last night?\"; the others are leading or vague.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29557680-aabe-4a21-b419-a81acbab52da', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'Why is it better to survey 100 randomly chosen students than 5 randomly chosen students?', '["A larger sample always gives the same results as a smaller sample.","A larger sample lets the surveyor choose which students to include.","A larger sample removes the need to ask a fair question.","A larger random sample is more likely to be close to the whole population."]', 'A larger random sample is more likely to be close to the whole population.', NULL, 'With more randomly chosen students, one unusual student has less effect, so the results are more likely to be close to what the whole population would say. A bigger sample does not make the results identical, and it does not fix unfair questions or biased selection.', 'checked', '{"lint":[],"solve":{"answer":"A larger random sample is more likely to be close to the whole population.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A larger random sample tends to give results closer to the population.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('647221ba-e992-4615-9995-61cc67607f59', 'NC26.8.RD.5', 1, 'numeric', 'Summarize a distribution with its five-number summary', 'The five-number summary of a set of test scores is: least 4, Q1 9, median 13, Q3 18, greatest 26. What is the range of the scores?', '[]', '22', '26-4', 'The range is the greatest value minus the least value: $26 - 4 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26 - 4 = 22.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7ad9710-bfa7-4a56-b32d-16e934521a28', 'NC26.8.RD.5', 1, 'numeric', 'Summarize a distribution with its five-number summary', 'The five-number summary of the time (in minutes) that students spend on homework is: least 10, Q1 25, median 40, Q3 55, greatest 90. What is the interquartile range?', '[]', '30', '55-25', 'The interquartile range is Q3 minus Q1: $55 - 25 = 30$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q3 - Q1 = 55 - 25 = 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
