INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a150b504-7c29-4003-a8b5-3ba6fd4fa158', 'NC26.M1.RMM.1', 1, 'choice', 'Name quantities and variables', 'A scooter rental costs 6 dollars to start plus 2 dollars per mile. Which quantity depends on how many miles are ridden?', '["The 6 dollar starting fee","The total cost of the rental","The 2 dollar price per mile","The color of the scooter"]', 'The total cost of the rental', NULL, 'The starting fee and the price per mile are fixed. The total cost changes with the number of miles, so it depends on the miles ridden.', 'checked', '{"lint":[],"solve":{"answer":"The total cost of the rental","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 6 + 2(miles) depends on miles; fees are constants.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
