INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cf42852-46d4-4cee-b0e5-9ba6f4dccdeb', 'NC26.M1.RMM.1', 1, 'choice', 'Identify the assumptions of a model', 'A model says a puppy gains exactly 2 pounds every week. Which assumption is built into this model?', '["The puppy''s weight doubles every week","The puppy weighs 2 pounds at the moment it is born","The puppy stops gaining after 2 weeks","The puppy gains the same amount each week"]', 'The puppy gains the same amount each week', NULL, '"Exactly 2 pounds every week" means a constant weekly gain. That is the assumption of the model.', 'checked', '{"lint":[],"solve":{"answer":"The puppy gains the same amount each week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Constant gain of 2 lb/week assumes equal weekly gain (linear).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
