INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ece4725c-2079-4a02-b7a2-deae611b600c', 'NC26.M1.RMM.1', 1, 'choice', 'Identify the assumptions of a model', 'Sam finds the cost of 3 notebooks priced at 2 dollars each by calculating $3 \times 2$. What is he assuming?', '["Every notebook costs the same price","Notebooks get cheaper when more are bought","A sales tax is added to the total","He plans to buy more than 3 notebooks later"]', 'Every notebook costs the same price', NULL, 'Multiplying the number of notebooks by one price only works if every notebook costs that same price.', 'checked', '{"lint":[],"solve":{"answer":"Every notebook costs the same price","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 2 assumes each notebook costs 2 dollars, same price.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
