INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d64ba3d2-1443-497f-a638-ed53ff0450ab', 'NC26.M1.RMM.1', 1, 'choice', 'Build a model from a situation or data', 'A video is seen by 3 people on day 0, and the number of viewers doubles every day. Which equation gives the number of viewers $V$ after $d$ days?', '["$V = 3 \\times 2^d$","$V = 2 \\times 3^d$","$V = 3 + 2d$","$V = 6d$"]', '$V = 3 \times 2^d$', NULL, 'Starting at 3 and doubling each day means multiplying by 2 a total of $d$ times: $3 \times 2^d$.', 'checked', '{"lint":[],"solve":{"answer":"$V = 3 \\times 2^d$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Starts at 3, doubles daily: V = 3 x 2^d. Check d=0: 3.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c9e9db8-7382-4f50-8f34-c370ba464090', 'NC26.M1.RMM.1', 1, 'numeric', 'Build a model from a situation or data', 'A pool holds 90 gallons and drains at a steady rate of 6 gallons per minute. The model is $G = 90 - mt$, where $t$ is the time in minutes. What is the value of $m$?', '[]', '6', '6', 'The rate of draining is 6 gallons each minute, so $m = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drains 6 gal/min, G = 90 - 6t, so m = 6.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f89ba9d-d54c-4204-b37c-3b19675138c1', 'NC26.M1.RMM.1', 1, 'numeric', 'Build a model from a situation or data', 'A population is 4, 8, 16 and 32 at times $x = 0, 1, 2, 3$. The model $y = 4b^x$ fits these values. What is $b$?', '[]', '2', '8/4', 'Each value is double the one before, so the growth factor is $b = 2$. Check: $4 \times 2^3 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 8/4 = 2, y = 4(2)^x fits all.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37e2082a-6dc0-4907-a326-7952fe341525', 'NC26.M1.RMM.1', 1, 'numeric', 'Analyse a model to predict or solve', 'A rain barrel holds 90 liters and loses 5 liters each day. The model $L = 90 - 5d$ gives the liters left after $d$ days. How many liters are left after 7 days?', '[]', '55', '90-5*7', 'Put $d = 7$: $90 - 5 \times 7 = 90 - 35 = 55$.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 90 - 5(7) = 90 - 35 = 55.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d1dca0e-6519-44c6-ad91-a7771478d0f3', 'NC26.M1.RMM.1', 1, 'numeric', 'Analyse a model to predict or solve', 'The model $P = 25 + 10w$ gives the points $P$ a player has after $w$ weeks of a reading challenge. After how many weeks does the model say a player reaches 125 points?', '[]', '10', '(125-25)/10', 'Solve $25 + 10w = 125$. Subtract 25 to get $10w = 100$, so $w = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + 10w = 125 -> 10w = 100 -> w = 10.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b317e25-789c-4fc5-8920-6b9d451ac0dd', 'NC26.M1.RMM.1', 1, 'numeric', 'Analyse a model to predict or solve', 'Use $V = 3 \times 2^d$, the model for the viewers of a video after $d$ days. How many viewers does it predict after 4 days?', '[]', '48', '3*2^4', 'Put $d = 4$: $3 \times 2^4 = 3 \times 16 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 2^4 = 3 x 16 = 48.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
