INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da346e99-1ab2-469a-9d68-ea56d66d190c', 'NC26.M1.RMM.1', 1, 'numeric', 'Analyse a model to predict or solve', 'The model $W = 40t$ gives the words $W$ typed after $t$ minutes. How many minutes does the model say it takes to type 360 words?', '[]', '9', '360/40', 'Solve $40t = 360$. Divide by 40: $t = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40t = 360 -> t = 9.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
