INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6207f0a9-013b-4959-a7e1-bbf4e24b9e8b', 'NC26.M1.RMM.1', 1, 'numeric', 'Analyse a model to predict or solve', 'The model $y = 3x + 2$ gives the dollars $y$ paid for $x$ sandwiches at 3 dollars each plus a 2 dollar bag fee. How many dollars does the model give for 9 sandwiches?', '[]', '29', '3*9+2', 'Put $x = 9$: $3 \times 9 + 2 = 27 + 2 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(9) + 2 = 29.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
