INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd68dabd-04f1-497d-b355-08047b2cad0a', 'NC26.M1.RMM.1', 1, 'numeric', 'Test a conjecture or model against data', 'A model predicts that a bus ride will take 45 minutes. A student times the ride and gets 52 minutes. By how many minutes does the model miss?', '[]', '7', '52-45', 'Compare the prediction with the measurement: $52 - 45 = 7$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 - 45 = 7.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
