INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58b97b50-fb08-4327-ade6-8f8da1fa2e69', 'NC26.M1.RMM.1', 1, 'choice', 'Test a conjecture or model against data', 'A student has a conjecture that a bean plant grows about 3 centimeters each week. Which is the best way to test it?', '["Measure the plant once after one day and decide that is enough","Ask several friends whether the plant looks like it has grown","Measure only the tallest bean plant that can be found in a store","Measure the plant every week for several weeks and compare with 3 each week"]', 'Measure the plant every week for several weeks and compare with 3 each week', NULL, 'A conjecture about weekly growth is tested by measuring over several weeks and comparing with the claimed growth.', 'checked', '{"lint":[],"solve":{"answer":"Measure the plant every week for several weeks and compare with 3 each week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Repeated weekly measurements compared with 3 cm/week test the conjecture.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
