INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f81a802-0380-42ee-ba06-0d3d3ff4ab06', 'NC26.M1.RMM.1', 1, 'choice', 'Test a conjecture or model against data', 'A model predicts 30 and the measured value is 31. What does this suggest?', '["The model must be thrown away","The model fits well at this point","The new measurement should simply be ignored","The model''s value was too high"]', 'The model fits well at this point', NULL, 'The prediction and the measurement differ by only 1, so the model fits well here. The model predicted slightly too low, not too high.', 'checked', '{"lint":[],"solve":{"answer":"The model fits well at this point","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 vs 31, off by 1: close fit. Model was too low, not too high.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
