INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0f7a8ab-2c67-487c-aed1-e774a1c085c9', 'NC26.M1.RMM.1', 1, 'choice', 'Revise a model', 'A student has revised her model after it missed the data. What should she do next?', '["Stop, because a revised model is always correct now","Delete the measurements that disagree with the model","Change the question the model was built to answer","Test the revised model against the data again"]', 'Test the revised model against the data again', NULL, 'A revised model must be tested again, since the revision might not have fixed the problem.', 'checked', '{"lint":[],"solve":{"answer":"Test the revised model against the data again","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After revising, test again (cycle).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebedbc30-7aad-45e1-99c8-df9f905f4706', 'NC26.M1.RMM.1', 1, 'numeric', 'Explain what a model''s parts mean', 'In the model $T = 8 + 5h$, $T$ is the dollars a tutor charges for $h$ hours. How many dollars does each extra hour add to the charge?', '[]', '5', '5', 'The number multiplying $h$ is the amount added for each hour. It is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 5 dollars per hour.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f75be990-39d9-4a2e-945e-64081258681f', 'NC26.M1.RMM.1', 1, 'numeric', 'Explain what a model''s parts mean', 'In the model $N = 5 \times 3^t$, $N$ is the number of bacteria after $t$ hours. How many bacteria does the model say there are at the start, when $t = 0$?', '[]', '5', '5*3^0', 'Put $t = 0$: $5 \times 3^0 = 5 \times 1 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 3^0 = 5.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdca6c57-26ed-40a1-a99f-a91916e93447', 'NC26.M1.RMM.1', 1, 'choice', 'Critique a model and its limits', 'A model for a sale says $N = 100 - 20d$ items are left after $d$ days. On day 8 it gives $-60$. What does this show?', '["The model does not make sense for that many days","The store sold 60 items on day 8","The store owes its customers 60 items","The sale lasted exactly 8 days"]', 'The model does not make sense for that many days', NULL, 'A store cannot have a negative number of items. The stock runs out at day 5, so the model only applies up to then.', 'checked', '{"lint":[],"solve":{"answer":"The model does not make sense for that many days","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 160 = -60 items is impossible; model domain exceeded (stock runs out at d = 5).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b75ef40-4ed0-4ca9-b032-c5f499afa423', 'NC26.M1.RMM.1', 1, 'numeric', 'Critique a model and its limits', 'A model says 7.5 buses are needed for a field trip. What is the fewest buses the school can order so that everyone can go?', '[]', '8', '8', 'You cannot order half a bus, and 7 buses would be too few. Round up to 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.5 buses -> round up to 8.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05edecb1-7dbd-4862-872b-6542b614e545', 'NC26.M1.RMM.1', 1, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 5, 7, 9, 11. Which model fits all four values?', '["$y = 5 \\times 2^x$","$y = 5x + 2$","$y = 5 + 2x$","$y = 7x - 2$"]', '$y = 5 + 2x$', NULL, 'The value goes up by 2 each time, starting at 5, so $y = 5 + 2x$. Check $x = 3$: $5 + 6 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5 + 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5, +2 each step: y = 5 + 2x. Check 5x+2: 2 at x=0 no; 7x-2: -2 no; 5*2^x: 5,10 no.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af2dd1d1-c6bd-4509-a4f3-7974e97d09a6', 'NC26.M1.RMM.1', 1, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 81, 27, 9, 3. Which model fits all four values?', '["$y = 81 - 27x$","$y = 81 - 26x$","$y = 81\\left(\\frac{1}{3}\\right)^x$","$y = 81 \\times 3^x$"]', '$y = 81\left(\frac{1}{3}\right)^x$', NULL, 'Each value is one third of the one before, starting at 81. Check $x = 3$: $81 \times \frac{1}{27} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 81\\left(\\frac{1}{3}\\right)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 1/3: 81(1/3)^x gives 81,27,9,3. 81-26x gives 55 at x=1; 81-27x gives 54 at x=1; 81*3^x grows.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47f30993-78dd-4c65-ac86-68127c03ea80', 'NC26.M1.RMM.1', 1, 'choice', 'Order the steps of the modeling cycle', 'Which list puts these modeling steps in a sensible order? (1) Check predictions against data. (2) Decide what question to answer. (3) Write an equation. (4) Revise the model.', '["2, 3, 1, 4","3, 2, 4, 1","1, 2, 3, 4","2, 1, 3, 4"]', '2, 3, 1, 4', NULL, 'First decide the question (2), then write an equation (3), then check it against data (1), and revise if needed (4).', 'checked', '{"lint":[],"solve":{"answer":"2, 3, 1, 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Question, equation, check, revise: 2,3,1,4.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e910e521-1118-4fa7-ae75-6d3fbe0132f0', 'NC26.M1.RMM.1', 1, 'choice', 'Order the steps of the modeling cycle', 'A student reports her model, her assumptions and her results to the class so they can question it. Which part of modeling is this?', '["Identifying the problem","Choosing the variables","Writing and simplifying the equation","Explaining and defending the model"]', 'Explaining and defending the model', NULL, 'Presenting the model, its assumptions and its results so that others can question it is explaining and defending the model.', 'checked', '{"lint":[],"solve":{"answer":"Explaining and defending the model","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reporting to others for questioning = explaining/defending.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9246e2c0-74bb-444a-9b9d-f79276a32fc6', 'NC26.M1.RMM.1', 2, 'numeric', 'Compare a model prediction with observed data', 'A student models her savings with $S = 40 + 15w$, where $S$ is her savings in dollars after $w$ weeks. After 3 weeks she really has 90 dollars. How many dollars more is her real savings than the model predicts?', '[]', '5', '90-(40+15*3)', 'The model predicts $S = 40 + 15 \times 3 = 85$ dollars. She really has 90 dollars, which is $90 - 85 = 5$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Model: S = 40 + 15(3) = 85. Real 90. 90 - 85 = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc4bcb2b-88b4-42d6-b718-4125b864404b', 'NC26.M1.RMM.1', 2, 'choice', 'Critique a model using measured data', 'A student models a tank that starts with 100 liters and empties at a constant 4 liters per minute: $V = 100 - 4t$. Measurements show 60 liters after 10 minutes and 35 liters after 20 minutes. Which statement is the best critique of the model?', '["The tank empties faster over time, so the rate should be larger","The model matches at 10 minutes, so it is right at every time","The model is wrong because the tank cannot start with 100 liters","The tank empties more slowly over time, so a constant rate is a poor assumption"]', 'The tank empties more slowly over time, so a constant rate is a poor assumption', NULL, 'At 10 minutes the model gives $100 - 40 = 60$ liters, which matches. At 20 minutes it gives $100 - 80 = 20$ liters, but 35 liters were measured. The tank has more water left than predicted, so it empties more slowly as time goes on. Matching at one time does not make a model right everywhere.', 'checked', '{"lint":[],"solve":{"answer":"The tank empties more slowly over time, so a constant rate is a poor assumption","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Model: V(10) = 60 (matches), V(20) = 20 but measured 35. Data: lost 40 L in first 10 min (4 L/min), 25 L in next 10 min (2.5 L/min), so draining slows; constant rate is a poor assumption. Option 1 overgeneralizes, option 3 is unsupported, option 4 has the direction wrong.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a87967fc-fe6d-4d73-8a2a-e31bb4482d62', 'NC26.M1.RMM.1', 2, 'numeric', 'Use a model to answer a question within a limit', 'Printing $n$ flyers costs $C = 12 + 0.25n$ dollars. A club has 62 dollars to spend. What is the greatest number of flyers the club can print?', '[]', '200', '(62-12)/0.25', 'The club can spend at most 62 dollars: $12 + 0.25n \le 62$, so $0.25n \le 50$ and $n \le 200$. The greatest number is 200 flyers.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 0.25n <= 62 -> 0.25n <= 50 -> n <= 200. Check: 12 + 0.25(200) = 62 exactly. Greatest is 200.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d538f21d-fb71-49db-b02a-95a5482e7c9b', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the problem a model should answer', 'A school club needs to raise 500 dollars by selling cookies at 2 dollars each. Which is the best question for a model to answer?', '["Do students enjoy cookies more than they enjoy any other snack?","How many cookies must be sold to reach 500 dollars?","Which flavor of cookie should the club choose to sell at the event?","Is it fair to ask students to buy cookies?"]', 'How many cookies must be sold to reach 500 dollars?', NULL, 'Only the first question can be answered by calculating with the given quantities: $500 \div 2 = 250$ cookies.', 'checked', '{"lint":[],"solve":{"answer":"How many cookies must be sold to reach 500 dollars?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Measurable: 500/2 = 250 cookies.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c28d787a-40e3-4d62-8e93-ef93596cbcee', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the problem a model should answer', 'Which question can be answered using a mathematical model?', '["Is saving money for the future more fun than spending it right away?","How many weeks until saving 15 dollars a week reaches 240 dollars?","Who is the best at saving money among all the students in the class?","Should students be paid an allowance for doing their chores at home?"]', 'How many weeks until saving 15 dollars a week reaches 240 dollars?', NULL, 'A model works with quantities. The first question asks for a number of weeks from a rate of saving and a target; the others are matters of opinion or comparison.', 'checked', '{"lint":[],"solve":{"answer":"How many weeks until saving 15 dollars a week reaches 240 dollars?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only the savings question is quantitative: 240/15 = 16 weeks.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1839d25-e6d6-43eb-b91b-f90498f4417e', 'NC26.M1.RMM.1', 2, 'choice', 'Name quantities and variables', 'Mia is modeling how many weeks she needs to save for a 300 dollar tablet. She saves 20 dollars a week. Which piece of information is not needed for the model?', '["The tablet''s price","Her saving each week","Her savings so far","The color of the tablet"]', 'The color of the tablet', NULL, 'The model needs the price, the weekly saving and the amount saved already. The color has no effect on the number of weeks.', 'checked', '{"lint":[],"solve":{"answer":"The color of the tablet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Color is irrelevant; price, current savings and weekly saving all affect the weeks.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c62e76e7-a563-4b72-9204-5bb3df566746', 'NC26.M1.RMM.1', 2, 'choice', 'Name quantities and variables', 'In a model, $d$ is a distance in miles and $t$ is a time in hours. What does $\frac{d}{t}$ represent?', '["Speed in miles per hour","Time in hours for each mile","Distance in miles","Time in hours"]', 'Speed in miles per hour', NULL, 'Distance divided by time is a rate of travel: miles per hour, or speed.', 'checked', '{"lint":[],"solve":{"answer":"Speed in miles per hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"miles/hours = speed in mph.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30eacbca-0b1d-4a41-86a1-c5d741dead98', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a trip says the time is $t = \frac{d}{50}$ hours for a distance of $d$ miles. Which real-world factor does this model ignore?', '["The total length of the trip in miles, which the model uses","The assumed speed of 50 miles per hour on the whole trip","Traffic and stops that slow the average speed","The units of the distance"]', 'Traffic and stops that slow the average speed', NULL, 'The model assumes a steady 50 miles per hour, so it ignores anything that changes the speed, such as traffic and stops.', 'checked', '{"lint":[],"solve":{"answer":"Traffic and stops that slow the average speed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d/50 assumes constant 50 mph; ignores traffic and stops. Other options are things the model uses.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66b91c1f-f11b-4d14-982d-9e386ae407c1', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a town is $P = 2000(1.05)^t$ people after $t$ years. Which assumption does it make?', '["The population grows by the same number of people each year","The population stops growing altogether after 5 years","The population grows by the same percent each year","The population falls by 5% of its size every single year"]', 'The population grows by the same percent each year', NULL, 'Multiplying by 1.05 each year is growth of 5% of the current population every year, which is a constant percent, not a constant number of people.', 'checked', '{"lint":[],"solve":{"answer":"The population grows by the same percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 1.05 each year: constant percent growth (5%).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f17d736-f1db-4240-bc40-2c0f241b0213', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'Dan models the time to fill a bathtub by assuming the faucet runs at a steady rate. Which event would break this assumption?', '["The water pressure drops while others use water in the house","The tub turns out to hold more water than expected","Dan fills the tub in the evening instead of the morning","Dan measures the water in liters, not gallons"]', 'The water pressure drops while others use water in the house', NULL, 'A change in pressure changes how fast the water flows, so the rate is no longer steady. The other events do not affect the rate.', 'checked', '{"lint":[],"solve":{"answer":"The water pressure drops while others use water in the house","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A pressure drop changes flow rate, breaking the steady-rate assumption.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acbc7010-cede-4184-938e-a3bbefa84859', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A hot tub holds 500 gallons and drains 25 gallons each minute. Which equation gives the gallons $G$ left after $m$ minutes?', '["$G = 25 - 500m$","$G = 500 + 25m$","$G = 475m$","$G = 500 - 25m$"]', '$G = 500 - 25m$', NULL, 'The tub starts at 500 gallons and loses 25 gallons for each of the $m$ minutes, so $G = 500 - 25m$.', 'checked', '{"lint":[],"solve":{"answer":"$G = 500 - 25m$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 500, minus 25 per minute: G = 500 - 25m.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76e89df5-b701-4811-80a7-865f927c68c9', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A savings account starts with 800 dollars and earns 3% interest each year. Which equation gives the balance $A$ after $t$ years?', '["$A = 800 + 0.03t$","$A = 800(1.03)^t$","$A = 800(0.03)^t$","$A = 800 \\times 3^t$"]', '$A = 800(1.03)^t$', NULL, 'Each year the balance is multiplied by 1.03 (100% plus 3%), so after $t$ years it is $800(1.03)^t$.', 'checked', '{"lint":[],"solve":{"answer":"$A = 800(1.03)^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3% growth: factor 1.03: A = 800(1.03)^t.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3440d8af-20c4-441b-bd42-c316977d561d', 'NC26.M1.RMM.1', 2, 'numeric', 'Build a model from a situation or data', 'A seedling is 12 centimeters tall at week 0 and 42 centimeters tall at week 5. If it grows by the same amount each week, how many centimeters does it grow per week?', '[]', '6', '(42-12)/5', 'It grows $42 - 12 = 30$ centimeters in 5 weeks, so $30 \div 5 = 6$ centimeters each week.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(42 - 12)/5 = 30/5 = 6.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60fb0885-6585-4580-b19d-5bf93c62f165', 'NC26.M1.RMM.1', 2, 'numeric', 'Build a model from a situation or data', 'A culture had 80 cells at hour 0, 120 cells at hour 1 and 180 cells at hour 2. The cells grow by the same factor each hour. What is that factor?', '[]', '1.5', '120/80', 'Divide each count by the one before: $120 \div 80 = 1.5$ and $180 \div 120 = 1.5$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120/80 = 1.5, 180/120 = 1.5.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370d7b54-2813-439a-b86d-34458bcbd789', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A farmer has 40 meters of fence for a rectangular pen. If the width is $w$ meters, which equation gives the area $A$ in square meters?', '["$A = w(40 - w)$","$A = w(20 - w)$","$A = 40w$","$A = 20 - w^2$"]', '$A = w(20 - w)$', NULL, 'Two widths and two lengths use 40 meters, so width plus length is 20. The length is $20 - w$, and the area is $w(20 - w)$.', 'checked', '{"lint":[],"solve":{"answer":"$A = w(20 - w)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2w + 2L = 40 -> L = 20 - w; A = w(20 - w).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
