INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61c08f1c-b387-4b47-b971-5667d557bf75', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'A baker sells loaves at 4 dollars each. Each loaf costs 1.50 dollars to make. In a model of profit, how many dollars of profit come from selling 40 loaves?', '[]', '100', '40*(4-1.5)', 'Profit per loaf is $4 - 1.50 = 2.50$ dollars. For 40 loaves: $40 \times 2.50 = 100$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Profit per loaf 4 - 1.50 = 2.50; 40 x 2.50 = 100.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a02e98f7-6c11-413d-9257-78c0b33b1bd4', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'The height of a thrown ball is modeled by $h = -5t^2 + 40t$ meters after $t$ seconds. What height does the model give after 3 seconds, in meters?', '[]', '75', '-5*9+40*3', 'Put $t = 3$: $-5 \times 9 + 40 \times 3 = -45 + 120 = 75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5(9) + 40(3) = -45 + 120 = 75.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
