INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7f774a5-f234-4155-b105-2750e0ecaa6e', 'NC26.M1.RMM.1', 2, 'numeric', 'Test a conjecture or model against data', 'The model $P = 12 + 3d$ gives the pages $P$ read after $d$ days. A student has really read 31 pages after 5 days. By how many pages is the real number above the prediction?', '[]', '4', '31-(12+3*5)', 'The model predicts $12 + 3 \times 5 = 27$ pages. The real number is 31, which is $31 - 27 = 4$ more.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prediction 12 + 15 = 27; 31 - 27 = 4.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
