INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('200a6c99-ed3d-4ee2-8005-7d0c213cae59', 'NC26.M1.RMM.1', 3, 'choice', 'Critique a model and its limits', 'A model for future sales is built only from three unusually good months. What is the best critique?', '["It uses too few operations","It must be accurate, because the months were good","It uses data that are not typical, so it will probably overpredict","It cannot be used because sales are positive"]', 'It uses data that are not typical, so it will probably overpredict', NULL, 'A model is only as good as the data it is built from. Unusually good months make predictions too high for typical months.', 'checked', '{"lint":[],"solve":{"answer":"It uses data that are not typical, so it will probably overpredict","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unrepresentative good months bias predictions high.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bea71a93-425b-4db5-afe7-7a404e70bf38', 'NC26.M1.RMM.1', 3, 'numeric', 'Choose the model that fits the data', 'The values 2, 3, 6 and 11 occur at $x = 0, 1, 2, 3$ and follow a quadratic pattern. What is the next value, at $x = 4$?', '[]', '18', '11+7', 'The differences are 1, 3, 5, which grow by 2 each time. The next difference is 7, so the next value is $11 + 7 = 18$. (This is $y = x^2 + 2$.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences 1, 3, 5 (second differences 2); next difference 7: 11 + 7 = 18.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e16cab50-1828-4e80-a2e0-3b8de6cd5e9f', 'NC26.M1.RMM.1', 3, 'numeric', 'Choose the model that fits the data', 'The values 80, 72 and 64.8 occur at $x = 0, 1, 2$ and follow an exponential pattern. What is the value at $x = 3$?', '[]', '58.32', '64.8*0.9', 'Each value is 0.9 times the one before ($72 \div 80 = 0.9$ and $64.8 \div 72 = 0.9$). Next: $64.8 \times 0.9 = 58.32$.', 'checked', '{"lint":[],"solve":{"answer":"58.32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 72/80 = 0.9; 64.8 x 0.9 = 58.32.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8eb6304-2986-46c5-8a9c-c93c11be45c7', 'NC26.M1.RMM.1', 3, 'choice', 'Order the steps of the modeling cycle', 'A student built a model, tested it, found it too high, revised it, and tested it again. What does this show about modeling?', '["Modeling is a cycle that repeats until the model is good enough","The first model is always right","Testing is needed only once","Revising a model means starting again from nothing every single time"]', 'Modeling is a cycle that repeats until the model is good enough', NULL, 'Modeling is a cycle: build, test, revise, test again. Each pass improves the model until it fits well enough to use.', 'checked', '{"lint":[],"solve":{"answer":"Modeling is a cycle that repeats until the model is good enough","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Build, test, revise, test again: a cycle.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe2c67b-3982-455a-a975-adb67cae1792', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply powers with the same base', 'Simplify $x^3 \cdot x^4$.', '["$x^7$","$x^{12}$","$2x^7$","$x^{-1}$"]', '$x^7$', NULL, 'When you multiply powers with the same base, add the exponents: $x^3 \cdot x^4 = x^{3+4} = x^7$.', 'checked', '{"lint":[],"solve":{"answer":"$x^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: x^(3+4) = x^7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebd0103b-5e4b-4d38-be71-1e826504c98a', 'NC26.M1.ANFR.1', 1, 'numeric', 'Evaluate zero and positive integer exponents', 'What is the value of $5^0 + 3^2$?', '[]', '10', '5^0+3^2', 'Any nonzero number to the power 0 is 1, so $5^0 = 1$. Also $3^2 = 9$. The sum is $1 + 9 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^0 = 1, 3^2 = 9, sum 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b17b0c24-ecd0-46b5-8340-4ffd35abc21d', 'NC26.M1.ANFR.1', 1, 'numeric', 'Add polynomials by combining like terms', 'Add $(4x^2 + 3x + 1) + (x^2 + 6x + 5)$. What is the coefficient of $x$ in the sum?', '[]', '9', '3+6', 'Combine like terms: $(4x^2 + x^2) + (3x + 6x) + (1 + 5) = 5x^2 + 9x + 6$. The coefficient of $x$ is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 5x^2 + 9x + 6. Coefficient of x is 3 + 6 = 9.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b7a7a82-ba41-4707-815d-9ca873e0c210', 'NC26.M1.ANFR.1', 1, 'numeric', 'Multiply powers with the same base', 'The product $3^{4} \cdot 3^{2}$ is equal to $3^{n}$. What is the value of $n$?', '[]', '6', '4+2', 'When you multiply powers with the same base, you add the exponents: $3^{4} \cdot 3^{2} = 3^{4+2} = 3^{6}$. So $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: 3^4 * 3^2 = 3^(4+2) = 3^6, so n = 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3659a7bc-18d2-49c8-b881-1a29d817c586', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply powers with the same base', 'Which expression is equal to $y^{5} \cdot y^{3}$?', '["$y^{8}$","$y^{15}$","$y^{2}$","$2y^{8}$"]', '$y^{8}$', NULL, 'Multiplying powers with the same base means adding the exponents: $y^{5} \cdot y^{3} = y^{5+3} = y^{8}$. Multiplying the exponents (15) or subtracting them (2) are common mistakes.', 'checked', '{"lint":[],"solve":{"answer":"$y^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y^5 * y^3 = y^(5+3) = y^8. Distractors: y^15 multiplies exponents, 2y^8 adds coefficients wrongly, y^2 subtracts.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aaa48739-ecae-4820-9c7e-3f8e4deccb68', 'NC26.M1.ANFR.1', 1, 'numeric', 'Divide powers with the same base', 'Complete the equation $\frac{7^{9}}{7^{4}} = 7^{n}$. What is $n$?', '[]', '5', '9-4', 'When you divide powers with the same base, you subtract the exponents: $\frac{7^{9}}{7^{4}} = 7^{9-4} = 7^{5}$. So $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quotient of powers: 7^(9-4) = 7^5, n = 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616e2d74-faf7-4ed4-9874-6de3a85b1c40', 'NC26.M1.ANFR.1', 1, 'choice', 'Divide powers with the same base', 'Simplify $\frac{x^{10}}{x^{6}}$, where $x$ is not zero.', '["$x^{16}$","$x^{4}$","$x^{-4}$","$4x$"]', '$x^{4}$', NULL, 'Subtract the exponent in the bottom from the exponent in the top: $10 - 6 = 4$. So $\frac{x^{10}}{x^{6}} = x^{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^10 / x^6 = x^(10-6) = x^4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdfc5081-f737-438e-8e42-a4ebd9d29943', 'NC26.M1.ANFR.1', 1, 'numeric', 'Raise a power to a power', 'The expression $(4^{2})^{3}$ equals $4^{k}$. What is $k$?', '[]', '6', '2*3', 'To raise a power to a power, multiply the exponents: $(4^{2})^{3} = 4^{2 \times 3} = 4^{6}$. So $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Power of a power: (4^2)^3 = 4^(2*3) = 4^6, k = 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
