INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d13bafbc-0bf1-48c9-89f0-c5e09e5c905e', 'NC26.M1.ANFR.1', 1, 'choice', 'Raise a power to a power', 'Simplify $(x^{4})^{2}$.', '["$x^{6}$","$x^{16}$","$x^{8}$","$2x^{4}$"]', '$x^{8}$', NULL, 'Multiply the exponents: $4 \times 2 = 8$. So $(x^{4})^{2} = x^{8}$. Adding the exponents (6) is a different rule, for multiplying powers.', 'checked', '{"lint":[],"solve":{"answer":"$x^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^4)^2 = x^(4*2) = x^8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
