INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a32a1047-ed3b-4494-97dc-462beb824dbf', 'NC26.M1.ANFR.1', 1, 'choice', 'Raise a product or quotient to a power', 'Simplify $(xy)^{3}$.', '["$xy^{3}$","$3xy$","$x^{3} + y^{3}$","$x^{3}y^{3}$"]', '$x^{3}y^{3}$', NULL, 'A power of a product is the product of the powers: $(xy)^{3} = x^{3}y^{3}$. Both factors get the exponent 3.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3}y^{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Power of a product: (xy)^3 = x^3 y^3.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7a6b8e2-e567-4806-a5e6-d0757da76283', 'NC26.M1.ANFR.1', 1, 'numeric', 'Raise a product or quotient to a power', 'The expression $(2x)^{3}$ can be written as $kx^{3}$. What is $k$?', '[]', '8', '2^3', 'The exponent applies to both the 2 and the $x$: $(2x)^{3} = 2^{3}x^{3} = 8x^{3}$. So $k = 8$. (It is not $2 \times 3 = 6$.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x)^3 = 2^3 x^3 = 8x^3, k = 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb5c9f21-074e-466e-a8ea-6680de30de1d', 'NC26.M1.ANFR.1', 1, 'numeric', 'Zero and negative exponents', 'What is the value of $(-4)^{0}$?', '[]', '1', '1', 'Any nonzero number raised to the power 0 equals 1. So $(-4)^{0} = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any nonzero number to the power 0 is 1: (-4)^0 = 1.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
