INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dc45503-d563-4c5a-a43b-1240e07e366c', 'NC26.M1.ANFR.1', 1, 'choice', 'Zero and negative exponents', 'Which number is equal to $2^{-3}$?', '["$\\frac{1}{8}$","$-8$","$-6$","$\\frac{1}{6}$"]', '$\frac{1}{8}$', NULL, 'A negative exponent means a reciprocal: $2^{-3} = \frac{1}{2^{3}} = \frac{1}{8}$. It is not negative, and it is not $2 \times 3$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-3 = 1/2^3 = 1/8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a1b12c7-5ee2-4f6b-b739-0263a4aec51f', 'NC26.M1.ANFR.1', 1, 'numeric', 'Zero and negative exponents', 'If $5^{-2}$ is written as the fraction $\frac{1}{n}$, what is $n$?', '[]', '25', '5^2', '$5^{-2} = \frac{1}{5^{2}} = \frac{1}{25}$. So $n = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^-2 = 1/5^2 = 1/25, n = 25.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44380130-39df-4775-afe8-e78b7ac96624', 'NC26.M1.ANFR.1', 1, 'numeric', 'Combine several exponent properties', 'Write $\frac{2^{5} \cdot 2^{3}}{2^{4}}$ as a single power of 2. What exponent does it have?', '[]', '4', '5+3-4', 'Add the exponents in the top: $5 + 3 = 8$, so the top is $2^{8}$. Then divide by $2^{4}$ by subtracting: $8 - 4 = 4$. The result is $2^{4}$, so the exponent is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^(5+3) / 2^4 = 2^(8-4) = 2^4; exponent 4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e96c2754-8056-430d-97c9-e371e7da0e4a', 'NC26.M1.ANFR.1', 1, 'choice', 'Compare polynomial and integer operations', 'Adding two integers always gives an integer. Which statement about adding two polynomials is true?', '["The sum is always an integer","The sum is a polynomial only if both have the same degree","The sum always has a greater degree than either polynomial","The sum is always a polynomial"]', 'The sum is always a polynomial', NULL, 'Polynomials are closed under addition, just as integers are: adding two polynomials always gives a polynomial. It need not be an integer, and the degree of the sum can be the same or even lower (for example, $x^{2} + (-x^{2} + 1) = 1$).', 'checked', '{"lint":[],"solve":{"answer":"The sum is always a polynomial","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Polynomials are closed under addition, like integers: the sum of two polynomials is always a polynomial. Not always an integer; degrees need not match; degree can stay the same or drop.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bb12fd0-aeab-45dc-ab46-8e8218698a2b', 'NC26.M1.ANFR.1', 1, 'numeric', 'Compare polynomial and integer operations', 'Place value connects whole numbers and polynomials. If $x = 10$, the polynomial $3x^{2} + 4x + 5$ names a whole number. What is that number?', '[]', '345', '3*100+4*10+5', 'With $x = 10$: $3x^{2} + 4x + 5 = 3 \times 100 + 4 \times 10 + 5 = 300 + 40 + 5 = 345$. The coefficients are the digits of the number.', 'checked', '{"lint":[],"solve":{"answer":"345","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(10^2) + 4(10) + 5 = 300 + 40 + 5 = 345.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ae5de0-31ef-49f0-af8b-71093c795f26', 'NC26.M1.ANFR.1', 1, 'choice', 'Add polynomials', 'Add: $(2x + 5) + (4x + 3)$.', '["$6x + 8$","$6x^{2} + 8$","$6x + 15$","$14x$"]', '$6x + 8$', NULL, 'Add the $x$ terms: $2x + 4x = 6x$. Add the constants: $5 + 3 = 8$. The sum is $6x + 8$. The $x$ terms and the constants are different kinds of terms, so they stay separate.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 4x) + (5 + 3) = 6x + 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b55d62e-e293-45cd-b627-3590c0030740', 'NC26.M1.ANFR.1', 1, 'numeric', 'Add polynomials', 'Two boards are laid end to end. One is $(2x + 1)$ feet long and the other is $(5x + 3)$ feet long. Together they are $ax + b$ feet long. What is $a + b$?', '[]', '11', '(2+5)+(1+3)', 'Total length: $(2x + 1) + (5x + 3) = 7x + 4$. So $a = 7$ and $b = 4$, and $a + b = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 1) + (5x + 3) = 7x + 4, a = 7, b = 4, a + b = 11.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e36f3b49-8f91-4ba7-9b9b-d1761d6d2371', 'NC26.M1.ANFR.1', 1, 'choice', 'Subtract polynomials', 'Subtract: $(6x + 9) - (2x + 4)$.', '["$4x + 13$","$4x + 5$","$8x + 13$","$4x - 5$"]', '$4x + 5$', NULL, 'Subtract each term of the second polynomial: $6x - 2x = 4x$ and $9 - 4 = 5$. The result is $4x + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$4x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 9 - 2x - 4 = 4x + 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20e961e4-cf0f-4847-9352-ee13c6c4091c', 'NC26.M1.ANFR.1', 1, 'numeric', 'Subtract polynomials', 'A tank holds $(8x + 15)$ liters of water. Then $(3x + 6)$ liters are used. The water left is $ax + b$ liters. What is $b$?', '[]', '9', '15-6', 'Water left: $(8x + 15) - (3x + 6) = 5x + 9$. So $a = 5$ and $b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8x + 15) - (3x + 6) = 5x + 9, b = 9.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
