INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc769d1c-a548-4e16-9016-ae285af4b5ff', 'NC26.M1.ANFR.1', 1, 'numeric', 'Multiply a monomial by a polynomial', 'When $5(2x + 3)$ is written as $ax + b$, what is $a + b$?', '[]', '25', '5*2+5*3', 'Distribute the 5: $5(2x + 3) = 10x + 15$. So $a = 10$ and $b = 15$, and $a + b = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(2x + 3) = 10x + 15, a + b = 25.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
