INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b602487-9912-4284-8f9e-d83af7f5a6b3', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply a monomial by a polynomial', 'Expand: $x(x + 7)$.', '["$x^{2} + 7$","$2x + 7$","$x^{2} + 7x$","$x^{2} + 7x^{2}$"]', '$x^{2} + 7x$', NULL, 'Multiply $x$ by each term: $x \cdot x = x^{2}$ and $x \cdot 7 = 7x$. The result is $x^{2} + 7x$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} + 7x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x*x + x*7 = x^2 + 7x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf15bc24-65e7-4b7f-9d01-6f1559bcf74f', 'NC26.M1.ANFR.1', 1, 'numeric', 'Multiply a monomial by a polynomial', 'A rectangle is 4 feet wide and $(x + 9)$ feet long. Its area is $4x + c$ square feet. What is $c$?', '[]', '36', '4*9', 'Area is width times length: $4(x + 9) = 4x + 36$. So $c = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 4(x + 9) = 4x + 36, c = 36.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
