INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0cf85b5-904a-4d57-8464-77138de4a11c', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply two binomials', 'Multiply: $(x + 2)(x + 5)$.', '["$x^{2} + 10$","$x^{2} + 7x + 7$","$x^{2} + 10x + 7$","$x^{2} + 7x + 10$"]', '$x^{2} + 7x + 10$', NULL, 'Multiply each term of the first by each term of the second: $x \cdot x = x^{2}$, $x \cdot 5 = 5x$, $2 \cdot x = 2x$, $2 \cdot 5 = 10$. Combine the $x$ terms: $5x + 2x = 7x$. The product is $x^{2} + 7x + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} + 7x + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 5x + 2x + 10 = x^2 + 7x + 10.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b60114d-3c17-4fd9-bd6b-7f97e933d80b', 'NC26.M1.ANFR.1', 1, 'numeric', 'Multiply two binomials', 'When $(x + 3)(x + 4)$ is multiplied out as $x^{2} + bx + c$, what is $b$?', '[]', '7', '3+4', '$(x + 3)(x + 4) = x^{2} + 4x + 3x + 12 = x^{2} + 7x + 12$. So $b = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 4x + 3x + 12 = x^2 + 7x + 12, b = 7.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
