INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3645337-5e11-4eba-81df-362df342cd72', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply two binomials', 'Multiply: $(y + 6)(y + 1)$.', '["$y^{2} + 6$","$7y + 6$","$y^{2} + 7y + 6$","$y^{2} + 6y + 7$"]', '$y^{2} + 7y + 6$', NULL, '$y \cdot y = y^{2}$, $y \cdot 1 = y$, $6 \cdot y = 6y$, $6 \cdot 1 = 6$. Combine: $y + 6y = 7y$. The product is $y^{2} + 7y + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y^{2} + 7y + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y^2 + y + 6y + 6 = y^2 + 7y + 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
