INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b30a268b-1c75-404b-9f6e-9a20f1ebc3cd', 'NC26.M1.ANFR.1', 1, 'numeric', 'Rewrite an expression in an equivalent form', 'When $x^{2} + 3x + 5x$ is written with like terms combined, it is $x^{2} + bx$. What is $b$?', '[]', '8', '3+5', 'The terms $3x$ and $5x$ are like terms, so $3x + 5x = 8x$. The expression is $x^{2} + 8x$, so $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 5x = 8x, so x^2 + 8x, b = 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
