INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7d76992-1601-4a76-a463-e0c161000096', 'NC26.M1.ANFR.1', 1, 'choice', 'Rewrite an expression in an equivalent form', 'Which expression is equivalent to $4(x + 1) - 4$?', '["$4x + 8$","$4x + 4$","$4x - 3$","$4x$"]', '$4x$', NULL, 'Distribute the 4: $4(x + 1) = 4x + 4$. Then subtract 4: $4x + 4 - 4 = 4x$.', 'checked', '{"lint":[],"solve":{"answer":"$4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 4 - 4 = 4x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
