INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4940e659-8914-492f-8810-b0fefa82b1e7', 'NC26.M1.ANFR.2', 1, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'The first term of an arithmetic sequence is 10 and the common difference is 4. What is the 4th term?', '[]', '22', '10+3*4', 'The terms are 10, 14, 18, 22. The 4th term is $10 + 3 \times 4 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms: 10, 14, 18, 22. a4 = 10 + 3*4 = 22.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
