INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21e1658e-ac26-482b-8af5-442802d5a529', 'NC26.M1.ANFR.2', 1, 'choice', 'Predict a value from a table', 'In a linear relationship, $y = 4$ when $x = 0$ and $y = 7$ when $x = 1$. What is $y$ when $x = 2$?', '["14","10","11","9"]', '10', '7+3', 'The value of $y$ goes up by $7 - 4 = 3$ each time $x$ goes up by 1. When $x = 2$, $y = 7 + 3 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear: rate = 7-4 = 3 per unit of x. At x=2: 7+3=10.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
