INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adc236f1-1dcc-4909-97d3-a7f900bdef9d', 'NC26.M1.ANFR.2', 1, 'numeric', 'Predict a value from points on a graph', 'A straight line passes through the points $(0, 3)$, $(1, 5)$ and $(2, 7)$. What is the $y$-coordinate of the point on the line with $x = 4$?', '[]', '11', '3+4*2', 'Each time $x$ goes up by 1, $y$ goes up by 2. Starting at $y = 3$ when $x = 0$, at $x = 4$ the value is $3 + 4 \times 2 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (5-3)/1=2, y-intercept 3: y=2x+3. At x=4: 8+3=11.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b502f5a0-ea96-472a-b8a0-6434f03be86f', 'NC26.M1.ANFR.2', 1, 'numeric', 'Predict a value from points on a graph', 'The points $(0, 1)$, $(1, 3)$ and $(2, 9)$ lie on the graph of an exponential relationship. What is the $y$-coordinate of the point on the graph with $x = 3$?', '[]', '27', '9*3', 'Each $y$-value is 3 times the one before ($3 \div 1 = 3$, $9 \div 3 = 3$). At $x = 3$, $y = 9 \times 3 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,3,9: multiplied by 3 each step (y=3^x). At x=3: 9*3=27.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
