INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('073b1e76-f497-461c-96c7-aaf4157b4479', 'NC26.M1.ANFR.2', 1, 'choice', 'Compare linear and exponential growth', 'Two savings plans each start with 2 dollars. Plan L adds 3 dollars each week. Plan E triples its amount each week. After 2 weeks, how do the plans compare?', '["Plan E has 10 dollars more than Plan L","Plan E has 4 dollars more than Plan L","Plan L has 2 dollars more than Plan E","Plan E has 28 dollars more than Plan L"]', 'Plan E has 10 dollars more than Plan L', NULL, 'Plan L: $2 \to 5 \to 8$, so 8 dollars. Plan E: $2 \to 6 \to 18$, so 18 dollars. Plan E has $18 - 8 = 10$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"Plan E has 10 dollars more than Plan L","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Plan L: 2 -> 5 -> 8 dollars after 2 weeks. Plan E: 2 -> 6 -> 18 dollars. 18-8=10, Plan E has 10 dollars more.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1825c0f-58f6-4d99-b2da-f879f1af7fef', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a table', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 3, 6, 12, 24. Which statement describes the pattern?', '["Exponential: $y$ is multiplied by 2 each time $x$ increases by 1","Linear: $y$ increases by 3 each time $x$ increases by 1","Linear: $y$ increases by 6 each time $x$ increases by 1","Exponential: $y$ is multiplied by 3 each time $x$ increases by 1"]', 'Exponential: $y$ is multiplied by 2 each time $x$ increases by 1', NULL, 'The differences are 3, 6, 12, which are not equal, so the pattern is not linear. The ratios are $6 \div 3 = 2$, $12 \div 6 = 2$ and $24 \div 12 = 2$, so $y$ is multiplied by 2 each time.', 'checked', '{"lint":[],"solve":{"answer":"Exponential: $y$ is multiplied by 2 each time $x$ increases by 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,6,12,24: differences 3,6,12 not constant; ratios 2,2,2 -> exponential, multiplied by 2.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce3e7f25-668d-4b8a-b40d-519df3a41553', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value in an exponential decay pattern', 'A table gives $P$ for $t = 0, 1, 2, 3$: the values of $P$ are 640, 320, 160, 80. The pattern continues in the same way. What is $P$ when $t = 6$?', '[]', '10', '640*(1/2)^6', 'Each value is half the one before it. So $P = 640 \times \left(\frac{1}{2}\right)^t$. At $t = 6$: $640 \div 64 = 10$. (Continuing the list: 80, 40, 20, 10.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halving each step: 640, 320, 160, 80, 40 (t=4), 20 (t=5), 10 (t=6).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2488f536-ef8c-4590-8782-3eca13048890', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value in a linear pattern from a table', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 10, 14, 18, 22. The pattern continues in the same way. What is $y$ when $x = 6$?', '[]', '34', '10+4*6', 'The values go up by 4 each time, so $y = 10 + 4x$. When $x = 6$: $y = 10 + 24 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adds 4 each step: y = 10 + 4x. At x = 6: 10 + 24 = 34.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4828a77-9f85-4464-9614-d185903d5123', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a table', 'The values of $y$ at $x = 0, 1, 2, 3, 4$ are 160, 80, 40, 20, 10. How should this relationship be described?', '["Exponential, because $y$ is multiplied by 2 each time","Linear, because $y$ keeps decreasing","Linear, because $y$ decreases by 80 each time","Exponential, because $y$ is multiplied by $\\frac{1}{2}$ each time"]', 'Exponential, because $y$ is multiplied by $\frac{1}{2}$ each time', NULL, '$80 \div 160 = \frac{1}{2}$, $40 \div 80 = \frac{1}{2}$, and so on, so $y$ is multiplied by $\frac{1}{2}$ each time. The decreases are 80, 40, 20, 10, which are not equal, so it is not linear.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because $y$ is multiplied by $\\frac{1}{2}$ each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80/160=1/2, 40/80=1/2, 20/40=1/2, 10/20=1/2: constant ratio 1/2 -> exponential decay, multiplied by 1/2. Differences -80,-40,-20,-10 are not constant, so not linear; not multiplied by 2.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1189bdc5-335b-42d6-bc6f-f00d84d17d3e', 'NC26.M1.ANFR.2', 2, 'numeric', 'Tell linear from exponential in a table', 'The relationship between $x$ and $y$ is linear. When $x$ is 0, 5, 10 and 15, $y$ is 2, 12, 22 and 32. By how much does $y$ change each time $x$ increases by 1?', '[]', '2', '(12-2)/5', 'When $x$ goes up by 5, $y$ goes up by $12 - 2 = 10$. So for each increase of 1 in $x$, $y$ goes up by $10 \div 5 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y rises by 10 for each increase of 5 in x (12-2, 22-12, 32-22). Rate = 10/5 = 2 per unit of x.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d3579dd-ca3f-478a-b8e4-61f38cd179df', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a table', 'A savings account holds 100, 110, 121 and 133.1 dollars after 0, 1, 2 and 3 years. Which statement describes the pattern?', '["Linear, because each amount is 10 more than the one before","Linear, because each amount is 11 more than the one before","Exponential, because each amount is 1.1 times the one before","Exponential, because each amount is 10 times the one before"]', 'Exponential, because each amount is 1.1 times the one before', NULL, 'The increases are 10, 11, 12.1, which are not equal, so it is not linear. The ratios $110 \div 100$, $121 \div 110$ and $133.1 \div 121$ are all $1.1$, so each amount is 1.1 times the one before.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because each amount is 1.1 times the one before","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"110/100=1.1, 121/110=1.1, 133.1/121=1.1: constant ratio -> exponential. Differences 10, 11, 12.1 not constant.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a264032d-a936-44f8-85dc-662ea2991ec2', 'NC26.M1.ANFR.2', 2, 'numeric', 'Tell linear from exponential in a table', 'The values of $y$ at $x = 0, 1, 2, 3$ are 81, 27, 9, 3. Each value is the same multiple of the one before it. What is that multiple?', '[]', '1/3', '27/81', 'Divide each value by the one before it: $27 \div 81 = \frac{1}{3}$, $9 \div 27 = \frac{1}{3}$ and $3 \div 9 = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27/81=1/3, 9/27=1/3, 3/9=1/3. The multiple is 1/3.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9164ef5-e41c-44df-b167-cb4c21ac7e43', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a situation or equation', 'Which situation shows exponential decay?', '["A candle burns down 2 centimeters every hour","A car loses 15% of its value each year","A tank drains 5 gallons every minute","A phone battery drops 4 percentage points every hour"]', 'A car loses 15% of its value each year', NULL, 'Exponential decay multiplies by the same number between 0 and 1 each time. Losing 15% of the value each year multiplies the value by 0.85. The other three lose the same fixed amount each time, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"A car loses 15% of its value each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Losing 15% each year means multiplying by 0.85 each year -> exponential decay. The battery (4 points/hour), tank (5 gal/min) and candle (2 cm/hour) decrease by constant amounts -> linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7a8d5c1-9a32-4c90-867d-f41f1bb42a18', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a situation or equation', 'Which equation represents a linear relationship?', '["$y = 2(4)^x$","$y = (x + 4)^2$","$y = 4^{2x}$","$y = 2(x + 4)$"]', '$y = 2(x + 4)$', NULL, '$y = 2(x + 4)$ simplifies to $y = 2x + 8$, which is linear. $y = 2(4)^x$ and $y = 4^{2x}$ (which equals $16^x$) are exponential, and $y = (x + 4)^2$ has a squared variable.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2(x + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=2(x+4)=2x+8 is linear. y=2(4)^x and y=4^{2x}=16^x are exponential; y=(x+4)^2 is quadratic.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('963f8cc3-3323-4fb6-b8af-086c92e50e32', 'NC26.M1.ANFR.2', 2, 'numeric', 'Tell linear from exponential in a situation or equation', 'A fish population grows by 12% each year. By what number is the population multiplied from one year to the next?', '[]', '1.12', '1+12/100', 'Growing by 12% means keeping 100% of the population and adding 12% more, so the new population is $100\% + 12\% = 112\%$, which is $1.12$ times the old one.', 'checked', '{"lint":[],"solve":{"answer":"1.12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growing by 12% means new = old + 0.12*old = 1.12*old. Factor 1.12.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b11dd2fb-a5ba-4e6c-98b3-ef7984f7729e', 'NC26.M1.ANFR.2', 2, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'Which relationship is neither linear nor exponential?', '["The perimeter of a square as its side length changes","The cost of buying pencils at 30 cents each as the number of pencils changes","The area of a square as its side length changes","The amount in an account that doubles each year as the number of years changes"]', 'The area of a square as its side length changes', NULL, 'The area is $s^2$, which is neither linear nor exponential. The perimeter $4s$ and the pencil cost are linear (a fixed amount added each time), and an amount that doubles each year is exponential.', 'checked', '{"lint":[],"solve":{"answer":"The area of a square as its side length changes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area of square A=s^2: quadratic -> neither. Doubling account: exponential. Pencils at 30 cents: linear. Perimeter P=4s: linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a51cf284-2eec-4430-abc6-e1f45387433e', 'NC26.M1.ANFR.2', 2, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'A ball is thrown straight up. Its height rises, reaches a top, then falls back to the ground. Which statement is true about modeling the whole flight?', '["Neither a linear nor an exponential function fits, because the height rises and then falls","A linear function fits, because the ball moves at a steady speed","An exponential function fits, because the height keeps multiplying","One linear function fits if its rate of change is positive and then negative"]', 'Neither a linear nor an exponential function fits, because the height rises and then falls', NULL, 'A linear function always goes one way (up if the rate is positive, down if it is negative) and so does an exponential function. The height of the ball goes up and then down, so neither kind of function can model the whole flight.', 'checked', '{"lint":[],"solve":{"answer":"Neither a linear nor an exponential function fits, because the height rises and then falls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A linear function is always increasing or always decreasing (or constant), with one fixed rate; an exponential function is also monotonic. Height rising then falling cannot be either. One linear function cannot have a rate that changes sign. So neither fits.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48463943-8416-4905-8f37-abd9987378b6', 'NC26.M1.ANFR.2', 2, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'The numbers of dots in figures 1, 2, 3 and 4 are 1, 3, 6 and 10. Which statement is true?', '["Linear, because the number of dots keeps increasing","Neither: the increases 2, 3, 4 are not equal and the ratios are not equal","Linear, because it goes up by 2 each time","Exponential, because it is multiplied by 3 at the start"]', 'Neither: the increases 2, 3, 4 are not equal and the ratios are not equal', NULL, 'The increases are $3 - 1 = 2$, $6 - 3 = 3$, $10 - 6 = 4$, so it is not linear. The ratios are $3$, $2$, $1.67$, so it is not exponential.', 'checked', '{"lint":[],"solve":{"answer":"Neither: the increases 2, 3, 4 are not equal and the ratios are not equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,3,6,10: increases 2,3,4 not equal -> not linear; ratios 3, 2, 1.67 not equal -> not exponential. Neither.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9c01b3a-38a0-4daa-b18f-903b276b26d3', 'NC26.M1.ANFR.2', 2, 'numeric', 'Recognize a pattern that is neither linear nor exponential', 'Here are four sequences. A: 4, 8, 12, 16. B: 4, 8, 16, 32. C: 4, 8, 14, 22. D: 4, 8, 13, 19. How many of them are neither arithmetic nor geometric?', '[]', '2', NULL, 'A adds 4 each time, so it is arithmetic. B multiplies by 2 each time, so it is geometric. C has differences 4, 6, 8 and D has differences 4, 5, 6, and neither has a constant ratio. So 2 sequences, C and D, are neither.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: diffs 4,4,4 arithmetic. B: ratio 2 geometric. C: diffs 4,6,8; ratios 2, 1.75, 1.57 -> neither. D: diffs 4,5,6; ratios 2, 1.625, 1.46 -> neither. Two are neither.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014a36ac-062b-42ec-bc95-9fa66f18033e', 'NC26.M1.ANFR.2', 2, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'What is the 20th term of the arithmetic sequence 5, 8, 11, 14, ...?', '[]', '62', '5+19*3', 'The common difference is 3. The 20th term is the first term plus 19 differences: $5 + 19 \times 3 = 5 + 57 = 62$.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=5, d=3. a20 = 5 + 19*3 = 5 + 57 = 62.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0edc96b-7cdc-4f8c-8b98-eafbb9cb32a6', 'NC26.M1.ANFR.2', 2, 'choice', 'Arithmetic sequences: difference, terms and formulas', 'Which formula gives the $n$th term of the arithmetic sequence 7, 11, 15, 19, ...?', '["$a_n = 7 + 4(n - 1)$","$a_n = 7 + 4n$","$a_n = 4 + 7(n - 1)$","$a_n = 7(4)^{n-1}$"]', '$a_n = 7 + 4(n - 1)$', NULL, 'The first term is 7 and the common difference is 4, so $a_n = 7 + 4(n - 1)$. Check: $n = 1$ gives 7 and $n = 2$ gives 11. The formula $7 + 4n$ gives 11 for $n = 1$, and the last formula is geometric.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 7 + 4(n - 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=7, d=4: a_n = 7 + 4(n-1). Check n=1: 7, n=2: 11. 7+4n gives 11 at n=1 (wrong); 4+7(n-1) gives 4 at n=1 (wrong); 7(4)^{n-1} is geometric.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5813f7b9-769d-46c5-9392-e70577d6e318', 'NC26.M1.ANFR.2', 2, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'An arithmetic sequence has first term 100 and common difference $-7$. What is the 6th term?', '[]', '65', '100-5*7', 'The 6th term is the first term plus 5 differences: $100 + 5 \times (-7) = 100 - 35 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a6 = 100 + 5*(-7) = 100 - 35 = 65. (100, 93, 86, 79, 72, 65)","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c96e629-4b2e-4874-80b9-bc08d2689009', 'NC26.M1.ANFR.2', 2, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'A theater has 12 seats in the first row. Each row has 3 more seats than the row in front of it. How many seats are in row 10?', '[]', '39', '12+9*3', 'The numbers of seats form an arithmetic sequence with first term 12 and difference 3. Row 10 has $12 + 9 \times 3 = 12 + 27 = 39$ seats.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Row n has 12 + 3(n-1) seats. Row 10: 12 + 27 = 39.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5945f042-6618-4100-8952-28dafe99f272', 'NC26.M1.ANFR.2', 2, 'numeric', 'Geometric sequences: ratio, terms and formulas', 'What is the 6th term of the geometric sequence 3, 6, 12, 24, ...?', '[]', '96', '3*2^5', 'The common ratio is 2. The 6th term is the first term times the ratio 5 times: $3 \times 2^5 = 3 \times 32 = 96$.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 2: 3, 6, 12, 24, 48, 96. 6th term = 3*2^5 = 96.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4e6ad3e-da06-46ae-bbc4-5dc2da932709', 'NC26.M1.ANFR.2', 2, 'choice', 'Geometric sequences: ratio, terms and formulas', 'Which formula gives the $n$th term of the geometric sequence 5, 10, 20, 40, ...?', '["$a_n = 5 + 5(n - 1)$","$a_n = 5(2)^n$","$a_n = 2(5)^{n-1}$","$a_n = 5(2)^{n-1}$"]', '$a_n = 5(2)^{n-1}$', NULL, 'The first term is 5 and the common ratio is 2, so $a_n = 5(2)^{n-1}$. Check: $n = 1$ gives 5 and $n = 3$ gives 20. The formula $5 + 5(n - 1)$ is arithmetic, $5(2)^n$ gives 10 for $n = 1$, and $2(5)^{n-1}$ swaps the first term and the ratio.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 5(2)^{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=5, r=2: a_n = 5(2)^{n-1}. Check n=1: 5, n=2: 10. 5(2)^n gives 10 at n=1 (wrong); 2(5)^{n-1} gives 2 (wrong); 5+5(n-1) is arithmetic.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
