INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc093ab5-3d9a-4775-a94f-336437abb61a', 'NC26.M1.ANFR.2', 2, 'numeric', 'Geometric sequences: ratio, terms and formulas', 'A ball is dropped and bounces. The first bounce reaches 200 centimeters. Each later bounce reaches 60% as high as the bounce before it. How high is the third bounce, in centimeters?', '[]', '72', '200*0.6^2', 'The heights form a geometric sequence with ratio $0.6$: first bounce 200, second bounce $200 \times 0.6 = 120$, third bounce $120 \times 0.6 = 72$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First bounce 200, second 0.6*200=120, third 0.6*120=72 cm.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135c4347-4d8d-4b0f-9103-a87e38229a86', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value from a table', 'A taxi charges 5.50 dollars for 1 mile, 8 dollars for 2 miles and 10.50 dollars for 3 miles, and the pattern continues. How many dollars does it charge for 8 miles?', '[]', '23', '5.5+7*2.5', 'The charge goes up by $8 - 5.50 = 2.50$ dollars for each extra mile. For 8 miles it is $5.50 + 7 \times 2.50 = 5.50 + 17.50 = 23$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.50, 8.00, 10.50: adds 2.50 per mile. Cost for n miles = 5.50 + 2.50(n-1). n=8: 5.50 + 17.50 = 23 dollars.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0b9dfd4-5cce-4b8b-8f7a-63a250e4aba3', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value from a table', 'A new account has 5 followers on day 0, 10 on day 1, 20 on day 2 and 40 on day 3. The pattern continues. How many followers does it have on day 7?', '[]', '640', '5*2^7', 'The number of followers doubles each day, so on day 7 it is $5 \times 2^7 = 5 \times 128 = 640$.', 'checked', '{"lint":[],"solve":{"answer":"640","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubles each day: 5*2^d. Day 7: 5*128 = 640.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3684a63b-24d5-4fbf-9eda-a94a1e9aba38', 'NC26.M1.ANFR.2', 2, 'choice', 'Predict a value from a table', 'A linear relationship has $y = 4, 11, 18, 25$ when $x = 0, 2, 4, 6$. What is $y$ when $x = 5$?', '["25","19","21.5","20"]', '21.5', '(18+25)/2', 'When $x$ goes up by 2, $y$ goes up by 7, so $y$ goes up by $3.5$ for each increase of 1 in $x$. At $x = 5$, $y = 18 + 3.5 = 21.5$. This is also halfway between 18 and 25.', 'checked', '{"lint":[],"solve":{"answer":"21.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y rises 7 for every 2 in x: slope 3.5, y = 4 + 3.5x. At x=5: 4 + 17.5 = 21.5.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da530468-008b-437d-9a76-773d6e8361e5', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value from a table', 'A machine is worth 8100 dollars when new, 5400 dollars after 1 year, 3600 dollars after 2 years and 2400 dollars after 3 years. If the pattern continues, how many dollars is it worth after 4 years?', '[]', '1600', '2400*2/3', 'Each value is $\frac{2}{3}$ of the one before: $8100 \times \frac{2}{3} = 5400$, $5400 \times \frac{2}{3} = 3600$, $3600 \times \frac{2}{3} = 2400$. After 4 years it is $2400 \times \frac{2}{3} = 1600$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5400/8100 = 2/3, 3600/5400 = 2/3, 2400/3600 = 2/3. Constant ratio 2/3. After 4 years: 2400*2/3 = 1600.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cf85e9d-fc26-4c95-865c-c0e51ceba85e', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value from points on a graph', 'A straight line passes through the points $(2, 7)$ and $(5, 16)$. What is the $y$-coordinate of the point on the line with $x = 10$?', '[]', '31', '16+5*(16-7)/(5-2)', 'From $x = 2$ to $x = 5$, $y$ goes up by 9, so $y$ goes up by 3 for each increase of 1 in $x$. From $x = 5$ to $x = 10$, $y$ goes up by $5 \times 3 = 15$, so $y = 16 + 15 = 31$.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (16-7)/(5-2) = 9/3 = 3. y = 7 + 3(x-2). At x=10: 7 + 24 = 31.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('969b84b8-6acd-479a-8342-9e56e4d67a66', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value from points on a graph', 'The graph of an exponential relationship passes through $(1, 6)$ and $(2, 18)$. What is the $y$-coordinate of the point on the graph with $x = 4$?', '[]', '162', '6*(18/6)^3', 'Each $y$-value is $18 \div 6 = 3$ times the one before. From $x = 1$ to $x = 4$ is 3 steps, so $y = 6 \times 3^3 = 6 \times 27 = 162$.', 'checked', '{"lint":[],"solve":{"answer":"162","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 18/6 = 3 per unit x. x=3: 54, x=4: 162.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc06f513-54fc-4033-8221-d4635d9065f1', 'NC26.M1.ANFR.2', 2, 'choice', 'Predict a value from points on a graph', 'A straight line passes through the points $(0, 20)$ and $(4, 12)$. Which point is also on the line?', '["$(6, 8)$","$(6, 10)$","$(5, 12)$","$(7, 4)$"]', '$(6, 8)$', NULL, 'From $x = 0$ to $x = 4$, $y$ goes down by 8, so it goes down by 2 for each increase of 1 in $x$. The line is $y = 20 - 2x$. At $x = 6$, $y = 20 - 12 = 8$. At $x = 5$, $y = 10$, and at $x = 7$, $y = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (12-20)/4 = -2: y = 20 - 2x. (7,4): 6 no. (5,12): 10 no. (6,10): 8 no. (6,8): 20-12=8 yes.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e5f15c5-029c-4ec9-87c2-bcb42c739855', 'NC26.M1.ANFR.2', 2, 'choice', 'Predict a value from points on a graph', 'A graph passes through the points $(0, 100)$, $(1, 80)$, $(2, 64)$ and $(3, 51.2)$. Which statement is true?', '["Linear, because $y$ goes down by 20 each time","Exponential growth, because the growth factor is 0.8","Exponential decay, because each $y$-value is 0.8 times the one before","Exponential decay, because each $y$-value is 0.2 times the one before"]', 'Exponential decay, because each $y$-value is 0.8 times the one before', NULL, '$80 \div 100 = 0.8$, $64 \div 80 = 0.8$ and $51.2 \div 64 = 0.8$. Each $y$-value is 0.8 times the one before, which is exponential decay. The decreases (20, 16, 12.8) are not equal, so it is not linear.', 'checked', '{"lint":[],"solve":{"answer":"Exponential decay, because each $y$-value is 0.8 times the one before","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80/100 = 0.8, 64/80 = 0.8, 51.2/64 = 0.8: constant ratio 0.8 < 1 -> exponential decay, each value 0.8 times the one before. Differences -20, -16, -12.8 not constant.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c52023fd-f554-48d5-b455-428be219e771', 'NC26.M1.ANFR.2', 2, 'numeric', 'Compare linear and exponential growth', 'Two plans are measured at $t = 0, 1, 2, 3, 4$. Plan A has the values 8, 12, 16, 20, 24 and Plan B has the values 2, 4, 8, 16, 32. For what value of $t$ does Plan B first have a greater value than Plan A?', '[]', '4', NULL, 'At $t = 3$, Plan A is 20 and Plan B is 16. At $t = 4$, Plan A is 24 and Plan B is 32. Plan B is first greater at $t = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t=0: 8 vs 2; t=1: 12 vs 4; t=2: 16 vs 8; t=3: 20 vs 16; t=4: 24 vs 32. B first greater at t=4.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29a4e8a9-62e1-485d-88ce-2f2b23f21716', 'NC26.M1.ANFR.2', 2, 'choice', 'Compare linear and exponential growth', 'Let $f(x) = 4x + 100$ and $g(x) = 2^x$. Which statement is true?', '["$g(x) < f(x)$ for every value of $x$","$g(5) < f(5)$ but $g(20) > f(20)$","$g(x) > f(x)$ for every value of $x$","$g(5) > f(5)$ but $g(20) < f(20)$"]', '$g(5) < f(5)$ but $g(20) > f(20)$', NULL, '$g(5) = 32$ and $f(5) = 120$, so $g(5) < f(5)$. $g(20) = 1{,}048{,}576$ and $f(20) = 180$, so $g(20) > f(20)$. The exponential function starts lower but grows faster and passes the linear one.', 'checked', '{"lint":[],"solve":{"answer":"$g(5) < f(5)$ but $g(20) > f(20)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(5)=120, g(5)=32: g(5)<f(5). f(20)=180, g(20)=1048576: g(20)>f(20). So \"g(5) < f(5) but g(20) > f(20)\".","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052f0569-3754-4e24-800f-c421856d1213', 'NC26.M1.ANFR.2', 2, 'numeric', 'Compare linear and exponential growth', 'Account A starts with 200 dollars and adds 25 dollars each year. Account B starts with 200 dollars and is multiplied by 1.1 each year. After 2 years, how many more dollars does Account A hold than Account B?', '[]', '8', '200+2*25-200*1.1^2', 'Account A: $200 + 2 \times 25 = 250$ dollars. Account B: $200 \times 1.1 \times 1.1 = 242$ dollars. Account A holds $250 - 242 = 8$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 200 + 2*25 = 250. B: 200*1.1^2 = 200*1.21 = 242. 250 - 242 = 8.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2656b6a4-9bc3-45f0-b160-1cf8f3c3c128', 'NC26.M1.ANFR.2', 3, 'choice', 'Recognize a table that is neither linear nor exponential', 'Four tables each give $y$ for $x = 1, 2, 3, 4$. Which table is neither linear nor exponential?', '["y: 2, 5, 8, 11","y: 2, 6, 18, 54","y: 2, 5, 10, 17","y: 32, 16, 8, 4"]', 'y: 2, 5, 10, 17', NULL, 'For 2, 5, 10, 17 the differences are 3, 5, 7 (not equal) and the ratios are 2.5, 2, 1.7 (not equal), so it is neither. 2, 5, 8, 11 adds 3 each time, 2, 6, 18, 54 multiplies by 3, and 32, 16, 8, 4 multiplies by one half.', 'checked', '{"lint":[],"solve":{"answer":"y: 2, 5, 10, 17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32,16,8,4: ratio 1/2 exponential. 2,5,10,17: differences 3,5,7 (not constant), ratios 2.5, 2, 1.7 (not constant) -> neither (quadratic, x^2+1). 2,6,18,54: ratio 3 exponential. 2,5,8,11: difference 3 linear.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78dc96f2-4df1-40ec-ac42-55b303912c7e', 'NC26.M1.ANFR.2', 3, 'numeric', 'Compare a linear and an exponential plan', 'Plan A has value $A = 100 + 20t$ and Plan B has value $B = 20(2)^t$ after $t$ whole years. For the first whole number of years $t$ where Plan B is greater than Plan A, what is $t$?', '[]', '4', NULL, 'Compare year by year. $t = 0$: A is 100, B is 20. $t = 1$: 120 and 40. $t = 2$: 140 and 80. $t = 3$: 160 and 160, which are equal, not greater. $t = 4$: A is 180 and B is 320, so Plan B is greater for the first time at $t = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t=0: A 100, B 20. t=1: 120 vs 40. t=2: 140 vs 80. t=3: 160 vs 160 (equal, not greater). t=4: 180 vs 320 -> B greater. t = 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58de2bd1-ce2f-4797-852a-48ea396e06f0', 'NC26.M1.ANFR.2', 3, 'numeric', 'Find a later term of an arithmetic sequence from two terms', 'In an arithmetic sequence, the 3rd term is 11 and the 7th term is 31. What is the 10th term?', '[]', '46', '31+3*(31-11)/4', 'From the 3rd to the 7th term there are 4 steps, and the terms rise by $31 - 11 = 20$, so each step adds $20 \div 4 = 5$. The 10th term is 3 steps after the 7th: $31 + 3 \times 5 = 46$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a7 - a3 = 4d = 31 - 11 = 20, d = 5. a10 = a7 + 3d = 31 + 15 = 46.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc83ec26-61ec-4dff-a37d-5f75c79d70ba', 'NC26.M1.ANFR.2', 3, 'choice', 'Tell linear from exponential in a table', 'A table gives $y$ for $x = 1, 2, 4, 6$: the values are 5, 8, 14, 20. Which statement is true?', '["Neither, because the changes in $y$ (3, 6, 6) are not equal","Exponential, because $y$ keeps increasing","Linear, because $y$ goes up by 6 each time $x$ goes up by 1","Linear, because $y$ goes up by 3 for every increase of 1 in $x$"]', 'Linear, because $y$ goes up by 3 for every increase of 1 in $x$', NULL, 'The $x$-values do not go up by 1 each time. From $x = 1$ to 2, $y$ goes up by 3 (a rate of 3 per unit). From $x = 2$ to 4, $y$ goes up by 6, which is 3 per unit. From $x = 4$ to 6, $y$ goes up by 6, which is 3 per unit. The rate is constant, so the relationship is linear.', 'checked', '{"lint":[],"solve":{"answer":"Linear, because $y$ goes up by 3 for every increase of 1 in $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x steps are uneven: 1->2 (Dx=1, Dy=3), 2->4 (Dx=2, Dy=6), 4->6 (Dx=2, Dy=6). Rate Dy/Dx = 3 each time -> linear, y = 3x + 2. Option A ignores the uneven x-steps.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1fe1c8d-6f8c-4f8c-8c90-93f903121834', 'NC26.M1.ANFR.2', 3, 'numeric', 'Tell linear from exponential in a table', 'A table gives $y$ for $x = 0, 2, 4, 6$: the values are 3, 12, 48, 192. The relationship is exponential, and $y$ is multiplied by the same positive number each time $x$ goes up by 1. What is that number?', '[]', '2', NULL, 'When $x$ goes up by 2, $y$ is multiplied by $12 \div 3 = 4$. Going up by 2 means multiplying by the factor twice, so factor $\times$ factor $= 4$. The positive number is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each step of 2 in x multiplies y by 4 (12/3, 48/12, 192/48). Per unit x: b^2 = 4, b positive -> b = 2. y = 3*2^x.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac8f51b8-ac7a-4cfa-85f1-7230764c3dc6', 'NC26.M1.ANFR.2', 3, 'choice', 'Tell linear from exponential in a table', 'Each list gives the values of $y$ at $x = 0, 1, 2, 3$. Which list shows exponential decay?', '["100, 90, 80, 70","100, 90, 81, 72.9","100, 91, 82, 73","100, 90, 81, 70"]', '100, 90, 81, 72.9', NULL, 'In 100, 90, 81, 72.9 each value is 0.9 times the one before, which is exponential decay. The lists 100, 90, 80, 70 and 100, 91, 82, 73 decrease by a constant amount (linear), and in 100, 90, 81, 70 the last step does not follow the pattern.', 'checked', '{"lint":[],"solve":{"answer":"100, 90, 81, 72.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100,90,81,72.9: ratios 0.9, 0.9, 0.9 -> exponential decay. 100,90,81,70: 70/81 is not 0.9. 100,91,82,73 and 100,90,80,70 are linear (constant differences).","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050ceb24-0c2e-48c4-a584-d45d2bbd49b5', 'NC26.M1.ANFR.2', 3, 'choice', 'Tell linear from exponential in a situation or equation', 'Which situation is modeled by an exponential function?', '["The number of cases in an outbreak is 20% greater each day than the day before","A subscription costs 9 dollars the first month and 2 dollars more each month than the month before","A rope is shortened by 3 feet each time a piece is cut off","A pool is filled at 40 gallons per minute"]', 'The number of cases in an outbreak is 20% greater each day than the day before', NULL, 'Each day the number of cases is multiplied by 1.2, which is exponential. The subscription adds 2 dollars each month, the rope loses 3 feet each time, and the pool gains 40 gallons each minute; these all change by a fixed amount, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"The number of cases in an outbreak is 20% greater each day than the day before","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cases 20% greater each day: multiply by 1.2 daily -> exponential. Subscription +2 each month, rope -3 feet each cut, pool 40 gal/min: constant differences -> linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c0e28cf-d4f7-4224-aa7c-122fd0f81647', 'NC26.M1.ANFR.2', 3, 'numeric', 'Tell linear from exponential in a situation or equation', 'A town has 2000 people. Its population grows by 5% each year. How many more people does the town gain in the second year than in the first year?', '[]', '5', '2000*1.05^2-2000*1.05-(2000*1.05-2000)', 'After year 1: $2000 \times 1.05 = 2100$, a gain of 100. After year 2: $2100 \times 1.05 = 2205$, a gain of 105. The town gains $105 - 100 = 5$ more people in the second year.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Year 1 gain: 5% of 2000 = 100, population 2100. Year 2 gain: 5% of 2100 = 105. 105 - 100 = 5 more.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
