INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9819389-fbda-4219-af0e-08550169f5c8', 'NC26.M1.ANFR.2', 3, 'choice', 'Compare linear and exponential growth', 'Let $f(x) = 4x + 4$ and $g(x) = 4(2)^x$. Which statement about whole-number values of $x$ is true?', '["They are equal at $x = 0$ and $x = 1$, and $f(x) > g(x)$ for every whole number $x \\ge 2$","They are equal for every whole number $x$","$g(x) > f(x)$ for every whole number $x \\ge 0$","They are equal at $x = 0$ and $x = 1$, and $g(x) > f(x)$ for every whole number $x \\ge 2$"]', 'They are equal at $x = 0$ and $x = 1$, and $g(x) > f(x)$ for every whole number $x \ge 2$', NULL, '$x = 0$: both are 4. $x = 1$: both are 8. $x = 2$: $f = 12$, $g = 16$. $x = 3$: $f = 16$, $g = 32$. $x = 4$: $f = 20$, $g = 64$. The exponential function pulls ahead from $x = 2$ on.', 'checked', '{"lint":[],"solve":{"answer":"They are equal at $x = 0$ and $x = 1$, and $g(x) > f(x)$ for every whole number $x \\ge 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0)=4, g(0)=4; f(1)=8, g(1)=8: equal at 0 and 1. f(2)=12, g(2)=16; f(3)=16, g(3)=32; g doubles while f adds 4, so g>f for all x>=2.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75c4a797-0ad6-4d90-a5cd-65ffa5a6369c', 'NC26.M1.ANFR.2', 3, 'numeric', 'Compare linear and exponential growth', 'Town A has 5000 people and gains 250 people each year. Town B has 4000 people and grows by 10% each year. After 3 years, how many more people live in Town A than in Town B?', '[]', '426', '5000+3*250-4000*1.1^3', 'Town A: $5000 + 3 \times 250 = 5750$. Town B: $4000 \times 1.1^3 = 4000 \times 1.331 = 5324$. Town A has $5750 - 5324 = 426$ more people.', 'checked', '{"lint":[],"solve":{"answer":"426","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5000 + 3*250 = 5750. B: 4000*1.1^3 = 4000*1.331 = 5324. 5750 - 5324 = 426.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a0ad4b0-a49f-47dd-ad37-50a1c5eece08', 'NC26.M1.ANFR.2', 3, 'choice', 'Compare linear and exponential growth', 'Let $f(x) = 1000x$ and $g(x) = 1.1^x$. At $x = 1$, $f(1)$ is much greater than $g(1)$. Which statement is true for very large values of $x$?', '["$g(x)$ eventually becomes greater, because $g$ is multiplied by 1.1 each step but $f$ only adds 1000","$f(x)$ stays greater than $g(x)$, because 1000 is much larger than 1.1","$g(x)$ never catches up with $f(x)$, because 1.1 is close to 1","$f(x)$ and $g(x)$ become equal at some point and then stay equal"]', '$g(x)$ eventually becomes greater, because $g$ is multiplied by 1.1 each step but $f$ only adds 1000', NULL, 'Each step adds the same 1000 to $f$, but each step multiplies $g$ by 1.1, so the amount $g$ gains each step keeps growing. Eventually the gain of $g$ per step is more than 1000 and $g$ catches up with and passes $f$.', 'checked', '{"lint":[],"solve":{"answer":"$g(x)$ eventually becomes greater, because $g$ is multiplied by 1.1 each step but $f$ only adds 1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any exponential with base > 1 eventually exceeds any linear function: g multiplies by 1.1 per unit of x, f adds 1000. E.g. 1.1^200 is about 1.9e8 > 200000. So g eventually becomes greater (and stays greater).","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c4f5b78-ecc6-455d-a3dd-5117d7d3f283', 'NC26.M1.ANFR.2', 3, 'numeric', 'Compare linear and exponential growth', 'Plan A pays 1 cent on day 1, 2 cents on day 2, 4 cents on day 3, and keeps doubling each day. Plan B pays 20 cents on day 1, 40 cents on day 2, 60 cents on day 3, and keeps adding 20 cents each day. On what day does Plan A''s payment first exceed Plan B''s payment?', '[]', '9', NULL, 'On day $n$, Plan A pays $2^{n-1}$ cents and Plan B pays $20n$ cents. Day 8: 128 compared with 160. Day 9: 256 compared with 180. Plan A first pays more on day 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A on day n: 2^(n-1) cents; B: 20n cents. Day 7: 64 vs 140; day 8: 128 vs 160; day 9: 256 vs 180. A first exceeds B on day 9.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
