INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('821c4c86-761e-4c39-a606-913e0f414c72', 'NC26.M1.ANFR.3', 1, 'choice', 'Evaluate a function written in function notation', 'If $f(x) = x + 8$, which statement is true?', '["$f(5) = 40$","$f(5) = 13$","$f(13) = 5$","$f(5) = 3$"]', '$f(5) = 13$', NULL, '$f(5) = 5 + 8 = 13$. The statement $f(5) = 40$ multiplies instead of adding, $f(13) = 5$ swaps the input and the output, and $f(5) = 3$ subtracts.', 'checked', '{"lint":[],"solve":{"answer":"$f(5) = 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(5) = 5 + 8 = 13 (true). f(13) = 21, not 5; f(5) is not 3 or 40.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
