INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c01af73f-47ce-45b2-b023-ec638ba6c26b', 'NC26.M1.ANFR.3', 1, 'choice', 'Find the domain of a function', 'A store lets each customer buy 1, 2, 3, 4 or 5 notebooks. A function gives the cost of $n$ notebooks. Which set is the domain of this function?', '["$\\{1, 2, 3, 4, 5\\}$","All real numbers","The set of possible costs","All real numbers between 1 and 5"]', '$\{1, 2, 3, 4, 5\}$', NULL, 'The domain is the set of possible inputs. The inputs are the numbers of notebooks a customer may buy: 1, 2, 3, 4 and 5. The costs are the outputs, which make up the range.', 'checked', '{"lint":[],"solve":{"answer":"$\\{1, 2, 3, 4, 5\\}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The inputs are the allowed numbers of notebooks: 1, 2, 3, 4, 5. Domain = {1, 2, 3, 4, 5}. Not every real number between 1 and 5 (no fractional notebooks); costs are the range.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
