INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf709287-3ab5-4128-88bf-ca1e7d0a974f', 'NC26.M1.ANFR.3', 1, 'choice', 'Find the domain of a function', 'The function $f(x) = 3x + 1$ can be used with any real number $x$. What is its domain?', '["$x > 0$","$x \\ge 1$","All real numbers","$x \\ge 0$"]', 'All real numbers', NULL, 'Any real number can be multiplied by 3 and then have 1 added, so every real number is an allowed input. The domain is all real numbers.', 'checked', '{"lint":[],"solve":{"answer":"All real numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any real x may be used, so the domain is all real numbers.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
