INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('924f9dc7-0462-4b92-90a5-80c724000b05', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find the range of a function', 'Let $f(x) = 2x + 1$ with domain $\{0, 1, 2, 3\}$. What is the largest number in the range?', '[]', '7', '2*3+1', 'The outputs are $f(0) = 1$, $f(1) = 3$, $f(2) = 5$ and $f(3) = 7$. The largest is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0)=1, f(1)=3, f(2)=5, f(3)=7. Range {1,3,5,7}; largest is 7.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
