INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4150abd4-3fb6-4542-956d-1cf9e518d207', 'NC26.M1.ANFR.3', 1, 'choice', 'Find the range of a function', 'The function $f(x) = 2x$ is defined for all real numbers $x$. What is its range?', '["$y > 0$","All real numbers","$y \\ge 0$","All whole numbers"]', 'All real numbers', NULL, 'Any real number $y$ is an output, because $x = y \div 2$ gives $f(x) = y$ (negative outputs come from negative inputs). So the range is all real numbers.', 'checked', '{"lint":[],"solve":{"answer":"All real numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"For any real y, x = y/2 gives f(x) = y. Range is all real numbers.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43a70170-6a68-4cb5-8d09-07615bfb6b2a', 'NC26.M1.ANFR.3', 1, 'choice', 'Decide whether a function is discrete or continuous', 'Which quantity is discrete?', '["The number of cars in a parking lot","The weight of a bag of apples","The time it takes to run a race","The temperature of a room"]', 'The number of cars in a parking lot', NULL, 'A discrete quantity is counted in separate values, such as whole numbers. Cars can be counted: 0, 1, 2, and so on. Weight, time and temperature can take any value in a range, so they are continuous.', 'checked', '{"lint":[],"solve":{"answer":"The number of cars in a parking lot","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cars are counted in whole numbers -> discrete. Time, weight and temperature are measured and can take any value in an interval -> continuous.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
