INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('625a3b09-0072-4128-a777-d6793640acd9', 'NC26.M1.ANFR.3', 1, 'choice', 'Decide whether a function is discrete or continuous', 'Which quantity is continuous?', '["The number of tickets sold","The amount of juice in a glass as it is poured","The number of students absent","The number of goals scored"]', 'The amount of juice in a glass as it is poured', NULL, 'A continuous quantity can take any value in a range, including parts of a unit. The amount of juice can be 100.5 milliliters or 100.52 milliliters. Tickets, students and goals are counted in whole numbers, so they are discrete.', 'checked', '{"lint":[],"solve":{"answer":"The amount of juice in a glass as it is poured","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Amount of juice being poured can take any value -> continuous. Students absent, goals, tickets are counts -> discrete.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f60f6b88-8cc5-44d4-b657-06b6f3b2e6d4', 'NC26.M1.ANFR.3', 1, 'choice', 'Decide whether a function is discrete or continuous', 'A function gives the cost of $n$ pencils, where $n$ is 0, 1, 2, 3, and so on. Is the function discrete or continuous, and why?', '["Continuous, because $n$ can be any number","Continuous, because the cost goes up steadily","Continuous, because the cost can be any amount of money","Discrete, because $n$ can only be a whole number"]', 'Discrete, because $n$ can only be a whole number', NULL, 'You cannot buy 2.5 pencils, so the inputs are only whole numbers. A function whose inputs are separate values like this is discrete.', 'checked', '{"lint":[],"solve":{"answer":"Discrete, because $n$ can only be a whole number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inputs n are 0, 1, 2, 3, ... (whole numbers only), so the graph is separate points -> discrete.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81780468-bc7d-4749-86a4-234780601f1f', 'NC26.M1.ANFR.3', 1, 'choice', 'Decide whether a function is discrete or continuous', 'What does the graph of a discrete function look like?', '["A solid line with no breaks","A smooth curve with no breaks","A set of separate points","A shaded region"]', 'A set of separate points', NULL, 'A discrete function is defined only at separate input values, so its graph is separate points. A solid line or a smooth curve with no breaks is the graph of a continuous function.', 'checked', '{"lint":[],"solve":{"answer":"A set of separate points","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A discrete function is defined only at separate input values, so its graph is a set of separate (unconnected) points.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d51a0277-e26f-4bf5-9de9-c2d510f7e210', 'NC26.M1.ANFR.3', 1, 'choice', 'Tell growth from decay and find the factor or rate', 'Which function shows exponential growth?', '["$f(x) = 3(0.5)^x$","$f(x) = 1.5x$","$f(x) = 0.5(0.9)^x$","$f(x) = 3(1.5)^x$"]', '$f(x) = 3(1.5)^x$', NULL, 'Exponential growth has $x$ in the exponent and a base greater than 1. In $3(1.5)^x$ the base is 1.5. The bases 0.5 and 0.9 give decay, and $1.5x$ is linear, not exponential.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 3(1.5)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exponential growth needs a(b)^x with a > 0, b > 1. 3(1.5)^x: b = 1.5 > 1 -> growth. 0.5(0.9)^x and 3(0.5)^x are decay; 1.5x is linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e344444-f90c-4a69-9822-4bb7189e4c4b', 'NC26.M1.ANFR.3', 1, 'numeric', 'Tell growth from decay and find the factor or rate', 'In the function $f(x) = 6(3)^x$, what is the growth factor?', '[]', '3', NULL, 'An exponential function $f(x) = a \cdot b^x$ has initial value $a$ and growth factor $b$. Here $a = 6$ and $b = 3$, so the growth factor is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x) = 6(3)^x: base 3 is the growth factor.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('744c9f07-710a-4c33-8048-fc7e0cb0a7b4', 'NC26.M1.ANFR.3', 1, 'numeric', 'Tell growth from decay and find the factor or rate', 'What is the initial value (the value when $x = 0$) of $f(x) = 40(0.5)^x$?', '[]', '40', '40*0.5^0', '$f(0) = 40 \times 0.5^0 = 40 \times 1 = 40$. In $f(x) = a \cdot b^x$ the initial value is $a$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = 40 * 0.5^0 = 40.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c1871ff-fb65-4d5d-a369-0199e4ab6979', 'NC26.M1.ANFR.3', 1, 'choice', 'Tell growth from decay and find the factor or rate', 'The value of a car is multiplied by 0.85 every year. What kind of change is this?', '["Exponential growth","Exponential decay","Linear decay","Linear growth"]', 'Exponential decay', NULL, 'The value is multiplied by the same number each year, so the change is exponential. The number 0.85 is less than 1, so the value gets smaller: exponential decay.', 'checked', '{"lint":[],"solve":{"answer":"Exponential decay","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying by a constant factor 0.85 (between 0 and 1) each year -> exponential decay.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a7646ea-84a7-4e80-af53-c62f4f5d49c3', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find and use an average rate of change', 'A plant is 12 centimeters tall at week 2 and 30 centimeters tall at week 5. What is its average rate of change, in centimeters per week?', '[]', '6', '(30-12)/(5-2)', 'Average rate of change = change in height $\div$ change in time $= (30 - 12) \div (5 - 2) = 18 \div 3 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(30 - 12)/(5 - 2) = 18/3 = 6 cm per week.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('998c562c-5290-422d-81c6-6974ef04f1e6', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find and use an average rate of change', 'Let $f(x) = 4x + 3$. What is the average rate of change of $f$ from $x = 1$ to $x = 5$?', '[]', '4', '((4*5+3)-(4*1+3))/(5-1)', '$f(1) = 7$ and $f(5) = 23$. The average rate of change is $(23 - 7) \div (5 - 1) = 16 \div 4 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 7, f(5) = 23. (23 - 7)/(5 - 1) = 16/4 = 4.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5203e38-fac2-4383-9459-5d31caee8ffc', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find and use an average rate of change', 'A tank holds 90 liters at minute 0 and 60 liters at minute 5. What is the average rate of change of the amount of water, in liters per minute?', '[]', '-6', '(60-90)/5', 'The change is $60 - 90 = -30$ liters over 5 minutes, so the average rate of change is $-30 \div 5 = -6$ liters per minute.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(60 - 90)/(5 - 0) = -30/5 = -6 liters per minute.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3978dc4-5678-4e47-9217-cfb94a30506a', 'NC26.M1.ANFR.3', 1, 'choice', 'Find and use an average rate of change', 'Which expression gives the average rate of change of a function $f$ from $x = a$ to $x = b$?', '["$\\frac{f(b) - f(a)}{b - a}$","$\\frac{f(b) - f(a)}{a - b}$","$\\frac{f(b) + f(a)}{b + a}$","$\\frac{b - a}{f(b) - f(a)}$"]', '$\frac{f(b) - f(a)}{b - a}$', NULL, 'The average rate of change is the change in output divided by the change in input: $\frac{f(b) - f(a)}{b - a}$. The other expressions flip the sign of the denominator, add instead of subtract, or turn the fraction upside down.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{f(b) - f(a)}{b - a}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Average rate of change = change in output / change in input = (f(b) - f(a))/(b - a).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56f06fff-d178-411d-a106-9ae2850f114b', 'NC26.M1.ANFR.3', 1, 'choice', 'Compare two functions', 'Let $f(x) = 3x + 2$ and $g(x) = 5x + 1$. Which function has the greater rate of change?', '["$f$, because 2 is greater than 1","They have the same rate of change","$g$, because 5 is greater than 3","$f$, because 3 is greater than 1"]', '$g$, because 5 is greater than 3', NULL, 'In $y = mx + b$ the rate of change is $m$. For $f$ it is 3 and for $g$ it is 5, so $g$ changes faster. The numbers 2 and 1 are the starting values, not the rates.', 'checked', '{"lint":[],"solve":{"answer":"$g$, because 5 is greater than 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rates (slopes): f has 3, g has 5. g has the greater rate of change because 5 > 3. The constants 2 and 1 are intercepts.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8bc836a4-8858-4518-aa92-946fef6256d3', 'NC26.M1.ANFR.3', 1, 'numeric', 'Compare two functions', 'Let $f(x) = 2x + 6$ and $g(x) = 3x$. How much greater is $f(2)$ than $g(2)$?', '[]', '4', '(2*2+6)-3*2', '$f(2) = 2 \times 2 + 6 = 10$ and $g(2) = 3 \times 2 = 6$. The difference is $10 - 6 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(2) = 4 + 6 = 10. g(2) = 6. 10 - 6 = 4.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bae06fd-1df1-48a1-97d8-208a8fd47889', 'NC26.M1.ANFR.3', 1, 'choice', 'Compare two functions', 'Function $f$ has $f(0) = 2$, $f(1) = 4$, $f(2) = 6$ and $f(3) = 8$. Function $g$ is $g(x) = 3x + 1$. Which function has the greater rate of change?', '["$g$, with a rate of 3 compared with 2","$f$, with a rate of 2 compared with 1","They have the same rate of change, 2","$f$, because $f(0) = 2$ is greater than $g(0) = 1$"]', '$g$, with a rate of 3 compared with 2', NULL, 'The values of $f$ go up by 2 each time $x$ goes up by 1, so its rate is 2. For $g(x) = 3x + 1$ the rate is 3. So $g$ has the greater rate of change.', 'checked', '{"lint":[],"solve":{"answer":"$g$, with a rate of 3 compared with 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f rises 2 per unit (2,4,6,8): rate 2. g(x) = 3x + 1: rate 3. g has the greater rate, 3 vs 2.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('280e8909-ca47-4754-8697-fd7dc79926df', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate a function in context', 'A plant''s height after $w$ weeks is $h(w) = 4 + 2.5w$ centimeters. What is $h(6)$, in centimeters?', '[]', '19', '4+2.5*6', '$h(6) = 4 + 2.5(6) = 4 + 15 = 19$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(6) = 4 + 2.5(6) = 4 + 15 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1340d717-16a0-42d9-8467-a6288724dcda', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find an average rate of change', 'For a function $f$, $f(2) = 7$ and $f(6) = 19$. What is the average rate of change of $f$ from $x = 2$ to $x = 6$?', '[]', '3', '(19-7)/(6-2)', 'Average rate of change is the change in output divided by the change in input: $\frac{19 - 7}{6 - 2} = \frac{12}{4} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(19 - 7)/(6 - 2) = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44484717-1c68-4b81-83b9-774d4fd9d808', 'NC26.M1.ANFR.3', 2, 'choice', 'Decide whether a function in context is discrete or continuous', 'A car travels at a steady 60 miles per hour, so after $t$ hours it has gone $d(t) = 60t$ miles, where $t$ can be any time from 0 to 5 hours. Which statement is true?', '["The graph is discrete because distance is measured in miles","The graph is continuous because $t$ can be any value from 0 to 5","The graph is discrete because 60 is a whole number","The graph is continuous only because it passes through the origin"]', 'The graph is continuous because $t$ can be any value from 0 to 5', NULL, 'A function is continuous when its inputs can be any value in an interval. Time can be any value from 0 to 5 hours, including parts of an hour, so the graph is continuous. The units and the number 60 do not decide this.', 'checked', '{"lint":[],"solve":{"answer":"The graph is continuous because $t$ can be any value from 0 to 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Time can take any value in [0, 5], so the graph is an unbroken segment: continuous for that reason. The other options give wrong reasons.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a0faf8a-8426-4d6e-b56b-a6c0129017b3', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate a function written in function notation', 'Let $f(x) = 3x - 8$. For what value of $x$ is $f(x) = 19$?', '[]', '9', '(19+8)/3', 'Solve $3x - 8 = 19$. Add 8: $3x = 27$. Divide by 3: $x = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 8 = 19 -> 3x = 27 -> x = 9.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed39b9f9-a98c-452a-81b3-a63391e5ac3d', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate a function written in function notation', 'Let $f(x) = 2x + 3$ and $g(x) = x - 4$. What is $f(5) - g(5)$?', '[]', '12', '(2*5+3)-(5-4)', '$f(5) = 2 \times 5 + 3 = 13$ and $g(5) = 5 - 4 = 1$. So $f(5) - g(5) = 13 - 1 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(5) = 13, g(5) = 1. 13 - 1 = 12.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14853372-684f-4c02-b036-be48de218756', 'NC26.M1.ANFR.3', 2, 'choice', 'Evaluate a function written in function notation', 'If $f(x) = 5 - 2x$, which expression is equal to $f(a + 1)$?', '["$6 - 2a$","$8 - 2a$","$4 - 2a$","$3 - 2a$"]', '$3 - 2a$', NULL, 'Replace $x$ with $a + 1$: $f(a + 1) = 5 - 2(a + 1) = 5 - 2a - 2 = 3 - 2a$. The expression $6 - 2a$ forgets to multiply the 1 by $-2$, and $4 - 2a$ subtracts 1 instead of 2.', 'checked', '{"lint":[],"solve":{"answer":"$3 - 2a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(a+1) = 5 - 2(a+1) = 5 - 2a - 2 = 3 - 2a.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('642e7a73-0902-4a7d-8ca4-1c682cfdba54', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate and interpret a function in context', 'The value of a car after $t$ years is $V(t) = 20000(0.9)^t$ dollars. What is its value after 2 years, in dollars?', '[]', '16200', '20000*0.9^2', '$V(2) = 20000 \times 0.9^2 = 20000 \times 0.81 = 16200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"16200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V(2) = 20000 * 0.9^2 = 20000 * 0.81 = 16200.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83233fc8-7388-4a7d-96db-d412b0a700f7', 'NC26.M1.ANFR.3', 2, 'choice', 'Evaluate and interpret a function in context', 'The number of bacteria in a dish is $B(t) = 500(2)^t$, where $t$ is in hours. What does $B(0) = 500$ tell you?', '["There were 500 bacteria after 1 hour","There were 500 bacteria at the start","The number of bacteria doubles every 500 hours","There were no bacteria after 500 hours"]', 'There were 500 bacteria at the start', NULL, 'The input $t = 0$ is the start (zero hours have passed). The output $B(0) = 500$ is the number of bacteria then, so there were 500 bacteria at the start.', 'checked', '{"lint":[],"solve":{"answer":"There were 500 bacteria at the start","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t = 0 is the start; B(0) = 500 means 500 bacteria at the start.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6866eb0c-8bcc-48ce-9888-86ba6fc8a920', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate and interpret a function in context', 'Renting a bike costs $C(h) = 8 + 3h$ dollars for $h$ hours. For how many hours was the bike rented if the cost was 29 dollars?', '[]', '7', '(29-8)/3', 'Solve $8 + 3h = 29$. Subtract 8: $3h = 21$. Divide by 3: $h = 7$ hours.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 3h = 29 -> 3h = 21 -> h = 7 hours.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
