VALUES ('26ee433d-02a3-46ec-b748-e13d1c6ea556', 'NC26.M1.ANFR.4', 1, 'choice', 'Write a line in slope-intercept form', 'Which equation has slope $-4$ and y-intercept 7?', '["$y = 7x - 4$","$y = 4x + 7$","$y = -4x - 7$","$y = -4x + 7$"]', '$y = -4x + 7$', NULL, 'In $y = mx + b$, $m$ is the slope and $b$ is the y-intercept. Here $m = -4$ and $b = 7$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -4x + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b with m = -4, b = 7: y = -4x + 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
