VALUES ('c7584831-ebd5-4ad3-83ea-750a4cbf6a2f', 'NC26.M1.ANFR.4', 2, 'choice', 'Evaluate a recursive rule for a geometric sequence', 'A sequence has $a_1 = 5$ and $a_n = 4a_{n-1}$ for $n \ge 2$. What is $a_3$?', '["13","64","320","80"]', '80', '5*4*4', '$a_2 = 4 \cdot 5 = 20$ and $a_3 = 4 \cdot 20 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=5, a2=20, a3=80.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
