INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5e2154f-f5b0-4a74-883b-576589629d34', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a recursive rule for a sequence', 'On day 1 a patch of lilies covers 2 square meters of a pond. Each day the patch covers 3 times the area it covered the day before. Which recursive rule gives the area $A_n$ on day $n$?', '["$A_1 = 2$, $A_n = A_{n-1} + 3$","$A_1 = 3$, $A_n = 2A_{n-1}$","$A_1 = 2$, $A_n = 2A_{n-1} + 3$","$A_1 = 2$, $A_n = 3A_{n-1}$"]', '$A_1 = 2$, $A_n = 3A_{n-1}$', NULL, 'The area starts at 2 and is multiplied by 3 each day, so $A_1 = 2$ and $A_n = 3A_{n-1}$.', 'checked', '{"lint":[],"solve":{"answer":"$A_1 = 2$, $A_n = 3A_{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A1 = 2, each day triples: A_n = 3A_(n-1).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
