INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3f1464b-e24f-45fb-b748-e1618e19a4ea', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a linear function from a situation', 'A hiker starts at an elevation of 1200 feet and climbs 150 feet for each kilometer walked. Which function gives the elevation $E$, in feet, after $k$ kilometers?', '["$E(k) = 1200k + 150$","$E(k) = 1350k$","$E(k) = 150k + 1200$","$E(k) = 1200 - 150k$"]', '$E(k) = 150k + 1200$', NULL, 'The elevation starts at 1200 and rises 150 per kilometer: $E(k) = 150k + 1200$.', 'checked', '{"lint":[],"solve":{"answer":"$E(k) = 150k + 1200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 1200, plus 150 per km: E(k) = 150k + 1200.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
