INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec683e5f-6cad-4366-86de-3f3d3ed037d2', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write a linear function from a situation', 'A bamboo plant is 18 inches tall now and grows 3 inches each day. After how many days will it be 60 inches tall?', '[]', '14', '(60-18)/3', 'The height is $18 + 3d$. Setting $18 + 3d = 60$ gives $3d = 42$, so $d = 14$ days.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 + 3d = 60, 3d = 42, d = 14.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
