INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d6e0fe9-558f-431c-bd2c-532986de65d7', 'NC26.M1.ANFR.4', 2, 'choice', 'Write and use an exponential function from a situation', 'A sample of 80 grams of a substance halves in mass every year. Which function gives the mass $M$, in grams, after $t$ years?', '["$M(t) = 80 - \\frac{1}{2}t$","$M(t) = \\frac{1}{2} \\cdot 80^t$","$M(t) = 80 \\cdot 2^t$","$M(t) = 80 \\cdot (\\frac{1}{2})^t$"]', '$M(t) = 80 \cdot (\frac{1}{2})^t$', NULL, 'The mass starts at 80 and is multiplied by $\frac{1}{2}$ each year: $M(t) = 80 \cdot (\frac{1}{2})^t$.', 'checked', '{"lint":[],"solve":{"answer":"$M(t) = 80 \\cdot (\\frac{1}{2})^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halves each year: M(t) = 80*(1/2)^t.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
