INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4f3c881-af43-479f-9650-359717982802', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a line in slope-intercept form', 'A line passes through the points $(2, 3)$ and $(4, 11)$. Which equation represents the line?', '["$y = 4x + 5$","$y = 4x - 5$","$y = 4x + 3$","$y = \\frac{1}{4}x - 5$"]', '$y = 4x - 5$', NULL, 'The slope is $\frac{11 - 3}{4 - 2} = 4$. Using $(2, 3)$: $3 = 4 \cdot 2 + b$, so $b = -5$ and $y = 4x - 5$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-3)/(4-2) = 4. 3 = 4*2 + b, b = -5. y = 4x - 5. Check (4, 11): 16 - 5 = 11.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
