VALUES ('b59affc1-6b1d-4c19-9c77-ecc83940aab8', 'NC26.M1.ANFR.4', 2, 'choice', 'Choose a linear or exponential model', 'Which situation is best modeled by an exponential function?', '["A bank balance of 1000 dollars grows by 4% each year","A plumber charges 40 dollars plus 30 dollars per hour","A sunflower grows 3 centimeters each day","A bus travels at 50 miles per hour"]', 'A bank balance of 1000 dollars grows by 4% each year', NULL, 'A percent growth multiplies the amount by the same factor each period, which is exponential. The other three add the same amount each time, which is linear.', 'checked', '{"lint":[],"solve":{"answer":"A bank balance of 1000 dollars grows by 4% each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth by a fixed percent (4% per year) is exponential; the others are constant rates (linear).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c84d0c82-2095-4f60-82a1-330744a2e133', 'NC26.M1.ANFR.4', 2, 'choice', 'Choose a linear or exponential model', 'For $x = 0, 1, 2, 3$, which list of $y$-values comes from a linear function?', '["$y = 4, 8, 16, 32$","$y = 4, 6, 9, 13$","$y = 4, 7, 10, 13$","$y = 4, 12, 36, 108$"]', '$y = 4, 7, 10, 13$', NULL, 'Only 4, 7, 10, 13 goes up by the same amount (3) each time. The others are multiplied by a constant (2 or 3) or have changing differences.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4, 7, 10, 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, 7, 10, 13 has constant difference 3. 4, 6, 9, 13 has differences 2, 3, 4; others are geometric.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8f9e226-d53c-4900-917d-fe2a4b3b1685', 'NC26.M1.ANFR.4', 2, 'numeric', 'Choose a linear or exponential model', 'A function has $f(0) = 3$, $f(1) = 6$ and $f(2) = 12$, and it is exponential. What is $f(4)$?', '[]', '48', '3*2^4', 'Each value is twice the one before, so $f(x) = 3 \cdot 2^x$. Then $f(4) = 3 \cdot 16 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 3, b = 2: f(4) = 3*16 = 48.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
