INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('268f066a-c5ec-4ba8-8d05-6c0b1b1b3327', 'NC26.M1.ANFR.4', 2, 'numeric', 'Choose a linear or exponential model', 'A linear function has $g(0) = 3$, $g(1) = 7$ and $g(2) = 11$. What is $g(5)$?', '[]', '23', '3+4*5', 'The value rises by 4 each step and starts at 3, so $g(x) = 4x + 3$. Then $g(5) = 23$.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x) = 4x + 3. g(5) = 23.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
