INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34474a01-a645-4e9c-94e9-d00c2d830aba', 'NC26.M1.ANFR.4', 2, 'choice', 'Choose a linear or exponential model', 'One table gives $y = 6, 12, 18, 24$ for $x = 1, 2, 3, 4$. A second table gives $y = 6, 12, 24, 48$ for the same $x$ values. Which statement is true?', '["The first table is exponential and the second is linear","Both tables are linear","Both tables are exponential","The first table is linear and the second is exponential"]', 'The first table is linear and the second is exponential', NULL, 'The first table adds 6 each time (linear). The second table doubles each time (exponential).', 'checked', '{"lint":[],"solve":{"answer":"The first table is linear and the second is exponential","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First: +6 each step (linear). Second: x2 each step (exponential).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60716a07-44bb-49cb-99f9-ae217551bde1', 'NC26.M1.ANFR.4', 2, 'numeric', 'Interpret the parts of a linear or exponential function', 'A car''s value, in dollars, after $t$ years is $V(t) = 15000 \cdot 0.9^t$. By what percent does its value drop each year?', '[]', '10', '(1-0.9)*100', 'The factor 0.9 means the car keeps 90% of its value, so it loses $100\% - 90\% = 10\%$ each year.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 0.9 keeps 90%, so drops 10% each year.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f736ec0d-58a3-4126-831d-ef1d6c3099b1', 'NC26.M1.ANFR.4', 2, 'choice', 'Interpret the parts of a linear or exponential function', 'The number of fans of a band is modeled by $N(t) = 200 \cdot 1.5^t$, where $t$ is in months. Which statement is true?', '["The number of fans increases by 1.5 each month","The number of fans increases by 150% each month","The number of fans increases by 50% each month","The number of fans increases by 1.5% each month"]', 'The number of fans increases by 50% each month', NULL, 'A growth factor of 1.5 means the amount is multiplied by 1.5 each month: $1.5 = 1 + 0.5$, an increase of 50%.', 'checked', '{"lint":[],"solve":{"answer":"The number of fans increases by 50% each month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 1.5 = 1 + 0.5: increases by 50% each month.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9902265b-b745-4fd8-93fc-4bceb63a7021', 'NC26.M1.ANFR.4', 2, 'numeric', 'Interpret the parts of a linear or exponential function', 'A bike rental costs $C(h) = 8h + 12$ dollars for $h$ hours. How many dollars does it cost to rent a bike for 45 minutes?', '[]', '18', '8*0.75+12', '45 minutes is 0.75 hours. $C(0.75) = 8 \cdot 0.75 + 12 = 6 + 12 = 18$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 min = 0.75 h. C = 8*0.75 + 12 = 6 + 12 = 18.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
