INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db901b7a-52fd-4a7b-88b1-28c64294d3ef', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for an arithmetic sequence', 'A sequence has $a_1 = 5$ and $a_n = a_{n-1} + 6$ for $n \ge 2$. One term of the sequence is 71. Which term number is it?', '[]', '12', '(71-5)/6+1', 'From 5 to 71 the sequence rises $71 - 5 = 66$, which is $66 \div 6 = 11$ steps after the first term. So 71 is term number $11 + 1 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_n = 5 + 6(n-1) = 71 gives 6(n-1) = 66, n-1 = 11, n = 12.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0c66920-0b63-4f61-af6e-e2519d6b0c3b', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for an arithmetic sequence', 'In a sequence with the rule $a_n = a_{n-1} + d$, the first term is 5 and the fourth term is 20. What is $d$?', '[]', '5', '(20-5)/3', 'There are 3 steps from the first term to the fourth term and the total change is $20 - 5 = 15$. So $d = 15 \div 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a4 = a1 + 3d: 20 = 5 + 3d, d = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22eced56-5029-40ae-b7f2-92209c932a06', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for a geometric sequence', 'A sequence starts with 2, and each term is 3 times the term before it. What is the first term that is greater than 1000?', '[]', '1458', '2*3^6', 'The terms are 2, 6, 18, 54, 162, 486, 1458. The first one greater than 1000 is 1458.', 'checked', '{"lint":[],"solve":{"answer":"1458","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 6, 18, 54, 162, 486, 1458. First term over 1000 is 1458.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dec97742-1b26-470c-94bc-fd651c0b912b', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for a geometric sequence', 'Each term of a geometric sequence is the same multiple of the term before it. The second term is 12 and the third term is 36. What is the fifth term?', '[]', '324', '36*(36/12)^2', 'The multiplier is $36 \div 12 = 3$. The fourth term is $36 \cdot 3 = 108$ and the fifth is $108 \cdot 3 = 324$.', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 36/12 = 3. Fourth 108, fifth 324.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
