INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffe7e810-9db9-419e-af75-259fed6fd8d6', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for a geometric sequence', 'A sequence has $a_1 = 192$ and $a_n = \frac{1}{2}a_{n-1}$ for $n \ge 2$. What is $a_7$?', '[]', '3', '192/2^6', 'Halving 6 times gives 96, 48, 24, 12, 6, 3. So $a_7 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"192, 96, 48, 24, 12, 6, 3. a7 = 192/64 = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9630197-b82d-43d8-8fa6-da9cb9b64b28', 'NC26.M1.ANFR.4', 3, 'choice', 'Evaluate a recursive rule for a geometric sequence', 'In a sequence, each term is the same positive multiple of the term before it. If the first term is 3 and the third term is 48, what is that multiple?', '["8","16","15","4"]', '4', '4', 'Multiplying twice by the same number $r$ turns 3 into 48, so $r^2 = 48 \div 3 = 16$. Since $r$ is positive, $r = 4$. Check: $3 \to 12 \to 48$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3r^2 = 48, r^2 = 16, r = 4 (positive).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e81576f-365a-437b-a4db-1049f9adb654', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a recursive rule for a sequence', 'Which recursive rule produces the sequence 5, 8, 14, 26, 50, ...?', '["$a_1 = 5$, $a_n = 2a_{n-1} - 2$","$a_1 = 5$, $a_n = 2a_{n-1}$","$a_1 = 5$, $a_n = a_{n-1} + 3$","$a_1 = 5$, $a_n = 2a_{n-1} + 2$"]', '$a_1 = 5$, $a_n = 2a_{n-1} - 2$', NULL, 'Try doubling and then subtracting 2: $2 \cdot 5 - 2 = 8$, $2 \cdot 8 - 2 = 14$, $2 \cdot 14 - 2 = 26$, $2 \cdot 26 - 2 = 50$. The other rules fail on the second or third term.', 'checked', '{"lint":[],"solve":{"answer":"$a_1 = 5$, $a_n = 2a_{n-1} - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Test 2a-2: 5 -> 8 -> 14 -> 26 -> 50. Matches. 2a gives 10; 2a+2 gives 12; a+3 gives 8 then 11.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e623dfda-6d86-453a-8b9b-c89136613a00', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a recursive rule for a sequence', 'A pool holds 500 gallons of water on day 0. Each day it loses 4% of the water it held the day before. Which recursive rule gives the amount $V_n$, in gallons, on day $n$?', '["$V_0 = 500$, $V_n = 0.04V_{n-1}$","$V_0 = 500$, $V_n = 0.96V_{n-1}$","$V_0 = 500$, $V_n = V_{n-1} - 4$","$V_0 = 500$, $V_n = 1.04V_{n-1}$"]', '$V_0 = 500$, $V_n = 0.96V_{n-1}$', NULL, 'Losing 4% leaves 96% of the water, so each day''s amount is $0.96$ times the day before: $V_n = 0.96V_{n-1}$.', 'checked', '{"lint":[],"solve":{"answer":"$V_0 = 500$, $V_n = 0.96V_{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Losing 4% keeps 96%: V_n = 0.96 V_(n-1), V0 = 500.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('004aec33-35dd-4056-9c83-6f618c3b2c61', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a linear function from a situation', 'Water drains from a tank at a constant rate. After 3 minutes the tank holds 90 liters, and after 5 minutes it holds 70 liters. Which function gives the liters $V$ in the tank after $t$ minutes?', '["$V(t) = 90 - 10t$","$V(t) = 120 + 10t$","$V(t) = 90 - 20t$","$V(t) = 120 - 10t$"]', '$V(t) = 120 - 10t$', NULL, 'The tank loses $90 - 70 = 20$ liters in 2 minutes, which is 10 liters per minute. Going back 3 minutes from $t = 3$ gives $90 + 30 = 120$ liters at the start. So $V(t) = 120 - 10t$.', 'checked', '{"lint":[],"solve":{"answer":"$V(t) = 120 - 10t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate (70-90)/(5-3) = -10 L/min. V(3) = 90 so V(0) = 90 + 30 = 120. V(t) = 120 - 10t. Check V(5) = 70.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
