INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e47e4c85-79c3-4007-a2f5-01bf610eb7f2', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write a linear function from a situation', 'A tub drains at a constant rate. After 5 minutes it holds 300 gallons, and after 8 minutes it holds 264 gallons. After how many minutes from the start will it be empty?', '[]', '30', '(300+(300-264)/(8-5)*5)/((300-264)/(8-5))', 'The tub loses $300 - 264 = 36$ gallons in 3 minutes, which is 12 gallons per minute. At the start it held $300 + 12 \cdot 5 = 360$ gallons. It is empty after $360 \div 12 = 30$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate (264-300)/3 = -12 gal/min. V(0) = 300 + 5*12 = 360. Empty when 360 - 12t = 0, t = 30.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8e95159-6ad4-4579-857e-5ea6b5fe7c38', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a linear function from a situation', 'A printer prints 45 pages per minute. Which function gives the number of pages $P$ printed after $s$ seconds?', '["$P(s) = 0.75s$","$P(s) = 45s$","$P(s) = \\frac{4}{3}s$","$P(s) = 2700s$"]', '$P(s) = 0.75s$', NULL, 'There are 60 seconds in a minute, so the printer prints $45 \div 60 = 0.75$ pages each second: $P(s) = 0.75s$.', 'checked', '{"lint":[],"solve":{"answer":"$P(s) = 0.75s$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 pages per 60 s = 0.75 pages per second. P(s) = 0.75s.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed8121ff-bffb-4225-b92f-552e9e230988', 'NC26.M1.ANFR.4', 3, 'choice', 'Write and use an exponential function from a situation', 'A culture starts with 50 cells and doubles every 3 hours. Which function gives the number of cells $N$ after $t$ hours?', '["$N(t) = 50 \\cdot 2^{3t}$","$N(t) = 50 \\cdot 2^{t/3}$","$N(t) = 50 \\cdot 2^t$","$N(t) = 50 \\cdot 3^t$"]', '$N(t) = 50 \cdot 2^{t/3}$', NULL, 'The culture doubles once for every 3 hours, so the number of doublings is $t \div 3$. That gives $N(t) = 50 \cdot 2^{t/3}$. (Check: at $t = 3$ the value is $100$.)', 'checked', '{"lint":[],"solve":{"answer":"$N(t) = 50 \\cdot 2^{t/3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling every 3 hours means t/3 doublings: N(t) = 50*2^(t/3).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04374e53-8571-4d14-a6ca-feb8c30bf164', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an exponential function from a situation', 'The function $f(x) = a \cdot b^x$ with $b > 0$ passes through the points $(0, 6)$ and $(2, 54)$. What is $b$?', '[]', '3', '3', 'At $x = 0$, $f(0) = a = 6$. At $x = 2$, $6b^2 = 54$, so $b^2 = 9$. Since $b > 0$, $b = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = a = 6. f(2) = 6b^2 = 54, b^2 = 9, b = 3 (b > 0).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d40d894-5c2d-4b6d-8010-8d8dbc850ef8', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an exponential function from a situation', 'The function $f(x) = a \cdot b^x$ with $b > 0$ passes through the points $(1, 12)$ and $(3, 108)$. What is $a$?', '[]', '4', '4', 'Going from $x = 1$ to $x = 3$ multiplies the value by $108 \div 12 = 9$, which is $b^2$. So $b = 3$. Then $f(1) = 3a = 12$ gives $a = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ab = 12, ab^3 = 108. Dividing: b^2 = 9, b = 3. a = 12/3 = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a834bd63-c515-4ef3-b9c9-5bab68eab8b7', 'NC26.M1.ANFR.4', 3, 'choice', 'Write and use an exponential function from a situation', 'An account starts with 2000 dollars and earns 3% interest every 6 months. Which function gives the balance $B$, in dollars, after $y$ years?', '["$B(y) = 2000 \\cdot 1.03^y$","$B(y) = 2000 \\cdot 1.03^{y/2}$","$B(y) = 2000 \\cdot 1.03^{2y}$","$B(y) = 2000 \\cdot 1.3^{2y}$"]', '$B(y) = 2000 \cdot 1.03^{2y}$', NULL, 'There are 2 six-month periods in each year, so after $y$ years there are $2y$ periods. Each period multiplies the balance by 1.03: $B(y) = 2000 \cdot 1.03^{2y}$.', 'checked', '{"lint":[],"solve":{"answer":"$B(y) = 2000 \\cdot 1.03^{2y}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two 6-month periods per year, factor 1.03 each: B(y) = 2000*1.03^(2y).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19c6df49-9eb7-4b69-abc6-06bac26e676e', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a line in slope-intercept form', 'Which equation is $3x - 4y = 12$ written in slope-intercept form?', '["$y = \\frac{3}{4}x - 3$","$y = \\frac{3}{4}x + 3$","$y = -\\frac{3}{4}x - 3$","$y = 3x - 12$"]', '$y = \frac{3}{4}x - 3$', NULL, 'Subtract $3x$: $-4y = -3x + 12$. Divide every term by $-4$: $y = \frac{3}{4}x - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{3}{4}x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4y = -3x + 12, y = (3/4)x - 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a88c1532-1f17-474e-b798-6aae6e99b47a', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write a line in slope-intercept form', 'A line passes through the points $(4, 1)$ and $(10, 4)$. What is its y-intercept?', '[]', '-1', '1-4*(4-1)/(10-4)', 'The slope is $\frac{4 - 1}{10 - 4} = \frac{1}{2}$. Using $(4, 1)$: $1 = \frac{1}{2} \cdot 4 + b$, so $b = 1 - 2 = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (4-1)/(10-4) = 1/2. 1 = (1/2)*4 + b, b = -1.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5b0cb32-11cd-41de-a183-ced54d24b4cb', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write a line in slope-intercept form', 'A line has slope $-\frac{2}{3}$ and passes through the point $(6, 1)$. What is its y-intercept?', '[]', '5', '1+6*2/3', 'Put the point into $y = mx + b$: $1 = -\frac{2}{3} \cdot 6 + b = -4 + b$. So $b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 = (-2/3)*6 + b = -4 + b, b = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65f9fa3b-903d-4877-b564-aab02ff63c73', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a line in slope-intercept form', 'A line passes through $(0, -1)$ and has the same slope as the line through $(1, 2)$ and $(3, 8)$. Which is its equation?', '["$y = 3x + 1$","$y = 3x - 1$","$y = 2x - 1$","$y = \\frac{1}{3}x - 1$"]', '$y = 3x - 1$', NULL, 'The slope of the line through $(1, 2)$ and $(3, 8)$ is $\frac{8 - 2}{3 - 1} = 3$. The new line has slope 3 and y-intercept $-1$, so $y = 3x - 1$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (8-2)/(3-1) = 3. Through (0, -1): y = 3x - 1.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3eccfd68-3a15-4fbf-a098-9116dcd5cb4e', 'NC26.M1.ANFR.4', 3, 'choice', 'Choose a linear or exponential model', 'A table gives $y = 5, 20, 80, 320$ for $x = 0, 2, 4, 6$. Which function fits all four pairs?', '["$y = 5 \\cdot 4^x$","$y = 5 \\cdot 2^x$","$y = 7.5x + 5$","$y = 20 \\cdot 2^x$"]', '$y = 5 \cdot 2^x$', NULL, 'At $x = 0$, $y = 5$, so $a = 5$. When $x$ increases by 2, $y$ is multiplied by 4, so $b^2 = 4$ and $b = 2$. Check: $5 \cdot 2^2 = 20$, $5 \cdot 2^4 = 80$, $5 \cdot 2^6 = 320$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5 \\cdot 2^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x up by 2 multiplies y by 4, so b^2 = 4, b = 2, a = 5. y = 5*2^x: 5, 20, 80, 320. 7.5x+5 gives 35 at x=4; 5*4^x gives 80 at x=2; 20*2^x gives 20 at x=0.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63c6bce6-f4f5-4ec1-a9b5-4f6fd3d22325', 'NC26.M1.ANFR.4', 3, 'numeric', 'Choose a linear or exponential model', 'Job A pays 100 dollars on day 1 and 20 dollars more each day than the day before. Job B pays 5 dollars on day 1 and doubles its pay each day. On which day does Job B first pay more than Job A?', '[]', '7', NULL, 'Job A pays $100 + 20(n - 1)$ and Job B pays $5 \cdot 2^{n-1}$ on day $n$. Day 6: A pays 200 and B pays 160. Day 7: A pays 220 and B pays 320. So day 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 100+20(n-1); B: 5*2^(n-1). Day 5: A 180, B 80. Day 6: A 200, B 160. Day 7: A 220, B 320. First on day 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29be13a3-94ea-45e0-8267-dc7e25e973a7', 'NC26.M1.ANFR.4', 3, 'numeric', 'Choose a linear or exponential model', 'What is the least positive whole number $x$ for which $2^x$ is greater than $10x$?', '[]', '6', NULL, '$x = 5$: $2^5 = 32$ and $10 \cdot 5 = 50$, so no. $x = 6$: $2^6 = 64$ and $10 \cdot 6 = 60$, so yes. Smaller values fail too ($2 < 10$, $4 < 20$, $8 < 30$, $16 < 40$).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=1: 2 vs 10; x=2: 4 vs 20; x=3: 8 vs 30; x=4: 16 vs 40; x=5: 32 vs 50; x=6: 64 vs 60 -> true. Least is 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f0c8f0-9f11-4209-a147-691e7fac7b8b', 'NC26.M1.ANFR.4', 3, 'numeric', 'Choose a linear or exponential model', 'Plan A starts with 100 dollars and adds 20 dollars each month. Plan B starts with 100 dollars and grows by 20% each month. How many more dollars does Plan B have than Plan A after 3 months?', '[]', '12.8', '100*1.2^3-(100+20*3)', 'Plan A has $100 + 20 \cdot 3 = 160$ dollars. Plan B has $100 \cdot 1.2^3 = 172.8$ dollars. The difference is $172.8 - 160 = 12.8$.', 'checked', '{"lint":[],"solve":{"answer":"12.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 100 + 3*20 = 160. B: 100*1.2^3 = 100*1.728 = 172.8. Difference 12.8.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed1d7cc2-b272-4f8c-9766-51d9cdbd48b5', 'NC26.M1.ANFR.4', 3, 'numeric', 'Interpret the parts of a linear or exponential function', 'A population grows by 20% each year. By what percent has it grown in total after 2 years?', '[]', '44', '(1.2^2-1)*100', 'After 2 years the population is multiplied by $1.2^2 = 1.44$. That is a total increase of 44%, not 40%.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2^2 = 1.44, so total growth 44%.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8929cd27-4092-48e0-8968-58c732099e72', 'NC26.M1.ANFR.4', 3, 'choice', 'Interpret the parts of a linear or exponential function', 'The function $f(x) = a \cdot b^x$ has $f(0) = 8$ and $f(1) = 12$. Which statement is true about $f$?', '["$f$ increases by 4 each time $x$ increases by 1","$f$ increases by 50% each time $x$ increases by 1","$f$ increases by 12% each time $x$ increases by 1","$f$ doubles each time $x$ increases by 1"]', '$f$ increases by 50% each time $x$ increases by 1', NULL, '$f(0) = a = 8$ and $f(1) = 8b = 12$, so $b = 1.5$. A factor of 1.5 is an increase of 50% each step. (Going from 8 to 12 is a rise of 4 only the first time.)', 'checked', '{"lint":[],"solve":{"answer":"$f$ increases by 50% each time $x$ increases by 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 8, b = 12/8 = 1.5: increases by 50% per unit of x.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f5d3ffd-a844-440a-b7d6-d430502e6898', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an explicit rule for a sequence', 'The explicit rule for a sequence is $a_n = 5 \cdot 2^{n-1}$. Which term number $n$ has the value 320?', '[]', '7', '7', '$5 \cdot 2^{n-1} = 320$ gives $2^{n-1} = 64 = 2^6$, so $n - 1 = 6$ and $n = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*2^(n-1) = 320, 2^(n-1) = 64, n-1 = 6, n = 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83752e9b-5f57-42ae-8854-de6eb23c5897', 'NC26.M1.ANFR.4', 3, 'choice', 'Write and use an explicit rule for a sequence', 'A sequence has the recursive rule $a_1 = 6$ and $a_n = a_{n-1} + 4$. Which explicit rule gives the same sequence?', '["$a_n = 4n + 6$","$a_n = 4n + 2$","$a_n = 6n + 4$","$a_n = 4n - 2$"]', '$a_n = 4n + 2$', NULL, 'The terms are 6, 10, 14, ..., so the rule is $4n + b$. At $n = 1$, $4 + b = 6$ gives $b = 2$: $a_n = 4n + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 4n + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_n = 6 + 4(n-1) = 4n + 2. Check n=1: 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6a90908-3252-4a4f-8737-e3757d70fe82', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an explicit rule for a sequence', 'The first level of a parking garage has 140 spaces, and each higher level has 6 fewer spaces than the level below it. How many spaces are on level 15?', '[]', '56', '140-6*14', 'Level 15 is 14 levels above level 1, so it has $140 - 6 \cdot 14 = 140 - 84 = 56$ spaces.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"140 - 6*(15-1) = 140 - 84 = 56.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a652008c-eb8c-4321-a96e-4a63cea25592', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a one-step-plus-one linear equation', 'Solve for $x$: $3x + 5 = 20$.', '[]', '5', '(20-5)/3', 'Subtract 5 from both sides: $3x = 15$. Divide both sides by 3: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
