INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e68f305-b7f0-4e00-8b57-36dea56ef224', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a formula for one quantity', 'The formula $d = rt$ relates distance $d$, rate $r$ and time $t$. Solve the formula for $t$.', '["$t = dr$","$t = \\frac{r}{d}$","$t = \\frac{d}{r}$","$t = d - r$"]', '$t = \frac{d}{r}$', NULL, 'To get $t$ alone, divide both sides of $d = rt$ by $r$: $t = \frac{d}{r}$.', 'checked', '{"lint":[],"solve":{"answer":"$t = \\frac{d}{r}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide both sides of d = rt by r: t = d/r.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73989cf0-3f9f-4ddc-9bfb-2f00c5533fcb', 'NC26.M1.ANFR.5', 1, 'choice', 'Justify a step in solving an equation', 'In solving $4x - 7 = 21$, a student writes the next line as $4x = 28$. Which property justifies this step?', '["Addition property of equality","Multiplication property of equality","Distributive property","Commutative property of addition"]', 'Addition property of equality', NULL, 'The student added 7 to both sides: $4x - 7 + 7 = 21 + 7$. Adding the same number to both sides of an equation keeps it true, which is the addition property of equality.', 'checked', '{"lint":[],"solve":{"answer":"Addition property of equality","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From 4x - 7 = 21 to 4x = 28, 7 is added to both sides: addition property of equality.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6e5d571-a091-4241-8354-b4f490a9bb18', 'NC26.M1.ANFR.5', 1, 'choice', 'Justify the steps in solving an equation', 'In solving $x + 9 = 15$, a student writes $x = 6$ as the next line. What was done to both sides of the equation?', '["9 was added to both sides","Both sides were divided by 9","9 was subtracted from both sides","Both sides were multiplied by 9"]', '9 was subtracted from both sides', NULL, 'Subtracting 9 from both sides leaves $x = 15 - 9 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"9 was subtracted from both sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 9 = 15 -> x = 6 is obtained by subtracting 9 from both sides (15 - 9 = 6).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acc753fb-61b2-448d-b6fe-9e3dfb293e03', 'NC26.M1.ANFR.5', 1, 'choice', 'Justify the steps in solving an equation', 'In solving $\frac{x}{4} = 7$, a student writes $x = 28$ as the next line. Which property justifies this step?', '["Multiplication property of equality","Addition property of equality","Subtraction property of equality","Distributive property"]', 'Multiplication property of equality', NULL, 'Multiplying both sides by 4 undoes the division by 4: $x = 7 \cdot 4 = 28$. That is the multiplication property of equality.', 'checked', '{"lint":[],"solve":{"answer":"Multiplication property of equality","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/4 = 7 -> x = 28: both sides multiplied by 4, the multiplication property of equality.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ade8daa-eb31-4a48-81d8-cff0a4510efc', 'NC26.M1.ANFR.5', 1, 'choice', 'Justify the steps in solving an equation', 'A student rewrites $3(x + 2) = 15$ as $3x + 6 = 15$. Which property justifies this step?', '["Addition property of equality","Distributive property","Commutative property of addition","Division property of equality"]', 'Distributive property', NULL, 'Multiplying 3 by each term inside the parentheses, $3 \cdot x + 3 \cdot 2$, uses the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"Distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+2) -> 3x + 6 distributes 3 over the sum: distributive property.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d44a1749-2853-401e-87ee-94f28e99d003', 'NC26.M1.ANFR.5', 1, 'numeric', 'Justify the steps in solving an equation', 'To solve $x - 7 = 12$, a student adds the same number to both sides. What number is added?', '[]', '7', '7', 'Adding 7 to both sides undoes the subtraction: $x - 7 + 7 = 12 + 7$, so $x = 19$. The number added is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 7 = 12; add 7 to both sides to isolate x: x = 19. Number added is 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
