INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f64ad88-1a99-4065-b2f5-249f93c02d42', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $\frac{x}{5} - 3 = 4$.', '[]', '35', '(4+3)*5', 'Add 3: $\frac{x}{5} = 7$. Multiply both sides by 5: $x = 35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/5 - 3 = 4 -> x/5 = 7 -> x = 35.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
