INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92ad5ce9-0a02-4adc-9be6-2c5f85c03bdd', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $2x + 9 = 1$.', '[]', '-4', '(1-9)/2', 'Subtract 9: $2x = -8$. Divide by 2: $x = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 9 = 1 -> 2x = -8 -> x = -4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
