VALUES ('11245616-ac51-474b-90d3-d58e46b80bb3', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $4x \le 20$.', '["$x \\le 5$","$x \\ge 5$","$x \\le 80$","$x \\le 16$"]', '$x \le 5$', NULL, 'Divide both sides by 4 (a positive number, so the sign stays): $x \le 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x <= 20 -> x <= 5 (dividing by positive 4, no reversal).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
