INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbf11173-fba8-44c8-a825-b0b5359655e4', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a formula for a quantity', 'Solve the formula $P = 4s$ for $s$.', '["$s = 4P$","$s = \\frac{P}{4}$","$s = P - 4$","$s = \\frac{4}{P}$"]', '$s = \frac{P}{4}$', NULL, 'Divide both sides by 4: $s = \frac{P}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$s = \\frac{P}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 4s -> divide by 4: s = P/4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
