INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e596fc8-4380-4ff0-8324-72c3664df11e', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a formula for a quantity', 'The perimeter of a rectangle is $P = 2l + 2w$. A rectangle has perimeter 30 and width 5. What is its length?', '[]', '10', '(30-2*5)/2', 'Put in the values: $30 = 2l + 10$. Subtract 10: $20 = 2l$. So $l = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 = 2l + 2(5) -> 2l = 20 -> l = 10.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
