INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd6f7f6d-01b2-4d73-b7c9-71ae35a738ff', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a formula for a quantity', 'Solve the formula $A = \frac{1}{2}bh$ for $b$.', '["$b = \\frac{2A}{h}$","$b = \\frac{A}{2h}$","$b = 2Ah$","$b = \\frac{h}{2A}$"]', '$b = \frac{2A}{h}$', NULL, 'Multiply both sides by 2: $2A = bh$. Divide both sides by $h$: $b = \frac{2A}{h}$.', 'checked', '{"lint":[],"solve":{"answer":"$b = \\frac{2A}{h}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (1/2)bh -> 2A = bh -> b = 2A/h.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
