INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3b2c6f1-f8d2-43fb-9bab-0b0cbaf1f497', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a formula for a quantity', 'The area of a triangle is $A = \frac{1}{2}bh$. A triangle has area 36 and base 9. What is its height?', '[]', '8', '2*36/9', 'Put in the values: $36 = \frac{1}{2} \cdot 9 \cdot h$, so $72 = 9h$ and $h = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = (1/2)(9)h = 4.5h -> h = 8.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
