INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e5c015e-9e1d-4645-b95a-3b18dd1a21fb', 'NC26.M1.ANFR.5', 1, 'choice', 'Write an exponential equation from a situation', 'A video starts with 5 views, and the number of views triples every hour. Which equation can be solved to find the number of hours $t$ until there are 405 views?', '["$5 \\cdot t^3 = 405$","$3 \\cdot 5^t = 405$","$5 \\cdot 3^t = 405$","$5 + 3t = 405$"]', '$5 \cdot 3^t = 405$', NULL, 'The count starts at 5 and is multiplied by 3 each hour, so after $t$ hours it is $5 \cdot 3^t$. Set this equal to 405.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\cdot 3^t = 405$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5, factor 3 per hour: views = 5 * 3^t. Set equal to 405: 5 * 3^t = 405 (t = 4).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8855af8c-3204-448f-978a-1e3e5fe7a35a', 'NC26.M1.ANFR.5', 1, 'numeric', 'Write an exponential equation from a situation', 'A message is passed on so that the number of people who have it doubles every round: after $t$ rounds, $2^t$ people have it. After how many rounds will 64 people have it?', '[]', '6', NULL, 'Solve $2^t = 64$. Since $2^6 = 64$, $t = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^t = 64 = 2^6 -> t = 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
