INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ba9d076-1539-407e-bde2-4b828f2457b4', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $5 \cdot 2^x = 40$.', '[]', '3', NULL, 'Divide by 5: $2^x = 8$. Since $2^3 = 8$, $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 * 2^x = 40 -> 2^x = 8 -> x = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
