INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b0b1129-3626-455b-8d8b-654fed50b455', 'NC26.M1.ANFR.5', 1, 'numeric', 'Interpret the solution of an equation or inequality', 'A taxi ride costs 3 dollars plus 2 dollars per mile. Maria has 15 dollars. The inequality $3 + 2m \le 15$ gives the number of miles $m$ she can ride. What is the greatest number of miles she can ride?', '[]', '6', '(15-3)/2', 'Subtract 3: $2m \le 12$. Divide by 2: $m \le 6$. The greatest is 6 miles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2m <= 15 -> 2m <= 12 -> m <= 6. Greatest is 6 miles (cost exactly 15).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
