INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b306d36d-5145-429c-946e-a30ecfb9dd4a', 'NC26.M1.ANFR.5', 1, 'choice', 'Interpret the solution of an equation or inequality', 'The solution of an inequality in $x$, the number of whole pencils that can be bought, is $x \le 12.5$. Which statement is the best interpretation?', '["At most 13 pencils can be bought","Exactly 12.5 pencils can be bought","At least 12 pencils must be bought","At most 12 pencils can be bought"]', 'At most 12 pencils can be bought', NULL, 'Whole pencils cannot be split, so $x$ can be at most the greatest whole number not above 12.5, which is 12.', 'checked', '{"lint":[],"solve":{"answer":"At most 12 pencils can be bought","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x is a whole number of pencils and x <= 12.5, so x can be at most 12. 13 exceeds 12.5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
