INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae2b8f8-5aa4-4dcd-9fea-d16936c8e955', 'NC26.M1.ANFR.5', 1, 'choice', 'Interpret the solution of an equation or inequality', 'The equation $7.5h + 12 = 57$ models total pay in dollars for $h$ hours of work, including a 12 dollar bonus. Its solution is $h = 6$. What does the solution tell us?', '["Working 57 hours earns a total of 6 dollars","The hourly pay is 6 dollars","Working 6 hours earns a total of 57 dollars","The bonus is 6 dollars"]', 'Working 6 hours earns a total of 57 dollars', NULL, 'The equation asks for the hours that give a total of 57 dollars. The solution $h = 6$ means 6 hours of work gives 57 dollars.', 'checked', '{"lint":[],"solve":{"answer":"Working 6 hours earns a total of 57 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 6 hours gives total pay 7.5(6) + 12 = 57 dollars. So working 6 hours earns 57 dollars in total.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f88c67e-9d84-40fb-8b27-a38e731590bb', 'NC26.M1.ANFR.5', 1, 'choice', 'Write and solve a linear equation or inequality from a situation', 'Sam has 15 stickers and buys packs of 6 stickers. He wants 51 stickers in all. Which equation can be solved to find the number of packs $p$?', '["$6 + 15p = 51$","$21p = 51$","$15 + 6p = 51$","$15 \\cdot 6p = 51$"]', '$15 + 6p = 51$', NULL, 'He starts with 15 and adds 6 stickers for each pack: $15 + 6p = 51$.', 'checked', '{"lint":[],"solve":{"answer":"$15 + 6p = 51$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 15, plus 6 per pack: 15 + 6p = 51 (p = 6).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('719edf5f-0457-4499-8707-7c15159a31be', 'NC26.M1.ANFR.5', 1, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'A tutor charges 5 dollars to sign up and then 20 dollars per hour. A family paid 65 dollars in all. For how many hours was the tutor hired?', '[]', '3', '(65-5)/20', 'The equation is $5 + 20h = 65$. Subtract 5: $20h = 60$. So $h = 3$ hours.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 20h = 65 -> 20h = 60 -> h = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3bb865a-8ff7-40a8-9498-d8e4ee986282', 'NC26.M1.ANFR.5', 1, 'choice', 'Write and solve a linear equation or inequality from a situation', 'Which inequality states "3 less than twice a number is at most 9"?', '["$2n - 3 \\ge 9$","$2(n - 3) \\le 9$","$3 - 2n \\le 9$","$2n - 3 \\le 9$"]', '$2n - 3 \le 9$', NULL, '"Twice a number" is $2n$, "3 less than" that is $2n - 3$, and "at most 9" means $\le 9$.', 'checked', '{"lint":[],"solve":{"answer":"$2n - 3 \\le 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice a number: 2n; 3 less than that: 2n - 3; at most 9: <= 9. So 2n - 3 <= 9.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8df55f7c-ad0b-4c2b-bbc8-947cdff2c1ae', 'NC26.M1.ANFR.5', 1, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'Adult tickets cost 8 dollars and child tickets cost 5 dollars. A theater sold 12 adult tickets and some child tickets for a total of 126 dollars. How many child tickets were sold?', '[]', '6', '(126-12*8)/5', 'Adult tickets bring in $12 \cdot 8 = 96$ dollars. The child tickets bring in $126 - 96 = 30$ dollars, so $30 \div 5 = 6$ child tickets.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8(12) + 5c = 126 -> 96 + 5c = 126 -> 5c = 30 -> c = 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79f5fc23-b6eb-491d-b0b2-3bb7647f7338', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality, reversing the sign', 'Solve the inequality $-2x + 3 < 11$.', '["$x < -4$","$x > 4$","$x < 4$","$x > -4$"]', '$x > -4$', NULL, 'Subtract 3 from both sides: $-2x < 8$. Dividing both sides by $-2$ reverses the inequality sign: $x > -4$.', 'checked', '{"lint":[],"solve":{"answer":"$x > -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 3 < 11 -> -2x < 8 -> divide by -2 and flip: x > -4. Check x = 0: 3 < 11 true.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9fe7a4c-d1cc-4572-9e15-5aff7fdf5f47', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a formula for a quantity, given a value', 'The formula $F = \frac{9}{5}C + 32$ changes a temperature in degrees Celsius $C$ to degrees Fahrenheit $F$. A temperature is 68 degrees Fahrenheit. What is it in degrees Celsius?', '[]', '20', '(68-32)*5/9', 'Put $F = 68$ in the formula: $68 = \frac{9}{5}C + 32$. Subtract 32: $36 = \frac{9}{5}C$. Multiply by $\frac{5}{9}$: $C = 36 \times \frac{5}{9} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68 = (9/5)C + 32 -> (9/5)C = 36 -> C = 36 * 5/9 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90c25faa-1050-4d16-8a75-58c5016fcfda', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a simple exponential equation in context', 'A culture starts with 3 bacteria and triples every hour, so after $t$ hours it has $3 \cdot 3^t$ bacteria. After how many hours are there 243 bacteria?', '[]', '4', '4', 'Solve $3 \cdot 3^t = 243$. Divide by 3: $3^t = 81$. Since $3^4 = 81$, $t = 4$ hours. (Check: 3, 9, 27, 81, 243.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 * 3^t = 243 -> 3^t = 81 = 3^4 -> t = 4. Check: 3 * 81 = 243.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06de6617-d335-443d-8a29-70e4d9099200', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student rewrites $5x - 2x + 4 = 19$ as $3x + 4 = 19$. What justifies this step?', '["Division property of equality","Addition property of equality","Multiplication property of equality","Combining like terms"]', 'Combining like terms', NULL, '$5x$ and $-2x$ are like terms, and combining them gives $3x$. Nothing is done to both sides.', 'checked', '{"lint":[],"solve":{"answer":"Combining like terms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 2x = 3x on the left side only: combining like terms.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8936052-394e-4f3d-ab58-c87ba6d167e6', 'NC26.M1.ANFR.5', 2, 'numeric', 'Justify the steps in solving an equation', 'In solving $6x + 5 = 2x + 21$, a student subtracts $2x$ from both sides and then subtracts 5 from both sides, giving $4x = c$. What is $c$?', '[]', '16', '21-5', 'After subtracting $2x$: $4x + 5 = 21$. After subtracting 5: $4x = 16$. So $c = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 5 = 2x + 21; subtract 2x: 4x + 5 = 21; subtract 5: 4x = 16. c = 16.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458c302c-9dcd-4073-8001-7913baeee490', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student solves $-3x \ge 12$ and writes $x \le -4$. Which statement justifies reversing the inequality sign?', '["Dividing both sides of an inequality by a positive number reverses the inequality sign","Subtracting a number from both sides of an inequality reverses the inequality sign","The sign always reverses when the answer is negative","Dividing both sides of an inequality by a negative number reverses the inequality sign"]', 'Dividing both sides of an inequality by a negative number reverses the inequality sign', NULL, 'The student divided both sides by $-3$. Dividing (or multiplying) by a negative number flips the direction of the inequality: $x \le -4$.', 'checked', '{"lint":[],"solve":{"answer":"Dividing both sides of an inequality by a negative number reverses the inequality sign","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x >= 12, divide by -3: x <= -4. The reversal is because both sides were divided by a negative number.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88175f15-a0f5-4d47-a2e8-eb2d08c1cbf9', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student solves $2(x - 3) = 10$ and writes $2x - 3 = 10$ as the first line. Which property was applied incorrectly?', '["Division property of equality","Addition property of equality","Distributive property","Combining like terms"]', 'Distributive property', NULL, 'The 2 must multiply both terms in the parentheses: $2(x - 3) = 2x - 6$. The student multiplied only the first term.', 'checked', '{"lint":[],"solve":{"answer":"Distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x - 3) should be 2x - 6; writing 2x - 3 means the 2 was not distributed to the -3: distributive property misapplied.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df4d835e-6557-4439-9e5d-c9359464f0af', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $5(x - 2) = 3x + 6$.', '[]', '8', '(6+10)/2', 'Distribute: $5x - 10 = 3x + 6$. Subtract $3x$: $2x - 10 = 6$. Add 10: $2x = 16$. So $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 10 = 3x + 6 -> 2x = 16 -> x = 8. Check: 5(6) = 30, 24 + 6 = 30.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('580faadb-7536-46bc-872d-613277fa4ed5', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $7 - 3x = 2x - 13$.', '[]', '4', '(7+13)/5', 'Add $3x$ to both sides: $7 = 5x - 13$. Add 13: $20 = 5x$. So $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 3x = 2x - 13 -> 20 = 5x -> x = 4. Check: 7 - 12 = -5, 8 - 13 = -5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80599dec-a7a9-4fa4-949c-30d12a8dc9ac', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear equation in one variable', 'Solve for $x$: $\frac{2}{3}x + 4 = 10$.', '["21","4","9","6"]', '9', '(10-4)*3/2', 'Subtract 4: $\frac{2}{3}x = 6$. Multiply by $\frac{3}{2}$: $x = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)x + 4 = 10 -> (2/3)x = 6 -> x = 6 * 3/2 = 9.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
