INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47d5349f-8670-4e72-91dc-083289919f24', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $6x + 1 = 2x + 8$.', '[]', '7/4', '(8-1)/(6-2)', 'Subtract $2x$: $4x + 1 = 8$. Subtract 1: $4x = 7$. So $x = \frac{7}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"7/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 1 = 2x + 8 -> 4x = 7 -> x = 7/4 = 1.75.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
