INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9653c264-cd33-4f31-aa45-64d098e1bf4f', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $-3x + 4 \le 19$.', '["$x \\le -5$","$x \\ge 5$","$x \\ge -5$","$x \\le 5$"]', '$x \ge -5$', NULL, 'Subtract 4: $-3x \le 15$. Divide by $-3$ and reverse the sign: $x \ge -5$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge -5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x + 4 <= 19 -> -3x <= 15 -> x >= -5 (divide by -3, reverse).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
