INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1a38d99-4e53-4a1e-9990-358ad4380fce', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $5 - 2(x + 1) > 9$.', '["$x > -3$","$x < -3$","$x < 3$","$x > 3$"]', '$x < -3$', NULL, 'Distribute: $5 - 2x - 2 > 9$, so $3 - 2x > 9$. Subtract 3: $-2x > 6$. Divide by $-2$ and reverse the sign: $x < -3$.', 'checked', '{"lint":[],"solve":{"answer":"$x < -3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2x - 2 > 9 -> 3 - 2x > 9 -> -2x > 6 -> x < -3. Check x = -4: 5 - 2(-3) = 11 > 9.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
