INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6741f74-f2e7-4e59-bdb6-4d684aa94eb1', 'NC26.M1.ANFR.5', 2, 'choice', 'Write an exponential equation from a situation', 'A town of 12000 people grows 3% each year. Which equation can be solved to find the number of years $t$ until the population is 15000?', '["$12000 \\cdot 1.03^t = 15000$","$12000 \\cdot 0.03^t = 15000$","$12000 + 0.03t = 15000$","$12000 \\cdot 3^t = 15000$"]', '$12000 \cdot 1.03^t = 15000$', NULL, 'A 3% increase multiplies the population by 1.03 each year, so after $t$ years it is $12000 \cdot 1.03^t$.', 'checked', '{"lint":[],"solve":{"answer":"$12000 \\cdot 1.03^t = 15000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth 3% per year: factor 1.03. 12000 * 1.03^t = 15000.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('157e44a6-6931-400e-af2f-41e91d5bbdf3', 'NC26.M1.ANFR.5', 2, 'choice', 'Write an exponential equation from a situation', 'A truck worth 18000 dollars loses 12% of its value each year. Which equation can be solved to find the number of years $t$ until it is worth 9000 dollars?', '["$18000 \\cdot 0.88^t = 9000$","$18000 \\cdot 0.12^t = 9000$","$18000 \\cdot 1.12^t = 9000$","$18000 - 0.12t = 9000$"]', '$18000 \cdot 0.88^t = 9000$', NULL, 'Losing 12% leaves 88% of the value each year, so the value after $t$ years is $18000 \cdot 0.88^t$.', 'checked', '{"lint":[],"solve":{"answer":"$18000 \\cdot 0.88^t = 9000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Loses 12% per year: factor 1 - 0.12 = 0.88. 18000 * 0.88^t = 9000.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9c24567-6ca9-49c3-9360-170ea8aa6f3f', 'NC26.M1.ANFR.5', 2, 'numeric', 'Write an exponential equation from a situation', 'A drug amount halves every 4 hours. Starting from 120 milligrams, the equation $120 \cdot (\frac{1}{2})^n = 7.5$ gives the number of 4-hour periods $n$ until 7.5 milligrams remain. What is $n$?', '[]', '4', NULL, 'Divide by 120: $(\frac{1}{2})^n = \frac{7.5}{120} = \frac{1}{16}$. Since $2^4 = 16$, $n = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^n = 7.5/120 = 1/16 = (1/2)^4 -> n = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92c39aa5-1022-4031-b038-c3f20041bcea', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $7 \cdot 2^x = 224$.', '[]', '5', NULL, 'Divide by 7: $2^x = 32$. Since $2^5 = 32$, $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 * 2^x = 224 -> 2^x = 32 -> x = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3e4e971-2767-4a98-98ed-ca236b19bbd7', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $100 \cdot (\frac{1}{2})^x = 12.5$.', '["8","4","3","6"]', '3', '3', 'Divide by 100: $(\frac{1}{2})^x = 0.125 = \frac{1}{8}$. Since $(\frac{1}{2})^3 = \frac{1}{8}$, $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 (1/2)^x = 12.5 -> (1/2)^x = 0.125 = 1/8 -> x = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e0a9c4f-0276-47b7-8851-0300a7c9e529', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'The value of an investment is $V = 1000 \cdot 1.1^t$ dollars after $t$ years. A table gives $V$ as 1100, 1210, 1331 and 1464.1 for $t = 1, 2, 3, 4$. In which year $t$ does the value first exceed 1300 dollars?', '[]', '3', NULL, 'The values for $t = 1$ and $t = 2$ (1100 and 1210) are below 1300. For $t = 3$, the value is 1331, which is above 1300. So $t = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Table: t=1 1100, t=2 1210 (below 1300), t=3 1331 (above 1300). First exceeds 1300 at t = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9acb992-4890-49b4-ab66-fca937f3a468', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve an exponential equation with a table or by reasoning', 'A table of values of $1.5^t$ for $t = 2, 3, 4, 5$ is 2.25, 3.375, 5.0625, 7.59375. Between which two whole numbers is the solution of $1.5^t = 5$?', '["Between 2 and 3","Between 4 and 5","Between 5 and 6","Between 3 and 4"]', 'Between 3 and 4', NULL, '$1.5^3 = 3.375$ is below 5 and $1.5^4 = 5.0625$ is above 5, so the solution lies between $t = 3$ and $t = 4$.', 'checked', '{"lint":[],"solve":{"answer":"Between 3 and 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5^3 = 3.375 < 5 and 1.5^4 = 5.0625 > 5, so the solution of 1.5^t = 5 lies between 3 and 4 (about 3.97).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('053cbf7b-ffc8-4fd8-8f0b-6fff86d16395', 'NC26.M1.ANFR.5', 2, 'numeric', 'Interpret the solution of an equation or inequality', 'A student scored 88, 92 and 85 on three tests. What is the lowest score on a fourth test that gives an average of at least 90?', '[]', '95', '90*4-88-92-85', 'The average of four tests is at least 90 when the total is at least $90 \cdot 4 = 360$. The first three add to $88 + 92 + 85 = 265$, so the fourth score must be at least $360 - 265 = 95$.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(88 + 92 + 85 + s)/4 >= 90 -> 265 + s >= 360 -> s >= 95. Lowest score 95.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('426e2026-38da-42fe-9809-5735f5d1155a', 'NC26.M1.ANFR.5', 2, 'choice', 'Interpret the solution of an equation or inequality', 'A tank holds $50 - 4t$ liters of water after $t$ minutes. Solving $50 - 4t = 18$ gives $t = 8$. What does this tell us?', '["The tank holds 18 liters after 8 minutes","The tank holds 8 liters after 18 minutes","The tank is empty after 8 minutes","The tank loses 18 liters in 8 minutes"]', 'The tank holds 18 liters after 8 minutes', NULL, 'The equation asks when the amount $50 - 4t$ equals 18 liters. The solution $t = 8$ means that happens after 8 minutes.', 'checked', '{"lint":[],"solve":{"answer":"The tank holds 18 liters after 8 minutes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 4t = 18 at t = 8 means after 8 minutes the tank holds 18 liters. (It has lost 32 liters, not 18; empty would be 12.5 minutes.)","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a018c348-af6d-4166-bd87-d0d5e104c43c', 'NC26.M1.ANFR.5', 2, 'numeric', 'Interpret the solution of an equation or inequality', 'A kayak rental costs 15 dollars plus 9 dollars per hour. Mia has 62 dollars. What is the greatest number of whole hours she can rent the kayak?', '[]', '5', NULL, 'The inequality is $15 + 9h \le 62$. Subtract 15: $9h \le 47$, so $h \le 5.2$. She can rent for 5 whole hours (cost 60 dollars).', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 9h <= 62 -> 9h <= 47 -> h <= 5.22. Greatest whole number of hours 5 (15 + 45 = 60; 6 hours would be 69).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50d0906f-e4c4-42c0-9efb-aa4be8115446', 'NC26.M1.ANFR.5', 2, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'The length of a rectangle is 3 more than twice its width. The perimeter is 54 centimeters. What is the width, in centimeters?', '[]', '8', '(54/2-3)/3', 'With width $w$, the length is $2w + 3$. The perimeter gives $2(w + 2w + 3) = 54$, so $3w + 3 = 27$ and $w = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 2w + 3. Perimeter 2(2w + 3) + 2w = 6w + 6 = 54 -> 6w = 48 -> w = 8. (L = 19; 2(19 + 8) = 54.)","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ca89da1-0194-4e66-88a7-b402296b9565', 'NC26.M1.ANFR.5', 2, 'choice', 'Write and solve a linear equation or inequality from a situation', 'Mia has 40 dollars and saves 7 dollars each week. Ana has 100 dollars and spends 8 dollars each week. Which equation can be solved to find the number of weeks $w$ until they have the same amount?', '["$40 + 7w = 100 + 8w$","$40 + 7w = 100 - 8w$","$40 - 7w = 100 - 8w$","$47w = 108w$"]', '$40 + 7w = 100 - 8w$', NULL, 'Mia has $40 + 7w$ after $w$ weeks and Ana has $100 - 8w$. Set them equal.', 'checked', '{"lint":[],"solve":{"answer":"$40 + 7w = 100 - 8w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia: 40 + 7w. Ana: 100 - 8w. Equal: 40 + 7w = 100 - 8w (w = 4).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3a3ddde-f2b4-4b02-89af-c482a990251a', 'NC26.M1.ANFR.5', 2, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'Three consecutive whole numbers add up to 117. What is the largest of the three?', '[]', '40', '117/3+1', 'With the smallest number $n$, the sum is $n + (n + 1) + (n + 2) = 3n + 3 = 117$. So $n = 38$ and the largest is $40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + (n + 1) + (n + 2) = 117 -> 3n + 3 = 117 -> n = 38. Numbers 38, 39, 40. Largest 40.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dfe51dc-bc01-4a08-af01-b009a32daa6c', 'NC26.M1.ANFR.5', 2, 'choice', 'Write and solve a linear equation or inequality from a situation', 'A club has 200 dollars to spend. Each pizza costs 12 dollars and delivery is a flat fee of 20 dollars. Which inequality can be solved to find the number of pizzas $p$ the club can afford?', '["$12p + 20 \\le 200$","$12p + 20 \\ge 200$","$12(p + 20) \\le 200$","$20p + 12 \\le 200$"]', '$12p + 20 \le 200$', NULL, 'The total cost is $12p + 20$, and it must be at most 200: $12p + 20 \le 200$.', 'checked', '{"lint":[],"solve":{"answer":"$12p + 20 \\le 200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = 12 per pizza times p plus flat 20 delivery: 12p + 20, which must be at most 200: 12p + 20 <= 200.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8466950c-487a-4219-b5ba-9c53b76b3944', 'NC26.M1.ANFR.5', 3, 'choice', 'Write an exponential equation from a situation', 'A population starts at 200 and doubles every hour. Which equation can be solved to find the number of hours $t$ until the population is 3200?', '["$200 + 2t = 3200$","$200(2)^t = 3200$","$2(200)^t = 3200$","$200(2t) = 3200$"]', '$200(2)^t = 3200$', NULL, 'The starting amount is 200 and it is multiplied by 2 for each hour, so after $t$ hours the population is $200(2)^t$. Setting that equal to 3200 gives $200(2)^t = 3200$.', 'checked', '{"lint":[],"solve":{"answer":"$200(2)^t = 3200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population after t hours = 200(2)^t; set equal to 3200: 200(2)^t = 3200 (t = 4).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a33d09c5-3ce7-4619-b6c8-d32a2db66f09', 'NC26.M1.ANFR.5', 3, 'numeric', 'Interpret the solution of an inequality in context', 'You have 52 dollars. Park entry costs 14 dollars, and each ride ticket costs 3 dollars. You can only buy whole tickets. What is the greatest number of ride tickets you can buy?', '[]', '12', NULL, 'The inequality is $14 + 3r \le 52$, so $3r \le 38$ and $r \le 12.67\ldots$. You can only buy whole tickets, so the greatest number is 12 (12 tickets cost 36 dollars, for a total of 50 dollars).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 + 3n <= 52 -> 3n <= 38 -> n <= 12.67. Greatest whole n = 12 (14 + 36 = 50; 13 would cost 53).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd7dc7e6-e61b-449c-8d7b-347df0d301e1', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a formula for time, given values', 'The formula $A = P + Prt$ gives the total $A$ in dollars after $t$ years when $P$ dollars earn simple interest at yearly rate $r$ (written as a decimal). When $P = 200$ and $r = 0.05$, the total is $A = 230$. How many years is that?', '[]', '3', '(230-200)/(200*0.05)', 'Put in the values: $230 = 200 + 200(0.05)t = 200 + 10t$. Subtract 200: $30 = 10t$. So $t = 3$ years.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"230 = 200 + 200(0.05)t = 200 + 10t -> 10t = 30 -> t = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9e9b65c-2d32-4fed-9b61-558700845bc1', 'NC26.M1.ANFR.5', 3, 'choice', 'Justify the steps in solving an equation', 'A solution is shown. Line 1: $3(x + 4) = 2x + 20$. Line 2: $3x + 12 = 2x + 20$. Line 3: $x + 12 = 20$. Line 4: $x = 8$. What was done to get from Line 2 to Line 3?', '["12 was subtracted from both sides","$2x$ was subtracted from both sides","Both sides were divided by 3","$3x$ was subtracted from both sides"]', '$2x$ was subtracted from both sides', NULL, '$3x - 2x = x$ on the left and $2x - 2x = 0$ on the right, so $2x$ was subtracted from both sides.', 'checked', '{"lint":[],"solve":{"answer":"$2x$ was subtracted from both sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 2: 3x + 12 = 2x + 20. Subtract 2x from both sides: x + 12 = 20 (Line 3).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c69573-ba47-4f10-b31f-135131e80e1e', 'NC26.M1.ANFR.5', 3, 'numeric', 'Justify the steps in solving an equation', 'A student solves $2(3x - 4) = 4x + 6$. Line 1: $2(3x - 4) = 4x + 6$. Line 2: $6x - 8 = 4x + 6$. Line 3: $2x - 8 = 6$. Line 4: $2x = -2$. Line 5: $x = -1$. Which line number contains the first mistake?', '[]', '4', NULL, 'Lines 1 to 3 are correct. From $2x - 8 = 6$, adding 8 to both sides gives $2x = 14$, not $2x = -2$. So the first mistake is in Line 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 2: 6x - 8 = 4x + 6 correct. Line 3: subtract 4x: 2x - 8 = 6 correct. Line 4: add 8: 2x = 14, but student wrote 2x = -2 (subtracted 8). First mistake is Line 4. (Correct x = 7.)","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d2851df-2142-4a6b-9f88-083b9127eccb', 'NC26.M1.ANFR.5', 3, 'choice', 'Justify the steps in solving an equation', 'Which operation turns $\frac{x}{3} + 2 = 5$ into $x + 6 = 15$?', '["Multiplying every term on both sides by 3","Adding 3 to both sides","Multiplying only the left side by 3","Dividing both sides by 3"]', 'Multiplying every term on both sides by 3', NULL, 'Multiplying each term by 3 gives $x + 6 = 15$. The multiplication property of equality allows multiplying both sides, and the distributive property applies it to each term.', 'checked', '{"lint":[],"solve":{"answer":"Multiplying every term on both sides by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply each term by 3: 3(x/3) + 3(2) = 3(5) -> x + 6 = 15. Multiplying only the left side would give x + 6 = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20deec50-ea8b-4df9-b2b4-0a3c43ace8fe', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $\frac{x + 3}{2} = \frac{2x - 1}{3}$.', '[]', '11', '9+2', 'Multiply both sides by 6: $3(x + 3) = 2(2x - 1)$. Distribute: $3x + 9 = 4x - 2$. Subtract $3x$ and add 2: $11 = x$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cross-multiply: 3(x + 3) = 2(2x - 1) -> 3x + 9 = 4x - 2 -> x = 11. Check: 14/2 = 7, 21/3 = 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3516a7f3-f048-4ae9-9a49-8fb1cf4899f4', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $0.4(x + 5) = 0.25x + 4.1$.', '[]', '14', '(4.1-0.4*5)/(0.4-0.25)', 'Distribute: $0.4x + 2 = 0.25x + 4.1$. Subtract $0.25x$ and 2: $0.15x = 2.1$. So $x = 2.1 \div 0.15 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4x + 2 = 0.25x + 4.1 -> 0.15x = 2.1 -> x = 14. Check: 0.4(19) = 7.6; 3.5 + 4.1 = 7.6.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86708197-af16-41d3-a9ff-e4288578bafe', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve a linear equation in one variable', 'How many solutions does the equation $3(x + 2) = 3x + 6$ have?', '["No solution","Infinitely many","Exactly one solution","Exactly two solutions"]', 'Infinitely many', NULL, 'Distributing gives $3x + 6 = 3x + 6$, which is true for every value of $x$. So there are infinitely many solutions.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6 is 3x + 6 = 3x + 6, an identity: true for every x, infinitely many solutions.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3870a8a-d5d7-4980-aa45-f1b7c5049e2e', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $4(2x - 3) - 5x = 2(x + 7) + 1$.', '[]', '27', '15+12', 'Distribute: $8x - 12 - 5x = 2x + 14 + 1$, so $3x - 12 = 2x + 15$. Subtract $2x$ and add 12: $x = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left: 8x - 12 - 5x = 3x - 12. Right: 2x + 14 + 1 = 2x + 15. 3x - 12 = 2x + 15 -> x = 27. Check: 4(51) - 135 = 69; 2(34) + 1 = 69.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d64d785e-32c7-44aa-abf3-d2cd334b1e1d', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $\frac{x}{-3} - 2 \ge 1$.', '["$x \\le -9$","$x \\ge -9$","$x \\le 9$","$x \\ge 9$"]', '$x \le -9$', NULL, 'Add 2: $\frac{x}{-3} \ge 3$. Multiply both sides by $-3$ and reverse the sign: $x \le -9$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le -9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/(-3) - 2 >= 1 -> x/(-3) >= 3 -> multiply by -3 and reverse: x <= -9. Check x = -12: 4 - 2 = 2 >= 1.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d097f9a3-8b92-430c-850b-40be2d062d0e', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a linear inequality in one variable', 'What is the greatest whole number that satisfies $7 - 3x > 2x - 18$?', '[]', '4', NULL, 'Add $3x$ and 18: $25 > 5x$, so $x < 5$. The greatest whole number less than 5 is 4. (Check: for $x = 4$, $-5 > -10$ is true; for $x = 5$, $-8 > -8$ is false.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 3x > 2x - 18 -> 25 > 5x -> x < 5. Greatest whole number 4 (check 4: -5 > -10 true; 5: -8 > -8 false).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9cfe4f6-6077-4c85-9a34-33f9adb551a1', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $-2(3 - x) \ge 4x - 10$.', '["$x \\ge 2$","$x \\le \\frac{2}{3}$","$x \\le 2$","$x \\ge \\frac{2}{3}$"]', '$x \le 2$', NULL, 'Distribute: $-6 + 2x \ge 4x - 10$. Subtract $4x$ and add 6: $-2x \ge -4$. Divide by $-2$ and reverse the sign: $x \le 2$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(3 - x) = -6 + 2x. -6 + 2x >= 4x - 10 -> 4 >= 2x -> x <= 2. Check x = 0: -6 >= -10 true; x = 3: 0 >= 2 false.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3ecb0cd-a63b-4788-b7c7-ce497000d021', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a formula for a quantity', 'The area of a trapezoid is $A = \frac{1}{2}h(b_1 + b_2)$. A trapezoid has area 60, height 8 and one base $b_1 = 5$. What is the other base $b_2$?', '[]', '10', '2*60/8-5', 'Put in the values: $60 = 4(5 + b_2)$. Divide by 4: $15 = 5 + b_2$. So $b_2 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = (1/2)(8)(5 + b2) = 4(5 + b2) -> 15 = 5 + b2 -> b2 = 10.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f002906-0c70-456c-ae40-ae3d1396dba9', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve a formula for a quantity', 'Solve the formula $A = \frac{1}{2}h(b_1 + b_2)$ for $b_2$.', '["$b_2 = \\frac{2A - b_1}{h}$","$b_2 = 2Ah - b_1$","$b_2 = \\frac{2A}{h} - b_1$","$b_2 = \\frac{A}{2h} - b_1$"]', '$b_2 = \frac{2A}{h} - b_1$', NULL, 'Multiply by 2: $2A = h(b_1 + b_2)$. Divide by $h$: $\frac{2A}{h} = b_1 + b_2$. Subtract $b_1$: $b_2 = \frac{2A}{h} - b_1$.', 'checked', '{"lint":[],"solve":{"answer":"$b_2 = \\frac{2A}{h} - b_1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (1/2)h(b1 + b2) -> 2A = h(b1 + b2) -> 2A/h = b1 + b2 -> b2 = 2A/h - b1.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b07a2e98-8eb8-46b1-9e24-3d6f27c9065a', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a formula for a quantity', 'The slope of a line is $m = \frac{y_2 - y_1}{x_2 - x_1}$. A line has slope 3 and passes through the point $(2, 4)$. A second point on the line has $x_2 = 7$. What is $y_2$?', '[]', '19', '3*(7-2)+4', 'Put in the values: $3 = \frac{y_2 - 4}{7 - 2}$. Multiply both sides by 5: $15 = y_2 - 4$. So $y_2 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 = (y2 - 4)/(7 - 2) = (y2 - 4)/5 -> y2 - 4 = 15 -> y2 = 19.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d4e049-ac11-4595-9047-81373536ce54', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve a formula for a quantity', 'Solve the equation $\frac{x}{a} + \frac{y}{b} = 1$ for $y$.', '["$y = b + \\frac{bx}{a}$","$y = \\frac{b - x}{a}$","$y = 1 - \\frac{x}{a} - b$","$y = b - \\frac{bx}{a}$"]', '$y = b - \frac{bx}{a}$', NULL, 'Subtract $\frac{x}{a}$: $\frac{y}{b} = 1 - \frac{x}{a}$. Multiply both sides by $b$: $y = b - \frac{bx}{a}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = b - \\frac{bx}{a}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/a + y/b = 1 -> y/b = 1 - x/a -> y = b(1 - x/a) = b - bx/a.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b791677e-3a92-4389-88f7-57513b4ab91e', 'NC26.M1.ANFR.5', 3, 'numeric', 'Write an exponential equation from a situation', 'A culture grows from 250 cells to 4000 cells in 4 hours. Each hour the number of cells is multiplied by the same factor $b$ with $b > 0$, so $250 \cdot b^4 = 4000$. What is $b$?', '[]', '2', NULL, 'Divide by 250: $b^4 = 16$. Since $2^4 = 16$ and $b > 0$, $b = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"250 b^4 = 4000 -> b^4 = 16 -> b = 2 (b > 0).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf058961-b72e-414e-b154-44d2b77ad629', 'NC26.M1.ANFR.5', 3, 'choice', 'Write an exponential equation from a situation', 'A sample of 80 grams halves every 3 years. Which equation can be solved to find the number of years $t$ until 10 grams remain?', '["$80 \\cdot (\\frac{1}{2})^{3t} = 10$","$80 \\cdot (\\frac{1}{2})^{t/3} = 10$","$80 \\cdot (\\frac{1}{3})^t = 10$","$80 - 3t = 10$"]', '$80 \cdot (\frac{1}{2})^{t/3} = 10$', NULL, 'In $t$ years there are $t \div 3$ halvings, so the mass is $80 \cdot (\frac{1}{2})^{t/3}$.', 'checked', '{"lint":[],"solve":{"answer":"$80 \\cdot (\\frac{1}{2})^{t/3} = 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halves every 3 years: number of halvings after t years is t/3. 80 * (1/2)^(t/3) = 10 (t = 9).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80bdad1d-d0e7-486a-bc4f-846c1717c1ab', 'NC26.M1.ANFR.5', 3, 'choice', 'Write an exponential equation from a situation', 'A fungus colony covers 3 square centimeters and doubles in area every 5 days. Which equation can be solved to find the number of days $d$ until it covers 96 square centimeters?', '["$3 \\cdot 2^{5d} = 96$","$3 \\cdot 2^d = 96$","$3 \\cdot 5^{d/2} = 96$","$3 \\cdot 2^{d/5} = 96$"]', '$3 \cdot 2^{d/5} = 96$', NULL, 'In $d$ days there are $d \div 5$ doublings, so the area is $3 \cdot 2^{d/5}$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\cdot 2^{d/5} = 96$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubles every 5 days: doublings after d days = d/5. 3 * 2^(d/5) = 96 (d = 25).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33bb966d-b532-47d5-8644-9be339495265', 'NC26.M1.ANFR.5', 3, 'numeric', 'Write an exponential equation from a situation', 'Mold on a slice of bread covers 4 square millimeters and doubles in area every 3 days, so its area after $d$ days is $4 \cdot 2^{d/3}$. After how many days will it cover 256 square millimeters?', '[]', '18', '6*3', 'Solve $4 \cdot 2^{d/3} = 256$. Divide by 4: $2^{d/3} = 64 = 2^6$. So $\frac{d}{3} = 6$ and $d = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 * 2^(d/3) = 256 -> 2^(d/3) = 64 = 2^6 -> d/3 = 6 -> d = 18.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9a5b1e3-28a1-47b7-aa3e-c9dab4fedd30', 'NC26.M1.ANFR.5', 3, 'choice', 'Write an exponential equation from a situation', 'Which situation matches the equation $500 \cdot 0.9^t = 200$?', '["A value of 500 dollars gains 10% each year; $t$ is the number of years until it is worth 200 dollars","A value of 500 dollars loses 90% each year; $t$ is the number of years until it is worth 200 dollars","A value of 500 dollars loses 10% each year; $t$ is the number of years until it is worth 200 dollars","A value of 200 dollars loses 10% each year; $t$ is the number of years until it is worth 500 dollars"]', 'A value of 500 dollars loses 10% each year; $t$ is the number of years until it is worth 200 dollars', NULL, 'The start is 500 and the factor 0.9 keeps 90% of the value, which is a loss of 10% each year. The result 200 is the target.', 'checked', '{"lint":[],"solve":{"answer":"A value of 500 dollars loses 10% each year; $t$ is the number of years until it is worth 200 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500 is the start, 0.9 = 1 - 0.10 means it loses 10% per period, 200 is the target. Matches: 500 dollars loses 10% each year until worth 200.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be4b9ae4-8cdd-4290-afd9-7999168c7c02', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'A culture has $B(t) = 50 \cdot 2^t$ bacteria after $t$ hours. What is the least whole number of hours after which there are more than 10000 bacteria?', '[]', '8', NULL, 'Divide by 50: we need $2^t > 200$. $2^7 = 128$ is too small and $2^8 = 256$ is enough. So $t = 8$ (12800 bacteria; at 7 hours there are only 6400).', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 * 2^t > 10000 -> 2^t > 200. 2^7 = 128 (6400 bacteria), 2^8 = 256 (12800). Least whole t = 8.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa5126e6-54c5-4640-aace-7fe033e662ec', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'A car''s value is $V(t) = 20000 \cdot 0.8^t$ dollars after $t$ years. What is the least whole number of years after which it is worth less than 10000 dollars?', '[]', '4', NULL, 'We need $0.8^t < 0.5$. $0.8^3 = 0.512$ (value 10240) is still too high, and $0.8^4 = 0.4096$ (value 8192) is below 10000. So $t = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20000 * 0.8^t < 10000 -> 0.8^t < 0.5. 0.8^3 = 0.512 (10240, not less), 0.8^4 = 0.4096 (8192). Least whole t = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0460759d-7420-45d8-8e22-30809f5e9e64', 'NC26.M1.ANFR.5', 3, 'choice', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $2^{x+3} = 128$.', '["7","4","125","5"]', '4', '4', '$128 = 2^7$, so $x + 3 = 7$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"128 = 2^7, so x + 3 = 7 -> x = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
