INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ab7bccf-9f9e-49af-be3f-9d72249f740b', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $5 \cdot 2^{x-1} = 80$.', '[]', '5', NULL, 'Divide by 5: $2^{x-1} = 16 = 2^4$. So $x - 1 = 4$ and $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 * 2^(x-1) = 80 -> 2^(x-1) = 16 = 2^4 -> x - 1 = 4 -> x = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
