INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adfa7d67-b312-4985-b5f6-cacec3809391', 'NC26.M1.ANFR.5', 3, 'numeric', 'Interpret the solution of an equation or inequality', 'Plan A costs $20 + 5g$ dollars and Plan B costs $8 + 7g$ dollars for $g$ gigabytes of data. For how many gigabytes do the two plans cost the same?', '[]', '6', '(20-8)/(7-5)', 'Set the costs equal: $20 + 5g = 8 + 7g$. Subtract $5g$ and 8: $12 = 2g$. So $g = 6$ gigabytes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 5g = 8 + 7g -> 12 = 2g -> g = 6. Check: 50 = 50.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb278d0a-ee30-4b19-adfe-15383be523a2', 'NC26.M1.ANFR.5', 3, 'numeric', 'Interpret the solution of an equation or inequality', 'A class already has 120 cans for recycling, and each student brings 4 more. The class needs at least 500 cans. What is the least number of students needed?', '[]', '95', '(500-120)/4', 'The inequality is $120 + 4s \ge 500$. Subtract 120: $4s \ge 380$. Divide by 4: $s \ge 95$. The least number is 95 students.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 + 4s >= 500 -> 4s >= 380 -> s >= 95. Least number of students 95.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('492bcd35-31c1-483b-8e15-e0c2d01e640d', 'NC26.M1.ANFR.5', 3, 'choice', 'Interpret the solution of an equation or inequality', 'The inequality $2x + 5 > 17$ has the solution $x > 6$, where $x$ is the number of whole boxes ordered. Which statement is correct?', '["At least 6 boxes must be ordered","At least 7 boxes must be ordered","At most 7 boxes can be ordered","Exactly 7 boxes must be ordered"]', 'At least 7 boxes must be ordered', NULL, '$x > 6$ and $x$ is a whole number, so $x$ can be 7, 8, 9, and so on. The smallest allowed number is 7, so at least 7 boxes must be ordered.', 'checked', '{"lint":[],"solve":{"answer":"At least 7 boxes must be ordered","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x > 6 with x a whole number means x >= 7: at least 7 boxes must be ordered. (At least 6 would allow 6, which fails 2(6)+5 = 17 > 17.)","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd8809ad-52cb-42da-9f42-d801645bf554', 'NC26.M1.ANFR.5', 3, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'Car A is 30 kilometers ahead of car B and travels at 60 kilometers per hour. Car B travels at 75 kilometers per hour in the same direction. After how many hours does car B catch up to car A?', '[]', '2', '30/(75-60)', 'Car B gains $75 - 60 = 15$ kilometers each hour. It must make up 30 kilometers, so it takes $30 \div 15 = 2$ hours. (Equation: $30 + 60t = 75t$.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Positions: A = 30 + 60t, B = 75t. Equal: 75t = 30 + 60t -> 15t = 30 -> t = 2 hours.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff8afd81-b015-4259-b0fd-4147fe8084b5', 'NC26.M1.ANFR.5', 3, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'One third of a number plus 5 equals one half of the same number minus 3. What is the number?', '[]', '48', '8/(1/2-1/3)', 'With the number $n$: $\frac{n}{3} + 5 = \frac{n}{2} - 3$. Move terms: $8 = \frac{n}{2} - \frac{n}{3} = \frac{n}{6}$. So $n = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/3 + 5 = x/2 - 3 -> multiply by 6: 2x + 30 = 3x - 18 -> x = 48. Check: 16 + 5 = 21; 24 - 3 = 21.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
