INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cec2419-89dc-4bac-a255-d1fffeb80dd0', 'NC26.M1.ANFR.5', 3, 'choice', 'Write and solve a linear equation or inequality from a situation', 'A class trip costs a bus fee of 300 dollars plus 12 dollars for each student. Each student pays 18 dollars. Which inequality can be solved to find the number of students $s$ needed for the payments to cover the cost?', '["$18s \\ge 300 - 12s$","$18s + 12s \\ge 300$","$18 + 12s \\ge 300$","$18s \\ge 300 + 12s$"]', '$18s \ge 300 + 12s$', NULL, 'The money collected is $18s$. The cost is $300 + 12s$. Payments cover the cost when $18s \ge 300 + 12s$.', 'checked', '{"lint":[],"solve":{"answer":"$18s \\ge 300 + 12s$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Payments: 18s. Cost: 300 + 12s. Payments cover cost: 18s >= 300 + 12s (s >= 50).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d232ba87-d536-4cb5-898a-f51b16aed2eb', 'NC26.M1.ANFR.5', 3, 'numeric', 'Interpret the solution of an equation or inequality', 'An elevator can carry at most 1200 pounds in all, counting the 150-pound operator who always rides. Each box weighs 80 pounds. What is the greatest number of boxes the elevator can carry on one trip?', '[]', '13', NULL, 'The total weight is $150 + 80b \le 1200$, so $80b \le 1050$ and $b \le 13.125$. Only whole boxes can be carried, so the greatest number is 13. Check: $150 + 80(13) = 1190 \le 1200$, but 14 boxes would weigh $150 + 1120 = 1270$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 + 80b <= 1200 -> 80b <= 1050 -> b <= 13.125. Greatest whole number 13. Check: 150 + 1040 = 1190 <= 1200; 14 boxes gives 1270.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2319747d-e118-4426-b587-34abc24717c2', 'NC26.M1.ANFR.6', 1, 'choice', 'Test a point in a two-variable inequality', 'Which point is a solution of $y \ge x + 1$?', '["$(1, 3)$","$(3, 1)$","$(2, 2)$","$(4, 4)$"]', '$(1, 3)$', NULL, 'Put each point in. For $(1, 3)$: $3 \ge 1 + 1 = 2$ is true. For $(3, 1)$: $1 \ge 4$ is false. For $(2, 2)$: $2 \ge 3$ is false. For $(4, 4)$: $4 \ge 5$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,3): 3 >= 2 yes. (4,4): 4 >= 5 no. (3,1): 1 >= 4 no. (2,2): 2 >= 3 no.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb4d5f2c-cd95-42c3-9bc7-53a9be0d7769', 'NC26.M1.ANFR.6', 1, 'numeric', 'Find the boundary value of y for a given x', 'The inequality is $y < 3x + 2$. For the point $(4, y)$ to be a solution, what is the greatest whole number that $y$ can be?', '[]', '13', '3*4+2-1', 'When $x = 4$: $y < 3(4) + 2 = 14$. The greatest whole number less than 14 is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y < 3(4) + 2 = 14 (strict). Greatest whole number y = 13.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ba17924-b40d-4198-800f-d2f24f9fd984', 'NC26.M1.ANFR.6', 1, 'choice', 'Write a linear inequality from a context', 'A theater sells child tickets for 5 dollars each ($x$ of them) and adult tickets for 8 dollars each ($y$ of them). Total ticket sales for one show must be at most 200 dollars. Which inequality models this?', '["$5x + 8y \\ge 200$","$8x + 5y \\le 200$","$5x + 8y \\le 200$","$13(x + y) \\le 200$"]', '$5x + 8y \le 200$', NULL, 'Child sales are $5x$ dollars and adult sales are $8y$ dollars, so the total is $5x + 8y$. "At most 200" means $\le 200$.', 'checked', '{"lint":[],"solve":{"answer":"$5x + 8y \\le 200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor realism: a theater capping its sales at ''at most'' 200 dollars is an odd context (a cost or budget limit reads more naturally), though the maths and key are unambiguous.","work":"Child sales 5x, adult sales 8y, total at most 200: 5x + 8y <= 200.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db6b79e1-269e-4254-bd5e-b664dc9894bb', 'NC26.M1.ANFR.6', 1, 'choice', 'Write an inequality from a context', 'Dana spends 20 minutes on each math worksheet and 15 minutes on each reading section. She has no more than 90 minutes in all. If she does $m$ worksheets and $r$ reading sections, which inequality models this?', '["$20m + 15r \\ge 90$","$20m + 15r \\le 90$","$15m + 20r \\le 90$","$20m + 15r < 90$"]', '$20m + 15r \le 90$', NULL, '$m$ worksheets take $20m$ minutes and $r$ reading sections take $15r$ minutes. "No more than 90" allows a total of exactly 90 or less, so the inequality is $20m + 15r \le 90$.', 'checked', '{"lint":[],"solve":{"answer":"$20m + 15r \\le 90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Worksheets 20m minutes, reading 15r minutes; \"no more than 90\" means <= 90.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61e5a37e-5934-4acf-b900-168947c728c8', 'NC26.M1.ANFR.6', 1, 'numeric', 'Write an inequality from a context', 'A coach wants at least 3 dozen balls in all, a mix of $x$ soccer balls and $y$ basketballs. This is written $x + y \ge N$. What number is $N$?', '[]', '36', '3*12', 'One dozen is 12, so 3 dozen is $3 \times 12 = 36$. The coach needs $x + y \ge 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 dozen = 3 x 12 = 36.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('215da490-15ba-46cb-8db9-b091eba7ca0c', 'NC26.M1.ANFR.6', 1, 'choice', 'Write an inequality from a context', 'A bakery must bake at least 50 loaves each morning, $w$ of wheat bread and $r$ of rye bread. Which inequality shows this?', '["$w + r \\le 50$","$w + r > 50$","$w + r \\ge 50$","$w - r \\ge 50$"]', '$w + r \ge 50$', NULL, 'The total number of loaves is $w + r$. "At least 50" means 50 or more, so the symbol is $\ge$: $w + r \ge 50$.', 'checked', '{"lint":[],"solve":{"answer":"$w + r \\ge 50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total loaves w + r, \"at least 50\": w + r >= 50.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb05779-cb77-4442-865b-682c513e85d6', 'NC26.M1.ANFR.6', 1, 'choice', 'Test a point in a linear inequality', 'Which ordered pair is a solution of $2x + y < 7$?', '["$(3, 2)$","$(2, 3)$","$(4, 0)$","$(1, 3)$"]', '$(1, 3)$', NULL, 'Substitute each pair. For $(1, 3)$: $2(1) + 3 = 5$, and $5 < 7$ is true. For $(3, 2)$ the value is 8, for $(2, 3)$ it is 7 (not less than 7), and for $(4, 0)$ it is 8. Only $(1, 3)$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3): 7 < 7 no. (3,2): 8 no. (1,3): 5 < 7 yes. (4,0): 8 no.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9226074b-5fdb-4c2d-952b-e0cb66cc4125', 'NC26.M1.ANFR.6', 1, 'numeric', 'Test a point in a linear inequality', 'How many of the points $(0, 5)$, $(2, 3)$, $(4, 1)$, $(6, 0)$ and $(3, 3)$ are solutions of $x + y \le 5$?', '[]', '3', NULL, 'Add the coordinates of each point. $(0, 5)$ gives 5, $(2, 3)$ gives 5 and $(4, 1)$ gives 5, and each is at most 5. $(6, 0)$ gives 6 and $(3, 3)$ gives 6, which are too big. So 3 points are solutions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + y: (0,5) 5 yes, (2,3) 5 yes, (4,1) 5 yes, (6,0) 6 no, (3,3) 6 no. 3 points.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64a7baf4-2db8-493e-906c-2e570fc332cc', 'NC26.M1.ANFR.6', 1, 'choice', 'Test a point in a linear inequality', 'The point $(2, -1)$ is a solution of which inequality?', '["$y < 3x - 5$","$y > x + 1$","$x + y > 3$","$2x + y \\le 2$"]', '$y < 3x - 5$', NULL, 'Put $x = 2$ and $y = -1$ into each one. $y < 3x - 5$ becomes $-1 < 1$, which is true. The others become $-1 > 3$ (false), $1 > 3$ (false) and $3 \le 2$ (false).', 'checked', '{"lint":[],"solve":{"answer":"$y < 3x - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,-1): x + y = 1 > 3 no; 3x - 5 = 1, -1 < 1 yes; x + 1 = 3, -1 > 3 no; 2x + y = 3 <= 2 no.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4512e25c-43ad-48f6-91bd-cca41ebfa3b1', 'NC26.M1.ANFR.6', 1, 'choice', 'Interpret a solution in context', 'At a school fair, a ride ticket costs 2 dollars and a snack costs 3 dollars. Mia has 20 dollars, so a plan of $x$ rides and $y$ snacks must satisfy $2x + 3y \le 20$. Which plan can Mia afford?', '["4 rides and 5 snacks","5 rides and 3 snacks","6 rides and 3 snacks","3 rides and 5 snacks"]', '5 rides and 3 snacks', NULL, 'Find the cost of each plan. 5 rides and 3 snacks: $10 + 9 = 19$ dollars, within 20. 4 rides and 5 snacks: $8 + 15 = 23$. 6 rides and 3 snacks: $12 + 9 = 21$. 3 rides and 5 snacks: $6 + 15 = 21$. Only the first plan costs at most 20 dollars.', 'checked', '{"lint":[],"solve":{"answer":"5 rides and 3 snacks","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3y: 5 and 3: 19 <= 20 yes; 4 and 5: 23; 6 and 3: 21; 3 and 5: 21.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fe98e8e-d9f3-49b8-9355-e2c14306b057', 'NC26.M1.ANFR.6', 1, 'numeric', 'Interpret a solution in context', 'Fish food costs 3 dollars a bag and treats cost 2 dollars a pack. A pet store has a budget of 30 dollars, so $3f + 2t \le 30$. The store buys 6 bags of fish food ($f = 6$) and 4 packs of treats ($t = 4$). How many dollars of the budget are left?', '[]', '4', '30-(3*6+2*4)', 'The purchases cost $3(6) + 2(4) = 18 + 8 = 26$ dollars. That leaves $30 - 26 = 4$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(6) + 2(4) = 18 + 8 = 26; 30 - 26 = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a04b1e6-8b11-4813-ab6c-7d070b1df020', 'NC26.M1.ANFR.6', 1, 'choice', 'Interpret a solution in context', 'A student can spend at most 20 dollars on $n$ notebooks at 2 dollars each and $p$ pens at 3 dollars each, so $2n + 3p \le 20$. What does the solution $(n, p) = (4, 3)$ mean?', '["Buying 3 notebooks and 4 pens costs 18 dollars, within the limit","Notebooks cost 4 dollars each and pens cost 3 dollars each","Buying 4 notebooks and 3 pens costs 17 dollars, within the limit","Buying 4 notebooks and 3 pens costs exactly 20 dollars"]', 'Buying 4 notebooks and 3 pens costs 17 dollars, within the limit', NULL, 'The first number is $n$ and the second is $p$, so $(4, 3)$ is 4 notebooks and 3 pens. They cost $2(4) + 3(3) = 8 + 9 = 17$ dollars, which is less than 20, so the purchase is allowed.', 'checked', '{"lint":[],"solve":{"answer":"Buying 4 notebooks and 3 pens costs 17 dollars, within the limit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(4) + 3(3) = 8 + 9 = 17 <= 20: 4 notebooks and 3 pens for 17 dollars.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c699c84-2f55-40f5-b29f-06717ec36120', 'NC26.M1.ANFR.6', 1, 'choice', 'Solid or dashed boundary line', 'Which inequality has a solid boundary line when it is graphed?', '["$y < 3x$","$y > x - 2$","$x + y < 6$","$y \\ge -x + 4$"]', '$y \ge -x + 4$', NULL, 'A solid line is used when points on the line are solutions, which happens with $\le$ or $\ge$. Of these, only $y \ge -x + 4$ has an "or equal to" symbol. The other three use $<$ or $>$ and have dashed lines.', 'checked', '{"lint":[],"solve":{"answer":"$y \\ge -x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solid boundary for <= or >=; only y >= -x + 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce85831-8451-46f5-8563-fcac35b0819d', 'NC26.M1.ANFR.6', 1, 'numeric', 'Solid or dashed boundary line', 'How many of these inequalities have a dashed boundary line: $y < x$, $y \le 2x$, $y > 3x + 1$, $y \ge x - 1$, $x + y > 7$?', '[]', '3', NULL, 'A dashed line goes with a strict symbol, $<$ or $>$. The inequalities $y < x$, $y > 3x + 1$ and $x + y > 7$ are strict. The other two include "or equal to" and have solid lines. So 3 are dashed.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dashed for strict < or >: y < x, y > 3x + 1, x + y > 7. That is 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36fba5ed-850b-47a9-98f6-10e2b5d38939', 'NC26.M1.ANFR.6', 1, 'choice', 'Solid or dashed boundary line', 'Marcus graphs $x + 2y < 10$. Which statement about the boundary line $x + 2y = 10$ is true?', '["Dashed, because $(10, 0)$ is on the line but $10 < 10$ is false","Solid, because $(10, 0)$ is on the line and $10 < 10$ is true","Dashed, because $(10, 0)$ is on the line and $10 < 10$ is true","Solid, because $(10, 0)$ is on the line but $10 < 10$ is false"]', 'Dashed, because $(10, 0)$ is on the line but $10 < 10$ is false', NULL, 'The point $(10, 0)$ is on the line, and $10 + 2(0) = 10$. Since $10 < 10$ is false, points on the line are not solutions, so the line is dashed.', 'checked', '{"lint":[],"solve":{"answer":"Dashed, because $(10, 0)$ is on the line but $10 < 10$ is false","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strict <: points on the line are not solutions; (10,0) gives 10 < 10, false, so dashed.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53dcf477-6f78-4e36-a4bd-d1bf2f30200d', 'NC26.M1.ANFR.6', 1, 'choice', 'Decide which side is shaded', 'To graph $y > 3x - 5$, which part of the plane is shaded?', '["The region below the boundary line","The region above the boundary line","The region to the left of the boundary line","The region to the right of the boundary line"]', 'The region above the boundary line', NULL, 'The inequality says $y$ is greater than the line''s value, so the solutions have larger $y$-values than the line, which is above it.', 'checked', '{"lint":[],"solve":{"answer":"The region above the boundary line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y > 3x - 5 with y alone and >: shade above the line.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4b4f162-4931-4182-bb8d-c675a0ad8b57', 'NC26.M1.ANFR.6', 1, 'numeric', 'Decide which side is shaded', 'Solving $y - 2x > 5$ for $y$ gives $y > 2x + c$. What is $c$?', '[]', '5', '5', 'Add $2x$ to both sides: $y > 2x + 5$. So $c = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 2x to both sides: y > 2x + 5, so c = 5.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
