INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be98430-d144-4f08-b852-5ebe41c3f66b', 'NC26.M1.ANFR.6', 1, 'choice', 'Intercepts of the boundary line', 'What is the $y$-intercept of the boundary line of $y > 2x + 7$?', '["$(7, 0)$","$(0, 2)$","$(0, -7)$","$(0, 7)$"]', '$(0, 7)$', NULL, 'The boundary line is $y = 2x + 7$. At $x = 0$, $y = 7$, so the line crosses the $y$-axis at $(0, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2x + 7 crosses the y-axis at (0, 7).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
