INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfa6f3ee-5007-485d-9fdd-8332810eae33', 'NC26.M1.ANFR.6', 1, 'numeric', 'Intercepts of the boundary line', 'Tess has 24 dollars to spend on pencils at 3 dollars each ($x$) and pens at 2 dollars each ($y$), so $3x + 2y \le 24$. If she buys no pencils, what is the greatest number of pens she can afford?', '[]', '12', '24/2', 'With no pencils, $x = 0$ and the inequality becomes $2y \le 24$. So $y \le 12$, and she can afford at most 12 pens. This is the $y$-intercept of the boundary line.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0: 2y <= 24, y <= 12.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a0aa52d-e0dd-450b-a27d-7511d599d1b6', 'NC26.M1.ANFR.6', 1, 'choice', 'Write an inequality from a described graph', 'A graph has a solid boundary line $y = -x + 3$ with the region below it shaded. Which inequality does it show?', '["$y \\le -x + 3$","$y \\ge -x + 3$","$y < -x + 3$","$y \\le x + 3$"]', '$y \le -x + 3$', NULL, 'A solid line means "or equal to", and the shaded region below the line has smaller $y$-values. So the inequality is $y \le -x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y \\le -x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solid -> includes equality; below -> y <= -x + 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3d61b39-dfc3-45a8-ad27-6e340bae5cc3', 'NC26.M1.ANFR.6', 1, 'numeric', 'Write an inequality from a described graph', 'A graph shows a solid boundary line with slope 3 and $y$-intercept $-2$. The region above the line is shaded. Its inequality is $y \ge 3x + b$. What is $b$?', '[]', '-2', '-2', 'The line is $y = 3x + b$ with $b$ equal to the $y$-intercept. The $y$-intercept is $-2$, so $b = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-intercept -2, so b = -2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
