INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14078dcc-f049-46a0-a911-207a6530e9a7', 'NC26.M1.ANFR.6', 1, 'choice', 'Write an inequality from a described graph', 'A graph shows a dashed vertical line at $x = 5$ with the region to the right of it shaded. Which inequality does it show?', '["$x < 5$","$x > 5$","$x \\ge 5$","$y > 5$"]', '$x > 5$', NULL, 'Points to the right of the line have $x$-values greater than 5. The line is dashed, so 5 itself is not included. The inequality is $x > 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x > 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dashed (strict), right of x = 5: x > 5.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0f15053-8066-4bb1-9ecf-49ffb6b7526d', 'NC26.M1.ANFR.6', 1, 'numeric', 'Greatest or least value of one variable', 'A basket holds at most 20 pieces of fruit, $a$ apples and $p$ pears, so $a + p \le 20$. If the basket has 8 apples, what is the greatest whole number of pears it can have?', '[]', '12', '20-8', 'With $a = 8$: $8 + p \le 20$, so $p \le 12$. The greatest number of pears is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + p <= 20 -> p <= 12.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a311063-6dd8-4345-9ff7-203bec83b864', 'NC26.M1.ANFR.6', 1, 'numeric', 'Greatest or least value of one variable', 'The pair $(5, y)$ is a solution of $y > 2x - 3$. What is the least whole number $y$ can be?', '[]', '8', '2*5-3+1', 'With $x = 5$, $2x - 3 = 7$, so $y > 7$. The least whole number greater than 7 is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y > 2(5) - 3 = 7, so least whole number y = 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
