INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d39d8d4-97e2-41c3-97bc-83988234a176', 'NC26.M1.ANFR.6', 1, 'choice', 'Greatest or least value of one variable', 'In $2x + y \le 10$, suppose $x = 3$. What is the greatest whole number $y$ can be?', '["5","7","4","3"]', '4', '10-2*3', 'Put $x = 3$: $6 + y \le 10$, so $y \le 4$. The greatest whole number is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + y <= 10 -> y <= 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc84a618-8426-45a6-9c63-59c6c2419b13', 'NC26.M1.ANFR.6', 1, 'numeric', 'Count whole-number solutions', 'How many pairs of whole numbers $(x, y)$, counting 0, satisfy $x + y \le 2$?', '[]', '6', NULL, 'List them by $x$. If $x = 0$, $y$ can be 0, 1 or 2 (3 pairs). If $x = 1$, $y$ can be 0 or 1 (2 pairs). If $x = 2$, $y$ must be 0 (1 pair). The total is $3 + 2 + 1 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 0: (0,0); sum 1: 2 pairs; sum 2: 3 pairs. Total 6.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9369d20-ab95-40b0-b142-997274d8328d', 'NC26.M1.ANFR.6', 1, 'choice', 'Count whole-number solutions', 'Which list shows every pair of positive whole numbers $(x, y)$ that satisfies $x + y < 4$?', '["$(1, 1), (1, 2), (2, 1), (2, 2)$","$(1, 1), (1, 2), (1, 3), (2, 1), (3, 1)$","$(1, 1), (1, 2)$","$(1, 1), (1, 2), (2, 1)$"]', '$(1, 1), (1, 2), (2, 1)$', NULL, 'Positive whole numbers start at 1, and the sum must be 3 or less. The pairs with sum 2 or 3 are $(1, 1)$, $(1, 2)$ and $(2, 1)$. A pair like $(2, 2)$ has sum 4, which is not less than 4.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 1), (1, 2), (2, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Positive x, y with x + y <= 3: (1,1), (1,2), (2,1).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a33c460-c375-4209-928e-445c6bf41e45', 'NC26.M1.ANFR.6', 1, 'numeric', 'Count whole-number solutions', 'Both $x$ and $y$ are whole numbers from 0 to 3, so there are 16 possible pairs $(x, y)$. How many of the pairs make $x + y > 3$ true?', '[]', '6', '16-10', 'Count the pairs with $x + y \le 3$ and subtract. For $x = 0$ there are 4 such pairs, for $x = 1$ there are 3, for $x = 2$ there are 2 and for $x = 3$ there is 1, a total of 10. So $16 - 10 = 6$ pairs have $x + y > 3$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4: (1,3),(2,2),(3,1); sum 5: (2,3),(3,2); sum 6: (3,3). Total 6.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90aa9f85-76d8-413c-b2b6-b0b31e9a1253', 'NC26.M1.ANFR.6', 1, 'choice', 'Reason about the solution set', 'The pairs $(x, y)$ can be any numbers, including fractions and decimals. How many pairs are solutions of $x + y \le 10$?', '["Infinitely many pairs","Exactly one pair","Exactly 10 pairs","Exactly 11 pairs"]', 'Infinitely many pairs', NULL, 'Pick any $x$, such as 1, 2.5 or $-3$, and many values of $y$ work with it. There is no end to the choices, so the inequality has infinitely many solutions. Its graph is a whole region, not a few points.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many pairs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Over real numbers the solution set is a half-plane: infinitely many points.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('102adf5f-f342-4756-ad49-ad2c04106311', 'NC26.M1.ANFR.6', 1, 'numeric', 'Reason about the solution set', 'The point $(3, 4)$ is a solution of $y \ge 2x + c$ and lies on its boundary line. What is $c$?', '[]', '-2', '4-2*3', 'A point on the boundary line satisfies $y = 2x + c$. So $4 = 2(3) + c = 6 + c$, and $c = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"On the line: 4 = 2(3) + c, so c = -2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ae1732c-10cc-41a0-ac5c-8fbc81233054', 'NC26.M1.ANFR.6', 1, 'choice', 'Reason about the solution set', 'Which of these points is NOT a solution of $x - y \ge 3$?', '["$(6, 2)$","$(3, 1)$","$(5, 1)$","$(4, 1)$"]', '$(3, 1)$', NULL, 'Find $x - y$ for each. $(6, 2)$: 4. $(5, 1)$: 4. $(4, 1)$: 3. $(3, 1)$: 2. A solution needs $x - y \ge 3$, and 2 is less than 3, so $(3, 1)$ is not a solution.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - y: (3,1) 2 (not >= 3); (5,1) 4; (4,1) 3; (6,2) 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153cc497-1ce3-4e9f-9035-e42b6475e2b7', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from its boundary line', 'The solutions of an inequality are all the points above the line $y = 2x - 1$, and points on the line are not solutions. Which inequality is it?', '["$y \\ge 2x - 1$","$y > 2x - 1$","$y < 2x - 1$","$y > -2x - 1$"]', '$y > 2x - 1$', NULL, 'Points above the line have $y$ greater than $2x - 1$, so the sign is $>$. Points on the line are not included, so it is $>$ and not $\ge$.', 'checked', '{"lint":[],"solve":{"answer":"$y > 2x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Above the line, line excluded: strict >, same line y = 2x - 1: y > 2x - 1.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d456565-4ec3-467f-8eca-955173f84f1f', 'NC26.M1.ANFR.6', 2, 'numeric', 'Interpret a solution of an inequality in context', 'A school buys $x$ notebooks at 3 dollars each and $y$ pens at 2 dollars each. Its budget is 60 dollars, so $3x + 2y \le 60$. If the school buys 12 notebooks, what is the greatest number of pens it can buy?', '[]', '12', '(60-3*12)/2', 'With $x = 12$: $36 + 2y \le 60$, so $2y \le 24$ and $y \le 12$. The greatest number of pens is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(12) + 2y <= 60 -> 2y <= 24 -> y <= 12. Greatest 12.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8ec0be2-f67f-41da-b7ab-3febac86137f', 'NC26.M1.ANFR.6', 2, 'choice', 'Find a point that is not a solution', 'Which point is NOT a solution of $2x + 3y \le 12$?', '["$(0, 0)$","$(3, 2)$","$(-2, 4)$","$(6, 1)$"]', '$(6, 1)$', NULL, 'Test each point. $(0, 0)$: $0 \le 12$ is true. $(3, 2)$: $6 + 6 = 12 \le 12$ is true. $(-2, 4)$: $-4 + 12 = 8 \le 12$ is true. $(6, 1)$: $12 + 3 = 15 \le 12$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,2): 6 + 6 = 12 <= 12 yes. (6,1): 12 + 3 = 15 > 12 NOT a solution. (-2,4): -4 + 12 = 8 yes. (0,0): 0 yes.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62649bf7-b093-4b2d-9b35-c79b28c9538d', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a context', 'Ava jogs at 6 miles per hour for $j$ hours and walks at 3 miles per hour for $w$ hours. She wants to cover more than 15 miles in all. Which inequality models this?', '["$6j + 3w \\ge 15$","$3j + 6w > 15$","$6j + 3w > 15$","$6j + 3w < 15$"]', '$6j + 3w > 15$', NULL, 'Distance is rate times time: $6j$ miles jogging and $3w$ miles walking. "More than 15" does not include 15, so the symbol is $>$: $6j + 3w > 15$.', 'checked', '{"lint":[],"solve":{"answer":"$6j + 3w > 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance 6j + 3w, \"more than 15\": strict >.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74711309-f18b-4e27-a200-dbb73a8795d3', 'NC26.M1.ANFR.6', 2, 'numeric', 'Write an inequality from a context', 'A trainer charges 30 dollars an hour for private lessons ($p$ hours) and 15 dollars an hour for group lessons ($g$ hours). To earn at least 450 dollars, $30p + 15g \ge 450$. Dividing every term by 15 gives $2p + g \ge M$. What number is $M$?', '[]', '30', '450/15', 'Divide each term by 15: $30p \div 15 = 2p$, $15g \div 15 = g$ and $450 \div 15 = 30$. The inequality is $2p + g \ge 30$, so $M = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/15 = 2, 15/15 = 1, 450/15 = 30, so 2p + g >= 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a3e45df-c562-40bf-90b5-7b1ee94868e8', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a context', 'Noah has 80 dollars. He buys $s$ shirts at 15 dollars each and $h$ hats at 9 dollars each, and he also pays one shipping fee of 5 dollars. Which inequality shows what he can buy?', '["$15s + 9h \\le 85$","$15s + 9h + 5 \\ge 80$","$15s + 14h \\le 80$","$15s + 9h + 5 \\le 80$"]', '$15s + 9h + 5 \le 80$', NULL, 'Shirts cost $15s$ and hats cost $9h$. The 5 dollar fee is paid once, so it is added once to the total: $15s + 9h + 5$. He can spend at most 80 dollars, so $15s + 9h + 5 \le 80$.', 'checked', '{"lint":[],"solve":{"answer":"$15s + 9h + 5 \\le 80$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 15s + 9h plus the 5 dollar fee, at most 80: 15s + 9h + 5 <= 80.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d10c39d-85e8-48a1-b31b-a52a429326c2', 'NC26.M1.ANFR.6', 2, 'choice', 'Test a point in a linear inequality', 'Which point is a solution of $3x - 2y > 5$?', '["$(3, 1)$","$(1, -1)$","$(2, 2)$","$(-2, -5)$"]', '$(3, 1)$', NULL, 'Test each point in $3x - 2y > 5$. $(3, 1)$ gives $9 - 2 = 7$, and $7 > 5$ is true. $(1, -1)$ gives $3 + 2 = 5$, which is not greater than 5. $(2, 2)$ gives $2$, and $(-2, -5)$ gives $-6 + 10 = 4$. Only $(3, 1)$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2y: (-2,-5) 4; (1,-1) 5 (not > 5); (2,2) 2; (3,1) 7 > 5 yes.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27ae06d6-8268-4ad3-96d2-4a417f768e3a', 'NC26.M1.ANFR.6', 2, 'numeric', 'Test a point in a linear inequality', 'How many of the points $(-1, 2)$, $(0, -4)$, $(3, -2)$, $(-5, 0)$ and $(2, 1)$ make $y \ge 2x - 3$ true?', '[]', '3', NULL, 'Check $y \ge 2x - 3$ at each point. $(-1, 2)$: $2 \ge -5$ true. $(0, -4)$: $-4 \ge -3$ false. $(3, -2)$: $-2 \ge 3$ false. $(-5, 0)$: $0 \ge -13$ true. $(2, 1)$: $1 \ge 1$ true. That is 3 points.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 3: (-1,2): 2 >= -5 yes; (0,-4): -4 >= -3 no; (3,-2): -2 >= 3 no; (-5,0): 0 >= -13 yes; (2,1): 1 >= 1 yes. 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ddaacaf-64f9-4e52-80dc-58100410c5ca', 'NC26.M1.ANFR.6', 2, 'choice', 'Test a point in a linear inequality', 'Nia says $(4, -3)$ is a solution of $x + 2y \le -2$. Which statement is correct?', '["She is wrong, because $4 + 2(-3) = -2$ and $-2$ is not less than $-2$","She is right, because $4 + 2(-3) = -2$ and $-2 \\le -2$ is true","She is wrong, because $4 + 2(-3) = 10$ and $10 \\le -2$ is false","She is right, because $4 + (-3) = 1$ and $1 \\le 2$ is true"]', 'She is right, because $4 + 2(-3) = -2$ and $-2 \le -2$ is true', NULL, 'Substitute: $4 + 2(-3) = 4 - 6 = -2$. The inequality says "less than or equal to", and $-2 \le -2$ is true, so $(4, -3)$ is a solution and Nia is right.', 'checked', '{"lint":[],"solve":{"answer":"She is right, because $4 + 2(-3) = -2$ and $-2 \\le -2$ is true","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 2(-3) = -2 and -2 <= -2 is true (the symbol includes equality), so she is right.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95b93054-e5ce-499a-ae68-f910b1f381d4', 'NC26.M1.ANFR.6', 2, 'choice', 'Interpret a solution in context', 'A club must raise at least 600 dollars. Adult tickets cost 12 dollars each ($a$ sold) and student tickets cost 8 dollars each ($s$ sold), so $12a + 8s \ge 600$. The club sells 30 adult tickets and 25 student tickets. Which statement is true?', '["The goal is met, with 40 dollars to spare","The goal is met, with exactly 600 dollars raised","The goal is not met; sales are 40 dollars short","The goal is not met; sales are 240 dollars short"]', 'The goal is not met; sales are 40 dollars short', NULL, 'Sales are $12(30) + 8(25) = 360 + 200 = 560$ dollars. Since $560 < 600$, the pair $(30, 25)$ is not a solution, and the club is $600 - 560 = 40$ dollars short.', 'checked', '{"lint":[],"solve":{"answer":"The goal is not met; sales are 40 dollars short","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12(30) + 8(25) = 360 + 200 = 560 < 600: 40 dollars short.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20ead600-45f0-4d41-826b-ea671709cec0', 'NC26.M1.ANFR.6', 2, 'numeric', 'Interpret a solution in context', 'A truck''s load limit is 2000 pounds, so $40c + 25p \le 2000$, where $c$ is the number of apple crates (40 pounds each) and $p$ is the number of pear crates (25 pounds each). A driver loads 30 apple crates and 24 pear crates. By how many pounds is the load under the limit?', '[]', '200', '2000-(40*30+25*24)', 'The load weighs $40(30) + 25(24) = 1200 + 600 = 1800$ pounds. The limit is 2000, so the load is $2000 - 1800 = 200$ pounds under it.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40(30) + 25(24) = 1200 + 600 = 1800; 2000 - 1800 = 200.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3311167-e6e7-4293-8d85-cfbc054d2000', 'NC26.M1.ANFR.6', 2, 'choice', 'Interpret a solution in context', 'A tutor has 20 hours a week for sessions. A group session ($g$ of them) takes 1.5 hours and a private session ($p$ of them) takes 1 hour, so $1.5g + p \le 20$. The pair $(g, p) = (8, 8)$ gives $1.5(8) + 8 = 20$. What does this tell us?', '["The tutor has 8 hours left over after these sessions","The tutor is 8 hours over the limit with these sessions","The tutor teaches 16 hours, so 4 hours are left over","The tutor uses all 20 hours, with none left over"]', 'The tutor uses all 20 hours, with none left over', NULL, 'The 8 group sessions take $1.5 \times 8 = 12$ hours and the 8 private sessions take 8 hours, a total of 20 hours. The limit is 20, so the plan fits exactly and no time is left.', 'checked', '{"lint":[],"solve":{"answer":"The tutor uses all 20 hours, with none left over","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5(8) + 8 = 12 + 8 = 20 = the limit: all 20 hours used, none left.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e3f74d-5af9-4f2a-95f2-3e679633e692', 'NC26.M1.ANFR.6', 2, 'choice', 'Solid or dashed boundary line', 'Pens cost 2 dollars each and pads cost 5 dollars each. Which rule for the total cost gives an inequality with a dashed boundary line when graphed?', '["The total cost is less than 40 dollars","The total cost is at most 40 dollars","The total cost is at least 40 dollars","The total cost is no less than 40 dollars"]', 'The total cost is less than 40 dollars', NULL, 'A dashed line goes with a strict inequality. "Less than 40" is strict ($<$). "At most", "at least" and "no less than" all allow a total of exactly 40, so those graphs have solid lines.', 'checked', '{"lint":[],"solve":{"answer":"The total cost is less than 40 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dashed needs a strict inequality: \"less than 40\" is 2x + 5y < 40. At least / at most / no less than include equality (solid).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1033c06-d5a3-4d9a-a97c-f9482e0e9476', 'NC26.M1.ANFR.6', 2, 'numeric', 'Solid or dashed boundary line', 'How many of these inequalities are graphed with a solid boundary line: $3x - 2y \ge 12$, $5x + y < 8$, $y \le 4x$, $x - y > 1$, $2x + 3y \ge 6$?', '[]', '3', NULL, 'Solid lines go with $\le$ and $\ge$. The inequalities $3x - 2y \ge 12$, $y \le 4x$ and $2x + 3y \ge 6$ include "or equal to". $5x + y < 8$ and $x - y > 1$ are strict. So 3 have solid lines.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solid for >= or <=: 3x - 2y >= 12, y <= 4x, 2x + 3y >= 6. That is 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d53d288-0dc8-42ac-b0bd-94bf4880cf65', 'NC26.M1.ANFR.6', 2, 'choice', 'Solid or dashed boundary line', 'Taylor graphs $y > -2x + 6$ and draws a solid boundary line. Which statement is correct?', '["The line is correct, because every graph of a linear inequality has a solid boundary","The line should be dashed, because a point on the line makes $y > -2x + 6$ false","The line should be dashed, because the slope of the line is negative","The line is correct, because a point on the line makes $y > -2x + 6$ true"]', 'The line should be dashed, because a point on the line makes $y > -2x + 6$ false', NULL, 'Take a point on the line, such as $(0, 6)$. Then $6 > 6$ is false, so points on the line are not solutions. The boundary must be dashed. The slope does not decide this.', 'checked', '{"lint":[],"solve":{"answer":"The line should be dashed, because a point on the line makes $y > -2x + 6$ false","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strict >: a point on the line gives equality, which makes > false, so the line must be dashed.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2d6b3f4-e04c-4440-a540-88632590c6a3', 'NC26.M1.ANFR.6', 2, 'choice', 'Decide which side is shaded', 'Which point cannot be used as a test point to decide which side of the line $y = 2x$ to shade?', '["$(0, 3)$","$(4, 1)$","$(0, 0)$","$(1, 6)$"]', '$(0, 0)$', NULL, 'A test point must not be on the boundary line. The point $(0, 0)$ is on $y = 2x$, since $0 = 2(0)$. The points $(0, 3)$, $(4, 1)$ and $(1, 6)$ are not on the line, so any of them works.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0,0) satisfies y = 2x (0 = 0), so it lies on the line and cannot decide a side. (1,6), (4,1), (0,3) are off the line.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fab2d405-4627-47ec-9598-e797a6fbe0d0', 'NC26.M1.ANFR.6', 2, 'numeric', 'Decide which side is shaded', 'The point $(2, 3)$ lies in the shaded region of $4x - y > k$, where $k$ is a whole number. What is the greatest whole number $k$ can be?', '[]', '4', '5-1', 'At $(2, 3)$, $4x - y = 8 - 3 = 5$. The point is shaded only if $5 > k$. The greatest whole number less than 5 is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2) - 3 = 5 > k, so k < 5; greatest whole number k = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0cb0a25-6f0c-42b0-8baa-92dfd018c02f', 'NC26.M1.ANFR.6', 2, 'choice', 'Decide which side is shaded', 'The boundary line of $2x - 5y < 10$ is graphed. Testing the origin gives $0 < 10$, which is true. Which part is shaded?', '["The side not containing the origin, which is below the line","The side below the line, because the symbol is \"less than\"","The side containing the origin, which is below the line","The side containing the origin, which is above the line"]', 'The side containing the origin, which is above the line', NULL, 'Because $(0, 0)$ makes the inequality true, the shaded side is the one containing the origin. Solving gives $y > \frac{2}{5}x - 2$, and the origin has $0 > -2$, so that side is above the line. The symbol alone does not tell which side is shaded.', 'checked', '{"lint":[],"solve":{"answer":"The side containing the origin, which is above the line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 2x - 5y = 10 has y-intercept -2, so the origin is above it. Origin test true, so shade the side containing the origin, which is above (equivalently y > 0.4x - 2).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c118d711-66b9-4487-a7d0-cb0ab5c6e640', 'NC26.M1.ANFR.6', 2, 'numeric', 'Intercepts of the boundary line', 'The boundary line of $3x - 4y \ge 24$ crosses the $x$-axis at what $x$-value?', '[]', '8', '24/3', 'On the $x$-axis $y = 0$. The boundary line is $3x - 4y = 24$, so $3x = 24$ and $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 0: 3x = 24, x = 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb2433dc-e6ed-465e-ad18-bb1e1cd51d26', 'NC26.M1.ANFR.6', 2, 'choice', 'Intercepts of the boundary line', 'Which pair gives the intercepts of the boundary line of $5x + 2y < 30$?', '["$(6, 0)$ and $(0, 15)$","$(0, 6)$ and $(15, 0)$","$(5, 0)$ and $(0, 2)$","$(30, 0)$ and $(0, 30)$"]', '$(6, 0)$ and $(0, 15)$', NULL, 'For the $x$-intercept let $y = 0$: $5x = 30$, so $x = 6$ and the point is $(6, 0)$. For the $y$-intercept let $x = 0$: $2y = 30$, so $y = 15$ and the point is $(0, 15)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 0)$ and $(0, 15)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 2y = 30: x-intercept 6 -> (6,0); y-intercept 15 -> (0,15).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('865e02cf-7a49-4296-9118-cc29d35bd892', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a described graph', 'A dashed boundary line passes through $(0, 3)$ and $(2, 7)$, and the region below it is shaded. Which inequality does the graph show?', '["$y > 2x + 3$","$y < 3x + 2$","$y < 2x + 3$","$y < 4x + 3$"]', '$y < 2x + 3$', NULL, 'The slope is $\frac{7 - 3}{2 - 0} = 2$ and the $y$-intercept is 3, so the line is $y = 2x + 3$. A dashed line with shading below gives $y < 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y < 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (7 - 3)/(2 - 0) = 2, intercept 3: y = 2x + 3. Dashed, below: y < 2x + 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458628c1-3b0b-41ce-b710-a72637aec048', 'NC26.M1.ANFR.6', 2, 'numeric', 'Write an inequality from a described graph', 'The boundary line of a graph passes through $(0, -1)$ and $(3, 5)$. What is its slope?', '[]', '2', '(5+1)/3', 'Slope is rise over run: $\frac{5 - (-1)}{3 - 0} = \frac{6}{3} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5 - (-1)) / (3 - 0) = 6/3 = 2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2b0b9ca-ce62-4698-8bf3-075bc8fdcb41', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a described graph', 'A solid boundary line passes through $(0, 6)$ and $(3, 0)$. The shaded region includes the origin. Which inequality does the graph show?', '["$y \\ge -2x + 6$","$y \\le 2x + 6$","$y \\le -\\frac{1}{2}x + 6$","$y \\le -2x + 6$"]', '$y \le -2x + 6$', NULL, 'The slope is $\frac{0 - 6}{3 - 0} = -2$ and the $y$-intercept is 6, so the line is $y = -2x + 6$. The origin gives $0 \le 6$, which is true, so the shading is below the line and the inequality is $y \le -2x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y \\le -2x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (0 - 6)/(3 - 0) = -2, intercept 6: y = -2x + 6. Origin: 0 <= 6 true, so y <= -2x + 6 (solid).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('283a8764-f3c0-4961-b433-075a0f5bd4d9', 'NC26.M1.ANFR.6', 2, 'numeric', 'Greatest or least value of one variable', 'A band sells T-shirts at 15 dollars each ($t$ sold) and posters at 6 dollars each ($p$ sold). It wants at least 500 dollars, so $15t + 6p \ge 500$. After selling 20 T-shirts, what is the least whole number of posters it must sell?', '[]', '34', '(500-15*20)/6+2/3', 'The 20 T-shirts bring in $15 \times 20 = 300$ dollars. The posters must bring in at least $500 - 300 = 200$ dollars, so $6p \ge 200$ and $p \ge 33.3\ldots$. Posters are whole, so the least number is 34.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15(20) = 300; 6p >= 200; p >= 33.3..., least whole number 34.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbf36dc8-ebc9-4314-931a-e94a9022dba5', 'NC26.M1.ANFR.6', 2, 'numeric', 'Greatest or least value of one variable', 'A box can hold at most 50 ounces. Item A weighs 7 ounces ($x$ of them) and item B weighs 4 ounces ($y$ of them), so $7x + 4y \le 50$. With 4 of item A in the box, what is the greatest whole number of item B that fits?', '[]', '5', '(50-28)/4-1/2', 'Four of item A weigh $7 \times 4 = 28$ ounces, leaving $50 - 28 = 22$ ounces. Then $4y \le 22$, so $y \le 5.5$. The greatest whole number is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7(4) = 28; 4y <= 22; y <= 5.5; greatest whole number 5.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e92557d9-8429-4060-87ec-9e92c8a04cea', 'NC26.M1.ANFR.6', 2, 'choice', 'Greatest or least value of one variable', 'Ben earns 9 dollars an hour mowing lawns ($m$ hours) and 6 dollars an hour raking leaves ($r$ hours). He wants at least 100 dollars, so $9m + 6r \ge 100$. If he mows for 6 hours, what is the least whole number of hours he must rake?', '["8","7","46","6"]', '8', '(100-9*6)/6+1/3', 'Mowing for 6 hours earns $9 \times 6 = 54$ dollars. He still needs $100 - 54 = 46$ dollars, so $6r \ge 46$ and $r \ge 7.67$. He must rake a whole number of hours, so the least is 8 hours.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9(6) = 54; 6r >= 46; r >= 7.67; least whole number 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29732871-5fed-4fb5-8655-708826aa5b99', 'NC26.M1.ANFR.6', 2, 'numeric', 'Count whole-number solutions', 'How many pairs of whole numbers $(x, y)$, counting 0, make $2x + y \le 6$ true?', '[]', '16', '7+5+3+1', 'Count the allowed $y$-values for each $x$. $x = 0$: $y \le 6$, so 7 values. $x = 1$: $y \le 4$, so 5 values. $x = 2$: $y \le 2$, so 3 values. $x = 3$: $y \le 0$, so 1 value. The total is $7 + 5 + 3 + 1 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0: y 0-6 (7); x = 1: y 0-4 (5); x = 2: y 0-2 (3); x = 3: y = 0 (1). Total 16.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ca6b0a4-0c40-403c-87cc-f83e2b96aa7e', 'NC26.M1.ANFR.6', 2, 'choice', 'Count whole-number solutions', 'How many pairs of positive whole numbers $(x, y)$ satisfy $3x + 2y \le 14$?', '["10","12","24","15"]', '12', '5+4+2+1', 'Count the allowed $y$-values for each $x$. $x = 1$: $2y \le 11$, so $y = 1$ to 5 (5 values). $x = 2$: $2y \le 8$, so $y = 1$ to 4 (4 values). $x = 3$: $2y \le 5$, so $y = 1, 2$ (2 values). $x = 4$: $2y \le 2$, so $y = 1$ (1 value). The total is $5 + 4 + 2 + 1 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 1: 2y <= 11, y 1-5 (5); x = 2: 2y <= 8, y 1-4 (4); x = 3: 2y <= 5, y 1-2 (2); x = 4: 2y <= 2, y = 1 (1). Total 12.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b054c9db-e3d8-4002-be5a-bee77af20e03', 'NC26.M1.ANFR.6', 2, 'numeric', 'Count whole-number solutions', 'A club orders at least 1 poster (3 dollars each) and at least 1 sticker pack (2 dollars each) for a total of at most 12 dollars. How many different orders $(p, s)$, with $p$ posters and $s$ sticker packs, are possible?', '[]', '8', '4+3+1', 'The cost is $3p + 2s \le 12$. If $p = 1$, $2s \le 9$, so $s = 1$ to 4 (4 orders). If $p = 2$, $2s \le 6$, so $s = 1$ to 3 (3 orders). If $p = 3$, $2s \le 3$, so $s = 1$ (1 order). If $p = 4$, no pack fits. The total is $4 + 3 + 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3p + 2s <= 12, p, s >= 1. p = 1: s <= 4.5 (4); p = 2: s <= 3 (3); p = 3: s <= 1.5 (1). Total 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b36a885-c67d-45ce-be86-e0356d3591fb', 'NC26.M1.ANFR.6', 2, 'choice', 'Reason about the solution set', 'Which inequality has exactly the same solutions as $2x + 4y \le 12$?', '["$x + 2y \\ge 6$","$x + 4y \\le 6$","$x + 2y \\le 6$","$x + 2y \\le 12$"]', '$x + 2y \le 6$', NULL, 'Divide every term by 2. Dividing by a positive number keeps the symbol: $x + 2y \le 6$. The other choices change the symbol or divide only some of the terms.', 'checked', '{"lint":[],"solve":{"answer":"$x + 2y \\le 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 2: x + 2y <= 6.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e971147-4085-42e5-bff4-197514ea6cdb', 'NC26.M1.ANFR.6', 2, 'numeric', 'Reason about the solution set', 'The point $(4, 3)$ lies on the boundary line of $ax + y \ge 11$. What is $a$?', '[]', '2', '(11-3)/4', 'A point on the boundary line makes the two sides equal: $a(4) + 3 = 11$. Then $4a = 8$ and $a = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a + 3 = 11 -> a = 2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ced4636-eb13-471e-bf56-51ad8ce8d0f4', 'NC26.M1.ANFR.6', 2, 'choice', 'Reason about the solution set', 'The point $(2, 5)$ is a solution of $y > 3x - 2$. Which statement must be true?', '["$(2, 4)$ is also a solution","$(3, 5)$ is also a solution","$(2, 5)$ lies on the boundary line","$(2, 6)$ is also a solution"]', '$(2, 6)$ is also a solution', NULL, 'Check each statement. At $(2, 6)$: $6 > 4$, true. At $(2, 4)$: $4 > 4$, false. At $(3, 5)$: $5 > 7$, false. For $(2, 5)$, the line has $y = 4$ at $x = 2$, not 5, so the point is not on the line. Only "$(2, 6)$ is also a solution" is true.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 6)$ is also a solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 2 the boundary is y = 4; (2,5) works because 5 > 4, so any larger y, e.g. (2,6), also works. (2,4) is on the line (not a solution), (3,5): 5 > 7 false, (2,5) is not on the line.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc9ff913-f552-4303-9af2-5d5151f9a1fa', 'NC26.M1.ANFR.6', 2, 'choice', 'Intercepts of the boundary line', 'A garden rule is $3p + 5q \le 45$, where $p$ is the number of herb pots (3 dollars each), $q$ is the number of flower pots (5 dollars each) and 45 dollars is the budget. The boundary line passes through the point $(0, 9)$, written as $(p, q)$. Which statement describes this point?', '["9 flower pots and no herb pots use up the whole budget","9 herb pots and no flower pots use up the whole budget","9 herb pots and 9 flower pots use up the whole budget","9 flower pots and no herb pots cost 9 dollars"]', '9 flower pots and no herb pots use up the whole budget', NULL, 'At $(0, 9)$ we have $p = 0$ and $q = 9$, so the cost is $3(0) + 5(9) = 45$, exactly the budget. That is 9 flower pots and no herb pots. Nine herb pots would cost only 27 dollars, and 9 of each would cost 72 dollars.', 'checked', '{"lint":[],"solve":{"answer":"9 flower pots and no herb pots use up the whole budget","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(p, q) = (0, 9): 0 herb pots, 9 flower pots; cost 3(0) + 5(9) = 45, the whole budget.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('926eaf83-695d-40d1-bb2e-be8774092c2c', 'NC26.M1.ANFR.6', 3, 'numeric', 'Count whole-number solutions of an inequality', 'How many ordered pairs $(x, y)$ of positive whole numbers make $x + y \le 5$ true?', '[]', '10', '4+3+2+1', 'List by $x$. If $x = 1$, then $y$ can be 1, 2, 3 or 4 (4 pairs). If $x = 2$: $y$ is 1, 2 or 3 (3 pairs). If $x = 3$: 2 pairs. If $x = 4$: 1 pair. If $x = 5$ there is no positive $y$. Total: $4 + 3 + 2 + 1 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x, y >= 1. x=1: y = 1..4 (4); x=2: 3; x=3: 2; x=4: 1; x=5 impossible. Total 4+3+2+1 = 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd441674-299f-426c-9c09-5840421e7d5d', 'NC26.M1.ANFR.6', 3, 'choice', 'Interpret a solution point in context', 'A club sells $a$ adult tickets at 15 dollars each and $b$ child tickets at 10 dollars each. To reach its goal, it needs $15a + 10b \ge 120$. What does the solution $(a, b) = (4, 6)$ mean?', '["Selling 4 adult and 6 child tickets raises more than 120 dollars, so the goal is beaten","Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met","Selling 4 adult and 6 child tickets raises less than 120 dollars, so the goal is missed","Selling 4 adult and 6 child tickets raises 4 + 6 = 10 dollars, far below the goal"]', 'Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met', NULL, 'Put in the numbers: $15(4) + 10(6) = 60 + 60 = 120$, and $120 \ge 120$ is true. The ticket sales raise exactly the 120 dollars needed, so this point lies on the boundary.', 'checked', '{"lint":[],"solve":{"answer":"Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15(4) + 10(6) = 60 + 60 = 120, which equals 120, so the goal is exactly met (>= holds with equality).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f43da357-8d05-42a3-bfb7-4bc40e2bc3c9', 'NC26.M1.ANFR.6', 3, 'numeric', 'Use the boundary line of an inequality', 'The boundary line of the inequality $3x - 2y \ge 6$ is the line $3x - 2y = 6$. The point $(4, k)$ lies on this line. What is $k$?', '[]', '3', '(3*4-6)/2', 'Put $x = 4$ in $3x - 2y = 6$: $12 - 2k = 6$, so $2k = 6$ and $k = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(4) - 2k = 6 -> 12 - 2k = 6 -> k = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77506f41-649b-4c0b-8799-eb71bc3ed373', 'NC26.M1.ANFR.6', 3, 'choice', 'Write an inequality from a context', 'A plumber charges a 45 dollar service fee, plus 30 dollars an hour for one worker ($x$ hours) and 20 dollars an hour for a helper ($y$ hours). A customer wants the bill to be under 200 dollars. Which inequality models this?', '["$45 + 30x + 20y \\le 200$","$45(30x + 20y) < 200$","$30x + 20y < 200 + 45$","$45 + 30x + 20y < 200$"]', '$45 + 30x + 20y < 200$', NULL, 'The bill is the fee plus the two hourly charges: $45 + 30x + 20y$. "Under 200 dollars" does not allow exactly 200, so the symbol is $<$: $45 + 30x + 20y < 200$.', 'checked', '{"lint":[],"solve":{"answer":"$45 + 30x + 20y < 200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bill 45 + 30x + 20y; \"under 200\" is strict: < 200.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('046c794c-2f8b-407f-a32e-1a5080643f04', 'NC26.M1.ANFR.6', 3, 'numeric', 'Write an inequality from a context', 'A tank already holds 60 liters and can hold 200 liters in all. Hose A adds 8 liters a minute for $x$ minutes and hose B adds 5 liters a minute for $y$ minutes. To avoid overflow, $8x + 5y \le K$. What number is $K$?', '[]', '140', '200-60', 'The two hoses can add only what the tank has room for: $200 - 60 = 140$ liters. So $8x + 5y \le 140$ and $K = 140$.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Room left = 200 - 60 = 140 liters, so 8x + 5y <= 140.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4496f062-2cf8-4385-ad97-37df385d9fd4', 'NC26.M1.ANFR.6', 3, 'numeric', 'Write an inequality from a context', 'A shipping box can hold at most 2 kilograms. Each book weighs 400 grams and each notebook weighs 150 grams. With $b$ books and $n$ notebooks, the inequality is $400b + 150n \le G$, with $G$ in grams. What is $G$?', '[]', '2000', '2*1000', 'The weights are in grams, so change the limit to grams: 2 kilograms is $2 \times 1000 = 2000$ grams. The inequality is $400b + 150n \le 2000$.', 'checked', '{"lint":[],"solve":{"answer":"2000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 kg = 2000 g.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('571d5848-e80d-4081-bae5-927bd108c998', 'NC26.M1.ANFR.6', 3, 'choice', 'Test a point in a linear inequality', 'Which point is a solution of $3(x - 1) \ge 2y + 1$?', '["$(5, 3)$","$(4, 5)$","$(1, 1)$","$(0, -1)$"]', '$(5, 3)$', NULL, 'Substitute into both sides. $(5, 3)$: left side $3(4) = 12$, right side $2(3) + 1 = 7$, and $12 \ge 7$ is true. $(4, 5)$: $9 \ge 11$ is false. $(1, 1)$: $0 \ge 3$ is false. $(0, -1)$: $-3 \ge -1$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x-1) vs 2y+1: (1,1) 0 >= 3 no; (5,3) 12 >= 7 yes; (0,-1) -3 >= -1 no; (4,5) 9 >= 11 no.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7b4e97a-8f0a-451c-b0ea-02e4211c844c', 'NC26.M1.ANFR.6', 3, 'numeric', 'Test a point in a linear inequality', 'A student wants to know which of five points make $\frac{x}{2} - y > 1$ true. The points are $(0, 0)$, $(4, -2)$, $(-6, 3)$, $(8, 4)$ and $(2, -5)$. How many of them do?', '[]', '2', NULL, 'Evaluate $\frac{x}{2} - y$ at each point. $(0, 0)$: $0$. $(4, -2)$: $2 + 2 = 4$. $(-6, 3)$: $-3 - 3 = -6$. $(8, 4)$: $4 - 4 = 0$. $(2, -5)$: $1 + 5 = 6$. Only 4 and 6 are greater than 1, so 2 points are solutions.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 - y: (0,0) 0 no; (4,-2) 4 yes; (-6,3) -6 no; (8,4) 0 no; (2,-5) 6 yes. 2 points.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62b0eb9c-318e-450a-aa2f-3c11e1f85b55', 'NC26.M1.ANFR.6', 3, 'numeric', 'Test a point in a linear inequality', 'Each of $x$ and $y$ can be $-1$, $0$ or $1$, which gives nine points $(x, y)$. How many of these nine points satisfy $x - 2y \ge 1$?', '[]', '4', NULL, 'If $y = -1$, then $x - 2y = x + 2$, which is at least 1 for all three values of $x$ ($1$, $2$, $3$): 3 points. If $y = 0$, we need $x \ge 1$: only $x = 1$, 1 point. If $y = 1$, then $x - 2 \ge 1$ needs $x \ge 3$: none. The total is $3 + 1 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -1: x + 2 >= 1 for x = -1, 0, 1 (3). y = 0: x >= 1 (x = 1, 1). y = 1: x >= 3 (none). Total 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7b7ef36-c404-435d-b5fe-d1e794120fd1', 'NC26.M1.ANFR.6', 3, 'choice', 'Interpret a solution in context', 'A group buys $x$ child tickets at 5 dollars each and $y$ adult tickets at 7 dollars each for at most 70 dollars, so $5x + 7y \le 70$. Which pair is a solution of the inequality but cannot happen in this situation?', '["$(4, 7)$","$(-2, 10)$","$(6, 6)$","$(0, 10)$"]', '$(-2, 10)$', NULL, '$(-2, 10)$ gives $-10 + 70 = 60 \le 70$, so it is a solution of the inequality, but nobody can buy $-2$ tickets. $(4, 7)$ gives 69 and $(0, 10)$ gives 70: both are solutions that can happen. $(6, 6)$ gives 72, which is not a solution at all.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, 10)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,7): 69 <= 70, possible. (6,6): 72 > 70, not a solution. (-2,10): -10 + 70 = 60 <= 70 is a solution, but -2 tickets is impossible. (0,10): 70 <= 70, possible.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9a8b94a-162f-4eb2-a25a-7cc776955862', 'NC26.M1.ANFR.6', 3, 'numeric', 'Interpret a solution in context', 'Jin plans to buy 12 bags of seed at 4 dollars each ($x = 12$) and 10 bags of soil at 7 dollars each ($y = 10$). His budget is 100 dollars, so a plan must satisfy $4x + 7y \le 100$. By how many dollars does this plan go over the budget?', '[]', '18', '4*12+7*10-100', 'The plan costs $4(12) + 7(10) = 48 + 70 = 118$ dollars. That is $118 - 100 = 18$ dollars over the budget, so it is not a solution.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(12) + 7(10) = 48 + 70 = 118; 118 - 100 = 18 over.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31b5fc63-0658-451e-b4b8-02b81783d0c5', 'NC26.M1.ANFR.6', 3, 'numeric', 'Interpret a solution in context', 'Sara has a 90-minute study block, so $12m + 9s \le 90$, where $m$ is the number of math sets (12 minutes each) and $s$ is the number of science sets (9 minutes each). She does 4 math sets, then as many whole science sets as fit in the time left. How many minutes of the block are left over?', '[]', '6', '90-12*4-9*4', 'Four math sets take $12 \times 4 = 48$ minutes, leaving $90 - 48 = 42$ minutes. Science sets take 9 minutes, and $4 \times 9 = 36 \le 42$ while $5 \times 9 = 45 > 42$, so she fits 4 sets. The time left over is $42 - 36 = 6$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 math sets = 48 min; 90 - 48 = 42 left; 42 / 9 = 4 sets (36 min); 42 - 36 = 6 minutes left.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00738497-c276-4685-b9d8-9a6a4a166744', 'NC26.M1.ANFR.6', 3, 'choice', 'Solid or dashed boundary line', 'Which statement is true about the graphs of $y \ge 2x - 3$ and $y > 2x - 3$?', '["Same boundary line, but the two graphs shade opposite sides of it","Different boundary lines, though both graphs shade the side above","Same line and same shading; only the graph of $y \\ge 2x - 3$ includes the line","Same shading, and both graphs are drawn with a dashed boundary line"]', 'Same line and same shading; only the graph of $y \ge 2x - 3$ includes the line', NULL, 'Both have the boundary $y = 2x - 3$ and both are true above the line, so the shading is the same. The graph of $y \ge 2x - 3$ has "or equal to", so its line is solid and its points are solutions. The graph of $y > 2x - 3$ has a dashed line, so points on the line are not solutions.', 'checked', '{"lint":[],"solve":{"answer":"Same line and same shading; only the graph of $y \\ge 2x - 3$ includes the line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both have boundary y = 2x - 3 and shade above; >= is solid (includes the line), > is dashed.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3904f5a8-ea6e-49b0-b86e-9c0761d5735a', 'NC26.M1.ANFR.6', 3, 'numeric', 'Solid or dashed boundary line', 'The inequality $y < 2x - 1$ has a dashed boundary line. How many of the points $(0, -2)$, $(1, 1)$, $(2, 2)$, $(3, 5)$, $(4, 6)$ and $(5, 9)$ are solutions?', '[]', '3', NULL, 'Compare $y$ with $2x - 1$ at each point. $(0, -2)$: $-2 < -1$ true. $(1, 1)$: $1 < 1$ false (on the line). $(2, 2)$: $2 < 3$ true. $(3, 5)$: $5 < 5$ false (on the line). $(4, 6)$: $6 < 7$ true. $(5, 9)$: $9 < 9$ false (on the line). The line is dashed, so 3 points are solutions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 1: (0,-2) -2 < -1 yes; (1,1) 1 < 1 no; (2,2) 2 < 3 yes; (3,5) 5 < 5 no; (4,6) 6 < 7 yes; (5,9) 9 < 9 no. 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6469b243-d976-4468-9f22-d6177c80eec0', 'NC26.M1.ANFR.6', 3, 'choice', 'Solid or dashed boundary line', 'The point $(3, 2)$ lies on the boundary line of each inequality below. For which inequality is $(3, 2)$ also a solution?', '["$2x - y < 4$","$x - y > 1$","$y < x - 1$","$x + y \\le 5$"]', '$x + y \le 5$', NULL, 'A point on the boundary is a solution only when the inequality includes "or equal to". Only $x + y \le 5$ does: $3 + 2 = 5 \le 5$. In the other three, the point makes the two sides equal, and a strict symbol is false for equal values.', 'checked', '{"lint":[],"solve":{"answer":"$x + y \\le 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,2) gives equality in each; only a non-strict symbol accepts it: x + y = 5 <= 5 true. The others are strict (1 > 1, 2 < 2, 4 < 4 all false).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ab01efc-cd9c-4531-ab4f-1f9d0d9a2d4f', 'NC26.M1.ANFR.6', 3, 'choice', 'Decide which side is shaded', 'Which description matches the graph of $-2y > 6x - 4$?', '["A dashed line $y = -3x + 2$, shaded below it","A dashed line $y = -3x + 2$, shaded above it","A dashed line $y = 3x - 2$, shaded below it","A dashed line $y = 3x - 2$, shaded above it"]', 'A dashed line $y = -3x + 2$, shaded below it', NULL, 'Divide both sides by $-2$ and reverse the symbol: $y < -3x + 2$. The boundary is the dashed line $y = -3x + 2$ and the solutions have smaller $y$-values, so they are below the line.', 'checked', '{"lint":[],"solve":{"answer":"A dashed line $y = -3x + 2$, shaded below it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by -2 and reverse: y < -3x + 2. Strict: dashed, shade below.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('644bcb89-38d7-41e1-9f04-54f9d2fd624b', 'NC26.M1.ANFR.6', 3, 'numeric', 'Decide which side is shaded', 'Rewriting $3x - 2y > 8$ with $y$ alone gives $y < mx - 4$. What is $m$? Give it as a fraction.', '[]', '3/2', '3/2', 'Subtract $3x$: $-2y > -3x + 8$. Divide by $-2$ and reverse the symbol: $y < \frac{3}{2}x - 4$. So $m = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2y > 8 - 3x; divide by -2 and reverse: y < (3/2)x - 4. m = 3/2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
