INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2086ef76-cd31-49e7-802a-8591ab3dc607', 'NC26.M1.ANFR.6', 3, 'choice', 'Decide which side is shaded', 'Which inequality is graphed by shading above its boundary line?', '["$3x + y < 6$","$x - 2y < 4$","$x - y > 2$","$2x - y > 4$"]', '$x - 2y < 4$', NULL, 'Solve each for $y$. $3x + y < 6$ gives $y < -3x + 6$ (below). $x - y > 2$ gives $y < x - 2$ (below). $2x - y > 4$ gives $y < 2x - 4$ (below). $x - 2y < 4$ gives $-2y < -x + 4$, so $y > \frac{1}{2}x - 2$ (above).', 'checked', '{"lint":[],"solve":{"answer":"$x - 2y < 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + y < 6 -> y < -3x + 6 (below). 2x - y > 4 -> y < 2x - 4 (below). x - y > 2 -> y < x - 2 (below). x - 2y < 4 -> y > x/2 - 2 (above).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72067a0c-213e-426a-a479-b702c4731030', 'NC26.M1.ANFR.6', 3, 'numeric', 'Intercepts of the boundary line', 'The boundary line of $3x + ky < 36$ has a $y$-intercept of 9. What is $k$?', '[]', '4', '36/9', 'At the $y$-intercept $x = 0$, so the boundary line gives $ky = 36$. With $y = 9$, $9k = 36$, so $k = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At the y-intercept x = 0: 9k = 36, k = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aaea9653-e676-42be-bb92-d4f8bca5952d', 'NC26.M1.ANFR.6', 3, 'choice', 'Intercepts of the boundary line', 'Which pair gives the intercepts of the boundary line of $2x - 3y \ge 12$?', '["$(6, 0)$ and $(0, 4)$","$(-6, 0)$ and $(0, -4)$","$(6, 0)$ and $(0, -4)$","$(0, 6)$ and $(-4, 0)$"]', '$(6, 0)$ and $(0, -4)$', NULL, 'Let $y = 0$: $2x = 12$, so $x = 6$ and the point is $(6, 0)$. Let $x = 0$: $-3y = 12$, so $y = -4$ and the point is $(0, -4)$. Dividing by $-3$ makes the $y$-intercept negative.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 0)$ and $(0, -4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 3y = 12: x-intercept 6 -> (6,0); y-intercept -4 -> (0,-4).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe19bde0-9ccb-47b3-b598-ddc60399a215', 'NC26.M1.ANFR.6', 3, 'numeric', 'Intercepts of the boundary line', 'The boundary line of $y > -\frac{2}{3}x + 4$ crosses the $x$-axis at what $x$-value?', '[]', '6', '4/(2/3)', 'On the $x$-axis $y = 0$, so $0 = -\frac{2}{3}x + 4$. Then $\frac{2}{3}x = 4$ and $x = 4 \times \frac{3}{2} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 = -(2/3)x + 4 -> (2/3)x = 4 -> x = 6.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0e49787-7b77-4be6-9d15-83126b4bf95c', 'NC26.M1.ANFR.6', 3, 'choice', 'Write an inequality from a described graph', 'A solid boundary line passes through $(2, 0)$ and $(0, 4)$. The shaded region does not contain the origin. Which inequality does the graph show?', '["$2x + y \\le 4$","$2x + y > 4$","$x + 2y \\ge 4$","$2x + y \\ge 4$"]', '$2x + y \ge 4$', NULL, 'The line through $(2, 0)$ and $(0, 4)$ is $2x + y = 4$. The origin gives $0 \ge 4$, which is false, so the shaded side is the other one: $2x + y \ge 4$. The line is solid, so the symbol includes "or equal to".', 'checked', '{"lint":[],"solve":{"answer":"$2x + y \\ge 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Through (2,0) and (0,4): 2x + y = 4. Solid; origin gives 0 >= 4 false, so shading away from origin: 2x + y >= 4. (x + 2y = 4 is a different line.)","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a00edc0c-ec06-47e0-adba-8fcda6e067ea', 'NC26.M1.ANFR.6', 3, 'numeric', 'Write an inequality from a described graph', 'The inequality $y < \frac{1}{2}x + c$ has a dashed boundary line that passes through $(4, 5)$. What is $c$?', '[]', '3', '5-4/2', 'The point is on the line, so $5 = \frac{1}{2}(4) + c = 2 + c$. Then $c = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 = (1/2)(4) + c = 2 + c, so c = 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a12961b3-1282-4b02-8db9-ecbfaa8be20d', 'NC26.M1.ANFR.6', 3, 'choice', 'Write an inequality from a described graph', 'A dashed boundary line passes through $(-2, 0)$ and $(0, 3)$. The shaded region contains the origin. Which inequality does the graph show?', '["$3x - 2y > -6$","$3x - 2y < -6$","$2x - 3y > -6$","$3x + 2y > -6$"]', '$3x - 2y > -6$', NULL, 'The line has slope $\frac{3 - 0}{0 - (-2)} = \frac{3}{2}$ and $y$-intercept 3, so $y = \frac{3}{2}x + 3$, or $3x - 2y = -6$. The origin gives $0 > -6$, which is true, so the origin''s side is shaded: $3x - 2y > -6$. The line is dashed, so the symbol is strict.', 'checked', '{"lint":[],"solve":{"answer":"$3x - 2y > -6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Through (-2,0), (0,3): slope 3/2, y = 1.5x + 3 -> 3x - 2y = -6. Dashed. Origin: 0 > -6 true, so 3x - 2y > -6. Other options are different lines or exclude the origin.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b88dd12-031d-4400-87f8-5d865ae2d369', 'NC26.M1.ANFR.6', 3, 'numeric', 'Greatest or least value of one variable', 'A taxi charges a base fare of 4 dollars, plus 3 dollars a mile in the city ($c$ miles) and 2 dollars a mile on the highway ($h$ miles). A rider wants to pay at most 40 dollars, so $4 + 3c + 2h \le 40$. If the rider goes 7 city miles, what is the greatest whole number of highway miles?', '[]', '7', '(40-4-3*7)/2-1/2', 'The base fare and the city miles cost $4 + 3(7) = 25$ dollars, leaving $40 - 25 = 15$ dollars. Then $2h \le 15$, so $h \le 7.5$. The greatest whole number of highway miles is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 3(7) = 25; 2h <= 15; h <= 7.5; greatest whole number 7.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d68631cd-85a6-4f3f-93cc-a6a17867a909', 'NC26.M1.ANFR.6', 3, 'numeric', 'Greatest or least value of one variable', 'Whole numbers $x$ and $y$ satisfy $2x + 3y \le 30$ and $y \ge 4$. What is the greatest possible value of $x$?', '[]', '9', '(30-3*4)/2', 'The value of $x$ is greatest when $y$ is as small as possible, so use $y = 4$. Then $2x + 12 \le 30$, so $2x \le 18$ and $x \le 9$. The greatest possible $x$ is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To maximise x take the least y, 4: 2x + 12 <= 30 -> x <= 9.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcf2d176-f5db-4b33-8928-5fe2dd2cff6d', 'NC26.M1.ANFR.6', 3, 'numeric', 'Count whole-number solutions', 'How many pairs of positive whole numbers $(x, y)$ satisfy $x + 3y \le 12$?', '[]', '18', '9+6+3', 'Count by $y$. If $y = 1$, $x \le 9$ (9 pairs). If $y = 2$, $x \le 6$ (6 pairs). If $y = 3$, $x \le 3$ (3 pairs). If $y = 4$, $x \le 0$, so none. The total is $9 + 6 + 3 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 1: x 1-9 (9); y = 2: x 1-6 (6); y = 3: x 1-3 (3); y = 4: x <= 0 (0). Total 18.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36129fb8-0181-4f1b-aeaa-999a328df87e', 'NC26.M1.ANFR.6', 3, 'choice', 'Count whole-number solutions', 'Exactly one of these inequalities has exactly 6 solutions in positive whole numbers $(x, y)$. Which one?', '["$x + y \\le 5$","$x + y < 4$","$x + y \\le 4$","$2x + y \\le 5$"]', '$x + y \le 4$', NULL, 'Count the positive whole-number pairs for each. $x + y \le 4$: 3 + 2 + 1 = 6. $x + y \le 5$: 4 + 3 + 2 + 1 = 10. $x + y < 4$: 2 + 1 = 3. $2x + y \le 5$: $(1, 1), (1, 2), (1, 3), (2, 1)$ = 4. Only $x + y \le 4$ has 6.', 'checked', '{"lint":[],"solve":{"answer":"$x + y \\le 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Positive solutions: x + y < 4: 3. x + y <= 5: 1 + 2 + 3 + 4 = 10. 2x + y <= 5: x = 1 (3), x = 2 (1) = 4. x + y <= 4: 1 + 2 + 3 = 6.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cec881f-949b-435b-a052-c5b9fb6d164d', 'NC26.M1.ANFR.6', 3, 'choice', 'Reason about the solution set', 'Which inequality has exactly the same solutions as $-3x + 6y > 9$?', '["$x - 2y > -3$","$x - 2y < 3$","$-x + 2y < 3$","$x - 2y < -3$"]', '$x - 2y < -3$', NULL, 'Multiply both sides by $-\frac{1}{3}$ (divide by $-3$) and reverse the symbol: $x - 2y < -3$. Keeping the symbol, changing the sign of 3, or reversing the symbol on a division by $+3$ would each give a different set.', 'checked', '{"lint":[],"solve":{"answer":"$x - 2y < -3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by -3 and reverse: x - 2y < -3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e60ea07f-9025-4b6d-8b9e-f00cc68f9434', 'NC26.M1.ANFR.6', 3, 'numeric', 'Reason about the solution set', 'The solutions of $y \ge mx + 2$ include the point $(3, 11)$ on the boundary line. The point $(2, p)$ is also on the boundary line. What is $p$?', '[]', '8', '(11-2)/3*2+2', 'On the boundary, $11 = 3m + 2$, so $3m = 9$ and $m = 3$. The line is $y = 3x + 2$. At $x = 2$: $p = 3(2) + 2 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 = 3m + 2 -> m = 3. p = 3(2) + 2 = 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4d9bfaa-d125-42bf-9157-7bce4035d613', 'NC26.M1.ANFR.6', 3, 'numeric', 'Greatest or least value of one variable', 'The point $(x, 1)$ is a solution of $-2x + 5y \le -9$, where $x$ is an integer. What is the least value $x$ can have?', '[]', '7', '(9+5)/2', 'Put $y = 1$: $-2x + 5 \le -9$, so $-2x \le -14$. Dividing by $-2$ reverses the inequality: $x \ge 7$. The least integer is 7. Check: $-2(7) + 5 = -9$, which is allowed.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 5(1) <= -9 -> -2x <= -14 -> x >= 7. Least integer 7. Check x=7: -14+5 = -9 <= -9 true; x=6: -7 > -9 false.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('108f9a7c-80fc-4e55-9e43-84e795f3f2d5', 'NC26.M1.ANFR.6', 3, 'numeric', 'Count integer solutions', 'Both $x$ and $y$ are integers from $-2$ to $2$, which gives 25 pairs $(x, y)$. How many of these pairs make $x - y \ge 2$ true?', '[]', '6', NULL, 'List the pairs by $x$. If $x = 0$, $y$ must be $-2$ (1 pair). If $x = 1$, $y$ can be $-2$ or $-1$ (2 pairs). If $x = 2$, $y$ can be $-2$, $-1$ or $0$ (3 pairs). For $x = -2$ or $-1$ no $y$ works. The total is $1 + 2 + 3 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - y = 2: (0,-2),(1,-1),(2,0) = 3. x - y = 3: (1,-2),(2,-1) = 2. x - y = 4: (2,-2) = 1. Total 6.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9252ec37-afeb-48fb-835f-55cfcec462b7', 'NC26.M1.ANFR.6', 3, 'choice', 'Reason about the solution set', 'Consider the solutions of $y \ge x - 2$ and the solutions of $y \le x - 2$ taken together. What do they cover?', '["only the points on the line $y = x - 2$","every point of the plane except those on the line $y = x - 2$","only the points above the line $y = x - 2$","every point of the plane, with the points of the line in both sets"]', 'every point of the plane, with the points of the line in both sets', NULL, 'Every point has a $y$-value that is greater than, less than or equal to $x - 2$. So together the two sets cover the whole plane. Points on the line satisfy both inequalities, so they belong to both sets.', 'checked', '{"lint":[],"solve":{"answer":"every point of the plane, with the points of the line in both sets","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any point has y >= x-2 or y <= x-2 (trichotomy), so the union is the whole plane; points with y = x-2 satisfy both.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e3ae02-f44e-415f-a4f3-52ba458c0073', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'A system has the equations $y = 2x$ and $x + y = 12$. What is $x$?', '[]', '4', '12/3', 'Substitute $y = 2x$ into $x + y = 12$: $x + 2x = 12$, so $3x = 12$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x = 12 -> 3x = 12 -> x = 4 (y = 8).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b09707b-f842-40be-b4ee-1331c7d263cd', 'NC26.M1.ANFR.7', 1, 'choice', 'Identify the solution of a system', 'Which ordered pair is the solution of both $x + y = 7$ and $x - y = 3$?', '["$(5, 2)$","$(2, 5)$","$(4, 3)$","$(3, 4)$"]', '$(5, 2)$', NULL, 'Check each pair in both equations. For $(5, 2)$: $5 + 2 = 7$ and $5 - 2 = 3$, so it works. $(2, 5)$, $(4, 3)$ and $(3, 4)$ all add to 7 but give $x - y$ equal to $-3$, 1 and $-1$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 2x = 10, x = 5; y = 2. Check 5 - 2 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4128922-9531-4dcb-af24-788755539757', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'A bakery sold 100 items in one day. Muffins ($x$ of them) cost 3 dollars each and bagels ($y$ of them) cost 2 dollars each, and the bakery took in 260 dollars. Which system models this?', '["$x + y = 100$ and $2x + 3y = 260$","$x + y = 260$ and $3x + 2y = 100$","$x + y = 100$ and $3x + 2y = 260$","$xy = 100$ and $3x + 2y = 260$"]', '$x + y = 100$ and $3x + 2y = 260$', NULL, 'The number of items is $x + y = 100$. The money taken in is 3 dollars per muffin plus 2 dollars per bagel: $3x + 2y = 260$.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 100$ and $3x + 2y = 260$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count: x + y = 100. Money: 3x + 2y = 260 (solution x = 60, y = 40).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c4ee790-78c3-40cf-85b4-bed563c8629a', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'A farm has chickens ($c$) and goats ($g$). There are 20 animals and 56 legs in all. Chickens have 2 legs and goats have 4 legs. Which system models this?', '["$c + g = 20$ and $2c + 4g = 56$","$c + g = 20$ and $4c + 2g = 56$","$c + g = 56$ and $2c + 4g = 20$","$c + g = 20$ and $2c - 4g = 56$"]', '$c + g = 20$ and $2c + 4g = 56$', NULL, 'The number of animals gives $c + g = 20$. Each chicken has 2 legs and each goat has 4, so the legs give $2c + 4g = 56$.', 'checked', '{"lint":[],"solve":{"answer":"$c + g = 20$ and $2c + 4g = 56$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count: c+g=20. Legs: 2c+4g=56. (Solution c=12, g=8.)","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef588030-7506-4cb8-818e-67c1158a2804', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'Two numbers have a sum of 15 and a difference of 3. Let $x$ be the larger number and $y$ the smaller number. Which system models this?', '["$x + y = 15$ and $y - x = 3$","$x + y = 15$ and $x - y = 3$","$x + y = 3$ and $x - y = 15$","$xy = 15$ and $x - y = 3$"]', '$x + y = 15$ and $x - y = 3$', NULL, 'A sum is found by adding: $x + y = 15$. Since $x$ is the larger number, the difference is $x - y = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 15$ and $x - y = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum x+y=15; larger minus smaller x-y=3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
