INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7212518-d768-4dea-bcb9-9d4e1b64b654', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'Club A charges 5 dollars to join plus 2 dollars per game. Club B charges 1 dollar to join plus 3 dollars per game. Let $x$ be the number of games and $y$ the total cost in dollars. Which system gives the cost at each club?', '["$y = 5x + 2$ and $y = x + 3$","$y = 5x + 2$ and $y = 3x + 1$","$y = 2x + 5$ and $y = 3x + 1$","$y = 2x + 5$ and $y = x + 3$"]', '$y = 2x + 5$ and $y = 3x + 1$', NULL, 'The cost per game is the slope and the joining fee is the starting amount. Club A: $y = 2x + 5$. Club B: $y = 3x + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 5$ and $y = 3x + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5 + 2x; B: 1 + 3x.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11646d9b-fc79-4fa6-a8c7-1cb7ab186e0a', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'A jar holds nickels ($n$) and dimes ($d$). It holds 10 coins worth 70 cents in all. A nickel is worth 5 cents and a dime is worth 10 cents. Which system models this?', '["$n + d = 10$ and $10n + 5d = 70$","$n + d = 70$ and $5n + 10d = 10$","$n + d = 10$ and $5n + 10d = 7$","$n + d = 10$ and $5n + 10d = 70$"]', '$n + d = 10$ and $5n + 10d = 70$', NULL, 'The number of coins gives $n + d = 10$. The value in cents gives $5n + 10d = 70$.', 'checked', '{"lint":[],"solve":{"answer":"$n + d = 10$ and $5n + 10d = 70$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coins n+d=10; value 5n+10d=70.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3cef615-12fe-4e74-b775-f0e66bab15f5', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'In a system, $x = 5$ and $3x + y = 21$. What is $y$?', '[]', '6', '21-3*5', 'Put $x = 5$ into $3x + y = 21$: $15 + y = 21$, so $y = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(5)+y=21, y=6.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f797e2a7-99c4-4b26-82ca-cc8fa9565360', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'A system has the equations $y = x + 4$ and $x + y = 14$. What is $x$?', '[]', '5', '(14-4)/2', 'Replace $y$ by $x + 4$: $x + x + 4 = 14$, so $2x = 10$ and $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (x+4) = 14, 2x = 10, x = 5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a91c71cc-74d7-4033-9a5f-93f599554d9f', 'NC26.M1.ANFR.7', 1, 'choice', 'Solve a system by substitution', 'You substitute $y = 2x + 1$ into the equation $x + y = 10$. Which equation do you get?', '["$x + (2x + 1) = 10$","$x + 2x = 10 + 1$","$x(2x + 1) = 10$","$x + y + 2x + 1 = 10$"]', '$x + (2x + 1) = 10$', NULL, 'Substituting means writing $2x + 1$ in place of $y$. That gives $x + (2x + 1) = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$x + (2x + 1) = 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Replace y by (2x+1): x + (2x+1) = 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8804d10-cc27-4f77-9618-7a0d1245dfe4', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'Lena solves a system and finds $x = 3$. One equation of the system is $y = 5x - 4$. What is $y$?', '[]', '11', '5*3-4', 'Put $x = 3$ into $y = 5x - 4$: $y = 15 - 4 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 5(3) - 4 = 11.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
