INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c60873e8-5647-493a-be54-b47fc842497d', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'A system has the equations $y = x - 2$ and $x + y = 10$. What is $y$?', '[]', '4', '(10-2)/2', 'Replace $y$ by $x - 2$ in the second equation: $x + x - 2 = 10$, so $x = 6$. Then $y = 6 - 2 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x - 2 = 10, x = 6, y = 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
