INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70d9122b-809f-4078-aae4-08b954b70d14', 'NC26.M1.ANFR.7', 1, 'choice', 'Solve a system by graphing', 'A point is on the graphs of both $y = x + 3$ and $y = 2x + 1$ only if it fits both equations. Which point is on both graphs?', '["$(1, 4)$","$(0, 1)$","$(5, 2)$","$(2, 5)$"]', '$(2, 5)$', NULL, 'Test each point. $(2, 5)$: $2 + 3 = 5$ and $2(2) + 1 = 5$, so it fits both. $(1, 4)$ fits only the first and $(0, 1)$ fits only the second.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+3 = 2x+1, x=2, y=5. (1,4) fails the second; (0,1) the first; (5,2) both.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c9b4dd6-badf-4984-a3ff-7b314d9b4ed8', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by graphing', 'The graphs of $y = x$ and $y = 6 - x$ cross at one point. What is the $x$-coordinate of that point?', '[]', '3', '6/2', 'At the crossing point the two $y$-values are equal: $x = 6 - x$, so $2x = 6$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 6 - x, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
