INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('786f72bd-b4c3-4818-b19a-6225112d3afb', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by graphing', 'Line 1 has the equation $y = 2x$ and line 2 has the equation $y = 9 - x$. Written as a table, line 1 gives $y = 2, 4, 6, 8$ and line 2 gives $y = 8, 7, 6, 5$ for $x = 1, 2, 3, 4$. At which value of $x$ do the lines have the same $y$-value?', '[]', '3', '9/3', 'Compare the rows: at $x = 3$ both lines give $y = 6$. This agrees with $2x = 9 - x$, so $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Table: at x=3 both give 6 (2*3=6, 9-3=6).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
