INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aad49c65-32cf-41f4-8edc-6624f1ca5745', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by graphing', 'A horizontal line $y = 7$ crosses the line $y = 4x - 5$. What is the $x$-coordinate of the crossing point?', '[]', '3', '(7+5)/4', 'At the crossing point $y = 7$, so $4x - 5 = 7$. Then $4x = 12$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 = 7, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
