INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddc4da60-8d74-4bc5-9d91-fb6e4863bf5b', 'NC26.M1.ANFR.7', 1, 'choice', 'Count the solutions of a system', 'How many solutions does the system $x + y = 6$ and $2x + 2y = 12$ have?', '["Infinitely many","No solution at all","Exactly one solution","Exactly two solutions"]', 'Infinitely many', NULL, 'Doubling every part of $x + y = 6$ gives $2x + 2y = 12$, so both equations describe the same line. Every point of it is a solution.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second equation is 2 times the first: same line.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
