INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccbfdebd-8271-4558-a61a-fb47d688ec02', 'NC26.M1.ANFR.7', 1, 'choice', 'Interpret the solution of a system in context', 'Ana and Ben are saving money. The solution of the system for their savings is $(4, 12)$, where $x$ is the number of weeks and $y$ is the savings in dollars. Which sentence matches this solution?', '["After 12 weeks, Ana and Ben have each saved 4 dollars","After 4 weeks, Ana has saved 12 dollars and Ben has saved 4","Ana saves 4 dollars a week and Ben saves 12 dollars a week","After 4 weeks, Ana and Ben have each saved 12 dollars"]', 'After 4 weeks, Ana and Ben have each saved 12 dollars', NULL, 'The $x$-value is weeks and the $y$-value is dollars saved. At the solution both people have the same amount: 12 dollars after 4 weeks.', 'checked', '{"lint":[],"solve":{"answer":"After 4 weeks, Ana and Ben have each saved 12 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x=4 both equal y=12.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
