INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb3b84d1-a485-4735-a267-e248e9521860', 'NC26.M1.ANFR.7', 1, 'choice', 'Systems of inequalities in context', 'Which ordered pair makes both $x + y < 8$ and $x > 2$ true?', '["$(4, 3)$","$(2, 3)$","$(5, 4)$","$(1, 1)$"]', '$(4, 3)$', NULL, 'Check both rules. $(4, 3)$: $4 + 3 = 7 < 8$ and $4 > 2$, so it works. $(2, 3)$ fails $x > 2$, $(5, 4)$ has sum 9 and $(1, 1)$ fails $x > 2$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3): x>2 false. (1,1) false. (4,3): 7<8, 4>2 true. (5,4): 9 not < 8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88b35da3-9658-4831-8026-4e6419ff2bb1', 'NC26.M1.ANFR.7', 1, 'choice', 'Systems of inequalities in context', 'Maya buys apples, $a$, and pears, $p$. She buys at most 10 pieces of fruit, so $a + p \le 10$, and at least 4 apples, so $a \ge 4$. Which pair $(a, p)$ satisfies both?', '["$(6, 6)$","$(5, 4)$","$(3, 5)$","$(4, 7)$"]', '$(5, 4)$', NULL, 'Check each pair in both. $(3, 5)$ has only 3 apples. $(6, 6)$ has $6 + 6 = 12$ pieces, more than 10. $(4, 7)$ has $4 + 7 = 11$ pieces, more than 10. $(5, 4)$ has $5 + 4 = 9 \le 10$ and $5 \ge 4$, so it works.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5,4): 9<=10, 5>=4 yes. (6,6): 12>10 no. (4,7): 11>10 no. (3,5): 3<4 no. Only (5,4).","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9f92336-8d87-4d6e-a768-3a37a1a82c4c', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $y = 2x + 3$ and $y = 2x - 5$ have?', '["Exactly one solution","Infinitely many solutions","Exactly two solutions","No solution"]', 'No solution', NULL, 'Both lines have slope 2 but different y-intercepts (3 and $-5$), so they are parallel and never meet. Setting the right sides equal gives $2x + 3 = 2x - 5$, which is never true.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same slope 2, different intercepts 3 and -5: parallel lines, never meet. No solution.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28800c1a-e9f6-49c0-bce7-4e300597eceb', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'A rental shop has bikes (2 wheels each) and trikes (3 wheels each). There are 14 vehicles with 38 wheels in all. How many trikes are there?', '[]', '10', '38-2*14', 'Let $b$ be bikes and $t$ be trikes. Then $b + t = 14$ and $2b + 3t = 38$. Replacing $b$ with $14 - t$: $2(14 - t) + 3t = 38$, so $28 + t = 38$ and $t = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b + t = 14, 2b + 3t = 38. 2(14) + t = 38 -> t = 10, b = 4. Check 8 + 30 = 38.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b34525e-e29d-4a0c-b020-22dea06879db', 'NC26.M1.ANFR.7', 2, 'numeric', 'Find the intersection of two lines', 'The lines $y = x + 2$ and $y = -x + 8$ cross at one point. What is the y-coordinate of that point?', '[]', '5', '(8-2)/2+2', 'At the crossing point the y-values are equal: $x + 2 = -x + 8$, so $2x = 6$ and $x = 3$. Then $y = 3 + 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2 = -x + 8 -> 2x = 6 -> x = 3, y = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2fd096e-dc36-43c2-b6d5-bc19a53dba14', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'Chen mows lawns ($m$) and walks dogs ($w$). Chen earns 15 dollars for each lawn and 8 dollars for each dog walk. Last week Chen did 11 jobs and earned 102 dollars. Which system models this?', '["$m + w = 11$ and $15m + 8w = 102$","$m + w = 11$ and $8m + 15w = 102$","$m + w = 102$ and $15m + 8w = 11$","$m + w = 11$ and $15m - 8w = 102$"]', '$m + w = 11$ and $15m + 8w = 102$', NULL, 'The number of jobs gives $m + w = 11$. The money earned gives $15m + 8w = 102$, with 15 dollars on each lawn and 8 dollars on each walk.', 'checked', '{"lint":[],"solve":{"answer":"$m + w = 11$ and $15m + 8w = 102$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jobs m+w=11; earnings 15m+8w=102 (m=2, w=9).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1040506c-f72c-464d-b51b-98ed582babac', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'The length $L$ of a rectangle is 4 centimeters more than twice its width $w$. The perimeter is 38 centimeters. Which system models this?', '["$L = 2w + 4$ and $L + w = 38$","$L = 2w + 4$ and $2L + 2w = 38$","$L = 2(w + 4)$ and $2L + 2w = 38$","$L = 2w - 4$ and $2L + 2w = 38$"]', '$L = 2w + 4$ and $2L + 2w = 38$', NULL, '"4 more than twice the width" is $L = 2w + 4$. The perimeter is two lengths plus two widths: $2L + 2w = 38$.', 'checked', '{"lint":[],"solve":{"answer":"$L = 2w + 4$ and $2L + 2w = 38$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 2w + 4; perimeter 2L + 2w = 38.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7758d50-576b-48ac-9d2b-3f8d28eefbba', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'One candle is 20 cm tall and burns down 2 cm every hour. A second candle is 16 cm tall and burns down 1 cm every hour. Let $x$ be the hours burned and $y$ the height in cm. Which system gives the two heights?', '["$y = 20 + 2x$ and $y = 16 + x$","$y = 2x - 20$ and $y = x - 16$","$y = 20 - 2x$ and $y = 16 - x$","$y = 20x - 2$ and $y = 16x - 1$"]', '$y = 20 - 2x$ and $y = 16 - x$', NULL, 'Each candle starts at its full height and loses height every hour, so the burning rate is subtracted: $y = 20 - 2x$ and $y = 16 - x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 20 - 2x$ and $y = 16 - x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights decrease from 20 by 2 per hour and from 16 by 1 per hour.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fff813c9-677b-45bb-be08-6cfb136d7aa5', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'Which situation is modeled by the system $x + y = 25$ and $3x + 2y = 60$?', '["A total of 25 tickets were bought: x at 2 dollars each and y at 3 dollars each, costing 60 dollars in all.","A total of 60 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 25 dollars in all.","A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, and the y tickets cost 60 dollars.","A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all."]', 'A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all.', NULL, 'In $x + y = 25$ the tickets are counted, so there are 25 tickets. In $3x + 2y = 60$ the $x$ tickets cost 3 dollars each and the $y$ tickets cost 2 dollars each, and the total cost is 60 dollars.', 'checked', '{"lint":[],"solve":{"answer":"A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=25 counts tickets; 3x+2y=60 is the total cost with x at $3, y at $2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d7b165a-e002-472b-91ea-4b4c63db7137', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by substitution', 'A system has the equations $2x + y = 11$ and $y = x - 1$. What is $x$?', '[]', '4', '(11+1)/3', 'Replace $y$ by $x - 1$: $2x + x - 1 = 11$, so $3x = 12$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + x - 1 = 11, 3x = 12, x = 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7a2495e-3b2b-4e22-b2ce-24a6f91b8ed1', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by substitution', 'Which ordered pair $(x, y)$ is the solution of $x = 2y - 3$ and $3x + y = 5$?', '["$(2, 1)$","$(1, 2)$","$(3, 3)$","$(0, 5)$"]', '$(1, 2)$', NULL, 'Substitute $x = 2y - 3$: $3(2y - 3) + y = 5$, so $7y - 9 = 5$ and $y = 2$. Then $x = 2(2) - 3 = 1$. Check: $3(1) + 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2y-3)+y=5, 7y=14, y=2, x=1. (1,2). Check others fail.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e5f5d7e-e248-4db0-80df-7f7a9eb4d6f4', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by substitution', 'A system has the equations $4x + 3y = 25$ and $x = y + 1$. What is $y$?', '[]', '3', '(25-4)/7', 'Replace $x$ by $y + 1$: $4(y + 1) + 3y = 25$, so $7y + 4 = 25$ and $y = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(y+1)+3y=25, 7y=21, y=3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c744e0cd-b802-4175-b36e-46946ce6116a', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by substitution', 'Which ordered pair is the solution of both $y = 3x - 1$ and $2x + y = 14$?', '["$(8, 3)$","$(2, 5)$","$(3, 8)$","$(1, 12)$"]', '$(3, 8)$', NULL, 'Substitute $y = 3x - 1$: $2x + 3x - 1 = 14$, so $5x = 15$ and $x = 3$. Then $y = 3(3) - 1 = 8$. Check: $2(3) + 8 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3x - 1 = 14, x=3, y=8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43687492-afa4-4005-953e-43a7977ea5a1', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by substitution', 'The equations $5x + 2y = 26$ and $y = 2x - 5$ make a system. What is $y$?', '[]', '3', '2*(26+10)/9-5', 'Replace $y$ by $2x - 5$: $5x + 2(2x - 5) = 26$, so $9x - 10 = 26$ and $x = 4$. Then $y = 2(4) - 5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 2(2x-5) = 26, 9x = 36, x=4, y=3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d931b7c0-6557-4471-a1fc-76e48b88be08', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by graphing', 'The lines $y = 3x - 2$ and $y = x + 4$ are graphed. What is the $x$-coordinate of the point where they cross?', '[]', '3', '(4+2)/(3-1)', 'Set the two expressions equal: $3x - 2 = x + 4$. Then $2x = 6$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2 = x + 4, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37d65915-50a8-4b87-bc0f-5f0fafeef6aa', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by graphing', 'One line has slope 3 and passes through $(0, -1)$. Another line has slope $-1$ and passes through $(0, 11)$. Which point is where the two lines cross?', '["$(8, 3)$","$(3, 8)$","$(2, 9)$","$(4, 11)$"]', '$(3, 8)$', NULL, 'The lines are $y = 3x - 1$ and $y = -x + 11$. Setting them equal gives $4x = 12$, so $x = 3$ and $y = 3(3) - 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3x-1 and y=-x+11: 4x=12, x=3, y=8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('908251ba-9ed9-461a-b8f8-6c9bc1349ef4', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by graphing', 'The lines $y = 2x + 3$ and $y = -x + 12$ are graphed together. What is the $y$-coordinate of their crossing point?', '[]', '9', '2*(12-3)/3+3', 'Set $2x + 3 = -x + 12$. Then $3x = 9$ and $x = 3$. So $y = 2(3) + 3 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+3 = -x+12, x=3, y=9.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('783e71c8-d7bd-4a50-8eab-e2c49a301133', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by graphing', 'Without drawing them, which pair of lines would cross each other on the $y$-axis?', '["$y = 2x + 4$ and $y = 2x - 3$","$y = 2x + 4$ and $y = -3x - 4$","$y = 2x + 4$ and $y = -3x + 4$","$y = 2x + 4$ and $y = 4x + 2$"]', '$y = 2x + 4$ and $y = -3x + 4$', NULL, 'Lines cross on the $y$-axis when they have the same $y$-intercept and different slopes. Both lines in the correct pair have $y$-intercept 4 and their slopes differ. The pair with equal slopes is parallel and never crosses.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 4$ and $y = -3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y-intercept 4 and different slopes: cross at (0,4).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae569eeb-2b21-4261-be6f-e68e1e66e430', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'Which system has no solution?', '["$y = 4x - 1$ and $8x - 2y = 2$","$y = 4x - 1$ and $8x - 2y = 6$","$y = 4x - 1$ and $8x + 2y = 6$","$y = 4x - 1$ and $2x - 2y = 6$"]', '$y = 4x - 1$ and $8x - 2y = 6$', NULL, 'Write each second equation as $y = mx + b$. In the correct system $8x - 2y = 6$ becomes $y = 4x - 3$: the same slope as $y = 4x - 1$ but a different intercept, so the lines are parallel. The other systems have a different slope (one solution) or are the same line.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 1$ and $8x - 2y = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Substituting y=4x-1: 8x-2y = 2 always. So 8x-2y=2 is the same line; 8x-2y=6 is parallel, no solution. Others have different slopes.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f59f4e6-46e8-4eb5-bd69-241950f2cefe', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $y = -2x + 6$ and $4x + 2y = 12$ have?', '["No solution at all","Exactly one solution","Infinitely many","Exactly two solutions"]', 'Infinitely many', NULL, 'Solve $4x + 2y = 12$ for $y$: $2y = -4x + 12$, so $y = -2x + 6$. The two equations are the same line, so there are infinitely many solutions.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+2y=12 gives y=-2x+6, identical.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d8274a5-0f6d-4770-b9ea-4962f16eadd6', 'NC26.M1.ANFR.7', 2, 'numeric', 'Count the solutions of a system', 'The system $y = 5x + 1$ and $y = mx + 4$ has no solution. What is $m$?', '[]', '5', '5', 'No solution means the lines are parallel with different intercepts. Parallel lines have equal slopes, so $m = 5$. The intercepts 1 and 4 differ, as needed.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel with different intercepts needs m = 5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
