INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83a347ea-fffb-49ac-a1a6-d3aad8eccf75', 'NC26.M1.ANFR.7', 2, 'choice', 'Interpret the solution of a system in context', 'Plant A grows according to $y = 4x + 1$ and plant B according to $y = 2x + 5$, where $x$ is weeks and $y$ is height in cm. The plants are the same height at $(2, 9)$. Which statement is true?', '["Plant B is taller than plant A after week 2","Plant A is taller than plant B before week 2","Plant A is taller than plant B after week 2","Plant A and plant B are 2 cm tall at week 9"]', 'Plant A is taller than plant B after week 2', NULL, 'Plant A grows 4 cm a week and plant B grows 2 cm a week. They meet at week 2, and after that the faster-growing plant A is taller. Before week 2 plant B was taller.', 'checked', '{"lint":[],"solve":{"answer":"Plant A is taller than plant B after week 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A grows faster (4 vs 2); after x=2 A is taller (e.g. x=3: 13 vs 11).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f933151-10af-49ee-a097-03271cf0c421', 'NC26.M1.ANFR.7', 2, 'numeric', 'Interpret the solution of a system in context', 'Taxi X charges $y = 4 + 2m$ dollars for $m$ miles and taxi Y charges $y = 1 + 3m$ dollars for $m$ miles. They cost the same for a 3-mile ride. For a 5-mile ride, how many dollars cheaper is the cheaper taxi?', '[]', '2', '(1+3*5)-(4+2*5)', 'For 5 miles taxi X costs $4 + 2(5) = 14$ dollars and taxi Y costs $1 + 3(5) = 16$ dollars. Taxi X is cheaper by $16 - 14 = 2$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 miles: X 4+10=14, Y 1+15=16. Difference 2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('293375ee-1122-47bd-898f-9613f18eccb1', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'Plant A is 4 cm tall and grows 3 cm each week. Plant B is 16 cm tall and grows 1 cm each week. After how many weeks are the two plants the same height?', '[]', '6', '(16-4)/(3-1)', 'The heights are $4 + 3w$ and $16 + w$. Setting them equal: $2w = 12$, so $w = 6$ weeks (both are 22 cm).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+3w = 16+w, w = 6.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90928c56-3ca9-4afd-aa80-cfd0d9472183', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'Two apples and one orange cost 7 dollars. One apple and one orange cost 5 dollars. How many dollars does one orange cost?', '[]', '3', '2*5-7', 'Let $a$ be an apple and $o$ an orange: $2a + o = 7$ and $a + o = 5$. Subtracting gives $a = 2$. Then $o = 5 - 2 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract: apple 2; orange 5-2 = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093d6dd5-938b-4bf0-a201-2ff1705a938d', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'Club 1 charges 10 dollars to join and 4 dollars per movie. Club 2 charges 22 dollars to join and 1 dollar per movie. After how many movies do the two clubs cost the same in total?', '[]', '4', '(22-10)/(4-1)', 'The costs are $10 + 4m$ and $22 + m$. Setting them equal: $3m = 12$, so $m = 4$ movies (both cost 26 dollars).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10+4m = 22+m, m = 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8962b28-3b9b-431c-bc3c-9656c474b149', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system from a situation', 'Sam is 4 years older than twice Kim''s age. The sum of their ages is 31. How old is Sam?', '["9","27","31","22"]', '22', '2*(31-4)/3+4', 'With $s = 2k + 4$ and $s + k = 31$: $3k + 4 = 31$, so $k = 9$ and $s = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S=2K+4, 3K+4=31, K=9, S=22.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ff55313-2033-427e-8e70-81ca34b7392a', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'A theater sold 30 tickets for 207 dollars. Adult tickets cost 8 dollars and child tickets cost 5 dollars. How many adult tickets were sold?', '[]', '19', '(207-5*30)/3', 'Let $a$ be adults and $c$ children: $a + c = 30$ and $8a + 5c = 207$. Replace $c$ by $30 - a$: $8a + 150 - 5a = 207$, so $3a = 57$ and $a = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+c=30, 8a+5c=207: 3a+150=207, a=19.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34d6f8ce-9742-478e-8ce5-2b951f24f011', 'NC26.M1.ANFR.7', 2, 'choice', 'Systems of inequalities in context', 'Jai buys pens (2 dollars each) and notebooks (3 dollars each). He wants at least 4 items and can spend at most 14 dollars. With $p$ pens and $n$ notebooks, this is $p + n \ge 4$ and $2p + 3n \le 14$. Which purchase works?', '["2 pens and 1 notebook","3 pens and 2 notebooks","1 pen and 5 notebooks","4 pens and 3 notebooks"]', '3 pens and 2 notebooks', NULL, '3 pens and 2 notebooks: 5 items (at least 4) and $2(3) + 3(2) = 12$ dollars (at most 14). Two pens and a notebook is only 3 items. The other two cost 17 dollars each.', 'checked', '{"lint":[],"solve":{"answer":"3 pens and 2 notebooks","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,3): 17>14. (2,1): 3<4. (3,2): 5 items, 12 dollars, works. (1,5): 17>14.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52fa6b50-a916-4f89-b780-ee04ca9038e8', 'NC26.M1.ANFR.7', 2, 'choice', 'Systems of inequalities in context', 'Which ordered pair is a solution of both $y > 2x$ and $y \le x + 5$?', '["$(2, 4)$","$(1, 7)$","$(1, 4)$","$(3, 5)$"]', '$(1, 4)$', NULL, '$(1, 4)$: $4 > 2$ and $4 \le 6$, so it works. $(2, 4)$ fails $y > 2x$ since $4 > 4$ is false. $(1, 7)$ fails $y \le x + 5$. $(3, 5)$ fails $y > 2x$ since $5 > 6$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,4): 4>4 false. (3,5): 5>6 false. (1,4): 4>2, 4<=6 true. (1,7): 7<=6 false.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4408578f-919d-4b05-a69a-77ac8f50e4ff', 'NC26.M1.ANFR.7', 2, 'numeric', 'Systems of inequalities in context', 'A room holds at most 60 people, so adults $a$ and children $c$ satisfy $a + c \le 60$. The event also needs at least 20 adults, $a \ge 20$. If 25 adults come, what is the greatest number of children who can come?', '[]', '35', '60-25', 'With $a = 25$ (which meets $a \ge 20$), $25 + c \le 60$ gives $c \le 35$. The greatest number is 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + c <= 60, c <= 35.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57cb8850-fea4-410c-9257-9bd9fed88666', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'A gym offers Plan A, which costs $y = 30 + 4x$ dollars for $x$ visits, and Plan B, which costs $y = 10 + 6x$ dollars for $x$ visits. The solution of the system is $(10, 70)$. What does it mean?', '["Plan A costs 10 dollars and Plan B costs 70 dollars","After 10 visits both plans cost the same total, 70 dollars","After 70 visits both plans cost the same total, 10 dollars","Plan B is cheaper no matter how many visits"]', 'After 10 visits both plans cost the same total, 70 dollars', NULL, 'The solution is the $(x, y)$ that makes both equations true: at $x = 10$ visits, Plan A costs $30 + 40 = 70$ and Plan B costs $10 + 60 = 70$. So after 10 visits the two plans cost the same, 70 dollars.', 'checked', '{"lint":[],"solve":{"answer":"After 10 visits both plans cost the same total, 70 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 10 visits, y = 70 dollars: 30 + 40 = 70 and 10 + 60 = 70. Both plans cost 70 after 10 visits.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee8bc7ec-c0c0-4f71-bcfe-dc62a5cd2952', 'NC26.M1.ANFR.7', 3, 'numeric', 'Find the value that gives infinitely many solutions', 'The system $y = 3x + 4$ and $2y = 6x + k$ has infinitely many solutions. What is $k$?', '[]', '8', '2*4', 'The system has infinitely many solutions when both equations describe the same line. Multiplying $y = 3x + 4$ by 2 gives $2y = 6x + 8$, so $k = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double the first: 2y = 6x + 8. Same line iff k = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2114a52-d059-439c-aa46-b20af868af41', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution with a coefficient', 'A system has the equations $3x + 2y = 16$ and $y = x + 3$. What is $y$?', '[]', '5', '(16-6)/5+3', 'Substitute $y = x + 3$: $3x + 2(x + 3) = 16$, so $5x + 6 = 16$ and $x = 2$. Then $y = 2 + 3 = 5$. Check: $3(2) + 2(5) = 16$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2(x + 3) = 16 -> 5x + 6 = 16 -> x = 2, y = 5. Check 6 + 10 = 16.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7663d683-5501-40ac-9c98-5405570ae0fa', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'Sam has 3 times as many stickers as Lia. If Sam gives Lia 10 stickers, they will have the same number. Let $s$ be Sam''s stickers and $l$ be Lia''s stickers now. Which system models this?', '["$s = 3l$ and $s - 10 = l + 10$","$s = 3l$ and $s + 10 = l - 10$","$s = l + 3$ and $s - 10 = l + 10$","$l = 3s$ and $s - 10 = l + 10$"]', '$s = 3l$ and $s - 10 = l + 10$', NULL, 'Sam has 3 times as many: $s = 3l$. After Sam gives away 10 he has $s - 10$ and Lia has $l + 10$, and these are equal.', 'checked', '{"lint":[],"solve":{"answer":"$s = 3l$ and $s - 10 = l + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s=3l; after giving: s-10 = l+10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('378d03af-adf5-401c-b8f2-9737f1a90840', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A school sold adult tickets ($a$) at 7 dollars and student tickets ($s$) at 4 dollars. It sold 3 times as many student tickets as adult tickets and took in 228 dollars. Which system models this?', '["$a = 3s$ and $7a + 4s = 228$","$s = 3a$ and $7a + 4s = 228$","$s = 3a$ and $4a + 7s = 228$","$s = a + 3$ and $7a + 4s = 228$"]', '$s = 3a$ and $7a + 4s = 228$', NULL, '"3 times as many student tickets" gives $s = 3a$. The money is 7 dollars for each adult ticket and 4 dollars for each student ticket: $7a + 4s = 228$.', 'checked', '{"lint":[],"solve":{"answer":"$s = 3a$ and $7a + 4s = 228$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = 3a; revenue 7a + 4s = 228 (a=12, s=36).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('decfcaf4-98bd-412c-a1ce-a65a91fe14d3', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A boat travels 24 km upstream in 3 hours and 24 km downstream in 2 hours. Let $b$ be the boat''s speed in still water and $c$ the speed of the current, both in km per hour. Going upstream the current slows the boat; going downstream it speeds the boat up. Which system models this?', '["$3(b + c) = 24$ and $2(b - c) = 24$","$3b - c = 24$ and $2b + c = 24$","$3(b - c) = 24$ and $2(b + c) = 24$","$b - c = 3$ and $b + c = 2$"]', '$3(b - c) = 24$ and $2(b + c) = 24$', NULL, 'Distance is speed times time. Upstream the speed is $b - c$ for 3 hours: $3(b - c) = 24$. Downstream the speed is $b + c$ for 2 hours: $2(b + c) = 24$.', 'checked', '{"lint":[],"solve":{"answer":"$3(b - c) = 24$ and $2(b + c) = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"distance = rate x time: 3(b-c)=24, 2(b+c)=24.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db0dfd2a-e6ff-4236-a6b5-730a4927e441', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A 10-liter juice mix is made from juice that is 20% fruit ($x$ liters) and juice that is 50% fruit ($y$ liters). The mix is 35% fruit, so it holds 3.5 liters of fruit. Which system models this?', '["$x + y = 10$ and $0.2x + 0.5y = 35$","$x + y = 10$ and $20x + 50y = 3.5$","$x + y = 3.5$ and $0.2x + 0.5y = 10$","$x + y = 10$ and $0.2x + 0.5y = 3.5$"]', '$x + y = 10$ and $0.2x + 0.5y = 3.5$', NULL, 'The amounts of juice add to 10 liters: $x + y = 10$. The fruit in each juice is 20% of $x$ plus 50% of $y$, which is $0.2x + 0.5y$, and the mix holds 3.5 liters of fruit.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 10$ and $0.2x + 0.5y = 3.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume x+y=10; fruit 0.2x+0.5y=3.5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98692731-eaa8-4a9b-9bfa-5e2e50592dbe', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution', 'Solve the system $3x - 2y = 7$ and $y = 2x - 5$. What is $x$?', '[]', '3', '(7-10)/(3-4)', 'Replace $y$ by $2x - 5$: $3x - 2(2x - 5) = 7$, so $3x - 4x + 10 = 7$. Then $-x = -3$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2(2x-5) = 7, -x + 10 = 7, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
