INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99015dca-e93e-47ec-9688-c77ddb5500a0', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by graphing', 'Line P passes through $(0, 1)$ and $(1, 4)$. Line Q passes through $(0, 11)$ and $(3, 5)$. What is the $x$-coordinate of the point where they cross?', '[]', '2', '(11-1)/(3+2)', 'Line P has slope 3 and $y$-intercept 1: $y = 3x + 1$. Line Q has slope $\frac{5 - 11}{3 - 0} = -2$ and $y$-intercept 11: $y = -2x + 11$. Setting them equal: $5x = 10$, so $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: y=3x+1. Q: slope -6/3=-2, y=-2x+11. 5x=10, x=2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70e11d3f-e32c-4c70-8fef-fc5a7f18a8d5', 'NC26.M1.ANFR.7', 3, 'choice', 'Solve a system by graphing', 'The lines $3x + 2y = 18$ and $y = x - 1$ are graphed. Which point is where they cross?', '["$(3, 4)$","$(6, 0)$","$(2, 1)$","$(4, 3)$"]', '$(4, 3)$', NULL, 'Replace $y$ by $x - 1$: $3x + 2(x - 1) = 18$, so $5x = 20$ and $x = 4$. Then $y = 3$. The point $(6, 0)$ is only on the first line and $(2, 1)$ is only on the second.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2(x-1) = 18, 5x = 20, x=4, y=3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4351c73f-032d-4ca6-9520-c6b62d9f7063', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by graphing', 'The lines $x + 2y = 8$ and $3x - 2y = 4$ are graphed. What is the $x$-coordinate of their crossing point?', '[]', '3', '(8+4)/4', 'Add the equations to remove $y$: $4x = 12$, so $x = 3$. (Then $y = 2.5$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 4x = 12, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
