INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60c22305-83cc-44a2-91df-c342348f7a44', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by graphing', 'The lines $y = 2x + 1$ and $y = -x + k$ cross at the point where $x = 3$. What is $k$?', '[]', '10', '2*3+1+3', 'At $x = 3$ the first line gives $y = 2(3) + 1 = 7$. The second line must give the same: $7 = -3 + k$, so $k = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x=3, y=7; 7 = -3 + k, k = 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
