INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8e8372e-96e2-4acb-95f5-ba7c4b2f8af8', 'NC26.M1.ANFR.7', 3, 'numeric', 'Count the solutions of a system', 'The system $3x + 2y = 10$ and $6x + 4y = c$ has infinitely many solutions. What is $c$?', '[]', '20', '2*10', 'The second equation must be the first with every part doubled: $6x + 4y = 2 \times 10 = 20$. So $c = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second must be 2 times the first: c = 20.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
