INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('864d743f-1ebb-4e3e-8fc3-8ac50855f7c0', 'NC26.M1.SGMR.1', 1, 'choice', 'Image after a sequence of transformations', 'The point $(1, 2)$ is translated 3 units to the right and then reflected across the y-axis. Where does it end up?', '["$(-4, 2)$","$(2, 2)$","$(4, 2)$","$(-4, -2)$"]', '$(-4, 2)$', NULL, 'Translating gives $(4, 2)$. Reflecting across the y-axis changes the sign of the x-coordinate, giving $(-4, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-4, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2) -> (4,2) -> (-4,2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
