INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d9a2c4b-cbee-4fda-a5ed-0e3349512e0e', 'NC26.M1.SGMR.1', 2, 'choice', 'Properties kept by rigid transformations', 'Line $\ell$ and line $m$ are parallel. The same rigid transformation is applied to both lines, giving lines $\ell''$ and $m''$. Which statement is true?', '["Lines $\\ell''$ and $m''$ are perpendicular.","Lines $\\ell''$ and $m''$ are parallel.","Lines $\\ell''$ and $m''$ cross at one point.","Lines $\\ell''$ and $m''$ may or may not be parallel."]', 'Lines $\ell''$ and $m''$ are parallel.', NULL, 'A rigid transformation keeps distances, so two parallel lines stay the same distance apart everywhere. The image lines are still parallel.', 'checked', '{"lint":[],"solve":{"answer":"Lines $\\ell''$ and $m''$ are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid transformations map parallel lines to parallel lines (they preserve distance, so the images never meet).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5db8545-368c-448f-97ac-36059de4acd4', 'NC26.M1.SGMR.1', 2, 'choice', 'Image of a point under a translation', 'A rectangle has vertices at $(1, 1)$, $(5, 1)$, $(5, 3)$ and $(1, 3)$. It is translated 3 units left and 4 units up. Which point is the image of the vertex $(5, 3)$?', '["$(8, -1)$","$(2, 7)$","$(2, -1)$","$(8, 7)$"]', '$(2, 7)$', NULL, 'Moving 3 units left subtracts 3 from the x-coordinate, and moving 4 units up adds 4 to the y-coordinate. So $(5, 3)$ becomes $(5 - 3, 3 + 4) = (2, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5-3, 3+4) = (2, 7).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbf1cd9e-bb6d-473c-bca4-953fd97d28c1', 'NC26.M1.SGMR.1', 2, 'choice', 'Image of a point under a translation', 'Under a translation, every point moves in the same way. If the point $(0, 0)$ moves to $(4, -3)$, where does the point $(2, 5)$ move?', '["$(6, 2)$","$(-2, 8)$","$(6, 8)$","$(-1, 9)$"]', '$(6, 2)$', NULL, 'The origin moved 4 units right and 3 units down, so every point moves 4 units right and 3 units down. Then $(2, 5)$ goes to $(2 + 4, 5 - 3) = (6, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector (4, -3). (2+4, 5-3) = (6, 2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb8357aa-454a-4ac4-9e5a-10f546fb760e', 'NC26.M1.SGMR.1', 2, 'numeric', 'Image of a point under a translation', 'The segment with endpoints $(-4, 2)$ and $(0, 5)$ is translated 7 units right and 3 units down. What is the y-coordinate of the image of the endpoint $(0, 5)$?', '[]', '2', '5-3', 'Moving down subtracts from the y-coordinate, and moving right does not change it. The endpoint $(0, 5)$ goes to $(7, 2)$, so its y-coordinate is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0, 5) -> (0+7, 5-3) = (7, 2). y = 2.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
