INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d96ed5c7-a432-4381-b074-3902861fb1ec', 'NC26.M1.SGMR.1', 2, 'choice', 'Image of a point under a reflection', 'Segment $AB$ has endpoints $A(1, 2)$ and $B(4, -3)$. It is reflected across the y-axis. Which pair gives the endpoints of the image?', '["$(1, -2)$ and $(4, 3)$","$(-1, -2)$ and $(-4, 3)$","$(2, 1)$ and $(-3, 4)$","$(-1, 2)$ and $(-4, -3)$"]', '$(-1, 2)$ and $(-4, -3)$', NULL, 'Reflecting across the y-axis changes the sign of each x-coordinate and keeps each y-coordinate. $A$ goes to (-1, 2) and $B$ goes to (-4, -3).', 'checked', '{"lint":[],"solve":{"answer":"$(-1, 2)$ and $(-4, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (-x, y): (1,2) -> (-1,2); (4,-3) -> (-4,-3).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
