INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6376fe9-65e9-4750-9780-cb5f97b888fb', 'NC26.M1.SGMR.1', 2, 'numeric', 'Image of a point under a rotation about the origin', 'A rotation of 270 degrees counterclockwise about the origin is applied to the point $(2, -7)$. What is the y-coordinate of the image?', '[]', '-2', '-2', 'A 270 degree counterclockwise turn is the same as a 90 degree clockwise turn, which sends $(x, y)$ to $(y, -x)$. So $(2, -7)$ goes to $(-7, -2)$, and the y-coordinate is $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"270 ccw = 90 cw: (x, y) -> (y, -x). (2, -7) -> (-7, -2). y = -2.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
