INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5d24974-ce98-4c02-a1a9-528ebd4e2335', 'NC26.M1.SGMR.1', 2, 'numeric', 'Transformations written in function notation', 'A transformation is given by $M(x, y) = (y, -x)$. What is the sum of the coordinates of $M(4, 9)$?', '[]', '5', '9-4', 'Put $x = 4$ and $y = 9$ into the rule: $M(4, 9) = (9, -4)$. The sum is $9 + (-4) = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M(4, 9) = (9, -4). Sum 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
