INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84066677-99f6-4539-b67d-388820323a71', 'NC26.M1.SGMR.1', 2, 'choice', 'Transformations written in function notation', 'The rule $G(x, y) = (-y, x)$ is applied to the point $(2, 7)$. What is $G(2, 7)$?', '["$(7, -2)$","$(-2, -7)$","$(7, 2)$","$(-7, 2)$"]', '$(-7, 2)$', NULL, 'Put $x = 2$ and $y = 7$ into the rule. The first coordinate is $-y = -7$ and the second is $x = 2$, so $G(2, 7) = (-7, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-7, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"G(2, 7) = (-7, 2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
