INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2792250-7413-4a87-8d34-25caacfe5f8e', 'NC26.M1.SGMR.1', 2, 'numeric', 'Find the preimage of a point', 'The image of a point under a 90 degree counterclockwise rotation about the origin is $(-6, 4)$. What is the sum of the coordinates of the original point?', '[]', '10', '4+6', 'A 90 degree counterclockwise turn sends $(a, b)$ to $(-b, a)$. Setting $(-b, a) = (-6, 4)$ gives $b = 6$ and $a = 4$. The original point is $(4, 6)$ and the sum is $4 + 6 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw: (x, y) -> (-y, x) = (-6, 4), so y = 6, x = 4. Original (4, 6); sum 10.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc27cc5c-0013-41b4-ae0c-52eab8e40739', 'NC26.M1.SGMR.1', 2, 'numeric', 'Find the preimage of a point', 'A figure is reflected across the y-axis. One vertex of the image is at $(-2, 9)$. What is the sum of the coordinates of the matching vertex of the original figure?', '[]', '11', '2+9', 'Reflecting back across the y-axis changes the sign of the x-coordinate, so the original vertex is $(2, 9)$. The sum is $2 + 9 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across y-axis is self-inverse: original (2, 9). Sum 11.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7f62e23-73ee-4069-920b-3db7429b2f2a', 'NC26.M1.SGMR.1', 2, 'choice', 'Identify the transformation from points and images', 'The images of the points $(3, 1)$ and $(5, 2)$ are $(-1, 3)$ and $(-2, 5)$. Which of these transformations produced those images?', '["a rotation of 90 degrees counterclockwise about the origin","a rotation of 90 degrees clockwise about the origin","a reflection across the line $y = x$","a rotation of 180 degrees about the origin"]', 'a rotation of 90 degrees counterclockwise about the origin', NULL, 'A 90 degree counterclockwise turn about the origin sends $(x, y)$ to $(-y, x)$. That takes $(3, 1)$ to $(-1, 3)$ and $(5, 2)$ to $(-2, 5)$, matching both images.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of 90 degrees counterclockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw: (x, y) -> (-y, x): (3,1) -> (-1,3), (5,2) -> (-2,5). Matches. 180 gives (-3,-1); 90 cw gives (1,-3); y = x gives (1,3).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f423fed-3b7d-4c21-bc8a-ab695bbf991b', 'NC26.M1.SGMR.1', 2, 'choice', 'Identify the transformation from points and images', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(4, 1)$ and $C(1, 3)$. Its image has vertices $A''(-1, -1)$, $B''(-4, -1)$ and $C''(-1, -3)$. Which transformation maps $ABC$ onto the image?', '["a reflection across the y-axis","a reflection across the x-axis","a translation 2 units left and 2 units down","a rotation of 180 degrees about the origin"]', 'a rotation of 180 degrees about the origin', NULL, 'Both coordinates of every vertex changed sign, which is a rotation of 180 degrees about the origin. A reflection would change only one sign, and a slide would move $B$ to $(2, -1)$.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of 180 degrees about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every vertex (x, y) -> (-x, -y): 180 rotation. Translation 2 left 2 down would send B(4,1) to (2,-1), not (-4,-1).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b2f6b68-f7de-45fb-931e-da1772b6434b', 'NC26.M1.SGMR.1', 2, 'numeric', 'Identify the transformation from points and images', 'A counterclockwise rotation about the origin takes the point $(0, 5)$ to the point $(5, 0)$. The rotation is more than 0 degrees and less than 360 degrees. What is its measure, in degrees?', '[]', '270', '270', 'Turning counterclockwise from the positive y-axis, the point passes the negative x-axis (90 degrees), then the negative y-axis (180 degrees), then reaches the positive x-axis (270 degrees). The rotation is 270 degrees.', 'checked', '{"lint":[],"solve":{"answer":"270","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0,5) is at 90 degrees; (5,0) is at 0 = 360 degrees. Counterclockwise from 90 to 360 is 270.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee78126b-b81b-4ca9-9e87-52d57dc093bb', 'NC26.M1.SGMR.1', 2, 'choice', 'Image after a sequence of transformations', 'Vertex $A$ of a triangle is at $(2, -1)$. The triangle is rotated 90 degrees counterclockwise about the origin and then translated 3 units to the left. Where is the final image of $A$?', '["$(-4, -2)$","$(1, -1)$","$(4, 2)$","$(-2, 2)$"]', '$(-2, 2)$', NULL, 'The rotation sends $(x, y)$ to $(-y, x)$, so $A$ goes to $(1, 2)$. Then moving 3 units left gives $(-2, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw: (2,-1) -> (1, 2). 3 left: (-2, 2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
