INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d5b64d6-076c-4298-aec7-7c7c5db6ba5a', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Triangle $ABC$ has sides of 5 cm, 7 cm and 9 cm. Triangle $XYZ$ has sides of 9 cm, 5 cm and 7 cm. What can be concluded?', '["They are congruent, by SSS","They are congruent, by SAS","They are not congruent, as the sides are in a different order","They cannot be compared without the angles"]', 'They are congruent, by SSS', NULL, 'Both triangles have the same three side lengths. The order in which they are listed does not matter, so they are congruent by SSS.', 'checked', '{"lint":[],"solve":{"answer":"They are congruent, by SSS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same three side lengths: SSS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
