VALUES ('fb325b13-8dcc-4755-ad26-a6e75bfc83ce', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Which rule uses two angles and a side that is NOT between those two angles?', '["SSS (side-side-side)","AAS (angle-angle-side)","SAS (side-angle-side)","ASA (angle-side-angle)"]', 'AAS (angle-angle-side)', NULL, 'In AAS the equal side is not between the two equal angles. In ASA the side is between them.', 'checked', '{"lint":[],"solve":{"answer":"AAS (angle-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-included side: AAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
