INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c10af72-27f0-48d6-b3c0-e6845131e3fc', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Mina knows that $\angle P = \angle S$, $\angle R = \angle U$ and $PR = SU$ in triangles $PQR$ and $STU$. Using only these facts, which rule can she use to show the triangles are congruent?', '["SSS (side-side-side)","SAS (side-angle-side)","ASA (angle-side-angle)","AAS (angle-angle-side)"]', 'ASA (angle-side-angle)', NULL, 'The side $PR$ joins $P$ and $R$, so it is between the two equal angles. Two angles and the side between them give ASA.', 'checked', '{"lint":[],"solve":{"answer":"ASA (angle-side-angle)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles P and R with PR between them: ASA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
