INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4666075b-cc23-47bd-a5b4-47ce734af0c5', 'NC26.M1.SGMR.2', 1, 'numeric', 'Using the angle sum before arguing congruence', 'Two congruent triangles are drawn. In the first triangle, two of the angles are $35^\circ$ and $85^\circ$. What is the measure of the third angle of the second triangle, in degrees?', '[]', '60', '180-35-85', 'The angles of the first triangle add to $180^\circ$, so its third angle is $180 - 35 - 85 = 60^\circ$. The second triangle has the same angles.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180-35-85 = 60.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
