INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('631a9319-e1c6-4d22-ae1a-671e82dcf31c', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle ABC \cong \triangle FED$, with the vertices matching in the order written. Which angle of $\triangle FED$ matches $\angle B$?', '["$\\angle F$","$\\angle D$","$\\angle B$","$\\angle E$"]', '$\angle E$', NULL, 'The letters match in order: $A$ with $F$, $B$ with $E$, $C$ with $D$. So $\angle B$ matches $\angle E$.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A-F, B-E, C-D: angle E.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
