INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad0eaf67-7736-4513-8b4f-2214bf4763d6', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle RST \cong \triangle UVW$, with the vertices matching in the order written. Which pair of sides must be equal in length?', '["$ST$ and $VW$","$ST$ and $UV$","$ST$ and $UW$","$RT$ and $VW$"]', '$ST$ and $VW$', NULL, '$R$ matches $U$, $S$ matches $V$ and $T$ matches $W$. Side $ST$ joins $S$ and $T$, so it matches $VW$.', 'checked', '{"lint":[],"solve":{"answer":"$ST$ and $VW$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S-V, T-W: ST matches VW.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
