INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f97d19b7-0525-42d3-92f1-f218e2a6763e', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle MNO \cong \triangle PQR$, with the vertices matching in the order written. Angle $N$ measures $44^\circ$. Which angle of $\triangle PQR$ also measures $44^\circ$?', '["$\\angle P$","$\\angle Q$","$\\angle R$","$\\angle O$"]', '$\angle Q$', NULL, '$N$ is second in the first name, so it matches the second letter of the other, $Q$. So $\angle Q = 44^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle Q$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"N-Q: angle Q.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
