INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b84414b9-5c57-4212-94d4-c2843b9ddd48', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written, and $AB = 5$ cm. Which side of $\triangle DEF$ is 5 cm long?', '["$EF$","$DF$","$DE$","$AB$"]', '$DE$', NULL, '$A$ matches $D$ and $B$ matches $E$, so $AB$ matches $DE$. Side $DE$ is 5 cm.', 'checked', '{"lint":[],"solve":{"answer":"$DE$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB matches DE.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
