INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18a306f3-7135-4b72-95bc-ecdb15203ccd', 'NC26.M1.SGMR.2', 2, 'numeric', 'Corresponding parts of congruent triangles', '$\triangle JKL \cong \triangle MNP$, with the vertices matching in the order written. In $\triangle JKL$, $\angle J = 62^\circ$ and $\angle K = 51^\circ$. What is the measure of $\angle P$, in degrees?', '[]', '67', '180-62-51', '$\angle P$ matches $\angle L$. The angles of a triangle add to $180^\circ$, so $\angle L = 180 - 62 - 51 = 67^\circ$, and $\angle P = 67^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 180-62-51 = 67; P matches L, so 67.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dd07972-5f27-4a0c-bd9d-3bdda7b3c20d', 'NC26.M1.SGMR.2', 2, 'choice', 'Corresponding parts of congruent triangles', 'Two triangles are congruent. Which statement about their areas must be true?', '["One area is larger than the other","One area is twice the other","The two areas are equal","The areas depend on the letters used"]', 'The two areas are equal', NULL, 'Congruent triangles have the same shape and size, so the space they cover, their area, is the same.', 'checked', '{"lint":[],"solve":{"answer":"The two areas are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Congruent figures have equal area.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d9eb781-6e33-453c-88dc-fa33d2fb8f7b', 'NC26.M1.SGMR.2', 2, 'numeric', 'Corresponding parts of congruent triangles', 'In $\triangle ABC$, $\angle A$ is $40^\circ$ larger than $\angle B$, and $\angle C = 20^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with $D$ matching $A$, $E$ matching $B$ and $F$ matching $C$. What is the measure of $\angle E$, in degrees?', '[]', '60', '(180-20-40)/2', 'Let $\angle B = b$. Then $\angle A = b + 40$ and $b + (b + 40) + 20 = 180$, so $2b = 120$ and $b = 60$. Since $E$ matches $B$, $\angle E = 60^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A+B = 160, A = B+40, so 2B = 120, B = 60; E = B = 60.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c182d1b9-ec34-42e6-996a-735bf755d476', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. $BC = 3x - 5$ and $EF = x + 9$. What is the value of $x$?', '[]', '7', '(9+5)/2', '$BC = EF$, so $3x - 5 = x + 9$. Then $2x = 14$ and $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-5 = x+9, 2x = 14, x = 7.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad948295-f757-4a1c-86bc-effded7bbe91', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', 'Triangles $ABC$ and $DEF$ are congruent and match in the order written. $\angle A = (4x - 6)^\circ$ and $\angle D = (2x + 18)^\circ$. What is the value of $x$?', '[]', '12', '(18+6)/2', 'The matching angles are equal: $4x - 6 = 2x + 18$. Then $2x = 24$ and $x = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x-6 = 2x+18, 2x = 24, x = 12 (angle 42).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ed85375-b7db-4ddd-a10c-41f12b010e3b', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', 'A triangular sign has sides of $x$ cm, $(x + 2)$ cm and $(x + 4)$ cm, and its perimeter is 27 cm. A second sign is congruent to the first. How long is the shortest side of the second sign, in centimeters?', '[]', '7', '(27-6)/3', 'The perimeter gives $x + (x + 2) + (x + 4) = 27$, so $3x + 6 = 27$ and $x = 7$. The shortest side is $x = 7$ cm, and the congruent sign has the same shortest side.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6 = 27, x = 7; shortest side 7, same in congruent sign.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4355081e-1d60-4cc6-9fe8-5556cc41546b', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. $AB = (2x + 3)$ cm and $DE = (4x - 9)$ cm. What is the length of $AB$, in centimeters?', '[]', '15', '2*6+3', '$AB = DE$, so $2x + 3 = 4x - 9$, giving $x = 6$. Then $AB = 2(6) + 3 = 15$ cm.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+3 = 4x-9, x = 6, AB = 15.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d3c4078-37e7-4bc0-a42c-eaea875e0866', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', 'In congruent triangles $ABC$ and $DEF$ (matching in the order written), $\angle B = (5x + 5)^\circ$ and $\angle E = (7x - 15)^\circ$. What is the measure of $\angle B$, in degrees?', '[]', '55', '5*10+5', 'Set the matching angles equal: $5x + 5 = 7x - 15$, so $x = 10$. Then $\angle B = 5(10) + 5 = 55^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+5 = 7x-15, x = 10, B = 55.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f654457e-3d35-4440-9066-51b49c781d1f', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', 'In triangles $ABC$ and $DEF$, $AB = DE$, $BC = EF$, $\angle B = (3x + 4)^\circ$ and $\angle E = (5x - 20)^\circ$. The triangles are congruent by SAS. What is the value of $x$?', '[]', '12', '(20+4)/2', 'The triangles are congruent, so the matching angles $B$ and $E$ are equal: $3x + 4 = 5x - 20$. Then $2x = 24$ and $x = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B is the included angle between AB and BC, E between DE and EF; SAS needs B = E: 3x+4 = 5x-20, x = 12 (40 degrees).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b45674bd-261d-444f-9823-617c65fe48ac', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A triangle has vertices $A(2, 3)$, $B(6, 3)$ and $C(2, 6)$. It is reflected across the $x$-axis. What is the perimeter of the reflected triangle, in units?', '[]', '12', '4+3+5', 'The sides of the original are $AB = 4$, $AC = 3$ and $BC = 5$ (a 3-4-5 right triangle). The reflection keeps these lengths, so the perimeter is $4 + 3 + 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = 4, AC = 3, BC = 5; perimeter 12, preserved by reflection.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40900c15-d7e1-4b1c-af12-e6ef21afa03c', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A triangle has vertices $(1, 1)$, $(4, 1)$ and $(4, 5)$. It is translated 2 units left and 3 units up. What is the $y$-coordinate of the image of the vertex $(4, 5)$?', '[]', '8', '5+3', 'Moving 3 units up adds 3 to the $y$-coordinate: $5 + 3 = 8$. (The move 2 units left changes only the $x$-coordinate, to 2.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,5) -> (2,8); y = 8.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84e167aa-3e6c-44e4-b5da-f413a90dfad4', 'NC26.M1.SGMR.2', 2, 'choice', 'Rigid motions preserve size and shape', 'Triangle $ABC$ is reflected across a line and then translated 6 units to the right to make triangle $DEF$. What can be concluded?', '["The triangles are only similar, as two moves were used","The triangles have equal angles but may have unequal sides","$\\triangle ABC \\cong \\triangle DEF$, as both moves keep lengths and angles","$\\triangle ABC \\cong \\triangle DEF$ only if the line passes through a vertex"]', '$\triangle ABC \cong \triangle DEF$, as both moves keep lengths and angles', NULL, 'A reflection and a translation are both rigid motions. A sequence of rigid motions keeps all lengths and angles, so the final triangle is congruent to the first.', 'checked', '{"lint":[],"solve":{"answer":"$\\triangle ABC \\cong \\triangle DEF$, as both moves keep lengths and angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Composition of rigid motions is rigid, so congruent.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3afc6af6-834c-4c74-853e-2439349c2fe3', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A rigid motion maps $\triangle ABC$ onto $\triangle A''B''C''$. Angle $A$ measures $52^\circ$, and angle $A''$ measures $(2x + 4)^\circ$. What is the value of $x$?', '[]', '24', '(52-4)/2', 'Rigid motions keep angle measures, so $2x + 4 = 52$. Then $2x = 48$ and $x = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+4 = 52, x = 24.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87cdd4e1-3aa7-4c8c-a274-2eb3f5f8bf0c', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Triangles $ABC$ and $DBC$ share the side $BC$. Also $AB = DB$ and $\angle ABC = \angle DBC$. Which rule shows that $\triangle ABC \cong \triangle DBC$?', '["SSS (side-side-side)","ASA (angle-side-angle)","AAS (angle-angle-side)","SAS (side-angle-side)"]', 'SAS (side-angle-side)', NULL, '$AB = DB$, $\angle ABC = \angle DBC$ (the angle between $AB$ and $BC$) and $BC = BC$ (shared). Two sides and the angle between them match, so SAS.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DB, included angle ABC = DBC, shared BC: SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5094152d-b750-4fa6-b339-d1d899a53de3', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In triangles $ABC$ and $DEF$, $\angle A = \angle D = 65^\circ$, $\angle C = \angle F = 45^\circ$ and $AB = DE = 10$. Using only the facts given, which rule shows that the triangles are congruent?', '["AAS (angle-angle-side)","SSS (side-side-side)","SAS (side-angle-side)","ASA (angle-side-angle)"]', 'AAS (angle-angle-side)', NULL, 'Two angles and a side are equal. $AB$ is not the side between $\angle A$ and $\angle C$ (that is $AC$), so the rule is AAS.', 'checked', '{"lint":[],"solve":{"answer":"AAS (angle-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles A and C; AB is not between them (AC is): AAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf3e7e90-da1c-458b-aa5a-ed7d52bb2bc2', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In kite $ABCD$, $AB = AD$ and $CB = CD$. The diagonal $AC$ splits the kite into $\triangle ABC$ and $\triangle ADC$. Which rule proves that these two triangles are congruent?', '["SAS (side-angle-side)","SSS (side-side-side)","ASA (angle-side-angle)","AAS (angle-angle-side)"]', 'SSS (side-side-side)', NULL, '$AB = AD$, $CB = CD$ and $AC$ is shared by both triangles. All three pairs of sides are equal, so SSS.', 'checked', '{"lint":[],"solve":{"answer":"SSS (side-side-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = AD, CB = CD, AC shared: SSS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21d13a3a-a17e-48d0-a5a7-2aea790f1a01', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Which pair of triangles can be shown to be congruent from the information given?', '["Both have three angles of $40^\\circ$, $60^\\circ$ and $80^\\circ$","Both have sides of 5 and 7, with $50^\\circ$ and $60^\\circ$ angles between them","Both have three sides of 5, 7 and 9 units","Both have sides of 5 and 7 and a $30^\\circ$ angle not between them"]', 'Both have three sides of 5, 7 and 9 units', NULL, 'Three equal sides give SSS. Equal angles alone do not fix the size. In the third pair the angles between the sides differ. In the fourth, the equal angle is not between the equal sides (SSA), which is not a congruence rule.', 'checked', '{"lint":[],"solve":{"answer":"Both have three sides of 5, 7 and 9 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Option 2 wording (''with 50 and 60 angles between them'') is muddled; presumably one triangle has 50 and the other 60. Does not affect the key.","work":"Option 1 SSA no; option 2 included angles differ, no; option 3 AAA no; option 4 SSS yes.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f94c538-7843-43bd-95ef-ddfe9f50901c', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Segments $AB$ and $CD$ cross at point $M$ with $AM = BM$ and $CM = DM$. Which rule shows that $\triangle AMC \cong \triangle BMD$?', '["SSS (side-side-side)","ASA (angle-side-angle)","AAS (angle-angle-side)","SAS (side-angle-side)"]', 'SAS (side-angle-side)', NULL, '$AM = BM$ and $CM = DM$. The angles $\angle AMC$ and $\angle BMD$ are vertical angles, so they are equal, and each is between the two equal sides. This is SAS.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AM = BM, vertical angles AMC = BMD, CM = DM: SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ae92c0a-eec5-4419-b08b-01f81aadae62', 'NC26.M1.SGMR.2', 2, 'choice', 'Why some information does not prove congruence', 'In $\triangle ABC$ and $\triangle DEF$, $AB = DE$, $BC = EF$ and $\angle C = \angle F$. Ruth says the triangles are congruent by SAS. What is wrong with her claim?', '["SAS needs all three pairs of sides to be equal in length","Angles can never be used to prove two triangles congruent","The equal angles are not between the pairs of equal sides","SAS needs two pairs of equal angles and one pair of sides"]', 'The equal angles are not between the pairs of equal sides', NULL, 'SAS needs the equal angle to be between the two equal sides. Here the sides are $AB$ and $BC$, whose angle is $\angle B$, but the known angles are $\angle C$ and $\angle F$. This is SSA, which does not prove congruence.', 'checked', '{"lint":[],"solve":{"answer":"The equal angles are not between the pairs of equal sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle between AB and BC is B, not C: SSA, not SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b54c2c65-ef6d-4466-bf88-597e6f820b94', 'NC26.M1.SGMR.2', 2, 'choice', 'Why some information does not prove congruence', 'In triangles $PQR$ and $XYZ$, which set of facts does NOT guarantee that the triangles are congruent?', '["$PQ = XY$, $QR = YZ$ and $PR = XZ$","$\\angle P = \\angle X$, $\\angle Q = \\angle Y$ and $PQ = XY$","$\\angle Q = \\angle Y$, $\\angle R = \\angle Z$ and $PQ = XY$","$PQ = XY$, $QR = YZ$ and $\\angle P = \\angle X$"]', '$PQ = XY$, $QR = YZ$ and $\angle P = \angle X$', NULL, 'The first set gives two sides and an angle that is not between them (SSA), which does not guarantee congruence. The other sets are SSS, ASA and AAS.', 'checked', '{"lint":[],"solve":{"answer":"$PQ = XY$, $QR = YZ$ and $\\angle P = \\angle X$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opt1 SSS, opt2 AAS (PQ not between Q and R), opt3 ASA, opt4 SSA (angle P not between PQ and QR): not guaranteed.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82e8f3f1-bab8-4695-86b3-3df5727cd12a', 'NC26.M1.SGMR.2', 2, 'choice', 'Why some information does not prove congruence', 'Which pair of triangles can NOT be congruent?', '["One has sides of 5, 5 and 8; the other has sides of 5, 8 and 8","One has sides of 6, 7 and 9; the other has sides of 9, 6 and 7","One has sides of 3, 6 and 7; the other has sides of 7, 3 and 6","One has sides of 4, 4 and 4; the other has sides of 4, 4 and 4"]', 'One has sides of 5, 5 and 8; the other has sides of 5, 8 and 8', NULL, 'Congruent triangles have the same three side lengths. The pair with sides 5, 5, 8 and 5, 8, 8 has different lists of lengths, so those triangles cannot be congruent. The other pairs have the same lengths in a different order, or exactly the same.', 'checked', '{"lint":[],"solve":{"answer":"One has sides of 5, 5 and 8; the other has sides of 5, 8 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,5,8 vs 5,8,8 have different side sets; others match.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('545e470a-7b71-4e62-a1af-bc089bb5abb0', 'NC26.M1.SGMR.2', 2, 'numeric', 'Using the angle sum before arguing congruence', 'In $\triangle ABC$, $\angle A = \angle B$ and $\angle C = 40^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with $D$ matching $A$, $E$ matching $B$ and $F$ matching $C$. What is the measure of $\angle E$, in degrees?', '[]', '70', '(180-40)/2', '$\angle A + \angle B = 180 - 40 = 140^\circ$, and the two angles are equal, so each is $70^\circ$. $\angle E$ matches $\angle B$, so $\angle E = 70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = B = (180-40)/2 = 70; E = 70.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
