INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('356f9bbd-0562-498b-85af-e267e67ab800', 'NC26.M1.SGMR.2', 2, 'choice', 'Reading a congruence statement (vertex order)', 'In triangles $ABC$ and $PQR$, $AB = QR$, $BC = RP$ and $CA = PQ$. Which congruence statement is correct?', '["$\\triangle ABC \\cong \\triangle PQR$","$\\triangle ABC \\cong \\triangle RPQ$","$\\triangle ABC \\cong \\triangle QPR$","$\\triangle ABC \\cong \\triangle QRP$"]', '$\triangle ABC \cong \triangle QRP$', NULL, '$AB = QR$ and $BC = RP$ show that $A \to Q$, $B \to R$ and $C \to P$. Written in that order, $\triangle ABC \cong \triangle QRP$.', 'checked', '{"lint":[],"solve":{"answer":"$\\triangle ABC \\cong \\triangle QRP$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A-Q, B-R, C-P gives AB=QR, BC=RP, CA=PQ: ABC = QRP.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc48ed3-5c1d-449a-ac60-561b1f2e8fdf', 'NC26.M1.SGMR.2', 2, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle JKL \cong \triangle NMP$, with the vertices matching in the order written. Which pair of angles must be equal?', '["$\\angle K$ and $\\angle M$","$\\angle K$ and $\\angle N$","$\\angle L$ and $\\angle M$","$\\angle J$ and $\\angle P$"]', '$\angle K$ and $\angle M$', NULL, '$J \to N$, $K \to M$ and $L \to P$. So $\angle K = \angle M$.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle K$ and $\\angle M$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"J-N, K-M, L-P: K and M.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('079c756c-a59d-466d-ad2e-2482acb199d0', 'NC26.M1.SGMR.2', 2, 'choice', 'Arguing that two triangles are congruent', 'In $\triangle ABC$ and $\triangle DEF$, $AB = DE$ and $\angle B = \angle E$. Which extra fact would prove the triangles congruent by SAS?', '["$AC = DF$","$\\angle A = \\angle D$","$BC = EF$","$\\angle C = \\angle F$"]', '$BC = EF$', NULL, 'The angle $\angle B$ is between $AB$ and $BC$. To use SAS the other side next to that angle is needed: $BC = EF$.', 'checked', '{"lint":[],"solve":{"answer":"$BC = EF$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need the other side of angle B: BC = EF.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('114095c7-7847-404d-8b01-dae1c2771ea1', 'NC26.M1.SGMR.2', 2, 'numeric', 'Arguing that two triangles are congruent', 'Six rules are: SSS, SAS, ASA, AAS, AAA and SSA. How many of these six can be used to prove that two triangles are congruent?', '[]', '4', '6-2', 'SSS, SAS, ASA and AAS prove congruence. AAA does not fix the size and SSA does not fix the shape. That makes 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SSS, SAS, ASA, AAS work; AAA and SSA do not: 4.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0ffd5a8-8635-4ab3-a5e4-7278574b9f68', 'NC26.M1.SGMR.2', 2, 'numeric', 'Arguing that two triangles are congruent', 'Two triangular brackets each have two sides of 12 inches and 16 inches that meet at a right angle. The brackets are congruent by SAS. How long is the third side of each bracket, in inches?', '[]', '20', '20', 'The third side is the hypotenuse of a right triangle with legs 12 and 16: $12^2 + 16^2 = 144 + 256 = 400$, so it is 20 inches. Congruent brackets have the same third side.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(144+256) = 20.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044d076e-7a42-4281-913f-d6f5d7f53ec7', 'NC26.M1.SGMR.2', 2, 'choice', 'Arguing that two triangles are congruent', 'Segments $AD$ and $BE$ cross at $C$. In a proof that $\triangle ABC \cong \triangle DEC$, a student writes $\angle ACB = \angle DCE$. What is the reason?', '["They are a linear pair, so they add to $180^\\circ$","They are vertical angles, so they are equal","They are corresponding angles of parallel lines","They are complementary, so they add to $90^\\circ$"]', 'They are vertical angles, so they are equal', NULL, '$\angle ACB$ and $\angle DCE$ sit on opposite sides of the point where the segments cross. Vertical angles are equal.', 'checked', '{"lint":[],"solve":{"answer":"They are vertical angles, so they are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles ACB and DCE are vertical angles at C.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eca8d22c-e9e3-4a99-bd77-ce60c99e54f4', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Rectangle $ABCD$ has the triangles $\triangle ABC$ and $\triangle DCB$. It is known that $AB = DC$, that both triangles have $BC$ as a side, and that $\angle ABC$ and $\angle DCB$ are both $90^\circ$. Using only these facts, which rule proves that $\triangle ABC \cong \triangle DCB$?', '["SSA (side-side-angle)","SAS (side-angle-side)","AAA (angle-angle-angle)","ASA (angle-side-angle)"]', 'SAS (side-angle-side)', NULL, '$AB = DC$ (given), $\angle ABC = \angle DCB$ (both right angles) and $BC = CB$ (shared side). The equal angle lies between the two equal sides in each triangle, so the rule is SAS. No pair of equal angles with a side between them is given for ASA, SSA is not a rule, and AAA does not prove congruence.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DC (side), angle ABC = angle DCB = 90 (included angle between AB,BC and DC,CB), BC = CB shared (side). Side-angle-side with the angle included: SAS. No second angle pair given for ASA; SSA and AAA are not valid criteria.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fb49fdf-1ebf-4e28-9ff4-1168f56e3553', 'NC26.M1.SGMR.2', 3, 'choice', 'The ambiguous side-side-angle case', 'In triangles $ABC$ and $DEF$, $AB = DE = 8$, $BC = EF = 6$, and $\angle A = \angle D = 30^\circ$. Which statement is correct?', '["The triangles are congruent by SAS","Congruence is not guaranteed, because the angle is not between the two known sides","The triangles are congruent by SSS","The triangles are congruent by ASA"]', 'Congruence is not guaranteed, because the angle is not between the two known sides', NULL, '$\angle A$ is not the angle between sides $AB$ and $BC$; it is opposite $BC$. Two sides and a non-included angle (SSA) do not guarantee congruence. Here, side $BC = 6$ can swing to meet the third side in two different places, giving two different triangles.', 'checked', '{"lint":[],"solve":{"answer":"Congruence is not guaranteed, because the angle is not between the two known sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle A lies between AB and AC, not between AB and BC, so this is SSA. Check ambiguity: side opposite A is BC = 6, adjacent AB = 8, height 8 sin 30 = 4; 4 < 6 < 8 so two different triangles exist. Congruence not guaranteed.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f410a059-f04d-4543-8947-2b45620211ba', 'NC26.M1.SGMR.2', 3, 'numeric', 'Proving congruence, then using it to solve', 'In triangles $ABC$ and $DEF$, $AB = DE$, $AC = DF$, and $\angle A = \angle D$. Also $BC = 4x - 3$ and $EF = 2x + 11$. What is the value of $x$?', '[]', '7', '(11+3)/(4-2)', '$AB = DE$, $AC = DF$, and the angle between them is equal ($\angle A = \angle D$), so the triangles are congruent by SAS. Matching sides of congruent triangles are equal, so $BC = EF$: $4x - 3 = 2x + 11$. Subtract $2x$ and add 3: $2x = 14$, so $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DE, AC = DF, angle A = angle D is included between AB and AC, so SAS: triangles congruent, BC = EF. 4x - 3 = 2x + 11, 2x = 14, x = 7 (BC = EF = 25).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b760a45c-a879-4d3c-ba50-348e93b14496', 'NC26.M1.SGMR.2', 3, 'choice', 'Arguing ASA after finding a third angle', 'Triangle $ABC$ has $\angle A = 50^\circ$, $\angle B = 60^\circ$, and $AB = 8$. Triangle $DEF$ has $\angle D = 50^\circ$, $\angle F = 70^\circ$, and $DE = 8$. Which argument is correct?', '["Not congruent, because the $70^\\circ$ angle is given for only one of the triangles","Not congruent, because only one pair of sides is known","Congruent by SAS, because $AB = DE$ and $\\angle A = \\angle D$","Congruent by ASA, because $\\angle E = 60^\\circ$ and $DE$ lies between $\\angle D$ and $\\angle E$"]', 'Congruent by ASA, because $\angle E = 60^\circ$ and $DE$ lies between $\angle D$ and $\angle E$', NULL, 'The angles in a triangle add to $180^\circ$, so $\angle E = 180^\circ - 50^\circ - 70^\circ = 60^\circ$. Then $\angle A = \angle D = 50^\circ$, $\angle B = \angle E = 60^\circ$, and the side $AB = DE = 8$ lies between those two angles in each triangle. That is the ASA rule. SAS would need two pairs of equal sides.', 'checked', '{"lint":[],"solve":{"answer":"Congruent by ASA, because $\\angle E = 60^\\circ$ and $DE$ lies between $\\angle D$ and $\\angle E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In DEF, angle E = 180 - 50 - 70 = 60. So angle A = angle D = 50, AB = DE = 8, angle B = angle E = 60; AB and DE are the included sides. ASA holds. Option 2 lacks a second side; options 3 and 4 are false.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f78d76c7-1c17-4b93-aca1-1c636be2cf4b', 'NC26.M1.SGMR.2', 3, 'numeric', 'Corresponding parts of congruent triangles', '$\triangle LMN \cong \triangle RST$, with the vertices matching in the order written. In $\triangle LMN$, $\angle L = 35^\circ$ and $\angle M$ is $20^\circ$ larger than $\angle L$. What is the measure of $\angle T$, in degrees?', '[]', '90', '180-35-(35+20)', '$\angle M = 35 + 20 = 55^\circ$, so $\angle N = 180 - 35 - 55 = 90^\circ$. $T$ matches $N$, so $\angle T = 90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L=35, M=55, N=180-90=90; T matches N, 90.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b3f932c-afd7-49bd-8ef0-0ed33e356b24', 'NC26.M1.SGMR.2', 3, 'numeric', 'Corresponding parts of congruent triangles', 'In right triangle $PQR$ the right angle is at $R$, and $\angle Q$ is twice as large as $\angle P$. Triangle $STU$ is congruent to $\triangle PQR$, with $S$ matching $P$, $T$ matching $Q$ and $U$ matching $R$. What is the measure of $\angle S$, in degrees?', '[]', '30', '90/3', 'The two acute angles add to $90^\circ$: $\angle P + 2\angle P = 90^\circ$, so $\angle P = 30^\circ$. Since $S$ matches $P$, $\angle S = 30^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P+Q = 90, Q = 2P, so 3P = 90, P = 30; S matches P, 30.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9daedce5-0598-499a-909e-36398c850af2', 'NC26.M1.SGMR.2', 3, 'numeric', 'Corresponding parts of congruent triangles', 'The perimeter of $\triangle ABC$ is 40 cm. It is congruent to $\triangle XYZ$, with $A$ matching $X$, $B$ matching $Y$ and $C$ matching $Z$. If $XY = 12$ cm and $YZ = 15$ cm, what is the length of $AC$, in centimeters?', '[]', '13', '40-12-15', '$XZ = 40 - 12 - 15 = 13$ cm because the perimeters are equal. $AC$ matches $XZ$, so $AC = 13$ cm.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = XY = 12, BC = YZ = 15, AC = 40-27 = 13.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2df1a085-f42e-4ebd-bf37-e75d6781c5ce', 'NC26.M1.SGMR.2', 3, 'numeric', 'Corresponding parts of congruent triangles', 'The sides of $\triangle ABC$ are in the ratio $AB : BC : CA = 3 : 4 : 5$, and its perimeter is 60 cm. Triangle $DEF$ is congruent to $\triangle ABC$, with the vertices matching in the order written. How long is $EF$, in centimeters?', '[]', '20', '60*4/12', 'The ratio parts add to $3 + 4 + 5 = 12$, so one part is $60 \div 12 = 5$ cm and $BC = 4 \times 5 = 20$ cm. $EF$ matches $BC$, so $EF = 20$ cm.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 parts = 60, part 5: AB 15, BC 20, CA 25. EF = BC = 20.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2673a96-7176-4cf3-b0fe-f0a083868896', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. $AB = 3x + 1$, $DE = 5x - 9$, $BC = 4y - 3$ and $EF = 2y + 7$, all in centimeters. What is the value of $x + y$?', '[]', '10', '5+5', '$AB = DE$: $3x + 1 = 5x - 9$, so $x = 5$. $BC = EF$: $4y - 3 = 2y + 7$, so $y = 5$. Then $x + y = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+1 = 5x-9, x = 5 (AB 16). 4y-3 = 2y+7, y = 5 (BC 17). x+y = 10.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a451530-4d24-4ecc-aae8-cd78686992be', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', 'In $\triangle ABC$, $\angle A = x^\circ$, $\angle B = 2x^\circ$ and $\angle C = 3x^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with $D$ matching $A$, $E$ matching $B$ and $F$ matching $C$. What is the measure of $\angle E$, in degrees?', '[]', '60', '2*180/6', 'The angles add to $180^\circ$: $x + 2x + 3x = 6x = 180$, so $x = 30$. $\angle B = 2x = 60^\circ$, and $\angle E$ matches $\angle B$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x = 180, x = 30, B = 60; E = 60.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d8c4c48-6360-41fd-8f62-54dd9db20ffe', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. In $\triangle ABC$, $AB = (2x + 5)$ cm and $AC = (x + 11)$ cm. In $\triangle DEF$, $DE = 15$ cm. How long is $DF$, in centimeters?', '[]', '16', '5+11', '$AB = DE$, so $2x + 5 = 15$ and $x = 5$. Then $AC = 5 + 11 = 16$ cm, and $DF$ matches $AC$, so $DF = 16$ cm.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DE: 2x+5 = 15, x = 5; AC = 16; DF = AC = 16.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1998b7d2-530a-459b-be14-4af53b5b617b', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', 'In $\triangle ABC$, $\angle A = (2x + 5)^\circ$, $\angle B = (3x)^\circ$ and $\angle C = 55^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with the vertices matching in the order written. What is the measure of $\angle E$, in degrees?', '[]', '72', '3*(180-55-5)/5', '$(2x + 5) + 3x + 55 = 180$, so $5x = 120$ and $x = 24$. Then $\angle B = 3(24) = 72^\circ$, and $\angle E$ matches $\angle B$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+5+55 = 180, x = 24; B = 72 (A = 53); E = 72.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('233b39bb-366d-4457-bd82-0daad8b477db', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. $\angle A = (3x + 10)^\circ$, $\angle D = (5x - 14)^\circ$, $\angle C = (2y)^\circ$ and $\angle F = (y + 36)^\circ$. What is the value of $x + y$?', '[]', '48', '12+36', '$3x + 10 = 5x - 14$ gives $x = 12$. $2y = y + 36$ gives $y = 36$. So $x + y = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+10 = 5x-14, x = 12 (A 46). 2y = y+36, y = 36 (C 72); B = 62 valid. x+y = 48.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2a9f720-0d76-41f3-b73e-9f9c49a92985', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', 'In parallelogram $ABCD$, the diagonal $AC$ splits the figure into two congruent triangles, $\triangle ABC \cong \triangle CDA$. Side $AB = 3x + 2$ and side $CD = 5x - 8$. What is the value of $x$?', '[]', '5', '(2+8)/2', 'In $\triangle ABC \cong \triangle CDA$, $A$ matches $C$ and $B$ matches $D$, so $AB$ matches $CD$. Then $3x + 2 = 5x - 8$, so $2x = 10$ and $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB matches CD: 3x+2 = 5x-8, x = 5.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eab3636-fabd-4b6a-b478-f11ef8202795', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', 'Segments $AB$ and $CD$ cross at $M$, the midpoint of both segments. This makes $\triangle AMC \cong \triangle BMD$. If $AC = 2x + 1$ and $BD = 4x - 5$, both in centimeters, how long is $AC$?', '[]', '7', '2*3+1', '$A$ matches $B$ and $C$ matches $D$, so $AC = BD$. Then $2x + 1 = 4x - 5$ gives $x = 3$, and $AC = 2(3) + 1 = 7$ cm.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+1 = 4x-5, x = 3, AC = 7.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
