INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de6f497d-09cc-4df8-8b66-47949733a0b8', 'NC26.M1.SGMR.2', 3, 'numeric', 'Rigid motions preserve size and shape', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(6, 0)$ and $C(0, 8)$. It is reflected across the $x$-axis and then translated 4 units to the right. What is the length of $B''C''$, in units?', '[]', '10', '10', 'Both moves keep lengths. In the original, $BC$ is the hypotenuse of a right triangle with legs 6 and 8, so $BC = 10$ (since $6^2 + 8^2 = 100$). Therefore $B''C'' = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BC = sqrt(36+64) = 10, preserved.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f258545-48ed-4e47-842d-b97fbfa8d874', 'NC26.M1.SGMR.2', 3, 'choice', 'Rigid motions preserve size and shape', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(4, 1)$ and $C(1, 5)$. Triangle $DEF$ has vertices $D(6, 2)$, $E(9, 2)$ and $F(6, 6)$. Which translation maps $A$ to $D$, $B$ to $E$ and $C$ to $F$?', '["1 unit right and 5 units up","5 units right and 1 unit down","6 units right and 2 units up","5 units right and 1 unit up"]', '5 units right and 1 unit up', NULL, 'From $A(1, 1)$ to $D(6, 2)$ is $+5$ in $x$ and $+1$ in $y$. Check $B$: $(4 + 5, 1 + 1) = (9, 2) = E$. Check $C$: $(1 + 5, 5 + 1) = (6, 6) = F$.', 'checked', '{"lint":[],"solve":{"answer":"5 units right and 1 unit up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A(1,1) -> D(6,2): +5, +1; B(4,1)->(9,2), C(1,5)->(6,6) check.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f0e02b2-b8d7-4dcd-9c04-7270d85a0115', 'NC26.M1.SGMR.2', 3, 'numeric', 'Rigid motions preserve size and shape', 'A triangle has vertices $(0, 0)$, $(8, 0)$ and $(0, 6)$. It is reflected across the $y$-axis and then translated 5 units up. What is the area of the final triangle, in square units?', '[]', '24', '8*6/2', 'Reflections and translations keep size, so the area is unchanged. The original is a right triangle with legs 8 and 6, so its area is $\frac{1}{2} \times 8 \times 6 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 8 and 6: area 24, preserved.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('471a1bbf-59ec-43ec-9b75-73ef092b933e', 'NC26.M1.SGMR.2', 3, 'choice', 'Rigid motions preserve size and shape', 'How can rigid motions be used to show that two triangles are congruent?', '["Find slides, turns and flips that map one triangle exactly onto the other","Find a dilation that makes one triangle the same size as the other triangle","Stretch one triangle until it covers the other triangle exactly","Show that the two triangles have the same three angle measures"]', 'Find slides, turns and flips that map one triangle exactly onto the other', NULL, 'Two figures are congruent when a sequence of rigid motions (translations, rotations, reflections) maps one exactly onto the other. A dilation or a stretch changes size, and equal angles alone do not fix the size.', 'checked', '{"lint":[],"solve":{"answer":"Find slides, turns and flips that map one triangle exactly onto the other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Congruence = a sequence of rigid motions mapping one onto the other.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2ad5c02-3dc2-487a-8fb2-c8d6cadd2ec9', 'NC26.M1.SGMR.2', 3, 'numeric', 'Rigid motions preserve size and shape', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(5, 0)$ and $C(0, 12)$. It is rotated $90^\circ$ about the origin and then translated 7 units to the left. What is the perimeter of the final triangle, in units?', '[]', '30', '5+12+13', 'Rotations and translations keep lengths. The legs are $AB = 5$ and $AC = 12$, so the hypotenuse is $BC = 13$ (since $5^2 + 12^2 = 169$). The perimeter is $5 + 12 + 13 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 5, 12, 13: perimeter 30, preserved.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4aee73a-4a2b-473b-8a77-656952562d55', 'NC26.M1.SGMR.2', 3, 'choice', 'Rigid motions preserve size and shape', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(4, 0)$ and $C(0, 3)$. Triangle $DEF$ has vertices $D(1, 1)$, $E(1, 5)$ and $F(-2, 1)$. Which statement is correct?', '["The triangles are not congruent, because they point in different directions","The triangles are congruent, because all three pairs of sides match","The triangles cannot be compared, because no angles are given","The triangles are congruent only if one is reflected before moving"]', 'The triangles are congruent, because all three pairs of sides match', NULL, 'In $\triangle ABC$: $AB = 4$, $AC = 3$, $BC = 5$. In $\triangle DEF$: $DE = 4$, $DF = 3$, $EF = \sqrt{3^2 + 4^2} = 5$. All three side lengths match, so the triangles are congruent by SSS. Pointing in a different direction does not matter.', 'checked', '{"lint":[],"solve":{"answer":"The triangles are congruent, because all three pairs of sides match","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABC: 4, 3, 5. DEF: DE 4, DF 3, EF sqrt(9+16) = 5. SSS congruent. Orientation: both counterclockwise (cross products +12), so no reflection needed; option 3 false.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2de93ad4-fa22-49f3-bcdd-0df4a6de7a15', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Which set of facts proves $\triangle ABC \cong \triangle DEF$ by the AAS rule?', '["$\\angle A = \\angle D$, $\\angle B = \\angle E$ and $AB = DE$","$\\angle A = \\angle D$, $\\angle C = \\angle F$ and $AB = DE$","$AB = DE$, $BC = EF$ and $\\angle A = \\angle D$","$\\angle A = \\angle D$, $\\angle B = \\angle E$ and $\\angle C = \\angle F$"]', '$\angle A = \angle D$, $\angle C = \angle F$ and $AB = DE$', NULL, 'AAS needs two equal angles and a side that is not between them. $\angle A$ and $\angle C$ have $AC$ between them, and $AB$ is not that side, so the first set is AAS. The second set is ASA, the third is SSA (not a rule) and the fourth is AAA (not a rule).', 'checked', '{"lint":[],"solve":{"answer":"$\\angle A = \\angle D$, $\\angle C = \\angle F$ and $AB = DE$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A, C and AB, which is not between A and C: AAS. Option 1 is ASA, 3 AAA, 4 SSA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75416a04-08b2-499a-bc64-80b545390f57', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In quadrilateral $ABCD$, $AB \parallel CD$ and $AB = CD$. Diagonal $AC$ makes $\angle BAC = \angle DCA$. Which rule proves that $\triangle ABC \cong \triangle CDA$?', '["SSS (side-side-side)","ASA (angle-side-angle)","SAS (side-angle-side)","AAS (angle-angle-side)"]', 'SAS (side-angle-side)', NULL, '$AB = CD$ (given), $\angle BAC = \angle DCA$ (the angle between $AB$ and $AC$, and between $CD$ and $CA$) and $AC = CA$ (shared). Two sides and the angle between them match: SAS.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = CD, included angle BAC = DCA, AC shared: SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4d818b0-2beb-4400-ad47-369daaa66c0c', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Segments $AC$ and $BD$ cross at $O$. $AO = CO$ and $\angle BAO = \angle DCO$. Which rule proves that $\triangle ABO \cong \triangle CDO$?', '["ASA (angle-side-angle)","SSS (side-side-side)","SAS (side-angle-side)","AAS (angle-angle-side)"]', 'ASA (angle-side-angle)', NULL, '$\angle BAO = \angle DCO$ (given), $AO = CO$ (given) and $\angle AOB = \angle COD$ (vertical angles). The side $AO$ is between $\angle BAO$ and $\angle AOB$, so the rule is ASA.', 'checked', '{"lint":[],"solve":{"answer":"ASA (angle-side-angle)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AO = CO, angle BAO = DCO, vertical angles AOB = COD; AO is between angles A and O: ASA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbf04366-5874-40eb-864c-9b39c5328906', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In parallelogram $ABCD$, the diagonal $BD$ forms $\triangle ABD$ and $\triangle CDB$. It is known that $\angle ABD = \angle CDB$ and $\angle ADB = \angle CBD$. Which rule proves $\triangle ABD \cong \triangle CDB$?', '["SSS (side-side-side)","SAS (side-angle-side)","ASA (angle-side-angle)","AAS (angle-angle-side)"]', 'ASA (angle-side-angle)', NULL, 'The shared side $BD$ lies between $\angle ABD$ and $\angle ADB$ in the first triangle, and between $\angle CDB$ and $\angle CBD$ in the second. Two angles and the side between them match: ASA.', 'checked', '{"lint":[],"solve":{"answer":"ASA (angle-side-angle)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles at B and D, shared side BD between them: ASA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7faa6cd2-6e1a-40d4-bc39-ee62a6219129', 'NC26.M1.SGMR.2', 3, 'choice', 'Why some information does not prove congruence', 'Triangles $ABC$ and $DEF$ have $\angle A = \angle D$, $\angle B = \angle E$ and $\angle C = \angle F$. Also $AC = DF$. Can we conclude that the triangles are congruent?', '["No, because equal angles can belong to triangles of different sizes","Yes, because two angles and the side between them are equal","Yes, but only if both triangles are right triangles","No, because the equal side is the longest side"]', 'Yes, because two angles and the side between them are equal', NULL, '$AC$ lies between $\angle A$ and $\angle C$, and $\angle A = \angle D$ and $\angle C = \angle F$ with $AC = DF$. That is ASA, so the triangles are congruent. (Equal angles alone are not enough, but with one pair of equal sides they are.)', 'checked', '{"lint":[],"solve":{"answer":"Yes, because two angles and the side between them are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = D, C = F, AC = DF with AC between A and C: ASA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('123d72f6-6f76-4a5a-b6eb-73711c0cdc04', 'NC26.M1.SGMR.2', 3, 'numeric', 'Using the angle sum before arguing congruence', 'The exterior angle at $C$ of $\triangle ABC$ measures $130^\circ$, and $\angle A = 50^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with $D$ matching $A$, $E$ matching $B$ and $F$ matching $C$. What is the measure of $\angle E$, in degrees?', '[]', '80', '130-50', 'An exterior angle equals the sum of the two remote interior angles: $130 = 50 + \angle B$, so $\angle B = 80^\circ$. $\angle E$ matches $\angle B$, so $\angle E = 80^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 180-130 = 50; B = 180-50-50 = 80 (or exterior = A + B: B = 80). E = 80.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8d48b3a-b8df-4bc0-aca8-65bfabd8fe87', 'NC26.M1.SGMR.2', 3, 'choice', 'Using the angle sum before arguing congruence', 'In $\triangle ABC$, $\angle B = 35^\circ$, $\angle C = 75^\circ$ and $BC = 10$. In $\triangle DEF$, $\angle D = 70^\circ$, $\angle E = 35^\circ$ and $EF = 10$. Which conclusion is correct?', '["They are congruent by SAS, as two sides are given","They are not congruent, as only one side is given","They are congruent by ASA, after the third angle of each is found","They are not congruent, as the angles are listed in different orders"]', 'They are congruent by ASA, after the third angle of each is found', NULL, '$\angle A = 180 - 35 - 75 = 70^\circ = \angle D$, and $\angle F = 180 - 70 - 35 = 75^\circ = \angle C$. Then $\angle B = \angle E$, $\angle C = \angle F$ and the side between them, $BC = EF = 10$: ASA.', 'checked', '{"lint":[],"solve":{"answer":"They are congruent by ASA, after the third angle of each is found","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: only DEF needs its third angle found for ASA; ''of each'' is loose but harmless.","work":"ABC: A = 70, B = 35, C = 75, BC = 10. DEF: F = 75, D = 70, E = 35, EF = 10. B-E, C-F with BC = EF between them: ASA.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9610e691-c705-43d8-91ad-bcf7003884ea', 'NC26.M1.SGMR.2', 3, 'choice', 'Reading a congruence statement (vertex order)', 'It is known that $\triangle ABC \cong \triangle DEF$ and also that $\triangle ABC \cong \triangle DFE$. What does this tell us about $\triangle ABC$?', '["Sides $AB$ and $BC$ are equal","Sides $AB$ and $AC$ are equal","All three sides are equal","It has a right angle at $A$"]', 'Sides $AB$ and $AC$ are equal', NULL, 'The first statement gives $AB = DE$ and $AC = DF$. The second gives $AB = DF$ and $AC = DE$. So $AB = DE = AC$ and $\triangle ABC$ is isosceles with $AB = AC$. The other sides need not be equal.', 'checked', '{"lint":[],"solve":{"answer":"Sides $AB$ and $AC$ are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DE and AB = DF, AC = DF and AC = DE, so AB = AC. Not necessarily equilateral.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e19daacf-391d-419c-96f9-7635ef9822ef', 'NC26.M1.SGMR.2', 3, 'choice', 'Arguing that two triangles are congruent', 'In $\triangle ABC$ and $\triangle DEF$, $\angle B = \angle E$ and $\angle C = \angle F$. Which extra fact would NOT be enough to prove the triangles congruent?', '["$AB = DE$","$AC = DF$","$BC = EF$","$\\angle A = \\angle D$"]', '$\angle A = \angle D$', NULL, 'If two angles are equal, the third angles are equal too, so $\angle A = \angle D$ adds nothing new. A side is needed: $BC = EF$ gives ASA, and $AB = DE$ or $AC = DF$ gives AAS.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle A = \\angle D$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = D gives only AAA; any side gives ASA or AAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aecdc8b0-9b35-4194-be18-e58a8cf50fdd', 'NC26.M1.SGMR.2', 3, 'choice', 'Arguing that two triangles are congruent', 'Which argument correctly proves that two triangles are congruent?', '["Both have sides of 4 and 6 with a $50^\\circ$ angle between them, so SAS","Both have angles of $50^\\circ$, $60^\\circ$ and $70^\\circ$, so AAA applies","Both have sides of 4 and 6 and a $50^\\circ$ angle across from the 4, so SAS","Both have one side of 4 and one angle of $50^\\circ$, so ASA applies"]', 'Both have sides of 4 and 6 with a $50^\circ$ angle between them, so SAS', NULL, 'Only the first argument names two sides and the angle between them. AAA is not a congruence rule. In the third argument the angle is not between the sides, and the fourth does not give two angles and a side.', 'checked', '{"lint":[],"solve":{"answer":"Both have sides of 4 and 6 with a $50^\\circ$ angle between them, so SAS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only option 3 is a valid SAS (included angle).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('920a7628-f251-4473-aca5-a4420b97614e', 'NC26.M1.SGMR.2', 3, 'choice', 'Arguing that two triangles are congruent', 'One triangle has sides of 7, 24 and 25. A second triangle has two sides of 7 and 24 with a right angle between them. Which statement is correct?', '["They are not congruent, since no angles are given for the first triangle","They are congruent by AAA, since both triangles have a right angle","They are congruent, since both have a right angle between sides 7 and 24","They cannot be compared, since the third side of the second triangle is unknown"]', 'They are congruent, since both have a right angle between sides 7 and 24', NULL, '$7^2 + 24^2 = 49 + 576 = 625 = 25^2$, so the first triangle is a right triangle, and the right angle is between the sides 7 and 24. Both triangles then have sides 7 and 24 with a $90^\circ$ angle between them: SAS.', 'checked', '{"lint":[],"solve":{"answer":"They are congruent, since both have a right angle between sides 7 and 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2+24^2 = 625 = 25^2, so first is right with the right angle between 7 and 24; second by SAS has hypotenuse 25. Congruent.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce26342-ac6d-4e7c-8ff4-1b2f4b57a7c0', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Triangle 1 has angles of $40^\circ$, $60^\circ$ and $80^\circ$ and a side of 5 cm. Triangle 2 has the same three angles and a side of 5 cm. Which statement is correct?', '["Congruent by AAS, because two angles and a side are equal","Congruent by AAA, because all three angles are equal","Not congruent, because AAA does not prove congruence","Not necessarily, because the 5 cm sides may not match"]', 'Not necessarily, because the 5 cm sides may not match', NULL, 'AAS needs the equal side to be in the same position in both triangles (opposite the same angle). Here the 5 cm side could be opposite $40^\circ$ in one triangle and opposite $60^\circ$ in the other. Then the triangles are different sizes. If the 5 cm sides do match, they would be congruent. We cannot tell, so the triangles are not necessarily congruent. AAA never proves congruence by itself.', 'checked', '{"lint":[],"solve":{"answer":"Not necessarily, because the 5 cm sides may not match","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft spot: stem asks ''Which statement is correct?'' but options read as answers to ''Are they congruent?'' (''Not necessarily...''). Rewording the stem to ''Are the two triangles congruent?'' would read better.","work":"Same three angles makes them similar. A 5 cm side in each makes them congruent only if the 5 cm sides are corresponding (opposite equal angles). Not stated, e.g. 5 cm opposite 40 in one and opposite 80 in the other gives different sizes. So not necessarily congruent. AAS claim ignores correspondence; ''Not congruent'' is too strong; AAA is not a criterion.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('393895e8-3787-44e3-8161-8cd795367ab2', 'NC26.M1.SGMR.2', 3, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In $\triangle ABC$, a line from $A$ meets side $BC$ at $D$. The line bisects $\angle BAC$ and is perpendicular to $BC$. Both $\triangle ABD$ and $\triangle ACD$ have $AD$ as a side. Using only these facts, which rule proves that $\triangle ABD \cong \triangle ACD$?', '["SSS (side-side-side)","SAS (side-angle-side)","AAA (angle-angle-angle)","ASA (angle-side-angle)"]', 'ASA (angle-side-angle)', NULL, '$\angle BAD = \angle CAD$ (bisector), $AD = AD$ (shared side) and $\angle ADB = \angle ADC = 90^\circ$ (perpendicular). The shared side $AD$ lies between the two equal angles in each triangle, so the rule is ASA. Only one pair of sides is known, so SSS and SAS cannot be used, and AAA does not prove congruence.', 'checked', '{"lint":[],"solve":{"answer":"ASA (angle-side-angle)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bisector: angle BAD = angle CAD. Perpendicular: angle ADB = angle ADC = 90. AD shared, and it lies between the angles at A and D in each triangle. Angle-side-angle with included side: ASA. No other sides known (no SSS/SAS); AAA invalid.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bf2975-9131-44bf-970f-530b5f734c32', 'NC26.M1.SGMR.3', 1, 'numeric', 'Midpoint of a segment', 'What is the $x$-coordinate of the midpoint of the segment with endpoints $(2, 4)$ and $(10, 8)$?', '[]', '6', '(2+10)/2', 'The midpoint''s $x$-coordinate is the average of the endpoints'' $x$-coordinates: $(2 + 10) \div 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-midpoint = (2 + 10)/2 = 6.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
