INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca919281-9f52-4c97-88b1-1c9abe0540d3', 'NC26.M1.SGMR.3', 1, 'numeric', 'Midpoint of a segment', 'The endpoints of a segment are $(-4, 5)$ and $(6, 5)$. What is the $x$-coordinate of its midpoint?', '[]', '1', '(-4+6)/2', 'The $x$-coordinate of the midpoint is the average of the two $x$-coordinates: $\frac{-4 + 6}{2} = \frac{2}{2} = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4 + 6)/2 = 1.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
