INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ac568e4-0e58-45cd-abe8-31e41993d4c2', 'NC26.M1.SGMR.3', 1, 'numeric', 'Midpoint of a segment', 'On a map, the library is at $(2, 7)$ and the park is at $(8, 3)$. A bench is exactly halfway between them. What is the sum of the bench''s two coordinates?', '[]', '10', '(2+8)/2+(7+3)/2', 'The bench is at the midpoint: $\left(\frac{2 + 8}{2}, \frac{7 + 3}{2}\right) = (5, 5)$. The sum of its coordinates is $5 + 5 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint (5, 5). Sum 10.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('672862de-30f4-4950-b799-5138beaa5ebb', 'NC26.M1.SGMR.3', 1, 'numeric', 'Endpoint from a midpoint', 'A segment has one endpoint at $(1, 6)$. Its midpoint is $(4, 6)$. What is the $x$-coordinate of the other endpoint?', '[]', '7', '2*4-1', 'The midpoint $x$-coordinate is the average of the endpoints'' $x$-coordinates: $\frac{1 + x}{2} = 4$. So $1 + x = 8$ and $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 2(4) - 1 = 7.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
