INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94e422c7-d679-4dd7-8901-c2c6cac8c088', 'NC26.M1.SGMR.3', 1, 'choice', 'Endpoint from a midpoint', 'The midpoint of segment $CD$ is $(5, 5)$ and $C$ is $(2, 3)$. Which point is $D$?', '["$(8, 7)$","$(3.5, 4)$","$(7, 8)$","$(3, 2)$"]', '$(8, 7)$', NULL, 'The midpoint is halfway from $C$ to $D$. From $C$ to the midpoint, $x$ goes up by $5 - 2 = 3$ and $y$ goes up by $5 - 3 = 2$. Make the same step again: $D = (5 + 3, 5 + 2) = (8, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(8, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D = (2(5) - 2, 2(5) - 3) = (8, 7).","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1021aebf-d1c8-4a25-8acd-b5965aa90874', 'NC26.M1.SGMR.3', 1, 'numeric', 'Perimeter from coordinates', 'The vertices of a square are $(2, 2)$, $(2, 7)$, $(7, 7)$ and $(7, 2)$. What is its perimeter, in units?', '[]', '20', '4*5', 'The side from $(2, 2)$ to $(2, 7)$ is vertical and $7 - 2 = 5$ units long. A square has 4 equal sides, so the perimeter is $4 \times 5 = 20$ units.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 5, perimeter 20.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3df6af9b-94ee-4772-83b8-2bd2f5578ea6', 'NC26.M1.SGMR.3', 1, 'choice', 'Perimeter from coordinates', 'A rectangle has opposite corners at $(-3, 1)$ and $(4, 5)$, and its sides are horizontal and vertical. What is its perimeter, in units?', '["28","22","11","14"]', '22', '2*(7+4)', 'The width is $4 - (-3) = 7$ and the height is $5 - 1 = 4$. The perimeter is $2(7 + 4) = 22$ units. (28 is the area, and 11 is only half the perimeter.)', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4 - (-3) = 7, height 5 - 1 = 4. Perimeter 2(11) = 22.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77bd3861-5a4a-4d0a-b071-8a4609263641', 'NC26.M1.SGMR.3', 1, 'numeric', 'Area from coordinates', 'A rectangle has opposite corners at $(2, 3)$ and $(9, 6)$, and its sides are horizontal and vertical. What is its area, in square units?', '[]', '21', '7*3', 'The width is $9 - 2 = 7$ and the height is $6 - 3 = 3$. The area is $7 \times 3 = 21$ square units.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 7, height 3: area 21.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
