INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5bc9f0a-a585-41db-b8c0-013789be8356', 'NC26.M1.SGMR.3', 1, 'numeric', 'Area from coordinates', 'A right triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 5)$. What is its area, in square units?', '[]', '15', '6*5/2', 'The two legs lie along the axes, with lengths 6 and 5. The area of a triangle is $\frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 6 \times 5 = 15$ square units.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(6)(5) = 15.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
