INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87b2c70b-6b3c-4dcf-8876-b87ea0371a14', 'NC26.M1.SGMR.3', 1, 'choice', 'Area from coordinates', 'A triangle has vertices $(1, 2)$, $(7, 2)$ and $(4, 8)$. What is its area, in square units?', '["36","12","18","24"]', '18', '6*6/2', 'The base from $(1, 2)$ to $(7, 2)$ is horizontal and 6 units long. The height is the vertical distance from the base to the top vertex: $8 - 2 = 6$. The area is $\frac{1}{2} \times 6 \times 6 = 18$ square units. (36 forgets the one half.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 6 (on y = 2), height 8 - 2 = 6. Area 18.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052826ed-19f7-4ea3-a91e-b71419ef5fb9', 'NC26.M1.SGMR.3', 1, 'numeric', 'Distance between two points', 'A vertical segment connects $(2, 3)$ and $(2, 12)$. How long is the segment, in units?', '[]', '9', '12-3', 'Both points have $x$-coordinate 2, so the segment is vertical. Its length is the difference of the $y$-coordinates: $12 - 3 = 9$ units.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 3 = 9.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
