INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ffffd33-a448-4670-ab3e-ce1d231dfc74', 'NC26.M1.SDSR.1', 1, 'numeric', 'Reading counts in a two-way table', 'A club sorts its members by grade and activity. In grade 9, 7 members are in chess and 5 are in drama. In grade 10, 8 members are in chess and 10 are in drama. How many members are in grade 9 and in drama?', '[]', '5', '5', 'The count for grade 9 and drama is given directly: 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 9 and drama cell = 5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
