INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10688985-d68f-4d1c-91b9-2707c73b86fd', 'NC26.M1.SDSR.1', 1, 'choice', 'Finding a missing entry in a two-way table', 'A class has 20 students, and 12 are boys. Of the boys, 7 play the drums. Also, 4 of the girls play the drums. How many girls do NOT play the drums?', '["5","7","8","4"]', '4', '20-12-4', 'There are $20 - 12 = 8$ girls. Of them, 4 play the drums, so $8 - 4 = 4$ do not.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls = 20 - 12 = 8; 4 girls play drums; 8 - 4 = 4 do not.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
