INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21d1188c-7e04-4c63-aa08-11c3bdfc4bff', 'NC26.M1.SDSR.1', 1, 'choice', 'Joint probability from a two-way table', 'Of 40 students, 12 boys walk to school, 8 boys ride the bus, 10 girls walk and 10 girls ride the bus. One student is chosen at random. What is the probability that the student is a girl who walks?', '["$\\frac{1}{4}$","$\\frac{1}{2}$","$\\frac{11}{20}$","$\\frac{3}{10}$"]', '$\frac{1}{4}$', NULL, 'There are 10 girls who walk out of 40 students, so the probability is $\frac{10}{40} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls who walk = 10; 10/40 = 1/4. Total 12+8+10+10=40.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
