INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aafa93f-8f16-4dec-92a9-b96f23d1a070', 'NC26.M1.SDSR.1', 2, 'numeric', 'Finding a missing entry in a two-way table', 'Of 40 students, 25 are girls. Of the girls, 15 like soccer. In all, 25 students like soccer. How many boys do NOT like soccer?', '[]', '5', '(40-25)-(25-15)', 'There are $40 - 25 = 15$ boys. Soccer fans who are boys: $25 - 15 = 10$. So $15 - 10 = 5$ boys do not like soccer.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 15; boys liking soccer 25 - 15 = 10; boys not = 5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
