INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('533f6f4e-29d5-4189-be92-984db7f0fb10', 'NC26.M1.SDSR.1', 2, 'numeric', 'Joint probability from a two-way table', 'A club has 40 students: 16 boys and 24 girls. Exactly 6 of the boys and 9 of the girls wear glasses. One student is chosen at random. What is the probability that the student is a girl who wears glasses? Write your answer as a fraction.', '[]', '9/40', '9/40', '9 of the 40 students are girls who wear glasses, so the probability is $\frac{9}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"9/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls with glasses 9; 9/40.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
