INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1224e28a-74a1-42ab-8be0-a1f543cf3905', 'NC26.M1.SDSR.1', 2, 'numeric', 'Marginal probability from a two-way table', 'A library recorded 70 visits. Students made 15 visits to borrow books and 20 visits without borrowing. Adults made 25 visits to borrow books and 10 visits without borrowing. One visit is chosen at random. What is the probability that it was made by an adult? Write your answer as a fraction.', '[]', '1/2', '1/2', 'Adult visits: $25 + 10 = 35$ out of 70. $\frac{35}{70} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adult visits 25 + 10 = 35; 35/70 = 1/2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
