INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f849a73-fad3-456d-b636-c8168952f5c7', 'NC26.M1.SDSR.1', 2, 'choice', 'Marginal probability from a two-way table', 'A bakery sold 60 items. Adults bought 18 muffins and 12 cookies. Children bought 22 muffins and 8 cookies. One sale is chosen at random. What is the probability that the item was a muffin?', '["$\\frac{3}{10}$","$\\frac{11}{30}$","$\\frac{2}{3}$","$\\frac{1}{3}$"]', '$\frac{2}{3}$', NULL, 'Muffins: $18 + 22 = 40$ out of 60. $\frac{40}{60} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Muffins 18 + 22 = 40; 40/60 = 2/3.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
