INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1acd2e35-f987-40d9-839a-3a6bc48a6ae8', 'NC26.M1.SDSR.1', 2, 'numeric', 'Probability of a complement (not)', 'A spinner has four colors. The probability of red is $\frac{1}{4}$, of blue is $\frac{1}{3}$ and of green is $\frac{1}{6}$. The rest of the spinner is yellow. What is the probability of landing on yellow? Write your answer as a fraction.', '[]', '1/4', '1-1/4-1/3-1/6', 'The four probabilities add to 1. Red, blue and green together make $\frac{3}{12} + \frac{4}{12} + \frac{2}{12} = \frac{9}{12}$, so yellow is $1 - \frac{9}{12} = \frac{3}{12} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 + 1/3 + 1/6 = 3/12 + 4/12 + 2/12 = 9/12; yellow = 3/12 = 1/4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89e22d97-e764-4e95-b4aa-af75dd0df253', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability of a union (or)', 'Of the 60 members of a school musical, 25 sing, 30 dance and 10 do both. One member is chosen at random. What is the probability that the member sings or dances?', '["$\\frac{3}{4}$","$\\frac{11}{12}$","$\\frac{1}{6}$","$\\frac{5}{12}$"]', '$\frac{3}{4}$', NULL, 'Singers or dancers: $25 + 30 - 10 = 45$ (the 10 who do both were counted twice). $\frac{45}{60} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + 30 - 10 = 45; 45/60 = 3/4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7cab40-fa7c-4161-b2f1-4840bc8134a7', 'NC26.M1.SDSR.1', 2, 'numeric', 'Probability of a union (or)', 'A spinner has 10 equal sections numbered 1 to 10. What is the probability that it lands on an even number or on a number greater than 7? Write your answer as a fraction.', '[]', '3/5', '3/5', 'Even: 2, 4, 6, 8, 10. Greater than 7: 8, 9, 10. Together (8 and 10 counted once): 2, 4, 6, 8, 9, 10, which is 6 numbers. $\frac{6}{10} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even: 2,4,6,8,10; >7: 8,9,10; union 2,4,6,8,9,10 = 6; 6/10 = 3/5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72c84f9f-f0ce-4b2b-b6fa-e697147f1b6d', 'NC26.M1.SDSR.1', 2, 'numeric', 'Counting both, either and neither', 'In a class, 17 students ride the bus to school, 12 walk, and 4 do both on different days. How many students ride the bus or walk (or both)?', '[]', '25', '17+12-4', 'Adding 17 and 12 counts the 4 who do both twice, so $17 + 12 - 4 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 + 12 - 4 = 25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
