INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff5629ea-ca17-4ea9-88f2-e58da647362b', 'NC26.M1.SDSR.1', 2, 'choice', 'Counting both, either and neither', 'In a survey, 20 students like pizza, 15 like tacos and 8 like both. How many students like pizza but NOT tacos?', '["7","12","5","27"]', '12', '20-8', 'Of the 20 pizza fans, 8 also like tacos, so $20 - 8 = 12$ like pizza only. (7 like tacos only; 27 is the number who like at least one.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 - 8 = 12.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
