INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5896a36e-576b-412a-9d37-da4b979a2448', 'NC26.M1.SDSR.1', 2, 'numeric', 'Counting both, either and neither', 'In a class of 30 students, 20 take art, 16 take music and 8 take both. How many students take neither?', '[]', '2', '30-(20+16-8)', 'Students taking art or music: $20 + 16 - 8 = 28$. The rest take neither: $30 - 28 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Union 20 + 16 - 8 = 28; neither 30 - 28 = 2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
