INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83272ab9-cf6d-4acc-8566-51519c708888', 'NC26.M1.SDSR.1', 2, 'numeric', 'Listing a sample space and counting outcomes', 'A spinner has 4 equal sections numbered 1 to 4. It is spun twice, and the pair of numbers is recorded in order. How many outcomes are in the sample space?', '[]', '16', '4*4', 'There are 4 results for the first spin and 4 for the second: $4 \times 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 4 = 16.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
