INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e8dea59-bb05-418a-809a-62e9efa2f977', 'NC26.M1.SDSR.1', 2, 'choice', 'Listing a sample space and counting outcomes', 'A coin is flipped three times. How many outcomes are in the sample space?', '["6","9","8","3"]', '8', '2^3', 'Each flip has 2 results, so there are $2 \times 2 \times 2 = 8$ outcomes. (HHH, HHT, HTH, HTT, THH, THT, TTH, TTT.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
