INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd511924-5440-4266-a0cd-7ce267da724c', 'NC26.M1.SDSR.1', 2, 'choice', 'Listing a sample space and counting outcomes', 'Two dice are rolled, and the results are written as an ordered pair. Which pair is NOT a possible outcome?', '["$(1, 6)$","$(4, 4)$","$(2, 5)$","$(7, 2)$"]', '$(7, 2)$', NULL, 'A die shows 1 to 6, so a 7 is impossible. The other pairs each use numbers from 1 to 6.', 'checked', '{"lint":[],"solve":{"answer":"$(7, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft: \"two dice\" does not say six-sided; standard assumption, answer unaffected.","work":"A die shows 1-6; 7 is impossible.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
