INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3ba9b3d-6fdf-4915-ac01-f19d07450265', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the sum is 7?', '["$\\frac{1}{6}$","$\\frac{1}{12}$","$\\frac{7}{36}$","$\\frac{1}{7}$"]', '$\frac{1}{6}$', NULL, 'There are 36 equally likely outcomes. The sums of 7 are (1,6), (2,5), (3,4), (4,3), (5,2), (6,1): 6 outcomes. $\frac{6}{36} = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6; 6/36 = 1/6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
