INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31280d04-a22e-4bf5-9e9f-2a2de26ee88c', 'NC26.M1.SDSR.1', 2, 'numeric', 'Probability from a sample space', 'A fair coin is flipped twice. What is the probability of getting exactly one head? Write your answer as a fraction.', '[]', '1/2', '1/2', 'The sample space is HH, HT, TH, TT. Exactly one head: HT and TH, which is 2 of 4. $\frac{2}{4} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HT, TH of HH, HT, TH, TT: 2/4 = 1/2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
