INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e73fa67c-90d1-4294-bb8e-ee029d82cb4a', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability from a sample space', 'A fair coin is flipped and a fair six-sided die is rolled. What is the probability of heads and an even number?', '["$\\frac{1}{2}$","$\\frac{1}{4}$","$\\frac{1}{12}$","$\\frac{1}{6}$"]', '$\frac{1}{4}$', NULL, 'The sample space has $2 \times 6 = 12$ outcomes. Heads with 2, 4 or 6 gives 3 outcomes. $\frac{3}{12} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Independent: 1/2 x 3/6 = 1/4 (3 of 12 outcomes).","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('042b8a7f-fb24-458b-a84b-44d05271224f', 'NC26.M1.SDSR.1', 2, 'numeric', 'Summarising raw data in a table', 'Twelve students voted for a class pet: dog, cat, dog, fish, cat, dog, dog, cat, fish, dog, cat, dog. When the votes are put in a table, how many more votes does dog have than cat?', '[]', '2', '6-4', 'Counting: dog 6, cat 4, fish 2 (total 12). Dog has $6 - 4 = 2$ more votes than cat.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dog at 1,3,6,7,10,12 = 6; cat at 2,5,8,11 = 4; fish 2 (sum 12). 6 - 4 = 2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
