INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2264e005-f803-4d52-8065-98532d6bf329', 'NC26.M1.SDSR.1', 2, 'choice', 'Summarising raw data in a table', 'Eight students gave their grade and whether they ride the bus: (9, yes), (10, no), (9, yes), (9, no), (10, yes), (10, no), (9, no), (10, no). Which summary is correct?', '["Grade 9: 3 yes, 1 no; Grade 10: 1 yes, 3 no","Grade 9: 2 yes, 2 no; Grade 10: 2 yes, 2 no","Grade 9: 2 yes, 2 no; Grade 10: 1 yes, 3 no","Grade 9: 2 yes, 2 no; Grade 10: 3 yes, 1 no"]', 'Grade 9: 2 yes, 2 no; Grade 10: 1 yes, 3 no', NULL, 'Grade 9 answers: yes, yes, no, no (2 yes, 2 no). Grade 10 answers: no, yes, no, no (1 yes, 3 no).', 'checked', '{"lint":[],"solve":{"answer":"Grade 9: 2 yes, 2 no; Grade 10: 1 yes, 3 no","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 9: yes, yes, no, no = 2 yes, 2 no. Grade 10: no, yes, no, no = 1 yes, 3 no.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34b25154-6c6f-468d-aeda-920ea94a3361', 'NC26.M1.SDSR.1', 2, 'choice', 'Reading and, or and not in words', 'Two coins are flipped. Event A is "at least one coin shows heads". Which describes the complement of A?', '["Both coins show heads","Exactly one coin shows tails","At least one coin shows tails","Both coins show tails"]', 'Both coins show tails', NULL, 'The complement of "at least one head" is "no heads", which means both coins show tails.', 'checked', '{"lint":[],"solve":{"answer":"Both coins show tails","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not at least one head = no heads = both tails.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30df1a23-9239-44b9-a97b-33fc6c95d37e', 'NC26.M1.SDSR.1', 2, 'numeric', 'Reading counts in a two-way table', 'Lunch choices by grade. Grade 6: 18 hot, 12 cold. Grade 7: 14 hot, 16 cold. Grade 8: 20 hot, 10 cold. How many more students chose hot lunch than cold lunch overall?', '[]', '14', '(18+14+20)-(12+16+10)', 'Hot: $18 + 14 + 20 = 52$. Cold: $12 + 16 + 10 = 38$. The difference is $52 - 38 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hot 18+14+20 = 52; cold 12+16+10 = 38; 52 - 38 = 14.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23267d92-2934-46a8-9593-67525d64e197', 'NC26.M1.SDSR.1', 2, 'numeric', 'Marginal probability from a two-way table', 'A table shows how 90 voters answered a question. Young voters: 15 said yes and 20 said no. Middle-aged voters: 25 said yes and 10 said no. Older voters: 12 said yes and 8 said no. One voter is chosen at random. What is the probability that the voter said yes? Write your answer as a fraction.', '[]', '26/45', '(15+25+12)/90', 'Yes answers: $15 + 25 + 12 = 52$ out of 90. $\frac{52}{90} = \frac{26}{45}$.', 'checked', '{"lint":[],"solve":{"answer":"26/45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Yes 15 + 25 + 12 = 52; total 35+35+20 = 90; 52/90 = 26/45.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8083bab7-3207-4940-ab8f-aeebb01615cf', 'NC26.M1.SDSR.1', 2, 'numeric', 'Finding a missing entry in a two-way table', 'In a class of 28 students, 15 are boys. In all, 12 students are in band, and 5 of them are boys. How many girls are NOT in band?', '[]', '6', '(28-15)-(12-5)', 'There are $28 - 15 = 13$ girls. Girls in band: $12 - 5 = 7$. So $13 - 7 = 6$ girls are not in band.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 13; girls in band 12 - 5 = 7; girls not in band 6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed4bbdcd-2c76-4795-b221-b37bbab6a5d3', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability from a sample space', 'A bag holds 4 red, 3 blue and 5 green marbles. One marble is drawn at random. What is the probability that it is red or blue?', '["$\\frac{7}{12}$","$\\frac{5}{12}$","$\\frac{1}{12}$","$\\frac{1}{7}$"]', '$\frac{7}{12}$', NULL, 'Red or blue marbles: $4 + 3 = 7$ out of 12 in all, so $\frac{7}{12}$. They cannot be both, so the counts just add.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 3 = 7 of 12; 7/12.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e408fcd7-dd99-4588-b837-5d84f79d162e', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability of a complement (not)', 'In a game, the probability of winning is $\frac{3}{8}$ and the probability of tying is $\frac{1}{4}$. A player either wins, ties or loses. What is the probability of losing?', '["$\\frac{5}{8}$","$\\frac{3}{8}$","$\\frac{1}{8}$","$\\frac{1}{4}$"]', '$\frac{3}{8}$', NULL, 'Winning or tying: $\frac{3}{8} + \frac{2}{8} = \frac{5}{8}$. Losing is the rest: $1 - \frac{5}{8} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 3/8 - 2/8 = 3/8.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('122ce948-55ab-4c6b-bee8-aebb8349db15', 'NC26.M1.SDSR.1', 3, 'numeric', 'Intersection from a union and a complement', 'Of 50 students, 30 play soccer, 25 play basketball, and 8 play neither sport. How many students play both?', '[]', '13', '30+25-(50-8)', 'The students who play at least one sport number $50 - 8 = 42$. Adding the soccer and basketball players gives $30 + 25 = 55$, which counts the students who play both twice. So the number who play both is $55 - 42 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least one sport = 50 - 8 = 42. Both = 30 + 25 - 42 = 13. (Soccer only 17, basketball only 12, both 13, neither 8: total 50.)","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36cb5abc-e219-488e-bd2e-230706ed65b4', 'NC26.M1.SDSR.1', 3, 'numeric', 'Using a two-way table with several given totals', 'Of 100 students, 60 are in grade 9 and the rest are in grade 10. In all, 45 of the students ride the bus, and 28 of the grade 9 students ride the bus. One student is chosen at random. What is the probability that the student is in grade 10 and does not ride the bus? Write your answer as a fraction.', '[]', '23/100', '(100-60-(45-28))/100', 'Grade 10 students: $100 - 60 = 40$. Grade 10 students who ride the bus: $45 - 28 = 17$. Grade 10 students who do not ride the bus: $40 - 17 = 23$. The probability is $\frac{23}{100}$.', 'checked', '{"lint":[],"solve":{"answer":"23/100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 10 = 100 - 60 = 40. Grade 10 bus riders = 45 - 28 = 17. Grade 10 not on bus = 40 - 17 = 23. P = 23/100.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07680225-0d4d-477c-a007-c118f4ec95e8', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the sum of the two numbers is NOT 8? Write your answer as a fraction.', '[]', '31/36', '1-5/36', 'There are $6 \times 6 = 36$ equally likely outcomes. The sum is 8 for $(2,6)$, $(3,5)$, $(4,4)$, $(5,3)$ and $(6,2)$: 5 outcomes. So $P(\text{sum is } 8) = \frac{5}{36}$ and $P(\text{not } 8) = 1 - \frac{5}{36} = \frac{31}{36}$.', 'checked', '{"lint":[],"solve":{"answer":"31/36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 equally likely outcomes. Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2) = 5. P(not 8) = 1 - 5/36 = 31/36.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('101dbea6-dcbf-4bd6-b8f8-0abc0f65d5e1', 'NC26.M1.SDSR.1', 3, 'numeric', 'Finding a missing entry in a two-way table', 'A club has 120 members, and 70 are girls. In all, 45 members play an instrument, and 30 of the boys do NOT play one. How many girls play an instrument?', '[]', '25', '45-(120-70-30)', 'Boys: $120 - 70 = 50$. Boys who play: $50 - 30 = 20$. Girls who play: $45 - 20 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 50; boys playing 50 - 30 = 20; girls playing 45 - 20 = 25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8a11633-8a6d-40e5-9648-ab1f56ce291d', 'NC26.M1.SDSR.1', 3, 'numeric', 'Finding a missing entry in a two-way table', 'Of 100 people asked a question, 60 are adults. In all, 55 people said yes, and 40 of the adults said yes. How many children said no?', '[]', '25', '(100-60)-(55-40)', 'Children: $100 - 60 = 40$. Children who said yes: $55 - 40 = 15$. Children who said no: $40 - 15 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Children 40; children yes 55 - 40 = 15; children no 25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
