INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2859fa89-5b30-4c89-b6de-7a07e6ff8f68', 'NC26.M1.SDSR.1', 3, 'choice', 'Finding a missing entry in a two-way table', 'Of 150 students, 90 ride the bus and 60 are in grade 9. The rest are in grade 10. Of the grade 9 students, 25 ride the bus. How many grade 10 students do NOT ride the bus?', '["35","65","25","90"]', '25', '(150-60)-(90-25)', 'Grade 10 has $150 - 60 = 90$ students. Grade 10 bus riders: $90 - 25 = 65$. So $90 - 65 = 25$ grade 10 students do not ride. (35 is the grade 9 students who do not ride; 65 is the grade 10 riders.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 10: 90; grade 10 bus 90 - 25 = 65; not bus 90 - 65 = 25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebf817bf-8dc5-4d2f-a720-f5a4fb554ce2', 'NC26.M1.SDSR.1', 3, 'numeric', 'Joint probability from a two-way table', 'In a survey of 120 people, 48 are women. Of the women, 30 prefer tea, and 24 of the men prefer tea. Everyone else prefers coffee. One person is chosen at random. What is the probability that the person is a man who prefers coffee? Write your answer as a fraction.', '[]', '2/5', '48/120', 'Men: $120 - 48 = 72$. Men who prefer coffee: $72 - 24 = 48$. The probability is $\frac{48}{120} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Men 72; men tea 24; men coffee 48; 48/120 = 2/5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aef0d24-63ad-4235-83b8-7cfd1b5bad45', 'NC26.M1.SDSR.1', 3, 'choice', 'Joint probability from a two-way table', 'Of 80 students, 50 are in band. In all, 36 of the 80 are girls, and 20 of the girls are in band. One student is chosen at random. What is the probability that the student is a boy in band?', '["$\\frac{5}{8}$","$\\frac{1}{4}$","$\\frac{9}{20}$","$\\frac{3}{8}$"]', '$\frac{3}{8}$', NULL, 'Boys in band: $50 - 20 = 30$. The probability is $\frac{30}{80} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys in band 50 - 20 = 30; 30/80 = 3/8.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c637980c-b866-46a2-a97f-8794e5fa0870', 'NC26.M1.SDSR.1', 3, 'choice', 'Joint probability from a two-way table', 'Of 120 shoppers, 70 are women. Of the women, 30 carry a bag, and 18 of the men carry a bag. One shopper is chosen at random. What is the probability that the shopper is a man who does NOT carry a bag?', '["$\\frac{4}{15}$","$\\frac{16}{25}$","$\\frac{3}{20}$","$\\frac{16}{35}$"]', '$\frac{4}{15}$', NULL, 'Men: $120 - 70 = 50$. Men without a bag: $50 - 18 = 32$. The probability is $\frac{32}{120} = \frac{4}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{15}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Men 50; men with bag 18; without 32; 32/120 = 4/15.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c57fed3-ceca-4d67-9109-a3a211bb603c', 'NC26.M1.SDSR.1', 3, 'numeric', 'Marginal probability from a two-way table', 'A table of probabilities for a student''s sex and how they get to school has these entries. P(girl and bus) = $\frac{3}{10}$, P(girl and walk) = $\frac{1}{5}$ and P(boy and bus) = $\frac{1}{4}$. Every student is a boy or a girl and either rides the bus or walks. What is the probability that a student walks? Write your answer as a fraction.', '[]', '9/20', '1/5+(1-3/10-1/5-1/4)', 'All four entries add to 1, so P(boy and walk) $= 1 - \frac{6}{20} - \frac{4}{20} - \frac{5}{20} = \frac{5}{20}$. Walkers: girls $\frac{4}{20}$ plus boys $\frac{5}{20}$ is $\frac{9}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(boy and walk) = 1 - (6+4+5)/20 = 5/20 = 1/4. P(walk) = 1/5 + 1/4 = 9/20.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ecbe99eb-8e16-473e-a2e2-55a4fe780edc', 'NC26.M1.SDSR.1', 3, 'choice', 'Marginal probability from a two-way table', 'A table of probabilities for a student''s sex and travel gives P(girl and bus) = 0.18, P(boy and bus) = 0.22, P(girl and walk) = 0.30 and P(boy and walk) = 0.30. Which statement is true?', '["The probability that a student is a girl is 0.18","The probability that a student takes the bus is 0.40","The probability that a student walks is 0.30","The probability that a student is a boy is 0.22"]', 'The probability that a student takes the bus is 0.40', NULL, 'Bus riders: $0.18 + 0.22 = 0.40$. Girls: $0.18 + 0.30 = 0.48$. Walkers: $0.30 + 0.30 = 0.60$. Boys: $0.22 + 0.30 = 0.52$.', 'checked', '{"lint":[],"solve":{"answer":"The probability that a student takes the bus is 0.40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walk 0.60, bus 0.40, girl 0.48, boy 0.52. Only bus = 0.40 is true.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd7cf338-a179-4600-827a-f388e91a722d', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability of a complement (not)', 'A bag has red, blue, green and yellow marbles. The probability of drawing a red marble is $\frac{1}{3}$ and of drawing a blue marble is $\frac{2}{5}$. What is the probability of drawing a marble that is neither red nor blue? Write your answer as a fraction.', '[]', '4/15', '1-1/3-2/5', 'Red or blue: $\frac{5}{15} + \frac{6}{15} = \frac{11}{15}$ (a marble cannot be both). Neither: $1 - \frac{11}{15} = \frac{4}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"4/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 1/3 - 2/5 = 1 - 11/15 = 4/15.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2145babc-dd73-45bd-9173-912bd15c2a44', 'NC26.M1.SDSR.1', 3, 'choice', 'Probability of a complement (not)', 'In a class of 36 students, 9 play chess, 15 play checkers and 4 play both. One student is chosen at random. What is the probability that the student plays neither game?', '["$\\frac{5}{9}$","$\\frac{1}{3}$","$\\frac{4}{9}$","$\\frac{1}{9}$"]', '$\frac{4}{9}$', NULL, 'Students playing at least one game: $9 + 15 - 4 = 20$. Neither: $36 - 20 = 16$. $\frac{16}{36} = \frac{4}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Union 9 + 15 - 4 = 20; neither 16; 16/36 = 4/9.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('810e18cc-9b85-4a39-a261-f15c79650512', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability of a complement (not)', 'The probability that a student in a school is NOT in the band is $\frac{5}{8}$. There are 24 students in the band. How many students are in the school?', '[]', '64', '24/(1-5/8)', 'The band is $1 - \frac{5}{8} = \frac{3}{8}$ of the school. So $\frac{3}{8}$ of the students is 24, and the school has $24 \div \frac{3}{8} = 64$ students.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(band) = 3/8; 24 / (3/8) = 64.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bb552e0-0731-479a-b2f2-9d7714d193bd', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability of a union (or)', 'Of 80 students, 35 take art, 28 take music and 10 take both. One student is chosen at random. What is the probability that the student takes art or music? Write your answer as a fraction.', '[]', '53/80', '(35+28-10)/80', 'Art or music: $35 + 28 - 10 = 53$ students out of 80, so $\frac{53}{80}$.', 'checked', '{"lint":[],"solve":{"answer":"53/80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35 + 28 - 10 = 53; 53/80.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('674ee37e-e780-43cf-99a2-4b33c3de6089', 'NC26.M1.SDSR.1', 3, 'choice', 'Probability of a union (or)', 'For two events, P(A) = $\frac{3}{8}$, P(B) = $\frac{1}{2}$ and P(A and B) = $\frac{1}{8}$. What is P(A or B)?', '["$\\frac{7}{8}$","$\\frac{5}{8}$","$\\frac{1}{2}$","$\\frac{3}{4}$"]', '$\frac{3}{4}$', NULL, 'P(A or B) = P(A) + P(B) - P(A and B) = $\frac{3}{8} + \frac{4}{8} - \frac{1}{8} = \frac{6}{8} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 + 4/8 - 1/8 = 6/8 = 3/4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8bd7ae7-8734-4717-ab0f-bb2781fb1b27', 'NC26.M1.SDSR.1', 3, 'choice', 'Probability of a union (or)', 'In a survey of 50 students, 30 are boys, 22 walk to school, and 12 are boys who walk. Which expression gives the probability that a student chosen at random is a boy or walks?', '["$\\frac{30 + 22 - 12}{50}$","$\\frac{30 + 22}{50}$","$\\frac{12}{50}$","$\\frac{30 + 22 + 12}{50}$"]', '$\frac{30 + 22 - 12}{50}$', NULL, 'Boys plus walkers counts the 12 boys who walk twice, so subtract them once: $\frac{30 + 22 - 12}{50} = \frac{40}{50}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{30 + 22 - 12}{50}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Addition rule: (30 + 22 - 12)/50.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99de0ca6-1aae-4bf4-92d0-ad13e1b188fb', 'NC26.M1.SDSR.1', 3, 'numeric', 'Counting both, either and neither', 'In a town survey of 40 people, 18 read novels, 22 read the news, and 6 read neither. How many read both novels and the news?', '[]', '6', '18+22-(40-6)', 'People reading at least one: $40 - 6 = 34$. Adding the two groups gives $18 + 22 = 40$, which is 6 too many, so 6 read both.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least one: 40 - 6 = 34; both = 18 + 22 - 34 = 6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458bb2c1-41d6-4725-83a7-7d9b61ccb6f0', 'NC26.M1.SDSR.1', 3, 'choice', 'Counting both, either and neither', 'In a school, 15 students are in chess club, 12 are in drama club, and 5 are in both. How many students are in exactly one of the two clubs?', '["22","17","27","12"]', '17', '(15-5)+(12-5)', 'Chess only: $15 - 5 = 10$. Drama only: $12 - 5 = 7$. Exactly one club: $10 + 7 = 17$. (22 is the number in at least one club.)', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Chess only 10, drama only 7; 17.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('691579cd-3894-452a-a41c-b68dc9234df3', 'NC26.M1.SDSR.1', 3, 'numeric', 'Listing a sample space and counting outcomes', 'A fair coin is flipped three times. How many of the outcomes have at least two heads?', '[]', '4', '4', 'The outcomes with at least two heads are HHH, HHT, HTH and THH: 4 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HHT, HTH, THH, HHH = 4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
