INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7630054-c722-4bc7-8586-1a4fc8ea8638', 'NC26.M1.SDSR.1', 3, 'choice', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the sum is 5 or 6?', '["$\\frac{11}{36}$","$\\frac{1}{9}$","$\\frac{5}{36}$","$\\frac{1}{4}$"]', '$\frac{1}{4}$', NULL, 'Sum 5: (1,4), (2,3), (3,2), (4,1) is 4 outcomes. Sum 6: (1,5), (2,4), (3,3), (4,2), (5,1) is 5 outcomes. Total 9 of 36: $\frac{9}{36} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 5: 4 ways; sum 6: 5 ways; 9/36 = 1/4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8901c4a7-e184-4ba1-b388-b1d7e5e0c34d', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the two numbers are different? Write your answer as a fraction.', '[]', '5/6', '5/6', 'Matching numbers: (1,1), (2,2), ..., (6,6) is 6 outcomes out of 36. Different: $36 - 6 = 30$, so $\frac{30}{36} = \frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubles 6 of 36; different 30/36 = 5/6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aafec09-365e-4eb2-8ae4-53e881075b66', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'A card is drawn at random from cards numbered 1 to 20. What is the probability that the number is a multiple of 3 or a multiple of 5? Write your answer as a fraction.', '[]', '9/20', '(6+4-1)/20', 'Multiples of 3: 3, 6, 9, 12, 15, 18 (6 of them). Multiples of 5: 5, 10, 15, 20 (4 of them). 15 is in both, so together there are $6 + 4 - 1 = 9$. The probability is $\frac{9}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 3: 6; of 5: 4; of 15: 1; 6 + 4 - 1 = 9; 9/20.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2386174b-d6b6-4ee1-85ab-2481eb542c20', 'NC26.M1.SDSR.1', 3, 'choice', 'Probability from a sample space', 'A fair coin is flipped three times. What is the probability of getting exactly two heads?', '["$\\frac{3}{8}$","$\\frac{1}{4}$","$\\frac{1}{8}$","$\\frac{1}{2}$"]', '$\frac{3}{8}$', NULL, 'There are 8 equally likely outcomes. Exactly two heads: HHT, HTH, THH, which is 3. $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HHT, HTH, THH: 3/8.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
