INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed81e3a2-c384-4f74-af44-5de7785b2edc', 'NC26.M1.SDSR.1', 3, 'numeric', 'Summarising raw data in a table', 'Ten students gave their grade and whether they own a pet: (9, yes), (10, yes), (9, no), (10, no), (9, yes), (9, no), (10, yes), (10, yes), (9, yes), (10, no). One of the ten is chosen at random. What is the probability that the student is in grade 9 and owns a pet? Write your answer as a fraction.', '[]', '3/10', '3/10', 'Grade 9 with a pet: the 1st, 5th and 9th answers, which is 3 of the 10 students. $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9, yes) at positions 1, 5, 9 = 3; 3/10.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('171d9ae6-70b9-4e63-8504-dd9d70c444bf', 'NC26.M1.SDSR.1', 3, 'choice', 'Summarising raw data in a table', 'Twelve students gave their sex and favorite subject (G = girl, B = boy; M = math, S = science): GM, BS, GS, GM, BM, BS, GM, GS, BM, BS, GM, BM. One student is chosen at random. What is the probability that the student is a boy or chose math?', '["$\\frac{7}{12}$","$\\frac{5}{6}$","$\\frac{1}{2}$","$\\frac{3}{4}$"]', '$\frac{5}{6}$', NULL, 'Boys: BS, BS, BM, BM, BS, BM is 6. Math: GM ×4 and BM ×3 is 7. Boys who chose math: 3. Boy or math: $6 + 7 - 3 = 10$ of 12, so $\frac{10}{12} = \frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys: BS,BM,BS,BM,BS,BM = 6; girls with math: GM x4 = 4; union 10/12 = 5/6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5348e733-da77-4df0-83cd-a77d6896f42e', 'NC26.M1.SDSR.1', 3, 'choice', 'Reading and, or and not in words', 'Event A is "a student plays soccer" and event B is "a student plays tennis". Which phrase describes "not (A or B)"?', '["A student who does not play soccer or does not play tennis","A student who plays soccer but does not play tennis","A student who plays neither soccer nor tennis","A student who plays at least one of the two sports"]', 'A student who plays neither soccer nor tennis', NULL, '"A or B" means soccer, tennis or both. Its complement is everyone who plays neither sport.', 'checked', '{"lint":[],"solve":{"answer":"A student who plays neither soccer nor tennis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"not (A or B) = neither (De Morgan).","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e573aa7e-9018-4e5a-a2d1-fc2da7426673', 'NC26.M1.SDSR.1', 3, 'numeric', 'Row and column totals of a two-way table', 'A survey sorted students by sex and favorite pet (cat or dog). The boys'' total was 27. Of the students who chose cats, 16 were boys and 14 were girls. In all, 11 girls chose dogs. How many students were surveyed?', '[]', '52', '27+14+11', 'Boys who chose dogs: $27 - 16 = 11$. Girls: $14 + 11 = 25$. Everyone surveyed: $27 + 25 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys dogs 27 - 16 = 11; girls 14 + 11 = 25; total 27 + 25 = 52.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
