INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32b9dd72-e748-48d0-9d2d-893f82f76d77', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'Pat wants to see whether the age of a car affects its resale price. Which two columns of data does Pat need?', '["Car color and resale price","Age of the car and number of doors","Age of the car and resale price","Number of doors and color of the car"]', 'Age of the car and resale price', NULL, 'To study the effect of age on price, Pat needs the age column and the price column.', 'checked', '{"lint":[],"solve":{"answer":"Age of the car and resale price","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need the explanatory variable (age) and response (resale price).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
