INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d36ba31b-d4b7-4285-918f-79b3dcd1a92d', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'Dev wants to know whether the distance a student lives from school affects the time the trip takes. Which variable is NOT needed?', '["The distance from the student''s home to the school","The number of minutes that the trip takes","How the student travels (bus, bike or walking)","The student''s favorite school subject"]', 'The student''s favorite school subject', NULL, 'Distance and trip time are the two variables in the question, and the way of traveling may matter too. A favorite subject has nothing to do with trip time.', 'checked', '{"lint":[],"solve":{"answer":"The student''s favorite school subject","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft: strictly, travel mode is also not needed for the two-variable question as asked, though it is clearly relevant. Intended answer is still clear.","work":"Distance and trip time are essential; travel mode is a relevant third variable; favorite subject is irrelevant.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
