INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7b1f9a5-dcec-47c5-ab17-4da986a66a91', 'NC26.M1.SDSR.3', 1, 'choice', 'Splitting data by a third variable', 'Test scores and hours studied are recorded for ninth and tenth graders mixed together. Dani wants to see whether the pattern differs by grade. What should she do?', '["Delete the tenth graders'' scores","Plot each grade separately and compare","Add each student''s hours and score together","Average the two grades into one number"]', 'Plot each grade separately and compare', NULL, 'Splitting the data by the third variable, grade, lets her compare the two patterns.', 'checked', '{"lint":[],"solve":{"answer":"Plot each grade separately and compare","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To see if the pattern differs by grade, split by grade and plot each separately.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2968685-9537-4207-ba70-ce1b38cb752d', 'NC26.M1.SDSR.3', 1, 'choice', 'Splitting data by a third variable', 'Dani sorts the rows of a dataset into two piles: students who ride the bus to school and students who do not. Which variable did she split the data by?', '["The student''s test score","The student''s grade level","How the student travels","The student''s height"]', 'How the student travels', NULL, 'The two piles are made by how students get to school, so that is the splitting variable.', 'checked', '{"lint":[],"solve":{"answer":"How the student travels","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus vs not bus is a split by mode of travel.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bdf88f5-356b-4033-a597-d749e0eb72a5', 'NC26.M1.SDSR.3', 1, 'numeric', 'Using a third variable to improve a model', 'In the morning class, the line that predicts a test score is $y = 4x + 50$, where $x$ is the hours studied. What score does the line predict for a student who studied 5 hours?', '[]', '70', '4*5+50', 'Put $x = 5$ into the line: $y = 4(5) + 50 = 70$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*5 + 50 = 70.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc929d8e-ecba-4d18-b18d-fe0271b956b3', 'NC26.M1.SDSR.3', 1, 'choice', 'Using a third variable to improve a model', 'A single line fits all the data points badly. Which step uses a third variable to improve the model?', '["Remove the third variable from the data","Draw a longer line through the same points","Fit a separate line for each group","Round all values"]', 'Fit a separate line for each group', NULL, 'Splitting the points by the third variable and fitting a line to each group can follow each group''s pattern.', 'checked', '{"lint":[],"solve":{"answer":"Fit a separate line for each group","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Using a grouping variable to fit separate lines per group improves the model.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77938cfe-9429-4e22-8c3b-60cb9eb9e173', 'NC26.M1.SDSR.3', 1, 'choice', 'Using a third variable to improve a model', 'Two groups each have their own line. Group 1: $y = 5x + 3$. Group 2: $y = 5x + 3$. What does this tell you about splitting the data by group?', '["The two groups must both have been measured wrongly by someone","Splitting helps a lot, because there are now two separate lines","The slope of each of these two lines has to be exactly zero","Splitting does not help, since both groups share one line"]', 'Splitting does not help, since both groups share one line', NULL, 'Both groups have the same equation, so one line describes them equally well.', 'checked', '{"lint":[],"solve":{"answer":"Splitting does not help, since both groups share one line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Identical lines: the grouping variable makes no difference, so splitting does not help.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd86c615-ab72-4ff9-8190-3dbb194e90b1', 'NC26.M1.SDSR.3', 1, 'numeric', 'Using a third variable to improve a model', 'For practice hours $x$, the line for juniors is $y = 3x + 20$ and the line for seniors is $y = 3x + 30$. When $x = 10$, how many points higher is the seniors'' prediction than the juniors'' prediction?', '[]', '10', '(3*10+30)-(3*10+20)', 'Juniors: 3(10) + 20 = 50. Seniors: 3(10) + 30 = 60. The difference is 10 points.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Juniors 50, seniors 60; difference 10 (intercept difference).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65bcc70e-ee68-4473-9d23-a497718d0c05', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'Fires attended by more firefighters tend to cause more damage. Which third variable best explains this?', '["The age of the firefighters","The name of the fire station","The color of the fire trucks","The size of the fire"]', 'The size of the fire', NULL, 'A big fire both needs many firefighters and causes much damage. The firefighters are not causing the damage.', 'checked', '{"lint":[],"solve":{"answer":"The size of the fire","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bigger fires draw more firefighters and cause more damage.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1d627d2-8596-4fb6-bda1-c6de1d2d6003', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'A variable that is not one of the two being compared but affects both of them is often called what?', '["A prediction residual","A lurking variable","An outlier point","A random sample"]', 'A lurking variable', NULL, 'A hidden variable that influences both quantities being compared is called a lurking (or confounding) variable.', 'checked', '{"lint":[],"solve":{"answer":"A lurking variable","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition of a lurking (confounding) variable.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7686124-80ff-432f-9ce6-2b2bec8e82df', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'Which relationship is most likely explained by a third variable, rather than one quantity directly changing the other?', '["Number of sheets in a stack of paper and the height of the stack","Number of tickets bought and the total cost of those tickets","Daily ice cream sales and daily numbers of people swimming","Miles driven and gallons of gas used on one trip"]', 'Daily ice cream sales and daily numbers of people swimming', NULL, 'Hot weather raises both ice cream sales and swimming. In the other pairs, one quantity directly changes the other.', 'checked', '{"lint":[],"solve":{"answer":"Daily ice cream sales and daily numbers of people swimming","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ice cream sales and swimming are both driven by hot weather; the others are direct relationships.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('645051bb-05b3-4681-a2c8-4ba9a807cb53', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'Cities with more libraries also have more crime. Which third variable most likely explains this?', '["The names of the mayors of those cities","The colors of the library buildings","The number of books on each library shelf","The number of people in the city"]', 'The number of people in the city', NULL, 'Larger cities tend to have both more libraries and more crime, simply because more people live there.', 'checked', '{"lint":[],"solve":{"answer":"The number of people in the city","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population size drives both library count and crime count.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09656532-e854-4008-b3db-9a23b21bd84c', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'Towns where more bicycle helmets are sold also report more bicycle injuries. Which third variable most likely affects both of these?', '["The brand name printed on the helmets","The average price of one helmet","The number of people who ride bikes","The color most helmets are painted"]', 'The number of people who ride bikes', NULL, 'A town with more bike riders sells more helmets and also has more injuries, so the number of riders affects both. The brand, the price and the color of helmets do not explain why injuries would rise along with sales.', 'checked', '{"lint":[],"solve":{"answer":"The number of people who ride bikes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More riders means more helmets bought and more injuries; the number of riders drives both. Color, brand and price do not plausibly drive injuries.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1989b525-c13e-40d9-8d8a-2ced6c140f04', 'NC26.M1.SDSR.3', 1, 'numeric', 'Splitting data by a third variable', 'A survey of 90 students records each student''s grade and whether the student owns a bike. There are 60 ninth graders and 30 tenth graders. In all, 51 of the 90 students own a bike, and 39 of them are ninth graders. What percent of the tenth graders own a bike?', '[]', '40', '(51-39)/30*100', 'Split the students by grade. Bike owners who are tenth graders: 51 - 39 = 12. There are 30 tenth graders, so 12 / 30 = 0.4, which is 40 percent.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bike owners 51, of whom 39 are ninth graders, so 51 - 39 = 12 tenth graders own a bike. 12/30 = 0.4 = 40%.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d84e6cb-be56-482d-aa18-07aa1b17e8cb', 'NC26.M1.SDSR.3', 1, 'choice', 'Using a third variable to improve a model', 'A scatter plot shows plant height against days of growth. Plants grown in sun are drawn as blue dots and plants grown in shade as red dots. What does the color of a dot show?', '["The light the plant grew in","The number of days it has grown","The height the plant has reached","The amount of water it received"]', 'The light the plant grew in', NULL, 'Height and days of growth are already shown by where the dot sits. The color adds a third variable, the kind of light (sun or shade), so a separate pattern can be seen for each group.', 'checked', '{"lint":[],"solve":{"answer":"The light the plant grew in","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = sun, red = shade, so color encodes the light condition (the third variable). Height and days are the axes; water is not shown.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb355f45-d1d6-44e9-8822-7b866973498c', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging a source''s credibility', 'A company says its Study Plus app raises grades, and it shows a chart as proof. Which question would best help you decide whether to believe the claim?', '["What colors does the app''s logo use?","Who chose the students in the data?","How many people have downloaded the app?","Does the app cost money to download?"]', 'Who chose the students in the data?', NULL, 'Whether a claim can be trusted depends on how the data were collected. If the company picked only its best students, the chart is misleading. The logo, the number of downloads and the cost say nothing about whether the grades really improved.', 'checked', '{"lint":[],"solve":{"answer":"Who chose the students in the data?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Credibility of the evidence depends on how the sample was chosen (selection bias). Logo colors, price and download counts do not test whether the chart supports the claim.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c14c0e46-5b88-4872-a2a8-53d7ecdb3436', 'NC26.M1.SDSR.3', 1, 'numeric', 'Using a third variable to improve a model', 'Basketball players are split by a third variable, position. For guards, the line that predicts free throws made in a drill is $f = 4w + 10$, and for centers it is $f = 2w + 10$, where $w$ is the number of weeks of practice. After 6 weeks, how many more free throws does the line predict for a guard than for a center?', '[]', '12', '(4*6+10)-(2*6+10)', 'Guard at 6 weeks: $4(6) + 10 = 34$. Center at 6 weeks: $2(6) + 10 = 22$. The difference is 34 - 22 = 12 free throws.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft spot: mostly tests evaluating two linear models; the third-variable idea is only framing.","work":"Guard: 4(6)+10 = 34. Center: 2(6)+10 = 22. Difference 34 - 22 = 12.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7a955e5-e142-4409-b5e5-d5a1a936580b', 'NC26.M1.SDSR.3', 1, 'choice', 'Choose the variables that answer a question', 'Sara wants to know whether students who sleep more tend to score higher on quizzes. For each classmate she records hours of sleep, quiz score, shoe size and favorite color. Which two variables should she compare?', '["Shoe size and favorite color","Hours of sleep and shoe size","Hours of sleep and quiz score","Quiz score and favorite color"]', 'Hours of sleep and quiz score', NULL, 'Her question is about sleep and quiz scores, so those are the two variables that matter. Shoe size and favorite color have nothing to do with her question, so pairs that include them would not help her answer it.', 'checked', '{"lint":[],"solve":{"answer":"Hours of sleep and quiz score","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question is whether more sleep goes with higher quiz scores, so the relevant variables are hours of sleep (explanatory) and quiz score (response). Shoe size and favorite color are irrelevant.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a350ad5-53fb-47e1-a115-284540ae210e', 'NC26.M1.SDSR.3', 2, 'choice', 'Recognizing a third variable', 'A dataset shows that students who own more books tend to have higher reading scores. A researcher thinks a student''s age may affect both the number of books and the reading score. In this situation, how is age best described?', '["The only cause of the higher reading scores","A variable that can be ignored because it was not in the question","A third variable that may influence both of the others","A sign that the data were collected incorrectly"]', 'A third variable that may influence both of the others', NULL, 'Older students may own more books and also read better. Age is then a third variable related to both, and it can help explain the pattern. It should not be ignored, and it does not mean the data are wrong.', 'checked', '{"lint":[],"solve":{"answer":"A third variable that may influence both of the others","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Age may influence both books owned and reading score: a third (lurking/confounding) variable.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbdd4900-8367-4774-adad-30e3c911dfd6', 'NC26.M1.SDSR.3', 2, 'numeric', 'Comparing two groups', 'Of 50 students who used a study app, 35 passed the test. Of 50 students who did not use the app, 30 passed. How many percentage points higher is the pass percent of the app group than the pass percent of the other group?', '[]', '10', '35/50*100-30/50*100', 'App group: $\frac{35}{50} = 70$ percent. Other group: $\frac{30}{50} = 60$ percent. The difference is $70 - 60 = 10$ percentage points.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"App group 35/50 = 70 percent; other group 30/50 = 60 percent. Difference = 10 percentage points.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8342c786-05d0-4aff-a77c-e83345d05ad9', 'NC26.M1.SDSR.3', 2, 'choice', 'Doubting a claim about data', 'A website says, "Our vitamin drink raises math scores by 30 percent!" Which detail would make you the MOST doubtful of the claim?', '["The website sells the drink and does not say how scores were measured","The study included a comparison group that did not drink it","The study reports how many students took part","The data were collected by an outside research team"]', 'The website sells the drink and does not say how scores were measured', NULL, 'A seller with something to gain, and no information on how the scores were measured, is a reason to doubt. A comparison group, a stated number of students and independent researchers all make a claim more credible.', 'checked', '{"lint":[],"solve":{"answer":"The website sells the drink and does not say how scores were measured","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A seller with an interest in the result who gives no measurement method is the most reason for doubt; the other details make the claim more credible.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34af72f0-0b09-45c8-8e0e-e103652c9153', 'NC26.M1.SDSR.3', 2, 'choice', 'Judging the credibility of a data source', 'A tutoring company''s ad shows the quiz scores of its five best students and says, "Our students improve fast!" What is the main problem with this data?', '["It shows only the best results, not a typical group of students","Quiz scores cannot be used to measure learning at all","Showing five students gives too much data to understand","The company should have shown even fewer students"]', 'It shows only the best results, not a typical group of students', NULL, 'Choosing only the top students hides the rest. A fair claim needs results from a typical or random group.', 'checked', '{"lint":[],"solve":{"answer":"It shows only the best results, not a typical group of students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cherry-picked best five students are not typical.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('857b55fe-d6de-4053-9627-32a0e92b42c7', 'NC26.M1.SDSR.3', 2, 'choice', 'Judging the credibility of a data source', 'Two sources give the population of a town. Source 1 is a national census that counted every household two years ago. Source 2 is an undated blog post that gives a different number and no explanation. Which should you use, and why?', '["Source 2, because a blog post is bound to be newer than a national census","Source 1, because its method is clear and it comes from a full count","Source 2, because a different number shows more careful work","Source 1, because official sources are always exactly right"]', 'Source 1, because its method is clear and it comes from a full count', NULL, 'Source 1 explains how the number was found and is dated. Source 2 has no date or explanation. Even official sources are not perfect, but this one is much more credible.', 'checked', '{"lint":[],"solve":{"answer":"Source 1, because its method is clear and it comes from a full count","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Census is a full count with a clear method; blog is undated and unexplained. ''Always exactly right'' overclaims.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8aac6a3-9f8c-4a2e-99ee-1cbf8c5a1f97', 'NC26.M1.SDSR.3', 2, 'choice', 'Judging the credibility of a data source', 'A graph in an advertisement has a vertical axis that starts at 96 instead of 0. The bars show 97 for last year and 99 for this year, and the second bar looks several times taller. What is the problem?', '["Bars should always be drawn in order from tallest to shortest","Values of 97 and 99 are too close together to be graphed at all","Starting the axis at 96 makes a small change look very large","A vertical axis must always count up by tens or hundreds"]', 'Starting the axis at 96 makes a small change look very large', NULL, 'Because the axis does not start at 0, the difference of 2 looks huge. A misleading scale is a reason to doubt how data are presented.', 'checked', '{"lint":[],"solve":{"answer":"Starting the axis at 96 makes a small change look very large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Truncated axis: 97 vs 99 drawn as 1 vs 3 units above 96, exaggerating a small change.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c5b0522-20f2-4744-96eb-4cdee6af71c9', 'NC26.M1.SDSR.3', 2, 'numeric', 'Judging the credibility of a data source', 'A poll reports that 54 percent of people favor a new park, with a margin of error of 3 percentage points. According to the poll, what is the lowest percent that the true value could reasonably be?', '[]', '51', '54-3', 'The true value is likely within 3 percentage points of 54 percent, so the lowest reasonable value is 54 - 3 = 51 percent.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 - 3 = 51.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2894fdd8-e833-4d8c-b476-88f1c1d78975', 'NC26.M1.SDSR.3', 2, 'choice', 'Judging the credibility of a data source', 'A study says a candy does not cause cavities. The candy''s maker paid for the study, and only the maker has seen the full data. Which question is the most useful to ask first?', '["Does the candy come in more than one flavor, shape or size?","Is the maker''s name printed clearly on the front of the report?","How many people at the company really enjoy eating this candy?","Can independent researchers check the data and methods?"]', 'Can independent researchers check the data and methods?', NULL, 'Because the maker paid for the study and holds the data, the key issue is whether others can check how the data were collected and analyzed.', 'checked', '{"lint":[],"solve":{"answer":"Can independent researchers check the data and methods?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Funding bias plus hidden data: first ask whether independent researchers can verify.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9205fdb7-1dbc-439d-886b-2fa05d8a7671', 'NC26.M1.SDSR.3', 2, 'choice', 'Choosing relevant variables', 'Ben wants to predict a student''s final exam score. His dataset has: homework average, shirt size, number of absences, locker number and hours of TV watched last year. Which pair of variables is the most reasonable to use?', '["Shirt size and locker number","Homework average and number of absences","Locker number and hours of TV watched last year","Shirt size and hours of TV watched"]', 'Homework average and number of absences', NULL, 'Homework average and absences relate to how the student is doing in the course. Shirt size and locker number have no reasonable link to an exam score.', 'checked', '{"lint":[],"solve":{"answer":"Homework average and number of absences","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Homework average and absences plausibly relate to exam score; shirt size, locker number irrelevant; last year''s TV weak.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb99abcf-fb79-45b4-9a9f-a6e8e7295980', 'NC26.M1.SDSR.3', 2, 'numeric', 'Choosing relevant variables', 'Rosa wants to study how study hours and sleep hours together relate to test score. Her table has these columns: study hours, sleep hours, test score, hair color and number of siblings. How many of the columns will she use?', '[]', '3', '1+1+1', 'She uses study hours, sleep hours and test score. Hair color and number of siblings are not part of her question. That is 3 columns.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Study hours, sleep hours, test score = 3 columns.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60af707f-b48d-48a7-a35a-c84e381d57c3', 'NC26.M1.SDSR.3', 2, 'choice', 'Choosing relevant variables', 'A dataset records each person''s height in inches and also in centimeters. Why is it not helpful to use both as predictors of weight?', '["Height cannot help predict a person''s weight in any situation","Centimeters are always less accurate than inches for people","They give the same information, so the second adds nothing","Two predictors that have units can never be used together"]', 'They give the same information, so the second adds nothing', NULL, 'Inches and centimeters are the same measurement in two units, so using both is redundant.', 'checked', '{"lint":[],"solve":{"answer":"They give the same information, so the second adds nothing","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inches and centimeters are the same measurement rescaled; redundant.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a794d9e-283b-4a14-9dc0-d3456eac048c', 'NC26.M1.SDSR.3', 2, 'choice', 'Choosing relevant variables', 'A school wants to predict, before the semester starts, whether a student will pass a course. Which variable could NOT be used for this?', '["The student''s grade in the previous math course","The student''s attendance last year","The student''s score on a placement quiz","The student''s final course grade"]', 'The student''s final course grade', NULL, 'The final grade is not known before the semester starts, so it cannot be used to predict the result.', 'checked', '{"lint":[],"solve":{"answer":"The student''s final course grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Final course grade is not known before the semester starts (and is essentially the outcome).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b9b2cd7-3b38-4710-9c32-71c3deb54bf5', 'NC26.M1.SDSR.3', 2, 'numeric', 'Choosing relevant variables', 'A dataset has 5 numeric variables. A student plans to make one scatter plot for every different pair of variables. How many scatter plots will she make?', '[]', '10', '5*4/2', 'Each variable can be paired with 4 others, which gives 5 x 4 = 20 ordered pairs. A plot of x against y shows the same pair as y against x, so divide by 2: 10 plots.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(5,2) = 10 pairs.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e64994b-fbe5-492b-9e37-30964c041dae', 'NC26.M1.SDSR.3', 2, 'choice', 'Evaluating a dataset for a question', 'To estimate how many hours a night teens in North Carolina sleep, a researcher surveys only the members of one school''s early-morning swim team. What is the main concern?', '["Sleep is much too hard to measure accurately for any teens","A swim team has far too many members for her to ever survey","The researcher should have surveyed adults instead of teens","The swim team may not be typical of teens in the state"]', 'The swim team may not be typical of teens in the state', NULL, 'The sample comes from one unusual group, so it may not represent all teens.', 'checked', '{"lint":[],"solve":{"answer":"The swim team may not be typical of teens in the state","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Early-morning swimmers are not representative of NC teens'' sleep.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('248018c6-5f79-413a-b761-0e7025ede13d', 'NC26.M1.SDSR.3', 2, 'numeric', 'Evaluating a dataset for a question', 'A dataset has 250 rows. The income is missing in 20 percent of the rows. How many rows have an income value?', '[]', '200', '250-250*20/100', '20 percent of 250 is 50 rows missing. 250 - 50 = 200 rows have an income.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20% of 250 = 50 missing; 250-50 = 200.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b4ed80a-079e-4ab3-9833-b1d8814ed67d', 'NC26.M1.SDSR.3', 2, 'choice', 'Evaluating a dataset for a question', 'Alex wants to know whether summers in his town are getting warmer. He has the daily highs for June, July and August from 1950 to 1960 only. What is wrong with using this data?', '["It stops in 1960, so it says nothing about recent summers","Summer temperatures cannot be compared across years","Daily highs are not related to the weather in any way","Ten years of data is always far too much data to examine"]', 'It stops in 1960, so it says nothing about recent summers', NULL, 'To tell whether summers are getting warmer now, he needs data from recent years as well.', 'checked', '{"lint":[],"solve":{"answer":"It stops in 1960, so it says nothing about recent summers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Data from 1950-1960 only cannot show a trend into the present.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1941ca27-1171-4878-97a8-a24ab6a0f37d', 'NC26.M1.SDSR.3', 2, 'numeric', 'Evaluating a dataset for a question', 'A dataset has 130 rows. There are 18 rows missing the weight and 7 rows missing the height, and no row is missing both. A student deletes every row that is missing a value. How many rows are left?', '[]', '105', '130-18-7', 'No row is counted twice, so 18 + 7 = 25 rows are deleted. 130 - 25 = 105 rows remain.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No overlap: 18+7 = 25 rows removed; 130-25 = 105.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f21d5196-2087-41a6-b578-f51c2b1d4b4f', 'NC26.M1.SDSR.3', 2, 'choice', 'Evaluating a dataset for a question', 'A table has the columns city, population and average monthly rent. Which question can these data help answer?', '["Do people in larger cities tend to have more free time?","Do cities with more people tend to have higher rents?","Which of the cities has the best public parks in it?","Do families with more children pay lower rents?"]', 'Do cities with more people tend to have higher rents?', NULL, 'Only the first question uses the variables in the table, population and rent.', 'checked', '{"lint":[],"solve":{"answer":"Do cities with more people tend to have higher rents?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only population and rent are available per city: question 2.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4365923-f62e-4df9-8b6e-933bb0b70200', 'NC26.M1.SDSR.3', 2, 'numeric', 'Splitting data by a third variable', 'Greenhouse 1 has 15 tomato plants with a mean height of 80 centimeters. Greenhouse 2 has 25 tomato plants with a mean height of 88 centimeters. What is the mean height of all 40 plants, in centimeters?', '[]', '85', '(15*80+25*88)/40', 'Total heights: 15 x 80 = 1,200 and 25 x 88 = 2,200, together 3,400. Divide by 40 plants: 85 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(15*80 + 25*88)/40 = (1200+2200)/40 = 3400/40 = 85.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf4c10ed-baee-46cb-b73a-cf1ad9d8dff1', 'NC26.M1.SDSR.3', 2, 'numeric', 'Splitting data by a third variable', 'Among 40 ninth graders, 28 passed a test. Among 60 tenth graders, 51 passed. By how many percentage points does the pass rate of the tenth graders exceed that of the ninth graders?', '[]', '15', '51/60*100-28/40*100', 'Ninth graders: 28 / 40 = 70 percent. Tenth graders: 51 / 60 = 85 percent. The difference is 85 - 70 = 15 percentage points.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28/40 = 70%; 51/60 = 85%; difference 15.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4fee7c9-41ec-479a-b4f5-ee864dd88ef7', 'NC26.M1.SDSR.3', 2, 'numeric', 'Splitting data by a third variable', 'In a dataset, the 12 boys have a mean score of 75 and the 18 girls have a mean score of 75. What is the mean score of all 30 students?', '[]', '75', '(12*75+18*75)/30', 'The total is 12 x 75 + 18 x 75 = 900 + 1,350 = 2,250. Divide by 30: 75. If both groups have the same mean, the combined mean is the same.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both groups mean 75, so combined mean 75.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1b9360f-3c00-4e1f-a3a6-fe545580c65a', 'NC26.M1.SDSR.3', 2, 'numeric', 'Splitting data by a third variable', 'A shop surveyed 200 customers: 120 adults and 80 teens. Thirty percent of the adults and 60 percent of the teens bought a pass. How many of the 200 customers bought a pass?', '[]', '84', '120*30/100+80*60/100', 'Adults: 30 percent of 120 is 36. Teens: 60 percent of 80 is 48. Together 36 + 48 = 84 customers.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.30*120 = 36; 0.60*80 = 48; total 84.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9ba8ba3-aa5b-454c-bc3e-7a371caf563d', 'NC26.M1.SDSR.3', 2, 'choice', 'Splitting data by a third variable', 'Why might an analyst split a dataset by a third variable before comparing two groups?', '["Splitting always forces the two groups to have exactly equal averages","A third variable is needed so that the dataset becomes much larger","Groups may be compared only after the data are cut into three parts","The groups may differ in a third variable that affects results"]', 'The groups may differ in a third variable that affects results', NULL, 'If the groups differ in the third variable, a difference between them may come from that variable. Comparing within each level of it gives a fairer picture.', 'checked', '{"lint":[],"solve":{"answer":"The groups may differ in a third variable that affects results","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Splitting controls for a third variable on which the groups may differ (confounding).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3619fc36-0c2a-40fd-a1bc-777e9561206f', 'NC26.M1.SDSR.3', 2, 'numeric', 'Using a third variable to improve a model', 'After splitting by drink type, cooling is modeled as tea: $T = 90 - 3m$ and coffee: $T = 95 - 4m$, where $T$ is the temperature in degrees and $m$ is the minutes. What temperature does the coffee line predict after 10 minutes?', '[]', '55', '95-4*10', 'Use the coffee line: $T = 95 - 4(10) = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"95 - 4*10 = 55.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949c075d-8e7c-4062-8d09-b4bdb3e9f032', 'NC26.M1.SDSR.3', 2, 'choice', 'Using a third variable to improve a model', 'A single line is fit to the data for all students. Its residuals are mostly positive for the morning class and mostly negative for the evening class. What does this suggest?', '["Class period matters, so the groups need separate lines","The line is perfect and no change is needed","The evening students should be deleted from the data","The morning scores should be lowered to fit the line"]', 'Class period matters, so the groups need separate lines', NULL, 'A pattern in the residuals that follows a group shows that the group variable should be used in the model.', 'checked', '{"lint":[],"solve":{"answer":"Class period matters, so the groups need separate lines","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Systematic residuals by class mean class period is a missing variable: fit separate lines.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1efe2540-bfff-48fd-b2f4-a039e3c9a6ce', 'NC26.M1.SDSR.3', 2, 'numeric', 'Using a third variable to improve a model', 'After splitting by sport, the best-fit lines for height $h$ (in inches) and age $a$ (in years) are: swimmers, $h = 2a + 30$; runners, $h = 3a + 18$. At what age do the two lines predict the same height?', '[]', '12', '(30-18)/(3-2)', 'Set the heights equal: $2a + 30 = 3a + 18$. Subtract $2a$ and 18 from both sides: $12 = a$. So the age is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Context is a little odd (linear height-by-age lines for athletes) but the math is clean.","work":"2a + 30 = 3a + 18, so a = 12.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4eb7ed30-8678-40e3-a247-a96afae5cb28', 'NC26.M1.SDSR.3', 2, 'choice', 'Using a third variable to improve a model', 'A scatter plot of fuel used against distance for all vehicles shows two separate, nearly straight bands of points. What would be most helpful for improving the model?', '["Draw one line through the middle of the gap between the bands","Find a variable that separates the bands and fit a line to each","Delete the points of whichever band has the fewer points in it, then refit","Use one much flatter line that lies in between the two bands"]', 'Find a variable that separates the bands and fit a line to each', NULL, 'Two straight bands suggest two groups. A variable that identifies the groups allows a separate line for each.', 'checked', '{"lint":[],"solve":{"answer":"Find a variable that separates the bands and fit a line to each","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two bands suggest a grouping variable (e.g., vehicle type); separate and fit a line to each.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('057a04ae-5c4b-4ac0-ad4f-80431426c108', 'NC26.M1.SDSR.3', 2, 'numeric', 'Using a third variable to improve a model', 'The line for the morning class is $y = 4x + 50$, where $x$ is hours studied. How many hours of study does the line predict for a score of 78?', '[]', '7', '(78-50)/4', 'Solve $4x + 50 = 78$: $4x = 28$, so $x = 7$ hours.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 50 = 78, 4x = 28, x = 7.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
