INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79e71968-5eee-49ce-835e-f7fa2d76cfd4', 'NC26.M1.SDSR.4', 1, 'choice', 'Reading a point in context', 'On a scatter plot, temperature in degrees is on the horizontal axis and the number of cups of cocoa sold is on the vertical axis. On one day it was 30 degrees and 25 cups were sold. Which ordered pair is plotted for that day?', '["$(25, 30)$","$(30, 55)$","$(30, 25)$","$(5, 25)$"]', '$(30, 25)$', NULL, 'The horizontal value (temperature) is written first and the vertical value (cups sold) second, so the point is $(30, 25)$.', 'checked', '{"lint":[],"solve":{"answer":"$(30, 25)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal = temperature 30, vertical = cups 25: (30, 25).","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
