INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2853ed65-df02-4391-aa00-6fec6d7eca6f', 'NC26.M1.SDSR.4', 1, 'choice', 'Reading a point in context', 'Four students are plotted as (number of pets, number of siblings): $(0, 2)$, $(1, 1)$, $(2, 3)$ and $(3, 0)$. Which point is for a student who has more pets than siblings?', '["$(3, 0)$","$(0, 2)$","$(1, 1)$","$(2, 3)$"]', '$(3, 0)$', NULL, 'In each pair the first number is pets and the second is siblings. Only $(3, 0)$ has a first number larger than its second: 3 pets and 0 siblings. The others have fewer pets than siblings, or the same number.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pets > siblings: (0,2) no, (1,1) equal, (2,3) no, (3,0) yes.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
