INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee205d1b-4fc0-4584-bb63-c6239bb6d173', 'NC26.M1.SDSR.5', 1, 'choice', 'Least-squares line: meaning and prediction', 'A least-squares line for a bike rental shop is $\hat{y} = 6x + 4$, where $x$ is the hours rented and $\hat{y}$ is the predicted cost in dollars. What does the slope 6 tell you?', '["A rental of 0 hours is predicted to cost 6 dollars","A rental of 6 hours is predicted to cost 4 dollars","Each extra hour adds about 6 dollars to the predicted cost","Every rental is predicted to last about 6 hours"]', 'Each extra hour adds about 6 dollars to the predicted cost', NULL, 'The slope is the change in the predicted $y$ for each 1-unit increase in $x$: 6 dollars more per hour.', 'checked', '{"lint":[],"solve":{"answer":"Each extra hour adds about 6 dollars to the predicted cost","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = change in predicted cost per extra hour = 6 dollars.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
