INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97160c69-5cf6-4914-be2f-4fac4a0354c0', 'NC26.M1.SDSR.5', 1, 'choice', 'Least-squares line: meaning and prediction', 'A least-squares line predicts the height $\hat{h}$ (in centimeters) of a burning candle after $t$ hours: $\hat{h} = 20 - 2t$. What does the 20 represent?', '["The predicted number of hours the candle will burn","The predicted height lost during each hour","The predicted height of the candle after 2 hours","The predicted height when the candle is first lit"]', 'The predicted height when the candle is first lit', NULL, 'The 20 is the value of the line at $t = 0$, the moment the candle is lit.', 'checked', '{"lint":[],"solve":{"answer":"The predicted height when the candle is first lit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At t=0, h=20: height when first lit.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
