VALUES ('d71b86a9-3db7-44b3-8caa-2f0cd88074a9', 'NC26.M1.SDSR.5', 1, 'numeric', 'Least-squares line: meaning and prediction', 'The least-squares line for a data set is $\hat{y} = 3x - 4$. What is the predicted value of $y$ when $x = 5$?', '[]', '11', '3*5-4', '$3(5) - 4 = 15 - 4 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(5)-4=11","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
