VALUES ('7ea0d1d1-2b54-44ed-a62e-51029580e6fb', 'NC26.M1.SDSR.5', 1, 'numeric', 'Exponential models', 'A colony of bacteria doubles every hour. It starts with 5 bacteria. How many bacteria are there after 4 hours?', '[]', '80', '5*2^4', 'Doubling 4 times: 5 x 2 x 2 x 2 x 2 = 5 x 16 = 80.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*2^4=80.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
