INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93e18db1-3476-4095-a5d1-d5aa05d697c3', 'NC26.M1.SDSR.5', 1, 'choice', 'Exponential models', 'Which equation shows exponential growth?', '["$y = 1.2x + 3$","$y = 3(0.8)^x$","$y = 3x^2 + 1.2$","$y = 3(1.2)^x$"]', '$y = 3(1.2)^x$', NULL, 'Exponential growth has the form $y = a \cdot b^x$ with $b > 1$. The base 1.2 is greater than 1; the base 0.8 would be decay.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3(1.2)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base >1 in a*b^x: 3(1.2)^x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d3605d-a233-4a21-89bf-9275f80fcc70', 'NC26.M1.SDSR.5', 1, 'numeric', 'Exponential models', 'A population is modeled by $P = 250(1.04)^t$, where $t$ is the time in years. What is the population when $t = 0$?', '[]', '250', '250', 'When $t = 0$, $(1.04)^0 = 1$, so $P = 250$. The number in front of the base is the starting amount.', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"250(1.04)^0=250.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
