VALUES ('fc27ab8b-d936-46bf-9d2e-506a23ea35e7', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation coefficient: sign and strength', 'Which value of $r$ describes a strong negative linear relationship?', '["$r = -0.95$","$r = 0.95$","$r = -0.10$","$r = 0.10$"]', '$r = -0.95$', NULL, 'Negative means $y$ decreases as $x$ increases. Strong means $r$ is close to $-1$ or $1$. Only $-0.95$ is both.', 'checked', '{"lint":[],"solve":{"answer":"$r = -0.95$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strong negative: close to -1: -0.95.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
