INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1f0ef25-b09c-4129-88c2-6909bc653957', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation coefficient: sign and strength', 'The correlation coefficient $r$ always lies between which two numbers?', '["$0$ and $1$","$-10$ and $10$","$-1$ and $1$","$0$ and $100$"]', '$-1$ and $1$', NULL, 'By definition $-1 \le r \le 1$.', 'checked', '{"lint":[],"solve":{"answer":"$-1$ and $1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1 <= r <= 1.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
