INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e900ea2d-16e8-4348-b281-71f1f566562e', 'NC26.M1.SDSR.5', 1, 'numeric', 'Residuals and residual plots', 'The line $\hat{y} = 2x + 5$ is used to predict $y$. At $x = 4$, the actual value of $y$ is 15. What is the residual?', '[]', '2', '15-(2*4+5)', 'Predicted: 2(4) + 5 = 13. Residual = 15 - 13 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predicted 2(4)+5=13; 15-13=2.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
