INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1825506-7326-4dfa-b44b-aecab84a581c', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'On a scatter plot, one point is far from the line, and it turns out that its value was typed wrongly. What should be done?', '["Correct the error, since the point was recorded wrongly","Move the line so that it passes through that one wrong point","Remove every other point from the data set, then draw a new line","Leave the error in the data and say nothing about it to anyone"]', 'Correct the error, since the point was recorded wrongly', NULL, 'If a point is far from the pattern because of a recording mistake, the right step is to fix the mistake.', 'checked', '{"lint":[],"solve":{"answer":"Correct the error, since the point was recorded wrongly","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A known recording error should be corrected.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3820e438-10d3-4fb6-8c0a-f54f0661dc26', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'Ten-year-olds'' heights in centimeters are recorded as (age, height) pairs. Which pair is an outlier?', '["(10, 138)","(10, 60)","(10, 140)","(10, 142)"]', '(10, 60)', NULL, 'Most ten-year-olds are about 140 centimeters tall. A height of 60 centimeters is far from the others.', 'checked', '{"lint":[],"solve":{"answer":"(10, 60)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 cm is far from ~140 cm.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e93b12e-562b-4e6c-830c-9e02e22e4d7b', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation versus causation', 'A study finds that students who wear glasses tend to read more books. Can we conclude that wearing glasses causes more reading?', '["Yes, because the two variables go together so clearly in the data","Yes, because the information came from a real study","No; glasses cannot be linked to anything about reading","No; being linked does not show that one causes the other"]', 'No; being linked does not show that one causes the other', NULL, 'A correlation shows the variables are associated, not that one causes the other.', 'checked', '{"lint":[],"solve":{"answer":"No; being linked does not show that one causes the other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correlation is not causation.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('824a0d56-30b1-4a27-9b98-ae54c5f4ccab', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation versus causation', 'Which is the best way to find out whether a new fertilizer causes plants to grow taller?', '["Randomly choose which plants get the fertilizer, then compare heights","Compare plants that gardeners chose to fertilize with all of the others","Ask gardeners which plants look the tallest","Notice that the tall plants in the garden are often the fertilized plants"]', 'Randomly choose which plants get the fertilizer, then compare heights', NULL, 'Random assignment makes the groups alike in every other way, so a difference in height can be traced to the fertilizer.', 'checked', '{"lint":[],"solve":{"answer":"Randomly choose which plants get the fertilizer, then compare heights","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random assignment experiment shows cause.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94dd02a7-5c78-4ead-bfef-c63fa3cc0e30', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation versus causation', 'Two variables $X$ and $Y$ have a strong correlation. What does this show?', '["$X$ is the cause of $Y$, and nothing else is involved in the link","$X$ and $Y$ are associated, but neither need cause the other","$Y$ is the cause of $X$, and nothing else is involved in the link","$X$ and $Y$ are really just one variable that was measured twice"]', '$X$ and $Y$ are associated, but neither need cause the other', NULL, 'Correlation describes association only; cause needs more evidence, such as a well-designed experiment.', 'checked', '{"lint":[],"solve":{"answer":"$X$ and $Y$ are associated, but neither need cause the other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correlation shows association only.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1a32765-51ab-41bb-9819-5fd5a29bf3e6', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation versus causation', 'Teams that practice more tend to win more games. A coach says winning teams may enjoy practice more. What is the coach pointing out?', '["Practice has no connection with winning of any kind","The data on wins must have been recorded wrongly","The cause and effect might run the other way around in this case","More practice always means more wins in every case"]', 'The cause and effect might run the other way around in this case', NULL, 'The coach suggests the cause and effect may run the other way, so the correlation alone does not settle which causes which.', 'checked', '{"lint":[],"solve":{"answer":"The cause and effect might run the other way around in this case","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Winning may cause enjoying practice (more practice): reverse causation.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb4b2c5b-66d9-46d0-bc9e-de0039cc4c50', 'NC26.M1.SDSR.5', 1, 'choice', 'Making and judging predictions', 'A line is fit to data with $x$-values from 10 to 50. Which prediction is an extrapolation?', '["Predicting $y$ for $x = 20.5$","Predicting $y$ for $x = 80$","Predicting $y$ for $x = 35.5$","Predicting $y$ for $x = 45.5$"]', 'Predicting $y$ for $x = 80$', NULL, 'Extrapolation means predicting outside the range of the data. 80 is outside 10 to 50.', 'checked', '{"lint":[],"solve":{"answer":"Predicting $y$ for $x = 80$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 is outside 10-50.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de62d842-102e-44eb-9571-0d56f87a790c', 'NC26.M1.SDSR.5', 1, 'numeric', 'Making and judging predictions', 'A line fits the prices of used cars aged 1 to 10 years: $\hat{y} = -1200x + 15000$, where $x$ is the age in years and $\hat{y}$ is the price in dollars. What price does the line predict for a car aged 4 years?', '[]', '10200', '-1200*4+15000', '$-1200(4) + 15000 = -4800 + 15000 = 10200$ dollars. Age 4 is inside the range of the data, so this is a reasonable prediction.', 'checked', '{"lint":[],"solve":{"answer":"10200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1200(4)+15000=10200.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d51fdd7c-a980-446e-94e6-d8032a78d9d0', 'NC26.M1.SDSR.5', 1, 'choice', 'Making and judging predictions', 'A line fit to data predicts a negative number of fish for a lake far beyond the range of the data. What does this tell you?', '["The lake must truly have no fish in it at that point","The line should be shifted so that it fits that one point","The line should not be trusted that far away from the data it was fit to","The data points near the middle must all have been wrong"]', 'The line should not be trusted that far away from the data it was fit to', NULL, 'A negative count is impossible. The line only describes the pattern within the range of the data.', 'checked', '{"lint":[],"solve":{"answer":"The line should not be trusted that far away from the data it was fit to","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Extrapolation far beyond data is untrustworthy.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a20cf14-3807-48f1-badb-8c466c9584a4', 'NC26.M1.SDSR.5', 1, 'numeric', 'Making and judging predictions', 'A model predicts that a plant will be 48 centimeters tall. The plant measures 51 centimeters. By how many centimeters was the prediction off?', '[]', '3', '51-48', '51 - 48 = 3 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"51-48=3.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a277e0e-2479-4191-90e4-7a961e1bf6a2', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'The line $\hat{y} = x + 2$ fits a scatter plot well. Four of the data points are $(1, 3)$, $(2, 4)$, $(3, 20)$ and $(4, 6)$. Which point is an outlier?', '["$(1, 3)$","$(2, 4)$","$(3, 20)$","$(4, 6)$"]', '$(3, 20)$', NULL, 'At $x = 1, 2, 3, 4$ the line predicts $y = 3, 4, 5, 6$. The points $(1, 3)$, $(2, 4)$ and $(4, 6)$ lie right on the line. The point $(3, 20)$ is 15 units above the predicted 5, far from the pattern, so it is the outlier.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 20)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predicted y = x+2: (1)->3, (2)->4, (3)->5, (4)->6. Actual 3,4,20,6. Only (3,20) is far from the line (residual 15); the others have residual 0.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b927e9c2-2596-413d-a608-ce89ac0e8ae1', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation versus causation', 'Among children aged 5 to 12, shoe size and reading score have a strong positive correlation. Which explanation is the most reasonable?', '["Older children tend to have both bigger feet and higher reading scores","Having bigger feet helps a child read more words correctly on the test","Reading more books makes a child''s feet grow to a larger shoe size","The correlation must be a mistake, because feet cannot affect reading at all"]', 'Older children tend to have both bigger feet and higher reading scores', NULL, 'Age is a third variable. Older children have bigger feet and also have had more time to learn to read. Neither one causes the other, but the correlation is real, so it is not a mistake.', 'checked', '{"lint":[],"solve":{"answer":"Older children tend to have both bigger feet and higher reading scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Age is a lurking variable: older children have bigger feet and read better. The causal options (B, D) are unreasonable, and C wrongly says the correlation must be a mistake; correlation can exist without causation.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87faf088-ae97-4fc1-8568-6c8dfa68d8f7', 'NC26.M1.SDSR.5', 2, 'numeric', 'Predicting from a least-squares line', 'The least-squares line for a plant''s height, $y$ (in centimeters), after $x$ weeks is $\hat{y} = 1.5x + 12.4$. Use the line to predict the height after 6 weeks, in centimeters.', '[]', '21.4', '1.5*6+12.4', 'Substitute $x = 6$: $\hat{y} = 1.5(6) + 12.4 = 9 + 12.4 = 21.4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"21.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 1.5(6) + 12.4 = 9 + 12.4 = 21.4.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4682bc4-808c-4047-b15d-52c0a17fb635', 'NC26.M1.SDSR.5', 2, 'choice', 'Judging an extrapolated prediction', 'A line fits the heights of children aged 5 to 12 well. A student uses the line to predict the height of a 40-year-old. Why is this prediction unreliable?', '["Predictions from a line of best fit are never reliable","A line of best fit must pass through every point to be used","Age 40 is far outside the ages in the data, and the pattern may not continue","Height cannot be predicted from age at all"]', 'Age 40 is far outside the ages in the data, and the pattern may not continue', NULL, 'The line was fitted to ages 5 to 12. Predicting far outside that range (extrapolating) assumes the same pattern continues, but people stop growing as they become adults.', 'checked', '{"lint":[],"solve":{"answer":"Age 40 is far outside the ages in the data, and the pattern may not continue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Extrapolation far outside the data range (5-12); growth stops in adulthood so the line will not hold.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5394a825-0ff1-48fb-b27e-148f09ed632e', 'NC26.M1.SDSR.5', 2, 'choice', 'Meaning of an exponential growth factor', 'A town''s population is modeled by $P = 2{,}000(1.05)^t$, where $t$ is the number of years. What does the 1.05 tell you?', '["The population grows by 5 percent each year","The population grows by 105 percent each year","The population grows by 1.05 people each year","The population shrinks by 5 percent each year"]', 'The population grows by 5 percent each year', NULL, 'Each year the population is multiplied by 1.05, which is 100 percent plus 5 percent. So it grows by 5 percent each year.', 'checked', '{"lint":[],"solve":{"answer":"The population grows by 5 percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth factor 1.05 = 1 + 0.05: the population grows by 5 percent each year (it becomes 105 percent of the previous year, not grows by 105 percent).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65ed6896-c1ce-4aeb-af66-da1b4cd883d1', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'For a data set, the mean of the $x$-values is 10 and the mean of the $y$-values is 50. The least-squares line has slope 3. What is its $y$-intercept?', '[]', '20', '50-3*10', 'A least-squares line passes through the point (mean of $x$, mean of $y$) = (10, 50). So $50 = 3(10) + b$, which gives $b = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LSRL passes through (10,50): 50=3(10)+b, b=20.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5b4a61b-3958-48cf-a1e3-b6d1f5414f02', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'The least-squares line $\hat{y} = 2.5x + 10$ predicts the weight of a puppy, in pounds, at age $x$ weeks. At what age does the line predict a weight of 35 pounds?', '[]', '10', '(35-10)/2.5', 'Solve $2.5x + 10 = 35$: $2.5x = 25$, so $x = 10$ weeks.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5x+10=35, 2.5x=25, x=10.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49b04598-1204-4fb8-bed6-5e260f93b8e8', 'NC26.M1.SDSR.5', 2, 'choice', 'Least-squares line: meaning and prediction', 'As the temperature $x$ rises, the number of winter coats $y$ sold in a store falls. Which equation could be the least-squares line for these data?', '["$\\hat{y} = -4.2x + 300$","$\\hat{y} = 4.2x + 300$","$\\hat{y} = -4.2x - 300$","$\\hat{y} = 300x + 4.2$"]', '$\hat{y} = -4.2x + 300$', NULL, 'Sales fall as temperature rises, so the slope is negative. The intercept must also be positive: a negative intercept would predict negative sales on a very cold day.', 'checked', '{"lint":[],"solve":{"answer":"$\\hat{y} = -4.2x + 300$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Falling y means negative slope; -4.2x-300 gives negative sales for positive temps, so -4.2x+300.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e716440e-a9d0-4077-b89f-71c2058b437f', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'A line of best fit passes through the points $(2, 14)$ and $(6, 30)$. What value of $y$ does the line predict when $x = 10$?', '[]', '46', '30+(30-14)/(6-2)*(10-6)', 'Slope = (30 - 14) / (6 - 2) = 4. From $x = 6$ to $x = 10$ is 4 more units, so $y = 30 + 4(4) = 46$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope=(30-14)/(6-2)=4; y=14+4(10-2)=46.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08e7c1a5-a3a2-4de3-b8e2-7fee3b964822', 'NC26.M1.SDSR.5', 2, 'choice', 'Least-squares line: meaning and prediction', 'What makes a line the least-squares line for a data set?', '["It passes through as many of the data points as it possibly can do","It makes the sum of the squared residuals as small as possible","It has the same number of points above it as below it","It connects the first data point in the list to the last data point"]', 'It makes the sum of the squared residuals as small as possible', NULL, 'The least-squares line is the one for which the total of the squares of the residuals is smallest.', 'checked', '{"lint":[],"solve":{"answer":"It makes the sum of the squared residuals as small as possible","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition: minimizes sum of squared residuals.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7732675-01d6-4fdc-95bf-ede6662c3b63', 'NC26.M1.SDSR.5', 2, 'numeric', 'Exponential models', 'An account holds 2000 dollars and grows by 10 percent each year, so $A = 2000(1.1)^t$. How many dollars are in the account after 2 years?', '[]', '2420', '2000*1.1^2', '$(1.1)^2 = 1.21$, and 2000 x 1.21 = 2420 dollars.', 'checked', '{"lint":[],"solve":{"answer":"2420","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2000(1.21)=2420.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d9c6ecd-45b1-4a2b-81d2-32b455489c31', 'NC26.M1.SDSR.5', 2, 'choice', 'Exponential models', 'The values of $y$ for $x = 0, 1, 2, 3$ are 4, 12, 36, 108. Which equation fits these data?', '["$y = 4 + 8x$","$y = 4(3)^x$","$y = 4(8)^x$","$y = 12x + 4$"]', '$y = 4(3)^x$', NULL, 'Each value is 3 times the one before it (12/4 = 3, 36/12 = 3, 108/36 = 3), so the growth factor is 3 and the start is 4.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4(3)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratios 12/4=36/12=108/36=3, start 4: y=4(3)^x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f7bb393-ce76-429f-b733-2c68a9f006ae', 'NC26.M1.SDSR.5', 2, 'numeric', 'Exponential models', 'An exponential model passes through the points $(0, 6)$ and $(1, 15)$. What is its growth factor?', '[]', '2.5', '15/6', 'In $y = a \cdot b^x$, $a = 6$ (the value at $x = 0$). At $x = 1$, $y = 6b = 15$, so $b = 15/6 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=6, ab=15, b=2.5.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa929d0-4ed6-418a-ac7e-b855d6ff6aac', 'NC26.M1.SDSR.5', 2, 'choice', 'Exponential models', 'The value of a machine is modeled by $V = 3000(0.85)^t$, where $t$ is in years. By what percent does its value decrease each year?', '["85 percent a year","0.85 percent a year","15 percent each year","8.5 percent a year"]', '15 percent each year', NULL, 'Each year the value is 0.85 times the year before, which is 85 percent of it. So it loses 100 - 85 = 15 percent.', 'checked', '{"lint":[],"solve":{"answer":"15 percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-0.85=0.15: 15 percent decrease per year.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
