INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d85a0c4e-4804-40e8-b372-81e2bbc3e885', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation coefficient: sign and strength', 'Compare two data sets: one has $r = -0.8$ and the other has $r = 0.6$. Which statement is true?', '["The set with $r = 0.6$ has the stronger linear relationship because it is positive","Both sets have equally strong relationships because both are far from 0","The set with $r = -0.8$ has the weaker relationship because it is negative","The set with $r = -0.8$ has the stronger linear relationship"]', 'The set with $r = -0.8$ has the stronger linear relationship', NULL, 'Strength depends on how close $|r|$ is to 1, not on the sign. $|{-0.8}| = 0.8$ is greater than $0.6$.', 'checked', '{"lint":[],"solve":{"answer":"The set with $r = -0.8$ has the stronger linear relationship","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-0.8|>|0.6|, so r=-0.8 is stronger.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4289ffbe-5e63-4f23-82f6-4d596cec84c5', 'NC26.M1.SDSR.5', 2, 'numeric', 'Correlation coefficient: sign and strength', 'Heights in inches and weights in pounds of some adults have $r = 0.7$. Each height is then converted to centimeters. What is the new value of $r$?', '[]', '0.7', '0.7', 'Changing the units of a variable does not change $r$, so it is still 0.7.', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r unchanged by positive linear change of units: 0.7.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40fe5eec-65ca-4f9b-8137-acfe1299e713', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation coefficient: sign and strength', 'The points on a scatter plot follow a clear U-shaped curve, yet the calculated correlation is $r \approx 0$. What does this mean?', '["There is no straight-line link, but there may be a curved one","There is no relationship of any kind between the variables","The data must contain a mistake that should be corrected","The relationship is strong and negative"]', 'There is no straight-line link, but there may be a curved one', NULL, '$r$ measures only linear association. A curve can be very strong yet have $r$ near 0.', 'checked', '{"lint":[],"solve":{"answer":"There is no straight-line link, but there may be a curved one","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r measures only linear association; U-shape is a curved relationship.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a42e9b6d-ad97-4bc0-b940-337fa122f02f', 'NC26.M1.SDSR.5', 2, 'numeric', 'Correlation coefficient: sign and strength', 'A set with $r = 0.6$ shows a moderate linear relationship. How many of these correlation coefficients show a stronger linear relationship than that: 0.35, $-0.92$, 0.78, $-0.5$?', '[]', '2', NULL, 'Compare |r| with 0.6: 0.35 is weaker, 0.92 is stronger, 0.78 is stronger, 0.5 is weaker. So 2 of them are stronger.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|r|>0.6: -0.92 and 0.78 -> 2.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
