INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab84757c-6a87-4677-a5e4-49ce1f85c0a1', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation coefficient: sign and strength', 'The points on a scatter plot rise from left to right and lie close to a straight line, but not exactly on it. Which value of $r$ fits best?', '["$r = -0.9$","$r = 0.9$","$r = 0.1$","$r = 9$"]', '$r = 0.9$', NULL, 'Rising means positive, and being close to a line means $|r|$ is near 1. Also, $r$ can never be as big as 9.', 'checked', '{"lint":[],"solve":{"answer":"$r = 0.9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rising, close to line: strong positive, 0.9.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
