INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('234a3c66-5308-4ca5-8918-cd2e82fa1eb9', 'NC26.M1.SDSR.5', 2, 'numeric', 'Residuals and residual plots', 'A model predicts a score of 62 for a student. The residual for that student is $-5$. What was the student''s actual score?', '[]', '57', '62-5', 'Actual = predicted + residual = 62 + (-5) = 57.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"actual=62+(-5)=57.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
