INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0edce3e-a97a-4428-99c8-6fe555f79514', 'NC26.M1.SDSR.5', 2, 'choice', 'Outliers and influential points', 'A student wants to delete a point because it lowers the correlation. When is it reasonable to remove it?', '["Whenever it lowers $r$, as the goal is to get the highest $r$ possible","Never, because points can never be removed","Whenever it lies on the left side of the plot","Only with a good reason, such as a known recording error"]', 'Only with a good reason, such as a known recording error', NULL, 'A point should be removed only if there is a reason to believe it is an error or does not belong. Otherwise it should be kept, perhaps reporting the results both ways.', 'checked', '{"lint":[],"solve":{"answer":"Only with a good reason, such as a known recording error","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remove only with a good reason, e.g. recording error.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
