INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fe32769-77ea-44a7-9d01-f3f9a835c3e9', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation versus causation', 'Sales of heaters and sales of wool hats both rise in December. What is the best explanation?', '["Buying heaters makes people go out and buy wool hats too","Buying wool hats makes people buy heaters","The two are not linked in any way","A third variable, cold weather, influences both"]', 'A third variable, cold weather, influences both', NULL, 'Cold weather affects both. This is a lurking variable rather than one product causing the other.', 'checked', '{"lint":[],"solve":{"answer":"A third variable, cold weather, influences both","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cold weather is a lurking variable for both.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
