VALUES ('311b2cde-e2c1-4596-88c3-e424f6a4e093', 'PRE.01', 3, 'choice', 'Commutative and associative properties', 'Exactly one of these statements is true. Which one?', '["$10 - 6 = 6 - 10$","$10 \\div 5 = 5 \\div 10$","$10 + 6 = 6 + 10$","$(10 - 6) - 2 = 10 - (6 - 2)$"]', '$10 + 6 = 6 + 10$', NULL, 'Addition can be done in either order. The other three are false: $4 \ne -4$, $2 \ne \frac{1}{2}$ and $2 \ne 6$.', 'checked', '{"lint":[],"solve":{"answer":"$10 + 6 = 6 + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10+6 = 16 = 6+10 true. 2 vs 0.5; 2 vs 6; 4 vs -4 false.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
