VALUES ('6eb91d34-0d16-4b75-bef9-735701234420', 'PRE.01', 3, 'choice', 'Adding and subtracting negative numbers', 'Which expression has the greatest value?', '["$-4 - (-9)$","$4 - 9$","$-4 - 9$","$4 - (-9)$"]', '$4 - (-9)$', NULL, 'The values are $13$, $5$, $-5$ and $-13$. The greatest is $4 - (-9) = 13$.', 'checked', '{"lint":[],"solve":{"answer":"$4 - (-9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4+9 = 5; 4+9 = 13; -5; -13. Greatest 13.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
