INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('571a1dc9-8c91-4d01-b2e4-dc0d755bacd4', 'PRE.01', 3, 'numeric', 'Adding and subtracting negative numbers', 'In a game, Jo starts with 0 points. Her rounds score +9, -6, -11, +12 and -7. How many points does she have now? Write a negative number if she is below 0.', '[]', '-3', '9-6-11+12-7', '$9 - 6 = 3$, $3 - 11 = -8$, $-8 + 12 = 4$, $4 - 7 = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 6 - 11 + 12 - 7 = 21 - 24 = -3.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9030fc26-b553-4690-9e12-ac2a8035be43', 'PRE.01', 3, 'numeric', 'Adding and subtracting negative numbers', 'Two numbers add to $-3$. The first minus the second is 11. What is the first number?', '[]', '4', '(-3+11)/2', 'Adding the two facts: first + second + first - second = $-3 + 11 = 8$, which is twice the first number. So the first is 4 and the second is $-7$ (check: $4 + (-7) = -3$ and $4 - (-7) = 11$).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + y = -3, x - y = 11; add: 2x = 8, x = 4 (y = -7).","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
