INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23dab429-9563-4fcf-8621-b842568c1a25', 'PRE.02', 3, 'numeric', 'Order of operations', 'Find $2^3 - (4 - 1)^2 \times 2 + 18 \div 3^2$.', '[]', '-8', '8-18+2', '$2^3 = 8$. $(4 - 1)^2 \times 2 = 9 \times 2 = 18$. $18 \div 3^2 = 18 \div 9 = 2$. So $8 - 18 + 2 = -8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 9x2 + 18/9 = 8 - 18 + 2 = -8.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
