INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75ca735f-3d4a-419c-b897-2c08a06ecd01', 'PRE.02', 3, 'choice', 'Order of operations', 'Find $8 - 2 \times 3^2 \div (1 + 2)$.', '["$6$","$8$","$2$","$14$"]', '$2$', '8-2*9/3', 'Brackets: $1 + 2 = 3$. Power: $3^2 = 9$. Then left to right: $2 \times 9 = 18$ and $18 \div 3 = 6$. Finally $8 - 6 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^2 = 9; 2x9 = 18; 18/3 = 6; 8 - 6 = 2.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
