INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b06c0532-544d-4ff2-aad9-dac52d63f504', 'PRE.02', 3, 'choice', 'Order of operations', 'Find $3 + 4 \times 2^3 - (6 - 1)^2 \div 5$.', '["$30$","$51$","$35$","$40$"]', '$30$', '3+32-5', '$2^3 = 8$ so $4 \times 8 = 32$. $(6 - 1)^2 = 25$ and $25 \div 5 = 5$. So $3 + 32 - 5 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"$30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8; 4x8 = 32; 5^2 = 25; 25/5 = 5; 3 + 32 - 5 = 30.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
