INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f076123d-7589-4880-8f11-31a63f30568f', 'PRE.02', 3, 'numeric', 'Rewriting and comparing numbers with exponents', 'What is the ones digit of $7^{2026}$? The ones digits of $7^1, 7^2, 7^3, 7^4$ are 7, 9, 3, 1, and then the pattern repeats.', '[]', '9', '9', 'The pattern repeats every 4 powers. $2026 = 4 \times 506 + 2$, so $7^{2026}$ ends like $7^2$, which is 49. The ones digit is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2026 = 4x506 + 2; remainder 2 gives 9.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39607abd-9ff7-44c4-b0c3-c8f9eb4d8384', 'PRE.02', 3, 'choice', 'Rewriting and comparing numbers with exponents', 'What is the last digit of $2^{30}$? The last digits of $2^1, 2^2, 2^3, 2^4$ are 2, 4, 8, 6, and then the pattern repeats.', '["$2$","$4$","$6$","$8$"]', '$4$', '4', 'The pattern repeats every 4 powers. $30 = 4 \times 7 + 2$, so $2^{30}$ ends like $2^2$. The last digit is 4.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 = 4x7 + 2; remainder 2 gives 4.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e62a04b3-5cf1-418c-ac6d-bc29d76dea8c', 'PRE.02', 3, 'choice', 'Rewriting and comparing numbers with exponents', 'Which statement is true?', '["$2^{30} > 3^{20}$","$2^{30} = 3^{20}$","$2^{30} < 3^{20}$","$2^{30} \\times 3^{20} = 1$"]', '$2^{30} < 3^{20}$', NULL, '$2^{30} = (2^3)^{10} = 8^{10}$ and $3^{20} = (3^2)^{10} = 9^{10}$. Since $8^{10} < 9^{10}$, we have $2^{30} < 3^{20}$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{30} < 3^{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^30 = 8^10, 3^20 = 9^10; 8^10 < 9^10.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
