INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6abd0979-0b15-40af-8330-f483a289c081', 'PRE.02', 3, 'numeric', 'Rewriting and comparing numbers with exponents', 'A pond has a lily patch that doubles in area every day. On day 20 the patch covers the whole pond. On which day did it cover exactly half of the pond?', '[]', '19', '20-1', 'Doubling turns half the pond into the whole pond in one day. So half the pond was covered on day 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubles each day, so it was half the day before: day 19.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
