VALUES ('cabcd8e9-1f8b-439e-84af-43ec05cfd4fc', 'PRE.02', 3, 'choice', 'Rewriting and comparing numbers with exponents', 'How many zeros are at the end of the number $5^4 \times 2^6$?', '["$6$","$10$","$4$","$2$"]', '$4$', '4', '$5^4 \times 2^6 = 5^4 \times 2^4 \times 2^2 = 10^4 \times 4 = 40000$. It ends in 4 zeros.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^4 x 2^4 x 2^2 = 10^4 x 4 = 40000: 4 zeros.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
