INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7325d59c-1a0e-4541-aef0-7f454a55457c', 'PRE.02', 3, 'choice', 'Product and quotient laws of exponents', 'Find $\frac{3^5 + 3^5 + 3^5}{3^4}$.', '["$3$","$9$","$1$","$27$"]', '$9$', '3^2', 'Three copies of $3^5$ is $3 \times 3^5 = 3^6$. Then $3^6 \div 3^4 = 3^2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3^5 / 3^4 = 3^6/3^4 = 9.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
