INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcf77b70-a204-453f-88db-f32fbae25216', 'PRE.02', 3, 'choice', 'Zero and negative exponents', 'Which of these is equal to $\frac{1}{8}$?', '["$2^{-3}$","$-2^{-3}$","$(-2)^3$","$\\frac{1}{2^{-3}}$"]', '$2^{-3}$', NULL, '$2^{-3} = \frac{1}{2^3} = \frac{1}{8}$. The others are $-\frac{1}{8}$, $-8$ and $8$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{-3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-3 = 1/8; (-2)^3 = -8; 1/2^-3 = 8; -2^-3 = -1/8.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
