INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37c730db-916c-4bee-946d-c4f065ecd088', 'PRE.03', 1, 'choice', 'Identify primes and composites', 'Which of these numbers is prime?', '["29","21","27","33"]', '29', '29', 'A prime has exactly two divisors, 1 and itself. $21=3\times 7$, $27=3\times 9$ and $33=3\times 11$ are all multiples of 3, so they are composite. 29 is not divisible by 2, 3 or 5, so it is prime.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27=3*9, 33=3*11, 21=3*7; 29 has no divisor 2,3,5 (5^2<29<6^2), so prime.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
