INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a09e8905-94db-411c-a513-0e14fc98c0ae', 'PRE.03', 1, 'numeric', 'Identify primes and composites', 'How many prime numbers are there between $10$ and $20$?', '[]', '4', '4', 'Check each number from 11 to 19. The primes are 11, 13, 17 and 19. The others (12, 14, 15, 16, 18) each have another divisor. So there are 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes between 10 and 20: 11, 13, 17, 19.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
