INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18655bd4-fc75-46dc-b69e-cc674a109dbf', 'PRE.03', 1, 'choice', 'Prime factorization', 'Which is the prime factorization of $12$?', '["$2\\times 6$","$2^2\\times 3$","$3\\times 4$","$2^3\\times 3$"]', '$2^2\times 3$', NULL, 'Break 12 into primes: $12=2\times 6=2\times 2\times 3=2^2\times 3$. The products $2\times 6$ and $3\times 4$ use composite numbers, and $2^3\times 3$ equals 24.', 'checked', '{"lint":[],"solve":{"answer":"$2^2\\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2*2*3 = 2^2*3.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
