VALUES ('b5207f16-47a8-4bc8-a55f-91009eca9337', 'PRE.03', 1, 'numeric', 'Divisibility rules', 'What digit can replace the ? so that the number $56?$ is divisible by $10$?', '[]', '0', '0', 'A number is divisible by 10 when its last digit is 0. So the ? must be 0, giving 560.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 10 needs last digit 0.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
