INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48e1e028-7ab0-4b0a-853c-21c76183a606', 'PRE.03', 1, 'choice', 'Divisibility rules', 'Which of these numbers is divisible by $9$?', '["253","254","255","252"]', '252', NULL, 'A number is divisible by 9 when its digit sum is. $2+5+2=9$, so 252 is divisible by 9 ($252=9\times 28$). The digit sums of the others are 10, 11 and 12; 255 is divisible by 3, but not by 9.', 'checked', '{"lint":[],"solve":{"answer":"252","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digit sums 11,12,10,9: 252.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
