VALUES ('92c6ce88-df80-4337-b082-82f13e06ec5f', 'PRE.03', 1, 'choice', 'Divisibility rules', 'Every whole number that ends in the digit $4$ must also be...', '["divisible by 2","divisible by 4","divisible by 5","divisible by 8"]', 'divisible by 2', NULL, 'Any number ending in 4 is even, so it is divisible by 2. But 14 is not divisible by 4 or 8, and no number ending in 4 is divisible by 5.', 'checked', '{"lint":[],"solve":{"answer":"divisible by 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 not divisible by 4, 8 or 5; ends in even digit so divisible by 2.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
