INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d74c9f36-5558-4525-9693-4156f0aee54d', 'PRE.03', 1, 'choice', 'Greatest common divisor', 'What is the greatest common factor of $20$ and $30$?', '["5","10","60","2"]', '10', '10', 'Both numbers are multiples of 10, and nothing bigger divides both ($20=2\times 2\times 5$, $30=2\times 3\times 5$, so the shared primes are 2 and 5). 5 and 2 are common factors but not the greatest, and 60 is the least common multiple.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(20,30)=10.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
