INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3961fd78-4135-492f-a6ae-587241a07377', 'PRE.03', 1, 'choice', 'Greatest common divisor', 'Which pair of numbers has a greatest common divisor of $1$?', '["6 and 9","10 and 25","8 and 15","14 and 21"]', '8 and 15', NULL, '8 and 15 share no prime factor ($8=2^3$, $15=3\times 5$), so their GCD is 1. The pairs 6 and 9, 10 and 25, 14 and 21 have GCDs 3, 5 and 7.', 'checked', '{"lint":[],"solve":{"answer":"8 and 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8=2^3, 15=3*5 share nothing -> gcd 1; others 5,3,7.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
