INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdff1833-7101-446a-b65c-10cc12a2a910', 'PRE.03', 1, 'numeric', 'Counting divisors', 'How many positive factors does $20$ have?', '[]', '6', '6', 'Pair them up: $1\times 20$, $2\times 10$ and $4\times 5$. That gives 1, 2, 4, 5, 10, 20, which is 6 factors.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20=2^2*5: 3*2=6.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('724fcb46-7ab5-4134-a42d-8a0940384a0c', 'PRE.03', 1, 'choice', 'Counting divisors', 'Which list shows all of the positive divisors of $10$?', '["1, 2, 5","2, 5, 10","1, 2, 5, 10, 20","1, 2, 5, 10"]', '1, 2, 5, 10', NULL, 'The divisors come in pairs: $1\times 10$ and $2\times 5$. So the list is 1, 2, 5, 10. The other lists leave out 10, leave out 1, or include 20, which does not divide 10.', 'checked', '{"lint":[],"solve":{"answer":"1, 2, 5, 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1, 2, 5, 10.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abd7e9d7-3a97-4799-b450-f02e169ed1f9', 'PRE.03', 1, 'numeric', 'GCD and LCM in word problems and relationships', 'One bus leaves a stop every $6$ minutes and another bus leaves every $8$ minutes. Both leave together at 9:00. After how many minutes will they next leave together?', '[]', '24', '24', 'We need the least common multiple of 6 and 8. Multiples of 8: 8, 16, 24. The first one that is also a multiple of 6 is 24. So they leave together again after 24 minutes.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,8)=24.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63f1ef63-ceaa-4d64-9897-e8125898fe6f', 'PRE.03', 1, 'numeric', 'GCD and LCM in word problems and relationships', 'Ana has $12$ pencils and $18$ erasers. She wants to make gift bags that are all the same, using every item. What is the greatest number of bags she can make?', '[]', '6', '6', 'The number of bags must divide both 12 and 18. The greatest such number is the GCD, 6. Each bag has 2 pencils and 3 erasers.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(12,18)=6 bags (2 pencils, 3 erasers each).","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0630793-85a5-40d2-8687-1f620e81f1b1', 'PRE.03', 1, 'choice', 'GCD and LCM in word problems and relationships', 'A red light blinks every $5$ seconds and a blue light blinks every $10$ seconds. They blink together now. After how many seconds will they next blink together?', '["15","50","10","5"]', '10', '10', 'The blue light blinks at 10, 20, 30, ... seconds. The red light blinks at every multiple of 5, which includes 10. So they next blink together after 10 seconds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(5,10)=10.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('773cb97e-f492-4ee7-ad46-5a560d9e1564', 'PRE.03', 1, 'numeric', 'GCD and LCM in word problems and relationships', 'A ribbon $20$ cm long and a ribbon $30$ cm long are each cut into pieces that are all the same length, with nothing left over. What is the greatest possible length of one piece, in centimeters?', '[]', '10', '10', 'The piece length must divide both 20 and 30, so we want the GCD, which is 10. The ribbons make 2 and 3 pieces.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(20,30)=10.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e8d6b9d-b2af-44b7-9d62-915e180be1a9', 'PRE.03', 2, 'choice', 'Identify primes and composites', 'What is the sum of all the prime numbers that are less than $20$?', '["78","77","75","60"]', '77', '2+3+5+7+11+13+17+19', 'The primes below 20 are 2, 3, 5, 7, 11, 13, 17 and 19. Their sum is $2+3+5+7=17$, then $17+11+13=41$, then $41+17+19=77$.', 'checked', '{"lint":[],"solve":{"answer":"77","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+3+5+7+11+13+17+19 = 77.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91c0c92c-3fc8-4ae9-b2b2-b115ac46dd03', 'PRE.03', 2, 'choice', 'Identify primes and composites', 'Which of these numbers is NOT prime?', '["53","59","51","61"]', '51', NULL, 'The digits of 51 add to 6, so 51 is divisible by 3: $51=3\times 17$. The numbers 53, 59 and 61 are not divisible by 2, 3, 5 or 7, so they are prime.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"51=3*17 not prime; 53, 59, 61 prime.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a0b4553-53c5-41c9-bea0-ef0d0c6979a7', 'PRE.03', 2, 'choice', 'Identify primes and composites', 'Which statement is true?', '["Every prime number is odd.","Every odd number is prime.","The product of two primes is a prime.","The number 1 is neither prime nor composite."]', 'The number 1 is neither prime nor composite.', NULL, 'A prime has exactly two different divisors, but 1 has only one, so it is neither prime nor composite. The number 2 is an even prime, 9 is an odd number that is not prime, and $2\times 3=6$ is a product of two primes that is not prime.', 'checked', '{"lint":[],"solve":{"answer":"The number 1 is neither prime nor composite.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product of primes is composite; 2 is even prime; 9 is odd not prime; 1 is neither prime nor composite.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c39b625c-a178-4a8d-9454-b77f50bdba55', 'PRE.03', 2, 'numeric', 'Identify primes and composites', 'How many two-digit prime numbers have $7$ as their units digit?', '[]', '5', '5', 'The two-digit numbers ending in 7 are 17, 27, 37, 47, 57, 67, 77, 87 and 97. Now remove those that are not prime: $27=3\times 9$, $57=3\times 19$, $77=7\times 11$ and $87=3\times 29$. The primes left are 17, 37, 47, 67 and 97, so the answer is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17,27,37,47,57,67,77,87,97: 27=3*9, 57=3*19, 77=7*11, 87=3*29 out; 17,37,47,67,97 prime -> 5.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff6ac938-7986-4ef3-acff-fa3c6eaa3994', 'PRE.03', 2, 'numeric', 'Identify primes and composites', 'Two different prime numbers have a sum of $20$ and a product of $91$. What is the larger of the two primes?', '[]', '13', '13', 'List pairs of primes that add to 20: 3 and 17 (product 51), 7 and 13 (product 91). So the primes are 7 and 13, and the larger is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=20, xy=91=7*13; 7+13=20. Larger 13.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b313719-8121-4373-9733-5949f5f7b2ce', 'PRE.03', 2, 'numeric', 'Prime factorization', 'What is the sum of the different prime factors of $84$?', '[]', '12', '2+3+7', '$84=2\times 42=2\times 2\times 21=2^2\times 3\times 7$. The different primes are 2, 3 and 7, so the sum is $2+3+7=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84=2^2*3*7; 2+3+7=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65188ee9-80d2-4f1c-b14f-67e0bc098c4e', 'PRE.03', 2, 'choice', 'Prime factorization', 'Which is the prime factorization of $360$?', '["$2^3\\times 3\\times 5$","$2^2\\times 3^2\\times 5$","$2^3\\times 3^2\\times 5^2$","$2^3\\times 3^2\\times 5$"]', '$2^3\times 3^2\times 5$', NULL, '$360=36\times 10=(2^2\times 3^2)\times(2\times 5)=2^3\times 3^2\times 5$. Check: $8\times 9\times 5=360$. The other three equal 120, 180 and 1800.', 'checked', '{"lint":[],"solve":{"answer":"$2^3\\times 3^2\\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360=8*45=2^3*3^2*5.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c2850fd-97a0-4c59-8c48-dbbc1fd3587f', 'PRE.03', 2, 'choice', 'Prime factorization', 'A number is equal to $2^3\times 3\times 5^2$. What is the number?', '["120","600","300","1800"]', '600', '2^3*3*5^2', '$2^3=8$ and $5^2=25$. Then $8\times 3\times 25=24\times 25=600$.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*3*25=600.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cac1656-6bd4-4585-8e37-d360df309559', 'PRE.03', 2, 'numeric', 'Prime factorization', 'What is the largest prime factor of $221$?', '[]', '17', '17', 'Test small primes: 221 is not divisible by 2, 3, 5, 7 or 11, but $221=13\times 17$. Both are prime, so the largest prime factor is 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"221=13*17; largest 17.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73db73c4-62aa-4bc4-b1a0-ab8c94c51935', 'PRE.03', 2, 'choice', 'Prime factorization', 'The number $N=2^3\times 3\times 7$. Which of these numbers is a factor of $N$?', '["28","35","27","16"]', '28', '28', '$28=2^2\times 7$, and both $2^2$ and $7$ fit inside $2^3\times 3\times 7$, so 28 is a factor ($N=168=28\times 6$). The number 35 needs a 5, 27 needs $3^3$, and 16 needs $2^4$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"N=168. 16=2^4 no; 28=2^2*7 yes (168/28=6); 35 needs 5; 27 needs 3^3.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27e2c348-1765-4c54-887b-6fc742b78d9b', 'PRE.03', 2, 'numeric', 'Divisibility rules', 'How many whole numbers from $1$ to $200$ are divisible by both $3$ and $5$?', '[]', '13', '195/15', 'A number divisible by both 3 and 5 is divisible by 15. The multiples of 15 up to 200 are $15, 30, \dots, 195$, and $200\div 15$ is a little more than 13. So there are 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 3 and 5 means by 15; floor(200/15)=13.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ed6ed9f-f350-4168-ba6d-87729c1a82d6', 'PRE.03', 2, 'choice', 'Divisibility rules', 'Which digit can replace the ? so that the three-digit number $4?6$ is divisible by $9$?', '["1","8","2","5"]', '8', '18-10', 'The digits must add to a multiple of 9. $4+6=10$, so $10+?$ must be 18, which makes the ? equal to 8. Check: $486=9\times 54$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+?+6=10+? -> 18, ?=8.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0965979e-8b4a-43fe-ae0e-0d67cd91afc7', 'PRE.03', 2, 'choice', 'Divisibility rules', 'Which of these numbers is divisible by $4$?', '["$1{,}214$","$3{,}426$","$7{,}324$","$5{,}718$"]', '$7{,}324$', NULL, 'A number is divisible by 4 when its last two digits make a number divisible by 4. $24=4\times 6$, so $7324$ works. The endings 14, 26 and 18 are not multiples of 4.', 'checked', '{"lint":[],"solve":{"answer":"$7{,}324$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Last two digits 18, 24, 26, 14: only 24 divisible by 4.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3c322d3-71ee-4a69-9c19-7f42ab8e665d', 'PRE.03', 2, 'numeric', 'Divisibility rules', 'What is the smallest four-digit number that is divisible by $9$?', '[]', '1008', '1008', '$1000$ has digit sum 1. We need a digit sum of 9. The smallest way is to raise the units digit by 8: $1008$ has digit sum $1+0+0+8=9$. Nothing from 1000 to 1007 has a digit sum of 9, so the answer is 1008.', 'checked', '{"lint":[],"solve":{"answer":"1008","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1000 has digit sum 1; next with sum 9: 1008 = 9*112.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60e89f15-82ab-4d7f-9c98-1d96c751e749', 'PRE.03', 2, 'choice', 'Divisibility rules', 'Which of these numbers is divisible by $6$ but NOT by $4$?', '["144","156","168","138"]', '138', NULL, 'Divisible by 6 means even and with a digit sum divisible by 3. All four numbers qualify. Now test 4 with the last two digits: 38 is not divisible by 4, but 44, 56 and 68 are. So the answer is 138.', 'checked', '{"lint":[],"solve":{"answer":"138","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All even, digit sums 12,12,9,15 divisible by 3. Last two digits 38 not div by 4; 56, 44, 68 are. 138.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85de638f-4c08-411c-a7ad-1cfef9240b2f', 'PRE.03', 2, 'numeric', 'Greatest common divisor', 'What is the greatest common divisor of $84$ and $126$?', '[]', '42', '2*3*7', '$84=2^2\times 3\times 7$ and $126=2\times 3^2\times 7$. Take the smaller power of each shared prime: $2^1\times 3^1\times 7=42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84=2^2*3*7, 126=2*3^2*7; gcd 2*3*7=42.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19120a2b-913e-4b73-aeca-c9bbc0e77a0a', 'PRE.03', 2, 'choice', 'Greatest common divisor', 'One number is $2^3\times 3^2\times 5$ and another is $2^2\times 3^3\times 7$. What is their greatest common divisor?', '["6","108","72","36"]', '36', '2^2*3^2', 'Use the smaller power of each prime that appears in both: $2^2$ (smaller of $2^3$, $2^2$) and $3^2$ (smaller of $3^2$, $3^3$). The primes 5 and 7 are not shared. So the GCD is $2^2\times 3^2=36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min exponents: 2^2*3^2=36.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9656fb1-4107-4323-b1b3-3cce82b1f6b2', 'PRE.03', 2, 'numeric', 'Greatest common divisor', 'What is the greatest common factor of $210$ and $330$?', '[]', '30', '2*3*5', '$210=2\times 3\times 5\times 7$ and $330=2\times 3\times 5\times 11$. They share 2, 3 and 5, so the GCF is $2\times 3\times 5=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"210=2*3*5*7, 330=2*3*5*11; gcd 30.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d902a08-5614-49c4-be87-5c39c82266f7', 'PRE.03', 2, 'choice', 'Greatest common divisor', 'By which number can you divide both the top and bottom of $\frac{48}{72}$ so that the fraction is in lowest terms in one step?', '["24","12","8","6"]', '24', '24', 'To reach lowest terms in one step, divide by the greatest common divisor of 48 and 72. $48=2^4\times 3$ and $72=2^3\times 3^2$, so the GCD is $2^3\times 3=24$, giving $\frac{2}{3}$. Dividing by 12, 8 or 6 does not finish the job.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(48,72)=24 -> 2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04832e57-ac2f-42a5-af8b-05ed96eac818', 'PRE.03', 2, 'numeric', 'Greatest common divisor', 'What is the greatest common divisor of $91$ and $143$?', '[]', '13', '13', '$91=7\times 13$ and $143=11\times 13$. The only shared prime is 13, so the GCD is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"91=7*13, 143=11*13; gcd 13.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62fc291d-4ed0-4d44-bfd3-e32cf1b9b0bc', 'PRE.03', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of $12$ and $18$?', '[]', '36', '36', '$12=2^2\times 3$ and $18=2\times 3^2$. Take the larger power of each prime: $2^2\times 3^2=36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^2*3^2=36.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a068e79-926b-4df2-b938-523b25f61a31', 'PRE.03', 2, 'choice', 'Least common multiple', 'One number is $2^2\times 3\times 5$ and another is $2\times 3^2\times 7$. What is their least common multiple?', '["7560","420","6","1260"]', '1260', '4*9*5*7', 'Take the larger power of every prime that appears: $2^2$, $3^2$, $5$ and $7$. So the LCM is $4\times 9\times 5\times 7=1260$. The number 7560 is the plain product of the two numbers, 420 forgets $3^2$, and 6 is the GCD.', 'checked', '{"lint":[],"solve":{"answer":"1260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max exponents: 2^2*3^2*5*7=1260.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093d6ad0-9613-43cd-8810-cb88e4159c14', 'PRE.03', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of $6$, $10$ and $15$?', '[]', '30', '30', '$6=2\times 3$, $10=2\times 5$ and $15=3\times 5$. The LCM uses 2, 3 and 5 once each: $2\times 3\times 5=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,10,15)=30.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8fad487-f9cc-4661-ae87-ba78cb5769a2', 'PRE.03', 2, 'numeric', 'Least common multiple', 'What is the smallest number greater than $100$ that is a multiple of both $6$ and $15$?', '[]', '120', '120', 'The LCM of 6 and 15 is 30, so the common multiples are 30, 60, 90, 120, ... The first one above 100 is 120.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,15)=30; first multiple over 100 is 120.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
