INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d583c4d-919b-42f9-bd63-f0c276e269a8', 'PRE.03', 2, 'choice', 'Least common multiple', 'What is the least common multiple of $14$ and $21$?', '["42","7","294","84"]', '42', '42', '$14=2\times 7$ and $21=3\times 7$. The LCM is $2\times 3\times 7=42$. The number 7 is the GCD, 294 is the product $14\times 21$, and 84 is a common multiple but not the least.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14=2*7, 21=3*7; lcm 42.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e3015a1-a872-477c-bcf3-57a117ba0247', 'PRE.03', 2, 'numeric', 'Counting divisors', 'How many positive divisors does $36$ have?', '[]', '9', '3*3', '$36=2^2\times 3^2$. Each divisor uses a power of 2 from $2^0$ to $2^2$ (3 choices) and a power of 3 from $3^0$ to $3^2$ (3 choices), so there are $3\times 3=9$. They are 1, 2, 3, 4, 6, 9, 12, 18, 36.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36=2^2*3^2: 3*3=9.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac7ec131-f0d2-4a84-a17d-e1851b362eb3', 'PRE.03', 2, 'choice', 'Counting divisors', 'A number has the prime factorization $2^3\times 5^2$. How many positive divisors does it have?', '["12","6","7","5"]', '12', '(3+1)*(2+1)', 'Add 1 to each exponent and multiply: $(3+1)\times(2+1)=4\times 3=12$. The numbers 6, 7 and 5 come from multiplying the exponents, adding the plus-one numbers, and adding the exponents.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3+1)(2+1)=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1a4c109-1dad-4353-8d88-2e6a82de96f3', 'PRE.03', 2, 'choice', 'Counting divisors', 'What is the sum of all the positive divisors of $28$?', '["55","28","42","56"]', '56', '1+2+4+7+14+28', 'The divisors of 28 are 1, 2, 4, 7, 14 and 28. Their sum is $1+2+4+7+14+28=56$.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+2+4+7+14+28=56.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
