INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c62eff3-f183-4d49-b68d-3cd0e60158d9', 'PRE.03', 2, 'numeric', 'Counting divisors', 'How many positive divisors does $48$ have?', '[]', '10', '(4+1)*(1+1)', '$48=2^4\times 3$. Add 1 to each exponent and multiply: $(4+1)\times(1+1)=5\times 2=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48=2^4*3: 5*2=10.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
