INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77966158-0856-402d-a6dc-0ef5d2675c4e', 'PRE.03', 3, 'choice', 'Divisibility rules', 'Every whole number that is divisible by both $4$ and $6$ must also be...', '["divisible by 12","divisible by 24","divisible by 8","divisible by 18"]', 'divisible by 12', NULL, 'The smallest number divisible by both 4 and 6 is 12, and every such number is a multiple of 12. But 12 itself is not divisible by 24, 8 or 18, so those do not have to be true.', 'checked', '{"lint":[],"solve":{"answer":"divisible by 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(4,6)=12, so divisible by 12; 12 itself not by 24, 18, 8.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97792226-d9bc-4fdd-8d04-c546ef85e876', 'PRE.03', 3, 'numeric', 'Divisibility rules', 'The four-digit number $4A6B$ is divisible by $2$, $5$ and $9$, where $A$ and $B$ are digits. What is $A$?', '[]', '8', '18-10', 'Divisible by 2 and 5 means divisible by 10, so $B=0$. Then the digit sum $4+A+6+0=10+A$ must be a multiple of 9. The only way with a single digit is $10+A=18$, so $A=8$. Check: $4860=9\times 540$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisible by 2 and 5: B=0. 4+A+6+0=10+A multiple of 9 -> A=8 (4860).","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be8f2496-dcaa-4e5b-89b8-bcec918530ef', 'PRE.03', 3, 'choice', 'Divisibility rules', 'How many whole numbers from $1$ to $100$ are divisible by $2$ or by $3$ (or both)?', '["83","66","50","67"]', '67', '50+33-16', 'There are 50 multiples of 2 and 33 multiples of 3. The 16 multiples of 6 were counted in both lists, so subtract them once: $50+33-16=67$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50+33-16=67.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6cff0ad-c35b-44c9-94c1-4a3ae0c4b560', 'PRE.03', 3, 'choice', 'Greatest common divisor', 'What is the greatest common divisor of $720$ and $1{,}080$?', '["360","180","720","240"]', '360', '8*9*5', '$720=2^4\times 3^2\times 5$ and $1080=2^3\times 3^3\times 5$. Take the smaller power of each prime: $2^3\times 3^2\times 5=8\times 9\times 5=360$.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"720=2^4*3^2*5, 1080=2^3*3^3*5; gcd 2^3*3^2*5=360.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06ea3ffa-cfae-4124-b8d9-8192d8eb0593', 'PRE.03', 3, 'numeric', 'Greatest common divisor', 'What is the greatest number that divides evenly into all three of $84$, $140$ and $210$?', '[]', '14', '2*7', '$84=2^2\times 3\times 7$, $140=2^2\times 5\times 7$ and $210=2\times 3\times 5\times 7$. The primes in all three are 2 and 7, each to the smaller power: $2^1\times 7^1=14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84=2^2*3*7, 140=2^2*5*7, 210=2*3*5*7; gcd 2*7=14.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a90b565-5e87-4c3f-a820-609d5bdabc37', 'PRE.03', 3, 'numeric', 'Greatest common divisor', 'What is the greatest common divisor of $1{,}001$ and $1{,}547$?', '[]', '91', '7*13', '$1001=7\times 11\times 13$ and $1547=7\times 13\times 17$. They share 7 and 13, so the GCD is $7\times 13=91$.', 'checked', '{"lint":[],"solve":{"answer":"91","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1001=7*11*13, 1547=7*13*17; gcd 91.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cf26a0a-fc78-4706-af53-0dd36566627c', 'PRE.03', 3, 'numeric', 'Greatest common divisor', 'Two different whole numbers differ by exactly $1$. What is their greatest common divisor?', '[]', '1', '1', 'Any number that divides both of them also divides their difference, which is 1. The only whole number that divides 1 is 1, so the GCD is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any common divisor divides the difference 1, so gcd 1.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdb312dc-05a8-46ea-84e8-1e9b7c689b53', 'PRE.03', 3, 'numeric', 'Greatest common divisor', 'The greatest common divisor of $48$ and a number $n$ is $12$. If $n$ is between $50$ and $70$, what is $n$?', '[]', '60', '60', 'Since 12 divides $n$, $n$ is a multiple of 12. The multiples of 12 between 50 and 70 are 60 only (48 is too small and 72 too large). Check: $\gcd(48,60)=12$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n multiple of 12 in 50-70: only 60; gcd(48,60)=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b46ba428-7ac9-4aa9-8b7f-1592adaaf812', 'PRE.03', 3, 'choice', 'Least common multiple', 'What is the least common multiple of $24$, $36$ and $60$?', '["120","360","720","180"]', '360', '8*9*5', '$24=2^3\times 3$, $36=2^2\times 3^2$ and $60=2^2\times 3\times 5$. Take the greatest power of each prime: $2^3\times 3^2\times 5=360$.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3*3^2*5=360.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0933cffc-b06e-43bf-905f-19dbd592410b', 'PRE.03', 3, 'choice', 'Least common multiple', 'What is the smallest whole number greater than $1$ that leaves a remainder of $1$ when divided by $4$, by $5$ and by $6$?', '["60","121","61","62"]', '61', '60+1', 'One less than the number must be a multiple of 4, 5 and 6. The LCM of 4, 5 and 6 is 60, so the number is $60+1=61$. Check: $61=4\times 15+1=5\times 12+1=6\times 10+1$.', 'checked', '{"lint":[],"solve":{"answer":"61","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(4,5,6)=60; 60+1=61.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fda69f43-1bd6-48ac-908c-1b5beceae05f', 'PRE.03', 3, 'choice', 'Least common multiple', 'What is the least common multiple of $16$, $24$ and $40$?', '["120","240","480","80"]', '240', '16*3*5', '$16=2^4$, $24=2^3\times 3$ and $40=2^3\times 5$. The greatest powers are $2^4$, $3$ and $5$, so the LCM is $16\times 3\times 5=240$. The number 120 has only $2^3$, 80 leaves out the 3, and 480 is twice too big.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^4*3*5=240.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dae4328-35b1-4c44-965b-f2f9ba687766', 'PRE.03', 3, 'numeric', 'Least common multiple', 'What is the smallest positive whole number that is divisible by every whole number from $1$ to $10$?', '[]', '2520', '8*9*5*7', 'Use the highest power of each prime that appears up to 10: $2^3=8$, $3^2=9$, $5$ and $7$. Then $8\times 9\times 5\times 7=2520$.', 'checked', '{"lint":[],"solve":{"answer":"2520","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3*3^2*5*7=2520.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
