INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('469ae58b-6e33-478f-9cc8-6ae6ffc7698d', 'PRE.03', 3, 'numeric', 'Least common multiple', 'What is the sum of the two smallest positive numbers that are multiples of both $6$ and $9$?', '[]', '54', '18+36', 'The LCM of 6 and 9 is 18, so the common multiples are 18, 36, 54, ... The two smallest are 18 and 36, and $18+36=54$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,9)=18; 18+36=54.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbcc2743-2d8e-466a-a1f5-68273100031a', 'PRE.03', 3, 'choice', 'Counting divisors', 'How many positive divisors of $60$ are even?', '["8","12","6","4"]', '8', '2*2*2', '$60=2^2\times 3\times 5$. An even divisor must use 2 at least once, so the power of 2 can be $2^1$ or $2^2$ (2 choices). The 3 can be used or not (2 choices) and the 5 can be used or not (2 choices). That gives $2\times 2\times 2=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60=2^2*3*5; even divisors = 2*(divisors of 30) = 8.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('810f4671-9d2c-4e69-9dae-380e1e05faa6', 'PRE.03', 3, 'choice', 'Counting divisors', 'What is the smallest positive whole number that has exactly $6$ positive divisors?', '["18","12","20","28"]', '12', '12', 'Check the numbers in order. 1 has 1 divisor, 2, 3, 5, 7, 11 have 2, 4 has 3, 6 has 4, 8 has 4, 9 has 3, 10 has 4. The number 12 has the divisors 1, 2, 3, 4, 6, 12, which is 6, so the answer is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divisor counts: 12 has 6 (1,2,3,4,6,12); smaller numbers 1-11 have at most 4. 12.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf85af1d-8904-4f55-89ff-e701be89d7ed', 'PRE.03', 3, 'choice', 'Counting divisors', 'Which of these numbers has an odd number of positive divisors?', '["80","81","82","84"]', '81', NULL, 'Divisors usually come in pairs, which gives an even count. A pair repeats only when the number is a perfect square, like $81=9\times 9$. The divisors of 81 are 1, 3, 9, 27, 81, which is 5. The numbers 80, 82 and 84 are not perfect squares.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only perfect squares have odd count; 81=9^2.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cad2c777-bdc0-4353-95bf-ac8394b7e630', 'PRE.03', 3, 'choice', 'Counting divisors', 'How many positive divisors of $72$ are perfect squares?', '["3","6","4","9"]', '4', '2*2', '$72=2^3\times 3^2$. A divisor that is a perfect square uses an even power of each prime: 2 to the power 0 or 2 and 3 to the power 0 or 2. That gives $2\times 2=4$ divisors: 1, 4, 9 and 36.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72=2^3*3^2; square divisors 1,4,9,36 -> 4.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('057bc5f2-68f5-4ebf-b974-247ee46f4622', 'PRE.03', 3, 'numeric', 'GCD and LCM in word problems and relationships', 'Three lights flash every $6$, $8$ and $10$ seconds. All three flash together at noon. How many more times do all three flash together in the next $11$ minutes?', '[]', '5', '600/120', 'The LCM of 6, 8 and 10 is 120 seconds ($2^3\times 3\times 5$). Eleven minutes is 660 seconds. The lights flash together at 120, 240, 360, 480 and 600 seconds; the next would be at 720, which is too late. So 5 times.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,8,10)=120 s = 2 min; in 11 min at 2,4,6,8,10 min -> 5.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02d533d4-ec28-4840-8493-d9e8081b7207', 'PRE.03', 3, 'numeric', 'GCD and LCM in word problems and relationships', 'Two different whole numbers, both between $10$ and $30$, have a greatest common divisor of $6$ and a least common multiple of $72$. What is the sum of the two numbers?', '[]', '42', '18+24', 'Both numbers are multiples of 6 between 10 and 30: 12, 18, 24. GCD times LCM equals the product, so the product is $6\times 72=432$. Of the pairs, $18\times 24=432$. Check: GCD of 18 and 24 is 6, LCM is 72. The sum is $18+24=42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=6x, b=6y, xy=12, coprime: (1,12)->6,72 or (3,4)->18,24. Both in 10-30: 18+24=42.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddd63d91-1db5-4183-82aa-8af2d776cd5c', 'PRE.03', 3, 'numeric', 'GCD and LCM in word problems and relationships', 'A shop has $60$ apples, $84$ oranges and $108$ pears. It makes the greatest possible number of identical fruit baskets, using all of the fruit. How many pieces of fruit are in each basket?', '[]', '21', '5+7+9', 'The number of baskets must divide 60, 84 and 108, so the greatest number is their GCD: $60=2^2\times 3\times 5$, $84=2^2\times 3\times 7$ and $108=2^2\times 3^3$, so the GCD is 12. Each basket has $60\div 12=5$ apples, $84\div 12=7$ oranges and $108\div 12=9$ pears. That is $5+7+9=21$ pieces.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(60,84,108)=12 baskets; each has 5+7+9=21.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebc89206-ed3c-493a-9805-d933a78ee288', 'PRE.03', 3, 'choice', 'GCD and LCM in word problems and relationships', 'One clock chimes every $20$ minutes and another chimes every $45$ minutes. They chime together at 1:00 pm. After how many minutes do they next chime together?', '["180","5","65","900"]', '180', '180', '$20=2^2\times 5$ and $45=3^2\times 5$. The LCM is $2^2\times 3^2\times 5=180$ minutes, which is 3 hours (4:00 pm). The number 5 is the GCD, 65 is the sum, and 900 is the product, which is a common time but not the first.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(20,45)=180.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1482fe19-ae94-4efd-aad7-129467452a0a', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', 'Which fraction is $\frac{6}{8}$ in simplest form?', '["$\\frac{3}{8}$","$\\frac{4}{3}$","$\\frac{3}{4}$","$\\frac{2}{3}$"]', '$\frac{3}{4}$', NULL, 'Both 6 and 8 can be divided by 2: $6\div 2=3$ and $8\div 2=4$. So $\frac{6}{8}=\frac{3}{4}$. Nothing but 1 divides both 3 and 4, so this is simplest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 2: 3/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('375dd920-351f-490d-84ed-ab70af73a345', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', 'Which fraction is equal to $\frac{2}{3}$?', '["$\\frac{4}{6}$","$\\frac{4}{5}$","$\\frac{3}{4}$","$\\frac{2}{6}$"]', '$\frac{4}{6}$', NULL, 'Multiply the top and bottom of $\frac{2}{3}$ by 2 to get $\frac{4}{6}$. Adding the same number to the top and bottom, as in $\frac{4}{5}$ and $\frac{3}{4}$, changes the value, and $\frac{2}{6}$ is only $\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6 (times 2/2).","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('350768a6-61b7-4c55-961e-eb65eb4e8a84', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', '$\frac{3}{5}=\dfrac{?}{20}$. What number is the ?', '["8","15","17","12"]', '12', '3*4', 'The bottom changed from 5 to 20, which is times 4. So the top must also be times 4: $3\times 4=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20=5*4, so 3*4=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04d86797-9d2c-4d0b-9a59-8defa2c9aa02', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', 'Which of these fractions is already in simplest form?', '["$\\frac{6}{9}$","$\\frac{7}{12}$","$\\frac{10}{15}$","$\\frac{14}{21}$"]', '$\frac{7}{12}$', NULL, 'The fractions $\frac{6}{9}$, $\frac{10}{15}$ and $\frac{14}{21}$ can be reduced (by 3, 5 and 7). The only number that divides both 7 and 12 is 1, so $\frac{7}{12}$ is in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 and 12 share no factor; 10/15, 14/21, 6/9 all reduce to 2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
