INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5da97ba-e28a-4a3c-b770-11b8163fe4c3', 'PRE.04', 1, 'numeric', 'Add and subtract fractions', 'What is $\frac{3}{8}+\frac{2}{8}$?', '[]', '5/8', '3/8+2/8', 'The denominators are the same, so add the numerators: $3+2=5$. The answer is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
