INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1c62231-fa85-4f6a-95e6-95b8e1ee2e78', 'PRE.04', 1, 'choice', 'Add and subtract fractions', 'What is $\frac{1}{2}+\frac{1}{4}$?', '["$\\frac{2}{6}$","$\\frac{3}{4}$","$\\frac{1}{3}$","$\\frac{2}{4}$"]', '$\frac{3}{4}$', NULL, 'Write $\frac{1}{2}$ as $\frac{2}{4}$. Then $\frac{2}{4}+\frac{1}{4}=\frac{3}{4}$. Adding the tops and the bottoms separately, as in $\frac{2}{6}$, is a mistake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4+1/4=3/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
