INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5a924da-f759-471a-8da2-15a40c477f4f', 'PRE.04', 1, 'numeric', 'Add and subtract fractions', 'What is $\frac{5}{6}-\frac{1}{6}$? Write the answer in simplest form.', '[]', '2/3', '5/6-1/6', '$\frac{5}{6}-\frac{1}{6}=\frac{4}{6}$. Divide the top and bottom by 2 to get $\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
