INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e5b8991-eeb5-47ee-a30c-67a496a9ced6', 'PRE.04', 1, 'numeric', 'Add and subtract fractions', 'Sam ate $\frac{1}{3}$ of a pizza and Mia ate $\frac{1}{6}$ of the same pizza. What fraction of the pizza did they eat in all? Write it in simplest form.', '[]', '1/2', '1/3+1/6', '$\frac{1}{3}=\frac{2}{6}$, so together they ate $\frac{2}{6}+\frac{1}{6}=\frac{3}{6}=\frac{1}{2}$ of the pizza.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/6+1/6=3/6=1/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
