INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac759d6c-2d27-4f0a-b954-de73b8375b05', 'PRE.04', 1, 'choice', 'Add and subtract fractions', 'What is $\frac{7}{10}-\frac{2}{5}$?', '["$\\frac{5}{5}$","$\\frac{1}{5}$","$\\frac{3}{10}$","$\\frac{5}{10}$"]', '$\frac{3}{10}$', NULL, 'Write $\frac{2}{5}$ as $\frac{4}{10}$. Then $\frac{7}{10}-\frac{4}{10}=\frac{3}{10}$. Subtracting tops and bottoms separately gives $\frac{5}{5}$, which is wrong.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/10-4/10=3/10.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
