INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d910608-3898-4fb1-bf1d-955031c95ad8', 'PRE.04', 1, 'choice', 'Multiply fractions and find a fraction of a number', 'What is $\frac{2}{3}\times\frac{3}{4}$?', '["$\\frac{5}{7}$","$\\frac{8}{9}$","$\\frac{1}{12}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, '$\frac{2\times 3}{3\times 4}=\frac{6}{12}=\frac{1}{2}$. Adding tops and bottoms gives $\frac{5}{7}$, and $\frac{8}{9}$ is what you get by dividing instead of multiplying.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/12=1/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
