INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87ac16fe-8a52-4e4a-803a-17d233ffb85b', 'PRE.04', 1, 'numeric', 'Multiply fractions and find a fraction of a number', 'A box has $36$ crayons. Five ninths of the crayons are new. How many crayons are new?', '[]', '20', '5/9*36', 'One ninth of 36 is $36\div 9=4$. Five ninths is $5\times 4=20$ crayons.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/9*5=20.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
