INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51a22fe4-f8a0-4024-bf42-35378e8a2d20', 'PRE.04', 1, 'numeric', 'Divide fractions and use reciprocals', 'What is the reciprocal of $\frac{3}{7}$? Write it as a fraction.', '[]', '7/3', '7/3', 'The reciprocal flips a fraction upside down, so the top and bottom swap places. The reciprocal of $\frac{3}{7}$ is $\frac{7}{3}$ (and $\frac{3}{7}\times\frac{7}{3}=1$).', 'checked', '{"lint":[],"solve":{"answer":"7/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reciprocal 7/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
