INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7a68ff2-13db-4f27-975b-69dc8e673de9', 'PRE.04', 1, 'choice', 'Divide fractions and use reciprocals', 'What is $\frac{1}{3}\div\frac{1}{6}$?', '["$\\frac{1}{18}$","$\\frac{1}{2}$","3","2"]', '2', '1/3/(1/6)', 'Dividing by $\frac{1}{6}$ means multiplying by 6: $\frac{1}{3}\times 6=2$. There are two sixths in one third. The value $\frac{1}{18}$ comes from multiplying instead, and $\frac{1}{2}$ from dividing the other way round.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3*6=2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
