INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60b43ef2-fbc9-4072-b837-e893eb734444', 'PRE.04', 1, 'numeric', 'Fraction word problems and order of operations', 'How much more is $\frac{3}{4}$ of $12$ than $\frac{2}{3}$ of $12$?', '[]', '1', '3/4*12-2/3*12', '$\frac{3}{4}$ of 12 is 9 and $\frac{2}{3}$ of 12 is 8. The difference is $9-8=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-8=1.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
