INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('696ae32e-13d0-4bf2-b495-c19100d31a94', 'PRE.04', 2, 'numeric', 'Simplify, compare and find equivalent fractions', 'Write $\frac{84}{126}$ in simplest form.', '[]', '2/3', '84/126', 'The greatest common divisor of 84 and 126 is 42. Divide both by 42: $84\div 42=2$ and $126\div 42=3$. So $\frac{84}{126}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(84,126)=42: 2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f067f72-7004-4e5e-8a5b-aea9644a3c4c', 'PRE.04', 2, 'choice', 'Simplify, compare and find equivalent fractions', 'Which of these fractions is the greatest?', '["$\\frac{7}{9}$","$\\frac{8}{11}$","$\\frac{5}{6}$","$\\frac{3}{4}$"]', '$\frac{5}{6}$', NULL, 'Compare how far each is from 1: $\frac{5}{6}$ is $\frac{1}{6}$ short, $\frac{7}{9}$ is $\frac{2}{9}$ short, $\frac{8}{11}$ is $\frac{3}{11}$ short and $\frac{3}{4}$ is $\frac{1}{4}$ short. The smallest gap, $\frac{1}{6}$, belongs to $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each is 1 minus 1/6, 2/9, 1/4, 3/11; smallest gap 1/6 (0.167 < 0.222, 0.25, 0.273). 5/6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70f6a2fb-1864-45b7-8957-ed83085de3ca', 'PRE.04', 2, 'numeric', 'Simplify, compare and find equivalent fractions', 'A fraction is equal to $\frac{5}{9}$, and its numerator and denominator add to $42$. What is its numerator?', '[]', '15', '5*42/14', 'The numerator and denominator are $5k$ and $9k$ for some number $k$. Then $5k+9k=14k=42$, so $k=3$. The fraction is $\frac{15}{27}$ and its numerator is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5k+9k=42 -> k=3; 15/27.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec6dbb8b-50d6-4c91-a674-c51df39667c5', 'PRE.04', 2, 'choice', 'Simplify, compare and find equivalent fractions', 'Which of these fractions is between $\frac{1}{3}$ and $\frac{1}{2}$?', '["$\\frac{1}{4}$","$\\frac{3}{5}$","$\\frac{5}{8}$","$\\frac{2}{5}$"]', '$\frac{2}{5}$', NULL, 'Use a common denominator of 30: $\frac{1}{3}=\frac{10}{30}$ and $\frac{1}{2}=\frac{15}{30}$. Then $\frac{2}{5}=\frac{12}{30}$ lies between them. The others are $\frac{1}{4}$ (too small), $\frac{3}{5}$ and $\frac{5}{8}$ (too big).', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3~0.333, 1/2=0.5; 2/5=0.4 lies between; 3/5, 5/8 too big, 1/4 too small.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
