VALUES ('a491e8e2-a2eb-4079-b273-0d0526e86476', 'PRE.04', 2, 'choice', 'Add and subtract fractions', 'What is $\frac{2}{3}+\frac{3}{4}$? Write the answer as an improper fraction.', '["$\\frac{17}{12}$","$\\frac{5}{7}$","1","$\\frac{5}{12}$"]', '$\frac{17}{12}$', NULL, 'Use the common denominator 12: $\frac{8}{12}+\frac{9}{12}=\frac{17}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{17}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/12+9/12=17/12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
