VALUES ('849c3460-b5a4-4e62-86e3-9b98e02247ab', 'PRE.04', 2, 'choice', 'Add and subtract fractions', 'What is $\frac{1}{2}+\frac{1}{3}+\frac{1}{6}$?', '["$\\frac{3}{11}$","$\\frac{5}{6}$","$\\frac{2}{3}$","1"]', '1', '1/2+1/3+1/6', 'Use the common denominator 6: $\frac{3}{6}+\frac{2}{6}+\frac{1}{6}=\frac{6}{6}=1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6+2/6+1/6=1.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
