VALUES ('feba385a-5fd7-43a2-8db2-71fae17bdcb2', 'PRE.04', 2, 'choice', 'Multiply fractions and find a fraction of a number', 'What is $\frac{4}{9}\times\frac{15}{16}$?', '["$\\frac{5}{12}$","$\\frac{5}{16}$","$\\frac{12}{5}$","$\\frac{1}{12}$"]', '$\frac{5}{12}$', NULL, 'Cancel: 4 and 16 share a factor of 4, and 15 and 9 share a factor of 3. This gives $\frac{1\times 5}{3\times 4}=\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/144=5/12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
