VALUES ('7bdac6cd-77cc-4f2e-a358-2c16e2c8169e', 'PRE.04', 2, 'choice', 'Multiply fractions and find a fraction of a number', 'What is $\left(\frac{3}{5}\right)^3$?', '["$\\frac{27}{125}$","$\\frac{9}{15}$","$\\frac{9}{25}$","$\\frac{27}{15}$"]', '$\frac{27}{125}$', NULL, '$\left(\frac{3}{5}\right)^3=\frac{3\times 3\times 3}{5\times 5\times 5}=\frac{27}{125}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{27}{125}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27/125.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
