INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8f8b2cf-3113-422a-b43e-50f06d3fe6e3', 'PRE.04', 2, 'numeric', 'Multiply fractions and find a fraction of a number', 'A recipe needs $\frac{2}{3}$ cup of sugar. Mia makes $\frac{3}{4}$ of the recipe. How many cups of sugar does she use? Write the answer in simplest form.', '[]', '1/2', '3/4*2/3', '$\frac{3}{4}\times\frac{2}{3}=\frac{6}{12}=\frac{1}{2}$ cup.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3*3/4=6/12=1/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
