INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf5922f5-cb13-421f-b502-6b64492f6198', 'PRE.04', 2, 'choice', 'Multiply fractions and find a fraction of a number', 'What is $\frac{2}{3}$ of $\frac{3}{5}$ of $30$?', '["18","12","20","6"]', '12', '2/3*3/5*30', 'First, $\frac{3}{5}$ of 30 is 18. Then $\frac{2}{3}$ of 18 is 12. (18 is only the first step, and 20 is $\frac{2}{3}$ of 30.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 of 30=18; 2/3 of 18=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
