VALUES ('f24ccc59-eec2-4ca6-b29c-ab9760ce3200', 'PRE.04', 2, 'numeric', 'Divide fractions and use reciprocals', 'What is $\frac{3}{4}\div\frac{9}{10}$? Write the answer in simplest form.', '[]', '5/6', '3/4/(9/10)', 'Multiply by the reciprocal: $\frac{3}{4}\times\frac{10}{9}=\frac{30}{36}=\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4*10/9=30/36=5/6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
