INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5d98013-badc-4daf-93d8-b8ffbc49f8af', 'PRE.04', 2, 'choice', 'Divide fractions and use reciprocals', 'What is $\frac{5}{8}\div\frac{5}{12}$?', '["$\\frac{3}{2}$","$\\frac{2}{3}$","$\\frac{25}{96}$","$\\frac{3}{8}$"]', '$\frac{3}{2}$', NULL, '$\frac{5}{8}\times\frac{12}{5}=\frac{60}{40}=\frac{3}{2}$. The value $\frac{2}{3}$ comes from flipping the wrong fraction, and $\frac{25}{96}$ comes from multiplying without flipping.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8*12/5=12/8=3/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
