INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bdccbed-a3eb-442d-8018-aef4092ce3fc', 'PRE.04', 2, 'numeric', 'Divide fractions and use reciprocals', 'A jug has $\frac{3}{4}$ liter of juice. It is poured into small cups that each hold $\frac{1}{8}$ liter. How many cups are filled?', '[]', '6', '3/4/(1/8)', '$\frac{3}{4}\div\frac{1}{8}=\frac{3}{4}\times 8=6$ cups. (Or: $\frac{3}{4}=\frac{6}{8}$, which is six eighths.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 / 1/8 = 6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
