INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c7378ab-d616-4bb7-a512-2ce64dfa6df2', 'PRE.04', 2, 'numeric', 'Divide fractions and use reciprocals', 'What is $\frac{7}{9}\div\frac{14}{27}$? Write the answer in simplest form.', '[]', '3/2', '7/9/(14/27)', '$\frac{7}{9}\times\frac{27}{14}$. Cancel 7 with 14 and 9 with 27: $\frac{1\times 3}{1\times 2}=\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/9*27/14=3/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
