INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('530699f1-9024-4d62-b512-9dfe67241c5a', 'PRE.04', 2, 'choice', 'Divide fractions and use reciprocals', 'What is $\frac{6}{7}\div\frac{3}{14}$?', '["$\\frac{9}{49}$","4","$\\frac{1}{4}$","3"]', '4', '6/7/(3/14)', '$\frac{6}{7}\times\frac{14}{3}=\frac{84}{21}=4$. The value $\frac{9}{49}$ is what you get by multiplying the fractions without flipping, and $\frac{1}{4}$ comes from flipping the first fraction instead.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/7*14/3=4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
