INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d822519d-28e6-4ccf-a4ff-4eabda83868e', 'PRE.04', 2, 'numeric', 'Mixed numbers and improper fractions', 'Maya has $3\dfrac{1}{2}$ cups of milk and buys $2\dfrac{3}{4}$ more cups. How many cups of milk does she have now? Write the answer as a mixed number.', '[]', '6 1/4', '7/2+11/4', 'Add the wholes: $3+2=5$. Add the fractions: $\frac{1}{2}+\frac{3}{4}=\frac{2}{4}+\frac{3}{4}=\frac{5}{4}=1\frac{1}{4}$. Total: $5+1\frac{1}{4}=6\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"6 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 2/4+2 3/4=5 5/4=6 1/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5054f4a-d8cd-48ab-9336-28ac3f9cd7ba', 'PRE.04', 2, 'choice', 'Mixed numbers and improper fractions', 'What is $5\dfrac{1}{3}-2\dfrac{1}{2}$? Write the answer as a mixed number.', '["$3\\frac{1}{6}$","$2\\frac{5}{6}$","$3\\frac{5}{6}$","$2\\frac{1}{6}$"]', '$2\frac{5}{6}$', NULL, '$5\frac{1}{3}=\frac{16}{3}=\frac{32}{6}$ and $2\frac{1}{2}=\frac{5}{2}=\frac{15}{6}$. The difference is $\frac{17}{6}=2\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16/3-5/2=32/6-15/6=17/6=2 5/6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e5baeeb-f9c5-4224-b629-899726a684fa', 'PRE.04', 2, 'choice', 'Mixed numbers and improper fractions', 'What is $2\dfrac{1}{2}\times 1\dfrac{1}{5}$?', '["$2\\frac{1}{10}$","3","$3\\frac{7}{10}$","$2\\frac{1}{12}$"]', '3', '5/2*6/5', 'Convert to improper fractions: $\frac{5}{2}\times\frac{6}{5}=\frac{30}{10}=3$. Multiplying wholes and fractions separately gives $2\frac{1}{10}$, adding gives $3\frac{7}{10}$, and dividing gives $2\frac{1}{12}$, all wrong.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/2*6/5=3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5feac1c0-fb7a-44c3-b7d6-b5ef056472ad', 'PRE.04', 2, 'numeric', 'Mixed numbers and improper fractions', 'How many times does $1\dfrac{1}{2}$ go into $3\dfrac{3}{4}$? Give the answer as a mixed number.', '[]', '2 1/2', '15/4/(3/2)', '$3\frac{3}{4}=\frac{15}{4}$ and $1\frac{1}{2}=\frac{3}{2}$. Then $\frac{15}{4}\times\frac{2}{3}=\frac{30}{12}=\frac{5}{2}=2\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/4 / 3/2=15/4*2/3=5/2=2 1/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
