INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccc7ac7e-3c9f-451a-965f-77bf9ca5ce4c', 'PRE.04', 2, 'numeric', 'Mixed numbers and improper fractions', 'A board is $7\dfrac{1}{4}$ feet long. A piece $2\dfrac{2}{3}$ feet long is cut off. How long is the rest, in feet? Write the answer as a mixed number.', '[]', '4 7/12', '29/4-8/3', '$7\frac{1}{4}=7\frac{3}{12}$ and $2\frac{2}{3}=2\frac{8}{12}$. Borrow 1 from the 7: $6\frac{15}{12}-2\frac{8}{12}=4\frac{7}{12}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"4 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29/4-8/3=87/12-32/12=55/12=4 7/12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
