INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aeb06c8f-ed4f-44d6-a41f-9d29ffdafe08', 'PRE.04', 2, 'choice', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{\frac{3}{5}}{\frac{9}{10}}$? Write the answer in simplest form.', '["$\\frac{2}{3}$","$\\frac{3}{4}$","$\\frac{5}{6}$","$\\frac{27}{50}$"]', '$\frac{2}{3}$', NULL, '$\frac{3}{5}\div\frac{9}{10}=\frac{3}{5}\times\frac{10}{9}=\frac{30}{45}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5*10/9=30/45=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
