INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc20b563-2c7c-466a-a017-108cc0cd99d7', 'PRE.04', 2, 'choice', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{1}{1+\frac{1}{3}}$?', '["$\\frac{3}{4}$","$\\frac{4}{3}$","$\\frac{1}{4}$","$\\frac{1}{3}$"]', '$\frac{3}{4}$', NULL, 'First, $1+\frac{1}{3}=\frac{4}{3}$. Then $1\div\frac{4}{3}=\frac{3}{4}$. The value $\frac{4}{3}$ is the bottom without the final flip.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/(4/3)=3/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
