INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcdc04f8-d257-4060-8cf7-a034ea4dff66', 'PRE.04', 2, 'numeric', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{\frac{5}{6}+\frac{1}{3}}{\frac{7}{12}}$?', '[]', '2', '(5/6+1/3)/(7/12)', 'The top is $\frac{5}{6}+\frac{2}{6}=\frac{7}{6}$. Then $\frac{7}{6}\div\frac{7}{12}=\frac{7}{6}\times\frac{12}{7}=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6+2/6=7/6; 7/6*12/7=2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
