INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('966b2ded-e147-4573-917e-f3ed085640ff', 'PRE.04', 2, 'numeric', 'Fraction word problems and order of operations', 'What is $\left(\frac{1}{4}+\frac{2}{3}\right)\times 12$?', '[]', '11', '(1/4+2/3)*12', 'Do the brackets first: $\frac{1}{4}+\frac{2}{3}=\frac{3}{12}+\frac{8}{12}=\frac{11}{12}$. Then $\frac{11}{12}\times 12=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+8=11.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
