INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5abb0813-e83e-4bda-960a-f5ba19425138', 'PRE.04', 2, 'choice', 'Fraction word problems and order of operations', 'Ana spent $\frac{1}{4}$ of her money on a book and $\frac{1}{3}$ of her money on lunch. She has 10 dollars left. How many dollars did she have at the start?', '["25","15","24","30"]', '24', '10/(1-1/4-1/3)', 'She spent $\frac{1}{4}+\frac{1}{3}=\frac{7}{12}$ of her money, so $\frac{5}{12}$ is left. If $\frac{5}{12}$ is 10 dollars, then $\frac{1}{12}$ is 2 dollars and the whole is $12\times 2=24$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 1-1/4-1/3=5/12 of start = 10 -> 24.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31128ac0-bba1-4b44-ba85-38107ad894e0', 'PRE.04', 2, 'choice', 'Fraction word problems and order of operations', 'A tank holds $60$ liters. It is $\dfrac{2}{5}$ full. How many more liters are needed to make it $\dfrac{3}{4}$ full?', '["21","36","45","24"]', '21', '3/4*60-2/5*60', 'Now it has $\frac{2}{5}\times 60=24$ liters. At three fourths it would have $\frac{3}{4}\times 60=45$ liters. The difference is $45-24=21$ liters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4*60=45, 2/5*60=24; 21.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('921c0e90-3a6e-43f2-8a48-44cc574c77f4', 'PRE.04', 2, 'numeric', 'Fraction word problems and order of operations', 'What is $\frac{5}{6}+\frac{1}{2}\div\frac{3}{4}$? Write the answer as an improper fraction.', '[]', '3/2', '5/6+1/2/(3/4)', 'Divide first: $\frac{1}{2}\div\frac{3}{4}=\frac{1}{2}\times\frac{4}{3}=\frac{2}{3}$. Then add: $\frac{5}{6}+\frac{2}{3}=\frac{5}{6}+\frac{4}{6}=\frac{9}{6}=\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2*4/3=2/3; 5/6+4/6=9/6=3/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0293cbff-2345-4b54-80d6-bdd2c7cd017e', 'PRE.04', 2, 'choice', 'Fraction word problems and order of operations', 'Max walks $\frac{2}{5}$ of the way to school. Then he walks $\frac{1}{3}$ of the distance that is still left. What fraction of the whole way has he walked?', '["$\\frac{11}{15}$","$\\frac{3}{5}$","$\\frac{1}{5}$","$\\frac{2}{3}$"]', '$\frac{3}{5}$', NULL, 'After the first part, $\frac{3}{5}$ of the way is left. He walks $\frac{1}{3}$ of that, which is $\frac{1}{3}\times\frac{3}{5}=\frac{1}{5}$. In all he has walked $\frac{2}{5}+\frac{1}{5}=\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 + 1/3*3/5 = 2/5+1/5=3/5.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('584a2ae0-023a-453a-8eb0-3d0e93f048a5', 'PRE.04', 3, 'numeric', 'Simplify, compare and find equivalent fractions', 'For how many whole numbers $n$ with $0<n<12$ is the fraction $\dfrac{n}{12}$ already in simplest form?', '[]', '4', '4', 'The fraction is in simplest form when $n$ shares no prime factor with $12=2^2\times 3$. So $n$ must be odd and not a multiple of 3. From 1 to 11 the numbers that work are 1, 5, 7 and 11. That is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n coprime to 12 in 1..11: 1,5,7,11 -> 4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41931651-0547-4ab8-88fc-9f4f4d8659ee', 'PRE.04', 3, 'numeric', 'Simplify, compare and find equivalent fractions', 'Write $\frac{24\times 35}{14\times 45}$ in simplest form without multiplying the top and bottom out first.', '[]', '4/3', '24*35/(14*45)', 'Break into primes: $24=2^3\times 3$, $35=5\times 7$, $14=2\times 7$, $45=3^2\times 5$. The top is $2^3\times 3\times 5\times 7$ and the bottom is $2\times 3^2\times 5\times 7$. Cancel $2$, $3$, $5$ and $7$ from both: $\frac{2^2}{3}=\frac{4}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/14=12/7, 35/45=7/9; 12/7*7/9=12/9=4/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8291c14a-c6ad-40a1-80bb-0210c2e8e45e', 'PRE.04', 3, 'choice', 'Simplify, compare and find equivalent fractions', 'Three of these fractions are equal to one another. Which one is NOT equal to the other three?', '["$\\frac{24}{40}$","$\\frac{12}{18}$","$\\frac{14}{21}$","$\\frac{20}{30}$"]', '$\frac{24}{40}$', NULL, 'Simplify each: $\frac{12}{18}=\frac{2}{3}$, $\frac{14}{21}=\frac{2}{3}$ and $\frac{20}{30}=\frac{2}{3}$, but $\frac{24}{40}=\frac{3}{5}$. So the odd one out is $\frac{24}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{24}{40}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/21=20/30=12/18=2/3; 24/40=3/5.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e928a4e0-3ca3-47b8-8e5b-1ae092e45119', 'PRE.04', 3, 'numeric', 'Simplify, compare and find equivalent fractions', 'Write $\frac{2^3\times 3^2\times 5}{2^2\times 3\times 5^2\times 7}$ in simplest form. What is the sum of the numerator and the denominator?', '[]', '41', '6+35', 'Cancel the shared factors $2^2$, $3$ and $5$: the top keeps $2\times 3=6$ and the bottom keeps $5\times 7=35$. The simplest form is $\frac{6}{35}$, and $6+35=41$.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cancel: 2*3/(5*7)=6/35; 6+35=41.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
