INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af4eb37b-cba0-4f8b-a32a-fc34766d56d9', 'PRE.04', 3, 'numeric', 'Add and subtract fractions', '$? + \frac{3}{8} = \frac{7}{10}$. What fraction is the ?', '[]', '13/40', '7/10-3/8', 'The ? equals $\frac{7}{10}-\frac{3}{8}$. With denominator 40: $\frac{28}{40}-\frac{15}{40}=\frac{13}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"13/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28/40-15/40=13/40.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
