INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e476e975-6e3a-4e20-8ad8-378b966fb8c5', 'PRE.04', 3, 'choice', 'Add and subtract fractions', 'Find the sum $\frac{1}{2}+\frac{1}{6}+\frac{1}{12}+\frac{1}{20}+\frac{1}{30}$.', '["$\\frac{1}{2}$","$\\frac{5}{6}$","$\\frac{3}{4}$","1"]', '$\frac{5}{6}$', NULL, 'Notice $\frac{1}{2}=1-\frac{1}{2}$, $\frac{1}{6}=\frac{1}{2}-\frac{1}{3}$, $\frac{1}{12}=\frac{1}{3}-\frac{1}{4}$, $\frac{1}{20}=\frac{1}{4}-\frac{1}{5}$, $\frac{1}{30}=\frac{1}{5}-\frac{1}{6}$. In the sum, the middle terms cancel and $1-\frac{1}{6}=\frac{5}{6}$ remains. Check by adding in order: $\frac{1}{2}+\frac{1}{6}=\frac{2}{3}$, then $\frac{3}{4}$, $\frac{4}{5}$, $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Telescoping: (1-1/2)+(1/2-1/3)+...+(1/5-1/6)=1-1/6=5/6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d82e0172-b6a1-465b-8fb6-c89ebaf0620f', 'PRE.04', 3, 'choice', 'Add and subtract fractions', 'What fraction must be added to $\frac{7}{12}$ to make $1\frac{1}{4}$?', '["$\\frac{3}{4}$","$\\frac{1}{2}$","$\\frac{2}{3}$","$\\frac{5}{6}$"]', '$\frac{2}{3}$', NULL, '$1\frac{1}{4}=\frac{5}{4}=\frac{15}{12}$. Then $\frac{15}{12}-\frac{7}{12}=\frac{8}{12}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/12-7/12=8/12=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b3f44e6-11d7-4ab6-93b0-735c6460d7f5', 'PRE.04', 3, 'choice', 'Add and subtract fractions', 'Which of these differences is the greatest?', '["$\\frac{1}{3}-\\frac{1}{4}$","$\\frac{1}{2}-\\frac{1}{3}$","$\\frac{1}{4}-\\frac{1}{5}$","$\\frac{1}{5}-\\frac{1}{6}$"]', '$\frac{1}{2}-\frac{1}{3}$', NULL, 'Each difference simplifies to a unit fraction: $\frac{1}{2}-\frac{1}{3}=\frac{1}{6}$, $\frac{1}{3}-\frac{1}{4}=\frac{1}{12}$, $\frac{1}{4}-\frac{1}{5}=\frac{1}{20}$, $\frac{1}{5}-\frac{1}{6}=\frac{1}{30}$. The largest is $\frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}-\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/(n(n+1)): 1/30, 1/20, 1/12, 1/6; greatest 1/2-1/3=1/6.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3281ab2d-2874-4c98-ae5e-b03bc7ad2149', 'PRE.04', 3, 'numeric', 'Add and subtract fractions', 'A water tank is $\frac{3}{4}$ full. Then water equal to $\frac{1}{3}$ of the whole tank is used, and after that water equal to $\frac{1}{8}$ of the whole tank is added. What fraction of the tank is full now?', '[]', '13/24', '3/4-1/3+1/8', 'Start with $\frac{3}{4}$, subtract $\frac{1}{3}$ and add $\frac{1}{8}$. In 24ths: $\frac{18}{24}-\frac{8}{24}+\frac{3}{24}=\frac{13}{24}$.', 'checked', '{"lint":[],"solve":{"answer":"13/24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24-8/24+3/24=13/24.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c34f2f0a-6ceb-47df-8690-42b5b0c8194d', 'PRE.04', 3, 'choice', 'Multiply fractions and find a fraction of a number', 'Find the product $\frac{1}{2}\times\frac{2}{3}\times\frac{3}{4}\times\frac{4}{5}\times\frac{5}{6}\times\frac{6}{7}$.', '["$\\frac{1}{6}$","$\\frac{1}{7}$","$\\frac{1}{2}$","$\\frac{6}{7}$"]', '$\frac{1}{7}$', NULL, 'Each top cancels with the bottom of the next fraction: the 2s, 3s, 4s, 5s and 6s all cancel. Only the first top, 1, and the last bottom, 7, remain, so the product is $\frac{1}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Telescoping product: 1/7.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
