INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180e78bb-29b8-4378-8228-3e813289a8e7', 'PRE.04', 3, 'numeric', 'Multiply fractions and find a fraction of a number', 'Three fourths of a number is the same as $\frac{5}{6}$ of $18$. What is the number?', '[]', '20', '5/6*18/(3/4)', '$\frac{5}{6}$ of 18 is 15. So three fourths of the number is 15, which means one fourth is 5 and the whole number is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6*18=15; 3/4 x=15 -> x=20.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c0e89eb-4a88-437c-873d-525a3dd049f6', 'PRE.04', 3, 'choice', 'Divide fractions and use reciprocals', 'A number divided by $\frac{2}{3}$ is $12$. What is the number?', '["18","9","16","8"]', '8', '12*2/3', 'Dividing by $\frac{2}{3}$ is multiplying by $\frac{3}{2}$, so $\text{number}\times\frac{3}{2}=12$. Undo it: $12\times\frac{2}{3}=8$. Check: $8\div\frac{2}{3}=12$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12*2/3=8.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7c76074-c9c9-497c-8c89-f112d9539595', 'PRE.04', 3, 'numeric', 'Divide fractions and use reciprocals', 'What is $\left(\frac{5}{6}\div\frac{1}{3}\right)\div\left(\frac{3}{4}\div\frac{1}{2}\right)$? Write the answer in simplest form.', '[]', '5/3', '(5/6/(1/3))/(3/4/(1/2))', 'First bracket: $\frac{5}{6}\times 3=\frac{5}{2}$. Second bracket: $\frac{3}{4}\times 2=\frac{3}{2}$. Then $\frac{5}{2}\div\frac{3}{2}=\frac{5}{2}\times\frac{2}{3}=\frac{5}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"5/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6*3=5/2; 3/4*2=3/2; (5/2)/(3/2)=5/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d67a6fb1-a53b-4e1c-a4ca-2e8b229e61c7', 'PRE.04', 3, 'numeric', 'Divide fractions and use reciprocals', 'Flour is sold in scoops of $\frac{3}{8}$ cup. How many full scoops can be made from $4\frac{1}{2}$ cups of flour, with none left over?', '[]', '12', '9/2/(3/8)', '$4\frac{1}{2}=\frac{9}{2}$. Then $\frac{9}{2}\div\frac{3}{8}=\frac{9}{2}\times\frac{8}{3}=\frac{72}{6}=12$ scoops.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/2*8/3=12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
