INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb3e2fb5-577c-41b9-8859-2425a2452c31', 'PRE.04', 3, 'choice', 'Divide fractions and use reciprocals', 'Which expression below has the greatest value?', '["$\\frac{1}{3}\\div\\frac{1}{2}$","$\\frac{1}{2}\\times\\frac{1}{3}$","$\\frac{1}{2}\\div\\frac{1}{3}$","$\\frac{1}{2}+\\frac{1}{3}$"]', '$\frac{1}{2}\div\frac{1}{3}$', NULL, '$\frac{1}{2}\div\frac{1}{3}=\frac{3}{2}$, $\frac{1}{3}\div\frac{1}{2}=\frac{2}{3}$, $\frac{1}{2}\times\frac{1}{3}=\frac{1}{6}$ and $\frac{1}{2}+\frac{1}{3}=\frac{5}{6}$. Only the first is greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}\\div\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6, 5/6, 3/2, 2/3: greatest 1/2 div 1/3 = 3/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('972f7cec-c77d-4a10-a2c9-9aa4de163c15', 'PRE.04', 3, 'choice', 'Divide fractions and use reciprocals', 'The area of a rectangle is $\frac{5}{6}$ square meter and its length is $\frac{5}{4}$ meter. What is its width, in meters?', '["$\\frac{2}{3}$","$\\frac{25}{24}$","$\\frac{3}{2}$","$\\frac{1}{2}$"]', '$\frac{2}{3}$', NULL, 'Area = length times width, so width = area $\div$ length $=\frac{5}{6}\div\frac{5}{4}=\frac{5}{6}\times\frac{4}{5}=\frac{4}{6}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 / 5/4 = 5/6*4/5=4/6=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
