VALUES ('a66e092a-9898-47c6-9b8a-4786854bfb21', 'PRE.04', 3, 'choice', 'Mixed numbers and improper fractions', 'What is $1\dfrac{3}{4}\times 2\dfrac{2}{7}$?', '["$2\\frac{3}{14}$","$4\\frac{1}{28}$","4","$3\\frac{1}{2}$"]', '4', '7/4*16/7', '$1\frac{3}{4}=\frac{7}{4}$ and $2\frac{2}{7}=\frac{16}{7}$. The product is $\frac{7\times 16}{4\times 7}=\frac{16}{4}=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/4*16/7=4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
