INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d348c43-53be-4110-a5d9-3dd4966e877c', 'PRE.04', 3, 'numeric', 'Mixed numbers and improper fractions', 'What is $3\dfrac{1}{3}+2\dfrac{1}{4}+1\dfrac{1}{6}$? Write the answer as a mixed number.', '[]', '6 3/4', '10/3+9/4+7/6', 'Wholes: $3+2+1=6$. Fractions in twelfths: $\frac{4}{12}+\frac{3}{12}+\frac{2}{12}=\frac{9}{12}=\frac{3}{4}$. The total is $6\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"6 3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 4/12+3/12+2/12 = 6 9/12 = 6 3/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
