INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7578fe9d-55b4-4247-8873-0121022e3068', 'PRE.04', 3, 'choice', 'Mixed numbers and improper fractions', 'What is $5-1\dfrac{2}{3}-2\dfrac{3}{4}$?', '["$1\\frac{7}{12}$","$\\frac{11}{12}$","$1\\frac{1}{2}$","$\\frac{7}{12}$"]', '$\frac{7}{12}$', NULL, 'Add what is taken away: $1\frac{2}{3}+2\frac{3}{4}=3+\frac{8}{12}+\frac{9}{12}=4\frac{5}{12}$. Then $5-4\frac{5}{12}=\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/12-20/12-33/12=7/12.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
