INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66870970-1c77-4c29-a770-ead1560a4408', 'PRE.04', 3, 'choice', 'Mixed numbers and improper fractions', 'Which of these numbers is the greatest?', '["$2\\frac{3}{5}$","$\\frac{5}{2}$","$\\frac{8}{3}$","$2\\frac{4}{7}$"]', '$\frac{8}{3}$', NULL, 'Write each as a number of whole units plus a fraction: $\frac{8}{3}=2\frac{2}{3}$, $2\frac{3}{5}$, $\frac{5}{2}=2\frac{1}{2}$ and $2\frac{4}{7}$. Compare the fractions: $\frac{2}{3}$ (about 0.67) is bigger than $\frac{3}{5}$ (0.6), $\frac{4}{7}$ (about 0.57) and $\frac{1}{2}$. So $\frac{8}{3}$ is greatest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.6, 2.5, 2.571..., 2.667: 8/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
