INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1eaa517-c689-4b79-bfc7-6af7487ef70d', 'PRE.04', 3, 'numeric', 'Mixed numbers and improper fractions', 'What number can be added to $3\dfrac{2}{5}$ to get $8\dfrac{1}{10}$? Write the answer as a mixed number.', '[]', '4 7/10', '81/10-17/5', 'Subtract: $8\frac{1}{10}-3\frac{2}{5}=8\frac{1}{10}-3\frac{4}{10}$. Borrow: $7\frac{11}{10}-3\frac{4}{10}=4\frac{7}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"4 7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81/10-34/10=47/10=4 7/10.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
