INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd61e9f2-bb05-422c-8cf7-ecd68eca38a2', 'PRE.04', 3, 'choice', 'Fractions within fractions (complex fractions)', 'What is the value of $1+\dfrac{1}{1+\dfrac{1}{1+\dfrac{1}{2}}}$?', '["$\\frac{5}{3}$","$\\frac{3}{5}$","$\\frac{8}{5}$","$\\frac{7}{4}$"]', '$\frac{8}{5}$', NULL, 'Work from the inside out. $1+\frac{1}{2}=\frac{3}{2}$. Then $\frac{1}{3/2}=\frac{2}{3}$, so the middle part is $1+\frac{2}{3}=\frac{5}{3}$. Then $\frac{1}{5/3}=\frac{3}{5}$, and finally $1+\frac{3}{5}=\frac{8}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+1/2=3/2; 1/(3/2)=2/3; 1+2/3=5/3; 1/(5/3)=3/5; 1+3/5=8/5.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8625b470-986a-44cc-bc83-7bea9e756c8b', 'PRE.04', 3, 'choice', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{\frac{1}{2}+\frac{1}{3}}{\frac{1}{2}-\frac{1}{3}}$?', '["1","5","$\\frac{5}{6}$","$\\frac{1}{5}$"]', '5', '(1/2+1/3)/(1/2-1/3)', 'The top is $\frac{3}{6}+\frac{2}{6}=\frac{5}{6}$. The bottom is $\frac{3}{6}-\frac{2}{6}=\frac{1}{6}$. Then $\frac{5}{6}\div\frac{1}{6}=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5/6)/(1/6)=5.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
