INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('973cedf0-e5b1-49c6-83d9-49ec2c6d1333', 'PRE.04', 3, 'numeric', 'Fractions within fractions (complex fractions)', 'Simplify $\dfrac{\frac{3}{4}-\frac{1}{6}}{\frac{1}{3}+\frac{1}{2}}$. Give your answer as a fraction.', '[]', '7/10', '(3/4-1/6)/(1/3+1/2)', 'The top is $\frac{9}{12}-\frac{2}{12}=\frac{7}{12}$. The bottom is $\frac{2}{6}+\frac{3}{6}=\frac{5}{6}$. Then $\frac{7}{12}\times\frac{6}{5}=\frac{42}{60}=\frac{7}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12-2/12=7/12; 2/6+3/6=5/6; 7/12*6/5=7/10.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
