INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f86e7b77-ecd0-47d9-be58-291e6a85125c', 'PRE.04', 3, 'numeric', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{2-\frac{1}{3}}{3-\frac{1}{2}}$? Write the answer in simplest form.', '[]', '2/3', '(2-1/3)/(3-1/2)', 'The top is $2-\frac{1}{3}=\frac{5}{3}$. The bottom is $3-\frac{1}{2}=\frac{5}{2}$. Then $\frac{5}{3}\div\frac{5}{2}=\frac{5}{3}\times\frac{2}{5}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5/3)/(5/2)=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
