INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1963b7ec-5af7-4c25-b186-8abbe9ed25fd', 'PRE.04', 3, 'choice', 'Fraction word problems and order of operations', 'Three friends share a pizza. The first eats $\frac{1}{3}$ of it, the second eats $\frac{1}{4}$ of it and the third eats $\frac{1}{5}$ of it. What fraction of the pizza is left?', '["$\\frac{13}{60}$","$\\frac{47}{60}$","$\\frac{3}{12}$","$\\frac{1}{12}$"]', '$\frac{13}{60}$', NULL, 'In 60ths: $\frac{20}{60}+\frac{15}{60}+\frac{12}{60}=\frac{47}{60}$ is eaten. So $1-\frac{47}{60}=\frac{13}{60}$ is left.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13}{60}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-(20+15+12)/60=13/60.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce1f8c08-bc0e-4935-b64a-fd43a87fc733', 'PRE.04', 3, 'choice', 'Fraction word problems and order of operations', '$\frac{3}{4}\times ?=\frac{2}{5}+\frac{1}{10}$. What fraction is the ?', '["$\\frac{1}{2}$","$\\frac{2}{3}$","$\\frac{3}{4}$","$\\frac{8}{15}$"]', '$\frac{2}{3}$', NULL, 'Add the right side first: $\frac{2}{5}+\frac{1}{10}=\frac{4}{10}+\frac{1}{10}=\frac{1}{2}$. Then ? $=\frac{1}{2}\div\frac{3}{4}=\frac{1}{2}\times\frac{4}{3}=\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5+1/10=1/2; ?=1/2*4/3=2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
