INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cfb8aa5-f05d-412a-b22e-7cd2707f05f5', 'PRE.04', 3, 'numeric', 'Fraction word problems and order of operations', 'A recipe uses $1\dfrac{1}{2}$ cups of flour to make $12$ muffins. How many cups of flour are needed for $20$ muffins? Write the answer as a mixed number.', '[]', '2 1/2', '3/2*20/12', '20 muffins is $\frac{20}{12}=\frac{5}{3}$ of the recipe. Then $\frac{5}{3}\times\frac{3}{2}=\frac{5}{2}=2\frac{1}{2}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/2*20/12=60/24=5/2=2 1/2.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
