VALUES ('02b38bfa-95f2-44a4-808d-290893446e67', 'PRE.05', 2, 'numeric', 'Write and solve an inequality for a word problem', 'Tom scored 76 and 82 on his first two tests. He wants an average of at least 80 over three tests. What is the lowest score he can get on the third test?', '[]', '82', '3*80-76-82', 'The three scores must add to at least $3\times80=240$. So $76+82+x\ge240$, which gives $158+x\ge240$ and $x\ge82$.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(76 + 82 + t)/3 >= 80, t >= 240 - 158 = 82.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b4eff6f-08e1-4770-b10f-fba6dadd92da', 'PRE.05', 2, 'numeric', 'Check a solution or find an unknown constant', 'The number 3 is a solution of $2x+k=15$. What is $k$?', '[]', '9', '15-6', 'Put $x=3$ into the equation: $6+k=15$. So $k=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + k = 15, k = 9.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b047e1c6-8e5d-412c-a75f-61eda65b475d', 'PRE.05', 2, 'choice', 'Check a solution or find an unknown constant', 'Which equation has $x=5$ as its solution?', '["$2x+7=15$","$4x-3=21$","$\\frac{x}{5}+3=5$","$3x-4=11$"]', '$3x-4=11$', NULL, 'Put $x=5$ into each: $3\times5-4=11$ is true. The others give 17, 17 and 4, which are not 15, 21 and 5.', 'checked', '{"lint":[],"solve":{"answer":"$3x-4=11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=5: 17, 4, 11 (true), 17. Only 3x-4=11.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
