INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e6e81c9-bf9c-491d-ba26-e23a6330cd10', 'PRE.05', 2, 'choice', 'Check a solution or find an unknown constant', 'Which of these inequalities is true when $x=-3$?', '["$5-x>7$","$2x+1>0$","$x+10<5$","$3x\\ge-6$"]', '$5-x>7$', NULL, 'For $x=-3$: $5-(-3)=8>7$ is true. The others become $-5>0$, $7<5$ and $-9\ge-6$, which are all false.', 'checked', '{"lint":[],"solve":{"answer":"$5-x>7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=-3: -9>=-6 no; 8>7 yes; 7<5 no; -5>0 no.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
