INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d13b950-64b7-4f2e-8da2-c8db320a5afc', 'PRE.05', 2, 'choice', 'Check a solution or find an unknown constant', 'For which value of $k$ is $x=3$ the solution of $kx+3=2x+9$?', '["$2$","$4$","$6$","$3$"]', '$4$', '(15-3)/3', 'Put $x=3$ in: $3k+3=6+9=15$. So $3k=12$ and $k=4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3k + 3 = 6 + 9 = 15, k = 4.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
