VALUES ('55aeb50b-7cdb-4fd1-96b3-2b3b12104728', 'PRE.05', 3, 'numeric', 'Solve a one- or two-step equation', 'Solve $\frac{3x-5}{2}=11$. What is $x$?', '[]', '9', '(11*2+5)/3', 'Multiply both sides by 2: $3x-5=22$. Add 5: $3x=27$. Divide by 3: $x=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 5 = 22, 3x = 27, x = 9.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
