INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('842f89ad-8e63-4852-a5ef-8d94a0ef7aff', 'PRE.05', 3, 'choice', 'Solve a one- or two-step equation', 'Which equation has the solution $x=-4$?', '["$3x+5=-7$","$3x+5=17$","$3x-5=-7$","$-3x+5=-7$"]', '$3x+5=-7$', NULL, 'Put $x=-4$ into $3x+5$: $3\times(-4)+5=-12+5=-7$, so the first equation works. The others give $x=4$, $x=-\frac{2}{3}$ and $x=4$.', 'checked', '{"lint":[],"solve":{"answer":"$3x+5=-7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x=-4: 3(-4)+5 = -7 true. Others: -3(-4)+5=17, 3(-4)+5=-7 not 17, 3(-4)-5=-17. Only one works.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
