INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9da2be1-882a-4a8f-b75f-fb7c395d69b8', 'PRE.05', 3, 'choice', 'Solve a one- or two-step equation', 'If $2x+3=11$, what is the value of $4x+6$?', '["$16$","$11$","$22$","$44$"]', '$22$', '2*11', 'Notice that $4x+6$ is twice $2x+3$, so $4x+6=2\times11=22$. (Or solve: $x=4$, and $4\times4+6=22$.)', 'checked', '{"lint":[],"solve":{"answer":"$22$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+6 = 2(2x+3) = 2*11 = 22.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
