INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b54be4ed-0cd6-490a-85d0-b7229e35ae33', 'PRE.05', 3, 'choice', 'Solve an equation with the variable on both sides', 'The expressions $4x+7$ and $9x-18$ have the same value for exactly one number $x$. What is that number?', '["$5$","$\\frac{11}{5}$","$-5$","$\\frac{25}{13}$"]', '$5$', '(7+18)/(9-4)', 'Set them equal: $4x+7=9x-18$. Subtract $4x$: $7=5x-18$. Add 18: $25=5x$. So $x=5$. Check: both are 27.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 = 5x, x = 5.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
