VALUES ('ad3cc415-43aa-4a49-ab92-242a97d89dad', 'PRE.05', 3, 'choice', 'Solve an equation with the variable on both sides', 'Solve $5-4x=7x+27$. What is $x$?', '["$2$","$-2$","$-\\frac{22}{3}$","$\\frac{32}{11}$"]', '$-2$', '(5-27)/11', 'Add $4x$ to both sides: $5=11x+27$. Subtract 27: $-22=11x$. So $x=-2$.', 'checked', '{"lint":[],"solve":{"answer":"$-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-22 = 11x, x = -2.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
