VALUES ('336cd6a0-8693-4e3b-bce2-1e2467ec7f55', 'PRE.05', 3, 'choice', 'Solve an equation with parentheses or fractions', 'Solve $\frac{x}{2}+4=\frac{x}{3}+6$. What is $x$?', '["$-12$","$\\frac{12}{5}$","$12$","$2$"]', '$12$', '36-24', 'Multiply every term by 6: $3x+24=2x+36$. Subtract $2x$: $x+24=36$. So $x=12$.', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 - x/3 = 2, x/6 = 2, x = 12.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
