INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6905d2a9-1e2e-4cb1-8f8b-507906c2b14d', 'PRE.05', 3, 'choice', 'Solve an equation with parentheses or fractions', 'Solve $3(2x-1)-2(x+4)=17$. What is $x$?', '["$3$","$\\frac{3}{2}$","$6$","$7$"]', '$7$', '(17+11)/4', 'Distribute: $6x-3-2x-8=17$, so $4x-11=17$. Then $4x=28$ and $x=7$.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 3 - 2x - 8 = 17, 4x - 11 = 17, 4x = 28, x = 7.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
