INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62a4cda5-ecb7-4008-9579-1a593d6affd3', 'PRE.05', 3, 'numeric', 'Solve an equation with parentheses or fractions', 'Solve $\frac{2x-1}{3}=\frac{x+3}{2}$. What is $x$?', '[]', '11', '9+2', 'Multiply both sides by 6: $2(2x-1)=3(x+3)$. So $4x-2=3x+9$, and $x=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(2x-1) = 3(x+3), 4x - 2 = 3x + 9, x = 11.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
