INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28fbb99f-f0c0-4d05-b44e-22cf146cda0b', 'PRE.05', 3, 'choice', 'Solve an equation with parentheses or fractions', 'Solve $5-(x-3)=2(x+1)-6$.', '["$4$","$2$","$12$","$-4$"]', '$4$', '12/3', 'The left side is $5-x+3=8-x$. The right side is $2x+2-6=2x-4$. So $8-x=2x-4$, giving $12=3x$ and $x=4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - x = 2x - 4, 12 = 3x, x = 4.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
