INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19c787f9-501a-4105-9de9-c6ee2329f20f', 'PRE.05', 3, 'numeric', 'Write an equation for a word problem and solve it', 'In 5 years Jo will be twice as old as she was 4 years ago. How old is Jo now?', '[]', '13', '5+8', 'Let Jo be $x$ years old now. Then $x+5=2(x-4)$, so $x+5=2x-8$. So $x=13$. Check: in 5 years she is 18, and 4 years ago she was 9.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 5 = 2(x - 4), x + 5 = 2x - 8, x = 13. Check: 18 = 2*9.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26609279-af0d-47e8-ada6-6023cdd66408', 'PRE.05', 3, 'choice', 'Write an equation for a word problem and solve it', 'Pens cost 3 dollars each and notebooks cost 5 dollars each. Kim buys 4 more pens than notebooks and spends 52 dollars in all. How many notebooks does she buy?', '["$5$","$9$","$\\frac{13}{2}$","$8$"]', '$5$', '(52-12)/8', 'Let $n$ be the notebooks. Then she buys $n+4$ pens, and $3(n+4)+5n=52$. So $8n+12=52$, $8n=40$ and $n=5$.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n notebooks, n+4 pens: 5n + 3(n+4) = 52, 8n = 40, n = 5. Check 25 + 27 = 52.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bbdec1a-b290-4b82-9308-7ef9f7502f8e', 'PRE.05', 3, 'choice', 'Write an equation for a word problem and solve it', 'Candle A is 30 cm tall and burns down 2 cm every hour. Candle B is 24 cm tall and burns down 1 cm every hour. After how many hours are the two candles the same height?', '["$3$","$6$","$18$","$54$"]', '$6$', '30-24', 'After $t$ hours the heights are $30-2t$ and $24-t$. Set them equal: $30-2t=24-t$. So $6=t$. Check: both are 18 cm tall.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 - 2t = 24 - t, t = 6 (both 18 cm).","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1472d9a-3a33-42f7-9264-1d43d567c491', 'PRE.05', 3, 'choice', 'Write an equation for a word problem and solve it', 'Ben has 3 times as many cards as Cy. Ben gives away 10 cards, and then they have the same number. If Cy has $c$ cards, which equation matches this?', '["$3c+10=c$","$3c-10=c$","$3(c-10)=c$","$c-10=3c$"]', '$3c-10=c$', NULL, 'Ben starts with $3c$ cards. After giving away 10 he has $3c-10$. This equals Cy''s $c$, so $3c-10=c$.', 'checked', '{"lint":[],"solve":{"answer":"$3c-10=c$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ben 3c, after giving away 10: 3c - 10 = c. (c=5, Ben 15 -> 5.)","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
