INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95536b96-1d0c-420d-bb3d-5de92c1541fa', 'PRE.05', 3, 'numeric', 'Write an equation for a word problem and solve it', 'A farm has only chickens (2 legs each) and cows (4 legs each). There are 20 animals and 56 legs in all. How many chickens are there?', '[]', '12', '(80-56)/2', 'Let $c$ be the chickens. Then there are $20-c$ cows, and $2c+4(20-c)=56$. So $80-2c=56$, $2c=24$ and $c=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cows w: 2(20-w) + 4w = 56, 40 + 2w = 56, w = 8, chickens 12.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
