INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('709cdd33-31cb-4798-a843-e0df0a716886', 'PRE.05', 3, 'choice', 'Solve a linear inequality', 'Which inequality is the solution of $2(x-3)\le5x+9$?', '["$x\\ge-5$","$x\\le-5$","$x\\ge-4$","$x\\ge5$"]', '$x\ge-5$', NULL, 'Distribute: $2x-6\le5x+9$. Subtract $2x$: $-6\le3x+9$. Subtract 9: $-15\le3x$. Divide by 3: $-5\le x$, which is $x\ge-5$.', 'checked', '{"lint":[],"solve":{"answer":"$x\\ge-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 6 <= 5x + 9, -15 <= 3x, x >= -5.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
