VALUES ('7f164f95-19d4-4056-82c1-112d9ce87d4b', 'PRE.05', 3, 'choice', 'Solve a linear inequality', 'Add up all the whole numbers $x$ for which $3x-4\le11$. (Zero counts as a whole number.) What is the sum?', '["$10$","$21$","$15$","$5$"]', '$15$', '0+1+2+3+4+5', 'Add 4: $3x\le15$, so $x\le5$. The whole numbers are 0, 1, 2, 3, 4, 5, and their sum is 15.', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x <= 15, x <= 5; 0+1+2+3+4+5 = 15.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
