INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e135bdee-ceff-4b5c-9c1c-39e13a3014c2', 'PRE.05', 3, 'choice', 'Solve an inequality with a negative coefficient', 'Which inequality is the solution of $3-2x\ge x+15$?', '["$x\\ge-4$","$x\\le-4$","$x\\le4$","$x\\ge4$"]', '$x\le-4$', NULL, 'Add $2x$: $3\ge3x+15$. Subtract 15: $-12\ge3x$. Divide by 3: $-4\ge x$, which is $x\le-4$.', 'checked', '{"lint":[],"solve":{"answer":"$x\\le-4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-12 >= 3x, x <= -4.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
