INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5ee43c6-c59d-4b8d-abb7-5aa749582333', 'PRE.05', 3, 'choice', 'Solve an inequality with a negative coefficient', 'How many whole numbers $x$ satisfy both $2x-1>5$ and $-x\ge-8$?', '["$6$","$4$","$3$","$5$"]', '$5$', '8-4+1', 'The first gives $x>3$. The second gives $x\le8$ (the sign reverses). The whole numbers 4, 5, 6, 7, 8 satisfy both, which is 5 numbers.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x > 3 and x <= 8: 4,5,6,7,8 = 5 numbers.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
