INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4818db5-03fd-4ef4-ba13-b5a2d21c2363', 'PRE.05', 3, 'choice', 'Solve an inequality with a negative coefficient', 'Which statement about the inequality $-4x<12$ is true?', '["$x=-3$ is a solution","$x=-4$ is a solution","$x=-2$ is a solution","$x=-5$ is a solution"]', '$x=-2$ is a solution', NULL, 'Dividing by $-4$ reverses the sign: $x>-3$. So $-2$ works. Check: $-4\times(-2)=8<12$. But $-4\times(-3)=12$ is not less than 12, and $-4$ and $-5$ give 16 and 20.', 'checked', '{"lint":[],"solve":{"answer":"$x=-2$ is a solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x > -3. -2 works; -5, -4, -3 do not (at -3, 12 < 12 false).","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2ec5540-730b-40c1-b895-e3bc1f2d314a', 'PRE.05', 3, 'numeric', 'Solve an inequality with a negative coefficient', 'Find the sum of all integers $x$ for which both $-2x\le6$ and $x-1<4$.', '[]', '4', '4', 'The first gives $x\ge-3$ (the sign reverses). The second gives $x<5$. The integers are $-3,-2,-1,0,1,2,3,4$. Pairs $-3$ and 3, $-2$ and 2, $-1$ and 1 cancel, leaving $0+4=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x >= -3 and x < 5: -3..4, sum = 4.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be0d68f0-c3cd-4de4-841c-4073641e63cf', 'PRE.05', 3, 'numeric', 'Write and solve an inequality for a word problem', 'Zoe has 90 dollars and must keep 15 dollars for the bus. Jackets cost 24 dollars each. What is the greatest number of jackets she can buy?', '[]', '3', '3', 'She can spend $90-15=75$ dollars. So $24j\le75$, which gives $j\le3.125$. The greatest whole number is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24j <= 75, j <= 3.125, so 3.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
