INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e190727-24eb-479b-a533-f8b9d7a79974', 'PRE.05', 3, 'numeric', 'Write and solve an inequality for a word problem', 'A rectangle has a width of $w$ cm and a length that is 4 cm more than its width. Its perimeter must be less than 50 cm. What is the greatest whole number of centimeters the width can be?', '[]', '10', '10', 'The perimeter is $2(w+w+4)=4w+8$. We need $4w+8<50$, so $4w<42$ and $w<10.5$. The greatest whole number is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(w + w + 4) < 50, 4w + 8 < 50, w < 10.5, so 10.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b4c9f05-3bad-449c-bf15-c928bdeb3341', 'PRE.05', 3, 'choice', 'Write and solve an inequality for a word problem', 'Three more than twice a number is at most 4 less than five times the number. Which inequality matches this?', '["$2n+3\\ge5n-4$","$2n+3\\le5n-4$","$2n+3\\le5n+4$","$3(2n)\\le5n-4$"]', '$2n+3\le5n-4$', NULL, '"Three more than twice a number" is $2n+3$. "4 less than five times the number" is $5n-4$. "At most" means $\le$. So $2n+3\le5n-4$.', 'checked', '{"lint":[],"solve":{"answer":"$2n+3\\le5n-4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n + 3 <= 5n - 4.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
