INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39ffe3f7-b259-43ae-a731-1baa802184c7', 'PRE.06', 3, 'choice', 'Multiply decimals', 'A wall is 2.5 meters high and 3.2 meters wide. Paint costs 1.5 dollars for each square meter. How many dollars does it cost to paint the whole wall?', '["$8$","$8.55$","$12$","$120$"]', '$12$', '2.5*3.2*1.5', 'The area is $2.5\times3.2=8$ square meters. The cost is $8\times1.5=12$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 2.5*3.2 = 8 m^2; 8*1.5 = 12.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
