VALUES ('c06551e7-4d7c-474e-8571-230a7207c84a', 'PRE.06', 3, 'choice', 'Round decimals', 'Which of these numbers is 2.50 when rounded to the nearest hundredth?', '["$2.516$","$2.486$","$2.504$","$2.56$"]', '$2.504$', '2.504', '2.504 has thousandths digit 4, so it rounds down to 2.50. The others round to 2.52, 2.49 and 2.56.', 'checked', '{"lint":[],"solve":{"answer":"$2.504$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.486->2.49, 2.516->2.52, 2.56, 2.504->2.50.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
