INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51dd87b8-01a5-4b3a-a9df-a6f798fa9ce8', 'PRE.06', 3, 'choice', 'Convert a fraction to a decimal', 'Which of these fractions is equal to a decimal that repeats forever?', '["$\\frac{7}{16}$","$\\frac{7}{40}$","$\\frac{7}{25}$","$\\frac{7}{12}$"]', '$\frac{7}{12}$', NULL, 'A fraction in lowest terms ends in a decimal only if its bottom number has no prime factors except 2 and 5. The numbers 16, 40 and 25 do not. But $12=4\times3$ has the factor 3, so $\frac{7}{12}=0.58\overline{3}$ repeats.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Denominators 40, 16, 25 have only 2s and 5s (terminate); 12 has a 3 and 7/12 is in lowest terms, so it repeats: 0.58333...","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
