INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bccd968a-efa4-4674-ad62-b83527e8551c', 'PRE.06', 3, 'choice', 'Convert a fraction to a decimal', 'Which of these is the greatest?', '["$0.\\overline{6}$","$\\frac{5}{8}$","$0.62$","$\\frac{3}{5}$"]', '$0.\overline{6}$', NULL, 'As decimals: $0.\overline{6}=0.666\ldots$, $\frac{5}{8}=0.625$, $0.62$ and $\frac{3}{5}=0.6$. The greatest is $0.\overline{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$0.\\overline{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6, 0.625, 0.62, 0.666...; greatest 0.(6).","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
