INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4eff6a87-26c0-413f-b665-0378841fb438', 'PRE.06', 3, 'numeric', 'Convert a fraction to a decimal', 'The fraction $\frac{3}{7}$ is the repeating decimal $0.428571428571\ldots$ What is the 20th digit after the decimal point?', '[]', '2', '2', 'The digits 428571 repeat in blocks of 6. $20=3\times6+2$, so the 20th digit is the 2nd digit of the block, which is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period 428571 has length 6; 20 = 3*6 + 2, so the 2nd digit: 2.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
