INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('549ab692-e3e6-4284-b11b-278239fb3f73', 'PRE.06', 3, 'choice', 'Turn a repeating decimal into a fraction', 'Write $0.1\overline{6}$ as a fraction in lowest terms.', '["$\\frac{1}{6}$","$\\frac{16}{99}$","$\\frac{8}{45}$","$\\frac{1}{16}$"]', '$\frac{1}{6}$', NULL, '$0.1\overline{6}=0.1+0.0\overline{6}$. Now $0.0\overline{6}$ is $0.\overline{6}$ divided by 10, which is $\frac{2}{3}\div10=\frac{1}{15}$. So the sum is $\frac{1}{10}+\frac{1}{15}=\frac{3}{30}+\frac{2}{30}=\frac{5}{30}=\frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0.1666..., 10x = 1.666..., 100x = 16.666..., 90x = 15, x = 1/6.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
