INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('516aaa67-5f8f-432a-b0c7-4675385ac604', 'PRE.06', 3, 'choice', 'Turn a repeating decimal into a fraction', 'Write $0.4\overline{3}$ as a fraction in lowest terms.', '["$\\frac{43}{99}$","$\\frac{13}{30}$","$\\frac{43}{90}$","$\\frac{4}{9}$"]', '$\frac{13}{30}$', NULL, '$0.4\overline{3}=0.4+0.0\overline{3}$. We have $0.0\overline{3}=0.\overline{3}\div10=\frac{1}{30}$. So the sum is $\frac{4}{10}+\frac{1}{30}=\frac{12}{30}+\frac{1}{30}=\frac{13}{30}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13}{30}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0.4333..., 100x - 10x = 43 - 4 = 39, x = 39/90 = 13/30.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
