INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f89c2e26-df55-4dc7-a3c2-f44030abb207', 'PRE.06', 3, 'choice', 'Turn a repeating decimal into a fraction', 'What is the value of $0.\overline{9}$?', '["$\\frac{9}{10}$","$1$","$\\frac{99}{100}$","$\\frac{9}{11}$"]', '$1$', NULL, '$0.\overline{9}=9\times0.\overline{1}=9\times\frac{1}{9}=1$. The decimal $0.999\ldots$ goes on forever and is exactly equal to 1.', 'checked', '{"lint":[],"solve":{"answer":"$1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.(9) = 9/9 = 1.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
