INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65f75c46-bde2-44fd-a24c-3f63bc75c5d1', 'PRE.06', 3, 'choice', 'Solve word problems with decimals', 'A 0.5 liter bottle of juice costs 1.20 dollars. A 1.5 liter bottle costs 3.30 dollars. How many dollars less does a liter cost in the bigger bottle?', '["$0.1$","$2.2$","$0.2$","$2.4$"]', '$0.2$', '1.2/0.5-3.3/1.5', 'The small bottle costs $1.20\div0.5=2.40$ dollars a liter. The big bottle costs $3.30\div1.5=2.20$ dollars a liter. The difference is $0.20$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$0.2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Small: 1.20/0.5 = 2.40 per liter; big: 3.30/1.5 = 2.20 per liter; difference 0.20.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
