INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('745d9285-1fb8-41ea-9653-5b2d70d25579', 'PRE.06', 3, 'numeric', 'Solve word problems with decimals', 'Zara buys 3.5 kilograms of oranges at 2.20 dollars a kilogram and 2.25 kilograms of grapes at 4 dollars a kilogram. She pays with a 20 dollar bill. How many dollars change does she get?', '[]', '3.3', '20-(3.5*2.2+2.25*4)', 'Oranges: $3.5\times2.20=7.70$ dollars. Grapes: $2.25\times4=9$ dollars. Total: $16.70$ dollars. Change: $20-16.70=3.30$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"3.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.5*2.20 = 7.70; 2.25*4 = 9.00; total 16.70; change 3.30.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
