INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b63ba176-bfe1-4057-9629-ab4c4f8e9b3f', 'PRE.06', 3, 'choice', 'Solve word problems with decimals', 'Three numbers add up to 12.3. The second number is 1.5 more than the first, and the third is twice the first. What is the first number?', '["$3.075$","$10.8$","$5.4$","$2.7$"]', '$2.7$', '(12.3-1.5)/4', 'Call the first number $x$. The three are $x$, $x+1.5$ and $2x$, and they add to $4x+1.5=12.3$. So $4x=10.8$ and $x=2.7$. Check: $2.7+4.2+5.4=12.3$.', 'checked', '{"lint":[],"solve":{"answer":"$2.7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (x+1.5) + 2x = 12.3, 4x = 10.8, x = 2.7.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17ada69c-cb62-4586-9b61-c1e364744b65', 'PRE.06', 3, 'numeric', 'Solve word problems with decimals', 'Mia has 15 dollars. She buys 4 notebooks at 2.95 dollars each, and then spends all the rest of her money on stickers that cost 0.40 dollars each. How many stickers does she buy?', '[]', '8', '(15-4*2.95)/0.4', 'The notebooks cost $4\times2.95=11.80$ dollars. That leaves $15-11.80=3.20$ dollars. $3.20\div0.40=8$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*2.95 = 11.80; 15 - 11.80 = 3.20; 3.20/0.40 = 8.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
