INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2706d08-1031-4736-9cc3-b12df772b684', 'PRE.07', 2, 'choice', 'Ratios and fractions of a whole', 'At a show the ratio of adults to children is $3:7$. There are 21 adults. How many people are there in all?', '["70","49","28","63"]', '70', '21/3*10', '21 adults is 3 parts, so 1 part is 7 people. There are $3+7=10$ parts in all: $10\times 7=70$ people. (49 is only the children.)', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21/3=7 per part, children 49, total 70","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
