INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e1c3882-9d65-492f-92dd-3044a7cd3635', 'PRE.07', 2, 'choice', 'Ratios and fractions of a whole', 'The ratio of cats to dogs in a town is $3:5$. Which statement must be true?', '["Cats are $\\frac{3}{5}$ of all the animals","There are more cats than dogs","There are exactly 8 animals","For every 3 cats there are 5 dogs"]', 'For every 3 cats there are 5 dogs', NULL, 'A ratio $3:5$ compares cats to dogs: for every 3 cats there are 5 dogs. Cats and dogs together make 8 parts, so cats are $\frac{3}{8}$ of them, not $\frac{3}{5}$. There are fewer cats than dogs, and the ratio does not say how many animals there are.', 'checked', '{"lint":[],"solve":{"answer":"For every 3 cats there are 5 dogs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a 3:5 ratio means for every 3 cats there are 5 dogs; cats are 3/8 of animals, fewer cats, total unknown","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
