INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9ed48f1-834f-413b-9477-d982a009c89c', 'PRE.07', 2, 'choice', 'Work problems', 'Ann can paint a room in 6 hours. Bo can paint the same room in 3 hours. What fraction of the room do they paint together in 1 hour?', '["$\\frac{2}{9}$","$\\frac{1}{9}$","$\\frac{1}{3}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, 'In 1 hour Ann paints $\frac{1}{6}$ and Bo paints $\frac{1}{3}=\frac{2}{6}$. Together: $\frac{1}{6}+\frac{2}{6}=\frac{3}{6}=\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6+1/3=1/2","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
