INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd1f10e3-63f9-43d6-8b03-76292c057620', 'PRE.07', 3, 'numeric', 'Ratios and fractions of a whole', 'In a bag, the ratio of red beads to green beads is $7:4$. There are 15 more red beads than green beads. How many green beads are there?', '[]', '20', '15/3*4', 'The difference between the ratio numbers is $7-4=3$ parts, and that is 15 beads, so 1 part is 5 beads. Green is 4 parts: $4\times 5=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"difference 3 parts=15, part 5, green 20","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
