VALUES ('c771f30f-3795-4e32-aa96-e53a48bf9be6', 'PRE.07', 3, 'choice', 'Ratios and fractions of a whole', 'The ratio of $a$ to $b$ is $2:3$ and the ratio of $b$ to $c$ is $4:5$. What is the ratio of $a$ to $c$?', '["$2:5$","$8:15$","$10:12$","$6:5$"]', '$8:15$', NULL, 'Make the $b$ parts match: $a:b=8:12$ and $b:c=12:15$. So $a:c=8:15$.', 'checked', '{"lint":[],"solve":{"answer":"$8:15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a:b=8:12, b:c=12:15, a:c=8:15","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
