INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2643752-e73c-48d2-93d0-a71419015322', 'PRE.07', 3, 'numeric', 'Ratios and fractions of a whole', 'A jar holds dimes and nickels in the ratio $3:2$. Their total value is 2.00 dollars. How many dimes are in the jar?', '[]', '15', '15', 'Each group of 3 dimes and 2 nickels is worth $30+10=40$ cents. 200 cents is $200\div 40=5$ groups, so there are $5\times 3=15$ dimes.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3k dimes, 2k nickels: 30k+10k=200 cents -> k=5, 15 dimes","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
