INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6ef97cf-6fb0-4a4a-bda4-2865e204119b', 'PRE.07', 3, 'choice', 'Ratios and fractions of a whole', 'In a club the ratio of boys to girls is $3:5$. After 4 more boys join, the numbers of boys and girls are equal. How many girls are in the club?', '["6","16","10","20"]', '10', '10', 'Before: $3k$ boys and $5k$ girls. Then $3k+4=5k$, so $k=2$. There are $5\times 2=10$ girls.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3k+4=5k, k=2, girls 10","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
