VALUES ('f574d49e-6f45-4bd7-85de-31ff09968166', 'PRE.07', 3, 'choice', 'Rates and unit rates', 'A reader reads 12 pages in 8 minutes. At that rate, how many minutes does it take to read a 90-page book?', '["135","720","60","6"]', '60', '90/12*8', 'She reads $12\div 8=1.5$ pages a minute. $90\div 1.5=60$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5 pages/min; 90/1.5=60","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
