INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ed72786-6361-447f-93d4-944b0bc912c6', 'PRE.07', 3, 'numeric', 'Rates and unit rates', 'A tub holds 90 liters. A tap adds 5 liters every 20 seconds while a drain removes 2 liters every 20 seconds. Starting empty with both open, how many minutes does it take to fill the tub?', '[]', '10', '90/3*20/60', 'Every 20 seconds the water level rises by $5-2=3$ liters. 90 liters needs $90\div 3=30$ such periods, which is $30\times 20=600$ seconds, or 10 minutes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"net 3 L per 20 s = 9 L/min; 90/9=10","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
