INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0c81f57-e6e9-479f-ada9-a3c83f9b4f21', 'PRE.07', 3, 'numeric', 'Speed, distance and time', 'Two trains start 300 miles apart and drive toward each other, one at 40 miles per hour and the other at 60 miles per hour. How many hours pass before they meet?', '[]', '3', '300/(40+60)', 'Together they close the gap by $40+60=100$ miles each hour. $300\div 100=3$ hours.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"closing 100 mph; 300/100=3","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
