INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a67b2330-5bf1-4dbf-8b3d-af34468b426c', 'PRE.07', 3, 'choice', 'Speed, distance and time', 'A driver goes 60 miles at 30 miles per hour and then 60 miles at 60 miles per hour. What is her average speed for the whole 120 miles, in miles per hour?', '["45","50","30","40"]', '40', '120/(60/30+60/60)', 'The first part takes $60\div 30=2$ hours and the second takes $60\div 60=1$ hour. 120 miles in 3 hours is $120\div 3=40$ miles per hour. (It is not 45, the average of the two speeds.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 h + 1 h = 3 h; 120/3=40","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
