INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd69124a-d76d-4790-ac0f-271939b13e4a', 'PRE.07', 3, 'choice', 'Speed, distance and time', 'A walker starts at 6 kilometers per hour. Exactly 2 hours later a cyclist leaves the same place on the same path at 18 kilometers per hour. How many hours after the cyclist leaves does the cyclist catch up?', '["1","2","12","0.5"]', '1', '12/(18-6)', 'The walker has a head start of $6\times 2=12$ kilometers. The cyclist gains $18-6=12$ kilometers each hour, so catches up in $12\div 12=1$ hour.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"walker 12 km ahead; gain 12 km/h; 1 hour","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
