INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d42bf8a-3cd1-4f47-b1a1-40c072676ab1', 'PRE.07', 3, 'choice', 'Speed, distance and time', 'Kim walks to school at 4 miles per hour and walks home the same 2.4-mile way at 6 miles per hour. How many minutes does she walk in total?', '["50","60","72","30"]', '60', '2.4/4*60+2.4/6*60', 'To school: $2.4\div 4=0.6$ hour, which is 36 minutes. Home: $2.4\div 6=0.4$ hour, which is 24 minutes. Total: $36+24=60$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4/4=0.6 h=36 min; 2.4/6=0.4 h=24 min; total 60","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
