INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('246824c1-0e99-4bd3-818d-6d684d1050f0', 'PRE.07', 3, 'choice', 'Speed, distance and time', 'Car A leaves town at 1:00 pm and drives at 50 miles per hour. Car B leaves the same town at 2:00 pm on the same road and drives at 70 miles per hour. At what time does Car B catch up with Car A?', '["4:00 pm","3:30 pm","4:30 pm","5:00 pm"]', '4:30 pm', NULL, 'At 2:00 pm Car A is already 50 miles ahead. Car B gains $70-50=20$ miles each hour, so it needs $50\div 20=2.5$ hours. 2:00 pm plus 2 hours 30 minutes is 4:30 pm.', 'checked', '{"lint":[],"solve":{"answer":"4:30 pm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"at 2 pm A is 50 mi ahead; gains 20 mph; 2.5 h -> 4:30 pm","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
