INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ede4f3d3-7c26-453c-bdfa-e8974ad41515', 'PRE.07', 3, 'numeric', 'Speed, distance and time', 'A boat travels 12 miles upstream in 3 hours and 12 miles back downstream in 2 hours. The boat''s own speed in still water and the speed of the current both stay the same. What is the boat''s speed in still water, in miles per hour?', '[]', '5', '(12/3+12/2)/2', 'Upstream the boat goes $12\div 3=4$ miles per hour, and downstream $12\div 2=6$ miles per hour. The still-water speed is halfway between them: $(4+6)\div 2=5$ miles per hour (the current is 1).', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"upstream 4 mph, downstream 6 mph; boat=(4+6)/2=5","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
