INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8fffb9d-02cd-4208-80bc-b438e53e2a73', 'PRE.07', 3, 'choice', 'Speed, distance and time', 'A train 150 meters long travels at 20 meters per second through a tunnel that is 250 meters long. How many seconds pass from the moment the front of the train enters the tunnel until the back of the train leaves it?', '["12.5","7.5","17.5","20"]', '20', '(150+250)/20', 'The train must travel the tunnel length plus its own length: $250+150=400$ meters. At 20 meters per second this takes $400\div 20=20$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"distance 250+150=400 m; 400/20=20 s","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
