INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99b1a43f-98ad-4048-ba51-43e1cbb00248', 'PRE.07', 3, 'choice', 'Work problems', 'Worker A can finish a job in 6 hours and worker B can finish it in 3 hours. How many hours do they take working together?', '["2","9","4.5","3"]', '2', '1/(1/6+1/3)', 'A does $\frac{1}{6}$ of the job an hour and B does $\frac{1}{3}=\frac{2}{6}$. Together they do $\frac{3}{6}=\frac{1}{2}$ an hour, so the job takes 2 hours.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6+1/3=1/2 per hour -> 2 h","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
