INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb71b383-2590-4b78-aa00-59db506e6e19', 'PRE.07', 3, 'choice', 'Work problems', 'Together, A and B finish a job in 4 hours. A alone would take 12 hours. How many hours would B take alone?', '["8","6","3","16"]', '6', '1/(1/4-1/12)', 'Together they do $\frac{1}{4}$ of the job an hour and A does $\frac{1}{12}$, so B does $\frac{1}{4}-\frac{1}{12}=\frac{2}{12}=\frac{1}{6}$ an hour. B takes 6 hours.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4-1/12=2/12=1/6 -> 6","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65d5aa83-2b40-4a8c-8a36-546c6eae4476', 'PRE.07', 3, 'numeric', 'Work problems', 'Pipe A fills a pool in 2 hours and pipe B fills it in 6 hours. A drain empties a full pool in 3 hours. With both pipes and the drain open, how many hours does it take to fill the empty pool?', '[]', '3', '1/(1/2+1/6-1/3)', 'Each hour A adds $\frac{1}{2}$, B adds $\frac{1}{6}$ and the drain removes $\frac{1}{3}$. Net: $\frac{3}{6}+\frac{1}{6}-\frac{2}{6}=\frac{2}{6}=\frac{1}{3}$ of the pool an hour, so 3 hours.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2+1/6-1/3=3/6+1/6-2/6=1/3 -> 3 h","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
