INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9fede1d-935f-4b53-83ca-6b99a9d1fd89', 'PRE.07', 3, 'numeric', 'Work problems', '3 painters paint 2 houses in 12 days. All painters work at the same pace. How many days do 6 painters need to paint 4 houses?', '[]', '12', '12/2*2', '3 painters paint 2 houses in 12 days. 6 painters (twice as many) would paint those 2 houses in 6 days, and 4 houses is twice the work, so it takes $6\times 2=12$ days.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 painter-days for 2 houses = 18 per house; 4 houses=72; 72/6=12","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
