INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74e8c59a-4baf-4d93-8bc4-410629bca5fe', 'PRE.07', 3, 'choice', 'Work problems', 'Ali can wash a car in 20 minutes and Beth can wash a car in 30 minutes. Working together, how many minutes do they need to wash 5 cars?', '["125","50","60","75"]', '60', '5/(1/20+1/30)', 'Together they wash $\frac{1}{20}+\frac{1}{30}=\frac{3}{60}+\frac{2}{60}=\frac{5}{60}=\frac{1}{12}$ of a car a minute, so one car takes 12 minutes. 5 cars take $5\times 12=60$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/20+1/30=1/12 car/min; 5 cars = 60 min","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
