INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28481bc7-6e1e-42b1-b654-d3beb8ae4bfe', 'PRE.08', 3, 'numeric', 'Percent of a number', 'A store has 80 shirts. 35% are red. Half of the shirts that are not red are blue. How many shirts are neither red nor blue?', '[]', '26', '80*0.65/2', '35% of 80 is 28 red shirts, so 52 are not red. Half of 52 is 26 blue, so $52-26=26$ are neither red nor blue.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"red 28; not red 52; blue 26; neither 26","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
