VALUES ('baba4348-aff1-4379-a782-64909d70d175', 'PRE.08', 3, 'choice', 'Finding what percent one number is of another', 'What percent of 45 is 0.9?', '["0.2%","2%","20%","50%"]', '2%', NULL, '$\frac{0.9}{45}=0.02$, which is 2%.', 'checked', '{"lint":[],"solve":{"answer":"2%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.9/45=0.02=2%","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
