INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2460af23-a080-49cb-9444-240fd0fbc941', 'PRE.08', 3, 'choice', 'Successive percent changes', 'An 80-dollar coat is 30% off. Then a 10% sales tax is added to the sale price. What is the total cost in dollars?', '["56","61.6","64","88"]', '61.6', '80*0.7*1.1', '30% off makes the price $80\times 0.7=56$ dollars. The 10% tax is 5.6 dollars, so the total is $56+5.6=61.6$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"61.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80*0.7=56; 56*1.1=61.6","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
