INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('161cfd7e-120f-4242-90f7-f6e12476dd90', 'PRE.08', 3, 'choice', 'Successive percent changes', 'A store takes 20% off a price and then takes 30% off the new price. This is the same as one discount of what percent?', '["50%","56%","44%","10%"]', '44%', NULL, 'Start with 100. After 20% off: 80. Then 30% of 80 is 24, leaving 56. The total taken off is $100-56=44$, which is 44%.', 'checked', '{"lint":[],"solve":{"answer":"44%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8*0.7=0.56, discount 44%","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
