INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e04f6780-89d0-4560-b2cd-d4380866e1b1', 'PRE.08', 3, 'numeric', 'Successive percent changes', 'A price goes up by 25%. By what percent must the new price then be lowered to get back to the original price? Give the number only.', '[]', '20', '(1.25-1)/1.25*100', 'Start with 100. After the 25% rise it is 125. To get back to 100 we take off 25, and $\frac{25}{125}=20\%$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.25 -> 1: lower by 0.25/1.25=20%","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
