VALUES ('537281b9-3ab1-47db-a9a1-b6d6352eed31', 'PRE.09', 3, 'choice', 'Simplifying square roots', 'Write $\sqrt{450}$ in simplest form.', '["$225\\sqrt{2}$","$15\\sqrt{2}$","$2\\sqrt{15}$","$15\\sqrt{3}$"]', '$15\sqrt{2}$', NULL, 'Find the biggest perfect square that divides 450: 450 = 225 × 2. Then $\sqrt{450}=\sqrt{225}\times\sqrt{2}=15\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$15\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"450=225*2 -> 15sqrt2.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
