INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51622e4f-bcb7-41b7-9aac-307f59d5e717', 'PRE.09', 3, 'numeric', 'Square roots in squares: side and area', 'A square has a perimeter of 36 units. A rectangle that is 3 units wide has the same area as the square. How long is the rectangle, in units?', '[]', '27', '(36/4)^2/3', 'The square''s side is $36\div 4=9$, so its area is 81. The rectangle''s length is $81\div 3=27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 9, area 81, length 81/3=27.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
