INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d045900-a54f-4add-ba6c-6fed01a9ba57', 'PRE.09', 3, 'choice', 'Square roots in squares: side and area', 'A square has sides of $5\sqrt{3}$ centimeters. What is its area, in square centimeters?', '["75","15","$25\\sqrt{3}$","150"]', '75', '75', 'Area = side × side = $5\sqrt{3}\times 5\sqrt{3}=25\times 3=75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25*3=75.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
