INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6be0bdaf-35ad-4ac1-aa0c-b02b45811464', 'PRE.09', 3, 'choice', 'Square roots in squares: side and area', 'A small square has sides of 6 cm. A big square has twice the area. What is the side of the big square, in centimeters?', '["12","$6\\sqrt{2}$","$2\\sqrt{6}$","36"]', '$6\sqrt{2}$', NULL, 'The small area is 36, so the big one is 72. Its side is $\sqrt{72}=\sqrt{36\times 2}=6\sqrt{2}$. (Doubling the area does not double the side.)', 'checked', '{"lint":[],"solve":{"answer":"$6\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 72, side sqrt72=6sqrt2.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
