INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2e62915-4c3d-440f-b722-6b39c8d572c3', 'PRE.09', 3, 'choice', 'Comparing and ordering square roots', 'Which of these four numbers has the largest value?', '["$2\\sqrt{10}$","$3\\sqrt{5}$","$5\\sqrt{2}$","$4\\sqrt{3}$"]', '$5\sqrt{2}$', NULL, 'Put each under one root: $5\sqrt{2}=\sqrt{50}$, $4\sqrt{3}=\sqrt{48}$, $3\sqrt{5}=\sqrt{45}$, $2\sqrt{10}=\sqrt{40}$. The biggest is $\sqrt{50}$, which is $5\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$5\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"As square roots: 45, 48, 40, 50 -> 5sqrt2 largest.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
