VALUES ('2ff82c6a-8949-40c7-8d77-0c16639e0aa0', 'PRE.10', 2, 'numeric', 'Vertical angles', 'Two lines cross. A pair of vertical angles measure $(2x+10)^\circ$ and $(3x-5)^\circ$. What is $x$?', '[]', '15', '15', 'Vertical angles are equal, so $2x+10=3x-5$. Then $x=15$. Each angle is 40 degrees.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+10=3x-5, x=15.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
