INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('428c613e-d2f4-42c3-a18d-06446bcca69b', 'PRE.10', 2, 'numeric', 'Vertical angles', 'Two lines cross. One of the four angles is 3 times as big as an angle next to it. How many degrees is the smaller of the two?', '[]', '45', '180/4', 'Two angles next to each other add to 180. With parts 1 and 3, one part is $180\div 4=45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles are supplementary: x+3x=180, x=45.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
