INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5017038f-2338-4a87-821a-023b751f5a19', 'PRE.10', 2, 'choice', 'Vertical angles', 'Two lines cross and make four angles. Which statement must be true?', '["All four angles are equal","Any two angles that are side by side add up to 180 degrees","Any two angles that are side by side are equal","All four angles are acute"]', 'Any two angles that are side by side add up to 180 degrees', NULL, 'Two side-by-side angles together make a straight line, so they add to 180. The four angles are not all equal unless the lines meet at right angles.', 'checked', '{"lint":[],"solve":{"answer":"Any two angles that are side by side add up to 180 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles form a straight line, sum 180. Not all equal/acute in general.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
