INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d89311f-bb3b-4c61-aa61-5f1696b70d0c', 'PRE.10', 2, 'choice', 'Parallel lines and a transversal', 'Two parallel lines are cut by a transversal. Which statement is always true?', '["Two interior angles on the same side are equal","Alternate interior angles add up to 180 degrees","Corresponding angles are equal","Vertical angles add up to 180 degrees"]', 'Corresponding angles are equal', NULL, 'Corresponding angles are equal. Interior angles on the same side add to 180 (they are equal only if both are 90), alternate interior angles are equal, and vertical angles are equal.', 'checked', '{"lint":[],"solve":{"answer":"Corresponding angles are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles are equal; others false.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
