VALUES ('c99e206c-809a-445a-896d-36632c02cd99', 'PRE.10', 2, 'numeric', 'Angles of a triangle', 'The angles of a triangle measure $x^\circ$, $2x^\circ$ and $3x^\circ$. How many degrees is the smallest angle?', '[]', '30', '180/6', '$x+2x+3x=6x=180$, so $x=30$. The smallest angle is 30 degrees.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x=180, x=30.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
