INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db0a0718-3319-4ed0-b661-fdd4e8743416', 'PRE.10', 3, 'numeric', 'Angle measures, turns and kinds of angles', 'At exactly 4:00, the hour hand and the minute hand of a clock make an angle. How many degrees is the smaller angle between them?', '[]', '120', '4*30', 'The 12 hour marks are spread around 360 degrees, so each hour is 30 degrees. At 4:00 the minute hand points at 12 and the hour hand at 4, which is $4\times 30=120$ degrees apart.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hour at 4 (120 deg), minute at 12: 120.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
