INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78fc90de-846f-4520-9553-410e23e80bee', 'PRE.10', 3, 'numeric', 'Angle measures, turns and kinds of angles', 'At exactly 3:30, the hour hand and the minute hand of a clock make an angle. How many degrees is the smaller angle between them?', '[]', '75', '180-105', 'Each hour is 30 degrees. The minute hand points at 6, which is 180 degrees from 12. The hour hand is halfway between 3 and 4, which is $3.5\times 30=105$ degrees from 12. The difference is $180-105=75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hour at 105 deg, minute at 180: 75.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14e345e4-3246-405b-bca0-6c9df956e00b', 'PRE.10', 3, 'numeric', 'Angle measures, turns and kinds of angles', 'At exactly 2:20, the hour hand and the minute hand of a clock make an angle. How many degrees is the smaller angle between them?', '[]', '50', '120-70', 'The minute hand points at 4, which is $4\times 30=120$ degrees from 12. The hour hand has moved past 2 by a third of an hour: $60+10=70$ degrees from 12. The difference is $120-70=50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hour at 60+10=70 deg, minute at 120: 50.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc12c81c-9543-419a-b597-f82e44cd897a', 'PRE.10', 3, 'numeric', 'Angle measures, turns and kinds of angles', 'Four angles fit exactly around a point. Three of them are $90^\circ$, $110^\circ$ and $75^\circ$. How many degrees is the fourth?', '[]', '85', '360-90-110-75', 'Angles around a point make a full turn, 360 degrees. $90+110+75=275$ and $360-275=85$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360-90-110-75=85.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
