VALUES ('37906e19-cc88-4151-a085-cd0d8833113b', 'PRE.10', 3, 'numeric', 'Complementary angles', 'An angle is $6^\circ$ less than 3 times its complement. How many degrees is the angle?', '[]', '66', '(3*90-6)/4', 'Let the angle be a. Its complement is $90-a$. So $a=3(90-a)-6=264-3a$, which gives $4a=264$ and $a=66$. Check: the complement is 24, and $3\times 24-6=66$.', 'checked', '{"lint":[],"solve":{"answer":"66","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=3(90-a)-6, 4a=264, a=66.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b1fca1b-c469-436e-a07f-4b691ebbcf53', 'PRE.10', 3, 'choice', 'Complementary angles', 'Two complementary angles differ by $20^\circ$. How many degrees is the bigger angle?', '["55","35","70","45"]', '55', '(90+20)/2', 'If the bigger angle is 20 more than the smaller, then bigger + bigger = $90+20=110$, so the bigger angle is 55 degrees (and the smaller is 35).', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b=90, a-b=20: a=55.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc4e452-17e4-45b0-9088-cb1318a25422', 'PRE.10', 3, 'choice', 'Complementary angles', 'The supplement of an angle is 3 times its complement. How many degrees is the angle?', '["30","45","60","135"]', '45', '90/2', 'Let the angle be a. Then $180-a=3(90-a)=270-3a$, so $2a=90$ and $a=45$. Check: supplement 135, complement 45, and $3\times 45=135$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180-a=3(90-a), 2a=90, a=45.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
