INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b471815-da3f-4072-83c2-56087a59ae14', 'PRE.10', 3, 'numeric', 'Supplementary angles and angles on a line', 'Three angles on a straight line measure $x^\circ$, $2x^\circ$ and $3x^\circ$. How many degrees is the smallest of them?', '[]', '30', '180/6', '$x+2x+3x=6x=180$, so $x=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x=180, x=30.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
