INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ed56e05-c342-472d-b2a5-096f8b5b7d3d', 'PRE.10', 3, 'choice', 'Supplementary angles and angles on a line', 'Two supplementary angles are in the ratio 2 to 7. How many degrees is the bigger angle?', '["40","126","140","70"]', '140', '180*7/9', 'There are $2+7=9$ parts making 180 degrees, so a part is 20 degrees. The bigger angle is $7\times 20=140$.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 parts =180, 20 each, bigger 7*20=140.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
