INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47a15c6a-448a-4205-b373-068970253f99', 'PRE.10', 3, 'numeric', 'Vertical angles', 'Three straight lines cross at one point and make six angles around it. Going around the point, the angles are $a^\circ, b^\circ, c^\circ, a^\circ, b^\circ, c^\circ$ in turn. If $a=35$ and $b=60$, what is $c$?', '[]', '85', '180-35-60', 'Three angles side by side on one side of a line make a straight line: $a+b+c=180$. So $c=180-35-60=85$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(a+b+c)=360, a+b+c=180, c=180-35-60=85.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01f18c77-8019-481c-aad1-a0f817ac7ffe', 'PRE.10', 3, 'numeric', 'Vertical angles', 'Two lines cross. A pair of vertical angles measure $(4x+15)^\circ$ and $(6x-25)^\circ$. How many degrees is an angle that is next to one of them?', '[]', '85', '180-(4*20+15)', 'Vertical angles are equal: $4x+15=6x-25$, so $x=20$. Each of them is $4\times 20+15=95$ degrees. An angle next to it is $180-95=85$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+15=6x-25, x=20, angle 95, adjacent 180-95=85.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
