INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1733840-5f50-4af7-942e-e1cdcbbdddd2', 'PRE.10', 3, 'numeric', 'Vertical angles', 'Two lines cross. One angle measures $(3x+12)^\circ$ and an angle next to it measures $(2x+3)^\circ$. What is $x$?', '[]', '33', '(180-15)/5', 'Angles next to each other add to 180: $5x+15=180$, so $5x=165$ and $x=33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent: 5x+15=180, x=33.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
