INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('432e6347-0486-4ab1-bd11-a85314cd1ea3', 'PRE.10', 3, 'numeric', 'Parallel lines and a transversal', 'A transversal cuts two parallel lines and makes 8 angles. One of the angles is $70^\circ$. How many of the 8 angles measure $110^\circ$?', '[]', '4', '4', 'Four angles match the 70-degree angle (the same size). The other four are next to them on straight lines, so each is 110 degrees.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles are 70 or 110, four each: 4.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
