INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1262c87a-85fa-4c6b-9846-dcfc693a6f47', 'PRE.10', 3, 'choice', 'Parallel lines and a transversal', 'Two parallel lines are cut by a transversal. Which pair of angles must add up to 180 degrees?', '["Two angles between the lines, on the same side of the transversal","Two corresponding angles","Two alternate interior angles","Two vertical angles"]', 'Two angles between the lines, on the same side of the transversal', NULL, 'Interior angles on the same side of the transversal are supplementary. Corresponding, alternate interior and vertical angles are equal pairs (they add to 180 only when all are 90 degrees).', 'checked', '{"lint":[],"solve":{"answer":"Two angles between the lines, on the same side of the transversal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angles are supplementary.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
