VALUES ('e06e1eac-000d-49a4-9357-60aaa5d7bd29', 'PRE.10', 3, 'numeric', 'Angles of a triangle', 'The angles of a triangle measure $x^\circ$, $(x+10)^\circ$ and $(x+20)^\circ$. What is $x$?', '[]', '50', '(180-30)/3', '$3x+30=180$, so $3x=150$ and $x=50$. The angles are 50, 60 and 70.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+30=180, x=50.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
