INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62a88458-696e-44b0-a490-5a1f052f9324', 'PRE.10', 3, 'numeric', 'Angles of a triangle', 'An exterior angle at one corner of a triangle is $110^\circ$. The two inside angles that are not next to it are in the ratio 4 to 7. How many degrees is the larger of those two?', '[]', '70', '110*7/11', 'An exterior angle equals the sum of the two far inside angles, so they add to 110. There are $4+7=11$ parts, each 10 degrees, so the larger is $7\times 10=70$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remote interior sum = 110; 11 parts of 10; larger 70.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
