INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3a795df-43ad-4465-b35b-532d8e0e760f', 'PRE.10', 3, 'numeric', 'Angles of a triangle', 'In a triangle, angle A is $20^\circ$ more than angle B, and angle C is twice angle B. How many degrees is angle B?', '[]', '40', '(180-20)/4', 'Call angle B b. Then A is $b+20$ and C is $2b$, so $b+(b+20)+2b=4b+20=180$. Then $4b=160$ and $b=40$. The angles are 60, 40 and 80.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(B+20)+B+2B=180, B=40.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
