INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da89f600-fe72-402a-b241-53f03890cf3e', 'PRE.10', 3, 'choice', 'Angles of a triangle', 'An isosceles triangle has an angle of $100^\circ$. How many degrees is each of its other two angles?', '["80","50","100","40"]', '40', '(180-100)/2', 'Two angles of 100 would already make 200, which is too many, so the 100-degree angle is the one that is alone. The other two are equal and share $180-100=80$, so each is 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 must be the vertex angle (two 100s exceed 180): (180-100)/2=40.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
