VALUES ('dcc52217-9efb-421a-8fa3-5bf31033426e', 'PRE.11', 2, 'numeric', 'Perimeter and area of a rectangle', 'A rectangular field has a perimeter of 54 meters. It is 17 meters long. How many meters wide is it?', '[]', '10', '54/2-17', 'Half the perimeter is length + width: $54\div 2=27$. So the width is $27-17=10$ meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W = 27, W = 27-17 = 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e470b7b2-3b49-44ea-962a-feadb08394c0', 'PRE.11', 2, 'choice', 'Perimeter and area of a rectangle', 'The length of a rectangle is 3 times its width, and its perimeter is 48 centimeters. What is its area, in square centimeters?', '["144","72","216","108"]', '108', '6*18', 'If the width is $w$, the perimeter is $2(w+3w)=8w=48$, so $w=6$ and the length is 18. The area is $6\times 18=108$.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3w+w)=48, w=6, L=18, A=108.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d4420f1-714b-412d-a211-911f6a393e33', 'PRE.11', 2, 'numeric', 'Perimeter and area of a rectangle', 'A rectangular poster is 1.5 meters long and 0.8 meter wide. What is its area, in square meters?', '[]', '1.2', '1.5*0.8', 'Area = $1.5\times 0.8=1.2$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"1.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5*0.8 = 1.2.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cb34adb-8bfe-48c6-9941-1cfd6ae4a310', 'PRE.11', 2, 'numeric', 'Perimeter and area of a rectangle', 'Rectangle P is 8 cm by 3 cm. Rectangle Q is 6 cm by 5 cm. How many more square centimeters of area does Q have than P?', '[]', '6', '6*5-8*3', 'P has area $8\times 3=24$. Q has area $6\times 5=30$. The difference is $30-24=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q: 30, P: 24, difference 6.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
