INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b330a31-b781-475a-af29-33aafabfaace', 'PRE.11', 2, 'numeric', 'Perimeter and area of a square', 'A square courtyard has an area of 81 square meters. What is its perimeter, in meters?', '[]', '36', '4*9', 'The side is 9 meters because $9\times 9=81$. The perimeter is $4\times 9=36$ meters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 9, P = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
