INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ecb172e-bcd9-45a4-855a-e8a3a4b73838', 'PRE.11', 2, 'numeric', 'Perimeter and area of a square', 'A runner jogs twice around a square field. Each side of the field is 120 meters long. How many meters does the runner jog?', '[]', '960', '2*4*120', 'One lap is $4\times 120=480$ meters. Two laps are $2\times 480=960$ meters.', 'checked', '{"lint":[],"solve":{"answer":"960","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 480, twice = 960.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
