INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('342c66e3-c4b9-4dda-8719-31f1c3396260', 'PRE.11', 2, 'numeric', 'Area of a triangle', 'A right triangle has legs of 9 centimeters and 12 centimeters. What is its area, in square centimeters?', '[]', '54', '9*12/2', 'The legs of a right triangle are a base and a height. Area $=\frac12\times 9\times 12=54$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9*12/2 = 54.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
