INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a628e4b-56ca-4dbf-987f-6ac5f974dc83', 'PRE.11', 2, 'choice', 'Area of a triangle', 'A triangle has a side of 14 centimeters. The height drawn to that side is 12 centimeters. The other two sides are 13 centimeters and 15 centimeters long. What is the area of the triangle, in square centimeters?', '["168","195","78","84"]', '84', '14*12/2', 'Use the side of 14 as the base and the height 12: area $=\frac12\times 14\times 12=84$. The other side lengths are not needed.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14*12/2 = 84 (13-14-15 triangle consistent: segments 5 and 9).","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1cc3ef3-e029-47a6-b7bf-081d42967353', 'PRE.11', 2, 'numeric', 'Area of a triangle', 'The base of a triangle is twice its height. The area of the triangle is 36 square units. How long is the base?', '[]', '12', NULL, 'If the height is $h$, the base is $2h$ and the area is $\frac12\times 2h\times h=h^2$. So $h^2=36$, $h=6$ and the base is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b=2h, bh/2 = h^2 = 36, h=6, b=12.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79788cc9-e200-4aaf-8cb8-3f4ab757d532', 'PRE.11', 2, 'choice', 'Area of a triangle', 'Which triangle has the greatest area?', '["Base 9 cm and height 7 cm","Base 6 cm and height 10 cm","Base 8 cm and height 7 cm","Base 5 cm and height 11 cm"]', 'Base 9 cm and height 7 cm', NULL, 'Compare base $\times$ height: $63$, $60$, $56$ and $55$. The greatest is base 9 and height 7, with area 31.5 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"Base 9 cm and height 7 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Areas: 28, 27.5, 31.5, 30. Greatest 31.5.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b698de7-9a87-452e-843d-f4b99c2ce27e', 'PRE.11', 2, 'choice', 'Area of a parallelogram', 'A parallelogram has a base of 9 centimeters, a slanted side of 6 centimeters and a height of 5 centimeters. What is its area, in square centimeters?', '["45","54","30","22.5"]', '45', '9*5', 'Area is base times height, not base times the slanted side: $9\times 5=45$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9*5 = 45 (slanted side irrelevant).","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
