INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9754032a-3288-4364-8eff-5f210c42006f', 'PRE.11', 2, 'numeric', 'Area of a parallelogram', 'A parallelogram has an area of 84 square meters and a height of 7 meters. A rectangle has the same base as the parallelogram and a height of 3 meters. What is the area of the rectangle, in square meters?', '[]', '36', '84/7*3', 'The base is $84\div 7=12$ meters. The rectangle has area $12\times 3=36$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 84/7 = 12; rectangle 12*3 = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
