INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c675254-fac3-4bd9-8e2e-aee4b24a3271', 'PRE.11', 2, 'numeric', 'Area of a parallelogram', 'A field shaped like a parallelogram has a base of 25 meters and a height of 16 meters. One bag of seed covers 100 square meters. How many bags are needed to cover the whole field once?', '[]', '4', '25*16/100', 'The area is $25\times 16=400$ square meters. One bag covers 100, so $400\div 100=4$ bags.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25*16 = 400; 400/100 = 4 bags.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
