INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('314f43df-913f-4895-a5e5-70716e2d2cfa', 'PRE.11', 2, 'choice', 'Area of a parallelogram', 'Which parallelogram has the greatest area?', '["Base 8 cm and height 5 cm","Base 6 cm and height 7 cm","Base 10 cm and height 4 cm","Base 5 cm and height 8 cm"]', 'Base 6 cm and height 7 cm', NULL, 'The areas are $6\times 7=42$, $8\times 5=40$, $10\times 4=40$ and $5\times 8=40$. The greatest is 42.', 'checked', '{"lint":[],"solve":{"answer":"Base 6 cm and height 7 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42, 40, 40, 40. Greatest 42.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
