INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5e4585d-3ce3-4f7c-8b5e-2160df075365', 'PRE.11', 2, 'numeric', 'Area of a trapezoid', 'A trapezoid has an area of 54 square centimeters and a height of 6 centimeters. One of its parallel sides is 11 centimeters long. How long is the other parallel side, in centimeters?', '[]', '7', '54*2/6-11', 'The two parallel sides add to $54\times 2\div 6=18$. The other side is $18-11=7$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 = (11+x)/2*6 -> 11+x = 18, x = 7.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
