INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd7ac451-cf63-4950-8e8f-3fe70239aa3b', 'PRE.11', 2, 'choice', 'Area of a trapezoid', 'A garden bed is a trapezoid. Its two parallel sides are 12 meters and 20 meters long, and they are 9 meters apart. What is its area, in square meters?', '["144","288","108","180"]', '144', '(12+20)*9/2', 'Area $=\frac12\times(12+20)\times 9=16\times 9=144$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12+20)/2*9 = 144.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
