INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc7b3ffc-a707-48e9-b95b-347ce4e8b812', 'PRE.11', 2, 'choice', 'Area of a trapezoid', 'Trapezoid R has parallel sides of 3 cm and 9 cm and a height of 5 cm. Trapezoid S has parallel sides of 4 cm and 8 cm and a height of 5 cm. Which statement is true?', '["R has the greater area.","R and S have the same area.","S has the greater area.","R has twice the area of S."]', 'R and S have the same area.', NULL, 'R: $\frac12\times 12\times 5=30$. S: $\frac12\times 12\times 5=30$. The parallel sides add to 12 in both, so the areas are equal.', 'checked', '{"lint":[],"solve":{"answer":"R and S have the same area.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R: 12/2*5 = 30; S: 12/2*5 = 30. Equal.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
