INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dd9bf31-3ac8-4e1d-ae8f-a3e9074f06ae', 'PRE.11', 2, 'choice', 'Circumference and area of a circle', 'A round clock has a diameter of 12 centimeters. What is its area, in square centimeters?', '["$144\\pi$","$12\\pi$","$36\\pi$","$72\\pi$"]', '$36\pi$', NULL, 'The radius is 6 centimeters. Area $=\pi\times 6^2=36\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 6, A = 36pi.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
