INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c531a80e-3b9b-479d-bfb5-35268375e75a', 'PRE.11', 2, 'numeric', 'Circumference and area of a circle', 'The circumference of a circle is $20\pi$ meters. What is its radius, in meters?', '[]', '10', '20/2', 'Circumference $=2\pi r=20\pi$, so $r=10$ meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2pi r = 20pi, r = 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
