INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56fc8f3f-11cd-4a26-b6b8-3eb1a2f63a2a', 'PRE.11', 2, 'numeric', 'Circumference and area of a circle', 'The area of a circle is $49\pi$ square centimeters. What is its diameter, in centimeters?', '[]', '14', '2*7', '$\pi r^2=49\pi$, so $r^2=49$ and $r=7$. The diameter is $2\times 7=14$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2 = 49, r = 7, d = 14.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
