INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97058440-25a2-4dfd-a866-9249e867a38e', 'PRE.11', 2, 'choice', 'Circumference and area of a circle', 'A wheel has a radius of 30 centimeters. How far does it roll, in centimeters, during one full turn?', '["$30\\pi$","$900\\pi$","$15\\pi$","$60\\pi$"]', '$60\pi$', NULL, 'In one full turn the wheel rolls one circumference: $2\pi r=2\pi\times 30=60\pi$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$60\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2pi*30 = 60pi.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
