INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d252404f-d2a6-40e9-aecb-fbb34da39398', 'PRE.11', 2, 'numeric', 'Area and perimeter of composite shapes', 'A picture is 20 centimeters long and 15 centimeters wide. A frame 3 centimeters wide goes all the way around the picture. What is the area of the frame itself, in square centimeters?', '[]', '246', '26*21-20*15', 'The picture and frame together are $26$ by $21$, with area $546$. The picture alone is $20\times 15=300$. The frame is $546-300=246$.', 'checked', '{"lint":[],"solve":{"answer":"246","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer 26*21 = 546, minus 300 = 246.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('087984c7-9364-43a4-bc87-740a2218c6e3', 'PRE.11', 2, 'choice', 'Area and perimeter of composite shapes', 'An L-shaped room is made by cutting a 4 meter by 3 meter rectangle out of a corner of a 10 meter by 8 meter rectangle. What is the perimeter of the L-shaped room, in meters?', '["29","50","68","36"]', '36', '2*(10+8)', 'Cutting a rectangle from a corner does not change the perimeter: the new edges replace the old ones. The perimeter is $2\times(10+8)=36$ meters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corner notch keeps perimeter equal to bounding rectangle: 2(10+8) = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddac8015-db63-42aa-aa82-01f1b5cf3fa4', 'PRE.11', 2, 'choice', 'Area and perimeter of composite shapes', 'A shape is a rectangle 10 centimeters long and 6 centimeters wide, with a half circle added on one of the 6-centimeter sides. That side is the diameter of the half circle. What is the area of the whole shape, in square centimeters?', '["$60+\\frac{9}{2}\\pi$","$60+9\\pi$","$60+3\\pi$","$60+36\\pi$"]', '$60+\frac{9}{2}\pi$', NULL, 'The rectangle has area 60. The half circle has radius 3, so its area is $\frac12\pi\times 3^2=\frac92\pi$. The total is $60+\frac92\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$60+\\frac{9}{2}\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half circle radius 3: 9pi/2. Total 60 + 9pi/2.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c919f30d-7fee-4d38-b720-8f10b46f80c8', 'PRE.11', 2, 'numeric', 'Comparing perimeter and area', 'A rectangle has a perimeter of 24 centimeters and whole-number sides. What is the greatest area it can have, in square centimeters?', '[]', '36', NULL, 'The sides add to 12. The products are $1\times 11=11$, $2\times 10=20$, $3\times 9=27$, $4\times 8=32$, $5\times 7=35$ and $6\times 6=36$. The greatest is 36.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W = 12, max at 6x6 = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16cb6615-36f3-45fa-beed-187886622c34', 'PRE.11', 2, 'numeric', 'Comparing perimeter and area', 'Each side of a 3 centimeter by 5 centimeter rectangle is doubled in length. How many square centimeters larger is the area of the new rectangle?', '[]', '45', '6*10-3*5', 'The old area is 15. The new rectangle is 6 by 10, with area 60. The difference is $60-15=45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*10 - 3*5 = 60 - 15 = 45.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2e173a1-a100-41c5-90f8-15c67aa8df47', 'PRE.11', 2, 'choice', 'Comparing perimeter and area', 'Four fields all have a perimeter of 36 meters. Which one has the greatest area?', '["A rectangle, 12 m by 6 m","A square, 9 m by 9 m","A rectangle, 14 m by 4 m","A rectangle, 16 m by 2 m"]', 'A square, 9 m by 9 m', NULL, 'The areas are $81$, $72$, $56$ and $32$ square meters. For a given perimeter, the square has the greatest area.', 'checked', '{"lint":[],"solve":{"answer":"A square, 9 m by 9 m","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Areas 32, 81, 72, 56. Square 81.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a3e3066-5bfe-4802-a70d-a4d51cdfd406', 'PRE.11', 2, 'numeric', 'Area and perimeter in real-life problems', 'A rectangular floor is 5 meters long and 4 meters wide. It is covered with square tiles that are 50 centimeters on each side. How many tiles are needed?', '[]', '80', '(500/50)*(400/50)', 'The floor is 500 cm by 400 cm. Along the length there are $500\div 50=10$ tiles and along the width $400\div 50=8$ tiles. The total is $10\times 8=80$ tiles.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 by 8 tiles of 0.5 m = 80.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9bdcd08-ecce-4ef3-886b-6682f0df35fc', 'PRE.11', 2, 'choice', 'Area and perimeter in real-life problems', 'A pen is built against a long straight wall, so only three sides need fencing. The two sides that touch the wall are 7 meters long, and the side opposite the wall is 12 meters long. How many meters of fence are needed?', '["26","38","19","84"]', '26', '7+7+12', 'Fence is needed for the two 7-meter sides and the 12-meter side: $7+7+12=26$ meters.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 7 + 12 = 26.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2244178d-b545-49f7-94e6-0ff29d441e64', 'PRE.11', 2, 'numeric', 'Area and perimeter in real-life problems', 'A wall is 6 meters wide and 3 meters high. A window 2 meters wide and 1 meter high will not be painted. Paint costs 2 dollars for each square meter. How many dollars does it cost to paint the rest of the wall?', '[]', '32', '(18-2)*2', 'The wall has area $6\times 3=18$. The window has area $2\times 1=2$. Painted area is $16$ square meters, costing $16\times 2=32$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 - 2 = 16 m^2, *2 = 32.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9536b60f-6c66-4b88-89f9-a347f0a438bf', 'PRE.11', 2, 'choice', 'Area and perimeter in real-life problems', 'A strip of wood is 3 meters long and 40 centimeters wide. What is its area, in square centimeters?', '["$120$","$12{,}000$","$1{,}200$","$120{,}000$"]', '$12{,}000$', NULL, '3 meters is 300 centimeters. The area is $300\times 40=12{,}000$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$12{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"300 cm * 40 cm = 12000.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
