INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f998f60-7d1d-49cc-9824-d0b6b0a3959e', 'PRE.11', 3, 'numeric', 'Perimeter and area of a rectangle', 'A rectangle has whole-number sides, a perimeter of 30 centimeters and an area of 56 square centimeters. How long, in centimeters, is its longer side?', '[]', '8', NULL, 'The two sides add up to 15. Whole numbers with product 56 are 1 and 56, 2 and 28, 4 and 14, 7 and 8. Only 7 and 8 add to 15. The longer side is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W=15, LW=56 -> 7 and 8. Longer side 8.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e58e83f2-e9d1-4219-92b4-4654793d106e', 'PRE.11', 3, 'numeric', 'Perimeter and area of a rectangle', 'A rectangle is 5 meters by 8 meters. Both its length and its width are made 2 meters longer. By how many square meters does the area grow?', '[]', '30', '7*10-5*8', 'The old area is $5\times 8=40$. The new rectangle is 7 by 10, with area 70. The area grows by $70-40=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New 7*10=70, old 5*8=40, growth 30.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
