INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b5db055-c64e-4dee-82a2-e9f859eed614', 'PRE.11', 3, 'choice', 'Perimeter and area of a rectangle', 'A rectangle has an area of 36 square units, and both of its sides are whole numbers. How many different perimeters can such a rectangle have?', '["5","4","9","6"]', '5', '5', 'The side pairs are 1 by 36, 2 by 18, 3 by 12, 4 by 9 and 6 by 6. Their perimeters are 74, 40, 30, 26 and 24, which are 5 different values.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Answer 5 relies on counting the 6x6 square as a rectangle; a student who excludes squares gets 4, which is an option. Correct by definition, but worth noting.","work":"Factor pairs of 36: 1x36 (P74), 2x18 (40), 3x12 (30), 4x9 (26), 6x6 (24). Five distinct perimeters (a square counts as a rectangle).","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81c237bc-3b38-4509-9c34-cc26aca54c4b', 'PRE.11', 3, 'numeric', 'Perimeter and area of a square', 'When each side of a square is made 3 centimeters longer, the area of the square grows by 39 square centimeters. How long was each side of the original square, in centimeters?', '[]', '5', '(39-9)/6', 'Try a side of 5: the area goes from 25 to $8\times 8=64$, which is 39 more. In general the new area is $s^2+6s+9$, so $6s+9=39$ and $s=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(s+3)^2 - s^2 = 6s+9 = 39, s = 5.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09628908-aada-4177-a9e3-86729d2f8897', 'PRE.11', 3, 'choice', 'Perimeter and area of a square', 'Each side of a square is made 3 times as long. The area of the new square is how many times the area of the old square?', '["9","3","6","12"]', '9', '3*3', 'If the old side is $s$, the new side is $3s$ and the new area is $(3s)^2=9s^2$. The area is 9 times as large.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 3, area scale 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32bbde54-0e21-446d-9af3-8b3bdb07b595', 'PRE.11', 3, 'numeric', 'Perimeter and area of a square', 'A square piece of paper has sides of 10 centimeters. A strip 2 centimeters wide is cut off along one side, leaving a rectangle. What is the perimeter of the rectangle, in centimeters?', '[]', '36', '2*(10+8)', 'The rectangle left is 10 centimeters by 8 centimeters. Its perimeter is $2\times(10+8)=36$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 by 8, P = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
