INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6333468-288d-4c9b-87d9-574cf87c1956', 'PRE.11', 3, 'choice', 'Perimeter and area of a square', 'Two squares have areas of 25 square centimeters and 9 square centimeters. How many centimeters longer is the perimeter of the larger square than the perimeter of the smaller square?', '["16","8","2","34"]', '8', '4*5-4*3', 'The sides are 5 and 3 centimeters. The perimeters are 20 and 12, which differ by 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 5 and 3, perimeters 20 and 12, difference 8.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
