INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7a97bd1-5754-4cd7-9af7-f896cb8ba186', 'PRE.11', 3, 'numeric', 'Area of a triangle', 'Triangle ABC has a base BC of 10 centimeters and an area of 60 square centimeters. Point D is on BC, 4 centimeters from B. What is the area of triangle ABD, in square centimeters?', '[]', '24', '4*12/2', 'Triangles ABC and ABD have the same height (from A to line BC). The height is $60\times 2\div 10=12$. Triangle ABD has base 4, so its area is $\frac12\times 4\times 12=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 2*60/10 = 12. ABD has base 4, same height: 24.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
