INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2700e7a8-e46f-4697-b798-b753ef827f7e', 'PRE.11', 3, 'choice', 'Area of a triangle', 'The base of a triangle is made 3 times as long, and its height is cut in half. The new area is how many times the old area?', '["$\\frac{1}{2}$","$\\frac{3}{2}$","$3$","$\\frac{1}{6}$"]', '$\frac{3}{2}$', NULL, 'Area is proportional to base $\times$ height. The new product is $3\times\frac12=\frac32$ times the old one.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 * 1/2 = 3/2.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c48c497d-fc49-47a4-b563-50e50de5534f', 'PRE.11', 3, 'numeric', 'Area of a triangle', 'A triangle with a base of 9 centimeters has the same area as a square whose perimeter is 24 centimeters. What is the height of the triangle, in centimeters?', '[]', '8', '36*2/9', 'The square has side $24\div 4=6$ and area 36. For the triangle, $\frac12\times 9\times h=36$, so $9h=72$ and $h=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square side 6, area 36. 9h/2 = 36, h = 8.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56399e21-1226-48f8-bba3-81729150766d', 'PRE.11', 3, 'choice', 'Area of a triangle', 'A triangle has corners at (0, 0), (8, 0) and (3, 6) on a grid where each unit is 1 centimeter. What is its area, in square centimeters?', '["48","12","24","9"]', '24', '8*6/2', 'Take the side from (0, 0) to (8, 0) as the base: 8 centimeters. The third corner is 6 units above it, so the height is 6. Area $=\frac12\times 8\times 6=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 8 on x-axis, height 6: area 24.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d42fb71d-6823-43da-b079-e5e66e84fde4', 'PRE.11', 3, 'numeric', 'Area of a parallelogram', 'A parallelogram has a base of 14 centimeters. Its base is lengthened by 6 centimeters while its height stays the same, and its area grows by 48 square centimeters. What is the height, in centimeters?', '[]', '8', '48/6', 'The extra area is the extra base times the height: $6\times h=48$, so $h=8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6h = 48, h = 8.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
