INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbc9b704-b5c3-4ba9-bd63-19d47548f4be', 'PRE.11', 3, 'choice', 'Area of a parallelogram', 'A rectangle is 9 centimeters long and 6 centimeters wide. It is pushed over into a parallelogram with the same four side lengths. The height of the parallelogram above its 9-centimeter side is now 3 centimeters. What is the area of the parallelogram, in square centimeters?', '["54","18","27","30"]', '27', '9*3', 'The area is the 9-centimeter base times the new height: $9\times 3=27$ square centimeters. It is less than the rectangle''s 54.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9*3 = 27.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57e8154d-419a-4c40-b4d6-99613878b507', 'PRE.11', 3, 'numeric', 'Area of a parallelogram', 'A parallelogram has a perimeter of 36 centimeters. One side is 10 centimeters long, and the height to that side is 6 centimeters. What is the height to the other, shorter side, in centimeters?', '[]', '7.5', '60/8', 'The sides are 10 and 8 centimeters, because $10+8=36\div 2$. The area is $10\times 6=60$. Using the 8-centimeter side as the base, the height is $60\div 8=7.5$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 10 and 8. Area 10*6 = 60; height to 8-side = 60/8 = 7.5.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d2ae27b-23ca-417b-b2f5-07b9a61e9331', 'PRE.11', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has a height of 6 centimeters. Its shorter parallel side is b centimeters long and its longer parallel side is 4 centimeters longer than that. Its area is 66 square centimeters. What is b?', '[]', '9', '(66*2/6-4)/2', 'The parallel sides add to $66\times 2\div 6=22$. So $b+(b+4)=22$, $2b=18$ and $b=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(b + b+4)/2*6 = 6(b+2) = 66, b = 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3daa2de-a109-4a48-8cc3-3af2c078a9eb', 'PRE.11', 3, 'choice', 'Area of a trapezoid', 'A trapezoid has two right angles. Its parallel sides are 5 centimeters and 11 centimeters, and its height is 8 centimeters. It is cut into a rectangle and a right triangle. What is the area of the triangle, in square centimeters?', '["48","40","24","64"]', '24', '(11-5)*8/2', 'The rectangle is 5 by 8. The triangle has a base of $11-5=6$ and a height of 8, so its area is $\frac12\times 6\times 8=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle legs 11-5 = 6 and 8: area 24.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66a989a9-17b7-4f69-8689-965e44fb2b72', 'PRE.11', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has an area of 90 square centimeters and a height of 9 centimeters. Its parallel sides are in the ratio 2 : 3. How long is the longer parallel side, in centimeters?', '[]', '12', '20*3/5', 'The parallel sides add to $90\times 2\div 9=20$. Split 20 in the ratio 2 : 3: 8 and 12. The longer side is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 2*90/9 = 20; 2:3 gives 8 and 12. Longer 12.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3af8b84b-0394-4257-afd9-50ad789040b0', 'PRE.11', 3, 'choice', 'Area of a trapezoid', 'A trapezoid has corners at (0, 0), (10, 0), (8, 5) and (3, 5) on a grid where each unit is 1 centimeter. Its top and bottom sides are parallel. What is its area, in square centimeters?', '["75","50","25","37.5"]', '37.5', '(10+5)*5/2', 'The bottom side is 10 long. The top side runs from x = 3 to x = 8, so it is 5 long. The height is 5. Area $=\frac12\times(10+5)\times 5=37.5$.', 'checked', '{"lint":[],"solve":{"answer":"37.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bases 10 and 5, height 5: 7.5*5 = 37.5.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b7e5799-d596-4189-8a92-a8088e5b76b9', 'PRE.11', 3, 'choice', 'Circumference and area of a circle', 'A circle with radius 4 centimeters lies inside a circle with radius 7 centimeters, and the two circles have the same center. What is the area of the ring between them, in square centimeters?', '["$33\\pi$","$9\\pi$","$65\\pi$","$66\\pi$"]', '$33\pi$', NULL, 'Area of ring = big circle minus small circle $=49\pi-16\pi=33\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$33\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49pi - 16pi = 33pi.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11a1e656-a15e-4a40-a1cb-ef5533a0d5dc', 'PRE.11', 3, 'numeric', 'Circumference and area of a circle', 'One circle has a circumference of $8\pi$ centimeters. A second circle has a circumference of $24\pi$ centimeters. The area of the second circle is how many times the area of the first?', '[]', '9', '3*3', 'The radii are 4 and 12, so the second radius is 3 times the first. Area grows with the square of the radius, so the second area is $3^2=9$ times as large.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radii 4 and 12, ratio 3, area ratio 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
