INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69d306d9-135f-48c0-bcf6-e6b8b73193d6', 'PRE.11', 3, 'numeric', 'Circumference and area of a circle', 'A circular rug has a radius of 2 meters. Rugs cost 10 dollars for each square meter. Use 3.14 for $\pi$. How many dollars does the rug cost?', '[]', '125.6', '3.14*2*2*10', 'Area $\approx 3.14\times 2^2=12.56$ square meters. The cost is $12.56\times 10=125.6$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"125.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14*4 = 12.56 m^2; *10 = 125.6.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d99c7da2-e9d0-4eb6-948b-6170a3299518', 'PRE.11', 3, 'numeric', 'Area and perimeter of composite shapes', 'A shape is made of five columns, each 1 centimeter wide, standing side by side on a flat base. The columns are 1, 2, 3, 4 and 5 centimeters tall, from left to right. What is the perimeter of the shape, in centimeters?', '[]', '20', '2*(5+5)', 'Count the flat parts: the bottom is 5 long, and the tops of the five columns add up to 5 more, so the horizontal parts total 10. Count the upright parts: the right side is 5 tall, and the left side (1) plus the four steps up (1 each) make 5 more, so the upright parts total 10. The perimeter is $10+10=20$, the same as a 5 by 5 square.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Staircase: perimeter equals bounding box 5 by 5: 20. (Horizontal 5+5, vertical 5 left/right total 5+5.)","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fa70fa5-d024-4c23-8a07-ef47c2161b39', 'PRE.11', 3, 'choice', 'Area and perimeter of composite shapes', 'A circle fits exactly inside a square with sides of 10 centimeters, touching all four sides. What is the area of the part of the square that is outside the circle, in square centimeters?', '["$100-100\\pi$","$100-25\\pi$","$100-10\\pi$","$100-50\\pi$"]', '$100-25\pi$', NULL, 'The circle has diameter 10, so radius 5 and area $25\pi$. The square has area 100. The part outside is $100-25\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$100-25\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circle r=5, area 25pi; 100 - 25pi.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ecfd55d8-7024-46ba-919a-ca948b41d26e', 'PRE.11', 3, 'numeric', 'Area and perimeter of composite shapes', 'A photo is 8 centimeters by 6 centimeters. It is mounted on a board so that there is a border of the same width on all four sides. The board has an area of 120 square centimeters. How wide is the border, in centimeters?', '[]', '2', NULL, 'If the border is $x$ wide, the board is $(8+2x)$ by $(6+2x)$. Try $x=2$: $12\times 10=120$. It works, and a wider border makes the board larger than 120, a narrower one smaller, so the border is 2 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8+2x)(6+2x) = 120; x = 2 gives 12*10 = 120.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa171c5-6093-4b6d-aaa5-98315b6531d8', 'PRE.11', 3, 'choice', 'Area and perimeter of composite shapes', 'Two squares with sides of 6 centimeters and a rectangle 6 centimeters tall and 3 centimeters wide are joined in a row, side to side, to make one long rectangle. What is the perimeter of the long rectangle, in centimeters?', '["66","21","42","90"]', '42', '2*(15+6)', 'The long rectangle is $6+6+3=15$ wide and 6 tall. Its perimeter is $2\times(15+6)=42$. (66 adds up the three separate perimeters; 90 is the area.)', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 6+6+3 = 15, height 6, P = 42.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b4aaa31-643f-407f-a2d2-c8555357fc7e', 'PRE.11', 3, 'numeric', 'Comparing perimeter and area', 'A rectangle has an area of 60 square centimeters and whole-number sides. What is the least perimeter it can have, in centimeters?', '[]', '32', '2*(6+10)', 'The side pairs are 1 and 60, 2 and 30, 3 and 20, 4 and 15, 5 and 12, 6 and 10. The sums are 61, 32, 23, 19, 17, 16, so the perimeters are 122, 64, 46, 38, 34 and 32. The least is 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Closest factor pair 6x10: P = 32.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9005a421-f63e-4cbd-a448-d4a62db8115b', 'PRE.11', 3, 'choice', 'Comparing perimeter and area', 'The length of a rectangle is increased by 20 percent and its width is decreased by 20 percent. What happens to the area?', '["It stays the same","It increases by 4 percent","It decreases by 4 percent","It decreases by 20 percent"]', 'It decreases by 4 percent', NULL, 'The new area is $1.2\times 0.8=0.96$ of the old area, which is 4 percent less.', 'checked', '{"lint":[],"solve":{"answer":"It decreases by 4 percent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2*0.8 = 0.96: decreases 4%.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a588f079-c82d-4796-a793-910afedd5bc3', 'PRE.11', 3, 'numeric', 'Comparing perimeter and area', 'A rectangle and a square both have a perimeter of 40 centimeters. The rectangle is 4 centimeters longer than it is wide. How many square centimeters greater is the area of the square than the area of the rectangle?', '[]', '4', '10*10-12*8', 'The square has sides of 10 and area 100. The rectangle''s sides add to 20 and differ by 4, so they are 12 and 8, with area 96. The difference is $100-96=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square 10x10 = 100. Rectangle L+W = 20, L-W = 4: 12x8 = 96. Difference 4.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb01a1b2-5a05-4c5e-b2d7-99aec8f1f998', 'PRE.11', 3, 'numeric', 'Comparing perimeter and area', 'One side of a rectangle is tripled and the other side stays the same. The perimeter changes from 20 centimeters to 36 centimeters. What is the area of the original rectangle, in square centimeters?', '[]', '24', '4*6', 'Let the sides be $a$ (the one that is tripled) and $b$. Then $a+b=10$ and $3a+b=18$. Subtracting, $2a=8$, so $a=4$ and $b=6$. The original area is $4\times 6=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b = 10, 3a+b = 18 -> a = 4, b = 6. Area 24.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d201073-9123-4256-afb1-a3eb88c08b5a', 'PRE.11', 3, 'numeric', 'Area and perimeter in real-life problems', 'A floor is 480 centimeters long and 360 centimeters wide. It is covered with equal square tiles, with no cutting. The tiles are as large as possible. How many tiles are needed?', '[]', '12', '(480/120)*(360/120)', 'The tile side must divide both 480 and 360. The largest such number is 120. Along the length there are $480\div 120=4$ tiles and along the width $360\div 120=3$ tiles, so $4\times 3=12$ tiles.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(480,360) = 120; 4*3 = 12 tiles.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5be9ab0-8fba-4f13-9dd2-3258de482edf', 'PRE.11', 3, 'choice', 'Area and perimeter in real-life problems', 'A rope 56 meters long is made into a rectangle with whole-number sides, using all of the rope. Which of these areas, in square meters, is NOT possible?', '["196","187","200","160"]', '200', NULL, 'The sides add to 28. The areas are $14\times 14=196$, $11\times 17=187$ and $8\times 20=160$, all possible. The greatest possible area is 196, so 200 is not possible.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W = 28. 196 = 14x14, 160 = 8x20, 187 = 11x17; 200 needs x(28-x)=200, discriminant 784-800 < 0 (also > max 196). Not possible.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7738e4aa-b733-4d91-956d-cf54bac77d3e', 'PRE.11', 3, 'numeric', 'Area and perimeter in real-life problems', 'Three square pens, each with sides of 4 meters, are built in a row, touching along their sides. Fence goes around the outside of the whole row and also along each wall between pens. How many meters of fence are needed in all?', '[]', '40', '2*(12+4)+2*4', 'The whole row is $3\times 4=12$ meters long and 4 meters wide, so the outside is $2\times(12+4)=32$ meters. There are 2 walls between pens, each 4 meters: 8 more. The total is $32+8=40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer 2(12+4) = 32, plus 2 inner walls of 4 = 8. Total 40.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b88aacb0-e250-4b8c-a899-0a888de0335d', 'PRE.11', 3, 'choice', 'Area and perimeter in real-life problems', 'A rectangular floor is 6 meters long and 5 meters wide. Tiles are sold in packs. Each pack covers 2.4 square meters and costs 20 dollars. Only whole packs can be bought. What is the least cost to cover the floor, in dollars?', '["250","240","600","260"]', '260', '13*20', 'The floor is 30 square meters. $30\div 2.4=12.5$, so 13 packs are needed. $13\times 20=260$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 30; 30/2.4 = 12.5 -> 13 packs; 13*20 = 260.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9a4bc10-ec8e-41b6-a54a-84e5ad907303', 'PRE.12', 1, 'numeric', 'Hypotenuse of a right triangle', 'The legs of a right triangle are 6 centimeters and 8 centimeters long. How long is the hypotenuse, in centimeters?', '[]', '10', '10', 'By the Pythagorean theorem, $6^2+8^2=36+64=100$, and $\sqrt{100}=10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(36+64) = 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8a5dfe2-bd3c-4234-8f9b-9862b685a519', 'PRE.12', 1, 'choice', 'Hypotenuse of a right triangle', 'A right triangle has legs of 5 and 12. What is the length of the hypotenuse?', '["17","13","7","169"]', '13', '13', '$5^2+12^2=25+144=169$, and $\sqrt{169}=13$. (17 adds the legs; 169 forgets the square root.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(25+144) = 13.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54b90466-1e67-438b-82c8-3b4759e7d5a9', 'PRE.12', 1, 'numeric', 'Hypotenuse of a right triangle', 'Ana walks 9 meters east and then 12 meters north. How many meters is she from where she started, in a straight line?', '[]', '15', '15', 'Her path and the straight line make a right triangle with legs 9 and 12. $9^2+12^2=81+144=225$, and $\sqrt{225}=15$ meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(81+144) = 15.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
