VALUES ('7ffa249b-20fe-432b-96da-5d77628c7647', 'PRE.12', 1, 'choice', 'Hypotenuse of a right triangle', 'A right triangle has legs of 2 and 3. What is the length of its hypotenuse?', '["$5$","$13$","$\\sqrt{13}$","$\\sqrt{5}$"]', '$\sqrt{13}$', NULL, '$2^2+3^2=4+9=13$, so the hypotenuse is $\sqrt{13}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{13}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(4+9) = sqrt13.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
