VALUES ('a6e0fd38-4fa9-4d16-a937-1e9ac8a59db8', 'PRE.12', 1, 'choice', 'Missing leg of a right triangle', 'A right triangle has a hypotenuse of 5 and one leg of 3. What is the length of the other leg?', '["2","8","16","4"]', '4', '4', '$5^2-3^2=25-9=16$, and $\sqrt{16}=4$. (16 forgets the square root.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(25-9) = 4.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
