INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c269796-6a67-4fb6-af06-7caf08e5abe7', 'PRE.12', 1, 'choice', 'Pythagorean triples', 'Which set of three numbers can be the side lengths of a right triangle?', '["5, 12, 14","5, 11, 13","6, 12, 13","5, 12, 13"]', '5, 12, 13', NULL, 'Check $a^2+b^2=c^2$ with the largest as $c$. $5^2+12^2=25+144=169=13^2$ works. The other sets do not.', 'checked', '{"lint":[],"solve":{"answer":"5, 12, 13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25+144 = 169. Others fail.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
