INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b021bb48-d50f-491c-8106-9eb078fb8ba6', 'PRE.12', 1, 'numeric', '45-45-90 triangles', 'A 45-45-90 triangle has a hypotenuse of $9\sqrt{2}$ centimeters. How long is each leg, in centimeters?', '[]', '9', '9', 'In a 45-45-90 triangle the hypotenuse is the leg times $\sqrt2$. So the leg is $9\sqrt2\div\sqrt2=9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leg = hyp/sqrt2 = 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
