INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21c4fa8d-5717-4e59-be66-c949af6a2fdf', 'PRE.12', 1, 'choice', '45-45-90 triangles', 'Each leg of a 45-45-90 triangle is 5 centimeters long. What is the length of the hypotenuse?', '["$5\\sqrt{2}$","$5\\sqrt{3}$","$10$","$\\frac{5\\sqrt{2}}{2}$"]', '$5\sqrt{2}$', NULL, 'The hypotenuse is the leg times $\sqrt2$, so it is $5\sqrt2$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$5\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5sqrt2.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
