INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('467c20cc-bae3-48e4-8f7c-684070e09789', 'PRE.12', 1, 'numeric', '45-45-90 triangles', 'A right triangle has two legs that are both 4 centimeters long. How many degrees is each of its other two angles?', '[]', '45', '90/2', 'Equal legs mean equal angles opposite them. The three angles add to 180 and one is 90, so the other two share 90 degrees: 45 each.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Isosceles right triangle: (180-90)/2 = 45.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
