VALUES ('bf93f068-a81b-4ee1-b2ce-234950cbd1f7', 'PRE.12', 1, 'numeric', '30-60-90 triangles', 'The shortest side of a 30-60-90 triangle is 5 centimeters. How long is the hypotenuse, in centimeters?', '[]', '10', '2*5', 'The hypotenuse is twice the shortest side: $2\times 5=10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*5 = 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
