VALUES ('5e5ffc8a-5707-4731-acb6-4ffb31152de9', 'PRE.12', 1, 'choice', '30-60-90 triangles', 'The hypotenuse of a 30-60-90 triangle is 14 centimeters. How long is the shortest side, in centimeters?', '["28","$7\\sqrt{3}$","7","$14\\sqrt{3}$"]', '7', '14/2', 'The shortest side is half the hypotenuse: $14\div 2=7$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/2 = 7.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
