INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('536ddea3-d8d3-4cf6-8e84-42c0106a7005', 'PRE.12', 1, 'choice', 'Applications of the Pythagorean theorem', 'A rectangular screen is 8 inches wide and 6 inches tall. How long is its diagonal, in inches?', '["14","48","28","10"]', '10', '10', '$8^2+6^2=64+36=100$, and $\sqrt{100}=10$ inches. (14 adds the sides; 28 is the perimeter.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(64+36) = 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
