INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eab764af-305b-472c-893a-d3bd7014143e', 'PRE.12', 1, 'choice', 'Applications of the Pythagorean theorem', 'A gate is 12 feet wide and 5 feet tall. A brace runs along the diagonal from one corner to the opposite corner. How long is the brace, in feet?', '["13","17","60","7"]', '13', '13', '$12^2+5^2=144+25=169$, and $\sqrt{169}=13$ feet.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(144+25) = 13.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
