INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb84569b-b298-43fa-8196-618a7392c384', 'PRE.12', 1, 'numeric', 'Angles and properties of quadrilaterals', 'Three angles of a quadrilateral are 90, 80 and 100 degrees. How many degrees is the fourth angle?', '[]', '90', '360-90-80-100', 'The four angles of a quadrilateral add to 360 degrees. The three known angles add to 270, so the fourth is $360-270=90$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360 - 270 = 90.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
