INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cc2b939-7f9f-4cc3-9ca0-f30d4e79a2e7', 'PRE.12', 2, 'choice', 'Hypotenuse of a right triangle', 'A right triangle has legs of 4 and 6. What is the length of its hypotenuse?', '["$\\sqrt{10}$","$10$","$2\\sqrt{5}$","$2\\sqrt{13}$"]', '$2\sqrt{13}$', NULL, '$4^2+6^2=16+36=52$. The hypotenuse is $\sqrt{52}=\sqrt{4\times 13}=2\sqrt{13}$.', 'checked', '{"lint":[],"solve":{"answer":"$2\\sqrt{13}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(16+36) = sqrt52 = 2sqrt13.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
