INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b89f5538-559e-4eb9-8ceb-a7ab94fc9ed2', 'PRE.12', 2, 'numeric', 'Hypotenuse of a right triangle', 'The legs of a right triangle are 20 centimeters and 21 centimeters long. What is the perimeter of the triangle, in centimeters?', '[]', '70', '20+21+29', '$20^2+21^2=400+441=841=29^2$, so the hypotenuse is 29. The perimeter is $20+21+29=70$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hyp sqrt(400+441) = 29; P = 20+21+29 = 70.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
