INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc04e4e6-32f9-43e3-8d27-1c140491e781', 'PRE.12', 2, 'choice', 'Hypotenuse of a right triangle', 'A square is built on each side of a right triangle. The squares on the two legs have areas of 36 square centimeters and 64 square centimeters. How long is each side of the square built on the hypotenuse, in centimeters?', '["10","100","14","2"]', '10', '10', 'The legs are $\sqrt{36}=6$ and $\sqrt{64}=8$ centimeters, so the hypotenuse is 10 (the area of its square is $36+64=100$, and 100 is the area, not the side).', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hyp square area 100, side 10.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
