INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32a923fe-d329-479e-b503-eeeaff280b24', 'PRE.12', 2, 'numeric', 'Missing leg of a right triangle', 'An isosceles triangle has two sides of 13 centimeters and a base of 10 centimeters. How tall is the triangle, measured from the base to the opposite corner, in centimeters?', '[]', '12', '12', 'The height cuts the base in half, into 5 and 5. It forms a right triangle with hypotenuse 13 and one leg 5, so the height is $\sqrt{169-25}=\sqrt{144}=12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half base 5; sqrt(169-25) = 12.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
