INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec9b7af1-0f07-408e-8984-60adbae5cd2f', 'PRE.12', 2, 'choice', 'Pythagorean triples', 'Which set of side lengths does NOT make a right triangle?', '["10, 24, 27","9, 12, 15","7, 24, 25","20, 21, 29"]', '10, 24, 27', NULL, 'Check each with the largest side as hypotenuse: $9^2+12^2=225=15^2$, $7^2+24^2=625=25^2$, $20^2+21^2=841=29^2$. But $10^2+24^2=676$, not $27^2=729$.', 'checked', '{"lint":[],"solve":{"answer":"10, 24, 27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100+576 = 676 != 729. Others: 49+576=625, 400+441=841, 81+144=225.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
