INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bdbc225-c672-4207-98c8-376582740f53', 'PRE.12', 2, 'numeric', 'Pythagorean triples', 'A right triangle has sides in the ratio 5 : 12 : 13, and its perimeter is 90 centimeters. How long is its longest side, in centimeters?', '[]', '39', '13*90/30', 'The ratio parts add to $5+12+13=30$, so one part is $90\div 30=3$ centimeters. The longest side is $13\times 3=39$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30k = 90, k = 3, 13*3 = 39.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
