INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d76fced-3905-413a-a91c-3fb07772f897', 'PRE.12', 2, 'numeric', 'Pythagorean triples', 'A triangle has sides of 7, 24 and 25 centimeters. It is a right triangle. What is its area, in square centimeters?', '[]', '84', '7*24/2', 'The two shorter sides are the legs, since $7^2+24^2=625=25^2$. The area is $\frac12\times 7\times 24=84$.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7*24/2 = 84.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98a331fd-6fbb-4bdb-b154-59fba5d51490', 'PRE.12', 2, 'choice', 'Pythagorean triples', 'A triangle has sides of 9, 40 and 41. Which statement is true?', '["The angle opposite the side of length 9 is a right angle.","The angle opposite the side of length 41 is a right angle.","The angle opposite the side of length 40 is a right angle.","No angle of the triangle is a right angle."]', 'The angle opposite the side of length 41 is a right angle.', NULL, '$9^2+40^2=81+1600=1681=41^2$, so the sides satisfy the Pythagorean theorem and the triangle is a right triangle. The right angle is opposite the longest side, 41.', 'checked', '{"lint":[],"solve":{"answer":"The angle opposite the side of length 41 is a right angle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81+1600 = 1681 = 41^2: right angle opposite 41.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1e4f33f-76ec-4f63-bd83-45315d049bf8', 'PRE.12', 2, 'numeric', '45-45-90 triangles', 'The diagonal of a square is $10\sqrt{2}$ centimeters long. What is the area of the square, in square centimeters?', '[]', '100', '10*10', 'The diagonal is the side times $\sqrt2$, so the side is 10 centimeters. The area is $10\times 10=100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 10, area 100.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c88d4040-7181-423f-ae53-8cdda2cfbf10', 'PRE.12', 2, 'choice', '45-45-90 triangles', 'The hypotenuse of a 45-45-90 triangle is 10 centimeters long. How long is each leg, in centimeters?', '["$10\\sqrt{2}$","$5$","$5\\sqrt{2}$","$5\\sqrt{3}$"]', '$5\sqrt{2}$', NULL, 'Leg $=$ hypotenuse $\div\sqrt2=\frac{10}{\sqrt2}=\frac{10\sqrt2}{2}=5\sqrt2$.', 'checked', '{"lint":[],"solve":{"answer":"$5\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/sqrt2 = 5sqrt2.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ca9db11-1640-4737-9d46-7e92097f73a9', 'PRE.12', 2, 'numeric', '45-45-90 triangles', 'A right triangle has two equal legs and a hypotenuse of 12 centimeters. What is its area, in square centimeters?', '[]', '36', '144/2/2', 'Each leg squared is $\frac{12^2}{2}=72$ (since $\text{leg}^2+\text{leg}^2=144$). The area is $\frac12\times 72=36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 12/sqrt2 = 6sqrt2; area 72/2 = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cf15281-f510-4916-ad41-de6aa6f790e0', 'PRE.12', 2, 'choice', '45-45-90 triangles', 'The diagonal of a square is 8 centimeters long. What is the perimeter of the square, in centimeters?', '["$32$","$8\\sqrt{2}$","$32\\sqrt{2}$","$16\\sqrt{2}$"]', '$16\sqrt{2}$', NULL, 'The side is $\frac{8}{\sqrt2}=4\sqrt2$. The perimeter is $4\times 4\sqrt2=16\sqrt2$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$16\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 8/sqrt2 = 4sqrt2; P = 16sqrt2.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
