INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5341fad-7dde-4a9b-ba05-174c76c6323d', 'PRE.12', 2, 'numeric', '30-60-90 triangles', 'The hypotenuse of a 30-60-90 triangle is 9 centimeters longer than its shortest side. How long is the hypotenuse, in centimeters?', '[]', '18', '2*9', 'The hypotenuse is twice the shortest side, so it is exactly 1 shortest side longer than it. That side is 9, and the hypotenuse is $2\times 9=18$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - x = 9, x = 9, hyp 18.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
