INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('647a4e23-dfe4-4107-b3ca-b0c696b3e8c5', 'PRE.12', 2, 'choice', '30-60-90 triangles', 'An equilateral triangle has sides of 8 centimeters. How tall is it, measured from one side to the opposite corner, in centimeters?', '["$4\\sqrt{3}$","$8\\sqrt{3}$","$4$","$4\\sqrt{2}$"]', '$4\sqrt{3}$', NULL, 'The height cuts the triangle into two 30-60-90 triangles with hypotenuse 8. The shortest side is 4 (half the base), so the height is $4\sqrt3$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$4\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 8*sqrt3/2 = 4sqrt3.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
