INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9afc91b6-5963-441a-8d76-476e1d355bdd', 'PRE.12', 2, 'numeric', 'Applications of the Pythagorean theorem', 'A 25-foot ladder leans against a wall and reaches 24 feet up. How many feet is the foot of the ladder from the wall?', '[]', '7', '7', '$25^2-24^2=625-576=49$, and $\sqrt{49}=7$ feet.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(625-576) = 7.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
