INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7decbab-7b5d-4cd0-bee9-21e90deafc98', 'PRE.12', 2, 'choice', 'Applications of the Pythagorean theorem', 'A path goes 6 kilometers east and then 8 kilometers north. A new straight path joins the start and the end directly. How many kilometers shorter is the new path?', '["10","4","14","2"]', '4', '4', 'The old path is $6+8=14$ kilometers. The straight path is the hypotenuse: $\sqrt{36+64}=10$ kilometers. It is $14-10=4$ kilometers shorter.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 14, new 10, shorter by 4.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
