INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56970292-5300-46f1-9b54-328954fcec14', 'PRE.12', 2, 'numeric', 'Applications of the Pythagorean theorem', 'A flagpole is 15 meters tall. A wire runs from the top of the pole to a point on the ground 8 meters from the base of the pole. How long is the wire, in meters?', '[]', '17', '17', '$15^2+8^2=225+64=289$, and $\sqrt{289}=17$ meters.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(225+64) = 17.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
