INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5ae5481-fc60-4e06-898f-c9907c308a64', 'PRE.12', 2, 'choice', 'Angles and properties of quadrilaterals', 'Which statement is true for every rhombus?', '["Its diagonals have the same length.","All four of its angles are right angles.","Its diagonals cross at right angles.","Exactly one pair of its sides is parallel."]', 'Its diagonals cross at right angles.', NULL, 'The diagonals of a rhombus are perpendicular. They are equal only in a square, the angles are right angles only in a square, and a rhombus has two pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Its diagonals cross at right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rhombus diagonals are perpendicular.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
