INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('265068f0-13c6-45d9-b594-773cda220f58', 'PRE.12', 2, 'numeric', 'Angles and properties of quadrilaterals', 'An isosceles trapezoid has a longer base and a shorter base. The angles at the longer base are 65 degrees each. How many degrees is each angle at the shorter base?', '[]', '115', '180-65', 'Angles on the same leg of a trapezoid add to 180 degrees, because the bases are parallel. So each angle at the shorter base is $180-65=115$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"115","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 65 = 115.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cd967f0-52b5-476f-b712-25de0eca019f', 'PRE.12', 2, 'numeric', 'Area of quadrilaterals', 'A square has diagonals of 10 centimeters. What is its area, in square centimeters?', '[]', '50', '10*10/2', 'A square is a rhombus, so its area is half the product of its diagonals: $\frac12\times 10\times 10=50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2/2 = 50.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
