INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02765202-9abb-45e6-abd4-66e25a1b1758', 'PRE.12', 2, 'choice', 'Area of quadrilaterals', 'A rhombus has an area of 60 square centimeters, and one diagonal is 10 centimeters long. How long is the other diagonal, in centimeters?', '["6","50","24","12"]', '12', '60*2/10', 'Area $=\frac12 d_1 d_2$, so $\frac12\times 10\times d_2=60$, $5d_2=60$ and $d_2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*60/10 = 12.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63ce6e35-84f8-447c-a1da-f180f1bed746', 'PRE.12', 2, 'numeric', 'Area of quadrilaterals', 'A table top is a trapezoid. Its two parallel edges are 120 centimeters and 80 centimeters long, and they are 50 centimeters apart. What is the area of the table top, in square centimeters?', '[]', '5000', '(120+80)*50/2', 'Area $=\frac12\times(120+80)\times 50=100\times 50=5000$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"5000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(120+80)/2*50 = 5000.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
