INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0f2c42c-82d5-4f18-885d-ac547de85640', 'PRE.12', 2, 'choice', 'Area of quadrilaterals', 'A rhombus has diagonals of 12 centimeters and 16 centimeters. What is its perimeter, in centimeters?', '["40","28","56","20"]', '40', '40', 'The diagonals cross at right angles and cut each other in half, making right triangles with legs 6 and 8. Each side is $\sqrt{36+64}=10$, and the perimeter is $4\times 10=40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half diagonals 6, 8, side 10, P = 40.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab8c985-6d0f-41f2-8cb0-fa24f66fc25c', 'PRE.12', 2, 'choice', 'Classifying quadrilaterals and their diagonals', 'Which statement is true?', '["Every rectangle is a square.","Every parallelogram is a rhombus.","Every trapezoid is a parallelogram.","Every square is a rectangle."]', 'Every square is a rectangle.', NULL, 'A square has four right angles, so it is a rectangle. A rectangle need not have equal sides, a parallelogram need not have equal sides, and a trapezoid has only one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Every square is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every square is a rectangle.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
