INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af8a63a9-c770-4321-b1f2-270190ad21e7', 'PRE.12', 3, 'choice', 'Hypotenuse of a right triangle', 'A right triangle has a hypotenuse of 17 and a perimeter of 40. What is its area?', '["120","60","30","100"]', '60', '60', 'The legs add up to $40-17=23$. Also $a^2+b^2=17^2=289$. Since $(a+b)^2=a^2+b^2+2ab$, we get $529=289+2ab$, so $ab=120$. The area is half of that, 60. (The legs are 8 and 15.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b = 23, a^2+b^2 = 289; 2ab = 529-289 = 240, ab = 120, area 60 (8-15-17).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72f71ace-6578-4173-a88c-ced517c1e967', 'PRE.12', 3, 'numeric', 'Missing leg of a right triangle', 'An isosceles triangle has two sides of 17 centimeters and a base of 16 centimeters. What is its area, in square centimeters?', '[]', '120', '16*15/2', 'The height splits the base into 8 and 8 and makes a right triangle with hypotenuse 17, so the height is $\sqrt{289-64}=\sqrt{225}=15$. The area is $\frac12\times 16\times 15=120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half base 8; height sqrt(289-64) = 15; area 16*15/2 = 120.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b3c0a83-c040-41d9-b1e3-bcdfe6f2e008', 'PRE.12', 3, 'choice', 'Missing leg of a right triangle', 'The hypotenuse of a right triangle is 10. Its two legs differ in length by 2. How long is the shorter leg?', '["4","6","8","5"]', '6', '6', 'Try legs 6 and 8: they differ by 2 and $6^2+8^2=36+64=100=10^2$. So the shorter leg is 6. (A leg of 8 is the longer one.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + (x+2)^2 = 100 -> x = 6 (6-8-10).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e632509-cc30-4c5a-98f0-7e2c9e3030cb', 'PRE.12', 3, 'numeric', 'Missing leg of a right triangle', 'Triangle ABC has a right angle at B. Side AC is 30 centimeters and side AB is 18 centimeters. What is the perimeter of the triangle, in centimeters?', '[]', '72', '30+18+24', 'AC is the hypotenuse. $BC=\sqrt{30^2-18^2}=\sqrt{900-324}=\sqrt{576}=24$. The perimeter is $30+18+24=72$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AC hypotenuse 30, AB 18, BC = 24. P = 72.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48c95d38-9d82-4dd7-8811-5c79c6c700c4', 'PRE.12', 3, 'choice', 'Missing leg of a right triangle', 'A right triangle has a hypotenuse of 41 and one leg of 9. What is the length of the other leg?', '["32","50","40","1600"]', '40', '40', '$41^2-9^2=1681-81=1600$, and $\sqrt{1600}=40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(1681-81) = sqrt1600 = 40.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e016848-eff6-448c-88c0-8dbbcfca85b0', 'PRE.12', 3, 'numeric', 'Pythagorean triples', 'A right triangle has two sides of 12 and 16. The third side could be the hypotenuse, or it could be a leg (if 16 is the hypotenuse). What is the sum of the squares of the two possible lengths of the third side?', '[]', '512', '400+112', 'If the third side is the hypotenuse, its square is $12^2+16^2=144+256=400$. If 16 is the hypotenuse, the square of the third side is $16^2-12^2=256-144=112$. The sum is $400+112=512$.', 'checked', '{"lint":[],"solve":{"answer":"512","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hyp case: 144+256 = 400. Leg case: 256-144 = 112. Sum 512.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d5d00d5-83a8-4412-bc36-faaf5fec9586', 'PRE.12', 3, 'choice', 'Pythagorean triples', 'How many different right triangles with whole-number side lengths have a hypotenuse of 25?', '["1","3","2","4"]', '2', '2', 'We need $a^2+b^2=625$ with whole numbers. The pairs are 7 and 24 ($49+576$) and 15 and 20 ($225+400$). No other pair works, so there are 2 triangles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs with a^2+b^2 = 625: (7,24), (15,20). Two triangles.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('547114f5-0296-401b-b6fd-a55604a23cd9', 'PRE.12', 3, 'numeric', 'Pythagorean triples', 'The three side lengths of a right triangle are consecutive even numbers. What is the perimeter of the triangle?', '[]', '24', '6+8+10', 'Call the sides $x$, $x+2$ and $x+4$. Trying small even numbers: 2, 4, 6 fail ($4+16\ne 36$), and 4, 6, 8 fail ($16+36\ne 64$), but 6, 8, 10 work ($36+64=100$). The perimeter is $6+8+10=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)^2 + x^2 = (x+2)^2 -> x^2 = 8x, x = 8: 6, 8, 10. P = 24.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac142d0c-81c4-4c80-86b0-dab48a781a2f', 'PRE.12', 3, 'choice', 'Pythagorean triples', 'The right triangles 3-4-5, 5-12-13, 7-24-25 and 9-40-41 all have whole-number sides, and in each one the hypotenuse is exactly 1 more than the longer leg. A right triangle with a shorter leg of 11 follows the same pattern. What are its longer leg and its hypotenuse?', '["56 and 57","48 and 49","120 and 121","60 and 61"]', '60 and 61', NULL, 'If the longer leg is $b$, the hypotenuse is $b+1$, so $11^2+b^2=(b+1)^2$, which gives $121=2b+1$ and $b=60$. Check: $11^2+60^2=121+3600=3721=61^2$.', 'checked', '{"lint":[],"solve":{"answer":"60 and 61","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"121 = c^2 - b^2 = (c-b)(c+b) = c+b, c-b = 1 -> b = 60, c = 61.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6397da7b-354a-40ca-89ce-dc9f338f84d8', 'PRE.12', 3, 'numeric', '45-45-90 triangles', 'A right triangle with two equal legs has an area of 49 square centimeters. What is the square of the length of its hypotenuse?', '[]', '196', '4*49', 'Area $=\frac12\ell^2=49$, so $\ell^2=98$. The hypotenuse squared is $\ell^2+\ell^2=196$. (The hypotenuse is 14.)', 'checked', '{"lint":[],"solve":{"answer":"196","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"leg^2/2 = 49, leg^2 = 98; hyp^2 = 2*98 = 196.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe7d4a66-643e-4afc-a42c-12c80f1cc65f', 'PRE.12', 3, 'choice', '45-45-90 triangles', 'A 45-45-90 triangle has a hypotenuse of $6\sqrt{2}$ centimeters. A line is drawn from the right angle straight down to the hypotenuse, meeting it at a right angle. How long is this line, in centimeters?', '["$3\\sqrt{2}$","$6$","$3$","$6\\sqrt{2}$"]', '$3\sqrt{2}$', NULL, 'The legs are 6 centimeters each, so the area is $\frac12\times 6\times 6=18$. Using the hypotenuse as the base: $\frac12\times 6\sqrt2\times h=18$, so $h=\frac{6}{\sqrt2}=3\sqrt2$.', 'checked', '{"lint":[],"solve":{"answer":"$3\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 6; altitude = 6*6/(6sqrt2) = 3sqrt2 (half the hypotenuse).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('452e4b2d-bdbb-4801-aad6-a756a38bd660', 'PRE.12', 3, 'numeric', '45-45-90 triangles', 'The diagonal of a square is 14 centimeters long. What is the area of the square, in square centimeters?', '[]', '98', '14*14/2', 'If the side is $s$, then $s^2+s^2=14^2=196$, so $s^2=98$. The area of the square is $s^2=98$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"98","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = d^2/2 = 196/2 = 98.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24c3e85e-7305-4ec2-9cf4-7584518cbd98', 'PRE.12', 3, 'numeric', '30-60-90 triangles', 'An equilateral triangle is $5\sqrt{3}$ centimeters tall. What is its perimeter, in centimeters?', '[]', '30', '3*10', 'The height is the shortest side times $\sqrt3$, so half of the base is 5 and the side is 10 centimeters. The perimeter is $3\times 10=30$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s*sqrt3/2 = 5sqrt3 -> s = 10, P = 30.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
