INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1a72591-af04-4953-bf0f-fb0c0bb5c4cf', 'PRE.12', 3, 'choice', '30-60-90 triangles', 'What is the area of an equilateral triangle with sides of 6 centimeters, in square centimeters?', '["$18\\sqrt{3}$","$9\\sqrt{3}$","$36\\sqrt{3}$","$9\\sqrt{2}$"]', '$9\sqrt{3}$', NULL, 'The height is $3\sqrt3$ (a 30-60-90 triangle with shortest side 3). The area is $\frac12\times 6\times 3\sqrt3=9\sqrt3$.', 'checked', '{"lint":[],"solve":{"answer":"$9\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(sqrt3/4)*36 = 9sqrt3.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6f2e9e5-3309-472e-817a-20758c1e3071', 'PRE.12', 3, 'numeric', '30-60-90 triangles', 'A 30-60-90 triangle has an area of $8\sqrt{3}$ square centimeters. How long is its shortest side, in centimeters?', '[]', '4', '4', 'If the shortest side is $s$, the legs are $s$ and $s\sqrt3$, so the area is $\frac12 s^2\sqrt3=8\sqrt3$. Then $s^2=16$ and $s=4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs x and xsqrt3: x^2 sqrt3/2 = 8sqrt3 -> x^2 = 16, x = 4.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273d96f3-a8c6-46ee-89d6-eeea39ead667', 'PRE.12', 3, 'choice', '30-60-90 triangles', 'A rectangle has a diagonal of 20 centimeters. The diagonal makes a 30 degree angle with the longer side. What is the perimeter of the rectangle, in centimeters?', '["$40\\sqrt{3}$","$20+10\\sqrt{3}$","$20+20\\sqrt{3}$","$60$"]', '$20+20\sqrt{3}$', NULL, 'The diagonal and two sides form a 30-60-90 triangle with hypotenuse 20. The shorter side is 10 and the longer side is $10\sqrt3$. The perimeter is $2(10+10\sqrt3)=20+20\sqrt3$.', 'checked', '{"lint":[],"solve":{"answer":"$20+20\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Short side 10 (opposite 30), long 10sqrt3. P = 20 + 20sqrt3.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ecd8198-f035-446a-bbb6-ab3bbc6f39c7', 'PRE.12', 3, 'numeric', 'Applications of the Pythagorean theorem', 'A 25-foot ladder leans against a wall with its foot 7 feet from the wall. The top of the ladder slides down the wall by 4 feet, and the ladder does not leave the wall or the ground. How many feet does the foot of the ladder move away from the wall?', '[]', '8', '15-7', 'At first the ladder reaches $\sqrt{625-49}=24$ feet up. After sliding 4 feet it reaches 20 feet, so the foot is now $\sqrt{625-400}=15$ feet from the wall. It has moved $15-7=8$ feet.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top at sqrt(625-49) = 24, slides to 20; foot sqrt(625-400) = 15; moves 15-7 = 8.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54d68267-528f-4872-8dfb-082df0db2e0a', 'PRE.12', 3, 'choice', 'Applications of the Pythagorean theorem', 'A rectangle has a diagonal of 26 centimeters and one side of 10 centimeters. What is its area, in square centimeters?', '["260","120","240","68"]', '240', '10*24', 'The other side is $\sqrt{26^2-10^2}=\sqrt{576}=24$. The area is $10\times 24=240$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other side sqrt(676-100) = 24; area 240.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e754db-5280-469b-9f11-3307579d8707', 'PRE.12', 3, 'numeric', 'Applications of the Pythagorean theorem', 'A box is 3 centimeters wide, 4 centimeters deep and 12 centimeters tall. What is the distance from one bottom corner to the opposite top corner, straight through the inside of the box, in centimeters?', '[]', '13', '13', 'The diagonal across the bottom is $\sqrt{3^2+4^2}=5$. This and the 12-centimeter edge are the legs of a right triangle whose hypotenuse is the distance wanted: $\sqrt{5^2+12^2}=\sqrt{169}=13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(9+16+144) = sqrt169 = 13.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd5eab64-359f-4fca-8848-92f29b7affe4', 'PRE.12', 3, 'choice', 'Applications of the Pythagorean theorem', 'Two poles stand on level ground, 9 meters apart. One pole is 14 meters tall and the other is 2 meters tall. A straight rope is stretched from the top of one pole to the top of the other. How long is the rope, in meters?', '["21","3","$\\sqrt{85}$","15"]', '15', '15', 'The tops differ in height by $14-2=12$ meters, and are 9 meters apart across the ground. The rope is the hypotenuse of a right triangle with legs 12 and 9: $\sqrt{144+81}=15$ meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal 9, vertical 12: sqrt(81+144) = 15.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('665267d0-e07c-4b09-92de-406b1c2b4cea', 'PRE.12', 3, 'numeric', 'Angles and properties of quadrilaterals', 'The four angles of a quadrilateral are x, x + 10, x + 20 and x + 30 degrees. What is x?', '[]', '75', '(360-60)/4', 'The sum is $4x+60=360$, so $4x=300$ and $x=75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 60 = 360, x = 75.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2803d599-c8bc-416b-95c3-dbbeb32d1b48', 'PRE.12', 3, 'choice', 'Angles and properties of quadrilaterals', 'In parallelogram ABCD, the diagonals AC and BD cross at point E. AC is 20 centimeters long and BD is 14 centimeters long. What is the length AE + BE, in centimeters?', '["34","27","24","17"]', '17', '10+7', 'The diagonals of a parallelogram cut each other in half. So $AE=20\div 2=10$ and $BE=14\div 2=7$, and $AE+BE=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonals bisect: AE = 10, BE = 7; 17.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25daca54-dca8-4e52-ae5e-7ae8011ab36e', 'PRE.12', 3, 'numeric', 'Angles and properties of quadrilaterals', 'ABCD is a rhombus and angle A is 50 degrees. The diagonal AC cuts angle A into two equal angles. How many degrees is angle CAB?', '[]', '25', '50/2', 'The diagonals of a rhombus bisect its angles, so angle CAB is half of 50: 25 degrees.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50/2 = 25.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6053f013-c3e0-4b9b-b5e7-5f0597b9829d', 'PRE.12', 3, 'choice', 'Angles and properties of quadrilaterals', 'The two diagonals of a parallelogram have the same length. How many of the parallelogram''s four angles are right angles?', '["4","2","0","1"]', '4', '4', 'Take one side of the parallelogram. The two diagonals and that side and the opposite side make two triangles that are the same shape and size, so the angles at the two ends of that side are equal. In a parallelogram those two angles also add to 180 degrees, so each is 90 degrees. All four angles are right angles (the shape is a rectangle).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal diagonals make it a rectangle: 4 right angles.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f51eebc-5e50-4ed6-9114-c3d58db4c767', 'PRE.12', 3, 'numeric', 'Area of quadrilaterals', 'An isosceles trapezoid has parallel sides of 10 centimeters and 20 centimeters, and each slanted side is 13 centimeters long. What is its area, in square centimeters?', '[]', '180', '(10+20)*12/2', 'The bases differ by 10, so each end sticks out 5. The height satisfies $5^2+h^2=13^2$, so $h=12$. Area $=\frac12\times(10+20)\times 12=180$.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Overhang (20-10)/2 = 5, height sqrt(169-25) = 12; area 15*12 = 180.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
