INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42bc8107-aee9-4a4c-8902-4241cdee63b6', 'PRE.12', 3, 'choice', 'Area of quadrilaterals', 'A trapezoid has two right angles. Its parallel sides are 7 centimeters and 16 centimeters long, and its slanted side is 15 centimeters long. What is its area, in square centimeters?', '["180","138","108","276"]', '138', '(7+16)*12/2', 'The parallel sides differ by $16-7=9$. The slanted side is the hypotenuse of a right triangle with one leg 9, so the height is $\sqrt{225-81}=12$. Area $=\frac12\times(7+16)\times 12=138$.', 'checked', '{"lint":[],"solve":{"answer":"138","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right trapezoid: horizontal 16-7 = 9, slant 15, height 12. Area 23/2*12 = 138.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a922957-01a1-4f5f-84a9-a821b44160aa', 'PRE.12', 3, 'numeric', 'Area of quadrilaterals', 'A parallelogram has sides of 8 centimeters and 12 centimeters, and the angle between them is 30 degrees. What is its area, in square centimeters?', '[]', '48', '12*4', 'Take the 12-centimeter side as the base. The height makes a 30-60-90 triangle with the 8-centimeter side as hypotenuse, so the height is half of 8, which is 4. Area $=12\times 4=48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height on base 12 = 8 sin30 = 4 (30-60-90). Area 12*4 = 48.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3092967f-ebad-4724-b79b-1ad370f146a2', 'PRE.12', 3, 'numeric', 'Classifying quadrilaterals and their diagonals', 'A rhombus has diagonals of 10 centimeters and 24 centimeters. What is its perimeter, in centimeters?', '[]', '52', '4*13', 'The diagonals cross at right angles and cut each other in half, making right triangles with legs 5 and 12. Each side is $\sqrt{25+144}=13$. The perimeter is $4\times 13=52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half diagonals 5, 12, side 13, P = 52.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95f2ceb6-3333-4007-ad35-c7b28b132df2', 'PRE.12', 3, 'choice', 'Classifying quadrilaterals and their diagonals', 'The diagonals of a quadrilateral are equal in length and cut each other in half at right angles. What is the quadrilateral?', '["A rectangle","A square","A rhombus","A trapezoid"]', 'A square', NULL, 'Diagonals that bisect each other make a parallelogram. Equal diagonals make it a rectangle. Perpendicular diagonals make it a rhombus. A shape that is both is a square.', 'checked', '{"lint":[],"solve":{"answer":"A square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal, bisecting, perpendicular diagonals: square.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f960951-d6b9-48df-971e-82fb87943502', 'PRE.12', 3, 'numeric', 'Classifying quadrilaterals and their diagonals', 'A rectangle has a diagonal of 25 centimeters and a perimeter of 62 centimeters. What is its area, in square centimeters?', '[]', '168', '(31*31-625)/2', 'The two sides add to $62\div 2=31$, and their squares add to $25^2=625$. Since $31^2=961=625+2ab$, we get $ab=168$. (The sides are 24 and 7.)', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W = 31, L^2+W^2 = 625; 2LW = 961-625 = 336, LW = 168 (7 by 24).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebf58b40-018e-46d0-977a-31b0bcbaf98f', 'PRE.12', 3, 'choice', 'Classifying quadrilaterals and their diagonals', 'The midpoints of the four sides of a square with sides of 8 centimeters are joined in order to make a smaller square. What is the area of the smaller square, in square centimeters?', '["16","64","32","48"]', '32', '64-4*8', 'Each corner of the big square has a small right triangle cut off with legs 4 and 4, area 8. The four triangles total 32, so the smaller square has area $64-32=32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inner square side 4sqrt2, area 32 (half of 64).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
