INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6259f272-e88a-4892-8d0e-16aa584e088e', 'PRE.13', 1, 'numeric', 'How changing the data changes the mean', 'Five numbers have a mean of 20. One of them, 12, is changed to 17. What is the new mean?', '[]', '21', '20+(17-12)/5', 'The total was $5\times20=100$. Changing 12 to 17 adds 5, so the total is 105. The new mean is $105\div5=21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 100, +5 -> 105; 105/5=21.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
