INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c144486e-ae37-4107-b90b-f0ff7d56db88', 'PRE.13', 1, 'choice', 'Adding or removing a value', 'The median of 2, 4, 8, 10 and 11 is 8. A sixth number, 12, is added to the list. What is the median of the six numbers?', '["$9$","$8$","$10$","$6$"]', '$9$', '(8+10)/2', 'Now the list 2, 4, 8, 10, 11, 12 has six numbers. The median is halfway between the 3rd and 4th, 8 and 10: $(8+10)\div2=9$.', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,4,8,10,11,12: median (8+10)/2=9.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
