INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e55da95-5e77-49e8-887d-25b9c80ba051', 'PRE.13', 1, 'choice', 'Comparing mean, median, mode and range', 'Which of these tells how spread out a list of numbers is, from the smallest to the largest?', '["The mean","The median","The mode","The range"]', 'The range', NULL, 'The range is the largest number minus the smallest, so it measures the spread. The mean, median and mode describe the middle or the most common value.', 'checked', '{"lint":[],"solve":{"answer":"The range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spread from smallest to largest is the range.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
