INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37a01c42-5935-4bb3-9d98-5e5867ba2aa9', 'PRE.13', 1, 'choice', 'Comparing mean, median, mode and range', 'Which of these is found by adding all the numbers and then dividing by how many numbers there are?', '["The mean","The median","The mode","The range"]', 'The mean', NULL, 'Adding the numbers and dividing by how many there are gives the mean. The median is the middle number in order, the mode is the most common, and the range is largest minus smallest.', 'checked', '{"lint":[],"solve":{"answer":"The mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum divided by count is the mean.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
