INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0f0f527-698c-4f74-a5d8-1e5e8e20b629', 'PRE.13', 2, 'choice', 'Range of a list', 'Which of these lists has the greatest range?', '["$5, 40, 22, 18$","$30, 31, 32, 60$","$100, 120, 90, 110$","$7, 8, 9, 10, 41$"]', '$5, 40, 22, 18$', NULL, 'The ranges are: $40-5=35$; $60-30=30$; $120-90=30$; $41-7=34$. The greatest is 35, from $5,40,22,18$. Big numbers do not make a big range: only the gap between largest and smallest matters.', 'checked', '{"lint":[],"solve":{"answer":"$5, 40, 22, 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 120-90=30. B: 40-5=35. C: 41-7=34. D: 60-30=30. Greatest B.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
