VALUES ('4179afba-808b-4b6b-bdee-3c4c21a2476f', 'PRE.13', 2, 'numeric', 'Range of a list', 'The range of five scores is 18. The lowest score is 62. What is the highest score?', '[]', '80', '62+18', 'Range = highest minus lowest, so highest = lowest plus range: $62+18=80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62+18=80.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
