INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60d1c99e-dcaa-41f4-bf1d-008afd153751', 'PRE.13', 2, 'choice', 'Totals and the mean', 'Rain fell on 5 days with a mean of 6 millimeters per day. On a sixth day, 4 more millimeters fell. How many millimeters fell in total over the six days?', '["$10$","$34$","$24$","$30$"]', '$34$', '6*5+4', 'The first five days gave $5\times6=30$ millimeters. Add the sixth day: $30+4=34$.', 'checked', '{"lint":[],"solve":{"answer":"$34$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*6=30; 30+4=34.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
