INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81e4696a-a0cb-4ea0-b53d-4df831172183', 'PRE.13', 2, 'numeric', 'Mean of two groups together', 'Two classes took the same test. The 20 students in class P had a mean score of 80. The 30 students in class Q had a mean score of 90. What was the mean score of all 50 students?', '[]', '86', '(80*20+90*30)/50', 'Class P total: $20\times80=1600$. Class Q total: $30\times90=2700$. All together: $4300$. Divide by 50: $4300\div50=86$.', 'checked', '{"lint":[],"solve":{"answer":"86","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20*80=1600, 30*90=2700; 4300/50=86.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('635968fd-05d5-4893-a806-64ea4fefbd67', 'PRE.13', 2, 'numeric', 'Mean of two groups together', 'Four boys have a mean weight of 150 pounds. Six girls have a mean weight of 140 pounds. What is the mean weight of all ten children, in pounds?', '[]', '144', '(150*4+140*6)/10', 'The boys weigh $4\times150=600$ pounds and the girls $6\times140=840$ pounds. Together that is 1440 pounds, so the mean is $1440\div10=144$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*150=600, 6*140=840; 1440/10=144.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
