INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2539d16b-2b46-462f-8a8a-b63c15b815f5', 'PRE.13', 2, 'choice', 'Mean of two groups together', 'The mean of 3 numbers is 12 and the mean of 2 other numbers is 17. What is the mean of all five numbers?', '["$14.5$","$14$","$29$","$70$"]', '$14$', '(12*3+17*2)/5', 'The first three total $3\times12=36$ and the other two total $2\times17=34$. All five total 70, so the mean is $70\div5=14$. (The mean is not halfway between 12 and 17, because the groups are different sizes.)', 'checked', '{"lint":[],"solve":{"answer":"$14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36+34=70; 70/5=14.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
