INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fe34827-b79e-4b11-bad7-d2f7610c6423', 'PRE.13', 2, 'numeric', 'How changing the data changes the mean', 'Eight numbers have a mean of 25. One of them, 40, is replaced by 24. What is the new mean?', '[]', '23', '25-(40-24)/8', 'The total was $8\times25=200$. Replacing 40 by 24 takes away 16, so the total is 184. The new mean is $184\div8=23$.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 200, -16 -> 184; 184/8=23.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
