INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('861844bc-f6cc-416d-be05-4275ea5ae4fb', 'PRE.13', 2, 'numeric', 'How changing the data changes the mean', 'Six numbers have a mean of 30. One of the numbers is increased by 12 and another is decreased by 6. What is the new mean?', '[]', '31', '30+(12-6)/6', 'The total was $6\times30=180$. The changes add $12-6=6$ to the total, which becomes 186. The new mean is $186\div6=31$.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 180, +12-6 -> 186; 186/6=31.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
