INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92c03bd7-3b5c-4f52-8960-558e30cb595e', 'PRE.13', 2, 'numeric', 'Adding or removing a value', 'The mean of six numbers is 15. One of them, 25, is removed. What is the mean of the five numbers left?', '[]', '13', '(15*6-25)/5', 'The six numbers total $6\times15=90$. Without 25 the total is 65, and the mean of five numbers is $65\div5=13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 90; 90-25=65; 65/5=13.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
