INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49b8be90-fc53-4a54-a6c2-2a6ae59e10eb', 'PRE.13', 2, 'choice', 'Adding or removing a value', 'The mean of five scores is 80. A sixth score of 92 is added. What is the mean of all six scores?', '["$86$","$82$","$80$","$84$"]', '$82$', '(80*5+92)/6', 'The first five total $5\times80=400$. With 92 the total is 492, and $492\div6=82$. (86 is halfway between 80 and 92, which ignores that 80 stands for five scores.)', 'checked', '{"lint":[],"solve":{"answer":"$82$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 400+92=492; 492/6=82.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
