INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dac708c-99ab-4b71-bdb1-9fd6159d326a', 'PRE.13', 2, 'numeric', 'Adding or removing a value', 'The seven numbers 2, 5, 9, 14, 20, 21 and 30 have a median of 14. The number 1 is added to the list. What is the new median?', '[]', '11.5', '(9+14)/2', 'The eight numbers in order are 1, 2, 5, 9, 14, 20, 21, 30. The median is halfway between the 4th and 5th: $(9+14)\div2=11.5$.', 'checked', '{"lint":[],"solve":{"answer":"11.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,2,5,9,14,20,21,30: median (9+14)/2=11.5.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
