INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86136092-6e86-462e-9d11-a7759dbaf3ae', 'PRE.13', 2, 'numeric', 'Comparing mean, median, mode and range', 'For the list 4, 5, 5, 6, 40, how much larger is the mean than the median?', '[]', '7', '(4+5+5+6+40)/5-5', 'The mean is $(4+5+5+6+40)\div5=60\div5=12$. The median (middle number) is 5. The mean is $12-5=7$ larger.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 60/5=12; median 5; difference 7.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
