INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90e30f02-cc0b-4926-8ff3-74459525bf5b', 'PRE.13', 2, 'choice', 'Comparing mean, median, mode and range', 'Which statement is true for the list 2, 3, 3, 4, 18?', '["The median is greater than the mean","The mode is greater than the median","The mean is greater than the median","The range is smaller than the mean"]', 'The mean is greater than the median', NULL, 'The mean is $30\div5=6$, the median is 3, the mode is 3 and the range is $18-2=16$. Only "the mean is greater than the median" is true: the large number 18 pulls the mean up but not the median.', 'checked', '{"lint":[],"solve":{"answer":"The mean is greater than the median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 30/5=6, median 3, mode 3, range 16. A true; B false (16>6); C false; D false (3=3).","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
