INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75fe6e5a-cfe7-453c-bd19-d17dc3b564fb', 'PRE.13', 2, 'numeric', 'Comparing mean, median, mode and range', 'For the list 10, 12, 12, 14, 22, what is the sum of the mean, the median and the mode?', '[]', '38', '(10+12+12+14+22)/5+12+12', 'The mean is $70\div5=14$. The median is 12 and the mode is 12. The sum is $14+12+12=38$.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 70/5=14, median 12, mode 12; 14+12+12=38.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
