INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21fbc870-0381-434c-9422-25023297d37c', 'PRE.13', 2, 'numeric', 'Data given as counts', 'Among 10 students, 3 wear size 5 shoes, 5 wear size 6 and 2 wear size 7. What is the mean shoe size?', '[]', '5.9', '(5*3+6*5+7*2)/10', 'The sizes total $3\times5+5\times6+2\times7=15+30+14=59$. The mean is $59\div10=5.9$.', 'checked', '{"lint":[],"solve":{"answer":"5.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15+30+14=59; 59/10=5.9.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
