INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f917d2af-0441-484e-9e27-76c22aba7ace', 'PRE.13', 2, 'numeric', 'Data given as counts', 'A jar holds 4 coins worth 5 cents, 3 coins worth 10 cents and 3 coins worth 20 cents. What is the mean value of a coin, in cents?', '[]', '11', '(5*4+10*3+20*3)/10', 'The coins total $20+30+60=110$ cents. There are 10 coins, so the mean is $110\div10=11$ cents.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20+30+60=110; 110/10=11.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
