INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2cfaaba-0077-4a2d-8cae-dba4fa886165', 'PRE.13', 3, 'numeric', 'Mean of a list', 'What is the mean of all the whole numbers from 1 to 49?', '[]', '25', '(1+49)/2', 'The numbers are evenly spread, so the mean is halfway between the smallest and the largest: $(1+49)\div2=25$. (Pairing 1 with 49, 2 with 48, and so on, gives pairs that each add to 50, so the middle number 25 is the mean.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 1..49 = 49*50/2 = 1225; 1225/49 = 25 (the middle number).","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
