INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92bfcb6b-41b8-4825-b160-5824c3edab2f', 'PRE.13', 3, 'choice', 'Mean of a list', 'What is the mean of 1.2, 0.8, 2.5 and 1.5?', '["$1.35$","$6$","$1.7$","$1.5$"]', '$1.5$', '(1.2+0.8+2.5+1.5)/4', 'The sum is $1.2+0.8+2.5+1.5=6$. Divide by 4: $6\div4=1.5$. ($1.35$ is the median, $6$ is the sum and $1.7$ is the range.)', 'checked', '{"lint":[],"solve":{"answer":"$1.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2+0.8+2.5+1.5=6; 6/4=1.5.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
