INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13238ee3-7b8c-41a7-821a-9f233a519177', 'PRE.13', 3, 'numeric', 'Median of a list', 'Five different numbers have a median of 12. Four of them are 5, 9, 20 and 31. What is the fifth number?', '[]', '12', '12', 'The median of five numbers is the 3rd in order. With 5, 9, 20, 31 already there, the fifth number must go between 9 and 20 to be 3rd. Then it is the median itself, so it is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted known: 5,9,20,31. Median of five is the 3rd. If the fifth number were below 9 the median would be 9; above 20 it would be 20; between 9 and 20 it is the fifth number itself, so it must be 12 (different from the others, ok).","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d8fdfdf-f2e0-4bf7-b192-83cc6dd53867', 'PRE.13', 3, 'choice', 'Median of a list', 'Which of these lists has a median of 6?', '["$1, 9, 6, 3, 7$","$2, 4, 6, 8$","$10, 3, 6, 1, 2$","$6, 1, 2, 3, 9, 11$"]', '$1, 9, 6, 3, 7$', NULL, 'Put each list in order. $1,3,6,7,9$ has middle number 6. $2,4,6,8$ has median $5$. $1,2,3,6,10$ has median $3$. $1,2,3,6,9,11$ has median $4.5$. Only the first list has median 6.', 'checked', '{"lint":[],"solve":{"answer":"$1, 9, 6, 3, 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 1,3,6,7,9 median 6. B: 1,2,3,6,10 median 3. C: 1,2,3,6,9,11 median 4.5. D: 2,4,6,8 median 5. Only A.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1d0b295-0779-4c96-bc80-3ad30bed1a0e', 'PRE.13', 3, 'numeric', 'Median of a list', 'The numbers 4, 9, 15, 2, 11 and x are listed, where x is a whole number bigger than 15. What is the median of the six numbers?', '[]', '10', '(9+11)/2', 'Since x is bigger than 15, the order is 2, 4, 9, 11, 15, x. The median is halfway between the 3rd and 4th numbers: $(9+11)\div2=10$. It does not matter which number x is.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x>15 so sorted 2,4,9,11,15,x; median (9+11)/2=10.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
