INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('136c479e-7700-42c3-bed9-92023e8e13bb', 'PRE.13', 3, 'choice', 'Mode of a list', 'Which list has a mean of 6, a median of 5 and a mode of 4?', '["$4, 4, 5, 8, 9$","$4, 5, 5, 7, 9$","$4, 4, 6, 7, 9$","$3, 4, 4, 5, 9$"]', '$4, 4, 5, 8, 9$', NULL, 'The list $4,4,5,8,9$ has sum 30, so the mean is 6; its middle number is 5 and 4 appears twice. The list $4,5,5,7,9$ has mode 5. The list $4,4,6,7,9$ has median 6. The list $3,4,4,5,9$ has mean 5.', 'checked', '{"lint":[],"solve":{"answer":"$4, 4, 5, 8, 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 30 mean 6, median 5, mode 5 (no). B: 4,4,5,8,9 sum 30 mean 6, median 5, mode 4 (yes). C: median 6. D: sum 25 mean 5. B.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
