INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3949d8f-ec36-4039-92c9-52f231f6b601', 'PRE.13', 3, 'numeric', 'Range of a list', 'The range of the numbers 3, 15, x, 8, 11 and 6 is 20, and x is bigger than all the other numbers. What is x?', '[]', '23', '3+20', 'The smallest number is 3, and x is the largest. Largest minus smallest is 20, so $x=3+20=23$.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min is 3; x-3=20 so x=23.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8de04b28-fc5c-4a99-aaf8-eaf5441ec30b', 'PRE.13', 3, 'numeric', 'Range of a list', 'What is the smallest possible range of a list of five different whole numbers?', '[]', '4', '5-1', 'The closest five different whole numbers are consecutive, such as 1, 2, 3, 4, 5. Their range is $5-1=4$. Any other five different whole numbers are at least as spread out.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Five different whole numbers: consecutive like 1..5 give range 4; any five distinct integers span at least 4.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ede300d-d0f7-41da-889c-c342eaa297cf', 'PRE.13', 3, 'numeric', 'Range of a list', 'In one week the hottest day was 3 degrees more than twice the temperature of the coolest day. The range of the week''s temperatures was 14 degrees. What was the hottest temperature, in degrees?', '[]', '25', '2*11+3', 'If the coolest day was c degrees, the hottest was $2c+3$. The range is $(2c+3)-c=c+3=14$, so $c=11$. The hottest day was $2\times11+3=25$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"H=2L+3 and H-L=14, so L+3=14, L=11, H=25.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('889a3628-845b-4268-870f-7ce793b77941', 'PRE.13', 3, 'numeric', 'Missing value for a given mean', 'After 5 games a player had scored a mean of 14 points per game. What mean number of points must the player score over the next 3 games so that the mean over all 8 games is 17?', '[]', '22', '(17*8-14*5)/3', 'After 8 games the total must be $8\times17=136$. The first 5 games gave $5\times14=70$. The last 3 games must give $136-70=66$, a mean of $66\div3=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total needed 8*17=136; have 5*14=70; next 3 games total 66, mean 22.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f32ff3-4974-4189-b8b3-452050d9b267', 'PRE.13', 3, 'numeric', 'Missing value for a given mean', 'Five numbers have a mean of 20. The largest is 36, and the other four are all equal. What is each of the other four?', '[]', '16', '(20*5-36)/4', 'The total is $5\times20=100$. Without 36, the other four total 64, so each is $64\div4=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 100; 100-36=64; 64/4=16.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('450b11aa-0229-4803-9a4b-32e589c1f33d', 'PRE.13', 3, 'numeric', 'Missing value for a given mean', 'The mean of five test scores is 84. When the highest score is removed, the mean of the other four is 80. What was the highest score?', '[]', '100', '84*5-80*4', 'The five scores total $5\times84=420$. The four others total $4\times80=320$. The highest is $420-320=100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*84=420; 4*80=320; highest 100.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32498f43-b9da-4363-8215-cf2e770adb19', 'PRE.13', 3, 'numeric', 'Totals and the mean', 'Seven numbers have a mean of 18. The mean of the first four is 15 and the mean of the last four is 21. (The fourth number is in both groups.) What is the fourth number?', '[]', '18', '15*4+21*4-18*7', 'The seven numbers total $7\times18=126$. The first four total 60 and the last four total 84, so together $60+84=144$. This counts the fourth number twice, so it is $144-126=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 7*18=126. First four sum 60, last four sum 84; 60+84=144 counts the fourth twice, so fourth = 144-126=18.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1f894e8-eddf-44c1-99eb-727f40e9f511', 'PRE.13', 3, 'numeric', 'Totals and the mean', 'Seven numbers have a mean of 9. Three of them have a mean of 5. What is the mean of the other four?', '[]', '12', '(9*7-5*3)/4', 'The seven numbers total $7\times9=63$. The three total $3\times5=15$. The other four total $63-15=48$, so their mean is $48\div4=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 63; three sum 15; other four 48; mean 12.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb5c15b6-4257-4f3b-a623-6e9cf7f5d146', 'PRE.13', 3, 'choice', 'Totals and the mean', 'The sum of a list of numbers is 132, and their mean is 12. How many numbers are in the list?', '["$120$","$144$","$11$","$12$"]', '$11$', '132/12', 'Mean = sum divided by how many, so how many = sum divided by mean: $132\div12=11$.', 'checked', '{"lint":[],"solve":{"answer":"$11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"132/12=11.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('568fd445-a835-48a9-8567-cee65b6923a6', 'PRE.13', 3, 'numeric', 'Mean of two groups together', 'In a class the mean test score is 78. The 12 girls have a mean score of 80 and the boys have a mean score of 75. How many boys are in the class?', '[]', '8', '(80-78)*12/(78-75)', 'Let b be the number of boys. Total points: $75b+80\times12=78(b+12)$, so $75b+960=78b+936$. Then $3b=24$ and $b=8$. Check: $600+960=1560$ and $1560\div20=78$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"960+75b=78(12+b)=936+78b; 24=3b; b=8.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('138ffeb5-aa89-477d-9351-61742a15bc73', 'PRE.13', 3, 'numeric', 'Mean of two groups together', 'Six numbers have a mean of 10. Some other numbers have a mean of 20. All the numbers together have a mean of 16. How many other numbers are there?', '[]', '9', '6*(16-10)/(20-16)', 'Let n be the number of other numbers. Then $60+20n=16(6+n)=96+16n$, so $4n=36$ and $n=9$. Check: $60+180=240$ and $240\div15=16$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60+20n=16(6+n)=96+16n; 4n=36; n=9.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61e15661-ed2a-4e91-b3ae-237e4083bb02', 'PRE.13', 3, 'choice', 'Mean of two groups together', 'The mean of 15 numbers is 8. Ten more numbers are added. The mean of all 25 numbers is 10. What is the mean of the ten new numbers?', '["$9$","$18$","$13$","$15$"]', '$13$', '(10*25-8*15)/10', 'All 25 numbers total $25\times10=250$. The first 15 total $15\times8=120$. The ten new numbers total $250-120=130$, so their mean is $130\div10=13$.', 'checked', '{"lint":[],"solve":{"answer":"$13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25*10=250; 15*8=120; new ten sum 130; mean 13.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbbd01ad-bbe4-445b-ba8c-6421a4ba7acf', 'PRE.13', 3, 'numeric', 'How changing the data changes the mean', 'Nine numbers were found to have a mean of 22, but one of them was read as 35 when it should have been 53. What is the correct mean?', '[]', '24', '(22*9-35+53)/9', 'The total with the mistake was $9\times22=198$. Replacing 35 by 53 adds 18, so the correct total is 216. The correct mean is $216\div9=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 198, +18 -> 216; 216/9=24.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0d64c9d-eedd-4b3d-913b-0f2b7d9281e4', 'PRE.13', 3, 'numeric', 'How changing the data changes the mean', 'A list of numbers has a mean of 40. One of the numbers is increased by 30, and the mean becomes 43. How many numbers are in the list?', '[]', '10', '30/3', 'Increasing one number by 30 adds 30 to the total. That raises the mean by 3, so $30\div n=3$ and $n=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean rises 3 when sum rises 30: 30/n=3, n=10.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
