INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30e9fb28-c234-4921-8932-177a673ab39d', 'PRE.13', 3, 'choice', 'How changing the data changes the mean', 'A list of 4 numbers has a mean of 10. Each number is replaced by three times itself minus 4. What is the sum of the new numbers?', '["$26$","$116$","$104$","$120$"]', '$104$', '4*(3*10-4)', 'The new mean is $3\times10-4=26$. With 4 numbers, the sum is $4\times26=104$. ($116$ forgets to take 4 off each of the four numbers.)', 'checked', '{"lint":[],"solve":{"answer":"$104$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 40; new sum 3*40-4*4=104.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf3e6d2-332f-4496-a779-eb2fa41a9d74', 'PRE.13', 3, 'numeric', 'Adding or removing a value', 'The mean of five numbers is 12. A sixth number, x, is added, and the mean of the six numbers is 14. What is x?', '[]', '24', '14*6-12*5', 'The five numbers total $5\times12=60$. The six total $6\times14=84$. So $x=84-60=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*14=84; 5*12=60; x=24.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
