VALUES ('6bb0e332-6f7c-46c1-b1a1-30df28ab708a', 'PRE.14', 1, 'choice', 'Coins, dice and repeated choices', 'A red die and a blue die are rolled together. How many different outcomes are there?', '["$12$","$36$","$6$","$30$"]', '$36$', '6*6', 'The red die has 6 results and the blue die has 6 results: $6\times6=36$.', 'checked', '{"lint":[],"solve":{"answer":"$36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*6=36.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
