INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('837be35e-1e01-46cc-8e89-3dafd293f508', 'PRE.14', 2, 'choice', 'The multiplication principle', 'An ice cream shop has 6 flavors, 3 kinds of cone and 4 toppings. A treat is one flavor, one cone and one topping. How many different treats are there?', '["$13$","$18$","$24$","$72$"]', '$72$', '6*3*4', 'Multiply the choices: $6\times3\times4=72$.', 'checked', '{"lint":[],"solve":{"answer":"$72$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*3*4=72.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
