INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f652189e-06dc-451a-af62-f56517250f89', 'PRE.14', 2, 'choice', 'The multiplication principle', 'A password is one letter from A, B, C, D, E, then one digit from 0 to 9, then one symbol from 3 symbols. How many different passwords are there?', '["$150$","$18$","$50$","$30$"]', '$150$', '5*10*3', 'Multiply the numbers of choices: $5\times10\times3=150$. (Adding gives 18, which is wrong because every choice can go with every other.)', 'checked', '{"lint":[],"solve":{"answer":"$150$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*10*3=150.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
