INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9fc724e-01a7-4da4-a56f-84c96e7db363', 'PRE.14', 2, 'choice', 'The multiplication principle', 'To travel from city P to city Q you must pass through city R and then city S. There are 3 roads from P to R, 4 roads from R to S and 2 roads from S to Q. How many different routes are there from P to Q?', '["$9$","$24$","$12$","$8$"]', '$24$', '3*4*2', 'Multiply the choices at each stage: $3\times4\times2=24$.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*4*2=24.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
