INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3259e34f-bd12-469f-a560-ed507ea5d6c3', 'PRE.14', 2, 'choice', 'Digits, codes and numbers', 'How many 3-digit numbers can be made from the digits 1, 2, 3 and 4, if no digit may be used more than once in a number?', '["$12$","$24$","$64$","$9$"]', '$24$', '4*3*2', 'There are 4 choices for the hundreds digit, then 3 for the tens digit and 2 for the ones digit: $4\times3\times2=24$.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*3*2=24.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
