INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('403690d3-2c6b-40da-8f19-e388231c950b', 'PRE.14', 2, 'choice', 'Digits, codes and numbers', 'How many 3-digit whole numbers are there?', '["$999$","$899$","$900$","$1000$"]', '$900$', '999-100+1', 'The 3-digit numbers go from 100 to 999. The count is $999-100+1=900$. (Or: 9 choices for the first digit, 10 each for the others: $9\times10\times10$.)', 'checked', '{"lint":[],"solve":{"answer":"$900$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100..999: 900.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
