INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0e9754c-5886-4f8f-8c37-f7fd13a29c50', 'PRE.14', 2, 'numeric', 'Digits, codes and numbers', 'A 4-digit code uses the digits 0 to 9. The first digit cannot be 0, but digits may repeat. How many different codes are possible?', '[]', '9000', '9*10*10*10', 'There are 9 choices for the first digit and 10 for each of the other three: $9\times10\times10\times10=9000$.', 'checked', '{"lint":[],"solve":{"answer":"9000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9*10*10*10=9000.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
