INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d04fd71e-9f99-43d6-9450-d8e92b6c80c0', 'PRE.14', 2, 'choice', 'Casework', 'In how many ways can you make exactly 30 cents using only dimes (10 cents) and nickels (5 cents)? Either kind may be left out.', '["$3$","$6$","$7$","$4$"]', '$4$', '4', 'Split by the number of dimes. 0 dimes: 6 nickels. 1 dime: 4 nickels. 2 dimes: 2 nickels. 3 dimes: 0 nickels. That makes 4 ways.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dimes 0,1,2,3 each with nickels making up the rest: 4.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
