INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d815f2d0-1200-4d82-9607-4acf4ae9bcac', 'PRE.14', 2, 'numeric', 'Casework', 'To go from town A to town C you can drive straight there on one of 2 roads, or you can go through town B, using one of 3 roads from A to B and one of 2 roads from B to C. How many different ways are there to get from A to C?', '[]', '8', '2+3*2', 'Case 1, straight there: 2 ways. Case 2, through B: $3\times2=6$ ways. The cases do not overlap, so the total is $2+6=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Direct 2 + via B 3*2=6: 8.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8587193c-7d95-45de-bbb1-2c1bfaef3f02', 'PRE.14', 2, 'numeric', 'Counting the complement', 'How many two-digit numbers have at least one digit equal to 5?', '[]', '18', '90-8*9', 'Count the opposite. Numbers with no 5: 8 choices for the tens digit (1 to 9 without 5) and 9 for the ones digit (0 to 9 without 5): $8\times9=72$. So $90-72=18$ have a 5.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tens digit 5: 10 numbers; units 5 with tens not 5: 8; total 18 (complement: 90-8*9=18).","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f09423aa-2595-4467-96a6-1148b022f7f2', 'PRE.14', 2, 'choice', 'Counting the complement', 'A red die and a blue die are rolled. In how many of the 36 outcomes is the total not 7?', '["$30$","$6$","$35$","$29$"]', '$30$', '36-6', 'The total is 7 in 6 outcomes: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). So $36-6=30$ outcomes are not 7.', 'checked', '{"lint":[],"solve":{"answer":"$30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 7 in 6 outcomes; 36-6=30.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
