INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66685d96-0ead-4b4c-af11-1aee7f72579b', 'PRE.14', 2, 'numeric', 'Counting the complement', 'Four-letter lists are made using the letters A, B and C, and letters may repeat (like ABCA). How many of these lists have at least one A?', '[]', '65', '3^4-2^4', 'All lists: $3^4=81$. Lists with no A use only B and C: $2^4=16$. So $81-16=65$ have at least one A.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^4=81 total; no A: 2^4=16; 81-16=65.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
