INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('313fcebf-afdf-431c-b31b-6d61fd273602', 'PRE.14', 2, 'choice', 'Arranging objects in a row', 'Six guests sit down in six chairs in a row. In how many different ways can they be seated?', '["$36$","$720$","$120$","$21$"]', '$720$', '6*5*4*3*2*1', '$6\times5\times4\times3\times2\times1=720$.', 'checked', '{"lint":[],"solve":{"answer":"$720$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6!=720.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
