INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddf54b92-b8dc-4de1-8c53-6aa4c780cc3b', 'PRE.14', 2, 'numeric', 'Arranging objects in a row', 'The number of ways to line up 6 different children is how many times the number of ways to line up 5 different children?', '[]', '6', '(6*5*4*3*2*1)/(5*4*3*2*1)', 'Lining up 6 children can be done in $6\times5\times4\times3\times2\times1$ ways; lining up 5 in $5\times4\times3\times2\times1$. The first number is 6 times the second.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6!/5!=6.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
