INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdfb6528-b21f-424a-bec5-e4b2d2d41ea6', 'PRE.14', 2, 'numeric', 'Arranging with a condition', 'Ana and Ben hold the two ends of a banner. Three other children stand in a row between them to hold the middle. In how many different orders can the three children stand?', '[]', '6', '3*2*1', 'Ana and Ben are fixed. The other 3 people fill the middle 3 places in $3\times2\times1=6$ ways.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3!=6.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
