INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('781e79a6-6e20-4a42-b049-056487a64bbb', 'PRE.14', 2, 'numeric', 'Arranging with a condition', 'Eli and Fay want to sit next to each other in a row of 4 chairs. Two other children also sit in the row. In how many different ways can the four children be seated if Eli and Fay must sit side by side?', '[]', '12', '3*2*1*2', 'Treat Eli and Fay as one block. The block and the 2 other children can be arranged in $3\times2\times1=6$ ways. Inside the block, Eli and Fay can be in 2 orders. $6\times2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pair occupies chairs 1-2, 2-3 or 3-4 (3 ways), 2 orders within, other two children 2 ways: 3*2*2=12.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
