VALUES ('914a2c0b-fa8b-48cb-a231-1c63298407df', 'PRE.14', 2, 'choice', 'Choosing in order (offices and places)', 'Ten runners are in a race, with no ties. In how many ways can first, second and third places be filled?', '["$27$","$720$","$1000$","$90$"]', '$720$', '10*9*8', '10 choices for first, 9 for second and 8 for third: $10\times9\times8=720$.', 'checked', '{"lint":[],"solve":{"answer":"$720$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*9*8=720.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
