VALUES ('b657c868-83a2-4e5c-aa95-a2240af05a94', 'PRE.14', 2, 'choice', 'Choosing in order (offices and places)', 'A club of 8 students elects a president, a vice president and a treasurer, all different people. In how many ways can this be done?', '["$56$","$512$","$336$","$24$"]', '$336$', '8*7*6', '8 choices for president, 7 for vice president, 6 for treasurer: $8\times7\times6=336$. ($512$ would let one person hold more than one job.)', 'checked', '{"lint":[],"solve":{"answer":"$336$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*7*6=336.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
