INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcb78b92-1bc2-4921-843b-7d15c3a7e3c7', 'PRE.14', 2, 'numeric', 'Overlapping groups', 'In a class of 30 students, 18 are in the choir, 14 are in the band and 6 are in both. How many students are in neither?', '[]', '4', '30-(18+14-6)', 'In choir or band: $18+14-6=26$. In neither: $30-26=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18+14-6=26; 30-26=4.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
