INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7090e05c-3ea2-460d-82c1-8bb05960f98f', 'PRE.14', 2, 'choice', 'Overlapping groups', 'Everyone in a group of 40 people speaks Spanish or French (or both). 25 speak Spanish and 20 speak French. How many speak both?', '["$45$","$15$","$5$","$20$"]', '$5$', '25+20-40', 'Adding 25 and 20 gives 45, which is 5 more than the 40 people. Those 5 were counted twice, so 5 people speak both.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25+20-40=5.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
