INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff81b475-f12a-4959-a5fe-19c716a8c530', 'PRE.14', 2, 'numeric', 'Overlapping groups', 'How many of the whole numbers from 1 to 30 are multiples of 2 or multiples of 3 (or both)?', '[]', '20', '15+10-5', 'Multiples of 2: 15. Multiples of 3: 10. Multiples of both (the multiples of 6): 5. So $15+10-5=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 2: 15; of 3: 10; of 6: 5; 15+10-5=20.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
