INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a7d535c-5177-4cd9-8504-97890e921279', 'PRE.14', 2, 'numeric', 'Choosing from separate groups', 'From 4 different maths books and 3 different art books, Eli picks 2 maths books and 1 art book. How many different selections can he make?', '[]', '18', '(4*3/2)*3', 'Choose 2 of the 4 maths books: $\frac{4\times3}{2}=6$ ways. Choose 1 art book: 3 ways. $6\times3=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(4,2)*3=6*3=18.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
