INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e4c0428-5903-44fc-8c2d-cc2c36d6474a', 'PRE.14', 2, 'choice', 'Choosing from separate groups', 'A committee has 2 boys chosen from 5 boys and 1 girl chosen from 4 girls. How many different committees are possible?', '["$60$","$20$","$40$","$45$"]', '$40$', '(5*4/2)*4', 'Choose 2 boys from 5: $\frac{5\times4}{2}=10$ ways. Choose 1 girl from 4: 4 ways. $10\times4=40$.', 'checked', '{"lint":[],"solve":{"answer":"$40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(5,2)*4=10*4=40.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
