INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77bbab19-0fa9-4d8a-bb0a-6fc6b2ba1cc2', 'PRE.14', 2, 'numeric', 'Choosing from separate groups', 'A class has 6 boys and 5 girls. The teacher picks 2 boys and 2 girls for a skit. How many different groups of 4 can she pick?', '[]', '150', '(6*5/2)*(5*4/2)', 'Boys: $\frac{6\times5}{2}=15$ ways. Girls: $\frac{5\times4}{2}=10$ ways. $15\times10=150$.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(6,2)*C(5,2)=15*10=150.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
