VALUES ('4a98f46d-bca6-4646-baba-a245ab62973f', 'PRE.14', 2, 'choice', 'Coins, dice and repeated choices', 'A quiz has 5 true-or-false questions. In how many different ways can all five questions be answered?', '["$10$","$25$","$16$","$32$"]', '$32$', '2^5', 'Each question has 2 answers: $2\times2\times2\times2\times2=32$.', 'checked', '{"lint":[],"solve":{"answer":"$32$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5=32.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
