INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10d22384-5f24-4e9f-bbbb-11cf40fe8dc9', 'PRE.14', 3, 'numeric', 'The multiplication principle', 'How many different positive whole numbers divide 72 exactly?', '[]', '12', '4*3', 'Write $72=2\times2\times2\times3\times3=2^3\times3^2$. A factor uses 0, 1, 2 or 3 twos (4 choices) and 0, 1 or 2 threes (3 choices): $4\times3=12$. (They are 1, 2, 3, 4, 6, 8, 9, 12, 18, 24, 36, 72.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72=2^3*3^2; divisors (3+1)(2+1)=12: 1,2,3,4,6,8,9,12,18,24,36,72.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
