INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec86b0eb-e461-4e91-a347-1f71bec4c657', 'PRE.14', 3, 'numeric', 'The multiplication principle', 'There are 5 different bus routes between town A and town B. Mia rides from A to B on one route and rides back on a different route. How many different round trips can she make?', '[]', '20', '5*4', 'There are 5 choices for the trip out. For the trip back there are only 4 routes left. So $5\times4=20$ round trips.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 choices there, 4 different choices back: 20.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
