INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd19a5b0-6b8f-4011-b86f-44d8e3900fc3', 'PRE.14', 3, 'choice', 'The multiplication principle', 'Jo has 4 shirts, 3 pairs of pants and 2 pairs of shoes. She will not wear her red shirt with her blue pants. How many different outfits (shirt, pants and shoes) can she make?', '["$24$","$20$","$22$","$18$"]', '$22$', '4*3*2-2', 'Without the rule there are $4\times3\times2=24$ outfits. The forbidden red shirt with blue pants can go with either pair of shoes, so 2 outfits are not allowed. $24-2=22$.', 'checked', '{"lint":[],"solve":{"answer":"$22$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All outfits 4*3*2=24; forbidden red shirt + blue pants with any of 2 shoes: 2; 24-2=22.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c216ba6-bc7a-4462-bb9c-dd355c2cf079', 'PRE.14', 3, 'numeric', 'Digits, codes and numbers', 'A 3-digit number is written so that no digit is used twice (and the first digit is not 0). How many such numbers are there?', '[]', '648', '9*9*8', 'The hundreds digit has 9 choices (not 0). The tens digit can be 0 or any digit except the first: 9 choices. The ones digit has 8 choices left. $9\times9\times8=648$.', 'checked', '{"lint":[],"solve":{"answer":"648","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 9 (1-9), second 9 (any but first, 0 allowed), third 8: 648.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('059db79f-5f99-4d1e-b38c-371fc7104451', 'PRE.14', 3, 'numeric', 'Digits, codes and numbers', 'Rosa writes down every odd number from 100 to 999 whose three digits are all different from each other. How many numbers does she write?', '[]', '320', '5*8*8', 'Choose the ones digit first: it must be 1, 3, 5, 7 or 9, so 5 choices. The hundreds digit cannot be 0 or the ones digit: 8 choices. The tens digit is any of the 8 digits not yet used. $5\times8\times8=320$.', 'checked', '{"lint":[],"solve":{"answer":"320","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Units odd: 5 choices; hundreds nonzero and not the units digit: 8; tens any of remaining 8: 5*8*8=320.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15425a5d-e71a-4488-9e74-0543d15f2971', 'PRE.14', 3, 'choice', 'Digits, codes and numbers', 'How many whole numbers from 1 to 200 have no digit 0 in them?', '["$180$","$162$","$190$","$171$"]', '$171$', '9+81+81', 'Count by length. 1 to 9: 9 numbers. 10 to 99: 9 choices for the tens digit and 9 (1 to 9) for the ones digit, $81$. 100 to 199: the hundreds digit is 1, then $9\times9=81$. The number 200 has 0s. Total $9+81+81=171$.', 'checked', '{"lint":[],"solve":{"answer":"$171$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-9: 9; 10-99: 9*9=81; 100-199: 1 then 9*9=81; 200 has a 0. Total 171.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d635d52-c8db-42aa-b687-7ff81824ca4e', 'PRE.14', 3, 'numeric', 'Casework', 'In how many ways can you make exactly 40 cents using quarters (25 cents), dimes (10 cents) and nickels (5 cents)? Any of the three kinds may be left out.', '[]', '7', '5+2', 'Split by the number of quarters. No quarter: 40 cents from dimes and nickels, with 0, 1, 2, 3 or 4 dimes and nickels filling the rest: 5 ways. One quarter: 15 cents left, with 0 or 1 dime: 2 ways. Two quarters is too much. Total $5+2=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One quarter: 15 left -> 1 dime+1 nickel or 3 nickels: 2. No quarter: dimes 0-4 with nickels: 5. Total 7.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48ea33c4-e193-4a49-a0ac-7a14827e02bf', 'PRE.14', 3, 'choice', 'Casework', 'How many 3-digit numbers have digits that add up to 4?', '["$10$","$9$","$12$","$6$"]', '$10$', '10', 'Split by the hundreds digit. 1: the other two digits add to 3, giving 103, 112, 121, 130 (4 numbers). 2: they add to 2, giving 202, 211, 220 (3). 3: they add to 1, giving 301, 310 (2). 4: 400 (1). Total $4+3+2+1=10$.', 'checked', '{"lint":[],"solve":{"answer":"$10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First digit a>=1, b+c=4-a: a=1:4, a=2:3, a=3:2, a=4:1; total 10.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ed7a913-d862-4dc4-86b8-3fdb6319eede', 'PRE.14', 3, 'numeric', 'Casework', 'A red die and a blue die are rolled. In how many outcomes is the total 8 or 9?', '[]', '9', '5+4', 'Total 8: (2,6), (3,5), (4,4), (5,3), (6,2), 5 outcomes. Total 9: (3,6), (4,5), (5,4), (6,3), 4 outcomes. The cases do not overlap: $5+4=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 8: (2,6),(3,5),(4,4),(5,3),(6,2)=5; total 9: (3,6),(4,5),(5,4),(6,3)=4; 9.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
