INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbe209a2-be65-4055-a937-4a2cfb944358', 'PRE.14', 3, 'numeric', 'Counting the complement', 'How many 3-digit numbers have at least one digit equal to 7?', '[]', '252', '900-8*9*9', 'There are 900 three-digit numbers. With no 7: 8 choices for the hundreds digit (1 to 9, not 7) and 9 for each other digit, $8\times9\times9=648$. So $900-648=252$.', 'checked', '{"lint":[],"solve":{"answer":"252","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"900 total; no 7: 8*9*9=648; 900-648=252.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e313133-eba6-4b5b-b925-d29647df2dcd', 'PRE.14', 3, 'numeric', 'Counting the complement', 'A committee of 3 people is chosen from 4 men and 3 women. How many different committees have at least one woman?', '[]', '31', '35-4', 'There are $\frac{7\times6\times5}{3\times2\times1}=35$ committees in all. Those with no woman use only the men: 4 committees. So $35-4=31$.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(7,3)=35; all men C(4,3)=4; 35-4=31.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('150def1b-620d-49b7-a702-1fdf0e57f48b', 'PRE.14', 3, 'choice', 'Counting the complement', 'In how many different orders can the letters A, B, C and D be put in a row so that A is not first?', '["$6$","$18$","$12$","$24$"]', '$18$', '24-6', 'All orders: $4\times3\times2\times1=24$. Orders with A first: the other 3 letters can follow in $3\times2\times1=6$ ways. So $24-6=18$.', 'checked', '{"lint":[],"solve":{"answer":"$18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4!=24; A first: 3!=6; 24-6=18.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('434fe6e7-81d1-43bd-b675-af50f99cfb8a', 'PRE.14', 3, 'numeric', 'Arranging objects in a row', 'How many different ways can the letters of the word BOOK be arranged in a row? (Swapping the two O''s does not make a new arrangement.)', '[]', '12', '(4*3*2*1)/2', 'If all 4 letters were different there would be $4\times3\times2\times1=24$ orders. But swapping the two O''s gives the same word, so each arrangement was counted twice. $24\div2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4!/2!=12.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8775e3ad-25a6-40d6-8fec-f379c5ec0b44', 'PRE.14', 3, 'choice', 'Arranging objects in a row', 'How many different 4-letter arrangements can be made using the letters of the word MAMA, each letter once?', '["$24$","$12$","$6$","$4$"]', '$6$', '(4*3*2*1)/(2*2)', 'If all 4 letters were different there would be 24 orders. The two M''s can swap and the two A''s can swap without changing the word, so each arrangement was counted $2\times2=4$ times. $24\div4=6$. (MMAA, MAMA, MAAM, AMMA, AMAM, AAMM.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4!/(2!2!)=6.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15dd9510-b369-45c7-8581-0e4be91d2209', 'PRE.14', 3, 'numeric', 'Arranging objects in a row', 'A group of children can line up in 120 different orders. How many children are in the group?', '[]', '5', '5', 'Try small groups: 3 children make $3\times2\times1=6$ orders, 4 make 24, and 5 make $5\times4\times3\times2\times1=120$. So there are 5 children.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5!=120, so 5 children.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ef7e390-b953-412f-87e2-05747591e317', 'PRE.14', 3, 'numeric', 'Arranging with a condition', 'Five people line up. Ana and Ben must NOT stand next to each other. How many different orders are possible?', '[]', '72', '120-4*3*2*1*2', 'All orders: $5\times4\times3\times2\times1=120$. Orders with Ana and Ben side by side: treat them as a block, $4\times3\times2\times1=24$ orders of the block with the 3 others, times 2 orders inside the block, $48$. So $120-48=72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5!=120; together: treat as block 4!*2=48; 120-48=72.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf7e9be6-86be-419e-8aeb-0baab2d1214c', 'PRE.14', 3, 'numeric', 'Arranging with a condition', 'On a shelf there are 3 different maths books and 2 different science books. In how many different orders can all 5 books be placed in a row if the 3 maths books must be next to each other?', '[]', '36', '3*2*1*3*2*1', 'Treat the 3 maths books as one block. The block and the 2 science books can be arranged in $3\times2\times1=6$ ways. Inside the block the maths books can be ordered in $3\times2\times1=6$ ways. $6\times6=36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maths block plus 2 science books: 3! orders, times 3! inside block: 36.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
