INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73c02184-ddeb-4b82-8eb4-be43103ebe1e', 'PRE.14', 3, 'choice', 'Arranging with a condition', 'Using each of the digits 1, 2, 3, 4 and 5 exactly once, how many 5-digit numbers can be made that are multiples of 5?', '["$120$","$24$","$96$","$5$"]', '$24$', '4*3*2*1', 'A multiple of 5 must end in 0 or 5, and there is no 0, so the last digit is 5. The other 4 digits fill the first four places in $4\times3\times2\times1=24$ ways.', 'checked', '{"lint":[],"solve":{"answer":"$24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must end in 5; other four digits 4!=24.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba5258c8-00ba-4164-b013-106c538fef0a', 'PRE.14', 3, 'numeric', 'Choosing in order (offices and places)', 'A club has 7 members, including Mo. It elects a president, a vice president and a treasurer, all different people. Mo must hold one of the three jobs. In how many ways can this be done?', '[]', '90', '3*6*5', 'Choose which job Mo has: 3 ways. Then fill the other two jobs from the other 6 members: $6\times5=30$ ways. $3\times30=90$.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mo picks one of 3 jobs, other two jobs from 6 then 5: 3*6*5=90 (or 210-120).","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26262d0a-36be-48a0-9bd2-d85a1a77c09d', 'PRE.14', 3, 'numeric', 'Choosing in order (offices and places)', 'A club picks a president and then a different member as vice president. This can be done in 42 ways. How many members does the club have?', '[]', '7', '7', 'If there are n members the number of ways is $n\times(n-1)$. We need $n\times(n-1)=42$. Since $7\times6=42$, the club has 7 members.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n(n-1)=42; n=7.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01977a49-b3b0-46d5-ac8b-45ca735cb897', 'PRE.14', 3, 'choice', 'Choosing in order (offices and places)', 'Six runners race with no ties. Kim wins gold. In how many ways can silver and bronze be given to two of the other runners?', '["$120$","$30$","$60$","$20$"]', '$20$', '5*4', 'Kim is fixed for gold. Silver goes to one of the other 5 runners, then bronze to one of the 4 left: $5\times4=20$.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 choices for silver, 4 for bronze: 20.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59cc80da-0683-4942-8ff2-b1c017be80b9', 'PRE.14', 3, 'numeric', 'Choosing a group (order does not matter)', 'At a party everyone shakes hands once with everyone else, and there are 45 handshakes in all. How many people are at the party?', '[]', '10', '10', 'With n people there are $\frac{n\times(n-1)}{2}$ handshakes. We need $n\times(n-1)=90$. Since $10\times9=90$, there are 10 people.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n(n-1)/2=45; n=10.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fbd4b81-3136-405b-bb56-325931815e44', 'PRE.14', 3, 'numeric', 'Choosing a group (order does not matter)', 'A committee of 3 people is chosen from 6 people. Ann is one of the 6, and she must be on the committee. How many different committees are possible?', '[]', '10', '5*4/2', 'Ann is on it. Choose the other 2 members from the other 5 people: $5\times4=20$ in order, and $20\div2=10$ without order.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Choose the other 2 from 5: C(5,2)=10.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f251d99b-44af-4fe5-8365-99865773dc79', 'PRE.14', 3, 'choice', 'Choosing a group (order does not matter)', 'Seven points are marked on a circle. Every pair of points is joined by a straight line segment. How many segments are drawn?', '["$42$","$14$","$49$","$21$"]', '$21$', '7*6/2', 'Each pair of points makes one segment. $7\times6=42$ ordered pairs, and each segment is counted twice, so $42\div2=21$.', 'checked', '{"lint":[],"solve":{"answer":"$21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(7,2)=21.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2bf1d15-46d8-45c4-ab0e-05bfd66e57b6', 'PRE.14', 3, 'numeric', 'Overlapping groups', 'Of 50 students, 30 play chess, 25 play checkers and 10 play neither. How many play both games?', '[]', '15', '30+25-(50-10)', '$50-10=40$ students play at least one game. Adding $30+25=55$ counts the students who play both twice, so $55-40=15$ play both.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least one: 50-10=40; both = 30+25-40=15.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42ab8849-4ba8-40a2-82f3-eb28ef41c0d6', 'PRE.14', 3, 'numeric', 'Overlapping groups', 'How many of the whole numbers from 1 to 100 are multiples of 4 or multiples of 6 (or both)?', '[]', '33', '25+16-8', 'Multiples of 4: 25. Multiples of 6: 16. A number is a multiple of both 4 and 6 when it is a multiple of 12: 8 of them. So $25+16-8=33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4: 25; of 6: 16; of 12: 8; 25+16-8=33.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e89dd93-ee0e-4936-9536-12ab9fe54e74', 'PRE.14', 3, 'choice', 'Overlapping groups', 'In a class, 22 students have a brother, 17 have a sister, 9 have both and 6 have neither. How many students are in the class?', '["$54$","$45$","$30$","$36$"]', '$36$', '22+17-9+6', 'With a brother or a sister: $22+17-9=30$. Add the 6 with neither: $30+6=36$.', 'checked', '{"lint":[],"solve":{"answer":"$36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Brother or sister 22+17-9=30; plus 6 neither: 36.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019623a1-baaa-418c-ad20-31abf7e335c1', 'PRE.14', 3, 'numeric', 'Choosing from separate groups', 'A committee of 3 is chosen from 5 men and 4 women. How many committees have at least one woman?', '[]', '74', '84-10', 'All committees: $\frac{9\times8\times7}{3\times2\times1}=84$. Committees of men only: $\frac{5\times4\times3}{3\times2\times1}=10$. So $84-10=74$.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(9,3)=84; all men C(5,3)=10; 74.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64d35a80-4eb9-40dc-aa96-5e21306a726c', 'PRE.14', 3, 'numeric', 'Choosing from separate groups', 'A team of 4 is chosen from 5 boys and 3 girls. How many teams have exactly 2 girls?', '[]', '30', '(3*2/2)*(5*4/2)', 'Choose 2 of the 3 girls: 3 ways. Choose 2 of the 5 boys: $\frac{5\times4}{2}=10$ ways. $3\times10=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(3,2)*C(5,2)=3*10=30.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e28f9ec-71c3-46b3-a3f4-d897c86b6428', 'PRE.14', 3, 'choice', 'Choosing from separate groups', 'A group of 3 is chosen from 4 men and 4 women. How many groups have at least one man and at least one woman?', '["$56$","$24$","$40$","$48$"]', '$48$', '56-4-4', 'All groups of 3 from 8 people: $\frac{8\times7\times6}{3\times2\times1}=56$. Groups of only men: 4. Groups of only women: 4. $56-4-4=48$.', 'checked', '{"lint":[],"solve":{"answer":"$48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(8,3)=56; all men 4; all women 4; 56-8=48.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0029e5df-f90c-4f8d-a6d1-00db6c951cdb', 'PRE.14', 3, 'numeric', 'Coins, dice and repeated choices', 'Three dice (red, blue and green) are rolled. In how many outcomes do the three dice show three different numbers?', '[]', '120', '6*5*4', 'The red die shows any of 6 numbers. The blue die must differ: 5 numbers. The green die must differ from both: 4 numbers. $6\times5\times4=120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*5*4=120.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
