INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f4256f4-9122-44b5-8d9f-7d77f35f690b', 'PRE.14', 3, 'numeric', 'Coins, dice and repeated choices', 'A coin is flipped 5 times. In how many of the possible sequences is there at least one head?', '[]', '31', '2^5-1', 'All sequences: $2^5=32$. Only one sequence has no heads (TTTTT). So $32-1=31$.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5=32; all tails 1; 31.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
