INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e79a769d-399f-40dc-b447-2faa3ef323f6', 'PRE.14', 3, 'choice', 'Coins, dice and repeated choices', 'A red die and a blue die are rolled. In how many of the 36 outcomes does the red die show a bigger number than the blue die?', '["$21$","$15$","$18$","$30$"]', '$15$', '(36-6)/2', 'In 6 outcomes both dice show the same number. The other 30 outcomes split evenly between red bigger and blue bigger: $30\div2=15$. ($21$ would also count the ties.)', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 minus 6 ties = 30, half have red bigger: 15.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b1cbb2d-de47-4823-90ad-a4e887078686', 'PRE.15', 1, 'numeric', 'Work backwards', 'Mia thinks of a number and adds 7. The result is 25. What number did she think of?', '[]', '18', '25-7', 'Undo the adding: subtract 7 from 25. $25-7=18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Work backwards: 25 - 7 = 18.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
