VALUES ('6740a9cf-e2ff-4335-a8b3-c519d49e86cd', 'PRE.15', 1, 'choice', 'Work backwards', 'Tom multiplies a number by 4 and gets 36. What was the number?', '["9","144","32","40"]', '9', '36/4', 'Undo the multiplying by dividing: $36\div4=9$. Check: $9\times4=36$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / 4 = 9.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
