INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7fde82-3bba-4cb7-b1e2-a2601259209c', 'PRE.15', 1, 'numeric', 'Work backwards', 'A number is doubled, and then 5 is subtracted. The result is 21. What is the number?', '[]', '13', '(21+5)/2', 'Undo the steps in reverse order. Add 5: $21+5=26$. Then halve: $26\div2=13$. Check: $13\times2-5=21$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo: 21 + 5 = 26, 26 / 2 = 13. Check 2*13 - 5 = 21.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
