INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fee9735f-b2eb-4f04-a6f4-2c5d01b85b2c', 'PRE.15', 1, 'choice', 'Work backwards', 'Sam gave away 8 marbles and then found 3 more. Now he has 20 marbles. How many marbles did he have at the start?', '["31","25","15","9"]', '25', '20-3+8', 'Undo the last step first: before finding 3 he had $20-3=17$. Before giving away 8 he had $17+8=25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo finding 3: 20 - 3 = 17; undo giving 8: 17 + 8 = 25.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
