INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('624ad1f6-4125-48fd-a8d5-b29e6bb0cedc', 'PRE.15', 1, 'choice', 'Work backwards', 'A bus has some people on it. At the first stop 6 people get off. At the second stop 9 people get on. Now there are 31 people on the bus. How many people were on the bus at the start?', '["34","46","28","16"]', '28', '31-9+6', 'Go backwards. Before 9 got on there were $31-9=22$. Before 6 got off there were $22+6=28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo second stop: 31 - 9 = 22; undo first stop: 22 + 6 = 28.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62623fe2-7fd5-4274-bdc8-32a6788a1166', 'PRE.15', 1, 'numeric', 'Work backwards', 'I think of a number, divide it by 3, and then add 2. I get 10. What is my number?', '[]', '24', '(10-2)*3', 'Undo adding 2: $10-2=8$. Undo dividing by 3: $8\times3=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 - 2 = 8; 8 * 3 = 24. Check 24/3 + 2 = 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbe8aa6d-e7ad-4733-ab91-806c7b83ee58', 'PRE.15', 1, 'choice', 'Work backwards', 'In the last round of a game Lena won 15 points. In the round before that she lost 5 points. Now she has 40 points. How many points did she have before those two rounds?', '["50","60","20","30"]', '30', '40-15+5', 'Undo the last round: $40-15=25$. Undo the loss of 5 points by adding 5 back: $25+5=30$. Check: $30-5+15=40$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo last round: 40 - 15 = 25; undo the loss: 25 + 5 = 30.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
