INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52dc8066-7fe2-4647-b84c-5f4ebc053cfd', 'PRE.15', 1, 'choice', 'Find and extend a pattern', 'The letters A, B, C, D repeat in this order: A B C D A B C D A B C D ... What is the 10th letter?', '["B","A","C","D"]', 'B', NULL, 'The letters repeat every 4. The 8th letter is D, so the 9th is A and the 10th is B.', 'checked', '{"lint":[],"solve":{"answer":"B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 = 2*4 + 2, so the 2nd letter of the cycle: B.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
