INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1330d024-2d8b-4eef-b09e-82439e4ff584', 'PRE.15', 2, 'numeric', 'Work backwards', 'I think of a number, multiply it by 3, subtract 7, and then divide by 2. The result is 10. What is my number?', '[]', '9', '((10*2)+7)/3', 'Undo each step in reverse order. Multiply by 2: $10\times2=20$. Add 7: $27$. Divide by 3: $9$. Check: $9\times3=27$, $27-7=20$, $20\div2=10$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*2 = 20; 20 + 7 = 27; 27/3 = 9. Check (27-7)/2 = 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce4b2d27-c6e4-4491-b4f5-298a8bc31d4a', 'PRE.15', 2, 'choice', 'Work backwards', 'Priya spent half of her money on a book. Then she spent 6 dollars on lunch. She has 11 dollars left. How many dollars did she have at the start?', '["34","17","22","10"]', '34', '(11+6)*2', 'Before lunch she had $11+6=17$ dollars. That was half of her money, so at the start she had $17\times2=34$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 + 6 = 17 was the half left; 17*2 = 34.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
