INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65fe78b2-d741-4ccf-8a58-39037b685cd6', 'PRE.15', 2, 'numeric', 'Work backwards', 'A positive number is squared, and then 4 is added. The result is 53. What was the number?', '[]', '7', NULL, 'Undo adding 4: $53-4=49$. The number whose square is 49 and which is positive is 7. Check: $7^2+4=53$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"53 - 4 = 49; positive square root 7.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
