INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c6cebdb-dcda-470f-a250-2da5cfe7233d', 'PRE.15', 2, 'choice', 'Work backwards', 'A shop sold half of its apples on Monday. On Tuesday it sold 12 more apples. On Wednesday it got a delivery of 30 apples, and now it has 50 apples. How many apples did the shop have before Monday?', '["32","184","64","16"]', '64', '(50-30+12)*2', 'Before the delivery the shop had $50-30=20$ apples. Before Tuesday''s sales it had $20+12=32$. That was half of what it had before Monday, so it had $32\times2=64$.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before delivery: 50 - 30 = 20; before Tuesday: 20 + 12 = 32; before Monday: 32*2 = 64.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3aa27075-f800-452d-9809-f3950d078b9b', 'PRE.15', 2, 'numeric', 'Work backwards', 'In a game, you start with a score, double it, lose 10 points, and then double it again. The final score is 60. What was the starting score?', '[]', '20', '(60/2+10)/2', 'Undo the last doubling: $60\div2=30$. Undo losing 10 points: $30+10=40$. Undo the first doubling: $40\div2=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/2 = 30; 30 + 10 = 40; 40/2 = 20. Check 20->40->30->60.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
