INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f4cdf50-ec3d-445d-956e-c975a96f93ca', 'PRE.15', 2, 'numeric', 'Find and extend a pattern', 'A machine gives these results: put in 1 and get 5, put in 2 and get 8, put in 3 and get 11, put in 4 and get 14. What does it give when 10 is put in?', '[]', '32', '5+9*3', 'The output goes up by 3 each time the input goes up by 1, starting from 5 at input 1. Input 10 is 9 steps later: $5+9\times3=32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Output = 3n + 2; n = 10 gives 32.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
