INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bae587c4-8d8c-4c7e-91b4-5bd8c854fc91', 'PRE.15', 2, 'choice', 'Find and extend a pattern', 'What is the units digit of $3^{20}$?', '["3","9","7","1"]', '1', NULL, 'The units digits of $3^1,3^2,3^3,3^4,\ldots$ are 3, 9, 7, 1, and then they repeat every 4 powers. Since 20 is a multiple of 4, the units digit of $3^{20}$ is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Units digits of powers of 3 cycle 3,9,7,1; 20 is a multiple of 4, so 1.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
