INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5232e72a-02c2-48c7-8af1-9b427eb629e4', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'How many three-digit numbers can be written using only the digits 1, 2, 3 and 4, if no digit is used twice in the same number?', '[]', '24', '4*3*2', 'There are 4 choices for the first digit, then 3 for the second, then 2 for the third: $4\times3\times2=24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*3*2 = 24.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
