INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('453a96b7-fe75-4c99-8c27-8a9dac202021', 'PRE.15', 2, 'choice', 'Make an organized list and count', 'In how many ways can you make 25 cents using dimes (10 cents), nickels (5 cents) and pennies (1 cent), with any number of each?', '["12","9","10","15"]', '12', '6+4+2', 'List by dimes. With 0 dimes, 25 cents can use 0 to 5 nickels (the rest pennies): 6 ways. With 1 dime, 15 cents is left, 0 to 3 nickels: 4 ways. With 2 dimes, 5 cents is left, 0 or 1 nickel: 2 ways. Total $6+4+2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 dimes: 0-5 nickels, 6 ways; 1 dime: 0-3 nickels, 4 ways; 2 dimes: 0-1 nickel, 2 ways. Total 12.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616c2597-0785-492c-be0d-73286882e88a', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'A lunch is one soup, one main dish and one dessert. There are 3 soups, 5 main dishes and 2 desserts to choose from. How many different lunches are possible?', '[]', '30', '3*5*2', 'Multiply the choices: $3\times5\times2=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*5*2 = 30.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
