INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7eec2801-5afc-4c57-a4c8-f56311805a12', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'A teacher picks 2 students from a group of 5 students to carry the books. The order does not matter. How many different pairs can she pick?', '[]', '10', '5*4/2', 'Name the students A, B, C, D, E. The pairs are AB, AC, AD, AE, BC, BD, BE, CD, CE, DE. That is 10 pairs.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*4/2 = 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
