INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21e8d2a2-c962-4a43-ab1a-3e48ee4b0232', 'PRE.15', 2, 'choice', 'Make an organized list and count', 'Two six-sided dice are rolled and the numbers on top are added. How many different totals are possible?', '["12","11","10","36"]', '11', '12-2+1', 'The smallest total is $1+1=2$ and the largest is $6+6=12$. Every total from 2 to 12 can happen, which is $12-2+1=11$ totals.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Totals 2 through 12: 11.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
