INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d718a900-b646-4b03-9e29-639c62e49d3f', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'How many ordered pairs of positive whole numbers $(a, b)$ have $a\times b=36$? For example $(4, 9)$ and $(9, 4)$ are different pairs.', '[]', '9', NULL, 'The whole numbers that divide 36 are 1, 2, 3, 4, 6, 9, 12, 18, 36. Each one can be $a$, and then $b$ is decided. That gives 9 pairs.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 has divisors 1,2,3,4,6,9,12,18,36: 9 ordered pairs.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
