INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7b54ecd-7720-4833-b055-6fdc7ad37d63', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'The letters A, B and C are each used once to write a three-letter code, and the code may not start with C. How many codes are possible?', '[]', '4', '6-2', 'All the codes: ABC, ACB, BAC, BCA, CAB, CBA. The two that start with C (CAB, CBA) are not allowed. That leaves 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3! = 6 codes, 2 start with C; 4.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
