INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a16ea87e-d014-4990-b0a8-efdce3f31e91', 'PRE.15', 2, 'numeric', 'Make an organized list and count', 'A staircase has 4 steps. You climb it by taking 1 step or 2 steps at a time. In how many different ways can you reach the top?', '[]', '5', NULL, 'List the sequences of steps: 1+1+1+1, 1+1+2, 1+2+1, 2+1+1, 2+2. That is 5 ways.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1111, 112, 121, 211, 22: 5.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
