INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2edc6ab-81eb-467b-abfa-9df248210a38', 'PRE.15', 2, 'choice', 'Reason logically from clues', 'If it rains, the game is cancelled. The game was not cancelled. What must be true?', '["It rained.","The game was played in the sun.","The game was moved to another day.","It did not rain."]', 'It did not rain.', NULL, 'If it had rained, the game would have been cancelled. It was not cancelled, so it did not rain.', 'checked', '{"lint":[],"solve":{"answer":"It did not rain.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Contrapositive: not cancelled implies it did not rain.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb5706a-42ca-4e59-9c7b-ac2521bff10f', 'PRE.15', 2, 'numeric', 'Reason logically from clues', 'A farm has only chickens and cows. Together they have 10 heads and 28 legs. How many cows are there?', '[]', '4', '(28-20)/2', 'Try 4 cows and 6 chickens: heads $4+6=10$, legs $4\times4+6\times2=16+12=28$. It fits. (If all 10 were chickens there would be 20 legs; each cow instead of a chicken adds 2 legs, so $8\div2=4$ cows.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All chickens: 20 legs; extra 8 legs, 2 per cow: 4 cows (6 chickens). Check 4*4 + 6*2 = 28.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b8ee4f0-2308-41fa-8c7e-c6b796a17df9', 'PRE.15', 2, 'choice', 'Reason logically from clues', 'In a class of 25 students, 14 have a dog, 9 have a cat, and 4 have both a dog and a cat. How many students have neither?', '["6","19","2","11"]', '6', '25-(14+9-4)', 'Students with a dog or a cat: $14+9-4=19$ (the 4 with both were counted twice). So $25-19=6$ have neither.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dog or cat: 14 + 9 - 4 = 19; neither 25 - 19 = 6.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c86a4d1a-effc-4f26-a9ac-cf23b20a24b2', 'PRE.15', 2, 'choice', 'Reason logically from clues', 'Four runners finish a race with no ties. Ali finishes before Bo. Cy finishes after Bo. Di finishes before Ali. Who finishes third?', '["Ali","Bo","Cy","Di"]', 'Bo', NULL, 'Di is before Ali, Ali is before Bo, and Bo is before Cy. The order is Di, Ali, Bo, Cy, so Bo is third.', 'checked', '{"lint":[],"solve":{"answer":"Bo","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Di < Ali < Bo < Cy in finishing order; third is Bo.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7637399-b815-44a8-b0de-2f8cf23950dc', 'PRE.15', 2, 'choice', 'Reason logically from clues', 'The sum of three consecutive whole numbers (like 5, 6, 7) is 48. What is the largest of the three numbers?', '["16","15","17","18"]', '17', '48/3+1', 'The middle number is the average, $48\div3=16$. The numbers are 15, 16, 17, so the largest is 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Middle 48/3 = 16; 15, 16, 17; largest 17.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e8eb854-b842-4354-94a5-a3aa6d3a7d96', 'PRE.15', 2, 'choice', 'Reason logically from clues', 'No dog in the park wears a hat. Rex wears a hat. Which statement must be true?', '["Rex is not a dog at all.","Rex is somewhere in the park.","Some dogs in the park wear hats.","Rex is not a dog in the park."]', 'Rex is not a dog in the park.', NULL, 'If Rex were a dog in the park, he would not wear a hat. He does wear one, so he is not one of the dogs in the park. (He could be a dog somewhere else.)', 'checked', '{"lint":[],"solve":{"answer":"Rex is not a dog in the park.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If Rex were a dog in the park he would not wear a hat; he does, so he is not a dog in the park. He could still be a dog elsewhere.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('601639b3-dd22-473c-8526-52b6750a8fa8', 'PRE.15', 2, 'numeric', 'Reason logically from clues', 'A bag holds many red, blue and green marbles. You take marbles out without looking. How many must you take out to be sure that at least two of them are the same color?', '[]', '4', '3+1', 'In the worst case the first 3 marbles are all different colors. The 4th must match one of them. So 4 marbles are needed.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 colors: 3 could all differ; 4 guarantees a pair.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e423997-3c01-4aa5-9b52-106efa1926f5', 'PRE.15', 2, 'numeric', 'Reason logically from clues', 'Ann finished a race in 7th place. Exactly 3 runners finished between Ann and Bea, and Bea finished ahead of Ann. What place did Bea finish in?', '[]', '3', '7-3-1', 'The three runners between them finished 4th, 5th and 6th, so Bea was just ahead of those, in 3rd place.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Places 4, 5, 6 between; Bea is 3rd.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39d3cb88-a54f-4fe9-b9c6-1944b3dcfa05', 'PRE.15', 3, 'numeric', 'Work backwards', 'A number is multiplied by 2, then 3 is added, then the result is multiplied by 4, and finally 5 is subtracted. The answer is 79. What was the original number?', '[]', '9', '((79+5)/4-3)/2', 'Undo in reverse order. Add 5: $79+5=84$. Divide by 4: $21$. Subtract 3: $18$. Divide by 2: $9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"79 + 5 = 84; 84/4 = 21; 21 - 3 = 18; 18/2 = 9.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
