INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bca2247-9683-4c1f-8031-1f19031b1758', 'PRE.15', 3, 'numeric', 'Work backwards', 'Some coins are shared among three people. Ann takes half of the coins and one more. Then Ben takes half of the coins that are left and one more. Then Cy takes the last 3 coins. How many coins were there at first?', '[]', '18', '((3+1)*2+1)*2', 'After Ben, 3 coins were left. Ben took half of what was there plus one, so those 3 coins were half minus one: half was 4, and before Ben there were 8. In the same way, Ann left 8 coins, so half was 9 and there were 18 at first. Check: Ann takes $9+1=10$, leaving 8; Ben takes $4+1=5$, leaving 3.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before Ben x: x - (x/2 + 1) = x/2 - 1 = 3, x = 8. Before Ann y: y/2 - 1 = 8, y = 18. Check: Ann 10, left 8; Ben 5, left 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99495c12-1994-43d0-8f7a-2ca7baed108f', 'PRE.15', 3, 'numeric', 'Work backwards', 'Rita spent one-half of her money at the first shop. At the second shop she spent one-third of what she had left. At the third shop she spent one-fourth of what she then had left. After that she had 15 dollars. How many dollars did she have at the start?', '[]', '60', '15*4/3*3/2*2', 'After the third shop she kept three-fourths, which is 15 dollars, so before it she had $15\div3\times4=20$ dollars. After the second shop she kept two-thirds: 20 dollars is two-thirds, so before it she had 30 dollars. After the first shop she kept half: 30 dollars is half, so she started with 60 dollars.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 is 3/4 of 20; 20 is 2/3 of 30; 30 is 1/2 of 60.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdea1778-9c19-4e9b-9451-44b5779f428f', 'PRE.15', 3, 'choice', 'Work backwards', 'The area of a pond covered by algae doubles every day. On day 12 the whole pond is covered. On which day was exactly one-quarter of the pond covered?', '["6","10","9","11"]', '10', '12-2', 'Working backwards, each day the area halves. On day 11 half was covered. On day 10 one-quarter was covered.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Day 12 full, day 11 half, day 10 quarter.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0c77d12-59af-44ab-a036-68da8cec8ad3', 'PRE.15', 3, 'numeric', 'Work backwards', 'Max thinks of a positive number. He squares it, subtracts 6, and then multiplies by 3. The result is 57. What was his number?', '[]', '5', NULL, 'Undo multiplying by 3: $57\div3=19$. Undo subtracting 6: $19+6=25$. The positive number whose square is 25 is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"57/3 = 19; 19 + 6 = 25; positive root 5.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27b0c7de-619f-41e8-829e-2ae8729af506', 'PRE.15', 3, 'numeric', 'Work backwards', 'A jacket''s price is cut by 20 percent. Then a coupon takes 10 dollars off that sale price, so the jacket costs 38 dollars. What was the price before the 20 percent cut, in dollars?', '[]', '60', '(38+10)*5/4', 'Before the coupon the sale price was $38+10=48$ dollars. That is 80 percent of the original price, so one-fifth of the original is $48\div4=12$, and the original is $12\times5=60$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sale price 38 + 10 = 48 = 0.8 P; P = 60.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58b0c86a-073e-406b-97e4-27f7f1a258c2', 'PRE.15', 3, 'numeric', 'Work backwards', 'Every day Leah doubles the number of coins in her jar and then puts in 5 more coins. After 3 days the jar has 59 coins. How many coins were in the jar at the start?', '[]', '3', '(((59-5)/2-5)/2-5)/2', 'Work backwards through each day: take away 5, then halve. End of day 3: 59. Before the 5 coins: 54, halved: 27. End of day 2: 27, take away 5: 22, halved: 11. End of day 1: 11, take away 5: 6, halved: 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo each day: (59-5)/2 = 27; (27-5)/2 = 11; (11-5)/2 = 3. Check 3->11->27->59.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088115be-eec9-4931-95ef-578911fa68aa', 'PRE.15', 3, 'choice', 'Work backwards', 'A movie ends at 4:10 pm. The movie itself is 2 hours 25 minutes long, and before it there are 20 minutes of previews. At what time did the previews start?', '["1:45 pm","2:05 pm","1:25 pm","1:05 pm"]', '1:25 pm', NULL, 'The movie started 2 hours 25 minutes before 4:10 pm, which is 1:45 pm. The previews started 20 minutes before that, at 1:25 pm.', 'checked', '{"lint":[],"solve":{"answer":"1:25 pm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 2 h 45 min before 4:10 pm: 4:10 - 2:45 = 1:25 pm.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df7eeb16-cb8e-41d9-a94a-126195409d6d', 'PRE.15', 3, 'numeric', 'Work backwards', 'Each week Pia spends half of her savings, and then her grandmother gives her 10 dollars. After 3 weeks she has 30 dollars. How many dollars did she have at the start?', '[]', '100', '(((30-10)*2-10)*2-10)*2', 'Work backwards one week at a time: take away the 10 dollars, then double. End of week 3: 30, minus 10 is 20, doubled is 40. End of week 2: 40, minus 10 is 30, doubled is 60. End of week 1: 60, minus 10 is 50, doubled is 100.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo a week: (30-10)*2 = 40; (40-10)*2 = 60; (60-10)*2 = 100. Check 100->60->40->30.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5559a35d-04bc-46fb-bd0a-05408ef1b3ec', 'PRE.15', 3, 'choice', 'Find and extend a pattern', 'The first row of a pattern has 2 dots, the second row has 5 dots, the third row has 8 dots, and each row has 3 more dots than the row before. How many dots are there in the first 10 rows altogether?', '["155","145","290","310"]', '155', '10*(2+29)/2', 'The 10th row has $2+9\times3=29$ dots. The row sizes go up evenly, so the total is the number of rows times the average of the first and last: $10\times\frac{2+29}{2}=155$.', 'checked', '{"lint":[],"solve":{"answer":"155","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Row 10 has 2 + 9*3 = 29. Sum = 10*(2+29)/2 = 155.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ab355cb-ef40-4325-b883-d82b12893d3e', 'PRE.15', 3, 'numeric', 'Find and extend a pattern', 'What is the units digit of $7^{43}+3^{43}$?', '[]', '0', NULL, 'Units digits of powers of 7 repeat 7, 9, 3, 1; since $43=4\times10+3$, $7^{43}$ ends in 3. Units digits of powers of 3 repeat 3, 9, 7, 1; so $3^{43}$ ends in 7. The units digit of the sum is the units digit of $3+7=10$, which is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 cycle 7,9,3,1; 43 = 4*10+3 so 3. 3 cycle 3,9,7,1 so 7. 3 + 7 = 10, units digit 0.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25b4299a-253f-4c96-8d78-fe61a56a9cee', 'PRE.15', 3, 'numeric', 'Find and extend a pattern', 'Figure 1 uses 3 toothpicks, figure 2 uses 5, and figure 3 uses 7. Each figure uses 2 more toothpicks than the one before. One figure uses 101 toothpicks. Which figure number is it?', '[]', '50', '(101-3)/2+1', 'Figure $n$ uses $3+2\times(n-1)$ toothpicks. Setting this to 101 gives $2\times(n-1)=98$, so $n-1=49$ and $n=50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Figure n uses 2n + 1; 2n + 1 = 101 gives n = 50.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddfc6b87-68d3-4db2-be41-06a049453153', 'PRE.15', 3, 'numeric', 'Find and extend a pattern', 'How many of the whole numbers from 1 to 100 are multiples of neither 2 nor 3?', '[]', '33', '16*2+1', 'In each block of 6 numbers (1 to 6, 7 to 12, and so on) only the numbers that leave remainder 1 or 5 qualify, so 2 per block. There are 16 full blocks (96 numbers), giving 32. Among 97, 98, 99, 100 only 97 qualifies. Total $32+1=33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 2: 50, of 3: 33, of 6: 16. 50+33-16 = 67; 100 - 67 = 33.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09213a74-9836-4641-95bd-a286b9e8229c', 'PRE.15', 3, 'choice', 'Find and extend a pattern', 'Notice that $1=1$, $1+3=4$, $1+3+5=9$, and $1+3+5+7=16$. Use the pattern to find the sum of all the odd numbers from 1 to 39: $1+3+5+\cdots+39$.', '["380","400","780","200"]', '400', '20*20', 'The sum of the first $n$ odd numbers is $n\times n$. The odd numbers from 1 to 39 are 20 numbers, so the sum is $20\times20=400$.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of first n odd numbers is n^2; 1..39 has 20 odd numbers; 400.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7725d10-d097-4227-b354-34aa59abf19b', 'PRE.15', 3, 'choice', 'Find and extend a pattern', 'The numbers 1, 2, 4, 7, 11, 16, ... go up by 1, then by 2, then by 3, then by 4, then by 5, and the gaps keep growing by 1. What is the 12th number?', '["66","78","67","79"]', '67', '1+11*12/2', 'The 12th number comes after 11 gaps: $1+(1+2+3+\cdots+11)=1+66=67$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"nth = 1 + (1+2+...+(n-1)) = 1 + n(n-1)/2; n = 12: 1 + 66 = 67.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20cdfd53-b95a-4c21-9ae0-dd7d394e03f9', 'PRE.15', 3, 'choice', 'Find and extend a pattern', 'The whole numbers are written in rows. Row 1 is: 1. Row 2 is: 2 3. Row 3 is: 4 5 6. Row 4 is: 7 8 9 10. Each row has one more number than the row before. What is the first number in row 10?', '["45","55","56","46"]', '46', '9*10/2+1', 'Rows 1 to 9 hold $1+2+\cdots+9=45$ numbers, so they use the numbers 1 to 45. Row 10 begins with 46.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rows 1-9 hold 45 numbers, so row 10 starts at 46.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e98e2498-c63e-49c0-85fc-f1348f40ac18', 'PRE.15', 3, 'numeric', 'Find and extend a pattern', 'The whole numbers are written one after another with no spaces: 123456789101112... What is the 100th digit?', '[]', '5', NULL, 'The numbers 1 to 9 use 9 digits. The remaining $100-9=91$ digits come from two-digit numbers. 45 such numbers (10 to 54) use 90 digits. The 91st digit is the first digit of 55, which is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-9 use 9 digits; 91 left. 45 two-digit numbers (10-54) use 90; the 100th digit is the first digit of 55: 5.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e13a064-83fb-4ddc-aa4d-526b28d623d4', 'PRE.15', 3, 'choice', 'Make an organized list and count', 'How many different triangles have three whole-number side lengths and a perimeter of 12? Triangles with the same three side lengths count as one.', '["4","5","3","2"]', '3', '3', 'The longest side must be shorter than the sum of the other two, so it is less than 6. Longest side 5: the others add to 7, giving (2, 5, 5) and (3, 4, 5). Longest side 4: the others add to 8, giving (4, 4, 4). A longest side of 3 or less cannot reach 12. That is 3 triangles.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a<=b<=c, a+b>c, sum 12 so c<6 and c>=4. c=5: (2,5,5),(3,4,5); c=4: (4,4,4). 3 triangles.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107f9237-a182-4ce7-9f41-2fe41f9c4d63', 'PRE.15', 3, 'choice', 'Make an organized list and count', 'How many of the whole numbers from 1 to 50 are multiples of 4 or multiples of 6 (or both)?', '["20","24","12","16"]', '16', '12+8-4', 'Multiples of 4: 4, 8, ..., 48 is 12 numbers. Multiples of 6: 6, 12, ..., 48 is 8 numbers. Both lists contain the multiples of 12 (12, 24, 36, 48), which are 4 numbers counted twice. So the total is $12+8-4=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4: 12; of 6: 8; of 12: 4. 12 + 8 - 4 = 16.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('605c549c-75b3-4f42-97b9-d12074cb9490', 'PRE.15', 3, 'choice', 'Make an organized list and count', 'Three different prizes are given to students from a group of 5. No student can get more than one prize. In how many ways can the prizes be given out?', '["60","125","15","10"]', '60', '5*4*3', 'The first prize can go to any of 5 students, the second to any of the remaining 4, the third to any of the remaining 3: $5\times4\times3=60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*4*3 = 60.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4163bd05-2a77-408b-89df-4de9df5c39bb', 'PRE.15', 3, 'numeric', 'Make an organized list and count', 'How many three-digit whole numbers have digits that add up to 5?', '[]', '15', '5+4+3+2+1', 'List by the first digit. First digit 1: the other two add to 4 (04, 13, 22, 31, 40): 5 numbers. First digit 2: other two add to 3 (4 ways). First digit 3: add to 2 (3 ways). First digit 4: add to 1 (2 ways). First digit 5: add to 0 (1 way). Total $5+4+3+2+1=15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds digit a>=1: (a-1)+b+c = 4, C(6,2) = 15. By hundreds digit: 5+4+3+2+1 = 15.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('681dadba-4620-4e26-908c-2df7c5ae7109', 'PRE.15', 3, 'choice', 'Make an organized list and count', 'A rectangle is made of 2 rows of 3 unit squares each, so it has 6 unit squares. How many rectangles of any size can you find, with their sides along the grid lines?', '["6","18","12","20"]', '18', '3*6', 'The grid has 3 horizontal lines and 4 vertical lines. A rectangle is decided by choosing 2 horizontal lines (3 ways) and 2 vertical lines (6 ways): $3\times6=18$ rectangles.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Choose 2 of 3 horizontal lines and 2 of 4 vertical lines: 3*6 = 18.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11815137-ea8e-433b-b92c-439ac5e17a8b', 'PRE.15', 3, 'numeric', 'Make an organized list and count', 'The digits 1, 2, 3 and 4 are each used once to make a four-digit number. How many of these numbers are even?', '[]', '12', '2*6', 'An even number must end in 2 or 4. If it ends in 2, the other three digits can be arranged in 6 ways; likewise if it ends in 4. Total $2\times6=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Last digit 2 or 4 (2 ways), the other three in 3! = 6 orders: 12.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a1ea8c5-2f9c-4abe-a29f-07a0cd7d02bf', 'PRE.15', 3, 'numeric', 'Make an organized list and count', 'In how many ways can you make exactly 50 cents using quarters (25 cents), dimes (10 cents) and nickels (5 cents), with any number of each, including none?', '[]', '10', '6+3+1', 'List by quarters. With 0 quarters, 50 cents from dimes and nickels: 0 to 5 dimes, the rest nickels, 6 ways. With 1 quarter, 25 cents is left: 0 to 2 dimes, 3 ways. With 2 quarters, 1 way. Total $6+3+1=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 quarters: 0-5 dimes, 6 ways; 1 quarter: 0-2 dimes, 3 ways; 2 quarters: 1 way. Total 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f9e8f88-3529-4c6a-a0b7-0763835e043c', 'PRE.15', 3, 'choice', 'Make an organized list and count', 'How many different ways can the letters of the word LEVEL be arranged in a row?', '["120","60","30","24"]', '30', '120/4', 'If all 5 letters were different there would be $5\times4\times3\times2\times1=120$ arrangements. The two L''s can swap without changing the word, and so can the two E''s, so divide by $2\times2=4$: $120\div4=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5!/(2!*2!) = 30 (two L, two E).","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
